		{
			{
				10126
			},
			1,
			"Let's make 'em taste the rainbow!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[100021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Commander! I found a suspicious letter, bulin! ...Bulin? Oh, it was just for you...",
