_G.pg.base.ship_skin_words[101160] = {
	hp_warning = "",
	feeling3 = "I am cuteness, and cuteness is me. Don't you agree, Commander? Yay!",
	mail = "Mail for you, Commander! I didn't want to anyone else to peek, so I went ahead and took a look myself first!",
	expedition = "Commander, the commission's been completed! I'm going to have to punish you if you forget about those girls!",
	win_mvp = "Hoho! Even the most cunning fox couldn't best a rabbit like me!",
	home = "Were you thinking about how badly you wanted to come back and meet me~? Come here, I'll give a positively explosive hug! ... Hm? Fine... I'm sorry, I'll put away the dynamite... J-just hold on a minute~",
	unlock = "Yahoo! Commander! Aren't you charmed by how cute and risqué I am? Huh? W-who am I? ... Hahaha... My name is Benson... It's a pleasure to meet you...",
	touch2 = "Ah, I feel so hot... I'm burning inside!",
	mission = "A mission? No problem! Easy peasy! Bring it on, whatever it may be!",
	vote = "",
	drop_descrip = "Benson-class Destroyer - Benson, Hull Number DD-421!",
	feeling4 = "Commander, you keep telling me I'm stupid, but you actually like me, don't you?",
	lose = "Oh nooo! You didn't see anything, Commander! Got it?! *Sob*... I failed...",
	feeling1 = "Oh evil being who conspires against cuties... in the name of the moon, I will punish you!",
	skill = "Benson is... invincible!",
	upgrade = "My cuteness level has gone up even higher!",
	propose = "Hehe, so you've finally noticed how important I am? Have you? Do you understand that I'm irreplaceable and that just a glance of me makes your heart skip a beat? ... Commander, why are you touching my forehead?",
	feeling5 = "Commander! Cutie Benson has come again! I've been stopping by too often lately? That's because you haven't been paying this super duper cutie Benson a visit, so you left me no choice~ I'm not lonely at all, I swear!",
	main = "I'm so cute! The cutest in the universe!|I'm telling you, Commander, Fletcher's house next door is full of people! Us girls need to help her out every now and then~.|If you don't talk to me enough then I'll stop being a bunny! Woof woof!",
	touch = "Whoa! I actually fell asleep! Could this be because of that fabled super hypnosis thing?!",
	voice_key_2 = -1,
	mission_complete = "Come on, come on! Give me a reward!",
	battle = "It won't be as simple as going back to the title screen if we get a game over~",
	id = 101160,
