_G.pg.base.ship_skin_words[101250] = {
	hp_warning = "",
	feeling3 = "You're totally wrong if you think you've improved your relationship with me! ... I guess I'll admit it's improved.... But just a little!",
	mail = "I brought your mail, Commander... Where's my \"thanks\"?!",
	expedition = "A commission has been completed, idiot!",
	win_mvp = "Hmph, did you really think this would be enough to make me happy?",
	home = "Good work... I-I didn't say anything! Get back to work, now!",
	unlock = "Hey! Don't stare at me like such an idiot, you pervert! ... I'm cute? Did you really think just complimenting me would make me happy? You moron!",
	touch2 = "(Picks up phone) Hello, is this Military Police? Yes, this Commander is a pervert and he...",
	mission = "Go finish your missions already!",
	vote = "",
	drop_descrip = "Sims-class Destroyer - Hammann, Hull Number DD-412!",
	feeling4 = "Why am I always so angry? Because a certain commander just won't learn! And I'm angry at myself for not getting angry at him!",
	lose = "*Sob*... Commander, you big idiot!",
	feeling1 = "I don't even feel like getting angry anymore...",
	skill = "I'm not doing it just for you or anything like that!",
	upgrade = "Hmph, flattering me won't get you anywhere!",
	propose = "You've finally learned, haven't you? I'll gratefully accept it... B-b-but I'm not happy about it in the slightest!",
	feeling5 = "If you're not looking at me, then at whom?! You just don't understand girls at all because you're so stupid! Just because I'm not being proactive doesn't mean you... Wha?! Don't hug me all of a sudden... I-I'll call the police!",
	main = "Get ready for punishment if you open the window!|I-168's been here, hasn't she? I'll teach her a lesson!|Why won't you talk to me?",
	touch = "I don't want you touching me, you pervert!",
