_G.pg.base.ship_skin_words[101330] = {
	hp_warning = "I-I'm not giving up yet!",
	feeling3 = "You know, I'm actually quite athletic! Check it out, I could hop side to side all day! ... *Pant*, *pant*... This is exhausting... I can't hop anymore...",
	mail = "I've brought your mail along! What does it say?",
	expedition = "Oh, it's time to go welcome the commission team back!",
	win_mvp = "Hehehe! That was super easy!",
	home = "Whoa! Everyone's back home!",
	unlock = "I'm Bush, from the Fletcher class! I'll be staying here from now on!",
	touch2 = "It's not okay to touch me like that!",
	mission = "You've got some missions left to do. Commander, you're not... slacking off again, are you?",
	vote = "",
	drop_descrip = "Fletcher-class destroyer – Bush, Hull Number DD-529.",
	feeling4 = "Gotcha! ... Well, how do you like the prank Thatcher taught me, Commander? ... Huh? But I thought you liked pranks, or at least Thatcher said that you do...",
	lose = "Nooo! Get those planes away from meee!",
	feeling1 = "You need to learn to smile, Commander...",
	skill = "Where is the enemy at?",
	upgrade = "Huh? Will this make me stronger?",
	propose = "Does this mean you love me more than anyone else? If so, will you do anything I ask you to? Okay! I want some snacks from that store that just opened, so let's go there right now!",
	feeling5 = "For whatever reason, I don't feel that scared of planes anymore. It's got to be because we love each other, Commander! ... At least that's what Thatcher told me. She's not wrong, is she?",
	main = "If I stay out of sight, the Commander probably won't notice I'm neglecting my work...|Uughh... Following a schedule is so boooring! I say we do stuff when we see it needs doing! ... What? That's not gonna fly?|I've got a bunch of sisters, both younger and older than me! I forget their names all the time, though...",
	touch = "Yep, what is it?",
	voice_key_2 = -1,
	mission_complete = "Mission complete! ... Did I do it right?",
	battle = "I'll fight with all I've got!",
	id = 101330,
	gift_dislike = "",
	gift_prefer = "Whee, it's my favorite!",
	profile = "I'm the Fletcher-class destroyer Bush. Like my sisters, I fought in the Pacific Ocean and took on tons of missions! ... Planes? I-I don't wanna talk about those scary things!",
	voice_key = 10133,
	headtouch = "",
	feeling2 = "Whuah! A-a plane came flying towards me! ... What? Th-that was just a beetle...?",
	login = "Umm... What are we doing today, again?",
	detail = "What is it? Do you want something from me?",
	couple_encourage = {}
}


