_G.pg.base.ship_skin_words[101380] = {
	hp_warning = "Damage confirmed, continuing combat.",
	feeling3 = "\"What do I plan to do after the war is over?\" Hmm... I've never given this much thought, nor have I wanted to. However, why did you bring it up all of a sudden?",
	mail = "Commander, there's mail for you.",
	expedition = "Commander, a commission has finished.",
	win_mvp = "This is a fine example of tactical synergy. Let's keep it up.",
	home = "I see you've returned at the scheduled time, Commander. However, you can't afford to take it easy just yet.",
	unlock = "I am the Fletcher-class destroyer, Kimberly. From today onward, I will be one of your subordinates. Pleased to meet you.",
	touch2 = "Do you want to pay a visit to the court martial?",
	mission = "As a commander, it is only fitting that you complete these tasks.",
	vote = "",
	drop_descrip = "Fletcher-class Destroyer - Kimberly (DD-521)",
	feeling4 = "Recently, I had a strange dream. I dreamt that I wasn't on the battlefield, but instead taking a walk along the port, hand-in-hand with someone close to me... Wh-what's so funny?",
	lose = "Strategic retreat...",
	feeling1 = "The incompetent will be weeded out by time. You are no exception.",
	skill = "Let's put this needless battle to an end!",
	upgrade = "Strengthening combat effectiveness is also an important link when it comes to battle.",
	propose = "S-so this is a promise ring... Really, I never could have imagined that this would happen to me... However, I'm truly, truly happy, from the bottom of my heart. Is this... the \"love\" that my sisters were talking about? Hey... don't laugh!",
	feeling5 = "After discussing things with my sisters a bit, I realized that if the war actually ended, I wouldn't know how to do anything else... Eh, you'd stay with me and teach me yourself... so there would be no problem? E-ehhh?",
	main = "If you are tired, please take a break. If you were to collapse, the command chain would follow suit. |For me, no matter where I am, or what I am called, I will continue to fight on as long as I live. |I was born for battle and died for peace. Other than this fact, I won't dwell on anything else.",
	touch = "What tasks are there?",
	voice_key_2 = -1,
	mission_complete = "Mission complete. However, your work doesn't end there.",
	battle = "Prepare to meet the enemies.",
	id = 101380,
	gift_dislike = "",
	gift_prefer = "This is for me? *whispers* ...How did you find out about my preferences...?",
	profile = "I am the Fletcher-class destroyer Kimberly. I am normally tasked with escort and anti-submarine duties, so should the need arise, please do not hesitate to deploy me.",
	voice_key = 10138,
	headtouch = "What is... the meaning of this?",
	feeling2 = "As long as we keep on winning, will we be able to bring an end to the war? Rather than searching for the answer to that question, it would be more practical to focus on winning the battles ahead of us.",
	login = "Being punctual is a good habit to have, so please keep it up.",
	detail = "Just what are you looking at? You ought to hurry up and return to your post.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[101382] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Every time I return to port, I feel a wave of relief wash over me. Is this what \"home\" is?",
	unlock = "When I change into clothes from the Dragon Empery, I can't help but to reminisce about the time I spent there... Commander, which style of clothes do you prefer - Union, or Empery?",
	touch2 = "Commander... you could go to jail for this, you know?",
	mission = "If you put things off for tomorrow, you'll find that there's always another tomorrow. That's why you shouldn't put off today's missions for tomorrow.",
	vote = "",
	drop_descrip = "While wearing clothes from the Dragon Empery, I can't help but reminisce about those days... Hehe, Commander, do you prefer me in Empery-style clothes, or Union-style clothes?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "When I'm with you, I feel energized and my productivity goes through the roof. Perhaps... this is your magic spell? Hehe~",
	main = "My friends from the Dragon Empery told me about a lot of fascinating legends! Commander, do you want to hear them too? |Recently, I tried to learn the bamboo flute. Commander, want to give it a listen? |Ugh... calligraphy is really difficult...",
	touch = "There's still a lot of work left to do... but don't worry, Commander! Let's knock it out together!",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Commander, want to take a break?",
	battle = "",
	id = 101382,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "C-Commander, the buns are going to get messed up...",
	feeling2 = "",
	login = "There is a proverb from the Dragon Empery: \"A day's plans begin in the morning.\" Even if it's not the morning though, don't you think it's important to start off on the right foot, Commander?",
	detail = "There are many differences between the Eagle Union and the Dragon Empery, but the one thing that doesn't change no matter where you are is everyone's desire for a better future.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[101390] = {
	hp_warning = "Oh no... ",
	feeling3 = "My cooking would be perfect if I stopped trying to study weird things? Well, that's a darn shame! If you ask me, the element of surprise is the most important spice!",
	mail = "Commander, there's mail for you. Don't forget to read it!",
	expedition = "Commander, a commission has been finished!",
	win_mvp = "I'm number one? Um... as long as I can be of help to you, I'll be happy...",
	home = "Commander, good work~ Would you like to have a meal? I kept your food warm.",
	unlock = "Hello Commander, I am the Fletcher-class destroyer, Mullany. From today onwards, we'll be spending a lot of time together. Please take good care of me!",
	touch2 = "C-Commander... so you're also interested in the racy stuff...",
	mission = "Work hard to finish your missions, Commander~",
	vote = "",
	drop_descrip = "Fletcher-class Destroyer - Mullany (DD-528)",
	feeling4 = "Commander, are you keeping up with your schedule? If you feel like you can't manage everything alone, please let me handle your domestic affairs~",
	lose = "Commander, I'm sorry...",
	feeling1 = "Cooking for someone you don't like is suffering...",
	skill = "I'm ready to go!",
	upgrade = "Ah! An inspiration for my new recipe!",
	propose = "Commander, would you like me to keep cooking for you every day, even after a long, long time? Hm, you'd like there to be fewer weird dishes? Hehe, I guess I can manage that~",
	feeling5 = "You feel bad for always imposing on me? It's fine, it's fine! I'm happiest when I can be of use to the one I care about~ so feel free to rely on me even more from now on!",
	main = "Aww... I thought I followed the recipe perfectly, so how did it turn out like this...? |Commander, make sure to strike the right balance between work and leisure! It's not good to be lazy or overworked~ |Commander, do your best! Believe in yourself, you're the greatest!",
	touch = "Uhh... the black smoke coming from that side of the kitchen? Ahaha... ha... I have no idea what you're talking about~",
	voice_key_2 = -1,
	mission_complete = "Mission rewards, huh... Should I also prepare something for you, Commander?",
	battle = "I have to work hard for Commander today as well~",
	id = 101390,
	gift_dislike = "",
	gift_prefer = "Wow! Is it someone's birthday or something?",
	profile = "The Fletcher-class is pretty big, so it's not strange that you haven't heard of me. Though I had my fair share of dangerous moments, I managed to return peacefully. Right after that, I even went to live the Dragon Empery for a while! Is that why you think I look a bit bigger? Who knows~ ",
	voice_key = 10139,
	headtouch = "Being treated like a kid... feels a bit weird... ahaha...",
	feeling2 = "Commander, what are your interests? My hobby is cooking - though sometimes weird stuff come out, it usually tastes pretty good anyway. Mhm!",
	login = "Commander, have you eaten? Should I prepare something for you?",
	detail = "Commander, please let me know if there's anything you need me for.",
	couple_encourage = {
		{
			{
				10109
			},
			1,
			"Fletcher, I'm coming to help you!",
			0
		}
	}
}


