_G.pg.base.ship_skin_words[101452] = {
	hp_warning = "",
	feeling3 = "",
	mail = "You've got a letter, Commander! ...Come to think of it, I should send out some calling cards, too.",
	expedition = "",
	win_mvp = "Ahahah! Another huge haul and another star on my treasure list!",
	home = "Hey! Welcome back, Commander! Quick, swap personas! We've got a case to do, partner!",
	unlock = "Heheh! Policewoman who protects the city's order by day, vigilante who takes from the rich and gives to the poor by night! She is phantom thief Miss Terious, or PhantoM for short! Your riches are now mine! Your dumb little traps wouldn't catch me in a hundred years!",
	touch2 = "Heheh. Who's your favorite between policewoman Allen and phantom thief Allen?",
	mission = "",
	vote = "拉票描述",
	drop_descrip = "Heheh! Policewoman who protects the city's order by day, vigilante who takes from the rich and gives to the poor by night! She is phantom thief Miss Terious, or PhantoM for short! Your riches are now mine! Your dumb little traps wouldn't catch me in a hundred years!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Ahah! I just got a great idea! Next time we get the chance, we should form, like, a super legendary phantom thief team. Think about it – we're as close as close gets, so our acting and teamwork would be smooth as butter! Give it some thought!",
	main = "\"The world-renowned phantom thief has come. The treasures I called out are now mine!\" ...Yeah! I referenced some other movies and came up with this line. I'd say I nailed it!|Leaving a calling card and putting your target on edge, then stealing their treasure with ease despite the high security... Now THAT'S a challenge worth taking on, heehee.|A police officer and a phantom thief think and operate completely differently, but I'm the flexible type, so I can switch between the two like it's the most natural thing ever!|You can change costumes from police to thief in an instant with just one easy trick. Wanna know it? I'll tell you if you're interested!|Is there any treasure only I could steal? Shh, it's daytime, and I'm still a police officer! Let's save this convo for Miss Terious to answer later tonight! Heehee♪",
	touch = "Sheesh, it's not easy playing your role, Commander. Do you need script revisions or direction? Don't be shy to ask for anything you need!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 101452,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "PhantoM has come! The treasure I'll be stealing today is your heart! How's that for giving you palpitations?",
	detail = "Ahah! It's pretty fun to play a double-agent thief! Cracking down on crime in daylight, then thieving for the good of the people in moonlight... The two sides contrast nicely with each other and it's surprisingly invigorating!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[101460] = {
	hp_warning = "All right, no more messing around...",
	feeling3 = "Hm? Why do I always just sit and stare when you take me in as the secretary? Becaaaause... you never explicitly ask for help? If you need something done, just like, tell me? I'm not the most attentive person in the universe, so sorry for that.",
	mail = "Kind of curious who sent that unread letter on your desk.",
	expedition = "A commission's been completed. Just throwing that out there before I forget.",
	win_mvp = "Cool beans. I wasn't trying to style on 'em, but I'll take any commendations I'll get.",
	home = "Hum-hmmhm~♪ Oh, welcome back.",
	unlock = "Fletcher-class Stephen Potter here. You've probably met a million of my sisters already, so I'll spare you my life story. See you around.",
	touch2 = "Whoa! Talk about a blunt-ass approach...",
	mission = "Hey, a new mission! Oh, whoops... I guess we've both gotta actually do work now that I've said that.",
	vote = "",
	drop_descrip = "Fletcher-class destroyer – Stephen Potter, Hull Number DD-538.",
	feeling4 = "It's getting harder and harder to tune you out of my mind... No, I don't mean that in reference to like, work, my free time, or whatever... I mean you, Commander. I'll just keep my eyes on you for now.",
	lose = "Crap. I went too easy on 'em...",
	feeling1 = "Yeah, no, I'll find someplace less boring to hang out. Hit me up only if you've got business with me.",
	skill = "Let's get this over with.",
	upgrade = "Welp, guess the Slacker Council has to disband for the day.",
	propose = "It's gonna be so tiring, dealing with the responsibilities that come with getting hitched... Just saying, that's all. Hehe, I can handle a bit of fatigue as long as I've got you, sweetheart.",
	feeling5 = "Well yeah, I've thought about love before? It's not alien to me. Although thinking about it drains too much brainpower and just makes me sleepy in the end. I'd rather just be with you, Commander, and figure it out over time.",
	main = "Dang, you caught me spacing out at work. ...Oh? Maybe you didn't after all? Cool. I'll just get back to doing it then.|Hey, how about a bit of jazz? Chill, I'm just getting up to put a song on. I'm not gonna bail on you or anything.|Mind if I borrow your coat, Commander? Thanks. This will work great as a blanket.",
	touch = "You want some gum? 'Kay. Mint or orange flavor?",
	voice_key_2 = -1,
	mission_complete = "Finished a mission, huh? Cool, then let's take ten to veg out.",
	battle = "All right, since I've gotta take this flagship thing seriously... Let 'em have it, girls!",
	id = 101460,
	gift_dislike = "",
	gift_prefer = "Whoa, getting exactly what you wanted all of a sudden's kinda scary! I'm super happy, though! Thank you♪",
	profile = "My record's got the usual destroyer stuff. You know, did anti-air duty, hunted a submarine, and went on the odd rescue mission. So basically, I can do anything a destroyer should be able to, just don't expect me to singlehandedly save the day like some superhero.",
	voice_key = 10146,
	headtouch = "Okay, now I think I get why some girls have headpat addictions.",
	feeling2 = "You need help with something? I've got a bazillion sisters, why not try asking them first?",
	login = "Welcome to the circle of hell known as \"the office.\" Relax, I'll lend a hand if the cauldron gets too hot for you.",
	detail = "Here to chillax and hang out, eh, Commander?",
	couple_encourage = {
		{
			{
				10109,
				10110,
				10111,
				10112,
				10113,
				10114,
				10115,
				10129,
				10130,
				10131,
				10133,
				10134,
				10135,
				10138,
				10139,
				10141,
				10142,
				10143
			},
			2,
			"I'm gonna chill for just like, a little bit. Don't rat me out, 'kay?",
			0
