_G.pg.base.ship_skin_words[101470] = {
	hp_warning = "Mr. Bear, save me...!",
	feeling3 = "Commander, are you curious about Mr. Bear? T-Then, I'll introduce him to you.",
	mail = "Mr. Bear, bring the mail over to the Commander.",
	expedition = "A commission has been completed. Umm, if you need any help, I don't mind...",
	win_mvp = "Whew... That should give me a bit of leeway...",
	home = "Commander, umm... I don't know if these will be of any use, but... (Morrison hands you some files)",
	unlock = "Phew... Finally got here in one piece... Ah, um, are you the commander? My name is Morrison. Yes, the Fletcher-class Morrison with way too many sisters...",
	touch2 = "M-Mr. Bear is on a rampage?!",
	mission = "Commander, if you need any help completing the missions, I don't mind...",
	vote = "",
	drop_descrip = "Fletcher-class destroyer – Morrison, Hull Number DD-560.",
	feeling4 = "Commander, um, could I have a bit of your time...? I wanted to get your input on what kinds of things I could do to improve upon Mr. Bear's specs... ",
	lose = "Oww... Ugh, I want to go back to port...",
	feeling1 = "Just like I thought, things are better without me around...",
	skill = "Does anyone need any help?",
	upgrade = "I really don't think you need to go that far for someone like me...",
	propose = "Phew... I've worked hard to prepare myself for this moment, so it's okay. Commander, if it's you, I'm okay with it...! Breathe in... Breathe out... C-C-Commander, u-u-um, I-I-I've finished preparing my heart! I-I'll be in your care!",
	feeling5 = "Commander, am I helpful to you? I'm not a bother, am I? ...Mm, every time I hear your words of reassurance, I can relax a bit... Thank you very much, Commander.",
	main = "I'd really like to get my hands on a few sets of the Iron Blood's rigging... Heh, hehehe...|Y-yes, you called? ...You didn't...? I'm sorry...|It's sunny out today... Though, it's not like sunny days are always good either.",
	touch = "Mr. Bear, why don't you greet the Commander? Yes, normally, just like this... P-please keep your paws to yourself!",
	voice_key_2 = -1,
	mission_complete = "You completed the missions? That means that I'm free for the time being, right?",
	battle = "N-not another battle...",
	id = 101470,
	gift_dislike = "",
	gift_prefer = "Wh-why are you so nice to me...?",
	profile = "I'm the Fletcher-class destroyer, Morrison. I participated in anti-submarine warfare and rescue missions with my allies... If there's anything you want me to do... I-I should be able to do it.",
	voice_key = 10147,
