_G.pg.base.ship_skin_words[101472] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "\"Welcome back, Milord. Your ninja servant Morrison awaits your orders\"... Ugh, this is so embarrassing...",
