	feeling2 = "",
	login = "Commander, what are you ordering today? You'd like my recommendation? Hehe, okay!",
	detail = "There are rumors of a really attractive ranger coming by the tavern. Can you guess who it is? It's you, of course! Next drink's my treat.",
	couple_encourage = {}
