_G.pg.base.ship_skin_words[101530] = {
	hp_warning = "This GOAT never loses...!",
	feeling3 = "(Keeping up this bad-girl persona is going to be hard, but will the Commander like me if I don't?) 'Sup, Commander. Here to beg the GOAT to stop wreaking havoc on your life?",
	mail = "(Hmm... My notes say we should have work mail coming right about now...) Oh! Commander, you've got new mail! How do I always notice first? H-how should I know?!",
	expedition = "Oi, Commander! The commission team's back, so how about we go see them? I-I wanna help... I mean, I wanna help PRANK them!",
	win_mvp = "I told you I'm the strongest, baddest babe out there! (Heheh, this cool smirk is sure to steal the Commander's heart!)",
	home = "Miller the GOAT has cleaned up your office for you! ...Thanks? No thanking me! I didn't do it for you – I did it so I'd have more fun wrecking the place!",
	unlock = "Heheh! The strongest, baddest girl in the port, Miller the GOAT has finally arrived! Hey you, are you ready to turn this place upside down?! ...B-bwuh? Why isn't the Commander saying anything? Was my carefully practiced greeting weird...?",
	touch2 = "I-I may be a bad girl, but rules are rules! Go write an apology letter, NOW!",
	mission = "Commander... How do you still have so much work left over? ....Because you know I'll take care of it later? I-I'd never do that! It's the elves living in your floorboards! Th-that's gotta be it!",
	vote = "",
	drop_descrip = "Fletcher-class destroyer – Miller, Hull Number DD-535.",
	feeling4 = "Commander! Check out this new prank I thought of! It's really original... Whoa! Don't turn the page! \"Being bad to attract the Commander's attention\"? You must've misread it! Turn it back already! Uuugh... Give me back my notebook, please...",
	lose = "Damn...! Does this mean I still haven't worked hard enough?!",
	feeling1 = "Hmph. I knew you wouldn't understand me – just like everyone else. I wouldn't... I wouldn't be sad about that...!",
	skill = "Behold my power!",
	upgrade = "Yeeeeah! I'm the baddest girl around!",
	propose = "Mm... If I take this, I'll have to act a certain way to keep your attention, won't I? I'll have to be a good girl, won't I? ...Y-you don't care, as long as everything's in moderation? Y-yeah, you're right! That's how the GOAT operates! I knew you'd understand me!",
	feeling5 = "Umm... Commander, I might not be as cool and bad as I present myself... Do you still like me, though? I'm so selfish and annoying... Huh? You think that's actually cuter?! C-cut that out! ...I like you too, okay?",
	main = "Heheh, I modded my uniform again today. Now I'm even badder... You think it's cute how I'm dressed up? Nuh-uh! Bad girls don't dress up cute!|Hm? All of my sock holes are in the same spots? Yeah, duh, because I made them on purpose... Ack! I mean, they're all keepsakes from my dirtiest deeds! It's just a coincidence that they're all in the same spots! I did NOT do it on purpose!|Heheheh! See those documents there, Commander? I shuffled them all out of order! Now you'll never find the important ones, 'cause they're on the bottom... WHAT?! That made it EASIER to plan out your work?!",
	touch = "Hm? What's the matter? Need something from the GOAT?",
	voice_key_2 = -1,
	mission_complete = "Mission complete! Wait, why are there only rewards for you? Bah, forget it. The GOAT needs no charity.",
	battle = "Heheh, Miller the GOAT is ready to kick ass!",
	id = 101530,
	gift_dislike = "",
	gift_prefer = "A p-present for me? If you care that much... I'll take it, okay?",
	profile = "Heheh, you wanna know more about this GOAT? I'm pretty famous for being a bad girl, ya know. ...People say I'm sweet and helpful?! WHO?! I can't have people spreading lies behind my back... Hwuh? Everyone did? Urrrg...",
	voice_key = 10153,
	headtouch = "Hey! No touching the GOAT's head... Whoa, you listened?! Stay a little longer!",
	feeling2 = "Would I look badder if I had an arrogant smirk? Man, it's hard... Hwuh? C-Commander? No, I'm NOT practicing how to smirk like a bad girl! This is the wicked coolness this GOAT was born with!",
	login = "Umm... O-oh! I-if it isn't the Commander! What's with the bucket in my hand? Uhh... Well, uh... It's kind of a mean prank, so I only put a LITTLE bit of water in it, but I don't want to get your documents wet... so I was just putting it away!",
	detail = "When the Commander usually wants lunch... Your favorite tea... The last time you praised me... Mm, I give it two stars. I'll start practicing my new cool look tomorrow – Aaaargh! H-how long have you been there?! Stop peeping when I'm journaling, stupid!",
	couple_encourage = {
		{
			{
				19905
			},
			1,
			" Hmm... Is that supposed to get the Commander's attention?",
			0
		},
		{
			{
				40603
			},
			1,
			" You call yourself a good girl?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[101531] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Commander! New mail for you! Ugh, I told you to stop asking why I always know first!",
	expedition = "You're going to see the commission team? Hmph. Then I'll have to buy time here!",
	win_mvp = "",
	home = "Where'd you go? You gotta tighten up – what if bad girls catch you and... Well, I guess the coolest, strongest, baddest, GOATiest experiment out there will have to save you~ (I could use an opportunity to show the Commander my skills!)",
	unlock = "Don't move, Commander! ...Heheh, looks like it's time for the GOAT to take the stage. That was a sick entrance, right?! Hm? N-no, I'm not here to help you out! I'm here to, uhh... Yeah, to take revenge on the scientists who experimented on me!",
	touch2 = "Hyah?! Th-these claws are sharp, so be careful...",
	mission = "Do you have missions to do? I didn't think you'd be so focused on work at a time like this...",
	vote = "",
	drop_descrip = "Don't move, Commander! ...Heheh, looks like it's time for the GOAT to take the stage. That was a sick entrance, right?! Hm? N-no, I'm not here to help you out! I'm here to, uhh... Yeah, to take revenge on the scientists who experimented on me!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Heheh! I might be a monster, but as long as you know I'm a good girl... I mean, the baddest and coolest girl out there, it doesn't matter what anyone thinks! ...You think I look cute like this, too...? G-geez, now isn't the time for that!",
	main = "Commandeeer! My tail's cool as hell, right? *wag* *wag* ...Huh? I look like an attention-seeking kitten? Grrr... I'm a scary monster!|It's okay, Commander, let this bad monster girl... that is, Miller the GOAT, rescue you! Just take my hand – Huh?! You can't get a grip?!|Mmgh... Here, Commander. It took a lot of work to get these keys! I wanted the two of us to escape together, but there's no choice now! Hurry! I'll hold them back!",
	touch = "Hm? Did you find a way out?",
	voice_key_2 = -1,
	mission_complete = "Mission rewards... Do they have any clues to help us get out of this mess?",
	battle = "",
	id = 101531,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Mm! It feels weird? Well, what do you want me to do about it?",
	feeling2 = "",
	login = "W-welcome back~ Did you find the exit? Oh, okay... (Maybe I should just make an exit? I don't wanna hurt the Commander, though.)",
	detail = "Why am I an experiment gone wrong when everyone else is a nurse or a doctor? Umm... 'Cause it's cool? I can't get your attention if I go along with all the other sheep! Heheh, besides, wouldn't it be unforgettable if the monster saved you?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[101550] = {
	hp_warning = "My defense systems need urgent maintenance!",
	feeling3 = "If it means removing all safety risks, I don't mind working overtime. You don't have to worry about me.",
	mail = "Commander, new mail came for you. If you forget to pick it up, I'll remind you again later.",
	expedition = "Commander, the commission team just returned. I asked them to collect combat data for their equipment, so let's go greet them together.",
	win_mvp = "Hmm... Well, my combat performance seems to be within the standard deviation.",
	home = "Commander, how are your missions going? I'll check all of your equipment again before you leave. Best have everything in tip-top condition, after all.",
	unlock = "The name's Clarence K. Bronson. I'll be testing, evaluating, and improving equipment around the port starting today. If you ever need to be apprised of our tech status, ask me anytime.",
	touch2 = "C-Commander...? Umm, this is going to interfere with my... sensor calibrations...",
	mission = "Commander, you have unfinished tasks. Doing them quickly will reduce the number of risks we face.",
	vote = "",
	drop_descrip = "Fletcher-class destroyer – Clarence K. Bronson, Hull Number DD-668.",
	feeling4 = "Commander, I have a slight technical problem. I-if you don't mind... I could really use your advice. Umm, I think your advice... would give me the spark of inspiration I need...",
	lose = "It's my fault for not detecting our shortcomings sooner...",
	feeling1 = "Don't get in the way of my work, please. You'll lower the reliability of my test results.",
	skill = "Removing all risk factors!",
	upgrade = "Equipment performance improved... I'll test its stability now.",
	propose = "You want... to make an oath with me? Th-this is uncharted territory... I have to remove the risks! First, we must make sure the ring is my size... Would you please put it on my finger, Commander?",
	feeling5 = "C-Commander, umm... Could I ask you to hold me for a while? I'm in the middle of an important test... That is, testing how important you are to me... I think I have a conclusion, too. To me, you are... irreplaceable.",
	main = "Leave all equipment testing to me. I'll deal with any hidden risks.|Test reports for this batch are complete. I recorded potential risks and improvements, and I await your review.|Commander, did you read those test reports? The ones for torpedoes, main cannons, and aerial bombs. Do you think we should start with a smaller deployment? No worries – they all passed safety testing. The data doesn't lie.",
	touch = "You're... thanking me for my work? I-I was just... doing my job, that's all...",
	voice_key_2 = -1,
	mission_complete = "So you've finished your work before the deadline? Not bad. Leave the rest to me.",
	battle = "All combat units have passed final inspections. Ready to engage.",
	id = 101550,
	gift_dislike = "",
	gift_prefer = "Oh, a gift! I-I definitely don't dislike it...",
	profile = "I'm Clarence K. Bronson, a Fletcher-class destroyer and equipment tester working under the Eagle Union. If you have any new machines that haven't been vetted for stability, I'll examine and analyze it per my checklist to guarantee your safety.",
	voice_key = 10155,
	headtouch = "Huh?! O-oh no, one of the machines is throwing an error. I-I'd better go check it!",
	feeling2 = "Equipment performance and reliability must be tested in real combat. I've made preliminary assessments of the testing risks, so don't be worried.",
	login = "Good morning, Commander. I've finished my routine inspections. Would you like to check behind me?",
	detail = "The riskier and more unstable your machine is, the more meticulously it needs to be tested. That's why my job exists... I hope you provide good insurance, though.",
	couple_encourage = {
		{
			{
				10110
			},
			1,
			"That rigging... Uh, maybe it could use another round of testing?",
			0
		},
		{
			{
				60802
			},
			1,
			"Your new inventions are safe in my hands!",
			0
		}
	}
}


