_G.pg.base.ship_skin_words[102010] = {
	hp_warning = "",
	feeling3 = "Mmph... C-come on, surely you like your girls with a little more meat on them!",
	mail = "You've got mail, Commander! Maybe it's the snacks I ordered yesterday?",
	expedition = "Don't look at me like that, Commander. I'd take on commissions too if they gave snacks as rewards!",
	win_mvp = "Oh yeah! There's no armor my guns can't penetrate!",
	home = "Commander! What should we have first? Breakfast? Or lunch? Or maybe dinner~?",
	unlock = "Omaha-class cruiser - Omaha! Greetings, Commander! You could say that I'm a fleet veteran~!  Hehe~! So, since this is the first time we meet, shouldn't you celebrate by giving me some sort of gift?",
	touch2 = "You're not \"checking if I've gained weight\" at all! You're just a big old pervert, Commander~!",
	mission = "Huh? A mission? Let me just finish these chips first...",
	vote = "",
	drop_descrip = "Omaha-class light cruiser – Omaha, Hull Number CL-4!",
	feeling4 = "Maybe I should lose some weight... What, isn't it normal to try and look good for the person you like? Besides, it's not like I'm really fat or anything!",
	lose = "Wait until I come back with a full belly!",
	feeling1 = "Something to eat? I'm actually full right now. No thanks, Commander.",
	skill = "Oh no! I loaded my guns with snacks instead!",
	upgrade = "I got stronger, but I also got hungrier at the same time!",
	propose = "Now we have a promise, Commander. You take care of the cooking, and I'll take care of the ea... housework! That way I can eat and still lose weight! I'm so smart!",
	feeling5 = "Commander, from now on, if I don't lose weight, then that's your fault! You have to take responsibility! How? By taking care of me for the rest of your life, of course!",
	main = "Ahh... I'm so hungry...|You don't eat snacks, Commander? How dull your life must be!|Have you eaten yet, Commander? Cause you don't look too great...",
	touch = "Hm... I'm getting a bit chubby? No! I'll never give up my search for the most delicious food!",
	voice_key_2 = -1,
	mission_complete = "Feed me, feed me! We'll talk about losing weight tomorrow!",
	battle = "I'm invincible now that I'm full! You can't stop me from fighting until I'm totally exhausted!",
	id = 102010,
	gift_dislike = "",
	gift_prefer = "Whoa! This looks yummy... I mean, cute!",
	profile = "Omaha has arrived! I was born after the first World War, but as a reconnaissance ship, I've got a lifetime's worth of intel in my brain!",
	voice_key = 10201,
	headtouch = "",
	feeling2 = "Hmm? I only like commanders who can actually cook!",
	login = "Commander~ Any fun things you want Omaha to do today?",
	detail = "M-my belly isn't fat at all, Commander! Ah, don't look at it!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102020] = {
	hp_warning = "",
	feeling3 = "You want to know more about me? Hmm... you may be the first person to treat me like an equal. I'm happy about that, I suppose.",
	mail = "Your mail has been sorted. Remember to read your messages thoroughly, please!",
	expedition = "It's almost time, Commander. I'll go ahead and welcome the girls back from their commission.",
	win_mvp = "You can't use the same trick on me twice!",
	home = "You did quite well, Commander!",
	unlock = "I'm Raleigh, the Omaha-class light cruiser. Please sign this contract here... There we go. I'm hoping we'll make a good team from now on, Commander.",
	touch2 = "I'm not immune to getting angry, you know... Co-man-der!",
	mission = "Commander, please don't forget about your unfinished missions!",
	vote = "",
	drop_descrip = "Omaha-class light cruiser – Raleigh, Hull Number CL-7!",
	feeling4 = "You've been taking it pretty easy recently, Commander... *Sigh*... I guess some of the blame is mine to share... It's hard to be strict with someone I like...",
	lose = "Phew... That was close... I nearly...",
	feeling1 = "I'm not a kid, okay!",
	skill = "Let me show you some textbook maneuvers.",
	upgrade = "Now I can properly mentor you, Commander.",
	propose = "To receive something so precious from a student... I should be ashamed to call myself a professional mentor... But you make me...",
	feeling5 = "You're calling me 'professor' in such an... interesting way when we're alone. Are you expecting to receive private lessons? You're just like a little kid, Commander...",
	main = "Shall we begin our training, Commander?|For a beginner, every bit of training is very important~!|My name is Raleigh, not... that! Also, don't forget the \"Ms.\"!",
	touch = "Please don't tug me like that... I'm not a kid!",
	voice_key_2 = -1,
	mission_complete = "Please don't forget to claim your mission rewards.",
	battle = "Please pay attention, everyone! This is a good chance to get some real combat experience~",
	id = 102020,
	gift_dislike = "",
	gift_prefer = "For me? You really put thought into this, Commander.",
	profile = "I'm the training officer of the Omaha-class fleet - Raleigh. I'm going to be very strict with anyone who won't listen to what I say!",
	voice_key = 10202,
	headtouch = "",
	feeling2 = "Commander, mature people like you need to pay attention on the job.",
	login = "Hello, Commander. I've been waiting for you. Oh my, look at the time! Shouldn't we start the training now?",
	detail = "Make sure you ask me any questions if you're lost before we head out!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102030] = {
	hp_warning = "",
	feeling3 = "It feels like I've been managing your personal affairs more than foreign affairs lately, Commander... Surely this isn't on purpose, is it?",
	mail = "There's mail for you, Commander... Hm? Where was this sent from?",
	expedition = "Though it may be tough for everyone, completing commissions like this will help raise our reputation. Let's start another one as soon as possible.",
	win_mvp = "Now then, let us talk about reparations.",
	home = "Good work, Commander. I will make sure that the results of your last battle come to good use.",
	unlock = "I am Brooklyn. I am an elite cruiser, so you may let me handle all foreign diplomacy matters.",
	touch2 = "A diplomat is not the same thing as a secretary... Please, restrain yourself, Commander!",
	mission = "Completing missions is a good way to demonstrate our capabilities. Please take a look at some of the new missions.",
	vote = "",
	drop_descrip = "Brooklyn-class Light Cruiser – Brooklyn, Hull Number CL-40!",
	feeling4 = "Commander, a diplomat doesn't usually take on the role of a secretary... but I personally wish to deepen my relationship with you.",
	lose = "Now we won't have an advantage during the negotiations...",
	feeling1 = "Commander, I'm thinking of resigning because you just don't seem like you're worth the effort.",
	skill = "Deterrence is also a part of diplomacy...",
	upgrade = "Power is the foundation of gunboat diplomacies. Thank you.",
	propose = "Thank you, now I have more confidence in managing the fleet's affairs. Hm? I may act on your behalf for a little? What a pleasant joke. ... At any rate, I will not let you down.",
	feeling5 = "I wish to fight only for you, to give you the upper hand... Maybe I am no longer suited to be the entire fleet's diplomat.",
	main = "It's important to communicate with other nations.|Please don't stare at me in such a weird way.|I may be a diplomat, but don't even think about underestimating my power.",
	touch = "Are you interested in my tanned skin, Commander?",
	voice_key_2 = -1,
	mission_complete = "Here is a summary of the rewards. Your confirmation, please, Commander.",
	battle = "Fire at will! I have you covered!",
	id = 102030,
	gift_dislike = "",
	gift_prefer = "Presents are an indispensable part of diplomacy. But either way, I'm glad to get a present from you, Commander.",
	profile = "As the representative of the then newly constructed pre-war cruisers, I was put in charge of foreign diplomacy. That said, my firepower is never to be underestimated, so please put your mind at ease.",
	voice_key = 10203,
	headtouch = "",
	feeling2 = "Commander, my responsibility is to ensure that you have the upper hand in foreign affairs. Rest assured, I am an expert in that area.",
	login = "You came just in time. A few files need your signature.",
	detail = "This information is confidential, so please keep it a closely guarded secret.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102040] = {
	hp_warning = "My hand is calling out to me to seize victory!",
	feeling3 = "What's the matter? If you're okay with me then I can give you some advice!",
	mail = "Hey! Commander! Your mail is here!",
	expedition = "Commission completed... Hey, isn't it about time you let me head out on one?",
	win_mvp = "Hahah! Aren't there any strong enemies left for me to fight?",
	home = "Looks like we made it back safe and sound as usual today!",
	unlock = "Are you the commander? I'm Phoenix. That's right, the legendary phoenix! Do you have what it takes to lead me?",
	touch2 = "Hey~! Be a gentleman!",
	mission = "How could you fall behind on something as simple as missions?",
	vote = "",
	drop_descrip = "Brooklyn-class light cruiser – Phoenix, Hull Number CL-46!",
	feeling4 = "Although I respect that man, you're still you, Commander. As long as you're with me, I'm invincible!",
	lose = "Tsk, I'll get you for this!",
	feeling1 = "Get outta here, coward!",
	skill = "Paint the East... in blood...!",
	upgrade = "Alright! I've gotten stronger!",
	propose = "... Thank you. I'll accept it. Also, um... I don't really know how to talk all sweet or flirt or anything like that, but now that you've chosen me, I promise I won't let you down!",
	feeling5 = "I see. It's no wonder that whenever I'm with you, I'm in such high spirits! I feel like my heart is on fire! This is it, this is love... I've never experienced this before...",
	main = "My motto is: \"be the best at everything\"!|Is the sun bigger in Argentina?|There's nothing more thrilling than coming back from the verge of death!",
	touch = "It's here, it's here! Want to head out now?",
	voice_key_2 = -1,
	mission_complete = "Looks like our well-deserved rewards have been delivered.",
	battle = "Look to the east! It's burning red!",
	id = 102040,
	gift_dislike = "",
	gift_prefer = "Whoa! I've been gunning for this for a while! Thanks!",
	profile = "I'm Phoenix. I once escorted a certain important person. Just like a phoenix, no matter what happens to me, I'll always come back from death! Throw all the dangerous missions you've got at me, I won't let you down!",
	voice_key = 10204,
	headtouch = "",
	feeling2 = "Only those who aren't afraid of death deserve to live! Ahh, don't be afraid Commander, I don't mean that literally! What I meant to say is that it's not about living or dying, it's about what mindset you have!",
	login = "Hey, Commander! I'll protect you, like I always do!",
	detail = "What's the matter, Commander? You look kinda emotionless.",
	couple_encourage = {
		{
			{
				10504
			},
			1,
			"C'mon, sis, brighten up a little.",
			0
		},
		{
			{
				7
			},
			3,
			"Chicken? I'm a phoenix!",
			4
		}
	}
}


_G.pg.base.ship_skin_words[102050] = {
	hp_warning = "SG, lock on the enemy position!",
	feeling3 = "My expression? Ah... it's because I left while we were on the losing end of the war... I might just not be so used to peace and happiness. But don't worry, I'll be fine!",
	mail = "You've got new mail. It's important to stay in touch with your loved ones.",
	expedition = "Hey, Commander, could I lend my SG radar to my sisters this time?",
	win_mvp = "... We actually won?",
	home = "Did everyone make it back safe and sound? Good. But there's spare parts lying around in the docks now... I wonder why...",
	unlock = "Nice to meet you, Commander. I'm Helena. My strong suit is enemy reconnaissance. Please... guide us towards victory.",
	touch2 = "If this makes you feel good, then... I'm fine with it.",
	mission = "Bit by bit we'll build the foundation for victory. We'll start by doing missions.",
	vote = "",
	drop_descrip = "Brooklyn-class Light Cruiser – Helena, Hull Number CL-50!",
	feeling4 = "I think I've been more at ease lately... No, I was just too tense up until now. It's all thanks to the courage you've given me by being beside me.",
	lose = "... Please, save me... Ignore the enemy, just let them go...",
	feeling1 = "SG, protect me...",
	skill = "SG, give me your power!",
	upgrade = "I'll use this power to protect everyone!",
	propose = "A promise... from you, Commander? I see... I'm so happy...",
	feeling5 = "I believe that you will bring us hope, Commander. This time, I'll fight to the end... Just the thought of saying goodbye to the person I love makes me feel like my heart will tear in half...",
	main = "Are you trying to hide, Commander? No matter where you hide, I know where you are.|Commander, what should we do after the war?|If only my guns could be as strong as my radar...",
	touch = "Hm? I'm fine. I'm just... a little distracted.",
	voice_key_2 = -1,
	mission_complete = "Resources are no good if they just pile up. We should make use of them.",
	battle = "The enemy can't hide from me.",
	id = 102050,
	gift_dislike = "",
	gift_prefer = "I... kind of like this.",
	profile = "I was designed to be on par with heavy cruisers, but just my power alone isn't enough to save everyone... Commander, can you help me?",
	voice_key = 10205,
	headtouch = "",
	feeling2 = "If only my recon could help the others...",
	login = "... Ah, welcome back, Commander. Sorry, I was just brooding over something.",
	detail = "I can't rely on this thing alone...",
	couple_encourage = {
		{
			{
				10503
			},
			1,
			"Penny, cover me!",
			0
		},
		{
			{
				10502,
				10504,
				10508
			},
			2,
			"SG, full area scan! I will never let that tragedy repeat itself!",
			0
		},
		{
			{
				7
			},
			3,
			"Chicky Unit... sounds kind of cute!",
			4
		},
		{
			{
				10213
			},
			1,
			"St. Louis, please take the battle a bit more seriously...",
			0
		},
		{
			{
				10212
			},
			1,
			"Honolulu, I'm here to back you up!",
			0
		},
		{
			{
				10209
			},
			1,
			"Cleveland, we won't lose, right?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[102051] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "That's right...! You did a great job, me!",
	home = "Let me be part of the mission, Commander. My SG would surely be good to have.",
	unlock = "I... want to be part of the new year festivities too. Oh, you don't have to worry about me. I'm no longer the fledgling I once was.",
	touch2 = "C-Commander, please stop...",
	mission = "",
	vote = "",
	drop_descrip = "I... want to be part of the new year festivities too. Oh, you don't have to worry about me. I'm no longer the fledgling I once was.",
	feeling4 = "",
	lose = "It's okay, there's always the next time...!",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Commander? You don't have to worry about me. I was just thinking about how I now have friends and a sweetheart who I can celebrate the new year together with, and how unbelievably happy it makes me.",
	main = "My New Year's wish is... that I'll be more courageous and positive, and that no harm will come to any of my friends...|For this year's shrine visit, the whole Brooklyn-class, Cleveland, and her Knights of The Sea all went there together as one big family.|It's snowing... I never realized how peaceful and beautiful snow can be.",
	touch = "Huh? I was just thinking about what I should do during New Year's... There are so many things I want to do.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "I... want to win!",
	id = 102051,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "It seems the New Year's spirit has swept over the entire fleet.",
	detail = "St. Louis must've had a lot of fun making me try out so many clothes... Do you really think I look cute this way, Commander?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102052] = {
	hp_warning = "",
	feeling3 = "",
	mail = "It seems you've got an invitation to another dance party... Hahah, you really are a superstar, Commander.",
	expedition = "Commander, let's extend an invitation to the commission team to join us for the party.",
	win_mvp = "Yeah, that's right...! You're awesome, Helena! ",
	home = "Commander, before we leave for the party, do you have any unfinished business?",
	unlock = "Um, Commander, could we... share a dance? I have things I want to tell you...",
	touch2 = "Eek?! ... Ah, sorry, did I step on your foot, Commander?",
	mission = "Commander, please go complete your missions. Don't worry, I'll be here waiting for you.",
	vote = "",
	drop_descrip = "Um, Commander, could we... share a dance? I have things I want to tell you...",
	feeling4 = "",
	lose = "It's okay, there's always next time...!",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "You and my friends have always taken care of, looked after, and protected me. But that can't go on forever. I want to stand beside you and become someone people can count on... So, could you wait for me just a little longer... please?",
	main = "Commander, you know something? It's thanks to you that I've become as cheerful as I am now. Ahah~|I'm not going to be scared or hesitate ever again because you and my friends are always with me.|My dance partner will be... No, it'll just be you, Commander. I have so many things I want to tell you.",
	touch = "I'm all ready, Commander. Shall we dance?",
	voice_key_2 = -1,
	mission_complete = "You really are incredible, Commander.",
	battle = "I... want to win!",
	id = 102052,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, the party is about to start.",
	detail = "In preparation for today, I got St. Louis to teach me how to dance. She laughed a lot at me, telling me I'm \"such a klutz\"... Ahah.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102053] = {
	hp_warning = "",
	feeling3 = "",
	mail = "A letter has arrived. Do you want to read it now?",
	expedition = "The commission team is back. No, it wasn't my SG that told me, but a friend. As for who... that's a secret.",
	win_mvp = "Thank you, SG. You help me push myself.",
	home = "Welcome back, Commander. If you, uh, have a moment, we could go for a swim... I know you just got back from the ocean, but... still?",
	unlock = "Commander, what do you think... umm... about this swimsuit? Actually, umm, never mind. If I were to hear your impressions directly, I'd be too embarrassed to stand in front of you... So, would you mind, umm... secretly whispering it to me?",
	touch2 = "Umm, I... *blushes*",
	mission = "Commander, please go complete your missions. Don't worry, I'll be here waiting for you.",
	vote = "",
	drop_descrip = "Commander, what do you think... umm... about this swimsuit? Actually, umm, never mind. If I were to hear your impressions directly, I'd be too embarrassed to stand in front of you... So, would you mind, umm... secretly whispering it to me?",
	feeling4 = "",
	lose = "Commander, over here! I'll keep you safe!",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Be confident, Helena. It's okay to fawn on the Commander. You started this when you mustered your courage, remember? So just... H-hey! Commander, would you mind... taking the lead for our date?",
	main = "SG, track the Commander's exact location. If we meet before I've mentally prepared myself for it, I might just freak out...|I like \"you're pretty\" over \"you're cute\" as a compliment... Oh, that doesn't mean you can't say I'm cute or anything... It's obviously up to you to decide how to compliment me, Commander, you can even use both, so... *whimper*...|Just tell me if anything feels wrong. It's my... No, it's all our job to ensure you don't have anything to worry about.",
	touch = "Mhm, I'm all ears. What is it, Commander?",
	voice_key_2 = -1,
	mission_complete = "You really are incredible, Commander.",
	battle = "Keep calm and focus, Helena!",
	id = 102053,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Heehee... *blushes*",
	feeling2 = "",
	login = "Whew... This breeze is lovely... Hey, Commander, for just a brief moment, I was thinking I could... be more daring around you...",
	detail = "I'm okay with wearing a swimsuit – we all wear them on the beach, after all. It's only when you look at me that I get all shy... It's a weird feeling.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102054] = {
	hp_warning = "",
	feeling3 = "",
	mail = "A letter? Ahh... Sorry, Commander, but please read that one yourself first.",
	expedition = "Uh-oh, the commission team is back... D-don't worry about me, you just go ahead and go out to meet them!",
	win_mvp = "Whew... I worked up a sweat. Oh, I guess I should bathe again when we get back...",
	home = "Welcome back, Commander. The bath will be ready in a few moments. Wanna join me? Also, want to try letting me wash your back?",
	unlock = "Eek! C-Commander? Um, I'm fine! Nothing's wrong, I just tripped on– Wait, why did the smart glass turn off?! Oh nooo!",
	touch2 = "Even though there's glass between us... *blushes*",
	mission = "There's no need to worry about the missions, Commander. We can take our time with them later.",
	vote = "",
	drop_descrip = "Eek! C-Commander? Um, I'm fine! Nothing's wrong, I just tripped on– Wait, why did the smart glass turn off?! Oh nooo!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "It'll be fine, Helena. You'll get to bathe with the Commander in just a minute, and then... Hm? Open the door so you can come help? Oh, right! I'm so forgetful. I should've invited you in the first– Ah, be careful!",
	main = "Bath items... Check. Same for the towels and bottles of sake... Oh, shoot, I forgot to pour the sak– Eek! The soap fell... I need to find it, and fast.|I've never run a bath quite like this before. It takes a lot more than just courage to take on new things. You know, like composure, knowledge, handiness...|Whew... This aroma of fruit and cypress makes me feel so relaxed. How about a whiff, Commander?",
	touch = "The soap fell? Umm, where did it go?",
	voice_key_2 = -1,
	mission_complete = "You never cease to amaze me, Commander. Oh, I'm almost done over here, too! I think!",
	battle = "I'm... okay!",
	id = 102054,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Since I'd never done this before, I researched everything from how to get ready to how to enter the bath, but in the end, nothing went as I'd planned... I should've just asked you in the first place.",
	detail = "It's only natural that I want to make the best of this luxury bath. Whether I can do it or not is a different matter, though...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102058] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission team has come back. That's at least some weight off my mind.",
	win_mvp = "Don't get complacent, Helena... You've got to get even stronger!",
	home = "",
	unlock = "Wh-what do you think, Commander? Does it suit me? ...I never could've imagined getting to wear this even in my dreams, let alone experience the bliss I feel now... Thank you so, so much.",
	touch2 = "W-wait, I need time to prepare myself...",
	mission = "",
	vote = "",
	drop_descrip = "Wh-what do you think, Commander? Does it suit me? ...I never could've imagined getting to wear this even in my dreams, let alone experience the bliss I feel now... Thank you so, so much.",
	feeling4 = "",
	lose = "It's okay, Helena. There's always next time...!",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "When I'm with you, I keep hoping you'll rely on me, but instead I'm the one who relies on you... It's sort of backwards, isn't it? Heehee... I'm so, so happy to be your wife, Commander.",
	main = "I'll cook dinner tonight! And breakfast tomorrow, and dinner after that, and breakfast the day after– Oops! I blurted all that without thinking...|Having experienced such bliss for a while now, I've started wishing for an even more blissful future... It's sort of selfish of me, but you don't mind, do you?|I can't be reliant on my SG forever... Huh? So I should turn to you for help instead? ...Okay! I'll try to, at least...",
	touch = "I should be fine if you, um, hold my hand for just another minute...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "I'm... going to win!",
	id = 102058,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Welcome back, Commander. My SG told me that you were on your way, but I had to see you with my own eyes.",
	detail = "I used to feel constant anxiety over if I'm capable or not, but nowadays... that anxiety's been overtaken by confidence, knowing all will be fine when you're with me. Heehee.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102059] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "SG receiving message... A commission team has returned to port.",
	win_mvp = "Don't get complacent, Helena... You've got to get even stronger!",
	home = "",
	unlock = "This new equipment... might take some time to get used to... N-no, I'm sure I can handle it now! Commander, Helena will... meet your expectations!",
	touch2 = "You really can't go around doing this, Commander!",
	mission = "",
	vote = "",
	drop_descrip = "This new equipment... might take some time to get used to... N-no, I'm sure I can handle it now! Commander, Helena will... meet your expectations!",
	feeling4 = "",
	lose = "It's okay, Helena. There's always next time...!",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I feel a bit more confident in myself when I'm with you, Commander. But I want more; I want to be the girl you rely on so I can be the center of your attention... It might be selfish to ask, but... will you love me?",
	main = "You want to know what my new and improved SG is capable of? All right... Find a place to hide that nobody knows about. Hehehe~|I think everyone would be better off living in the present without regrets than spend every day anxious about the future.|It's not enough to focus only on improving my equipment. I need to become stronger to use it properly, too.",
	touch = "",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "I'm... going to win!",
	id = 102059,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Welcome back, Commander. Let's get to work and do our best.",
	detail = "St. Louis always praises me like, \"my, how you've grown\" whenever I do anything... It's kind of embarrassing...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102060] = {
	hp_warning = "",
	feeling3 = "The bigger the better, don't you think? ...Hey! What are you staring at?! Gee, sorry for not being big enough, I guess!",
	mail = "You've got new mail! I wonder if any of the messages are from my sisters...",
	expedition = "Commander, the commission's done. Are we gonna go welcome the girls back?",
	win_mvp = "All targets eliminated. Requesting new mission!",
	home = "That's the Commander I know. No problem for you at all, right?",
	unlock = "I'm the anti-aircraft cruiser Atlanta. Kept you waiting, huh, Commander? But from now on you can rest easy and let me handle everything!",
	touch2 = "*Eek* W-what are you doing?!",
	mission = "So, does this mean you're leaving all your unfinished missions to me, Commander?",
	vote = "",
	drop_descrip = "Atlanta-class light cruiser – Atlanta, Hull Number CL-51!",
	feeling4 = "Are you fond of assertive big sister type characters? That is to say... someone like me...",
	lose = "Argh, this is bad... My big sister image is ruined...",
	feeling1 = "Sometimes I'm happy that I'm not actually your big sister...",
	skill = "It's on now!",
	upgrade = "Let me handle things from now on!",
	propose = "Thank you... From now on I'll... What? You'd prefer it if I took the initiative and gave it to you instead? Y-you have a point... Okay then, should we do it again from the start?",
	feeling5 = "... Huh? You want me to take the initiative? O-o-o-o-of course, I don't mind! I-I mean, I'm your big sister after all, so it's my job to guide you!",
	main = "Not being a flagship sure is more peaceful...|San Francisco was terrible to me! Just once is tolerable for accidental friendly fire, but she shot me well over ten times!|Shooting down aircraft is my specialty. Want me to teach you how to do it, Commander?",
	touch = "Mgh, don't touch me like that... My big sister image would be ruined!",
	voice_key_2 = -1,
	mission_complete = "Our mission rewards have arrived. I'll give my share of the rewards to my little sisters.",
	battle = "I'll show you what the tons-of-guns doctrine is really worth!",
	id = 102060,
	gift_dislike = "",
	gift_prefer = "Ooh, this is... Thanks a lot!",
	profile = "I'm the anti-aircraft cruiser Atlanta... I was the flagship of the 10th and 11th Atlantic cruising fleet and I've taken part in nearly every military operation in the Pacific. Even the President has given me praise!",
	voice_key = 10206,
	headtouch = "",
	feeling2 = "Being a big sister isn't just about looking like one, you need to have the personality of one as well. That's why you can depend on me all you want~!",
	login = "Commander, if you ever run into a problem, please tell me!",
	detail = "Ah, Commander's looking... I have to behave like a big sister!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102070] = {
	hp_warning = "",
	feeling3 = "Commander, can I go to bed with you again tonight? ... I feel very safe when I sleep next to you...",
	mail = "Commander... excuse me... here's your mail...",
	expedition = "Umm... Commander... there's a commission that's been completed...",
	win_mvp = "Phew... I almost got hit... *Sob*... I don't care about being the MVP... I'm just trying my best so I can come home in one piece...",
	home = "I'm really hoping this war will end soon... Once it's over, let's all go someplace together...",
	unlock = "I-I'm Juneau... I'm a cruiser... I'm scared of pain... *Sob* And I'm scared of you, Commander...!",
	touch2 = "Mmh... *Whimper*...",
	mission = "What? A mission? I don't mind as long as we aren't fighting submarines...",
	vote = "",
	drop_descrip = "Atlanta-class light cruiser – Juneau, Hull Number CL-52!",
	feeling4 = "I'm not afraid of having nightmares anymore... b-but can I still sleep together with you, Commander...?",
	lose = "That hurts! ... I can't feel my left foot... Someone come save me....!",
	feeling1 = "Don't come near me! ...Sorry, I think you're a little scary, Commander...",
	skill = "Me too! I-I'll give it my best shot!",
	upgrade = "I'll... try to work harder...!",
	propose = "...Mhm, I have faith in you, Commander... I told the people in my dreams that I've found happiness and would do my best to live on for their sake as well... I'm truly... truly happy right now...",
	feeling5 = "Now when I dream about those five brothers... I can see their faces clearly, and they bless me with their smiles... But somehow it was so sad it almost made me cry... *Tearful sobbing*... Can I really live happily together with you, Commander? It's not just a dream, right...?",
	main = "*Eek* Commander?! Y-you scared me...|I want to be brave... But it's really hard...|Commander, have I annoyed you in any way...?",
	touch = "Pl... please be gentle... I'm very susceptible to pain...",
	voice_key_2 = -1,
	mission_complete = "I don't need any rewards... just being here with everyone is enough for me...",
	battle = "Everyone... look after yourselves... and watch out for those mean submarines...",
	id = 102070,
	gift_dislike = "",
	gift_prefer = "I can... have this? I-I'll cherish it like it's my baby! Aaaah, I can't believe I said that!",
	profile = "I-I'm Juneau, an Atlanta-class anti-aircraft cruiser... Because I have high anti-air capabilities, I was assigned to a Task Force, but I'm actually scared of getting shot... Unfortunately I couldn't make it back home from Espiritu Santo...",
	voice_key = 10207,
	headtouch = "",
	feeling2 = "I... often have nightmares about five brothers whose faces are all blurred, and they tell me to come with them... It's really scary...",
	login = "C-Commander... I'll always be w-waiting for you here...",
	detail = "The... old injury to my foot? Well... my foot's still a bit stiff, but I won't ever let myself drag everyone else down...!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102071] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Oops, I got completely distracted by the scenery... Commander, a commission just got completed!",
