	touch = "Gee, thanks! You made my bubble pop!",
	voice_key_2 = -1,
	mission_complete = "Today's missions were a breeze! Total walk in the park!",
	battle = "Dang, guess I've got no choice! I'll show you the might of us Southerners!",
