	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome back. I've put on the heater for you. Oh, me? I'd like to stay here and enjoy the snow a little longer.",
	unlock = "The Sakura Empire's clothes are just so refined. Ahaha... Aren't you cold standing out there, Commander? Sit down with me and have a drink.",
	touch2 = "",
	mission = "",
	vote = "",
