	mission_complete = "",
	battle = "",
	id = 102132,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "You should drink a little something to warm yourself up before getting to work.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102133] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Helena messaged me, saying the party's starting soon. Check your mail, then let's hurry on back to the venue.",
	expedition = "",
	win_mvp = "",
	home = "Do you have everything, Commander? We're not driving back if you forgot to bring something.",
	unlock = "Oh my, what a good little commander you've been, waiting here all this time for me. Hop in~ Did you think you would be driving? Hehe, you shouldn't underestimate me~",
	touch2 = "",
	mission = "You have an urgent mission? I'll wait another five minutes for you, then.",
	vote = "",
	drop_descrip = "Oh my, what a good little commander you've been, waiting here all this time for me. Hop in~ Did you think you would be driving? Hehe, you shouldn't underestimate me~",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "As much as I like parties, I like being alone with you even more, Commander... Maybe we could sneak out and go for a drive together? But probably not~ Hehehe~",
	main = "Oh dear, was that... Jamaica? Hehehe... Fasten your seatbelt, Commander. This'll be a bit of a wild ride.|You want to use my car? You can, of course, but promise me one thing in return: take Honolulu on a nice trip.|Whew... Finally we've arrived at the party. Now, Commander, wait here for thirty minutes while I reapply my makeup. Relax, I'm just joking! Hehehe~",
	touch = "Let's see here... Ah, thanks, Commander. Hehehe, you're getting quite good at this.",
	voice_key_2 = -1,
	mission_complete = "Oh, you went and claimed those mission rewards? You could've taken your time if you wanted. Hehehe~",
	battle = "",
	id = 102133,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "The view here is lovely~ Let's pull over for a moment to take in the winds of good luck.",
	detail = "Hehehe, you thought I'd drive in these high heels? It's certainly not impossible, but I'd rather use the other pair of shoes I have inside.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102134] = {
	hp_warning = "",
	feeling3 = "",
	mail = "You've got mail. Wanna check it after we relax a little longer?",
	expedition = "You want to go greet the commission team? Oh, fine... I'll help you change clothes♥",
	win_mvp = "Now I can go back to enjoying my voyage with the Commander.",
	home = "Welcome back, Commander. Want a drink? Unfortunately, I only have one straw...",
	unlock = "Commander, I've been waiting for you. Lazing about and enjoying the sights here does sound nice, but... Heheh, it just isn't the same without you by my side♪",
	touch2 = "Geez, you're impatient, Commander... You can't bear to wait anymore, can you?♥",
	mission = "I wanted you all to myself for a little longer, but it looks like you still have missions left.",
	vote = "拉票描述",
	drop_descrip = "Commander, I've been waiting for you. Lazing about and enjoying the sights here does sound nice, but... Heheh, it just isn't the same without you by my side♪",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Your fingers heat up my skin even more than the sun itself. I wish I could stay in your arms and listen to the waves with you forever... Heehee.",
	main = "I've been waiting for you so long that I'm all hot and flushed now. Hm? A cold drink is nowhere near enough. Heheheh... You'll have to think of other methods.|...Mmh, this swimsuit's a little tight. Geez... Commander, can't you help me out a little? Yeah, that's the spot.|Wanna lie down on my floatie with me, Commander? We can probably fit together. Or do you wanna snuggle in closer?♪|Going on this cruise with you was a great idea. Watching the sea together is refreshing.|Do you think traveling with Lucky Lou herself might bring you good luck? Heheh, I know eeeven better ways for you to... get lucky♥",
	touch = "You'll put my sunscreen on for me? Okay. Then I'm all yours, Commander. Heehee.",
	voice_key_2 = -1,
	mission_complete = "Mission complete! As a reward, I'll put your sunscreen on for you. Mind if I touch you, Commander?♪",
	battle = "Shall we go on a Lucky Cruise Trip~?",
	id = 102134,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Heehee. Is that enough to satisfy you, Commander?",
	feeling2 = "",
	login = "Welcome back. Heheh, I think my sunscreen is starting to wear off. Commander, it's time for you to make up for making me wait♪",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102140] = {
	hp_warning = "Big sis told me... to never give up!",
	feeling3 = "My big sis is... strong, cool, has a golden smile, and she could probably beat anyone in a fight... I want to be like her one day.",
	mail = "I left your mail over here.",
	expedition = "A commission's done. Aren't you gonna welcome the team back?",
	win_mvp = "This is how victory feels... Not bad.",
	home = "Well done. You should get some rest.",
	unlock = "You're a commander? You don't... look reliable. But my big sis works for you... I've no choice, then. Montpelier, reporting for duty. I don't really care whether you give me orders or not.",
	touch2 = "G-gotta put up with it... This is obviously a test of the trust I have for my big sis...!",
	mission = "Commander, we've got a mission. Time's money... get going already.",
	vote = "",
	drop_descrip = "Cleveland-class light cruiser – Montpelier, hull number CL-57.",
	feeling4 = "I used to think commanding was just about giving orders from a comfy room while sounding like a bigshot... But after seeing it for myself, now I understand. You have a tough job, Commander.",
	lose = "Big sis... I'm sorry... I've stained the reputation of the Knights of the Sea...",
	feeling1 = "Guess my big sis can't tell good and bad people apart...",
	skill = "You're an eyesore. Disappear!",
	upgrade = "I'm one step closer to my big sis...!",
	propose = "Big sis told me to follow my heart. Which is why I'm here: to follow my heart. Are you following yours, Commander?",
	feeling5 = "I don't just blindly listen to everything my big sis says. I listen because she's always right... And I finally get why she chose you. It's because you're outstanding.",
	main = "How can I be more like Cleveland... \"Smile\"? ... That might not be possible...|I don't get along with anyone but my sisters. As for you, Commander... I'll try.|Commander, I'm curious: when my sister's doing secretary work, what's she like?",
	touch = "... Huh? If you've no need of me, don't call for me.",
	voice_key_2 = -1,
	mission_complete = "Rewards, eh... Guess this is part of my job. I'll go get them.",
	battle = "Knights of the Sea, onwards!",
	id = 102140,
	gift_dislike = "",
	gift_prefer = "...Thanks. I'll give you something in return later.",
	profile = "Listen, the Cleveland-class were the most powerful cruisers the Eagle Union had in the war. You should show more respect for my big sis. ... Me? I was in the battles of Midway, Augusta Bay, and a few others. I guess I did okay.",
	voice_key = 10214,
	headtouch = "",
	feeling2 = "I don't get why my big sis chose you. But I trust her intuition.",
	login = "So, you're back. I'll take my leave, then. It's too crowded in here for me.",
	detail = "Big sis! ... Oh, it's you. Need something?",
	couple_encourage = {
		{
			{
				10209
			},
			1,
			"... I won't embarrass you, big sis!",
			0
		},
		{
			{
				30212,
				30307,
				30115
			},
			1,
			"Night battles? Two can play at that game!",
			0
		},
		{
			{
				10215
			},
			1,
			"Let us become fine warriors who will not disappoint our sister!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[102141] = {
