_G.pg.base.ship_skin_words[102142] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "\"Kneel to the power of darkness!\" ...Is it cooler to recite this line from the script?",
	home = "Time to go back to the party? All right. Give me a moment to come down.",
	unlock = "As unreliable as you are, I didn't think you'd be too scared to approach a movie prop... You're just \"admiring it from a distance?\" ...Fair enough.",
	touch2 = "Are you that keen to taste the power of darkness?",
	mission = "",
	vote = "",
	drop_descrip = "As unreliable as you are, I didn't think you'd be too scared to approach a movie prop... You're just \"admiring it from a distance?\" ...Fair enough.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "I'm only wearing this dress because big sis told me to. It's the total opposite of the clothes I'm used to wearing... Hm? That's not the point of this all?|Change my pose? Okay. How's this? ...I have no clue what you think is so funny about this. Guess it doesn't matter as long as big sis is enjoying herself...|Wanna sit next to me? This thing is built to handle several people.",
	touch = "No thanks. I can get down on my own. The set isn't a hard climb or anything, I'm just not used to wearing this dress.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 102142,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "\"Welcome back, darling.\" ...This feels wrong. Doesn't fit the scene.",
	detail = "This set really is expertly made. It shocked me when I first laid eyes on it.",
	couple_encourage = {}
