_G.pg.base.ship_skin_words[102143] = {
	hp_warning = "",
	feeling3 = "",
	mail = "I left your letters... over there...",
	expedition = "Time is money... Get out there and... welcome them back...",
	win_mvp = "",
	home = "You're back. Man, my head's spinning... Why are you wearing those thick clothes? Just looking at you makes me feel hot... Come here and I'll help you change into something else.",
	unlock = "Ugh... It's so humid... And this water tastes weird... Commander? Did you just finish bathing? Alright, we could hang out if... No, you see, I've got this weird fever right now...",
	touch2 = "Mh... Aahh... Feels weird how... hot I feel... Wh-what do I do, Commander?",
	mission = "New missions? Right after getting out, too... Actually, if anything, I guess we might get it done more efficiently now...",
	vote = "",
	drop_descrip = "Ugh... It's so humid... And this water tastes weird... Commander? Did you just finish bathing? Alright, we could hang out if... No, you see, I've got this weird fever right now...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Ugh... Commander... It's so hot I can't sleep... This heat just won't let go of me... N-no, I'm not saying it's your fault necessarily... Still—think you could... help me cool down a little?",
	main = "Something wrong with my yukata, Commander? Ah, well, there weren't any Sakurans around, so I had to figure it out myself... The sash? I loosened it because it was too hot otherwise...|Hm? You're telling me that was alcohol I drank? No wonder I'm dizzy... I couldn't figure out why... Ugh. Gotta sober up somehow...|Ugh... This heat just won't go away... Commander... give me something to cool down with...",
	touch = "Ohh... Your hand's nice and cold... Hey, wait! Don't move it away...",
	voice_key_2 = -1,
	mission_complete = "Ah, rewards... I'd love to go fetch 'em for you, but, well...",
	battle = "",
	id = 102143,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Mmh... Feels surprisingly... comfortable... Zzz...",
	feeling2 = "",
	login = "Don't you feel hot with all those clothes on, Commander? Hmm... I'm the only hot one here? No way that's true...",
	detail = "I don't get it, Commander... Why am I the only one feeling weak after my sisters and I all went into the hot spring?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102150] = {
	hp_warning = "Scars are the only battle honors I need!",
	feeling3 = "I've relentlessly honed my skills in order to defeat all our enemies, but... is that really all there is to life?",
	mail = "Commander, check your mail!",
	expedition = "Let's load up some extra supplies. In a battle of attrition, we can't let supplies run out before our spirits do.",
	win_mvp = "Let's seize the day! And the next!",
	home = "Welcome back! I prepared some refreshments, but... Sorry, this isn't exactly my forte.",
	unlock = "Hello! I'm Denver, 4th Cleveland-class cruiser and Knight of the sea! Before I officially start working for you, I've got one question: what is the future you want to see?",
	touch2 = "Commander, what are you trying to feel for?",
	mission = "Rain or shine, hell or high water, I'm always ready to sortie!",
	vote = "",
	drop_descrip = "Cleveland-class light cruiser - Denver (CL-58)",
	feeling4 = "Even though I don't think I can ever truly grasp the kind of future that you are envisioning, if it is something that you can stand by firmly, it must be very dazzling and beautiful.",
	lose = "I'm still not... mature enough?",
	feeling1 = "Commander, where's your dignity!?",
	skill = "Your weak point... is here!",
	upgrade = "I'll make sure to put this power to good use!",
	propose = "Commander, your ideals and morals are loftier and purer than anyone else's... From now on, can I have the privilege of being your sword so that I may cut aside everything barring you from your future?",
	feeling5 = "Commander, you are the one who I admire and look up to the most... so if one day, you ever decide to turn your back on the person you are now, I will make sure... to drag you back!",
	main = "I want to fight alongside my sisters again, just like at Augusta Bay. |I want to be able to dominate the battlefield with swagger, just like Cleveland. |Even though many of my younger sisters were converted into light aircraft carriers, I'm not jealous of them at all. After all, it's best to be yourself.",
	touch = "How strange, Commander, you're also a fan of the \"bro fist?\" I thought we were the only ones who used that greeting.",
	voice_key_2 = -1,
	mission_complete = "We were able to complete our mission without a hitch because of everyone's superb teamwork!",
	battle = "All the stars in the sky are our enemies! Everyone, fiiiiire!",
	id = 102150,
	gift_dislike = "",
	gift_prefer = "I'll cherish it!",
	profile = "I am Denver, fourth ship of the Cleveland-class light cruisers. I fought hard alongside my sisters in the Battle of Empress Augusta Bay. Though I still lack experience, I won't let you down, Commander!",
	voice_key = 10215,
	headtouch = "",
	feeling2 = "Before I met you, Commander, I felt like I was always trapped within Cleveland's shadow.",
	login = "Welcome back, Commander! Today's a fine day to sortie!",
	detail = "Commander, what do you do for your own training? Why don't you come join us down here every now and then?",
	couple_encourage = {
		{
			{
				10209
			},
			1,
			"Cleve, you're always kickin' ass!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[102151] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome back, Commander! The tea's still warm, so go ahead and drink up!",
	unlock = "Aahhh... This is heaven! Hm? Commander, wanna join me? Oh, the bath just felt so good I couldn't help but moan! There's no funny business going on!",
	touch2 = "Wooooah! ...That was close! I almost flipped the tray over...",
	mission = "",
	vote = "",
	drop_descrip = "Aahhh... This is heaven! Hm? Commander, wanna join me? Oh, the bath just felt so good I couldn't help but moan! There's no funny business going on!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Ever hear that saying that you should share the best things with those you love most... W-well, umm, that's why I wanna share this bath with you, Commander! So, umm... wanna come in? I just... want to be a bit closer to you!",
	main = "Commander, these dango are soft yet chewy, a perfect mouthfeel! Add in this matcha... and you've got a complete hot springs experience!|Huh? I shouldn't drink while soaking in the bath? Of course I know! ...Hmm, what am I pouring right now? It's water, of course!|Wondering why I have a private indoor bath when there's also an outdoor bath I could go to? Heheh~ it's because I wanted to relax and have some time to myself... Oh, but, it's a different story if you're here, Commander! Being with you is always best, wherever that is!",
	touch = "Whoa, a surprise attack from the Commander! Well, take this – Denver Splash! H-huh? Why didn't you dodge? I-it's not like I was trying to get you wet on purpose...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 102151,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "H-hwuh?! Did you just find my weak point?!",
	feeling2 = "",
	login = "Fwaaah... Soaking in the hot springs is sooo relaxing~ Oh, Commander, work's been doing a number on you, right? Come right in, then!",
	detail = "Cleve always told me that laziness is an enemy that we must all defeat... but right now, I wanna be buddy-buddy with it... for just a bit longer... Haah... feels so good...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102160] = {
	hp_warning = "We can't afford to be careless!",
	feeling3 = "Who can blame you for being so captivated by me? Very well, I'll allow you to gawk a bit longer.",
	mail = "Please go get the mail. I expect some good news.",
	expedition = "The commission fleet has returned. Don't forget to check the performance records later.",
	win_mvp = "Hmph! Did you witness that? That's the glory that only I can bring to bear~",
	home = "Hehe, not bad. But don't get too cocky. There are still many trials ahead of us.",
	unlock = "Hmm, so you're the commander here? Don't worry, I'll carry out my duties as an escort ship. But first, you'll have to meet my standards!",
	touch2 = "If you don't unhand me this instant, I'll make you regret it~",
	mission = "If there are any missions left, take care of them right away. Don't procrastinate... Hey, I'm talking to you, Commander!",
	vote = "",
	drop_descrip = "Omaha-class light cruiser – Memphis, Hull Number CL-13.",
	feeling4 = "Sidling up to me this closely... Are you trying to smell my hair? Hehe, how is it? Does it remind you of the sea breeze?",
	lose = "To think that I would lose... how unsightly!",
	feeling1 = "Hmph. If it's about me ignoring you, you brought this upon yourself!",
	skill = "Leave the escort duties to me!",
	upgrade = "I wonder if I'll be even better at my escort duties now?",
	propose = "Do you feel honored? You've managed to earn my recognition. From here on out, I'll have high expectations for you, so don't let me down~",
	feeling5 = "You feel uneasy when I'm not around? Don't worry, I'll always be here to escort you. As a matter of fact, you should make sure to always be around me.",
	main = "Capturing everyone's attention with my brilliant performance at Naval Reviews - that's the way I like to do things. |Because of my hectic schedule, I never got much time to relax back in port... But that's fine, someone like me ought to be busy, wouldn't you agree~? |You want me to bring you back a souvenir next time? Should you really be asking that while you still have work to do?",
	touch = "Hm? You'd like to see me while I'm training? Very well... you'd better burn this into your eyes!",
	voice_key_2 = -1,
	mission_complete = "You've earned these rewards. Take a look when you have time.",
	battle = "Let's go! I want to see everyone at their best!",
	id = 102160,
	gift_dislike = "",
	gift_prefer = "This looks pretty nice. You've got a good eye for picking the right present, Commander.",
	profile = "I am the Omaha-class light cruiser, Memphis. I've hosted some very famous people, as well as served as flagship of the fleet in the Royal front. Make sure you carefully observe my every move!",
	voice_key = 10216,
	headtouch = "",
	feeling2 = "Next, I'll handle the paperwork and review the training plans. Commander, make sure to check my work properly. Don't slow me down, got it?",
	login = "Commander, you sure took your time getting here. Come on, let's set sail. Can you keep up with me?",
	detail = "If you intend to keep me by your side, you'd better carefully observe my every move!",
	couple_encourage = {
		{
			{
				10201,
				10202,
				10211
			},
			1,
			"At long last, we're finally able to fight together. Follow my lead!",
			0
		}
	}
}


