_G.pg.base.ship_skin_words[102190] = {
	hp_warning = "Wh-what should I do, what should I do?!",
	feeling3 = "Commander, this hairstyle is really popular right now. Um, I still think I prefer this other one though better though... Which do you prefer?",
	mail = "Huh... there's new mail? Commander, would you mind getting it yourself? I'm... having a bit of a bad hair day...",
	expedition = "Commander, big sis told me before that nobody likes tardy people.",
	win_mvp = "Heehee, I am the cutest after all~",
	home = "Commander, do you have time to help comb my hair?",
	unlock = "How should I do my hair today~? Huh? Wh-who are you? Why are you in my room? Huh? This isn't my room...? Eh? Ehhhh...?!",
	touch2 = "Commander, all the girls will hate you if you do stuff like this!",
	mission = "Commander, what do you think about the idea of wearing this hairstyle out to a mission?",
	vote = "",
	drop_descrip = "Brooklyn-class light cruiser – Helena (CL-50)",
	feeling4 = "Before, it was always big sis who helped me style my hair and put on makeup. But now, you're here to help me too! Ehehe, thank you, Commander~♪",
	lose = "*sniffle* Waaah... Commander, they're bullying me...",
	feeling1 = "Commander, it's no fun being with you... I-I'm leaving!",
	skill = "Cuteness... is justice!",
	upgrade = "Commander, I'll help rub your back~!",
	propose = "Big sis always told me that an \"Oath\" was the proof of a deep bond... In other words, Commander and I are going to always get along and be together forever, right? Ehehe, I'm so glad~!",
	feeling5 = "I wonder why... my heart always flutters when you help me do my hair... It's totally different from when big sis does it... Hopefully, I'm not sick or something...",
	main = "Big sis is just like a model, always changing into all kinds of clothes... B-but, if everyone thinks her clothes are cute, it's probably not too bad... |Huh? Who's that blonde-haired boy always surrounded by everyone? Um, I... I'm not particularly interested or anything... |Commander, do I look cute today?",
	touch = "Commander, um... look, a bunny~",
	voice_key_2 = -1,
	mission_complete = "The mission rewards are here? Good job, Commander!",
	battle = "You won't get away!",
	id = 102190,
	gift_dislike = "",
	gift_prefer = "Whoa, thanks, Commander!",
	profile = "I'm the Brooklyn-class light cruiser, Helena. I'm good at anti-air, and I like dressing up. Even though I seem to have come to a weird place, my big sis, St. Louis, taught me that a proper lady must remain calm at all times. You don't seem to be a shady person, so I guess I'll be your care.",
	voice_key = 10219,
	headtouch = "",
	feeling2 = "Jeez, Commander, how many times have I told you not to just barge into a girl's room?! ... Huh?",
	login = "C-Commander... I haven't decided on how to do my hair yet, so please don't come barging in...",
	detail = "My dream is to one day be as pretty as my sis, St. Louis!",
	couple_encourage = {
		{
			{
				10220
			},
			1,
			"H-hello! I'm H-Huh... Lena!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[102200] = {
	hp_warning = "Don't stop now!",
	feeling3 = "I know how busy you are, Commander, and you still make time to come along with us... All right, from this day forward, I'm making the Commander an honorary member of our Explorers' Team!",
	mail = "New mail's here. Hey, you're as popular as me, Commander!",
	expedition = "Race you to the pier, Commander! Winner gets a prize!",
	win_mvp = "Hahaa! I train every day!",
	home = "Need a little pick-me-up, Commander? I got all kinds of snacks on me!",
	unlock = "Hello, my name is Cleveland! My dream is to one day join the Solomon Knights! I'm working hard towards that goal every day!",
	touch2 = "Huh? You wanna rub my belly?",
	mission = "Commander, go bang out that mission!",
	vote = "",
	drop_descrip = "Cleveland-class light cruiser – Cleveland (CL-55)",
	feeling4 = "C-Commander, lemme ask you something. Helena said if I eat too much chocolate, I'll get fat and you won't wanna be with me anymore ... Is... is that true?",
	lose = "Commander, this is looking kinda bad...?",
	feeling1 = "Everybody's waiting for me! See ya, Commander!",
	skill = "Can't stop me!",
	upgrade = "Hehe, that feels good!",
	propose = "This means we're best friends forever? I'll take good care of it! Hehee, if you ever get into trouble, Commander, just let me know. I'll take good care of you!",
	feeling5 = "Heh... I was right to ask you, Commander! You always help me out. That's why I love you! From now on, I'm gonna come to you anytime I don't understand something. Sound good?",
	main = "I've got lots of little sisters, and I love each and every one of 'em! Lemme introduce you someday!|Hey, Commander, is there a blue-haired girl in the fleet, about yea big, always staring at herself in the mirror? You mind if I go play with her?|Being this small is kind of inconvenient sometimes. ... Like when? Like when I'm trying to help somebody with something...?",
	touch = "It's important to keep your energy up, Commander! Here, have a chocolate bar!",
	voice_key_2 = -1,
	mission_complete = "Hey, the rewards are here! I got lots of tasty snacks to trade. Whaddya say, Commander?",
	battle = "I'll take you all on! I ain't scared!",
	id = 102200,
	gift_dislike = "",
	gift_prefer = "Oh, that looks tasty!",
	profile = "I'm the big sister of the Cleveland-class... but I guess that's obvious from my name alone. I may be a light cruiser, but I can match a heavy cruiser no problem! I am gonna dominate the seas, after all!",
	voice_key = 10220,
	headtouch = "",
	feeling2 = "Hey, Commander, me and some of the girls are forming a Port Explorers' Team! You wanna come with us?",
	login = "Morning, Commander! How about a chocolate bar?",
	detail = "I eat so much every day, but I'm not growing at all... Why...?",
	couple_encourage = {
		{
			{
				10219
			},
			1,
			"I'm Cleveland! Let's play!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[102210] = {
	hp_warning = "Hey, guys, why so serious??",
	feeling3 = "What should I do if there's stuff that I can't stop worrying about though...? Ah! Got it! That's what Commander is there for!",
	mail = "Commander, you always get so much mail... Next time, I'll write you a letter too!",
	expedition = "...?! Commander, my Sandy Senses are tingling! There's someone waiting at the port!",
	win_mvp = "Did you see that? Just now?! I'm freakin' awesome!",
	home = "Commander, were you trying to play hide-and-seek with me?",
	unlock = "San Diego, making her shining debut! She shoots, she scores~ Yaay! Hehe, only a genius like me could come up with a one-of-a-kind intro like that!",
	touch2 = "Commander, you jerk!",
	mission = "I'm gonna finish up all these missions in one fell swoop!",
	vote = "",
	drop_descrip = "Atlanta-class light cruiser – San Diego (CL-53)",
	feeling4 = "No matter what kind of stuff I ask you, you always have an answer... Commander, are you actually pretty smart?!",
	lose = "Huhhh? Isn't that the way back home?",
	feeling1 = "Don't feel bad, Commander, it's not your fault that you're dumber than San Diego.",
	skill = "Got it! It's about time we get serious~!",
	upgrade = "Eehhh? Is this stuff really going to be useful?",
	propose = "What's this shiny, loopy thing? I'm supposed to put it on my finger? Ooh, it's so pretty! Hehe, I guess I'll keep it on then!",
	feeling5 = "As long as you're here, Commander, I'll know where to turn to whenever I have any problems! Hehe, I love how you know everything, Commander!",
	main = "My sisters always told me to ask if there's anything I don't understand. But, what if I still don't get it? |Hrmmm... Is there some way to get everyone to know about how awesome I am? |Ehhh? Commander, doesn't it get boring sitting there all day?",
	touch = "Awright! It's my turn to be it! One, two, skip a few... Ninety-nine, a hundred! Here I come, Commander!",
	voice_key_2 = -1,
	mission_complete = "Sooooo many rewards! Well? I'm pretty helpful, aren't I?",
	battle = "We're headed for the ocean! Chaaaaarge!!",
	id = 102210,
	gift_dislike = "",
	gift_prefer = "For me? You're the best, Commander!",
	profile = "I'm the third ship of the Atlanta-class light cruisers, San Diego! I'm aiming to become the fleet's number one Super☆Star!",
	voice_key = 10221,
	headtouch = "",
	feeling2 = "The key to happiness is to not worry about the stuff you don't get. Isn't that right, Commander?",
	login = "Yo, Commander! There's a lot of paper lying around here, so let's fold some paper airplanes and see whose fly the farthest!",
	detail = "The skies don't just belong to the planes, but to clouds and stars as well!",
	couple_encourage = {
		{
			{
				10206
			},
			1,
			"Hey, Atl-auntie, look over here! Here!",
			0
		},
		{
			{
				10208
			},
			1,
			"Together, we're ☆invincible☆!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[102220] = {
	hp_warning = "I-it's just a scratch! I can keep going...!",
	feeling3 = "Um, I know I can be a little hard on you, Commander. But you get what I mean, don't you? ... Commander?",
	mail = "I got your mail for you. Don't forget to check it.",
	expedition = "The resources from the commission have been delivered. Commander, why don't you... Umm, I'll go check on them.",
	win_mvp = "Victory is just a result of the effort we put into the fight. It's nothing to be especially proud of.",
	home = "Welcome back, Commander! ... D-did it go okay?",
	unlock = "I am San Juan, Atlanta-class anti-aircraft cruiser number four. I've served as a support unit for the Eagle Union's carrier fleets. You seem like a person up to your ears in work, Commander... so I now offer to support you!",
	touch2 = "W-w-w-watch your hands!!",
	mission = "How do you still have unfinished missions? Well, since you're hopeless without me, I suppose I can help you out...",
	vote = "",
	drop_descrip = "Atlanta-class light cruiser – San Juan, Hull Number CL-54.",
	feeling4 = "Commander, I always thought you wouldn't like me... and I'm glad that isn't true! B-but, how do we take our relationship to the next level? Wh-what are we supposed to do? I... I don't know about these things...",
	lose = "Agh...! Go! I'll cover your retreat!",
	feeling1 = "I thought this might happen, but... I won't give up!",
	skill = "You've entered a no-fly zone!",
	upgrade = "Now I can escort those carriers even better!",
	propose = "L-look, Commander... I'm only doing this because you're easier to deal with than my sisters. I only have enough patience to take care of one more person, so thank your lucky stars that it's you! I wouldn't do this for anyone else, got it?!",
	feeling5 = "Um, I was thinking, if you have time, could we go out on a da... date? I know it's my fault for being so hard on you all the time, so I'm trying to make it up to you... Whatever I need to do to take us to the next level, I'll do it... Okay!?",
	main = "Commander... are you daydreaming again?|Supporting a carrier group is just watching the skies all day. I wish supporting you was as easy...|My sisters haven't been causing you any trouble, have they? Oh, thank goodness...",
	touch = "I know you're tired, Commander, but you don't have to whine about it. ... Okay, once you finish your work, how about I give you a massage?",
	voice_key_2 = -1,
	mission_complete = "Mission complete! Feels pretty nice to be done, huh?",
	battle = "I'll keep the skies clear for you! Everyone, forward!",
	id = 102220,
	gift_dislike = "",
	gift_prefer = "Giving me a present out of nowhere... I-I hope you're not thinking anything weird!",
	profile = "I am San Juan, Atlanta-class anti-aircraft cruiser number four. I escorted many carrier groups: Enterprise, Saratoga, several of the Essex-class. I fought alongside them all. Let's just say I have a lot of experience in aircraft carrier support combat!",
	voice_key = 10222,
	headtouch = "",
	feeling2 = "The fleet is gonna lose faith in you if you keep spacing out like that. Commander, get your head in the game!",
	login = "Clock's ticking! We gotta get to work— Oh, come on! Here, let me straighten your collar. You're a mess!",
	detail = "I set the trap just like the book said, but why haven't I caught anything yet? That's strange...",
	couple_encourage = {
		{
			{
				10206
			},
			1,
			"You don't always have to put so much emphasis on the \"sister\" thing!",
			0
		},
		{
			{
				10208
			},
			1,
			"San Diego, quit screwing around already!",
			0
		},
		{
			{
				10207
			},
			1,
			"Juneau, you don't have to push yourself if it gets too scary out there...",
			0
		}
	}
}


_G.pg.base.ship_skin_words[102221] = {
	hp_warning = "",
	feeling3 = "",
	mail = "I left your mail where I always do. Give it a read sometime later.",
	expedition = "The goods have come in from the last commission. Commander, mind if I take a peek?",
	win_mvp = "I can get away with showing off just for today... I-I am number 1!",
	home = "",
	unlock = "All right, dress looking good. Now just to check my makeup... Need to be thorough, so I don't embarrass myself in front of– What?! C-Commander?!",
	touch2 = "Aah! Wh-what was that?!",
	mission = "",
	vote = "",
	drop_descrip = "All right, dress looking good. Now just to check my makeup... Need to be thorough, so I don't embarrass myself in front of– What?! C-Commander?!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "S-so, what do you think of my dress? It's definitely different from the rest of my wardrobe, a-and I just hope you don't think it's a letdown... Y-you don't? Th-that's great then! Really great!",
	main = "Commander? If you wanna slack off, now's the time to do it! ...Oh god, I can't believe I just said that!|Whew... Remember, Commander: overworking is bad for you. Though having that said, we're both guilty of that...|nil",
	touch = "I'm beat. Saying hi to everyone isn't as easy as I expected... Oh right, makeup... Do I look okay, Commander?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "I'll send 'em packing, you know it!",
	id = 102221,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Hmm... Hope my lipstick looks fine... Commander? You're here already? O-okay, I'm coming!",
	detail = "That's right! My sisters can take care of themselves for once! My only focus today will be enjoying myself at the party! ...Oh, who am I kidding, they can't go without supervision...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102230] = {
	hp_warning = "They have superior firepower! This may be bad...!",
	feeling3 = "You think I'm overly stoic...? True, but I must be in order to repel the darkness that envelops the sea.",
	mail = "Mail for you. My intuition tells me it's good news. If it's bad news, I will help you digest it.",
	expedition = "Every little bit counts in the end. The worth of this commission will become clear one day.",
	win_mvp = "The next battleground awaits. I will stay on my guard.",
	home = "It is good to see you unscathed. I suggest taking a break.",
	unlock = "Starting today, Cleveland-class light cruiser Birmingham is on active duty. I will not rest until the future of the sea is secure. Commander, grant me your guidance and support.",
	touch2 = "Is this amusing to you?",
	mission = "New mission from HQ. Let's complete it right at once, Commander.",
	vote = "",
	drop_descrip = "Cleveland-class light cruiser – Birmingham, Hull Number CL-62.",
	feeling4 = "Commander, it feels as though you have the peculiar power of calming people. Just like a peaceful sea would...",
	lose = "What could I have done differently...",
	feeling1 = "Commander, you should reflect on your actions thoroughly.",
	skill = "Full speed ahead!",
	upgrade = "This enhancement was necessary for me to keep advancing.",
	propose = "This must be an oath... Have we already spent this much time together, Commander...? No, I'm not displeased at all. It's just... in this case, it's... *Ahem*! Now, then... Commander, will you watch the sunrise over the horizon of the sea together with me?",
	feeling5 = "A smile? Like this? That is an unusual order to issue. That is not to say I dislike it... *Giggle*",
	main = "Princeton... please be okay. If I had fought harder back then, things wouldn't have...|Sometimes people ridicule me for being unlucky, but having survived that hellish battle, I feel quite lucky.|I feel at ease when I'm with Cleve and my sisters. I believe this is what's known as a \"bond.\"",
	touch = "What is it, Commander? Was that your sortie order?",
	voice_key_2 = -1,
	mission_complete = "Mission rewards have arrived. Perhaps there is ice cream in... Oh, um, never mind that.",
	battle = "Time is money, so let's strike quickly! I will lead the way!",
	id = 102230,
	gift_dislike = "",
	gift_prefer = "Commander, did you do research on what I like?",
	profile = "I am Birmingham, the eighth Cleveland-class light cruiser. Born during the war, I fought to its end alongside my many sisters and earned 9 battle stars. As a Knight of the Sea, my duty continues, and I will now fight for the sea's future.",
	voice_key = 10223,
	headtouch = "",
	feeling2 = "Being a light cruiser, I can't markedly affect the war... However, I firmly believe that the power to protect the sea rests within me.",
	login = "Sortie preparations complete. Your orders, Commander?",
	detail = "Someday I hope to see the sea return to its peaceful former state...",
	couple_encourage = {
		{
			{
				10209
			},
			1,
			"Sis! I will cover your flanks!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[102231] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "",
	unlock = "Good morning, Commander. Unfortunately, this bicycle only seats one person, but I could dismount and lead it along as we walk together.",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "Good morning, Commander. Unfortunately, this bicycle only seats one person, but I could dismount and lead it along as we walk together.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "It seems the academy has no bicycling club... Perhaps I should petition to create one... Hmm...|A new dessert shop opened, and their specialty is ice cream...? ... C-Commander, do you mind if I leave for a moment?|U-47, how about we go on a bicycling trip the next time you're off duty?",
	touch = "Bicycling is an excellent way to train the body. Prepare your bicycle and we can go for a ride, Commander.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 102231,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Is it time to sortie? Please wait. I must park my ride somewhere first.",
	detail = "A bicycle must be maintained regularly, so I asked U-47 for advice and help. One day I need to offer her a favor in return.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102232] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Apparently tying your hair up into buns like this is the norm in the Dragon Empery... Huh? It's not?",
	unlock = "Happy Lunar New Year, Commander. I'm trying out Dragon Empery fashion for a change, though this dress will some getting used to. Hey, uh, do you want to join me under the umbrella? For cover against the snowfall, I mean.",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "Happy Lunar New Year, Commander. I'm trying out Dragon Empery fashion for a change, though this dress will some getting used to. Hey, uh, do you want to join me under the umbrella? For cover against the snowfall, I mean.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Princeton, I'm pretty sure that aerial maneuver you learned from Saratoga is only good for pranking people...|Ice cream doesn't melt so easily when the temperature drops. Is it weird to talk about ice cream in the middle of winter? ...Oh. Now I know...|The family all gathering to make dumplings while they chit-chat... I like the sound of this Dragon Empery tradition. It warms the heart.",
	touch = "You want to... hold hands? My hands are a bit chilly, but if you don't mind that, then sure.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 102232,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Welcome back, Commander. There's snow on my umbrella? Oh, darn it. I got so absorbed in the wintry landscape that I forgot to shake the snow off.",
	detail = "When snow falls over the farmlands, it kills off crop-eating insects and keeps the soil at a stable temperature. Then when the snow melts, it waters the earth... Now I can see why they call it \"fruitful snow.\"",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102233] = {
	hp_warning = "",
	feeling3 = "",
	mail = "A letter? We'll check it later. Let's hope it's good news.",
	expedition = "That's the commission team! Commander, change course!",
	win_mvp = "Pfah! That felt awesome! I... Err, Commander, do me a favor and pretend you didn't see that.",
	home = "I saw you coming into the port. Great job out there, now get some rest. Your surfing lesson can wait.",
	unlock = "The wind and the waves are great today. You wanna try windsurfing after this, Commander? It's a lot of fun and I can teach you the... Hang on, there's a good wind coming and I've got to catch it!",
	touch2 = "Do you really expect you'll maintain your balance while doing this?",
	mission = "A new mission? I think we'll– Oh crap! ...Thanks for the save, Commander.",
	vote = "",
	drop_descrip = "The wind and the waves are great today. You wanna try windsurfing after this, Commander? It's a lot of fun and I can teach you the... Hang on, there's a good wind coming and I've got to catch it!",
	feeling4 = "",
	lose = "Must've been because I lost my balance, huh... Looks like I still have a lot to learn.",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "When you want to change course, move to a different position on the surfboard and... Crap! Are you okay, Commander?|Wish Biloxi and her gals would give this a shot... Actually, no, they've got their own hobbies. The reason I chose this one is because I'm true to myself!|Watersports at the academy don't seem particularly big, but that's probably because we see enough water as shipgirls. Or, I just don't know about it...",
	touch = "That's it, keep the sail leaned. You're getting the hang of this.",
	voice_key_2 = -1,
	mission_complete = "Mission rewards have arrived? Sweet. Nothing beats ice cream on a hot summer day.",
	battle = "",
	id = 102233,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Since you love learning, let's get right into it. We'll start on the beach. Don't worry, I wouldn't just throw you into the ocean from the start.",
	detail = "The windsurfing speed record is apparently over a hundred kilometers an hour. It's wild that you can go that fast from just riding the wind... Hmm, I don't think Cleve has ever experienced that before.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102234] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome back, Commander. Relish this calm while we have it. As for those dissonant noises, don't worry. I'll deal with them.",
	unlock = "Step back, Commander. I hear something up ahead... As your adjutant maid, I will protect you against interference from uninvited guests.",
	touch2 = "Commander? This can't be a good time for a patdown.",
	mission = "",
	vote = "",
	drop_descrip = "Step back, Commander. I hear something up ahead... As your adjutant maid, I will protect you against interference from uninvited guests.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "Nice. I can better protect you now.",
	propose = "",
	feeling5 = "Commander, stay at a distance where I can protect you at a moment's notice. I can't let you out of my sight, and... I can't trust anyone to watch my back but you.",
	main = "I'm right here. If you feel ill or need something, then don't be shy and just let me know.|Something doesn't feel right... Commander, stay behind me. Rest assured, I won't let any harm come to you.|Mmh. It's true; I'm not a real battle maid, but I believe my performance in real battles is nothing short of perfect.",
	touch = "...This won't scare me. I'm aware of your presence.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 102234,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Is this... your way of encouraging your maid?",
	feeling2 = "",
	login = "Welcome back, Commander. The danger hasn't completely passed yet, but it's okay. I'm here.",
	detail = "A maid must be fluent in the language of combat – that's what Sheffield told me. Um, you look like you want to say something, Commander. Did I do something odd?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102240] = {
	hp_warning = "I will keep drumming till the end!",
	feeling3 = "Maybe saying I grow bonsai as a hobby sounds too basic... Maybe it is... Gah, I'm at my wit's end! Commander, what do I write to make a decent self-introduction?",
	mail = "New mail's come in! I've already told you: it's for you, not for me! Come on already!",
	expedition = "Commission complete! Don't forget everyone's got a schedule to follow, all right?",
	win_mvp = "Whew! So who's our next target?",
	home = "Oh, you tired? The dressing room is free right now. You could use that if it's too exhausting to walk to the office.",
	unlock = "Light cruiser Cleveland, right here! I'm new to this whole idol biz, but I'll go with the flow and give it my all! Oh, and I'm counting on your support, Commander!",
	touch2 = "Commander?! I'm trying to get by as an idol here! Th-Think of my image...",
	mission = "We've got job offers... I mean, commissions! Let's get 'em done!",
	vote = "",
	drop_descrip = "Light cruiser Cleveland, right here! I'm new to this whole idol biz, but I'll go with the flow and give it my all! Oh, and I'm counting on your support, Commander!",
	feeling4 = "Dammit, Columbia... She's an expert at this stuff so I asked her to help. I'm shocked she wrote a bio for me that's half lies... Thank goodness you fixed it, Commander, or else I would've died of shame on stage...",
	lose = "I can't show myself to my sisters like this...",
	feeling1 = "Sorry, I've got more important stuff to do. I don't have time for you.",
	skill = "Let's get hyped!",
	upgrade = "All those lessons are paying off!",
	propose = "I heard that in some places, idols aren't allowed to be in relationships. Well, I'm sure we'll be fine! Anyway, Commander... Hehe, please continue to take good care of me! ",
	feeling5 = "Whew... You've really helped me out tons, Commander... I'm not the greatest when it comes to this stuff, and I never thought I could be a star on stage like you've made me... We really were meant to be together, Commander!",
	main = "Hehe~ It's time to break it down! Can you keep up? Just kidding~ Downes is a bit of a class act, isn't she? |Well, I'm not nervous at all because I've had a few chances to sing in front of everyone. Also, it helps that I'm not the lead vocalist, hehe. |Montpelier, Denver, what the heck are you wearing? That's embarrassing...! And Birmingham, you don't have to go waving that thing around!",
	touch = "I've gotta train for the handshake meet-and-greet. Think you could \"give me a hand,\" Commander?",
	voice_key_2 = -1,
	mission_complete = "Mission complete! Phew... We oughta start looking over our job offers.",
	battle = "Lights, on! Let's get this battle started!",
	id = 102240,
	gift_dislike = "",
	gift_prefer = "Thanks! This is great!",
	profile = "I'm Cleveland, the light cruiser. My sisters and I took part in the World War and... Well, let's just say we did pretty good for ourselves. This time around I'm wearing this special uniform, and I'm gonna fight with the power of song!",
	voice_key = 10224,
	headtouch = "",
	feeling2 = "I'm Cleveland, one of the fleet's idols! Nice meeting you, Commander!",
	login = "Hey! You all having a good time? ...All right, that should do it! Oh, hey, Commander! Heheh, I was just doing some practice!",
	detail = "What's important for concerts is having confidence! If you believe you're a star, then you are! Really! Hey, that actually sounded like a pretty cool one-liner.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102250] = {
	hp_warning = "Tsk... This is nothing!",
	feeling3 = "I sometimes enjoy talking with people about what we do on our off days... What? What's so weird about me bringing up people's hobbies? When I have time off, I enjoy myself. I'm no workaholic, you hear?",
	mail = "You've got mail, Commander. Better check it ASAP. Might be good news, after all!",
	expedition = "Those commission team girls are back. Let's go check what rewards they've brought. They might have a surprise for us.",
	win_mvp = "Thanks for the backup, guys.",
	home = "Well done on that sortie. From this point on, I'm gonna assume you'll always return triumphant.",
	unlock = "I'm Biloxi. I hope we can work together and seize victory as fellow fleet members. Anyway, that's all for introductions. Nice meeting you.",
	touch2 = "One without manners is one garnering contempt. Is that really how you wanna be, Commander?",
	mission = "These missions just keep piling up. Laziness will not be tolerated, Commander.",
	vote = "",
	drop_descrip = "Cleveland-class light cruiser – Biloxi, Hull Number CL-80. ",
	feeling4 = "Guess it's just the two of us again. Heheh, let's forget about work and have a fun chat. You know, just relax. You wanna get some drinks and snacks? It's on me.",
	lose = "Argh... This isn't over yet, you hear?!",
	feeling1 = "Look, if you wanna do nothing all day, do it without involving me.",
	skill = "No aircraft shall evade my sights! ",
	upgrade = "With great power comes great responsibility. That couldn't be more true.",
	propose = "I used to think prestige meant dashing gallantly onto the battlefield... But now I see how being by your side is just as... No, it's *more* prestigious than that idea.",
	feeling5 = "Zooming around from sea to sea can even get me feeling tired sometimes. But lately I've been having this thought... This thought that here, where you are, is my home.",
	main = "\"Big sis\"? Who, me? Ahh, you mean the lead ship. I respect Cleve just as a sister ship. Hahahah!|We *are* an improved model, but we didn't end up as carriers like Bataan, and our improvements aren't extensive enough to call us part of a subclass. The differences are more obvious through our looks and personalities, though.|A friend always deserves help, even if you yourself are in a tough spot. That's what \"no man left behind\" is all about. Ain't that right?",
	touch = "Check out my gear. Nobody's got better AA than I do. You bet your butt it'll shoot down bogeys like back in the Turkey Shoot.",
	voice_key_2 = -1,
	mission_complete = "Reward recovery complete. Time to see what fruits you've earned for your labor, Commander.",
	battle = "Victory will come to us nice and easy!",
	id = 102250,
	gift_dislike = "",
	gift_prefer = "For me? Color me impressed. I didn't know you could be this tasteful.",
	profile = "I'm Eagle Union light cruiser Biloxi. I fought in heaps of battles and carried out many carrier escort missions. Sure, the Cleveland class has its hallmark anti-air fire, but everyone's gotta work together to win. So let's do just that, Commander.",
	voice_key = 10225,
	headtouch = "",
	feeling2 = "Whew... I'm still gonna be busy for a long time, but right now I need a break. You up for chatting about stuff, Commander?",
	login = "Mission status: all green. Eyes on the progress, Commander.",
	detail = "Yeah? If you need any help, just say the word. My schedule's pretty packed too, but I can always squeeze in some time to take on your orders.",
	couple_encourage = {
		{
			{
				10729,
				10722
			},
			2,
			"Here we are again, side by side. Let's do this!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[102251] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "",
	unlock = "We're celebrating an overseas holiday, hence my not-so-casual outfit today. Heheh, what do you think? Looking slick?",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "We're celebrating an overseas holiday, hence my not-so-casual outfit today. Heheh, what do you think? Looking slick?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I came up with something that could make our trip more interesting. How about we give the Manjuu a break and *you* pull the cart to our next destination? Hahahah! I'm just joking around.",
	main = "These Dragon Empery signs are really unique, in a good way. I think they're fascinating.|The seat on this Manjuu cart is pretty small. I'd offer to share if there was more room.|I was just about to go procure some souvenirs. What would you buy if you were me, Commander?",
	touch = "Getting tired? Then let's catch a breather. Oh yeah, could you pour me some wine? Let's have a toast. To a wonderful day!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 102251,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Where do you wanna go today, Commander? Don't worry, we don't have to rush it. I've got plenty of time to spare.",
	detail = "A friend told me this look would totally steal your heart. So, has it? Are you head over heels for me? Hahahah! I'm just kidding with you.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102252] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "\"Clear out the rest of these fools, will you?\" Hahah, guess there'll be no need for that.",
	home = "",
	unlock = "\"Hehe... Now that you've finally fallen into my hands, why don't we take the day to get to know each other real well, Commander?\" Oh my, was my acting a bit too realistic~?",
	touch2 = "\"Looks like someone here doesn't know proper manners.\"",
	mission = "",
	vote = "",
	drop_descrip = "\"Hehe... Now that you've finally fallen into my hands, why don't we take the day to get to know each other real well, Commander?\" Oh my, was my acting a bit too realistic~?",
	feeling4 = "",
	lose = "Argh! Interesting...!",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I came here intent on enjoying the party, but I wound up slipping into acting instead... Although, there's fun to be had in that, too. Listen, Commander, I'm sorry to ask, but I wanna know: are you... enjoying yourself?",
	main = "Let's take a ride to the party. Don't worry about the Manjuu, I've seen how well he can drive... What, that wasn't your concern?|You oughta take today off at the very least. No need to be a busy bee and work day in, day out.|Mental clarity is the key to keeping your cool on the battlefield. My sisters, they all have the fortitude it takes.",
	touch = "",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 102252,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "How's it going, Commander? It might be unprofessional of me to ask, but... Is something up?",
	detail = "My feelings for you haven't changed, but yeah, these clothes make me act really intimidating... Maybe I'm getting into my role too much.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102253] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "",
	unlock = "I heard that this place is famous for its festivals with beautiful fireworks, so I made sure to come dressed for the occasion... What do you think? ...I'm even more beautiful? Well, I couldn't let the fireworks be the only things leaving an impression upon you tonight! Ahaha, just kidding~",
	touch2 = "...You wanna make like a firework and go bang, or what?",
	mission = "",
	vote = "",
	drop_descrip = "I heard that this place is famous for its festivals with beautiful fireworks, so I made sure to come dressed for the occasion... What do you think? ...I'm even more beautiful? Well, I couldn't let the fireworks be the only things leaving an impression upo",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Even in the cold winter, the thrill of watching fireworks with your friends warms you up. Ahahahah!|Being here with my sisters, us all watching the fireworks together... It's actually pretty nice.|Seeing these stunning fireworks makes me hope next year will go smoothly. Fingers crossed, Commander!",
	touch = "Fancy my dress? You can have a closer look at it all you want later.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 102253,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "There you are, Commander! They're putting on a fireworks display tonight. Come with me and we'll check it out.",
	detail = "Beauty is fleeting. Look away for one moment, and you'll miss it forever... It's not exclusive to fireworks, either. When you see a thing of beauty, keep your eyes on it, Commander.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102254] = {
	hp_warning = "",
	feeling3 = "",
	mail = "There's a letter for you. Be sure to read it. Who knows, it could be from someone dear to you.",
	expedition = "",
	win_mvp = "",
	home = "Welcome back, Commander. While coming home is a trying experience in certain love stories, I'm guessing everything went fine for you? That's good.",
	unlock = "The cast is all here. So, what do we rehearse first? The part where we elope and live happily ever after? Hahahah!",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "The cast is all here. So, what do we rehearse first? The part where we elope and live happily ever after? Hahahah!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "\"O Commander, Commander, wherefore art thou the Commander?\" ...Surprised? See, this line actually has a tragic story to it...|\"What light through yonder window breaks? It is the east, and the Commander is the sun!\" ...I'm just reciting lines here. Don't take it at face value, all right?|Hmm. I think I can pull off either role... Commander, which do you think suits me best? I was thinking I'd let Cleve play whichever one I don't take in the end.",
	touch = "Why are you holding my hand? Are you asking me for a dance? Sure, let's do it.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 102254,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "What's the mask for? It's a prop used in musicals. Speaking of which, could you help me practice my part, Commander? All right, let's get to it... \"Let us soar above a common bound~\"",
	detail = "You can't tell whether I'm playing the male or the female lead? Well, I've not decided on that yet, so I've read both their scripts. And don't worry, I can dress the part if I go for the male role. Hahahah!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102260] = {
	hp_warning = "I could do this all day!",
	feeling3 = "There was a time when I was training really hard to become a superhero... But these huge things got in the way of my dreams... the flat girls don't know how good they have it...",
	mail = "Mail for you, Commander. Is it a fan letter?",
	expedition = "The commission came back. You want to go out and see them?",
	win_mvp = "Yeah! The good guys always win!",
	home = "Good fight out there, Commander. Here's a towel and a drink... Hm? Isn't this what a sidekick does?",
	unlock = "You're the Commander? Ahh, I've always wanted to meet you! I mean, aren't people like you basically heroes trying to save the world? Which kind of makes me your sidekick, right? Oh, I'm Reno, part of the Oakland class! It's a pleasure!",
	touch2 = "You think they're big too? They really get in the way...",
	mission = "We got a lot to do... But I'm sure you can knock it out easy peasy, Commander!",
	vote = "",
	drop_descrip = "Atlanta-class light cruiser – Reno, Hull Number CL-96.",
	feeling4 = "I may have given up my training, but I still love watching sports. Oh, but even more than sports, I love watching superhero shows...! But now that my real hero is here, Commander, maybe I'm good on that front.",
	lose = "They say it's always darkest before the dawn... Mm. We'll try harder next time.",
	feeling1 = "They say you should never meet your heroes. Now I know why... Sigh...",
	skill = "I am Reno！",
	upgrade = "Hah ha! I'm the Commander's sidekick!",
	propose = "So like, from now on I'm more than just your sidekick. I gotta learn how to be a partner to you too, for the rest of your life... I don't really know how to do that ♪ so you'll just have to speak up and tell me what to do~",
	feeling5 = "They say \"with great power comes great responsibility,\" but superheroes need some downtime too, just like warships. Sometimes I just gotta be a regular girl, and you're no different. Let's do something fun sometime. ",
	main = "You looking at my gear, Commander? If you press this here, it shoots out a light like bzzzzew! And if you press this one, it goes like kshaw ksshhew. And then this one's like...|Commander, I'm in a bind... Well, I guess it's not really that big a deal. It's just, I wasn't able to get this premium figure I've been wanting...|Woooww.... Hm? Oh, was I bothering you? I was just basking in the amazing feeling of a sidekick watching her hero work up close~",
	touch = "I'm doing good work...? Oooh! My hero complimented me! Of course my face is gonna turn bright red!",
	voice_key_2 = -1,
	mission_complete = "That's my Commander! You always get the best rewards!",
	battle = "Just leave the planes to me!",
	id = 102260,
	gift_dislike = "",
	gift_prefer = "Wait, is this the limited edition one?! Oh, I love you, Commander!",
	profile = "I'm Reno, an Atlanta-class cruiser of the later Oakland subclass. We've got souped up anti-air power compared to the regular Atlanta-class. We only saw the last bits of the war, but we still fought hard. But I feel really bad about Princeton... Nnng, it's fine! We can do it!",
	voice_key = 10226,
	headtouch = "",
	feeling2 = "Commander, you're looking at my superhero gadgets! This is my Ibranium shield, this is my Chiropterang, and this here's my Worpher Belt... Cool, huh? You name it, I've got it, Commander.",
	login = "Commander, today we do our best to save the world. like always!",
	detail = "Commander, I'm in a bit of a pickle... I can't get any of the parts for my costume at Akashi's shop... I guess I'll just have to make them myself... Hrm...",
	couple_encourage = {
		{
			{
				10106
			},
			1,
			"Let's get 'em all fired up!",
			0
		},
		{
			{
				10208
			},
			1,
			"San Diego, you've been playing with my collectibles again, haven't you?!",
			0
		},
		{
			{
				10111
			},
			1,
			"Don't give up, keep fighting for your dreams, and so will I!",
			0
		}
	}
}


