	feeling2 = "",
	login = "Commander, I got a great view of the games from here. Come watch with me~",
	detail = "Craven was supposed to be cheer squad leader on account of she's older, but she ended up asking me to do it... I can't let her down. I gotta cheer hard!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102262] = {
