	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Commander, are you in Sleep Mode? Then please, rest well! ...You don't have to worry about me. I've already rested for a bit, and I was thinking about heading out to make my rounds anyway!",
	unlock = "\"Superhero spin-off! The superhero who saved the world is enjoying a hard-earned vacation on the afternoon beach with the sidekick!\" ... Hehe, Commander, a tagline like that sounds pretty cool, doesn't it?",
	touch2 = "Woah?! I-If you touch it like that, it's going to snap!!",
	mission = "",
	vote = "",
