	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "So I was telling everyone about Reno Bunnino, and for whatever reason, North Carolina was super keen to hear it... Not like that's a bad thing. More friends is always good!|Hungry, Commander? Vestal taught me a handful of recipes. I could cook something up for you.|Y'know, I think this Reno Bunnino's thing really gonna take off. I'm counting on you to facilitate that, Commander.",
	touch = "This gauntlet I'm always wearing? Oh, uh, I've not made my Reno Bunnino tool belt just yet, so I'm making do with this for now.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 102263,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "What can I get you, Commander?",
	detail = "Reno, tired of seeing her commander fighting all alone, assumed an alter ego and joined the commander in the battle against the forces of evil! Pretty cool origin story, wouldn't you say?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102264] = {
