_G.pg.base.ship_skin_words[102270] = {
	hp_warning = "Guess I've gotta crank up the serial factor...!",
	feeling3 = "I'm not really shy about my past as an ordinary girl. What's then is then, what's now is now, y'know? I think my new look better expresses who I am~ So anyway, as I was saying...",
	mail = "Guess this is new mail or something... Right, I'll just pretend I never saw it.",
	expedition = "Commander, I figure a commission should be done by now. Hm? Nah, I've just got a good mental clock~",
	win_mvp = "Smile for the camera, Commander~ I need a selfie to preserve this moment~",
	home = "Commander, you feelin' hungry? I got some cake, fresh outta the oven.",
	unlock = "Sup. Name's Marblehead. Are you the Commander? Ahah☆ I dig your style. Hehehe, let's hang out sometime!",
	touch2 = "Whuah?! Commander, that's *really* creepy, okay?",
	mission = "Once this mission's done, could you go get the milk tea I ordered? And not too much sugar, thanks.",
	vote = "",
	drop_descrip = "Omaha-class light cruiser – Marblehead, Hull Number CL-12.",
	feeling4 = "I guess it's like, you lose sight of what's fun when you go super-serial all-work-and-no-play, you get me? I'm having tons of fun now, and wouldn't go back to my dorky self even if you told me to.",
	lose = "I have to investigate into what went wrong this battle... Oh, uh, never mind I said anything!",
	feeling1 = "You're uncool as heck, Commander. I'mma hit up Concord and hang with her instead...",
	skill = "Try *this* on for size!",
	upgrade = "Huh. You fancy a girl like me?",
	propose = "I totally knew it, we're like, made for each other~ I looked into your personal preferences ages ago, so yeah~ All right, you wanna come with me and have some fun again today?",
	feeling5 = "I dunno if you're into girls like me, but *I'm* into commanders like *you*, so~ What do you say we get closer each other? Let's get the ball rolling with a date~",
	main = "Yo, Commander, I promised Memphis I'd color her nails in 2 hours! That's gonna take about an hour to do, so if you've got work for me then you might wanna give it now.|Let's see... Hey, Commander~ See this? I don't really get what this part says, but somethin' about it looks off.|Put the seal there, check the numbers, make a report... Hm? Oh, I'm not up to anything special! You're just imagining things, probably!",
	touch = "Commander, I'm trying to take a selfie here, so could you move?",
	voice_key_2 = -1,
	mission_complete = "You, uh, one of those super-achievers, Commander? I'm... I-I'm kinda sorta into people like that.",
	battle = "Tiiiime to get serial!",
	id = 102270,
	gift_dislike = "",
	gift_prefer = "This is really cool! I love it, Commander!",
	profile = "I'm Marblehead, your average Omaha-class girl. I went like, all over the globe during the war, and stuff like that. Anyhoo, let's be buds and just chill, 'kay?",
	voice_key = 10227,
	headtouch = "",
	feeling2 = "This here picture I've got? Ah, that average-looking girl used to be me. Whatevs, let's put that aside and go have some fun~!",
	login = "Libra's horoscope for today promises... super good luck.",
	detail = "Why follow the stupidly serial boss-and-subordinate template, am I right? Hehehe, let's just hang out and be friends!",
	couple_encourage = {
		{
			{
				10201,
				10202,
				10211,
				10216,
				10218
			},
			1,
			"Omaha-class, moooovin' out!",
			0
		},
		{
			{
				20216,
				30308
			},
			1,
			"You girls wanna get together later?",
			0
		}
	}
}


