_G.pg.base.ship_skin_words[102320] = {
	hp_warning = "It hurts even worse when you trip and fall on stage...",
	feeling3 = "Am I doing a good job as an idol? If you really mean it, Commander... then I'll work even harder and harder!",
	mail = "Commander, you have new mail. When I was practicing my dancing, I almost let it get snatched up by a passing bunny...",
	expedition = "Commander, the team is back from their commission. I'm an idol, but I still can't handle crowds... L-let's go greet them together...",
	win_mvp = "Top performer... We win, Commander.",
	home = "Welcome back, Commander. I-I'm in the middle of practicing a new dance... Do you want to watch...?",
	unlock = "I'm Cyanidin light cruiser, Boise... Huff, puff... Umm, does this outfit get your attention better? Good...",
	touch2 = "Huff... C-Commander, does it have to be... now?",
	mission = "Commander, it's important to do your missions every day. They're just like rehearsing for shows.",
	vote = "",
	drop_descrip = "I'm Cyanidin light cruiser, Boise... Huff, puff... Umm, does this outfit get your attention better? Good...",
	feeling4 = "The VIP seat I got for you is right over here. There's still a little while until the show, but... It's dedicated to you, so don't miss it, okay?",
	lose = "We lost... Did we not have enough lessons...?",
	feeling1 = "Commander... If you keep this up, I won't be able to go out onstage...",
	skill = "Keep up this rhythm...!",
	upgrade = "My breathing has gotten a little more stable. I need to keep doing my best.",
	propose = "Oh, my... Giving this to me at such a dreamy moment... My heart is pounding. Huff, puff... Huff, puff... I-I'm still an inexperienced idol, but... I'll do my very best for you!",
	feeling5 = "Why am I working and training so hard? Well... I've been given a chance to shine, and I want to shine my best for you, Commander...",
	main = "Huff puff, huff puff... I switched to a mask that better fit my stage clothes... Do you think it makes me a little more friendly?|Oh, I can wear this mask all the time since I'm an idol, right? I don't know if I could handle taking it off onstage...|This dance is a little hard... B-but I'll do my best to learn it! Because you're looking forward to my performance!",
	touch = "The theme of this outfit is fairy tales... Do you like it, Commander?",
	voice_key_2 = -1,
	mission_complete = "We completed the mission. You already know that though, right?",
	battle = "Huff... I have to be more serious.",
	id = 102320,
	gift_dislike = "",
	gift_prefer = "Wow... I'll treat it like a treasure.",
	profile = "This is the first time... I've experienced what it's like to be a pop star! It's as if every moment is a dream... Haah... Haah... Which is why I have to do my best to bring you a dreamlike experience!",
	voice_key = 10232,
	headtouch = "Do you like this hair accessory...?",
	feeling2 = "Going up on stage for the first time is nerve-wracking... But we've stuck to our practice for so long now. I'm sure we can make this show a success!",
	login = "Huff... Puff... The scent of nature, with a little bit of... Just a tiiiny bit of... Oh, that's the Commander's smell. Good morning, Commander.",
	detail = "Puff... Being an idol is hard. So many lessons every day... Cyanidin is full of such great people. I'd better not hold them back...",
	couple_encourage = {
		{
			{
				80109
			},
			1,
			" Tem, wait up. I can't keep up...",
			0
		},
		{
			{
				30408
			},
			1,
			" Kongou, the way you move is so elegant...",
			0
		}
	}
}


_G.pg.base.ship_skin_words[102330] = {
	hp_warning = "Dis-tress... Sad-ness... Des-pair...",
	feeling3 = "I did? I smiled? People typically smile to express positive feelings like happiness or pleasure, which means... I see now. That warm and fuzzy feeling I get when I'm around you is happiness.",
	mail = "A seaplane just arrived with a letter addressed to you, Commander.",
	expedition = "The commission team is back. You should raise your happiness index by 2.3% before you go greet them.",
	win_mvp = "We wooon. Hooraaay.",
	home = "Judging by the fact your happiness index stands at 74.6% right now, I can infer that your sortie was a succe– You're happy to see me, that's why? I see. Then I should increase my own happiness index by 64.3% as well.",
	unlock = "Hello, Commander. I'm Fargo. According to my emotion factor analysis, raising my happiness index by 45.36% would be ideal for our first encounter... Let me start over. Hiii, Commander! I'm Fargo, here to discuss moving cargo with you. Nice to meet you!",
	touch2 = "\"Eek. You creep.\" That's the emotion I'm meant to express, right?",
	mission = "A leader must be able to efficiently complete their missions, Commander.",
	vote = "",
	drop_descrip = "Fargo-class light cruiser – Fargo, Hull Number CL-106.",
	feeling4 = "My heart's beats per minute far exceed the baseline and my ratio of positive emotions has risen remarkably... Upon comparison, this data points to the emotion that is commonly described as... \"love\"?",
	lose = "We looost. Boooo.",
	feeling1 = "After much data gathering and analysis, I've reached a conclusion – you are not exactly the ideal choice for a business partner.",
	skill = "Supeeer power!",
	upgrade = "The emotion index has been successfully updated. I can now analyze emotions more accurately.",
	propose = "Analyzing present emotion state... Although, I don't need any data to sense what's in your heart. We're both feeling the exact same thing right now, aren't we?",
	feeling5 = "While this isn't an unusual emotion forecast, I'm still surprised I fell into that pattern... You've really enlightened me in many ways, Commander.",
	main = "You want me to guess what you're feeling right now without any analysis? Okay... You're feeling gloomy. What? You're actually feeling happy? Why's that?|Let me know if you ever need anything delivered. I can do it within a day. Oh, and if you can, ask the recipient to tell me how they felt when they got the package so I can record it for future reference. Don't worry, I only want it for data-gathering purposes.|I'm doing market research on finance and travel, among other things... Are you SURE you don't want to partner with us, Commander?|Your fatigue index has reached 63.34%. Put your work on hold for the time being.",
	touch = "Did that regulate your emotions?",
	voice_key_2 = -1,
	mission_complete = "Mis-sion com-plete! Re-mem-ber to claim your re-wards!",
	battle = "Emotion index recording has been initiated.",
	id = 102330,
	gift_dislike = "",
	gift_prefer = "Thanks, Commander.",
	profile = "I'm Fargo, the lead ship of my class of light cruisers. The great war was over by the time I was born, so I didn't earn much glory. I don't care about wars anyway, I'm more into business, and I run my own shipping company. Would you consider becoming a partner?",
	voice_key = 10233,
	headtouch = "Headpats are typically an expression of affection or adoration. I'll interpret it as such.",
	feeling2 = "Lacking emotional intelligence impairs one's judgment in business decisions. For that reason, I could use your help.",
	login = "Commander, your emotion forecast for today is happy, depressed, stressed... Hmm. You have all these feelings going on inside, but you don't let it show... I'm confused.",
	detail = "My customer profile graphs describe a phenomenon known as impulse buying under abnormal emotional states. I don't quite understand it. Would you explain it to me, Commander?",
	couple_encourage = {
		{
			{
				10209
			},
			1,
			" You should raise your calmness index by 1.11%.",
			0
		},
		{
			{
				80503
			},
			1,
			" Try to keep your titillation in check so it won't affect the battle.",
			0
		}
	}
}


