}


_G.pg.base.ship_skin_words[102340] = {
	hp_warning = "Oof, that hurt! But it's not enough to bring me down!",
	feeling3 = "What was in that package Fargo gave you just now, huh? A bouquet of flowers, maybe? ...Chocolate? For me?! Wooow, thank you, thank you!",
	mail = "You have new mail, so don't forget to read it! By the way, do people send you any secret confessions? No? ...You sure about that? Come on, tell me!",
	expedition = "The commission team is back! I'll go help them do inventory... Hm? You're coming with? Ooh, I see~ You don't wanna leave my side, right? Nyahaha!",
	win_mvp = "Nyahaha! I told you I could take care of everything!",
	home = "Welcome back! Did anything happen during your mission? No?! That can't be right. I noticed how Helena won't even look you in the eye!",
	unlock = "Commander, I'm Santa Fe, here to represent the Eagle Union... Ooh! That's a whole lot of documents you got there! You're as busy as everyone says, huh? Heheh, just leave all this to me! I'll sort 'em out... Huh? You say I'm actually just making a mess?",
	touch2 = "I-If you want to do that, it's fine with me... Huh?! What? I-it was an accident?!",
	mission = "Commander! I just heard this crazy rumor – Oh... Work comes first? Th-then let's get it done quick!",
	vote = "",
	drop_descrip = "Cleveland-class light cruiser – Santa Fe, Hull Number CL-60.",
	feeling4 = "Sorry, Commander... I messed up again, and I need your help! ...You need me to stop clinging to you first? Aww, okay... I guess...",
	lose = "I can't win this! I need to seek refuge in the Commander's arms...",
	feeling1 = "Uuugh... Commander, you're so boring.",
	skill = "See if you can withstand my full power! Nyahaha!",
	upgrade = "Nyahaha! I'm even stronger now! Leave all those battles to me, 'kay?",
	propose = "What's my answer? \"I do,\" of course! Wait, did you just hear that shutter noise?! Oh, no... Are we about to be all over the headlines tomorrow?",
	feeling5 = "FleetChat's going crazy right now. What does everyone talk about? Ooh... Now that's an exciting title! \"Who's meeting the Commander in secret every night? It must be Santa Fe!\" Whaaat?! ME?!",
	main = "You say everyone's acting weird lately? Putting on bunny girl outfits to come see you, helping you with your documents while in swimsuits...? Hmm. That is weird, but it got your attention, right? So my advice is working! Ack... There I go running my mouth again...|Why do I like gossip so much? Because it helps me get to know people's interesting sides faster! Heheh, and I've learned some cute fun facts about you, too!|What were you just talking about with Enty? Just work stuff, huh? Pssh, yeah right. What work talk would make her blush that hard? Nyahaha! Have I just witnessed something incredible?",
	touch = "Commander, this help wanted notice for Akashi's maid café says she's looking for \"a hard worker who understands the Commander's needs.\" That's LITERALLY me, isn't it?! So why did she reject me?!",
	voice_key_2 = -1,
	mission_complete = "Whaaat?! You finished yours already? I better not fall behind... NOOO, I spilled my drink!",
	battle = "I'll take care of this♪",
	id = 102340,
	gift_dislike = "",
	gift_prefer = "Wow! Thanks, Commander! This is exactly what I wanted!",
	profile = "I'm Santa Fe, a Cleveland-class light cruiser from the Eagle Union! If you need someone to work, do battle, take care of you, or exchange some gossip, I'm your girl! Ooh, yeah, I know that look on your face... You wanna know Union gossip! Oh... You just wanted to discuss work? Lame.",
	voice_key = 10234,
	headtouch = "What's up? Got some tasty gossip for me?",
	feeling2 = "Aw, man! I promised Alfredo I'd help her get some dirt on you, but I broke her camera! Aaaargh, now I'll never get to write my awesome gossip column!",
	login = "Morning, Commander! I took care of your docs for you! Tadaaa! Great job, huh? ...Hm? What are they sorted by? By the color of their cover pages, duh! Nyahaha!",
	detail = "Psst, hey, have you heard? Yesterday, New Jersey got so drunk off her juice that she got naked in the plaza! ...What, that's not right? New Jersey did drink some juice, but Pittsburgh was the one who got drunk, and Mogador was the one stripping...? Huh?! How do you know so much?!",
	couple_encourage = {
		{
			{
				60108
			},
			1,
			" Got any juicy gossip... Uh, I mean, news for me?",
			0
		},
		{
			{
				10209
			},
			1,
			" Hey Sis, let me handle this one!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[102341] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "If you need anything, let me get it for you. I'm healthy, so... Oh, you need a nurse to change out your fluids? Leave it to me – aaaack! I almost fell... Geez, who just tripped me over? Oh... It was a bandage.",
	unlock = "Huh? You're already in bed, Commander? Come on, it's time for late-night gossip! Nyahaha! Let me slip into bed with you so we can chat the night away!",
	touch2 = "Whoa?! If someone saw that, we'd be all over the news tomorrow!",
	mission = "",
	vote = "",
	drop_descrip = "Huh? You're already in bed, Commander? Come on, it's time for late-night gossip! Nyahaha! Let me slip into bed with you so we can chat the night away!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Hehe, I'm not bored at all! Even if we can't gossip, we can still chat. And I'm happy to be so close to you, too! You heard me – no matter what, I'm happy as long as I'm by your side! Nyahaha!",
	main = "You thirsty? I'll get you some water... Aaagh, I spilled it! I'll wipe it up first... Uhh, i-it spilled in a pretty private place, huh... Y-you do it!|I brought the softest pillow they have! Let's talk until morning, whether it's gossip or stuff about you!|Commander, you and Franklin were alone for a looong time. She wasn't just treating you, was she? Ooh, you're averting your eyes! Even more suspicious. Nyahaha!",
	touch = "I'll tuck you in! O-oh... I didn't just touch your wound, did I?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 102341,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "You want me to sleep? At least tell me some juicy bedtime stories!",
	feeling2 = "",
	login = "Why did I come here? To see you, duh! You must be so sad and lonely here in this hospital bed, right? Nyahaha!",
	detail = "Are you SURE the nurses haven't left you any exciting notes? Aww... Okay, then I will! I'll write a hundred to start! \"I love you, Commander! Call me anytime!\" Bam.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102350] = {
	hp_warning = "It'll take more than that to stop me!",
	feeling3 = "Hey! Heehee – bought this adorbs hair ornament, and I think it'd look sweet on you! You should put it on, then we'll take a selfie together!",
	mail = "Commander, there might just be a surprise from me in this new letter. Heehee♪",
	expedition = "Commission's done and the celebration's ready to start! Let's go check it out, Commander!",
	win_mvp = "Big wins like this call for a celebration!",
	home = "Truth be told, Commander, I'm working on a li'l celebration! We're just waiting for you! C'mon, let's go!",
	unlock = "Ta-dah! Here's a special debut surprise from your girl Pasadena! Did you like it? Hahah! I'll take that dub. My surprise plan was a success!",
	touch2 = "Oohh, so THIS is the kind of surprises you like. I see♪",
	mission = "Got any missions we could make a surprise out of? If so, lemme at it!",
	vote = "",
	drop_descrip = "Cleveland-class light cruiser – Pasadena, Hull Number CL-65.",
	feeling4 = "Commander, open your mouth! Say \"Ahh\"! ...How's that? Pretty banging cake, right? Heh – I knew you'd like it! Feels like I'm starting to figure out your vibe!",
	lose = "What?! This was no surprise, it was a shock!",
	feeling1 = "Aww, don't like the celebrations I worked on? How about some bombastic surprises, then?",
	skill = "Here's a bombastic celebration!",
	upgrade = "Oooh! Let's dance!",
	propose = "I-is this surprise from you?! Heehee – I dig it♪ Okay! Today is gonna be our commemorative day of love! Every anniversary from now on, we'll throw a huge celebration and party our butts off!",
	feeling5 = "Check this out, Commander! It's a selfie stick! See, I'm making a video centered around us spending the day together. I wanna record some happy moments between us to look back on!",
	main = "The much-anticipated ice cream day is here! What kinda celebration should we throw? ...Hm? Never heard of an ice cream festival? Hahah! Have this frozen goodness and let's have a look!|Hey, Commander, we've been working for a long while now, so how about some house music to relax to? Let's follow the beat and go check out the surprise I've got for you!|Commander, didya see the stamp pad down there? You can get a mystery gift from collecting all of 'em! Let's give it a shot!",
	touch = "Ahh... Feels much better with my hair down! Let's continue, Commander♪",
	voice_key_2 = -1,
	mission_complete = "Heheh! Claiming those mission rewards feels about as good as a celebration, doesn't it?",
	battle = "Yooo! Giiirls! Time to celebrate!",
	id = 102350,
	gift_dislike = "",
	gift_prefer = "Woooah! Now this is a wild surprise!",
	profile = "Self-intro? I'm Pasadena, Eagle Union light cruiser. Heh – there're loads of other things I could tell you. Whaddya wanna know? My interests? Got plenty of those. My favorite, though, that's gotta be throwing celebrations with people!",
	voice_key = 10235,
	headtouch = "Ahh, I see, so this is how you show you're feeling glad? Don't mind if I do the same... Pat-pat! Here's a headpat!",
	feeling2 = "Everybody's smiling and celebrating! C'mon, Commander, doesn't this nice mood make you wanna smile?",
	login = "Can you guess what surprise I have in store for you today, Commander? Ta-dah! I gave your office a celebratory makeover!",
	detail = "Commander, I just got a frickin' amazing idea! How about we throw a musical festival at the port? People would absolutely love it!",
	couple_encourage = {
		{
			{
				10234
			},
			1,
			"Get the word out that I'm working on a music festival!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[102351] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome back, Commander! Wanna continue where we left off? If you're too tired, I've got a surprise in store for you instead♪",
	unlock = "Surprise! How do you like my special showdown outfit? I got it specifically for the game we're gonna play! Ahaha♪ Let the Meow-Meow Celebration Service begin!",
	touch2 = "Eek! C-Commander... Of all the cards you could draw! Mmh... Still not done? You're taking... an awful lot of time for a surprise...♡",
	mission = "",
	vote = "",
	drop_descrip = "Surprise! How do you like my special showdown outfit? I got it specifically for the game we're gonna play! Ahaha♪ Let the Meow-Meow Celebration Service begin!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "What's this? A secret stage?! No, it's an Easter egg just for you and me! When we're together, even uneventful days become filled with surprises! *smooch*... Heehee – that was a surprise meant to make your heart race♡",
	main = "I endured! Take this! Thirtyfold shield parry! Victory's mine. Hm? My reaction time got quicker all of a sudden? Heheh – that's 'cause this match blindfold makes me a master at this game!|Hmm... I drew the \"put a mask on and meow like a cat\" card... Well, alright! Meow! Meow, meow♥ G-god, I'm glad you can't see my face right now... *blushes*|Maaan, you win. My card iiis... \"Paw Print: Move your paw print to a location of the winner's choice.\" Wonder what that means... Eek! C-Commander?!",
	touch = "Whoa! Hey! No off-the-board tricks! Ahaha – two can play at that game!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 102351,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Hm? Surprise touchy-touchy! Meow, meow! Meow, meow!",
	feeling2 = "",
	login = "Hoho! You're really into this, Commander. Can't help your urge to want to school me, huh? Heheh. The sensory equipment's up and ready. Let's do this!",
	detail = "Already getting excited about the surprise after our showdown? Ahaha! I got loads of surprise cards for our punishment game! All with veeery different punishments.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[102360] = {
	hp_warning = "Th-there's been an accident onstage!",
	feeling3 = "Commandeeer, I washed my own clothes for the first time today! Hm? Is it just me, or did they get smaller...? Hmm. They're definitely tight... Huh? I'm supposed to look at the tag before I wash them? \"Dry clean\"... What's that supposed to mean?",
	mail = "You have mail, Commander! Could it be fanmail? Hurry up and see!",
	expedition = "The commission team just came home! I gave them my blessing before their departure, so I hope they brought back a big haul~",
	win_mvp = "I did it! Commander, did you see me protecting everyone? Hehe, this is exactly why I decided to be an idol!",
	home = "Welcome back! Guam was just teaching me a new cheer dance. Check this out! ...Phew. Did that lift your spirits at all?",
	unlock = "Vicksburg makes a dazzling entrance – Whoops! I slipped into stage mode again... Umm, I heard first impressions are everything, so I wanted you to see me at my most spectacular, Commander! From now on, I'll light up the port with smiles and good fortune! Please show your support for Vicksburg!",
	touch2 = "I don't really understand what you're doing, but... it does feel really good...",
	mission = "It's time for missions! I'll cheer you on, so tackle that work with lots of energy!",
	vote = "",
	drop_descrip = "Cleveland-class light cruiser – Vicksburg",
	feeling4 = "Commander! Did you notice how my dance was different today? Hehe, I learned some awesome moves just to show you! I practiced a lot in front of the mirror! From now on, I'll try all kinds of new things just for you♪",
	lose = "Don't give up! Keep trying – fortune is on our side!",
	feeling1 = "Commander, y-you're kind of being a little... *sniffle*...",
	skill = "Shining, Lucky Beam of... LOOOVE!",
	upgrade = "Now I can shine even brighter!",
	propose = "Huh? A-a vow... Does that mean we'll be together forever? Goodness... I'd be happy to! Because you're the most important person ever to me! I love, love, love you!",
	feeling5 = "Every time I see you smile, I feel my energy rising! No matter how grueling the training, I'll be just fine knowing you're cheering me on. It really goes both ways for us, huh?",
	main = "San Diego told me that eating is the best part of the day, so I've decided to treat everyone to an all-day feast! That'll really make them happy!|My lessons have been pretty intense lately... Huh?! You want to massage my sore spots? Th-thank you!|I hope I can be your lucky star, Commander... No, that's not enough. I need to be an idol strong enough to protect you!",
	touch = "Hmm? You want a blessing of good fortune? Leave it to me! Heart... Sparkle... Lucky poweeer!",
	voice_key_2 = -1,
	mission_complete = "Earnestly devoting yourself to every task is the mark of a true idol! Commander... I think you have what it takes!",
	battle = "Go, go, Commander! Beat those baddies!",
	id = 102360,
	gift_dislike = "",
	gift_prefer = "Idols aren't really supposed to accept gifts, but... I know you put your heart into this! I'll happily accept it, Commander.",
	profile = "I'm Vicksburg, a Cleveland-class light cruiser under the Eagle Union! I-I only just made my debut, but I promise to light up your life with my brightest smiles and sincerest blessings!",
	voice_key = 10236,
	headtouch = "Look... I braided it in the shape of a four-leaf clover! Keep patting, and you might just get good luck♪",
	feeling2 = "This crème brûlée is adorable! I wanna eat it so bad... Oh no, Vicksburg, stop! You're an idol, so you have to mind your calories... *sniffle*... Commander, you need to take this away from me before something awful happens!",
	login = "Phew... Commander? Oh, sorry – I was just practicing my steps in your office... U-umm, could you give me some pointers when you have a while?",
	detail = "Wanna do something to pass the time? Hmm... How about playing chess? I happen to have a board with me! If you come over sometime, we could even go horse-riding or play golf~ I'm really good at them!",
	couple_encourage = {
		{
			{
				11802
			},
			1,
			" Guam! Let's do our best on this performance! ",
			0
		},
		{
			{
				10208
			},
			1,
			" I'll do my best to keep up with you, San Diego!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[102361] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "We did it! You're in first place, Commander! We're champions! Say... May I hold the trophy later?",
	home = "The race is about to start. I practiced my cheer dance a lot for you! I'm sure I can fill you with more energy than ever right now!",
	unlock = "Commandeeer! I finally found you! I heard the opening ceremony needed a dazzling racer idol, so I came to help out... I'm not sure what I need to do, but I'll do my best to cheer you on!",
	touch2 = "If you wanna do something fun... let's do it before the race♪",
	mission = "",
	vote = "",
	drop_descrip = "Commandeeer! I finally found you! I heard the opening ceremony needed a dazzling racer idol, so I came to help out... I'm not sure what I need to do, but I'll do my best to cheer you on!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Just between you and me... I've already prepared your first-place reward! This hug has all of my joy, love, and good fortune... Ah! I accidentally gave it to you early!",
	main = "Um, is taking pictures all I need to do? Should I do a little dance first, maybe...? I'm an idol, after all! I should be cheering you on!|What pose should we go for next? I'm taking requests, so leave it all to me! Heheh, my idol creds aren't just for show!|Why am I not wearing my stage clothes? U-umm, it said you needed to be in uniform to enter the venue... I searched the changing room from top to bottom, and this was all that was left.",
	touch = "Do you get nervous before races, too? Don't worry. I'll give you a big idol hug... Say goodbye to those nerves!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 102361,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Heheh, you've been blessed with my super-invincible lucky power! This race is in the bag♪",
	feeling2 = "",
	login = "Oh, Commander, welcome back! It's almost time for the race! I'll cheer you on with all my energy!",
	detail = "",
	couple_encourage = {}
}


