_G.pg.base.ship_skin_words[103100] = {
	hp_warning = "I... I can still keep fighting! Probably...",
	feeling3 = "Commander... you're sure nice to everyone...",
	mail = "Looks like there's new mail... but it's too far away... Don't wanna go...",
	expedition = "The commission fleet's back... Looks like spacing out time is over...",
	win_mvp = "V is for victory!",
	home = "Welcome back, Commander. There are some interesting-looking clouds in the sky today...",
	unlock = "I'm Vincennes of the New Orleans-class... Commander, don't you want to take me home?",
	touch2 = "Woah?! Commander, what are you doing?!",
	mission = "Surely... it wouldn't hurt to skip a few of these missions...",
	vote = "",
	drop_descrip = "New Orleans-class heavy cruiser – Vincennes, hull number CA-44.",
	feeling4 = "You don't act the same towards everyone? Then how come whenever you look at me, your face is always so gentle... Why is that?",
	lose = "Commander, we should run...",
	feeling1 = "Commander?! How dangerous...",
	skill = "It's time to get serioush...!",
	upgrade = "What's the point... of getting stronger anyway?",
	propose = "Even though being with my sisters is already a lot of fun, as long as you're with me, I feel like we'll have even more fun! So, let's continue getting along!",
	feeling5 = "Now I like to observe your expressions instead of watching the clouds... Commander, your face when you're having fun, when you're worried, when you're in a pinch, or when you're surprised... they're all so interesting...",
	main = "Because my sisters like to take care of everything for me, my primary responsibility is spacing out. |My sisters gave me way too many snacks... Commander, wanna help me out? |So bored... Commander, let's do something together... like spacing out...",
	touch = "Commander... can you guess what I'm thinking right now?",
	voice_key_2 = -1,
	mission_complete = "Commander, why don't you let me take a nap as a reward instead...?",
	battle = "Wanna go swim together?",
	id = 103100,
	gift_dislike = "",
	gift_prefer = "Thanks.",
	profile = "I'm Vincennes, New Orleans-class heavy cruiser number 7. I've been to lots of places and given it my all in many battles... The last one I remember was at Savo Island...",
	voice_key = 10310,
	headtouch = "",
	feeling2 = "Quincy is always busy helping other people, so she never has time to space out with me...",
	login = "Commander's sleeping face... cute...",
	detail = "Wanna space out and stare at the clouds?",
	couple_encourage = {}
}


