_G.pg.base.ship_skin_words[103110] = {
	hp_warning = "How about unveiling what secret plan you have in store for me?",
	feeling3 = "You're curious about my whip? Well, I bought it on a whim long ago, but it's been surprisingly useful. Particularly when I'm pointing at a map.",
	mail = "I'm entrusting the mail to you.",
	expedition = "Hm? Looks like a commission's been completed... Hmph, a few commissions are easy pickings for our mighty fleet.",
	win_mvp = "Hah! These weaklings are no match for me!",
	home = "Good work, Commander. You should rest as well.",
	unlock = "You're the commander? Very well. Starting today you will be my adviser. You will devote your time to helping me conquer the seas!",
	touch2 = "Are you trying to get a taste of my whip?",
	mission = "A new mission? Read it out loud for me.",
	vote = "",
	drop_descrip = "Wichita-class heavy cruiser – Wichita, Hull Number CA-45! \n<color=#ffde38>Unlock build after receiving</color>",
	feeling4 = "Though it may be a little late, I really wanted to thank you for putting up with my selfishness and staying with me... Will you continue doing so? Hah! That's just that what I wanted to hear, Commander!",
	lose = "Now this is interesting. Hmph, fall back!",
	feeling1 = "Hmph, it seems I made the wrong decision... by relying on someone as useless as you...",
	skill = "This shot will be it for you!",
	upgrade = "With this kind of power...!",
	propose = "I see you as my best friend... No, I'm not planning on treating you as my best friend... Hold on, let me think for a moment. No, that doesn't mean I'm turning you down... Just give me some time to ready my heart for this...",
	feeling5 = "Listen, Commander. I was just joking about it at first, but if we join forces, we might just be able to conquer the entire ocean! Since what's mine is yours, there won't be any need to split everything equally, am I right?",
	main = "Torpedoes? Far too weak!|Look! Our conquest extends to the ends of this blue sea!|There exists no problem that a shot from my huge cannons cannot resolve!",
	touch = "What is it, want to have a go with me?",
	voice_key_2 = -1,
	mission_complete = "You're giving ME a reward?!",
	battle = "All units, fire at will!",
	id = 103110,
	gift_dislike = "",
	gift_prefer = "This is really nice. Present accepted.",
	profile = "I am the one and only fearless general of the seas, Lady Wichita! Even carriers would be crushed beneath my feet, if I wanted to end them myself. That's why, Commander, I'll be expecting much of you.",
	voice_key = 10311,
	headtouch = "",
	feeling2 = "My dream is to conquer the world! What happens after I've done that? Hmph, who cares about that!",
	login = "You've returned. You really kept me waiting. Get ready to depart.",
	detail = "Relish in the power of a true heavy cruiser!",
	couple_encourage = {
		{
			{
				20301,
				30702
			},
			1,
			"Ahahahahahaha! Show me a grand plan that'll leave me satisfied!",
			0
		},
		{
			{
				3
			},
			2,
			"Heavy cruisers, attack!",
			1
		},
		{
			{
				1
			},
			5,
			"Kaede's Legion, follow me!",
			4
		}
	}
}


_G.pg.base.ship_skin_words[103111] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Hah! Pathetic. Can't they send someone who'll put up a fight?",
	home = "That level of workout is nothing you can't handle. Right, Commander?",
	unlock = "It's about time you showed up, Commander. Now, show me some spirit! As my lieutenant, don't do anything slovenly that would incur the mockery of others! Very well, let's move out!",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "It's about time you showed up, Commander. Now, show me some spirit! As my lieutenant, don't do anything slovenly that would incur the mockery of others! Very well, let's move out!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "What are you looking at? You want a drink, huh? Why didn't you just say so right away?|Even the world's best warrior would succumb to exhaustion if they never stopped fighting. Everyone needs time off for recreation, you know? So enjoy yourself tonight.|Not going to lie, St. Louis's car looked really slick. I'm considering asking for the keys and taking it for a spin later.",
	touch = "Hey! You nearly put your hand on my shoulder there... Try to avoid doing that in public at the very least.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "You want to play, do you? Come here!",
	id = 103111,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "What took you so long, Commander?",
	detail = "Mannerisms, etiquette, dress codes... Hmph. This is all more convoluted than naval battles, that's for sure. Still, I agreed to participate, so I mustn't act like a total simpleton.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[103112] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "My fangs and ears look very realistic? Of course they do. I had them specially procured just for this holiday.",
	unlock = "Tonight I am not a renowned naval general, I am a feared commander of witches! And you... Yes, you're not my lieutenant, you are my arcane familiar!",
	touch2 = "Desperate to once more taste the sting of my whip, are we?",
	mission = "",
	vote = "",
	drop_descrip = "Tonight I am not a renowned naval general, I am a feared commander of witches! And you... Yes, you're not my lieutenant, you are my arcane familiar!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Ghosts? Goblins? Hah! On this night, they too are under my control! Hahahaha!|Trick-or-treaters? It's your job to deal with those. Wouldn't want to risk petrifying any children with my terrific costume.|Raising the brim of my witch hat to reveal my razor-sharp fangs – now that's what I'm talking about!",
	touch = "Come, familiar. Get up on the pumpkin and take in the Halloween spirit.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 103112,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "The curtain rises on All Hallows' Eve! Commander, we're leaving!",
	detail = "Darkness may unnerve people, but you need some well-placed lighting to truly frighten them. So, tell me, Commander: have any ideas for setting up a Halloween scene?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[103120] = {
	hp_warning = "I can't go down as long as they can't hit me...!",
	feeling3 = "What do I do off-duty? Hmm. I hang out with my sisters, I go fishing, I take naps... Things like that.",
	mail = "You've got new mail. I've added \"check the mailbox\" to today's task list.",
	expedition = "The commission girls are back. Have you decided on what to give them yet?",
	win_mvp = "War is about always thinking two or three steps ahead of the enemy.",
	home = "I held the fort while you were away on your sortie. Here's a list of things you should review.",
	unlock = "Heavy cruiser New Orleans, reporting in. Hehe, you'll be sure to receive a medal for finding me. Anyway... Do you have any urgent tasks for me?",
	touch2 = "Hehehe. You wouldn't stand a chance against me in a real fight.",
	mission = "You've still not finished these missions, Commander. Do you need my assistance?",
	vote = "",
	drop_descrip = "Heavy cruiser New Orleans, reporting in. Hehe, you'll be sure to receive a medal for finding me. Anyway... Do you have any urgent tasks for me?",
	feeling4 = "I like it when you ask me for help. It's... soothing, in a way. Hehehe, maybe that's a strange thing to say.",
	lose = "Neither will alone... nor strength alone... is enough.",
	feeling1 = "You're like a little kid, Commander.",
	skill = "Lock on... Fire!",
	upgrade = "You think I can handle this power? Thank you. I'll trust you.",
	propose = "Is this your proposal? Or are you asking for more help than ever? Hehe, whichever it is, I'll oblige. As long as you want to be with me, I'll do everything you ask of me, Commander.",
	feeling5 = "If you ever need help, or want someone to talk to, just say my name. I'll always be there to support you, Commander.",
	main = "Being focused is a good thing, but overworking yourself will only burn you out in the end.|I suppose rigging rocket boosters are still a way's off... Oh, just talking to myself.|My sisters are all very eccentric. Hehe, rest assured, they're good people all the same.",
	touch = "Whether you want close contact, or hand-to-hand combat, I'll oblige.",
	voice_key_2 = -1,
	mission_complete = "I compiled a list of all the mission rewards. Have a look.",
	battle = "I'll bring victory to you, Commander!",
	id = 103120,
	gift_dislike = "",
	gift_prefer = "You went this far for me? Thank you.",
	profile = "I'm New Orleans, nameship of my class. I used to fight for the Eagle Union. I had a frighteningly close call once in a battle, but fortunately, I lived to see another day. But the past is the past – treat me no different from how you would anyone else in the fleet.",
	voice_key = 10312,
	headtouch = "Even my sisters haven't touched me like that. Hehehe~",
	feeling2 = "Weapons are extensions of our own bodies. They need regular care, too.",
	login = "Welcome back, Commander. I'm counting on you today.",
	detail = "A rigging inspection? Hehe, go ahead, Commander.",
	couple_encourage = {
		{
			{
				10308
			},
			1,
			"We've both got to set examples for our little sisters.",
			0
		},
		{
			{
				10309
			},
			1,
			" I'm here. No need to push yourself too far.",
			0
		},
		{
			{
				10310
			},
			1,
			"Stay sharp, Vincennes!",
			0
		},
		{
			{
				10313
			},
			1,
			"Be careful so the hunter doesn't become the hunted.",
			0
		},
		{
			{
				10314
			},
			1,
			"Don't take it too easy now, okay?",
			0
		}
	}
}


