_G.pg.base.ship_skin_words[103130] = {
	hp_warning = "Hey, it seems like these guys are giving us a bit of trouble.",
	feeling3 = "There’s actually a few places in port that I am interested in investigating. Let’s go and explore them now! ...Work? We can still make it on time even if we wait a bit longer!",
	mail = "Urgent mission? No, turns out it was only an ordinary mail.",
	expedition = "It seems our friends have returned from the hunt.",
	win_mvp = "Sorry, from the very beginning, I never intended for any of you to escape.",
	home = "You all returned safely? That’s good to hear.",
	unlock = "Hey ya! New Orleans class Heavy Cruiser, reporting in! I excel at hunting. If you have any prey that you’d like to hunt, then leave it to me!",
	touch2 = "Ya! ...you, do you want to become my prey?",
	mission = "New mission, new prey, oh boy~",
	vote = "",
	drop_descrip = "New Orleans class Heavy Cruiser— Minneapolis, hull number CA-36.",
	feeling4 = "When did you get this injury? Could it be that time when you were with me... hey, don’t move, let me help you by licking it.",
	lose = "Hey, the caught prey actually...",
	feeling1 = "It’s kinda boring talking to you...",
	skill = "Got it!",
	upgrade = "I feel my body is heating up!",
	propose = "It turns out that I was your prey, Commander? Even though I still am reluctant to believe it... but, I’ll hold onto Commander’s words! All-in-all, please take care of me in the future, Commander!",
	feeling5 = "After all, you are the Commander of the entire fleet. So you can’t always accompany everyday. But without you, I seem to be less motivated...",
	main = "My war paint? Oh, I’m not the only one who does this… is this what you mean? |Torpedo? I’m not afraid of that, I was just unlucky that one time… |Hey, don’t just sit there, come with me and let’s take a look around!",
	touch = "Are you ready for the hunt?",
	voice_key_2 = -1,
	mission_complete = "Is this all the rewards... not as good as I expected.",
	battle = "Who will be my next prey?",
	id = 103130,
	gift_dislike = "",
	gift_prefer = "Oooh, I've been craving this forever!",
	profile = "From the Coral Sea to Guadalcanal, I have left my footprints everywhere in the Pacific theater. Although I had to pause my mission due to little annoyances... but considering the results, my battle record can be considered as outstanding!",
	voice_key = 10313,
	headtouch = "",
	feeling2 = "Compared to staying at port, it’s way more fun to go on a hunt! How about we plan one right away?",
	login = "You have very good spirit, are you ready for today’s hunt?",
	detail = "Do you want to hear my hunting stories? Alright! But which one do I start with...",
	couple_encourage = {
		{
			{
				10702
			},
			1,
			"I’ll protect you this time!",
			0
		},
		{
			{
				10308,
				10309,
				10310
			},
			1,
			"To go into battle with my sisters, it’s not a bad feeling at all...",
