_G.pg.base.ship_skin_words[103162] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "You don't need to know why I look this way. Because if you did, you'd vanish from this world. I'm just kidding around. Hahaha!",
