_G.pg.base.ship_skin_words[103245] = {
	hp_warning = "",
	feeling3 = "",
	mail = "This letter's for you? Oh, you shoulda said so! I was 'bout to throw it away!",
	expedition = "The commission team is... How did you know that? You hiding your phone in that pillow or something?",
	win_mvp = "That was refreshing for the both of us! Heheh!",
	home = "Aahh, that was divine! I've drained the bath and gotten the sauna fired up. You ready for the next round of soothing, Commander?",
	unlock = "Hold still, Commander! You gotta relax in this position or else I can't do my thing. Take it easy and let me handle them weary bones. Alright, from your hands to your arms, then to your neck and shoulders, time to press down!",
	touch2 = "C'mon, Commander, just let me do my thing♪",
	mission = "Wow, talking 'bout missions while getting a massage... Fine. If I can help, just lemme know!",
	vote = "",
	drop_descrip = "Hold still, Commander! You gotta relax in this position or else I can't do my thing. Take it easy and let me handle them weary bones. Alright, from your hands to your arms, then to your neck and shoulders, time to press down!",
	feeling4 = "",
	lose = "Oops, I guess I got too cocky...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Ahh... A little late, but I'm really sorry for barging in! I just saw you hangin' out with other girls at the amusement park, and... Nah, it didn't make me jealous. I just got anxious, wondering when it'd be my turn...",
	main = "Couldn't find me earlier today? Well, I was at the amusement park, I was thinking about how to approach you, and I had a lotta consultation work to do. Heheh, I got off to a late start, but this is where I make my comeback!|Before you hit the hay and sleep like a log, you gotta treat your body right to actually get rid of your exhaustion. That means taking a bath in a big tub and getting a hottie to massage you before anything else!|Man, you're real reckless, Commander – opening the door to the room before even checking who it is. You're bound to get pounced like that.",
	touch = "Here we GO! Hm? Did I use too much force?",
	voice_key_2 = -1,
	mission_complete = "Mission complete! Whew... Don't move, just lie on your back now!",
	battle = "",
	id = 103245,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Morning, Commander! Kinda rude of you to fall asleep in the middle of my massage... Heheheh, guessing you want something a little more \"stimulating,\" eh?",
	detail = "We finally got some time to spend together – ain't nothing wrong with doing one or two things that're off-brand for me, right? Besides, it's too late to quit now, so you might as well accept me takin' the lead here!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[103248] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome back, Commander! Gimme a big hug before I update my Juustagram~ Ahaha♪",
	unlock = "Three, two, one, go! Did you get a pic of me tossing the bouquet, Commander? Ahahah! I'm postin' this to Juustagram later, so you should do the same! It'll be like... retaking our pledge of love♪",
	touch2 = "So, do you like what you see? Oh, and whisper me your answer♪",
