_G.pg.base.ship_skin_words[103270] = {
	hp_warning = "Secure an escape route, just in case...!",
	feeling3 = "Commander, I'm here to help you with your work today. You always seem so tired, so I want to help out... Wait, I told you yesterday that I would? A-ahahaha... Goodness, is there something wrong with me?",
	mail = "You have mail. Let's open this one first... Huh? Which one was the new one, again...? Do you remember?",
	expedition = "Did someone just come home? ...Hmph, of course I know it's the commission team. Commander, please don't tease me.",
	win_mvp = "Louisville wins the title of MVP! Isn't that just lovely~",
	home = "Welcome back, Commander. I made a nutritious meal for you, so eat up... You want to eat together? Okay! In that case... Oh, my. I didn't make any for myself...",
	unlock = "Heavy cruiser Louisville has come to port. From now on, I work for the Commander... Say, where was the Commander's office, again? Not here... Over there, maybe? Umm, can I trouble you to help me find it...?",
	touch2 = "Ah...? Did you just touch me?",
	mission = "I feel like there were missions to be done... Commander, would you mind checking again?",
	vote = "",
	drop_descrip = "Northampton-class heavy cruiser – Louisville, Hull Number CA-28.",
	feeling4 = "Commander, I finished sorting your documents. ...The time? Oh... I'm sorry. I always lose track of time... I-it's not like I'm done working, so I might as well continue...?",
	lose = "It seems I've failed... Let's escape through this route, okay, Commander?",
	feeling1 = "Never hurt your friends or make them sad. If you remember only one thing, let that be it.",
	skill = "Focus on the target... and fire!",
	upgrade = "My power-up was a success. This is just amazing, isn't it~",
	propose = "What are you just staring for, Commander? Aren't we supposed t o exchange vows—Hm? You want to kiss first...? I-I understand you're not forgetting the order. You're just trying to skip a step or two... W-we can skip ahead even more, if you want...?",
	feeling5 = "Zzzz... Oh, no. I fell asleep in the Commander's office... H-huh? Why am I here...? I was helping you work? Did I really offer to do that...?",
	main = "I go drinking with Lucky Lou all the time~ Oh, but the next day, I never remember what happened... Even when I don't get drunk...|Of course I remember my job. Even I can remember things if I really put my mind to it! Yep!|When you get focused on work, you can tend to lose sight of what's around you and forget what needs remembering. No matter how tight your schedule is, make sure to work in moderation, okay?",
	touch = "Do you need something, Commander?",
	voice_key_2 = -1,
	mission_complete = "Mission complete. I think you should accept those rewards before you forget.",
	battle = "Lady Lou is here to fight!",
	id = 103270,
	gift_dislike = "",
	gift_prefer = "You memorized my preferences? My! I should study what you like too, Commander...",
	profile = "I'm the Northampton-class heavy cruiser, Louisville. During the war, I supported aircraft carriers, helped as a training ship, intercepted battleship fleets... Oh, hmm. My training ship era may have been earlier in my career...? Um, I'm not quite sure...",
	voice_key = 10327,
	headtouch = "Hmm...?",
	feeling2 = "Commander, it's almost break time. I brought you some snacks... Oh? You say I just brought you drinks? Now that you mention it...",
	login = "Today's schedule is... observing the port, confirming the drill plans, sitting in on a friendly meeting... Hm? Which one was the first thing in the morning, again...?",
	detail = "Do my best to remember your plans for today...? I-isn't that a little too easy...? Your next item of business today would be... U-umm...",
	couple_encourage = {
		{
			{
				10303,
				10304,
				10305
			},
			1,
			" Is it just me, or does my outfit not match...?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[103271] = {
