_G.pg.base.ship_skin_words[103280] = {
	hp_warning = "My neck's starting to ache...",
	feeling3 = "This juice is my favorite flavor... Wanna guess what it is? Oh, but I already finished it, huh? What a conundrum... Say, maybe you can still taste it on my lips? Heehee♪",
	mail = "Commander, mail for you. Ah... No, nothing. I was just wondering if I should write something on my skin for you, instead of on paper...",
	expedition = "Hm? The commission team is back? Should we cut things short for now, then? Heehee♪",
	win_mvp = "That was so easy, it was almost boring. Hey Commander, do you wanna do something more fun?",
	home = "Commandeeer! Welcome baaack! ...Hm? No, I'm not drunk. Who'd get drunk off of one glass of juice? ...My face is hot? Well, how about you check somewhere else? Like... Here? Am I hot here?",
	unlock = "We fiiinally meet, Commander. I'm Pittsburgh, a heavy cruiser... Oh, no. I forgot to bring a gift for you. Okay... Instead, ask me for anything, and I'll give it to you. And I mean anything, Commander... Heehee~",
	touch2 = "Mind if I teach you a little trick, Commander? It'll make things more pleasurable for both of us♥",
	mission = "Go do your lame missions, okay? I'll show you something fun later.",
	vote = "",
	drop_descrip = "Baltimore-class heavy cruiser – Pittsburgh, Hull Number CA-72.",
	feeling4 = "Commander, I think we've gotten past the \"seeing if we're into each other\" phase. It's time for our reckless, passionate love phase, don't you think? Heheh...",
	lose = "Has to be because of that typhoon...",
	feeling1 = "Oh. So this is how you are? Boring.",
	skill = "I'm as strong as Viper!",
	upgrade = "Does my rigging fit me a little better? Come get a closer look.",
	propose = "Aww, is this for me? You understand what this means, don't you? Heehee, this means you'll never get to escape. You'll have to keep satisfying my lust forever and ever♥",
	feeling5 = "I'm not drunk at all. It's just that strong love and desire get me a little hot... Why are YOU so hot when you haven't even had my juice? C'mon... Tell me why~♪",
	main = "Commander? What's so fun about staring so fixedly at me? If there's something you want to do with me, then just do it.|Wanna guess where your folder is? Hint: it's not in my clothes, but... Heheh♪|McKeesport... How do you know about that, Commander? Tease me, and you'll be in big trouble.|The button on my upper chest? Oh... Of course, I left it unbuttoned on purpose. Heheh...",
	touch = "Well? Is that all you want? Commander...?♡",
	voice_key_2 = -1,
	mission_complete = "I'm not really interested in mission rewards. What I AM interested in is the reward you'll give me, though♪",
	battle = "Don't interrupt my time alone with the Commander!",
	id = 103280,
	gift_dislike = "",
	gift_prefer = "You've had your eye on me all this time, huh, Commander? I like that... Heheh, I'm getting tingles again.",
	profile = "I'm Pittsburgh, a Baltimore-class heavy cruiser with the Union. As for the \"McKeesport\" thing... Well, I can tell you about it sometime if you really want. In my room, if that works for you.",
	voice_key = 10328,
	headtouch = "Hmm? Hinting at something, are we? Heehee.",
	feeling2 = "Heehee! Gee, I wish you'd be even more fun, Commander~ Just kidding♪",
	login = "Commander, mind helping me straighten out my outfit a little before we get to work?",
	detail = "Inspection, huh... You can check anywhere you like, except for my neck. If you don't know where to start... I'd be happy to guide you.",
	couple_encourage = {
		{
			{
				10316
			},
			1,
			" As cool as ever, heehee.",
			0
		},
		{
			{
				10324
			},
			1,
			" Keep yourself in tip-top shape.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[103281] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Heehee♪ I win! I'm ready for my reward, Commander.",
	home = "Commandeeer, you're finally back~ Hahaha, I'm tired of roulette. Let's do something more fun... What? Everyone can see us? Let them watch~ Heehee♪",
	unlock = "Welcome to the saloon, Commander. Be it drinking juice, or playing games of chance, I'm happy to join you. And I offer more special services, too...",
	touch2 = "Let's gamble on it. If you win, I'll let you take the next step♪",
	mission = "",
	vote = "",
	drop_descrip = "Welcome to the saloon, Commander. Be it drinking juice, or playing games of chance, I'm happy to join you. And I offer more special services, too...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Wow, the last bullet is still in there. You win, Commander... God, there's something fascinating about you. Just looking at you gets my mind racing... Time for you to take responsibility, Commander♥",
	main = "Isn't this dress just lovely? See, if I grab here and pull... Heehee, it comes right off.|Commander... Oh, should I call you \"legendary bounty hunter\"? Really? That gets you more in the mood, doesn't it?|How's about a wager? Whoever wins gets to do whatever they want to the loser. For example... Bang♥|Here's the juice you ordered. ...Oh, I spilled a little on me. Still want a taste of it...?",
	touch = "You like seeing me in this dress, don't you? Heehee♪",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 103281,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Do you like it more when my hair's a little disheveled?",
	feeling2 = "",
	login = "Would you like some juice, Commander? A smoked malt? Don't worry... There are plenty of ways to quench your thirst.",
	detail = "Sometimes, it can be a little fun to do it in a dirty little saloon, right? Heehee, or even out in the wilderness♥",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[103290] = {
	hp_warning = "Owwie... Anchorage is scared... *sniffle*",
