	mail = "Mail...? Anchorage doesn't get it... Can I fold stars with it?",
	expedition = "Everyone is back... Anchorage is excited. Let's play together...!",
	win_mvp = "Anchorage and Teacher... won? Yay... I'm so happy!",
	home = "Teacher... is back! Anchorage has been folding bunnies... I like the red and blue ones!",
	unlock = "Anchorage... is here! Com-man-der? Hmm... Anchorage will call you... Teacher!",
	touch2 = "Warm hands... Touch, touch!",
	mission = "Work... again? Good luck, Teacher! Anchorage will do my best to help...!",
	vote = "",
	drop_descrip = "Heavy cruiser – Anchorage.",
	feeling4 = "Teacher's hands are so warm and soft... They feel good! Anchorage is happy...! I like it! Teacher... Keep going! Yeah...!",
	lose = "Aah... Anchorage is scared! Teacher, help me...",
	feeling1 = "Teacher... Is something wrong? Are you sick? Anchorage will take care of you!",
	skill = "Anchorage isn't scared!",
	upgrade = "Anchorage... is amazing! I can protect Teacher... the best!",
	propose = "Anchorage... has seen this in books! Wearing it on your ring finger... is a promise! Teacher and Anchorage... together forever! Yay!",
	feeling5 = "When will there be... a shooting star? Anchorage wants to make a wish... to be together forever and ever... with Teacher!",
	main = "Teacher... Hold hands! In my sleeve!|Teacher, what's your favorite color? Anchorage likes... rainbow!|Anchorage's tongue... is blue? Because of candy? Why...? I don't get it!",
	touch = "Teacher... Anchorage wants to fly high!",
	voice_key_2 = -1,
	mission_complete = "Work... done? Teacher... Let's go outside!",
	battle = "It's time... to fight! Teacher, everyone!",
	id = 103290,
	gift_dislike = "",
	gift_prefer = "Teacher... Anchorage loves... all of your gifts!",
	profile = "Heavy... cruiser, Anchorage! With the Eagle Union! I love Teacher the most...!",
	voice_key = 10329,
	headtouch = "Teacher... Do you like this thing on my head? You can have it! Hnnh... It won't come off...!",
	feeling2 = "Teacher working... Anchorage isn't lonely, though! Teacher is here... That's all I need!",
	login = "Anchorage really, really... really wanted to see you!",
	detail = "Drawing... done! This is Teacher... and this is Anchorage! We're in the sun...!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[104010] = {
	hp_warning = "The stars are dimming...",
	feeling3 = "The stars told me your fortune. They said – your prayer will be answered positively; you can be at ease, Commander.",
	mail = "Commander, you have new mail... Fetch the latest Astronomy Monthly while I'm here? Heehee. Of course.",
	expedition = "The commission team has returned. I'd like to go to distant lands, if I get the chance... A sea far from all the lights would be the ideal stargazing spot.",
	win_mvp = "To describe this feeling, it's like a happenstance meeting with the stars. It's majestic, serene, and lifts the spirit.",
	home = "Great. You're back. It's a relief to see you again, Commander.",
	unlock = "Stars – shining in the clear night sky, their glow traveling countless lightyears. To see it with your eyes, to witness and embrace this glimmer from space, 'tis romance. Lexington-class battlecruiser Constellation greets you, Commander.",
	touch2 = "Eep! H-here I thought you only had eyes for the stars...",
	mission = "You've received a new mission. Commander, there is quite a lot of paperwork to process... Which do I start with? This one? Or this?",
	vote = "",
	drop_descrip = "Lexington-class battlecruiser – Constellation, Hull Number CC-2.",
	feeling4 = "I brought you some Astronomy Monthly mags... Was it tiring, you wonder? They weren't exactly THAT heavy... Um, the reason I brought them all is because I couldn't decide on just one. You choose whichever looks the most interesting!",
	lose = "The clouds have gathered... The stars are with us no more... Ugh...",
	feeling1 = "Oh... So you're also measuring mine and other girls' worth...",
	skill = "Gaze upon the stars and travel the cosmos!",
	upgrade = "Stars more far-flung are now in my view.",
	propose = "You're giving this... to me? It's like wearing a star on my finger... F-from now on, you'll be my star and mine alone. Heehee... Because the only one I'll be gazing at is you♥",
	feeling5 = "What's on my mind? Nothing too complicated. Just pondering which telescope to buy, comparing their designs and features... It's not about how I'm going to use it, because I'm gonna give it to y– Ahem! I-I'm only gonna use it to see what's out there in deep space! *blushes*",
	main = "Do you know about the Daily Horoscope Reading channel, Commander? Heehee, truth be told, I'm the one who runs it. Shall I tell you your fortune for today?|I watch the stars at night and sleep during the day. I'm sad that I miss meetups with my friends, but I don't know what else I could do...|I've been thinking about how much overtime you do, and it worries me. I'm going to stay here with you today.",
	touch = "Commander...? Are you going to take me somewhere?",
	voice_key_2 = -1,
	mission_complete = "Gosh, this is so hard... You may be the only one who can finish all these missions efficiently, Commander.",
	battle = "Hmm... Y-you leave me with no choice! Swarm them!",
	id = 104010,
	gift_dislike = "",
	gift_prefer = "Are you giving this to me? And you're sure I can have it? I-I like it so much that I almost feel I shouldn't...",
	profile = "I am Constellation, hull number CC-2. It was a little unfortunate that I couldn't sail forth with my sister ships. It became my routine to gaze at the stars while I awaited my own time to shine. Commander, how is the view of the night sky from this port?",
	voice_key = 10401,
	headtouch = "Does the thing on my head get in the way of stargazing, you ask? Nope. I can even make it go away. Like this.",
	feeling2 = "On a stroll, Commander? ...Me? I'm waiting for the stars... Ahem, what I meant to say is... I'm just feeling the wind in my hair.",
	login = "*yawn*... Welcome back, Commander... A little out of it, you say? Sorry, I stayed up late waiting for a meteor shower last night. I'll manage, so don't you worry.",
	detail = "A beginner-friendly stargazing spot... Maybe parks, or mountaintops? Sparse suburbs and remote beaches are good, too. If it's my personal favorite you're asking for... That's much harder to choose.",
	couple_encourage = {
		{
			{
