_G.pg.base.ship_skin_words[105010] = {
	hp_warning = "",
	feeling3 = "Commander, Oklahoma told me about a nice shop around here. Wanna have a look? ... Hey, stop standing there like a pole! Let's go",
	mail = "Yo~ Commander! A message!",
	expedition = "Commander, the commissions have returned without issue. Make sure to comlement them for their efforts!",
	win_mvp = "Ha, you think you can beat me with such weak firepower and defences?",
	home = "If you're tired, you can always rest on my shoulders. Don't be embarrassed. Come on!",
	unlock = "Are you the commander, young man? I'm Nevada. I'll be working with you from here on out.",
	touch2 = "Are you that interested in my 'priority defenses'?",
	mission = "As soldiers, completing missions is our divine duty.",
	vote = "",
	drop_descrip = "Nevada-class battleship – Nevada, Hull Number BB-36!",
	feeling4 = "If you like someone, just say it up front. What use is there to hide it? ...It's just not like you at all, Commander!",
	lose = "Tsk, wait and see how I take you on next time!",
	feeling1 = "I'm a bit disappointed in you...",
	skill = "You are still way off!",
	upgrade = "Mmm, not a bad feeling!",
	propose = "Oh you... what are you doing, getting so bold at a time like this? Have you never considered the time and place for such an important thing? Hmph. yeah yeah. I'm not saying no, so bring it.",
	feeling5 = "The idea behind priority defenses? That is to protect our most important areas... What, you want to know how important they are? W-well, if it's you...",
	main = "Gambling? I'm not usually interested, but I'll give it a shot with you if you're up for it!|Commander, go do what you want while you're still young!|Bantry Bay Squadron? I just missed my chance, you see...",
	touch = "Who knew you were a people person?",
	voice_key_2 = -1,
	mission_complete = "Mission rewards have been delivered!",
	battle = "How lively! Allow me to join in the fun!",
	id = 105010,
	gift_dislike = "",
	gift_prefer = "Nice! I love it!",
	profile = "Yo! I'm the big sister of the Nevada-class battleships, Nevada! I served in both the Atlantic and Pacific fleets. The President was once on board me, I've changed kidneys, carried two atomic bombs, and even cleared out an entire battlefield!",
	voice_key = 10501,
	headtouch = "",
	feeling2 = "I'm quite confident in my own luck. Want to gamble a bit?",
	login = "Hey, get your spirits up!",
	detail = "At times like these, I tend to like your mindfulness...",
	couple_encourage = {}
}


