_G.pg.base.ship_skin_words[105070] = {
	hp_warning = "",
	feeling3 = "Commander, you are still too weak. Come and train with me, and I will turn you into a proper Commander!",
	mail = "Commander, you've got new mail",
	expedition = "The commission team is back? Allow me to show how they should really be handled.",
	win_mvp = "This kind of battle is quite good",
	home = "When is the next sortie?",
	unlock = "You're the Commander? Hmm... Looks like you have potential. I'm motivated enough to help with your dreams. Ah, that reminds me, I am Tennessee. Got it memorized?",
	touch2 = "I'm not a 'Clear' target like in a game!",
	mission = "Hurry and take care of the missions, will you?",
	vote = "",
	drop_descrip = "Tennessee-class battleship –  Tennessee, Hull Number BB-43!",
	feeling4 = "You're looking good these days. Hmm? Ah, not to worry. I've always stuck around with you. I don't want all the training to be in vain, after all.",
	lose = "Yes. Yes! This is the kind of challenge I'm looking for!",
	feeling1 = "You really are helpless...",
	skill = "Witness true firepower!",
	upgrade = "Like a full score and then some... Not bad.",
	propose = "If I take this, it means I'm yours forever? Fine, but on one condition; I want none of that 'You'll get hurt if you're in the battlefield' crap. I need some action every now and then!",
	feeling5 = "I'm used to your pace now after all this time. I've yet to get used to staying in a room all day... If anything happens to me because of this, it's all on you. Don't tell me you're gonna dodge the issue.",
	main = "Commander! If you don't sortie, I'll bring the girls and head to new waters myself!|I totally cannot comprehend why you're so easygoing...|The secret to getting a better figure?... Cease with such jokes.",
	touch = "Mm... 'Cute' doesn't quite fit me.",
	voice_key_2 = -1,
	mission_complete = "Your rewards are here, Commander.",
	battle = "March through the gates of hell! May our image be burned into the eyes of our enemies!",
	id = 105070,
	gift_dislike = "",
	gift_prefer = "Hahahaha! This is great! Thanks!",
	profile = "I am the new type of battleship, Tennessee. In terms of combat, my waterline protection and hull armor have been upgraded, and my fire control systems have improved my fighting capabilities further. Commander, your orders?",
	voice_key = 10507,
	headtouch = "",
	feeling2 = "My motto is, 'survival of the fittest'",
	login = "Commander, it's time to roll!",
	detail = "You can look all you want. Just don't forget about your job.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[105080] = {
	hp_warning = "",
	feeling3 = "*humming* Ah, Commander~ Just who I was looking for. I was thinking about taking you some place to have fun!",
	mail = "It's new mail. Wanna open it up right away?",
	expedition = "Commander, the girls from the commissions have returned. Let me do one next time, please~",
	win_mvp = "Aaah... that was a great workout",
	home = "You looked great just now, Commander!",
	unlock = "Hello, Commander. I am California. It's not good to brag, but I'm quite strong you know. Do look forward to it~",
	touch2 = "Wait-... Commander! Where are you touching? Big sis wouldn't do this!",
	mission = "Commander, don't forget to do your missions!",
	vote = "",
	drop_descrip = "Tennessee-class battleship –  California, Hull Number BB-44!",
	feeling4 = "We've already had fun throughout the docks. How about we go some place farther? Just the two of us... Heh heh heh...",
	lose = "Oof... Big sis will lecture me for sure!",
	feeling1 = "Commander, I'll go play on my own now~",
	skill = "",
	upgrade = "Now I can reach for further waters~",
	propose = "Commander, where are we going to play today? ...WHA! ...Seriously, I don't... I'm happy and all, but please don't pull this again. You surprised me...",
	feeling5 = "Tennesee said to me, 'You must be careful who you choose as a partner.' 'Once you do, tell me', she also said. Well, if it's you, Commander, she won't say a word, I think...",
	main = "I feel different from big sister? That's not true. She might not look it but she's actually kind|Ah~ Big sis didn't say much today... Wha! N-nothing at all!|Ah, where did my undies go? Eheh",
	touch = "This is comfy. Every time big sis scolds me, she comforts me with this afterwards as well.",
	voice_key_2 = -1,
	mission_complete = "Hahaha, this is good!",
	battle = "Don't panic...Calm down... Let's go!",
	id = 105080,
	gift_dislike = "",
	gift_prefer = "Wow, I love this! Thanks!",
	profile = "Hello. I am the second of the Tennessee class battleships, California. I was once the flagship of the Pacific fleet, and was part of the Atlantic fleet as well. How about it? Bet you didn't expect that I was a popular one, did you? Hehe~",
	voice_key = 10508,
	headtouch = "",
	feeling2 = "You don't know if you can be friends with someone unless you tried to make them. Commander, wanna hang out together?",
	login = "Weather, check. Wind, check. A fine sailing day, Commander.",
	detail = "Commander, I will do my best to meet everyone's expectations",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[105090] = {
	hp_warning = "The bridge was hit? Damage control, now!",
	feeling3 = "Commander, why do you care about me so much? Many people are afraid of me and keep their distance from me. Perhaps I've been too used to this. But recently, I’ve suddenly felt... so lonely.",
	mail = "You’ve got new mail. There may be news from my sisters...",
	expedition = "A lot of oil and supplies have been shipped in. Looks like we got plenty of both for the next mission.",
	win_mvp = "Huh? Am I the MVP? Such a piece of cake for one of the BIG SEVEN.",
	home = "Making sure everyone returns home safely is also one of my duties.",
	unlock = "Are you the one calling me? Well, I've been waiting for this day for a long time. In the name of the BIG SEVEN, Eagle Union battleship Colorado, reporting in.",
	touch2 = "Shall I load the Commander into a 406mm gun and fire him?",
	mission = "Whether you need fire support or fleet battle, please give the order Commander.",
	vote = "",
	drop_descrip = "Colorado class battleship— Colorado, hull number BB-45",
	feeling4 = "The Commander is willing to talk to someone as bad-tempered as me. Such a weirdo... I don't hate talking to the Commander, though.",
	lose = "This is not the end of the line...",
	feeling1 = "Commander, please… don’t come any closer.",
	skill = "It's time to show you the true power of the BIG SEVEN!",
	upgrade = "Emm, as one of the BIG SEVEN, my powers are unquestionable. Although, timely enhancements are still a necessity.",
	propose = "Unknowingly I’ve slowly become more dependent on you, Commander. With the power of the BIG SEVEN, I shall protect you until my dying breath.",
	feeling5 = "The Commander's compliment after the end of each battle is something which I crave for. Commander, can you... praise me a little more?",
	main = "Commander, although aircraft carriers are really powerful, but battleships are not obsolete. They are indispensable! |Amelia... She was a great woman, though she still cannot be found. Perhaps she is flying freely in another world... |My poor sisters were hurt on that humiliating day. One day, I will have those invaders pay for what they have done!",
	touch = "Commander, please don't touch the main gun that I was just using, you will affect my shooting accuracy.",
	voice_key_2 = -1,
	mission_complete = "Commander, mission reward has been delivered.",
	battle = "I will not allow you to misbehave anymore... All guns, ready to fire a volley!",
	id = 105090,
	gift_dislike = "",
	gift_prefer = "Is this meant to improve my temper? Well, I may as well accept it as a one-off...",
	profile = "I'm the lead ship of the Colorado class. In order to gain an advantage in the decisive battle, I'm the first ship to be equipped with 406mm guns. BIG SEVEN... is the most honored title for us battleships.",
	voice_key = 10509,
	headtouch = "",
	feeling2 = "I’m proud of my BIG SEVEN title. Unfortunately the battleship era is closing, and a new wave of ships are arriving...",
	login = "Commander, you’ve rested long enough. When shall we weigh anchor?",
	detail = "Commander... Can you take your eyes off me?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[105092] = {
	hp_warning = "",
	feeling3 = "",
	mail = "So there's new mail. Maryland's as fast to act as always.",
	expedition = "",
	win_mvp = "The fact that I can still be helpful to people makes me happy.",
	home = "I want to perform for people, not a crowd of trees in the barren wilderness. I'll keep fighting in order to keep it that way... together with my sisters.",
	unlock = "Hmm-hum-hum... So very cute~♪ ...Commander? Um, about that... Please do me a favor and forget you heard anything.",
	touch2 = "Don't I feel... cold to the touch?",
	mission = "Commander, there are still some missions left... Make sure you check on them later.",
	vote = "",
	drop_descrip = "Hmm-hum-hum... So very cute~♪ ...Commander? Um, about that... Please do me a favor and forget you heard anything.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Hm-hmm~♪ It's in pretty good condition today, just as you said. Um... would you mind if I played you one more song?",
	main = "The Big Five... Yet another name that we were proud to be called.|I'm not sure what I'll do if there ever comes a time when I can take off my rigging, along the title of the Big Seven... I'm sure that that girl from the Sakura Empire is thinking the same thing.|Where would I like to go? Well... if it's not too much to ask... that place where you can pet cats.",
	touch = "It's already been tuned, Commander. Leave it be. It's as delicate as my main guns are.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "I can't let you get caught up in the battle... Shoo, hurry away!",
	id = 105092,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "...Hehehe. ",
	feeling2 = "",
	login = "(If the Commander wasn't waiting for me, I'd have liked to stay like this for a bit longer...)",
	detail = "Commander, um... your gaze is making me a bit uncomfortable. My sisters might be different, but I'm not really used to having people look at me...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[105093] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission team's back. Will you be back... after you've gone to see them?",
	win_mvp = "We won't go down. No matter what.",
	home = "Welcome back, Commander. Have you seen my sisters? No, I'm not worried about them, just wondering if they'd tried to rope you into something. Heehee.",
	unlock = "You'd rather stay here and watch the sunset with me than bathe with the rest in the sea? You sure you wanna spend your beach day that way? Err, well... I'm fine with it if you are.",
	touch2 = "Doing this while they're all still there...",
	mission = "I wish I could tell you to forget your missions... Let's get them done so we can all watch the fireworks together.",
	vote = "",
	drop_descrip = "You'd rather stay here and watch the sunset with me than bathe with the rest in the sea? You sure you wanna spend your beach day that way? Err, well... I'm fine with it if you are.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "You being here for us has helped us find new goals and pleasures. Yeah, I'm not talking about big stuff like being the strongest or world peace. I mean performing with friends, watching fireworks, and enjoying this beautiful view. I value the wonderful times we spend together more than anything else.",
	main = "I'll never get tired of this amazing view. I'd have been worse off if you hadn't told me about it.|Do you not like getting tanned? Me neither, really. Don't tell anyone, though... If people knew, I'd look less reliable both as a Big Seven and as an older sister.|\"I'm conserving my stamina for the concert later\"... Sounds like a believable excuse, but I don't think you'd buy it. In reality, I'm locking down a seat early for the fireworks show. Heheh.",
	touch = "The sea breeze is starting to get colder. Should we put on some clothes?",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Now we can enjoy the closing party with peace of mind.",
	battle = "",
	id = 105093,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "La-la-laa♪ ...Oh, it's a new song me and my sisters made. Thought I'd brush up on it a bit.",
	detail = "Where do you wanna go next time? Ah, there are still some places you suggested to me that I haven't been to yet. Let's do those first. After that... could I suggest a few places?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[105099] = {
	hp_warning = "Dammit! It was a trap!",
	feeling3 = "",
	mail = "Commander, you have a new letter. The stamp and the postmark are a mess...",
	expedition = "",
	win_mvp = "I've waited long for a victory like this. Our glory shall never fade.",
	home = "You've made a small but resolute step toward our goal. Welcome back, Commander.",
	unlock = "You called, and I returned stronger, fiercer, and more complete. Now I await your orders. On my name as a Big Seven, I swear to decimate anyone who stands in your way.",
	touch2 = "Maybe I should fire you off into space. Heh, I'm just kidding. Keep your warm hands on me a while longer.",
	mission = "",
	vote = "拉票描述",
	drop_descrip = "You called, and I returned stronger, fiercer, and more complete. Now I await your orders. On my name as a Big Seven, I swear to decimate anyone who stands in your way.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "Aim all guns! Unleash full firepower!",
	upgrade = "",
	propose = "",
	feeling5 = "You being here helps me stay true to myself in battle. I've always, um, felt drawn to your vision for the future... D-do you think you could tell me more about it today?",
	main = "At this point, \"Big Seven\" is just a prestigious title, but that doesn't break my spirit. My era still isn't over yet.|Do you think the sky being blue means anything? It means a lot to me. I mean, it's the same color as the sea... The world beyond is so interesting.|A hot air balloon can cross a mountain, and an airplane can take you beyond the horizon. The view of the future is vast – how does it look to you, Commander?",
	touch = "\"Big-barreled guns gun down bugging brigade bigguns begging for beatings\"... Your tongue twister makes less sense the more I think about it.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Combat code red! Everyone, in position!",
	id = 105099,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Mhm...",
	feeling2 = "",
	login = "This is Colorado, standing by. Awaiting orders.",
	detail = "Commander, I agree that my new main guns are cool, but you're staring at them an awful lot... It's not the guns you're looking at, it's me? Oh, I see... *blushes*",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[105100] = {
	hp_warning = "Now, this is a fun battle!",
	feeling3 = "The war cannot be won by a single person. Without true sisters fighting alongside you and a reliable backline supporting you, no matter how strong you are, your defeat is inevitable!",
	mail = "When writing a reply back, should I carry an anti-aircraft gun with me...",
	expedition = "Even though commissions are an important part of the war, but I'm just not interested in them.",
	win_mvp = "Haha! This is just the appetizer before the main course!",
	home = "Sigh, staying in port is so boring...",
	unlock = "I am Maryland, a member of the BIG SEVEN. “Fighting Mary”, yes, that's what they call me! I heard there are many battles ahead. I look forward to them all!",
	touch2 = "Commander, our fighting power is not in that area of expertise.",
	mission = "If I don’t complete the mission, then I can’t get a battle star.",
	vote = "",
	drop_descrip = "Colorado class battleship— Maryland, hull number BB-46",
	feeling4 = "Not all problems can be solved by fighting? Well, I don't really believe that... but you always seem to find a way to solve things. After all, you are my favorite Commander.",
	lose = "If only Oklahoma was here...",
	feeling1 = "A saying that I recently heard from my sister, “Never protest your loyalty to the weak”.",
	skill = "No matter how many times it takes, I will sink you again!",
	upgrade = "I really wanna try to shoot a volley from my main gun right now…",
	propose = "You really treasure these strange rings, do you? ...But since it's your decision, I'll go with it! From now on, I will protect you!",
	feeling5 = "Look into my eyes, as my most trusted companions, is it even necessary to use words to express the feelings I have for you in my heart?",
	main = "Fighting beside my sisters is the happiest thing in the world! |I hate foul play, only fair duels are real battles! |Working? ...I don’t know much about that, I’ll just do whatever you tell me to do.",
	touch = "Commander, are we going into battle?",
	voice_key_2 = -1,
	mission_complete = "Mission rewards... Darn, what a waste of time.",
	battle = "Dear opponents, do NOT disappoint me!",
	id = 105100,
	gift_dislike = "",
	gift_prefer = "I'll like this, right? Then I'll take it!",
	profile = "Eagle Union Colorado class battleship, ship no. 2 “Maryland”. As one of the BIG SEVEN, I often attended various celebrations. I escaped the attack on Pearl Harbor from behind Oklahoma. After undergoing retrofit, I successfully completed counter strike attacks on the Sakura Empire Navy. I participated in Operation Magic Carpet and received a total of seven battle stars. Commander, I just saw gunfire over there...oh, nevermind it was the sunset.",
	voice_key = 10510,
	headtouch = "",
	feeling2 = "I don't know who granted us the title of BIG SEVEN. But if those two keep mentioning it non-stop, then the title should have some special meaning to it.",
	login = "I think I smell gunpowder, has the battle started already? Pfft... turns out it was only Vestal cooking.",
	detail = "Celebration? Honor? Nothing else except for battles will draw my attention.",
	couple_encourage = {
		{
			{
				10502
			},
			1,
			"I will protect you this time!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[105102] = {
	hp_warning = "",
	feeling3 = "",
	mail = "You've got your mail delivered out here... Sheesh, how much work do you have?",
	expedition = "Commission team's back. Man, look how giddy they are.",
	win_mvp = "Hahaha! Now that was a perfect show!",
	home = "You picked a good time to come back. The fireworks show literally just started.",
	unlock = "Oh, hey, Commander – you here for a break, too? Relax, I won't rat you out to anyone else. Just kick back and enjoy the fireworks.",
	touch2 = "That was the tit – you ready for the tat?",
	mission = "",
	vote = "",
	drop_descrip = "Oh, hey, Commander – you here for a break, too? Relax, I won't rat you out to anyone else. Just kick back and enjoy the fireworks.",
	feeling4 = "",
	lose = "Tsk... Frickin' defeated.",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "You know how I feel even without having to put it into words. That means we've gotten so close, I'd trust you with my life. You're the reason I keep fighting, and... Gah, it's so embarrassing telling these things right to you!",
	main = "West Virginia wanted to play a number for the kids. I thought, \"Ugh, fine, as long as it gets the blood pumping\" and agreed... What she didn't say was we were gonna do a nursery song!|A beach performance oughta be big and exciting. If we can't all let loose, then it ain't relaxation!|Ahh! Love a drink by the beach! You want one, Commander?",
	touch = "Hey, wanna go swimming with... Whuh? Can't swim in my jeans? Who cares – I'll just take 'em off!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "I'm gonna pound you into dust!",
	id = 105102,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Hey! You're gonna mess up my hair!",
	feeling2 = "",
	login = "Secured a good seat for the fireworks show for you. C'mon, sit!",
	detail = "Oh yeah, how'd you like the concert me and my sisters put on earlier? I can give you a solo if you dig it – a little private show 'tween you and me.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[105109] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Oh, a letter. Alright, you write a reply while I replace the magazines on my AA guns.",
	expedition = "Gonna use those commission resources in the next battle, eh. Could use 'em in the NEXT next battle, y'know.",
	win_mvp = "You piles of junk aren't even worth mentioning!",
	home = "Just imagining scenarios all day... Nah, that's not gonna work. You need to get your exercise in or you'll turn weak.",
	unlock = "My retrofit is capital-D done! Hah, I generally know what's changed – the details, I'll discover in live battles! That alright with you?",
	touch2 = "Ahh, this where your fighting strength is? Hahaha!",
	mission = "New missions... I hope you get a battle star of your own. Hahaha!",
	vote = "",
	drop_descrip = "My retrofit is capital-D done! Hah, I generally know what's changed – the details, I'll discover in live battles! That alright with you?",
	feeling4 = "",
	lose = "Gah, they got me good...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I don't care if other people see me as a battle maniac, but I wanted to show you a different side of me... Although, I'll only go so far to not be myself. What do you think of me? I'll work hard in my own way depending on how you answer! Hahah!",
	main = "West Virginia can lull me to sleep in three minutes with her guitar... Huh? Colorado's violin does it in 30 seconds? H-how'd you know?!|There's all kinds of battle freaks. There're those who charge in headfirst, those who fight one-on-one fair and square, and those who just blindly swing their fists around. Me? I dunno what kind I am!|Ugh, work... You stick to what you know best, and I'll stick to what I do best – which means fighting!",
	touch = "We going into battle yet? Not that I'd mind shooting the breeze with you! Hahaha!",
	voice_key_2 = -1,
	mission_complete = "Rewards are here. Take 'em!",
	battle = "Strike first! Both with your shells AND fists!",
	id = 105109,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Fighting Mary has arrived! Just thought I'd say hello before I went off to the battlefield.",
	detail = "Since we're buds, will you fight with me? 'Course, you don't have to force yourself... Hm? Hahahaha! You've become a real fighter!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[105110] = {
	hp_warning = "Getting hit by a torpedo... it feels bad.",
	feeling3 = "I’m proud of my BIG SEVEN title. But aircraft carriers seem to be replacing us battleships in naval battles. I am losing myself in all this confusion: this strength that I possess... what is it for?",
	mail = "Could these be letters from my sisters?",
	expedition = "The commission fleet is really efficient. I hope the Commander can learn a thing or two about efficiency.",
	win_mvp = "Have you seen this? This is the inevitably tragic ending of those who dare challenge the BIG SEVEN.",
	home = "What a peaceful port, it reminds me of Hawaii before the war.",
	unlock = "It’s finally my time to show my strength... Under the guidance of fate, the third ship of Colorado class, West Virginia, reporting in.",
	touch2 = "Commander, it seems you’re rather close to getting lectured by me.",
	mission = "Carrying out missions is an important part of enhancing the strength of the fleet.",
	vote = "",
	drop_descrip = "Colorado class battleship— West Virginia, hull number BB-48.",
	feeling4 = "After joining your fleet, the answer to my question has been gradually answered... This power of mine is destined to protect everyone including you, Commander. My strength still has its value, even if I'm no longer the heroine of the battlefield.",
	lose = "I don't want to recall the humiliation I suffered on that day...!",
	feeling1 = "Commander's laziness is almost beyond my bottom line.",
	skill = "Have a taste of my 406mm guns!",
	upgrade = "It seems the Spokane Cup this year will still be mine.",
	propose = "You’ve decided to perform a pledge ritual with me? Commander really made a bold decision... In that case, I will not let your expectation down. I'll guard you until the very end.",
	feeling5 = "Commander, you have become someone who can completely take charge on the battlefield. At last, my powers have found a worthy partner... What? A love confession? Don't you trick me to say that, you fool——",
	main = "The combat exercise didn’t go well… Is the Commander being lazy again? |I will never forget the humiliation I suffered on that day. |On the night of the Surigao Strait, I witnessed the last moments of the Sakura Empire fleet... They truly are a worthy opponent...",
	touch = "This should be... a friendly gesture I suppose.",
	voice_key_2 = -1,
	mission_complete = "The mission was nicely executed, good one.",
	battle = "The humiliation I once suffered... I'll repay you double!",
	id = 105110,
	gift_dislike = "",
	gift_prefer = "Not bad... I'll treasure it.",
	profile = "During a \"Naval Holiday\", my sisters and I were honored amongst the world's strongest battleships. We were granted the high-profile title of - BIG SEVEN. Although times are changing, the three of us still have the strength to fight any enemy fleet in a decisive battle, please don't forget that.",
	voice_key = 10511,
	headtouch = "",
	feeling2 = "I was once seriously injured, but then I was greatly enhanced during the process for my repairs…",
	login = "You’re late... the exercise has already begun, hurry!",
	detail = "Do not doubt my combat performance, Commander.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[105112] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission team's back. Hope they'll make it in time for our last song.",
	win_mvp = "Do not mess around with a Big Seven. Ever.",
	home = "We've already started, but you've shown up at the perfect time. You're gonna like this next song, Commander.",
	unlock = "Colorado, Maryland, you two ready to rock? Keep your cool! Commander, and everyone in the audience, get ready for the Big Seven's big performance!",
	touch2 = "I wasn't trying to tempt you into this...",
	mission = "",
	vote = "",
	drop_descrip = "Colorado, Maryland, you two ready to rock? Keep your cool! Commander, and everyone in the audience, get ready for the Big Seven's big performance!",
	feeling4 = "",
	lose = "Guh... We almost had it...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Mic test, mic test. Can you hear me clearly, Commander? What about you, Colorado and Maryland?|While I usually play slightly more chill, calm tunes when I'm alone, this case obviously calls for something explosive.|I always thought the ladies of the Royal Navy hated this genre... But as Rodney and more have shown, presumptions do you no good.",
	touch = "A song request? Colorado, Maryland, we're playing the Commander's fave next.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Sink or swim. Let's go.",
	id = 105112,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Whew... You feeling the heat, Commander? Er, not the weather, I was talking about the performance... Alright, awesome.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[105119] = {
	hp_warning = "",
	feeling3 = "",
	mail = "It's about damn time Maryland learned how to file paperwork... Oh, Commander, there's a letter for you.",
	expedition = "It's unhealthy to overwork yourself, Commander. Let the rest of us greet the commission team.",
	win_mvp = "",
	home = "You like it when the port is bustling? Fair enough. I don't mind either way as long as there's no fighting.",
	unlock = "West Virginia, completing retrofit. Back when I joined the fleet, I said I'd show you my strength – now, after you've made me this much stronger, I feel humbled. Once more, Commander, my strength is yours.",
	touch2 = "I hope you're ready to face the consequences. Now then... *blushes*",
	mission = "",
	vote = "",
	drop_descrip = "West Virginia, completing retrofit. Back when I joined the fleet, I said I'd show you my strength – now, after you've made me this much stronger, I feel humbled. Once more, Commander, my strength is yours.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Although I don't try to appear frail, it does work at tricking the enemy into thinking so. Just like that Sakura Empire Big Seven... Or am I wrong?|\"Wee Vee?\" Ahahah. You're free to call be my whatever nickname you want.|So, Commander, about that private training we talked about a while ago... You were thinking the same thing? Okay... Should we go, then?",
	touch = "I accept your affection.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "It's time to face off!",
	id = 105119,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Look, I'm not Colorado...",
	feeling2 = "",
	login = "Still a while to go until the wargame starts... Hey, Commander. I've been waiting for you.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[105120] = {
	hp_warning = "Sisters, hold on!",
	feeling3 = "If you’re only going by appearances, every child in this fleet looks cute. But in terms of personality, they all have their unique quirks. To be honest, I am a bit envious of them. (strokes chin).",
	mail = "You’ve got new mail~",
	expedition = "The commission is over, they should be back soon~",
	win_mvp = "If the Commander gives me a few praises, then I will be very happy~",
	home = "Ah, hold on, your collar is all messed up. Stand still while I fix it... there you go~ (waves).",
	unlock = "North Carolina here, awaiting your dispatch. Although I may seem to have a bland personality compared to my sisters. But as the saying goes, no personality is still a personality, hehe. Anyways, awaiting your orders, sir.",
	touch2 = "Not good...",
	mission = "It’s not good to leave tasks unfinished.",
	vote = "",
	drop_descrip = "North Carolina class battleship— North Carolina, hull number BB-55.",
	feeling4 = "I always believe there is nothing wrong with being ordinary. But after meeting you Commander, I want to change myself a little... after all, my sisters are all so charismatic~ Well.. Commander, are you fond of bunny girls?~",
	lose = "Not so successful... let's try again next time.",
	feeling1 = "Commander, I'm gonna get angry.",
	skill = "Never let your guard down.",
	upgrade = "I'll try to work a bit harder~",
	propose = "Well, your trust deserves to be rewarded... umm... Commander, do you like bunny girls?~",
	feeling5 = "Do you want to eat something later Commander? And then you can accompany me to go shopping, if you want to get something then let’s go together. Then... hehe... let’s take a walk in the park? Commander, everywhere I go as long as I’m with you will be just fine~",
	main = "What do I wear inside? It's not something that’s so significant |If I think about it, I certainly have been to many places... seen many landscapes, and also parted ways with many people. |Sometimes I get so envious of my younger sister Washington and how she’s so energetic all the time.",
	touch = "Do you need help with something?",
	voice_key_2 = -1,
	mission_complete = "The mission rewards were sent out, are you not going to pick it up?",
	battle = "Don’t be overconfident, and try not to be so nervous while focusing on winning~",
	id = 105120,
	gift_dislike = "",
	gift_prefer = "Are you sure? Th-thank you.",
	profile = "I am North Carolina class ship no.1. I can be considered the big sister battleship of the Eagle Union~ I don’t particularly like or dislike anything, so to speak. Even though I have fought in all kinds of engagements, I have not gained any fame... I am a little bit troubled by this.",
	voice_key = 10512,
	headtouch = "",
	feeling2 = "Commander remembers me~ Not that I’m boasting or anything, but I still have confidence in my low sense of existence. (smiles wryly)",
	login = "Welcome back~",
	detail = "Being stared like that makes me a bit shy...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[105121] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Maybe I should keep this outfit on and give the commission team a real surprise when they return... Hehehe~ I'm just joking.",
	win_mvp = "Victory isn't the result of individuality. It's the result of good teamwork. Hehehe~",
	home = "Could you help out with my ribbon? It's a bit too close for my liking... Ah, thank you.",
