	touch2 = "I'll take that to mean you really like this outfit, am I right? Hehehe~",
	mission = "",
	vote = "",
	drop_descrip = "Commander? Oh, umm, this is just, err, equipment changing practice... Also, I recall you saying you like bunny girls. You still do, right?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Commander, are you free today? We could go on a date somewhere. Not in this outfit, of course, just my regular one. Thank you for understanding. Hehehe~",
	main = "Whew. This feels so liberating! ...And not in any indecent sense, or anything.|Did Washington manage a proper smile today? She's got features as sharp as a knife, so it's easy to misinterpret her expression.|I am genuinely interested in bunny girl things, but it's quite awkward to actually tell people about them...",
	touch = "",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 105121,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "It's true – you need the ears, or you can't call yourself a bunny girl. Hehehe~",
	feeling2 = "",
	login = "Welcome back, dear! Is there anything you need a hand with?",
	detail = "\"Do I wear this all the time\"? Maybe, maybe not. I'll leave the answer up to your imagination.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[105122] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "My air cushion's a bit deflated... Good timing, Commander! Let's inflate it together.",
	unlock = "Commander, today I'm in a bunny swimsuit, see? You don't see how it's a bunny swimsuit...? Come closer and get a better look, then. Heheheh.",
	touch2 = "Heehee. Be thorough over here, too♪",
	mission = "",
	vote = "",
	drop_descrip = "Commander, today I'm in a bunny swimsuit, see? You don't see how it's a bunny swimsuit...? Come closer and get a better look, then. Heheheh.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Are you nodding off? Come hither~ The cushion's a bit small, so hold onto my waist... Good night, Commander. May your dreams be full of hopping bunnies~",
	main = "You want to nap with me? Mmgh... There, over here, Commander. I made room for you on my air cushion.|The sea breeze is making me sleepy... But you won't pull any frisky pranks on me while I nap, right? Right~?|I saw all sorts of distinctive designs when I was picking out my swimsuit... But this is the one that sits right♪",
	touch = "Commander, a bit higher... To the right... Oh, you already put some there? Heheh, but you like touching me there, right?",
	voice_key_2 = -1,
	mission_complete = "Mission complete! Oh, I didn't mean my sunscreen. Keep it up, please!",
	battle = "",
	id = 105122,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "You're putting sunscreen on my hair, too? Quite the peculiar preference...",
	feeling2 = "",
	login = "Over here, Commander! I'm a bit shy to ask for this, but... Could you rub some sunscreen on me? On every inch, every nook and cranny of my back~",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[105130] = {
	hp_warning = "I won't let go of victories to my enemies!",
	feeling3 = "No, no, that’s not right. If we do it this way, won’t it end much the same like in the past? … Don’t try so hard? You sometimes say stuff like that… Hmm? That was a good smile from me just now?",
	mail = "Hey, your mail.",
	expedition = "Your memory can’t be worse than mine, right? The commission fleet has returned, won’t you go greet them?",
	win_mvp = "Sure enough, I am happiest when all the foes are annihilated~",
	home = "I’m glad that you didn’t get hurt—— What?! I don’t have feelings for you!",
	unlock = "Hello, Commander, I am Washington... my sister told me that I cannot be so rough once I join the fleet, so I am practicing my smile. Darn, why must I listen to her...",
	touch2 = "...You wish to die? (Smiles)",
	mission = "A new mission? Haha, now my blood is boiling.",
	vote = "",
	drop_descrip = "North Carolina class battleship— Washington, hull number BB-56.",
	feeling4 = "Lately, my smile has become more natural? Emm, huh (scratches head), I was recently trying to find a new hobby. While I was searching, I realized that being with you is not so bad… (whispers)",
	lose = "Oh, I will not forget you!",
	feeling1 = "You are too weak, it’s no fun playing with you, go practice some more.",
	skill = "Out of my way. I'm ready to fight!",
	upgrade = "It feels so good to become stronger.",
	propose = "Wait wait! We’re doing “that”, right? Is this your new way of teasing me!... Damn, you bastard, I’m not sure if I should cry or laugh about this...",
	feeling5 = "I couldn’t help but smile when I saw you, this is the first time that I’m feeling this way... although, I also have other feelings rushing towards me. I suddenly want to see your expression when you are bullied by me—— Commander, stay with me for a while. (Laughs)",
	main = "My smile looks beautiful? You jerk... oops, keep smiling, keep smiling. Thank you for your compliments. | Hey, that rigid South Dakota is still the same. Commander, you see, I am cuter than her. | A true measurement of friendship is their actions and not their words, I don’t like people who are rhetorical in nature.",
	touch = "Don’t touch me as if you’re trying to be intimate with me.",
	voice_key_2 = -1,
	mission_complete = "Go grab the reward yourself, I’m not interested.",
	battle = "Ok, let’s work out. (Snickers)",
	id = 105130,
	gift_dislike = "",
	gift_prefer = "Oh? Alright, who do you want me to send flying?",
	profile = "North Carolina class ship no. 2. I am Washington! The thing I like to do the most is to destroy my enemies. Recently, I am practicing on my smile. —— Battle record? I don’t really show off with such things, all in all, how’s my smile?",
	voice_key = 10513,
	headtouch = "",
	feeling2 = "What must I do to possess a good smile... think about the things I like? If so, I feel very happy even at the thought of winning against South Dakota... muahahaha...",
	login = "Welcome back... how does my smile look? (Forcibly smiles)",
	detail = "Hmm, you want to know how well I fight?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[105131] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Crap, the commission team must be... Oh, you remembered? Full marks, Commander.",
	win_mvp = "Now this is something worth celebrating! Am I right?",
	home = "Back safe and sound. Thank goodness... Uh, no? I-I wasn't... talking about you...",
	unlock = "Sup, Commander? ...Looking good? I don't think this outfit's anything special... You better not be trying to cozy up to me, or I'll knock your teeth out!",
	touch2 = "What the–?! Are you drunk out of your mind?!",
	mission = "We've got a new mission. It'll do nicely as an after-dinner workout.",
	vote = "",
	drop_descrip = "Sup, Commander? ...Looking good? I don't think this outfit's anything special... You better not be trying to cozy up to me, or I'll knock your teeth out!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Heheh, so then South Dakota and I just... Hang on, I feel like I'm talking to myself here! C'mon, tell me a funny story or something! I've smiled like you asked me to, so keep up your end of the deal...",
	main = "W-welcome back, dear♪ ...Doesn't hit the same. How does North Carolina do it?|South Dakota's on the piano, huh. I ain't got her level of finesse, so don't go comparing me to her... Wish I could play like that.|Remember our deal, Commander – I'm coming along when you go around greeting people, got it?",
	touch = "Breaktime already? All right, take a load off.",
	voice_key_2 = -1,
	mission_complete = "You claimed the rewards yet? ...Oh please, like I give a damn about that!",
	battle = "We've got this in the bag, easily.",
	id = 105131,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Wipe that stupid grin off your face. I know exactly what you're thinking! I am NOT gonna dress up like my sister today!",
	detail = "Huh. Guess I can't help but crack a smile after having some good grub and a bit of liquor... Meaning, I don't gotta practice smiling anymore!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[105132] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Was that the new letter alert? Are you still working at this hour? I'm confiscating that damn letter!",
	expedition = "Finished a commission, did you? Hold off on that reception until your full-body examination is done.",
	win_mvp = "",
	home = "Stay right where I can see you– Ahem... What I mean is: Don't go wandering around at night. It's dangerous, and you're my patient.",
	unlock = "Yo, Commander. Called for a nurse, didn'tcha? ...You didn't? Bullcrap, you totally did! Listen up, you're a patient, so act like it – drop your damn work and let me examine you.",
	touch2 = "Oh boy, your condition's serious. This calls for emergency measures.",
	mission = "You've still got missions to do? Don't care, you need to rest right now.",
	vote = "",
	drop_descrip = "Yo, Commander. Called for a nurse, didn'tcha? ...You didn't? Bullcrap, you totally did! Listen up, you're a patient, so act like it – drop your damn work and let me examine you.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "The hell? Why's your heartbeat through the roof? ...'Cause I'm standing next to you? L-look, I can't examine you without getting close! And I can't just leave you be, so I gotta nurse you even harder. I'll be tending to you the whole night, so brace yourself...",
	main = "Ugh. I happened to be on duty, that's all... Man, your temp really is going up. Better give you a thorough examination, then.|You don't think the call-nurse button even beeped? Uh, of course it did, dumbass! Why would I be here if it didn't? Listen – beep-beep-beep! There, it beeped. Now shut up and let me continue my examination.|Nurses gotta be nice to their patients, blah blah blah... If you don't do as I ask, you leave me no choice but to MAKE you comply.",
	touch = "Hold still, dammit. I'm examining you.",
	voice_key_2 = -1,
	mission_complete = "The mission rewards can wait, okay? Focus on the examination!",
	battle = "",
	id = 105132,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Y-you're ill, so act like it, god dammit!",
	feeling2 = "",
	login = "(Gotta smile, gotta smile...) You ready, Commander? Save your files and all that so I can start examining your... Wh-what? Why're you looking at me like that?",
	detail = "Hey... Quit staring at me. What's the big deal? It's just a nurse outfit. F-for your information, I'm just here to do my job... So stop fricking staring!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[105140] = {
	hp_warning = "I won't hold back now...!",
	feeling3 = "I exist to help you achieve your goals, Commander. Other than that, I have no real value... A skirt? I've never worn something so fluffy before.",
	mail = "There's new mail, Commander.",
	expedition = "The commission teams are back... If it is necessary, send me off as well.",
	win_mvp = "Partial victories aren't worth celebrating, Commander.",
	home = "Good fight out there, Commander.",
	unlock = "I am South Dakota, Commander. I shall become your shield and protect you from all cannon fire.",
	touch2 = "If this is what you want to do...",
	mission = "Commander, please do not forget about completing the missions.",
	vote = "",
	drop_descrip = "South Dakota-class battleship –  South Dakota, Hull Number BB-57!",
	feeling4 = "Another way to live other than fighting? I... do not know what to do, Commander. I have always lived like this... Can you teach me?",
	lose = "I am sorry, Commander... It's a shame...!",
	feeling1 = "... I shall follow your orders.",
	skill = "This is your stop!",
	upgrade = "My shields have become stronger",
	propose = "I feel warm when you're by my side, Commander. Your goals bring me the drive to fight. I become happy when I hear your words... I once offered you my shields. From now on... I give you my heart.",
	feeling5 = "So this is your perspective, Commander... I choose how I live, was what you said... This time, I fight not for my duty, but for the sake of your smile, Commander.",
	main = "In the darkness, my will was tempered. I fear nothing.|As long as I am of use to Commander, I am fine with handing my credit over to others.|Those who stand as Commander's enemies, are enemies all the same.",
