_G.pg.base.ship_skin_words[105141] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Everyone's back safe and sound. Now I can resume practicing with peace of mind.",
	unlock = "Massachusetts suggested I learn something useful that's unrelated to combat, so I started playing the piano... It seemed impossible at first, but after actually trying it, I've developed a pretty good feel for it.",
	touch2 = "",
	mission = "Music and instruments are simply hobbies. We ought to prioritize our missions, Commander.",
	vote = "",
	drop_descrip = "Massachusetts suggested I learn something useful that's unrelated to combat, so I started playing the piano... It seemed impossible at first, but after actually trying it, I've developed a pretty good feel for it.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Without you, I doubt I would've ever come to understand what splendor this world holds, or started playing the piano either... Commander, I'd like to play you a song that's important to me.",
	main = "I can't get used to this flimsy dress. I'd rather wear my regular clothes...|My cat goes for the keyboard when I'm not playing... Do you want to practice the piano too, kitty?|We can express so much through music. I suppose that's fitting for someone bad at expressing their feelings like I am.",
	touch = "",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 105141,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "What song should I play for you today...",
	detail = "Aurora asked me to perform with her... I guess it can't hurt to try.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[105150] = {
	hp_warning = "I'm still in the fight!",
	feeling3 = "Not only are you good with brain-intensive strategy, you've even got the chops for bodybuilding. AND you work pretty hard. Yeah, I've gotta hand it to you!",
	mail = "Commander, you've got mail! Ah, and the mag I ordered has arrived, too.",
	expedition = "The commission team's back. I wonder if they had any good fights out there...",
	win_mvp = "That was too easy! Gimme a more challenging fight next time!",
	home = "Cool, you're back. Now drink this protein shake and feed your muscles!",
	unlock = "South Dakota-class battleship Indiana, reporting for duty! ...No need to be so stiff and formal? Then... Nice to meetcha, Commander. You're on the victory train with me now, baby!",
	touch2 = "I'm \"muscular in other places, but squishy here\"? Th-the hell are you talking about?!",
	mission = "You've got to do your missions, Commander. Hm? You weren't expecting me to remind you? I may not look it, but I have a good sense of time.",
	vote = "",
	drop_descrip = "South Dakota-class battleship – Indiana, Hull Number BB-58.",
	feeling4 = "(\"The sun's rays embrace the Earth, and the moon's light kisses the sea. If you hadn't put your lips to mine, the meaning in Mother Nature's pretty work would cease to be.\" Alright, let's go with that. Now just to sneak it in between the pages of this training mag I'm gonna give the Commander...)",
	lose = "It's alright. Retreating ain't the same thing as losing. We'll try again once we're stronger!",
	feeling1 = "Ugh... I hoped you'd be one of the few who'd be my equal and make me use my brain.",
	skill = "Go to hell!",
	upgrade = "Ahh! I can feel the power growing within me!",
	propose = "Your answer's in this envelope? Alright, let's– Hang on, why'd you put it in an envelope? ...'Cause my feelings struck a chord with you? Oh, okay! Then on the ring goes! Now c'mon, stop standing there and make your vows with me!",
	feeling5 = "Ahem... So, Commander, did you read that mag I gave you yet? What? You haven't?! ...Well, it's just, I kinda snuck a love letter in there... To hell with it! Read it NOW! One page at a time! Don't you dare flip through it!",
	main = "Copying childhood heroes doesn't make you brave. It just makes you a reckless moron.|I brought you lunch, Commander! Steak, fruit salad, and a protein shake with kale! Healthy and nutritious stuff! ...Why are you giving me that weird look?|Tactics? Yeah, I know those give you a battlefield advantage and all. But me, I like the thrill of fighting my foes head-on. Plus, ain't it more satisfying when you win that way?",
	touch = "Hm? We got a combat mission?",
	voice_key_2 = -1,
	mission_complete = "We've got mission rewards waiting. I heard they're selling supplement lucky boxes and I feel like trying my luck.",
	battle = "Behold the might of Indiana!",
	id = 105150,
	gift_dislike = "",
	gift_prefer = "Hey, this looks like something that'll up my power!",
	profile = "I'm Indiana, Eagle Union South Dakota-class battleship. That's about it, really. All you need to know is this – I will grind all your enemies into dust. Put it another way, nobody can mess with you as long as I'm around.",
	voice_key = 10515,
	headtouch = "Hm? Need something?",
	feeling2 = "The destroyers and submarines around here all clam up or look shocked when they see me... Did I do something wrong or what?",
	login = "Oh, you're back, Commander. Office work is sooo lame without you... How do you handle this day in, day out? I'd rather take on a hundred, no, a thousand enemies.",
	detail = "I'm surprised the port's got so much gym equipment! We should go work out, you and I, Commander. It'll put some muscle on your bones AND help clear your mind.",
	couple_encourage = {
		{
			{
				10706
			},
			1,
			" Hah! Imagine getting to fight alongside you!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[105151] = {
	hp_warning = "",
	feeling3 = "",
	mail = "That stuff floating through the air... Oh, here, Commander. Found a letter with your name on it.",
	expedition = "",
	win_mvp = "If this is all you've got, you're not cut out for robbery!",
	home = "Finished another task, huh? Have some beef jerky. It's got protein in it and fills your stamina right back up. Try a bite.",
	unlock = "Oh, look who's here. What am I doing here? Well, I figured through the roof was the fastest way in, so I punched a hole through the ceiling. The bandits are all down for the count, so let me take it from here.",
	touch2 = "Urgh! Can you STOP doing this?! We're in public here!",
	mission = "",
	vote = "",
	drop_descrip = "Oh, look who's here. What am I doing here? Well, I figured through the roof was the fastest way in, so I punched a hole through the ceiling. The bandits are all down for the count, so let me take it from here.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "When we get tired of this, let's settle down for a stable, comfortable life. Ahem... Because you've supported me and made a place where I belong. What I'm trying to say is – you're the most important person in the world to me! Don't make me say another word!",
	main = "You can't arrest bandits with brawn alone. You need a general plan. How do you get in? How do you prevent them from getting away? You need to think on your feet – and you do that by having your boots on the scene! Hahaha!|You think it was funny how they came up to me, swinging a knife, and I just shot 'em? Hahah! I've got the advantage at this range. Times are changing.|It's never too late for justice, but I don't like delayed justice, so I deliver what's long overdue with a bullet!",
	touch = "You digging my revolver? Ahh. It's been my partner for many years.",
	voice_key_2 = -1,
	mission_complete = "You got 'em all done, huh? Hell of a good job, Commander! Lemme treat you to a drink!",
	battle = "",
	id = 105151,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Cut it out! You're gonna mess up my hat!",
	feeling2 = "",
	login = "Watch your step, Commander. This place is falling apart and one wrong step could send you to the floor below. We've still gotta collect the cash and return it to the bank.",
	detail = "That's that robbery case finally done and dusted. The bandits can cover the tavern's repair bill, heh. Now, you ready to receive your bounty?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[105170] = {
	hp_warning = "I know just the thing to turn this situation around!",
	feeling3 = "Look at that, you're already starting to chat me up. So, what's on your mind today? Something a bit more technical? Small talk about daily life? ...Oh, you want me to choose?",
	mail = "You've got new mail. Heh, dont'cha just love the anticipation~?",
	expedition = "Your commission fleet's back. Are your words of praise not the best reward you can give them? Hehe~♪",
	win_mvp = "Course: steady! Objective: completed! Enemies who can stop us: none! Heheh, don'tcha love it when things go smoothly?",
	home = "Wanna check the battle results~♪ Yeah? Who do you wanna start with? Oh, you'll do it yourself? I'll listen in while enjoying some ice cream over here.",
	unlock = "The indomitable Black Dragon of the Eagle Union is none other than me, New Jersey! You're about to witness true power! Haha, just messing~♪ Don'tcha just love flashy introductions?",
	touch2 = "Commander, don'tcha just love being put on the defensive? In more ways than one~♪",
	mission = "Did you already accept this mission? Sounds good, let's take care of it together.",
	vote = "",
	drop_descrip = "Iowa-class battleship – New Jersey, Hull Number BB-62.",
	feeling4 = "My my, look who's all run down today... I knew it, you've been overworking yourself. C'mere, lie down here and let me take care of you. Yeah, my thighs make for a pretty good pillow substitute huh? Don'tcha just love this kind of stuff~?",
	lose = "Unbelievable... I'm actually getting cornered?! ...I'm not gonna be able to sleep 'til I figure out how to set things straight!",
	feeling1 = "Ah, so you're the kind of person who makes girls cry. Yeah, you'd better feel bad about it.",
	skill = "Fire control, I'm counting on you!",
	upgrade = "Some say that the age of battleships is over. They haven't met the Iowa class.",
	propose = "Commander, I can already hear everything you're thinking. As long as you're fine with it, I don't have any objections~ After all, I still owe you a proper confession, don't I? Hehe, don'tcha think that's what mutual love is supposed to look like?",
	feeling5 = "Commander, would you prefer I take the lead, or would you rather do it? Hold up~ I'll see for myself when the time is right, so there's no need for you to answer in words. After all, don'tcha just love being toyed with~?",
	main = "Iowa versus Yamato, huh? A real classic. Don'tcha just love that kind of stuff?|I go for the fruity stuff~ green apple, orange, and soda water. As for coffee... Not my favorite, I guess?|How much stuff should I be doing as your secretary? ...Lemme think, how does 40% sound? If I did everything, wouldn't that make me the commander? Heh.|About that matter... I must admit that you have a point, Commander. How about taking my suggestion next time though?|It's now the age of carriers? ...Dunno about that. If carriers are able to evolve, what's to say that battleships can't also evolve?|They call me Big J or the Black Dragon of the Eagle Union! ...What, got a problem with talking myself up a bit?",
	touch = "I'll take any work-related requests, but anything outside of that... won't come cheap. Just kidding~♪",
	voice_key_2 = -1,
	mission_complete = "Since we already got the hard stuff out of the way, why not take a little break? It's gonna be pretty easy to prioritize whatever is left~",
	battle = "Everyone, Level 1 combat readiness! Set sail!",
	id = 105170,
	gift_dislike = "",
	gift_prefer = "This is just what I wanted! Haha!",
	profile = "I am battleship New Jersey, the indomitable Black Dragon of the Eagle Union. When I say \"indomitable,\" I'm not just tooting my own horn, hehe~♪ If you knew more about me, you'd know exactly what I'm talking about.",
	voice_key = 10517,
	headtouch = "Done having your fun yet? Hehe, now it's my turn~♪ Take a seat!",
	feeling2 = "We'll only get in each other's way if we keep an ambivalent relationship. Say, don'tcha think getting touchy-feely might help break the ice? ...Just kidding~ See, you're already not as nervous~ Hehehe~♪",
	login = "Glad you made it. Do you already have a plan for what you wanna do? And how do I factor into those plans?",
	detail = "Thanks for finishing the equipment inspection. All systems nominal! ...Oh my, you seem to be unable to take your eyes off me~ Not that it bothers me though? Besides, don'tcha like this sort of stuff?",
	couple_encourage = {
