_G.pg.base.ship_skin_words[105172] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Commission team's here! ...You're still putting on your sunscreen? Come ooon.",
	win_mvp = "",
	home = "Good work out there! Oh, honey, you look a little burned. Hahaha, I'm kidding! Here, I'll get you a drink. Take it easy♪",
	unlock = "Sooo hot... Are you alright, honey? You're not heat-exhausted, are you? I'll share my drink with you if you're thirsty, but in return, I'll need you to put my sunscreen on for me. Heheh, that's just what you like to do, right, honey~?",
	touch2 = "Hyah?! Geez, honey. I know you like this stuff, but c'mon... *blushes*",
	mission = "",
	vote = "",
	drop_descrip = "Sooo hot... Are you alright, honey? You're not heat-exhausted, are you? I'll share my drink with you if you're thirsty, but in return, I'll need you to put my sunscreen on for me. Heheh, that's just what you like to do, right, honey~?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Once we're done, I'll spread stuff on you! That chilly, slick, sticky stuff, nice and slow... Hahah! I thought you might like me doing this. Do you?",
	main = "Aloe works as sunscreen, too? Then get to putting it on me! ...Whoa, it's all slippery and sticky... Hyah?!|Mm... I want ice cream now... Okay! Want one, honey? Don't worry– all of us Eagle Union ships brought ice cream.|Wanna go see Ticonderoga with me later? Tanning is fun and all, but I'd love to lie down in a cool place. You decide, honey.",
	touch = "I'm counting on you, honey!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "I won't let my honey shed a single tear!",
	id = 105172,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "It's a scorcher out there... Midsummer sunlight is rough no matter where you go. Honey, did you put on sunscreen? We'd better get some on you~ Hahaha♪",
	detail = "What's up? Oh, are you taken by my swimsuit? Hahah, well, it is me you're looking at. Of course you'd be stunned! Besides, that's just proof of your superb taste, since you picked it!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[105173] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Don't just stand there, honey. Dance with me! I'll teach you how, so don't worry if you've never done it~ Now, give me your hand and try spinning with me! Hahaha!",
	unlock = "Phew... It was really hard to cinch the ending, but I can handle anything! So, honey, did you like it? Hellooo, honey? Aww, are you so mesmerized that you can't speak? Hahaha!",
	touch2 = "Heheh~ Did that make your heart skip a beat? You must really love this outfit!",
	mission = "",
	vote = "",
	drop_descrip = "Phew... It was really hard to cinch the ending, but I can handle anything! So, honey, did you like it? Hellooo, honey? Aww, are you so mesmerized that you can't speak? Hahaha!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "There's this thing they say in the Dragon Empery... Umm, something about the moon waxing and waning and driving people apart... Anyway, the moon here never wanes! And that means I'll always get to be with you♡",
	main = "Mm, those flowers smell good~ Do you think they have ice cream with this flavor? I bet it'd be really tasty!|Did putting this together take a long time? Hmm... I mean, I guess it did. But what matters to me is that you like it!|Ack... How did my ribbon get tangled in my hair accessory? Honey, help me untangle them! ...I'm too far for you to see? Then get closer, silly!|You love this outfit, huh? Okay, pick. Which do you like more – the usual me, or me in this dress? ...Geez, don't hesitate now. You're supposed to say you love both, silly!",
	touch = "It's cold at night, y'know? Come here, honey~ Huuug!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 105173,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "So this is a Dragon Empery-style bun? It sure is hard to tie...",
	feeling2 = "",
	login = "You're right on time. Welcome, honey! When I saw you stunned and gawking, I just knew this surprise was a success.",
	detail = "I built this entire set myself, of course! This is easy stuff for the big, strong Black Dragon of the Eagle Union! Ting An deserves some of the credit for getting me the tools, though.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[105174] = {
	hp_warning = "",
