	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 105174,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "What's the matter? Want more kisses? Haha, I thought so♡",
	feeling2 = "",
	login = "Over here, honey! Hehe, this is the best seat in the house! I've got the AC at my back, and I can still see you as soon as you arrive! Ah, perfection.",
	detail = "Everyone's getting into the racing mood! You'd better warm up soon, honey! But first, a little good-luck charm... Mwah!",
