_G.pg.base.ship_skin_words[105200] = {
	hp_warning = "Well well, aren't you the frisky bunch... Ahaha!",
	feeling3 = "I've been gettin' along pretty well with the Sakura Empire girls. I thought they'd hold a grudge against me, but turns out that wasn't the case at all. Mhm, they're an interestin' bunch!",
	mail = "What's up, Commander? Oh, the mail? Ah, um, I forgot to bring it over. Give me a sec.",
	expedition = "I can see the commission fleet comin' back over the horizon. Mhm, I'm real proud of my eyesight!",
	win_mvp = "Kickin' the enemy's ass is all in a day's work for me. What are you praisin' me for?",
	home = "Commander, come sit in my lap. Huh? Isn't everyone doing this nowadays?",
	unlock = "I'm Alabama. You need somethin'? ... Prepare for duty? Oh, sure. Got nothin' better to do, so might as well. Let's go!",
	touch2 = "Huh......? Commander, the hell are you doing?",
	mission = "Commander, what's this big ol' stack of papers? Oh, I see... so those are the missions...",
	vote = "",
	drop_descrip = "South Dakota-class battleship – Alabama, Hull Number BB-60.",
	feeling4 = "Commander, let me give you a hug... This feels really nice and puts my mind at ease. Mhm, I like it.",
	lose = "Time to retreat? Fine...",
	feeling1 = "......Who the hell are you?",
	skill = "Don't die on me just yet!",
	upgrade = "I feel like I could beat someone up right now... Mmh!",
	propose = "Is this a promise to become my personal hugging' pillow? Will you let me cling to you as I fall asleep every night? Mm... that makes me happy. Commander, can I start huggin' you now?",
	feeling5 = "Commander, can you come to my room tonight? Um, I've always hugged a stuffed animal to help me sleep, but I was thinkin'... maybe you'd be even better...",
	main = "Commander. Com-man-der. Commanderrrr~ Oh, I didn't need anythin'. Just felt like callin' for you. |I'd like to have a Turkey Shoot. Makes me wish I could fly... |Sure is nice outside. Commander, wanna go lie in the grass under the sun? I could stay like that all day...",
	touch = "You're interested in my abs? Go ahead and feel 'em.",
	voice_key_2 = -1,
	mission_complete = "Commander, I'll go fetch the mission rewards. I'm big and strong, after all!",
	battle = "I won't let y'all leave until I've had my fun!",
	id = 105200,
	gift_dislike = "",
	gift_prefer = "That's mighty good of you, Commander.",
	profile = "I'm Alabama, fourth ship of the South Dakota-class, also known as Lucky A... What else? Uhh... I received some honors while fighting in Norway, the Marshall Islands, and the Marianas. Then, there was Leyte and the trip to the Sakura Empire... Since then, I've just been taking it easy in the Mobile Bay.",
	voice_key = 10520,
	headtouch = "",
	feeling2 = "Commander, can you call Tirpitz out here? I've always wanted to see which one of us is stronger, but she always ignores me.",
	login = "Oh, it's you, Commander. I almost mistook you for a shady person and sent you flyin'.",
	detail = "Commander, I'm hungry. Think you could get me a roast turkey?",
	couple_encourage = {
		{
			{
				10514
			},
			1,
			"Sis, I'll be the one to beat them to a pulp, okay?",
			0
		},
		{
			{
				40502
			},
			1,
			"I challenge you, Tirpitz!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[105201] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome back. You wanna order somethin'? We got steamin' hot baozi, if you're interested.",
	unlock = "Hrmm... Lotta orders to work through... Runnin' a Dragon Empery restaurant ain't easy. Hmm? You here for some chow too, Commander? Then how about... I put you ahead in line?",
	touch2 = "Uh, Commander? What kind of Lunar New Year tradition is this?",
	mission = "",
	vote = "",
	drop_descrip = "Hrmm... Lotta orders to work through... Runnin' a Dragon Empery restaurant ain't easy. Hmm? You here for some chow too, Commander? Then how about... I put you ahead in line?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Havin' snowball fights, lightin' firecrackers, eatin' baozi... It's all a ton of fun. Especially with friends.|Heard Massachusetts and Jean Bart are gonna have a snowball fight. Curious to see who'll win... By the way, are riggings fair game?|Two beef baozi, one veggie baozi, and some shaomai... Comin' right up. Manjuus, bring this note to the kitchen.",
	touch = "You'll take the bill? Gotcha. I'll get back to my work.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 105201,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Oh. Commander. Happy New Year, now give me a red envelope... is what everyone's been sayin'. Speakin' of, do you have one for me?",
	detail = "These girls are rackin' up a long, looooong tab... *sigh*...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[105202] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "",
	unlock = "Mmh... I reckon it'll be more excitin' if I show more skin... Commander? Great timing. Could you help me press the shutter?",
	touch2 = "Right now? Is this, like, a part of the shoot?",
	mission = "Commander, you've got unfinished missions. Let's save the rest of the shoot for after you come back.",
	vote = "",
	drop_descrip = "Mmh... I reckon it'll be more excitin' if I show more skin... Commander? Great timing. Could you help me press the shutter?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Snappin' pictures with you... It's a whole load of fun. More fun than anythin' else. Next time, and the time after that... um, take some more photos of me.",
	main = "You want me to get closer to the camera so I'm more exposed to the light? Alright. This spotlight sure is warm... I feel like ice cream in the sun...|Hmm... These clothes are so thin, but they completely \"swallow\" me... It's a pretty comfy fit. Could you help me lift this, Commander?|We ready to start yet, Commander? Oh, hang on, let me change my pose... Current one's fine, you say? Nah, I need to find a pose so good, it'll make you forget to press the shutter.",
	touch = "This is comin' along swimmingly. It's great havin' your help.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 105202,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, I just snapped these photos. Out of all the poses I picked, are there any that get you goin'?",
	detail = "Commander, come here. Directly show me what pose I should do next. Oh, you reckon this one makes my figure pop better? Alright. Just gotta figure out where to exert myself...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[106010] = {
	hp_warning = "",
	feeling3 = "The right answer is... BOO! Hahahahaah I Scared you! ... Ehhh... Commander, you suck at playing along...",
	mail = "Long Island used [Switcheroo] on Commander's mail! I am amazing!",
	expedition = "The girls who went out on commission aren't back yet~ Not yet~ ...Ah, they're back now!",
	win_mvp = "Hehehe~ Look at them! They don't even know what hit them!",
	home = "Com~man~der~ No one has returned yet~",
	unlock = "Hehe, I'm Long Island~ Hello, Commander. Actually, I have another name. Do you want to know?",
	touch2 = "Wh- what you touched isn't me! What you touched... is...a... a ghost!",
	mission = "Commander~ there's a new mission~ Once you are done~ let's sleep?",
	vote = "",
	drop_descrip = "Long Island-class escort carrier – Long Island, Hull Number CVE-1!",
	feeling4 = "Hehehe, Long Island the ghost has 'accidentally' possessed Commander, and cannot leave ever again~ Now Commander has no choice but to spend his every day life like this!",
	lose = "No... No way... Could they possibly have seen me?!",
	feeling1 = "Commander... He can't see me... He can't see me...",
	skill = "Phew... I almost flashed everyone...",
	upgrade = "Long Island's... EXP points... have been increased!",
	propose = "Contract established~! With this, Long Island has officially become the ghost possessing Commander~! ...But what I do will not change... Ehehe~",
	feeling5 = "That said, if I am really a ghost possessing Commander, I would have to be with you all the time. During meals, during naps, when going to the bathr... Wha! Too embarrassing!",
	main = "Russian roulette~ candy time~ Pick the one~ with wasabi inside~|Let's drink together, eh? Cheeers~ Bfft! So bitter... I ended up drinking what the Commander is supposed to drink!|Commander~ Do my sleeves~ look like those of a ghost~?",
	touch = "Commander, you dummy~! There's glue here~! ...Wh-What?! I'm stuck?! What do I do?!",
	voice_key_2 = -1,
	mission_complete = "Sneaky... sneaky... Apply glue to Commander's rewards...",
	battle = "Ehehe, let's party~ I'm gonna scare you to the point you're spilling fuel!",
	id = 106010,
	gift_dislike = "",
	gift_prefer = "Wow, I'm gonna use this to scare all the other girls!",
	profile = "Hehehe, I am Long Island. Eagle Union's first escort carrier~ Using cute little planes to protect merchant ships, as well as sea lanes... That is my job~",
	voice_key = 10601,
	headtouch = "",
	feeling2 = "*ears covered* Ghosts do not talk~~~",
	login = "Roooaar! ... Hehehe, were you shocked? I'm like a ghost that's going to haunt you every day!",
	detail = "Can't see me... can't see me... can't see me...",
	couple_encourage = {
		{
			{
				40809,
				20605,
				70202
			},
			1,
			"This ghost can pwn any of you in video games!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[106011] = {
	hp_warning = "",
	feeling3 = "Are you free, Commander? Wanna play a game then? We can make plastic models too if you want.",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Good work out there, Commander. Time to relax~ Here you go, you're now Player 2",
	unlock = "Everyone's favorite and talked-about Long Island, actually has another hidden secret...",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "Everyone's favorite and talked-about Long Island, actually has another hidden secret...",
	feeling4 = "Commander, my room is not a game store~ Oh, you just want to play with me? F...Fine! I just bought a newly launched title. Wanna play it together?",
	lose = "Ah, Long Island has become... Tired Island...",
	feeling1 = "Commander~ intruding into a person's room is against the law! I-I'm reporting you!",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "We need more co-op games, as well as tools... Eeeh, I don't wanna go outside~ Commander, for the sake of the future of the adorable Long Island~ Please buy this list up!",
	main = "Commander, don’t bother me, I’m really busy right now. Busy with what? Games! All of these stupid friggin backlogged games!|Commander, I brought a bunch of snacks~ Should I give you some?|Commander, do you like High Grade or Magical Grade stuff? I even got Powerful Grade stuff too!",
	touch = "",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Commander, can I just chill out back here?",
	id = 106011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "You found out my secret, Commander... Oh well! Please don't tell anyone else, ok?",
	login = "",
	detail = "That get up is the usual Long Island wearing her public face~ ... Want some potato chips?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[106013] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "It's easy to get burnt out when you do nothing but game streams... Oh, I know! Let's assemble a scale model instead next stream!",
	unlock = "\"Tune in everyone, Gamer Girl L.I. is about to begin her spooky Halloween special stream~\" ...Well, that should do it for my channel intro... Hmm, wonder how many viewers I'll get~",
	touch2 = "Y-you're gonna get me demonetized!",
	mission = "",
	vote = "",
	drop_descrip = "\"Tune in everyone, Gamer Girl L.I. is about to begin her spooky Halloween special stream~\" ...Well, that should do it for my channel intro... Hmm, wonder how many viewers I'll get~",
	feeling4 = "",
	lose = "Oh no, my viewership is going down!",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Hm? This message is from \"Prancing_dragon_warrior,\" who says: \"L.I., please impart more of your pro gamer knowledge to me!\" Uhh, sure, I guess. We can do a viewer co-op stream later.|Someone's at the door? Commandeeeer! Grab some of the snacks by the bed and give them to whoever's knocking~|If I can make this streaming thing pay then I'll be able to buy new games without it killing my wallet! You should give it a try too, Commander~",
	touch = "Tired after all that work, Commander? Here, have one of my cushions~",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 106013,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commandeeeer! Come help out with my streaming setup~ Hehehe, come on~ I'll give you all the snacks you can eat in return~",
	detail = "It being Halloween and me being a ghost, I went around trying to scare people, but it was too much work so I gave up and just went back to NEET it up in my room instead.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[106014] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Heehee... You've got as many letters as I've got phone calls asking to talk to you!",
	expedition = "",
	win_mvp = "",
	home = "Hm? You're here, Commander! Welcome back! ...What about the phone? It's fine, the caller is on hold!",
	unlock = "Ring-ring-ring... Hi, this is Long Island at the information desk speaking. What'd you say? Alright, sure. Don't worry, I'll relay aaall your feedback to the Commander. I'm going to hang up now. Buh-bye!",
	touch2 = "Heeey! I'm still on the clock, you know!",
	mission = "",
	vote = "拉票描述",
	drop_descrip = "Ring-ring-ring... Hi, this is Long Island at the information desk speaking. What'd you say? Alright, sure. Don't worry, I'll relay aaall your feedback to the Commander. I'm going to hang up now. Buh-bye!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Cooommaaandeeer! People say you look your coolest when you're working. Can you give your favorite ghost a little glimpse of that? Hah, just kidding! Let's play a game together once my shift is over!",
	main = "What things does a receptionist do, you ask? Uhh, copying things from one note to another, I guess? A ghost like me wouldn't really know!|Commandeeer! Need any help? No? That's good! Then if you've got nothing better to do, I could use a hand here!|Hello? ...You lost your sunglasses? Then call Akashi and order a new pair. Hello? ...You can't find the Commander anywhere? Probably got spirited away by a ghost, methinks. Heehee!",
	touch = "Had a change of mind? Do you feel like helping with these calls now?",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Can I have a gaming session in my bed as a treat?",
	battle = "",
	id = 106014,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Wooow, you'll get at me even when I have my hands full, huh?",
	feeling2 = "",
	login = "Oh geesh! Commandeeer! I need help with all these calls! ...What do you mean \"no\"?! They may be calling me, but it's YOU they want to speak to!",
	detail = "I just need to grit my teeth and bear through this... then I'll be able to afford that game's deluxe edition and figurine I've waited for!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[106015] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Commaaander! Got any red envelopes? If you don't... heheh, then I'll possess you and grope around until I find one!",
	unlock = "Heehee – may fortune come your way! Give me a red envelope! ...Hm? You've already given me one? Hey, the more red envelopes, the better! If you give me more, I'll let you have this steaming hot baozi as thanks!",
	touch2 = "S-so it's not just the baozi you want... You wanna eat me, too!",
	mission = "",
	vote = "",
	drop_descrip = "Heehee – may fortune come your way! Give me a red envelope! ...Hm? You've already given me one? Hey, the more red envelopes, the better! If you give me more, I'll let you have this steaming hot baozi as thanks!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Commander... do you want this baozi I took a chomp out of? Just kidding – let's share! There's still loads of tasty stuff to try, so go and buy me something. Please? Thanks!",
	main = "Red bean cake, potstickers and soup dumplings... There's yummy food wherever you look! This Dragon Empery night market is awesome!|Careful, or I'll fall? Hey, if I find myself in danger, I'll just fly over and take possession of you!|Once I get my red envelope, I'm gonna buy that new game... Commander, you've got to play it with me!",
	touch = "Commandeeer! Thanks for the red envelope. The baozi? Sorry, I already ate it! Heehee♪",
	voice_key_2 = -1,
	mission_complete = "I collected the mission rewards! My red envelope stack's growing and growing!",
	battle = "",
	id = 106015,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "The fireworks show by the market is about to start! Let's go give it a look-see, Commander!",
	detail = "This ghost prefers clinging to you over wandering around the busy night market below!",
	couple_encourage = {}
}


