_G.pg.base.ship_skin_words[106020] = {
	hp_warning = "",
	feeling3 = "You always give me the right ideas, Commander! As expected of a great coach! I, Bogue the pitcher, will follow you for life!",
	mail = "Commander, it's a mail! Which championship is it from?",
	expedition = "Curveball~! Oh crap I broke the window... Ah, Commander, the commission squad is back!",
	win_mvp = "Hmhmm~ As I thought, I am the best pitcher.",
	home = "Commander, you are a real veteran! That was a learning experience!",
	unlock = "*inhale*...HAA! Nice one... Oh, apologies. You're the Commander, I see. Fast pitcher, Bogue, here for duty!",
	touch2 = "Waah!! Commander, that's mean!",
	mission = "A new goal? I will not back down!",
	vote = "",
	drop_descrip = "Bogue-class escort carrier — Bogue, Hull Number CVE-9!",
	feeling4 = "Commander! I, Bogue, am requesting special training! The reason is, whenever I hear your voice, I lose my strength so I want to know how to prevent that... That's all!",
	lose = "Is this the end of the tournament...?",
	feeling1 = "Can you really make me stronger, Commander? ...I'm really worried...",
	skill = "Fly, my fastball!",
	upgrade = "My balls have become even faster!",
	propose = "...Now I understand! You noticed my feelings, Commander, and you want me to continue my journey without regrets! I, Bogue, am truly happy to have met you!",
	feeling5 = "Co-Commander. If I win in the next league, I- I'll tell you something important! S- So please wait for it! I will become stronger. Stronger than anyone!",
	main = "With this ball, I can sink a submarine!|Commander, can you polish the B-25s?|Boring... You look tired anyway, Commander, so let's go and sink some subs?",
	touch = "What's this? Training to resist against attacks?",
	voice_key_2 = -1,
	mission_complete = "It's satisfying to be rewarded for achieving the objective! Commander, check out the rewards!",
	battle = "Go, curveball!",
	id = 106020,
	gift_dislike = "",
	gift_prefer = "I was just running out of these, Commander! Thanks!",
	profile = "I am pro baseballer, Bogue! Yep, my greatest record is 12 strikeouts in a single match! I wish to sharpen my skills by your side, and become the shining star of the Major League!",
	voice_key = 10602,
	headtouch = "",
	feeling2 = "Someday, I hope to stand on the podium of the sea with your lead!",
	login = "The best pitchers are always training. Yep!",
	detail = "Please keep my stats in mind!",
	couple_encourage = {}
}


