_G.pg.base.ship_skin_words[106550] = {
	hp_warning = "Gah... This is starting to look impossible...",
	feeling3 = "I like movies and books. I adore stories with high and low points and emotionally touching scenes. As for my favorite genre, that would be... Umm, it's a secret!",
	mail = "I wonder if this message is from the Naval Headquarters... Commander, I think it'd be wise to check just in case.",
	expedition = "I've finished checking the resources from the commission. Please confirm.",
	win_mvp = "First place... me? Hmph. Fighting on the front lines might be easier than I expected.",
	home = "Welcome back, Commander. The combat report is... Wh-what book?! *cough* *cough*... It's nothing, forget you saw anything.",
	unlock = "Good morning to you. Escort carrier Casablanca, reporting in. I shall support the fleet to the best of my abilities, so you may rest assured.",
	touch2 = "Eek?! I... I've never read about stuff like this in my books before...!",
	mission = "You will surely be rewarded for your hard work. Please do your best, Commander!",
	vote = "",
	drop_descrip = "Casablanca-class escort carrier – Casablanca, Hull Number CVE-55.",
	feeling4 = "Oh, Ilsa... You poor thing, you can only choose one person... I wouldn't be able to do that... I am so happy that I don't have to face such a dilemma on m– C-Commander?! When did you get here?!",
	lose = "There's only so much I can do on the front lines as an escort carrier...",
	feeling1 = "So... you were the greatest obstacle to the development of the fleet...",
	skill = "I will do everything in my power to protect everyone!",
	upgrade = "Thank you very much, Commander!",
	propose = "Although love stories, with all their twists and turns, have a unique appeal, I personally would rather live a life of simple happiness. Do you think the same way, Commander? Then let us join in an embrace after you put the ring on my finger.",
	feeling5 = "Would you like to go watch a movie with me, Commander? My favorite kind, of course... A story of love and romance. Together with you...",
	main = "Commander, shall I help assess the state of the fleet's logistics? |Commander, where would you rather be, the thrilling, constantly-shifting front lines, or the humble, but critically important rear lines? |If possible, I'd like to hear about what happened at the Battle of Casablanca from Massachusetts.",
	touch = "Commander, what's the matter... Oh, is my necktie crooked?",
	voice_key_2 = -1,
	mission_complete = "Mission complete! All right, with these supplies, your fleet operations should be even smoother.",
	battle = "A head-on battle, huh... All right, leave the air support to me!",
	id = 106550,
	gift_dislike = "",
	gift_prefer = "Oh, I really like this! Thank you!",
	profile = "Back then, roughly fifty other Casablanca-class sisters entered service over the course of just over a year. Although most of us saw our missions come to an end shortly after the war, I will do my best to fulfill my duties to this fleet, whether as an escort, air support, or a transport. It's a pleasure to work with you, Commander.",
	voice_key = 10655,
	headtouch = "",
	feeling2 = "First Ameer, then Alazon Bay, and finally Casablanca. Isn't it nice when your name bodes good fortune? Hehe~",
	login = "Time is of the essence. Let us quickly begin the day's work.",
	detail = "Although fighting on the front lines is not my specialty, I'll give it my all if needed!",
	couple_encourage = {
		{
			{
				10601
			},
			1,
			"I am glad to have you by my side, Long Island!",
			0
		},
		{
			{
				80201
			},
			1,
			"A dash of flair is nice every now and then!",
			0
		},
		{
			{
				10704,
				20210
			},
			2,
			"When do you propose we host the next group reading?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[106551] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "The actual meet is coming up... I've got to practice even harder!",
	unlock = "Phew... Can't train hard if you don't stay hydrated! Oh, Commander, good day! Did you come to watch us practice?",
	touch2 = "Commander, you seem to be quite good at taking advantage of these situations...",
	mission = "",
	vote = "",
	drop_descrip = "Phew... Can't train hard if you don't stay hydrated! Oh, Commander, good day! Did you come to watch us practice?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Captain Reno, I think your enthusiasm is nothing but commendable, but wouldn't it be better to take a break now to conserve our energy? |Commander, I brought some water and sports drinks. Feel free to take whatever you want. |Even though this squad was thrown together last minute, thanks to the support of you and Craven, I don't want to lose to the other factions!",
	touch = "Is this towel for me? Ah, thank you very much, Commander.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 106551,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Cheerleaders raise the morale of the players. It doesn't seem much different from the role of an escort carrier, supporting those who are working hard on the battlefield.",
	detail = "Getting the choreography down isn't the hard part. It's being able to cheer so enthusiastically like Reno... It's a bit too embarrassing if you ask me...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107010] = {
	hp_warning = "",
	feeling3 = "You seem to be getting better at this- Eh? It's thanks to me? Ah, well... y-you're welcome...",
	mail = "Check your mail periodically. It's a good habit!",
	expedition = "The girls on the commission field trip have returned. Now, go and check their progress.",
	win_mvp = "Got it, everyone? Maintain this pace, alright?",
	home = "Commander, where are you heading? It's time for a reflection meeting",
	unlock = "I've been newly assigned to assist you. Name's Langley. You listening? I am going to fix what's wrong with you, and put you on the right track to running a fleet.",
	touch2 = "*phone call* Hello, is this the military police? Yes, it's the same place and the same person...",
	mission = "Erhmm... Have you finished your homework today?",
	vote = "",
	drop_descrip = "Langley-class aicraft carrier ー Langley, Hull Number CV-1!",
	feeling4 = "There's nothing more for me to teach you-- What? Teach you about myself? Y-You idiot!... Ugh",
	lose = "*sobs* ... I'm not qualified as a teacher... Maybe I should go back to transporting coal...",
	feeling1 = "I never thought that there would be a student I cannot teach... It seems better for me to quit...",
	skill = "Commander, pay close attention to my moves!",
	upgrade = "Even when you become stronger, never forget about why you had to in the first place.",
	propose = "I was concerned about whether Commander takes good care of himself before...so from now on, teacher Langley will also correct issues of your personal life; Don't even think about running away, Commander~",
	feeling5 = "I, Ms. Langley, do not mix personal and work lives! If you think that I'll give you special treatment just because of our relationship, you are sorely mistaken! ... B-but in private, I'm fine with that!",
	main = "Commander! ~Hey, you could've done better than this. Why are you not serious about this...?|At this rate nothing about the fleet will change! Get yourself together, Commander!|Commander? Are you listening? I'm gonna throw the chalk at you~! I hate people who don't listen to me! Hmph!",
	touch = "Please do not treat me like a child~! I am a teacher! TEA-CHER!",
	voice_key_2 = -1,
	mission_complete = "The reward for diligence has been delivered. Keep it up for next time!",
	battle = "This is the chance to show me what you learned. Do it properly!",
	id = 107010,
	gift_dislike = "",
	gift_prefer = "Is this for me? I... might be a little moved...",
	profile = "Ahem! I am the Eagle Union's first, I repeat, the first aircraft carrier, Langley! I do not think highly of my own fighting ability, but I've put out numerous outstanding pilots! The Eagle Union's aircraft carrier begins with me, I say!",
	voice_key = 10701,
	headtouch = "",
	feeling2 = "What are you doing, sleeping in the job?! Take you tutoring seriously!",
	login = "Commander, I'll assist you with your work the best I can!",
	detail = "Commander, you're staring at me... Are you ready to answer my questions?",
	couple_encourage = {}
}


