_G.pg.base.ship_skin_words[107020] = {
	hp_warning = "Maybe it's time to cheer everyone up with my song~",
	feeling3 = "Recently, whenever I dream about the Coral Sea, you are there, Commander. It somehow makes me feel safe. I wonder why~",
	mail = "A new mail has arrived. If your hands are full then perhaps I should reply it for you~",
	expedition = "Oh my~ The girls of the commission team have returned",
	win_mvp = "*giggles* Lady Lex is not really a title of mine~",
	home = "Oh, something's on your face. I'll wipe it off, so don't move~",
	unlock = "Good day, Mr. Commander~ I am Lexington. I heard that my name was from the first battlefield of the War for Independance. As an idol, I think I need to have a big heart. Don't you agree?",
	touch2 = "Oh goodness, are you unsatisfied with being the younger brother?",
	mission = "Oh Commander, there are still missions that have yet to be completed~",
	vote = "",
	drop_descrip = "Lexington-class aircraft carrier ー Lexington, Hull Number CV-2!",
	feeling4 = "Commander, wanna try becoming my manager? You're capable and you know me, and I can't think of you as anything short of dependable~",
	lose = "Oh my~ we can't keep up with their pace. Should we retreat for now?",
	feeling1 = "Oh dear, you are mistaken if you think I'm going to accept everything you do.",
	skill = "Go forth, carrier planes!",
	upgrade = "*giggles* I suddenly feel like singing. Wanna listen?",
	propose = "Oh, oh my oh my~ I was wondering how long I would have to wait for you, Commander~ *giggles* Well then, the private live show ticket has been sold out~ The show goes-- forever~",
	feeling5 = "A solo live show? Oh, I haven't had plans for that yet. But if someone were to give me a ring as a present, maybe I'll host that kind of show every day. And the audience is only a single person, you see~",
	main = "I'm not as lively as my younger sister, though I'm confident in my own charms. What do you think~|Oh my, where is Saratoga hiding? She's such a handful...|My eyes are gorgeous? Well, for an idol, my eyes have to look like this~",
	touch = "Commander, you seem like a hapless little brother~",
	voice_key_2 = -1,
	mission_complete = "Carrier planes, bring the mission rewards to the Commander",
	battle = "Everyone! Let's claim victory for our Commander!",
	id = 107020,
	gift_dislike = "",
	gift_prefer = "Oh my, is today a special day? Thank you. You've made me very happy!",
	profile = "Oh my~ I am aircraft carrier Lexington. \nI'm gentle? That's because I'm everyone's older sister~ That means you are a cute junior too! \nI feel assured since I've seen Saratoga working hard. Please give some attention to her as well",
	voice_key = 10702,
	headtouch = "",
	feeling2 = "Being an idol is a job that brings smiles to everyone. Of course, that includes you too, Commander. *giggles*",
	login = "Oh my~ Where are you heading, Commander? Don't worry. As long as I'm around, even the high flying crane won't get away",
	detail = "Aww, your frown has curled your brows. You have your share of hard work too, Commander...",
	couple_encourage = {
		{
			{
				10703
			},
			1,
			"Sara, don't be naughty!",
			0
		},
		{
			{
				10705
			},
			1,
			"Should we get some tea together when this is over?",
			0
		},
		{
			{
				10
			},
			5,
			"The Monkey Corps have arrived!",
			4
		}
	}
}


_G.pg.base.ship_skin_words[107021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Hehe, new outfits do bring new joys with them after all~",
	home = "A well-fought battle, Commander. Why don't you come try my Lexington-style East-West fusion cooking?",
	unlock = "Hehe… sometimes you can completely change the way people see you with just a simple change in attire. Don't you agree, Commander~? Don’t worry, I'm still your Lexington~",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "Hehe… sometimes you can completely change the way people see you with just a simple change in attire. Don't you agree, Commander~? Don’t worry, I'm still your Lexington~",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "In the Dragon Empery, the New Year symbolizes joy and reuniting with family. Commander, just being together with you and all the children in the port right now, counts as a \"family reunion,\" doesn't it? Hehe~",
	main = "An idol will change her outfits and dresses several times during a performance, each one bringing forth a different character... As long as I can bring smiles to everyone's faces, I will be happy. |nil|Wearing this outfit seems to have gotten the children all fired up~ Hehe, Commander, don't you think this outfit brings out my domestic side?",
	touch = "Commander, do you like my dress that much? Should we ask the Empery girls to tailor an outfit for you as well?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 107021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Welcome back, Commander. Are you well acquainted with the customs of the Dragon Empery? Then, why don't you tell me a bit about their New Year? I'm quite curious~",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107030] = {
	hp_warning = "Wah! I'm in a pinch!",
