	feeling1 = "Fakkyu! Fakkyufakkyu! Fakk! Yu!",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Commander, when I'm in this outfit, it feels as if I'm literally \"tied\" to you~! Sister Sara loves being tightly connected with you♡",
	main = "Since I don't usually get this opportunity, maybe I should try to record a song for an anime~♪ |A new opportunity? An idol only shines because of her courage! We can't be afraid to try new things! |Heh heh, the enemy's wide open! Pyoko Pyoko, go get 'em~!",
	touch = "Since I've finally become a virtual idol, maybe I should release some new songs~",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "I'll show you what a virtual idol is capable of!",
	id = 107033,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Uwah! Don't pull Pyoko Pyoko off my head~! Commander... you definitely can't treat the real Kizuna AI like this, got it? ",
	feeling2 = "",
	login = "Welcome back, Commander! I'm about to go watch Kizuna AI rehearse the lyrics for her next performance! It's a rare opportunity, so you should come along too!",
	detail = "A virtual idol has to make a good first impression... Long Island, show me some of those cool poses you're always talking about?",
	couple_encourage = {}
}


