_G.pg.base.ship_skin_words[107051] = {
	hp_warning = "Urk. I feel... a little sick...",
	feeling3 = "",
	mail = "You can't go off with someone else until you finish drinking with ME, Commander!",
	expedition = "You wanna sneak off to the harbor? Ugh, I TOLD you already, Commander, I'm *hic* not as think as you drunk I am!",
	win_mvp = "OOPSIE! What was that I just said in front of EVERYONE...?",
	home = "I'm not letting you leave until YOU have a drink with me, Commander.",
	unlock = "Hey, Commander, are you lost? How about a drink? ... Huh? Drunk? Me? Oh, Commander, you're such a card. This is just grape juice... isn't it?",
	touch2 = "OH! Commander, at least buy me a drink first!",
	mission = "Now now, Commander, I'll be mad at you if you ditch these assignments.",
	vote = "",
	drop_descrip = "Hey, Commander, are you lost? How about a drink? ... Huh? Drunk? Me? Oh, Commander, you're such a card. This is just grape juice... isn't it?",
	feeling4 = "",
	lose = "I, I have a feeling... like all the clout I had as a big sister is COMPLETELY GONE... after tonight...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I mean, it's only natural for a good couple to be a little clingy, right? After all I've been through, I'm WAY too shy to make the first move. So that means YOU have to do it. Got it?",
	main = "Enterprise is a good girl. So's Hornet. And Hammann. They all found their PLACE in this fleet. But me? The big sister? I'm HAPPY for them. And a teeeensy bit lonely.|You know, Commander, looking back, I have some regrets. Like if I knew you were THIS good? I'd've been more HONEST with myself.|Oh! Is that my cute little Hammann?! When did you get so BIG?! ...Oh, you're the Commander, aren't you? Have you seen Hammann?",
	touch = "Hey, Commander, you wanna hear some EMBARRASSING stories about Enterprise and Hornet? Oh, you'd rather hear mine? Hehe, THAT can be arranged.",
	voice_key_2 = -1,
	mission_complete = "Here's to a mission accomplished! CHEERS!",
	battle = "Uhhh, where am I?",
	id = 107051,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "You're late, Commander. You know what THAT means. One penalty drink!",
	detail = "Come to think of it, Enterprise did tell me not to drink the blue stuff like A MILLION TIMES. But like, what's the dig beal, Commander?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107052] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "What's the matter, my friend? I see, the commission team has returned? I'll let Hornet know.",
	win_mvp = "The purpose of my wings are to guide us towards peace––",
	home = "",
	unlock = "Across seven steps, in a tower atop a hill, you'll find the king's resting place... Hehe. Will you come with me to Utopia, Commander? I'm joking, of course, but I am very glad we could make this journey together.",
	touch2 = "Am I... good enough for you?",
	mission = "New mission notifications? Why don't you let Hood handle it?",
	vote = "",
	drop_descrip = "Across seven steps, in a tower atop a hill, you'll find the king's resting place... Hehe. Will you come with me to Utopia, Commander? I'm joking, of course, but I am very glad we could make this journey together.",
	feeling4 = "",
	lose = "Freedom... will never be extinguished...!",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "My true utopia... is the port that Enterprise and the others can call home. If there's ever a place that can bring me eternal peace... I'd think that it would be by your side, Commander.",
	main = "What kind of souvenir do you think Hammann would like? ...A warding stone...?|George is quite knowledgeable isn't she? Quite befitting of a Royal Knight, I'd say. Commander, why don't you tell me a bit about this place too?|I quite like it here. All the places we visit have quite a unique atmosphere, whether in Iris Libre or in the Eagle Union... Hehe.",
	touch = "",
	voice_key_2 = -1,
	mission_complete = "The mission rewards have arrived. I'm excited to see what we got.",
	battle = "For our ideals...!",
	id = 107052,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, how about taking a photo right here?",
	detail = "The cathedral, the Holy Well, and... Commander, where's the next spot again?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107058] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Commander, new mail has arrived. Shall we go through it together?",
	expedition = "The girls in the commission team have come back. Let's go greet... Ah, umm... M-maybe I shouldn't go in this outfit after all...?",
	win_mvp = "MVP? Hmm, I wonder what kind of reward I should ask for... Maybe I'll have the Commander pat me on the head as if I was a kid? Heehee~",
	home = "Shall we do a quick debriefing first? We can save the celebratory toast... for when the two of us have some alone time, okay?",
	unlock = "This wedding dress, brimming with light, flutters like a feather in the wind... I'm sure that I'm still in a long, deep, slumber... That's right, Commander. The two of us are surely sharing a blissful dream together, heehee.",
	touch2 = "Do you hear that throbbing? It's the sound of my heartbeat, intertwining with yours–",
	mission = "...Eagle? Mm, we have work, don't we? I need to strike while the iron is hot, before the Commander can get away~♪",
	vote = "",
	drop_descrip = "This wedding dress, brimming with light, flutters like a feather in the wind... I'm sure that I'm still in a long, deep, slumber... That's right, Commander. The two of us are surely sharing a blissful dream together, heehee.",
	feeling4 = "",
	lose = "Don't worry, I'll be fine. Commander, let's try to keep a clear head, okay?",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I, Yorktown, will always remain by your side. Through the moment when true peace finally arrives, through the bright and joyous days that follow after that, forever and ever...",
	main = "I've already prepared a drink for you, so just go ahead and lie down over there. I don't mind lending you my lap either should you need it~ Heehee.|Just as you saved me, Commander, I'm sure you'll also lead the other girls into the light. For your sake – for the person who I cherish so dearly, I wish to become your strength.|The wind seems to be picking up... Oh, Commander, shall we head back inside shortly? We'll have plenty of time to chat afterwards~ Heehee.",
	touch = "What do you think about the texture of my clothes? Smooth and soft? ...Ah, um... I think that's my skin you're feeling there, not my clothes... *blushes*...",
	voice_key_2 = -1,
	mission_complete = "What's wrong, Eagle? ...Hmm? The rewards are here? Heehee, I see~ It seems that you and Commander understand each other better now.",
	battle = "Please be careful, Commander.",
	id = 107058,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "I'm not sure I did anything to deserve this reward... Heehee, just kidding~",
	feeling2 = "",
	login = "Good day, Commander. For today's agenda... Umm, did you perhaps need a change of pace? Heehee. In that case, allow me to accompany you.",
	detail = "The sound of my pounding heart seems to be riding the breeze of happiness across this lake, all the way until it reaches your ears... No, what I should be saying is, I want you to hear it, Commander. Can you feel... my love for you?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107060] = {
	hp_warning = "Interesting...!",
	feeling3 = "All the lights in the sky are stars, just as all the lights on the seas are enemies... Commander, will there be a day where there's no more fighting?",
