_G.pg.base.ship_skin_words[107062] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "There's no harm in taking a little break before the next battle, Commander.",
	unlock = "So this is the traditional attire of the Dragon Empery? Hmm... it fits quite well. Oh? Custom-made bow and arrows… Interesting, let's see how far these arrows can fly.",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "So this is the traditional attire of the Dragon Empery? Hmm... it fits quite well. Oh? Custom-made bow and arrows… Interesting, let's see how far these arrows can fly.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "My flight deck is also decorated with a theme from the Dragon Empery. Its colors represent joy and happiness. Not bad, huh. |According to legend, a mythical beast called the \"Nian\" comes out during the Lunar New Year. It can be warded off by setting off a lot of firecrackers. |I heard that it's customary in the Dragon Empery to hand out \"red envelopes\" during the New Year. Should I prepare some for the Union girls?",
	touch = "Commander, it seems that this coat is big enough to accommodate two people. It's super warm - want to see for yourself?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 107062,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Lanterns... should be hung up like this, right? Ah, Commander, you're here. I heard that they hang lanterns up to celebrate Lunar New Year in the Dragon Empery, so I gave it a try... You think it's fine? Festive, isn't it?",
	detail = "Being able to enjoy this peaceful, festive holiday atmosphere is only possible because of everyone's continued hard work... Right, Commander?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107063] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Commander, there's an incoming message from fleet command. ",
	expedition = "",
	win_mvp = "For the sake of freedom and the Azur Lane, I'll keep on winning!",
	home = "Good work out there! Go ahead and take a break while the others are being inspected.",
	unlock = "Happy Anniversary! Commander, celebrate to your heart's content today! I'll be praying for our continued victories!",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "Happy Anniversary! Commander, celebrate to your heart's content today! I'll be praying for our continued victories!",
	feeling4 = "",
	lose = "Sometimes there really is a no-win scenario... ",
	feeling1 = "Maybe I should just hit the road and never look back... ",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Would you like to come with me, Commander? We can go anywhere in the world. Think of all the new people and cultures we could discover together on our trek!",
	main = "Commander? Recently... I've been thinking about how it would feel to be able to soar through the skies and stars... but that's not really possible. Sorry for making you listen to my idle thoughts. |Vacation, huh... To be honest, I've been deployed in so many places during my lengthy service that sometimes even vacations feel like yet another mission... |Recently, Essex has picked up biking as well. It'd be great to go out with everyone else next time.",
	touch = "Would you also like to see my trusty steed?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Enterprise, engage!",
	id = 107063,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Ah, you're here. I'm ready to go whenever you are. Oh, can't be forgetting my helmet!",
	detail = "Commander, are you doing well? Live long and prosper!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107064] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Would you like to greet the commission fleet? It's a good idea to get some exercise. Otherwise, Hornet's going to make fun of you.",
	win_mvp = "Our slight advantage seems to have given us the victory here.",
	home = "Commander, thank you for your hard work. Let's get ready for the next operation.",
	unlock = "There is no doubt in my mind that I was born to fight. For the azure lanes of liberty, Enterprise, engaging!",
