	voice_key_2 = -1,
	mission_complete = "",
	battle = "Enterprise, sallying forth! Let us crush our enemies!",
	id = 107064,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Good day, Commander. There's still some time until the strategy meeting, so you should rest up while you still have the opportunity to.",
	detail = "I do not believe that it is correct to wantonly resort to violence, even in the name of justice.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107065] = {
	hp_warning = "",
	feeling3 = "",
