}


_G.pg.base.ship_skin_words[107080] = {
	hp_warning = "",
	feeling3 = "Someone saw a ghost on the roof last night? Hahaha, that was probably me practicing outdoors~ It’s very comfortable at night, no one bothers you, and you’re surrounded by stars. Commander, you want to come try?",
	mail = "Commander, did you get the letter I just shot to you from outside?",
	expedition = "The commission fleet has returned, that’s good to hear. I also want to head out... Co-man-der~",
	win_mvp = "Hehe, I am very good, right?",
	home = "Commander, what do you think, the outdoors is more comfortable, right?",
	unlock = "Hmm? So you are the so-called Commander? Ok... if there is enough room in your fleet, then is it alright for me join you~",
	touch2 = "Commander, say the word, where do you NOT want to get shot at? I’ll try to avoid it~",
	mission = "Commander, we have a new mission. You can give me an errand or a target. But please no paperwork~",
	vote = "",
	drop_descrip = "Wasp class aircraft carrier- Wasp, hull number CV-7.",
	feeling4 = "Commander, let me teach you archery. At night, we can practice together. If you get tired, then we can stargaze. How does that sound?",
	lose = "Umm... it seems that today’s status is not very good...",
	feeling1 = "If you don’t want to get shot by me, then just stay away...",
	skill = "Who said a wasp can only sting once?",
	upgrade = "Oh, my physical strength has grown stronger, it's time to customize my bow.",
	propose = "Is this your answer, Commander? … hehehe, I am so very happy! Then—— “I am willing to give everything to you, my dearest Commander”—— Wow, I’m so shy,  i-isn’t this awkward?",
	feeling5 = "Archery, combat techniques, and… that sea of stars night, this is all I have. Commander, are you willing to accept me as who I am?",
	main = "Commander, where are you looking at, I am above you. Hahaha, indoor climbing is quite interesting~ | It’s said that the archers of Sakura Empire is totally different from mine. So I really want to see it. | Commander, if there’s nothing I can help with then I’ll go out and exercise?",
	touch = "Zipper? Hehe, please don’t mind me. This is just more convenient for me to move around~",
	voice_key_2 = -1,
	mission_complete = "Commander, come over here and take your rewards from the mission~ It’s too heavy for me to shoot it at you...",
	battle = "Let me give you a taste of my Wasp battle style!",
	id = 107080,
	gift_dislike = "",
	gift_prefer = "Thanks. I'd be happier if you came on an outing with me instead of getting me a present, though.",
	profile = "I am Wasp class carrier, Wasp~! The first thing I did was go on missions in the Atlantic, and I also supported the Royal Navy. Later on, when in the thick of things in the Pacific theater, I was sent to support my Yorktown sisters. But in the end, I didn’t help quite as much. After all, I was most afraid of torpedoes...",
	voice_key = 10708,
	headtouch = "",
	feeling2 = "I like natural but in actuality use a compound bow? Commander, you are stereotyping, this is called going with the times! And the use of a compound bow actually has a long history to it. You can listen to me tell you it all, in ancient times...",
	login = "Commander, remember to knock before you open the door next time. Otherwise, I can’t guarantee that I won’t accidentally shoot you...",
	detail = "Limbs... cams... stabilisers... hmm? Commander, do you require something? I'm quite busy with the inspection, so do as you like~",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107090] = {
	hp_warning = "The battle... has just started!",
	feeling3 = "Jealousy? No, that's not the case. Enterprise is a true hero worthy of all the respect she gets. However, compared to her dazzling aura, I'm just...",
	mail = "There's new mail for you. Here you go.",
	expedition = "The birth of the Essex-class would not have been possible without the hard work of the logistics teams. I have to show my gratitude to everyone.",
	win_mvp = "Enterprise, did you see my feat?",
	home = "The fleet has safely returned. Commander, I've prepared the battle report for you. Time is of the essence, so please review it right away.",
	unlock = "So this is where Enterprise is... A-ahem! I am Essex, one of the Union's state-of-the-art aircraft carriers. Commander, you can expect great things from me! I swear that I won't disappoint you!",
	touch2 = "Wh-what is this?! I, I...",
	mission = "There are still unfinished missions? Mind letting me handle things this time...?",
	vote = "",
	drop_descrip = "Essex-class aircraft carrier – Essex, Hull Number CV-9.",
	feeling4 = "I won't lose to anyone, not even to Enterprise. But how do I get everyone to acknowledge this? Commander, if you were in my shoes, what would you do?",
	lose = "I won't let it end like this... I swear it!",
	feeling1 = "I wonder how Enterprise puts up with someone like you...",
	skill = "Spread your wings and soar!",
	upgrade = "When will I be able to get jets...",
	propose = "Once you've experienced the happiness of two people supporting each other, it becomes something you can't live without. Thank you, Commander. I no longer have to walk alone in my quest to prove my worth. I promise to always be at your side, wherever you go.",
	feeling5 = "I might never be able to become a hero like Enterprise... But when I'm with you, I feel like I can do so much more than just that...",
	main = "Everyone knows that the Essex class is strong, but still, Enterprise is all they ever talk about... *sigh*... |There are a lot of ships in my class. As the nameship, I have to do everything I can to be a good role model... |Musashi and Yamato? They were... yes, formidable rivals worthy of respect. I hope I can meet them again one day.",
	touch = "Time to sortie?! Just leave it to me! Oh... you just wanted to chat...?",
	voice_key_2 = -1,
	mission_complete = "The mission rewards have arrived. Are you sure you don't need me to go get it?",
	battle = "All carrier-based aircraft in position, anti-air defense preparations complete. All forces, full speed ahead!",
	id = 107090,
	gift_dislike = "",
	gift_prefer = "You're giving this to me? (whispers) ...How did the Commander learn about my tastes? A-ahem. I didn't say anything. Thank you.",
	profile = "I am the nameship of the Essex-class carriers. Although I was built with great expectations, I was always overshadowed by Enterprise's success. If only I could have been deployed sooner...",
	voice_key = 10709,
	headtouch = "Mm... Nnh... Ah! I-I'm not moaning, I swear!",
	feeling2 = "I witnessed the end of the era of battleships with my own eyes. Will carriers share the same fate some day...?",
	login = "There you are. I've already finished preparing everything. Commander, give us your orders!",
	detail = "What would you like to know, Commander? I'll answer to the best of my abilities.",
	couple_encourage = {
		{
			{
				10706
			},
			1,
			"Just you watch, Enterprise! I won't lose to you so easily!",
			0
		},
		{
			{
				7
			},
			3,
			"The era of carriers is upon us!",
			1
		}
	}
}


_G.pg.base.ship_skin_words[107091] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Did you want to rest for a bit? That's fine, take your time.",
	unlock = "I'm not trying to go anywhere in particular; I just want to enjoy the scenery along the way. Commander, let's go experience the thrills of the road together.",
	touch2 = "Commander, could you be... too tired to know what you're doing? I knew we should have stopped to rest...",
	mission = "",
	vote = "",
	drop_descrip = "I'm not trying to go anywhere in particular; I just want to enjoy the scenery along the way. Commander, let's go experience the thrills of the road together.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Enterprise advised me to pursue some hobbies that aren't related to combat... This should count as one of those. |Combat is something that must be done at full throttle. It'd be dangerous to do that while riding though... |You followed us the entire way? What an incredible eagle!",
	touch = "Phew... Hm? This bottle of water is for me? Thank you very much! I'll help myself then.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 107091,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, have you put on your helmet yet? We're about to get going!",
	detail = "Even being able to see a small portion of these 2448 miles has been an eye-opening experience. Though I wasn't able to ride from sea to shining sea, what an unforgettable journey it's been!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107092] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Wh-why is a commission fleet coming back now of all times? ...Commander, I'll— *hic*...! I don't think I should go like this after all...",
	win_mvp = "",
	home = "Everyone was greeting me one after another at the party, and there I was basking in their attention, so... I started toasting everyone, and... Ugh! Why am I so childish...?!",
	unlock = "Commander?! Ah, um, no, I'm not drunk! ...I, uh, just had a bit too much to drink... just a bit! Please don't tell the others though!",
	touch2 = "Commander! Jeez, what are you doing... Did you also have a bit too much to drink? What am I going to do...",
	mission = "We've got new work? Um, I really hope my head clears up soon... Ugh, everything's still spinning...",
	vote = "",
	drop_descrip = "Commander?! Ah, um, no, I'm not drunk! ...I, uh, just had a bit too much to drink... just a bit! Please don't tell the others though!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "The princess and the prince snuggled up to one another and sailed into the sea of stars above the castle~ ...Did you hear that?! Ah, forget it... Just write it off as me being drunk... and let me cling to you already! Hehe, ehehehe...",
	main = "I even got Mr. Eagle here all decked out~ Looks pretty sharp and spiffy, right?|Hey... Commander, um... Yeah, so... have you ever seen Enterprise get drunk before? Ah, no, I was just asking out of curiosity... I mean, it's almost impossible to picture that happening to her, right?|Commander, don't worry about me. Don't you think you should head back to the venue before the others start to wonder where you went?",
	touch = "One more cup... Just one more! Commander, here! Cheers! Thanks for everything you're always doing for us. This is... a token of gratitude from me... *hic*!",
	voice_key_2 = -1,
	mission_complete = "Did the mission rewards already get here? Th-thank god...",
	battle = "",
	id = 107092,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Sorry, Commander, but could you give me a hand? ...Ugh, why is the hem of this dress so long...",
	detail = "By the way, Commander, there's nobody else around, right? *sigh*... Thank god... If Enterprise or Shangri-La saw me like this, I'd die of— ...Eh?! Shangri-La?! Wait, no, stop! Please, no photossssss!!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107093] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The longer the transport distance, the greater the logistical difficulty. I must extend my gratitude to everyone who works so hard to maintain our supply lines.",
	win_mvp = "How'd you like that! Commander, Enterprise, see that?",
	home = "",
	unlock = "The Dragon Empery's attire and tools of calligraphy... I see, just wearing this outfit makes me feel more scholarly and artistic! I shall put forth my best effort to prepare for the port's Spring Festival!",
	touch2 = "Am I supposed to add another stroke here? ...Eek?! Commander?!",
	mission = "",
	vote = "",
	drop_descrip = "The Dragon Empery's attire and tools of calligraphy... I see, just wearing this outfit makes me feel more scholarly and artistic! I shall put forth my best effort to prepare for the port's Spring Festival!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "This is a special technique to maneuver the flight deck... Fantastic! At this rate, I'll catch up to Enterprise in no time!|What are those girls doing... Eh? Is that how big brushes normally are?!|Intrepid, see that star right there? That's Mercury, but the Dragon Empery used to call it the \"Chenxing.\" Heheh~",
	touch = "Am I supposed to add another stroke here? I understand. Um... right... here?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Attack squadron, ready to scramble! Just like an eagle soaring through the sky!",
	id = 107093,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Happy Lunar New Year! I'll be waiting for your orders!",
	detail = "One, don't be blinded by the pursuit of perfection; two, seek harmony in the spacing between ink and paper... Hmm... Does this look right? No, there's something off still... Man, this is hard...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107094] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission team is back! Jamaica, sorry, but I'm going to borrow your bike for a sec! I need to greet– err, talk to the eyewitnesses!",
	win_mvp = "\"Don't assume someone's literally irrelevant just because of how they really look\" ...So that's what it means!",
	home = "Don't let your guard down when toasting in celebration. Remember your limits, and act accordingly...",
	unlock = "My eagle has gone missing... Just as Enterprise said, there's something strange going on in this port–– Wait, I definitely smell a case in the making! Commander, let's get to the bottom of this together!",
	touch2 = "Y-you're trying to pass down the WHAT...?",
	mission = "It's a great day for an investigation, Commander!",
	vote = "",
	drop_descrip = "My eagle has gone missing... Just as Enterprise said, there's something strange going on in this port–– Wait, I definitely smell a case in the making! Commander, let's get to the bottom of this together!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "This piece of evidence is... the drink Enterprise left behind? And there's... a lemon here too? Oh, uhh, forget I said anything!|This piece of evidence is... the witness's photograph, but I have to glue it back together – speaking of which, where'd the glue go?|This piece of evidence is... The Manjuus that interrogated Cheshire seemed to mention something about an organization called the \"Republic of Essex\"... How strange, I'll have to look into this the next time I catch her.|This piece of evidence is... Wait, isn't this Bunker Hill?! Why were you so fired up to get a shot like THIS?|Let's go over the evidence we have... What?! You already managed to get conclusive proof? I knew I could count on you, Commander!",
	touch = "Let's let Shangri-La analyze the photographs. We're more cut out for field work!",
	voice_key_2 = -1,
	mission_complete = "I just picked up the mission rewards. What the heck is up with this Matryoshka doll...? Pfft, ahaha, what a weird face~♪",
	battle = "Open up! Detective-Carrier Essex is on the case!",
	id = 107094,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I hope my eagle didn't get eaten... But now's not the time to worry about that. Gotta focus on the investigation first!",
	detail = "\"I am Detective-Carrier Essex, unraveller of mysteries, revealer of truths!\" ...Alright, that's a good-enough catchphrase... Gotta look cool in front of Intrepid and all.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107095] = {
	hp_warning = "",
	feeling3 = "",
	mail = "The new mail? Where did I leave it, again...?",
	expedition = "Shangri-La, please, put that down! Huh? You're just using it to let me know the commission team is back...?",
	win_mvp = "I'm better at fighting than I am at office work!",
	home = "Commander! Welcome baaack~",
	unlock = "\"Anchors aweigh! Arr, pirate aircraft carrier Essex be ready for battle! Nothing in the seven seas will escape my grasp!\" Hic... Hehehe... I wanna be a piraaate...",
	touch2 = "Hey, Commander?!",
	mission = "New missions... That means there's more office work to go with them... Ack!",
	vote = "",
	drop_descrip = "\"Anchors aweigh! Arr, pirate aircraft carrier Essex be ready for battle! Nothing in the seven seas will escape my grasp!\" Hic... Hehehe... I wanna be a piraaate...",
	feeling4 = "",
	lose = "Just imagining all the paperwork that's going to come from this defeat... Uuurgh!",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "You've got it rough, Commander... If I was gonna be stuck doing this every day, I'd run away and become a pirate... I'm kidding! If it means reducing your burden, I can handle it! Heheh.",
	main = "Mmm, the acidity of lemon works just right. I feel great! Now, let me get Enterprise to... Ah. You heard nothing!|Endless office work... So this is your everyday struggle, Commander. I underestimated you...!|Did you see that?! I, aircraft carrier Essex, have obtained the greatest treasure of all! I've overcome my elders—Shangri-La?! Hold it, hold it, hold it! I'll apologize! I'm sorry, I'm sorry!",
	touch = "Commander, wanna ride my ship? Huh? That'd make you the captain, wouldn't it? Then I'd be...?",
	voice_key_2 = -1,
	mission_complete = "Mission rewards... Now this is what I need to motivate myself to work!",
	battle = "Eagle Union's own Tempesta... Ack, that's not what I meant!",
	id = 107095,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commandeeer? Pssh, no, I'm not drunk! I just had two, MAYBE three beers during my break~",
	detail = "Uuurgh, my head hurts... I feel like I did something crazy yesterday... Do you have any idea, Commander?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107096] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Ty brought us this new letter. Are you going to read it?",
	expedition = "I'm sweaty all of a sudden... Oh, the commission team is back? Okay! Let's give them a warm welcome after the race is over!",
	win_mvp = "I managed to keep the lead by some miracle... Next!",
	home = "Excellent work! Shall we go to the pit after a quick break? Everyone from the R&D department is there.",
	unlock = "Cooldown lap completed! Did you see me on the racetrack, Commander? Heehee. Thanks for everything, from setting up the race to assigning racers and supporters!",
	touch2 = "Wh-whoa! Uhh...",
	mission = "New missions! Is there any way I can help with them? I've got time while my bike is being worked on!",
	vote = "",
	drop_descrip = "Cooldown lap completed! Did you see me on the racetrack, Commander? Heehee. Thanks for everything, from setting up the race to assigning racers and supporters!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Enterprise is rooting for me?! From where? It's really motivating, but at the same time, I feel a ton of pressure on me now...|I won't go easy on someone just because they're a friend! I'm going for the gold in my next race!|You don't want me drinking too much during the victory party? Of course I won't! ...(Weird. Why am I the only one being told that?)",
	touch = "Can't this get a little lower? Damn... Hm? Commander?! Oh, I was just... I didn't mean it the way you think!",
	voice_key_2 = -1,
	mission_complete = "Mission rewards have arrived! Maybe there are some replacement parts in there?",
	battle = "Essex, taking off!",
	id = 107096,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Everyone performed great on the track today. Maybe it was because you were watching, Commander? Ahahahah.",
	detail = "It's so hot... Just like the heated support from everyone. However, I must remain sharp at all times during a race. Heehee, then again, I've fought many battles before, so this is nothing I can't handle.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107097] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "This victory is thanks to all of our combined efforts, Commander!",
	home = "Wow... Another new record! Great work, Commander! Do you need a bottle of water?",
	unlock = "Don't worry, Commander. I'm making sure your ride is squeaky clean before the race! Check it out – I bet your car is the most dazzling one on the track now.",
	touch2 = "Commander?! You'll get your racing suit wet!",
	mission = "",
	vote = "",
	drop_descrip = "Don't worry, Commander. I'm making sure your ride is squeaky clean before the race! Check it out – I bet your car is the most dazzling one on the track now.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Do you feel this raw energy between us? I think we might just be the perfect duo! But, umm... It's kind of hot, isn't it? Should we go cool off in the shower together?",
	main = "Whoa, the hood is HOT! Commander, can you turn on the water for me? I need to cool this baby down!|I'll do everything I can for your victory! As your partner, I promise I'll be with you 'til the end!|Boy, it's hot... Hey, do you think it's okay if I cool down using the hose? Whoa?! H-hey, that's too much water pressure!",
	touch = "The race is about to start! Hurry and get in, Commander!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 107097,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commandeeer! I'm over here! Me and your car are both ready and raring to go!",
	detail = "It's almost time for the race... Are you nervous at all? I could rinse your car again... It might make things cooler inside.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107099] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The team that went on a commission should be back soon. I'll head out early to receive them. In the meantime, Commander, you should come up with some words of gratitude for them!",
	win_mvp = "This is par for the course, really!",
	home = "Well done out there. Now, the report should... Oh, you already finished it? Well, in that case... I'll proofread it to make sure there are no mistakes!",
	unlock = "Essex's retrofitting has finished! Now Enterprise will be– No, YOU will be 120% satisfied with me, Commander! Anyway, I, Essex-class aircraft carrier Essex, am at your command!",
	touch2 = "M-me?! Well, um... if it's me you want, then very well...",
	mission = "A new mission... Understood! Allow me to take care of it!",
	vote = "",
	drop_descrip = "Essex's retrofitting has finished! Now Enterprise will be– No, YOU will be 120% satisfied with me, Commander! Anyway, I, Essex-class aircraft carrier Essex, am at your command!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I must go above and beyond what's expected of me now that I have this new strength. I need to set an example for others, catch up to Enterprise, and above all else, make myself worth your trust and love, Commander. Gosh, it's unbelievably embarrassing to say it out loud like that...",
	main = "It's just as you said, Commander. It's fine to want acknowledgment from someone, but fighting for said acknowledgment is dangerous.|I'm planning on doing some optional drills in the exercise area on our next holiday. Would you like to come with me, Commander? Oh, um, not to do the drills with me, but rather to guide me – that's what I meant.|While it's true that I have grown, I can't let it get to my head. There's no such thing as a perfect person, and I still have to keep learning from my peers. Hm? You think you could learn to be as modest as me? No, no, I'm afraid I have nothing to teach you, Commander.",
	touch = "Never hesitate to rely on me, Commander!",
	voice_key_2 = -1,
	mission_complete = "Mission rewards have arrived. I'll go ahead and sort them so you'll have an easier time reviewing them.",
	battle = "",
	id = 107099,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I'm ready for anything! Be it a sortie, clerical work, patrolling the area, or even drafting an operation, just give me the word!",
	detail = "Would you care to join me for lunch, Commander? Ah, um, I'm not particularly hungry, it's just that this is the time you usually eat at, so... Huh? You were actually going to take me out to lunch, too?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107100] = {
	hp_warning = "I can't let something like this keep me down!",
	feeling3 = "Um, ahem... Oh, no, I'm in perfectly fine physical shape. I'm just not sure how I should act around you now that I'm in this form... I'm really alright.",
	mail = "This is... a delivery from Hornet? I see. That means it's your mail.",
	expedition = "The commission team has returned safe and sound. It's not good to keep them waiting, okay?",
	win_mvp = "Oh– Sorry, I wasn't watching my step... Thank you, Commander. I'll consider your embrace just now as reward for my MVP.",
	home = "Let us raise a glass to our Commander's triumphant return. Don't worry, it's just one glass. I'm glad you're worrying for my sake, but... Hehe, don't you think you're taking after Enterprise?",
	unlock = "The second ship of the Essex class, \"The Fighting Lady\" Yorktown, has returned to your side. Even the darkest night must always give way to the resplendent dawn of happiness. Commander, let us step into the future together!",
	touch2 = "The mark you've carved into me will always be here.",
	mission = "My, what's wrong, little eagle? I see, the mission has been completed... I will let the Commander know.",
	vote = "",
	drop_descrip = "Essex-class aircraft carrier – Yorktown II, Hull Number CV-10.",
	feeling4 = "It's not just you, but also Enterprise, Hornet, and Hammann. They're all looking after me as well. Commander, you're the one who has made my blissful life at this port possible, and the person I dedicate my entire life to.",
	lose = "The dawn that the Commander brought us... must not be lost here!",
	feeling1 = "This must be a trial... to see if I am able to stand on my own legs... That must be it, right?",
	skill = "With this power, I'll open a path to the future!",
	upgrade = "Strengthening complete. I'm becoming more and more used to this power.",
	propose = "I swear upon the freedom and peace borne within the name of Yorktown, upon the life of happiness that I so desire, and upon my pure love... That the warmth of my lips now belongs to you–",
	feeling5 = "As the light of the dawn of happiness, what should I do for the Commander who reached out to take my hand? Heehee, we'll live happily ever after, right? I understand now – that is how we can share this joy with everyone.",
	main = "Hammann? You look totally different... Oh, now that I think about it, I wonder if I've changed as well... Hmm...|I appreciate your concern, I truly do. But, I also don't understand why you're paying so much attention to me alone. Your time is valuable, Commander, so please make sure to look after our friends as well.|I see, so this is how you use this rigging... Thank you, Essex. We're all a part of the same class now, so there's no need for so much deference.|Lexington, when's your next performance? I'll bring Enterprise and Hornet along to cheer for you~|Just as how we are not here only to fight, Commander, you are not here only to work. If you're not making progress, take a break and come back refreshed later.",
	touch = "Enterprise, I hope you're doing alright...",
	voice_key_2 = -1,
	mission_complete = "Thank you, little eagle, I see that the mission rewards have arrived. Oh, I can't actually understand what it's saying, but I do get the gist of it~",
	battle = "For freedom and victory!",
	id = 107100,
	gift_dislike = "",
	gift_prefer = "Thank you, Commander. You've made me so happy.",
	profile = "I am the resurrected Fighting Lady, Essex-class aircraft carrier, Yorktown. ...Heehee, I'm actually still the same Yorktown you've always known. To allow me to fight alongside my friends in this new form, you're just as amazing as ever, Commander. Hehehe.",
	voice_key = 10710,
	headtouch = "Maybe I should try getting you to pamper me like a little child~?",
	feeling2 = "Commander, you showed me the light of dawn and offered me salvation. I've long stopped seeing our relationship as one between superior and subordinate... Instead, you're more like... Um, oh my, this is rather embarrassing...",
	login = "Good day, Commander. What's first on the agenda today? Don't worry, all of us have your back.",
	detail = "Though diplomacy may be a show of etiquette before the war, it also is the only way to put an end to war. I'm sure that means you'll have your work cut out for you though...",
	couple_encourage = {
		{
			{
				10706
