_G.pg.base.ship_skin_words[107102] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Commander, new mail just came in. Ah... Everyone might be surprised if they see me picking it up in this outfit...",
	expedition = "The commission team is here. Why don't you go see them first? I'll have the perfect drink waiting when you get back.",
	win_mvp = "",
	home = "Welcome back, Commandeeer~ Hehe, could you get that cup there? It's a cocktail for you. Drink it – I think you'll like it!",
	unlock = "I just had a little aperitif... How am I already so drunk? C-Commander, wait a second. I'll make you a cocktaaail... Where'd I put that shaker?",
	touch2 = "Oh, Commander... You're so greedy... *blush*",
	mission = "How about you work on your leftover missions while I search for that darn shaker?",
	vote = "",
	drop_descrip = "I just had a little aperitif... How am I already so drunk? C-Commander, wait a second. I'll make you a cocktaaail... Where'd I put that shaker?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I was originally just trying to get your attention, but before I knew it, I was already in your arms... Next time I make you a cocktail, I won't let you taste-test it. Hehe... Who knew that being bold could work out so well?",
	main = "Hmm... Not over there, not over here... Where in the world did I put that shaker?|Does this getup make me look a little too bold? As long as you like it... I-I'm fine with that...|Shaking drinks takes a certain level of skill. Hehe, don't worry. I might not look it, but I'm very capable!|I heard that adding lemon juice can enhance the mouthfeel of a cocktail. I'll try... Eep?! Commander, are you okay?!",
	touch = "Geez, now isn't the time to tease~",
	voice_key_2 = -1,
	mission_complete = "Wanna celebrate another mission well done? Then I'd better make some more cocktails!",
	battle = "",
	id = 107102,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, about that special cocktail... Do you have any requests? Or would you prefer... a surprise flavor?",
	detail = "You look like you've got something to say, Commander... What is it? Or is my cocktail just so delicious that you want seconds? Heehee!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107103] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Mail for you, Commander. Take it.",
	expedition = "Everyone from the supply commission just returned. Go say hi to them. You don't wanna focus on me all day, do you?♪",
	win_mvp = "",
	home = "You want to share the joy of victory with me? I'd love to! I'll grab some champagne right away.",
	unlock = "Welcome to my... no, YOUR own bar, Commander. Relax a little and enjoy exclusive service courtesy of yours truly. Umm... Okay, what now?",
	touch2 = "C-Commander... Is this the kind of hospitality you expected?",
	mission = "Commander, your quota today is... Ahem. I mean, you have unfinished missions.",
	vote = "",
	drop_descrip = "Welcome to my... no, YOUR own bar, Commander. Relax a little and enjoy exclusive service courtesy of yours truly. Umm... Okay, what now?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Are you enjoying tonight's service...? It was meant to be just a temporary role, but part of me wishes this night would go on forever. Something about taking care of you just makes my heart race...",
	main = "I'm still not used to waitressing, but seeing that surprised look on your face made it all worthwhile!|If you see any room for improvement in my service, don't hesitate to say so. Consider it making me a better Yorktown.|How do I like waitressing? Hmm... Well, I do enjoy being able to gaze at you more.|Hmm... I thought I was the one serving you, so why does it feel like I'm being taken care of?",
	touch = "What is it? Wanna share some gossip?",
	voice_key_2 = -1,
	mission_complete = "There you go! Quotas are all met. Now, Commander, what reward would you like?",
	battle = "",
	id = 107103,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Good day, Commander... Ah. I guess I should say \"welcome in\" right now, shouldn't I? Heehee.",
	detail = "This is my first time letting you see this outfit... Heehee, that look on your face is adorable~ I'm glad it came in handy!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107110] = {
	hp_warning = "Crap, I didn't think there'd be so many of them...",
	feeling3 = "Oh, Commander! This– yeowwwch! Who decided it was a good idea to leave a trolley here?! Jeez, why does this always happen to me...Ah, um, nevermind, I'm fine! More importantly, when do I get to sortie?",
	mail = "There's new mail... do we have new orders?",
	expedition = "Commission completed, resources received~! Hehe, way to go, Commander. You know exactly how important logistics are to our fleet operations! ",
	win_mvp = "The crown of victory goes to me, the one who knows no fear!",
	home = "Phew, I'm back! Oh, you need a battle report, repair and resupply overviews, and a mission debriefing? Sure, five minutes should be enough, right? After that, send me back out there!",
	unlock = "\"The Fighting I\" of the Essex-class, Intrepid, is here! Commander, leave the combat missions to me! I'll bring home victory and glory!",
	touch2 = "You... *sigh*...I'm way more inclined to beat you to a pulp than to praise you for your bravery.",
	mission = "Having trouble with your missions? If you're stumped, why don't you let me try my hand?",
	vote = "",
	drop_descrip = "Essex-class aircraft carrier – Intrepid, Hull Number CV-11.",
	feeling4 = "During my free time, I like to read, watch movies, or stargaze. Oh, by the way, I got a movie ticket from Casablanca. Why don't we go watch it?",
	lose = "I have to go to the docks again...? Damnit, why is it always me... Y-you didn't hear anything!",
	feeling1 = "Commander, the way you're acting now makes you no different from a coward!",
	skill = "Let's get this done!",
	upgrade = "I feel like I can always keep improving! For example, how 'bout giving me a dozen jets?",
	propose = "I didn't expect you to be the one to take the initiative... but I suppose that's fine too. Commander, guess I'll continue to be in your care then! As long as I am with you, I want you to push forward and face the future fearlessly!",
	feeling5 = "The stars in the night sky are distant. So distant that even with all the courage in the world, the effort it would take to reach them is unfathomable... However, all it takes to catch the commander in front of me is.... this! Hehe, isn't that right?",
	main = "Commander, do you like stargazing? Ahaha, it's fine if you aren't really into astronomy. If you're ever interested, just let me know. |Submarines are... quite strong. But I think I might be able to go toe-to-toe with them. |Despite the fact that there are many Essex-class carriers, we all have our good spots, you say? ...Uhh, you're not talking about our ship performance? I've never given much thought to those bothersome things...",
	touch = "Want something to drink? Then, how about a martini – shaken, not stirred? Just kidding!",
	voice_key_2 = -1,
	mission_complete = "Mission accomplished! See, there's nothing you can't do if you put your mind to it!",
	battle = "Flight preparations complete! Attack squadrons, roll out!",
	id = 107110,
	gift_dislike = "",
	gift_prefer = "Appreciate it, Commander! I'll pay you back on the battlefield!",
	profile = "I'm the third ship of the Essex class, Intrepid! Although my poor luck during the war earned me quite a few unflattering nicknames... Heheh, that's all behind me now! Commander, under your command, I'll show you just how powerful I am!",
	voice_key = 10711,
	headtouch = "Wooahh?! You're messing up my hair?!",
	feeling2 = "The great symbol of fearlessness is none other than I – Intrepid! Don't you forget that!",
	login = "Am I slated to sortie today? If not, hurry up and fix that!",
	detail = "One should always go all out, no matter the enemy... Having that said, there are various practical reasons why that isn't always possible...",
	couple_encourage = {
		{
			{
				10717,
				10722
			},
			1,
			"Task Force 38, let's rock and roll!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[107111] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Nobody can return one of my pitches!",
	home = "Phew, time for a break! Commander, thanks for coming out with me! Feel free to use the equipment however you'd like!",
	unlock = "There's been a lot of inter-port meets recently... But before I can join a team with my other Eagle Union colleagues, I've got to up my game first! So, Commander, mind training with me?",
	touch2 = "Even if you brought protection, getting hit by my fastball is gonna hurt like hell~",
	mission = "",
	vote = "",
	drop_descrip = "There's been a lot of inter-port meets recently... But before I can join a team with my other Eagle Union colleagues, I've got to up my game first! So, Commander, mind training with me?",
	feeling4 = "",
	lose = "Gah, I gave up a run...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "A ponytail really does get in the way, huh... Next time, maybe I'll try putting it up... |Gah! I threw the ball full power and lost control of it... My bad, my bad! |All righty! This one's headed towards the ends of the universe! Wait, how's the catcher gonna get it then...",
	touch = "Woah! I just thought of a new kind of pitch! Commander, let's go try it out!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 107111,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "It's not enough to just be a pitcher. I've gotta be a good batter as well! Oh, Bluegill's also out there training. Let's grab her for our practice!",
	detail = "Nice catch! You've got skill! How about becoming my catcher?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107120] = {
	hp_warning = "This ain't over! I'm just getting ready to make my comeback!",
	feeling3 = "Hmm? You prefer it better when I'm pouty versus when I'm lovey-dovey? Well, that's too bad. Because... it all depends on who I'm dealing with. Yup~",
	mail = "Perfect! It's the Magic Carpet Delivery System! ...Hmm, I don't know how to feel about that name...",
	expedition = "*yaaawn*... Shoot, can't be dozing off now... Uhh, our commission buddies are already back?",
	win_mvp = "That win was a pretty good workout! How 'bout you, Commander? Work up a good sweat?",
	home = "Whew~♪ Commander, you looked spiffy out there as always! Here's an ice-cold one for ya... Woah! Are you okay there?",
	unlock = "\"The Grey Ghost\" Hornet that everyone's talking about is me! Haha, maybe it's time for everyone to start calling me Ma'am! Anyway, let's keep getting things done, Commander!",
	touch2 = "E-even I'll get embarrassed if you touch me like that...",
	mission = "The weather's great and I'm raring to go. It's a perfect day for tackling some missions!",
	vote = "",
	drop_descrip = "Essex-class aircraft carrier – Hornet II, Hull Number CV-12.",
	feeling4 = "Leaving Enty aside, I wouldn't mind if you went out with Yorktown. I'd be totally fine with Zuikaku, Ty, or Northampton too... Nope, don't mind at all. Me? Being surly? Why, I'd never.",
	lose = "The new and improved Hornet... ain't gonna fall here!",
	feeling1 = "Say, Commander, are you really that dumb, or just playing? I really can't tell sometimes...",
	skill = "Now, you're done for!",
	upgrade = "I've powered up~!",
	propose = "Hoo... Haah... Alright, I'm ready! C'mon, Commander, are you ready to put a ring on it? Even if nothing is really gonna change, the ceremony is sometimes what matters!",
	feeling5 = "Well, there's no point being hung up on it, and it's not like I can control who you see. All that matters is that I'm your Hornet, and that's enough for me. Eeeyup! And I'll always love you, no matter what!",
	main = "I'm not worried about catchin' up to Enty's shadow anymore – I'm now thinkin' about how to become stronger and faster than her! After all, I can't be playing second fiddle to her forever~|Is that... Northampton? Hey, Northampton! ...Ahaha, stubborn as always~ Or is she just shy around you?|Even if you're confident, you're still going to lose if you don't assess the situation carefully. The victor is decided before the battle even begins.",
	touch = "Need me to lend a hand?",
	voice_key_2 = -1,
	mission_complete = "Your mission rewards are in! Make sure none of 'em leaked out first though.",
	battle = "Battle station connection established, attack formation ready to go – All ships, let's slug this one out!",
	id = 107120,
	gift_dislike = "",
	gift_prefer = "I shoulda known you'd know exactly what I like, Commander!",
	profile = "It's me, the mighty, new-and-improved Hornet, now an Essex-class aircraft carrier! Well, to be honest, besides the history, the outfit, and the combat power, I'm still pretty much the same girl inside! ...Hey, just because I look a little different doesn't mean I'm not real grateful to you~",
	voice_key = 10712,
	headtouch = "",
	feeling2 = "I've prepared some home cooking for my beloved Commander! Dig right in~♪ Look, it's totally different from what Enty and Yorktown make, right?",
	login = "The new and improved Hornet has arrived at the office! Hahaha, that's a good mornin' to ya, Commander!",
	detail = "Ahaha, have you fallen in love with the new and improved me all over again? No need to be ashamed about it; it was written all over your face~",
	couple_encourage = {
		{
			{
				10714
			},
			1,
			"Ty, where are you headed on your next day off?",
			0
		},
		{
			{
				10706,
				10705,
				10710
			},
			1,
			" Let's show 'em our teamwork!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[107121] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The girls are back from their commission~ I'll go on ahead to greet them~!",
	win_mvp = "Just means you were no match for Hornet, conquerer of waves!",
	home = "Whew... Worked up a good sweat... You want one as well, Commander? A nice can of Oxy-Cola after exercise... Nothing beats ice-cold pop after a workout~",
	unlock = "The title of fastest in the port is miiiine, hahaha! Commandeer, did you see how badass I was just now? There's a whole lot more I'd like to show you, but it'll hafta wait 'til the next race... Well, I'll let you ride with me later, so look forward to it~♪",
	touch2 = "C'mere, grab on tight from behind... Wha, wha?! Commander?!!",
	mission = "",
	vote = "",
	drop_descrip = "The title of fastest in the port is miiiine, hahaha! Commandeer, did you see how badass I was just now? There's a whole lot more I'd like to show you, but it'll hafta wait 'til the next race... Well, I'll let you ride with me later, so look forward to it~♪",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Isn't Yorktown's swimsuit simply breathtaking? You know, I was the one who picked it out. If it knocked the wind right out of your lungs, it's all thanks to me, hehe!|I've finally come to the beach to have some fun, so it's time to enjoy the day to the fullest!|The beach is loads better than the pool. This wind, this feeling of freedom~! Whew~ It just feels so darn good~!",
	touch = "Want a ride, Commander? I'll cheer you on~",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Rigging energy supply connected, all systems go! Time to send 'em flying!",
	id = 107121,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Oh, Commander~! Ahahaha, sorry! Did I get you all wet? Well, just think of it as having had a big wave crash down on you~!",
	detail = "Heheh~ Has my bewitching, swimsuit-clad figure stolen your heart? No need to be shy about it. That was my aim from the start, after all... Just kidding~♪",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107130] = {
	hp_warning = "Hmph! You'll have to do worse than that!",
	feeling3 = "Ah, a power outage? No worries. I'll go get my flashlight and spare batteries... Oops! Sorry, I think I bumped into the table. I'll get off of you now, heheh♡",
	mail = "Commander, there's a new letter for you.",
	expedition = "The commission team's back. Gathering materials is a ton of work, so I'll bet they're exhausted. Let's go talk to them.",
	win_mvp = "Easy win. Nothing to write home about.",
	home = "Welcome back. Yep, that trinket on the table is a souvenir for you. Pretty unique shape, right? ...Huh? You don't need to give anything back. I'd be happy if you just came along on an outing.",
	unlock = "Heya, Commander. I'm Franklin. It's nice to meet you. Gosh, I'll bet you're a mighty busy person, so do you mind if I just explore 'round the port? Ooor... should I get straight to giving you a hand instead?",
	touch2 = "Oh? Don't you want to go a step further, Commander? Heehee♥",
	mission = "Guess the adventure will have to wait until all these missions are finished... Come on, get 'em done. Any way I can help?",
	vote = "",
	drop_descrip = "Essex-class aircraft carrier – Franklin, Hull Number CV-13.",
	feeling4 = "While flipping through my journal filled with precious photos I took with everyone on adventures, I realized there aren't many pics of just you and me together. We should make some really special memories together, you and I♡",
	lose = "Bummer... Commander, you need to get more involved next time.",
	feeling1 = "As it stands now with you... I'm better off going out alone.",
	skill = "Time to demonstrate my expertise!",
	upgrade = "I've gotten stronger again. Now I should be able to explore that deep-sea cavern I have my eyes on...",
	propose = "Whatever happens in the distant unknown, I will always face it with our hands held together. This I promise, Commander. Now let's set off on the best journey of discovery of our lives♡",
	feeling5 = "The first lesson of wilderness survival is: Never let go of what's important. That's why I'm never letting go of your hand now, Commander! Heehee. Stay by my side forever♪",
	main = "When it comes to outdoor exploration, equipment isn't the only important thing – you need experience and courage, too. Of course, it's also vital to have companions with you. Wanna come with me sometime?|...You're amazed that I can eat Chi An's food without as much as flinching? I mean, have you ever had raw caterpillar paste? Chi An's dishes are still tasty compared to that.|Ah, interested in my journal, eh? You're one curious cat, Commander. Wanna look through it with me? I don't imagine you can see much from that far away. C'mon, come a little closer♡",
	touch = "You hurt your hand? Then you need to wrap it in gauze and... Oh, it's just a scratch? Okay. Here I thought you'd need some first aid.",
	voice_key_2 = -1,
	mission_complete = "Mission complete. You're a real reliable one, Commander. So, I know tons of ways to unwind after work – wanna try one?",
	battle = "Equipment is all good! Let's roll!",
	id = 107130,
	gift_dislike = "",
	gift_prefer = "A gift, huh? You don't see these just anywhere. Let me try and guess where it's from.",
	profile = "I'm Franklin, Eagle Union Essex-class aircraft carrier. I like getting out and exploring more than just sitting around. Will you come with me on an adventure? I guarantee it'll be an unforgettable experience, heehee♡",
	voice_key = 10713,
	headtouch = "My goggles? They're made to work in all kinds of scenarios. For instance, catching your eye like right now!",
	feeling2 = "Commander, get your outdoor supplies in– Oh, you've got it all ready. I'm impressed. Although, you should get some quick-drying clothes too. Better safe than sorry, as they say!",
	login = "Oh, it's you. I was just working out the route for my next adventure. As you suspect, I'll be exploring the unknown and doing some extreme sports... What do you mean it's \"that kind of adventure\"? What did you think I meant?",
	detail = "Improving the hardpoint on this hook and rope should make it more convenient to use... Hm? When'd you get here, Commander? ...It's fun to watch me tweak things? Heheh, alright, then come sit next to me for a better look.",
	couple_encourage = {
		{
			{
				10149,
				50102
			},
			1,
			" So, where are we going on this adventure of yours?",
			0
		},
		{
			{
				10709
			},
			1,
			" Let's show 'em how strong the Essex class is!",
			0
		},
		{
			{
				10738
			},
			1,
			" I found this mysterious cavern. Wanna check it out with me later?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[107131] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome back, Commander. Did you get hurt out there? Aw, you careless thing... Take a seat and I'll tend to you.",
	unlock = "Phew... Sorry I took so long, Commander. I'll be your examiner today. Ah, you're wondering how good I am as a nurse? Heehee. Let's just say you'll find out by... touch♡",
	touch2 = "Oh, you'll pat me dry? Doing it while standing is a pain, so... how about we do it in bed, hmm?",
	mission = "You've got a new mission. You just stay put and rest. I'll take care of it.",
	vote = "",
	drop_descrip = "Phew... Sorry I took so long, Commander. I'll be your examiner today. Ah, you're wondering how good I am as a nurse? Heehee. Let's just say you'll find out by... touch♡",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "There's no hurry, is there? You've been \"hurt,\" so what you should do is lie down and get some rest. Heehee. You might not know it, but I'm quite good at... looking after people♡",
	main = "You think I should be gentler when treating my own injuries? Um... Are you feeling sorry for me, Commander? Aww♡|Since you're already here, should we do a physical exam while we're at it? I've already got all the tools. Why don't we start by taking off your clothes so I can check your heartbeat?|Wondering if you're allowed to bathe? It should be fine if your wound's exposed to water. If you're concerned about getting an infection, I could help with that. Heehee♡",
	touch = "I rushed over as soon as I heard you were here. Worked up quite a sweat, so maybe I should shower before I... Huh? You don't mind?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 107131,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Phew... Could you pat me dry, Commander?",
	feeling2 = "",
	login = "I just got here, and I just got changed, too. My vibes are pretty different now, aren't they? Do I... look good?",
	detail = "Phew, the bleeding isn't too bad. Now I'll use glue or a lighter to... Well, I don't usually do this, but the circumstances demand it, so... Look, don't be so nervous. I promise I won't do this again, okay?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107140] = {
	hp_warning = "Hard to port! Watch out for fire!",
	feeling3 = "There are many excellent allies here at the port. I... I'll have to work hard, won't I~♪",
	mail = "There's some mail for you, Commander. You should check them as soon as possible. After all, it'd be a disaster if you overlooked something.",
	expedition = "The commissions team is back. We should go and greet them right away. ",
	win_mvp = "Oh, we won. It's because you were by our side, Commander.",
	home = "Good work on the operation, Commander. Give me your arm... Good, there we go. Hehe, doesn't it feel nice? Let all the fatigue dissipate, just like that!",
	unlock = "Hi there~ I'm Ticonderoga, the newest arrival at your port. Hmm, you look just as friendly as they said you'd be~ Thank goodness. So, how about a hug to start us off on the right foot? Hehe~",
	touch2 = "My, are you sure you want to be doing this? I think I saw Aoba or someone passing by with a camera earlier.",
	mission = "You still haven't completed the new missions? Hmm... Well, it's fine for now. Just take care of them at your own pace.",
	vote = "",
	drop_descrip = "Essex-class aircraft carrier – Ticonderoga, Hull Number CV-14.",
	feeling4 = "For some reason, it seems there are some strange rumors about the two of us floating about... Just as planned? ...Commander!",
	lose = "Where did we go wrong...",
	feeling1 = "It seems I won't be able to save the Commander with my efforts alone...",
	skill = "Let's show off the fruits of our labor!",
	upgrade = "I've gotten even stronger... Great!",
	propose = "Huh?! Uh, umm... What am I supposed to say in response to your proposal...? Uhh... You're really giving this to me? Ahh, I'm sorry, I'm just so happy that my heart is about to explode and I don't know what to do and ahh...",
	feeling5 = "I'm not particularly noteworthy as a warship, and it might be a while until I can truly stand by your side as your equal... Even so, are you really fine with me? Can I really stay at your side?",
	main = "What's on the moon, you wonder? A rabbit? Aliens? Hehe. Whatever it is, I'd like to see it for myself one day.|If you're tired, you can snuggle up to me and rest for a bit. Oh, would you rather have a lap pillow instead? Well, if someone walks in on us, I'll leave the explanations to you~ Hehe.|The files are organized, and the Commander's schedule is ready... Phew... I should be fine.",
	touch = "You shouldn't slack off, Commander. Oh my, am I the distracting you from your work? Heheh, just kidding~♪",
	voice_key_2 = -1,
	mission_complete = "Great job completing those missions! You're quite something, Commander!",
	battle = "Stick to the plan!",
	id = 107140,
	gift_dislike = "",
	gift_prefer = "You really are great at choosing presents, Commander.",
	profile = "The sixth ship in the Essex-class, and the first in the class to have a long hull. I was once called \"Hancock,\" but in the end, I was renamed to \"Ticonderoga\" in commemoration of the great war. That's about it.",
	voice_key = 10714,
	headtouch = "",
	feeling2 = "You're going to head out on patrol? Then... wrap your arm around mine, just like this~ Oh, do you dislike me, Commander? Or... are you worried about the other girls' reactions?",
	login = "Oh my, you don't look that great... How about I do something special for you? What, you ask? Hehe, why don't you try imagining what it might be?",
	detail = "Sigh... The last exercise revealed a lot of problems... Commander?! Please, could you please knock before entering a lady's room?",
	couple_encourage = {
		{
			{
				10709,
				10711,
				10717,
				10738
			},
			2,
			"Shall we show them our Essex-class synergy? Hehe~",
			0
		},
		{
			{
				10711
			},
			1,
			"Let's calm down and take this slowly!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[107141] = {
