_G.pg.base.ship_skin_words[107142] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission team is back. Let's go out to the beach to greet them with gifts!",
	win_mvp = "Phew... Cheers to victory! Right?",
	home = "Oh, Commander, you look tired. Wanna take a break here with me? The ice cream and fruits here are cold and tasty.",
	unlock = "Hi! Thoughts on my swimsuit, Commander? Does it suit your tastes? Heheh, thanks! If you had to leave a comment, what would you say? ...Where did you learn how to tease people so well?",
	touch2 = "What? You wanna put suntan lotion on me? Heheh, then how about we take things behind that tree over there...?",
	mission = "",
	vote = "",
	drop_descrip = "Hi! Thoughts on my swimsuit, Commander? Does it suit your tastes? Heheh, thanks! If you had to leave a comment, what would you say? ...Where did you learn how to tease people so well?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Eye candy or not, it's pretty easy to get shy surrounded by so many people in bathing suits... Makes you wanna go on a little faux-date, just the two of us... Geez, what am I saying? It could be a real date, right...?",
	main = "I was thinking of riding some waves for a while later. Wanna come, Commander? I bet you'll have fun.|Hm? You're interested in Saratoga's swimsuit? I see... Probably suits Bunker Hill or Essex more than me...|Georgia, the lace on your rash guard is so pretty. Huh? Seattle picked it for you? That's a surprise...",
	touch = "Essex and I don't really burn much. It's a shame we never get a good excuse to wear tanning oil.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 107142,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, you're late. I was about to melt out here waiting for you. What's that? You didn't promise to meet me here? Then why are you here, exactly? Heheh♪",
	detail = "The sun is strong on the beach, so sunglasses are a must... But y'know, Commander, you might be even more dazzling. Heheh, was that smooth, or what?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107160] = {
	hp_warning = "I'll have to go all-out this time.",
	feeling3 = "Oh? Your brow's all furrowed again. If you're worried about something, talk to me. We can solve it together... Hmm? When did I come get in here? Hehe, that's a secret!",
	mail = "You've got mail! Hehe, I hope there aren't any surprises inside!",
	expedition = "Commander, the commission team is back. I'll go check on their results!",
	win_mvp = "Heehee, have you fallen for this reborn Lady Lex all over again?",
	home = "I smell gunpowder... Commander, well done today. Heehee, before you get back to work, let's get you cleaned up. Go take a bath, okay?",
	unlock = "Hehe, nobody could've awakened the Blue Ghost from her long slumber but you. It's been a while, Commander, but I've finally come home to you.",
	touch2 = "Hehe... Yeah, just like that. You remember exactly what I like, don't you?",
	mission = "That mission is yours, this one is mine... There. Dividing the labor makes us twice as efficient!",
	vote = "",
	drop_descrip = "Essex-class aircraft carrier – Lexington II, Hull Number CV-16.",
	feeling4 = "The sea breeze brought news: today's the perfect day to relax. Commander, let's take the day off and take Sara on a picnic together.",
	lose = "The enemy's gotten arrogant... Commander, once we've regrouped, let's teach them a painful lesson.",
	feeling1 = "How long are you going to keep this silliness up, Commander? It's about time you grew up.",
	skill = "On my name as the Blue Ghost, I write your funeral dirge!",
	upgrade = "Now I can sing even better!",
	propose = "I understand, Commander – you put a lot of thought behind this moment, right? Hehe, you're the same as ever. My feelings are the same, too. No matter when, no matter where, we'll always be together.",
	feeling5 = "Sometimes, the breeze at port reminds me of that dream again. Happy summer days, cool waves... But in the end, a dream is just a dream. In this moment, as I'm holding your hand and sharing your warmth, I am truly happy.",
	main = "Bristol, Fu Shun, Gallant, Fu Po... Heehee, this port has welcomed a lot of delightful young ones, hasn't it?|I didn't expect the port could change so much... Commander, I'll have you know that I got lost in the dorms today!|Sara's awfully well-behaved today... Did our last little chat really make a difference?|Aircraft carriers' combat tactics change in the blink of an eye. Maybe I should be the student, for once?",
	touch = "What's on your mind, Commander? Ready to look at today's mission reports? Or... Is it me you're focused on?",
	voice_key_2 = -1,
	mission_complete = "Phew... The missions are all done and dusted. I booked us a private trip to the hot spring, if you'd like a little change of pace.",
	battle = "Everyone, let's win today for a greater tomorrow!",
	id = 107160,
	gift_dislike = "",
	gift_prefer = "Thank you. You never change, Commander♪",
	profile = "The Blue Ghost Lexington is back from her long dormancy... Commander, thank you for waiting for me. Nothing makes me happier than knowing that we're reunited.",
	voice_key = 10716,
	headtouch = "Hehe, you're always so encouraging!",
	feeling2 = "\"Being an idol is a job that brings smiles to everyone. Of course, that includes you too, Commander.\" Remember that? Well, for all the waiting I put you through, I'll have to make you smile twice as hard!",
	login = "Welcome, Commander. The weather's been fickle lately. Take good care of yourself between all of your work, okay?",
	detail = "Worried that I'd fall back into my deep slumber? Hehe, don't worry. I won't leave you again.",
	couple_encourage = {
		{
			{
				10703
			},
			1,
			"Sara, show me how much stronger you've gotten.",
			0
		},
		{
			{
				10710
			},
			1,
			"A new us, a new era... Let's spread our wings together.",
			0
		},
		{
			{
				10709
			},
			1,
			"Hehe, ready to fight together again, Essex?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[107161] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Oh? You're just in time... Commander, would you please hand me that cloth?",
	unlock = "I guess dressing up as maids is all the rage at port these days. It piqued my interest, so I just had to try it! Together, let's make this place as clean and relaxing as it can be.",
	touch2 = "Geez, I'm trying really hard to play the part... You're not making it any easier~",
	mission = "",
	vote = "",
	drop_descrip = "I guess dressing up as maids is all the rage at port these days. It piqued my interest, so I just had to try it! Together, let's make this place as clean and relaxing as it can be.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Since I'm playing the part of a maid, I have to ask... Are you enjoying my services? Hehe, that passionate gaze of yours does make my heart race... Master♡",
	main = "Phew... I'm almost done here. How do you plan to relax, Commander? Of course, I expect you'll be resting in my arms.|Oh? Commander, stay still. There's dust on your collar... Hehe, isn't it a maid's duty to pay attention to the little details?|I'm always telling you to leave things to me, but I didn't think we'd be this busy... It's kind of refreshing, honestly.|It's fun to change roles together once in a while, isn't it? Hehe... Yeah! It has to be both of us, together!",
	touch = "Mm... I really need to be careful when I'm dressed like this, huh?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 107161,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Mm... Is my hair sticking to you? Hehe, I might be a little bit sweaty.",
	feeling2 = "",
	login = "I think I'm starting to understand the joys of being a maid. Just doing my job well makes you more comfortable. Isn't that wonderful?",
	detail = "You and I are in perfect sync! We're almost done cleaning. Do you think this place has gotten more relaxing yet?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107170] = {
	hp_warning = "Why now of all times...?!",
	feeling3 = "Don't think I'm upset just because I have little to say. If anything, I'm probably thinking about something, or about how to express myself.",
	mail = "The mail's here... Wonder if there's any new intel?",
	expedition = "Pardon, but I'll go greet the girls who are coming back from their commission. Just wait here until I report back.",
	win_mvp = "So this is the end that you all chose...",
	home = "You've returned? ...Very well. Why don't we prepare for the next sortie?",
	unlock = "Bunker Hill, one of the Essex-class carriers, is joining the fleet under your command. Don't worry, you'll see the extent of my abilities soon enough.",
	touch2 = "By the looks of things, you won't learn your lesson without some harder-hitting \"experience.\"",
	mission = "Missions... should best be completed in a timely manner.",
	vote = "",
	drop_descrip = "Essex-class aircraft carrier – Bunker Hill, Hull Number CV-17.",
	feeling4 = "Something strange has been going on with my thoughts recently. Whenever I start thinking about things, your face pops up in my head and makes it hard for me to stay calm...",
	lose = "Their power... surpasses even the \"Dragon's Jaws\"...?",
	feeling1 = "I'd rather not talk to you right now.",
	skill = "Resistance is futile!",
	upgrade = "I grow stronger... yet again...",
	propose = "Sorry... My mind has gone completely blank... I'm lost for words... Oh, that's right! \"I pledge loyalty and love to you until the end of time.\" ...How does that sound?",
	feeling5 = "We were born as weapons of warfare, and I thought that is all we would ever be. But having spent time with you, I'm beginning to think... that there's more to our lives than war.",
	main = "Right now, another place out there is being engulfed by the flames of war...|Eldridge's ability? I'm not exactly sure, but... I feel like I've seen it somewhere... |All resistance is meaningless before the Essex-class's attack formation.",
	touch = "...Don't think I'm upset just because I have little to say. Just let me know if you need anything.",
	voice_key_2 = -1,
	mission_complete = "There are a ton of rewards? Of course.",
	battle = "Why did they choose to become our enemy...?!",
	id = 107170,
	gift_dislike = "",
	gift_prefer = "I never thought I'd be getting a present from you. Thanks.",
	profile = "Essex-class, Bunker Hill. My name comes from a battlefield in the Revolutionary War. I've seen my fair share of battles... and know that war brings nothing but sorrow and pain. Let's not talk about it any more.",
	voice_key = 10717,
	headtouch = "",
	feeling2 = "There is no beauty in warfare. There is only ugliness in the suffering and loss of life we inflict upon each other.",
	login = "We're in a state of emergency. Be prepared to run the Holiday Express, even if it's a holiday.",
	detail = "Commander, why are you staring at me...?",
	couple_encourage = {
		{
			{
				10709,
				10738
			},
			1,
			"You are nothing before the Essex class.",
			0
		},
		{
			{
				10126
			},
			1,
			"Project Rainbow? ...It has a nice ring to it...",
			0
		}
	}
}


