_G.pg.base.ship_skin_words[107223] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Feel like doing some stretches with me? I could use a hand with a couple of moves, like the forward bend for instance.",
	unlock = "Whew... A bit of stretching helps keep the body flexible. Hm? I'm in loungewear, what about it? I'd appreciate it if you wouldn't stare too much, though...",
	touch2 = "I appreciate your help with the pushes, but now you're just pushing your luck.",
	mission = "",
	vote = "",
	drop_descrip = "Whew... A bit of stretching helps keep the body flexible. Hm? I'm in loungewear, what about it? I'd appreciate it if you wouldn't stare too much, though...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Who's the most dexterous among the Cleveland class? If I had to guess... Columbia. She does ballet, you know.|Even the most basic of stretches qualify as exercise. Though I'll admit, it's not very rigorous exercise.|Long Island claims mastering yoga gives you the power to breathe fire and extend your arms. I don't buy that idea, though.",
	touch = "Yeah, that's it. Push on my back and hold it like that.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 107223,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Your health suffers if you don't move your muscles enough. Keep an eye on your posture in the office so you don't develop a hunchback, Commander.",
	detail = "Saratoga and Lexington do stretches on the regular, giving them great dexterity for aircraft carriers. They really live up to their rep as idols. Good examples of hard work paying off, too.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107224] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "I got a prize on my first try, so I tried it a few more times... but the crane wouldn't move like I wanted it to, and loosened up as soon as it grabbed something. What a failure. I thought I'd try again, only to find out I was all out of coins.",
	unlock = "Just need to feed it a coin, then operate the crane with the joystick... Oh! I got one! That was easier than I expected.",
	touch2 = "You ought to get some fresh air to cool that hot head of yours...",
	mission = "",
	vote = "",
	drop_descrip = "Just need to feed it a coin, then operate the crane with the joystick... Oh! I got one! That was easier than I expected.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "By the way, have you seen my pet eagle? Do you think he flew off somewhere? ...Wait, he's not in the crane game, is he?!|Apparently, if you bang on a machine hard enough, you might get lucky and get a prize for free. Though it's more likely to get you in trouble than anything else.|I've heard there's a café run by the Sakura Empire nearby. Why don't we stop by there later for a drink?",
	touch = "Here, have some coins. Good luck, Commander!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 107224,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, do you want to take a shot at this manjuu crane game?",
	detail = "Who put this crane game here? \"Supplied by Akashi, nya\"...? That's what it says on the back?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107225] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Great work out there, Commander. Hm? I see you brought a towel and... massage oil, huh? Is that for my legs? Oh, and my soles, too...? I-I see.",
	unlock = "Oh, Commander. You also came to the beach? What a coincidence... I just finished with my swim. Got a bit too enthusiastic when I got in the water though...",
	touch2 = "I-is this part of the massage?!",
	mission = "",
	vote = "",
	drop_descrip = "Oh, Commander. You also came to the beach? What a coincidence... I just finished with my swim. Got a bit too enthusiastic when I got in the water though...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I know I ought to solve my own problems, but being with you makes me feel like I can be vulnerable... Is this what it means to trust your beloved?",
	main = "Phew... Right there... I think it's starting to loosen up a bit. Wow... You're really good at this, Commander.|(Urk... The Commander's been staring at my feet for a while. This is embarrassing... Are the soles really that hard to work out?)|Is this hard part what you call a knot? So you cup it in your palm and slowly work it out along the muscle... Hey, it does feel a little better. It works!",
	touch = "Pfft... Hahahaha! Wh-why does... Haha, why does it tickle, hahaha, instead of hurt?! I-I'll do the soles myself... C-Commander, stop, hahaha!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 107225,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "My hair is wet? Oh, don't worry about it. The breeze will take care of it. Might mess up my styling a little, though...",
	feeling2 = "",
	login = "So, uh... I guess I didn't warm up enough before I started swimming, because my right leg is cramping pretty badly. Could you, umm... massage it for me?",
	detail = "You're really good at giving massages... I thought you were just supposed to press down on the sore spot, but now that you're doing this, I can tell – location, pressure, and what order you do things in all matter.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107229] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Commission goods have arrived. I'll help transport them, of course.",
	win_mvp = "Nothing can stand between my wings and the skies!",
	home = "You conducted that battle masterfully, Commander. Let's take a moment to roost, then get to work on the post-battle report.",
	unlock = "Light carrier Independence reporting. Retrofitting complete. I'm ready to take on harder, more vital missions. Leave anything like that to me.",
