	mission = "",
	vote = "",
	drop_descrip = "Light carrier Independence reporting. Retrofitting complete. I'm ready to take on harder, more vital missions. Leave anything like that to me.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "I should probably hang out with my own sisters as much as I hang out with Cleveland...|I've finished all the work you assigned me. Proofread it at your leisure.|Even I, someone who's terrible at inferring people's feelings, can clearly see how passionately Princeton is about her goals.",
	touch = "Are we sortieing? Or is there administrative work to do around the port? Either way, leave it to me.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 107229,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I'm in top condition and ready as always, Commander. Rest easy.",
	detail = "I am fully accustomed to my new weaponry. My next battles will be legendary in naval history. Okay, maybe not to that extent.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107230] = {
	hp_warning = "I won't let history repeat itself!",
	feeling3 = "Ahem! So you were asking about my hobbies? I like to read books and... study Saratoga's battle style. In terms of combat prowess, I sincerely believe that Saratoga is in a class of her own, and wouldn't lose even to Enterprise herself.",
	mail = "Your mail? I'll go get it, so just stay there and focus on your work.",
	expedition = "Heading out to greet the commission team? I'll go with you.",
	win_mvp = "Looking good. Let's press on.",
	home = "You look pretty tired. Here's a towel.",
	unlock = "I'm Princeton, Independence class. Tallahassee? I don't mind if you want to call me that.",
	touch2 = "Have you never tried a knuckle sandwich before? How about a taste of mine... Hyah!",
	mission = "We've been assigned new missions? Let's give them a look.",
	vote = "",
	drop_descrip = "Independence-class light aircraft carrier – Princeton (CVL-23.)",
	feeling4 = "Do you understand what I mean? Even though Saratoga's usually a perky, high-spirited kind of girl, she's always looking out for others, even in battle. I've personally been saved by her many times. There's also how... Commander? Oh no, you fell asleep...",
	lose = "Still out of Saratoga's league...",
	feeling1 = "Honestly, I'd rather have Saratoga be the one giving me directions.",
	skill = "Just like Saratoga would!",
	upgrade = "Not bad at all. Appreciate it, Commander.",
	propose = "I'm so lackluster compared to Saratoga, so why would you...? Err, not that I'm turning you down! If anything, I'd be willing to go through thick and thin with you, as long as you're fine with someone like me... Yes, let's be together!",
	feeling5 = "Commander, why do you have a picture of Saratoga? You picked it up from the floor?! Nooo! I can't believe I've screwed up so royally... You see, this is from my collection... Please keep this a secret from everyone else, I beg you!",
	main = "Sara? ...S-Saratoga is someone I admire very much. I wouldn't dare call her by her nickname.|Montpelier is a close friend of mine. It's not because we were both members of the Cleveland class, but because we both have someone we really look up to in our lives.|Feel free to give me as much work as you need. It's part of a secretary ship's duties, so don't fret it.",
	touch = "What, do you think I'm too inexpressive? I was wondering if that's why it's like you're always trying to make me laugh.",
	voice_key_2 = -1,
	mission_complete = "Mission rewards... My heart's dancing with glee.",
	battle = "Go forth... No. Let's put the lessons we've learned into practice!",
	id = 107230,
	gift_dislike = "",
	gift_prefer = "Thanks. Is there anything I can do for you in return?",
	profile = "Second ship of the Independence class, Princeton, at your service. I was originally laid down as the seventh ship in the Cleveland class, Tallahassee. I fought a lot alongside Saratoga in the war, and though I was able to learn much from her, I wasn't able to make it through the Battle of Leyte Gulf... It'd be an honor to fight by her side once again.",
	voice_key = 10723,
	headtouch = "",
	feeling2 = "You wanted to have a chat over some tea? Pl-please, just a moment... Umm, I need to tidy up the room a bit, so I'd appreciate it if you could give me half an hour or so...",
	login = "You're finally here. Did you rest well?",
	detail = "Did you need something? Oh, it's fine. I wasn't doing anything special, just sorta letting my mind wander.",
	couple_encourage = {
		{
			{
				10703
			},
			1,
			"Saratoga, I've got your back!",
			0
		},
		{
			{
				10214
			},
			1,
			"I'll do my best to get it done.",
			0
		},
		{
			{
				10223,
				10226
			},
			2,
			"You don't need to worry about me!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[107231] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "If you stay out while the sun's blazing... you're going to get heatstroke. Make sure not to let the sun cook you for too long.",
	unlock = "Commander, are you also here to swim? ...Ah, this here? I brought it with me to the ocean to get some practice in.",
	touch2 = "W-wait a second! If you move too suddenly, it'll capsize... Wah?!",
	mission = "",
	vote = "",
	drop_descrip = "Commander, are you also here to swim? ...Ah, this here? I brought it with me to the ocean to get some practice in.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Hehehe. With this, I'll be able to improve my sense of balance and my physical strength at the same time. Would you like to give this a try as well?|...It really will be a problem if my hair gets all messy from this. Um, Commander... do you think you could tie it down for me?|Independence and the others are calling for me? ...All right, I'll go.",
	touch = "You want to get on? I-it's not that I don't want you to, but...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 107231,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Have you done your stretches yet? You don't want to get cramps because you rushed into the ocean unprepared.",
	detail = "I got this collector's edition of \"Saratoga: Beautiful Summer Days\" from Gridley. Looking at Saratoga enjoying the summer with everyone else makes me wish I could join her...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107232] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Commander, where have you been all this... a premium Saratoga plushie?! W-Where in the world did you find this masterpiece!!!",
	unlock = "You're finally here? ...Ah, well, I only just got here as well, so don't worry about it. Anyway, shall we get going?",
	touch2 = "Y-You did that on purpose, didn't you?!",
	mission = "",
	vote = "",
	drop_descrip = "You're finally here? ...Ah, well, I only just got here as well, so don't worry about it. Anyway, shall we get going?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Commander, what's your favorite flavor of ice cream? ...Oh, umm, it's just for reference...|Saratoga told me this outfit looks fine on me, but I wonder I really do look presentable in such cute clothing...|A shooting game? Alright, I'll show you how much I've improved thanks to Saratoga's special training sessions! Oh... it's a bit embarrassing to get all pumped up by myself...",
	touch = "You want... to hold hands? ...W-Well, that's not a bad idea... Even though this isn't a big deal, why is my heart pounding so furiously...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 107232,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I heard there's a famous candy store around these parts. W-Why don't we stop by there first?",
	detail = "According to Saratoga, what I should be doing in this situation is... Wah?! Commander?!! I wasn't up to anything at all!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107233] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Check the mailbox? I'll do that when I go send out the presents.",
	expedition = "",
	win_mvp = "",
	home = "W-wait, Commander, watch out! I-I'm sorry, Commander... I wanted to try flying my presents over with my planes like Saratoga does... But you arrived just as I was about to test it out...",
	unlock = "I'm done changing... Is this supposed to be a \"reindeer\" costume? It feels a bit too risqué... Oh, Commander, since you're already here, come get your Christmas present.",
	touch2 = "H-hold up! The ribbon's going to come loose–!",
	mission = "",
	vote = "",
	drop_descrip = "I'm done changing... Is this supposed to be a \"reindeer\" costume? It feels a bit too risqué... Oh, Commander, since you're already here, come get your Christmas present.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "I heard someone at the port accidentally tied herself up while making some ribbons. I have to learn from those mistakes.|You want me to tell some Santa stories to the destroyer girls... I did promise Saratoga I would help her out, but I'm not much of a storyteller...|Commander, I've finished wrapping up my presents. Would you help me carry them over to the Christmas tree?",
	touch = "If you love my smile so much... I-I suppose I could smile a bit longer for you.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 107233,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Merry Christmas, Commander. Let us enjoy a joyful Christmas together.",
	detail = "Of course I've prepared a present for Saratoga, I do so every year. Saratoga didn't seem all too pleased though... What could be the issue?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107250] = {
	hp_warning = "Someone's a little stubborn~",
	feeling3 = "Commander~ My diet plan is working really well, isn't it? Keep it up!",
	mail = "Before you check your mail, drink this vegetable juice to recover your energy. It's your favorite flavor!",
	expedition = "Commander, I hear the girls who went on commission came back~ It's great to know that they're safe.",
	win_mvp = "Heehee... The joy of victory is the best nutrient of all!",
	home = "Commander, welcome home. You must be sooo exhausted. Come lean on me, drink this warm honey milk, and recover your strength... I won't take no for an answer!",
	unlock = "Commander♪ I'm Cowpens, and I've come to take care of you. With my high-quality milk and bountiful nutritional knowledge, I'll make you feel better than ever. Just do exactly what I say, okay?",
	touch2 = "Hmm? Commander... Are you looking for some \"special\" nutrients?",
	mission = "Commander~ Missions are important, but keeping yourself energized is just as essential. Drink this special energizing milk I made... THEN you can go take care of those missions!",
	vote = "",
	drop_descrip = "Independence-class light aircraft carrier – Cowpens, Hull Number CVL-25.",
	feeling4 = "Overtime isn't good for you, Commander. To ease my worries and improve your health, you'll just have to stop... Or else my nutrition won't be able to keep up with your efforts♡",
	lose = "Hmm... We'll have to change our diets and get more nutrients. Make sure you eat right too, okay, Commander?",
	feeling1 = "Commander... This can't continue. I'll have to try even harder to take care of you.",
	skill = "Stay still and let me give you the nutrients you crave!",
	upgrade = "Mmm, I feel so full of energy... I'll use this power to support you and everyone else even better than before.",
	propose = "At first, I just wanted to soothe you with the warmth and nutrients of milk... But at some point, my feelings turned into a lifelong bond. Heehee... You've given me a nutrient, too, Commander – the one called love.",
	feeling5 = "My beloved Commander... Your continued health and vitality are my greatest joy. Like milk that stays warm forever, my love and protection will never, ever cool down♡",
	main = "I don't think you're getting enough fiber lately... I'll add some more veggies to your diet tomorrow~ Commander... You'll eat them all, won't you?|Behold, my new milk enriched with even more nutrients. By the way, do you like your milk plain or sweetened? I can make both~|Commander, tell me all of your favorite foods. I'll incorporate as many as I can so your diet is nutritious AND delicious.",
	touch = "Heehee, do you want me to warm you up, silly? Don't worry. My arms are always open to you, Commander~",
	voice_key_2 = -1,
	mission_complete = "Are you tired, Commander? Hehe, time to have some of my special milk pudding! Nothing is more important than ample nutrition~",
	battle = "Battle starts~ Don't worry, Commander. I'll protect everyone.",
	id = 107250,
	gift_dislike = "",
	gift_prefer = "You know me so well, Commander~ Why don't I make you some special veggie juice tonight? Make sure you drink it all up~",
	profile = "Heehee. I'm Cowpens, the Union's Independence-class aircraft carrier – and your new nutritionist! Relax and leave it all to me, Commander. I'll give you plenty of nourishment and fill you with energy every day~",
	voice_key = 10725,
	headtouch = "Mmm... Your touch makes me want to press myself up against you, Commander...",
	feeling2 = "Please don't refuse my care, Commander. It's all for the sake of your health... Drinking milk can help you relax, too.",
	login = "Commander, welcome baaack. Would you like a piping-hot cup of milk full of love? Don't be modest~ Drink up while it's still warm.",
	detail = "Commander~ Wanna learn more about nutrition? Or... Do you need more intimate love and care?",
	couple_encourage = {
		{
			{
				10729
			},
			1,
			"Stay close to me!",
			0
		},
		{
			{
				10730
			},
			1,
			"Let's hold the line together!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[107251] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Good work today, Commander~ Sit down here. The ultimate nutrients await, so drink up♪",
	unlock = "Are you ready, Commander? You're about to get the most soothing infusion of nutrients in your life. Step one is to relax...",
	touch2 = "Mmm... Are you in the mood for extra nutrients today?",
