	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Stay here with me forever, Commander. I'll nourish every last inch of you with my milky love, day and night.",
	main = "I added calming honey to your milk to help you sleep~ Take a nice little nap in my arms... I'll hold you all the way through.|Physical affection can help you take in nutrients faster... Hmm? You don't think that's true? Heehee, I just wanted you to feel my body heat.|Commander~ If I do... this... do my softness and body heat feel nice and relaxing?",
	touch = "Commander~ Wanna try an even more amazing nutritional plan I've been cooking up?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 107251,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Mm? Hehehe... For being such a good Commander, you can touch all you like~",
	feeling2 = "",
	login = "Commander, you're back just in time. Come on in! My milk is at the perfect temperature now.",
	detail = "Isn't this material just so soft? Hehe... Has a nice mouth-feel, too, doesn't it?",
	couple_encourage = {}
