	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome back, Commander... Why don't you take a rest? I can lend you my pillow...",
	unlock = "Yaaaaawn... Huh!? Commander!? You scared me... I was just going to lie down and... Um, yes, with little Hellcat here... Goodnight...",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "Yaaaaawn... Huh!? Commander!? You scared me... I was just going to lie down and... Um, yes, with little Hellcat here... Goodnight...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Whether I'm hard at work or resting comfortably, you're always here, Commander... And I wouldn't trade it for the world. Hehe. Commander, would you like to hold the little one?",
	main = "Good sleep is very important to your work. Commander, do make sure you're getting enough rest.|Sorry, Commander, I'm fading again... Zzz...|A pajama party...? I want to go... I wonder if Independence would be interested...",
	touch = "These are my favorite pajamas... They aren't too childish? ... They suit me? Ahahaha... Th-thanks...",
