_G.pg.base.ship_skin_words[107300] = {
	hp_warning = "I can't cause trouble for the Commander, not now...",
	feeling3 = "You still have a whole lot of work left today, huh... Commander, would you like my help? In return... go out with me when we're done~",
	mail = "New mail arrived. I hope it's good news.",
	expedition = "What am I supposed to say now... \"Commission complete.\" Right, Commander?",
	win_mvp = "Whoa. It's already over? Eh, not that I'm all that disappointed~",
	home = "Welcome back, Commander. You look tired... Should I carry you over to the couch and help you—Oh! Wooow, so you can walk on your own~",
	unlock = "My name? I can't just go around telling strangers all that~ I'm kidding, I'm kidding♪ I'm San Jacinto, an Independence-class aircraft carrier. I'll be one of your new friends from now on~",
	touch2 = "You are getting to be that age~",
	mission = "Commandeeer! Keep slacking off, and you'll never finish your missions. That would be funny to watch, though~",
	vote = "",
	drop_descrip = "Independence-class light aircraft carrier – San Jacinto, Hull Number CVL-30.",
	feeling4 = "Goodness, Commander, your clothes are dirty. May I clean them for you? Yes, here and now. Let's hurry up and get those clothes off of you~",
	lose = "We lost, huh~ What now?",
	feeling1 = "You did that on purpose, didn't you, Commander~ Huh? Y-you were serious?",
	skill = "Sleep peacefully~",
	upgrade = "Heehee, it looks like I've grown a little~",
	propose = "The ceremony of exchanging vows, the proof commemorating it... I can tell you put so much thought into it~ Commander, may I be a little picky myself? Heehee. Close your eyes, lean in, and try giving me a little kiss♪",
	feeling5 = "Heehee, I get to visit your room today~ What will I be doing? Taking care of you, of course. You've been so kind to me, and I want to thank you, and also... Oh! Let's not just stand here and talk. Hope you don't mind if I borrow a spot in your bed~♪",
	main = "My heart's beating faster... Commander, come closer and listen... Hahaha! You look a little embarrassed, Commander~|Finback... She's done a lot for me. Now it seems like it'll be your turn to do the same, Commander. Heheh!|I'm an expert at taking care of airplanes and friends alike. Heehee, maybe I'd be good at taking care of you, too, Commander...?",
	touch = "Commander, can I drink that cola on your desk? Oh, you already drank some...? Well, don't mind if I do~ Heheheh♪",
	voice_key_2 = -1,
	mission_complete = "These are the only rewards you get? Have you considered applying for a raise?",
	battle = "The enemy formation is full of holes~ Heheheh.",
	id = 107300,
	gift_dislike = "",
	gift_prefer = "Goodness, what a lovely present! What would you like in return, Commander? Nothing's off the table~",
	profile = "I'm Independence-class aircraft carrier San Jacinto. During the war, I took to the water, fought, and watched over the flight of the young eagles... Frankly, I would've rather spent my time traveling around the world. Hahaha!",
	voice_key = 10730,
	headtouch = "You're gonna mess up my hair, you know. Still wanna do that?",
	feeling2 = "I hear you take care of everyone, but who cares for the carer? If nobody's doing it, I could... Well, maybe my worries are unnecessary~",
	login = "I'm on day duty today~ Commander, were you expecting any... romantic developments?",
	detail = "Is work going okay? Your strategies working out? Heheheh, so you're doing just fine... Are you sure you want to tell me that? That means one less girl worrying about you~",
	couple_encourage = {
		{
			{
				10722,
				10723,
				10727,
				10729
			},
			1,
			" Okay, everyone! Attacking positions!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[107301] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "If you're worried about anything, try getting a little tipsy to forget about it! I'm with you, so I won't let any of the others see you drunk, okay? Heehee.",
	unlock = "Would you like me to recommend a drink? Hmm... You're quite the drinker, Commander~ Let's see if you can handle my favorite♪ Heehee!",
	touch2 = "Heehee, I might've drank a liiittle too much♥",
	mission = "Missions, huh~ I'm trying to open this drink, so can it wait a minute?",
	vote = "",
	drop_descrip = "Would you like me to recommend a drink? Hmm... You're quite the drinker, Commander~ Let's see if you can handle my favorite♪ Heehee!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Hahaha, you must love these uniforms, Commander~ Oh? No, you say? Are you suuure?|You're not bad at drinking~ Who trained you? ...The Northern Parliament girls? Well... That does make sense.|You want to sit next to me? Be my guest~ You've been drinking, so careful you don't fall... Whoa, whoa?! Th-thank you...",
	touch = "Commander, c'meeere~ Whoa, stop, stop♪ Haha, your face crashed into my finger~",
	voice_key_2 = -1,
	mission_complete = "Yaaaay♪ Good job finishing your missions~ As a reward from me... let's pop this one open~",
	battle = "",
	id = 107301,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Thank you for waiting, Commander. I've brought you my favorite drink. Mind if I fill two glasses? Of course I plan to drink with you~",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[107380] = {
	hp_warning = "Put out the fire! Please, hurry!",
	feeling3 = "Commander, no matter how pressed for time you may be, eating junk food will only impact your health negatively. Please, I urge you to have this more healthy sandwich I made.",
	mail = "You've received new mail. If you're short on time, you could consider having me read it out for you.",
	expedition = "A commission has been completed. Shall go and we receive the returning team?",
	win_mvp = "Shangri-La will forever be out of reach to the likes of you.",
	home = "The fleet has returned to port. Let us hold a tactical debriefing once everyone has had some time to rest.",
	unlock = "CV-38, Shangri-La, has arrived. I'd like to share the stories in this notebook with you someday... but first, let's concentrate on the task at hand.",
	touch2 = "Did you just perform a health examination on me?",
	mission = "We've received a mission from headquarters. I made note of it in our task list.",
	vote = "",
	drop_descrip = "Essex-class aircraft carrier – Shangri-La, Hull Number CV-38.",
	feeling4 = "*sigh*, I've asked you time and time again to be more health-conscious... Please, have this cup of saffron tea. It's good for you.",
	lose = "This wasn't... supposed to happen!",
	feeling1 = "You've been added to my confidential informee blacklist, Commander. Do keep that in mind.",
	skill = "Weather the storm and fight with all your might!",
	upgrade = "Thank you. I will repay your generosity with greater glory in battle.",
	propose = "I'd love to write down my feelings without a moment's delay, but a more important task is at hand: holding you in a close embrace. I, Shangri-La, will forever be with you, following you to the mystical land at the end of your journey.",
	feeling5 = "Did you know that the saffron flower symbolizes joy in floriography? To me, writing your biography, fighting by your side, and personally looking after you... That is the greatest joy of my life.",
	main = "Are you curious about these butterflies? Bugwatching is one of my hobbies, actually. I brought these darlings with me from Panama.|Anti-sub warfare? I'd love to try my hand at it, should the opportunity arise. Who knows, I may be surprisingly talented!|Ensuring you stay in good health is part of my job, Commander. I sincerely urge you to be careful so as to not overwork yourself.",
	touch = "Which story would you like to hear, Commander? The one about the undiscovered haven, or the wonderland beyond the horizon?",
	voice_key_2 = -1,
	mission_complete = "A mission has been completed. I wonder what our reward will be. Perhaps an unmanned recon aircraft?",
	battle = "Turn bow to the wind! We shall teach them the importance of freedom!",
	id = 107380,
	gift_dislike = "",
	gift_prefer = "Oh, could I ask you to hold it for me, Commander? I'd like to take a photograph of your gift as a memento.",
	profile = "My name, Shangri-La, has its origins in a famous operation from the war. Being an Essex-class, I've been all over the world and got to record a myriad of things and events in my notebook. This, to me, is my source of pride.",
	voice_key = 10738,
	headtouch = "My hair ornaments? They're a gift from Yat Sen; she said they go well with my name.",
	feeling2 = "Starting today, I will take notes on everything related to you, Commander.",
	login = "Welcome back, Commander. I recorded all the noteworthy events that took place while you were gone. Would you care to read about them?",
	detail = "I strictly follow the principle of divulging nothing to outsiders, but giving full disclosure to my superior officers.",
	couple_encourage = {
		{
			{
				10709
			},
			1,
			"Don't worry too much, I'm sure we will one day surpass Enterprise.",
			0
		},
		{
			{
				10707
			},
			1,
			"Would you mind lending me some aircraft, Miss... Umm, \"Miss Cowgirl\"?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[107381] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Did you come across a new specimen I could add to my collection, Commander? Hehehe~",
	unlock = "Commander, welcome to my \"Utopia.\" Here, you can find my prized collection. Now, where should we start our detailed tour?",
	touch2 = "Both specimens and girls alike must be treated delicately. Understood, Commander?",
	mission = "",
	vote = "",
	drop_descrip = "Commander, welcome to my \"Utopia.\" Here, you can find my prized collection. Now, where should we start our detailed tour?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "*yawn*... Oh, was I dozing off just now? Sorry for that, Commander. I just feel so relaxed when I'm with you... But thanks for lending me your shoulder to rest on. Hehehe~",
	main = "If the opportunity presents itself, I might just host my own exhibit. Perhaps I could call it... \"Caracal\"?|I wouldn't mind sharing some of my prized specimens with you, Commander. You'd take good care of them, wouldn't you?|*click*! Nice, a fine new addition to my photo collection. I name it... \"Fleet Commander, in Profile.\" Hehehe~",
	touch = "Would you like to learn how to pin a specimen, Commander?",
	voice_key_2 = -1,
