	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Welcome back, Commander. Let's warm you up with a nice, hot drink. Would you like coffee or hot cocoa?",
	detail = "This shawl you gave me is really cozy. Hehe, let's huddle up like this... There, now we share the warmth.",
	couple_encourage = {}
