_G.pg.base.ship_skin_words[108010] = {
	hp_warning = "Um... did they find our hiding place...?",
	feeling3 = "Maya really packs a punch... I suppose she just got careless that time. Well, it is the job of a submarine to catch people off guard.",
	mail = "Commander! Mail's here! Check if my torpedoes are here~!",
	expedition = "The commission fleet has returned! How nice, I'd love to go out and shoot some... Ah, no no, this is commissions that we're talking about! Commander? Heey~ Commander!",
	win_mvp = "Heheh~ how do ya like them torpedoes!",
	home = "Good work out there, Commander! Here's a torpedo for you! Huh, what's it for? For hugging of course - it'll help you sleep comfortably when you're tired!",
	unlock = "Hi~ are you my new commander? I'm Dace from the Eagle Union, reporting for duty. I believe in shooting torpedoes first, and asking questions later~",
	touch2 = "Torpedo volley! Locked on to Commander~!",
	mission = "Commander! Ah, um, do you have any missions that require some serious torpedo launching?",
	vote = "",
	drop_descrip = "Gato-class submarine - Dace (SS-247)",
	feeling4 = "Commander, won't you come see my torpedo show next time? If you're not there, I can't get hyped at all... so, promise you'll be there!",
	lose = "Let... Lemme shoot off a few more at least!",
	feeling1 = "You're banned from the Torpedo Lovers Club!",
	skill = "Torpedoes, laaaunch! Let 'em have it!",
	upgrade = "Commander, did you remember to prioritize upgrading the torpedoes first?",
	propose = "This is for me? Really? Ehehe~ I'm so happy! Commander, it's a promise, okay? In return, I promise that if you order me to shoot a torpedo in one direction, I won't also shoot them in every other direction! ",
	feeling5 = "Hmm... if I had to choose between Commander and my torpedoes... Urgh, there are a lot of torpedoes out there but only one Commander, so I suppose I'll pick Commander! Mmhmm, that's right!",
	main = "\"Dace's Torpedo Circus.\" It's always been a dream of mine to make that happen one day! |Commander, I'm going to give you a crash course on torpedoes! Trust me, you'll be fascinated! |Commander, wanna have some torpedo chocolate or torpedo bread? Here, have some, I made 'em myself!",
	touch = "Commander, have you ever seen a dozen torpedoes go off at once? Don't you think it'd make for an awesome light show?",
	voice_key_2 = -1,
	mission_complete = "Mission rewards-attached torpedoes, laaaaunch~! Commander, I'm not sure you'll be able to catch this one~!",
	battle = "Torpedoes locked, loaded, and ready to go~!",
	id = 108010,
	gift_dislike = "",
	gift_prefer = "Wow! Now that's what I call a torpedo! You totally get me, Commander!",
	profile = "The name's Dace! My three favorite things are torpedoes, torpedo launchers, and uh, more torpedoes! My class? Oh right, I'm a Gato-class... If I remember properly, one of my achievements included taking out that Maya fellow... wonder if she's around. ",
	voice_key = 10801,
	headtouch = "",
	feeling2 = "Today's a good day to shoot a bunch of torpedoes!",
	login = "Ah, Commander, good timing! Mind helping me pick up those torpedoes next to your feet~?",
	detail = "The gleam of the metal, the coolness to the touch, the distinctive splash, and of course, the explosion... Ahh, Commander, torpedoes are simply the best!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[108020] = {
	hp_warning = "Huh? Have they spotted me or something?",
	feeling3 = "My shoulders are so stiff after a long day of swimming... Oh, I have an idea! If a certain someone gives me a massage, I might just forget that really embarrassing thing they did!",
	mail = "You've got mail! Say \"pretty please\" and I'll give it to you~",
	expedition = "Commission complete! C'mon, let's go! We can't just sit here and keep 'em waiting forever!",
	win_mvp = "Hah hah! Easy peasy!",
	home = "Weeelcome back! ... Why's the paperwork been stacked into a pyramid? Gee, a strong wind must've done it~!",
	unlock = "Tadaaah! I'm Albacore, from the Eagle Union! Oh, did I jump out and scare you? Sorry 'bout that~! I'll be a member of the fleet from now on, so let's get along!",
	touch2 = "I wonder what'd happen to you if I were to scream for help right now... Wanna find out? Heheheh~",
	mission = "Give me a massage and I'll keep quiet about that time you slacked off~",
	vote = "",
	drop_descrip = "Gato-class submarine – Albacore, Hull Number SS-218.",
	feeling4 = "It's mean to mess with you all the time, so today, you'll get a nice, relaxing massage! ... *Phew*... Hey, you feeling something inside your ears? It's your fault for blindly trusting me like that!",
	lose = "Time to get outta heeeere!",
	feeling1 = "Jeeeeeeerk!",
	skill = "Surpriiiiiiiise!",
	upgrade = "Ooh! That's good!",
	propose = "Just claiming my ring. If that's all then I'm gonna get going now... What? You're not gonna stop me? I-I'm telling ya, I really will walk outta here! ... Fiiiine, you win! I admit it, I just can't be without you anymore!",
	feeling5 = "H-hey, listen... If some day I don't come back from the battlefield, would you... Ahahaha! Like that's ever happening! C'mere! I'm gonna tickle you senseless!",
	main = "So, who are you into, Commander? Come on, tell me~ It'll be a secret between us... At least for a while!|I'm SOOOOOO tireeeeed~! Lemme sit on your lap, Commander! ... Sweet! Thanks, friendo!|This? This is how I've always looked. Do ya like it? Let me guess... you're having naughty thoughts, aren'tcha~?",
	touch = "Oh, my! Not even submarines are safe from the Commander's evil clutches!",
	voice_key_2 = -1,
	mission_complete = "Sweet mission rewards! So, when am I getting my share?",
	battle = "Who's it gonna be next~? Teehee♪",
	id = 108020,
	gift_dislike = "",
	gift_prefer = "Oooh! Yeah, I'm taking that!",
	profile = "My achievements? Let's see... Oh, right! I sank Taihou! She shouldn't have sunk so easily, though... Actually, why DID she sink?",
	voice_key = 10802,
	headtouch = "",
	feeling2 = "You wonder what'd happen if you tick me off? I'd host something like a public exhibit of your greatest blunders!",
	login = "The Commander's back? Sweet, today's gonna be jam-packed with mischie... Err, I mean, time for work!",
	detail = "Hohoh, I must've caught your attention~ Let me guess... you like 'em young, don't you, Commander?",
	couple_encourage = {
		{
			{
				30707
			},
			1,
			"Ahaha... C'mon, let bygones be bygones, okay~?",
			0
		},
		{
			{
				10801
			},
			1,
			"Catshark attack!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[108021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Time to spice up Cavalla's drink with a little... Darnit, you caught me in the act, Commander... All I wanted to do was give it a more mature but alcohol-free taste!",
	unlock = "Oopsie! I totally just dropped something by mistake~! I'd better pick it up quick! Hmm? Saw something you shouldn't have, Commander? Hehehe~ That makes you my partner in crime now!",
	touch2 = "I wonder how people would look at you if I set off a firecracker right now... Wanna find out? Heheheh~",
	mission = "",
	vote = "",
	drop_descrip = "Oopsie! I totally just dropped something by mistake~! I'd better pick it up quick! Hmm? Saw something you shouldn't have, Commander? Hehehe~ That makes you my partner in crime now!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "L-listen, I'm really grateful that you hang out and let me mess around with you! I've got something important to say... Come here so I can whisper... C'mon, a little closer... *smooch*♡ Hah, got 'em! Expect much more teasing to come~",
	main = "Commander, you seen Taihou anywhere? I've got an explosive surprise for her!|Which do you like more: this dress, or my ordinary getup? Why do I even ask? Hehehe~ C'mon, don't be shy and answer the question~|Over here, Commander! You agreed to be my accomplice right when you caught wind of my plan, so you've gotta follow me around the whole day~",
	touch = "You're gonna dig up location info under the guise of dancing with someone? Hey, pretty good idea! Huh? You just wanna dance? With me?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 108021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "How about a... KAPOW! Gave you a real scare, didn't I? Teehee~ Turned out pretty good, if I say so myself~",
	detail = "You wanna warn people about my firecrackers? Hehehe~ By all means, go ahead~ But how exactly are you gonna explain knowing that I had 'em hidden under my dress~? You get where I'm going with this, don'tcha? Hehehe~",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[108022] = {
