_G.pg.base.ship_skin_words[108030] = {
	hp_warning = "I won't give up, no matter how bad it gets!",
	feeling3 = "Sometimes, courage alone isn't enough... And that's when I need your strength, Commander! With your instructions, we can overcome anything!",
	mail = "A new message has arrived! Wonder if it's from one of my submarine friends!",
	expedition = "The commission team has returned safely!",
	win_mvp = "You can thank Cavalla for this victory! Hehehe~",
	home = "Commander, if you need the expertise of a submarine, just call on Cavalla!",
	unlock = "I'm Cavalla, the Eagle Union submarine! I'll make this fleet famous through glorious victories, so just you wait, Commander!",
	touch2 = "I-I'll have you arrested!",
	mission = "Do we get a boatload of rewards if we do these missions?",
	vote = "",
	drop_descrip = "Gato-class submarine – Cavalla, Hull Number SS-244.",
	feeling4 = "I've been feeling sick lately... I can't fight with the same flair as I used to when I think about you... That's it, it's gotta be your fault, Commander! ... Actually, I'm not so sure...",
	lose = "Bah... This happened just cause the sea is so salty...",
	feeling1 = "I hate you!",
	skill = "I've been waiting for this chance!",
	upgrade = "I feel stronger! Heheh!",
	propose = "Whuah! Hold on a sec! Why are you hugging me out of the blue?! What are you doing?! You call this \"weight training\"? A-are you kidding me?! Everyone's staring at us, so let go already!",
	feeling5 = "I had a dream where you carried me and walked around the port... It was really weird! But for some strange reason, it makes me feel happy... I wonder why...",
	main = "Could we make submarines stronger? By, for example... giving them stronger, better weapons or something?|It's so boring to just sit here and twiddle my thumbs... Give me something to do, Commander!|Whew! The breeze feels almost as good on land as it does at sea!",
	touch = "Ahahaha~! Stop! Ahahah~! That tickles– ahahaha!",
	voice_key_2 = -1,
	mission_complete = "Ooh! A boatload of rewards! Let's treat ourselves, Commander!",
	battle = "Give me strength, my friends!",
	id = 108030,
	gift_dislike = "",
	gift_prefer = "I love this!",
	profile = "I was given a golden opportunity during my maiden voyage and sank a carrier! ... It was a pretty risky move, and it wasn't easy! But in the end, I came out on top! If you wanna hear the whole story, just ask!",
	voice_key = 10803,
	headtouch = "",
	feeling2 = "Fear of failure can be overcome by showing your courage!",
	login = "Morning! You're right on time today!",
	detail = "I'm no fish out of water that can't fight on the surface! It's no problem for me!",
	couple_encourage = {
		{
			{
				10802
			},
			1,
			"Let's see who of us is the strongest!",
			0
		}
	}
}


