_G.pg.base.ship_skin_words[108040] = {
	hp_warning = "Oh dang, oh shoot!",
	feeling3 = "There you are, Commander! Come here! ...What's wrong with me hugging you? Am I holding you too tight? That's not it? Then what is it?",
	mail = "Is this mail for Bluegill? Oh, it's addressed to the Commander...",
	expedition = "Commander, the rewards from that commission have arrived!",
	win_mvp = "I hereby name this victory \"The Battle of Bluegill\"! ",
	home = "Good job, Commander! Come here!",
	unlock = "I've finally found one! My own commander! ...Hehehe, from now on, you're Bluegill's commander!",
	touch2 = "Whoa, whoa! Commander! You've kinda crossed a line here!",
	mission = "Commander, if you're heading out for a patrol, why not take Bluegill with you? It might be good to have me!",
	vote = "",
	drop_descrip = "Gato-class submarine – Bluegill, Hull Number SS-242.",
	feeling4 = "I figured out why my hugs bother you! It's because it feels embarrassing, right? Well, don't worry about that! I asked around, and nobody thinks less of you for it! ...W-was I wrong?",
	lose = "They nearly got us... But it won't go the same way next time!",
	feeling1 = "It's okay! You just need to bask in the sunshine for a bit, and your troubles will surely all go away!",
	skill = "Bluegill, comin' at ya!",
	upgrade = "Wooo! Wow, I've really gotten nimbler!",
	propose = "Can I hug you now, Commander?! Yay! Sharing a hug with you just feels like total bliss~ Hehehe~ Stay put, I wanna enjoy our embrace a little longer!",
	feeling5 = "So my hugs really put you in a pickle, huh, Commander... I'm sorry for that! I can't help it, I just feel super, *super* happy when I hug you! Hey, what if I wait with my hugs until you say you're ready? Okey-dokey! Just tell me whenever you want one!",
	main = "Sunny days are always good swimming days!|Hey, that's not a blank sheet, that's Bluegill's personal file on the back! Look! I wrote the whole thing myself!|How long are you gonna have a staredown with your desk, Commander? C'mon, let's catch a break!",
	touch = "You want a fight with me? You asked for it! Take *this*! Blue knockout punch!",
	voice_key_2 = -1,
	mission_complete = "Mission complete! Now it's time for a swim! ...Huh? Too early for a swim? But why?",
	battle = "Bluegill, setting out!",
	id = 108040,
	gift_dislike = "",
	gift_prefer = "Heheh, this belongs to Bluegill now!",
	profile = "I'm Bluegill, Gato-class submarine. I saw action all over the sea and gave my enemies a real scare. Hehe, I'll shine on at this port, too!",
	voice_key = 10804,
	headtouch = "",
	feeling2 = "Bluegills are, in fact, a type of sunfish! ...You knew that? Welp, and here I was hoping to tell you a surprising fact.",
	login = "Welcome back, Commander! Let's part these curtains, like... This! Hehe, now the sun's gleam reaches in here too!",
	detail = "I wonder if there's a way to become friends with Yuubari, that girl cooped up in the science department...",
	couple_encourage = {
		{
			{
				30201
			},
			1,
			"Whoa, is that a new piece of gear?!",
			0
		},
		{
			{
				10801,
				10802,
				10803
			},
			1,
			"Gato-class, let's go!",
			0
		}
	}
}


