_G.pg.base.ship_skin_words[108050] = {
	hp_warning = "Oh shoot, I screwed up!",
	feeling3 = "Hey, is that for me, Commander? Aww, how nice of you~ In return, I'll keep quiet about how you were ogling us while we practiced~",
	mail = "Uh, Tashkent, where's the Commander's mail? ...Oh, hi, Commander! No, just talking to myself!",
	expedition = "Teehee! I get this feeling like the commission team is about to enjoy a surprise concert!",
	win_mvp = "Encore! Encore until our next encounter!",
	home = "Your next line is, \"Why is Albacore prompting me to speak?\"",
	unlock = "Lights! Camera! Albacore! Ahaha, don't worry about it, I'm just getting fired up over here! Oh, did you come up with a better idea? Tell me, tell me~",
	touch2 = "I wonder what'd happen to you if I were to scream \"I'm being molested!\" right now... Wanna find out? Heheheh~",
	mission = "We've got new job offerinos!",
	vote = "",
	drop_descrip = "Lights! Camera! Albacore! Ahaha, don't worry about it, I'm just getting fired up over here! Oh, did you come up with a better idea? Tell me, tell me~",
	feeling4 = "Oh, Commander! Morniiing! Did you see the note I left about a date? It's your job as the producer to see to our personal needs, y'know~ I'll write down whoever else wants one, so be sure to give it a look~",
	lose = "Welp... I've got one final ace up my sleeve!",
	feeling1 = "You're really ruining it for the other members, you know that?",
	skill = "Let's make some noooooise!",
	upgrade = "My idol rank has gone up!",
	propose = "Say what? Idols aren't allowed to be in relationships? Yeah, well, I was a shipgirl before I became an idol, so it's all fine! This pretty little ring is mine now~ As are you, Commander~",
	feeling5 = "I want to be your center-stage idol that dazzles the audience, Commander! Heh, just kidding! Our WHOLE unit has to reach stardom together, after all. Hehehe~",
	main = "Surprise! How's my new stage prop look?|Most of the stuff we're wearing was brilliantly handmade by Dido! Curious about that doll she's got, though. What's it represent?|I wanna see Taihou's concern in person! We should totally set some time aside for that!",
	touch = "I wouldn't be here without your support!",
	voice_key_2 = -1,
	mission_complete = "Job donesy-done! Whew, I'm pooped.",
	battle = "Trap set! Let's goooo!",
	id = 108050,
	gift_dislike = "",
	gift_prefer = "Yippee and yahoo! Guess I'm just overjoyed!",
	profile = "Here comes Albacore, submarine-slash-idol! I'm unique, I'm in the groove, so make some noise as I perform for you! Vocals, dancing, you name it, I can do it!",
	voice_key = 10805,
	headtouch = "",
	feeling2 = "Being an idol's pretty good! I get to sing, dance, and smile for a massive audience! ...That sounds nothing like what I'd enjoy? Really, huh?",
	login = "Morning there, P! Let's make the most of today!",
	detail = "My new gig must leave me with little time to play pranks? Haha, my friend, a true idol can perform AND play pranks, too! If you want an example, look no further than Sara!",
	couple_encourage = {
		{
			{
				30711
			},
			1,
			"Yo, Taihou! How about a duo performance?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[108060] = {
	hp_warning = "What a pain in the ass...",
	feeling3 = "It feels soooo good to sneak between that sleeping fox's tails and floof them~ Though I'll admit, it's not cool to disturb someone's sleep like that. Ahaha~",
	mail = "New mail? Could I have a look at it? I'll have to get real, real close to do it~",
	expedition = "Commission goodies, coming in! If I bring them to you, will you gimme YOUR goodies? Ahaha~♪",
	win_mvp = "This is just par for the course when you sortie me~",
	home = "Welcome back home, daaaarlin'~ Ahah! Look at you blushing again! Hahahaha!",
