_G.pg.base.ship_skin_words[108080] = {
	hp_warning = "This is nothing! Hmph!",
	feeling3 = "I often visit the aquarium when I have time. It's so quiet and peaceful there underwater, compared to the sea. And it's so calming to watch the fishies blow bubbles.",
	mail = "Excuse me! Commander, there's a new letter for you.",
	expedition = "The commission team is back, and it looks like they brought a biiig pile of stuff with them.",
	win_mvp = "What a perfect sinking... *sniffle*... Heehee.",
	home = "I guess your foes didn't give you much trouble. Phew... That's a relief.",
	unlock = "Hello, Commander. I'm the Gato-class submarine Flasher, SS-249... *sniffle*... I-I'm crying because... w-well, not because I'm sick or scared or anything. It's just that I... *sob*... shed tears when I'm moved.",
	touch2 = "*whimper*... Sh-should we really be doing this?",
	mission = "A new mission... Are you gonna do it now, Commander?",
	vote = "",
	drop_descrip = "Gato-class submarine – Flasher, Hull Number SS-249.",
	feeling4 = "Commander, your uniform's second button from the top is a little loose... You'll let me replace it? Well, I don't have a sewing kit on me right now, and I promise I wasn't after your button, and... *whimper*...",
	lose = "Waaahh! We lost... But next time, victory will be mine!",
	feeling1 = "Target sighted! Umm... So... I-I'll be on my way now, Commander.",
	skill = "You're not getting away!",
	upgrade = "You really care about me... Thank you!",
	propose = "Gosh, you're taking this so seriously... D-don't get me wrong, I am happy, I just don't know how to... *whimper*... N-now I'm in tears... *sob*... I'm so happy... I'll be with you forever and ever!",
	feeling5 = "Heehee. I'm making a plushie, Commander. Look! This is a seal, and this one is... Huh? You've seen this button before? Well, yeah, you gave it to me... I'm making a plushie of you so you can always be with me.",
	main = "I hate arguments because I always cry before I even say anything, even when I've come up with a retort... *sob*...|Everyone here is so nice. Whenever something happens between me and my friends, we settle it peacefully. They even apologize even when I did something wrong... *sniffle*... Why are they THAT nice?|I make cosplay clothes for people when I'm not fighting. Commander, do you... have a character you wanna cosplay? I can... *sniffle*... make their outfit for you.",
	touch = "Your touch makes me happy... Ow! I forgot I was holding a needle! Waahhh! I pricked my finger! *whimper*...",
	voice_key_2 = -1,
	mission_complete = "Mission completifications! They even gave us some goodies. Whoa! A lot of them, actually!",
	battle = "If you think you can run, think again!",
	id = 108080,
	gift_dislike = "",
	gift_prefer = "I'm gonna sew a bag to put this present in!",
	profile = "I'm Flasher, Gato-class submarine. I cry a lot, but... *sniffle*... it's not... *whimper*... I-it's not because I'm a wimp or anything. When it comes to a fight, I've got you alright!",
	voice_key = 10808,
	headtouch = "I don't mind it if you pat a little more. Mhm. Thanks.",
	feeling2 = "Wow... You complimented me! Heehee... I only did my job, but still. Heehee... I'm kind of humbled. *sniffle*...",
	login = "Good morning, Commander. It's a lovely day today. Can we go hunt some enemies?",
	detail = "I did the frills and the appliqué on my clothes. I even made this sunfish plushie! I'll aaalways be safe as long as I have it with me, and it'll never get scared and run away.",
	couple_encourage = {
		{
			{
				10802,
				10804,
				10803,
				10801
			},
			1,
			" Group up, and let's all howl like wolves!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[108081] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "There! I totally nailed that order! Heehee...",
	home = "Welcome back! Have a drink to take the edge off!",
	unlock = "W-welcome, Commander... I-I as the manager will be serving you today, so l-let's hear your order... *sniffle*... I'm so tense it's making me cry...",
	touch2 = "Waahhh! I-I'm gonna drop the receipt!",
	mission = "",
	vote = "",
	drop_descrip = "W-welcome, Commander... I-I as the manager will be serving you today, so l-let's hear your order... *sniffle*... I'm so tense it's making me cry...",
	feeling4 = "",
	lose = "Waahhh... I-I got it wrong...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Heehee, I'm so happy to be with you. *sniffle*... B-but you've got work, so you should get going... It'll be fine? And you can be with me more than the usual today? Oh, that's great!",
	main = "Let's hear your order, Commander! ...Wh-whatever I want to have? A mango sundae, a parfait, and... W-wait, no! I'm supposed to be taking YOUR order!|Thanks, but I can bring it out myself... Hm? It's right for a manager to accept a customer's help? I-is it, really?|Heehee. I'm actually quite good at math, so don't you worry! I can man the register just fine, too. Your total comes to... Yup, just what I thought!",
