_G.pg.base.ship_skin_words[118022] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission team? So you're saying you'll help me AFTER you've gone and greeted them, right? No problem♪",
	win_mvp = "",
	home = "Welcome back, Commander! My feet are getting kinda numb here... Be a darling and come help me! Getting a little massage would be sweet, too!",
	unlock = "Kunoichi Guam, arriving in style! Brought to you live, this episode features a ninja with zero ninjutsu knowledge trying to enter the Commander's room to– Aaahhhh! Owch... This infiltration mechanism's so hard to use... No, wait, Commander, don't stop the camera! Little accidents are just part of a variety show♪",
	touch2 = "Ahaha♡ Are we heading in a sexy direction after all?",
	mission = "",
	vote = "",
	drop_descrip = "Kunoichi Guam, arriving in style! Brought to you live, this episode features a ninja with zero ninjutsu knowledge trying to enter the Commander's room to– Aaahhhh! Owch... This infiltration mechanism's so hard to use... No, wait, Commander, don't stop the camera! Little accidents are just part of a variety show♪",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Hm? When you REALLY think about it, I'm no professional kunoichi! And who cares if I make an oopsie once in a while? Besides, handling a little accident is what I do best as a multitalented presenter! And if I fail a mission, I'll just use my ultimate skill – Direct Declaration of Love! I love you, Commander!",
	main = "\"Try figuring it out on my own first\"? Look, Commander, I may be multitalented, but even I have limits on what I can and can't do!|The beautiful kunoichi Guam's in a real pickle! Now the Commander's gonna interrogate her! ...You reckon I should just play it straight in this case? Alright, then how are you gonna punish me for showing up out of nowhere, huh? Heehee♪|Chill, it's fine! Sure, some inappropriate parts might be showing, but it's all good as long as we have fun... right?",
	touch = "Oh, no, my clothes... Hey, you can't show this on TV!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 118022,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "This is kunoichi Guam, sneaking right into the Commander's room and– Aaahhh! M-my custom-made outfit got caught on something!",
	detail = "How would Dandy Siego get out of this sticky situation? Think, Guam, think... Wait, no, Dandy wouldn't think at all in this case! I'm screwed!",
	couple_encourage = {}
}


