_G.pg.base.ship_skin_words[137031] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "I will be your dance partner tonight, Commander!",
	home = "Great job! Nobody saw you when you snuck out, right? Although, it's no biggie even if somebody did.",
	unlock = "Tadah! Make way for the ladylike Sara in a gorgeous dress! Heh, I'm really surprised you found my secret spot this quickly. For that, you get a special reward – a lovely one-on-one with the lovely Sara!",
	touch2 = "Heheh! Two can play at that game when nobody else is around!",
	mission = "Hang on, did you abandon your missions just to meet me in secret? Umm, I'm kiiind of not a fan of you doing that.",
	vote = "拉票描述",
	drop_descrip = "Tadah! Make way for the ladylike Sara in a gorgeous dress! Heh, I'm really surprised you found my secret spot this quickly. For that, you get a special reward – a lovely one-on-one with the lovely Sara!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Commander, come closer– Whoa! H-hey! Don't surprise me like that! Fine, if you want it that way! Close your eyes! I'm gonna surprise you right back!",
	main = "How do you like this relaxation spot I picked, Commander? Pretty tasteful, right? Heehee. Seeing the glimmer of the morning sun really clears my mind!|Any thoughts on my dress, Commander? Heehee, I think black looks better on me than any other color.|How I'm going to prank you, you ask? Heheh, making someone think you're gonna prank them then doing nothing is a valid kind of prank!",
	touch = "Commander, do you wanna dance with me?",
	voice_key_2 = -1,
	mission_complete = "Did you finish all your missions before you came to see me? Wow! You've earned yourself a bonus kiss! *smooch*",
	battle = "",
	id = 137031,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
