_G.pg.base.ship_skin_words[137061] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "The smell of a freshly rained-on forest is so refreshing and relaxing. Say, Commander, how about we take a little walk together?",
	unlock = "Oh, Commander? Sorry you have to see me like this – I overheated a little in the bath... Hm? You smell like nature... It's nice.",
	touch2 = "I-is it just me, or is it getting hot in here...?",
	mission = "",
	vote = "",
	drop_descrip = "Oh, Commander? Sorry you have to see me like this – I overheated a little in the bath... Hm? You smell like nature... It's nice.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Crazy to think that I can really live a life like this. Relaxing in the hot spring, letting my body and soul cool down... I only get to do all of this because you're here. That's all I need to know to keep on persevering.",
	main = "They say the smell of oranges can cure dizziness. It's soothing, that's for sure. Oh, you brought me some? Thanks.|Commander, I've cooled down a bit, and the water's just right. Still a little hot... Maybe I'll take a shower to chill out a little more.|Be careful. The water pressure in the shower is – C-Commander?! Haha... You're soaked!",
	touch = "I smell like oranges? Heheh, want one?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 137061,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "There's something so relaxing about a nice hot spring bath in the woods once in a while... Hm? Oh, man... My top came undone?!",
	detail = "I'm feeling a little unmotivated after being in here so long... Phew, it's nice to get time to relax for once. This peace is what I've been fighting for all this time.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[137090] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Have you checked out the track already? Hmm, there's something wrong with the third downhill... I'll take note of that. Take a good break and leave the rest to me!",
