	expedition = "Commander, the girls out for commissions have returned! How about we greet them? Come on, hurry up~",
	win_mvp = "Ehehe, Commander, pat my head~",
	home = "Commander, good work out there~! *nuzzle*",
	unlock = "I finally got a chance to meet you, Commander! I'm B class' Beagle! The best of what I can do are escort missions! If you need my help just let me know! I am quite a worker!",
	touch2 = "Eeek! Commander, you perv...",
	mission = "Commander, there's a new mission!",
	vote = "",
	drop_descrip = "B-class destroyer ー Beagle, Hull Number H30!",
	feeling4 = "Commander, how about a walk? ...Walk by yourself? No no, it's not fun having a walk alone! I'm walking with you, Commander! Commander~ walk with me~!",
	lose = "*cries*... I lost...",
	feeling1 = "Commander... do you hate me...?",
	skill = "For the Commander!",
	upgrade = "For your sake, Commander, I'm gonna work harder!",
	propose = "Are you fine with giving me this...? Yes... I got it! Then for you, Commander, I'm gonna work extra, extra hard! Ehehe, I'm getting motivated!",
	feeling5 = "Commander, is there something I can do? Anything is alright, you know? You see, I'm happy being of use to you, Commander!",
	main = "Eh?! Y-You want to catch a rabbit? ...I don't get it, but for you, Commander, I'll give it a try!|Commander, what a nice weather today~ Let's take a walk, alright?|Hmm? Now that I think about it, I used to go to a lot of different places. ...Ah, Commander, I'll tell you all sorts of things about the places I have been to!",
	touch = "Ehehe, that tickles, Commander!",
	voice_key_2 = -1,
	mission_complete = "Commander, I brought the mission rewards~",
	battle = "Beagle, tally ho!",
	id = 201060,
	gift_dislike = "",
	gift_prefer = "Yay! I like this! Thank you, Commander!",
	profile = "Self introduction? Huh... I didn't accomplish much, but I took part in many escort missions, you know? Norway, Atlantic, Operation Torch, and then... Anyway, a lot of those! It will be nice if I can be of help, Commander!",
	voice_key = 20106,
	headtouch = "",
	feeling2 = "I'm full of energy today, Commander!",
	login = "Welcome back, Commander!",
	detail = "Commander, want to hang out together?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[201070] = {
	hp_warning = "",
	feeling3 = "There used to be 4 Single Barrels. Lil' A and Lil Y were retired because of submarine fighting, so now I'm left with Lil' B and Lil' X... I feel... a little bit lonely",
