_G.pg.base.ship_skin_words[201149] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Wahaha! My glorious new gear scared the daylights out of the commission team, so they brought back tons of tribute!",
	win_mvp = "",
	home = "Tadaaah! Here comes a special post-retrofit surprise from me, Glowworm! A big hug that's even warmer than you're used to!",
	unlock = "Hullo! Royal Navy G-class destroyer, Glowworm, has finished retrofitting! Heheh! I'm ultra-super strong now! You ready to be overwhelmed by the sheer positive energy inside me, Commander?",
	touch2 = "Headbutt gigamax! Double the damage!",
	mission = "Wahahaha! I, Glowworm, have become a super destroyer able to finish all these missions in a flash!",
	vote = "",
	drop_descrip = "Hullo! Royal Navy G-class destroyer, Glowworm, has finished retrofitting! Heheh! I'm ultra-super strong now! You ready to be overwhelmed by the sheer positive energy inside me, Commander?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Ahem! Dummy Commander! Sure, I'm stronger now, but my favourite thing in the world is still... you! Y-O-U! You, Commander! Heehee! Now suck on this headbutt of love from me, Glowworm!",
	main = "Yahoo! Have a taste of my upgraded Glowworm attack! ...Gah! I got too excited and stubbed my toe... It's fine, it doesn't hurt at all!|Heehee, Commander, do you wanna feel my glorious new gear? It's pretty awesome, but not as awesome as me, Glowworm!|Wanna play hide-and-seek before you start working? If you find me, I'll behave for the whole day, I promise! ...Huh?! No play? Why not?!",
	touch = "Whoa, hey! Th-that tickles! I think getting my retrofit made me more ticklish...",
	voice_key_2 = -1,
	mission_complete = "Heheh! Mission rewards, mission rewards! You couldn't have done it without me, so let's hear a \"thank you\"!",
	battle = "",
	id = 201149,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Heh, if you pat my head, it's gonna make my super Glowworm energy go boom! ...I'm kidding! Don't stop, keep patting it!",
	feeling2 = "",
	login = "Whoa! You're sooo late, Commander! I would've smashed your office door wide open with my new gear if you'd taken another moment!",
	detail = "Commander, Commander, I, Glowworm, have grown so strong I won't get sick from spinning around! I can even spin while doing a handstand! Want me to show you?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[201150] = {
	hp_warning = "Where does their strength come from?!",
	feeling3 = "I had a dream last night... You agreed to spar with me, and then... I lost to you 149 times! You were unbelievably strong...",
	mail = "Oh, you have new mail. I'll go get it.",
	expedition = "It's getting lively over there... Do you think the commission team is home?",
	win_mvp = "Heheh! Everyone's sure to notice this!",
	home = "Welcome back, Commander! HEY, Griffy, don't go clinging to the Commander all the time! You're being annoying!",
	unlock = "Royal knight in training, Griffin, reporting for duty! Whoa, Griffy, what's got you all excited? Is it the Commander's powerful aura, or... Ack! Quit struggling, or you'll fall out of my hat!",
	touch2 = "Hyah?! G-Griffy's watching!",
	mission = "Commander, your work isn't done yet... Huh? You wanna let me do it? Okay, I'll go right away! This must be your way of imparting secret knowledge to me!",
	vote = "",
	drop_descrip = "G-class destroyer – Griffin.",
	feeling4 = "I think I've figured out the secret behind your strength... Huh? There is no secret?",
	lose = "*sob*... The enemies are too strong... I underestimated them.",
	feeling1 = "C-Commander, you're getting weaker by the second... Get a hold of yourself!",
	skill = "With sharp fangs and pointy beaks!",
	upgrade = "Another step closer to knighthood!",
	propose = "I've earned your recognition... without even formally becoming a knight? ...Yes, I'd be happy to! I'll protect you for the rest of my life, Commander!",
	feeling5 = "I heard that you can get stronger by forging bonds with strong warriors... That means I'll be a full-fledged knight in no time!",
	main = "Commander! I just saw a praying mantis attacking, and I noticed its incredible strength! If it was as big as me, I think it would be invincible!|Griffy may be sweet when you're holding her, but normally, she's only that calm around adult griffins... Does that mean your strength rivals – no, outstrips – an adult griffin?!|How did you train to get so strong? ...By just sitting at your desk and working? No, you must have dumbbells hidden under there, or something...",
	touch = "What's this? You wanna see which one of us is stronger?!",
	voice_key_2 = -1,
	mission_complete = "Wow! You cleared such a difficult mission that fast? You're amazing, Commander!",
	battle = "Apprentice Royal Knight Griffin, ready and raring to go!",
	id = 201150,
	gift_dislike = "",
	gift_prefer = "Is this for me? Thanks... Hey, Griffy! Give that back! No taking my things!",
	profile = "I'm Griffin, a Royal Navy G-class destroyer and Royal Knight in training. And in my hat, we have my best friend, Griffy. Hmm? What about the ones in my shield? I haven't given them names yet... I was thinking of going with Loyalty, Hope, and Love, but they don't really feel right.",
	voice_key = 20115,
	headtouch = "You think I'm doing a good job...? Hehehe!",
	feeling2 = "Glowworm told me that you can even block her headbutts with ease... I can't believe it! You're way too strong!",
	login = "Zzz... Hmm? Commander...? I-I'm not slacking off! Griffy took my shield and flew off, so I couldn't train anyway!",
	detail = "Commander, I came up with a great way to train. I take my shield, and... Haaah! Phew, throwing it up high is a great arm workout, right? A-ahem... Griffy, get my shield for me!",
	couple_encourage = {
		{
			{
				20113,
				20139,
				20114
			},
			1,
			" Let's show them our hot-blooded combo attack!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[201151] = {
