_G.pg.base.ship_skin_words[201250] = {
	hp_warning = "",
	feeling3 = "There is one thing I want to set straight with you; I'm not foul-mouthed, I simply say what's on my mind. For instance... do you have a thing for little children?",
	mail = "Your mail, Commander. Don't forget to read it.",
	expedition = "Commander, a commission is done. You haven't forgotten about it, have you?",
	win_mvp = "This is the might of the J class! Regret your own carelessness!",
	home = "Don't overexert yourself after returning from the battlefield. Relax.",
	unlock = "Are you the Commander? My name is Jersey, and don't you forget it.",
	touch2 = "C-Commander?! I-I-I appreciate your straightforwardness, but now isn't the time...",
	mission = "Stop pretending like you haven't seen the new missions and get them done already.",
	vote = "",
	drop_descrip = "J-class destroyer – Jersey (F72.)",
	feeling4 = "But that's all right. You may fancy me if you like, but if you don't, then it's... not *not* a problem...",
	lose = "Ugh... You will pay dearly for staining my dress! Know this!",
	feeling1 = "You are a halfhearted and lousy individual.",
	skill = "Now's not the time to be taking it easy!",
	upgrade = "I will not let your efforts go to waste.",
	propose = "Now that I think about it, we've been so straightforward that we've not even done anything romantic... But now at least we know each other better than anyone else. I say we let romance into our lives starting today.",
	feeling5 = "Commander, I'm a straightforward person, and I'd like my partner to be as well. So be open-hearted and simply say what's on your mind. In return, I will be sincere with you as well.",
	main = "I hate it when others underestimate me because of my size!|No one knows what's on a person's mind if they don't say it aloud. I do not like people who are roundabout.|I wish you would compliment me for being honest, rather than for being \"cute.\" Not that I mind compliments like that.",
	touch = "What, you want to nuzzle against my lap? You can keep your fantasies in your dreams where they belong.",
	voice_key_2 = -1,
	mission_complete = "Commander, our rewards have arrived. Well done, I say.",
	battle = "We must face our enemies seriously, no matter who they are.",
	id = 201250,
	gift_dislike = "",
	gift_prefer = "I have been wanting one of these. I'm very grateful.",
	profile = "I'm Jersey, of the J class. While I have neither noble blood nor a particularly outstanding combat record, my personality is what it is, so spare me your complaints. What happened in Malta was just a slipup. But, admittedly, mistakes are mistakes. That much I know.",
	voice_key = 20125,
	headtouch = "",
	feeling2 = "Commander, while we're not that familiar with each other, I wouldn't take issue with having tea and chatting with you.",
	login = "Do you know how long you've kept me waiting, Commander? What's the meaning of this?",
	detail = "Do you need anything? Or are you just here to chat?",
	couple_encourage = {
		{
			{
				20121
			},
			1,
			"Everyone, try to keep up!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[201260] = {
	hp_warning = "",
	feeling3 = "Duke of York is tough, cool, and... Hehe~ She must make you jealous, too~",
	mail = "I'll go and get your mail~!",
	expedition = "I hope I can go on a safe transport mission together with you, Commander...",
	win_mvp = "Time for a photo~! C'mon, let's take a picture!",
	home = "I like it better when you're here, it makes me feel at ease...",
	unlock = "We meet at last, Commander! I am Matchless, an M-class Destroyer! Ah, although my name is \"Matchless,\" I'm actually very weak. Ehe~ Commander, will you protect me?",
	touch2 = "Because of that... I'm subtracting a few points off your record~!",
	mission = "I-I'm scared... I want to stay with you...",
	vote = "",
	drop_descrip = "M-class destroyer – Matchless (G52.)",
	feeling4 = "The feelings I have for you, and the feelings you have for me... Which of the two is more passionate?",
	lose = "S-someone, help meeee!",
	feeling1 = "I should've known... You can't possibly protect me...",
	skill = "Okay! Now close your eyes~!",
	upgrade = "Maybe you got stronger too, Commander?",
	propose = "Aww... I'm so happy... Thank you... Commander, I may not be able to protect you, but I'll do everything I can to protect your smile and warm your heart! Please, Commander, be happy!",
	feeling5 = "Physical scars heal over time, but mental scars never go away. So, please, don't make my heart ache!",
	main = "You know flattery won't get you anywhere with me, right?|Oh dear, it's getting cold again... Commander, can you lend me your coat when we leave port?|I hope I can just stay as your secretary forever... Hm? What? I didn't say anything!",
	touch = "Can I just stay with you forever, Commander?",
	voice_key_2 = -1,
	mission_complete = "You look so awesome from behind, Commander!",
	battle = "I-I'll try to stay where the Commander can protect me!",
	id = 201260,
	gift_dislike = "",
	gift_prefer = "So warm...",
	profile = "I'm Matchless, a Royal Navy M-class destroyer! After my escort missions in the Arctic, I was in the Battle of the North Cape, and then I helped escort Queen Mary! My name makes me sound powerful, but in reality, I'm totally helpless!",
	voice_key = 20126,
	headtouch = "",
	feeling2 = "My name might make me seem invincible, but that's not true at all. Don't mistake me for a Main Fleet ship just because of my name!",
	login = "You look sad, Commander... Let's try this... Hehe~ Feel better?",
	detail = "Everyone has someone they want to protect... So don't protect just me, okay, Commander?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[201261] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Commander, today, you're going to be escorting me full-time. You'll lose points if you let your attention wander~",
	unlock = "Ah, Commander, over here! Hm, you're going to take care of all the plans for today's date? In that case, I look forward to seeing just how suave you can be! Hehe~",
	touch2 = "Commander, I'm going to give you a big fat zero on today's performance.",
	mission = "",
	vote = "",
	drop_descrip = "Ah, Commander, over here! Hm, you're going to take care of all the plans for today's date? In that case, I look forward to seeing just how suave you can be! Hehe~",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Commander, stick out your arms~ Yeah, just like that! Huuug! Hehe~ ...Hm? It's hard to hold that posture? None of my business~ You should be able to endure it for my sake, right~?",
	main = "If some questionable individuals suddenly showed up, you'd be there to protect me, right? |Hmm... it feels like someone is always staring at me... is it just my imagination?|Haven't decided on where to go yet? That's totally fine, I'm happy to just have you here.",
	touch = "Commander, you're in charge of all the bags! Do your best for me, all right~? ",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 201261,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Oh you, Commander, you're going to lose points for keeping a girl waiting! Hehe, just kidding! I arrived a bit too early~",
	detail = "Commander, the super-luxurious ice cream crepes you bought are soooo good! Thanks! ...That's right, you should try some too. Come on, don't be shy, open up~",
	couple_encourage = {}
