_G.pg.base.ship_skin_words[201270] = {
	hp_warning = "",
	feeling3 = "I always have tons of fun hanging out with you!",
	mail = "Heehee~! See? I told you something nice would happen today!",
	expedition = "Wooow! Look at those mission rewards! We could fill a bathtub with all this oil!",
	win_mvp = "I'm gonna punch a hole straight through your heart~! Heheh, I've always wanted to say that!",
	home = "Take a gander at my new marching act, Commander! Relax, I'm only using blanks this time!",
	unlock = "I am the M-class Destroyer, Musketeer! Hehe... I knew something good was going to happen today~ Commander, can you point me to where the port is? Here? Or over here?!",
	touch2 = "It's not like I *dislike* it, but... Yeah, I actually don't dislike it!",
	mission = "Finish them all in one go!",
	vote = "",
	drop_descrip = "M-class destroyer – Musketeer (G86.)",
	feeling4 = "We should all forget our worries and live to have fun! Don't you think so too, Commander?",
	lose = "Time to make a sneaky exit~♫",
	feeling1 = "Come on... Return to your former self, Commander...",
	skill = "Locked and loaded~! Ready to fire!",
	upgrade = "Take aim~! Fire! Bang!",
	propose = "Thank you, Commander! This is the best thing I've ever gotten! Hey, tell me: have I given you some good memories, too?",
	feeling5 = "So much has happened since we first met... But I haven't changed a bit!",
	main = "Something nice is gonna happen today~ That's what I'm feeling!|Why am I always smiling? Hehehe, because I've been having so much fun ever since I came here!|The injuries I've sustained from combat? Hehehe, they don't hurt at all.",
	touch = "Hehehe~! You've reloaded me with energy!",
	voice_key_2 = -1,
	mission_complete = "Hehehe~ It's just human instinct to smile at the sight of money! Yeah, that's it! Smile, Commander~!",
	battle = "How-dee-doooo! I'm gonna shoot yooou!",
	id = 201270,
	gift_dislike = "",
	gift_prefer = "That's cheered me right up!",
	profile = "I'm the Royal Navy M-class destroyer Musketeer! I was in the Battle of the North Cape! Commander, little Musketeer is gonna shoot straight through your dreary heart with a bang bang!",
	voice_key = 20127,
	headtouch = "",
	feeling2 = "No matter what life throws at you, always be optimistic, happy, and positive! You just gotta be!",
	login = "Morning, Commander! Nice weather today! Click, click... bang! I'm not sure why, but I'm always brimming with energy!",
	detail = "Is it fun to hang out with me, Commander? ...Ah, sorry, never mind that.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[201290] = {
	hp_warning = "I need to hold out just a little longer... Edinburgh will come save me, I'm sure of it!",
	feeling3 = "Commander, you can't give up so easily. You must get into shape~ Come on, take a stroll around the port with Echo~♪",
	mail = "Mail has arrived~♪ Maybe there are yummy snacks enclosed within it~ Ehehe~",
	expedition = "The commission girls are back~♪ Echo will go check if they brought any yummy snacks with them~",
	win_mvp = "Wowee~♪ Echo got MVP? Ehehe~ So, you're basically praising me?",
	home = "Would you like to eat snacks with Echo~? ... You aren't hungry? In that case... you can just watch me while I eat.",
	unlock = "Hello, Commander~! Echo, reporting in! So, after I finish checking in, can I have a reward? Ehehe~♪ I loooove candy, you see~",
	touch2 = "Wha...? Hood said I shouldn't let people touch me there...",
	mission = "Commander, we should finish our missions! It's not good to be negligent~♪ Aha, don't you agree that Echo's suuuuuper duper reliable~?",
	vote = "",
	drop_descrip = "E-class destroyer – Echo.",
	feeling4 = "Echo made cookies~ Have a bite, Commander! ... It's too sweet for you? Ehehe, Hood said they have the signature \"Echo flavor\"~♪",
	lose = "Ugh... don't bully meee...",
	feeling1 = "Commander, people have said you've become a deadbeat, but what is a deadbeat even...? Hmm, in any event, Echo will do everything possible to make you more productive~ Let's begin by having you greet me properly~",
	skill = "Here I come! Witness Echo's might!",
	upgrade = "Ehehe~♪ I don't know if I've gotten stronger, but I'm grateful, Commander~♪",
	propose = "What are we here for? I don't quite get what this is for... Okay, if you give me candy, then I will stay with you to the end! Okie dokie, I'll open my mouth, so please feed me candy~♪",
	feeling5 = "Commander, can we go someplace far away... *Yawn*, I must've been sleeptalking... Hm? So you're okay with going somewhere with Echo? Hooray! Let's go somewhere, then!",
	main = "I made a promise to Edinburgh: I must return to port now and then, no matter how far away I go~♪|Be it with my E-class sisters or strangers, I can make friends with anyone I have fun with, so don't worry about me!|Echo is by your side, Commander! And if you give Echo a high-five, you might feel more motivated!",
	touch = "Commander, carry me like a princess! Echo's quite lightweight! ... Ahahaha~ Commander, that tickles~♪",
	voice_key_2 = -1,
	mission_complete = "Mission complete~♪ Echo will bring you the rewards, Commander!",
	battle = "Chaaarge! Ehehe, don't I sound like a flagship?",
	id = 201290,
	gift_dislike = "",
	gift_prefer = "You're giving Echo an amazing present like this? Yay! This is the best day ever!",
	profile = "I'm Echo, an E-class destroyer of the Royal Navy. I was in the Battle of the Denmark Strait along with Hood and Wales, after which I brought Wales safely back to port~ Ehehe, it's a memory I cherish! Oh, also, Edinburgh is really precious to me!",
	voice_key = 20129,
	headtouch = "",
	feeling2 = "Commander, please be positive. Be like Echo: smile, and be happy~ Ehehe♪",
	login = "Ah, Commander~♪ Ehehe, you're back! You know, Echo was reaaaally lonely~ Hurry up and come play with me~",
	detail = "Wales, someone can be small and still have a lot of potential, you know! Ehehe, Echo doesn't know what that means, but maybe they're words of praise~?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[201320] = {
	hp_warning = "It's not time to retreat yet!",
	feeling3 = "Y-you saw my room? Well, when I get too bored, I end up taking apart the furniture... and then I don't know how to put it back together. But why, though?",
	mail = "Commander, I got the mail for you~ Heh heh. It was nothing. Don't mention it.",
	expedition = "The commission team's back? I'll go get them!",
	win_mvp = "Yes! I'm the MVP! Now cheer for me!",
	home = "I finished all the work you left here for me.",
	unlock = "Eskimo, Tribal-class Destroyer, is here! Oi, this fleet's not half bad! Nice to meet you, Commander!",
	touch2 = "Oh? Something on my coat?",
	mission = "A new mission? All right, a new mission!",
	vote = "",
	drop_descrip = "Tribal-class destroyer – Eskimo.",
	feeling4 = "Too noisy? Hmm, well, I'm just trying to get your attention. Everyone's really... Oh no, could I be bothering someone? I'd better go apologize!",
	lose = "Oh noes... Sorry, Commander...",
	feeling1 = "You're no fun at all, Commander...",
	skill = "All right! Have a taste of this!",
	upgrade = "Yes! Now I'm feeling it!",
	propose = "All right, I promise, Commander. I'll work hard, and be good. I won't cause any more trouble! Just keep on giving me more attention! Eheheh!",
	feeling5 = "I've been good? Eheheh, that's all thanks to you, Commander. Since you've been giving me so much attention, I don't need to bother anyone else. I can just wait until you have time for me. Riiight?",
	main = "Commander, let's build an igloo when it snows! I'm pretty good at those!|Yippeeee! Yahoooo! Ah, Commander, errr~ Why am I horsing around like this? Just bored, I guess.|All right, target acquired: daydreaming Commander. Eskimo head smasher! GO!",
	touch = "What's up, Commander? Time I get to work? All right, time I get to work!",
	voice_key_2 = -1,
	mission_complete = "Commander, here's all the mission rewards. Take a look at them already!",
	battle = "Lemme at 'em!",
	id = 201320,
	gift_dislike = "",
	gift_prefer = "What's this for? Thanks!",
	profile = "I'm Tribal-class Destroyer Eskimo! During the war, I mostly served in the Home Fleet. I defeated Z19 at the Battle of Narvik, but then Z2 struck back at me... After that, I did good work in the Mediterranean.",
	voice_key = 20132,
	headtouch = "",
	feeling2 = "My outfit? It's different because I served in some pretty frigid waters back in the day~ Heheh, it's pretty cool though, huh? What do you think?",
	login = "Commander, you kept me waiting so long I got mad and took apart your chair! Wh-what if I can't put it back together...?",
	detail = "I was just looking for you, Commander! Let's do something fun.",
	couple_encourage = {
		{
			{
				40102
			},
			1,
			"Hey! Z2, you'd better make Z1 behave!",
			0
		}
	}
}


