	unlock = "Morning, Commander. Looks like our desks are right next to each other~ Whee~☆ Hmm? What's up? Is there something on my skirt? Teehee~♪",
	touch2 = "Hang in there, Commander – school's not out just yet~ Teehee♡",
	mission = "",
	vote = "",
	drop_descrip = "Morning, Commander. Looks like our desks are right next to each other~ Whee~☆ Hmm? What's up? Is there something on my skirt? Teehee~♪",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "The school festival? Right, that's in a few weeks... Oh, you trying to find a partner to look around with? Teehee~ Bullseye, huh?|School is sooo lame... You wanna swap notes with me next lesson? The teacher doesn't give a damn.|You forgot your compasses? Aww, what a stupid but lovable Sidekickommander~ I guess it's time to be the hero who saves your day♪",
	touch = "Lemme guess – praying for a peek at my undies? Teehee♪",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 201361,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Yesterday's subjects sure were tricky~ You done your homework yet, Commander? Need to copy mine? I'll let you, for a cost♪",
	detail = "They're selling some delicious new blueberry cakes in the canteen, and they sell out instantly if you're not quick! So, go get a slice for me, Commander~♪",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[201370] = {
	hp_warning = "Eeeeek! There's so much dirt!",
	feeling3 = "My friends are going to host a maid gathering to help deepen my understanding of a modern maid's duties, and I'm feeling kind of anxious... \"Steer clear of any weird indoctrination\"? Uh, I see...",
	mail = "Commander, you have a new letter! I brought it straight to you!",
	expedition = "Oh, look at that, the commission team is back. You'd better go out and greet them.",
	win_mvp = "That's the cleaning done! Feels fresh!",
	home = "Welcome back, Commander. What will it be? A massage, perhaps?",
	unlock = "I'm Nubian, and I'm good at housekeeping! Do you need my cleaning services, Commander? Uh, why do you look like you're about to cry? ...Normal maids like me are a rare gift? Uh, okay...",
	touch2 = "Um, okay...? What the heck are you doing?!",
	mission = "You've got a new list of targets to clean up. Get out there and deal with them!",
	vote = "拉票描述",
	drop_descrip = "Tribal-class destroyer – Nubian.",
	feeling4 = "So, I went to the maid gathering... Good god! Commander, are modern maids all like that? ...Like who? Like Sirius and her ilk! Don't tell me I'M the one who's out of touch here!",
	lose = "Ugh, dammit... My pride as a Royal Maid has been tarnished...",
	feeling1 = "...Keep this up, and I'm gonna have to clean YOU, Commander! That means purifying you from inside out, starting with your heart!",
	skill = "It's cleaning time!",
	upgrade = "Heheh! My cleaning skills have improved!",
	propose = "You're giving this... to me? O-okay, so you feel like this was the time to do it... Heheh, heheheh... In truth, I've had feelings for you for the longest... Ahem! What I meant to say is – I vow to be with you, now and forever!",
	feeling5 = "Ahh... Wait! C-Commander! You need to know that I'm a very normal and traditional girl! I'll only have... you know... with someone I love, and... G-god, what am I even saying?! *blushes*",
	main = "Commander, do you need any help? It doesn't have to be strictly housework-related. I can file paperwork, too. Probably.|Maids these days are a lot different to my idea of what a maid should be. Like how many of them are so strangely... \"service\"-oriented. Yeah...|Ding-dong! It's cleaning time! That means you need to leave the office! A battle between me and dust is about to unfold!|I heard this is what the maid of the modern age wears, but isn't it kind of... Oh, wait. It must be another one of those trends...",
	touch = "What's on your mind, Commander? ...Do \"the thing\"? What do you mean? I don't know what this \"thing\" even is...",
	voice_key_2 = -1,
	mission_complete = "Cleaning complete! Don't dally, go confirm your rewards!",
	battle = "Let the cleaning begin!",
	id = 201370,
	gift_dislike = "",
	gift_prefer = "I really like this! Thanks, Commander!",
	profile = "Nubian of the Tribal class extends you a greeting! Heheh, I'm not just a fully-fledged Royal Maid, I'm also a decorated and famous warship. When you need somebody to clean the seas, come straight to me!",
	voice_key = 20137,
	headtouch = "Oookay... Is this that \"reward\" people keep telling me about?",
	feeling2 = "*sigh*... You know, I just feel like I've not been particularly helpful to you, Commander. I've got a lot to learn from my maidly friends. But what's your take, Commander? What should I do to improve at my job?",
	login = "Good morning, Commander! I've finished sweeping your office! Have a productive day!",
	detail = "Welcome to my little corner of the port! Whether something's bothering you or you just want to chat, my ears are always open. Your secrets are as safe as can be with this Royal Maid!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[201371] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Heheh, I knew you'd become a regular here. So, what fascinating ingredients have you brought me this time?",
	unlock = "I'm Nubian, the master concocter of magic potions! What kind of potion do you want, Commander? ...Huh? It's been so long since you visited a normal potion maker who brews using a cauldron so you don't know what to order? ...Come again?",
	touch2 = "Uh, what...? You're doing this NOW?!",
	mission = "",
	vote = "拉票描述",
	drop_descrip = "I'm Nubian, the master concocter of magic potions! What kind of potion do you want, Commander? ...Huh? It's been so long since you visited a normal potion maker who brews using a cauldron so you don't know what to order? ...Come again?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "Have a taste of this confusion potion!",
	upgrade = "",
	propose = "",
	feeling5 = "Heheheh, is there a potion you want to make, Commander? I can make an elixir, a potion of happiness, anything you want. And of course, I'd be happy to join your party. Being with you is the best thing of all!",
	main = "Heheh, what potion do you want? Come on, don't be shy. I can even make a love potion if that's what you want.|Heheh, you'd be surprised to know I did my research before choosing to become a potion maker. Pretty good foresight on my part, right?|Why won't I call you \"Hero\"? Well... I'm not used to saying it yet, I guess. \"Commander\" feels much more natural!|Come to think of it, maids and potion makers have some things in common... Huh? Wait, doesn't that make witch is the most popular profession among modern maids?",
	touch = "Uh-oh... No, no, no! It's gonna overflow!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 201371,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Welcome to my brewing hut, Commander! I can make any potion you can think of as long as you have the right ingredients!",
	detail = "Welcome to my brewing hut! If you want something, just let me know! I'm a fully-fledged potion maker and can concoct almost anything!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[201372] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "My chocolate-making was a bust, but this was a brilliant success!",
	home = "Welcome back, Commander. If you need a Royal Maid's service, just ask for anything other than chocolate. Teehee!",
	unlock = "Uh, teehee! I was trying to make chocolate, then I slipped for some reason! ...Hang on a minute! How did I slip? Even a modern clumsy maid wouldn't blunder like that... Would she?!",
	touch2 = "Nooooo! Touching is fine, just don't lick me! ...Huh? That's NOT what you were doing?",
	mission = "",
	vote = "拉票描述",
	drop_descrip = "Uh, teehee! I was trying to make chocolate, then I slipped for some reason! ...Hang on a minute! How did I slip? Even a modern clumsy maid wouldn't blunder like that... Would she?!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I can make chocolate just fine! It's simply making Valentine's chocolate like a modern maid that I failed at. When I make yours, I will NOT fail, no way! Not only does my pride as a Royal Maid hinge on it, but my love for you does, too!",
	main = "There's nothing to worry about, I can clean this up in a jiffy, just you watch! Believe it or not, housekeeping is my forte!|Maids these days don't wear anything beneath their aprons? There's NO way that's true! Seriously? Some actually dress like that?!|If at first you don't succeed, you try and try and try again! I wouldn't cut it as a traditional Royal Maid if I wasn't determined!|Sorry, Commander, I made a big oopsie! ...H-how was that? Do I sound like a clumsy maid? I'm not cut out for this, am I?",
	touch = "Are you TRYING to make the kitchen messier than it already is?!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 201372,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Sorry for the oopsie-woopsie in the kitchen! ...Okay, okay! I'll start cleaning up, so quit laughing!",
	detail = "How would a modern maid get herself out of a sticky situation like this... Ask someone like Devonshire? Not a chance! If I asked, they'd know I'm behind the times!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[201380] = {
	hp_warning = "Things have changed. So must our plan.",
	feeling3 = "(This is how the Commander processes documents. Better remember that...) Oh, me? No, I wasn't spacing out. I was just thinking about our next battle plan.",
	mail = "I brought your mail.",
	expedition = "The commission team has returned, Commander. Allow me to check the goods with you.",
	win_mvp = "The glory of the Royal Navy shall never fade!",
	home = "Commander, I made coffee. If you'd like some, feel free. (People are so good at this in movies. Why am I too awkward to do it?)",
	unlock = "Greetings, Commander. I'm Trafalgar, a member of the Royal Navy. It's an honour. (Was that too cold? I didn't want to talk too much and sound rude...)",
	touch2 = "Huh?! Wh-what are you... (How am I supposed to react at a time like this?!)",
	mission = "Ah... Commander, here is your new mission list. Please take a look. (Our fingers just touched...)",
	vote = "",
	drop_descrip = "Battle-class destroyer – Trafalgar.",
	feeling4 = "C-Commander, I put the wrong document in here... Don't look at it, please... No, it's not a battle plan. It's my personal notes... (Goodness, how could I have forgotten my Commander research notes in there?!)",
	lose = "Commander, execute plan B!",
	feeling1 = "Commander, are you also this rash on the battlefield?",
	skill = "Engrave this moment upon the sea's memory!",
	upgrade = "Just you watch over my growth, Commander. (Did I sound too smug there?)",
	propose = "Okay... I want to explain my feelings with actions rather than words. From now on, I'll be ever by your side, protecting you with this very sword.",
	feeling5 = "I always feel uncomfortable in lively social situations. I tend to overthink things because I don't want to disappoint people, and then I end up not talking at all. *sigh*... This is the first time I've told anyone about this. I'm sorry you had to hear that embarrassing speech, but I had a feeling that the Commander I know wouldn't tease me...",
	main = "Are you holding a party in your office? Then I'll take my leave and go on patrol. (This is an opportunity to get to know the others, but a party's too much. I should just go on patrol...)|About today's meeting... (I actually wanted to talk about something else, but it's safer to talk about work...) Huh? You'd prefer to talk about something non-work-related?|Here's the latest combat report. Nothing is out of the ordinary, but feel free to take a look.|...Yes, I am the one who cleaned your desk. But you don't need to thank me; it was no big deal.",
	touch = "My collar's wrinkled? Oh. Thank you.",
	voice_key_2 = -1,
	mission_complete = "Well done, Commander. Your mission rewards are right this way.",
	battle = "For the glory of the Royal Navy!",
	id = 201380,
	gift_dislike = "",
	gift_prefer = "Thank you so much! (Was I a little too excited...?)",
	profile = "My name is Trafalgar, Battle-class destroyer with the Royal Navy. Please leave strategic and operational work to me. ...That's my whole self-introduction.",
	voice_key = 20138,
	headtouch = "Ah. Mm... (Maybe I am too cold... Oh! The Commander pulled away...)",
	feeling2 = "Ahem. Commander, requesting permission to join the next mission. (Phew... There have been a lot of parties lately, it would be rude to refuse directly, I'll use combat as an excuse...)",
	login = "Today's work plans, Commander. Documents to be processed are over there. If you have no questions, let's begin.",
	detail = "I've drawn up some exercise plans for this week. Here is the first, here is the second, and here is a backup I made in case of inclement weather. And these... would be my personal notes. Don't pay them any mind.",
	couple_encourage = {
		{
			{
				19901
			},
			1,
			"A party...? (Should I refuse, or...)",
			0
		},
		{
			{
				20501
			},
			1,
			"For the glory of the Royal Navy!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[201381] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "(The Commander's here. Everything's according to plan so far...) Fancy meeting you here, Commander! What a coincidence...",
	unlock = "The breeze is nice, isn't it? Do you want to have a drink with me? (This is exactly how my movies go, so this should work... Is my face too stiff?)",
	touch2 = "Eep?! Th-this might be easier... in the pool... (What am I saying right now?!)",
	mission = "Since you have new missions to do, why don't we take care of them together? Then we can come back together, and...",
	vote = "",
	drop_descrip = "The breeze is nice, isn't it? Do you want to have a drink with me? (This is exactly how my movies go, so this should work... Is my face too stiff?)",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "It's easier when I'm alone because I don't have to worry as much, but... when it's just you and me, I don't stress out as much from just chatting and sharing our feelings. So I like this more... Do you understand how I feel, Commander?",
	main = "Mmm... The sea breeze is wonderful, don't you think?|A cloudless night full of stars, just as I... Ahem. Just as the weather forecast said. (I hope the Commander didn't notice that slip of the tongue...)|Would you like to try my drink? I haven't put my lips on it yet... It would be okay if I did?|Phew... Lying down here is so comfortable. Want to join me...?",
	touch = "Do you like it when girls dress like this? (Yeah, this should be exactly what the Commander likes...)",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 201381,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Your hand is as gentle as the sea breeze... (This might be too corny.)",
	feeling2 = "",
	login = "Umm... Did you come for a breath of fresh air, too? (Oh no, am I being too boring?)",
	detail = "You think it's a little weird that there's a hammock in the pool? Well, I think it's fine... I see it a lot in movies, and stuff.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[201390] = {
	hp_warning = "Sound the alarm!",
	feeling3 = "What are the Port Guards, you ask? We're a police force that upholds the port's order and keeps you safe! We were established a few days ago! I'm the only guard so far, but I've already established 121 vigilance points around the port and I inspect them every day, which eliminates all kinds of dangers!",
	mail = "I feel like there are security risks in your mail system... I'll tell Nakhimov to upgrade the network security, then get her to join the Guards while at it!",
	expedition = "The commission team is back! Give me a moment while I finish the security check, Commander. You can see them after that!",
	win_mvp = "Kept the order pretty well, didn't I? Heheh!",
	home = "Welcome back, Commander! I request your cooperation in a routine inspection!",
	unlock = "Fwee-fwee! On-site security is in position! Commitment to maintaining order: Resolute! I've come as prepared as can be for this meeting! ...Ah, right, I've yet to introduce myself. I am Gallant, captain of the Port Guards! The honour is all mine!",
	touch2 = "If you don't stop, I'll... I'll blow my whistle! And I'll sound the alarm!",
	mission = "Fwee! Commander, we have to get to work ASAP!",
	vote = "",
	drop_descrip = "G-class destroyer – Gallant.",
	feeling4 = "I'm considering writing my name in all the secretary-on-duty slots... No, no, it's not fair to keep you all to myself! Hmm... But then again, it IS the captain's duty to be your personal bodyguard...",
	lose = "Fwee! Stay calm and retreat in an orderly fashion!",
	feeling1 = "Whaaat?! Everything's going to be a mess if you set a bad example and disturb the order!",
	skill = "To protect the order!",
	upgrade = "I will defend you with all my might!",
	propose = "I-I'll keep this nice and safe. I've... Wait, is that a commotion over there? Get behind me, Commander! I'll take care of– Hang on, my whistle... Fwee-fwee!",
	feeling5 = "Commander! You've, umm, disturbed the order by stealing my heart, so as the captain, I sentence you to never be apart from me! ...Heeey, stop laughing! I actually worked really hard to come up with that line!",
	main = "Commander, I'd like to make and put up 20 \"no loud noises\" signs around the office! ...Huh? I should quit my habit of blowing my whistle instead? Why?! I do it to maintain the order!|Hrmh... You allowed Mogador and her ilk to come near you again... Hrmmh... This is a danger that needs to be... Oh! I've figured out how to stop them!|Commander, here's the flowchart for entry into your office! One has to present a written request, then pass a facial recognition security check, then... Hm? Why are you clutching your face? Do you feel ill? I'll get the medicine box!",
	touch = "What is it? Got trouble? We need to lock down the– Owch! Stubbed my toe on the desk! Ow, ow, ow!",
	voice_key_2 = -1,
	mission_complete = "All the work is done! You must be tired, right? I've laid out a camping mattress that you can lie on! ...Hm? Why do you look so put off?",
	battle = "Follow the leader's signals! Onward!",
	id = 201390,
	gift_dislike = "",
	gift_prefer = "Thanks! So you do appreciate my guard work, huh?",
	profile = "I'm Gallant, Royal Navy G-class destroyer! I'm also the captain of the Port Guards! I will keep the order around here for you, Commander!",
	voice_key = 20139,
	headtouch = "You're NOT supposed to pull on my emergency light!",
	feeling2 = "You're an embodiment of justice! It's only natural that I'd protect you, being the captain of the Port Guards!",
	login = "Mornin', Commander! Oh, uh, the \"only authorised personnel\" sign on the door? It means exactly what it says. Without it, random people would make up some half-arsed reason to come in! We can't let folks freely come and go into important places!",
	detail = "Heheh! Look here, Commander! I installed some barriers leading up to your office, so now nobody will enter without... Hm? Nobody can enter it at all now? Well, now that you mention it... Umm, give me a minute to think!",
	couple_encourage = {
		{
			{
				20114,
				20113
			},
			1,
			" Won't you join the Port Guards?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[201391] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "I was worried what might've happened since you weren't answering your door. I was THIS close to putting up police tape and everything!",
	unlock = "Can you see me, Commander? I'm here to deliver your takeaway and a parcel! I've already made sure there's no danger out here – oh, and look, my ID! Just like the staff regulations stipulate! Come on, it's safe to open the door!",
	touch2 = "Commander... I'll be late for my next delivery if you won't stop...",
	mission = "You've got an urgent mission? Well, that happens. The lunch will have to wait until the mission's done!",
	vote = "",
	drop_descrip = "Can you see me, Commander? I'm here to deliver your takeaway and a parcel! I've already made sure there's no danger out here – oh, and look, my ID! Just like the staff regulations stipulate! Come on, it's safe to open the door!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "...Exhausted? Nonsense! I'm only covered in sweat because I wanted to see you as soon as possible. Yes, of course I obeyed the traffic laws!",
	main = "I got here 30 minutes ahead of time? Ahahaha... Well, I sort of prioritised your delivery. That's against the rules, so don't tell anyone!|It looks so nice and breezy inside your house. Mind if I take a quick break inside? I've, um, still got time before my next delivery, so... Alright, cheers! Let me also just take this off... No, I was talking about my jacket!|Why I came here on a regular bicycle? Well, um, Fargo and Akashi DID provide an e-bike, but I was in such a rush that I ran into something and broke it...",
	touch = "You want me to stay? Alright, let me just first check if the delivery drone has been repaired!",
	voice_key_2 = -1,
	mission_complete = "Heehee. Mission comple– Oh, blimey, I'm gonna be late for my next delivery! Excuse me! Enjoy your meal!",
	battle = "",
	id = 201391,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "H-hey! I'm covered in sweat!",
	feeling2 = "",
	login = "Alright, you finally answered. Open the door quickly, before your takeaway gets cold and loses flavour! Also, I want to see you!",
	detail = "The delivery drone broke down during the holiday, so I came to help! Ensuring the orderly distribution of goods is also one of the captain's duties!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202010] = {
	hp_warning = "",
	feeling3 = "I'm thinking of taking a walk, but I don't have a companion... Commander, want to take a walk with me?",
	mail = "Commander, you've got new mail~!",
	expedition = "Commander, the commissions are done.",
	win_mvp = "This victory belongs to everyone!",
	home = "Good work, commander. Is there anything I can help with?",
	unlock = "Good day to you. I am Leander class' light cruiser, Leander. Actually, I have some differences from my sisters. Do you want to know what they are?",
	touch2 = "Sometimes... I have to endure things I don't like, huh...",
	mission = "Commander, there are still unfinished missions.",
	vote = "",
	drop_descrip = "Leander-class light cruiser – Leander, Hull Number 75!",
	feeling4 = "We were distant sisters in the home country, so I'm happy now that we get to fight together in the same fleet. All of it is thanks to you, Commander.",
	lose = "I've caused you trouble...",
	feeling1 = "Being unable to judge your distance with others is problematic, Commander.",
	skill = "Mmh... just the right spot!",
	upgrade = "I'm gonna work a little harder",
	propose = "Always be by your side... is it? I understand. If it's alright, I'll happily stay by your side~",
	feeling5 = "Thanks to you, Commander, the others have gotten along better every day... Right. What kind of gift do you want, Commander?",
