	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, Happy New Year! Now it's off to the shrine for a special blessing, isn't it? Heheh, easy does it then.",
	detail = "Dressing up all Sakura style has me feeling like I want to listen to some Sakura music. Ehehe.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202072] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Good work, Commander. Y-you want to know what I've been up to...? Well... I've been slacking off for a bit, ehehe. Please keep it a secret from the others!",
	unlock = "Good day, Comm—Err, I guess it's \"Master?\" Ugh, I do prefer calling you Commander though... Anyway, I've been practicing the violin to help create better atmosphere around the shop. Did you come here because you were captivated by the sound of my music?",
	touch2 = "Eek?! I played off pitch because of you, Commander!",
	mission = "",
	vote = "",
	drop_descrip = "Good day, Comm—Err, I guess it's \"Master?\" Ugh, I do prefer calling you Commander though... Anyway, I've been practicing the violin to help create better atmosphere around the shop. Did you come here because you were captivated by the sound of my music?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "I mean, this is something all the Royal Maids can do. Even I've learned most of the skills necessary for being a maid.|I thought it'd be nice if we didn't have to play music live, but Her Majesty demanded that we provide live music for her at the venue...|Commander, have any song requests? It's a special treat from me. O-oh, but... nothing too difficult, please!",
	touch = "An encore? Alright. Here's a special song, just for you~",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 202072,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, since you're here, take a seat and relax! Sip on some tea and enjoy some good music~!",
	detail = "Do you get how it feels to kick back and let loose to some heavenly music now? Ehehe.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202078] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "It's time to greet the commission team, right? Let's stroll over leisurely, just as Newcastle does.",
	win_mvp = "A glorious victory, befitting a member of the Royal Knights! Ehehe~♪",
	home = "Excellent work as always, Commander. Please enjoy some hot and fresh tea while relaxing to the music I picked out myself~♪",
	unlock = "The Royal Knight, Southampton, makes her grand entrance in glorious wedding garb~! Oh, Commander, you look a bit on edge. Here, c'mere for a second~ Ehehe. *rub rub* Well? Feeling a bit less stiff?",
	touch2 = "I-I guess it's fine... You did give me a ring...",
	mission = "Wait, the mission's... deadline is right in front of us?! There's no time left to procrastinate, is there... Oh no...",
	vote = "",
	drop_descrip = "The Royal Knight, Southampton, makes her grand entrance in glorious wedding garb~! Oh, Commander, you look a bit on edge. Here, c'mere for a second~ Ehehe. *rub rub* Well? Feeling a bit less stiff?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "That one weird trick that I told you about earlier? It's going on a date with me! Ehehe, I guess you get what I meant now? ...After you finish working? Fine, I guess I have no other choice. I'll help you out a little bit!",
	main = "Commander, you look like you're drowning in work. I'll teach you this one weird trick that'll make all of your problems go away~! Ehehe.|You enjoyed my cooking? Hooray! I asked Sheffield to give me some pointers, and put my heart and soul into it. Ehehe.|Shh! Commander, come over here! Ehehe. Over here, we'll be able to slack– I mean, take a break, without Sheffield catching us.",
	touch = "What's wrong? I'm perfectly capable of working without slacking off if it's for your sake~♪",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "I'm still a member of the Royal Knights, you know!",
	id = 202078,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Welcome back! Mast... Err, pardon me! Umm, Commander? That's just the same as before... Oh, how about, \"Dear?\" Hmm... I hope that's not too over-the-top for you.",
	detail = "When I spin around in this dress, don't you think the fluttering ribbons make me look kind of like a butterfly? Commander? Um, Commander, are you there? What's wrong, are you so entranced that you're totally speechless?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202080] = {
	hp_warning = "So, you pests have a few tricks up your sleeves...",
	feeling3 = "To facilitate ease of reading, I took the liberty of organising and re-categorising all the books on your shelf. Please check the results.",
	mail = "Master, I've already sorted your mail.",
	expedition = "Master, does the sound of my gun not remind you of something? Perhaps, something like the commission fleet that you've kept waiting?",
	win_mvp = "Are you satisfied with these results, Master?",
	home = "Good work, Master. There is still some work for you to take care of. Please do your best.",
	unlock = "Ah... I thought you were a vermin, so I fired on instinct... You're my new Master? Excuse me. I am a member of the Royal Maids, Light Cruiser Sheffield. I am yours to command.",
	touch2 = "I do hope you have this same kind of strong spirit on the battlefield.",
	mission = "Please entrust all \"cleaning\" tasks to me.",
	vote = "",
	drop_descrip = "Sheffield-class Light Cruiser - HMS Sheffield",
	feeling4 = "I should learn... from Belfast's example? A maid should serve her master wholeheartedly without asking for anything in return. In contrast, that one is quite greedy... but, I am a bit envious...",
	lose = "Master, please assign me to the rear... ",
	feeling1 = "I see, Master, you are remarkably similar to a pest, morphologically. The world is full of mysteries.",
	skill = "Do you hear that? The ringing of your death knell.",
	upgrade = "Hmm... this feels a bit of all right. Thank you, Master.",
	propose = "Upon the name of Virgin Mary I pledge, may the hammer of love be dropped upon those that would harm my master... Master? U-um, I wasn't doing anything in particular. You must have heard me wrong. Anyway, let's get this absolutely mortifying ceremony over with as soon as possible...",
	feeling5 = "Master, are you troubled by the way I talk and act toward you? If so, you must understand that is the way I express my love, my beloved Master. Yes, it's true.",
	main = "\"Master, I love you.\" Please believe me, I put at least 30% emotion into those words. |Master, if you wish to take a nap, please tell me ahead of time. I will make sure you don't oversleep, with this gun. |Belfast dotes on you too much, Master. At this rate, I'm afraid that you will turn into a useless lump of driftwood.",
	touch = "Pest- I mean, Master, what requests do you have? I beg your pardon, that was a slip of the tongue.",
	voice_key_2 = -1,
	mission_complete = "Master, do you plan to give all the mission rewards to me?",
	battle = "\"Garbage\" will pile up if you don't \"clean\" it up...",
	id = 202080,
	gift_dislike = "",
	gift_prefer = "Is this for me, Master? Have you made another mess somewhere?",
	profile = "I am the Town-class light cruiser, Sheffield. I've basically only fought against Iron Blood, having witnessed the demise of Scharnhorst, and participated in the hunt for Bismarck and Tirpitz. However, I underwent repairs throughout the end of the Second Great War and was unable to sortie. If there's nothing else you'd like to know, I would like to head back now.",
	voice_key = 20208,
	headtouch = "",
	feeling2 = "I understand, Master. You've finally awakened to the realisation that you are an oversized lump of non-combustible rubbish, and your psyche is screaming for me to grant you the sweet release of... Just kidding, please wait while I make tea for you.",
	login = "Please mind your step, Master... Right there... is where I just mopped.",
	detail = "Hmm? \"Cleaning\" things up with a gun falls perfectly within a maid's normal line of duty, Master.",
	couple_encourage = {
		{
			{
				20212
			},
			1,
			"Surely you're not getting rusty, are you?",
			0
		},
		{
			{
				20702
			},
			1,
			"Do be careful with those Swordfish of yours...",
			0
		},
		{
			{
				20203
			},
			1,
			"I suppose this, too, is fate.",
			0
		},
		{
			{
				20208,
				20211,
				20212,
				20218,
				20219,
				20304
			},
			3,
			"Commander, I hope this is not some perverse hobby of yours.",
			0
		},
		{
			{
				20217
			},
			1,
			"Let me witness your \"justice.\"",
			0
		}
	}
}


_G.pg.base.ship_skin_words[202081] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Master, what do you plan to exchange for this all-important piece of mail?",
	expedition = "",
	win_mvp = "",
	home = "",
	unlock = "... Did you find out about my undercover identity? You leave me no choice. Master, I cannot allow you to leave this room... Of course I'm jesting, it's merely a hobby. ",
	touch2 = "Out of respect for your bravery, I shall reserve this special bullet just for you.",
	mission = "",
	vote = "",
	drop_descrip = "... Did you find out about my undercover identity? You leave me no choice. Master, I cannot allow you to leave this room... Of course I'm jesting, it's merely a hobby. ",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "The slumbering city, silent and dark, inexplicably makes me feel at ease... |Master, it is not incomprehensible that you would desire some excitement in your life, but please focus on the work at hand. |Do not let your guard down for even a second, and always be ready to fight. From this point, a secret agent and a maid are quite similar. Huh? Maids don't have to fight? Master, your jests are quite rich.",
	touch = "Master, you don't have to come all the way up to get me. It's going to be a pain to get you back down safely.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Let's hurry up and get this over with. The night wanes.",
	id = 202081,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Master, what kinds of missions are we to carry out tonight?",
	detail = "Maid by day, and secret agent by night? Hmm, that does fit the Royal style. Unfortunately for you, it's just your imagination.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202082] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Not a bad selection of fireworks. I thought that I had nothing to see since I've had to put on so many opulent displays of pyrotechnics for Her Majesty's enjoyment, but I feel like these are pretty tasteful.",
	unlock = "The Sakura Empire's summer festivals... they're quite noisy. It will be difficult to keep things clean with so many people around... Despite that, I'm still having a good time. Is there a problem?",
	touch2 = "I keep a gun with me at all times.",
	mission = "",
	vote = "",
	drop_descrip = "The Sakura Empire's summer festivals... they're quite noisy. It will be difficult to keep things clean with so many people around... Despite that, I'm still having a good time. Is there a problem?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "So this is cotton candy... Mmf.. It's very sweet... Nn... What are you waiting for? |Master, what do you think about this festival? If you're enjoying it, perhaps we can go to a similar Western-style event next time. |Southampton, why did you run off to the festival when you're supposed to be on duty? Ugh... What am I going to do with you... ",
	touch = "This outfit is quite breezy. I will have to thank Ms. Victorious on behalf of the Maid Team.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Regardless of the occasion, there is always time to take out the trash.",
	id = 202082,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Do you need something?",
	feeling2 = "",
	login = "So this is where you were, Master. I was afraid that you had gotten lost and almost mobilised the entire Maid Team. What exactly were you doing?",
	detail = "Swiftsure, don’t stay in your room while the festival is going on. Go out there and socialise with the others. Of course it's worth the effort...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202083] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Your enthusiasm for this party is understandable, but please do not forget about the commissions.",
	win_mvp = "",
	home = "Master, I do hope you haven't forgotten that there is still a party to attend... How hopeless you are. Allow me to tidy up your appearance.",
	unlock = "The fact that you're asking your own maid to be your partner at the ball shows a concerning lack of gumption as a human being... However, if you go and make a fool of yourself, it will reflect poorly upon my standing as a maid. Therefore, I have no choice but to accompany you.",
	touch2 = "Master, please do not get carried away in your excitement.",
	mission = "",
	vote = "",
	drop_descrip = "The fact that you're asking your own maid to be your partner at the ball shows a concerning lack of gumption as a human being... However, if you go and make a fool of yourself, it will reflect poorly upon my standing as a maid. Therefore, I have no choice but to accompany you.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Making your maid be your partner is a difficult request that falls outside normal lines of business. As fair compensation, please bring me a cake later.|As your partner, I will naturally draw plenty of unwanted attention. I must steel myself mentally.|I can see other members of the Maid Team going about their business... What a strange fetish you have, Master, to make someone who should be working behind the scenes take center stage... ",
	touch = "You'd like to escort me? Normally, I'd decline because that'd be embarrassing, but... you'd look so wretched that I simply have no choice but to accept.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 202083,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "There is no need for panic, Master. I've become quite accustomed to your lack of punctuality.",
	detail = "Don't worry, I've hidden my gun. If anything happens, I will protect you.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202084] = {
	hp_warning = "",
	feeling3 = "",
	mail = "You have received a letter. Now is the most opportune time to read it, Master.",
	expedition = "The commission team has returned. May I suggest that you contact them?",
	win_mvp = "It pleases me to know you can be of some use during these dark times as well, Master.",
	home = "Welcome back, Master. It surprises me to see you on the frontlines. While it's true you're helpless in a battle, your mere presence does inspire courage.",
	unlock = "Allow me to warn you ahead of time, Master. I will not come to your rescue if you spring another trap, so please mind your step henceforth... Just kidding. It is a maid's duty to aid her master, after all.",
	touch2 = "Is this how you would portray a monster?",
	mission = "You have received a new quest, Master. I pray it's nothing that will put you in danger.",
	vote = "",
	drop_descrip = "Allow me to warn you ahead of time, Master. I will not come to your rescue if you spring another trap, so please mind your step henceforth... Just kidding. It is a maid's duty to aid her master, after all.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "(As long as we're in this dungeon, I have the Master all to myself. I would ordinarily be insubordinate to ask for this exclusivity, but if the Master so desires it...) Oh, not at all. I have no desire to remain here for as long as possible.",
	main = "Have you truly had ample rest, Master? Considering your stamina, I sincerely cannot fathom a scenario wherein we reach the end of this dungeon together.|*sigh*... As much as I wish I could use my firearms to \"take out the trash,\" doing so would entail wreaking havoc on the stage dressing.|To think we must crawl through ventilation shafts. How revolting... Oh, it's nothing. Please, Master, lead the way – I insist.",
	touch = "Please, allow me to protect you, Master. You will make this more difficult for me if you suffer an injury.",
	voice_key_2 = -1,
	mission_complete = "Your quest rewards have come in. Please put them to good use.",
	battle = "I shall defeat our foes in one fell swoop.",
	id = 202084,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "It is good to see you, Master. Please let me know when you've chosen an infiltration route.",
	detail = "Why am I braving this dungeon with you, you ask? Well, I don't believe any other party would take it on with a master less capable than a mere maid.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202085] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission team has returned. I'll go check on them now.",
	win_mvp = "Cleanup complete. Master, let us proceed to the next combat zone.",
	home = "Thank you for your efforts. The game can wait until after you've rested. ...You don't want to make me wait? I'd rather not hear that from you.",
	unlock = "(Bang!) As usual, you fail to guard your back. This may just be a game, but I won't abide carelessness, Master. Let's clean this zone and hurry to the next.",
	touch2 = "...Hm. Did you fiddle with the tactile simulation settings?",
	mission = "",
	vote = "",
	drop_descrip = "(Bang!) As usual, you fail to guard your back. This may just be a game, but I won't abide carelessness, Master. Let's clean this zone and hurry to the next.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Congratulations on clearing that level. ...It's because of me? I appreciate your feelings, but frankly, I hoped you'd work harder. Rely on me too much, and I may get a little carried away, myself...",
	main = "Even in this virtual game, it's just too sluggish... No, Master, I'm referring to YOU.|I'll be ready to escape at a moment's notice, so don't stray too far from me. Also, please don't mess up and fall into any obvious traps.|I may be joining you in play, but this is serious maid work. ...Not to say that I'm not having fun, too.",
	touch = "Don't let go of my hand, Master.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 202085,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Reload complete... Now, don't get hasty and mess things up just because I happen to reload quickly. That would defeat the point. Stay calm, Master.",
	detail = "No matter how I'm dressed, I am your royal maid, Master... You want me to match my lines more to my current role? Please be reasonable.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202090] = {
	hp_warning = "It's alright! I can keep going!",
	feeling3 = "Right, so a good maid serves her Master proactively, eh... Cheers, Gloucester! I'll give the idea a go and clean Master's room right now then!",
	mail = "Letter, innit. Let's see... This how ya open it?",
	expedition = "Commission completed, innit, Master! Let's go say hi to the team!",
	win_mvp = "Cheers for helping me achieve a graceful win, Master!",
	home = "Welcome back, Master! Feeling a bit parched? I'll pop over to the Royal Maids, then!",
	unlock = "Pleasure meeting you. I'm Manchester, Royal Navy light cruiser. Heheh, looking forward to serving ya, Master-and-Commander!",
	touch2 = "Oh, Gloucester's gonna be right livid if ya keep that up, Master.",
	mission = "Missions, eh... Right, blimey! Gotta start looking for one you can do!",
	vote = "",
	drop_descrip = "Gloucester-class light cruiser – Manchester.",
	feeling4 = "Blimey, I should've thought this through... Can't enter Master's room without the key, obviously... Oh, hey up, Master. I was just thinking I'd clean your room...",
	lose = "They really did us in, eh? ...Easy now, Master, I'm well alright.",
	feeling1 = "That's just not how ya do it, Master.",
	skill = "It's cleaning time!",
	upgrade = "Brilliant! Cheers, Master!",
	propose = "I can't believe I'm getting an oath ring from you... I-I'm guessing ya won't mind me coming to your room when I feel like it? Relax, I'd never peek under your bed, 'course not!",
	feeling5 = "S-sorry, just feeling a bit tense to actually be inside your room... Yeah, of course I'll do a proper job cleaning it! Also, just wondering... c-could I pop around sometimes just to... see you, you know?",
	main = "If your work's not coming along, how about stopping to clean a bit? Tidy workspace improves your mood, dunnit?|I've proper wanted to learn cooking and stuff, but Gloucester says bollocks to that and won't let me. I'm not too dischuffed about it, but still...|I can do me maid tasks AND fight at the same time! Problem is, there's not much maid stuff you can do mid-combat, sadly...",
	touch = "Hey up! Need something?",
	voice_key_2 = -1,
	mission_complete = "You... You've completed all of 'em? That's bloody brilliant, Master!",
	battle = "C'mon then, let's have a go!",
	id = 202090,
	gift_dislike = "",
	gift_prefer = "Thank you for thinking of me, Master!",
	profile = "Me name's Manchester, Town-class light cruiser of the Royal Navy! I ran in convoys and helped with shipping during the war, and did loads of other missions too! Although I did make a hasty decision or two, and I didn't exactly meet a glorious end and all. Hehehe...",
	voice_key = 20209,
	headtouch = "Bit embarrassing, this, Master...",
	feeling2 = "Being a Royal Maid, it's me duty to serve you, innit. So whenever ya need something, just hit me up!",
	login = "Hey up, Master! Just got done tidying up the office. Go on then, have a seat! ♪",
	detail = "You can always count on me, Master! There's bound to be things ya can't do that I'm right capable of!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202091] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Ahaha! Brilliant work out there, Master! Now, come here and show me your neck~ Heheh, try to hold still now~♥",
	unlock = "Master, it's time for your injection! Hmm... Nowhere to be seen, eh... Then I guess I'll keep the sickbed warm until Master comes ba– Eep! M-M-Master?!",
	touch2 = "M-Master, don't move around so much!",
	mission = "",
	vote = "",
	drop_descrip = "Master, it's time for your injection! Hmm... Nowhere to be seen, eh... Then I guess I'll keep the sickbed warm until Master comes ba– Eep! M-M-Master?!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Hmm. A nurse's job isn't to clean rooms... but is it her job to clean her Master's body? Oh gosh, what am I even thinking...|What's up Gloucester's costume? I think she goes against her by-the-book nature to dress all fancy for special occasions... Ya think that's the case, Master?|We're in for a right bastard of a cleanup the day after Halloween, but this is all worth it for that! Plus, that'll be a chance for the Royal Maids to shine, wunnit!",
	touch = "Do ya want me to go slow, or do I just jab it in?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 202091,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Fooound you! Come on, Master, it's time for your shot~ Heheh♪",
	detail = "That's good, now just stay still... Actually, don't I need to do something before giving ya the shot? It's too late to ask Sheffy by now... Eh, oh well! Besides, I'm no ordinary nurse – I'm a succubus nurse! This'll go just fine!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202092] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "That group has got to be... Ah! It's the commission team!",
	win_mvp = "Ah, my swimsuit... Err, never you mind, Master! What matters is that we won!",
	home = "I'm done cleaning your beach house, Master. Now how 'bout reflecting on your battle over there? I'll go fetch ya a beverage!",
	unlock = "Welcome to the beach, Master! Pretty hot today, innit. If you'll have me, I'm right okay with spending the day together.",
	touch2 = "W-was this my fault...? *blushes*",
	mission = "",
	vote = "",
	drop_descrip = "Welcome to the beach, Master! Pretty hot today, innit. If you'll have me, I'm right okay with spending the day together.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "So, how was today, Master? Oh, sorry if ya felt obligated to hang out with me! I'll admit, I did kind of drag ya along from place to place... You had fun nonetheless? Heehee. Happy to hear it♪",
	main = "Got you a fizzy pop, Master! I can make a cocktail out of it if ya want.|Nelson's not too interested in the beach volleyball tournament... What about you, Master? I can sign ya up, no problem.|Can we talk about Ark Royal? She says she's using her camera to keep an eye on the destroyers, but we all know that's a bloody lie...",
	touch = "Yeah, Master? Need something?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 202092,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
