	mail = "",
	expedition = "",
	win_mvp = "",
	home = "The port is all done up for the festival. But I get a headache when I think about having to put it back as it was...",
	unlock = "Gloucester, light cruiser of the Royal Maids, at your service for the Spring Festival... You say I look displeased? I beg your pardon, it's just... Such holidays are in fact quite busy for the Maids. We have much on our minds. It is none of your concern.",
	touch2 = "We'll have to shackle the master until the end of the festival, I'm afraid...",
	mission = "",
	vote = "",
	drop_descrip = "Gloucester, light cruiser of the Royal Maids, at your service for the Spring Festival... You say I look displeased? I beg your pardon, it's just... Such holidays are in fact quite busy for the Maids. We have much on our minds. It is none of your concern.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "The floor is filthy again...? Oh those girls... I told them a thousand times to wipe their dirty shoes before coming inside...|Master, you should find a bit of time to spend with the girls. Don't forget those packets of New Year money.|The Royal Maids are preparing tonight's banquet. As long as Belfast is there, I don't think they will have any issues... Actually, I think I will go take a look after all...",
	touch = "Master, it's impolite to stare at a lady, maid or otherwise.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 202101,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Master, how is your work coming along? Let's avoid having you at the office for the holiday.",
	detail = "It was a terrible mistake letting Fiji handle this festival costuming... \"Spice up this bit and the Commander'll love it,\" and such. It's all a game to that girl...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202102] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "We should keep this place clean so that the commission team can use it after us.",
	win_mvp = "",
	home = "Welcome back, Master. You don't need to rush yourself to ride with me right away... Oh, you enjoy my commands? W-well...",
	unlock = "Commander, please sit properly when you're riding the carousel, and refrain from haphazardly bouncing up and down... Why am I holding a whip, you ask? Why, as a trainer, it is my duty to instruct you on the proper usage of fairgrounds equipment.",
	touch2 = "Ah... Let's, um... revisit this later...",
	mission = "",
	vote = "",
	drop_descrip = "Commander, please sit properly when you're riding the carousel, and refrain from haphazardly bouncing up and down... Why am I holding a whip, you ask? Why, as a trainer, it is my duty to instruct you on the proper usage of fairgrounds equipment.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Given your excellence and earnestness, it's understandable that you aren't used to such rides. It's sure to be many times more fun with the help of a Royal Maid such as myself... Oh? It's fun... just because I'm here? I-I see...",
	main = "Please don't comment on my attire, Master. Learning to be unaffected by such things is part of your education...I think.|I am simply here to help you practice, Master. If you'd like to change positions, then you may manhandle me as you see fit.|Focus on looking me in the eyes. The ride is moving, yes, but I can still tell that your eyes are darting about.",
	touch = "If you'd like to ride together, then I can hop over to yours... No? Okay, then.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 202102,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Are my instructions wrong? Forgive me for my presumptuousness, but I hope you're ready to show me a correct example.",
	feeling2 = "",
	login = "Sit up straight, butt on the seat, and face toward me. There... You may stare at me, yes. ...No need to put your hands behind your back yet.",
	detail = "*crack!* ...Ah, my apologies for startling you. Please continue to enjoy the ride. I'm just testing the whip... ahem, I mean, I'm simply getting a feel for this prop.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202110] = {
	hp_warning = "Gh... At least let me protect the gold...!",
	feeling3 = "I've been lectured by Bel again... Forgetting to lock doors when going out, and turning off the tap... What the heck! She's totally not like a little sister!",
	mail = "Commander, there's a new ma... Wh-What? Where's the mail? Where did I leave it... ??",
	expedition = "When it comes to military commissions, I'm a pro!",
	win_mvp = "Crushing the enemies with elegance... That, is the elegant Ediburgh of the royal family!",
	home = "I made cookies! Please have a taste... They taste the same as Bel's? Well, we're sisters, after all!",
	unlock = "This is my turn, you might say! I am 'her' older sister, Edinburgh! In a sense, I am the 'most accomplished' light cruiser!",
	touch2 = "Commander, a lady would never hide her gold bars there!",
	mission = "You have to finish your missions properly!",
	vote = "",
	drop_descrip = "Edinburgh-Class light cruiser ー Edinburgh, Hull number 16!",
	feeling4 = "Phew... I've finally found you, Commander. Actually... Aaaah-- Who the heck! Who left the banana peel here!",
	lose = "Gh... the bullion...",
	feeling1 = "Since it's Commander, I have to be even more careful... *stare*...",
	skill = "No matter how thick the armor is, it can't win against the power of gold!",
	upgrade = "It seems like I've become luckier!",
	propose = "Hmhm, I'm fine with sharing some of my money-luck with you. ...The gold? No! That belongs to the Belfast Foundation!",
	feeling5 = "Commander, want to have a walk together before it gets dark? Yes, don't worry. The lights were switched off, and the windows were shut. Everything's OK! ... W-what? ...Wh-Where did the keys go?!",
	main = "I want to be as elegant as Hood but, well...|Eeeh! ...Bel, where are you? I forgot my keys again...|Hmhmm~ Even Scharnhorst had to turn tail and run away when she saw me!",
	touch = "Hey!! Don't touch that! It's gonna fall!",
	voice_key_2 = -1,
	mission_complete = "I seem to have forgotten about something... Well, whatever!",
	battle = "Wh-Wh-What to do?? First let's retre... I mean, intercept them!",
	id = 202110,
	gift_dislike = "",
	gift_prefer = "Oh, wow! This present looks so pricey!",
	profile = "I am the lead ship of Edinburgh class of the Royal Navy. Sometimes it is stressful having an overly capable little sister... I took part in the pursuit of Bismarck and Scharnhorst, as well as many patrol missions in Atlantic, North sea and Mediterranean. In the end, I sunk with all my gold due to Ironblood torpedoes...",
	voice_key = 20211,
	headtouch = "Thanks! I'm feeling a bit more energized.",
	feeling2 = "Everything goes well when 'that girl' does it, so it should be fine if I'm a little clumsy, shouldn't it?",
	login = "Ah! I'm not doing anything weird! I'm just transporting gold bars into the room!",
	detail = "I'm not going to give these to you no matter how much you stare at me.",
	couple_encourage = {
		{
			{
				20212
			},
			1,
			"I didn't think I'd get a chance to fight with Belfast!",
			0
		},
		{
			{
				20208
			},
			1,
			"Sheffy, I'm counting on you!",
			0
		},
		{
			{
				20210
			},
			1,
			"Newcastle, let's talk about Bel sometime!",
			0
		},
		{
			{
				20129
			},
			1,
			"Echo, dear, do take care!",
			0
		}
	}
}


