_G.pg.base.ship_skin_words[202121] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Master, what do you think about handing some red envelopes to the hardworking girls still out on commissions?",
	win_mvp = "",
	home = "I baked this pastry for a certain Master who is so absorbed in work to the point of forgetting to eat. Please enjoy it.",
	unlock = "Hehe... Master, why are you so stunned from seeing me? I thought you perhaps wanted to see me in a qipao... was I mistaken?",
	touch2 = "I see, Master. The biggest drawback of this qipao is its ability to rob you of your self-control.",
	mission = "",
	vote = "",
	drop_descrip = "Hehe... Master, why are you so stunned from seeing me? I thought you perhaps wanted to see me in a qipao... was I mistaken?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Did you know, Master... all I can do for you is to learn from the cultures of the other camps in order to provide you with better service. But all this pales in comparison to all that you do for us on a daily basis, yet you take yourself for granted... What a lovable but also hateable person.",
	main = "A variety of culinary techniques and seasoning methods... the food culture of the Dragon Empery is truly eye-opening. |It's customary in the Dragon Empery for everyone to get together on New Year's to have a banquet? Ahh, so many people to serve... my maid's soul is trembling! |Only a few girls from the Dragon Empery have joined our fleet. Because of that, I can't afford to let them feel lonely.",
	touch = "Despite the fact that it is a holiday, I am still ready to sortie.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 202121,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Welcome back, Master. I specially procured some different teas from the Dragon Empery. Which one would you like to try first?",
	detail = "The outfits of the Dragon Empery do have a certain charm. Perhaps I can give them a little recommendation to the rest of the maid team. What do you think?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202122] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "A victory for the Master...",
	home = "Welcome home, Master. You may rest easy knowing the Royal Maids are here to protect you.",
	unlock = "This is special cold-weather equipment inspired by Eagle Union designs. It was made for practical purposes such as special operations in frigid climates, and as such, was not designed with appearances in mind. Please do forgive me, Master.",
	touch2 = "I'm afraid this battle dress may not adequately satisfy you, Master. I beg your pardon.",
	mission = "",
	vote = "",
	drop_descrip = "This is special cold-weather equipment inspired by Eagle Union designs. It was made for practical purposes such as special operations in frigid climates, and as such, was not designed with appearances in mind. Please do forgive me, Master.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "This power, it certainly is not just for the sake of destruction.",
	propose = "",
	feeling5 = "",
	main = "Madam Enterprise's cooking has improved noticeably. This is certainly thanks to Madam Vestal's lessons, but no doubt the Master is another important reason.|Such a willful appearance... a maid uniform is of course the appropriate dress for a maid, is it not?|It would be nice if I spent more time with my sister, hm...? I must agree with you, Master. I beg your pardon for making you worry so.",
	touch = "Do let us know if you have any needs that the Royal Maids might service.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 202122,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Welcome home, Master. Your coffee is ready. Please, enjoy it at your leisure.",
	detail = "It is only by maintaining a well-regulated lifestyle that one may keep a cool head and act appropriately when backed into a corner... It is with this in mind that I, Belfast, serve my Master as a maid.",
	couple_encourage = {}
}


