	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 202124,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I am accustomed to being the one who makes the arrangements, but occasionally letting others make plans for me has merits of its own. Master, our next location is for you to decide. Hehe~ I'm looking forward to it. ",
	detail = "Master, what would you like for lunch? I prepared some... Hmm? You're fine with just that? Master, you can't have snacks as a meal.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202125] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Here is the pizza you ordered. Do take your time and enjoy it.",
	unlock = "Welcome, table for one? Of course, right this way. Oh? What is it? Ah... I'm filling in for the manager at the moment, so that makes you my customer rather than my master, no?",
	touch2 = "While it is indeed a maid's duty to offer everything to her master... Not to be presumptuous, but you could consider the time and place.",
	mission = "",
	vote = "",
	drop_descrip = "Welcome, table for one? Of course, right this way. Oh? What is it? Ah... I'm filling in for the manager at the moment, so that makes you my customer rather than my master, no?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Miss Fubuki is rather excitable, but she is a clever and hardworking girl. Just give her a bit of direction and she'll figure it all right out.|While the customer is free to order anything she wants, as a maid I feel it is my responsibility to offer healthier suggestions. Particularly to the Union girls who order litres and litres of cola...|Leading customers to their tables, organising shifts, management... all of this would make a fine training program for the Royal Maids.",
	touch = "Yes, what can I get for you?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 202125,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Your menu. I would recommend our new offerings here. There is also a promotional campaign of which you might take advantage.",
	detail = "Whether serving my master or managing a restaurant, it is my responsibility as a Royal Maid to handle it promptly and efficiently. Now then, are you satisfied with my performance?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202126] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "You want me to join you for a shrine visit...? I'd be delighted. Your Belfast will gladly accompany you.",
	unlock = "It took me quite some time to prepare a suitable traditional Sakura Empire outfit. Terribly sorry. Master, won't you please allow this Belfast to serve you for another year?",
	touch2 = "Everything has its time and place, Master.",
	mission = "",
	vote = "",
	drop_descrip = "It took me quite some time to prepare a suitable traditional Sakura Empire outfit. Terribly sorry. Master, won't you please allow this Belfast to serve you for another year?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "An elegant fan emphasizes its holder's poise. Would you like to hold one, Master? Hehehe.|I was concerned that traditional Sakura Empire attire might hinder my maid work, but rather, it's easier to move than I thought.|Madam Hiei instructed me in the ways of Sakura Empire cuisine. In exchange, the Royal Maids will assist her with her next banquet. Do look forward to it, Master.",
	touch = "Master, if you're tired, please take a rest here.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 202126,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Happy New Year, Master. The maids have prepared you some New Year's dishes from the Sakura Empire. Please, enjoy.",
	detail = "Master, is there something I can do for you? Holiday or no, I am here to serve your every wish.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202127] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "I had to ask that they all disappear for the sake of your rest, Master.",
	home = "You must be tired, Master. Leave all of your little troubles and needs to me, okay?",
	unlock = "Heehee. How do you do, Master? The temperatures just won't go down this summer, so I brought cold, carbonated drinks for you to fend off heat stroke. Go on, have a drink.",
	touch2 = "Heehee. You're awfully anxious.",
	mission = "You have new missions, Master. Allow me to clear every obstacle out of your path forward.",
	vote = "",
	drop_descrip = "Heehee. How do you do, Master? The temperatures just won't go down this summer, so I brought cold, carbonated drinks for you to fend off heat stroke. Go on, have a drink.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Master, keep your eyes fixed on me. Good. Now, relax and lean into my arms... Phew. How do you feel? Did that relieve your exhaustion from playing all day? You say you can hear my heartbeat more than usual...? I'm sorry. It is beating faster right now – because of you, of course...",
	main = "Would you like some juice to cope with the sweltering heat, Master? ...Very well. Mm... There. Please enjoy.|Master... Master? You're staring at me again. Has the heat overwhelmed you? ...Heehee, then I'll prepare a sundae for your dessert.|You and I are alone right now. Does that mean I'm monopolizing you?",
	touch = "I'm right here, Master. Is there anything I can assist you with?",
	voice_key_2 = -1,
	mission_complete = "As efficient as ever, even on your days off. I'm impressed, Master.",
	battle = "",
	id = 202127,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Oh? Master?",
	feeling2 = "",
	login = "Welcome back, Master. What attraction would you like to begin with today?",
	detail = "Here's a map of the amusement park attractions, Master... Master? Are you listening? You seem distracted... Hm? Because you don't know where to look? Oh... Heehee. I see...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202128] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Anything interesting today? Tell me while we enjoy some dessert.",
	unlock = "Are you destined for me? Greetings. Belfast, from this moment onwards, I will always be with you.",
	touch2 = "W-wait a moment...honestly, I'm cleaning right now..",
	mission = "",
	vote = "",
	drop_descrip = "Are you destined for me? Greetings Belfast, from this moment onwards, I will always be with you.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Am I getting used to my new role? You really asked me a tough question, but...there's no sweeter question in the world.",
	main = "Master, dear, darling...some hard choices to make. Or do you have other ideas? |Just do according to your own plans, in my heart you will always be the best. |Wearing this makes it a little inconvenient to do things...but if you like it so much, then just be a bit more patient...",
	touch = "In comparison to standing behind you, I can see more when standing beside you.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 202128,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Is today the same as usual?",
	detail = "I'm not going to give up being your maid. Besides, who could understand you better than me?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202129] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Thank you for your efforts. Care for a shoulder massage? ...Okay, then close your eyes. While you relax, do feel free to share what you saw during your travels.",
	unlock = "Your perfect maid, Belfast, has returned, master – with even more reliable strength in hand. Should you have any duties, daily tasks, or special missions, you may entrust them all to me.",
	touch2 = "Heehee, do you need your curiosity satisfied? This is, of course, a part of my maidly duties.",
	mission = "",
	vote = "",
	drop_descrip = "Your perfect maid, Belfast, has returned, master – with even more reliable strength in hand. Should you have any duties, daily tasks, or special missions, you may entrust them all to me.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "This strength has changed me in many ways, but the best of all is that I can fulfill my wish with greater composure than ever. That one wish being... making my master happy. That is the meaning of this strength.",
	main = "An excellent Commander and skilled maid share certain traits: the foresight to anticipate needs, and the grace to meet those needs. In short, I feel I can care for you even better now.|I prepared tea and snacks – your favourites, naturally. Also, I've organized the paperwork on your desk, in hopes that it will allow you to handle them more easily.|Strength lies in the ability to protect what matters most. I am now confident in my ability to preserve a peaceful life by your side forever.|Master, might I suggest a more relaxed posture? For example... Would you prefer to be in my lap or in my arms? Heehee.",
	touch = "Are you... asking me to come closer, master?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Be it efficiency or elegance, I promise not to disappoint you.",
	id = 202129,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "If I may... I believe that all of my effort was leading up to this warm feeling.",
	feeling2 = "",
	login = "Welcome back, master. Everything is ready for you. Allow me to accompany you in today's work.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202130] = {
	hp_warning = "",
	feeling3 = "Don't get carried away! I came here because of a tasty cake! It's still too early for me to acknowledge you!",
	mail = "It's your mail so hurry up and get it. ...It's not like I'm concerned about who it's from! Hmph!",
	expedition = "The commission team is back. Hurry up and check the results from them, you idiot!",
	win_mvp = "Hmph! I will not acknowledge you just because you complimented me!",
	home = "You're so lacking at work that you're only good at returning here!",
	unlock = "You can be at ease now that I, Arethusa, have come. If anything, Commander, don't you dare become my hindrance!",
	touch2 = "Aaah! Pervert! Molester! Lewd! Go and die!",
	mission = "Idiot! Stop sleeping! There's a new mission!",
	vote = "",
	drop_descrip = "Arethusa-class light cruiser – Arethusa, Hull Number 26!",
	feeling4 = "You do have some positive qualities... Hmph! My opinion of you is slightly improved! There's still a lot for you to do!",
	lose = "Ugh... How could I fall here... of all places...",
	feeling1 = "I cannot acknowledge a commander like you!",
	skill = "If we keep doing this dillgently, it will all work out!",
	upgrade = "Commander, don't get in my way!",
	propose = "You dummy. You're making this too formal! This... should've been done a while ago...",
	feeling5 = "Umm... Good work... I mean, it's nothing! I just made some snacks since I felt like it, so hurry up and eat them!",
	main = "Even if they are allies, I will not show mercy to any threat towards  my comrades!|...Leaving me alone like this... I-I'm not feeling lonely or anything!|Hmph! You suck, Commander, so stop making me worry about you!",
	touch = "I-it's not like I'm fond of being touched by an idiot like you! ...I just feel sorry for you since you're so lonely!",
	voice_key_2 = -1,
	mission_complete = "Doesn't the reward suit you just fine? Hurry up and get it!",
	battle = "Listen up! Our pride rides on this battle! Let's take this seriously!",
	id = 202130,
	gift_dislike = "",
	gift_prefer = "Th-this is... Don't look at me like that! I hate it! Hmph!",
	profile = "I am the Arethusa class treaty cruiser, Arethusa: the first cruiser in the world designed with vertical armor! --Hmph! The fact that I'm amazing was decided from the beginning!",
	voice_key = 20213,
	headtouch = "",
	feeling2 = "I do not acknowledge a Commander like you! Hmph!",
	login = "Commander, I'm gonna get angry if you don't take this seriously!",
	detail = "...Idiot! Did no one teach you that it's rude to stare at a girl?!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202140] = {
	hp_warning = "",
	feeling3 = "I like you Commander, but it's important for all of us to be together. I'm troubled~",
	mail = "Mail time~ I wonder what reward I'll get for bringing it to you~?",
	expedition = "Commander~ *arms folded* let's head to the docks and greet the girls who went off for commissions",
	win_mvp = "You cannot escape from me! Be good, and accept~ your~ punishment~",
	home = "Aaaah cease your attacks! I'm on your side!",
	unlock = "I am Galatea, the 2nd of the Arethusa class~ Do you believe in fate, Commander? It is fate that I meet with you~",
	touch2 = "Ah... You're daring, Commander --Well then, do you want to hear my wishes?",
	mission = "Yes, let's see what today's missions are about~",
	vote = "",
	drop_descrip = "Arethusa-class light cruiser – Galatea, Hull Number 71!",
	feeling4 = "Commander, let me have your ear... *kiss*. I like you~ ... Yep. Such a thing would have to be done in reality, right~",
	lose = "Hmph! ...I curse you to be destroyed by my allies!",
	feeling1 = "Do you understand? Even the red string of fate is not absolute. I no longer think about anything concerning you anymore, Commander~",
	skill = "This has nothing to do with my fate~",
	upgrade = "This too is fate~",
	propose = "With this, the bond of fate has been formed~ There's still a long way ahead of us, so let's take care of each other, darling~",
	feeling5 = "The red string of fate was what made me grow from a seed, and you, Commander, were the one who made me bloom~ You're so great~ *kiss*",
	main = "Commander, I'm wearing new clothes today! --Hmm? I didn't say I'm heading out!|Commander, are you free? How about taking a walk together? I want to link our arms and be seen by the other girls|Hmm? Did you not hear that? ...There's no helping it. Lie down over here and let me check your ears",
	touch = "Hehe~ Commander, you really like to engage in skinship, don't you? Well, just this once, I'm allowing you to continue a bit more~",
	voice_key_2 = -1,
	mission_complete = "I'm gonna take your share of the rewards too, Commander.",
	battle = "Such disobedient kids~~ They must be punished~",
	id = 202140,
	gift_dislike = "",
	gift_prefer = "What a lovely present... Is this all part of some sinister plot?",
	profile = "I am Galatea, the second ship of the Arethusa class. I may not look like it, but in my service in the Mediterranean, I achieved some results~ You'll regret it if you underestimate me~",
	voice_key = 20214,
	headtouch = "",
	feeling2 = "It takes a long time for the bond to form after you tie the red string of fate. Do try hard, Commander~",
	login = "I'm going to do this and that again today. Please take care of it~",
	detail = "Geez~ If you keep on looking at me like that, I'll be reporting you to the authorities~",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202150] = {
	hp_warning = "Light of dawn, illuminate our path...!",
	feeling3 = "The goddess, Aurora, was said to have \"rose-coloured fingers.\" Though the same can't be said for me, my fingers at least smell like roses. Commander, want to check for yourself?",
	mail = "There's new mail, shall I read it aloud for you?",
	expedition = "Commander, it will be a problem if you keep staring at me and forget about the girls who have returned from commission.",
	win_mvp = "How wonderful, Commander, we won!",
	home = "Good work. Please take some time to relax.",
	unlock = "Greetings, Commander. I am the fourth ship of the Arethusa-class light cruisers, Aurora. From now on, I shall serve as your secretary. Please feel free to ask anything of me~ ",
	touch2 = "Commander! I... I'm going to be mad! Jeez! I'll really get mad!",
	mission = "Commander, a new mission dossier has been issued. I have already highlighted the most important parts, so please look over it.",
	vote = "",
	drop_descrip = "Arethusa-class light cruiser - Aurora, pennant number 12",
	feeling4 = "Commander, come here for a moment~ ... Hehe, this rose suits you best after all! Eh? I'm not making fun of you... In that case, why don't you pick one out to put on me? I'm sure I'll love whatever you pick~",
	lose = "It seems I have not yet become accustomed to the battlefield...",
	feeling1 = "Commander, please refrain from making a fool of yourself in public.",
	skill = "Commander, helping you solve problems and leave worries behind is also part of my job~",
	upgrade = "Commander, I'll be able to help with even more things now~",
	propose = "\"A rose by any name would smell as sweet.\" Whether I am called Aurora, the \"Goddess of Dawn,\" or even Chongqing, I am still the same me. Yes... I will always be at your side.",
	feeling5 = "Lately, some girls have been grumbling that I've been monopolosing all your time... But, I'm not going to back down on this. Commander, you too should be prepared to deal with a bunch of sulking girls~",
	main = "Dragon Empery? Oh, it's a great place. Mm... for example... |Even though I don't mind if you stare at me, please do your work properly~ |Hold still, Commander, there's something stuck on your cheek... There! Now, please do your best at work~",
	touch = "Commander, want to take a break and come water the flowers with me?",
	voice_key_2 = -1,
	mission_complete = "Some mission rewards had not yet been collected, so I retrieved them in your stead.",
	battle = "May we be blessed with victory~",
	id = 202150,
	gift_dislike = "",
	gift_prefer = "I shall treasure it.",
	profile = "I am Aurora of the Royal Navy, fourth ship of the Arethusa-class. You are welcome to call me the \"Goddess of Dawn,\" but please forget any nasty-sounding nicknames you might hear like the \"Silver Phantom.\" Commander, perhaps you are familiar with some of the other names that I've been called?",
	voice_key = 20215,
	headtouch = "",
	feeling2 = "Commander, would you like to see the roses that I planted? I have a lot of different kinds~",
	login = "My name symbolises the break of dawn. Ehehe~ Do you feel more energetic from seeing me?",
	detail = "Commander, is there anything I can help you with regarding equipment?",
	couple_encourage = {
		{
			{
				50203,
				50202
			},
			2,
			"Ping Hai, Ning Hai, are you two also practicing mask-changing opera? Eh, you're doing it to make money...?",
			0
		},
		{
			{
				30182
			},
			1,
			"If you can't decide, how about consulting a rose?",
			0
		}
	}
}


