_G.pg.base.ship_skin_words[202152] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "You must be weary, Commander. Allow me to soothe you with my music.",
	unlock = "I've always believed that music is unique in its power to touch one's heart, so I decided to learn the violin. Commander, please enjoy my performance.",
	touch2 = "Jeez, Commander, this is going to get in the way of my performance...",
	mission = "",
	vote = "",
	drop_descrip = "I've always believed that music is unique in its power to touch one's heart, so I decided to learn the violin. Commander, please enjoy my performance.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Commander, after everything is over, let's travel around the world, bringing blessings to the far corners of the world with our music. This is something only we can do.",
	main = "The pigeons always seem to gather to the sound of music. Hehe, turns out that they're hungry. |Commander, are you interested in learning an instrument? I'd recommend the piano so that you can accompany me! |Commander, if you ever find yourself lost and confused in the dark, you can always seek out my music!",
	touch = "Are you tired of working? Well, is there anything you'd like to listen to?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 202152,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "",
	detail = "Commander, I often perform in the main plaza. It'd be nice if you could come and listen.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202153] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Commander, you must be tired. Ahem! Please have some refreshments while you enjoy my upcoming performance!",
	unlock = "\"Next, Aurora will perform something you've never seen before - traditional Sichuan mask-changing opera!\" Hehe... Commander, I look like the real deal, right?",
	touch2 = "C-Commander?! If you keep this up, I'm going to use my polearm and sword, and um... it's going to hurt!",
	mission = "",
	vote = "",
	drop_descrip = "\"Next, Aurora will perform something you've never seen before - traditional Sichuan mask-changing opera!\" Hehe... Commander, I look like the real deal, right?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Commander, is there some mask that represents... um, \"love?\" Huh? Just show it with my own face? G-goodness, Commander, an elegant lady is supposed to maintain her composure.",
	main = "One of the specialities of Sichuan opera is something called \"mask changing.\" It lets you quickly portray different emotions, or even different characters. Hehe, it took a lot of practice to be able to do this. |\"Behind each minute on the stage is ten years of practice.\" The Dragon Empery's old adages are quite thought-provoking... |Commander, do you know how many different types of plays there are in the Dragon Empery?",
	touch = "What are these weapons for? Um, right now, I mostly play the flower girl character, but I hope to be able to play some warriors too! Hehe~",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 202153,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "What kind of performance should I prepare for today? I have too many things to choose from...",
	detail = "The operas are just a glimpse of the Dragon Empery's five thousand rich years of culture and history... As a ship with a deep connection with the Dragon Empery, I hope to share the charm of these ancient traditions with many more people!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202158] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The way you're staring at me... are you waiting for me to remind you to welcome the others back? Hehe~",
	win_mvp = "",
	home = "Well done. Which would you like, rose, saffron, or mint tea?",
	unlock = "Commander, please relax and take a seat. This is a special place for just the two of us... Just kidding, did I get your heart racing just now? Ehehe~",
	touch2 = "Commander...?",
	mission = "",
