_G.pg.base.ship_skin_words[202220] = {
	hp_warning = "T-trigger the anti-air defence alarm!",
	feeling3 = "Please do not blame me for being too strict. Royal etiquette is not something can be easily mastered.",
	mail = "This mail is for you. Don't worry, I'll be sure to leave when you are ready to check it.",
	expedition = "Commander, a commission has returned. Please follow me to greet everyone who is returning. It's proper etiquette, after all.",
	win_mvp = "As long as you strive for excellence, victory will naturally follow.",
	home = "Good work, Commander. I've prepared tea today according to your instructions from earlier. Please enjoy.",
	unlock = "Greetings, I am your Royal maid, Curlew. The responsibility of supervising the master’s daily routine falls on the maid. I will help you become a Royal gentleman through and through, so please pay attention and work hard.",
	touch2 = "C-Commander... what is the meaning of this...",
	mission = "A new mission has been posted. Please complete it as soon as possible - it's rude to keep others waiting.",
	vote = "",
	drop_descrip = "Ceres-class light cruiser - Curlew (D42)",
	feeling4 = "Just like libations, there is a time and place for drinking black tea. What, you want to have tea right now...? F-fine.. since it's been so long since you've had a break, I suppose there's no harm to it...",
	lose = "It appears that I need to have higher expectations of myself.",
	feeling1 = "To think that there would be people who cannot comprehend Royal etiquette at all...",
	skill = "I shall correct your perversion!",
	upgrade = "I am one step closer to becoming a perfect Royal maid. Thank you, Commander.",
	propose = "Since I have already made my oath with you, it would be improper if I was the only one instructing you. What would I like you to teach me? ...Master, can you please... teach me the etiquette of \"love\"?",
	feeling5 = "Being with you reminds me of the time I used to live with my sister. She'd always instruct me on how to be a prim and proper maid. I wonder if I've managed to become... an excellent maid just like her...",
	main = "Royal etiquette is steeped in social and life philosophy. Please keep that in mind at all times. |I already am a perfect maid? Surely you jest... have you not met my elder sister yet? |Lately, your etiquette has improved greatly. However, don't get too proud, Commander.",
	touch = "Please be mindful of your posture. Be confident and stand tall so that you can earn the respect of others.",
	voice_key_2 = -1,
	mission_complete = "A mission has been completed, but don't over-celebrate in an undignified manner, Commander.",
	battle = "Let's show our enemies what a Royal maid is capable of.",
	id = 202220,
	gift_dislike = "",
	gift_prefer = "What a wonderfully thoughtful and courteous gift. Thank you very much.",
	profile = "I am Curlew, one of the Royal Navy's Ceres-class light cruisers. C-class light cruiser? N-no, that's not the correct classification, please don't use that term anymore...",
	voice_key = 20222,
	headtouch = "",
	feeling2 = "The details make up the difference between success and failure, whether in etiquette or in battle. Commander, please remember to always be attentive to details.",
	login = "Welcome back, Commander. Your tie is crooked... let me fix it for you. Your otherwise refined attire cannot be taken seriously with such a flaw.",
	detail = "No matter the time or place, as a maid or as a soldier, one must always remember to observe proper etiquette.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202221] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Good work, Commander. Today, would you like to try some tea from the Dragon Empery?",
	unlock = "You can feel the profound heritage and culture of the Dragon Empery from all these customs and outfits for the Lunar New Year's Festival… It seems to be ever more necessary to study the traditions and etiquette of this wondrous culture.",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "You can feel the profound heritage and culture of the Dragon Empery from all these customs and outfits for the Lunar New Year's Festival… It seems to be ever more necessary to study the traditions and etiquette of this wondrous culture.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Commander, even if you're just eating a pork bun, please make sure to use a serviette. |Etiquette is closely linked to culture, so it's no surprise that there are many differences between the Royal Navy and the Dragon Empery. |The girls from the Empery said that they'd be willing to teach me a few New Year's greetings. Once I've learned them, I'll be able to give you some blessings!",
	touch = "For a Royal maid like myself to don the attire of the Dragon Empery... isn't this what cultural exchange is all about?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 202221,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Welcome back, Commander. Today, I'll be visiting the girls from the Dragon Empery to learn a bit more about their customs. Would you like to come with me?",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202229] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "You must be exhausted. I have prepared today's tea with your comfort in mind. A maid must always be aware of her master's condition, as well as mood. Relax, and enjoy. Hehehe.",
	unlock = "I am now more capable than ever of demonstrating the Royal Maids' style. Though I am not as talented as my sister, Curacoa, I sincerely hope you will find my service satisfactory. It is a great honour to work for you.",
	touch2 = "M- Master, what are you... Aie?!",
	mission = "",
	vote = "",
	drop_descrip = "I am now more capable than ever of demonstrating the Royal Maids' style. Though I am not as talented as my sister Curacoa, I sincerely hope you will find my service satisfactory. It is a great honour to work for you.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "\"To improve is to change. To be perfect is to change often...\" One should bear this quotation in mind.|Maintaining this new equipment takes significantly more time. I suppose that's the price of strength.|To study etiquette is to pursue knowledge. \"Only in properly managing oneself is one fit to lead others...\" Let's move forward together, Master.",
	touch = "I've made some adjustments to my outfit as suggested by the others. What do you think, Master?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 202229,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "",
	detail = "You've noticed my new fittings? Don't worry, they will not impact the execution of my duties as a maid.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202200] = {
	hp_warning = "As the Masters maid, I shall not be defeated!",
	feeling3 = "To me, there is nothing more honourable than to have the privilege of serving you, my honourable Master.",
	mail = "My honourable Master, the mail is here.",
	expedition = "My honourable Master, I have information regarding the results of a commission, so please relocate to the sofa and get in a relaxing position.",
	win_mvp = "My honourable Master, I have cleared the path so that you may move forward.",
	home = "It is good to see you return. There is tea and a light meal prepared for you. And, if you'll pardon my initiative, I have also prepared a creep... a crêpe. Would you like to have it now?",
	unlock = "It is an honour to meet you. I am Sirius of the Royal Maids, here to assume the position. Henceforth, Master, I shall serve you to protect your glory and your beliefs.",
	touch2 = "If you wish for me to service you tonight, then... M-my apologies! I made a rather careless assumption...",
	mission = "A mission of this magnitude is inconsequential. Isn't that correct, my honourable Master?",
	vote = "",
	drop_descrip = "Dido-class light cruiser – Sirius.",
	feeling4 = "If you find my embrace to be relieving, then I would gladly do so again at your command, my honourable Master.",
	lose = "How shameful... My honourable Master, it seems I have made a mess of myself. Please give this naughty maid her due punishment.",
	feeling1 = "...I implore you to be more honourable, my slightly disappointing Master.",
	skill = "My honourable Master, please grant me strength!",
	upgrade = "My honourable Master, I shall become even more gorgeous for you.",
	propose = "Oh, the bliss of getting to make this wondrous vow... Please, close your eyes for this unseemly maid and permit her to feel your warmth... My honourable Master...",
	feeling5 = "I ask of you to stand proud and illuminate all the world with your glorious image, my honourable Master...!",
	main = "\"Cleaning\"...? If it is combat you are referring to, then I vow to meet all expectations you set for me, my honourable Master.|Regardless of what may ever happen, I shall always accompany you, my honourable Master.|Achieving a balanced diet is essential for one's health. Therefore, although my cooking skill may be unsatisfactory to you, please do not forgo the meals I prepare, my honourable Master.",
	touch = "Please refrain from intimate contact while others can see us, my honourable Master.",
	voice_key_2 = -1,
	mission_complete = "My honourable Master, the mission rewards have arrived.",
	battle = "Let us bring victory and glory to our honourable Master!",
	id = 202200,
	gift_dislike = "",
	gift_prefer = "Thank you very much, my honourable Master.",
	profile = "I am Sirius, the 5th ship in the 2nd group of the Royal Navy's Dido-class of light cruisers. I participated in Operation Pedestal in the past, but now I serve as a Royal Maid and have the privilege of fighting for my honourable Master.",
	voice_key = 20220,
	headtouch = "My beloved Master... Touch me as you please.",
	feeling2 = "I take honour in my service to you, Master. However, should you find my service unsatisfactory in any way compared to the Head Maid, I kindly ask of you to tell me.",
	login = "It is good to see you return, my honourable Master.",
	detail = "My honourable Master, what would you like to learn more about today? Literature and culture? Logistics and strategy? The fine arts? Or, perhaps, you are more interested in more... carnal knowledge...?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202201] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "There is no greater happiness than your safe return, Master. Would you like to gather everyone to have tea?",
