	mission = "",
	vote = "",
	drop_descrip = "My dear, I changed into the new outfit as per your request. I would be most grateful were you to offer me words of praise, Master.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Whether it's under the swirling lights of the ballroom stage, or in the smoke and explosions of the battlefield, there will never be anything more radiant than you in my eyes. My honourable Master, please allow me to gaze upon you and be at your side, always...",
	main = "Every single maid dreams of being able to stand beside her master in such a dress... Please forgive me for my presumptuousness... |This dress seems ill-suited for combat... but since it is your wish, Master, I shall humbly carry out your will. |This necklaces suits me well...? Thank you for praising this unworthy maid, my honourable Master.",
	touch = "Oh, my Master who has intoxicated me with passions so, it is an honour to have been chosen as your dance partner.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 202201,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "",
	detail = "No matter what clothing I wear, I am still your maid and live only to fulfill your expectations, my honourable Master.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202202] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "",
	unlock = "I've received ample advice from my colleagues in the Maid Team regarding swimwear etiquette. My honourable Master, are you pleased with my appearance?",
	touch2 = "Understood. If you would like to see me in a bikini, then... Is, is that so? I'm terribly sorry... I prematurely jumped to conclusions yet again.",
