	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "My honourable Master, why are you staring at me so intently? Did this humble maid err somewhere?! ...I'm overthinking things...? |Swimming? If... if you wouldn't mind teaching me... Um, sorry, a lowly maid has no right to request your valuable time... |My honourable Master, are you tired? Something to rest on...? ...Um, if you wouldn't mind, then... feel free to use my body...!",
	touch = "My honourable Master, allow me to protect you from the sun.",
	voice_key_2 = -1,
	mission_complete = "",
