	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "No matter where we are, I shall do my utmost to keep you safe. My honourable Master, simply enjoy yourself, however you please.",
	detail = "Worry not, for I have come prepared for every occasion. Food, drinks, magazines, sunscreen, contingency combat armaments, life-saving equipment, and... a cat? Why are you here? ...Oh, umm, I was just talking to myself!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202203] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "My outfit is unsafe to wear in windy weather? Are you concerned with my wellbeing and would not want me catching a cold? Oh, honourable Master, your thoughtfulness humbles me!",
	unlock = "I have heard it is part of a maid's duties to dress to her honourable Master's liking over the holidays. Would this outfit happen to... satisfy the honourable Master's wishes?",
