	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Happy Lunar New Year, honourable Master. I have made a cup of tea for you.",
	detail = "I made some Dragon Empery dishes, however they turned out quite... Pl-Please, do not be concerned! *This* year, I vow to make delectable food that shall suit the honourable Master's palate!",
	couple_encourage = {}
