_G.pg.base.ship_skin_words[202204] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Giving you mail while I'm in this state... Oh, don't worry! For you, honourable Master, I'll do it right!",
	expedition = "The commission list... Oh, I'm sorry, it was on the floor! I'll pick it up right now!",
	win_mvp = "",
	home = "Aah, my ribbon's tangled... honourable Master, umm, I must apologize for not being able to properly greet you... Please punish your stupid, clumsy maid!",
	unlock = "To you, Honourable Master, I dedicate this dance of paradise. It is something I have spent a great deal of time practicing... I do hope that it is to your liking.",
	touch2 = "Even now... I'm ready, my honourable Master! Oh? That's not why you were touching me...?",
	mission = "",
	vote = "",
	drop_descrip = "To you, Honourable Master, I dedicate this dance of paradise. It is something I have spent a great deal of time practicing... I do hope that it is to your liking.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Even this clumsy maid has managed to earn your love and find true happiness... It's all thanks to your mercy, honourable Master. In return, I give you all of me...",
	main = "You are the only reason this clumsy maid can shine, my honourable Master. Because you've never left my side...|I wanted to help make dinner, but I wonder if I'd only get in everyone's way, so...|I made this outfit especially for you to see. Yes, I want to do everything I can to make your stay in this park as fun as possible!",
	touch = "Your warmth... I swear, I'll engrave it deep into my heart. Touch me more, my honourable Master!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "For my honourable Master!",
	id = 202204,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Have you taken a liking to my bunny ears, my honourable Master?",
	feeling2 = "",
	login = "Welcome back, honourable Master. I've put many hours into this dance, and now, I hope it will soothe your fatigue!",
	detail = "When I'm going through this hoop, it's easy for my ribbons to get tangled... Ah! Hm? You've been staring at me, honourable Master. Could it be...? If you happen to like seeing me like this...!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202208] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome back, my honourable Master. I've prepared tea and sweets... No, pardon me. Those aren't appropriate in such a time... But knowing I'm always doing something for you puts me at ease.",
	unlock = "Well met, my honourable Master. This dress represents all of my emotions. I am making my final preparations for the ceremony... Uhm, Master, do you... appreciate the way I look?",
	touch2 = "M-Master, I... I fully understand what your touch means...!",
	mission = "",
	vote = "",
	drop_descrip = "Well met, my honourable Master. This dress represents all of my emotions. I am making my final preparations for the ceremony... Uhm, Master, do you... appreciate the way I look?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "My honourable Master, please accept all that the name Sirius represents, be it past, present, or future... My name, all that I am, and all that I stand for are forever yours... That is my one true wish.",
	main = "I've practised my vows so many times over in my heart, but when the time comes to speak them... my voice trembles. I must train and discipline myself, so that I may convey my feelings to you no matter how wildly my heart races.|The Head Maid said that today, I stand not as a maid, but as a bride. But what does acting like a bride mean? Serving you is all I know and all I want...|Keep your back straight, your smile natural. Today is the most important day of your life, so you must act accordingly... Ah, m-my dear Master?! How long have you been there? I was so lost in thought, pardon me for not noticing you...",
	touch = "Your hands are so warm, my Master... Their touch stills my racing heart. Thank you, my honourable Master.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "May my unblemished heart cut open a path for you, my honourable Master!",
	id = 202208,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "M-my dear Master... My veil isn't dishevelled, is it? Whenever I feel your touch, I feel nothing but bliss...",
	feeling2 = "",
	login = "Today is a most special day... Ah, welcome back, my one and only Master. I am prepared for this special occasion, in both heart and body.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202230] = {
	hp_warning = "I have to get the others to safety, at least...!",
	feeling3 = "Fiji is always telling me to smile more. Is she right? Oh... Sorry, I must be boring you with this...",
	mail = "Commander, you have new mail. Oh, I've been checking about once per hour. So I don't think I've... no, I haven't missed any.",
	expedition = "Commander, the commission is nearly complete. If you head out now, you should be able to meet them as they return.",
	win_mvp = "Um, I... really tried...",
	home = "Excellent work. I've prepared a report for you. Take a moment to look it over.",
	unlock = "I am Swiftsure, a light cruiser of the Royal Navy... If it is not too much for one such as myself to ask, I would like to support your fleet in whatever way I can.",
	touch2 = "Commander, um... I think fleet regulations call this kind of thing \"inappropriate...\"",
	mission = "Commander, I've finished sorting out these tasks. Do look them over.",
	vote = "",
	drop_descrip = "I am Swiftsure, a light cruiser of the Royal Navy... If it is not too much for one such as myself to ask, I would like to support your fleet in whatever way I can.",
	feeling4 = "The Commander told me to help Jamaica fix up her bike. Hehehe, it turned out to be a lot more fun than I thought... Oh, Commander, sorry... about that... just now...",
	lose = "Sorry. If only I had tried harder...",
	feeling1 = "Someone like me deserves a Commander like this...",
	skill = "Get the timing right... I should be able to do this!",
	upgrade = "Swiftsure, swiftly and surely, everyone is counting on you...!",
	propose = "I'm really sorry about all this. Are you honestly okay with someone like me...? The way I am...? Umm, if you're alright with me, then I'll gladly be your partner! Commander, thank you so much! ",
	feeling5 = "I think I'd probably be better off being all cool like Sheffield than trying to smile all the time like Fiji... Right? If I every so often let slip a smile that could catch the Commander's eye... Oh, um, forget everything I said just now!",
	main = "Commander, let's work as hard as we ever do, eh?|Commander, do you think a Lady of the Royal Navy should be more elegant? Not like the maids, I mean Fiji and Jamaica... They stand out quite a bit... is that alright?|I envy the Knight Commander. If only I could comport myself so... Sorry about that. Forget I said anything.",
	touch = "As your secretary ship, I am responsibile for everything in all of the reports.",
	voice_key_2 = -1,
	mission_complete = "Commander, I've finished tallying up the mission rewards. Do look them over.",
	battle = "All ships, forward...! Form up on me!",
	id = 202230,
	gift_dislike = "",
	gift_prefer = "My apologies... Did I do something worthy of this reward?",
	profile = "I am Swiftsure, of the Royal Navy. I joined towards the end of the war, but with it winding down and fate taking some odd twists and turns, I wasn't able to perform as expected. If it pleases you, I will serve the fleet with everything I have. Oh, but if it doesn't, you need not worry about me...",
	voice_key = 20223,
	headtouch = "",
	feeling2 = "Commander, do you have something for me? I can handle anything... Oh, but only if you're okay with me...",
	login = "Good morning. Here is your work for the day... *Sigh*...",
	detail = "Um, sorry I made such a mess... Sheffield tried to teach me how to clean, but I'm a lot worse at it than I expected... Ahaha...",
	couple_encourage = {
		{
			{
				20208
			},
			1,
			"Right! Here I go... swiftly!",
			0
		}
	}
}


