_G.pg.base.ship_skin_words[202240] = {
	hp_warning = "Do I carry on? Or do I retreat?",
	feeling3 = "Commander, why are you laughing? Did something funny happen? Won't you please tell me too?",
	mail = "Mail call? I wonder what it is? Could it be your dismissal?",
	expedition = "Ah! Commander, I think the commission team is back.",
	win_mvp = "They're a fleet of smouldering hulks... Not a single one left afloat.",
	home = "Welcome back, Commander. Did you have a good fight?",
	unlock = "Err, you're... the Commander, yes? You don't know who I am? Ah, right, I've yet to introduce myself... I'm Black Prince of the Royal Navy... Will that suffice?",
	touch2 = "Commander, does that feel nice to... touch?",
	mission = "Dereliction of duty is grounds for court-martial... Maybe you should see to those missions?",
	vote = "",
	drop_descrip = "Bellona-class light cruiser – Black Prince.",
	feeling4 = "You like sweet girls, do you, Commander? Well... hrrmm... What if I were to hug you like this? Would that make me seem sweeter?",
	lose = "I failed... No, it can't be...",
	feeling1 = "Commander, are you my... enemy?",
	skill = "Wipe them out.",
	upgrade = "Commander, have I really grown stronger?",
	propose = "The way you treasure me gives me such warmth and solace... This is what true happiness is, isn't it? Commander, please, I beg you, let us share in even more happiness...",
	feeling5 = "I'm very important to you, am I, Commander? ... Now what am I supposed to do with that? Treat you even sweeter than I do now?",
	main = "A Maid? Me? Certainly not... But I do know how to make some simple dishes, and I suppose I could bring you some tea.|I can see the water from here. Commander, do you like the ocean?|Commander, are you daydreaming? What say... I join you and we daydream together?",
	touch = "Commander? Something about my body caught your attention, did it?",
	voice_key_2 = -1,
	mission_complete = "I sorted through the mission rewards, but I'm not sure I did it right...",
	battle = "Show them neither mercy nor pity...",
	id = 202240,
	gift_dislike = "",
	gift_prefer = "Is this for me? Thank you. I really like it!",
	profile = "I am a modified Dido-class... rather was it Bellona-class? ... Right then, you could say I'm quite well-travelled. Will you be sending me all over the world too?",
	voice_key = 20224,
	headtouch = ".........Phew...",
	feeling2 = "Commander, do you have something for me? I'm sure I can handle it.",
	login = "Commander, back again same time as always, eh?",
	detail = "I am the Longbow of Crécy, and the Shield of the Realm... By your will, I am at your disposal.",
	couple_encourage = {
		{
			{
				10501,
				10309,
				21301
			},
			1,
			"Once more, altogether then.",
			0
		}
	}
}


