_G.pg.base.ship_skin_words[202243] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Mail? Is it... a party invite? We're already at the party though...",
	expedition = "",
	win_mvp = "Shall I uncork a bottle to celebrate the victory?",
	home = "Another victory? Mm, then another bottle is in order... Huh, what do you mean I don't need to pop so many?",
	unlock = "You can't have a party without champagne, right? Now, if I remember right, you're meant to give it a good shake before popping the cork... Oh no! Look out, Commander!",
	touch2 = "Commander, are you drunk? What's the matter? Your hand's all hot.",
	mission = "What do you think the punishment for forgetting about your missions should be... One glass, or one bottle?",
	vote = "",
	drop_descrip = "You can't have a party without champagne, right? Now, if I remember right, you're meant to give it a good shake before popping the cork... Oh no! Look out, Commander!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "The way to treat those important to you... is to cherish them, and share all your joys and sorrows with them, right? Mm, I'm glad to be sharing all my joy with you right now.",
	main = "Dido and Sirius seem to be busy with something... Should I go help out too?|If every day was a party and there was no fighting to be seen... that would be a pretty nice world.|You're not supposed to shake the champagne bottle if you're trying to drink from it normally, huh... I see...",
	touch = "Want another glass? Mm, coming right up~",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Disappear, like a fleeting bubble...!",
	id = 202243,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander... Would you like some champagne? Don't worry, I know how much strength to put into it this time.",
	detail = "Um, sorry I got champagne all over you. I really feel bad about it... Next time, I'll be more careful.",
	couple_encourage = {}
}


