_G.pg.base.ship_skin_words[202248] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "All the enemies have been eliminated. Don't worry, I didn't let a single speck of dirt ruin my dress.",
	home = "Here is a victory song I dedicate to you. Oh, so you noticed I'm not actually performing... I can't play the piano, so... yeah.",
	unlock = "Commander, today's the day we make our vows, so could you make me do something for you? It'll make me feel warm, and... I want to feel that warmth a lot, lot more.",
	touch2 = "Let me... warm you.",
	mission = "Looks like... you still have missions to do. Shall we do them together?",
	vote = "",
	drop_descrip = "Commander, today's the day we make our vows, so could you make me do something for you? It'll make me feel warm, and... I want to feel that warmth a lot, lot more.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "While I don't know what's next for us yet, I know I'll keep this warmth from you close to my chest. And also... I know I'm going to make you very happy.",
	main = "Are we going to hold the ceremony in a place as lovely as this? This is a hugely important day, so I want to be ready... Yeah, that's it... *blushes*|Oh, my heel came loose... Hm? You'll put it back on for me? Well, um, the ribbon on my back is a little loose, too... Could you take care of that also?|I've been getting a lot of help from you today... Hm? You feel like that's brought us closer? Yes, true... Ah, my cheeks feel so warm suddenly...",
	touch = "What do you say when making an oath? I can't think of anything... Commander, what kind of oath would you like?",
	voice_key_2 = -1,
	mission_complete = "I'll go inspect the rewards... Hm? You'll come with me? Sure thing.",
	battle = "",
	id = 202248,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "This feels... so nice.",
	feeling2 = "",
	login = "You're here, Commander. Mhm. I was waiting here the whole time.",
	detail = "No matter how much time passes, I won't forget the warmth you gave me – the warmth known as joy.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202250] = {
	hp_warning = "I still have a contingency plan.",
	feeling3 = "I'm playing very well? Master, you are able to follow in my footsteps as well... as long as you dedicate yourself to practicing every day.",
	mail = "There's new mail. I'll make sure to respond to the fanmail.",
	expedition = "Do I need to pre-record a gunshot to remind you? ...A commission fleet has returned.",
	win_mvp = "The concert went well.",
	home = "Ah, Master, welcome back~ You heard a weird voice, you say? It must've been your imagination.",
	unlock = "I am Sheffield, from the Royal Maids. I will explain how this transpired to you, so please stop looking like the world has turned upside down.",
	touch2 = "Surely you're aware of the consequences for doing such things to an idol?",
	mission = "A new offer? I shall prepare myself then.",
	vote = "",
	drop_descrip = "I am Sheffield, from the Royal Maids. I will explain how this transpired to you, so please stop looking like the world has turned upside down.",
	feeling4 = "I used to think that doing maid work would make other jobs seem trivial in comparison, but reality certainly had a very different message for me... If you dare tell anyone else about what I just said to you, I'll have to sew your lips together... Just kidding, don't take it that seriously.",
	lose = "This failure was due to my incompetence. Sincerest apologies.",
	feeling1 = "To prevent harm from befalling the other members, I shall first eliminate you.",
	skill = "May my song bring you eternal rest...",
	upgrade = "I shall commit myself fully regardless of the workplace.",
	propose = "No matter what I am, I will always love you with all my heart and soul, my Master. ...I wasn't being facetious. Really.",
	feeling5 = "The girl who you like is not the maid or the shining star, but \"Sheffield?\" ...A stale confession, but thank you. I'll remember that.",
	main = "I heard that there are some folks out there who get aroused from being abused by their favorite idol... I'll never understand. |Defeating enemies with song? Utterly unrealistic, but might make for an interesting school project. |To be honest, I'm a bit jealous of Belfast. Her talents are boundless, beyond just being a maid.",
	touch = "I may not have my gun with me, but you would still be wise to mind your conduct.",
	voice_key_2 = -1,
	mission_complete = "So these are the royalties? I'm sure the other members will be pleased.",
	battle = "I will \"clean up\" the pests that seek to disrupt this concert.",
	id = 202250,
	gift_dislike = "",
	gift_prefer = "How fascinating, I thought it inconceivable that Master would give me something like this.",
	profile = "Town-class light cruiser, Sheffield. I am currently serving as an idol at Her Majesty's request. Do you have a problem with that?",
	voice_key = 20225,
	headtouch = "",
	feeling2 = "I've had to suspend maid duties due to my idol unit activities. I will make up for lost time after this is done.",
	login = "I finished cleaning up the office before I have to head off for lessons. I'd appreciate it if you don't mess it up while I'm gone.",
	detail = "Call you Producer? No thank you, Master works just fine for me. Or... would you prefer to be called a \"pest?\"",
	couple_encourage = {
		{
			{
				90503,
				10224,
				40307,
				30710
			},
			2,
			"Let's try to muster up a semblance of teamwork.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[202260] = {
	hp_warning = "tha...that's it?",
