_G.pg.base.ship_skin_words[202270] = {
	hp_warning = "It seems I let my guard down...",
	feeling3 = "Commander, are you working overtime today? Then I'll bring over some coffee. ...Um, it's not a bother, you know? After all, being by your side no matter what is a Royal Maid's duty.",
	mail = "Is this mail for you, Commander...? I apologize. I'll leave it here.",
	expedition = "Commander, let's put our work on hold and go to greet the team that's just returned from commissions.",
	win_mvp = "I'm sure Commander will be elated~",
	home = "Commander. For the time being, you're forbidden from doing more work, okay? You need to make sure to take a break from now and then.",
	unlock = "Good day. I am Hermione, from the Royal Maids. I'm delighted to make your acquaintance, Commander.",
	touch2 = "Commander, it's good to pay attention to the time and place when doing something like this, you know?",
	mission = "Commander, the more you don't deal with your work now, the more you'll have to deal with later.",
	vote = "",
	drop_descrip = "Dido-class light cruiser – Hermione (HMS Hermione.)",
	feeling4 = "Commander, if it doesn't bother you, would you mind leaving your laundry to me? Washing our clothes together saves time, but more than that, I want you to personally feel how great your clothes feel after being hand-washed by the Royal Maids♪",
	lose = "Oh my, what a failure...",
	feeling1 = "Commander, why are you so stubborn...",
	skill = "I hope this hits~",
	upgrade = "My, have I gotten stronger?",
	propose = "You'd like for me to stay by your side, forever...? Of course, Commander. Taking care of you is my job, after all. Ah, would this be what's called a \"confession\"...? Yes, of course. Commander, I'll be in your care, from now, 'til the end of time.",
	feeling5 = "Whew... I've finished cleaning the room. Next... Oh, welcome back. I'll prepare your meal right now, so please wait a moment, Commander.",
	main = "It's not good to strain yourself by overworking. How about splashing some water on your face to refresh yourself?|It seems like the price for this ingredient has gone up... Commander, from now on, we'll have fewer dishes that use this.|Commander, watching you easily handle your work makes me feel happy... I wonder why?",
	touch = "A fizzy drink? ...What am I going to do with you? I suppose you can have just one bottle, all right?",
	voice_key_2 = -1,
	mission_complete = "This mission's reward is quite sizeable. Congratulations, Commander!",
	battle = "The enemy's been detected~",
	id = 202270,
	gift_dislike = "",
	gift_prefer = "Thank you very much. I'll put this to good use.",
	profile = "I'm Hermione, a Dido-class ship belonging to the Royal Navy. In the past... I chased after Bismarck and participated in anti-submarine warfare in Sardegna... Besides that, there's nothing worth mentioning. Commander, do you have any questions?",
	voice_key = 20227,
	headtouch = "",
	feeling2 = "Doesn't Dido worry a bit... too much? She works so hard, and I know you don't hate her, but... please, watch over her some more, Commander.",
	login = "Good morning, Commander. Did you sleep well?",
	detail = "I really admire the head of the Royal Maid, Miss Belfast... She can do anything and has a strong will to boot... I hope I can become like her one day.",
	couple_encourage = {
		{
			{
				20204
			},
			1,
			"Dido, it's not good to worry so much",
			0
		},
		{
			{
				20212
			},
			1,
			"Miss Belfast, please allow me to watch and learn!",
			0
		}
	}
}


