	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202275] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Thanks for all your hard work, Commander. Shall we see a movie? Rest a moment at a café? At the least, we should find somewhere we can take things slow.",
	unlock = "Commander, umm... Happy Valentine's Day! What do you think of my outfit? Hehe, it's perfect for a date, isn't it?",
	touch2 = "Today... Heehee, well, it is a special day.",
	mission = "",
	vote = "",
	drop_descrip = "Commander, umm... Happy Valentine's Day! What do you think of my outfit? Hehe, it's perfect for a date, isn't it?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "Someone needs a lecture on manners.",
	upgrade = "",
	propose = "",
	feeling5 = "♪~ Commander, how did you enjoy our date? Me... Yes, I'm plenty satisfied. I hate to be selfish now, but part of me can't help but think... If only I could go on such lovely dates with you every day. Hahaha!",
	main = "What do you think of when you hear Valentine's? Chocolate, of course. What chocolate do you like, Commander? All kinds? Heehee, that is a relief, but it makes things a little hard for me♪|Am I blushing? Umm, I'm probably a little nervous... We're on a date, after all. How can you blame me for a bit of anxiety?|At this time of year, shops that sell gift wrapping are busier than ever. Heehee, I'm sure you know why. ...Now that we're dating, maybe I have reason to go myself~",
	touch = "Here you go! Valentine's chocolate. ...You're surprised that I just gave it to you instead of picking the perfect moment? Please. Every moment with you is plenty romantic, so there was no need to.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Interrupting a lady's date... How extremely senseless!",
	id = 202275,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, over here! Oh, it's okay. I just arrived, myself. Let's forget all the stuffy formalities and have a fun Valentine's together.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202278] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Thank you for your hard work, Commander. Make sure to monitor your work-life balance. Otherwise, I may find a way to force you to rest... Hehehe♪",
	unlock = "I'm so happy to have come this far with you, Commander. May this gorgeous sunrise watch over us for all time... I love you, Commander.",
	touch2 = "M-may I seek your warmth, too...?",
	mission = "",
	vote = "",
	drop_descrip = "I'm so happy to have come this far with you, Commander. May this gorgeous sunrise watch over us for all time... I love you, Commander.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Hmhm~? The room's all cleaned, time for... Oh, welcome back, Commander. I'll prepare your meal right away, so please wait a bit longer~",
	main = "Caring for your health, treasuring our life together... It doesn't feel like things have changed much, does it? I guess we've been the perfect team for a long time now.|I've heard that spoiling people too much can make them lazy... But you'd never be lazy, Commander! Umm, so... It's okay to let me pamper you once in a while, okay?|Commander, take it easy whenever you want to. I like you most when you're smiling without a care in the world♪",
	touch = "Are you tired? You may rest your head in my lap, Commander.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 202278,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, you look well. Is there anything at all I can help you with?",
	detail = "I never dreamed that I'd get to meet you as I wear this dress, Commander. I'm so, so very happy...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202280] = {
	hp_warning = "I can't let the Master throw me away...!",
	feeling3 = "I look good in my idol outfit? Thank you so much, Master...! Oh, does that mean I'm not a maid anymore?! Master, you aren't going to abandon me, are you...?!",
	mail = "Looks like some important mail, Master.",
	expedition = "Tashkent tells me the commission team is back.",
	win_mvp = "I know I can do it if I work hard. I'll become an idol you can be proud of!",
	home = "Master, are you hurt? Do you feel okay? I may be an idol for now, but if you need me, I can still service you anytime...",
	unlock = "I am the light cruiser, Dido, currently taking part in idol activities as part of the experimental Muse System. I learned more or less what idols are supposed to do from the others, so p-please... keep a close eye on me!",
	touch2 = "Nnng...",
	mission = "We have a gig offer, Master. Won't you take a look?",
	vote = "",
	drop_descrip = "I am the light cruiser, Dido, currently taking part in idol activities as part of the experimental Muse System. I learned more or less what idols are supposed to do from the others, so p-please... keep a close eye on me!",
	feeling4 = "You mean you're excited to see me as a maid, and as an idol...? Sorry, I misunderstood...",
	lose = "I can't sing as well as the Head Maid...",
	feeling1 = "Did I let you down, Master? What a despicable maid I am...",
	skill = "As an idol, for the Master...!",
	upgrade = "I wonder if Albacore's idea could actually work...",
	propose = "It's unthinkable that a lowly maid could shine onstage with all of you... But I will redouble my efforts to be worthy of the honour! All for the sake of my dearest Master!",
	feeling5 = "I'm doing well as a maid, and as an idol...? I'm honoured by your praise! I'll keep working hard as an idol... No, I'll keep working hard in everything I do for you, Master!",
	main = "Singing is more about conveying one's feelings than it is skill... So I will keep singing for you, Master...|Madam Illustrious focuses so much on her footwork during dance practice... is it because of the mirror?|My fellow maids, and the girls from the different camps come together to make a proper idol unit. It's truly amazing that you can bring all of us together, Master.",
	touch = "You need only ask and I'll be happy to shake your hand, or whatever you may want!",
	voice_key_2 = -1,
	mission_complete = "Master, here are the rewards. It's all thanks to their hard work.",
	battle = "Now, to steal Master's heart... with my dance!",
	id = 202280,
	gift_dislike = "",
	gift_prefer = "I never thought I would receive a present from Master... I am simply overjoyed!",
	profile = "I'm Dido, Royal Navy Light Cruiser. I'm but a lowly maid, and I never expected to be chosen to be an idol... But I'll do what I can!",
	voice_key = 20228,
	headtouch = "",
	feeling2 = "No longer a maid serving her master, I'm now an idol.I've learned so much from the other maids, but I'm still not sure if I can do this right...",
	login = "Master, what would you have me do today? Idol things or maid things, I'll do anything you want!",
	detail = "Between my idol lessons and shows, training and my maid duties, all to be useful to you, Master... It's a lot of work? You want to reduce my workload...? P- please don't throw me away...!",
	couple_encourage = {
		{
			{
				20227
			},
			1,
			"It's okay to show off from time to time...!",
			0
		},
		{
			{
				30711
			},
			1,
			"If only I could present myself to the Master like that!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[202290] = {
	hp_warning = "I... can still do this!",
	feeling3 = "If I leave the uncompleted work here, I wonder if eventually, I won't have to do it anymore.",
	mail = "Hmm... Ah, I knew I was forgetting something... Um... Right. The mail. Commander, I brought you the mail.",
	expedition = "The commission has been completed, and now I'm supposed to welcome the fleet back... But what comes after that?",
	win_mvp = "Commander, I followed your instructions and emerged victorious.",
	home = "I am glad that you have returned safely, Commander.",
	unlock = "Arethusa-class light cruiser... Penelope, is my name. From now on, I will be your subordinate. I hope that you... can at least remember my name.",
	touch2 = "Hm...? Commander, what are you doing?",
	mission = "\"Remind the commander if there are any unfinished missions.\" ...Got it. Commander, you have unfinished missions. What are they about? Umm...",
	vote = "",
	drop_descrip = "Arethusa-class light cruiser – Penelope.",
	feeling4 = "Would you like some of the rosehip tea that Aurora taught me to make? ...It's too sour? Hmm... Maybe I accidentally added vinegar...",
	lose = "I have been defeated. My sincerest apologies...",
	feeling1 = "Commander... aren't you acting a bit weird?",
	skill = "Is this good enough?",
	upgrade = "Have I become stronger than before?",
	propose = "A promise ring... proof that you always want to stay with me? Mm... But, even without this, as long as you think of me, sometimes call for me, and look at me... that's all I need.",
	feeling5 = "No matter how much time passes, I will continue to wait for you here, Commander. No matter what, I'll always wait for you to come back.",
	main = "Paperwork, paperwork... Where did I put it again? On that shelf? I can't seem to remember...|Pepperpot? ...Why yes, I do think that food generally tastes better with a healthy pinch of pepper.|I want to get along with U-410. ...Mm, with you here, Commander, I'm sure it will be fine.",
	touch = "...Hm? Is something amiss? I do believe I've been doing everything to your specifications...",
	voice_key_2 = -1,
	mission_complete = "\"Remind the commander to collect the rewards for completed missions.\" ...Got it. Commander, please remember to collect your rewards. What rewards? Umm...",
	battle = "Shall we go together?",
	id = 202290,
	gift_dislike = "",
	gift_prefer = "I'll cherish this. Thank you.",
	profile = "I am Penelope of the Royal Navy, Arethusa-class light cruiser. I participated in a transport mission with Aurora and her companions in the K Fleet. There were difficult times, but I managed to pull through. If only I had noticed her back then...",
	voice_key = 20229,
	headtouch = "Nnh... Are you treating me like a child?",
	feeling2 = "I shall wait for you here tomorrow as well, just as you instructed, Commander.",
	login = "Commander, are you going on a sortie? I shall stay here and await your return.",
	detail = "Hmm... You're staring at me so much... Did you happen to want these gloves?",
	couple_encourage = {
		{
			{
				20132
			},
			1,
			"I'm counting on you.",
			0
		},
		{
			{
				20215
			},
			1,
			"Aurora, we're together again.",
			0
		},
		{
			{
				29901
			},
			1,
			"Neptune... Um, sorry...",
			0
		},
		{
			{
				30172,
				10307
			},
			2,
			"Did you say something...?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[202291] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Commander, do you know about the Spring Festival? There are all kinds of interesting stories, and I'd like to hear more about that from you.",
	unlock = "Aurora chose this outfit for me because... the Spring Festival represents a time of celebration in the Dragon Empery, and red is the color that best symbolizes that. What do you think? Does this outfit... make you feel more festive?",
	touch2 = "...Um, Commander, I don't think... this is any way to conduct yourself.",
	mission = "",
	vote = "",
	drop_descrip = "Aurora chose this outfit for me because... the Spring Festival represents a time of celebration in the Dragon Empery, and red is the color that best symbolizes that. What do you think? Does this outfit... make you feel more festive?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Haah... Commander, I'm sorry... At this rate, this incense... is going to make me fall asleep... Zzzzz|The broth in the hotpot was as red as my clothes... It was a bit scary at first, but the food ended up being really delicious.|The pattern on this fan was embroidered. I learned how to do it from Yat Sen and the others a while back, but my hands were trembling so much I made a mess of things... Ugh, I wonder how everyone does this so well.",
	touch = "...Hm? Already tired? You can lie down here if you'd like.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 202291,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Happy Lunar New Year. I'm glad I can see you today.",
	detail = "Aurora also gave me this incense burner. It's supposed to be good for recovering from fatigue, so shall we give it a try together?",
	couple_encourage = {}
}


