_G.pg.base.ship_skin_words[202333] = {
	hp_warning = "",
	feeling3 = "",
	mail = "There's mail for you. Reading it, replying to it... Add to your list of good deeds one at a time.",
	expedition = "",
	win_mvp = "I only gave them the proper punishment for defying you, Master. Heehee.",
	home = "Welcome back, Master. If you'd like an appraisal of the previous battle, then don't hesitate to ask. Whether you'd like to rejoice in victory or be punished after defeat... Well, you just leave it all to me.",
