	touch2 = "You seem to enjoy how I accept your sinful acts, Master...",
	mission = "It isn't always optimal to rush through your missions. Finish them at your own pace, Master.",
	vote = "",
	drop_descrip = "Welcome, my dear Master – no, I suppose you're just a traveler at this moment? I'd like to say, \"All who pass through here must be judged,\" but I wouldn't be against simply letting my Master through.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "My, are you that worried about your daily deeds now? Don't worry. I accept every bit of you. My pitiful Master, my anxious Master, my poor Master, my sinful Master... All of them are mine♥",
	main = "Please, Master, show me your truest side. I'll do the same thing in return.|\"Sorry, but it seems you're hellbound.\" If I said that to you, how would you react? Heehee♥|Your fate is like putty in my hands... Far too much power for one maid to wield, but doesn't it sound exciting?|If you want, I could join you in your travels. To leave my role behind and work only as your most loyal maid... Really, I'm more accustomed to that to begin with, heehee.",
	touch = "Oh, Master? You'd entrust me with both your life and your fate? I'm more than happy to accept both.",
	voice_key_2 = -1,
	mission_complete = "Your missions are completed. A job well done, I say. Heehee♥",
	battle = "",
	id = 202333,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "If you want to receive my judgment, then I'm more than happy to oblige. I'll even do it over and over until you're satisfied with the result... Heehee.",
	detail = "This outfit is very different from what I typically wear. The style of the Nile, I suppose... Master, I noticed you staring. Don't avert your eyes now.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202340] = {
	hp_warning = "Hahaha! This is awesome!",
	feeling3 = "Master, would you rather have an eel bowl or lobscouse? Got it, you're fine with either. Then I'll just make both! Heheh, they're both my speciality dishes. Truth be told, I wasn't gonna let you choose anyway♪",
	mail = "God, look at this pile of letters! Oh no! It... It collapsed!",
	expedition = "Master, remember to smile when you talk to the commission team!",
	win_mvp = "Victory's ours! Now come here, Master! I wanna take a selfie with you!",
	home = "Welcome back, Master! I've got tea ready for– Oh! It's gone cold. Lemme put the kettle on again!",
	unlock = "Hello, Master! I'm Liverpool, Gloucester-class light cruiser! Come on, get over here! 3, 2, 1, say \"cheese\"! ...Yeah, that's a nice smile! Oh, and if Gloucester asks about me, will you do me a solid and say you haven't seen me? Cheers.",
	touch2 = "Ahahaha... If you're so desperate to turn into eel food, then fine!",
	mission = "A new mission list has... Blimey, that's long! And you've really got to do every task on here?",
	vote = "拉票描述",
	drop_descrip = "Gloucester-class light cruiser – Liverpool.",
	feeling4 = "You think I've been acting weird? I haven't really. Why are you telling me this all of... My face is red? I'm not sick, I just– Whoa! Oi, don't cling to me like that... A-and stop trying to take my temperature!",
	lose = "Ahahaha... Here I thought a happy-go-lucky maid could solve just about anything.",
	feeling1 = "Gosh, if this keeps up, I'LL be the one lecturing YOU instead of the other way around.",
	skill = "Let the chase begin!",
	upgrade = "I've gotten stronger! Maybe my smartphone camera's specs improved as well? Hm? That's not how it works? Ah, I hear you.",
	propose = "You've got a present for me? Uh-huh, and what's in the box... Wait, WHAT?! A-and you've got something important to tell me? O-okay! I'm in the right headspace for this... My answer is yes! I will gladly stay by your side forever!",
	feeling5 = "M-Master! I've, uhh, got something I wanna tell you... Nervous? Am not! Anyway, listen... Um, I love you! Oh, err, you don't need to say anything back right away! In fact, I'm not sure I'm ready yet to hear your response...",
	main = "Can't exactly say I'm a natural at maid work, but I do my job decently. I've got the energy to tackle all problems when they arise!|I got sooo many snacks today! Everything from dried fruits, to donuts, to roasted eel... How come, you ask? Heheh, because I'm everyone's BFF, that's why!|Hmm... I look too silly in this pic, and too cold in this one. Maybe this one... Oh, I know! Master! Come take a selfie with me! 3, 2, 1, say \"cheese\"! Alright, looking good!",
	touch = "(Whew... Psst, Master, don't you wanna ditch this place? I'll come with you. \"What about my maid work\"? Ahaha! I wasn't gonna do that anyway, so it's alright!)",
	voice_key_2 = -1,
	mission_complete = "...Check the mission rewards? Ahaha! Nah, I don't work in that capacity. But I can snap a pic of you doing it, if you want.",
	battle = "Brighten up and show 'em who's boss!",
	id = 202340,
	gift_dislike = "",
	gift_prefer = "This is for me? Thank you, Master!",
	profile = "I'm Liverpool, pennant number C11, Gloucester-class light cruiser. I've got a decent amount of experience under my belt, and I've served in a fair few fleets... Aerial torpedoes? Ahahaha... Those don't scare THIS happy-go-lucky maid!",
	voice_key = 20234,
	headtouch = "Hooray! Master gave me headpats♡",
	feeling2 = "You think I'm much more lively than the average Royal Maid? I mean, having energy to spare and being happy-go-lucky is just my nature! Or what, do you take me for some kind of bimbo?",
	login = "Morning, Master! It's a new day, so let's see a smile! Like this!",
	detail = "Let's see a smile, Master! When you smile, Lady Luck smiles upon you! Smiling makes you live longer, too!",
	couple_encourage = {
		{
			{
				20210
			},
			1,
			" Oh no! I'm sorry for everything I ever did, just let me off the hook this one time!",
			0
		},
		{
			{
				20209
			},
			1,
			" Oi, Manchester! Come and take a pic with me!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[202341] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "I offer a prayer for my Master's victory... Hey, uh, how did the prayer go again?",
