	drop_descrip = "Holy Wind! Blow them away! ...Oh no! The wind's so strong it's lifting up my dress! Um, Master, y-you didn't... see anything, did you?",
	feeling4 = "",
	lose = "Ugh... Seems there are some problems even a happy-go-lucky cleric can't solve...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Heheh, you ready, Master? Hold the camera steady and capture the moment I unleash a cool-arse spell! ...What's it for? To celebrate our date in Adventureland, duh!",
	main = "\"May you be blessed by the holy light\"... Heehee, how was that, Master? Did I sound like a cleric?|Weird... I just chanted some nonsense and it cast some OP-arse holy spell... \"That's because you're a cleric\"? Ahahah! Yeah, I guess you're not wrong!|So – holy protection, a good-luck blessing, or just an ordinary strength blessing? Hmm... I'm not sure which to choose...|Bollocks. I've got a role to play, but I've still been calling you \"Master\" instead of \"Hero\"... I plead whoopsie-daisy! Heehee!",
	touch = "Hm? You want some blessings? You got it, Master! Watch this! I know a holy spell to make our adventure more fun – it's called smiling!",
	voice_key_2 = -1,
	mission_complete = "Quest rewards are here! Maybe there're some ingredients... Ahahaha, no, I'm not expecting anything.",
	battle = "",
	id = 202341,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Here I am, Master! Let's go on another fun adventure together! And give me a smile!",
	detail = "\"God has granted us this solace.\" Heehee, now let's let loose and have fun, Master!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202350] = {
	hp_warning = "Don't worry. I brought a medical tome... Wait, this is a cookbook!",
	feeling3 = "You understand me more by the day. By the way, I was gifted with the most interesting prophecy... \"When the wise meets their destined one, two rainbows will shine above.\" It's just like when we first met!",
	mail = "There's new information for you. I just can't believe it wasn't written on papyrus with a golden quill pen...",
	expedition = "Master, behold! A commission has been completed! I calculated the time using astronomical observation... Huh? I can just set an alarm on my phone? B-but I was right!",
	win_mvp = "Only through Master and the gods' blessing, heehee!",
	home = "Welcome back. Let me brew a cup of the Nile civilization's most popular black tea... Huh? You say black tea didn't exist back then? Th-then do you know what vessels they used to drink water? Good! I'm happy to explain!",
	unlock = "I am Cleopatra. A Royal Maid in body, but an inheritor of great wisdom... Hm? Are you my master? Well, I'm both a skilled maid and a born wisewoman. You must know the 72 ways of hospitality of Nile tradition, surely? Because I do.",
	touch2 = "Eep?! M-Master... I was focused on a very important thought...",
	mission = "Master, you still have missions that need doing. Do you require my help?",
	vote = "",
	drop_descrip = "Dido-class light cruiser – Cleopatra.",
	feeling4 = "Do you suppose I only think about Nile culture all day, every day? I happen to take my maidly duties seriously! I make daily schedules, prepare meals, and even do little things like making beds!",
	lose = "I-I'm sorry, Master...",
	feeling1 = "Legend has it that those who ignore the words of the wise will become cacti in the desert...",
	skill = "Behold power blessed by the Nile gods!",
	upgrade = "Ooh. Has my tan gotten even prettier?",
	propose = "Hmm... According to this record of Nile civilization, the Ring of Promise should be worn on... Huh? This finger? My Master is ever so knowledgeable! I look forward to receiving more of your sage wisdom from now on♡",
	feeling5 = "Master, have you ever heard the story of queen and her lover? Don't you think their first meeting was a lot like ours? Heehee, but I think your legend will be even more glorious! After all... You have a wise maid by your side!",
	main = "Master, do you see these designs on my dress? They're based on, umm... someone VII's dress... Ugh, I forgot her name already!|Heehee... According to my divination, you should spend today's afternoon tea with the most sage of Royal Maids. That will bring you good luck!|Do you know why so many cats live at port? Allow me to explain~ They're actually agents that I sent to monitor you, haha!",
	touch = "Heehee. Do you need my service, Master?",
	voice_key_2 = -1,
	mission_complete = "There are mission rewards, you say? Hmm... None of it interests me.",
	battle = "I'll divine the perfect route for us.",
	id = 202350,
	gift_dislike = "",
	gift_prefer = "Aww, you'd give me something with so much cultural value? Okay... I'm happy to accept it!",
	profile = "I'm Cleopatra, a Royal Maid and an expert on the Nile civilization. Heehee... Interested in my tan lines? They're the marks of Ra's blessing and favour... Hm? You've never heard of that? Ahaha... Anyway, let me tell you about the meaning behind my accessories!",
	voice_key = 20235,
	headtouch = "Hmm... There was a book that said frequent petting brings good luck, now that you mention it.",
	feeling2 = "Master, I learned another new means of divination! Let's... Huh? I don't have the right tools here? Umm, I'm sure playing cards will work just fine!",
	login = "Oh, welcome home. I was just thinking of fascinating phenomena – specifically, why your chair keeps scooting left... There must be mysterious forces at work!",
	detail = "Hmm... The person who sold me this amulet said it was authentic, but it says \"Made in Port\" on the bottom... That must mean there was a trade relationship between the Nile and the port in olden times!",
	couple_encourage = {
		{
			{
				20204
			},
			1,
			" Let's tan together. Tans are a sign of Ra's blessing, you know♪",
			0
		},
		{
			{
				20220
			},
			1,
			" I'll teach you the Nile's cultural dishes!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[202351] = {
	hp_warning = "",
	feeling3 = "",
	mail = "New mail? Who could this wisdom be from?",
	expedition = "Master, the commission team is back! I want to gaze at the stars with you, but... it should wait until after we've received them!",
	win_mvp = "",
	home = "Welcome back, Master! You must be exhausted after our long day together. Come lie down with me, and I will tell you the stories of the stars above.",
	unlock = "Ah, Master, welcome. How do you like the set I put together? Has your heart been stolen? This book describes how the gods arrange their rooms when they look upon the stars... It's not quite a perfect replica, but isn't it pretty?",
	touch2 = "M-Master... This is the perfect time and place...",
	mission = "Umm... You have missions left over. Now isn't really the time for this...",
	vote = "",
	drop_descrip = "Ah, Master, welcome. How do you like the set I put together? Has your heart been stolen? This book describes how the gods arrange their rooms when they look upon the stars... It's not quite a perfect replica, but isn't it pretty?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Is it because of the set... No, I think it's because you're here! Whenever you're with me, the stars seem to shine more beautifully... Heehee, the legend of the wise woman and her fated one is closely tied to the stars. Would you like to hear more?",
	main = "Heheh, I put a lot of thought into these decorations! Huh? You think they're a little... seductive? Oh, goodness, umm... Is it just me, or is it getting hot in here?|I'll explain the constellations' secrets and astrological wonders to you tonight! If you want to hear me more closely... th-then you may rest your head in my lap...|Does this swimsuit highlight my tan lines? Hehe, I'm glad you've come to see their charms!",
	touch = "Oh? Which star are you interested in, Master? I'll tell you all about it.",
	voice_key_2 = -1,
	mission_complete = "Thank goodness... Your missions are all done, so will you finally come back to my side? Huh? You still need to get the rewards?",
	battle = "",
	id = 202351,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Heehee... Your warmth reminds me of the sun. It makes me want to worship you instead...",
	feeling2 = "",
	login = "Heehee... I had so much fun with you today~ Huh? Do I smell like the sea breeze? But I washed up... Oh, you were just joking?",
	detail = "You like my swimsuit...? Heh, it's the most unique of all the Royal Maids', isn't it? I made it myself~",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[202360] = {
	hp_warning = "It's alright. A true hunter always finds a chance to strike back.",
	feeling3 = "Your blushing face is so much more fascinating than I imagined. I wanna see more of it.",
	mail = "Commander, a new letter has arrived. Want me to whisper its contents to you?",
	expedition = "Commander, the commission team is back. Shall we go and see them? Let's also take a detour while we're out and about♪",
	win_mvp = "Oh my, your eyes are glowing, Commander. Was my performance that charming, hmm?",
	home = "Good work out there, Commander. If you're tired, want to rest in my lap? Oh, is that a blush I see?",
	unlock = "Heehee, you look like a fun one, Commander... Let's find out whether you'll go on the offensive or run away like prey would♪",
	touch2 = "Ahh... You're awfully dominant today... You gonna stop here, or will you keep going?",
	mission = "My, you've got some unfinished missions. Shall we do them together? It's not good to be lazy, you know.",
	vote = "拉票描述",
	drop_descrip = "Fiji-class light cruiser – Trinidad.",
	feeling4 = "That ba-dump, ba-dump I hear whenever I come near you... I wonder if it's coming from you – or maybe it's from me. How amusing...",
	lose = "Whew... I might've lost my cool back there...",
	feeling1 = "Now I know the kind of person you are. So disappointing. Maybe I'll resume my little hunt...",
	skill = "Caught you!",
	upgrade = "Heehee. Want to see how much I've grown?",
	propose = "From now on, you're prey who belongs to me and me only... Ah, or perhaps I should say you're my \"partner!\" You chose me of your own accord, after all – we need to keep our game of cat and mouse going forever♡",
	feeling5 = "How unexpected – I fell for you, and not the other way around. Which of us is really the prey, and who's really the hunter? Well, it's not like it matters now.",
	main = "Aww, my nails aren't quite coming together. Commander, mind if I repaint them right away?|Can I interest you in a game, Commander? I'll hug you from behind, and you have to guess who it is – well, I suppose there'd be no guessing involved♪|Work this, work that... I'm dying for a break, so why don't we have some tea? No? Why won't you just answer, \"Okay, let's\"?",
	touch = "Hm? I'm watching you.",
	voice_key_2 = -1,
	mission_complete = "You haven't claimed your mission rewards? Is that because you're hoping for some special reward from me?",
	battle = "You like it when I get serious? Okay, then watch this.",
	id = 202360,
	gift_dislike = "",
	gift_prefer = "My, my.. Your taste in gifts has gotten better and better. This is quite wonderful. I'll have to... think of a way to \"return the favour\"~♪",
	profile = "I'm Trinidad of the Royal Navy. Want to know more about me? Okay, then look at this – there's my red nails, then the aroma in my hair... everything about me hides a secret waiting to be found by you.",
	voice_key = 20236,
	headtouch = "Ooh, your hand feels kind of cold... Want me to warm it up?",
	feeling2 = "Heehee... You seem unwarrantedly wary of me. Oh well. If anything, I like it when my \"prey\" is like that.",
	login = "Your collar is a little loose. I can adjust it for you. Want me to spray some heartening perfume on you while I'm at it?",
	detail = "Oh, you think I adore red colours too much? Personally, I think beautiful, dangerous colours suit me. What do you think?",
	couple_encourage = {
		{
			{
				20217,
				20216
			},
			1,
			" My, I see you and I are going hunting today♪",
			0
		}
	}
}


_G.pg.base.ship_skin_words[202361] = {
	hp_warning = "",
	feeling3 = "",
	mail = "A new letter has come in. Then again, you're in no position to read it right now♡",
