_G.pg.base.ship_skin_words[202370] = {
	hp_warning = "You've made a mess of my attire... No, no, this will not do!",
	feeling3 = "Your pen-holding technique is better than last week's, and your collar is much neater, as well... Have you been taking my advice to heart?",
	mail = "Commander, new mail has arrived. Shall I pen a response for you?",
	expedition = "The commission team has returned. Shall we welcome them home, Commander? I've prepared the perfect celebration for them.",
	win_mvp = "A superb victory is deserving of a superb encore, don't you think?",
	home = "Welcome home, Commander. I prepared lavender tea to help you relax. Take a break and let its warmth help you forget the chilly sea breeze.",
	unlock = "I am Superb, a Royal Navy light cruiser, presenting my most superb entrance for you. Rest assured and leave anything to me, Commander~ Starting today, your life is about to become super dazzling.",
	touch2 = "Commander, are you looking for a... private lesson, perhaps?",
	mission = "We're still on the job, Commander. Do you have any suggestions regarding how we should proceed with this task?",
	vote = "",
	drop_descrip = "Swiftsure-class light cruiser, group 2 – Superb.",
	feeling4 = "You seem to glance my way more often lately. Are you learning from my etiquette? Or... do you just like what you see? Heehee, I don't mind either way. I'll just have to show you my most superb self.",
	lose = "We must maintain grace, even as we bow out.",
	feeling1 = "I suppose my arrangements are not to your satisfaction.",
	skill = "Behold a superbly spectacular opening act!",
	upgrade = "Oh, yes... I'm really superb now, aren't I?",
	propose = "I've rehearsed this event in my mind countless times – what flowers would go best in the bouquet, what tableware to have at the party... But now that we're here, those details don't seem to matter much anymore... Heehee. Let me tell you one thing: yes, I'll be yours forever.",
	feeling5 = "True beauty lies in perfecting every detail. I'm very proud of you for continuing to refine your etiquette, Commander. Heehee, I'm not just acknowledging you – this is genuine praise.",
	main = "Commander, put that work aside for a moment and have afternoon tea with me. Please eat starting with the savoury at the bottom, then the scones in the middle, and finally... the cake on top.|There was an abstract art exhibit at port. I did go there, but... Hmm, how should I put it? If nothing else, I could tell that there were flowers in that vase!|You sit with perfect posture... It's just a shame that your collar is crooked~ Stay still, and I'll fix it for you.",
	touch = "Commander, that was poor manners... But I suppose I can forgive you, just this once.",
	voice_key_2 = -1,
	mission_complete = "You've completed your mission! A superb round of applause for you, dear Commander.",
	battle = "Are you ready, everyone? Fire your salutes!",
	id = 202370,
	gift_dislike = "",
	gift_prefer = "Isn't this a lovely gift! You have a good eye for aesthetics.",
	profile = "I am Superb, a ceremonial ship of the Royal Navy. My duty is to meticulously polish every ceremony until they shine like diamonds. Commander, I invite you to witness that Royal glory firsthand.",
	voice_key = 20237,
	headtouch = "When greeting me, you ought to kiss my hand.",
	feeling2 = "My Royal etiquette lectures are on Saturdays. You're free to come and sit in, if you'd like. Of course... I will arrange opportunities for you to put the lessons into practice, as well.",
	login = "Sit down and have a cup of tea, Commander. Today's weather goes perfectly with this tea set.",
	detail = "A mess? Oh, I'm sure it might look that way, but every item here has its own home and a good reason for being there.",
	couple_encourage = {
		{
			{
				20223
			},
			1,
			" It's our turn to take the stage now!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[202371] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
