_G.pg.base.ship_skin_words[203010] = {
	hp_warning = "There seems to be a slight miscalculation...",
	feeling3 = "Your Excellency, would you like to have tea together? If you're not done with your work yet, then please tend to it first. Of course, I will be with you.",
	mail = "Your new mail is right over here. Please confirm it.",
	expedition = "Yes, the commission is done on time. Let's verify the results, shall we?",
	win_mvp = "Being praised by your Excellency is the greatest honor to me.",
	home = "Good work. I'll handle the official matters, so please go have some hot red tea.",
	unlock = "First ship of the London class, London. Member of the First Cruising Fleet, while also having took part in battles of North Atlantic and Pacific missions. If there's a mission, rest assured and let me handle it!",
	touch2 = "Pl... please don't do such an improper thing!",
	mission = "Do your best to finish your missions today.",
	vote = "",
	drop_descrip = "London-class heavy cruiser – London, Hull Number 69!",
	feeling4 = "A date? If your Excellency can finish all the work for the coming days, then there's no reason for me to refuse. How about it? Do you want to make the effort?",
	lose = "...I shouldn't be showing you manners when it comes to this.",
	feeling1 = "Your Excellency, please go elsewhere for your time. I shall handle everything here.",
	skill = "Well then, I'm gonna try harder as well.",
	upgrade = "I'm glad, but please mind the allocation of resources.",
	propose = "Thank you, please leave it there. More than that, look at this, Your Excellency... Surprised? Hehe. With our relationship, you should know why I'm not saying anything about this~ But, now that this is the occasion, let me handle the meal for today, with lots of what we like to eat.",
	feeling5 = "Please stay still! I had already told you to dress yourself properly. And your hair... You can be far too casual with your appearance at times, your Excellency... Yes, that should do. Where do we go for our date?",
	main = "Your Excellency... have you seen Amethyst? I've been searching for her.|The Arctic was very cold. I still feel like i'm getting a cold from there...|My, this is a fine day. Erm, well... I thought it's a good time for a conversation...",
	touch = "Bodily contact is... No, I don't mind. I'm just not used to it.",
	voice_key_2 = -1,
	mission_complete = "I've already made a list of the rewards. Please take a look at them when you have a moment.",
	battle = "Everyone, please be mindful of yourselves. Do not get hurt if possible!",
	id = 203010,
	gift_dislike = "",
	gift_prefer = "Thank you very much. I shall treasure this.",
	profile = "I am the lead ship of London class , London. I was a member of the First Cruising Fleet, and fought battles in North Atlantic and Pacific waters. Your Excellency, rest assured and leave the missions to me!",
	voice_key = 20301,
	headtouch = "",
	feeling2 = "Your Excellency, a moment please. There's a bit of a problem here... Mmm, yes!... Is there anything you need?",
	login = "Good day to you, your Excellency. I shall accompany you for today as well.",
	detail = "What's the matter? Your Excellency, what are you looking at so seriously?",
	couple_encourage = {
		{
			{
				20302,
				20303,
				20304,
				20305,
				20306
			},
			2,
			"County-class sisters, now is our time!",
			0
		},
		{
			{
				20309
			},
			1,
			"Now, now, let's turn that frown upside-down.",
			0
		},
		{
			{
				20302
			},
			1,
			"Keep teasing Our Excellency and I will punish you.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[203011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome back, Your Excellency. Hey, I wanted to ask you something about your... break times, I suppose. Heehee.",
	unlock = "Splendid work today, Your Excellency. Here are your documents for the next mission. It has everything you need to know, so please give it a read. Heehee, I'm happy to assist so that you may focus solely on achieving your goals.",
	touch2 = "Mmh... Maybe I should get changed... Hm? You'd really prefer it if I stuck around a while longer?",
	mission = "",
	vote = "",
	drop_descrip = "Splendid work today, Your Excellency. Here are your documents for the next mission. It has everything you need to know, so please give it a read. Heehee, I'm happy to assist so that you may focus solely on achieving your goals.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Although I do like the sound of filing paperwork normally as a shipgirl and getting paid a salary... For now, I'm content to serve by your side in this way, Your Excellency.|Galatea told me about a personality test that has been making the rounds. It supposedly measures how much love is in your heart. Um, Your Excellency... would you like to take that test with me?|Are you going outside? Alright, then please allow me to drive the car and pilot the mass-produced ship.|Sussex, you ought to look into how to be of service to Our Excellency. Here, this is a book on developing secretarial skills. Read it when you have the time.",
	touch = "Heehee. No need to hurry; I'm not going anywhere. I'll wait patiently until you've finished your work.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 203011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "It's a bit chilly today, so I took out a coat for you, Your Excellency. You may feel it's unnecessary, but... it's just in case. Please bear that in mind.",
	detail = "Post-battle results, supply requisitions, next field of operations data analysis... Sorry for working overtime, I just want to assist you as much as I can... D-do you think I'm letting my personal feelings influence my work?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[203018] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "A commission has been completed. Do remember to thank the team that worked hard to bring us these resources.",
	win_mvp = "",
	home = "I'm glad you made it back safely, Your Excellency. Shall I prepare you a hot cup of tea while you rest, as per usual?",
	unlock = "Why are you so astounded, Your Excellency? You expressly requested an unforgettable and elaborate ceremony. Heehee, you'll make it weird if you keep staring so much, so won't you please take my hand now?",
	touch2 = "How far our relationship has come...",
	mission = "I've left a note regarding your new missions. Take them on at your own pace, Your Excellency.",
	vote = "",
	drop_descrip = "Why are you so astounded, Your Excellency? You expressly requested an unforgettable and elaborate ceremony. Heehee, you'll make it weird if you keep staring so much, so won't you please take my hand now?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "What would you like for dinner tonight, Your Excellency? If nothing comes to mind, we could go grocery shopping together first so you can think while we browse the wares. If you like... you could think of it as a date, too. Heehee.",
	main = "I know you're enamoured with my dress, but you must not let your infatuation impede your work.|I've brought you refreshments to alleviate your stress. You needn't worry about putting on weight as they're made with healthy ingredients. Heehee.|A posh anniversary and a simple life aren't incompatible. Which is to say, you can certainly look forward to a candlelit dinner.",
	touch = "Us holding hands has become a perfectly ordinary thing at this point, hasn't it?",
	voice_key_2 = -1,
	mission_complete = "Mission rewards have come in. I'll write up the goods summary, if you don't mind.",
	battle = "",
	id = 203018,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Why, hello. Could you come a little closer? ...There we go. We need you to look your sharpest while at work!",
	detail = "Never change out of this dress? I see you can be quite mean, Your Excellency... Still, I'll indulge you just for a while.",
	couple_encourage = {}
}


