_G.pg.base.ship_skin_words[203020] = {
	hp_warning = "Oh dear, this is bad!",
	feeling3 = "Commander, you are a good man and you have a prospective future. But after I think about it calmly, now is just not the time. I'm sorry!",
	mail = "Commander, you have new mail~ Is it a love letter? It's a love letter, isn't it? Open it, open it!",
	expedition = "Commander? Staring at me is one thing, but you should also look out for the commission team. They have returned, you know?",
	win_mvp = "You need not shower me with praises. Pay attention to others as well~",
	home = "You were dashing, Commander! I have to put in effort as well... Hmm, how about I heal your damaged heart from the battlefield, with my junior wiles?",
	unlock = "London class' youngest, Shropshire, reporting for duty~ I've been told that I am air-headed and gullible, so I'll be giving you some problems~ Well then, my time awaits~",
	touch2 = "Ah! Commander, this is inappropriate!",
	mission = "A new mission... If you finish it properly, I will re-evaluate you right away~",
	vote = "",
	drop_descrip = "London-class heavy cruiser – Shropshire, Hull Number 73!",
	feeling4 = "You are my type, Commander, but there are no specific reasons for me to like you so... I'm sorry!",
	lose = "Commander, clumsy girls have their charms as well, wouldn't you say? Heh-hey~",
	feeling1 = "Commander, you're in the way. Move aside, move aside",
	skill = "Ganbara Knight!",
	upgrade = "It's alright to not become stronger. I'm fine as long as I can be of use to Commander~",
	propose = "I'm sorry... is what you thought I was going to say? Well Commander, from now on, my life is your life~",
	feeling5 = "Please mind the time, place and mood when you do this, so I'm sorry! ... Ah! I don't mind the amount of times you confess to me~",
	main = "I am a little nervous when I am alone with you, Commander, but since you are alone I'm fu... fully calm myself~|Com~man~der~ Help me~ Please, you are the only one I can count on~|Did you know, Commander? Sometimes, making small mistakes can make one seem cuter~",
	touch = "If you don't do your work properly, even I will show an angry face for it. Com~man~der?",
	voice_key_2 = -1,
	mission_complete = "The rewards have been distributed~ Or could it be~ that you want a reward from me?",
	battle = "I do not mind, but I really have to bring victory to Commander~",
	id = 203020,
	gift_dislike = "",
	gift_prefer = "Do I like this or not~? Teehee... that's~ a~ secret~❤",
	profile = "The youngest of London class, and sent abroad away from my sisters. That is me~ Ah, it's not that I particularly wanted your sympathy, but if you give me a little bit of attention, I'll give you high points for that! ... Acting cute? Oh shush, I was being serious you know~",
	voice_key = 20302,
	headtouch = "",
	feeling2 = "Do you need something? I'm concentrating on work right now, so spare me the sweet talk~",
	login = "Ah, have you come back, Commander? I was just about to go to your place~",
	detail = "You appear to have time, Commander~",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[203029] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "You can look at me all you want! As long as you don't forget to check your commission rewards.",
	win_mvp = "At least you're capable when it comes to complimenting me and the other girls, right? Heheh!",
	home = "Look at you, Commander! I'm falling for you all over again! ...That's enough for now, right? I don't want you getting TOO excited from all this buttering-up~",
	unlock = "As you know, I'm the youngest of London class, Shropshire~ I'm excited to work with you! Heheh, I look pretty capable now, don't I? Maybe I'll cause a little less trouble for you now, Commander!",
	touch2 = "We can't do this! But I know you won't listen~ Hmph.",
	mission = "A new mission... If you can do this, Commander, I might see you in a new light~ For real, I promise!",
	vote = "",
	drop_descrip = "As you know, I'm the youngest of London class, Shropshire~ I'm excited to work with you! Heheh, I look pretty capable now, don't I? Maybe I'll cause a little less trouble for you now, Commander!",
	feeling4 = "",
	lose = "That wasn't on purpose, I swear~!",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Oh, you messed this up here... Is that you trying to show off your good-for-nothing side, Commander? Bwuh? You say this is a real mistake?!|Commander, help meee~ You're the only person I can trust~ ...Okay, take care of this for me, please! Ehehe!|London says changing clothes can change feelings. Buuut... Whose feelings are they supposed to change, I wonder~?",
	touch = "Is this a cry for help, Commander?",
	voice_key_2 = -1,
	mission_complete = "Ready for your big reward for a job well done? Drumroooll... Next time Sussex lectures you, I'll put in a good word for you!",
	battle = "For once, Shropshire's gonna act capable! Here goes!",
	id = 203029,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Heheh, I've been waiting for you, Commander. I'll serve as your capable-ish secretary today!",
	detail = "Someone's looking awfully lazy~ Watch out before Sussex says something to you. She doesn't get that being a bit of a good-for-nothing makes you that much cooler~",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[203030] = {
	hp_warning = "",
	feeling3 = "Hey, Commander! Ah, nothing, nothing... Just keep doing you work. I'm happy just looking at you, Commander.",
	mail = "Warning! Radar indicates a paper plane folded with the new mail closing in at high speed!",
	expedition = "Good! Your commission team has successfully returned!",
	win_mvp = "Yeah! Contestant Kent is number one!",
	home = "Welcome! I'm still full of energy!",
	unlock = "Hey Commander! I'm Kent! How do you do? Good? Bad? Doesn't matter. Things will be better now that I'm here!",
	touch2 = "Oh... Commander... You big pervert...",
	mission = "Hmmm, a new mission, want to take a stab at it?",
	vote = "",
	drop_descrip = "Kent-class heavy cruiser - Kent, Hull Number 54!",
	feeling4 = "Staring...? Ah, it's nothing. I'm just wondering why you're so good looking, Commander. I'll never get tired of staring at you!",
	lose = "Ouch... Contestant Ken has been eliminated",
	feeling1 = "I'm disappointed... We don't make a good team at all.",
	skill = "Contestant Kent is sprinting!",
	upgrade = "Woah! Contestant Kent has become stronger!",
	propose = "Oh wow! Thanks, Commander! But something this important needs to be kept in a safe place. I can't afford to lose it.....",
	feeling5 = "Commander! Commander! Want to guess how many layers of armor I'm wearing? If you get it right, you get a prize! If you don't, then you'll have to count the layers yourself...!",
	main = "I forgot that Tigre isn't around...|Commander, do you wanna race against me?|I think I've seen ships from the Far East before... They look really strong!",
	touch = "Yoohoo~ Want to play, Commander?",
	voice_key_2 = -1,
	mission_complete = "Mission rewards! Let's take a look!",
	battle = "Let's show the enemies our true strength!",
	id = 203030,
	gift_dislike = "",
	gift_prefer = "Yaaay! Cheers, Commander!",
	profile = "I'm both one of the first County-class cruisers and the first ship of the Kent-class. Pretty impressive, right? Stuff like Armour can be made up with good motivation and a fighting spirit! Right?",
	voice_key = 20303,
	headtouch = "",
	feeling2 = "Commander, Let's play a game! No, it's not a catchphrase. I can change it anytime! Anyways, Let's play! Let's Play!",
	login = "Yo, Commander, let's go do something together!",
	detail = "Errr, Graciously overlook my poor armour and firepower, please!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[203040] = {
	hp_warning = "",
	feeling3 = "Reconnaissance is a very important task! Huh, I'm losing focus? W-what are you saying? I'm just o-observing the weather...",
	mail = "Commander... hm... what did I want to say... Ah, right! New mail for you!",
	expedition = "That cloud looks like cotton candy... hmm? Ah, Commander. The commission team is back~!",
	win_mvp = "That cloud looks like a.... Oh? We won?",
	home = "Good work, Commander! Care for a cup of tea?",
	unlock = "Where am I...? Ah, excuse me! Do you kno....Oh! You're the commander? This is great! I'm Suffolk, I finally found you!",
	touch2 = "... Ah! Commander! If you were here you should have said something.",
	mission = "The weather sure is nice... Oh? Commander! You've got some new missions.",
	vote = "",
	drop_descrip = "Kent-class heavy cruiser - Suffolk, Hull Number 55!",
	feeling4 = "My big sisters are so strong, if only I could be of more help to them... Huh? I'm doing a good job as well? Hehehe... I received a compliment~",
	lose = "*Cries*... If only I had paid more attention...",
	feeling1 = "... The sky is so blue...",
	skill = "What a beautiful seagull...",
	upgrade = "Now I can protect myself even if I get lost again!",
	propose = "Hmph, the Commander has finally noticed that under all that hazziness there is brilliance to be found! From now on I can be as lazy as I want. ... Huh? I can't?",
	feeling5 = "Even though it's nice to receive compliments, I am much happier just being able to support you the best I can, Commander.... Why is that?",
	main = "My greatest accomplishments were done just watching the waves like this.|Commander, want to watch the clouds with me? I bet we'll see some wonderful things!|Don't look at me like that, I've been to plenty of places before!",
	touch = "... C-Commander?",
	voice_key_2 = -1,
	mission_complete = "Commander! How can you also be so forgetful and forget to collect your rewards?",
	battle = "The enemies look quite strong...",
	id = 203040,
	gift_dislike = "",
	gift_prefer = "...Huh? Woah, I really like this! Thanks a lot, Commander!",
	profile = "I'm the fifth ship of the Kent-class. Although I look like this, I can still pull it off when it counts. During the Battle of the Denmark Strait, I basically saved the day!",
	voice_key = 20304,
	headtouch = "",
	feeling2 = "Hmm, clear skies, so a great day to scout out the waters~ Do you want to come with me, Commander?",
	login = "Commander, you're back! Me? I'm looking at the clouds.",
	detail = "My post-retrofit performance is very impressive!",
	couple_encourage = {}
}


