	touch = "The flow of the Force, can you feel it?",
	voice_key_2 = -1,
	mission_complete = "Tribulations are not solely a quest for strength, but also the rewards along with it. Don't forget.",
	battle = "Submit to the power of the Force!",
	id = 203070,
	gift_dislike = "",
	gift_prefer = "I can feel the Force bubbling up from within... As expected of my Fated companion! Thank you!",
	profile = "The nameship of the York-class heavy cruisers? That is merely an alias... One day I will conquer the Nightmare of Suda Bay, and become the Master of fate itself.",
	voice_key = 20307,
	headtouch = "",
	feeling2 = "I can feel the Force guiding our paths. Care to try out this new potion for me?",
	login = "Back from your training? Come, Fate is calling for us.",
	detail = "Feel free to admire the manifestation of my Force, though this is just the tip of the iceberg.",
