_G.pg.base.ship_skin_words[203071] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Without delving further into the Zone, we will not be able to uncover the Truth. Luckily, with you here, I will be able to enter realms normally inaccessible to me!",
	unlock = "The school has recently been consumed by a series of Mysteries... there must be some Mastermind lurking behind the scenes. Yes, another Tribulation awaits me! I shall part the veil and reveal all Truths!",
	touch2 = "Eeek! Just now, could it be... There's no doubt about it. The Mastermind took over your body to issue me a Warning!",
	mission = "",
	vote = "",
	drop_descrip = "The school has recently been consumed by a series of Mysteries... there must be some Mastermind lurking behind the scenes. Yes, another Tribulation awaits me! I shall part the veil and reveal all Truths! ",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Eyepatch? Nay. This is a tool that is necessary to seal off a portion of my Force. |Difficult Words, annoying Formulae... Curses, will I be defeated by these things before I am able to reveal the Truth?! |Exeter struggles with her Tests on a daily basis, but that is for the best. The true Tribulations are mine alone to bear.",
	touch = "Until all Truths are revealed and the Mastermind's identity is brought to light, I cannot relent!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 203071,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Now then, let us begin today's Investigation! The Mastermind will fall into our trap sooner or later!",
	detail = "The figure that suddenly showed up inside empty classrooms turned out to just be Eldridge. The mysterious stack of books in the library was nothing more than a Misdirection left by the Occult Club. And, the legends of the Ace who cloned herself to lead every sports club to victory; well, she was actually that incredible... But the Mastermind still hasn't appeared. Has my Investigation been misguided?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[203072] = {
	hp_warning = "",
	feeling3 = "",
	mail = "The messenger has returned from the depths. Could it be a message from the Unfathomable?",
	couple_encourage = "",
	expedition = "",
	win_mvp = "",
	home = "Ohhhhh... The bastions of white sand were instantly reoriginated by the waves... such is the might of the Unfathomable Force!",
	unlock = "O Unfathomable King of the slumbering depths, hear the call of my Force and step into this world through the Azur Gate! ...Huh, Commander? Why did you show up?",
	touch2 = "Ahh! ...No, can it be, your mind has been corrupted by the Unfathomable?",
	mission = "",
	vote = "",
	drop_descrip = "O Unfathomable King of the slumbering depths, hear the call of my Force and step into this world through the Azur Gate! ...Huh, Commander? Why did you show up?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "So, the first summoning failed. Such are the tribulations exacted by the Unfathomable. But I shall not capitulate so easily!|What's the matter, Commander...? Ah, could it be... the Unfathomable has left a clue upon my body?! |Bloody hell, if not for the fact that my Force is nullified by the slumbering depths' domain, I could delve even deeper in the search for Truth!",
	touch = "Excellent, let us combine our Force and channel it into this magic circle.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 203072,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "You're back? Then let us continue. This time, the Unfathomable will respond to our summons!",
	detail = "Jamaica, Z36... Through this arduous battle, I have met many companions who also see through the veil. Now, I am no longer alone in my Rebellion against Fate!"
}


