_G.pg.base.ship_skin_words[203092] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "N-now that we're through with battle, perhaps we could relax a... No, we have to focus on the party for now!",
	unlock = "What are you staring at me for? I'm just the same as any of the others... Y-you have a few more hands to shake? Of course...",
