_G.pg.base.ship_skin_words[203100] = {
	hp_warning = "I'm not giving up!",
	feeling3 = "Do I start with the salt or the sugar? Or do I mix the batter? Oh, and then there's the juicy fruits Drake gave me! What do mew think, Owner?",
	mail = "There's mail for you! I wish I could read it, but I don't know most of these words...",
	expedition = "The commission team has come back, Owner!",
	win_mvp = "Look, Owner! I won♪",
	home = "Owner! It's fine if you forget to bring me a gift, but you can't forget to give me huggles!",
	unlock = "Owneeeeer! Meeeow! Squeeze! Cuddle! Sniff! Heehee~ Here, you can have this as thanks for letting me give you the lovey-dovey cuddly-wuddly!",
	touch2 = "Here's another one for you, Owner!",
	mission = "You're amazing, Owner! You can do all these missions that are too much for me!",
	vote = "",
	drop_descrip = "Heavy cruiser – Cheshire.",
	feeling4 = "Aww... You were right, Owner. You can't make good sweets by mixing random stuff together... But I'm not gonna give up! I'll make something yummy eventually, you'll see!",
	lose = "Do we fight back meow, before they catch on? No?",
	feeling1 = "I loved you, Owner, I really did...",
	skill = "Have some cannon fire, too!",
	upgrade = "Thanks, Owner♪ Have this in return!",
	propose = "Wowie, a present! ...It's a ring? Ah, I get it, you wanna trade with me! Okey-dokey! In return, you geeet... Yup, you get me! Huggles♪",
	feeling5 = "Lookie, Owner! I made this cookie with the help of my friends! ...Huh? Why is it moving? Oh, oopsie! This isn't a cookie, it's a manjuu! Sorry I got them mixed up, Owner!",
	main = "Hey, Bel! Show me how to make good sweets!|You think I'm cute as a kitten? Heehee, you're making me blush, Owner♪|Drake! Please buy me a gift on your next trip! Something sweet would be nice!",
	touch = "What do you have for me, Owner?",
	voice_key_2 = -1,
	mission_complete = "Don't stop meow, Owner! Go get your rewards, then it's time for the next mission!",
	battle = "This is for you!",
	id = 203100,
	gift_dislike = "",
	gift_prefer = "I wuv you, Owner! Eheheh~ *rub* *rub*~♪",
	profile = "I'm Cheshire, the heavy cruiser! I'll do my best to be helpful to mew, Owner! I dunno exactly what I'm gonna do, but I'll do it well! Whee~♡",
	voice_key = 20310,
	headtouch = "Try on this kitty ear headband, Owner! Come on, have a go!",
	feeling2 = "I'm gonna make lots of yummy sweets for mew, Owner♪ ...Wait, what was step one again? I forgot...",
	login = "Owneeeeer! Mrreow~ Mmhh, you're so warm♪",
	detail = "Owner! Squeeeeze! Giving you huggles makes me all sleepy... *yawn*... Zzzzz...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[203130] = {
	hp_warning = "Tch... I lost my composure for a moment there...",
	feeling3 = "Commander, how do you prefer your Devonshire? \"A cutie-patootie?\" \"A cool girl who knows no sympathy?\" \"N-nervous mode?\" I am happy to suit your preference.",
	mail = "I finished organising your mail. Commander, when would you like to see it?",
	expedition = "The commission team is back. Please change into formal clothes when you welcome them. I believe you must always be aware of your patina as Commander.",
	win_mvp = "That took one second longer than expected. I will be more alert next time.",
	home = "Welcome back. I made tea and pastries, so enjoy a nice break.",
	unlock = "\"Pleasure to meet you, Commander. I'm the London-class heavy cruiser Devonshire. I happen to know some things about combat and maid duties. From now on, I will serve you as your personal maid. I look forward to working with you.\" I tried giving off a different vibe with this greeting. Did it come off too cold?",
	touch2 = "Right here? Commander, you're awfully bold today...",
	mission = "Commander, you have incomplete missions. Please do not forget them.",
	vote = "拉票描述",
	drop_descrip = "London-class heavy cruiser – Devonshire.",
	feeling4 = "\"Cutie-patootie mode comes in lots of little variations! Gimme a request if you want a little something special!\" ...You want to know me as I am? How... difficult you are to satisfy.",
	lose = "I've failed to take out the trash. Please retreat just in case the situation may get worse.",
	feeling1 = "*sigh*... Looks like I have to switch to business mode when dealing with you, Commander.",
	skill = "Killer mode engaged!",
	upgrade = "Technology advances quickly with the passage of time. Such palpable growth... I must thank you, Commander.",
	propose = "A truly skilled maid must be able to respond to all kinds of situations. It's only natural that we get used to putting on different facades... However, there is only one truth to how I feel about you, Commander. That will never change.",
	feeling5 = "You really are a greedy one, Commander, so seriously pursuing the truth of who I am. But I accept your feelings... In return for your authenticity, I will try to show you my unabridged self as well.",
	main = "As your maid, I have put together a perfect schedule for you. Yes, and I've ironed your clothes for your important meeting for you.|A sudden change of plans? That is quite the change... \"Tch. If I must, I'll rearrange EVERYTHING for you. Again.\"|Ahem. I've had enough of being-a-reliable-maid mode. Cutie-patootie mode engaged. \"What do I do? Aw, what a jam... I wanna eat the port sweets store's new donut sooo bad~ Commander, buy it for me!\"",
	touch = "Yes? Would you like me to switch to service mode?",
	voice_key_2 = -1,
	mission_complete = "If the rewards are donuts, then I will gladly take them in your place.",
	battle = "Cleaning mode engaged.",
	id = 203130,
	gift_dislike = "",
	gift_prefer = "Thank you. I accept this gift, along with the feelings you've poured into it.",
	profile = "I am Devonshire, London-class heavy cruiser. I have many achievements as a Royal Maid, such as traveling around the world and escorting important personnel. You think that would have broadened my perspectives? \"Heehee, you're too sweet.\"",
	voice_key = 20313,
	headtouch = "\"Commander? I don't presume you're treating me like a child?\"",
	feeling2 = "\"Baking sweets is such a basic thing for maids, so I'm confident in my skills~ Teehee, try my home-baked donuts, Commander! Just be warned, they're bonito-flavored!\"",
	login = "Oh, you're here. Is it time to begin today's work? ...Don't worry. I've gotten everything ready.",
	detail = "Mm, yes, I do like that expression. The surprise coloured by a charming shade of panic... Let's practice it in the mirror a little more.",
	couple_encourage = {
		{
			{
				20301
			},
			1,
			"London, you're far too gentle.",
			0
		},
		{
			{
				20309
			},
			1,
			"Gee, Sussex, don't be so nervous all the time!",
			0
		},
		{
			{
				20302
			},
			1,
			"Quit getting distracted in the middle of battle. Hmph!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[203131] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "\"Back so soon? You're not as weak as I thought.\" I'm afraid I cannot serve refreshments while I'm in roleplay mode. My apologies.",
	unlock = "Roleplay mode engaged. \"I am Devonshire, the greater demon who controls this land. If you understand the difference in our power levels, you will leave and train yourself in a beginner dungeon for three hundred years. Adventurers such as you will never make it through here alive.\"",
	touch2 = "\"Heheheh... Can I take this as a sign of surrender?\"",
	mission = "\"A request with a reward... Hmph. Do you mean to say that this is worthy of a greater demon's attention?\"",
	vote = "拉票描述",
	drop_descrip = "Roleplay mode engaged. \"I am Devonshire, the greater demon who controls this land. If you understand the difference in our power levels, you will leave and train yourself in a beginner dungeon for three hundred years. Adventurers such as you will never make it through here alive.\"",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "\"Even knowing that this is a game, you refuse to hurt me? You seek out a peaceful resolution?\" *sigh*... Roleplay mode disengaged. Allow me to communicate my honest feelings... I love you for being so loving, Commander.",
	main = "I've prepared a new mask based on this setting. Behold this expression, a mixture of coldness and contempt... This is the fruit of my efforts.|Roleplay mode engaged. \"Don't press your luck! The very thought that you can defeat me... Wait! Wh-what was that technique?! N-no, stooop!\"|Correct. You must defeat me to proceed in this scenario. ...Hm? Why are you shaking your head? You don't want to hurt me?|Left, right, left, right, B, A, B, A... I heard this is a secret way to win. Commander, would you like to try it?",
	touch = "\"It's too late to apologise now!\" Mm... It lacks energy, doesn't it?",
	voice_key_2 = -1,
	mission_complete = "\"You made money off of quests? Good. Use it to buy donuts and pay tribute to me!\"",
	battle = "",
	id = 203131,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "\"The insolence! A mere adventurer, laying hands on me?!\" I see... This is how you want me to treat you?",
	feeling2 = "",
	login = "\"You didn't just set up a save point here, did you?\" Was that good, Commander?",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[203140] = {
	hp_warning = "Urgh... I can still... carry out my orders!",
	feeling3 = "The other Royal Maids seem to know exactly what to do, without ever receiving orders... But I'll be okay. As long as you're here to instruct me, I can work, too.",
	mail = "I have your mail, Commander. If you'd like to read it, then please give the order.",
	expedition = "Commander, the commission team has returned... Huh? I-I need to tally up the goods? I will try... *sniffle*...",
	win_mvp = "Everybody is cheering... Did you give the order to rejoice? May I do the same?",
	home = "Your efforts are appreciated. What shall I do next? Or... should I simply stand by?",
	unlock = "It is a pleasure to make your acquaintance, Commander. Heavy cruiser Surrey, reporting for duty... What should I do, now that I've reported in? Shall I stand by for further orders? Follow you? Continue my self-introduction? I await your command.",
	touch2 = "Commander... Umm, is that your only request...?",
	mission = "Commander, there are still incomplete missions. Please proceed according to the mission list.",
	vote = "",
	drop_descrip = "Surrey-class heavy cruiser – Surrey.",
	feeling4 = "The head maid asked me why I'm always standing in view of you, so I replied that I wanted to be close at hand whenever you needed me... I don't understand, though. All I want is to watch you, so why did that make her smile so much?",
	lose = "I haven't received retreat orders yet, so I will fight until I am sunk... Hmm? I can retreat now? Understood!",
	feeling1 = "*glance*... Commander? *glance*... Commander? ...*glance*... Commander?",
	skill = "Orders confirmed. Firing!",
	upgrade = "It feels like... I can do more now. Maybe I won't have to count on my fingers anymore?",
	propose = "Could this be the most special order you've given me? To stay by your side forever, to always obey, and to never leave you? If it is... then I promise to carry out the rest of your requests forever, Commander.",
	feeling5 = "In my opinion, time spent waiting for orders is not time wasted. As long as I can see you and know that you're near... I'm not waiting – I'm spending time with you.",
	main = "Commander, you asked if I'd like to have a drink with you... What exactly does that mean? Does that mean we share one drink? Or will we have our own drinks? This is complicated...|I won't know which order to prioritize if you give me too many at once. Can you try giving me one at a time?|After the last mission, our remaining supplies total to... this many! Huh? Was my intuition wrong? Oh, no... I'm getting dizzy.",
	touch = "You're coming closer... May I remain on standby?",
	voice_key_2 = -1,
	mission_complete = "Mission accomplished. Commander, please review the results and provide your next orders.",
	battle = "Mission confirmed. Eliminating the enemy now.",
	id = 203140,
	gift_dislike = "",
	gift_prefer = "Commander, is this... for me? Is it right for me to accept it? Okay... I'll cherish this.",
	profile = "I am Surrey. *stare*... Commander, will you not ask me any questions? Perhaps my name, or what I can do? Without specific instruction, I'm not sure how to introduce myself...",
	voice_key = 20314,
	headtouch = "Is this affection a reward? I will remember that.",
	feeling2 = "It's an honour to assist you, Commander. Please make use of me as you please.",
	login = "I see you've returned safely. I await your orders. Whatever you need, it will be done diligently.",
	detail = "Commander, you requested that I organize your documents and desk while you were gone... but tidying the desk makes a mess of the papers, and tidying the papers makes a mess of the desk. Erm... What should I do?",
	couple_encourage = {
		{
			{
				20212
			},
			1,
			" Head Maid, I'm here to assist!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[203141] = {
