	win_mvp = "",
	home = "The number of buttons on my top is... one, two, three... Oh, I miscounted. Again... One, two... Commander, welcome back! May I stop standing by now?",
	unlock = "Change out of my sweat-soaked clothes, and get my temperature checked... Huh? Which of these orders should I prioritize? Should I just undress now, or...?",
	touch2 = "Even in this state... I'm happy to fulfill all of your needs, Commander... *blush*",
	mission = "",
	vote = "",
	drop_descrip = "Change out of my sweat-soaked clothes, and get my temperature checked... Huh? Which of these orders should I prioritize? Should I just undress now, or...?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Commander, if this ever happens to me again... will you be there to help me? Helping me sort out what needs doing, reminding me of my priorities... As long as you're around, all of my worries just fade away.",
	main = "I'm your maid, but you're the one looking after me... What a difficult situation this is. But to be frank... this is very relaxing for me.|I've been doing my best to stay still, but it's so hot... Commander, if you don't give me an order soon, I won't be able to hold back... Ngh...|Commander, if you'll help me, I don't mind direct contact... Please guide me personally on what I must do.",
	touch = "Commander, I feel like... I'm heating up even more. Is my temperature still rising?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 203141,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "My head is... warm, isn't it? Ah...",
	feeling2 = "",
	login = "I have been waiting patiently for you without taking any action. Now, should I... check my temperature? Or should I change my clothes with your help first?",
	detail = "",
	couple_encourage = {}
