_G.pg.base.ship_skin_words[204010] = {
	hp_warning = "Speed is the best defense!",
	feeling3 = "Commander, you always ask me to accompany you for walks. Is something bothering you?",
	mail = "If you have time, please look over the mail.",
	expedition = "The girls who went out on a commission have arrived. Please, let me go in their stead next time, Commander. I... don't like being on the receiving end of things.",
	win_mvp = "Enemy fleet eliminated. Mission complete.",
	home = "I will review this operation's performance and report back to you as soon as I can.",
	unlock = "Renown, Battlecruiser of the Royal Fleet of the Royal Navy, at your service. My guns shall aim where your sword points, Commander.",
	touch2 = "...!! Commander! I do not intend to resist... but still...",
	mission = "Commander, we still have missions to complete!",
	vote = "",
	drop_descrip = "Renown-class battlecruiser - Renown",
	feeling4 = "... Why would you arrange candles in a heart on the beach? And then... why did you cry when I said \"aren't you afraid of the fire being extinguished by the wind\"?",
	lose = "...I am sorry, Commander... I failed to live up to your expectations.",
	feeling1 = "Commander, you cannot continue like this.",
	skill = "Renown! Full speed ahead!",
	upgrade = "Your will is the source of my power.",
	propose = "Wait, Commander... Let... let me find some candles...and make a heart... and some covers to prevent them from being blown out.... t-t-then I'll... Please... don't look at me! I must be making a very strange face right now!",
	feeling5 = "Don't worry, I'm not that dense. Next time I will bring a cap and cover up the candles for you. Then you can tell me what is truly on your mind.",
	main = "No instructions, Commander? So we're using the, 'wait and see' strategy...?|My propeller? Hood bumped into me one day, and before I reacted I received this in apology.|What? You think Renown is cute...? Well, on her behalf, I give you my tha... Wait, what?!",
	touch = "... It's a bit strange... Only you have ever done this to me, Commander...",
	voice_key_2 = 204013,
	mission_complete = "Please, claim the mission rewards!",
	battle = "Enemy fleet in sight! All ships, fire at will!",
	id = 204010,
	gift_dislike = "",
	gift_prefer = "Thanks. I am quite fond of this.",
	profile = "I am Renown, Battlecruiser of the Royal Fleet of the Royal Navy. I have experienced issues in both great wars, and have countless accomplishments for which I am proud. No matter what orders you give me, Commander, it is my duty to carry them out with all of my strength!",
	voice_key = 20401,
	headtouch = "",
	feeling2 = "Love letter? How does one love something like a letter? People love all sorts of things, but that one I cannot understand.",
	login = "Commander, please give me your orders.",
	detail = "All systems functioning properly. Do not worry, Commander.",
	couple_encourage = {
		{
			{
				20403
			},
			1,
