	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I know I'm gonna do this dance at the party, but I really wanted YOU to see it! I'm not as elegant or attractive as the other girls, so I wanted to show you my best side in the best way I could...",
	main = "How do you like this stance? It's like I'm in a Wuxia movie, right?|My sister says my moves are sloppy, but this is just my style! You like me better this way anyway, don't you?|Commander~ Do you think I should add some cool jumps and flying maneuvers to the dance? I think it'd be fun! ...Huh? It's too much?",
	touch = "You wanna see my sword? Careful you don't poke an eye out!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 204021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Heheh~ Can I take that as praise?",
	feeling2 = "",
	login = "Hiya! Perfect timing there, Commander! Let me show you this cool thing I learned!",
	detail = "How do you like this outfit? I had it made just for my sword dancing performance!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[204030] = {
	hp_warning = "Even I am slightly angered.",
	feeling3 = "Though I speak of being refined at all times, you need not force yourself, Commander. Your normal self is the most charming, after all.",
	mail = "It's unopened... Commander... It would be ungentlemanly to ignore the messages of others.",
	expedition = "Having completed numerous commissions is a sign of glory. May I suggest rewarding those girls?",
	win_mvp = "The warm sun and the cool breeze: a brilliant victory.",
	home = "Commander, may I offer you some warm tea? We can drink it as we review your battle.",
	unlock = "Are you the commander? Greetings and well met. I am the glory of the Royal Navy: Hood. Wherever I go, victory follows.",
	touch2 = "Commander, you should understand the consequences of disrespecting a lady... Are you prepared?",
	mission = "Commander, we have been entrusted with new missions. Please look through them.",
	vote = "",
	drop_descrip = "Admiral-class battlecruiser - Hood, Hull Number 51!",
	feeling4 = "Hm? I'm too close? A lady must be elegant, but they must also seize the initiative towards the targets of their own affection.",
	lose = "Victory and defeat are commonplace among those who fight, and it is we that have all the time in the world!",
	feeling1 = "*Sigh* Seems like you must learn it the hard way.",
	skill = "Elegance is not just for show.",
	upgrade = "Your efforts will definitely be rewarded.",
	propose = "Aha, look how nervous you are. You can't convey your feelings to a lady when you're this nervous. However, your feelings have definitely reached my heart... I would happily oblige.",
	feeling5 = "\"Shall I compare thee to a summer's day? Thou art more lovely and more temperate... So long as men can breathe, or eyes can see, so long lives this, and this gives life to thee.\" ... A beautiful verse. Commander, could you read it out loud to me?",
	main = "An outstanding commander must have an in-depth knowledge of tea.|This word is... ah, so I read it wrong. Sorry, my eyes fail me.|Listen more, speak less. You should listen to the opinions of others, but also retain your own judgment.",
	touch = "Appropriate contact is indeed essential. Shall we dance?",
	voice_key_2 = 204033,
	mission_complete = "With glory comes rewards. Please do not forget about the latter.",
	battle = "May glory be with us today.",
	id = 204030,
	gift_dislike = "",
	gift_prefer = "To be able to pick out a present befitting a Royal Lady is the hallmark of an exceptional commander. Thank you.",
	profile = "Indeed, the glory of the Royal Navy now stands before you. Being able to maintain an air of elegance at all times is the hallmark of royalty. The Denmark straits? Soldiers know of victory and defeat alike. It was no more than a temporary setback.",
	voice_key = 20403,
	headtouch = "Commander, might that be a special reward meant only for refined ladies? I graciously accept.",
	feeling2 = "Commander, it's such a great afternoon. Shall we have a chat? ... Hm, alright... I'll talk about the times when I was with Renown.",
	login = "Welcome back, Commander. Care for a cup of tea?",
	detail = "Feel free to admire the glory of the Royal Navy to your heart's content.",
	couple_encourage = {
		{
			{
				20401
			},
			1,
			"Miss Renown, please mind where you're going.",
			0
		},
		{
			{
				20402
			},
			1,
			"Miss Repulse, mind your manners.",
			0
		},
		{
			{
				20501
			},
			1,
			"I shall do anything you ask of me, Your Majesty.",
			0
		},
		{
			{
				2
			},
			5,
			"The glory of the royal family, advancing.",
			3
		}
	}
}


_G.pg.base.ship_skin_words[204031] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "",
	unlock = "What a feast for sore eyes. I feel great~! Vacations really should be at the beach! Let's show Sara your beach ball, Cygnet!",
	touch2 = "This is exactly why Wales will always be a Prince and never a King.",
	mission = "",
	vote = "",
	drop_descrip = "What a feast for sore eyes. I feel great~! Vacations really should be at the beach! Let's show Sara your beach ball, Cygnet!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "So me and the other girls are going to play beach volleyball The player on my team that scores the least will be subjected to a small punishment game.| I can see the whole harbor from the mountain top, this is the best place to watch fireworks.|To be elegant at all times is the mannerism befitting of a lady.",
	touch = "The beach volleyball game is about to start. Let's find a good place to watch, Commander!",
	voice_key_2 = 0,
	mission_complete = "",
	battle = "",
	id = 204031,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Good day, Commander. Let not the heat shaketh thy inner peace. Keep calm and carry on!",
	detail = "My brilliance is like that of the sun? I'm in a good mood so I'll accept this praise of yours.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[204032] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "A gentle breeze, a soothing fragrance– An elegant victory indeed.",
	home = "Commander, would you like to try some roasted twig tea? Do be at ease while bathing in its elegant aroma.",
	unlock = "Thank you for inviting me on this wonderful trip. Now that I have donned this beautiful outfit, shall we partake of a Sakura Empire tea party– leisurely and elegantly?",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "Thank you for inviting me on this wonderful trip. Now that I have donned this beautiful outfit, shall we partake of a Sakura Empire tea party– leisurely and elegantly?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "\"As the heat retreats, harvest melons and eggplants, welcoming Autumn.\" ...My, what an evocative and refreshing poem. Commander, let's set aside all our worries and enjoy this trip, just the two of us.",
	main = "The Higashi Chaya District? ...Oh, isn't that a town famous for its teahouses? Hehe, a perfect place for enjoying the Sakura Empire's tastes and smells. I definitely hope to go there.|Add hot water to the matcha and stir gently with this bamboo whisk– The Sakura Empire has a truly profound way of appreciating tea...|Commander, why don't you take some photos as reference for Comet and the others? We might as well get as much out of this trip as possible - not just souvenirs, but also sources of inspiration.",
	touch = "Commander, how's my technique?",
	voice_key_2 = 0,
	mission_complete = "",
	battle = "",
	id = 204032,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "You can have some of the maid team's black tea if you'd like, but why not try some of the Sakura Empire's green tea today?",
	detail = "Rose patterns as well as our Royal Navy's motifs... How splendid this is! I must express my gratitude to those who dyed this kimono.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[204033] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Tea is of paramount importance to a leisurely outing. Naturally, I will leave that to you, Commander.",
	unlock = "Beauty is not always over the rainbow. Sometimes it is right in your backyard. Commander, how would you like to spend this quiet, lovely day right here with me?",
	touch2 = "Commander, when we get back, would you like another lecture on how to properly escort a lady?",
	mission = "",
	vote = "",
	drop_descrip = "Beauty is not always over the rainbow. Sometimes it is right in your backyard. Commander, how would you like to spend this quiet, lovely day right here with me?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Watch out for the stairs? Indeed, I'll do just that. Thank you for remembering that my eyesight can be troublesome.|If you don't have a destination in mind, why not simply enjoy the scenery all around us? For example... the roses in full bloom in this garden.|I can see that Bismarck is finally learning to shed the burdens placed upon her shoulders. Hehe, don't you think she should be more true to her feelings?",
	touch = "Commander, you'll properly fulfill your duties as my escort, yes?",
	voice_key_2 = 0,
	mission_complete = "",
	battle = "",
	id = 204033,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "The gentle sunlight, and a refreshing breeze – today is a fine day to venture outside.",
	detail = "Compared to the overly grandiose national parades, I greatly prefer the relaxing companionship of a single escort. Commander, will you be my escort?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[204034] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Whether you're on the lush plains or the open seas, the winds of victory are ever so pleasant.",
	home = "Thank you for your work, Commander. The weather is lovely, so I brought this lovely little horse from the stable to greet you.",
	unlock = "Whoa, there... There you are, Commander. You could have waited at the clubhouse... Why yes, the view is just beautiful, isn't it? Hahaha, thank you for bringing me here today.",
	touch2 = "I hope you'll use a gentle touch with the horse, as you do with me.",
	mission = "",
	vote = "",
	drop_descrip = "Whoa, there... There you are, Commander. You could have waited at the clubhouse... Why yes, the view is just beautiful, isn't it? Hahaha, thank you for bringing me here today.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Commander, if you're willing, you should try feeding horses. I promise it's adorable to see them eating right out of your hand.|Riding a horse through vast expanses of greenery is lovely, but I think I'd like to try riding on the coast sometime. Of course, I'll need the proper equipment.|Cygnet wants to try riding, too, so I'm going to pick out clothes for her later. Want to join me, Commander? Heehee.",
	touch = "Riding raging waves, running through the plains on a horse—Either way, it's a piece of cake for me. Hahaha!",
	voice_key_2 = 0,
	mission_complete = "",
	battle = "It's time I showed you the style of a royal lady.",
	id = 204034,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, how will you be going back? Would you like to ride together on my horse?",
	detail = "Horseback riding isn't really something to be praised. It's part of raising any royal lady... You say the others were impressed? My, and you, too?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[204035] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome back, Commander. I found myself gazing at this ring while you were gone. I must have been immersed in our shared memories.",
	unlock = "Commander, the invitation I received read: \"A Special Event for Lady Hood.\" Could that \"special event\" include your exclusive company and this brilliant surprise on my finger?",
	touch2 = "Goodness! As elegant a lady as I am, I am still defenceless beneath this finery. I hope you will escort me to the last, Commander. Hehehe.",
	mission = "",
	vote = "",
	drop_descrip = "Commander, the invitation I received read: \"A Special Event for Lady Hood.\" Could that \"special event\" include your exclusive company and this brilliant surprise on my finger?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I have devoted everything to my glorious duty. However, in this moment I would like to pour all of that emotion into the vow I hold with you. This ring is the greatest proof of our connection.",
	main = "I was lost in thought there. I couldn't help but touch the ring again unconsciously. It seems I wish to bask in this bliss for a while longer.|I value people with whom I can experience and share victory and glory alike. But this contentment, Commander, is something only between you and me. And that's more than enough.|The fragrance of today's tea seems a little different from usual. But it is certainly calming.",
	touch = "Could I ask you to put this ring on me, Commander?",
	voice_key_2 = 0,
	mission_complete = "",
	battle = "",
	id = 204035,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = -1,
	headtouch = "",
	feeling2 = "",
	login = "These garments are a part of my promise to you. The eternity we've spent side by side, and our vow that has weathered many a storm, are a most fitting match for the radiance of this ring.",
	detail = "I originally prepared these garments for a magnificent social occasion, but they are currently fulfilling a more suitable role. I am delighted that they are reserved for your eyes only, Commander.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[204038] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Commander, everytime I picture your face, my heart races and my spirit soars like a skylark at dawn.",
	unlock = "",
