	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Which black tea did you prepare for us, Commander? Please allow me to build up my anticipation for this tea party. | Commander, once the seven seas have returned to peace, let’s organize another “Imperial Cruise”.",
	touch = "Commander, let me teach you the proper etiquettes of being with a lady.",
	voice_key_2 = 0,
	mission_complete = "",
