_G.pg.base.ship_skin_words[204040] = {
	hp_warning = "Renown shall break your lines!",
	feeling3 = "Work is important, but taking breaks is also important! Coming from a Royal Knight, you're overworking yourself! After you finish this, please make sure to get some rest!",
	mail = "This one's for you, Commander. This one's also for you... and this one too...",
	expedition = "Commander! The commission fleet will return to port in ten minutes! Please... Wait, did I get the time wrong...?",
	win_mvp = "I've done it...! Wait, no! The books clearly teach that it is foolish to gloat over a single victory! Self control... self control...!",
	home = "You're not too bad, Commander... If Renown also works harder, will she be able to... be like you one day?",
	unlock = "The Renown-class battlecruiser Renown has come to join your ranks! My stature may be small, but my desire to succeed is great!",
	touch2 = "Commander! That's in violation of Royal etiquette!",
	mission = "Commander, please allow Renown to handle the missions! H-huh? Commander, you're doing them all yourself?!",
	vote = "",
	drop_descrip = "Renown-Class Battlecruiser - HMS Renown ",
	feeling4 = "Commander, why did the knights in that book betray their own king? Renown is nothing like those knights! I would never betray you even if it cost me my life!",
	lose = "My apologies, Commander...",
	feeling1 = "Commander, please get your act together! Renown shall not abandon you!",
	skill = "The enemy shall never see my back turned!",
	upgrade = "For the Commander's sake, I'm ready... to become stronger!",
	propose = "A promise ring? I know about this! Um, \"I pledge to defend the weak and act with valor...\" Oh, all I have to do is read this? Well then... \"through thick and thin, we shall share our pain and willingly give love eternal.\" ...Commander, does that sound right?",
	feeling5 = "So, Commander, is it fine for Renown to always stay here? Being close to you gives me strength, and above else, my love for you is absolute! ...Huh? Did I say something weird...?",
	main = "As long as Renown is here, no harm shall befall you, Commander! |The serious and dedicated Little Renown is cute? I see, I'll be sure to pass on the message to... wait, what? |It's not just you. Everyone here at port is truly amazing... I must redouble my efforts...!",
	touch = "Candy? I'll have you know, Commander... Renown has no use for such things!",
	voice_key_2 = 204043,
	mission_complete = "Heave-ho... C-Commander, the m-mission rewards are... wooooahhhh!!",
	battle = "Royal Navy, search and destroy!",
	id = 204040,
	gift_dislike = "",
	gift_prefer = "Thank you very much, Commander! I shall treasure this!",
	profile = "I am the battlecruiser Renown, and I was training in Govan before coming here! Being able to weigh anchor ahead of schedule is a testament to my strength... Indeed! I will do my utmost to live up to everyone's expectations!",
	voice_key = 20404,
	headtouch = "Myahh?! Wh-what are you doing?!",
	feeling2 = "I mustn't neglect my training or my studies... I'll do my utmost each day so that I may become a proper knight. Commander, do you want to follow this path as well?",
	login = "Commander, Renown is awaiting your orders! Please issue today's commands!",
	detail = "There are many things that I do not understand in the Codex of the Royal Knights! Commander, can you offer me any guidance?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[205010] = {
	hp_warning = "Why are you spacing out?! Hurry! Get them!",
	feeling3 = "I'm sitting here for just a moment because I like the mood! Don't start getting any strange ideas!",
	mail = "I have no interest in the contents of your mail... Mmh...",
	expedition = "The subjects tasked with a commission have returned. Go at once and see if they brought me a tribute!",
	win_mvp = "Piece of cake! There are no mistakes in my actions!",
	home = "A fine display, I shall be benevolent and permit you to rest.",
	unlock = "Are you the commander? You are still 100,000 years too early to command me! Well, I shall be generous and give you a chance... From this day on, you will be one of my faithful servants!",
	touch2 = "W-wait... You fool, what are you doing?! I-I'll sentence you to death!",
	mission = "Hurry and finish the mission! Do not skip your work!",
	vote = "",
	drop_descrip = "Queen Elizabeth-class battleship - Queen Elizabeth, Hull Number 00!",
	feeling4 = "H-hmph! You have been slightly exceeding in your duty, thus I will make an exception and promote you to captain of the Royal Guard! When I call for you, you will come hither immediately! Understood? Immediately! Swiftly! At maximum speed!",
	lose = "How despicable! To have brought shame to the great Elizabeth! You better remember this!",
	feeling1 = "You useless servant! I will have you relieved of your post!",
	skill = "Kneel before the Queen!",
	upgrade = "I have no need to get any stronger! But... well, if you're going through to effort of doing it, then...",
	propose = "Finally you have arrived before me. Foolish servant! Just how long did you intend to make me wait?! ...But I acknowledge your endeavors. Come here, I am giving you permission to take my hand! Yes! From now on I will always be with you!",
	feeling5 = "Hey, can't you just leave your work to your underlings? How can you be a proper consort if you aren't always by my side?! I-I would be so lonely...",
	main = "Being petite is a noble characteristic, understand?|You're saying I bumped into you? That's because you didn't make way for the Queen!|Do not touch my belly, it's rude!",
	touch = "Please do not touch our noble body so casually",
	voice_key_2 = -1,
	mission_complete = "Kneel before me and accept your mission rewards!",
	battle = "Witness the might of a super-dreadnought!",
	id = 205010,
	gift_dislike = "",
	gift_prefer = "One must admit, your taste is quite satisfactory! Now be grateful for this praise! Ahem!",
	profile = "I am the super-dreadnought of the Royal Navy. Make sure to remember my name! My military achievements? I let my subjects take care of those kind of things. I simply need to watch them do their work!",
	voice_key = 20501,
	headtouch = "",
	feeling2 = "Work hard for the great Elizabeth!",
	login = "Despicable, to have me wait on you for so long!",
	detail = "Peasant! Who permitted you to peak?! I-I have not prepared myself yet...",
	couple_encourage = {
		{
			{
				20502
			},
			1,
			"Warspite! Hurry up and take care of these enemies!",
			0
		},
		{
			{
				5
			},
			3,
			"Now this is the fleet I've been wishing for!",
			2
		},
		{
			{
				2
			},
			5,
			"Warriors of the Royal Navy, fight for glory!",
			3
		},
		{
			{
				20510
			},
			1,
			"The Queen orders you to move! THAT... INCLUDES... YOU!",
			0
		},
		{
			{
				20703,
				20704,
				20705,
				20711
			},
			2,
			"These oversized sisters... What an eyesore! ＞＜",
			0
		}
	}
}


_G.pg.base.ship_skin_words[205011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "",
	unlock = "Hah haah! You're a lucky servant this evening! We shall allow you to accompany us to the party! ... B-but it's not like I chose you because I like you! I just... Yes! I just sort of chose randomly! Got it?!",
	touch2 = "Aie! Warspite!! Level your fifteen-inch guns at this insolent servant! Off with its heeaaaaaad!!",
	mission = "",
	vote = "",
	drop_descrip = "Hah haah! You're a lucky servant this evening! We shall allow you to accompany us to the party! ... B-but it's not like I chose you because I like you! I just... Yes! I just sort of chose randomly! Got it?!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "So as not to embarrass me at the party, you need to practice your dancing! Y-you could practice with m-... You don't want to bother me?! B-b-but it really wouldn't be much trouble!|It is a servant's duty to clear the way for the Queen, are we clear?!|Bel! Is everything ready for the party? N-not that I'm excited about it or anything! I'm just supervising my maids!",
	touch = "Hm, hmph! ... Considering the lengths to which you went for this party, we shall overlook your boorishness for now. Be grateful for your queen's leniency! Lowly servant!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 205011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "",
	detail = "We shall allow you to bask in our splendor! ... Now out with your praise already! Lowly servant!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[205012] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Valiant, spread word of our victory far and wide!",
	home = "Fine work. As a reward, you may have this portrait of me. Keep it well!",
	unlock = "Now this is a stage worthy of our majesty! You are not to leave our sight, servant! Let your passions burn for me!",
	touch2 = "Watch your hands, servant! Or it's the oubliette for you!",
	mission = "An offer for me? W- well, it is a Queen's duty to hear out the commoners...",
	vote = "",
	drop_descrip = "Now this is a stage worthy of our majesty! You are not to leave our sight, servant! Let your passions burn for me!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "\"Grovel before me, servant!\" ...Hm? It feels a bit different from usual...?|Like so...? Is this cuter? Very good then, well done, Matchless. My servant will be blown away!|A maid idol...? What is it Bel and Gloucester have been teaching you?",
	touch = "Encore? Heh heh. I could give you a few more!",
	voice_key_2 = -1,
	mission_complete = "I've included a favour in your rewards. Show me your gratitude!",
	battle = "This is the Queen's stage!",
	id = 205012,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "How improper!",
	feeling2 = "",
	login = "Hah hah! Spread the word, servant! Let all be dazzled by our splendour!",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[205013] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Time to check my locker~♪ ...Hm, a note from Newcastle? Um... \"Already cleaned for you.\" ...Oh, I see.",
	expedition = "",
	win_mvp = "Ehehe, why it's only natural, of course! Nothing like that self-proclaimed \"spiritual leader!\"",
	home = "Mathematics, check. History, check... Physical Education? Pass! A noble like me playing basketball with commoners? Unthinkable!",
	unlock = "Hehe, behold the new outfit that I had Akashi make for me! Impressive, no? Prostrate yourself before the elegant charm of my school uniform, servant~♪",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "Hehe, behold the new outfit that I had Akashi make for me! Impressive, no? Prostrate yourself before the elegant charm of my school uniform, servant~♪",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Bel, where's my cake...? Servant, take Neptune with you and make yourself useful!|Warspite, how fares the tea party plans with Nagato and the others? Have George and the knights deliver the invites to them!|\"Field trip?\" Let us make our way to Sardegna! Have Veneto regale us with the most exquisite banquet!",
