_G.pg.base.ship_skin_words[205016] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "What's that, little ones? The commission team is back? Good! I shall go and greet them!",
	win_mvp = "Heheh!♪ George, be sure to record my accomplishments! And those of my servant, too!",
	home = "My, you've really given it your all! Heheh, I hereby permit you to rest! Take it easy by your queen's side, servant!",
	unlock = "Servant, what do you think you're doing?! Instead of wasting your life working, go have some fun in the sea for once! We went out of our way to come to the beach, so do not disappoint me!",
	touch2 = "Th-that was an accident, right?",
	mission = "You still have missions? Mm, I suppose I am a little concerned about Valiant...",
	vote = "",
	drop_descrip = "Servant, what do you think you're doing?! Instead of wasting your life working, go have some fun in the sea for once! We went out of our way to come to the beach, so do not disappoint me!",
	feeling4 = "",
	lose = "Grrr... Servant! We will devise a plan to get them back!",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "A beach party? Seattle, where is this coming from? ...Not that I mind, once my servant and Hiei arrive.|Richelieu, wait! Why are you bringing the Meowfficers?! And Jean Bart, don't just stand there and watch! Stop her!|You don't see the Royal Maids around? Well, of course not; I gave them the day off. My servant and the knights are here, and Neptune and Cheshire have always wanted to try maid work anyway! I see no cause for concern.",
	touch = "How kind and perceptive of you to offer to refill my tea for me! Make sure you bring sweets, too.",
	voice_key_2 = -1,
	mission_complete = "The rewards have arrived! Hood, go take a look with the destroyers.",
	battle = "Servant, we go together!",
	id = 205016,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Wh-what are you doing?! A reward, you say? Well, this is hardly...",
	feeling2 = "",
	login = "I left Valiant with all the busy work so I could take it easy today! Why don't you leave your work to someone else for once?",
	detail = "Hmph! A noble queen would never swim with the common folk! ...I-it's not because I can't swim! Fine. Let's race to that rock! I'll prove to you that I am a capable swimmer!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[205020] = {
	hp_warning = "So this is how harsh the battlefield can be.",
	feeling3 = "I'm not very elegant? I'm sorry that I'm not like Hood or the others... No... I'm not talking about my body...",
	mail = "You've got mail, Commander!",
	expedition = "Commissions? I suppose I do miss running around on errands... Let's go. We need to welcome back those hard workers!",
	win_mvp = "Don't be confined by the so-called \"limits\". It is indeed possible to be unsinkable!",
	home = "Whew, not a bad fight. Let's rest for a while.",
	unlock = "Greetings, I'm Warspite. I hold the record for the longest ranged hit on a moving target. Surprised? I'm smaller than you thought? Looks like we need to have a long talk...",
	touch2 = "Just so you understand, I'm definitely not that sort of, erm...",
	mission = "Accept your new mission and then get ready to head out, Commander!",
	vote = "",
	drop_descrip = "Queen Elizabeth-class battleship - Warspite, Hull Number 03!",
	feeling4 = "How do I put this... I'm considered to be one of the older girls, yet my body is like this... It might be unbecoming of one my age to compete with the younger girls, but I wanted to at least be attractive to you… What is a lady meant to do…",
	lose = "My damage control isn't functioning?! I've lost control of my steering wheel as well! Why now, at such a critical moment?!",
	feeling1 = "Would you please not act like we're close...",
	skill = "Belli dura despicio!",
	upgrade = "Battlefield, I'm coming for you.",
	propose = "Finally the day has come! It looks like my efforts were not in vain... Let's go, Commander, I'm prepared for this. Officers, draw swords!",
	feeling5 = "Well, enough of that. I'm Warspite, the one who spites war. Hmph! However, whosoever tries to take the Commander away from me will first have to face my cannons!",
	main = "Your orders are absolute, Commander. They shall be my highest priority.|This grand old lady can run faster without a skirt. Want to race with me?|If you make fun of me one more time, you'll be eating my 15 inch shells!",
	touch = "Body contact...? I don't hate it...",
	voice_key_2 = -1,
	mission_complete = "Missions give out rewards once you complete them. Don't forget that!",
	battle = "I would never let the commander's enemies escape!",
	id = 205020,
	gift_dislike = "",
	gift_prefer = "I didn't expect you to know what I like... thank you.",
	profile = "Elizabeth-class fast battleship, Warspite, reporting in. I hold the record for the longest ranged hit on a moving target. I've come close to being defeated quite a few times, but I managed to cheat death every time. This must be my fate.",
	voice_key = 20502,
	headtouch = "",
	feeling2 = "Commander, want to hear about the history of the Royal Navy? Maybe I should tell you something about the generals who used to accompany me.",
	login = "As long as I'm here, we can deal with any enemy, no matter how far they are.",
	detail = "Don't be blinded by statistics. Victory depends on far more!",
	couple_encourage = {
		{
			{
				10105,
				10108
			},
			1,
			"Do you want to race this old lady?"
		},
		{
			{
				10706
			},
			1,
			"Unmatched by any? *Sigh*...",
			0
		},
		{
			{
				20403
			},
			1,
			"Elegance does not belong on the battlefield.",
			0
		},
		{
			{
				20501
			},
			1,
			"Your Majesty, please look forward to my performance in battle.",
			0
		},
		{
			{
				20503,
				20504
			},
			2,
			"Youngsters, follow me.",
			0
		},
		{
			{
				20510
			},
			1,
			"Don't overdo it, alright?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[205021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Good. Since you are here, I can proceed to my next battleground - the important mission of delivering these gifts!",
	unlock = "This year, I am in charge of delivering presents to the children of the Royal Navy. Let's get going once I finish decorating this Christmas tree!",
	touch2 = "",
	mission = "Commander, while you're out delegating missions, mind helping me deliver this present to one of the kids along the way?",
	vote = "",
	drop_descrip = "This year, I am in charge of delivering presents to the children of the Royal Navy. Let's get going once I finish decorating this Christmas tree!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Apologies, Commander, it seems like our Christmas together was a bit unromantic. You... enjoyed it just fine? Heh, you're always like this... Well, at least, let us enjoy the rest of the night together while the bells of the Holy Night toll.",
	main = "Commander, do you want a present as well? If you really want one that badly, it's not like I can't give you one... |Hmm... what present should I pick out for Her Majesty? It can't be too expensive or too cheap, and it can't be too exotic or too ordinary. What exactly can I get her? |If I'm delivering Christmas presents, it's only natural to go through the chimney... Eh? Wouldn't that make me seem suspicious?",
	touch = "Commander, come help me decorate this Christmas tree - I'm not tall enough to reach... W-wait, who gave you permission to pick me up?!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 205021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Even warriors need to rest. Since it's a holiday, you shouldn't be too uptight either.",
	detail = "The wreath that goes on Her Majesty's door... Hmm, Belfast told me that the best way to make it is with seashells! Commander, let's head out to sea to collect some!",
	couple_encourage = {}
}


