_G.pg.base.ship_skin_words[205023] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "This outfit is battle-ready, too. Don't underestimate me.",
	home = "Well fought. You can't go see everyone with the air of combat still on you – blow off some steam on this watermelon, and that should fix you.",
	unlock = "Humph! Good, a perfectly halved watermelon. The Sakuran watermelon-splitting technique is surprisingly easy to master... Well met, Commander. Mind delivering these melons to the others for me?",
	touch2 = "Hm? What do you think you're doing?",
	mission = "",
	vote = "",
	drop_descrip = "Humph! Good, a perfectly halved watermelon. The Sakuran watermelon-splitting technique is surprisingly easy to master... Well met, Commander. Mind delivering these melons to the others for me?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "To be honest, I'd rather enjoy the festival with you than keep on splitting watermelons, but... this is fine, too. You're with me, and I'm with you. We're doing good work for everyone's sake. It suits our respective roles, doesn't it? Hehehe.",
	main = "Do Sakurans usually split watermelons while blindfolded? Hmm, I don't mind starting over, but I might miss the first few times... You think I should keep going as I am?|When you deliver these, make sure to give Her Majesty the one with the least seeds. Oh, and try to take them out, if you can...|How about we compete to see who can split them more evenly? Heheh, I've always wanted to see your swordsmanship.",
	touch = "Humph! Phew... Can you line up the next one for me?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 205023,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I'll split one for you, too. Haaah! ...Hm? You think I look unnecessarily murderous?",
	detail = "What happened to the bamboo and straw posts here? I was just taking a few practice swings. A wooden sword handles very differently from my usual weapons, after all. Heheh.",
	couple_encourage = {}
}


