_G.pg.base.ship_skin_words[205030] = {
	hp_warning = "Hmph, this is nothing!",
	feeling3 = "Just with results like these you want me to... You did all this yourself? Don't laugh! I suppose I can make an exception and admit that you did well this time. Hmph!",
	mail = "I picked up your mail while I was out on my walk. Read it and be thankful.",
	expedition = "Com-man-der! Did you forget about the returning commissions again?",
	win_mvp = "Hmph. Enemies like these aren't even worth the time.",
	home = "Have you witnessed the might of the Royal Navy?",
	unlock = "You're the commander? You don't look very capable to me, though. I'm Nelson. I'll be following your orders, for now.",
	touch2 = "Off to the bottom of Trafalgar with you, Com-man-der!",
	mission = "Why are you daydreaming if there are still missions to complete?",
	vote = "",
	drop_descrip = "Nelson-class battleship – Nelson, Hull Number 28!",
	feeling4 = "What are you looking at? I do approve of people who take of their work seriously. Besides, in the beginning I just thought you were unreliable, I never said you weren't serious!",
	lose = "To humiliate me like this... I'll get you back!",
	feeling1 = "I... don't even know what to tell you anymore... *Sigh*...",
	skill = "You're making a big mistake if you think I'm going to underestimate our enemies!",
	upgrade = "I suppose I should show a little appreciation for you; nice work.",
	propose = "Stand straight and puff your chest. You are the one I have chosen to spend the rest of my life with. This is something you should be proud of! ... Of course, to be chosen by you, is my honor... I'm not arrogant anymore? ... W-why, you... Do you want me to beat you up that badly?!",
	feeling5 = "Go out on a date? Well... It's not as if I won't, as long as you keep on working hard then...",
	main = "Experience from what's known as \"failure\"? Only a loser would say something like that!|I'm not just talking about you, but those who wave around empty words of \"friendship\" and \"efforts\" do not belong here.|One should only do work one is capable of. You still don't have what it takes to be entrusted with important tasks... Keep honing your skills.",
	touch = "Are you trying to get a taste of my cannons?!",
	voice_key_2 = -1,
	mission_complete = "Are you trying to make me get the rewards for you? I'll give you 10 seconds to do it yourself! 1, 2...",
	battle = "I expect everyone to do their duty.",
	id = 205030,
	gift_dislike = "",
	gift_prefer = "Hmph! I'll admit, your tastes aren't half bad. I'll accept this.",
	profile = "If you don't know who I am, go back to the naval academy and start over. I have no need of a commander who doesn't know me. ... You're calling me slow?! Huh?! That's brave of you to say... Stand still, I'll launch some knowledge into your head with my cannons!",
	voice_key = 20503,
	headtouch = "",
	feeling2 = "They let the likes of you be a commander? What a joke. Listen up! To be a commander, you must first... (One hour later)... Got it? Then work harder.",
	login = "Hmph. Are you done lazing around? I sorted out your documents, so I'm hoping you'll get some things done.",
	detail = "What are you staring at?! Keep it up and I'll gouge your eyes out!",
	couple_encourage = {
		{
			{
				20401
			},
			1,
			"Renown, try not to ruin my reputation!",
			0
		},
		{
			{
				20501
			},
			1,
			"Your Majesty, please let me take care of this for you.",
			0
		},
		{
			{
				1
			},
			5,
			"Kaede's Legion, unleash your full firepower!",
			4
		}
	}
}


_G.pg.base.ship_skin_words[205031] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "W-what are you gawking at?! What's so weird about my costume?!",
	unlock = "This costume... *Sigh*, whatever. It's Halloween, so some kind of entertainment is to be expected. But listen here: I'm not dressing up because I WANT to participate, okay?!",
	touch2 = "Do you wanna end up like this pumpkin?!",
	mission = "",
