	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Stop taking pictures, Rodney! I don't want people to see me like this...!|I guess it's okay to have fun with everyone like this sometimes... What? Did I say something funny?|What are you standing around for? It's a holiday; don't you have better things to do?",
	touch = "If you try anything weird at all... then you'll be in a world of pain!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 205031,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
