_G.pg.base.ship_skin_words[205032] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "A commission should be completed by now? Y-yeah, I know! I don't need you to remind me!",
	win_mvp = "",
	home = "You just witnessed the might of the Royal Navy! ...Ack! Y-you did NOT just see me trip! Got it?",
	unlock = "Hey, are you even enjoying yourself? At least pretend to have fun when I went out of my way to invite you, or else I'm going to lose sleep over this! ...Look behind me? What are you– Oh...!",
	touch2 = "",
	mission = "That's quite a few missions. Shouldn't you entrust some of these to other people?",
	vote = "",
	drop_descrip = "Hey, are you even enjoying yourself? At least pretend to have fun when I went out of my way to invite you, or else I'm going to lose sleep over this! ...Look behind me? What are you– Oh...!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "You'll have to shape up if you want to go out with me. Firstly, you... Look, I've told you a dozen times by now! This is not a date, you're just giving me a guided tour around the festival grounds!",
	main = "Look, those girls are dancing. Heehee, they seem to be having fun. That's the \"Awa Dance,\" if I remember right.|I will compliment the Sakura Empire on its impressive craftsmanship. Just look at their blue dyes and this tailor-made yukata.|These fireworks are gorgeous... You are looking at them, right? I don't want to stand here and watch them all alone... N-no, I don't mean that the way you think!",
	touch = "(Mgh... This sash feels far too tight, even compared to my regular uniform... Never thought a yukata would compress my breasts...)",
	voice_key_2 = -1,
	mission_complete = "I tasked the manjuus with collecting those rewards because I don't want you to leave... N-no, I didn't mean it like that!",
	battle = "",
	id = 205032,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "...Huh?!",
	feeling2 = "",
	login = "Make this day count, you hear? Y-you should know how to celebrate a holiday. You're not THAT stupid...",
	detail = "Rodney's with Colorado's group – they went to the shooting gallery. We can check that out, if you want... M-me, get lost among the crowd? Like that would ever happen! Especially when, you know, we're holding hands...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[205039] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "We can always rely on allies who see a job done right.",
