	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Become intoxicated with me. Then, giveth me thy purity, thy, devotion, and thy love. In return... I shall pledge thee an eternity of comfort within my bosom.",
	main = "Thou need not be nervous. This attire is but a temporary one... Perhaps thou believed to have escaped from my usual self? Ahaha... |Even though a night eternal may be out of the question, dost thou not wish... to sink into the embrace of night with me? |Following thy ideals are akin to swimming endlessly against the current... However, the way thou refuseth to bow thy head before fate gives me ample reason to remain by thee. Hehe...",
	touch = "Dost thou intend to spend the night alone, or perhaps... wouldst thou like to partake of a drink with me?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 205072,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Dost thou wish to try this blood... coloured fruity beverage?",
	detail = "Ahaha... I can hear the beating of thy heart. Yes, throb, throb... Ahh, what an enrapturing sound...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[205073] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
