	home = "",
	unlock = "My beautiful Adonis, why dost thou refuseth to take refuge in the trove of everlasting love... Perhaps my outfit can finally pierce thy heart? Hehe~",
	touch2 = "The snake devours the fruit — thy desires, thy true nature... I have grasped it all. Hehehe~",
	mission = "",
	vote = "",
	drop_descrip = "My beautiful Adonis, why dost thou refuseth to take refuge in the trove of everlasting love... Perhaps my outfit can finally pierce thy heart? Hehe~",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Wales, thou shalt not take my Adonis from me... Hehehe, but out of compassion, I shall allow you to have a third of our precious time together.|Yes, thy gaze... So full of resistance, yet also ready to give in at any time... How thine eyes can keep me entertained for all eternity... |Thou canst not win, be it in the heated environment of this sport, or in the sweetness of my absolute existence...",
	touch = "Beautiful, is it not? This outfit thou hath bestowed upon me is perfect for inspiring thy adoration... Is that difficult to understand?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 205073,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "",
	detail = "Love that can be robbed away holds no value. Only by becoming mine entirely will thou be worthy of my absolute attention.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[205074] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission team returns. Perhaps thou should fret thy own performance before that of others.",
	win_mvp = "Bear witness to the glorious fighting style of the Royal Knights.",
	home = "Palamedes of many talents, thou hast seized victory yet again. Phew... I am tired, as well. Let me just recross my legs... Heheh.",
	unlock = "Thou hast come. Welcome to my Athenaeum, young Odysseus. Today, thou shalt receive Duke of York's instruction – now, come forth, take a seat, and hearken to my teachings.",
	touch2 = "Dost thou expect something immoral? No matter thy position, thy lust knows no bounds♥",
	mission = "Forget neither thy missions nor the homework I've assigned thee.",
	vote = "拉票描述",
	drop_descrip = "Thou hast come. Welcome to my Athenaeum, young Odysseus. Today, thou shalt receive Duke of York's instruction – now, come forth, take a seat, and hearken to my teachings.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "The threads of fate binding thee are many, but thy path forward is singular. Haha, must I say any more? Now that thou art in my embrace, dost thou really have any other options?",
	main = "Incidentally, if thou were to change thy career, what wouldst thou choose? Of course, becoming my servant is a perfectly adequate path.|I'm impressed that thou listened so intently to my lesson. Dost thou perhaps... enjoy being taught? Guided?|By my authority as a teacher, I am able to fail thee no matter how accurate thy answers... Heehee, if thou wishest to avoid that... need I say the rest?",
	touch = "Defiling the morals of not just the students, but even those of a teacher as well? How wilt thou atone for this sin? Heheh...",
	voice_key_2 = -1,
	mission_complete = "Wealth, fame, and a kiss upon thy lips – what more reward couldst thou desire?",
	battle = "",
	id = 205074,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "If thou thirstest, then I shall make tea for thee. Staff office or not, a Royal Navy Athenaeum mustn't want for elegance.",
	detail = "If pressed to say, I think thy very existence makes the students' hearts flutter and stimulates their desire. Thy eyes, words, bearing... Even if thou dost not realize it, haha.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[205090] = {
	hp_warning = "I can't... falter now!",
	feeling3 = "Are you tired, Commander? Under the weather, perhaps? Heh, well, a nice cookie can fix that. Just eat one of these and you'll be right back to normal.",
	mail = "We've received what looks to be mail addressed to you.",
	expedition = "Do you need someone to escort the commission team home? I'm quite the experienced escort, I'll have you know.",
	win_mvp = "Heheh, I'm in top shape today!",
	home = "Nicely done out there. If you've got the energy to spare, perhaps you could write an after-battle report?",
	unlock = "It's a pleasure meeting you, Commander. I'm Howe of the King George V-class. I hope we can build a healthy relationship.",
	touch2 = "Umm... What are you doing?",
	mission = "Oh, missions? Are there any I can help with?",
	vote = "",
	drop_descrip = "King George V-class battleship – Howe (HMS Howe.)",
	feeling4 = "Come visit the dorm next time we're having cookies, Commander. We'd all love to have you, and I especially want to spend some quality time with you.",
	lose = "Next time... victory will be ours.",
	feeling1 = "A kind deed to others is a kind deed to yourself – or so I was naive enough to believe...",
	skill = "My aim shall not waver!",
	upgrade = "Phew... I'll return your gesture with valour on the battlefield, Commander.",
	propose = "Thank you for your sincerity, Commander. I will gladly be yours. I won't ask of you to share all your joys and sorrows with me, as I'm more than happy with just being by your side. Ah, that didn't sound like what I would say, did it? Well, hehehe~",
	feeling5 = "Bah, being indirect is just not like me. I adore you, Commander. Both as the leader of the fleet, and as my beloved special someone. I wish to know... do you adore me as well?",
	main = "Wales and York are lovely ladies. At times, however, I struggle to keep up with their thought processes.|George has always been good to me. She often treats me to a cookie or two... But I wish she'd stop treating me like I'm still a child.|If you have a hard time making friends with an eccentric person, my advice is this: bake some cookies, and offer to share with them.",
	touch = "Do save the massage for later. I'm not tired yet.",
	voice_key_2 = -1,
	mission_complete = "A mission's done. I can take care of claiming the rewards, no problem.",
	battle = "Heheh, there'll be no mercy for you!",
	id = 205090,
	gift_dislike = "",
	gift_prefer = "A present for me? Heehee, thank you.",
	profile = "Prior to my being sent to the Pacific, I always worked side by side with George. But aside from the one time we escorted our Sardegnian friends, I suppose I don't have too many notable feats to my name.",
	voice_key = 20509,
	headtouch = "Hm...?",
	feeling2 = "\"Shape the world into God's vision\" – if there is a God, what is his ideal world? It can't be one of perpetual war, that's for sure.",
	login = "How nice to see you. Now, let's get to work on today's tasks.",
	detail = "To your friends, show no cowardice; to your foes, show no mercy – that is my creed. Hehehe~",
	couple_encourage = {
		{
			{
				60502
			},
			1,
			"Allow me to witness your true might.",
			0
		},
		{
			{
				20505,
				20506,
				20507
			},
			2,
			"Let us show the world what we're made of.",
			0
		},
		{
			{
				20701
			},
			1,
			"Cookies are great, don't you know? Do you really not want one?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[205091] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Well done on that sortie. Let's proceed with our plan, shall we?",
	unlock = "Sorry to keep you waiting, but now I'm ready to– Commander? What's the matter? It'll get dark soon if you keep standing around like that.",
	touch2 = "Hm? Is there something on my dress?",
	mission = "",
	vote = "",
	drop_descrip = "Sorry to keep you waiting, but now I'm ready to– Commander? What's the matter? It'll get dark soon if you keep standing around like that.",
	feeling4 = "",
	lose = "I hope misfortune befalls you.",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Wales taught me the dos and don'ts of dating. Though enlightening, her advice seemed purposed for winning an ordinary girl's hand... So perhaps it's better intended for you, Commander?|Peckish, are you? Then you can have this cookie George gave me.|This dress is quite comfortable, actually. It's no trouble for me to walk a little longer.",
