	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "\"Masteeer, please untie meeee\"... Hmm...",
	detail = "Oh, who will come to my rescue? George? Or perhaps... you, love?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[205093] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission team is back. Heehee, I suppose we have to wait with the champagne for a bit.",
	win_mvp = "That is what I call an elegant victory. Phew... This will hopefully put George at ease.",
	home = "Welcome back, love. Go on and take a minute to rest. Let me know if you'd like to order anything.",
	unlock = "Thanks for your patience, love. I've looked forward to this evening's party for a long, long time. Hopefully George, York, and company won't laugh at me after how much effort I've put into this ensemble... What do you think of it, Commander?",
	touch2 = "Please, mind your manners...",
	mission = "",
	vote = "",
	drop_descrip = "Thanks for your patience, love. I've looked forward to this evening's party for a long, long time. Hopefully George, York, and company won't laugh at me after how much effort I've put into this ensemble... What do you think of it, Commander?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Monarch has me a tad bit concerned... Ah, no, she fits in just fine, I just wonder if she likes the food on offer.|All these foreign dresses have me mesmerised. I'd love to try some on for myself someday.|I don't want to stand out TOO much – you're the star of the show tonight, after all.",
	touch = "I can't walk all that fast in this outfit, so be a sweetheart and escort me.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "A Royal Knight is not to be trifled with!",
	id = 205093,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I'm right here, Commander. Seeing as we still have time, why don't you try this new flavour of cookie I made? ...Now's not the time?",
	detail = "What, you think my dress is ludicrously posh? It should be, considering what an important day this is... What about it is so important, you ask? Hm... That is an excellent question.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[205100] = {
	hp_warning = "H-hey, hurry up and do something about this...!",
	feeling3 = "Y-you're better than I expected... F-fine, I won't go easy on you next time...!",
	mail = "Tsk... Why is all the mail for you...",
	expedition = "Heheh, it seems that the commission team has been doing well. Do send them my best regards in my stead.",
	win_mvp = "A heroic battle commanded elegantly by the Commander— now this is the kind of flawless victory that befits me.",
	home = "My attendant, how fares the combat situation? Do tell me in detail.",
	unlock = "To be Valiant is to be me. Remember this face, for it is the face of a fleet leader! ...Speaking of faces, who are you? The Commander? Very well! I shall treat you as my personal servant!",
	touch2 = "What's the meaning of this?! Grrr... As a charismatic, generous, and VERY patient person, I will forgive you just this once!",
	mission = "I'll leave this these trifling quests to you.",
	vote = "",
	drop_descrip = "Queen Elizabeth-class battleship – Valiant (HMS Valiant.)",
	feeling4 = "H-hold up! Chess is like a real-world exercise, so you have to consider all the various external factors! Th-that's right! That last match was a fake! A fluke! Doesn't count! Cancelled! Got it?!",
	lose = "Ugh... H-how is this possible...",
	feeling1 = "I had great expectations for you...",
	skill = "Everything dances within the palm of my hand!",
	upgrade = "Not bad, my attendant~ Do you want a reward?",
	propose = "Well done! You've gained my recognition as my trustiest spear in the arsenal! To reward you for your continued loyalty, I shall allow you to stay at my side and bask in my charisma! May this ring be a symbol of our bond~♪",
	feeling5 = "As my subordinate, you should be considerate of your superior... I mean, sh-shouldn't you let me win at least once? I've lost to you so many times that I barely even have the confidence to play chess anymore... A-anyway! Lose to me! Just once! It can even be on purpose! This is an order, got it?",
	main = "So thirsty... Ahem. My attendant, do tell the Maid Team to brew me some black tea. Hmm, on second thought... that'd take too long. You can do it for me, can't you?|Charisma is the most important facet of a leader! To be charismatic is to command dignity, to imbue your every word with gravitas! Ahem... did you get all that?|Snack time?! ...Ahem! A proper leader must know how to balance their work with their life. Please do not forget that.",
	touch = "Speak your mind, my attendant. You have my ear.",
	voice_key_2 = -1,
	mission_complete = "Even the most trivial quests at least deserve some rewards.",
	battle = "Heed my command! Forward!",
	id = 205100,
	gift_dislike = "",
	gift_prefer = "This is...! Heh heh. I hereby accept your sentiments!",
	profile = "Queen Elizabeth-class battleship, Valiant. Hehe, this fleet is known from Jutland to the Far East for its heroic majesty, and I am the reason for that! Now, Commander, you shall become my assistant so that you may prove your worth as a subordinate.",
	voice_key = 20510,
	headtouch = "Wh-what are you doing?!",
	feeling2 = "Good, you came. If you have no other work to do, play me in a game of chess.",
	login = "It's about time! Now, show me today's itinerary!",
	detail = "Look, isn't Elizabeth acting a bit too spoiled? And Warspite and the others are totally enabling that. I knew I should have been the one in charge... Huhh? I'm more or less the same...? Wh-what did you say?!",
	couple_encourage = {
		{
			{
				20501,
				20502
			},
			1,
			"Feast your eyes upon the might of the noble Queen Elizabeth-class!",
			0
		},
		{
			{
				20502
			},
			1,
			"M-make sure you observe my every move!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[205101] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "I brought water for you. Make sure you drink plenty if you want to stay healthy... That's right, eight cups a day!",
	unlock = "Hehe~ As this medical facility training is crucially important, a charismatic leader such as myself would be best suited to instruct everyone on– Wait a moment, what's with this outfit?! You there, explain the meaning of this at once!",
	touch2 = "...I, I'm only overlooking this because you're the patient!",
	mission = "",
	vote = "",
	drop_descrip = "Hehe~ As this medical facility training is crucially important, a charismatic leader such as myself would be best suited to instruct everyone on– Wait a moment, what's with this outfit?! You there, explain the meaning of this at once!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Don't get any weird ideas. I'm only pouring tea for you because you're the patient!|When we're not training for this exercise, how about a game of chess? I already brought the board. I'll set it up, so just wait in bed!|As a patient, so you're supposed to listen to the nurse! Mm... Besides, shouldn't you already be heeding my every instruction? You're my attendant after all...|You're my patient today! Heheh, be grateful that you're now under the care of the charismatic nurse, Valiant, and heed my every command! ...It, it's not like I'm into this or anything, so don't expect me to do this every single time!|It's time to get your blood drawn, so stick your arm out! ...Geh... I can't handle this stuff like Vampire does...",
	touch = "What's the matter? Are you going to die if I don't take care of you~?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 205101,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "It's about time! ...Wait, just kidding! You're supposed to be the patient, right? How about you stop walking around so much? Get back in bed this instant!",
	detail = "Hey you, don't tell me you're actually enjoying being taken care of like this?! Grr... How unfair! How about this, next time, I'll be the patient, and you'll attend to my every whim!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[205102] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Today, I feel like the world is mine~ Oh, you're back, my attendant? You may enjoy my cooking as a reward!",
	unlock = "Why the astonished look on your face? You heard me correctly! On this day, I am not merely Valiant, I am the regal and royal Queen Valiant!",
	touch2 = "Hwah?! ...Ahem! I'm feeling extra charismatic today, so I will forgive your transgression for today!",
	mission = "",
	vote = "",
	drop_descrip = "Why the astonished look on your face? You heard me correctly! On this day, I am not merely Valiant, I am the regal and royal Queen Valiant!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Elizabeth lost a bet with me. Now, she has to surrender the Crown to me for a day, and do whatever I tell her to~♪|See to it that I, Queen Valiant, am the center of all attention at tonight's party! Huh? Don't overdo it...? I, I know that!|Are you well-versed in ballroom dancing? Hrmm... It's decided! You shall be my dance partner tonight!",
	touch = "H-how dare you lay your hands on Queen Valiant!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 205102,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Do you remember how you are to address me today? Yes, \"Your Majesty, Queen Valiant!\" Make sure you do not forget this!",
	detail = "O~ho~ho! With my regal display of wisdom and fortune, I have finally secured the Crown from Elizabeth's grasp! Heheh~ before you is the victor of the War of the Roses!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[205110] = {
	hp_warning = "I won't back down... Hah!",
	feeling3 = "Protecting the weak is the duty of us Royal Knights—Uhh, I'm not saying that you're weak, Your Excellency. Though, when we're on the battlefield, you're definitely on the side of \"having to be protected\"...",
	mail = "There is mail addressed to you, Your Excellency! Should I bring it to you right now?",
	expedition = "The girls are back from their commissions. Shall we go greet them together, Your Excellency?",
	win_mvp = "Alright, let's keep this up!",
	home = "I'm relieved that you were able to make it back safely. For now, please get some rest.",
	unlock = "...Woah?! S-sincerest apologies, I wasn't watching where I was going... Oh, you're the Commander? S-splendid! Battleship Revenge of the Royal Navy, at your service!",
	touch2 = "That's a discourteous thing to do to a lady. Don't you agree, Your Excellency?",
	mission = "Is there a new mission? Please let me know any time if you would like my assistance.",
	vote = "",
	drop_descrip = "R-class battleship – Revenge.",
	feeling4 = "Your Excellency, you always work so tirelessly for our sake... You really should try to make some time for yourself. When you do, I'll stroke your hair, and cheer you up, telling you things like, \"Good work, Commander, you've done such a good job~\"",
	lose = "I guess I shouldn't have forced things so hard...",
	feeling1 = "Please, don't give in to despair! If you just reform yourself, there will surely be a day when you are accepted by everyone!",
	skill = "I shall protect the Commander and my allies!",
	upgrade = "Thank you very much. I'll make sure to live up to your expectations.",
	propose = "*pant* *pant*... I heard you needed something from me, so I ran here as fast as I could... Wait—this is... a ring? N-no way, I-I-I-I'm sorry! This is so sudden, I don't know what to say... B-but, gladly! Of course!",
	feeling5 = "Your Excellency, not only are you the most important person in this port, but you are also the most important person in my life. That's why your safety is paramount to me—whether here, or on the battlefield... I'll make sure to protect you with all I've got.",
	main = "Eek?! I apologize, I didn't notice the papers on the table... I'll get to them right away!|Not so long ago, I accidentally bumped into a destroyer while hurrying along... I'm glad that neither of us were hurt, but...|If you spend too long working, your neck and shoulders are bound to become stiff. H-how about I give you a nice massage to help you loosen up?",
	touch = "Did something urgent come up? Then, put it over there... Y-you just want to chat for a bit...? I'm sorry for jumping to conclusions...",
	voice_key_2 = -1,
	mission_complete = "Allow me to retrieve our rewards for the missions we've completed! ...Oh, I need to check the list first...?",
	battle = "Everyone, follow my lead!",
	id = 205110,
	gift_dislike = "",
	gift_prefer = "Are you sure... I can have something this valuable?",
	profile = "I am Revenge, lead ship of the Royal Navy's Revenge-class battleships. I partook in the Jutland campaign, but since I participated mostly in escort missions afterward, I wasn't able to see too much action in that great war... I'm sorry... you must be disappointed to hear this.",
	voice_key = 20511,
	headtouch = "Um, excuse me...",
	feeling2 = "U-umm... Your Excellency, regarding the time I bumped into you when we first met... Are you truly alright? ...Should we get your body checked?",
	login = "Good morning, Your Excellency. Is there anything I can help out with today?",
	detail = "You're not looking all too great... Is something on your mind? If there's something troubling you, please feel free to open up to me. It's not good to bottle things up inside...",
	couple_encourage = {
		{
			{
				20501
			},
			1,
			" The Royal Knights are here to defend you, Your Majesty!",
			0
		},
		{
			{
				1
			},
			3,
			"I-I won't bump into you!",
			1
		}
	}
}


_G.pg.base.ship_skin_words[205111] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Fighting on the battlefield is so much easier than being a maid...",
	home = "*pant* *pant*... Phew... I can't believe I'm getting this tired from just cleaning... Your Excellency... Why don't you also take a short break?",
	unlock = "Hrmm... *sigh*... Looks like I bungled this one too... I sure hope the Commander doesn't see me like th– Hwuh?! C-Commander? P-please give me a moment! I'll straighten this out right away... Waaah!!",
	touch2 = "H-how should I serve you at a time like this...",
	mission = "",
	vote = "",
	drop_descrip = "Hrmm... *sigh*... Looks like I bungled this one too... I sure hope the Commander doesn't see me like th– Hwuh?! C-Commander? P-please give me a moment! I'll straighten this out right away... Waaah!!",
	feeling4 = "",
	lose = "I can't believe I failed again... Waah...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Leave this to me... Eek! Your Excellency, I apologize... It wasn't on purpose, I swear!|The office is all tied up, the documents are organized as well... Alright! Both the Commander and Her Highness should be pleased with the results!|Your Excellency, I've learned how to brew proper black tea and make cookies from the Royal Maids... I-if there's a chance in the future, I'd like to...",
	touch = "I, I'm fine. Something like this is nothing a maid can't handle... Especially for a Maid-Knight like me!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 205111,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Welcome back, Your Excellency. As you can see, I'm currently in the middle of cleaning...",
	detail = "The Royal Maids and the Royal Knights both work hard to protect our allies. Volunteering like this renews my sense of purpose.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[205130] = {
	hp_warning = "Tsk... What a persistent bunch!",
	feeling3 = "While yes, I am a palace guard, that doesn't mean I should be stuck in port. Won't you let me sortie already? *sigh*... I'm going mad. The stress is killing me...",
	mail = "I've brought you a letter. Give it a read, Commander.",
	expedition = "The commission team is back. Let's head out to receive them, Commander.",
	win_mvp = "Hoorah! Victory is mine! May the Commander's name and mine alike go down in history! ...Oops! I didn't mean to say that aloud!",
	home = "The Commander has returned! Ladies, arrange for repairs and a debriefing! Commander, get some rest – I'll take it from here.",
	unlock = "I am Vanguard, palace guard of the Royal Knights! I hereby pledge to you my sword, and the full extent of my loyalty! May glory be yours, and God save the Queen!",
	touch2 = "Thank you for ceasing your inappropriate behaviour right at... *gasp*! Do you have a death wish?",
	mission = "Word of a new mission has come in. Have a look, Commander.",
	vote = "",
	drop_descrip = "Battleship – Vanguard.",
	feeling4 = "What? You're working overtime AGAIN? I understand it has to be done, but this is a bit ridiculous... I won't force you to order a sortie, but please, can't you make one happen somehow? ...You can? Brilliant!",
	lose = "Tsk. You'll pay for this, you hear?! ...No, I'm fine. Take the others and retreat, quickly.",
	feeling1 = "*sigh*... If you're not suited for the job, just admit it so we can find a replacement. Stop acting tough, it just makes you look pathetic.",
	skill = "This is a knight's swordsmanship!",
	upgrade = "My sword's purpose is to bring glory to the Royal Navy – and to you, Commander!",
	propose = "By this ring, my sword and my life now belongs to you, 'til the end of time! ...All righty, do you mind if I tone down the formality a bit? I mean, what's the point in being super serious 'round the clock?",
	feeling5 = "Mmmmh! That was refreshing! Thanks, Commander – I really needed that! It's days like these that make serving as a palace guard worth it. Now, you who guides my sword, what is your next order?",
	main = "You may rest assured, King George. If Her Majesty and the Commander so desire, I will gladly be the spearhead that sunders the enemy line.|Is that Bismarck over there? Gracious, this will be quite awkward...|The port seems to be all in order, and I can confidently say you're as well-guarded as can be!|Pardon my bluntness, but Royal cuisine is total shite. Sure, different people like different things, but something's wrong if even I as a native think it's rubbish.|Here's your programme for today, Commander! ...Damn, that's at the same time as the show I want to watch... N-no, just talking to myself!",
	touch = "My duty as a palace guard is to aid and protect you at all times.",
	voice_key_2 = -1,
	mission_complete = "Mission complete. *sigh*... I should've checked on it sooner.",
	battle = "Come! Let's settle this, fair and square!",
	id = 205130,
	gift_dislike = "",
	gift_prefer = "Mhm, I shall most graciously accept your gift.",
	profile = "I am Vanguard, the battleship that was launched after the end of the war. My sword is yours – may it bring glory to your port. Also, if I may make a request... please do NOT call my weapons \"old-fashioned.\"",
	voice_key = 20513,
	headtouch = "Yes? How can I help?",
	feeling2 = "So, what's on the schedule for today? ...You'll be working overtime filing paperwork? I'm sorry to hear that. Be that as it may, you will be present during today's exercise, right?",
	login = "The Commander has arrived! Ladies, at attention! ...Now, let's get to work, shall we?",
	detail = "Loyalty reverberates through my blade, glory booms through my barrels! Behold, the light of my royal sabre! ...Ugh, that's so cringeworthy! Although it does sound cool... C-Commander?!",
	couple_encourage = {
		{
			{
				30514
			},
			1,
			" What's that noise...?",
			0
		},
		{
			{
				20403
			},
			1,
			" Please be careful, Lady Hood!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[205131] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission team has returned to port. I shall accompany you to them.",
	win_mvp = "I beat the crap out of them with grace and elegance! Hahah!",
	home = "A salute for the Commander's return! By the way, bring me along for the next sortie, would you?",
	unlock = "\"Please let me know if you need anything, Master\"... I'm starting to think you're making me wear this as a sick joke. The reason being, I am obviously NOT fit to be a Royal Maid... Even if I do adore their uniforms...",
	touch2 = "Compare me to any of the other maids and I'll destroy you.",
	mission = "You have a new mission, Master. Please review it.",
	vote = "",
	drop_descrip = "\"Please let me know if you need anything, Master\"... I'm starting to think you're making me wear this as a sick joke. The reason being, I am obviously NOT fit to be a Royal Maid... Even if I do adore their uniforms...",
	feeling4 = "",
	lose = "This sucks... I told you I wasn't cut out for this.",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "How would you evaluate my performance as a maid? Ill-suited though I am for this job, I can still accomplish any task you can throw at me... Y-you want me to keep doing this? You know, I really feel like you just enjoy watching me suffer!",
	main = "While Royal Maids also participate in battle, their approach differs greatly from us knights. The only way I can put it is... they hold back too much?|Yes, Master? ...\"Getting the hang of this,\" eh... Are you making fun of me?|I alone get to protect you, my honourable Commander. No one will take this privilege from me!|nil|I have both secretary AND maid work to do... *sigh*... Will I ever get to sortie again?",
	touch = "As you say. Your wish is my command.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 205131,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "The Commander has arrived! ...I know that's not what a maid would say, but it's not like I could pull it off anyway...",
	detail = "Why do you insist on having me as a maid? I can hardly cook and I'm terrible at cleaning. Wait... Don't tell me maids are your kink...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[205140] = {
	hp_warning = "Why does this keep happening to me...?",
	feeling3 = "I think my speed should be enough for patrol work from now on. Okay, I hope this next one goes safely... Please, please don't let me run into any submarines!",
	mail = "Ah... There it is! Who in the world folded the mail into a paper airplane?",
	expedition = "The commission team is back. Would you mind if I went with you to greet them? I'm a bit of a slow walker, but...",
	win_mvp = "Phew. I managed to do my job... right?",
	home = "Lord Commander, thank you for your efforts. Is there anything I can help you with? ...Anything is fine, really...",
	unlock = "I am Royal Oak, battleship under the Royal Navy. It's an honour, Lord Commander... I hope to overcome my weaknesses and pull my weight here, so... I-I'll be counting on you...",
	touch2 = "Eeeeek! *pant* *pant*... P-please, no more!",
	mission = "Lord Commander, you might want to finish those missions soon...",
	vote = "",
	drop_descrip = "R-class battleship – Royal Oak.",
	feeling4 = "Oh, my... Was I really so helpful, Lord Commander? The old me would never have believed that... Umm... P-please let me handle even more missions!",
	lose = "Why is this happening? I tried so hard...",
	feeling1 = "I just know you turned out this way because I was holding you back, Lord Commander...",
	skill = "Don't hate me for this!",
	upgrade = "\"The Mighty Oak.\" Do you think I can live up to that...?",
	propose = "I-is this real? I'm not dreaming... Lord Commander, you'd really give me something this valuable? Of course, I've always hoped that I could have this honour someday, and I'm as happy as can be! Umm, anyway, I happily accept!",
	feeling5 = "Not only did you not abandon me, but you've been considerate and even given me confidence in myself... S-say! If it's alright with you, could you teach me about more than just fighting and working...?",
	main = "Excuse me, Lord Commander! Oh, I didn't mean to interrupt... Umm... I'm not a fan of such quiet places. They make me remember painful things...|Lord Commander, don't stray training rounds come at you when you leave the window open...?|I at least have to see these documents delivered... Yes, I'll do my best to be back as soon as possible!",
	touch = "Ack! D-don't touch me out of nowhere, or you'll scare me...",
	voice_key_2 = -1,
	mission_complete = "Thank goodness... Back home safe from another mission. Ah, Lord Commander, I hope I wasn't holding you back!",
	battle = "P-please don't charge ahead so fast...",
	id = 205140,
	gift_dislike = "",
	gift_prefer = "Thank you! I shall treasure this with the greatest respect!",
	profile = "Introduce myself again? Okay... Umm, my name is Royal Oak, and I'm a Revenge-class battleship from the Royal Navy. I was able to accomplish something in the Battle of Jutland, but I ended up getting badly damaged after... I just hope I can escape my bad luck here at this port.",
	voice_key = 20514,
	headtouch = "",
	feeling2 = "I'm among the most senior Royal Knights, but I can't lead anyone. Heck, it takes all I have just to keep up... This fleet doesn't need a shipgirl like me.",
	login = "Hyah! Sorry, I wasn't standing behind the door on purpose... Umm, I'm okay, okay? You don't have to worry or apologize...",
	detail = "I was watching the girls perform a training exercise, and a stray training round hit me... N-no, I'm not injured, but... It really hurt...",
	couple_encourage = {
		{
			{
				40802
			},
			1,
			" D-d-don't come any closer!",
			0
		},
		{
			{
				20511
			},
			1,
			" Royal Knights, charge!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[205141] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Lord Commander, you don't need to fret over me. Though I am happy to have you here with me...",
	unlock = "Commander? Oh, what a coincidence... Were you slacking– err, I mean, taking a break, too? I can make some room for you if you'd like?",
	touch2 = "I-if a hall monitor sees this, everyone will know!",
	mission = "",
	vote = "",
	drop_descrip = "Commander? Oh, what a coincidence... Were you slacking– err, I mean, taking a break, too? I can make some room for you if you'd like?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "I'm not the worst at classroom learning. If there's anything you don't understand, I-I could help...?|If you want to pass the time, how about reading? For some reason, there are lots of confiscated novels and manga here...|By the way, how does Her Majesty normally spend time at school? Huh? She's actually bad at P.E. just like me?",
	touch = "The others might realize something's up if we go back now...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
