_G.pg.base.ship_skin_words[205160] = {
	hp_warning = "Heheh... There is no greater danger than a wounded lion!",
	feeling3 = "You're far more capable than I'd anticipated. Indeed, our cooperation has improved a lot since we became part of the same \"pack.\" Hahah – does my praise really make you that happy?",
	mail = "There is a new letter. I've confirmed it poses no threat.",
	expedition = "The commission team has returned. The duty of receiving them falls upon us. Come.",
	win_mvp = "The battlefield is an untamed expanse, and the victor is its king. This victory is proof of this.",
	home = "All is as it should be around the port – I verified it myself. No threat dares approach the den of the lion, it seems. Now be at ease.",
	unlock = "Oh? I was wondering who this new face is, and it's you! I do hope you won't disappoint me. Once again, I'm Lion – the protector of both you and this port.",
	touch2 = "Are you testing me to see how much I can tolerate?",
	mission = "You've yet to finish your missions? It disappoints me to see this port's leader be so neglectful. Fear not, though – I will assist you.",
	vote = "",
	drop_descrip = "Lion-class battleship – Lion.",
	feeling4 = "My intention was simply to protect you and the port, but before I knew it, I'd become unable to take my eyes off you. I'm not saying that's a bad thing, mind you.",
	lose = "You will suffer for this next time our paths cross. Commander, for now, we retreat.",
	feeling1 = "You have disappointed me. Regardless, I will keep watching you until you show growth.",
	skill = "Tear them to shreds!",
	upgrade = "Good. Now I can better protect both you and this territory.",
	propose = "This occasion marks you fully becoming the lion's property. Yes, you are my property, and no one will take you from me. Now, about my collection of adorable lions... I'll let you see them, if you wish to.",
	feeling5 = "Ahem... You know how it is. You are the Commander, and your duty is to lead us. That said, if you'd be willing to hear me out in private – that is, when we're all to ourselves – I could... treat you more gently, like a lion would treat its mate.",
	main = "My lion ornaments? Ahem... Why, they're there to intimidate enemies, and not because I'm particularly fond of them.|It is important to patrol the port. One cannot properly protect their territory without knowing every corner of it. Yes, that includes you.|Getting a sweeping view of the port bolsters my mood. Hm? Are you afraid of heights? Don't worry, I'll keep you safe.|Hm? Do you have something to tell me? Then spit it out. I hate those who beat around the bush – or should I say, I like you more when you're upfront.",
	touch = "Hm? Is something the matter?",
	voice_key_2 = -1,
	mission_complete = "You're progressing well on these missions. Do remember to claim your rewards, head held high as you do.",
	battle = "You wish to intimidate them with my presence? Good decision.",
	id = 205160,
	gift_dislike = "",
	gift_prefer = "Hmm, oh my... You truly know me quite well. Indeed, I shall treasure your sentiments as well.",
	profile = "I am Lion, Lion-class battleship of the Royal Navy. Heheh. While this port is indeed yours, know that it is also my territory. I will aid you in protecting it, letting not a single threat slip by undetected. This I swear.",
	voice_key = 20516,
	headtouch = "...You are an audacious one. Or are you just playing up to me? Hahaha.",
	feeling2 = "While I acknowledge you as this port's leader, I've yet to ascertain your ability. That said, our relationship may just improve if you put in the work.",
	login = "Good, you're back. Okay, eyes up and don't squirm! You need to learn to hold your head high under my gaze.",
	detail = "I created a programme for you to follow. First up: Sorting paperwork. Then, a patrol around the port, a focused inspection of our security system, and finally... Yes, I've of course included breaks. Rest assured, I will accompany you the entire day.",
	couple_encourage = {
		{
			{
				20501
			},
			1,
			" Your Majesty, it is dangerous on the battlefield. I shall take care of this.",
			0
		},
		{
			{
				20513
			},
			1,
			" You make a great assistant.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[205161] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "So the commission team is back. I'll allow you to step away for a while, then.",
	win_mvp = "",
	home = "You've returned. Can't handle the sun? Then consider sitting next to me for a while.",
	unlock = "Heh. I hereby claim this beach as part of my territory. Whew... Say, Commander, since we've been afforded some time to relax, why don't we do so? Oh, and feel free to come a little closer.",
	touch2 = "Heh... Making a bold move, are you?",
	mission = "You cannot let the missions pile up while on vacation... No, actually, stay here. I'll help you after we've had our fun.",
	vote = "",
	drop_descrip = "Heh. I hereby claim this beach as part of my territory. Whew... Say, Commander, since we've been afforded some time to relax, why don't we do so? Oh, and feel free to come a little closer.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Commander, this holiday mustn't be squandered. Let us take our time and enjoy this private world of ours. Hm? You'll decide how to spend our time right now? Fine, but at night, it will be you who listens to my orders♥",
	main = "One needs to protect against sunburns. Commander, could you reapply the suntan lotion right here?|When the mood is comfortable and relaxed, the lion shows its soft side. Will it bring us closer together, I wonder?|This is thanks for applying the suntan lotion on me. Open your mouth and I will feed you this fruit. Naturally, refusal is not an option♪|That's quite the delectable drink you chose. Care to try mine? You're not too embarrassed to use the same straw, are you?",
	touch = "What? Are you checking where I applied the suntan lotion?",
	voice_key_2 = -1,
	mission_complete = "Exemplary work with those missions. Do you want an additional reward? For instance... Ah, what do you wish to be fed this time?",
	battle = "",
	id = 205161,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Since it's only us here... I'll allow you to satisfy yourself.",
	feeling2 = "",
	login = "What's this? Have you been charmed by the lazy lion? That makes two of us. I feel... a little different from my usual self, somehow.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[206010] = {
	hp_warning = "",
	feeling3 = "Interests in anything besides dueling? Hmm... I've never thought about it. Will you show me something new, Commander?",
	mail = "You've got new mail, Commander. I wonder if it's a request for a duel!",
	expedition = "Hold on! Our fleet has come back from commission. Let's see what they've earned.",
	win_mvp = "When the stars gather in one place, our bonds will illuminate a new future!",
	home = "Gotcha! Your dueling was hot out there!",
	unlock = "Glory to the cards, my soul to the duel d... I mean, the flight deck! I am Hermes. Commander, give me your orders!",
	touch2 = "Hmm.... If the Commander is interested, I'll properly reward you each time you win.",
	mission = "Missions are like challenges, Commander. Let us challenge ourselves to even greater heights.",
	vote = "",
	drop_descrip = "Hermes-class aircraft carrier – Hermes, Hull Number 95!",
	feeling4 = "Mmm... Commander, I decided to engrave your portrait on the back of my cards. That way you're always with me!",
	lose = "I won't surrender. My turn... Let me go!",
	feeling1 = "Have you fallen to the forces of darkness, Commander...? I'll have to defeat you then!",
	skill = "It's my turn!",
	upgrade = "The new me now can move to even greater heights with my deck!",
	propose = "This feeling is……! The bonds formed between Commander and I here shall open up a brand new future, a path of brilliance! It’s our turn, draw!",
	feeling5 = "If two duelists fall in love, Commander, they can undertake more duels together! They also must truly understand each other... I think that requirement is already fulfilled for us... so... shall we try?",
	main = "It is my wish to duel with {namecode:89}|In each plane and every card resides a soul. |It's my turn!Victory aside, I also want to bring happiness to everyone.",
	touch = "What, you want to duel?",
	voice_key_2 = -1,
	mission_complete = "Rewards' is a good of a word as \"duel\". Let's see what you've got!",
	battle = "If you believe in your fleet, we'll work our hardest to meet your expectations!",
	id = 206010,
	gift_dislike = "",
	gift_prefer = "Thanks. I really like it.",
	profile = "I am called Hermes, I was the second aircraft carrier to be ever built. \n The only carrier to be sunk by the Sakura Empire? Can't do much about stuff like that. But if I ever get the chance, I want to duel that first carrier.",
	voice_key = 20601,
	headtouch = "",
	feeling2 = "What's up, Commander? Interested in duels? Don't worry, we'll start from the beginning, I'll teach you! The most important thing is spirit!",
	login = "You're back. Now it's time to duel!",
	detail = "Statistics aren't important, it's how you take advantage of them.",
	couple_encourage = {
		{
			{
				20217
			},
			1,
			"A fellow duelist?!",
			0
		},
		{
			{
				30603
			},
			1,
			"Houshou, there is infinite potential inside you!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[206019] = {
	hp_warning = "My path to victory does not end here!",
	feeling3 = "",
	mail = "There is something present in the mail beyond what you can see with your eyes. That is: friendship.",
	expedition = "",
	win_mvp = "Hatred, no matter how deep it runs, will always be weak.",
	home = "",
	unlock = "Our glory coalesces into the bonds that forge a bright new future! Let's rev it up! Hermes, retrofit complete!",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "Our glory coalesces into the bonds that forge a bright new future! Let's rev it up! Hermes, retrofit complete!",
	feeling4 = "",
	lose = "No one is truly undefeatable... If you give up now, you were never worthy of being my Commander.",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Houshou is strong. And now I know. That strength comes from her kindness.|Your spirit is a great weapon, and an even greater weakness. No matter where you are, you must not forget that.|Centaur taught me how to make this. Try it. I'm showing you that I'm more than just a duelist.",
	touch = "That's the wind... Commander, follow my wake!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Hangar, gate open!",
	id = 206019,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I've been waiting. The cards... no... my burning soul told me you'd returned.",
	detail = "For a true duelist, there are no accidents, Commander.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[206020] = {
	hp_warning = "B-but the Royal Navy's tradition and glory...!",
	feeling3 = "You'd like to take me around on your off day? If it's no trouble, then I'll gladly take you up on that offer. Oh... But I'll need you to bring me back to my dorm before curfew...",
	mail = "A letter's arrived. As for the envelope... Umm, should I just cut it open with scissors?",
	expedition = "The commission team has returned. Just like carrier-borne craft, you have to welcome the girls back after you've sent them away!",
	win_mvp = "Me, MVP? You're not joking? I can't believe it...",
	home = "Phew... Welcome back, Commander. *pant* *pant*... I managed to make it back in time before curfew...",
	unlock = "\"Know me as the Royal Navy's own Argus, bearer of a hundred all-seeing eyes, the primordial standard aircraft carrier and first to possess a full-length flight deck.\" W-will that do...? Sorry. As you can tell, I'm no good at introductions...",
	touch2 = "B-be gentle, please... *blush*",
	mission = "We have word of a mission. Are you sure we shouldn't take a look at it...?",
	vote = "",
	drop_descrip = "Light aircraft carrier – Argus.",
	feeling4 = "Thank you for another lovely day, Commander. Oh, it's getting late... I'd best get back to my dorm soon, but I-I'd like to take a walk together, first! I'm sorry... May I ask you to indulge me a little?",
	lose = "Urgh... Is this my punishment?",
	feeling1 = "Ah! If you don't need anything, I'd best be taking my leave! Phew...",
	skill = "Come back safe, please...!",
	upgrade = "\"My rigging, tempered a thousand times over\"... I just hope this is enough to help me hold my own in a fight...",
	propose = "I swear on the tradition and glory of the Royal Navy that I, aircraft carrier Argus, will always work my hardest for our mutual happiness. Commander... Would you hold my hand, please?",
	feeling5 = "Phew... Ehehe, curfew's come and gone already. Say, Commander? What if we kept hanging out together and gazed at the night sky together? There's no point in going back to the Royal Navy dorms, since it's past curfew already.",
	main = "\"Fall before the might of my ancient, glorious power\"... U-umm, could you go a little easier on the office work, please?|Houshou? Oh, thank you for the treats! Are these meant for a tea party? No?|You're going out? Okay, I'll take care of the place—Oh, but if you think you'll be out late, please remember my curfew...",
	touch = "Is this... a lesson?",
	voice_key_2 = -1,
	mission_complete = "Is the mission complete? Phew... That's great to hear.",
	battle = "Training... Aircraft carrier Argus is present and prepared!",
	id = 206020,
	gift_dislike = "",
	gift_prefer = "This is... for me? ME?!",
	profile = "\"Know me as Argus, oldest carrier in the world. With the glory and tradition of the Royal Navy at my back, I come to you to lead the next generation of heroes\"... I could never say something that grand with a straight face. I'm... looking forward to working with you, okay?",
	voice_key = 20602,
	headtouch = "You'll make a new hat for me?",
	feeling2 = "\"With the ancient wisdom gathered by sending off countless fledglings, I will lead you, Commander\"... May I lead you? If you'll have me, anyway.",
	login = "Shall we get to work, Commander? It's getting late. I don't think we should wait any longer...",
	detail = "\"You may enter. Come, and witness the glorious history and tradition of Argus\"... I-I mean... If you don't mind...",
	couple_encourage = {
		{
			{
				20601,
				30603,
				10701
			},
			1,
			" I will wield my power as the oldest carrier!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[206021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Costumes, materials, and printed materials are all done. I've contacted the commission team, as well... Things are really coming together. Phew...",
	win_mvp = "We won! None can rival the Royal Navy's glorious tradition!",
	home = "Welcome back, Commander. We have some time until our next plans, so feel free to take a little break.",
	unlock = "Yaaawn... Umm, did I doze off again? Oh no... Organising school events gets so hectic I always end up working right up until curfew... Just give me one more minute, please...",
	touch2 = "Whawha?!",
	mission = "There are still things to be done before the school festival... Let's begin with these missions.",
	vote = "",
	drop_descrip = "Yaaawn... Umm, did I doze off again? Oh no... Organising school events gets so hectic I always end up working right up until curfew... Just give me one more minute, please...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Achoo! ...Thank you. Of course sleeping here all the time would lead to me getting a cold. I should be more careful...|There are strange things going on at the haunted mansion? C-Commander, I'm sorry... Would you mind accompanying me?|Implacable! You can play that game at home, but you can't bring it to the festival! What do you mean, why? A-aren't you embarrassed?!",
	touch = "Is it time for the next item on our schedule?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 206021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Sorry you had to come and help me, Commander... Umm, so what were today's tasks, again?",
	detail = "Hosting school events is really such a task. I've been so sleep deprived lately... *yaaawn*... No, that's enough yawning. I still have work to do...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[206022] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission girls are back. Why don't we invite them to the party?",
	win_mvp = "\"This attire will do perfectly for the parade celebrating my triumph.\" Phew...",
	home = "The Commander picked this dress for me, so I need to wear it right... Commander? Welcome back. Did the mission go well...?",
	unlock = "\"Gaze upon this glorious dress. Admire its brilliance, tremble, and...\" If you don't mind, would you please take Argus' hand?",
