	mission = "The mission correspondence...? R-right! Now, where did I put it...?",
	vote = "",
	drop_descrip = "\"Gaze upon this glorious dress. Admire its brilliance, tremble, and...\" If you don't mind, would you please take Argus' hand?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "How long will this party go on? If it goes too late, my curfew... N-no, I'm not just trying to go home, I swear!|In fairy tales, girls lose their fancy clothes after midnight... And that means I... Eep... A-Argus, stop thinking such shameful things...|Don't drink too much at the party, now. If you get drunk, how am I going to change clothes? ...You want me to get Hermes and the others to help? G-good idea! Why didn't I think of that?",
	touch = "Am I really wearing it to perfection...? Commander, do you see any issues? Y-you can feel for yourself, if you want...?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "I-I'm a little worried about my back...",
	id = 206022,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Does this look right? Let me try spinning around—Hyah?! C-Commander, I'm sorry...",
	detail = "\"Take a good look upon the majesty and poise of Argus as she graces the venue.\" ...I feel much better practicing my bearing with you, Commander. Heehee.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[206023] = {
