	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome back, Commander... Um, I managed to carry out my training... without running away!",
	unlock = "\"When the honourable and dignified set out to achieve greatness, they must never be ashamed of exposing themselves\"... I prepared this swimsuit for special training, and yet... Just putting it on requires... a great deal of courage.",
	touch2 = "I-is this part of my training, too? Mm... Very well... Behold my... resolve...",
	mission = "",
	vote = "",
	drop_descrip = "\"When the honourable and dignified set out to achieve greatness, they must never be ashamed of exposing themselves\"... I prepared this swimsuit for special training, and yet... Just putting it on requires... a great deal of courage.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Normally, I'd have swooned from shame by now... But knowing I have you with me, Commander, nothing else matters... Don't blame me, no matter how this turns out. Ehehe♪",
	main = "\"With the glory and tradition of the Royal Navy at my back, I stand proud, my heart pure...\" The sun is so warm on my skin... Ah?! No, I did not come here to sunbathe, of course...!|Aaah... The string on my back is coming loose... It bothers me, but I cannot afford to check...|Commander, once we finish training, could you walk me back to my quarters? I'm worried about curfew...",
	touch = "T-touch me...one more time... That should make for good training...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 206023,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Mm... When you praise me, I feel as bashful as a little pet... But... Nnn...",
	feeling2 = "",
	login = "Commander, I'm still trying to work up the courage to show myself to you... Aaah, this is so embarrassing...",
	detail = "\"Behold, the Hundred-Eyed Giant, training in the majesty of a swimsuit\" – Aaah... Th-this swimsuit is quite skimpy at the back...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[206030] = {
