	touch = "Ehehe... Big brother... that tickles...",
	voice_key_2 = -1,
	mission_complete = "Don't miss... your rewards...",
	battle = "Leave the rear support to me... I'll... do my best...!",
	id = 206030,
	gift_dislike = "",
	gift_prefer = "I love it...",
	profile = "Royal Navy's... support carrier... I am Unicorn... I was born to support my big sister Illustrious... Later, I went to support other big sisters... but everyone treated me nicely. I worked hard in lots of different ways, you know? ...It would be nice if I become a little dependable... Ehehe, I'll work harder, big brother",
	voice_key = 20603,
	headtouch = "Big brother... is Unicorn a good girl...? ",
	feeling2 = "This over here is Yuni. Yuni the Unicorn... is my friend... Ehehe",
	login = "Welcome back, big brother... Are we going to sortie for today as well?",
	detail = "Big brother... do you want to know more about me?",
	couple_encourage = {
