	id = 206062,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "...Oh. Now it's your responsibility to comb my hair.",
	feeling2 = "",
	login = "Hm? Did you give up on being the early bird? ...Me? I'm the spring worm that sleeps in.",
