_G.pg.base.ship_skin_words[206070] = {
	hp_warning = "I've got to dig my heels in... I don't want to be a burden to my Elders!",
	feeling3 = "Hmm... Perhaps I need a new way of addressing my Elders of the destroyer class... And then there are the blueprint ships as well... But they're still my Elders... What should I do...?",
	mail = "There seems to be some new mail... Would you like to take a look?",
	expedition = "The whispers of the wind... tell me that the girls have returned from their commissions. Let me know when you're ready to meet with them.",
	win_mvp = "The unblemished Albion thus claims this victory!",
	home = "You did a great job, Commander. Please call for me if there's anything I can do to lighten your load.",
	unlock = "My name is Albion, sister ship to light carrier Centaur. As a Childe to this fleet, I hope to receive guidance from everyone in this fleet–– Um, Commander, that also makes you one of my Elders, right?",
	touch2 = "H-how embarrassing... Ugh...",
	mission = "Let us work towards the completion of your missions. It is by following your example that we shipgirls reach new heights.",
	vote = "",
	drop_descrip = "Centaur-class light aircraft carrier – Albion.",
	feeling4 = "Elder Commander, should I leave these documents over here? Urgh, I knew it would feel weird to call you that... Calling you one of my Elders doesn't feel respectful enough, and frankly, feels quite strange to say out loud...",
	lose = "How did I manage... to be so clumsy...",
	feeling1 = "Was there something amiss with the way I conducted myself...?",
	skill = "Please watch what I can do, my dear Elders!",
	upgrade = "The strengthening was a success. Commander, please see for yourself how the ride feels next time we head out.",
	propose = "A... Promise Ring? Um, I don't recall ever asking for one though... You're giving it to me because you love me? O-oh! Yes, I see! I apologise for being so thick-skulled that I didn't have an inkling of your feelings for me. Ehehe, thank you... very much. ♥",
	feeling5 = "How should I address the Commander then? Lord Commander? I'm sure my Elders have much more intimate ways of address... Ugh, I can't believe I sabotaged myself from the start, even though I'd like to have a closer relationship... Maybe I should try a different approach, like a date or something...?",
	main = "If you require a change of pace, I would like to suggest taking a stroll through the forest with Elder Centaur. I would especially recommend the forest by the hills, as the wind there feels particularly nice. Hehehe.|The ships of my class use a variety of arms in battle, so I don't think trying to copy their fighting style will be of much use to me. Instead, I can learn from their battle-readiness.|Grey Ghost...? I'm not sure I can shoulder the burden of sharing a nickname with Elder Enterprise... I-if you're fine with it, I do suppose you can call me that, if you wish...",
	touch = "U-um, go ahead... So long as you don't touch the rigging of my bow...",
	voice_key_2 = -1,
	mission_complete = "The rewards for your completed missions are here. Should I... check the address to confirm whether they've arrived at the right place?",
	battle = "With courage and loyalty, we shall prevail!",
	id = 206070,
	gift_dislike = "",
	gift_prefer = "A gift bestowed upon me by my Elder... Heehee.",
	profile = "I am the Royal Navy light carrier, Albion. I was constructed along with Centaur after that great war, and was one of the first aircraft carriers to carry out newly-developed tactics. Please watch over my growth under the tutelage of my Elders, Commander.",
	voice_key = 20607,
	headtouch = "",
	feeling2 = "As a Childe of the fleet, I can only hope to learn from the examples my Elders set in battle, as well as from how you manage the fleet. There is much for me to learn in terms of techniques, mental attitude, as well as everyday customs.",
	login = "Light carrier, Albion, at your service. I await your orders.",
	detail = "You want to know about my appearance? Unlike Elder Centaur, my name is not based on a mythological creature. If I had to say, the land where those with my appearance lived in the ancient times when legends roamed the world... Oh, am I talking your head off?",
	couple_encourage = {
		{
			{
				20601
			},
			1,
			" Elder Hermes, I'm right behind you!",
			0
		},
		{
			{
				20604
			},
			1,
			" Elder Centaur, don't push yourself too hard!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[206071] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "A victory as unblemished as... Oh, I wonder if I can still say that in these black clothes... I-in any case, a victory is a victory!",
	home = "Impeccable results. Oh, I suppose I should have a more condescending attitude towards you...? Umm, I suppose those were... passable results?",
	unlock = "Ah, umm... If you keep staring at me like that... Oh, um, Commander, this is supposed to be a Royalty of the Night costume, right? In that case... Would you mind kneeling for me first?",
	touch2 = "So this is what you're like when you've been seduced... I'll have to keep this in mind... Whew... *blushes*",
	mission = "",
	vote = "",
	drop_descrip = "Ah, umm... If you keep staring at me like that... Oh, um, Commander, this is supposed to be a Royalty of the Night costume, right? In that case... Would you mind kneeling for me first?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Commander, please continue serving me until the end of time. If you keep your end of the bargain, I swear that I... ehehe, will always take care of all your needs. Both faeries and vampires live long lives, so regardless, I'll always be with you~♪",
	main = "Shall I become a faerie, a vampire, or even a succubus...? Hmm, I wonder, which of these do I see myself being?|Elder Vampire has taken me under her tutelage, but it's quite difficult to walk in this outfit... Oh, I'd be just fine with you by my side, though.|It feels quite awkward having to give you orders... You know what? You should be the one ordering me around after all. Just say the word, and it shall be done.",
	touch = "This outfit is a bit too tight around certain places... Ugh...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 206071,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Tonight, I shall make a servant of you, Commander. Um... Excuse me, but could you do this favour for me please? *bows*",
	detail = "I-I apologise for making a fool of myself... If it's alright with you, can I tag along with you for a bit longer? I'm sure if I try hard enough, I'll be able to step on you more satisfactorily... But don't worry, I'm just playing a role.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[206072] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Thank you for your leadership in battle, Commander. Would you like tea? Our seniors in the Dragon Empery taught me, so I hope you like it...",
	unlock = "Hand brushing my hair behind my ear, eyes toward the camera... Mm, filming promotional material isn't easy... Commander, will this do?",
	touch2 = "C-Commander, perhaps we should show restraint for now...",
	mission = "",
	vote = "",
	drop_descrip = "Hand brushing my hair behind my ear, eyes toward the camera... Mm, filming promotional material isn't easy... Commander, will this do?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Heehee, I heard a little whisper just now. The breeze blowing against my ears and the wafting scent of flowers tell me that our hearts are connected, Commander. Do you hear it, too, Commander?",
	main = "Feeling the nighttime breeze on the veranda, the comforting fragrance of flowers... Hm? You thought that looked good and took a picture? U-umm... Th-that's a little sudden, no? I wasn't even posing yet...|Relaxing walks in the forest are nice, but there's a slightly more unique vibe right here. Do you feel it, Commander?|Is it easy to move in this dress? Umm... Well, I can fight and do chores just fine... Oh, shall I wear it to secretary duty tomorrow? Hm? You won't be able to focus? But why...?",
	touch = "Tickles a little... Do you want a photo like this, Commander?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 206072,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I must learn to be a proper model, at least until I'm worthy of this dress... Oh. Welcome back, Commander. Do you have orders for me today?",
	detail = "You can let me know if there's anything you ever need, Commander, whether it's for advertising or not. I would love a chance to see my seniors taking such charming photos...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[206073] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "The smell of something burning woke you up? Um... Sorry. I burned the toast.",
	unlock = "Good morning, Commander. Umm... I was excited to prepare a perfect breakfast for you, but I made some mistakes. Please wait a moment. I'll remake it in no time!",
	touch2 = "Huh? More milk...? Umm, Commander... Can it wait until after breakfast?",
	mission = "Missions? This early? Don't worry about me. I'll bring breakfast to you as soon as it's ready!",
	vote = "",
	drop_descrip = "Good morning, Commander. Umm... I was excited to prepare a perfect breakfast for you, but I made some mistakes. Please wait a moment. I'll remake it in no time!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Waking up next to you, making breakfast together, and basking in the morning sun... Life feels so warm and happy. Is it too much to hope that every morning could be like this from now on? Am I being too greedy...?",
	main = "Did you sleep well last night? I slept so soundly, and even had a warm dream – with you by my side... Would you like to know what it was about?|You want to make breakfast with me? Umm, sure, I don't mind. I'm certain it'll taste better when we make it together.|What a beautiful sunny day... Commander, what say we go out for a walk after breakfast?",
	touch = "C-Commander, may I have a good morning kiss? Oh, goodness... I managed to say it, but it's so embarrassing...",
	voice_key_2 = -1,
	mission_complete = "Commander, are you done with your missions? Great. I just made a new breakfast for you.",
	battle = "",
	id = 206073,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "I don't have to worry about it too much? Okay... Thank you.",
	feeling2 = "",
	login = "Ugh, I even spilled the milk... It's not on my clothes, is it? Phew. I'd better get this fixed up before the Commander wakes up... Huh? Commander, you're... already awake?",
	detail = "I wanted to make you a tasty, healthy breakfast... Umm, when I was checking the milk temperature, I remembered your warmth, lost my wits for a moment, and... Well, I'm sorry...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[206080] = {
	hp_warning = "I will not... succumb so easily!",
	feeling3 = "Care to join me? The woods are the perfect place for a tea party... Picnic? Hmm, I suppose it is more like a picnic, now that you say that...",
	mail = "Oh, this letter is addressed to you. I just assumed it was for me, since it arrived by homing pigeon.",
	expedition = "The commission team's come back. Do you know what comes next, Commander?",
	win_mvp = "How'd I do? Did I successfully realise the plan you had in mind, Commander?",
	home = "Splendid work, our Eagle of Victory. Before you go reflect on your performance, shouldn't we celebrate this triumph first?",
	unlock = "I am Theseus, Colossus-class light aircraft carrier. Well met, Shepherd of the Fleet. If you ever need someone to carry out combat, housework, or an incantation, just call my name.",
	touch2 = "Whoa! What's gotten into you?",
	mission = "Ah, missions... Got it. Shall we do them together, Commander?",
	vote = "",
	drop_descrip = "Colossus-class light carrier – Theseus.",
	feeling4 = "How's your evening, our Champion? Not too much work? Not feeling burnt out? Heehee. Do give me a call if you need anything. I'll do everything I can, and still consider the things I can't do.",
	lose = "Well, we lost... Commander, let's retreat for now and have another go later.",
	feeling1 = "Don't cross that delicate line, Villainous Fiend – or else I'll do everyone a favour and eradicate you.",
	skill = "Eyes open for my might! Taaake THIS!",
	upgrade = "Eyes open for my newfound strength!",
	propose = "I understand. You've given me the ring, but aren't sure how to profess your love. I'll do the honour, just... Oh, you worked up the courage? W-well, that's good! Heehee. Did I do a good job?",
	feeling5 = "Eyes open for my marvellous... Heehee, oh, it's nothing important. I simply used an incantation that tells me whenever you're in a spot. Saves you the effort of having to tell me. Convenient, no?",
	main = "Hi there, Unicorn. Do you mind if I take little Yuni on a tour de dessert again? ...Huh? What is it? Did I say something odd?|All this work piling up reminds me of herbs brewing in a cauldron... Eyes open, Commander. I'll have this done in a flash.|They say to strike while the iron is hot, but I'd say strike even if it's not. What I'm driving at is: let's take a break and clean the office, shall we?",
	touch = "I'm here and listening if you need someone to talk to♪",
	voice_key_2 = -1,
	mission_complete = "Heehee. These are more rewards than you can shake a stick at. How lovely.",
	battle = "The battle is on. Everyone, stick close to me!",
	id = 206080,
	gift_dislike = "",
	gift_prefer = "Wow! A gift from my Champion! ...My eyes are wide open~♪",
	profile = "Colossus-class light aircraft carrier Theseus, at your service. Sadly, I just barely missed my chance to fight in the war, but that's okay. Much like my namesake's ship, nothing will change who I am now.",
	voice_key = 20608,
	headtouch = "",
	feeling2 = "Funny our paths should cross here, Commander. Were you looking for me, perchance? Heehee, you're like a doggy, sniffing around in search of its friends♪",
	login = "Good morning, Guardian Knight of the Port. Hope you slept well. You can call on us anytime if you need a word.",
	detail = "I spy with my little eye a naughty cat who's snuck into my room to snoop around for secrets... Got you! Hm? No, Commander, this the creature in question – not you.",
	couple_encourage = {}
}


