_G.pg.base.ship_skin_words[207010] = {
	hp_warning = "A warrior of the Royal Navy won't back down so easily!",
	feeling3 = "I'm not a frequent attendee at Royal Navy tea parties... Which isn't to say I don't want to, it's just... they bring out snacks at tea parties... What do you think I mean, Commander?! I'd gain weight, that's the problem! ...Sorry, I lost my cool for a sec there.",
	mail = "There's mail for you. Don't forget to give it a look.",
	expedition = "Commission complete. Let's go and offer the returning team some biscuits. Don't worry about me, I can do without.",
	win_mvp = "To show compassion to your foe is to put the safety of your allies at risk.",
	home = "My body weight's still the same as it w– Oh! Commander! Didn't think you'd be back so soon. A-anyway, you'd better give our next mission plan a look!",
	unlock = "The name is Eagle. I intend to serve your fleet to the utmost of my abilities as a proud warrior of the Royal Navy.",
	touch2 = "You see, this is the reason why we have to teach people proper etiquette.",
	mission = "There's still unfinished missions, Commander. We should get them done sooner rather than later.",
	vote = "",
	drop_descrip = "Eagle-class light aircraft carrier – Eagle (HMS Eagle.)",
	feeling4 = "Despite my low-calorie diet and daily rigorous exercise, my weight stays the same... *sigh*, I guess my past status as a battleship defines me more than I think... But why?! How does everyone else manage to lose weight just fine?!",
	lose = "Tsk, I've taken damage after fighting for so long... I'll need repairs when we return.",
	feeling1 = "You're betraying everyone's trust in you by acting like this. Pull yourself together, for god's sake!",
	skill = "You're mine!",
	upgrade = "Enhancements, huh... I just wish they wouldn't affect my weight...",
	propose = "I once met my final obstacle in the Suez Canal... But if you ever need saving, I will overcome any obstacle to get to you, Commander. This is my promise not just as a warrior, but as your lover.",
	feeling5 = "You are irreplaceable to me. Whatever becomes of me... Scratch that. I'll stay the way I am now, just for you. Because I think this is what made me equally irreplaceable to you. Am I right?",
	main = "Let's see what's on the menu today... Fruits and a vegetable salad. Ideal for a low-calorie diet.|How much do I weigh? Ahem, you'd better drop this topic, or else...! Okay, I'm just exaggerating. But I hope you understand that it's a sensitive topic for me.|A band of Iron Blood submarines ran away before I could as much as say hello. Again... Guess I'll have to come up with a good way of approaching them.",
	touch = "What is it? An invitation to get lunch? Hmm... Sorry, but could you go in my place?",
	voice_key_2 = -1,
	mission_complete = "Now that's the face of an accomplished commander. Good job.",
	battle = "The battlefield... Heh, I'm getting all fired up!",
	id = 207010,
	gift_dislike = "",
	gift_prefer = "Th-thank you... very much...",
	profile = "After having been converted from a battleship into an aircraft carrier, I provided much early experience for the Royal Navy's carrier forces, and my final moments were spent fighting on the battlefield. Though I met a noble warrior's end, I do wish I'd been done in by a cannon or an airstrike, rather than a submarine.",
	voice_key = 20701,
	headtouch = "",
	feeling2 = "People say I'm not great at socializing, a fact that I begrudge. But my social skills aside, I do know my manners.",
	login = "Great to see you! Based upon your punctuality, I can already tell that you're a responsible commander.",
	detail = "There are many Royal Navy ships named \"Eagle,\" and I will go great lengths to maintain its honourable reputation.",
	couple_encourage = {
		{
			{
				20703
			},
			1,
			"Let us fight side by side!",
			0
		},
		{
			{
				90401
			},
			1,
			"Hrmh! Try as you wish, you won't beat me!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[207011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "\"Weight Loss and Health Care Metholody,\" eh... Oh, ahem! Good to see you again, Commander. I-I was just reading medical literature, that's all!",
	unlock = "This may be an exercise, but even so I will give it my all. Right now, I am not just a Royal Navy warrior, but a medical resident as well. If you ever feel ill, come see me, Commander.",
	touch2 = "Umm... Are you feeling lightheaded, Commander? Do you need a thorough examination?",
	mission = "",
	vote = "",
	drop_descrip = "This may be an exercise, but even so I will give it my all. Right now, I am not just a Royal Navy warrior, but a medical resident as well. If you ever feel ill, come see me, Commander.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "I've come up with a new, healthy diet that improves your physical stamina. Care to give it a try?|Treating wounds and saving lives – being a doctor comes with great responsibility, but also great pride.|Are you scared of needles, Commander? I understand. Then as part of this training, we should give you a shot, just so– Oh, okay, maybe we shouldn't.",
	touch = "Let's take your temperature, just to be sure. Mind if I assist with that?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 207011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Debrief me on your symptoms. Oh, that doesn't sound like what a doctor would say? Then how about... Do you feel ill?",
	detail = "I've come well prepared in hopes of learning the ropes of our infirmary.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[207020] = {
	hp_warning = "If only a destroyer would give me a hug!",
	feeling3 = "I thought you were finally going to have me Court Martialed, Commander! I'm grateful to finally be recognized by you. It's nothing to be ashamed of? Commander, I, Ark Royal, will follow you forever!",
	mail = "Do you need to me read out your mail, Commander?",
	expedition = "Commissions have been completed, Commander. If there are any cute destroyers in the fleet, allow me to welcome them back myself.",
	win_mvp = "An enemy who loses their ability to steer will be doomed!",
	home = "Is it time for a break? I'm going to see my destroyer sisters then!",
	unlock = "Ark Royal, reporting in for duty! I am confident in all manners of battle. Why, it was I who managed to destroy Bismarck's rudder!",
	touch2 = "Eh... Commander... please don't... Why are you doing this?!",
	mission = "Commander, it's a soldier's duty to complete missions!",
	vote = "",
	drop_descrip = "Aircraft carrier – Ark Royal, Hull Number 91!",
	feeling4 = "G-good grief... If you were the same size as those destroyers, Commander, I wouldn't be so embarrassed... I was fine with doing this with the little ones... but with you...",
	lose = "Damn, trapped!",
	feeling1 = "You can't compare with the destroyers, Commander...",
	skill = "It's time for you to leave!",
	upgrade = "Oh! oh! oh! Allow me to protect you, my destroyer friends!",
	propose = "I'll take care of all the destroyers from now on! No one can touch Commander or my destroyers. No one!",
	feeling5 = "If I were closer to you, Commander, I could get closer with the destroyers too... Of... of course, that can only happen with your approval. I'm more than happy to help you with destroyer inspections! Is that all right, commander?",
	main = "You look like you're busy, Commander. I won't bother you then. Let me know if you need anything.|Commander, umm... can you tell the destroyers to come to my room? I'd like to give them presents.|This is... So cute! *pat pat* Eh? Wh-when did you get here, Commander?!",
	touch = "Your warm hands keep me energized to keep fighting, Commander!",
	voice_key_2 = -1,
	mission_complete = "Commander, to leave your rewards unclaimed is disrespect to the mission.",
	battle = "Is that it? Hah! Swordfish squadron, prepare for battle!",
	id = 207020,
	gift_dislike = "",
	gift_prefer = "This is...! Your Excellency, how did you even know? Thank you so much!",
	profile = "Ark Royal, reporting in! I'm the first aircraft carrier specifically designed and built for the role in the Royal Navy, I'm proud of being a prototype to all other carriers that followed. \n Little needs to be said about my feats against the Bismarck. Rather I must ask, are there any of those cute little destroyers in our fleet?",
	voice_key = 20702,
	headtouch = "",
	feeling2 = "I... I'm going to say this in advance, but... those destroyer girls... u-um... I mean... I kind of hold them dear... I know how to mind my manners... It's not... it's not a crime!",
