	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 207021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Summer, huh... Commander, do you enjoy the summertime? I know I do.",
	detail = "It is dangerous to let the destroyers play on the beach alone... I suggest setting aside time every day to allow them to frolic together.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[207022] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Ooooooh! Brilliant! Perfect! – Ahem! Erm, well, that's right! This is just your average, everyday record keeping here. I'm not doing anything weird at all! No siree!",
	unlock = "One tends to let her guard down at a party like this, but worry not! Put the ball in my hands and let Ark Royal keep you safe!",
