	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "This camera is strictly for security recording purposes. You never know what might happen. Of course, I could also use it to record some tender moments.|Are you cold, Commander? You can have my jacket.|This party is so noisy, so rowdy. It's my responsibility to take watch over those sweet, innocent, little destroyer girls!",
	touch = "Oh, don't worry about me. While everyone else sinks into the enrapturing atmosphere of the evening, someone has to stay sober and alert.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Time to get rid of some troublemakers!",
	id = 207022,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, status report: all quiet over here.",
	detail = "You need to inspect what's on my camera? Well... let's not worry about it until after the party. I promise I'll hand over every last negative!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[207023] = {
