	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "I'm relieved to see the destroyers are back safe and sound. Wish I could be with them on dangerous missions... Ah, forget I said that. I'm not going anywhere, you hear?",
