	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Oh, you're back. Well, I'm not actually surprised – I saw you coming.",
	detail = "I've been here a few times before. They've never seated me near destroyers due to my reputation... But that's fine. I anticipated as much.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[207025] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Oh, you're back. Came to check on the amusement park, did you? Everything is fine! Maintaining order is a piece of cake!",
	unlock = "Commander! Here to enjoy yourself? Me, I'm working tirelessly on keeping order around the amusement park! ...That sounds fun to you? Alright, then watch how it's done!",
