	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Here's an idea for after work is over – there's going to be a fireworks display at the park tonight. Ahem... Do you care to come with me, Commander?",
	main = "Stay in the queue! Don't cut ahead – it's dangerous! ...How's that, Commander? I don't come off as too bossy, do I?|This height sign is meant to determine whether or not you're eligible to ride – it's not at all an excuse for me to get up close with destroyers! Want to see how you compare?|Why I volunteered for the job of maintaining order? Because my heart beats for law and order! ...I'm a terrible liar, you say? Ahem, well...",
	touch = "My plans after I'm done maintaining order? Hmm... Don't have any yet.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 207025,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "I'll let you touch me now, but do refrain from it when I need to reestablish order!",
	feeling2 = "",
	login = "Do you have any plans today? Got any rides you want to go on? I can introduce you to some fun ones if you want.",
	detail = "",
	couple_encourage = {}
}


