_G.pg.base.ship_skin_words[207041] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Phew, is the battle finally over? As I said, let's go out and have some fun!",
	unlock = "Hum~ dee dum♪~ I'm all dressed up, and my hair is perfect! Commander, I'm ready to go! Don't keep me waiting on a holiday!",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "Hum~ dee dum♪~ I'm all dressed up, and my hair is perfect! Commander, I'm ready to go! Don't keep me waiting on a holiday!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Rest is for the sake of being able to work better! Therefore, set aside that work and come play with me~! |Tirpitz, come and play with me~ I won't do anything to you~! |Stay in tip-top condition so you can work hard and play hard! That's my motto~!",
	touch = "This outfit is surprisingly warm... Even in this kind of weather, I don't feel cold at all!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Since you messed up the day off I was so looking forward to, I'm going to have to punish you!",
	id = 207041,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Way! Too! Slow! Commander, what does your schedule look like today? Hurry up and finish so you can take me shopping!",
	detail = "Do you need advice from the beautiful Victorious? Whether it's fashion tips or relationship trouble, you can ask me anything~!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[207042] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "A beautiful victory — now this is elegance~ Hehe~♪",
	home = "As a celebration of victory, why not decorate your office with this red New Year poster? Isn't it about time for a change in atmosphere?",
	unlock = "Are you preparing to hold an event for the port? Hehe, sounds like you could use my help. Don't worry, with someone as beautiful as me around, anything you do will surely be blessed with success!",
	touch2 = "Y-you put your work down just to do something like this?!",
	mission = "If you have any questions about your mission, you can always ask me. I'll be glad to give you my advice.",
	vote = "",
	drop_descrip = "Are you preparing to hold an event for the port? Hehe, sounds like you could use my help. Don't worry, with someone as beautiful as me around, anything you do will surely be blessed with success!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Having trouble deciding? If I was in your position, I'd just circle everything, then figure out the specifics later.|Unicorn, what kind of outfit would you like for next time? I'll make it for you~|I'll have an eye out for you, so if you need me for anything, just call~",
	touch = "I added a slight twist to my outfit this time. Can you spot what it is~?",
	voice_key_2 = -1,
	mission_complete = "I shall guide you until the rewards are secure in your hands— so, why don't you hurry up and do that?",
	battle = "Let's teach them a harsh lesson!",
	id = 207042,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "♪~ What should we start off with today?",
	detail = "A few words of advice from me: Invitations should be sent early, the venue should be grandiose, the programme should be discussed with everyone, and your attire should be flamboyant — just like mine~♪",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[207043] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "For the souvenirs... Oh! It's our turn to get souvenirs from the commission team.",
	win_mvp = "Elegantly, gracefully, and beautifully – that's how I will beat you up!",
	home = "To celebrate this victory... Oh, I'd better eat my watermelon now! Heehee♪",
	unlock = "*Yaaawn*... Basking in the autumnal night's wind while gazing at the moon is the very definition of elegance, is it not? Heehee. Right now, I am not acting as a Lady of the Royal Navy, but rather as an \"ojou\" of the Sakura Empire elegantly enjoying her tea... Hyeep! Hot?!",
	touch2 = "H-how forthright... *blushes*",
	mission = "Give being selfish a try, Commander. For example, you could decide, \"I'm not doing any missions day!\"",
	vote = "",
	drop_descrip = "*Yaaawn*... Basking in the autumnal night's wind while gazing at the moon is the very definition of elegance, is it not? Heehee. Right now, I am not acting as a Lady of the Royal Navy, but rather as an \"ojou\" of the Sakura Empire elegantly enjoying her tea... Hyeep! Hot?!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "It's nice to for once have someone else tailor my clothes for me... I think I'll read up a little on Sakuran clothing when I return home.|Invite Indomitable to come along next time? It'd be a hard idea to sell, because she feels just wearing a kimono is a chore. Though, maybe she will agree if YOU invite her?|*Yaaawn*... Get me some dangos, Commander♪ I've heard they're a must-eat when you're gazing at the moon.",
	touch = "I'll have another bath when I come back♪ Would you like to join me, Commander?",
	voice_key_2 = -1,
	mission_complete = "So, you completed a mission. I'll let you have this piece as your reward.",
	battle = "This is a bit hard to move in... Though I hardly need to lift a finger to achieve victory.",
	id = 207043,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "*huff puff*... The tea feels warmer than it should be because it's getting chilly outside... Should I just switch to iced tea instead?",
	detail = "A beautiful lady deserves beautiful surroundings. Oh, I'm joking♪ However beautiful the surroundings, I need you to be complete, Commander.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[207050] = {
	hp_warning = "You are all to redouble your efforts!",
	feeling3 = "My big sisters Illustrious and Victorious, like so many other ships you've gathered here, vouch for what a great commander you are. Now come, let this cake be a symbol of our new friendship. Take a bite, won't you?",
	mail = "Commander, I'm leaving the mail right here. Please don't forget to review it.",
	expedition = "Commander, the commission is complete. Shall we go to the harbour and greet the team?",
	win_mvp = "What a magnificent victory! Let us press the advantage.",
	home = "Hmm~♪ Hmm~♪ C-Commander! I am p-pleased that you have returned! ",
	unlock = "Good day, Commander. I am Formidable, third ship of the Illustrious class. Pleased to make your acquaintance. ",
	touch2 = "Commander, is this the appropriate way for one to behave?",
	mission = "Commander, please don't forget to review the mission list I prepared for you.",
	vote = "",
	drop_descrip = "Illustrious-class aircraft carrier – Formidable. ",
	feeling4 = "Truthfully, even though I'm a Lady of the Royal Navy, I sometimes want to have a bit of fun too. A side of me that I can't normally show except to people close to me like Illustrious... Doesn't that make you want to get closer with me?",
	lose = "Why you miserab- Ahem! You are truly worthy adversaries, but next time victory will be mine!",
	feeling1 = "I'm afraid I've contracted a disease that gives me a dreadful headache when you're nearby. Would you mind going someplace else?",
	skill = "The curtain falls. ",
	upgrade = "Formidable shall not disappoint.",
	propose = "I, Formidable, hereby dedicate my life to the love of my Commander, through good times and bad, rich times and poor... This is quite long, so I'll omit the rest~ Now then, Commander, it's your turn. I know it's a long vow but you are not to skip a single word ♪",
	feeling5 = "Commander, good day to you ♪ Shall we share another cake today? The maids have prepared a dreadfully sweet treat for us! Hmm...? I decided to let my hair down a bit more for you, Commander. Hehehe, I wonder if you'll find me just as captivating a Formidable as I was before?",
	main = "Commander, if you're not making any progress on your work, why not take a break? I've prepared tea and crumpets.|No harm in taking a rest while the Commander's dist– Heavens! Victorious! G-good day. Do you have some business with the Commander?|On the day of my launch, hmm... What a shame... though I didn't do it on purpose... Well! All water under the bridge now, isn't it?",
	touch = "I must admit, Tirpitz is quite the hard nut to crack.",
	voice_key_2 = -1,
	mission_complete = "Commander, please don't forget to review the list of mission rewards.",
	battle = "Ladies of the Royal Navy have many virtues, but mercy to enemies is not one of them!",
	id = 207050,
	gift_dislike = "",
	gift_prefer = "Thank you for your kindness, Commander.",
	profile = "I am Formidable, third ship of the Illustrious class. I operated in the Mediterranean for a time, crossing swords with a certain Veneto. Thereafter, I found myself all across the Seven Seas. While my service record is not particularly impressive, I feel I made a small contribution to the war effort.",
	voice_key = 20705,
	headtouch = "",
	feeling2 = "Commander, is there something required of me? If you have a moment, why not join me for a cup of tea?",
	login = "Commander, you're uncharacteristically punctual today.",
	detail = "?! ... Ah, I was just doing a bit of tidying up. Please, come right in.",
	couple_encourage = {
		{
			{
				20703
			},
			1,
			"Illustrious, my dear sister, what would you say to a spot of tea after this?",
			0
		},
		{
			{
				20704
			},
			1,
			"Victorious, my dear sister, have I comported myself well today?",
			0
		}
	}
}


