_G.pg.base.ship_skin_words[207053] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Heheh, just call me the perfect student on duty!",
	home = "Oh, welcome back! ...What's this? You brought me lunch? Thank you so much!",
	unlock = "Good afternoon, Commander. Why am I still in class during lunch break? Heheh, as you can see, I'm on duty. Commander, won't you spend some time with me while I prepare for the next class?",
	touch2 = "Eep?! What do you think you're doing?! You really expect me to believe you were just brushing chalk off? At least come up with a real excuse!",
	mission = "",
	vote = "拉票描述",
	drop_descrip = "Good afternoon, Commander. Why am I still in class during lunch break? Heheh, as you can see, I'm on duty. Commander, won't you spend some time with me while I prepare for the next class?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Commander, do you have any plans for lunch period? Me? Not really. Of course, doing nothing is fine. One adorable academy student is right in front of you – isn't that enough to satisfy you?",
	main = "Nnnh... This patch of chalk is beyond my reach. If I stand on a chair... What? You think it can't possibly be that strong? You're making me angry, Commander.|Commander, do you have any plans for lunch? Umm... If you don't, would you like to join me?|Today's class was nothing a royal lady such as myself cannot handle. Umm, though I did struggle to understand some of it...",
	touch = "Oh... Is there chalk residue on my shoulder? No? You just wanted to give me a massage? Th-thank you.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 207053,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Nnngh... Hnnh! Phew... Who made erasing chalk so difficult?! Huh? C-Commander? How long have you been standing there?!",
	detail = "Heheh, I actually like the vibe of a classroom more than I expected. It feels oddly freeing.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[207054] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission team is done. C-Commander, you'll stay with me, won't you...?",
	win_mvp = "",
	home = "Can you please get this cat away from me?! I'm scared I'll hit it with the scissors... Hyaaah?! Don't pull there, please!",
	unlock = "Phew... Finally got the scissors... Wait, C-Commander?! Why are you here already?! Close the door quickly and look away... N-no, actually, come and help me untangle this ribbon!",
	touch2 = "Do you not consider that taking advantage of me, Commander?!",
	mission = "",
	vote = "",
	drop_descrip = "Phew... Finally got the scissors... Wait, C-Commander?! Why are you here already?! Close the door quickly and look away... N-no, actually, come and help me untangle this ribbon!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Let's begin the show. But first... I need you to forget the state you saw me in! ...Huh? You don't want to, because you found it cute? Who taught you to be so corny... If that's how you feel, then I want you to remember how cute you found it forever... But you won't tell a soul, you hear me?!",
	main = "Commander, why are you still standing there? Come sit next to me. Phew, my leg is sore from being in that position for so long... Could you massage it for me?|I rehearsed these songs for you. If you'd like to make a request... Heheh, of course. They're all rock songs!|You want to try my electric guitar? Okay, hold it like this, and put your hand here... Come on, Commander. You're not the one tied up – relax a little.",
	touch = "How did I turn out like this, you ask? Gee, I'd like to know that, myself!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 207054,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "My hair's going to be such a mess... What? It already is?!",
	feeling2 = "",
	login = "Goodness, Commander, how long are you going to stand there?! Hurry and... untangle this thing!",
	detail = "I really just wanted to decorate a little and give you a private concert, and then maybe... Umm, anyway, I didn't expect to end up like this! My plans are in tatters!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[207055] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Your mail? Right here, of course!",
	expedition = "Our commission team is back. Mmm~ This is a good opportunity to stretch our legs...",
	win_mvp = "I dedicate this wonderful victory to you, Commander!",
	home = "Welcome home. I will elegantly take care of the rest for you, okay? Heehee♪",
	unlock = "To both express my eternal love and gratitude to you and celebrate the wonderful days we've spent together, I will be joining in the port's celebration. ...Ahem, Commander? Tell me the next part!",
	touch2 = "Th-this is how our relationship is now, after all...",
	mission = "If you had to choose between me and your missions... y-you WOULD choose me, right?!",
	vote = "",
	drop_descrip = "To both express my eternal love and gratitude to you and celebrate the wonderful days we've spent together, I will be joining in the port's celebration. ...Ahem, Commander? Tell me the next part!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Hmm... Now that I've changed into this dress, I feel a little restless for some reason. If I mess up such an important day for everyone... Oh! I know! It's because there's so much riding on my efforts today... You think I can take it easy? I-if you say so... don't blame me for anything that happens, okay?",
	main = "\"Elegant and gorgeous, like a Royal lady.\" Hehe♪ Commander, you were just taken by the sight of me, weren't you?|Shall we go to the venue together? I'm sure to get tired if I'm left to walk alone in this dress...|(The Commander's been staring for a while... What part of me is so attention-grabbing? My legs? My chest? Hmm...)",
	touch = "Be careful not to stain the dress, please!",
	voice_key_2 = -1,
	mission_complete = "Big Brother, your mission rewards are riiight here, nya♪",
	battle = "Elegantly... and gorgeously!",
	id = 207055,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "C-Commander... I see you're doing your best, too.",
	feeling2 = "",
	login = "Welcome, Commander. Come and celebrate the big day with me. Heehee♪",
	detail = "My love, along with everyone else's, has been put into this dress. It's the most perfect and elegant attire for today! Well, it would be even more perfect if it had some rock-and-roll energy in it...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[207060] = {
	hp_warning = "Sm- smokescreen!",
	feeling3 = "The kids in the sky have been working very hard. Can't they rest with me for a while? ... ... Commander, in times of war, is there no room for warmth?",
	mail = "I'll put the tea here... Mail? Ah, yes! There's new mail for you!",
	expedition = "Commander, after your commissions are complete, you should... uh... hm... collect your rewards!",
	win_mvp = "A glorious triumph!",
	home = "You need to always keep your guard up, Commander.",
