_G.pg.base.ship_skin_words[207090] = {
	hp_warning = "For the sake of love and peace, I must not be scared!",
	feeling3 = "Ah, Commander, wait a second... Here, use my handkerchief... Ehehe, there are some cake crumbs stuck on the corner of your mouth~",
	mail = "Commander, there's mail for you. Umm, where did I put it... Oh, there it is! Here!",
	expedition = "Everyone has come back from their commission. I'll have to hurry to bring the refreshments out to them!",
	win_mvp = "We're one step closer to a world of love and peace.",
	home = "Good job, Commander. Would you like Illustrious to give you a back massage?",
	unlock = "Good day to you, Commander. I am Illustrious of the Royal Navy. We'll spread the holy light of love and peace all across the ocean, right~♪",
	touch2 = "Is this some sort of new game...?",
	mission = "Commander, are you worried about the unfinished missions? Is there anything I can help you with?",
	vote = "",
	drop_descrip = "Illustrious-class aircraft carrier – Illustrious, Hull Number 87. ",
	feeling4 = "I heard that sitting down to talk with someone can help relieve your worries. Commander, if there's anything bothering you, I'd be glad to hear you out.",
	lose = "For the sake of a world of love and peace, next time... you won't get away!",
	feeling1 = "Were my prayers for love and peace not even enough to reach the person closest by my side...?",
	skill = "Holy light, pummel our enemies in the name of love and peace!",
	upgrade = "With this, I'll be able to further spread the light of love and peace...",
	propose = "S-so this is a promise ring... such an important thing, for me...? Ehehe, thank you so much! I may still be immature, but I will work hard to become the person of your dreams. No, I'm sure I'll be able to do it~♪",
	feeling5 = "Commander, you seem to not be feeling well... Are you tired from working too much? Hm... Ah, Commander, here... *pat pat* What a sweet child~ I heard this will help you not be tired... right? Ehehe, don't you feel better already?",
	main = "My planes? They're right here. Ehehe, everyone's so well-behaved. |Commander, I'll be there for you any time you're feeling lonely.|What an even more wonderful world it would be if everyone could understand each other.",
	touch = "Commander's hand is so big... much bigger than mine...",
	voice_key_2 = -1,
	mission_complete = "Mission complete! Thanks to your efforts, we'll be able to further spread the light of love and peace!",
	battle = "Bad guys that disturb the peace will be dealt with, like this!",
	id = 207090,
	gift_dislike = "",
	gift_prefer = "You're always taking such good care of me, Commander~",
	profile = "I am the world's first armoured aircraft carrier, ehehe. One day, I'll do my best for the glory of the Royal Navy!",
	voice_key = 20709,
	headtouch = "",
	feeling2 = "Commander, for the sake of love and peace, you mustn't quarrel with others, all right?",
	login = "Good day, Commander. I helped organize a little bit based upon how you had things before. How does everything look?",
	detail = "Illustrious is steady in her steps!",
