	drop_descrip = "*Sigh*... I thought changing into maid attire would break up the monotony, but just getting into these clothes has tired me out... Oh, Commander? You came at a good time. Shall we slack off together?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "What jobs am I capable of doing? Let's see... Oh, I can warm up the bed for you before you go to sleep?|Now that I think about it, considering how capable you are as a commander, doing a maid's job should hardly be considered work, right? Maybe I'll have you take over the rest of my maid duties... Ahaha, well, it was worth a shot...|I'm sure someone with THIS many maids would live an absolutely blessed lifestyle... Ugh, it's making me jealous the more I think about it...",
	touch = "Are you trying to give me a massage? My shoulders were just starting to feel a bit stiff, so massage away~",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 207121,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Welcome back, Master~♪ All righty, that's all my maid-motivation used up...",
	detail = "Knowing how to brew tea is one of the essentials for the Royal Maids, no? Well, that's something even I can do. Though only once a day, no more than that.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[207122] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "We won. It was mostly thanks to you, Commander, but I'm sure my navigation helped to some extent.",
	home = "Nice work, Commander. Would you like to rest with me in the car? I can...vouch for how comfortable the seats are.",
	unlock = "It's unusual for me to arrive before you, Commander. Will you let me navigate today? Huh? You don't think I'll just sit on the passenger seat and enjoy the view, do you?",
	touch2 = "C-carry on and...I might not be able to keep my focus later...",
	mission = "",
	vote = "",
	drop_descrip = "It's unusual for me to arrive before you, Commander. Will you let me navigate today? Huh? You don't think I'll just sit on the passenger seat and enjoy the view, do you?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "The thought of a drive with you makes me feel so happy and at peace... It's not time for the race yet. Want to take a nap with me? Yeah, I meant right here.",
	main = "The course data? Firmly in my head, of course. Oh, but I need to close my eyes and relax to remember it clearly...|Just standing saps all my energy, and I have to hold this on top of that...? Here, your ice-cold drink. I only drank a little of it.|Could you drive the rest of the course a bit more carefully? All this jumping about is making it hard to rela – I mean, to hold back...",
	touch = "Commander... would you carry me to the car? I don't even have the strength left to open the door...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 207122,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "How kind of you to tidy up my hair...",
	feeling2 = "",
	login = "*Yawn*. The sunlight and wind feel so nice. It's perfect weather for relaxing in the passenger seat... Ahem, for navigating, I mean. Let's get going, Commander.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[207130] = {
	hp_warning = "Don't hit me, don't hit me! Ah...",
	feeling3 = "You want to know if ladies of the Royal Navy get tired? It's not so bad; we only have to constantly mind our manners and carry ourselves with elegance... Ugh, it's a hassle! I just wanna lie on the couch and eat candy—Ahem! F-forget you heard that!",
	mail = "Commander, I brought your mail. I heard that's part of a secretary's job... I-is that right?",
	expedition = "I heard there's tasty milk chocolate in the commission supplies... I-I didn't say anything. How about we go greet the commission team?",
	win_mvp = "Hmph. Do not underestimate Formidable!",
	home = "While you were away, a few of the older girls visited. They all left messages, which I wrote down on this sheet of paper for you... (whispering) The Commander's really suspicious...",
	unlock = "Hmm... Are you the so-called \"Commander\"? You don't look all that scary, but maybe this is what they call camouflage...? Hmm... I dunno... Oh! I'm the third Illustrious-class ship, Formidable. It's... a pleasure to meet you?",
	touch2 = "Just you wait! I'm gonna go tell big sis Illustrious aaall about all the bad things you did!",
	mission = "Missions? Can we eat candy if we finish them all?",
	vote = "",
	drop_descrip = "Illustrious-class aircraft carrier – Formidable.",
	feeling4 = "You're a lot like me, Commander. Every day is so full of things you must do, you're only able to do what you want to do in private. Even grown-ups have it rough... But it's okay! I will do whatever I can to help you! Not that I know exactly what that entails...",
	lose = "Th-the Commander's gonna lecture me... Urk...",
	feeling1 = "I-I'm sorry! I-I'll listen better from now on, so don't get mad at me...",
	skill = "Evildoers, begone at once!",
	upgrade = "Wooow. You can use airplanes for this, too?",
	propose = "People tell me that you only give these to those you really care about... Does that mean I'm your best friend, too? Ehehe, I'm overjoyed! I'd better go tell big sis Illustrious about this!",
	feeling5 = "I always thought you were a strict and scary person, so I acted cold to you... N-now I know that you're a good person and fun to be around! Commander, you're my best friend! Ehehe!",
	main = "I'm about to go to a tea party with the others... Commander, do you have a mirror? I want to make sure I'm looking sharp... No, you don't need to help me! I can do it myself.|Little Bel, how much longer are you going to be? \"It's only been three minutes\"? You mean you've ALREADY taken three minutes!|One of my Royal Maid sisters told me I'd turn \"plump\" if I ate too much cake. Does she think I believe these childish lies? ...C-Commander, that is a lie, right?!",
	touch = "I-it is rude to touch a lady without her permission!",
	voice_key_2 = -1,
	mission_complete = "Commander, the missions are all done now, so you should take a break. ...You're too busy? It must be hard being grown-up...",
	battle = "Evildoers! I'm not scared of you!",
	id = 207130,
	gift_dislike = "",
	gift_prefer = "Woah, I've always wanted this! ...Ahem, I mean, umm... th-thank you very much!",
	profile = "Illustrious-class aircraft carrier number three, with a promising future of becoming an armoured carrier. Commander, I humbly request your aid in training me to become a proper lady... Huh? What kind of sweets do I like? Why are you asking me... I like all kinds of sweets!",
	voice_key = 20713,
	headtouch = "Hawawah! D-do not rustle the hair of a proper lady!",
	feeling2 = "Do you need something? Ladies of the Royal Navy are quite busy, I'll have you know—You say there's a party full of sweets? And we don't have to be all stuffy and formal? AND big sis Illustrious said I can go? Hmmm... O-okay, I'll go! I'll go!",
	login = "W-welcome back... I suppose I should start my etiquette training now, right? For example, practicing how I stand and sit...",
	detail = "I hear that you're an evil taskmaster who punishes shipgirls when they don't do exactly as they're told... Hwah? That's not true? I dunno, you're kinda suspicious...",
	couple_encourage = {
		{
			{
				20703,
				20704,
				20709
			},
			1,
			" F-for love and peace!",
			0
		},
		{
			{
				20712
			},
			1,
			" Hm? Umm... Are you okay? It looks like you're asleep...",
			0
		}
	}
}


_G.pg.base.ship_skin_words[207140] = {
	hp_warning = "Wha...?! Well, that's one way to play!",
	feeling3 = "Wow, you're really comparing my performances to Illustrious's? You've got some nerve! ...So? Obviously, I'm the winner... Ahem. I didn't say anything!",
	mail = "There's fan mail for you here, too, Commander. Don't forget to read it.",
	expedition = "Ding dong, ding dong♪ The commission rewards have arrived. The equipment for our show came, too, so why don't we go look together?",
	win_mvp = "Heheh, a perfect performance! I think our group has made our feelings clear now.",
	home = "The intermission is over... Commander, I look forward to your support and your cheers!",
	unlock = "Commander, third ship and idol of the Illustrious class, Formidable, humbly makes your acquaintance. Please do enjoy the show... Heehee, doesn't that just make you shudder with excitement?",
	touch2 = "Commander, don't think you can get away with calling this a joke. Heheh, I won't let you explain it away.",
	mission = "Here is today's mission list... No matter how busy you are, don't neglect those missions.",
	vote = "拉票描述",
	drop_descrip = "Commander, third ship and idol of the Illustrious class, Formidable, humbly makes your acquaintance. Please do enjoy the show... Heehee, doesn't that just make you shudder with excitement?",
	feeling4 = "Hmm? Why did I decide to join in the Muse System tests? Because I want to be true to myself. I don't need to act like a royal lady, I can play the music I like, and I get your attention... Heheh, doesn't it sound like a nice deal?",
	lose = "We didn't rehearse well enough... Th-the next performance will be a perfect one, I swear!",
	feeling1 = "You think I looked despondent during my show? I can only imagine it's because of a certain someone who OBVIOUSLY doesn't get me... Eep?! You're getting too close! D-dummy! Okay, I forgive you! I forgive you!",
	skill = "Time for my encore!",
	upgrade = "Now that's satisfying! Heheh♪",
	propose = "This is... more support than I'd expect from just one fan. Is this how you feel when you see me on stage, Commander? Okay... I understand exactly what you're trying to say! I'll give you the most unique show you've ever seen to show you how I feel in return!",
	feeling5 = "Welcome, Commander. Are you here to watch my lessons again? Wait, is this... my promotional poster? Wow, I didn't think you enjoyed my shows THAT much! Of course! I'd be happy to show you my cutest side in return!",
	main = "What song will I choose? This one, of course! Feast your ears upon Formidable's own style of rock-and-roll! Don't you love that dynamic sound, Commander?|Right this way, Commander... Why, you ask? Because I want you to get closer to me, of course!|Illustrious's show was just breathtaking... Oh! I can't let her go uncontested! You'd best be an impartial judge, Commander!",
	touch = "Hmm? Do you want to be my number-one fan, Commander? Yeah! That must be it!",
	voice_key_2 = -1,
	mission_complete = "Heh heh heh... Which is more important? My performance, or a fat stack of mission rewards? Knowing you, I bet you'd place equal value on them.",
	battle = "Witness how a lady rocks and rolls!",
	id = 207140,
	gift_dislike = "",
	gift_prefer = "Th-this is... Commander, I've received your feelings, loud and clear!",
	profile = "I, Formidable, shall bring my elegance as a Royal lady to the stage as a member of the idol group, Alizarin! From now on, I will do my best to express my unique style, so please look forward to my performance!",
	voice_key = 20714,
	headtouch = "I-I'll have you know I am working as an idol right now! Aah! Put that hand back! No pulling!",
	feeling2 = "Commander? You're here early. Heehee, did you decide to come to rehearsal because you were just sooo excited to see my performance?",
	login = "Hm? Commander, you're early. In that case... Maybe now is the perfect time to give you a taste of my solo performance♪",
	detail = "Heheh♪ Commander, what do you think of my – huh? V-very cool? Ahem! At least let me finish asking first... *blush*",
	couple_encourage = {
		{
			{
				20711
			},
			1,
			" Illustrious, I'm taking center stage today!",
			0
		},
		{
			{
				40315
			},
			1,
			" You won't outdo me today!",
			0
		},
		{
			{
				30224
			},
			1,
			" Let's liven up this show even more!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[213010] = {
	hp_warning = "The darkness is with us.",
	feeling3 = "Whenever I'm afraid, all I have to do is think of my little sister. It gives me the strength to push on. Even though my sister can't be without me, I can't be without her either.",
	mail = "Letters are what connect humans. Hold them dear.",
	expedition = "I'm not particularly interested in embarking on commissions... The other girls always say I see weird stuff. I suppose it can't be helped... Anyway, your girls are back!",
	win_mvp = "Allow me to harvest the souls of our enemies.",
	home = "The silence after a battle is divine. Take your time and rest.",
	unlock = "Commander, is that you? I'm Erebus. I followed your voice and have come from afar.",
	touch2 = "... ... uh... ... I'm sorry, it seems like I was having an out-of-body experience.",
	mission = "You'll experience an eternity of restlessness if you die with incomplete missions.",
	vote = "",
	drop_descrip = "Erebus-class monitor – Erebus, Hull Number I02!",
	feeling4 = "I'm afraid no longer. Being next to you, I'm willing to become the darkness to your light; And if that light were to swallow me... No, even if I was to be devoured, that would be fine too.",
	lose = "Even if you manage to defeat me, you'll never escape the infinite darkness.",
	feeling1 = "Commander, if you fall into darkness, know that it will be me hunting your soul...",
	skill = "Want a taste of death?",
	upgrade = "The purer the darkness, the calmer my mind.",
	propose = "Shadows chase after light, and light embraces the shadows. I've heard of foolish lovers who erase each other, but who can judge another's love? Isn't that right, Commander?",
	feeling5 = "Where there's light, there's darkness. Wherever you are, I'll be near. This isn't fate but the law of this world... It's nothing, it's just something that I've wanted to say for a long time, if I ever found someone who I truly liked.",
	main = "Did you just have an out-of-body experience?|I'll always protect my little sisters.|I have to say, this warmth, I don't dislike it.",
	touch = "Allow me to channel forth the whispers of the dead...",
	voice_key_2 = -1,
	mission_complete = "Rewards are but worldly possessions. It makes no difference to me whether you collect them or not.",
	battle = "Please remain calm. The darkness will only make the stars shine brighter.",
	id = 213010,
	gift_dislike = "",
	gift_prefer = "Thanks. Never thought I'd get something like this.",
	profile = "Erebus, my name, sounds surreal?\nMy predecessor was a ship which carried explorers to the North Pole and never returned... like a journey into the abyss.\nPlease pay more attention to my sisters!",
	voice_key = 21301,
	headtouch = "",
	feeling2 = "It was hard to take care of my sister at the beginning, but I got used to it... used to being alone? I'm just used to the fear of it.",
	login = "Commander, I'm always here, awaiting for your summons...",
	detail = "I am not the harbinger of death... I am just..... guiding them after their times are up",
	couple_encourage = {
		{
			{
				21302
			},
			1,
			"Terror, stay close to me.",
			0
		},
		{
			{
				20123
			},
			1,
			"Vampire, please imbibe wine – I mean, blood – with moderation...",
			0
		},
		{
			{
				20502
			},
			1,
			"Lady Warspite, I shall support you.",
			0
		},
		{
			{
				10
			},
			5,
			"Saru Legion? What a fun name!",
			4
		}
	}
}


