	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "I can hear the wailing of souls passing through the ever darkness... You want to know what they're saying...?",
	unlock = "\"I am the witch of Hallow's Eve, here to guide your soul into the ever darkness\"... that's what the concept of the Halloween witch is about, right?",
	touch2 = "Commander, have you been possessed by a perverted ghost?",
	mission = "",
