_G.pg.base.ship_skin_words[213043] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Tee hee! There's no criminal who can escape ME!",
	home = "Welcome back, Commander! The shooting starts in a minute! But first, tell me about all the cool stuff you saw today!",
	unlock = "Found you! No criminals are escaping on my watch! You have the right to remain silent! Everything you say can and will be used against you in a court of law! Tee hee, now surrender peacefully, Commander!",
	touch2 = "Whuaah! Wait, what are you doing?! We're still filming!",
	mission = "Oh? A new mission? Did an inmate escape? Got it! Mark I Search Team, find them!",
	vote = "拉票描述",
	drop_descrip = "Found you! No criminals are escaping on my watch! You have the right to remain silent! Everything you say can and will be used against you in a court of law! Tee hee, now surrender peacefully, Commander!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "La-la-la, I can't hear you!",
	upgrade = "",
	propose = "",
	feeling5 = "Let's cuff you up! Tee hee, you're not going anywhere! Now you're a prisoner to me and me alone! I get to choose which ward you're going to. We'll never be apart again!",
	main = "Commander, have a gander at this! My Mark I got an original makeover! Isn't that lovely? This will surely be handy for the upcoming shoot when... Dangerous? Not at all! It's not loaded, see?|Let's play a game of naval cat and mouse! You'll run away while we try to catch you. By the way, what do you think happens to the mouse when the cat catches it? ...How's that? Pretty strong acting, right?|Escapees always end up cornered! Inmate 001, give up and surrender peacefully!",
	touch = "Hm? You can bribe me with candy, but I'm still going to arrest you!",
	voice_key_2 = -1,
	mission_complete = "We caught the escaped inmate! Mission complete!",
	battle = "",
	id = 213043,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "How bold, patting the warden's head like this! I do like it... but I'm still arresting you! Tee hee! Don't give me lip about how it's \"cowardly\"!",
	feeling2 = "",
	login = "Tee hee! You willingly went back into your cell? Looks like life on the outside wasn't what it used to be!",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[231210] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Commander, the girls who went on commission are back! Let's take them to the party with us!",
	win_mvp = "",
	home = "Good work today, Commander! Let's take a little break before we go back to the party. I'll bring you a snack... I mean, hors d'oeuvres!",
	unlock = "Tadah! I've got a banquet dress! Heehee~ I decided to go with something refined and voguish this time, as opposed to cute! I mean, it's a dress fit for a banquet, so I think it makes me look pretty grown-up.",
	touch2 = "C-Commander, we're at a party! Be a little more refined...!",
	mission = "",
