	feeling4 = "",
	lose = "Ack... Maybe I'm not ready for this dress after all...?",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Let's see, the dance moves here... Left, right, and then... Huh? Is it left next, or was it right...? Whoa, whoa...?!|Commander, umm, let's review a little more before the performance! Otherwise, I'm gonna step on your feet during the dance...|C-Commander, I know I'm cute—I mean, pretty—in this dress, but it's embarrassing when you stare so much...",
	touch = "Are you tired already, Commander? But we're about to dance...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 231210,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Whoa whoa! No rustling my hair! You're gonna mess it up!",
	feeling2 = "",
	login = "Welcome back, Commander! Are you ready to dance with me?",
	detail = "Huh? You think I'm cute? Aww! I did everything I could to give off a different vibe, so I wanted you to call me gorgeous or fashionable! Th-though I do still appreciate the compliment.",
	couple_encourage = {}
}


