_G.pg.base.ship_skin_words[237030] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Oh, new mail...? Want some tea while you read it?",
	expedition = "Go ahead and greet everyone. I'll have sweets ready and waiting for their return!",
	win_mvp = "",
	home = "You've been working so hard. Today's cake turned out perfect, so would you like a slice? Good! Open up so I can feed you~",
	unlock = "Commander, come and try this cake I made... Oh? Heehee, of course I know. That's the ring that symbolizes our eternal vow. I promise to cherish both you and the ring forever...",
	touch2 = "Heehee, Commander... Was cake not enough to satisfy you?",
	mission = "You have to take both your missions and afternoon tea seriously. I'll be cheering you on, Commander.",
	vote = "",
	drop_descrip = "Commander, come and try this cake I made... Oh? Heehee, of course I know. That's the ring that symbolizes our eternal vow. I promise to cherish both you and the ring forever...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I'll never forget the ring you gave me, nor this special tea party... Heehee, not for as long as I live. Whenever I see this ring, I'll remember today's warmth and love. Let's make so many more beautiful memories together. I'll always be by your side, Commander.",
	main = "See how the ring sparkles in the sun? It's just as bright as your smile, heehee.|Commander, you do love staring at me... Of course, I find your gaze reassuring.|I hope my tea and snacks are to your liking, Commander.",
	touch = "Your hands are always so warm...",
	voice_key_2 = -1,
	mission_complete = "Good job. Just like dessert after tea, don't forget to enjoy your rewards for a job well done.",
	battle = "",
	id = 237030,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Hmm? Want me to feed you again?",
	feeling2 = "",
	login = "Afternoon tea is ready, Commander. Let's enjoy some alone time♪",
	detail = "You came just in time for the cake to finish baking. I didn't even have time to change out of my apron. Heehee, not that I'd mind at all if you... \"accidentally\" saw me in a state of disrobe.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[332210] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Your letters... Ah, be careful not to get them wet.",
	expedition = "Our commission team is back. Er... Should we get out already?",
	win_mvp = "We'll wash away our fatigue in the hot spring later. We're almost done here.",
	home = "Phew. The wind is blowing hard, but I don't feel chilly at all. I guess I won't have to worry about you catching a cold here, heheh.",
	unlock = "Basking in the summer night's air and chatting with someone I love, all under the moonlight... Now this is a nice bath. By the way... did you know you dropped your towel?",
	touch2 = "You want me to take my towel off too so that we're even? G-goodness...",
	mission = "Do you have missions to do? Go take care of them. I'll wait for you here.",
	vote = "",
	drop_descrip = "",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I think you're right – I have gotten more expressive these days. I can even say that I love you with ease... But even in this state of undress, I feel awfully hot. Maybe I've been in the bath too long...",
	main = "If you want your towel back, then tell me you love me ten times! ...Sakawa would say something like that. She's a little bit of a tease.|It's not that I'm being straightforward because we're alone – I just think it's hard to cover up my feelings when I'm so physically exposed. Gotta let it all hang out in the bath... right?|If you like hot spring baths, then how about we go on a hot spring tour some time? The Sakura Empire would be good for it... I think visiting all of the world's famous hot springs would also make for a great vacation.",
	touch = "That's enough mischief from you. Heheh.",
	voice_key_2 = -1,
	mission_complete = "Mission completed. Don't you think it's weird that I'm the one telling you this?",
	battle = "",
	id = 332210,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, there's no need to force yourself. Staying in a hot bath for too long can be bad for you. Me? No, I'm fine... Probably...",
	detail = "You feel embarrassed? That's okay... I've embarrassed myself in front of you countless times... No, it's nothing.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301010] = {
	hp_warning = "Looks like this isn’t the time to joke around...",
	feeling3 = "Not sure how my sisters are faring… Although, since they are my sisters, I’m sure they’re prospering wherever they are!",
	mail = "Here’s some mail~ ah… So it’s for the Commander...",
	expedition = "Hey~ The Commission fleet is back, stop sleeping!",
	win_mvp = "Uh-huh, I’m good right~",
	home = "First, you do this, then this....?! C-Commander, welcome back~ Hahaha, I wasn’t up to anything!",
	unlock = "Yoohoo~ yours truly {namecode:2} class has arrived, so you’re the Commander? I'm looking forward to your guidance~",
	touch2 = "Wow! You scared me to death!",
	mission = "Commander, there are so many uncleared missions—— ahhh~!!! Were you being lazy again?",
	vote = "",
	drop_descrip = "Special type I {namecode:2} Destroyer Class— {namecode:2}",
	feeling4 = "What type of girls do you like, Commander? Hmm? I’m just curious. Ha~ perhaps you’ve misunderstood me?",
	lose = "That hurts so much… Commander, let’s run away!",
	feeling1 = "I thought the Commander would understand me...",
	skill = "Hmph, taste the power of the Special type Destroyers!",
	upgrade = "Wow?! Excellent condition!",
	propose = "Even though I said that the Commander would like me “in the future”, but it seems that “future” has become unexpectedly sooner~ Were you a bit shy when I asked you?~ Hehehe.",
	feeling5 = "I was implying something before? Regardless, no matter what type of girls you like, as long as you will like me in the future, then that’ll be just fine~ Hehehe.",
	main = "The weather today sure is beautiful, don’t you think, Commander? |Listen up {namecode:14}, even if the Commander is a total loser, but I am totally (probably) reliable! |Even if the Commander praises 100 times, that still won’t be too much... hmm, or perhaps 100 praises will be a bit tiresome to listen to.",
	touch = "Help with work? O right… Looking at the Commander being so idle, I almost forgot about work~",
	voice_key_2 = -1,
	mission_complete = "Commander, the mission rewards are here~ With me being here, perhaps there are more rewards now? Hehe.",
	battle = "Good weather, even better mood~ Let’s go!",
	id = 301010,
	gift_dislike = "",
	gift_prefer = "Thanks, Commander! It's my lucky day!",
	profile = "Yoohoo~ I am the destroyer who recently made the world tremble, call me {namecode:2}! Sorry, I’m not trying to be complacent, in fact, I was in many battles… although none of them are worth writing home about… I will continue to do better!",
	voice_key = 30101,
	headtouch = "",
	feeling2 = "What’s in my hands? I think it’s called “Gohei” or something like that. It looks so pretty when swung back and forth, so I thought to grab it with me~",
	login = "Commander, how are ya feeling today?~",
	detail = "Hehe, are you that lonely Commander?~",
	couple_encourage = {
		{
			{
				30105
			},
			1,
			"Let’s give the enemy a taste of our might!",
			0
		}
	}
}


