_G.pg.base.ship_skin_words[301013] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Tooooot! The commission team has come back, Commander! ... No surprise: this tuba's reminding potential is totally next-level♪",
	win_mvp = "Okay, let's play a victory march to celebrate... H-hey! Wait for meeee!",
	home = "Did my pre-sortie motivational song serve you well, Commander?",
