	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 301014,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Let's begin today's performance! 3, 2, 1, Start!",
	detail = "I bear the hopes and expectations of all the Special-type destroyers. I can't afford to be anything less than perfect!",
	couple_encourage = {}
}


