_G.pg.base.ship_skin_words[301016] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome back! First thing's first – help, please? We can hang up the lanterns after that.",
	unlock = "C-Commander?! Aw, shoot... I, uh, can't explain this in just one sentence... Please, just help me!",
	touch2 = "Not there, Commander!",
	mission = "New missions? Hey, wait! I'll help you, just untie me first!",
	vote = "",
	drop_descrip = "C-Commander?! Aw, shoot... I, uh, can't explain this in just one sentence... Please, just help me!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Ugh, I'm supposed to set an example for my class and impress you, yet here I am, hopelessly tangled up... Huh? It's fine in the end because you got to see quite the sight? Uhh... It feels like you're poking fun at me here...",
	main = "I heard you'd be attending the mid-autumn festival, so I thought I'd get better at hanging up lanterns... Ahahaha... It's sooo hard!|I was gonna hang this one there, and then that one over there, but then I got caught up in the wires and fell over!|Commander! I know what you're thinking – you're gonna bully me now, aren't you? I've told you I'm super ticklish...",
	touch = "This is just, uh... an accident, that's all!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 301016,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Weeehhh... Is this your way of cheering me up?",
	feeling2 = "",
	login = "Ahahaha... I can't exactly greet you when I'm tangled up like this.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301020] = {
	hp_warning = "This doesn't look promising...",
	feeling3 = "I don't like crowds. All the noise they make gives me headaches... I much prefer quiet places.",
