	headtouch = "Nnh... Don't pet my ears so much, or I'll get sleepy...",
	feeling2 = "",
	login = "H-hi, Commander... Are you sure we should be going on a date right now? Your work... Oh, you finished it? Th-thank goodness!",
	detail = "Oh, Commander, kitties are gathering around... Do you think they're hungry? Hmm... Wait a second, okay? I can share just a little bit of my crepe...",
	couple_encourage = {}
}


