_G.pg.base.ship_skin_words[301057] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Victory pose. Yeah.",
	home = "If I imagine performances to be like battles, and think of the audience as enemies... Err, wait, that's not going to work.",
