	home = "To one day find Hibiki – that is the reason I set out upon this journey!",
	unlock = "Is this the place called the Northern Parliament?! It is colder than I thought... Th-thank goodness I brought gear for extreme environments! Hibiki, please wait a bit longer! Your sister is coming to see you!",
	touch2 = "Oooh, I feel myself warming up! I don't know why, though... Something about it feels strange.",
	mission = "",
	vote = "",
	drop_descrip = "Is this the place called the Northern Parliament?! It is colder than I thought... Th-thank goodness I brought gear for extreme environments! Hibiki, please wait a bit longer! Your sister is coming to see you!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "I've still not found Hibiki... I really do wonder when we'll meet again.|It is thanks to my compass that I have arrived at the Northern Parliament! Huh? How long has the needle been frozen in place?!|I'm curious as to how Ikazuchi and Inazuma are faring...",
	touch = "Would you care to harken to one of my tales of valor?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 301091,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Being fully prepared is the key to going in the right direction! Say that again? The East lies *that* way?",
	detail = "I made friends of these bears on my journey! I suggest you try befriend them too, Commander... Er, forsooth!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301092] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "My bond with my companion has grown even deeper!",
	unlock = "What do you think, Commander? I have a brand new outfit and a brand new companion! I am no longer a plain old ninja... I am now a motoninja!",
