_G.pg.base.ship_skin_words[301093] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission team has returned! Speaking of... Where did my presents for them go?",
	win_mvp = "",
	home = "I could've sworn we met here just a minute ago... Wait, a-am I going in circles?!",
	unlock = "Look out! Move, Commander! ...Phew. To explain, I am helping Santa give out Christmas presents! Now excuse me, I cannot tarry here or I'll be late... Wait, have I come to the wrong place? WHAT?!",
	touch2 = "C-careful, lest the rope come loose!",
	mission = "The sp-spirits of Christmas roam the port at night? C-C-C-Commander! It takes more than that to perturb me, I'll have you know!",
	vote = "",
	drop_descrip = "Look out! Move, Commander! ...Phew. To explain, I am helping Santa give out Christmas presents! Now excuse me, I cannot tarry here or I'll be late... Wait, have I come to the wrong place? WHAT?!",
	feeling4 = "",
	lose = "I m-must maintain my posture...!",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "I'm well acquainted with how to use a grappling hook! ...What? Oh no! The presents!|Hmgh! Oh goodness... That's a long way down. C-Commander, how did we end up ascending so high?!|Hibiki will deliver the remaining presents? Phew, that's good to know...",
	touch = "Umm, C-Commander... You will stop my fall, won't you?!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "No ambushes! Let us fight face to face!",
	id = 301093,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "These presents must all be delivered before the end of today... Commander, we should depart at once!",
	detail = "This obstacle will be child's play if I'm able to leverage my ninja skills... I-I'm going the right way this time, I'm sure of it!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301094] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission team has– Oh no, oh no! ...That was close... Thank you for breaking my fall, Commander...",
	win_mvp = "My ninjutsu is no mere acrobatic act, it's authentic! ...At least I'm fairly sure it is!",
	home = "You've returned, Commander! Let us continue the performance! Hi-yaaah! Behold! Jutsu of Concealment!",
	unlock = "Welcome, Commander, to DesDiv 6's tent of entertainment! For our first act, I shall perform for you my most stunning ninjutsu! ...\"Circus\"? I've never heard of this word before!",
	touch2 = "H-hands off!",
	mission = "A mission, you say? It shall serve as a fine side act!",
	vote = "",
	drop_descrip = "Welcome, Commander, to DesDiv 6's tent of entertainment! For our first act, I shall perform for you my most stunning ninjutsu! ...\"Circus\"? I've never heard of this word before!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Ikazuchi, are you all right?! ...Phew... Don't make your sister worry like that!|Behold! Jutsu of Flame Escape! ...*cough cough*! This darned pyrotechnic device is needlessly complicated!|Don't just stand there, Hibiki – come and assist! ...Your anchor really contains a hidden camera?! ...You just made that up? Aghh! Hibikiiii!",
	touch = "Watch and be amazed, Commander!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "I shall dance around our foes!",
	id = 301094,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I see... So it's called a performance, not an exhibition... Be that as it may, the show must go on!",
	detail = "Inazuma's elephant is quite the clever fellow. Heehee, let us see if it can catch this ball!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301100] = {
	hp_warning = "I won't let it end like this!",
	feeling3 = "Akatsuki, you've been pretty gung-ho about getting the 6th DesDiv back together... Well, the name's not that important as long as we're all together. That's what I think anyway~",
	mail = "Mail? Show me as well! Show me!",
	expedition = "Ah, that's right, the commission fleet seems to have returned? Should I go with you to welcome them back?",
	win_mvp = "Heheh~ I'll be taking that gold star~!",
	home = "Good work out there~ Well, having that said, you still have a lot of stuff that needs to be done... Ahaha...",
	unlock = "Nihihi~ We finally meet at last, Commander! The name's Hibiki! Don't you forget it!",
	touch2 = "Ah~! Commander, I bet you did that on purpose just now!",
	mission = "We sure have all sorts of different missions, huh... Don't sweat it though! I'll help you out!",
	vote = "",
	drop_descrip = "Type III Akatsuki-class destroyer number two – Hibiki.",
	feeling4 = "Ah, that reminds me! Commander, have you been taking care of yourself properly? We'd be in serious trouble if you got sick and collapsed or something... Well, even if that happened to you, Hibiki would tenderly nurse you back to health~♪",
	lose = "Awww... Looks like I'll have to go back to port for repairs...",
	feeling1 = "Commander, it seems like the only way to get you to open your eyes is to get a bit rough... *sigh*...",
	skill = "Trust in me! ",
	upgrade = "So this is that \"leveling up\" thing that Ikazuchi mentioned? Nihihi~",
	propose = "I've been waiting so long for this! Ehehe~ I love you, Commander! ...Ah, look at you getting all bashful~ But my turn's not over yet. I love love love you~! Ehehe~",
	feeling5 = "Commander, why don't you tell me your story? I'm really interested! ...Why? No particular reason~ Haven't we exhausted all the other topics already? Ehehe~",
	main = "Verniy...? It has a nostalgic ring to it... |I'm so glad that we can all be together again~♪ |If you don't need me for anything, I'm going to go play with Ikazuchi and Inazuma~",
	touch = "Yo! Did you call me, Commander?",
	voice_key_2 = -1,
	mission_complete = "Missionnnn... complete! ...Hey, Commander, you should get pumped up too!",
