_G.pg.base.ship_skin_words[301120] = {
	hp_warning = "",
	feeling3 = "A shared sorrow is one made half, and shared joy is one made double. So please feel free to talk to me about anything.",
	mail = "You have mailophobia? ... You don't have to be scared, I'm here with you.",
	expedition = "Commander... your \"gasoline\" and \"resources\" have arrived.",
	win_mvp = "... I'M the MVP? ... Is this fleet... doing okay?",
	home = "Welcome back, Commander. Even if you didn't \"acquire new characters\",I will always be here.",
	unlock = "Are you the commander...? You don't seem very reliable... Ah, sorry, my self-introduction. My name is... {namecode:14}.",
	touch2 = "Commander... there's no medicine that can fix you.",
	mission = "If you leave your missions unfinished forever... then you'll end up having to do this bad thing called \"overtime\".",
	vote = "",
	drop_descrip = "Type III {namecode:11}-class destroyer number four - {namecode:11}.",
	feeling4 = "Commander, no matter where you go, I will always be with you. ... However... I don't think I can... leave the boundaries of this screen...",
	lose = "Phew... Commander... you're very good at running away...",
	feeling1 = "Commander, no matter what you may become, I will always be with you.",
	skill = "If only everyone were here with us...",
	upgrade = "Phew... I'm glad that didn't hurt as much as I thought.",
	propose = "Commander... please feel at ease. I would never abandon you. Even if you've had enough and run away, I will always, always be waiting here for you.",
	feeling5 = "Commander, it's terrible for your body eat junk food all the time. How about cooking your own food once in a while? Hm? Don't worry, I'll taste test it together with you!",
	main = "Commander, your biggest flaw is how kind you are.|{namecode:40}... she's helped me quite a lot...|\"Salvaging\" is my specialty!",
	touch = "Commander... could you pat my head?",
	voice_key_2 = -1,
	mission_complete = "This month's bonus pay won't be postponed into the next month.",
	battle = "Hm... Huh?! We've been ambushed!",
	id = 301120,
	gift_dislike = "",
	gift_prefer = "Nice one, Commander! 50 DKP plus!",
	profile = "I am... the Sakura Empire's {namecode:11}-class type III destroyer, {namecode:14}. As the youngest of my class, I participated in a lot of battles in the World War. But I prefer escorts, transports, and rescues over combat. ... Commander? Would you like to have your head patted too?",
	voice_key = 30112,
	headtouch = "",
	feeling2 = "Commander, I will assist you.",
	login = "Is that... you, Commander? I can't believe you're logging in at this time of day... shouldn't you be doing something else?",
	detail = "Commander... it seems you're always holed up in your room...",
	couple_encourage = {
		{
			{
				10204
			},
			1,
			"{namecode:12}...? Sorry, I thought you were someone else...",
			0
		},
		{
			{
				30111
			},
			1,
			"Destroyer Division Six... departing!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[301121] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "",
	unlock = "It doesn’t matter if {namecode:14} becomes Mr. Commander's dessert… but if {namecode:14} cannot be found, Mr. Commander will feel so devastated, perhaps he won’t be able to command the fleet… so… please! Please convey {namecode:14}'s heartfelt wish to Mr. Commander——",
	touch2 = "Mr. Commander, have you heard {namecode:14}’s heartfelt words? You’re really amazing Mr. Commander!",
	mission = "",
	vote = "",
	drop_descrip = "It doesn’t matter if {namecode:14} becomes Mr. Commander's dessert… but if {namecode:14} cannot be found, Mr. Commander will feel so devastated, perhaps he won’t be able to command the fleet… so… please! Please convey {namecode:14}'s heartfelt wish to Mr. Commander——",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Are you hungry… Mr. Commander? |Are you trying to find {namecode:14}, Mr. Commander? {namecode:14} is right in front of you. |Mr. Commander, you’re always so gentle...",
	touch = "Mr. Commander, are we starting this… please accept all of {namecode:14}, both the good and the bad—",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 301121,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "...{namecode:14}’s heartfelt wish, has it been communicated? …Mr. Commander...",
	detail = "Mr. Commander, after you swallowed {namecode:14} up... you must be ready to sortie.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301122] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Prioritizing work over Inazuma... Commander, you sure are a workaholic.",
	unlock = "I usually go to festivals with Ikazuchi, but this would be my first time going with you. Hmm? Where should we visit first?",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "I usually go to festivals with Ikazuchi, but this would be my first time going with you. Hmm? Where should we visit first?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Commander, I know I'm super cute and all, but you'll develop social anxiety if you constantly cling to me and ignore everyone else. Since I'm also super responsible, you should go to the festival and enjoy the company of others.",
	main = "Commander, I'd like some taiyaki. Is that okay? |It feels unexpectedly nice to walk around without my shoes... Commander, why don't you try it too? |Commander, you can go check out everyone's yukatas if you'd like. I'll look around by myself first.",
	touch = "Commander, no matter how much you poke me, I won't have any Live2D.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 301122,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I was beginning to think that you forgot about our plans, Commander.",
	detail = "Commander, you didn't just buy these clothes for me because Ikazuchi asked you to, right? It doesn't bother me. Not one bit...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301123] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Whether you are fighting, taking care of commissions, or just checking daily missions, I will always be waiting for you here.",
	unlock = "I'm the fairy of lightning that illuminates the stars in the night sky... So that's what we're going with, huh. Commander, will you accompany me to the party?",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "I'm the fairy of lightning that illuminates the stars in the night sky... So that's what we're going with, huh. Commander, will you accompany me to the party?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Akatsuki said she wanted to join us so we can have a 6th DesDiv get-together at the party, but she seems to have gotten lost on the way... I hope Hibiki is able to find her.|\"The moon is beautiful tonight\" is supposed to be a pretty famous line, right? Eh... How'd you already know about it, Ikazuchi?|Ikazuchi seems to have brought you some strawberries. Judging from your expression, I'm... supposed to bring you blueberries?",
	touch = "Commander, shall I bring you something to eat or drink?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 301123,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, I'm glad you haven't forgotten the promise you made with me and Ikazuchi.",
	detail = "If you combine both of our wings, there might not be much room left on the screen... Why don't you edit it in and see for yourself, Commander?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301124] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "I'm so happy you made it back safe and sound. I've been waiting here for you for so long.",
	unlock = "One, two... Mm. All done, Commander. Yep... I'll be your maid today. I don't know how to do much other than make flower arrangements, but I can stay by your side all day.",
	touch2 = "Commander, you're always in such a hurry... But it's okay this time.",
	mission = "You have new missions. My overtime alarms are practically blaring right now.",
	vote = "拉票描述",
	drop_descrip = "One, two... Mm. All done, Commander. Yep... I'll be your maid today. I don't know how to do much other than make flower arrangements, but I can stay by your side all day.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I'm a maid, so it's normal for me to stick close to the person I serve. ...Yep, you don't have to lift a finger. As long as you rely on me, that's enough.",
	main = "I've been practicing with this incredible tool called PictureShop. It makes my flower arrangements look even better and motivates me to practice more.|A purple rose suits me well. ...If you want to decorate your office with a few, go ahead and take some more.|\"If loving you is a sin, then I'll kill God if I have to!\" ...That was a joke. That's kind of a quote, right? Yeah... Totally.",
	touch = "Do you want to let me try cleaning your ears for you? Okay, lay your head in my lap...",
	voice_key_2 = -1,
	mission_complete = "Mission completed, overtime fee received. Not too bad, right?",
	battle = "",
	id = 301124,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Yep. Your hands... are very warm.",
	feeling2 = "",
	login = "Huh? I'm supposed to be your maid for now, but you got here earlier than me... Uh, is it too late to serve you?",
	detail = "I know I'm supposed to be a maid, but I actually can't do anything but make flower arrangements. But I guess it's fine since all you care about is the outfit, huh...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301130] = {
	hp_warning = "",
	feeling3 = "Huh...? Commander? I realized a while back that I'm always by your side, did you cast some kind of magic on me?",
	mail = "Commander, there's mail!",
	expedition = "Commander, while I was lost just earlier, I ran into some girls who'd just completed a commission...",
	win_mvp = "All ships, open fire! Wa... wait... we've already won?",
	home = "Commander, you didn't get lost out there? Wooow!",
	unlock = "Um, I'm {namecode:15}, the first ship of the {namecode:15}-class... Hello, Commander. My name is {namecode:15}... Huh? I just said that? Hm... I don't know how to get back home, so I guess I'll stay here. I hope I can be of service.",
	touch2 = "Whua... it feels weird when you touch me like that...",
	mission = "We've got a job to do! This time I won't forget!",
	vote = "",
	drop_descrip = "{namecode:15}-class destroyer number one -  {namecode:15}.",
	feeling4 = "*Whimper*... Commander, you're being mean... I thought I'd do something to you in return~ So I'll let you hug me...",
	lose = "Gah... ow ow... what in the world hit me...?",
	feeling1 = "Huh...? I got lost and ended up next to the commander... I'd better run...",
	skill = "Huh? Where are we? Oh no, it's the enemy!",
	upgrade = "Huh... Commander, where are we? My body feels so warm...",
	propose = "Ah! Now I remember what I wanted to say! But... you said it first... even though I wanted to be the first to say it...",
	feeling5 = "Commander, recently whenever I see you I've wanted to tell you something, and I try to catch up to you, but then I forget what I wanted to say... It has to be something important... But what could it be...",
	main = "Commander, did you see my torpedo? ... It went off somewhere suddenly.|Weird... lately I seem to forget what I'm forgetting... What am I gonna do...|*Yawn*... So tired... I hope the commander isn't looking... so I'll sleep for a bit longer...",
	touch = "*Yawn*... I get so tired when people touch me...",
	voice_key_2 = -1,
