_G.pg.base.ship_skin_words[301292] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission team has come back! But as it stands now, we can't meet them!",
	win_mvp = "Hippity hoppity! That's what happens when you underestimate me!",
	home = "Ah, Commander! Heehee~ I stumbled across this delicious tea just earlier! Join me on a break and we'll drink it together!",
	unlock = "Whoa-whoa-whoa! Why'd I end up here again?! Even though I've been running for a whole hour! ...Commander?! Waaaah, I'm so glad to see you! Please, help me get out of heeeeeeere!",
	touch2 = "At least it's not my... No, ears or not, it's embarrassing when you touch me like that!",
	mission = "Laffey could find a way out if she were here... Whoa! Word of a new mission just came in!",
	vote = "",
	drop_descrip = "Whoa-whoa-whoa! Why'd I end up here again?! Even though I've been running for a whole hour! ...Commander?! Waaaah, I'm so glad to see you! Please, help me get out of heeeeeeere!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Whoa! There's cake over there! Heehee... No, Commander! Finding the exit comes first, like I told you before!|If Suruga was here, how would she... Wait, COULD Suruga even find a way out of this place? Because I am completely out of ideas!|There's the exit! Watch, I'm going to make a mad dash for– Owie! Th-this is just a dang mirror!",
	touch = "Mhm! Allow me to show you the right path to your destination!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 301292,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "After much thinking, I've realized that I'm not Alice, but rather the White Rabbit! So isn't it weird that I'm lost in here?",
	detail = "The sheer scale of this set is staggering! I've run around all over the place and still found no sign of the exit... What?! I've been going in circles all this time?!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301293] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome back, Commander! I just got back as well – from a long swim, in my case!",
	unlock = "You can't keep sprinting across the sea forever. Sometimes, you need to rest and recover your strength. Speaking of, you may use my parasol if you like, Commander!",
	touch2 = "Do you think this is acceptable in broad daylight?! Please!",
	mission = "",
	vote = "",
	drop_descrip = "You can't keep sprinting across the sea forever. Sometimes, you need to rest and recover your strength. Speaking of, you may use my parasol if you like, Commander!",
	feeling4 = "",
	lose = "I'm almost more scared of being pursued by sharks than the enemy...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Naganami must surely hate getting her tail wet... One could say the same about my ears, I suppose.|Now, now, Kii, please don't try to pressure Suruga into... Wow! You'll really let me take her place in the beach volleyball tournament?|I don't need sunscreen – I can simply dart in and out of the shade! Fwoosh, fwoosh!",
	touch = "Whatever it is you need, I'm all ears.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "I fight at peak performance even in this swimsuit!",
	id = 301293,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Please sit over here and relax, Commander! I'm going for a quick run around!",
	detail = "Hippity hoppity! Let's go for a swim in the sea! It'll be a boatload of fun, Commander!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301294] = {
	hp_warning = "",
	feeling3 = "",
	mail = "One mooncake, two, three... Wait, a letter? Oh, right, I was supposed to deliver this to you, Commander!",
	expedition = "The commission team has returned! I'll go deliver them a couple of mooncakes! Hippity hoppity!",
	win_mvp = "",
	home = "Welcome back, Commander! Today is a day to celebrate with friends and family, so let us all get together and enjoy ourselves! I will join you, of course!",
	unlock = "Oh no! Commander, look out! ...Phew. That was really close. Apologies for my clear lack of attentiveness! I shouldn't have been in such a rush to deliver all these mooncakes...",
	touch2 = "Whoa! Commander?! Please! This is NOT how you're supposed to act!",
	mission = "",
	vote = "",
	drop_descrip = "Oh no! Commander, look out! ...Phew. That was really close. Apologies for my clear lack of attentiveness! I shouldn't have been in such a rush to deliver all these mooncakes...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Kii! Who's the lady in your company? ...Oh! A friend of Suruga, I see! Say, could I ask you to tell me where she is? I'd like to share my mooncakes with her!|These mooncakes aren't the biggest, but they are quite dense. I've only had one, yet I feel stuffed as a turkey!|Whoa! Nice catch, little manjuus! Better pick these mooncakes up quickly, before... Oh no! Now that manjuu pounding mochi fell over!",
	touch = "Ugh, running too fast can be dangerous after all... *sniffle*",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 301294,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Hippity! This feels like a terribly unlucky day for me! ...Oh no! The mooncakes!",
	detail = "Would you like a mooncake, Commander? This batch was made specifically for the occasion. I can personally vouch for their good taste!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301295] = {
	hp_warning = "",
	feeling3 = "",
	mail = "You have a new letter? Well, I can't move at the moment... I don't know what to do!",
	expedition = "",
	win_mvp = "",
	home = "Are you here to partake in the endurance contest, Commander? Oh, you're just spectating? (Oh gosh, the Commander is staring at me... This makes things embarrassing...)",
	unlock = "So I need only lie down and stay still in order to win? Alright... Then allow me to demonstrate my persistence to you!",
	touch2 = "Eek! Please don't try to sabotage me!",
	mission = "",
	vote = "",
	drop_descrip = "So I need only lie down and stay still in order to win? Alright... Then allow me to demonstrate my persistence to you!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Urgh... I'm itchy... Commander, would you please lend me a hand? ...Yes, that's the spot!|Commander, are you tired? If so, I suggest you rest and... Oh, we'd better put this endurance contest on hold, given the circumstances! Let's rest while we can! Heehee♪|(Hrmh... Patience... You must put up with it! Do like Laffey always does and make yourself comfortable... Now stay like that!)",
	touch = "Commander, is the contest still underway? Ah, wait! I might have forgotten to ask how long the time limit is!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 301295,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Whuaahh?! Not my ears, not now! You'll ruin my stillness!",
	feeling2 = "",
	login = "Urgh... My arms itch... as do my feet... I'll just stretch while nobody's look– C-Commander?! Why, no, I haven't moved! Not a single muscle!",
	detail = "Perhaps I could just sleep until the contest ends... What? You still move unconsciously when you sleep? Oh, then I'd better stay sharp!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301300] = {
	hp_warning = "",
	feeling3 = "My hobbies? 3 rounds of food and sleep and a bit of teasin' you. Hohoho~! That look there is what I wanted to see.",
	mail = "Mail, eh... It ain't an errand from the Union, is it...?",
	expedition = "Guess the commission team's back again all in one piece. Hum hum, splendid!",
	win_mvp = "You see this? This is what years of experience looks like!",
	home = "Look at you, back safe and sound! Reward yourself with a sip of my nutritious drink! Hey now, don't be shy~!",
	unlock = "{namecode:124}, First Destroyer Division ship number one, has arrived. Are you certain you're the commander? Then things are gonna get interesting from now on. *Giggle* Enjoy watching me do my work~",
	touch2 = "Well well, looks like your naughty desires are starting to show themselves. How about an exorcism for ya?",
	mission = "Duties, eh. How's about we go give it a look?",
	vote = "",
	drop_descrip = "{namecode:124}-class destroyer number one – {namecode:124}.",
	feeling4 = "Well, Commander, what type of girl do you fancy~? Me? Maybe someone more refined? ... But is that really true? Right, I've got that on tape now~! Now the question is: who will I play it to~?",
	lose = "Ugh... Should've known I can't keep up like this...",
	feeling1 = "You're more boring than I ever imagined, Commander.",
	skill = "Sorry, ain't got time for one-on-ones.",
	upgrade = "Yup, I'm just oozing with energy~ Hoho~! Now I can go on another rampage~",
	propose = "Commander, it ain't too late to change your mind yet~ Yeah, that's it, take your time thinking about me~ Hm? The door? Oh no, it looks like it's been locked shut~ What will we do~?",
	feeling5 = "Commander... Ya know, I like you~ Oh dear, your face is all red~ So red it's even reached your ears~!",
	main = "Winners are those who hold out 'till the very end!|Hawksbill! That girl couldn't beat me, but she put up a real good fight.|Those Fifth Carrier Division folks... they're pretty nice...",
	touch = "Oh? You need somethin'?",
	voice_key_2 = -1,
	mission_complete = "Hm? Payment for those duties? Right then, take care bringing 'em here!",
	battle = "Watch out for them submarines and torpedoes. Full speed ahead!",
	id = 301300,
	gift_dislike = "",
	gift_prefer = "Oh? You really know your stuff, huh~",
	profile = "I'm {namecode:124}, {namecode:124}-class destroyer number one. I was a part of the First Destroyer Division. My name's got a mighty ring to it, don'tcha think? Hoho~! I fought in numerous battles in the Pacific Islands since the start of the World War, so me being a fleet veteran ain't just for show or me being whimsical. I may not look it, but ASW is my forte. Every time I think about my battle with that wolf pack my blood starts to boil~",
	voice_key = 30130,
	headtouch = "",
	feeling2 = "Commander, only rookies and small-timers judge equipment by how new it is.",
	login = "Aha, you've finally showed up~! Will we be doin' anything interesting today?",
	detail = "Hoho~ What about me's gotten you so interested?",
	couple_encourage = {
		{
			{
				30907
			},
			1,
			"It's time for us to stand together again!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[301309] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Being in the first Destroyer Division and being the first of my class, it's only natural I also get first place!",
	home = "",
