_G.pg.base.ship_skin_words[301320] = {
	hp_warning = "",
	feeling3 = "Comaindeeeer! Let's play together! What should we play? You pick, Comainder!",
	mail = "Comainder, you have mail! If you want it you'll have to give me candy!",
	expedition = "Comainder! The older girls are back! I wonder if they brought me any candy?",
	win_mvp = "We won~!",
	home = "I'll take some candy while the comainder's still... Oh!",
	unlock = "Co... main... der? Are you like my mommy or daddy? Hm? Ah, it's Commander! This my candy, I'm not giving you any!",
	touch2 = "Comainder, that tickles!",
	mission = "Mish... shun? What's that? Is that a candy?",
	vote = "",
	drop_descrip = "{namecode:33}-class destroyer number one – {namecode:33}.",
	feeling4 = "Comainder! Let's play house! You'll be daddy and I'll be mommy!",
	lose = "*Sob*... Comainder...",
	feeling1 = "Where's {namecode:34}... I miss her...",
	skill = "I'll show you how powerful candy is~!",
	upgrade = "Will you give me more candy now? ... You won't?!",
	propose = "Prow... miss? Does that mean we're close friends? Hm... Okay! Comainder, I'll give you some candy! That makes us close friends!",
	feeling5 = "\"Hey! Did you go out to meet that woman again today? ... Are you still trying to hide it from me?! You... you reek of adultery!\" ... Huh? I saw it on TV! ... What does it mean? I dunno!",
	main = "Co... main... der? I can't pronounce that... \"Mommy\" and \"daddy\" are easier to pronounce!|First apple, then mango... next time I'll buy one that tastes like strawberry!|One, two, three, four... I forgot... six... after that comes... eleven! Then nineteen! I did it!",
	touch = "I won't give you my candy, even if you are the comainder!",
	voice_key_2 = -1,
	mission_complete = "Rewards, rewards~! Candy, candy~!",
	battle = "Ah! Those are the meanies who steal people's candy!",
	id = 301320,
	gift_dislike = "",
	gift_prefer = "Yaaay! My favorite candy!",
	profile = "I'm {namecode:33}, I'm in the \"Thirtieth Destroyer Division,\" and I'm the oldest {namecode:33}-class ship! There are newer ships, but I'm strong! I love candy! I hate Stu... Um... I can't pronounce that... Stookuhs? I hate those!",
	voice_key = 30132,
	headtouch = "",
	feeling2 = "Both candies look tasty... I can't choose a single one... Help me pick, Commander!",
	login = "You want some candy too, Comainder? You're not getting any of mine!",
	detail = "Candy is the best snack!",
	couple_encourage = {}
}


