	unlock = "Com... man... der? Hi, I'm {namecode:34}... Uh, umm, uh... I don't taste good, so please don't eat me...",
	touch2 = "Eek...! That feels... a little weird...",
	mission = "Commander... W-we have new missions...",
	vote = "",
