	propose = "I'm {namecode:34}... I'll try my best, even if I'm not strong at all... Because... I love everyone...",
	feeling5 = "Can I stay here forever? If a big bad wolf or planes come here, will you protect me from them, Commander?",
	main = "Being alone with strangers... is so scary...|I wanna play with the other girls in the Thirtieth Destroyer Division...|Commander, I hope I haven't caused you any trouble by staying here...",
	touch = "Eek! Commander... please don't touch me without warning...",
	voice_key_2 = -1,
	mission_complete = "Commander, the rewards... I can't carry them...",
	battle = "Planes... get away from me...!",
	id = 301330,
	gift_dislike = "",
	gift_prefer = "Thanks... I'll treasure this...",
	profile = "I'm {namecode:34} of the {namecode:33}-class. I'm always with {namecode:33}... I hate planes and Wake Island... I just want to be together with everyone...",
	voice_key = 30133,
	headtouch = "",
	feeling2 = "Commander... you won't eat me, right...?",
	login = "Eek! You scared me... I thought a wolf was coming...",
	detail = "I'm jealous of {namecode:33}...",
