_G.pg.base.ship_skin_words[301410] = {
	hp_warning = "",
	feeling3 = "Clothes are so annoying... I hate getting dressed... I just want to eat taiyaki...",
	mail = "Commander, what's this package for? Can I pack up my taiyaki?",
	expedition = "Commander, I'm heading out to welcome back the commission team! They promised they'd buy me some taiyaki!",
	win_mvp = "Isn't it about time for a snack?",
	home = "Ah... Commander, want some too? I've got more.",
	unlock = "Aahh... Hm? Hmm? Co... main... der? I'm Mikazuki. Want some taiyaki? You can have half of mine.",
	touch2 = "Oh, I dropped my taiyaki...",
	mission = "Commander, new missions!",
	vote = "",
	drop_descrip = "Mutsuki-class destroyer number ten – Mikazuki.",
	feeling4 = "Always telling me to wear my clothes... you're just like my mom... But I still like you, Commander. Almost as much as I like taiyaki... Okay, Commander, help me get dressed.",
	lose = "I'm hungry...",
	feeling1 = "Ahh~ *Nom* (Mikazuki doesn't seem to notice you.)",
	skill = "You're not getting any of my taiyaki!",
	upgrade = "I ate... too much taiyaki... I'm stuffed...",
	propose = "A promise...? Does that mean you'll help me get dressed? I don't really get it... I should really do it on my own...? Commander, you're weird... I'm fine with you helping me get dressed, I told you before...",
	feeling5 = "\"Only really close people should help each other get dressed\"? Are we not close, Commander? I love you, Commander. Do you not like me?",
	main = "I'm full... and sleepy... Commander, gimme a hug~|I like taiyaki filled with bean paste even in their tail fins.|Taiyaki looks like a fish... Fish live in the sea! Hm... the sea is on Earth! Earth is in space! Mm... so tasty!",
	touch = "Commander, want some? I don't mind sharing.",
	voice_key_2 = -1,
	mission_complete = "Commander, does the reward include any taiyaki?",
	battle = "That's the enemy... can we eat them?",
	id = 301410,
	gift_dislike = "",
	gift_prefer = "That looks really tasty!",
	profile = "I'm Mikazuki. I've got a lot of little and big sisters. We're all friends. I'm really good at escort and transport missions! Oh, and I love taiyaki! Do you want some too, Commander?",
	voice_key = 30141,
	headtouch = "",
	feeling2 = "Commander, want to eat some taiyaki with me?",
	login = "Commander? Wel~co~me back~! *Nom*... Delicious!",
	detail = "Commander, I still have lots of taiyaki, so I'm fine.",
	couple_encourage = {}
}


