_G.pg.base.ship_skin_words[301470] = {
	hp_warning = "I can... hold on a bit longer...!",
	feeling3 = "Commander, um... would you like to go feed the seagulls with me? ...Yay! Here, let me give you some bread... Uh oh, I'm sorry! It fell...",
	mail = "Commander, I left the new mail on your desk.",
	expedition = "The commission fleet seems to have brought back a lot of rewards. Shall I help you bring them in?",
	win_mvp = "Ehehe... It was only made possible by everyone else's hard work...",
	home = "Commander... Ehehe, to tell the truth, I was really wondering when you would come back...",
	unlock = "I am the revised Shiratsuyu-class destroyer, Umikaze. Commander, I hope I will be able to support you and your fleet to the fullest of my abilities... I d-do hope we'll get along!",
	touch2 = "*sniffle* ...Commander...",
	mission = "Commander, um... Might there be anything I can help with?",
	vote = "",
	drop_descrip = "Shiratsuyu-class destroyer number seven – Umikaze.",
	feeling4 = "Commander, if it's not too much to ask, could you please take my hand? I'd like to try to get used to being touched, so... please don't let go no matter what! I, I'll endure it all!!",
	lose = "Don't worry about me... More importantly, are the others safe...?",
	feeling1 = "Commander, I'm so sorry I wasn't able to help you...",
	skill = "I'll try to be helpful!",
	upgrade = "Thank you for always looking after me...!",
	propose = "Um, it's terribly embarrassing still, but... I finally managed to put the ring on...! Um... Commander... please allow me to stay at your side forever...!",
	feeling5 = "Thanks to your help, I've become a lot better at the touchy-feely stuff... Um, if it's not too much to ask, could you continue to \"practice\" it with me...?",
	main = "Commander, shall I open the window? You'll feel a lot fresher if it's nice and breezy, right?|Please don't interrupt Yamakaze and Kawakaze's work... Um, if you want someone to play with, use me instead...|I wonder if any seagulls will show up if we put some crumbs out by the window... Ehehe...",
	touch = "Um, excuse me...! You're getting... a bit too touchy-feely...",
	voice_key_2 = -1,
	mission_complete = "Mission complete! I'm so glad that I was able to be of help to you, Commander...!",
	battle = "Fair winds, good visibility... Mhm!",
	id = 301470,
	gift_dislike = "",
	gift_prefer = "Huh? I-is it okay for me to accept something so extravagant...?",
	profile = "\"Revised Shiratsuyu-class\"... Yes, my sisters and I were called that. During that war, the four of us formed the 24th DesDiv... My memories from back then weren't all rainbows and sunshine though...",
	voice_key = 30147,
	headtouch = "Eek?! P-please stop that...",
	feeling2 = "I don't mind feeding seagulls, or petting cute little animals... So why can I not handle being touched by the commander... *sigh*...",
	login = "Good morning, Commander. I hope that I was able to adequately prepare today's schedule. Is there anything else I can help you with...?",
	detail = "Commander... Um, I'm afraid I'm not very good with physical contact...",
	couple_encourage = {
		{
			{
				30163
			},
			1,
			" I hope I don't cause you any trouble this time...",
			0
		},
		{
			{
				30213
			},
			1,
			"Thank you for your instruction, Jintsuu!",
			0
		},
		{
			{
				30228,
				30117
			},
			1,
			"L-let's all be careful here, okay?",
			0
		}
	}
}


