	detail = "I may be a ninja and a guard, but I still get bored waiting for visitors all the time... What? You want me to take a nap and let you handle it? Are you being serious right now?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301498] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "The Commander, Lady Nagato, and all my friends depend on me. I cannot afford to lose now.",
	home = "When the fighting ends, I will always be here waiting for you. Put your mind at rest.",
	unlock = "This must be the dream you've awaited so eagerly... Of course, I vowed to be with you until the end of our days. I shall take my rightful place beside you and your ideals. We are... together.",
	touch2 = "It's humiliating to watch the other girls get ahead of me...",
	mission = "You have new missions. Shall we have a casual discourse while you review them?",
	vote = "",
	drop_descrip = "This must be the dream you've awaited so eagerly... Of course, I vowed to be with you to the end of our days. I shall take my rightful place beside you and your wishful thinking. We are... together.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "\"Your dreams will come true if you don't give up on them.\" They will, so let us make them real. I swear it to you upon all my being.",
	main = "The same sword that takes lives can also save them. It is my goal to become that: a sword that protects.|You must not fixate on only either brains or brawn. The ideal leader is both wise and strong. Ahahah, here I am, paraphrasing Naka.|You've got a cheerful gang going with this fleet. And you are a part of it, Commander.",
	touch = "How I feel about secretary work? Work is work, that is all. I will gladly do anything for you.",
	voice_key_2 = -1,
	mission_complete = "Mission rewards are here. Hopefully, they'll have been worth our efforts.",
	battle = "I fight... for the one I love!",
	id = 301498,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "What is it?",
	feeling2 = "",
	login = "Today is another day devoid of change. But nothing needs to change if I can happily remain by your side.",
	detail = "I want you to pay Lady Nagato a visit from time to time. There's little I can do to ease her loneliness, but I believe that you can. Don't you worry, I know you'll still come to see me as well.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301540] = {
	hp_warning = "I-I'm not going to give up!",
	feeling3 = "Ugh... It's so scary at night... Commander, w-when it gets late, could you pretty please lead me to the dorm...?",
	mail = "Your mail has arrived! Let's take a look at it, Commander!",
	expedition = "The commission team just returned to port. Umm... I think we should go check on them...",
	win_mvp = "I-I got... first place? Y-you're... not just joking, right...?",
	home = "Well done on the last sortie, Commander... W-would you like to pet Hoppy? I-it's really comforting to stroke his fluffy fur...",
	unlock = "Yuugumo-class destroyer Kiyonami, r-reporting for duty... And this is my friend, Hoppy... I-it's nice to meet you! ... Ugh...",
	touch2 = "I-I'm not sure why you're doing this... B-but please stop, it tickles, Commander...!",
	mission = "We still have quite a few missions to complete... Commander, can you do it...?",
	vote = "",
	drop_descrip = "Yuugumo-class destroyer number eight – Kiyonami.",
	feeling4 = "I have many more fluffy friends than just Hoppy... Commander, would you like to come visit my House of Fluffs sometime later...?",
	lose = "Ugh... S-stay away...!",
	feeling1 = "Everyone's been saying the Commander is a mean person... Commander, is that really true...?",
	skill = "W-we will do this together, Hoppy!",
	upgrade = "Hoppy and I think we got a little stronger...",
	propose = "Will we really be able to be together forever from now on...? That's great...! N-now, I learned from Yuugure that... the next thing I should do is close my eyes and wait for you to do something, right? O-okay!",
	feeling5 = "I'm not scared of the dark or planes when I'm with you, Commander... W-would you mind if, from now on, I walked ahead of you, rather than behind you...?",
	main = "I feel safe around Yuugure. I enjoy playing and having sleepovers with her. I wish I had more friends like her...|Oh no, a-another air raid?! ... Commander, please don't scare me like that!|I'm always doing my best, trying to catch up to everyone... S-so please, don't ever leave me behind, okay...?",
	touch = "Hoppy is cute, isn't he? Ehehe~ He's always there with me when I go to bed.",
	voice_key_2 = -1,
	mission_complete = "A mission... Yes, it seems a mission has been completed! You're quite the go-getter, Commander...",
	battle = "I-I'm supposed to give orders?! ... Whuah?! C-come on, everyone!",
	id = 301540,
	gift_dislike = "",
	gift_prefer = "Th-thank you very much, Commander! I, umm... how should I even return the favor... Nngh...",
	profile = "I'm Kiyonami, the eighth Yuugumo-class destroyer... I had improved anti-air capabilities, but neither Yuugure nor I could really deal with things in the air... Ugh... If only I'd done a better job back then... B-but even so, I did achieve a couple of things! Wh-what I'm getting at is that I'll do the best job I can...!",
	voice_key = 30154,
	headtouch = "",
	feeling2 = "Why do I like to hide behind you...? Umm, that's because... I feel more comfortable with you leading the way, Commander...",
	login = "Welcome back, Commander... Come on, Hoppy, say hi to the Commander.",
	detail = "Ugh... C-could you please not stare so much...?",
	couple_encourage = {
		{
			{
				30126
			},
			1,
			"Yuugure, d-do you mind if I stay behind you...?",
			0
		}
	}
}


