_G.pg.base.ship_skin_words[301582] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "I'm aware that setting off firecrackers is an important Dragon Empery tradition. That said... This many firecrackers may be excessive.",
	unlock = "Mmh... Happy New Year. I'm working on hooking my friends up with these firecrackers... The bun I'm eating? I received it as a thank-you for my efforts.",
	touch2 = "Perhaps the noise of the firecrackers can dispel your sinful thoughts too?",
	mission = "",
	vote = "",
	drop_descrip = "Mmh... Happy New Year. I'm working on hooking my friends up with these firecrackers... The bun I'm eating? I received it as a thank-you for my efforts.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Yat Sen's dim sum is wonderful. I'm particularly fond of this meat bun she made.|If lighting firecrackers sounds too frightening, would you like to light a firework instead?|Make a fai chun? Sorry, such things are beyond my means. You may wish to ask Hanazuki or Suzutsuki instead.",
	touch = "Don't worry, it's not very heavy. I'm capable of carrying it.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 301582,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Is there anything I can help you with, Commander? You seem busy as ever, even during the Lunar New Year, so...",
	detail = "The noise of the firecrackers is said to repel a monster called the \"Nian.\" As for why this monster only appears during Lunar New Year's, I'm not quite sure...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301590] = {
	hp_warning = "Such a tactical mistake...",
	feeling3 = "{namecode:128} and {namecode:127} are both so whimsical and wandering around. Those girls sure don’t have the temperment of being in the Navy. They still need to lean on me, being their big sister. Such a headache...",
	mail = "You’ve got mail… hmm? You read it, I didn’t really focus on what was written, don’t mind me.",
	expedition = "The commission fleet has returned, did you forget?",
	win_mvp = "We won… naturally, what’s there to gloat about?",
	home = "You’ve worked hard today, please get some rest.",
	unlock = "So it turns out to be you, are you the Commander of the 17th Destroyer fleet from today onwards? You seem so ordinary. I am {namecode:19} class {namecode:142}, show me what you got, Commander.",
	touch2 = "This type of things should not be tolerated, right? In that case, die...",
	mission = "I’ve organized all the missions… say what, you want me to clear them as well?!",
	vote = "",
	drop_descrip = "The 11th Destroyer of {namecode:19} class — {namecode:142}",
	feeling4 = "Actually, even though I don’t care that much and I have confidence in myself, for the sake of asking… do you think I’m independent enough?",
	lose = "Damn, give me… victory. Win or lose, that’s the way of life in the Navy.",
	feeling1 = "Stay away from me, stupidity is contagious.",
	skill = "The time has come!",
	upgrade = "Thank you… my ears are twitching? Impossible, I’m not that happy at all.",
	propose = "Commander, you’ve finally realized my greatness. To be frank… my ears are not twitching. I’m not that happy, shut up, let’s continue the ceremony!",
	feeling5 = "What, I just asked offhandedly, you sure are opinionated… forget it. I’ll still listen to what you got to say. Just you wait, one day I’ll impress you.",
	main = "That {namecode:128} girl, as my little sister she always acts superior to {namecode:127}, even more than I do, darn… | If only we discovered Tusk, then {namecode:70}-sama would not… sigh, forget it, what’s important is the present |Official documents? Let me see… hmm… ahh I see I see...",
	touch = "Don’t poke me unstoppingly, are you a monkey?",
	voice_key_2 = -1,
	mission_complete = "The mission rewards have been confirmed, I’ll leave the labor work of transporting it here to you.",
	battle = "Muahaha, all ships… set sail!",
	id = 301590,
	gift_dislike = "",
	gift_prefer = "Mmhmm. Not bad, not bad. Quite thoughtful of you.",
	profile = "The 17th Destroyer fleet have been together for most of the time, and we participated in all sorts of sorties and operations for almost the entirety of the war. In the end I was with {namecode:70}-sama as we both made our last stand… to the end. So I don’t care about those little things.",
	voice_key = 30159,
	headtouch = "",
	feeling2 = "My fan? Its military issue, not some ordinary fan. It’s used by Admirals, so don’t underestimate me… hehehe. Hmm? I said nothing.",
	login = "So slow, are you like a turtle who’s stumbled onto the battlefield?",
	detail = "O you mean this family emblem? I designed this myself, plus the clothes. I won’t accept any other comments except for “its cute”.",
	couple_encourage = {
		{
			{
				30161,
				30162
			},
			2,
			"17th Destroyer fleet ready to take out the enemy!!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[301591] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Another greeting card for you... Curse you, what a normie.",
	expedition = "",
	win_mvp = "",
	home = "",
	unlock = "Before you raise a fuss about it, let me just tell you this - the concept of \"Christmas\" already existed during the Sengoku period, so there's nothing weird about putting on a Christmas outfit!",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "Before you raise a fuss about it, let me just tell you this - the concept of \"Christmas\" already existed during the Sengoku period, so there's nothing weird about putting on a Christmas outfit!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Look here, Christmas nowadays is a holiday that you celebrate with those who are important to you. You came here knowing that, didn't you? Me? I... don't particularly object...",
	main = "{namecode:143}, stop frolicking around like a little kid, and don't pull on me either! Ugh... what am I going to do with you? |I still have to prepare presents for the three stooges... Jeez, can't they be a bit more considerate towards their big sis normally? Oh well, I suppose that's how it should be. |It's snowing... Hmm? It's not like I particularly want to play in the snow or anything, but if you want to so badly, I suppose I can tag along.",
	touch = "Santa Claus? ... Hmph, I graduated from that fairy tale long ago.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 301591,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Merry Christmas. I suppose I'll let you take it easy today.",
	detail = "You should know that I designed this outfit just by seeing the family crest here. Do you think it looks good?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301592] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "What? Was I wrong? Hm... It's been quite some time since Tanikaze said she'd go receive the commission team... Hope nothing has happened to her...",
	win_mvp = "",
	home = "Do we have any potential new band members? ...What? Nobody has even applied? Grrr... I suppose there's no point in getting mad at you for it, though...",
	unlock = "Ugh... Even though we finally got all our gear, we still need more band members... Commander! Stop complaining and come hither! From now on, you're a member of the Sengoku Shredders!",
	touch2 = "",
	mission = "Being a general is no excuse to skip out on rehears– Ahem! I mean missions.",
	vote = "",
	drop_descrip = "Ugh... Even though we finally got all our gear, we still need more band members... Commander! Stop complaining and come hither! From now on, you're a member of the Sengoku Shredders!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Hamakaze said she won't join because it would \"impact her academic performance\"... Hmph! She doesn't know what she's missing out on!|A band logo? Yes, and we'll use my family crest as the motif, of course!|If you're going to rest, find something durable to sit on... I'm not \"showing concern,\" just giving you instructions!",
	touch = "Go on. Read the score and play the song like I taught you.",
	voice_key_2 = -1,
	mission_complete = "You've brought the missions rewards? Splendid, Isokaze! I'll see to it you receive a castle for your efforts!",
	battle = "Let us do like rock stars do and turn it up to eleven!",
	id = 301592,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Enough dilly-dallying! It's time to get on with today's rehearsal!",
	detail = "Of course they had music during the Sengoku period! ...But they didn't have rock bands? Listen, it's called \"getting with the times.\"",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301600] = {
	hp_warning = "I will never back down!",
	feeling3 = "Western Army, attack! Fire on the Eastern Army! Our next move will be... Oh no! Hideaki was lured away! That's unfair, General! Darn, now I'm... *Sob*...",
	mail = "General, I have a letter for you!",
	expedition = "Our target: the base's docks! We must welcome back the commission team! Giddy-up, General!",
	win_mvp = "Urakaze-sama, can you see my glorious victory?!",
	home = "You make me proud, General! Hey, uh, listen! I have a report for you! You see...",
	unlock = "All units, attaaack! ...Wait a second, where am I?! Oh, I know you! Urakaze-sama said you're... the general! Hmph! I'm Isokaze, the one destined to become a general that will make the whole world tremble in fear!",
	touch2 = "Hahaha, that tickles~!",
	mission = "General! Put me in charge of the mission! I'll finish it you before you can say \"set sail\"!",
	vote = "",
	drop_descrip = "Kagerou-class destroyer number twelve – Isokaze.",
	feeling4 = "General, let's play a game! Huh?! You've got work to do?! You really do? Do you want me to help? Then how about a massage? ...Hooray! I love you, General!",
	lose = "Hamakaze, Hamakaze where are you... You have to save me!",
	feeling1 = "Hmph! I'm done playing with you! Hamakaze, Tanikaze, where are you?",
	skill = "N-nothing can stop me!",
	upgrade = "I am Isokaze, the leader of Destroyer Division 17!",
	propose = "General, if anyone starts being mean to you then tell me. Hamakaze and I will go and get revenge on them for you. We're here for you, because we're all friends!",
	feeling5 = "General, Urakaze-sama seemed angry at me and said I've started being cold to Hamakaze! But I still want to play with you... So come on! Let's go play together with Hamakaze!",
	main = "General! Come play warring states with me! You can be... Ieyasu! I'll be Mitsunari!|Hamakaze! Tanikaze! Let's depart! We're heading for the capital!|Urakaze-sama, my coat has been torn again... Fix it for me!",
	touch = "General, give me a piggyback ride! We must charge into the enemy stronghold!",
	voice_key_2 = -1,
	mission_complete = "General, our mission rewards are here! How much koku did we receive?",
	battle = "I will lead the charge into batt... Hey, stop! Wait for me!",
	id = 301600,
	gift_dislike = "",
	gift_prefer = "Woahhh! Thank you, General!",
	profile = "I am Isokaze of DD17! In the past, you see, I've worked with Hamakaze, Urakaze, Tanikaze... oh, and Yukikaze! My service record stands second to none! And that's why you should put me in charge of your missions!",
	voice_key = 30160,
	headtouch = "",
	feeling2 = "How I know so much? Urakaze-sama taught me everything about the warring states! She's really smart! But Hamakaze is still my best friend in the end! Heheheh~",
	login = "General! It's time to charge into battle!",
	detail = "One banner, one nation!",
	couple_encourage = {
		{
			{
				30161
			},
			1,
			"Hamakaze, follow my lead!",
			0
		}
	}
}


