_G.pg.base.ship_skin_words[301610] = {
	hp_warning = "",
	feeling3 = "I hope one day... Destroyer Division 17 can reunite here...",
	mail = "Reading through these reports should be your top priority.",
	expedition = "Well done... Commissions are hardly a big deal compared to Rat Transports, right?",
	win_mvp = "Heheh! This is nothing spectacular for me!",
	home = "Great job. Did everyone do their job during the sortie?",
	unlock = "Hamakaze, 13th ship of the Kagerou-class destroyers, reporting for duty. Commander, try not to get my name wrong.",
	touch2 = "Eek! ... Commander, just where do you think you're touching?",
	mission = "Our next mission is...",
	vote = "",
	drop_descrip = "Kagerou-class destroyer number thirteen – Hamakaze.",
	feeling4 = "The breeze feels really nice today... But we can't afford to rest yet! Yamato... wait for me...",
	lose = "I have to rescue the survivors...",
	feeling1 = "Stupid meatheaded Commander...",
	skill = "I see an opening!",
	upgrade = "The wind grows stronger.",
	propose = "M-maybe we should wait until it's all over... Th-that said, I'd feel bad if I rejected you now, so I'll have to accept it... Hey, stop laughing!",
	feeling5 = "For as long as the wind blows, I will always be by your side.",
	main = "Tanikaze, until you finish your training, don't expect to get much beauty sleep!|Though I may be but a single destroyer, I'll still do all I can to protect everyone.|Bou-no-misaki... where it all came to an end...|",
	touch = "Hm? What are you looking at, Commander?",
	voice_key_2 = -1,
	mission_complete = "Your grades are going up, Commander.",
	battle = "This wind... is perfect for battle!",
	id = 301610,
	gift_dislike = "",
	gift_prefer = "Th-thanks... I really appreciate it.",
	profile = "I'm Hamakaze, 13th Kagerou-class destroyer. Although I took part in quite a few battles, it feels like I spent more time rescuing friends than sinking foes... And now, I fight once more to protect my friends.",
	voice_key = 30161,
	headtouch = "",
	feeling2 = "Commander, history surely won't repeat itself... right?",
	login = "Now's not the time to lose focus, Commander.",
	detail = "This time too... I swear to protect my friends!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301611] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "That parabola... was beautiful...",
	home = "",
	unlock = "Learning is exciting. The joy of acquiring new knowledge, the sense of achievement from solving difficult problems... you'll understand once you try it. So, shall we study together, Commander?",
	touch2 = "Commander, take your reading more seriously!",
