_G.pg.base.ship_skin_words[301630] = {
	hp_warning = "The situation... seems to not be ideal.",
	feeling3 = "I had another nightmare yesterday. Commander, would you please stay with me tonight? That black abyss, not being able to see anything... I'm scared...",
	mail = "Shall I go through the email for you? Maybe there's a letter from Arashio...",
	expedition = "Isn't it about time to welcome the others back?",
	win_mvp = "It seems that I accidentally did something awesome...",
	home = "There is nothing more reassuring than being here. Commander, don't you think so too?",
	unlock = "I am Asashio. I've come to join this fleet in order to search for my missing comrade. Commander, do you also have someone who you could not give up on?",
	touch2 = "What a weird feeling...",
	mission = "Commander, your missions... Please show some motivation once in a while.",
	vote = "",
	drop_descrip = "Asashio-class destroyer number one – Asashio.",
	feeling4 = "Commander, I'm at ease when I'm with you... But every time I think about Arashio, I get anxious again...",
	lose = "If only I had upgraded my anti-air equipment a bit more...",
	feeling1 = "Arashio... Where are you?",
	skill = "This time... I won't fail again!",
	upgrade = "I think... it'd be better to mount another anti-air gun.",
	propose = "If there's one good thing that's happened to me, it's that I was able to meet you, Commander. Will you stay by my side until I fall asleep? Tonight... and tomorrow... and every night...",
	feeling5 = "Commander, you're somehow always able to put my heart at ease. But recently, I've discovered something else that scares me... Commander, you'll always stay by my side... right?",
	main = "Dampier Strait? I don't really want to think about that place anymore... More importantly, Commander, can you install another anti-air gun? |Happiness is a full belly and a good night's sleep. |*Yawns* ...It's already so late, but Commander is still at it... Please make sure to take care of yourself.",
	touch = "Don't worry, I... am not afraid anymore!",
	voice_key_2 = -1,
	mission_complete = "The mission rewards... can I use them to buy something to eat?",
	battle = "Anti-air preparations... is everything in place?",
	id = 301630,
	gift_dislike = "",
	gift_prefer = "How'd you even know what I like? Commander, could it be... that you're a mind-reader?!",
	profile = "Asashio-class nameship, Asashio. Arashio and I, along with our friends, formed the 8th DesDiv. Though we were disbanded in the end, I strongly believe that we'll be able to be together again one day. Commander... do you want to help me find them?",
	voice_key = 30163,
	headtouch = "",
	feeling2 = "Every time I look out into the horizon, memories of that time come flooding back to me...",
	login = "Welcome back, Commander. If you don't want to set sail right away, why don't you rest first?",
	detail = "I'd like to stay here forever... But at this rate, I won't be able to find Arashio.",
	couple_encourage = {
		{
			{
				30166
			},
			1,
			"This time... let's go home, together.",
			0
		},
		{
			{
				30164
			},
			1,
			"I also like cute girls. Hm? It's not the same?",
			0
		},
		{
			{
				30165
			},
			1,
			" I love to sing as well~",
			0
		}
	}
}


