_G.pg.base.ship_skin_words[301660] = {
	hp_warning = "You must remain calm in the face of danger. Don't worry about me.",
	feeling3 = "Did you have another nightmare? Aww, relax, Commander, everything will be okay.",
	mail = "You've received mail. Shall we go see what it is, Commander?",
	expedition = "Commander, I believe the commission team has returned. Let us head over to receive them.",
	win_mvp = "Why, I'm the MVP...? Hmm, this might not be so bad.",
	home = "Stellar work, Commander. Would you like to rest your head in my lap?",
	unlock = "Destroyer Arashio, here to join your fleet. I'll provide everyone with the support they need~",
	touch2 = "Eeeeek! ... Is this truly necessary to become an adult?",
	mission = "New missions have appeared. I'll gladly help you with them, Commander.",
	vote = "",
	drop_descrip = "Asashio-class destroyer number four – Arashio.",
	feeling4 = "It's gotten quite late... But I really enjoyed chatting with you! Say, don't your shoulders get stiff from sitting down all day? Would you like a massage?",
	lose = "There's no need to worry, we'll win the next time!",
	feeling1 = "Oh, Asashio? There there, there's nothing to be afraid of... You'll have to excuse me, I need to stay with Asashio.",
	skill = "I'll keep everyone out of harm's way.",
	upgrade = "Now it'll be easier for me to avoid getting hurt. Thank you, Commander.",
	propose = "Commander, I won't say anything indecent, but there's one thing I want to tell you... Umm... I'll always be there to support you. Your side is the place where I truly belong.",
	feeling5 = "We're all to ourselves now. My heart's been thumping for some time now... Commander, could we huddle up next to each other, just for a little while?",
	main = "Asashio and I have always been together. Yup, we even sleep in the same bed. She's so quiet when she's sleeping.|We might not always be able to stick together, but we'd never leave anyone behind... That's why this place feels like home to me.|I've made you some tea. Take your time to savor it. By the way, is my tea-making ability to your liking?",
	touch = "Mmh... I try not to think about why we all got separated. Besides, we got to reunite here, so let's instead live our lives happily ever after.",
	voice_key_2 = -1,
	mission_complete = "A mission has been completed. You did a great job, Commander!",
	battle = "Everyone, try to avoid getting hurt if you can...",
	id = 301660,
	gift_dislike = "",
	gift_prefer = "Heehee. You really get me, don't you? I'd be honored to receive such a wonderful present!",
	profile = "I am Arashio, the fourth Asashio-class destroyer. I was part of Destroyer Division 8 along with Ooshio, Michishio, and of course Asashio. Lastly... I hope I can stay with everyone this time around.",
	voice_key = 30166,
	headtouch = "",
	feeling2 = "I'd like to get to know you, Commander. *Giggle*, what should we start with?",
	login = "You don't find my appearance odd? I feel the best way to greet someone is with a smile!",
	detail = "I feel a little sad when I see planes in the air... But it's okay, that's all in the past. What's more important is keeping my chin up and smiling. Right, Commander?",
	couple_encourage = {
		{
			{
				30163,
				30164,
				30165
			},
			2,
			"Destroyer Division 8, let's all stick together now.",
			0
		},
		{
			{
				30163
			},
			1,
			"Asashio, I'm right by your side. Don't be scared.",
			0
		}
	}
}


