_G.pg.base.ship_skin_words[301810] = {
	hp_warning = "Kasumi... is very strong when she gets serious!",
	feeling3 = "Commander, Foo and Kasumi will always stay by yourside, because you're our friend.",
	mail = "It'd be nice if Foo could get the mail...",
	expedition = "\"The commission team has been waiting for Commander for a long, long time.\" ...That's what Foo told me.",
	win_mvp = "Foo, we did it.",
	home = "Foo, Commander's back. Commander, your tea.",
	unlock = "I'm Kasumi. Commander, are you my friend?",
	touch2 = "Commander, Foo is biting you.",
	mission = "Foo told me... that there are still missions left, and that Commander should stop slacking off...",
	vote = "",
	drop_descrip = "Asashio-class destroyer number 10 – Kasumi.",
	feeling4 = "Commander, do you want to watch a movie with Kasumi? Kasumi likes movies with lots of friends that look like Foo... Let's watch one together?",
	lose = "Foo, make sure to... protect the others.",
	feeling1 = "Don't be sad, Commander. Kasumi will be your friend.",
	skill = "Let's do our best, everyone.",
	upgrade = "Foo, is Kasumi any different...?",
	propose = "Commander, you've given me the most precious gift. That's why I'll give it my all to become the person most precious to you. ...Foo, what's the matter? I have to act more lovey-dovey? Um, then... *kiss*... Like that?",
	feeling5 = "Foo will chase away all the bad guys that Commander cannot see. Kasumi will also protect you. We'll always be together...",
	main = "Foo is my good friend. We're always together. |Kasumi... gets tired easily... Commander, your chest is really comfortable. |Foo is always scared around Shiranui... Commander, is there no way to help Foo not be afraid of her will-o'-the-wisps...?",
	touch = "Commander, would you like to talk to Foo?",
	voice_key_2 = -1,
	mission_complete = "\"Mission complete~ Good job, Commander, Kasumi will give you a reward\" ...Foo, what are you saying...",
	battle = "Foo, let's do our best?",
	id = 301810,
	gift_dislike = "",
	gift_prefer = "For me...? Thank you. I like it.",
	profile = "I'm Kasumi, from the Asashio-class. During Operation Rei-go, my friends and I did our best to complete our missions. Without them, I would not have been able to accomplish anything alone.",
	voice_key = 30181,
	headtouch = "",
	feeling2 = "Foo can't handle being around lots of people, so Kasumi also dislikes crowded places...",
	login = "Hello, Commander. Foo, say hi to Commander too, okay?",
	detail = "Kasumi can see lots of things that others can't, like Foo here, for example. Kasumi saw that Foo was all alone, so we became friends.",
	couple_encourage = {
