_G.pg.base.ship_skin_words[301830] = {
	hp_warning = "My friends are still fighting, so I can't afford to go down here!",
	feeling3 = "My tail is warm and fluffy, but Wakaba's is shinier in comparison... Hatsushimo's is slender, and Shimakaze's is tiny... Um, there are all different sorts!",
	mail = "Commander, new mail has arrived. Here, I brought it for you. Maybe someone brought good tidings!",
	expedition = "Commander, everyone in the commission fleet has come home. I'm sure they're all tired, so I'll go give them a warm hug!",
	win_mvp = "I didn't even realize I got MVP... But, this was only possible because of everyone's hard work!",
	home = "Commander, good job in battle! Hurry, come sit over here~ I'm going to give your shoulders a nice rub!",
	unlock = "So this place is the port? Huh... Oh, Commander! I'm the fourth ship of the Yuugumo class, Naganami. It's a pleasure to finally meet you! Um... what's my selling point... Love! I love you, and everyone else as well!",
	touch2 = "C-Commander, it's still work hoursss...",
	mission = "I can probably help out with transport missions, but as for other tasks... By the way, Commander, I see you tackling all sorts of different missions every day! That's really amazing!",
	vote = "",
	drop_descrip = "Yuugumo-class destroyer number four – Naganami.",
	feeling4 = "Oyashio taught me a little trick! If I remember properly, it goes a little like... this! This circle on your forehead is supposed to make you luckier when it comes to your love life, and also helps you become happier!",
	lose = "I'll have to work much harder if I want to become an ideal flagship...",
	feeling1 = "Commander, if there's anything bothering you, please let me know. I'll be waiting for you... as long as it takes...",
	skill = "Try this torpedo strike on for size!",
	upgrade = "The feeling of warmth and safety... this is what it feels like to get stronger... Commander, thank you very much!",
	propose = "Um... Commander, I thought we had grown a lot closer, but this still feels a bit awkward... Wh-what should I do? ...Ah! Commander, try hugging my tail! I'm sure its warmth and fluffiness will help you loosen up! Mhm!",
	feeling5 = "Still not enough good fortune in your life? ...You leave me no other choice then! Even if you have bad luck, there's a way to compensate for it! I just have to pass it to you directly... Mmwah~",
	main = "Jintsuu is always so knowledgeable and reliable... I wish I could be just like her... |Commander, can you let me be flagship next time? I'll work even harder, for the sake of everyone's happiness! |Lately, everyone has been circulating rumors that hugging me or cuddling my tail has healing properties, like coming out of a bath. They're even saying that it can cure colds... There's no way that's true, right?!",
	touch = "I'm more than just a ball of fluff, you know? Look, it's my smile and my ability to bring warmth to others that counts~",
	voice_key_2 = -1,
	mission_complete = "Mission complete! Great work today! Come, come, don't be shy – come rest on this big fluffy pillow!",
	battle = "I'm the flagship? All right, just leave it to me!",
	id = 301830,
	gift_dislike = "",
	gift_prefer = "You're giving something this wonderful to me...? Thank you so much, Commander!",
	profile = "I'm Naganami, fourth ship of the Yuugumo class. During the War, I was primarily involved in transport operations, but I did participate in some large-scale operations and even served as flagship. Any hardship on the battlefield can be overcome as long as you believe in one another... I just know it!",
	voice_key = 30183,
	headtouch = "",
	feeling2 = "Everyone in the Mutsuki class is super fluffy and cute! Being at this port makes me so happy~!",
	login = "Welcome back, Commander! Um, Naganami will always be waiting for you right here! That's because, well... I'm happiest when I'm by your side!",
	detail = "I give off warm and fuzzy vibes? Ehehe, I've heard that from the others as well~ It's a little embarrassing... Nuh uh, I don't mind at all. I'm really glad to hear it!",
	couple_encourage = {
		{
			{
				30149,
				30117,
				30127,
				30180
			},
			2,
			"When we work together, the 2nd Torpedo Squadron will never lose!",
			0
		},
		{
			{
				30213,
				30221
			},
			1,
			"It's an honor to fight at your side!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[301831] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Commander... Um, I mean, Master! Welcome back! Whether you want to enjoy some refreshments, or take a nap on my tail... either way is fine!",
	unlock = "Akashi pushed me into getting this outfit, saying that it would surely make you happy, but... What do you think...?",
	touch2 = "Commander, at least let me set the tray down first! Eek! It's going to fall!",
	mission = "",
	vote = "",
	drop_descrip = "Akashi pushed me into getting this outfit, saying that it would surely make you happy, but... What do you think...?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Commander, your entire body is radiating happiness – I can smell it! Huh? You want to try smelling my happiness? Um, in that case, come a bit closer... Even closer...",
	main = "This is the first time I've made sweets by hand. Commander, how are they? You'd like to have some more? Of course! I'll make them for you right away! |Let's emulate the Royal Maids and form the Maids of the 2nd Torpedo Squadron! What do you think, commander? |\"Just spotting Naganami immediately causes one's mood to improve?\" ...More weird rumors are circulating again... But if you believe that, Commander... Hehehe, I guess I'll believe it too!",
	touch = "Being able to go about business as usual in this kind of outfit is no easy feat... Real maids are truly something...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 301831,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I'll do my best to bring happiness to everyone at port, Commander! Just believe that one day, this place will be filled with happiness!",
	detail = "I want to be a maid who can bring happiness to everyone! ...I'm going to have to work even harder to make that happen...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301832] = {
	hp_warning = "",
	feeling3 = "",
	mail = "We've got new mail. I'm sure it's good news.",
	expedition = "Commander, our friends have returned from their commission. Sh-should we head down to welcome them back?",
	win_mvp = "",
	home = "Do you like it when I massage your back with my feet like this, Commander? ...Not in that sense? I see... I don't really get it though...",
	unlock = "There's still some time before the banquet begins, and I'm afraid I'm feeling a little sleepy... W-would you mind if I took a nap? Thank you...",
	touch2 = "*pant* *pant*...",
	mission = "Commander, your missions are of utmost importance... Mm, so I'll wait for you right here...",
	vote = "",
	drop_descrip = "There's still some time before the banquet begins, and I'm afraid I'm feeling a little sleepy... W-would you mind if I took a nap? Thank you...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Commander, are you happy? ...I don't mean like in general, but... like, when we're together... Um... As for me, when it's just the two of us, I feel amazingly happy...♡",
	main = "My tail is fluffy and warm, and you can even use it as a blanket... At least, that's what Oyashio and the others keep saying. Would you like to give it a try, Commander?|Commander, whenever I gaze at you, whenever I talk to you, I feel so at ease that I could go to sleep... Hm? You feel the same way about me?|This outfit feels a bit tight around the chest... Um, Commander, p-please don't stare at me so much...",
	touch = "It's not time for the party yet...? Then, um, let's stay like this for a bit longer...",
	voice_key_2 = -1,
	mission_complete = "Great job on finishing your mission, Commander! Um, ahem! Don't you want to cuddle up with my big, fluffy tail...?",
	battle = "I, I'll do my best...!",
	id = 301832,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, did you come just to see me...? Ohh, for the first thing I see when I wake up to be you... I must be dreaming...!",
	detail = "You feel a sense of relief when you see me? I'm not quite sure what you mean by that, but I'm glad that you're happy...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301833] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Oh, there's some new mail for us! ...I wonder if it's the storybooks I had ordered.",
	expedition = "Commander, the girls are back from their commissions! I'll head out to greet them!",
	win_mvp = "",
	home = "Commander, good work! I'm ready for you as well. Well then, um, let's get started. Ahem... A long, long time ago...",
	unlock = "I wanted to help you relieve some stress, so I thought I would read some folk tales to you... When I mentioned that, Akashi suggested these clothes to me... Wh-what do you think?",
	touch2 = "I-I'm going to lose my place...!",
	mission = "No more~ No matter how much you want to keep listening to the story, you need to prioritize your missions first!",
	vote = "",
	drop_descrip = "I wanted to help you relieve some stress, so I thought I would read some folk tales to you... When I mentioned that, Akashi suggested these clothes to me... Wh-what do you think?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "...The end. Commander, for the next story, should I try speaking in a softer voice... Huh? Commander? Looks like you've already fallen asleep, hehe.|I wanted to surprise you, so I'll be reading one of my personal favorites to you today. If there's something you want to listen to next time, please let me know, and I'll have it ready!|nil",
	touch = "You want me to read the next story? S-sure, I'd love to!",
	voice_key_2 = -1,
	mission_complete = "You've finished your missions! Good job with them. Since you held tight and worked hard to complete them, I've prepared lots of rewards for you~",
	battle = "It's time for me to get serious...!",
	id = 301833,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Tonight, I'll be putting all my heart into reading, all for your sake!",
	detail = "The sound of my voice puts you at ease? Th-that's great... it was worth practicing ahead of time!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301834] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Good work today, Commander! Before you taste your chocolate, taste me first! Umm... I-I just meant I wanted a hug...",
	unlock = "Commander? You stopped eating. Does it taste too bitter...? Oh no, if you don't like the chocolate I made, I... I-I can still make you happy in other ways!",
	touch2 = "Do you feel so warm and fuzzy that you might... melt in my arms?",
	mission = "",
	vote = "",
	drop_descrip = "Commander? You stopped eating. Does it taste too bitter...? Oh no, if you don't like the chocolate I made, I... I-I can still make you happy in other ways!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Whether it's chocolates or my tail, I'll use anything to make you happy! No, not just things – if using my own body and soul will do the trick, then I'll do it... I love you, Commander♡",
	main = "Commander, umm, can you breathe okay? You've been wrapped up in there for a while now, so if you can't... Y-you're fine? Okay!|Ah. Are you not eating your chocolate because of my smell... Hm? It's more of a visual problem?|After you touch my tail, can I have another hug? I-I'm nice and warm, so you'll be as comfy as can be!",
	touch = "Fluff to your heart's content...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 301834,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Fluffy, fluffy... D-does my tail feel good? Does it make you happy?",
	detail = "Why am I dressed like this? Well, I can already make you all mine by wrapping you up with my tail, so I thought I should give myself to you in return...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301838] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome home...d-dear! Calling you that now is still a little embarrassing!",
	unlock = "Now that the big day is here, I'm awfully nervous... I-I'll be in your care now and forever, okay?",
	touch2 = "If you want to cuddle up with me and my tail, then...I don't mind. Indulge yourself.",
	mission = "It's time for a mission. I will naturally assist you. After all, finishing it early means more quality time with you!",
	vote = "",
	drop_descrip = "Now that the big day is here, I'm awfully nervous... I-I'll be in your care now and forever, okay?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "In sickness and in health... No! You are already happy now, Commander, so... Healthy times aside, I don't know about... I-I'm sorry! Forget it, umm... Let's just be together forever!",
	main = "I've never done the san san kudo ceremony before. I hope I don't mess it up...|My white kimono looks lovely? Why, thank you. I'll cherish the memory of it for all my life.|Moving is rather difficult when I have to worry about my tail and the train... Heehee! That's another fond memory to look back on.",
	touch = "You want to hold hands, don't you? I'd be happy to!",
	voice_key_2 = -1,
	mission_complete = "Well done on another completed mission! Now we can spend some time together, just the two of us.",
	battle = "For the happiness of those we love!",
	id = 301838,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "It's amazing how happy I am just to be with you forever. Commander, let's enjoy another blissful day together!",
	detail = "I'm by your side. Always have been, always will be. Your happiness is my happiness, Commander.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301840] = {
	hp_warning = "The real fight's only getting started!",
	feeling3 = "Commander, you can rely on me as well! ...What?! You think you can one-up me...?!",
	mail = "Huh? The envelope got torn? ...Ahaha... Sorry 'bout that, must've been Pooky...",
	expedition = "The commission fleet has returned! Lemme take home the extras!",
	win_mvp = "The enemy general’s head is mine~! Just kidding, ahaha~♪",
	home = "Team A is directly under my command. Teams B and C will follow the plan, and then... Oh, Commander, when'd you get back?",
	unlock = "Ahaha, Pooky, listen up, we're gonna live here from now on! Uhh... Third ship of the Akizuki-class, Suzutsuki, reporting in! I'll be the one to protect my comrades and you, Commander! Just kidding~♪",
	touch2 = "C-Commander! Jeez, there are some things that you shouldn't be doing!",
	mission = "A tough mission, huh? Lemme take a look, maybe I can help out!",
	vote = "",
	drop_descrip = "Akizuki-class destroyer number three – Suzutsuki.",
	feeling4 = "Hmm... What would I like the commander to do for me? ...Make tea? Pack my lunch? Carry me back to the dorms after I fall asleep? ...Th-th-that's way too embarrassing!",
	lose = "Guh... No matter what, we all have to make it back safely...!",
	feeling1 = "Commander, you're gonna make me hate you...",
	skill = "Suzutsuki, defending her friends!",
	upgrade = "Give me more power, so that I may protect everyone!",
	propose = "Ahahaha... Being in a situation like this is quite nerve-racking, isn't it? ...I thought I had mentally prepared myself... Commander, you c-can handle the rest... right...?",
	feeling5 = "Commander, get over here! Hup~ ...Mmhmm, that's much cozier. Now it feels more like I'm relying on you, doesn't it? See, you'll also have to take good care of me from now on~ Just kidding~♪ Ahaha!",
	main = "\"The invincible Suzutsuki is here! Your attacks shall not put a scratch on me!\" How'd that sound? Hya hah!|Ahaha! You'd rather sit atop Commander's head instead of mine? Very well, go forth! Oh, but no pranks though!|Commander, you sure have a lot of work, don't you~ Look, Isokaze, Urakaze, being a warlord or a general is a lot of hard work. A better job would be to become Commander's retainers!",
	touch = "This marking on my right cheek? You haven't heard of it, Commander? It's the latest fashion trend! Here, I'll draw one on for you!",
	voice_key_2 = -1,
	mission_complete = "Mission complete! Commander, don't forget about the rewards!",
	battle = "May the odds ever be in your favor! Go forth!",
	id = 301840,
	gift_dislike = "",
	gift_prefer = "Ooh! Can I really have this?",
	profile = "I'm Suzutsuki, Akizuki-class destroyer. I was a member of the 61st DesDiv along with Akizuki and Hatsuzuki, and escorted Musashi and participated in Noshiro's rescue mission! Not a shabby record, right? I had a close call at the Battle of Bou-no-Misaki when I got hit by two torpedoes, but I managed to survive until the end!",
	voice_key = 30184,
	headtouch = "Look, fluffy and super pattable, right? ...Hey, I'm talking about Pooky, not my ears!",
	feeling2 = "I may come across as a braggart, but that's because I'm pretty reliable! \"Oh, Suzutsuki, you saved me! I don't know what I would've done without you!\" Yeah, I get that a lot~",
	login = "Welcome back! ...Got any new jobs? I'm down for anything!",
	detail = "When my friends are counting on me, I can feel power surging within me that makes me feel like I can do anything!",
	couple_encourage = {
		{
			{
				30220
			},
			1,
			"Be careful out there!",
			0
		},
		{
			{
				30156,
				30157,
				30158,
				30182
			},
			1,
			"I will be the one to protect my friends!",
			0
		},
		{
			{
				30160
			},
			1,
			"Isokaze, back me up!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[301841] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Not enough people for a game of beach volleyball? All right! I'll go play some watermelon splitting with Georgia first!",
	unlock = "Commander, over here! We're about to start without you! Ahaha, what would you like to do, Commander? Beach volleyball? Sandcastle building? We can also go relax in the water if you'd like!",
	touch2 = "Jeez, Commander! What are you doing in front of this many people?!",
	mission = "",
	vote = "",
	drop_descrip = "Commander, over here! We're about to start without you! Ahaha, what would you like to do, Commander? Beach volleyball? Sandcastle building? We can also go relax in the water if you'd like!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Phew... Playing by the beach is super fun, but after all the commotion, I could use some relaxation... Yup, I'm gonna lie down right here! Mm... Yeah, just stay put like that. Hehe~",
	main = "Do we have enough people to build a sand castle? Great, count me in as well! Wait, Commander, hold on!|Pooky likes coming to the sea as well, isn't that right~? Ah, careful not to fall into the water!|Agano's not here? That's too bad, I was looking forward to playing with her... Commander, why do you look so relieved? Hm? It's just my imagination?",
	touch = "Woah?! ...Oh, it's you, Commander, you surprised me... Hibiki shoved a crab in my face earlier and it gave me a nasty pinch...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 301841,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, time out! Look, the others have already started playing without you~ Fine, fine... I shall be the one to accompany you then!",
	detail = "I'm pretty refreshing and cool, right? Just like my name suggests~",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301842] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Suzutsuki, now reading the contents of your mail out loud!",
	expedition = "The girls from the commission fleet are back! Darn it, I wish Hatsushimo could come with me!",
	win_mvp = "",
	home = "",
	unlock = "I, Akizuki-class destroyer, Suzutsuki, shall not allow you to pass through these arches! Hwuh?! I missed the return again...!",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "I, Akizuki-class destroyer, Suzutsuki, shall not allow you to pass through these arches! Hwuh?! I missed the return again...!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Aaahhhhh!! Jean Bart, you don't have to shank every shuttlecock out of existence!|Pooky, I got some sunflower seeds from Hanazuki! Here, come and eat your fill~ Grow big and strong and scare the heck out of the commander~ Ahaha!|I can't sit still during the New Year! After all, there are so many things going on that only happen during this time of year!",
	touch = "Commander, make sure the matches continue smoothly!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "You ready, Pooky? Let's— go!",
	id = 301842,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Happy New Year, Commander!",
	detail = "These markings are the proof of my battle scars as a warrior... they're not just doodles! Ugh... I swear, I'll be back for revenge after I train some more!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301850] = {
	hp_warning = "When push comes to shove, retaliate...!",
	feeling3 = "You need an attendant for your outing? Understoo– Wait, why would you need an attendant for a tour of your own port? ...You want to \"hang out\" with me? What does that mean?",
	mail = "Correspondence has arrived. Don't come nagging later, saying I didn't inform you.",
	expedition = "The commission team has returned. I will see to the transport of the goods, and you to its inspection.",
	win_mvp = "All I did was perform my duty, as I said I would.",
	home = "No unauthorized persons entered the office in your absence. End of report.",
	unlock = "I am Kamikaze-class destroyer Oite, assuming my post starting today. I will perform my duties, and anything beyond that I will decide on a case-by-case basis. End of report.",
	touch2 = "Whuah?! Wh-wh-wha-what has gotten into you, fool?!",
	mission = "To think a trivial task would have you up-ended like this... If you so insist it's impossible, then I will set an example.",
	vote = "",
	drop_descrip = "Kamikaze-class destroyer number six – Oite.",
	feeling4 = "I cannot wrap my head around your need for an attendant when there are no hostiles at the port... Nor do I grasp this \"hang out\" business! Although I did enjoy our friendly exchange! E-e-end of report!",
	lose = "We must start anew at boot camp...",
	feeling1 = "I expect no betterment from you. Go on, let your name be irreversibly tarnished.",
	skill = "Let us finish this!",
	upgrade = "You have my gratitude.",
	propose = "I don't know what to do at this ceremony! You insisted on it, so it's your responsibility to g-guide me through it! E-end of report...",
	feeling5 = "All your talk of attendants and \"hanging out\" was just an attempt to seduce me, was it not? N-no, I mean nothing bad by it! Oh, forget it! You toyed with my heart, and now you must o-own up to it!",
	main = "How, I wonder, would one go about making Agano stop touching my ears...|Urgh... Reading so much fine print text has given me a headache. Commander, requesting permission to rest...|I like the quiet of the office, free from the jarring hum of propeller aircraft.",
	touch = "Whuah! Would you STOP tickling me?",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Will you get a move on already and process the rewards?",
	battle = "Enough talk! Have at you!",
	id = 301850,
	gift_dislike = "",
	gift_prefer = "You're more perceptive than I thought~",
	profile = "I served as flagship of Destroyer Division 29 within Destroyer Squadron 6. I performed various escort and transport missions. Leave any tasks of this nature to me. End of report.",
	voice_key = 30185,
	headtouch = "What the–?! K-k-keep your hands off my ears!",
	feeling2 = "What do you need from me? Make it quick.",
	login = "You came of your own accord. How fortunate... Never you mind. Get to work.",
	detail = "All you do is loaf around in here... Are you a commander, or a deadbeat?",
	couple_encourage = {
		{
			{
				30220
			},
			1,
			"I have you covered!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[301851] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Truly, Kamikaze? You're certain I will become proficient faster if I wear a blindfold?",
