_G.pg.base.ship_skin_words[301852] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Should you think of any good ideas for verses, tell me. I will write them down.",
	unlock = "Happy New Year to you, Commander. To celebrate the season, I had these garments tailor-made for me, using traditional Dragon Empery clothes as a basis. I don't look... childish, do I?",
	touch2 = "Eek?! Y-y-you reprobate! What's the matter with you?!",
	mission = "",
	vote = "",
	drop_descrip = "Happy New Year to you, Commander. To celebrate the season, I had these garments tailor-made for me, using traditional Dragon Empery clothes as a basis. I don't look... childish, do I?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "\"In the ninth year of Yonghe, and the year of the Water Ox...\" Bah! The rest of the text is unintelligible to me...|Writing a poem in seven steps? Is there a person on this earth capable of such a feat?|Kamikaze, what should one offer the young'uns as a new year's gift, other than money?",
	touch = "Eep! Y-y-you're doing this on purpose, aren't you?!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 301852,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Whuaah?! I've told you countless times! St-st-stop touching my ears!",
	feeling2 = "",
	login = "A New Year's poem... \"Many riches will grace you soon – I want my new year's gift by noon\"... No, this is backwards! I'm at the age where I'm the one who should give the young'uns gifts... Oh, Commander? When did you get back?",
	detail = "The essence of the plum tree is best captured with erratic brush strokes... This is quite the elegant ink painting.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301860] = {
	hp_warning = "Watch beneath the waves...",
	feeling3 = "You're not a bad person, so we can be friends... Do I wish I had more friends? I'm... not gonna tell you.",
	mail = "Mail for the commander? Okay birdies, go fetch... No, please don't fight over who gets to do it.",
	expedition = "The commission team's back. Don't forget to say hi to them... Me? Uhh, I think I'll stay right here.",
	win_mvp = "It'd be great if we could keep winning...",
	home = "Good going, Commander... You heard a strange noise just now? Uhh... I'm sure it was just your imagination.",
	unlock = "Kazagumo, Yuugumo-class, reporting for duty. I hope I'll be able to get along well with everyone else here... Commander, you're not cooking up some dastardly plan, are you? You look rather questionable...",
	touch2 = "You'll be cursed for this...",
	mission = "Look at all these unfinished missions... You should really do something about them.",
	vote = "",
	drop_descrip = "Yuugumo-class destroyer number three – Kazagumo.",
	feeling4 = "There have been rumors of this girl with long hair and skin as pale as a ghost's who appears out of nowhere at port... In fact, I think she's right behind you, Commander... What do you mean that's not gonna fool you? Well, I thought I'd just spook you a little...",
	lose = "Ugh. I'm really out of it today...",
	feeling1 = "I guess we're all fated to be alone. You, me, and everyone else...",
	skill = "I wanna get this over with...",
	upgrade = "Thanks, Commander.",
	propose = "I think... this is when you promise to never leave me. First you say it, then it's my turn... Hehehe~ Thank you. I love you.",
	feeling5 = "You're fun to be with, Commander. A lot of fun. In fact, you're my best friend... Hehehe~ I wanna always be with you. Always.",
	main = "Could you not stare at me like that, Commander? I can't focus like this...|You're on duty, so no chit-chatting with me allowed, okay? ...I mean, if you feel really lonely, then maybe...|I like the satisfying toot-toot noise that recorders make... Do you wanna hear it? It'll have to be later, not now...",
	touch = "Commander... What are you up to? (Kazagumo throws you a suspicious look.)",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Wonder if I'll get a reward for my efforts...",
	battle = "We can win this... Right?",
	id = 301860,
	gift_dislike = "",
	gift_prefer = "That looks pretty neat. ...Oh, it's for me? Thanks...",
	profile = "Kazagumo, Yuugumo-class destroyer number 3. I served the 10th Destroyer Squadron, mostly running transport missions and naval evacuations. These little birdies are my friends. My hobbies? I'm not telling you.",
	voice_key = 30186,
	headtouch = "I'm not a pet, so don't treat me like one...",
	feeling2 = "You want to be friends with me? Okay, but if I find out you're planning something bad... then I'll never talk to you again.",
	login = "*Yawn*... Oh. You scared away the birdies, Commander.",
	detail = "I like being alone in my own room. What exactly do I do in my free time? ...I'm not telling you.",
	couple_encourage = {
		{
			{
				30704
			},
			1,
			"I'll keep you safe, Hiryuu.",
			0
		},
		{
			{
				30180
			},
			1,
			"Watch beneath the waves, Makinami.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[301861] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "I'm glad we won. Hehehe.",
	home = "Welcome back, Commander. You didn't bring company... did you? Okay, good. I don't want others to hear how not-good I am at the recorder...",
	unlock = "Toot~♪ Oh, Commander, did you hear me practicing my recorder? Umm, I'd appreciate it if you didn't tell the others.",
	touch2 = "Oh... Seriously, Commander? You're messing up my melody.",
	mission = "",
	vote = "",
	drop_descrip = "Toot~♪ Oh, Commander, did you hear me practicing my recorder? Umm, I'd appreciate it if you didn't tell the others.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "I'll make you proud, Commander!",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Weird... I played pretty well just a moment ago, but now I can't do it...|The name of the song I just played? I'm not gonna tell you right now. After I've mastered it, all right?|You're so nice, hanging out with me even after school... I'm not taking up your time, am I?",
	touch = "Ugh... I lost track of the tempo because of that... Thanks, meanie.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 301861,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Zzz... What is it, Commander...? Me? The breeze was just too nice and I fell asleep...",
	detail = "I've practiced some more. I'll play you a song, if you'll listen... On second thought, maybe I won't.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301862] = {
	hp_warning = "",
	feeling3 = "",
	mail = "If you really want some ice cream... Wait, you had it delivered with the mail? A-aww...",
	expedition = "The commission team came back. Go and meet them, Commander. I'll watch your things.",
	win_mvp = "",
	home = "*blows* I'd better eat this ice cream before it melts... Would I get brain freeze if I just bit into it?",
	unlock = "*lick*... Oh, Commander, y-you're here for the fireworks? ...Want to watch them with me, then? I've got drinks. My ice cream? Umm... You can't have it.",
	touch2 = "Huh...? Oh... *blushes*",
	mission = "",
	vote = "",
	drop_descrip = "*lick*... Oh, Commander, y-you're here for the fireworks? ...Want to watch them with me, then? I've got drinks. My ice cream? Umm... You can't have it.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "You're tired from swimming? Take a break here with me. I'll watch over you, so you can even take a nap... if you want.|Umm, actually, I've been practicing a new song. Want me to play—Ack, the fireworks! Maybe another time...!|I wonder where Shimakaze went... How can she not be tired after playing on the beach all day?",
	touch = "Does my swimsuit... look weird?",
	voice_key_2 = -1,
	mission_complete = "You finished a mission. Is there a reward for me, too...?",
	battle = "",
	id = 301862,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Who is that launching fireworks over there, I wonder? Watching from directly below seems dangerous, but I bet they look prettiest from there...",
	detail = "Why am I out here all by myself? Because I get to be alone with... Oops, ignore that. I can't tell you...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301863] = {
	hp_warning = "",
	feeling3 = "",
	mail = "I put your mail right here, Master.",
	expedition = "The commission team is back. Hmm... I wonder what they brought.",
	win_mvp = "",
	home = "Master, welcome back. You may choose: piping-hot tea, or a shoulder massage? ...You don't need anything? O-okay, well, we could always just chat...",
	unlock = "I'm doing lots of training. Gardening, making tea, stuff like that. Here's an example... Umm, do you want dinner, or a bath, or... Hm? I shouldn't practice that one?",
	touch2 = "Master, t-today is a good day, if you know... what I mean...",
	mission = "Missions... We'll do them together, Master!",
	vote = "",
	drop_descrip = "I'm doing lots of training. Gardening, making tea, stuff like that. Here's an example... Umm, do you want dinner, or a bath, or... Hm? I shouldn't practice that one?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "Thank you, Master.",
	propose = "",
	feeling5 = "I don't understand... It feels like I'm still yearning for more. My Master is by my side already... But I think I want you here with me forever. I just wish you could be...",
	main = "Yep. I've been waiting here. ...For whom? Come on, you know... Don't tease me!|Master, sit down. Here's your tea! ...You feel warm and happy after drinking it? Th-thank you...|Play a song alongside the wind chimes...? Th-that may be hard... But if you want to hear it, then I'll try. D-don't make fun of me, though!",
	touch = "Master, if you ever get lonely, just let me know. I know just what to do about it... Heehee, I think you and I are thinking the same thing.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 301863,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Welcome back, Master. I brought you hot tea. ...You saw pretty flowers in the garden? I-I raised them in my spare time, so... I'm glad you like them.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301880] = {
	hp_warning = "Woah, I've got to regain my balance!",
	feeling3 = "Some people will turn their backs on their friends and their beliefs after gaining great power... You often read about these greedy powermongers in various stories! If I ever met someone like that one day... Hehe~",
	mail = "Commander, take a look at this! A top-secret letter has come! ...Oh, it's just an ordinary letter?",
	expedition = "A commission represents the trust of the requester. In other words, upholding that contract is righteous and good!",
	win_mvp = "The victor has been decided! Drop your weapons and surrender! Hahaha!",
	home = "I am glad you've returned safely! Ehehe, I could hardly sit still while waiting for you to come back, Commander...",
	unlock = "I'm Akizuki-class destroyer Wakatsuki. I heard your summons and came promptly to aid you, Commander! Kindly call upon me whenever you have need of me.",
	touch2 = "Woah, woah! What are you doing, Commander? That's the kind of stuff you end up groveling on your knees and apologizing for!",
	mission = "Are you worried about this mission, Commander? Just let me take care of it then!",
	vote = "",
	drop_descrip = "Akizuki-class destroyer number six – Wakatsuki.",
	feeling4 = "Are you going somewhere, Commander? ...Th-then, bring me along with you too! I'll make myself useful somehow! ...Whenever you're not here, I... Oh, you're just going on a quick patrol around the port?!",
	lose = "I shall protect your rear, so hurry up and retreat!",
	feeling1 = "Why did you have to leave me all alone? Did I do something wrong...?",
	skill = "Just leave it to me!",
	upgrade = "My body has become lighter and faster!",
	propose = "I see! So this is a symbol of my fealty to you! From now on, I swear to always remain by your side and to protect you with my life! If you ever need anything, just call my name. I'll do anything for you!",
	feeling5 = "I shall protect you today, just as I do every day! ...Huh? I seem to be in an especially good mood today? Well, of course! Nothing makes me happier than being at your side and serving you faithfully!",
	main = "Commander, please look over here! There're some little birdies by the windowsill... Aw, they flew off... Hmm, is there some way of approaching without scaring them away?|Commander, is there any work I would be able to help with? I might not be able to understand a lot of these documents right now, but if I work at it enough, I'm sure I'll get the hang of it!|I start to feel anxious when I'm not with my friends... Do you feel the same way when you're alone, Commander?",
	touch = "My blade is very heavy, so please be careful!",
	voice_key_2 = -1,
	mission_complete = "Mission complete! I don't think I've done anything worthy of praise, but it does feel great to overcome obstacles together with you!",
	battle = "Vanguard Wakatsuki has arrived! Everyone, charge forward with me!",
	id = 301880,
	gift_dislike = "",
	gift_prefer = "Much obliged!",
	profile = "Akizuki-class destroyer, Wakatsuki, is at your service! Like my sisters, I specialize in anti-air combat, but I'm no slouch when it comes to surface combat either! Don't you worry - I will never betray your orders, and will strive tirelessly to protect you!",
	voice_key = 30188,
	headtouch = "Is this my reward? Ehehe~",
	feeling2 = "My reason for helping others, huh... Hmm, I've never actually given it that much thought before. How about you, Commander? I heard you've done so much for everyone here, so what's your reason for all that?",
