_G.pg.base.ship_skin_words[301892] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Whuah?! Wh-what is it? The commission team's back? You should've just said so!",
	win_mvp = "Hooray! Now if only you'd be mine, everything would be perfect, Commander!",
	home = "Welcome back! Heehee. Your seat is on the couch over there – and MY seat is on your lap♪",
