	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 301898,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "This red string? Don't worry about it... The only red string I need is the one binding our hearts together♪",
	feeling2 = "",
	login = "Look, Commander! Pretty, huh? No, I DON'T mean the scenery – I mean ME!",
	detail = "The snow is blessing our union, Commander~ Do you hear it? It's saying, \"May your bond be as eternal and pristine as this world of snow!\"",
