	id = 301901,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Late again. You weren't out there playing with other girls on the beach, were you?",
	detail = "It's not as if we fight at all hours. You'd be better off if you learned how to relax. As someone who leads shipgirls to battle over the sea, you'd benefit the most from learning how to enjoy the ocean.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[301910] = {
	hp_warning = "The fire is spreading!",
	feeling3 = "Hm? I smiled? I was simply thinking about you. D-don't give me that look... I'm not used to it...",
	mail = "Commander, I've brought all your mail. Can I write you a letter too?",
	expedition = "Commander, the commission team is back. You want me to come along and welcome them? Sure.",
