	unlock = "Greetings, Commander. I'm Suzunami of the Sakura Empire, 10th ship of the Yuugumo class of destroyers. I hope we can be, um... friends...",
	touch2 = "Huh?! I-I'm not accustomed to... physical touch like this...",
	mission = "Commander, you really can't put off your tasks any longer.",
	vote = "",
	drop_descrip = "Yuugumo-class destroyer – Suzunami",
