_G.pg.base.ship_skin_words[301920] = {
	hp_warning = "Ouchies! Gonna need some ointment for that one...",
	feeling3 = "Ninja training was sooo hard today! Commander, rub my shoulders for me... C-Commander? Why are you holding a log? Ack! I'm sorry! I accidentally used my substitution jutsu.",
	mail = "New mail arrives on swift winds! Will there be shocking news within? Open it and find out!",
	expedition = "I came back with the commission team! ...Why was I disguised as a supply box? Because ninja training, duh!",
	win_mvp = "Ever elusive, coming and going without a trace, the kunoichi master of disguise brings you ultimate victory once again!",
	home = "Wachaaa! Welcome back, Commander! Did that startle you? Heheh... Huh? You saw my tail?!",
	unlock = "Ba-duuum! This hide-and-seek game is over! The Yuugumo-class destroyer and kunoichi who floats on the wind sneaks onto the scene! Now that you've discovered me... Bam! Smoke bomb! Another successful escape!",
	touch2 = "Huh? Wha? Whaaaat?! C-C-Commander?!",
	mission = "Got your mission requests here! Are they sneaky infiltrations? Or intel gathering? I can take care of any of them without leaving a trace!",
	vote = "",
	drop_descrip = "Yuugumo-class destroyer – Taekaze.",
	feeling4 = "Zzz... Zzzz.... Hah! I-I wasn't sleeping! Protecting her Commander is a kunoichi's duty! I'm going to stay right here by your side until you finish your work... I won't fall asleep, I swear... Zzzz...",
	lose = "Ugh, they saw through my disguise... Bam, substitution jutsu! Another successful escape!",
	feeling1 = "Wow, you're really boring. I don't even wanna prank you at this point...",
	skill = "Ninpo: Secret Wind Technique no Jutsu!",
	upgrade = "My ninja training has just begun!",
	propose = "So this is the bond called love... Elusive but indestructible, just like the wind. But sometimes... even the elusive can be caught. Hold me tight, and I'll never leave your arms.",
	feeling5 = "Heheh, so you've finally seen through my disguise! Better hug me quick, or I'll slip right out of your hands! ...Well? Hurry up... I'm trying so hard to let you catch me...",
	main = "I'm learning how to make these black pills! No, they're not ninja tools. They're tasty candy... Ahem, I mean nutritious soldier pills! Try eating one, Commander!|Wow! You caught me! Too bad, though – bam, substitution jutsu! Hehe, try and get me again!|Commander, look! I can walk on water... Gaaaah, I got distracted thinking about dinner BLRBLBLRF! Help meee!",
	touch = "D-don't grab my tail! Gaaah! Okay, I promise I won't disguise myself as your chair anymore!",
	voice_key_2 = -1,
	mission_complete = "Your mission rewards came! I'll just take these... Heheh, you'll have to catch me if you want them!",
	battle = "Kunoichi master Taekaze will take them by surprise!",
	id = 301920,
	gift_dislike = "",
	gift_prefer = "Ooh! I've always wanted one of these!",
	profile = "I'm Taekaze, a Sakuran Yuugumo-class destroyer! I've never had the chance to show off my true power before, but now, you'll get to see it as my Commander! Don't blink – transformation jutsu!",
	voice_key = 30192,
	headtouch = "Gaaaah, no no no! Number one rule of ninjas: you need to be unpredictable! I don't CARE how good it feels when you pet me, you can't... Ooh...",
	feeling2 = "A bonsai plant, a tree, or a manhole cover... What should I disguise myself as next? Any thoughts, Commander?",
	login = "Bam, smoke bomb! Heheh, did my entrance startle you... *cough*! *cough* *hack*! The smoke... it's in my throat!",
	detail = "Hmm? Your hat got blown off? Y-yeah, the wind sure is something today! You definitely didn't get it snatched away by a certain kunoichi...",
	couple_encourage = {
		{
			{
				30109,
