_G.pg.base.ship_skin_words[302060] = {
	hp_warning = "Kh, I'm fine! If I use my cheat skills, I can make it out of this...!",
	feeling3 = "I see, I see. So you finally understand my strength. That's right! I can use this ability to triple the price of toys in the port stores! ...Hm? What is that good for?",
	mail = "If only there was some convenient feature that lets you know with an icon that you had unread mail... \"You rely too much on humans. Here, I will notify the whippersnapper.\"",
	expedition = "Did you notice the commission girls are back? Heheh, you're not bad if you can keep up with my super senses.",
	win_mvp = "Did you think you could withstand a dragon's might? \"I've never seen a more foolish foe!\"",
	home = "Ooh~ You've finished your work! Then the workday is over! Maybe I'll go shopping with Nagara, or...",
	unlock = "\"Nuo ho ho! So this young whippersnapper here's the Commander! You don't look all that reliable to me~!\" ...Argh, do not interrupt me when I am speaking! Ahem– I am the strongest light cruiser Natori, and this is my partner, Old Man Hiranuma! Nice to meet you!",
	touch2 = "What are you doing to me?!",
	mission = "You STILL haven't finished your missions? Ugh, you average people... I'd have them done in the blink of an eye.",
	vote = "",
	drop_descrip = "Nagara-class light cruiser – Natori.",
	feeling4 = "You just don't understand. If I can triple prices, then I can resell what I purchase for massive profits! Jealous? ...Y-you're not jealous?!",
	lose = "This is not defeat! It's strategic withdrawal!",
	feeling1 = "Everything you say is a cheap lie. I don't trust you...",
	skill = "Behold, my latent power!",
	upgrade = "Ooh! My power... My power is surging! My stats are going through the roof!",
	propose = "Oh, I can't leave your side anymore, Commander... You always look after me, and you listen to the things I say... That's just unfair! What is this, your trap?! Is that it?!",
	feeling5 = "Hmm, my \"affinity\" stat has gone up too high. My old man says this is going to interfere with my daily work! Commander, what do you plan to do about this?!",
	main = "I must pass a trial to unlock my true power, no? Come with me when the time is right, Commander!|Ah, I'm hungry... Oh, Commander! Hey, treat me to a meal! \"I desire pudding for dessert!\"|\"By the way, there are plenty of ways to raise your attributes~ For example, these stats...\" Old man, would you just cut to the chase and tell me how?!|W-wait, Nagara! I-I'll clean it up, I promise, just don't throw away my manga... I know! Yura, let me hide them in your room for a little while!",
	touch = "...Mm? What? Do you need me?",
	voice_key_2 = -1,
	mission_complete = "Huh? The Commander's missions are finished already?! Old man, why didn't you tell me?!",
	battle = "I could defeat you all with one pinky finger.",
	id = 302060,
	gift_dislike = "",
	gift_prefer = "Eh?! What? For me? Really?! Wooow! Thank you!",
	profile = "I'm Natori, the third Nagara-class ship! As a light cruiser of the Sakura Empire, I often tell people that I fight with single-mounted guns and water scouting craft... But that is a ruse! For I am the incarnation of a dragon! My strength shatters boulders (with cannonballs) and soars over the sea (with my rigging)! So? Impressed?",
	voice_key = 30206,
	headtouch = "Nngh, do not stroke my hair so casually!",
	feeling2 = "I'll share this with you alone, Commander. If I close one eye and push like this, I can shoot laser beams! Or so this old geezer says. I've never tried, because it's far too destructive.",
	login = "♪~ I'm just so strong that I suffer from success~ Commander, join me! ...Not for work! For fun!",
	detail = "Hmph. Let me share some little-known information with you, Commander. These aren't oni horns; they're dragon horns! Isn't that incredible? \"Yes, yes, a dragon. I say so, and that means it is fact!\"",
	couple_encourage = {
		{
			{
				30214
			},
			1,
			"Alriiight! Naka, it's time to charge in!",
			0
		},
		{
			{
				30205
			},
			1,
			" Isuzu, can I follow behind you?",
			0
		},
		{
			{
				30209
			},
			1,
			"Keep your eyes forward, or you'll run into me, Abukuma!",
			0
		},
		{
			{
				30705
			},
			1,
			" Requesting air support, Kadekuru!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[302061] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Phew~ I am beat! Time for some juice and rest... Hey, old man! Do I have the power to create juice out of thin air? \"You might be able to make fried chicken, but no juice, kiddo. Have that whippersnapper buy you some.\"",
	unlock = "Mmfhuhu~♡ What's the matter, Commander? Enraptured by my charms? Heehee, you're frozen in place! You can't begin to think of how to compliment me, can you? \"Enough staring, out with the compliments!\"",
	touch2 = "Grr! My skin is too fine for you to be touching it so freely!",
	mission = "",
	vote = "",
	drop_descrip = "Mmfhuhu~♡ What's the matter, Commander? Enraptured by my charms? Heehee, you're frozen in place! You can't begin to think of how to compliment me, can you? \"Enough staring, out with the compliments!\"",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Mhmhm... Very, very interesting! I see your passionate gaze upon me, Commander! That gaze is the essence of summer!|Even the fish are knocked cold by my charms. Now's your chance for a big catch!|I'd say my sensuality matches even Isuzu's now, no? See, old man? Even the Commander is speechless!",
	touch = "Mmmm... There! My special ability allowed me to sense your approach! Incredible, no?!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 302061,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Mmfhuhu~♪ I'm a little different from the usual today, right? I'm sure you can figure out how, Commander♪",
	detail = "I've made everything up to the castle keep. At this rate, the sand castle competition is all but won... Heheh, now, time to go laugh at the others— \"A giant wave is approaching! Watch ooout!\"",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[302062] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Commander, you're finally back! Heheh, while you were gone, I took control of this entire venue!",
	unlock = "Heheh♪ The brightest star in the venue, she with the power to shake the earth – none other than Natori, of course! Go on, Commander, and kneel before me~ \"Nuo ho ho, even the whippersnapper is amazed!\"",
	touch2 = "I'm gonna faaall!",
	mission = "Must you constantly worry about missions even while we party? Why not just leave it all to me and the old man here?",
	vote = "拉票描述",
	drop_descrip = "Heheh♪ The brightest star in the venue, she with the power to shake the earth – none other than Natori, of course! Go on, Commander, and kneel before me~ \"Nuo ho ho, even the whippersnapper is amazed!\"",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Heheheh~ Commander! Once the party's over, let's go raise hell somewhere else! In fact, I found a way to stop my \"affection\" stat from rising infinitely! So now – w-wait! No touching! You're putting all of my efforts to waste!",
	main = "Phew... Using my power indiscriminately has left me hungry. Commander~ Let's go get some food soon!|Food Protection Magic, activate! When food is about to fall on the floor, it will float for not just three seconds, but ten! Ahahaha, incredible, isn't it? \"Nuo ho ho, how strong you've grown!\"|Commander, I hereby declare that you have become mine – an Adherent of the Dragon! \"Becoming an adherent is apparently a big deal, whippersnapper! Give her your full support!\"",
	touch = "Nuo ho ho~ Do you want a taste of my power, Commander?",
	voice_key_2 = -1,
	mission_complete = "\"Whippersnapper, the mission is complete!\" Aren't you glad you had us to help? Ahaha!",
	battle = "",
	id = 302062,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Whoa?! Commander, how did you... Have you awakened a new power?",
	feeling2 = "",
	login = "Heheh~ You've arrived, Commander! Get ready quickly and come with me! It takes two to play, of course.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[302070] = {
	hp_warning = "We should get back into formation.",
	feeling3 = "You want to know more about my Self? Well, she's also a part of me... Mm, if I were to put it simply, she's kind of like my familiar.",
	mail = "Shall my Self read it aloud for you?",
	expedition = "The girls are back from commissions. If you require assistance, shall my Self accompany you?",
	win_mvp = "My Self played a big role as well. I'll have to thank her for her help.",
	home = "It's good to see you, welcome back. I apologize, for I don't really know where to put these papers...",
	unlock = "Um... Would you happen to know where the Commander might be? My name is Yura, and I have just arrived here today. Are you the Commander? Um, do you have a signed note or certificate that corroborates that?",
	touch2 = "I have no choice but to become your wife now, Commander. Hehe~",
	mission = "Oh, Commander, I really think you shouldn't be neglecting these missions...",
	vote = "",
	drop_descrip = "Nagara-class light cruiser number four – Yura.",
	feeling4 = "Your fortune said that bad luck would follow you around, so I, along with Abukuma and the others, made a protective charm that will ward off evil. Please be careful, and always carry this around with you.",
	lose = "It might be better to withdraw first...",
	feeling1 = "I wonder if the fortune that foretold \"calamity\" was referring to you...",
	skill = "Safety first.",
	upgrade = "Oh, I feel something awakening inside me...",
	propose = "Oh, to think that I'd be able to become your betrothed, Commander. ...Is this truly alright? Hehe, I'm so happy that I lost my composure... Thank you.",
	feeling5 = "Whenever I think of you, I always worry that something bad might have happened to you. Please, stay with my Self's... no, my side. That way, I won't have to worry.",
	main = "Commander, if you're concerned that the tea is too hot... Um, should I blow on it for you?|Abukuma, I don't think that \"only eating and sleeping\" is a healthy lifestyle. I'm wrong about that? Well...|The destroyers are... well, they're always so full of energy and zipping about, that it's honestly a bit hard to keep pace with them...|Even when we can't see her, my Self is always by my side.|You want to know more about my Self? Do I think she has some kind of special connection with the meaning of my name...? I sometimes wonder myself.",
	touch = "Did you need something from me?",
	voice_key_2 = -1,
	mission_complete = "Oh, speaking of which... I haven't told you to receive the mission rewards yet... have I?",
	battle = "I'd like to wait a bit more and see what the situation is like...",
	id = 302070,
	gift_dislike = "",
	gift_prefer = "Is this really for me? Thank you so much!",
	profile = "I am the Nagara-class light cruiser, Yura. In a certain great war, I was the flagship of the Fourth Torpedo Squadron for a short period of time. I might have taken my leave earlier than my sister ships in that war, but this time, I swear that my Self will remain until the bitter end.",
	voice_key = 30207,
	headtouch = "Would you like to touch my horns?",
	feeling2 = "Commander, if there's nothing for me to do, I'll be heading to the shrine behind the mountain to help out.",
	login = "Commander, um... good job making your way over here.",
	detail = "Sometimes, I feel like I'm not quite myself... That must be my other Self...",
	couple_encourage = {
		{
			{
				30201
			},
			1,
			"Well... Let's try to stay safe. ",
			0
		},
		{
			{
				30181
			},
			1,
			"My friend? Mm, I'm not sure what you mean... ",
			0
		},
		{
			{
				21301
			},
			1,
			"Can you see my Self?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[302071] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "The wings are slipping off... Is there a mirror somewhere...?",
	unlock = "Uh... I think these clothes are a bit too much... Commander, I... don't look out of place in these, do I...?",
	touch2 = "Maybe you were the real succubus all along. Hehe.",
	mission = "",
	vote = "",
	drop_descrip = "Uh... I think these clothes are a bit too much... Commander, I... don't look out of place in these, do I...?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "A succubus is a being that tempts people in their dreams... I-I'd never do anything like that!|Isuzu, it's me, Yura! I'm not a ghost, you don't need to be afraid of me!|I don't know if today is a day of celebration, but everyone seems to be more lively than usual. I wonder if the Commander will be all right dealing with them...|It seems that thou are doing well. Hehe. Commander, do you perhaps prefer my Self to me?",
	touch = "Oh, did you need something?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "I'll seduce you, alright. Hehe.",
