_G.pg.base.ship_skin_words[302120] = {
	hp_warning = "",
	feeling3 = "I can't settle until I've made right out of wrong with my fists. That's my way of life. It's why I try not to get involved in anyone's business; I just don't wanna cause any trouble.",
	mail = "Here, your letter.",
	expedition = "Yo, commission's done. Don't tell me you're really considering just keeping those hardworking girls waiting.",
	win_mvp = "Heh. Won't even need to replace my bandages.",
	home = "When's the next sortie? I've still got a ton of spare bandages.",
	unlock = "You're a commander? I don't need one... But maybe we were fated to meet, or something. Guess you've got me to look after too, now. The name's Sendai. Don't forget it.",
	touch2 = "You got a damn death wish? You askin' me to knock some sense into that skull of yours? Izzat it, huh?!",
	mission = "A mission... That's my kinda deal.",
	vote = "",
	drop_descrip = "Sendai-class light cruiser number one – Sendai.",
	feeling4 = "Feels like I've been here a long time... I know I'm the one saying that, but still, it really has been a long time...",
	lose = "Owwww... Ahaha... Guess this is it...",
	feeling1 = "Think it's about time we say goodbye.",
	skill = "I'll wreck you!",
	upgrade = "I'll become stronger, then I'll...!",
	propose = "Commander, before you gave me this, I'd just have left you if you'd forgotten your principles... But now that you've given me this... Forget your principles, and you'll taste my fists of love and rage. *Giggle*",
	feeling5 = "People like you are pretty amazing. You do everything I want to, but just a bit better... When I'm with you, I even lose track of time... As long as you don't lose sight of who you are, I'll follow you to ends of the earth.",
	main = "I dream of justice, justice for... Never mind. Let's write off that one as a joke.|All I have are my principles and my fists. Even so, I'll always keep moving forward.|Commander, who do you think is our worst enemy? The Sirens? I think it's our own minds.",
	touch = "Commander, you'll end up gettin' hurt if you approach me without warning.",
	voice_key_2 = -1,
	mission_complete = "You sure you wanna ignore those mission rewards, Commander? Not that I really care.",
	battle = "You're going up against me!",
	id = 302120,
	gift_dislike = "",
	gift_prefer = "Need my help whoopin' somebody's ass?",
	profile = "I'm Sendai, the first ship of the Sendai-class. Although my service record isn't as impressive as my little sisters', I served as the flagship of Destroyer Squadron 3 and fought in tons of battles. I bit the dust at Bougainville, but I did so as a warrior with no regrets.",
	voice_key = 30212,
	headtouch = "",
	feeling2 = "I'm not much of a people person, so I'd rather you'd just leave me alone... Hey, relax. You're my boss, so I'll still do my job.",
	login = "I'm done warmin' up. Time to sortie, or what?",
	detail = "These bandages? They're not for when I get hurt, they're for wrapping around my fists... You'll struggle to find anyone who can actually injure me.",
	couple_encourage = {
		{
			{
				30301,
				30302
			},
			2,
			"Let's go, 5th CruDiv!",
			0
		},
		{
			{
				30302
			},
			1,
			"Kako, stay close to me.",
			0
		},
		{
			{
				30213
			},
			1,
			"Jintsuu, what should I do?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[302129] = {
	hp_warning = "Sorry to say... but I can't afford to be defeated here!",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Where'd I put my bandages... Oh, right, don't need 'em anymore... Totally forgot.",
	home = "Nice work. Want some sweets? You can have some of mine. They're all stuff I personally like, though.",
	unlock = "Hmh. Guess I won't be needin' these bandages anymore. Commander, how about we find out how strong I've gotten... by having you take one of my punches?",
	touch2 = "Hold still, Commander. We're pals, so I'll only hit you with 80% of my full strength!",
	mission = "",
	vote = "",
	drop_descrip = "Hmh. Guess I won't be needin' these bandages anymore. Commander, how about we find out how strong I've gotten... by having you take one of my punches?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Violence is the only solution I know of for my problems. That's why I envy you and Jintsuu sometimes.|Whenever I try to be like Jintsuu and use logic to solve problems, I usually end up using my fists anyway. I dunno why, either...|Hardships don't get under my skin, but I'm scared that I'll one day lose my way...",
	touch = "",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Sorry to say, but this is where you'll all die!",
	id = 302129,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "You're back, huh? Focus on your work. Gimme a shout when it's time to sortie.",
	detail = "Yeah? Oh, I'm working on my sortie pose. When goin' to war, you need a war pose, y'know?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[302130] = {
	hp_warning = "",
	feeling3 = "Commander, it's okay to respect my opinions, but please have confidence in your own judgment. I wouldn't be standing by your side if I didn't believe in you.",
	mail = "Commander! It's important to respond to messages promptly!",
	expedition = "Stop daydreaming! Commissions have returned!",
	win_mvp = "Is that it?",
	home = "Books cannot teach you everything. Some things can only be picked up through live combat. What do you think, Commander?",
	unlock = "The battlefield can change at any second. Think rationally and act cautiously so that you may never be defeated in battle. Commander, have you been able to achieve this? Flagship of the Second Torpedo Squadron, Jintsuu, reporting for duty.",
	touch2 = "You've got more guts than I expected, Commander. Do you have the heart to face the consequences, though?",
	mission = "Your new missions have been sorted. Please take a look.",
	vote = "",
	drop_descrip = "Sendai-class No. 2 light cruiser, Jintsuu.",
	feeling4 = "Commander, why do you think those famous generals of the past were willing to bow to their superiors? Was it the limit of their abilities, or was it devotion to their leaders? In my case, perhaps a bit of both.",
	lose = "All ships, retreat! Do not make meaningless sacrifices.",
	feeling1 = "You might as well just leave the fleet management to me.",
	skill = "I've been waiting for this moment!",
	upgrade = "Should we consider advancing deeper into enemy territory?",
	propose = "Deciding on the best course of action before acting cautiously has always been my creed. I can now say with confidence that choosing you, Commander, was the correct decision.",
	feeling5 = "Real leaders will always stick to their guns, no matter who opposes them. You can tell if their methods are correct by seeing who is willing to follow them. For example... me...",
	main = "If being cautious is considered cowardice, then shouldn't being brave also be considered recklessness?|There is no single solution for everything. Only through comparison, practice, and even failure, can one find their own correct answer.|Even if others don't understand my actions, I'll always do what I think is right... Even if you don't understand, Commander.",
	touch = "What's the matter? I'm just thinking about how to manage the fleet.",
	voice_key_2 = -1,
	mission_complete = "Rewards are here... Hmm? Don't worry. I'm just thinking about how to make our fleet more efficient.",
	battle = "All ships, charge forward!",
	id = 302130,
	gift_dislike = "",
	gift_prefer = "Thank you very much.",
	profile = "I'm Sendaii-class ship No. 2, Flagship of the Second Torpedo Squadron, Jintsuu. People have criticized me for being a coward, but I proved myself in the Battle of Kolombangara. Let me show you the glory of the Second Torpedo Squadron once more.",
	voice_key = 30213,
	headtouch = "",
	feeling2 = "I was a flagship before, but now I'm just a common warrior. Please treat me the same as you would the others.",
	login = "Commander, how you spend your time off-duty is no business of mine. Once you arrive, however, please do your work properly.",
	detail = "For the next operation, we need to allocate resources, and... Yes? Ah, help yourself, Commander.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[302131] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Here, iced coconut water. Please have some.",
	unlock = "Hmm? Is it unusual? Hah. Even I require a change of pace to clear my mind every so often. Commander, why don't you come out and get some fresh air as well?",
	touch2 = "You can't concentrate on your work when I'm wearing a swimsuit, right? Hehe, just consider this a test of will then.",
	mission = "",
	vote = "",
	drop_descrip = "Hmm? Is it unusual? Hah. Even I require a change of pace to clear my mind every so often. Commander, why don't you come out and get some fresh air as well?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "If you relax too much, you'll become undisciplined. If you're too uptight, you'll only find yourself out of breath. |Every year when it is swimsuit season, I can't help but to be envious of Sendai... Commander, I'm not being negligent in my exercise, am I? |Commander, your mind has wandered off onto the beach, hasn't it? It’s written all over your face.",
	touch = "Commander, you're concerned about it too, right? My tail is so conspicuous in this swimsuit...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 302131,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "After we finish work today, how about taking a break on the beach?",
	detail = "I said I was taking a vacation, but even out here on the beach, I'm still thinking about the affairs of the fleet... I really am a workaholic, aren't I?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[302132] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Maybe I should gobble you right up.",
	home = "Well done. I'll evaluate your battle plans for you, just like you evaluated my acting skills for me.",
	unlock = "\"Where do you think you're going so early in the morning, Little Red Riding Hood?\" ...Oh, if it isn't the Commander. This might be my own little whim, but I often find myself thinking the same way as this character... If you don't mind, I'd like to hear your feedback about my acting.",
	touch2 = "And, checkmate. Hehehe~",
	mission = "",
	vote = "",
	drop_descrip = "\"Where do you think you're going so early in the morning, Little Red Riding Hood?\" ...Oh, if it isn't the Commander. This might be my own little whim, but I often find myself thinking the same way as this character... If you don't mind, I'd like to hear your feedback about my acting.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "The moment you plan on striking down your prey is the moment you should be most alert. One can never know when a hunter might try to use the opportunity for their own benefit.|Speaking of hunters, none are better suited for the role than Sendai. I really wouldn't want to make an enemy out of her, even if it's just an act.|Hmm... I know I have it down in my head, but when I start to act it out, I keep running into trouble. Do you have any advice for me, Commander?",
	touch = "This outfit? ...Oh, it's what I have on before I turn into the grandmother.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 302132,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Even in fairytale-esque stories, there are hints of deception and trickery hidden throughout. Basically, make sure to stay on guard as you usually do...Hehehe♪",
	detail = "If you think about it, the Big Bad Wolf's plan has so many holes in it. For example, he could have left the grandmother alive and used her as bait... Ehehe, I'm just playing around.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[302139] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "I only gave the orders, the real credit goes to the fleet!",
	home = "",
	unlock = "Since I've gotten used to living with you, Commander, I've decided to be more laid-back after receiving my remodel. My dance? Hehe... I can't show that to just anyone so easily.",
	touch2 = "Commander, please do not mistake my cautiousness for tolerance.",
	mission = "",
	vote = "",
	drop_descrip = "Since I've gotten used to living with you, Commander, I've decided to be more laid-back after receiving my remodel. My dance? Hehe... I can't show that to just anyone so easily.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "I can always work harder for the fleet!",
	propose = "",
	feeling5 = "",
	main = "Sometimes it's hard to prove to others that what you believe is right. Commander, let's do our best together!|Every now and then, I get a bit jealous of {namecode:38} and how straightforward she is...|Even though some people may think that cautiousness is a sign of weakness, I'll be happy as long as our fleet truly understands me...",
	touch = "There's nothing wrong with wanting to see me dance... I'll show you, but only if you work seriously first!",
	voice_key_2 = -1,
	mission_complete = "Rewards have been issued! Want to see something interesting now that we can take it easy?",
	battle = "Everyone, get ready! ... Press forward!",
	id = 302139,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Did you sleep well, Commander? Do you need any help with fleet administration?",
	detail = "Commander, do you have any tactics you'd like to discuss with me? If you'd like... we can also just sit down and have a chat.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[302140] = {
	hp_warning = "Everyone, stay calm! Let's change our strategy!",
	feeling3 = "What are my hobbies? ...I don't really have one in particular. But I enjoy reading and training... Oh, would you like to train together with me? Heheheh~",
	mail = "Commander, I have mail for you. I picked it up on the way back from my training.",
	expedition = "I think a commission has been completed. We should go and say thanks to the returning team!",
	win_mvp = "Compared to my goal of surpassing my sisters, this is no big deal at all!",
	home = "There's nothing better than getting to come back home. Wouldn't you agree, Commander?",
	unlock = "Nice to meet you, Commander! I'm the light cruiser Naka! My sisters are better known than me, but I swear that one day I'll be even more famous than them!",
	touch2 = "Eek! ...Please, Commander, try to stay focused on your work while in the office!",
	mission = "I reorganized the mission list for you! Here, please choose one!",
	vote = "",
	drop_descrip = "Sendai-class light cruiser number three – Naka.",
	feeling4 = "Hmm, I feel a little guilty over always making you come with me... Is there anything you'd like to do? We'll do it together, of course!",
	lose = "Oh no! Commander, we should retreat immediately! Jintsuu said we shouldn't make meaningless sacrifices!",
	feeling1 = "My sisters chose you because you just let them mess around without being scolded? How strange...",
	skill = "I'm really powerful, you know!",
	upgrade = "With your support I can work even harder!",
	propose = "You can stare as much as you'd like. Hehehe~ From now on I will use my brains and brawn to serve you, my sweetheart whom I love so much!",
	feeling5 = "Huh? Are you saying you've been waiting for a chance to go on a date too? Heheh, in that case~ Why don't we do it, Commander?",
	main = "If it looks like there's nothing for me to do, would you mind if I did a little training on my own? I won't get in the way of your work!|Jintsuu is wise, Sendai is strong... but I'll work my way towards both brains and brawn! ...Ahahah, though I'm not sure if I can actually do it.|If you're tired, would you like me to give you a good relaxation tip? I actually know quite a lot about it~",
	touch = "Hum hum~♪ Oh, sorry, am I disturbing you in the middle of work...?",
	voice_key_2 = -1,
	mission_complete = "You've cleared another mission! You're so brilliant, Commander! I'll need to work just as hard!",
	battle = "My sisters, please look forward to my performance in battle!",
	id = 302140,
	gift_dislike = "",
	gift_prefer = "Thaaanks! I really appreciate it!",
	profile = "I'm Naka, Sendai-class light cruiser number three! Due to certain circumstances, my construction was delayed, I was redeployed to place after place, and my service record as the flagship of Desron 4 isn't much to brag about... but that's okay! I'll still work my butt off to try to surpass my sisters!",
	voice_key = 30214,
	headtouch = "",
	feeling2 = "What I do on my days off? Well, I get up and do morning training, I read for an hour, I do target practice for 2 hours, and then... Basically, I make full use of my vacation days! I have to work really hard to become stronger, you know?",
	login = "Welcome back, Commander! I'll try to be the best secretary you've ever had!",
	detail = "Commander, would you like to study together with me?",
	couple_encourage = {
		{
			{
				30212,
				30213
			},
			2,
			"I want to shine as gloriously as you, my sisters!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[302141] = {
	hp_warning = "",
	feeling3 = "",
	mail = "C-Commander?! We just got a message in a bottle!",
	expedition = "",
	win_mvp = "",
	home = "There's no way to keep this tail from getting in the way when I'm swimming, huh... Wait! I'm sure Sendai knows a way around it!",
	unlock = "Ahaha! Another big one's coming~! Phew~ that felt amazing~! Ah, Commander, let's hit the waves together, shall we?",
	touch2 = "Commander... if you do this kind of stuff on the beach, all the girls will hate you, you know?",
	mission = "Eh? Jintsuu, you even brought the mission documents along?",
	vote = "",
	drop_descrip = "Ahaha! Another big one's coming~! Phew~ that felt amazing~! Ah, Commander, let's hit the waves together, shall we?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Surfing is pretty fun once you get the hang of it, right? What do you think, Commander? Wanna go on a surf date with me?",
	main = "Sendai, how'd you split that watermelon blindfolded...?! Th-that was so cool...! |I'm sure Jintsuu will be writing some report like \"The Status of the Waves and Water in this Sea Region\" after our vacation is over. Hahaha! |It sure feels nice to just float around and let the waves sweep you away~",
	touch = "Hehe, Commander~ Did you just offer to give me a massage~?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 302141,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "We've gotta warm up before hitting the waves! C'mon, Commander, don't keep me waiting!",
	detail = "I heard that surfing is a great way to sharpen your motor skills, especially your sense of balance! C'mon, let's give it a try!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[302200] = {
	hp_warning = "Dear me, it seems things have gotten rather serious.",
	feeling3 = "Commander, why don't we have a chat? Yes, I'm curious as to what kind of person you are.",
	mail = "Are you sure this isn't a love letter from that girl you know? *Giggle*♪",
	expedition = "Commander, the girls that went on a commission have returned. If you keep twiddling your thumbs, you'll miss your chance to welcome them back...",
	win_mvp = "Did you witness my performance?",
	home = "Commander, fantastic work on the last sortie. May I offer you some hot tea?",
	unlock = "Are you the Commander? My name is Agano. The pleasure is all mine, *giggle*... Never mind that, it was nothing. I'm eager to assume my position within your fleet.",
	touch2 = "Oh, Commander~ *Grin*",
	mission = "I went ahead and sorted out the new mission documents.",
	vote = "",
	drop_descrip = "Agano-class light cruiser number one – Agano.",
	feeling4 = "Me? I'm fond of interesting things. Such as... the act of toying with you, Commander... *Giggle*, you'll have to excuse me for that~",
	lose = "How careless of me... I will undergo special training when we've returned. *Giggle*.",
	feeling1 = "Even breathing the same air as you do is unpleasant, Commander~",
	skill = "They don't call me \"state of the art\" for nothing~",
	upgrade = "Please, have faith in the skill of this Agano-class light cruiser.",
	propose = "You have feelings for me, Commander? You wish to be with me forever? ... Why am I asking the questions here? *Giggle*, because, even for someone like me, wouldn't it be humiliating to have someone else take the initiative at moments like these...?",
	feeling5 = "Someone who toys with the person they like... Are you familiar with anyone like that, Commander? *Giggle*, perhaps it's me~",
	main = "Commander, if you're tired, why not play a game of leapfrog and jump around in the office? It'll help improve your blood circulation~|Though supporting from behind the lines is easy, doing so for long periods makes me grow tired of it...|Commander, are you in need of some rest? Hm? *Giggle*, I just felt like asking. Stay focused and continue your work~",
	touch = "These documents are for me... Hm? That's unusual? I like to keep business and pleasure separate, you see.",
	voice_key_2 = -1,
	mission_complete = "Commander, if you keep tasking your secretary with collecting the mission rewards, your brain will eventually turn to mush. Although, it might be interesting if that happened... *Giggle*♪",
	battle = "Let's give it everything we have.",
	id = 302200,
	gift_dislike = "",
	gift_prefer = "Oh my... Thank you~",
	profile = "I am Agano, the lead ship of the Agano-class. My abilities as a light cruiser are first-rate, though my birth was just a tad bit late... Commander, it is a pleasure to be in your service.",
	voice_key = 30220,
	headtouch = "",
	feeling2 = "I wonder what will happen today... *Giggle*, I'm looking forward to finding out.",
	login = "Commander, it's not yet time for work. Are you confident you didn't get the time wrong?",
	detail = "Ah, if it isn't you, Commander. I was just making a snack. Could you taste it for pois... I mean, taste to see if it's done?",
	couple_encourage = {
		{
			{
				30204
			},
			1,
			"If you want to mess with Nagara, first you must get through me~",
			0
		},
		{
			{
				30221
			},
			1,
			"Noshiro, you'll have to develop a better relationship with the Commander.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[302201] = {
