_G.pg.base.ship_skin_words[302202] = {
	hp_warning = "",
	feeling3 = "",
	mail = "More mail, huh... You're quite the popular one. Hmph~",
	expedition = "",
	win_mvp = "Commander, it's more fun to play around this way~",
	home = "You must be tired, right? Here, if you'd like, you can come lie down over here.",
	unlock = "\"Oh my, you're also out for a stroll? Hehe, my name's Agano. And what might yours be?\" ...Jeez, Commander, take this more seriously. According to the setting, we just met for the first time.",
	touch2 = "Manhandling a girl who you barely just met... Heeh~ Commander, I didn't know you were that kind of person~",
	mission = "",
	vote = "",
	drop_descrip = "\"Oh my, you're also out for a stroll? Hehe, my name's Agano. And what might yours be?\" ...Jeez, Commander, take this more seriously. According to the setting, we just met for the first time.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Why'd I ask you to play a dating game? Well, if I teased you too much, wouldn't that only make you dislike me? But since I can't help it, I decided to make it up to you this way~ Do you think better of me now, Commander? ",
	main = "You haven't had anything to eat? If you'd like, you can have some of my crepe~ |\"Um... do you mind if I shift a bit closer to you? It's a bit chilly out here...\" What am I after? Jeez, way to spoil the mood... |\"Would you mind telling me more about yourself? I feel like... we have a lot in common~\" ...Hehe, in other words, I want to learn a lot more about you!",
	touch = "\"Want to take a stroll with me?\" *sigh*... It took me five minutes just to get you to ask me out. Commander, you have to take the initiative next time, got it?",
	voice_key_2 = -1,
	mission_complete = "All done with the mission? Did you also pick up a crepe for me? Thanks a lot~♪",
	battle = "",
	id = 302202,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "\"Hey, are you here by yourself? Hehe. Why don't we... have a little chat, then?\"",
	detail = "This super-cute girl was sitting on a bench all by herself while looking a little lonely~ But too bad this scaredy-Commander won't even pounce on the opportunity~",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[302203] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "My, Commander, you look simply resplendent when you return from battle... I'm once again head over heels for you. I mean it.",
	unlock = "The blunt approach is not my style, but I cannot have Noshiro think I only inch my way to success... Oh, I was just talking to myself, Commander. Hehe, so anyway, would you mind being my partner for tonight's party?",
	touch2 = "",
	mission = "You certainly are greeting many people tonight, Commander.",
	vote = "",
	drop_descrip = "The blunt approach is not my style, but I cannot have Noshiro think I only inch my way to success... Oh, I was just talking to myself, Commander. Hehe, so anyway, would you mind being my partner for tonight's party?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I am an... enigma to you? Why, I would say that you're the enigmatic individual between us, Commander. And yet, that makes one want to get to know you better, the sinful person that you are. Hehehe~",
	main = "Come to think of it, I haven't seen Noshiro around... Knowing her, she may be off on her own somewhere...|Say, Commander, would you care for a drink? Me? Well, I can hold my liquor at least as well as you. Heheh.|Please, Commander, you need not look so on-edge. I may enjoy teasing you, but I'm not so brash as to do it on this special occasion.",
	touch = "",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 302203,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Well, well. Were you hoping to fluster your lady by arriving late on purpose, Commander?",
	detail = "The competition tonight is considerably fiercer than I anticipated... This calls for a counterattack... Oh, it was nothing important. I was just thinking out loud about how, uh... fabulous that chandelier is.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[302210] = {
	hp_warning = "An enemy trap?!",
	feeling3 = "An invitation to a joint practice session together from Agano... How troubling. It's full of intent to bully. Even though I want to refuse, I can't think of an excuse. Instead, would you be willing to assign some official duties to me around that time?",
	mail = "Mail? I'll check to make sure there's nothing suspicious inside.",
	expedition = "Please form the next commission team, okay?",
	win_mvp = "If you lead with careful analysis and accurate decision-making, your victory is ensured.",
	home = "Hm... Ah, sorry. I was lost in thought. So you've returned. Let's start by reviewing this past battle.",
	unlock = "I'm the new arrival, Noshiro, second ship of the Agano-class, reporting for duty. Let's do our utmost to prove our worth to each other, shall we?",
	touch2 = "R-Regarding your conduct right now, I demand that you apologize and reflect upon your actions!",
	mission = "If you feel overwhelmed by the number of missions, why not try sorting them based on priority?",
	vote = "",
	drop_descrip = "Agano-class light cruiser number two – Noshiro.",
	feeling4 = "Ahem. I'm only asking this because I keep hearing my friends use the term over and over, but... out of curiosity, what exactly is this concept called `a woman's intuition'...? \"I have absolutely no clue,\" you say? I see. I guess it's an enigma to you, too.",
	lose = "We have no choice but to pull back...",
	feeling1 = "You seem to be in quite the hurry. For once, why don't you try calming down and reflecting upon your actions?",
	skill = "Now's the time!",
	upgrade = "Please, strengthen my combat ability.",
	propose = "In order to not just accept your feelings, but to reciprocate them as well... Umm, let's see... I'll need to prepare meals, go on dates on days off, but I also need to make sure I don't lose motivation for my regular duties, like practice... Eh? Ah, sorry, I got lost in my train of thought. Huh? I-I should keep going?",
	feeling5 = "So this is what it feels like to have your heart throb. While I used to be just as inexperienced with this feeling as I was experienced with being perceptive and relying on my instincts... Yes, it's all clear to me now. My feelings, as well as yours.",
	main = "...Let's try thinking of some recipes for tomorrow's meals... | Keeping everything neat and tidy shortens the time it takes to search for documents. Why don't we start by organizing the documents on your desk? | Agano's exp... Yes, it's truly impossible to tell what's behind that fearless smile... She always ends up leading me around by the nose.",
	touch = "If you're stuck, why not stop what you're doing, and instead, think of a different way to proceed?",
	voice_key_2 = -1,
	mission_complete = "I've received the mission rewards. Please double check that nothing has been left out.",
	battle = "Please look over the battle plans, just to double check.",
	id = 302210,
	gift_dislike = "",
	gift_prefer = "I... I'll cherish this!",
	profile = "Just as Agano says, the great war in which we were born may have been an era of misfortune. ...No. As a member of the improved Agano-class, I should be able to make you satisfied with my work, if only there was just a place I could display my true strength. ",
	voice_key = 30221,
	headtouch = "",
	feeling2 = "I am currently contemplating over the last practice exercise. Do you not also have things you should be doing right now?",
	login = "My, you're quite early today. For starters, how about checking today's schedule?",
	detail = "Regardless of the situation, you should first calm down, think of a way forward, and only then act. That's how I tackle things.",
	couple_encourage = {
		{
			{
				30220
			},
			1,
			"Agano, please be careful.",
			0
		},
		{
			{
				10707,
				10708
			},
			2,
			"Um... mind keeping a safe distance?",
			0
		}
	}
}


