_G.pg.base.ship_skin_words[302212] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Though it might not seem that way, we're actually pretty close to the Port. Shall we go and greet the Commissions Team?",
	win_mvp = "In the face of well-crafted plans, resistance is futile. Accept your defeat.",
	home = "Once you've rested up, why don't we go and make our appearance at the party together?",
	unlock = "Commander, what are you standing around for? Did you also need a change of pace? That makes two of us— Come, there's nothing to be afraid of here.",
	touch2 = "Excuse me... How about I give you a massage... with this?",
	mission = "",
	vote = "",
	drop_descrip = "Commander, what are you standing around for? Did you also need a change of pace? That makes two of us— Come, there's nothing to be afraid of here.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Hmm, I wonder what kind of scene this set is supposed to depict. A birdcage, crows, the sea, blue roses, and... you beside me... Um... Don't you think this is quite picturesque?",
	main = "Wah! ...Sorry. I can't believe I almost fell... Um... T-Thank you for catching me...|It's a given that I love the atmosphere here, but another reason I like this place is that I feel like I can finally get away from Agano's endless teasing here... Though, I'd rather she just stop worrying about me in the first place...|This is yet another massive set built right in the Port. Yes, it's incredibly gorgeous... Honestly, when I saw it for the first time, I forgot I was in still in the Port for a moment. Speaking of which, didn't you also stand and stare in awe when you first came here?",
	touch = "Hehe. I think even Agano would take a liking to this place, too.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Freeze, and turn to ice... Your time is up.",
	id = 302212,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Phew... Go on, fly away, little ones. Mind the cage on your way out, now... I've been taking care of these guys. What have you been up to?",
	detail = "Don't worry. There's nothing for you to worry about. All the preparations for the party and the related formalities have all been taken care of. All that's left for you to do is to enjoy the evening while savoring this beautiful scenery.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[302213] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome back. Oh... I know you're thirsty, but the tea's a bit hot. Take care not to burn yourself.",
	unlock = "Whew... Oh, are you cold by any chance? I have some hot tea for you if you'd like. If you want someone to chat with, I'd be glad to keep you company.",
	touch2 = "Sigh... Of course you would do that.",
	mission = "",
	vote = "",
	drop_descrip = "Whew... Oh, are you cold by any chance? I have some hot tea for you if you'd like. If you want someone to chat with, I'd be glad to keep you company.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Though the snow has piled up this much, it'll all melt with the coming of spring—becoming water that will nourish nascent life. I don't think I can remain cold like this for much longer, either. After all, before I was able to notice... spring has managed to start creeping into my life, too.",
	main = "You still haven't taken a sip yet. Is it too hot? ...Are you perhaps bad with hot things?|It's not like I'm opposed to going into battle as a warship, but... I'd really like to save people as well. Much like Hamakaze's always done.|The Manjuus' teapot is astonishingly authentic. I don't see any problems with adding one to the Office for daily use, either. Hehe.",
	touch = "There's really no reason to push yourself to get some work done today. It's a precious day off, so why don't you enjoy it for a change?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 302213,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "It's good to see you. How should we start the day off?",
	detail = "I like staying in places that are quiet and peaceful. They make me feel relaxed. The whisperings of the wind, the sound of flowing water, the harbingers of spring, and Commander's... Ehem, I-I didn't mean anything by that.",
	couple_encourage = {}
}


