	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "A cool summer's day in the forest~ One for me, one for you, and halfsies for the bears~ Ehehe, welcome back!♪",
	detail = "Aww, you came to see me again! Are you sure you want to spend time with me, and not Noshiro? Heheh, do you feel guilty? It's okay~ We can always make it up to Noshiro after we have fun together♪"
}


