_G.pg.base.ship_skin_words[302240] = {
	hp_warning = "Brace yourselves, everyone!",
	feeling3 = "This is exclusive Alizarin merch and my autograph... Would you like to have them? Heehee, it's nice to be a little childish once in a while.",
	mail = "A letter...? Is it a new concert mission?",
	expedition = "The commission is complete. Just as you planned.",
	win_mvp = "With my singing voice and the courage given to me by the Commander, I cannot lose!",
	home = "Nnh... Zzzz... Ah, C-Commander... Welcome back. I'm sorry, I just fell asleep... Do you have a new training mission for me?",
	unlock = "Agano-class ship number two, Noshiro, will now begin the Muse System test. I'll put my all into both my idol work and my mission, so you have no reason to worry.",
	touch2 = "Please... cut it out...",
	mission = "Do you need my help completing your missions, Commander? Heehee.",
	vote = "拉票描述",
	drop_descrip = "Agano-class ship number two, Noshiro, will now begin the Muse System test. I'll put my all into both my idol work and my mission, so you have no reason to worry.",
	feeling4 = "You think I look cool when I sing? Th-thank you. Does that mean I'm still far from being consistent, though... Haha, I thought you might say that. You love praising me, don't you? *blush*",
	lose = "Did I not train enough after all...?",
	feeling1 = "Commander, this course of action will have negative effects on my training.",
	skill = "Now's my chance!",
	upgrade = "I'm becoming even more refined.",
	propose = "This day came so much sooner than I expected. ...I know. You're ready and raring for us to move on to greater heights, aren't you?",
	feeling5 = "This... is special merchandise just for you. Please take it... The red mark there is, umm... I kissed... Never mind! It's nothing!",
	main = "I'm an idol, so I need to be even more mindful of my nutritional balance... Say, why don't you let me plan your meals for you too, Commander?|Improvising is great and all, but doing things without a plan does make me uncomfortable...|It's important to rest between your work, okay? Want me to bring you tea? Don't worry, I won't make it too hot.",
	touch = "Commander, you did that for the sake of instruction... right?",
	voice_key_2 = -1,
	mission_complete = "Mission accomplished. You really are a reliable help.",
	battle = "Fight just like we rehearsed!",
	id = 302240,
	gift_dislike = "",
	gift_prefer = "Thank you. I'll cherish this gift.",
	profile = "To meet Agano's and your expectations of me, I, light cruiser Noshiro, will do my best to complete this idol training mission. ...Was that good? Are you satisfied with me as a member of Alizarin?",
	voice_key = 30224,
	headtouch = "Hm? My hair's messed up? Thank you for telling me.",
	feeling2 = "Thank you for coming all this way to see my lesson. ...So? Was there anything I could do to improve my performance? Heehee.",
	login = "Welcome back, Commander. I finished drawing up today's lesson plan. See? Oh... You say this is your job, not mine?",
	detail = "Calmly reflect upon the lessons you've learned, and even a momentary performance will shine eternal. That is the kind of idol that I aspire to become.",
	couple_encourage = {
		{
			{
				20714
			},
			1,
			" Let's do our best together.",
			0
		},
		{
			{
				40315
			},
			1,
			" I'll do my best, too. You don't have to tell me!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[302250] = {
	hp_warning = "Ngh... I can't fall... Not here!",
	feeling3 = "I come to this courtyard often. Watching the flowers and birds, listening to the shishi-odoshi... Through this, I calm myself and nourish my spirit to hone my swordplay for the coming battle. Aren't you bored just sitting here, though? If there's anything you want to do, I'm all ears.",
	mail = "The pattern on this envelope's wax seal might work on a skirt... Oh, I'm sorry. Just spaced out a little. Here's your mail, Commander.",
	expedition = "Commander, the girls on commission have returned to port. Let's go meet them. Supplies are vital on the front lines of war.",
	win_mvp = "I'm happy that my blade could bring you victory, Commander.",
	home = "You've done great work, Commander. If you're tired, why not sit down and rest for a while? Whether you're commanding a battle or practicing martial arts, rest is vital.",
	unlock = "I am light cruiser Watarase of the Sakura Empire. It is a pleasure to meet you, Commander. With this blade, I shall protect the honor of the fleet.",
	touch2 = "Oh?! Commander, do you dislike my modifications here...?",
	mission = "Take your missions seriously, please. Oh, but don't forget to take regular breaks. I'll be sure to remind you.",
	vote = "",
	drop_descrip = "Type C44 light cruiser – Watarase.",
	feeling4 = "You're still stuck on work? Being faithful to duty is a good thing, but relaxing and letting yourself recover is important. Here's a sachet I made. It'll calm your nerves and help you sleep... Go ahead and put it on, please.",
	lose = "We must retreat! Hurry, before anyone else gets hurt!",
	feeling1 = "Your taste in attire is a little worrying...",
	skill = "With flowing shadow, pierce the waves!",
	upgrade = "This training session came with remarkable results. Phew... How about we all head to the training grounds and spar a little?",
	propose = "Commander, do you know the legend of Princess Shirataki? The promise made between the weaving princess and her lover, the korinseki stone that witnessed it... What you just put on is our own korinseki. May this ring oversee our love to the end.",
	feeling5 = "I made this charm for you, Commander. It'll protect you and ward off evil. Heheh, it's not enough on its own... but don't worry. I will train harder and endeavor to protect you with my blade as well.",
	main = "Did you lose a button? I'll sew it back on, so just stay still for me. Oh... We're a little close, huh? M-maybe you should take your shirt off instead...?|Hm? I'm sharpening my blade right now, so please be careful. It'll hurt if you bump into it.|If you're having trouble focusing, then how about a break? Efficient work only comes from ample rest.|Are you curious about this? This is a bill for a commissioned kimono from Akashi. As for the price... Er, let's keep that a secret.",
	touch = "Hm? Curious about the fabric? If you like it, I'd be happy to make you an outfit with it.",
	voice_key_2 = -1,
	mission_complete = "Good work, Commander. How about a quick massage... Acupuncture? I do use needles often, but not for that... I use them to sew.",
	battle = "Allow me to set the stage for you.",
	id = 302250,
	gift_dislike = "",
	gift_prefer = "Thank you very much, Commander. I really like these.",
	profile = "I'm Watarase, a modified Agano-class light cruiser with the Sakura Empire. My first life ended without fulfilling any expected purpose... but I will use the new power I've been given to protect you and yours, Commander.",
	voice_key = 30225,
	headtouch = "This hair accessory might look unusual, but I actually made it myself.",
	feeling2 = "My blade has no past – it descended unto the material world alongside me. However, its reason for existence is clear. It is here to aid me in protecting the people I love.",
	login = "Commander, how about a cup of tea or coffee before work? I always have a cup before training... It helps me focus and regulate my mood.",
	detail = "Hmm? My sleeve? Heehee, I made some corrections to it for aesthetics' sake. Don't worry – it won't get in the way in battle.",
	couple_encourage = {
		{
			{
				30311
			},
			1,
			" Let's compete together at a more suitable time!",
			0
		},
		{
			{
				20704,
				60302,
				30707,
				10808
			},
			1,
			" I'd love to see your latest clothing design.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[302251] = {
	hp_warning = "",
	feeling3 = "",
	mail = "There's a letter for you, Commander. If it's an invitation to a dance party, then may I join you as your partner?",
	expedition = "Commander, the commission team brought back spare fireworks.",
	win_mvp = "",
	home = "Dancing is no easier than combat training. You must be tired, too, Commander. Please, come rest in my pumpkin carriage with me.",
	unlock = "Commander! Oh... Umm, perhaps it would be more fitting to address you as \"Milord\" for this occasion? Since, you know, the two of us have the evening together... Now, if you don't mind, your hand please — Heehee, make sure to sit tight!",
	touch2 = "Umm... P-people will see us here...",
	mission = "You're still working? But it's time for your break... Fine, I'll just have to help you. Once we're done, we're going to have fun together, got it?",
	vote = "",
	drop_descrip = "Commander! Oh... Umm, perhaps it would be more fitting to address you as \"Milord\" for this occasion? Since, you know, the two of us have the evening together... Now, if you don't mind, your hand please — Heehee, make sure to sit tight!",
	feeling4 = "",
	lose = "I'll need to improve the mobility of this outfit...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Commander, listen – the clock just struck midnight! But my magic won't disappear like in the fairy tales, and you won't have to search for me, my prince. I'll find you, return to your side, take your hand, and weave the perfect tale just for us!",
	main = "Is the carriage uncomfortable? This is my first time designing anything other than clothes, so there were a lot of unknowns...|What if I just spirited you away in my carriage to watch the fireworks together? A little too selfish, perhaps?|Want to guess what spell the fairy cast on me? Okay, I'll tell you. It lets me find you no matter where you are... Heehee, just kidding.|Am I blushing? I-it's probably because of this... I do feel a little tipsy. Mind if I lean on your shoulder...?",
	touch = "Would you like to dance under the night sky? Just take my hand, Commander♪",
	voice_key_2 = -1,
	mission_complete = "Now that we're done with all that work, it's time to focus on enjoying the fireworks show♪",
	battle = "",
	id = 302251,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "I made this crown to match my outfit, too~",
	feeling2 = "",
	login = "Commander, it's time for the fireworks to start. Let's leave our work and daily training until after they're done, okay?",
	detail = "I designed not just this outfit, but the carriage as well. Heehee, isn't it as dreamy as a fairy tale?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[302260] = {
	hp_warning = "Oww... That hurts...",
	feeling3 = "I pray for your safety and happiness... This prayer isn't just for the sake of duty. It's... what I really want...",
	mail = "The mail for you is right here. Do you like traditional letters, too...?",
	expedition = "The commission team brought back so many supplies... I-is it because of my prayers, you think? Th-thank you! I'll keep doing my best to help out!",
	win_mvp = "Commander, the fleet has seized victory, and everyone made it home safe! Thank goodness...",
	home = "C-Commander... You're not hurt? I made yomogi mochi! And... I even grew the mugwort myself! Umm, my little bunnies thought it was good, too!",
	unlock = "P-pleased to meet you, Commander... My name is Ayase, of the Sakura Empire... Umm, y-yes, once again, it's an honor to be here! I l-look forward to working with you! Ah! Umm, yes, I brought my pet bunny here... Good girl, good girl, go say hello to the Commander...",
	touch2 = "Hyah?! Wh-what? D-do you find this part of me strange, too...?",
	mission = "Commander, h-have you finished your work? Oh, it's not like I doubt you... I'm just wondering if you're tired.",
	vote = "",
	drop_descrip = "Sendai-class light cruiser – Ayase.",
	feeling4 = "I have to confess... I once prayed that you'd give me attention over the others... It looks like that came true, huh? I'm really happy... Ooh...",
	lose = "Aah... Commander, we need to retreat right away...",
	feeling1 = "C-Commander, you're scary... Eep...",
	skill = "Urgh... I'll do my best!",
	upgrade = "Yes... I-I'll keep trying harder and harder!",
	propose = "C-calm down, Ayase...! C-Commander... I'm really, REALLY happy! Just once, give me this one opportunity to pray for us... *inhale*... *exhale*... \"May our love continue as long as we breathe!\"",
	feeling5 = "Phew... If this is your desire, Commander, then I... I offer a dance of blessing to you! May it bring you safety and happiness... Here goes!",
	main = "I do want to talk with everyone more, b-but... I always mess it up. Can you help me practice, Commander?|C-Commander... Umm... My bunnies want to stay here with us. Is that okay...? Th-thank you! They're grateful, too!|Commander... Would you like to go hiking with me? Chatting with the critters in the mountains is r-really fun...",
	touch = "You want to hug my bunny, too...? O-okay! She says she wants to give you a big hug, too!",
	voice_key_2 = -1,
	mission_complete = "Yes, I've received all of your mission rewards for you. Please, take a look...",
	battle = "Safe and healthy return, hale and hearty... S-setting sail now!",
	id = 302260,
	gift_dislike = "",
	gift_prefer = "Thank you very much, Commander! I really like it! Oh, and the bunnies seem to as well!",
	profile = "I-I'm Ayase, a Sakura Empire light cruiser... I was originally planned to be Sendai-class, but I was canceled... So I'm very happy to be in your fleet now, Commander! I'll... I'll do my very best!",
	voice_key = 30226,
	headtouch = "Thanks to you... I feel a lot more confident now, Commander! Th-thank you so much!",
	feeling2 = "Commander, do you want to see me d-dance? I-I'll do my best! But... not now!",
	login = "Be good, don't run around so much... C-Commander?! Welcome back... Uh, umm, would you like to drink some carrot... I mean, eat some tea... o-oh, what am I saying...",
	detail = "Ah, I can't see down to my legs... Urk... Hwuh?! C-Commander? Were you watching...? I'm sorry. I shouldn't have been training here... It's embarrassing to know that people can see me.",
	couple_encourage = {
		{
			{
				39907
			},
			1,
			"Daisen, your hair... Are you a bunny?",
			0
		},
		{
			{
				10117
			},
			1,
			" What is a \"Planet Bunnyian,\" exactly...?",
			0
		},
		{
			{
				31901
			},
			1,
			" They make your shoulders stiff, too, right? Same!  ",
			0
		}
	}
}


_G.pg.base.ship_skin_words[302261] = {
	hp_warning = "",
