_G.pg.base.ship_skin_words[302270] = {
	hp_warning = "Things are just going to get worse at this rate...",
	feeling3 = "I tried putting different seasonings in my hot pot this time. *sniff*... Hehe, I can smell excitement on you. You always look forward to my new creations, don't you?",
	mail = "New mail came for you, Commander. *sniff*... It doesn't smell weird, so it should be safe to open.",
	expedition = "The commission team finished their job, and I have hot pot ready. Let's go greet them with it and have a big feast together.",
	win_mvp = "Looks like the seasoning of success will be going in today's pot.",
	home = "Welcome back, Commander. *sniff*... You smell like the ocean breeze. Very nice!",
	unlock = "There you are, Commander! *sniff*... Mm, you smell hungry. Don't worry, I'll bring fresh hot pot for you right away.",
	touch2 = "C-Commander! The kitchen is no place for that. Do you WANT me to spill the food?",
	mission = "Commander, you still have untouched missions. Let me help you sort them out.",
	vote = "",
	drop_descrip = "Sendai-class light cruiser – Minase.",
	feeling4 = "*sniff*... You smell really good right now, Commander... (Is it me, or is this smell... possessing me? I want to get closer... It's like I can't think straight anymore.)",
	lose = "Defeat is ever so bitter...",
	feeling1 = "Commander... I made calming hot pot. Would you like some? Umm... I just want you to feel better...",
	skill = "*sniff*... Now!",
	upgrade = "*sniff*... Wow. I can distinguish scents even better than ever!",
	propose = "This is the taste of love... It's more enticing than any other ingredient. Hehe... How blessed I am to know that I'll get to be with you forever, Commander.",
	feeling5 = "Commander, I've been searching for the perfect seasoning that can balance all flavors... and I think I've found it. It's the seasoning called love... When love overflows and simmers into the hot pot, the person you love is reflected in the flavor.",
	main = "Have you ever made hot pot, Commander? What ingredients do you typically use? Call me next time you want to. It's even more fun as a team!|Be a little bold in your selection of ingredients and cooking methods, and you might just discover a new recipe.|(The Commander is making an odd face at my hot pot... Wait. Is the combination of tuna eyeballs and watermelon too much? It tasted good when I tried it, at least.)",
	touch = "Hyah?! N-not my ears, please... Eep...",
	voice_key_2 = -1,
	mission_complete = "It's important to check your rewards, too. After all... you do love them, don't you? *sniff sniff*",
	battle = "Let's end this before my seafood hot pot finishes cooking.",
	id = 302270,
	gift_dislike = "",
	gift_prefer = "*sniff* *sniff*...this smell! It's the thing I've wanted this whole time! Thank you so much, Commander!",
	profile = "I am Minase, a Sendai-class light cruiser of the Sakura Empire, and I'd like to make Sakuran hot pot to warm your heart and soul. Trust me to take care of you from now on, Commander.",
	voice_key = 30227,
	headtouch = "Mm... Hehe. When you pet me, I imagine I must smell like I'm overflowing with joy.",
	feeling2 = "*sniff*... Your condition seems off right now. Are you sure you aren't overworking yourself to exhaustion? I'd better make a meal full of nutrients for you!",
	login = "Great work today, Commander! Hehe, this hot pot helps with fatigue. Give it a try!",
	detail = "Some people say goose barnacles shouldn't go in hot pot, but they taste great if you prepare them properly. I want everyone to try mine!",
	couple_encourage = {
		{
			{
				30212,
				30213,
				30214,
				30226
			},
			1,
			"I brought fresh hot pot for everyone!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[302271] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Zzz... Zzz... Nnh? Commander... Come take a break, would you? It'd be nice to have someone to meditate with.",
	unlock = "Mmmm... That was a nice nap. *sniff*... Oh, Commander? I was just practicing meditation. This is the best place for it. Come and join me, if you'd like.",
	touch2 = "Eep?! C-Commander... Do you like fluffy things? Nnh... S-someone is going to see us if you keep that up!",
	mission = "",
	vote = "",
	drop_descrip = "Mmmm... That was a nice nap. *sniff*... Oh, Commander? I was just practicing meditation. This is the best place for it. Come and join me, if you'd like.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I can start meditating easily when you're here, but if you're not, my mind tends to wander... Maybe the red string of fate has bound us too tightly to ever be untied.",
	main = "When I'm meditating, these cute little creatures all start gathering around me. Heehee... Does this little fox want to train, too?|Huh? You want me to try just jumping down when I leave? Hmm... That would be faster, but I didn't bring footwear. Oh? You'll go down first and catch me? Then... m-maybe we could try...|Did you know that your senses sharpen while you meditate? For example, when you're sneaking glances at me... *sniff*... I can tell~",
	touch = "",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 302271,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Mm, hehehe... Your hands are warm. It's very calming.",
	feeling2 = "",
	login = "The sunlight is warm, the view is lovely... The only thing that could make this better is a nice bowl of hot pot.",
	detail = "Why am I meditating? Hmm... That's a secret. I can share it just with you, but listen – the roof of this shrine is the perfect place for meditation. Lie down here and close your eyes, and you'll discover the secret for yourself.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[302280] = {
	hp_warning = "My lightning... is out of control!",
	feeling3 = "Commander! You didn't get shocked, did you?! I... I merely wished to channel the lightning to aid you, only for it to backfire... Grrgh...",
	mail = "O fated one, I have sorted your letters. It was only a small favor, thus you need not thank me.",
	expedition = "The commission team is back. As my sea maps guided them, their holds must be brimming with treasure!",
	win_mvp = "Our greatest weapon is our maps of the sea!",
	home = "O fated one, the currents whispered to me the time of your return! ...Yes, yes, I admit it! I had but a brief glance at your schedule!",
	unlock = "Kizu is my name, and destiny's hand led me hither to find my fated one... which is you! Heheheh – now bid me welcome with tears of gratitude! ...Why are you silent? Y-you know what – forget I said anything...",
	touch2 = "Eek! N-no... You can't... Mmph...",
	mission = "(Hrmh... My fated one has forgotten about these missions... Should I speak up? Will I be seen as meddlesome if I do?)",
	vote = "",
	drop_descrip = "Sendai-class light cruiser – Kizu.",
	feeling4 = "Heheheh... O fated one, my eyes behold the Thread of Causality that links us. Clearer is it than the trajectory of the stars, and as inescapable as thunder.",
	lose = "This is but a part of my self-cultivation as a messenger of heaven...",
	feeling1 = "I clearly misjudged you...",
	skill = "Kneel before my thunder!",
	upgrade = "My power has at last been made fully manifest... Y-you're not frightened by me, are you?",
	propose = "O fated one, let us swear an eternal vow with the heavens as our witnesses. Every daybreak and every dusk, each moment until all life breathes its last, I shall forever be with you.",
	feeling5 = "Always have I kept these paired magatama with me, and solely to you do I entrust them, my fated one... Just take them! Who else could it be but you? And don't you dare lose them!",
	main = "Such simple work scarcely demands much toil. O fated one, you do know how to implore me for aid, don't you?|O fated one, behold the lightning that runs at my fingertips. This is a manifestation of nature, a– Eek! It shocked me! Urgh... How could this be...|The wind rises from the tip of a blade of grass, a downpour cascading from the sky over yonder... This means rain will come ere long. Be prepared, fated one.",
	touch = "You... You miscreant! Urgh...",
	voice_key_2 = -1,
	mission_complete = "O fated one, the \"cause\" of your missions has borne an \"effect\"... No, I'm merely informing you that it's time to check on your tasks.",
	battle = "Follow me! I shall pave the way for you!",
	id = 302280,
	gift_dislike = "",
	gift_prefer = "A gift just for me? Heheh. How thoughtful of you!",
	profile = "I am Kizu – an agent of the Divine Laws dispatched from heaven. Hm? What laws, specifically, you ask? Hrmh... The Law of Thunder, the Rule of Weather, and, um... Look, it doesn't matter!",
	voice_key = 30228,
	headtouch = "Eek! How dare you touch my sacred horns... Mmgh!",
	feeling2 = "Do you see the thunder over yonder? When the heavens brandish their might, the mortal world quakes in fear... Now, now, you needn't be afeard. I am your fortress.",
	login = "Secretary, you say? Hah, in other words, I am to serve you? If so fate dictates, I shall obey and minister to you.",
	detail = "Perceiving the will of nature, wielding the might of thunder, grasping the causality of all things – that is my power. What you need in this moment is... What? To know what the weather will be like in an hour? That's really all you need?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[302281] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Having won in this attire... brings me no joy whatsoever!",
	home = "Did... Did you come to laugh at me, fated one?! ...Ah, I misspoke! One more time!",
	unlock = "Wh-what are these lasers? My equipment, it's all... Urgh! How am I meant to continue my mission with my suit and gear all melted away?!",
	touch2 = "Eep! Wait... Not right now... I can't... Mrgh!",
	mission = "",
	vote = "",
	drop_descrip = "Wh-what are these lasers? My equipment, it's all... Urgh! How am I meant to continue my mission with my suit and gear all melted away?!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "I-I know what you want! Information! But I won't give it to you! Not ever!|(I cannot believe they're employing defenses as craven as these lasers! A play though this may be, that doesn't mean... Wait, where did they even find lasers that only dissolve clothes?!)|That noise... The lasers must be charging! Heavens above... N-no! I can't afford to be hit by another!",
	touch = "Wh-what is that you're holding? A laser pointer? ...W-wait, don't point it at me! Mrgh!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 302281,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "What?! Fine, use what you will – it still won't make me budge!",
	feeling2 = "",
	login = "Who are you?! Might you be... the lord of this mansion? So you heard the alarm and came hither... F-forget about how I look, will you?! Urgh!",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[302290] = {
	hp_warning = "I might've played around too much... Teehee!",
	feeling3 = "Aww, are you going to stay with me for real this time? Great. Then I'll go ahead and clear my plans for the rest of the day!",
	mail = "You have mail. Want me to dispose of the boring and troublesome ones for you?",
	expedition = "The commission team brought resources home. Hehe... That smile tells me you're quite satisfied with them.",
	win_mvp = "Easy win! All thanks to you, Commander.",
	home = "Good work today. Wanna rest your head in my lap for a bit?",
	unlock = "Are you the Commander here? You look like you're easily taken advantage of... Don't worry, though. I'll \"dispose\" of anything or anyone who'd cause you trouble.",
	touch2 = "I'll pay you back double for that one!",
	mission = "You still have unfinished missions. I'll help you get them done lickety-split.",
	vote = "",
	drop_descrip = "Sendai-class light cruiser – Nayoro.",
	feeling4 = "You've already made me lose interest in everything but you. Keep being interesting for me, okay, Commander? Otherwise... I might have to punish you.",
	lose = "We'd better retreat... Let's run, Commander!",
	feeling1 = "Commander, playing with you has gotten... boring.",
	skill = "Playtime is over. Get ready...",
	upgrade = "I feel better than ever!",
	propose = "So the time has finally come. My heart is already yours, but in return... I'll be taking your heart, too. Through my own methods, of course!",
	feeling5 = "When I'm with you, I feel joy that I've never experienced before. Don't worry, Commander... I'll hold on tight and never let go again.",
	main = "When you space out, you look like such defenseless prey. If I lock this door now... Heehee!|You have so many strange rules you have to follow... As far as I'm concerned, the only rule that should matter is, \"What the Commander says, goes.\" Don't you think so?|I just discovered that I can get all kinds of odd reactions from you just by talking. It's so much fun!",
	touch = "I'm ready to start fighting back, you know.",
	voice_key_2 = -1,
	mission_complete = "Mission accomplished! How do you plan to reward my efforts, hmm?",
	battle = "Let's mop them up all at once.",
	id = 302290,
	gift_dislike = "",
	gift_prefer = "Hmm? Thank you! I'd love to have it.",
	profile = "I'm Nayoro, she who can summon lightning even on sunny days. Hmm? Commander, I noticed you're staring at my tail... Wanna touch it? I'll try my best not to shock you.",
	voice_key = 30229,
	headtouch = "Aww... Are you treating me like your pet? Heehee!",
	feeling2 = "May I sit next to you? Don't say no just yet... There. My tail is wrapped around both of us now... Oh? Did I shock you again?",
	login = "Commander, would you like to touch my tail? I just finished grooming it... Hmm? It feels like it's crackling with electricity? Aw, am I leaking again?",
	detail = "Oh, my tail's leaking electricity again. It's your fault this time – your arrival got me a little excited, that's all... Heehee.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[302291] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "You look a little tired... It's okay. Leave the rest of that trouble to me.",
	unlock = "Our rendezvous went smoothly enough... but it looks like we're being tailed by some unsavory folk. Shall we go take care of them? Don't worry – it'll be over in no time.",
	touch2 = "Do you like improvising like this, Commander? Heehee, guess I'd better play along.",
	mission = "You have missions to do. Let's take care of that trouble together!",
	vote = "",
	drop_descrip = "Our rendezvous went smoothly enough... but it looks like we're being tailed by some unsavory folk. Shall we go take care of them? Don't worry – it'll be over in no time.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "Zzzap... Heehee, did that startle you?",
	propose = "",
	feeling5 = "No matter when it is, no matter where we are, I always feel furtive eyes glancing at you... I suppose the only way to keep you safe is to keep you in arm's reach at all times, huh? Heehee!",
	main = "Let me stay with you and protect you, Commander. If you have anything else in mind, well... Zap!|I'll control my electricity during battle so I just put our enemies to sleep. How long they sleep, well... That depends on them!|My stun gun needs regular maintenance to stay in tip-top shape. Just like my tail, it's perfect for \"convincing\" you to stay with me forever~",
	touch = "Are you worried about me? Don't be. I'll take care of the enemy in no time.",
	voice_key_2 = -1,
	mission_complete = "Missions complete. We might be the perfect combination!",
	battle = "",
	id = 302291,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "You caught me by surprise, Commander... Heehee.",
	feeling2 = "",
	login = "Heehee, I was worried that you'd gotten wrapped up in some trouble, but you made it on time after all. Any longer, and I would've come rushing to your aid!",
	detail = "I prepared this weapon just for today... Why are you staring? Are you hoping I'll use it on you? Heehee, of course I will.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[303010] = {
	hp_warning = "",
	feeling3 = "Commander~ Oww! ...Ehehe... Thanks, I almost fell again. I'm trying to pay more attention so that I don't trip as much, but I was so happy that I let my guard down.",
	mail = "Sorry, Commander... I tripped and fell while getting the mail and now it's all wrinkled...",
	expedition = "Commander! Ah... that hurts! I'm fine... I just wanted to tell you that commissions have been completed.",
	win_mvp = "Eh? I'm the MVP?",
	home = "Commander, I tripped again... Do you have a band-aid somewhere?",
	unlock = "Ah! Sorry for bumping into you... Huh? You're the Commander?! F-Furutaka, first ship of the Furutaka class, reporting for duty! Can you please forget what just happened? Ehehe...",
	touch2 = "I never thought you'd take an interest in me, Commander... Frankly, I'm a bit happy~",
	mission = "A new mission, huh? Seems like it might be a bit tricky.",
	vote = "",
	drop_descrip = "First ship of the {namecode:53}-class heavy cruisers, {namecode:53}.",
	feeling4 = "Yeah... Being able to live with Kako and seeing my sisters from the Mikawa and 6th Fleet was always a dream of mine. Commander, you've made my dream come true. That's why... I'll do anything for you!",
	lose = "We lost... Too bad...",
	feeling1 = "(Furutaka ignores you as she passes by)",
	skill = "All right, here I come!",
	upgrade = "Thanks, Commander!",
	propose = "I've never felt like this in my life before... But as long as I'm with you, I'll be able to feel this way more and more, right? I can't wait!",
	feeling5 = "If you're okay with this... then I don't mind, Commander. But... I've never been in a relationship before, so I don't know what it's like. Can you teach me?",
	main = "Commander, Kako doesn't really hate you, so don't take it too personally.|Um... because I'm not very smart, maybe Kako should take my place at meetings instead...|Ouch...! Ahh, I'm fine... I just nodded off and bumped my head.",
	touch = "What's up?",
	voice_key_2 = -1,
	mission_complete = "I bumped into something while getting the rewards... Oww...",
	battle = "I have to do well in this battle!",
	id = 303010,
	gift_dislike = "",
	gift_prefer = "Thanks for getting my favorite gift, Commander!",
	profile = "I'm the Furutaka-class heavy... Err, just call me Furutaka! I may not look it, but I participated in the First Battle of the Solomon Sea! I also helped my sister Aoba out a lot! In the end though, I rushed too far ahead and didn't make it back myself... Ehehe...",
	voice_key = 30301,
	headtouch = "",
	feeling2 = "Kako acts like that because she holds herself as the role model for heavy cruisers, but she's actually very gentle.",
	login = "Commander, please be more careful when you open the door...",
	detail = "I'm a bit bored...",
	couple_encourage = {}
}


