_G.pg.base.ship_skin_words[303030] = {
	hp_warning = "It's not very funny when I'm the one on the news.",
	feeling3 = "It's been a while since since I've been stationed here, so I've managed to get some good information from everyone. At first they thought you were a shady person, but you seemed to have earned their trust. Good for you!",
	mail = "Commander, you're way to careless with information... Take it, it's your mail!",
	expedition = "\"Come see a magnificent view of girls hard at work!\" ...Okay! Commander, let's pack some snacks and head to port to conduct some interviews!",
	win_mvp = "Okay, time to get a quick word from the losing side. Eh? Leaving already?",
	home = "Commander~ of the girls out on commission right now... who's your favorite?",
	unlock = "Hmm, hmm... I can smell it. This fleet is going to make the headlines! So you're the Commander, huh? Just let me, Aoba, gather all the information without holding back!",
	touch2 = "Commander... It's not wise to mess with reporters.",
	mission = "Missions? I'm just here to record your heroic image, Commander. Oh? I need to go too?",
	vote = "",
	drop_descrip = "First ship of the {namecode:55}-class heavy cruisers, {namecode:55}.",
	feeling4 = "I've made my fair share of mistakes, so I thought I could help by leaving something to commemorate everyone's hard work. Sorry for saying something so unlike me... but, you made me drop my guard. Now, you have to answer my questions!",
	lose = "I... Aoba... shouldn't be getting upset over this!",
	feeling1 = "Maybe I should go conduct some interviews overseas...",
	skill = "",
	upgrade = "I think I'm getting closer to my next big scoop. Thanks, Commander~!",
	propose = "Just to be clear, I'm not good at this kind of stuff... so don't expect me to say anything romantic... ever! Well, maybe just once... Um... I... l-l-love... you!",
	feeling5 = "Alright, I've decided. For all my precious friends here, I will record their lives! Does that include you? Oh you, don't you already know the answer to that?",
	main = "I believe that hard work pays off, you know. Eh? Why was I following you yesterday? I don't ever recall doing anything like that~|Say, Commander. If you let me interview you, I'll share some juicy gossip with you. Like... which girls might be looking your way~|It's sure hard getting a scoop... Maybe... I should make some news myself!",
	touch = "Ah, a good idea, finally! This will definitely make the front page!",
	voice_key_2 = -1,
	mission_complete = "Commander, stop lazing around. Go get your rewards and let me take a picture!",
	battle = "You're far too naive if you think  you can escape Aoba's eyes!",
	id = 303030,
	gift_dislike = "",
	gift_prefer = "Hmhmm? Should I write a few nice words about you?",
	profile = "Hai hai! The name's Aoba! I spent most of my days in the 6th Fleet, took part in many battles with my sisters, and did my best to survive until the end. Let's drop this boring topic, shall we? I was a writer for the Navy once, so I've picked up a thing or two. Commander, anything juicy going on around you lately?",
	voice_key = 30303,
	headtouch = "",
	feeling2 = "Commander, could you tell me how it feels to have such a large har- I mean, fleet?",
	login = "Hehe~ Commander, I saw that~!",
	detail = "What's up? You know I charge for intel.",
	couple_encourage = {
		{
			{
				30304
			},
			1,
			"It's over... I'm definitely going to get yelled at again...",
			0
		},
		{
			{
				30301
			},
			1,
			"{namecode:53}... I'm so sorry for what happened back then...",
			0
		},
		{
			{
				30301,
				30302,
				30304
			},
			1,
			"6th Fleet, set sail!",
			0
		},
		{
			{
				10105
			},
			1,
			"Let's see who has the better intuition!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[303040] = {
	hp_warning = "Don't panic. Get into formation!",
	feeling3 = "Don't be too hard on my sister... She actually has a lot of guilt buried in her heart.",
	mail = "Commander, do I have to tell you to check your mail every single time?",
	expedition = "Commander, since you didn't go yourself, you should at least welcome back the girls who worked hard on the commission!",
	win_mvp = "Everyone, don't let your guard down just because we won!",
	home = "Commander, it's important to balance work and rest. Since you just got back, why not take a quick break?",
	unlock = "Pleased to meet you! I'm Kinugasa. Have you been eating and sleeping well,  Commander? Don't be like my big sis... Speaking of which, is she also here by any chance?",
	touch2 = "Please take a seat, Commander. We're going to discuss fleet discipline.",
	mission = "Commander, work will only pile up if you keep putting it off!",
	vote = "",
	drop_descrip = "Second ship of the {namecode:55}-class heavy cruisers, {namecode:56}.",
	feeling4 = "I don't really like lecturing people... but I've gotten used to lecturing my sister, and you don't seem to mind. Eh? You actually appreciate it? Then... I guess I'll keep it up...",
	lose = "We need to call a meeting and review this performance...",
	feeling1 = "It's not like I care what you do...",
	skill = "",
	upgrade = "Being wasteful is no good, Commander.",
	propose = "Jeez, Commander. Your sleeves and collar are messy as always, even for such an important occasion. I'll lecture you later~ let's carry on with the ceremony!",
	feeling5 = "Aoba is always so impatient! But she's my big sis, and she's very important to me. Just like you, Commander. You're precious to me as well!",
	main = "Did you rest well, Commander? Health comes first!|I'm not sure if Aoba is getting enough rest... Please make sure to check up on her!|Work hard, play hard! That's the secret to a happy life!",
	touch = "Commander, did you also come to wind down with some light stretching?",
	voice_key_2 = -1,
	mission_complete = "Commander, leaving your rewards there won't make them grow.",
	battle = "Everyone! Stay alert, protect yourself, and don't be reckless!",
	id = 303040,
	gift_dislike = "",
	gift_prefer = "Commander? Ah... my apologies, I almost started launching into another lecture... Thank you very much.",
	profile = "Good day, I'm Kinugasa! I was in the 6th Fleet with my sister Aoba before it was disbanded. We fought together in many battles, like Wake Island, the Coral Sea, and the Solomon Islands. I'm not as lucky as her though... Anyways, Commander, try not to overwork yourself! Rest is important too!",
	voice_key = 30304,
	headtouch = "",
	feeling2 = "Did you clean your room, Commander? Did you lock the door? Have you forgotten anything?",
	login = "Welcome back, Commander! Did you get enough to eat? If you're still hungry, I can cook something for you!",
	detail = "Health comes first!",
	couple_encourage = {
		{
			{
				30303
			},
			1,
			"Stop looking around, sister!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[303060] = {
	hp_warning = "This is nothing... This won't make me fall behind...!",
	feeling3 = "Oh, are you curious about the intel I've gathered? Mm, like how everyone at the port feels about you? Just kidding, of course♪",
	mail = "There's some new mail for you. Please make sure not to look over any new information.",
	expedition = "Hm... According to my seaplanes, it seems like the commissions team is almost here.",
	win_mvp = "As long as the intel is correct, victory is guaranteed... Ehe♪",
	home = "Good work out there. Why don't you get started on the combat report? This experience will become the foundation for your next victory, after all.",
	unlock = "I am Chikuma. Pleased to make your acquaintance. Well, that might be the case, but I already know a bit about you... My, are you curious? You'll find out before long, hehe.",
	touch2 = "Looks like I've grasped another weakness of yours, Commander♪",
	mission = "Commander, I don't think it's a good habit to neglect your duties.",
	vote = "",
	drop_descrip = "Tone-class heavy cruiser number two – Chikuma.",
	feeling4 = "Mm... Even if there's something you really want to know, I can't just tell you... Right, how about this? You listen to one of my requests, and I'll tell you one thing you want to know in exchange. Hehehe♪",
	lose = "It's because I wasn't able to get enough info on them...",
	feeling1 = "I'm sorry. I'm not sure I can deal with someone like you...",
	skill = "Knowledge is the key to victory♪",
	upgrade = "My reconnaissance abilities have grown even sharper~",
	propose = "Are you disappointed that I'm not surprised at all? Don't be, I really am, you know? It's just that I'm so happy, it far exceeds any surprise I might've felt~♡ Hehehe~♪",
	feeling5 = "Hehe. As payment for the secret I told you, you'll be taking me out on a date♪ ...No refunds allowed, of course.",
	main = "You want to know what people are saying about you? ...You know, if you're that curious, I suggest that you dig around a bit yourself.|This is some juicy info here... Hm, I bet Aoba would love to hear about this~|Just like the \"eyes\" on my seaplanes need maintenance, our eyes should be maintained properly as well. That way, we can make sure they work well when they need to.",
	touch = "If you want some help, you should organize the information first.",
	voice_key_2 = -1,
	mission_complete = "Mission rewards... Lots of things here, so I'll leave the accounting to you♪",
	battle = "I've already seen through your tricks, hehe.",
	id = 303060,
	gift_dislike = "",
	gift_prefer = "Oh my, did you do a bit of homework on me, Commander? Thank you~",
	profile = "I'm the Tone-class heavy cruiser, Chikuma. I can carry more seaplanes than my heavy cruiser counterparts—you could say I've got plenty of eyes in the sky. I'm good at the art of knowing things, don't you think so? Hehehe.",
	voice_key = 30306,
	headtouch = "Are you trying to get my ears to spring up? Hehe~",
	feeling2 = "Let's see what my seaplanes' eyes have captured for me this time.",
	login = "Let's see... Well, it looks like you're right on time. Welcome back, Commander.",
	detail = "Knowledge is power. Not only in battle, but for everything else as well... right?",
	couple_encourage = {
		{
			{
				30601,
				30602,
				30603,
				30605,
