_G.pg.base.ship_skin_words[303070] = {
	hp_warning = "",
	feeling3 = "Commander, remember to take breaks as needed. Your efficiency will be worse if you run out of stamina... Lap... pillow? It's fine by me... but will it really help you recover faster?",
	mail = "New mail has arrived! Is this the latest training manual?",
	expedition = "Commission complete! Is everyone putting forward their best effort?",
	win_mvp = "This victory was made possible by everyone's efforts, not just my own!",
	home = "This method of relaxing is inefficient. Why not try some of my specially-made energy drink?",
	unlock = "I am, {namecode:63}, first ship of the {namecode:63}-class heavy cruisers. Commander, is there anything I can help you with?",
	touch2 = "... Commander, have some self-respect...",
	mission = "Commander, please don't hesitate to ask for help!",
	vote = "",
	drop_descrip = "First ship of the {namecode:63}-class heavy cruisers, {namecode:63}.",
	feeling4 = "I saw your light on, so I came to check on you. I had no idea you'd still be awake; even being a workaholic should have its limits! Come on, I'm not leaving until you fall asleep.",
	lose = "It's all because I neglected my daily training... Everyone, I'm sorry...",
	feeling1 = "Stop slacking off, Commander!",
	skill = "Burn this final sight into your memory!",
	upgrade = "I won't let such a small improvement get to my head.",
	propose = "Commander, your body is no longer just yours alone. Make sure you take care of yourself properly... for me, okay?",
	feeling5 = "Commander, I've finished processing those files. It's the end of the day, so why don't we grab dinner together? ... ... How's it taste?",
	main = "If I get another chance... I'd like to pet Hatsukaze's head again.|I've put on weight?! Commander... there are some things that even you shouldn't say.|Bergall?! Phew... you were talking about someone else.",
	touch = "I'm supervising the destroyers' training right now. Please save it for later if it's not an emergency.",
	voice_key_2 = -1,
	mission_complete = "Don't call it a day after finishing just one mission!",
	battle = "Let's see the fruits of my daily training! All guns, open fire!",
	id = 303070,
	gift_dislike = "",
	gift_prefer = "Commander, your feelings are reaching me.",
	profile = "I am {namecode:63}, of the Sakura Empire's {namecode:63}-class heavy cruisers. I participated in both the glorious victory of the Java Sea and the humiliating defeat at Leyte Gulf. Afterwards, I was struck by a torpedo and pursued by submarines. In the end, I could only watch from the South as my nation surrendered. It is hard to say whether that was fortune or misfortune. Anyways, Commander, you can always talk to me if something is on your mind.",
	voice_key = 30307,
	headtouch = "... Please do this kind of thing to destroyers, not me...",
	feeling2 = "It is not unusual for a weaker force to defeat a stronger one in a naval battle. Victory or defeat is often decided by good judgment and split-second decision making. We must be thorough in our training in order to cultivate these abilities.",
	login = "Would you like some homemade pancakes, Commander?",
	detail = "Commander, acquiring intel is the first step to victory.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[303080] = {
	hp_warning = "",
	feeling3 = "Hard work? Not at all. A genius like me doesn't need to work hard. I get stronger just by breathing.",
	mail = "You want your mail? Only if you beg me nicely~",
	expedition = "Mmhmm. It's important to work hard! Well, unless you're me!",
	win_mvp = "Hehe, this is only normal, of course.",
	home = "Good work. However, you won't be able to catch up to me with even ten times the effort!",
	unlock = "I'm {namecode:64}, the first post-treaty heavy cruiser from the Sakura Empire. My design is the very definition of perfection! I'll be in your care from here on out!",
	touch2 = "I-idiot... you're that fascinated with me? At least tell me in advance...",
	mission = "Only an idiot would be unable to complete such an easy mission.",
	vote = "",
	drop_descrip = "Second ship of the {namecode:63}-class heavy cruisers, {namecode:64}.",
	feeling4 = "Huh? Commander? What are you doing at the training area so late? You were worried about me? I-I was just taking a walk because I was bored. You heard cannon fire? Th-that was...",
	lose = "Damn it... just what went wrong?",
	feeling1 = "I wasn't talking to you!",
	skill = "Kneel before my cannons!",
	upgrade = "I'm even more flawless than before!",
	propose = "I know I have a hard time being honest with myself, but... I'll try my best to make you the happiest person in the world! I swear my name on it!",
	feeling5 = "I can't be honest with myself... because I can't stand the thought of people seeing me work hard... except for you, Commander. No matter who I become, surely you would...",
	main = "My sisters in the Fifth Fleet? I miss them a bit... err, just once in a blue moon!|Ghosts on the training ground? W-what are you, a kid? Who'd believe something like that?|Salt Lake City? I'm going to show her that Lady Luck doesn't bless the same person forever!",
	touch = "Commander, are you feeling lonely? I just happen to have more spare time than I know what to do with~",
	voice_key_2 = -1,
	mission_complete = "Heheh, looks like you couldn't have done this mission without me!",
	battle = "Hmph. Another bunch of blind idiots.",
	id = 303080,
	gift_dislike = "",
	gift_prefer = "This is for me? I appreciate it a lot!",
	profile = "I am {namecode:64}, second ship of the {namecode:63}-class heavy cruisers. Though I said second ship, I am no \"little sister\". I fought my way all around the Pacific, and served as flagship multiple times. I am greatest heavy cruiser - bear witness to my elegance and power!",
	voice_key = 30308,
	headtouch = "",
	feeling2 = "Commander, you're going to be unpopular forever if you don't pay attention to your appearance.",
	login = "I-I'm not training.. I'm just... being lazy and laughing at the other girls as they work up a sweat.",
	detail = "What is it? Do you want to be my lackey?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[303089] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	couple_encourage = "",
	expedition = "The commission team is really working hard. Heheh, hurry and go check out those rewards.",
	win_mvp = "Get on your knees and beg, and maybe I'll forgive you♪ See how tolerant I am?",
	home = "Thanks for your hard work~ Oh, you brought back tons of spoils... O-of course, you are working, like, fifteen times harder than before. I know you're catching up to me... *blushes*",
	unlock = "Howzit? Now that my retrofit's all done, don't I look even more perfect than before? Maybe now, our ever-so-reserved Commander here will be super impressed by my new abilities~ Wh-what do you mean I've been staying up too late training with my rigging? W-we're not gonna talk about that!",
	touch2 = "Hm? What's up... Hyah?! H-hey, did you just do that on purpose?!",
	mission = "These missions are so simple, they could be done instantly. I know I could, but surely even you can, Commander!",
	vote = "",
	drop_descrip = "Howzit? Now that my retrofit's all done, don't I look even more perfect than before? Maybe now, our ever-so-reserved Commander here will be super impressed by my new abilities~ Wh-what do you mean I've been staying up too late training with my rigging? W-we're not gonna talk about that!",
	feeling4 = "",
	lose = "I don't know what went wrong, but... Let's run away, Commander!",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Lately, I've been running into Haguro early in the mornings... Hm? You say I should train somewhere else? Good idea... Instead of the Sakura Empire dorm, I should come to your—no, I obviously can NOT do that!|You're feeling anxious? Hmm... Why not try working or crafting something to take your mind off of it? Like, say, origami?|Whoa, you're just openly slacking off... Heheh, then I'll just... NOT join you, obviously! C'mon, Commander! There's work to be done!",
	touch = "Feeling lonely, Commander? Heheh, same here... Uh, I mean, I'm just so darn bored!",
	voice_key_2 = -1,
	mission_complete = "You didn't even need my help! Heheh♪",
	battle = "",
	id = 303089,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "The perfect Nachi put together your daily schedule for you! Now, let's get some work done!",
	detail = "A gift? It's not like I asked you to go and buy this for... Hahaaah, I guess you're so used to running around and getting things for me that you couldn't help yourself! Well... Sure, I'll take it!"
}


_G.pg.base.ship_skin_words[303090] = {
	hp_warning = "This is the hour of reckoning! Chaaarge!!",
