_G.pg.base.ship_skin_words[303116] = {
	hp_warning = "",
	feeling3 = "",
	mail = "A letter, hm? ...I almost sliced it by accident...",
	expedition = "The commission fleet has made their return. Commander, wouldn't now be the ideal time to greet them?",
	win_mvp = "A little damage to my clothing won't affect me. As long as I have an arm to swing my blade, rigging to fire my cannons, and the will to fell my foes, I can fight on!",
	home = "Haaaah! ...Oh, you? I just finished dispatching the enemies here. Let's explore a little longer and take a break.",
	unlock = "My five senses are sharper than ever, perhaps even TOO sharp. No matter what trap awaits, my only way forward is to pierce through and focus on overcoming this trial... Haaah!",
	touch2 = "C-Commander...?! Are you being possessed by some evil spell... Kh?!",
	mission = "...I'll carry out any task you ask of me.",
	vote = "",
	drop_descrip = "My five senses are sharper than ever, perhaps even TOO sharp. No matter what trap awaits, my only way forward is to pierce through and focus on overcoming this trial... Haaah!",
	feeling4 = "",
	lose = "Kh... Commander... I've made a mistake!",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Miss Kirishima taught me ninja techniques, and Miss Washington instructed me in martial arts. I will flinch from no foe!|I can defeat enemies more quickly by using my rigging release technique, but that would endanger you, Commander. How can I respond if you're taken hostage? Kh...|\"Tentacle demon Observer, abomination of the deep! I, shipninja Takao, will strike you down!\" Hm... Will this do for my fighting stance?",
	touch = "Commander, watch out! Sorry... My first reaction was to hold you in my arms. Hm? Something of mine is touching you? Ah...",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Claim your rewards, but beware of any devious traps.",
	battle = "I, heavy cruiser Takao, shall be the exorcist's blade!",
	id = 303116,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, get behind me! They may just be set pieces, but it'll still hurt if you get hit by debris.",
	detail = "We may be able to dart about freely here, but a battlefield isn't so unrestricted. Don't be arrogant over good results in exercises, and remember that it's important to learn from real experience. ...Say, Commander, why don't you join me for a while longer?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[303117] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Back already, Commander?! I-I was... in the middle of trying a new technique... Consider it a little sneak peek!",
	unlock = "Is this not supposed to be for the sake of self-cultivation? I've never seen training methods such as this... However, now that it's come to this, fleeing is not an option. I must lead by example by adapting to these strange circumstances!",
	touch2 = "Y-you're suddenly so forward!",
	mission = "",
	vote = "",
	drop_descrip = "Is this not supposed to be for the sake of self-cultivation? I've never seen training methods such as this... However, now that it's come to this, fleeing is not an option. I must lead by example by adapting to these strange circumstances!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I try to keep my mind free of distractions, but your unwavering gaze is... perhaps a little unsettling. As I am now, if I keep eye contact with you for more than three seconds, I'll surely expose a weakness... Will you help me train my way through this, Commander?",
	main = "I see. The more one self-cultivates, the more naturally one can face dangerous situations... Watch carefully. My performance displays true mastery, does it not?|This fabric has such a different texture from the ones I usually wear. It's light, but when I wear it... I feel oddly sensitive.|Am I cold? Don't worry about me. I can meditate under waterfalls in the winter, so this chill is nothing to me.",
	touch = "Is this outfit really a best-seller? It doesn't leave much to the imagination...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 303117,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Am I still too tense? Apologies... I'm sure I'll be more confident once I have tried a few more outfits on.",
	feeling2 = "",
	login = "Hmm. Commander, I am prepared. I'll strike the perfect pose to show you true mental fortitude!",
	detail = "Mental fortitude is all about discarding the false and embracing the true, conveying a unique message to another through one's bearing alone... Was that hard to understand? Then watch me, and you will surely understand.",
	couple_encourage = {}
}


