	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Heehee. I'm not a dog right now, I'm a big wolf! You, on the other hand... you can be whatever you want, heehee.",
	feeling2 = "",
