	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Hungry, Suzuya? Wanna order home delivery?|Whatcha lookin' at, Commander? You more interested in me than the cards, or what?|Taking your sweet time, huh. Mmh... Meh... *yaaawn*...",
