_G.pg.base.ship_skin_words[303183] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Aw crap, got an e-mail! Commander, pass me the phone!",
	expedition = "",
	win_mvp = "",
	home = "C'mon, take a seat~ I'mma give those weary bones a nice massage! Heheh, where should I start? Your shoulders, or your feet? Tickle tickle tickle♪",
	unlock = "Tadah! Get a load of my... dancer outfit! So, whaddya think? Ahaha~♡ Hey, Commander, where are those eyes wandering? Did ya see something ya like?",
	touch2 = "Commander... Where's that hand of yours wanderin'...? ♡",
	mission = "",
	vote = "",
	drop_descrip = "Tadah! Get a load of my... dancer outfit! So, whaddya think? Ahaha~♡ Hey, Commander, where are those eyes wandering? Did ya see something ya like?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "That's... Mikuma? When'd she become so damn hot and stylish? Sheeeesh... Even I'm swooning over here!|Wanna see a rough rehearsal, Commander? Or are you gonna wait 'til the real deal?|This dance is like, murder on your back. I'm gonna be recovering in bed tomorrow, so go easy on me~ \"What're we gonna do then?\" Hang out, duh! Ahah☆",
	touch = "Ahah♡ Wait 'til I start shakin' it around~",
	voice_key_2 = -1,
	mission_complete = "We've got mission rewards~ Anything catch your eye?",
	battle = "I'm gonna evade all their attacks and dance around the– Oww!",
	id = 303183,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Welcome to my unveiling! Now let's see how many songs you can last before you fall for me~ Hahahah♡",
	detail = "Who else are ya excited to see, besides me? Ahahah☆ Hey, I'm not jelly in the slightest. I know you, Commander. Just name like, 20 or 30 other people~",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[303190] = {
	hp_warning = "I mustn't inconvenience the Commander...!",
	feeling3 = "You'd like to know what I want? Well... Hmm... Ummm... I can't really think of anything, but don't presume I'm without desire. But... Hmm, this is a quandary.",
	mail = "You have mail, Commander. Don't you think you should at least skim through it before you leave it in the box?",
	expedition = "The commission team is back. I can't wait to hear their stories, heehee.",
	win_mvp = "Rokkou's manifestation, Kaimon's divinity. Victory comes as holy mounts rise through the clouds.",
	home = "Welcome back, Commander. Would you like to take a warm bath? It must be hard to meet with friends with the stench of battle still on you.",
	unlock = "The threads of fate stretch far, I see. I am heavy cruiser Unzen, and I shall avail myself of your hospitality for the time being. Ah, not that I am planning to leave you, Commander, but I do intend to take time off for personal matters every now and then. Heehee, I do enjoy letting the wanderlust take over.",
	touch2 = "I know this training method... Would you like to try it on me, Commander?",
	mission = "You have a backlog of missions. Heehee, I understand. It's only human to procrastinate until right before your deadline.",
	vote = "",
	drop_descrip = "Heavy cruiser – Unzen.",
	feeling4 = "Commander, I came up with an answer to your question. Looking back, I've never felt... tied down. So I'd—oh, Commander? What's the matter?",
	lose = "Clearly... I've neglected my training.",
	feeling1 = "Normally, I would consider consigning people as immoral as you to death, but... I'm just joking. Please get a hold of yourself, Commander.",
	skill = "Boundless heaven and earth, expunge all sin and impurity––",
	upgrade = "I'm even stronger now. Heheh.",
	propose = "I'm deeply honored by your proposal. While I don't feel deserving, I graciously accept... Heehee, it seems I'll have to train to be a bride, won't I, Commander?",
	feeling5 = "It seems my answer from before has you in a dilemma. But understand that, as long as it's you, I really don't mind... Oh, or do you happen to have other inclinations?",
	main = "Are you thirsty? If you'd like tea, I'll bring some right away... But you look like you need a nutritional drink.|Looking for a diversion? You could take a little walk. Actually, there's a sacred mountain only three days away... Oh? That's too far for you?|I don't just know about seals; I have some knowledge of feng shui dragon veins, too. There are other girls in the port who know much more than me, though, so I suppose you don't need to ask me... *glance*|The Guardian Fox's little sister asks you questions incessantly? I suppose that would be difficult if you don't know the secret to victory. Commander, sometimes NOT answering is an option.|Sometimes, fleeing from work and human relationships is a viable option. I won't tell you to forsake society, but maybe you could learn a little about the hermit mentality?",
	touch = "If I suit your needs, then please ask anything of me.",
	voice_key_2 = -1,
	mission_complete = "You have some unchecked mission rewards. Heehee, don't worry. It's nice to watch them build up, isn't it?",
	battle = "Let us expel evil and bring purity to these blue seas.",
	id = 303190,
	gift_dislike = "",
	gift_prefer = "Commander, you're really going to give this to me? I'll make sure to put it to good use.",
	profile = "I am Unzen, a heavy cruiser made as part of the sixth shipbuilding plan. I'm unused to traversing this plane of existence, so I may lean on you for aid, Commander... But if you will accept me, I am more than happy to help—no, serve you. Heehee.",
	voice_key = 30319,
	headtouch = "Hmm, I'm not too sure about this...",
	feeling2 = "Your care is appreciated, Commander. Whether it be battle, odd jobs, or caring for your affairs, please ask me for anything you may need.",
	login = "Commander? You're quite early today. ...I, on the other hand, was tardy considering my role as your secretary ship, for which I apologize.",
	detail = "Ah, I'm feeling just fine, thank you. As a wanderer, my body is used to going days without eating or drinking... But you say the others would worry? Of course... *sigh*",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[303191] = {
	hp_warning = "",
	feeling3 = "",
	mail = "It seems there are letters waiting for you. It's okay. You may enjoy your break first and read it later.",
	expedition = "",
	win_mvp = "A shipgirl's power isn't tied to appearances... In other words, victory will be just as easy in this swimwear!",
	home = "Commander~ Welcome home~♥ I see, so this is what makes you happy? It seems I still have much to learn... Heehee.",
	unlock = "Commander~ Come over here~♥ Heehee, you look surprised... I don't think I'm dressed strangely at all. Or... is this swimsuit not enough to satisfy you, Commander?",
	touch2 = "You'd even do that out here...? Heehee♥",
	mission = "",
	vote = "",
	drop_descrip = "Commander~ Come over here~♥ Heehee, you look surprised... I don't think I'm dressed strangely at all. Or... is this swimsuit not enough to satisfy you, Commander?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Would you like to join me, Commander? Soak your feet and feel heaven and earth's energy through the land, sea, and ocean breeze...|There are some underwater hot springs nearby. How about you and I visit them later? They're quite close—it's just two days if we swim.|Commander, when you go on vacation, you should have fun. Yes, it's a rare opportunity to... move your body a little, don't you think?",
	touch = "This feeling of liberation... I'd love to feel more of this place's energy with my bare skin... Oh, I can't?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 303191,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander~ Heheh, come sit over here with me. It may be... a little cramped, but it's enough space for two, isn't it?",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[303192] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "It's good to see you've returned, Commander. I was just practicing my next jutsu. I did want to honor you for your services, but, well...",
	unlock = "Ah, Commander... What a predicament you've discovered me in. Hoping to put my skills to the test, I attempted to imitate so-called \"ninjutsu.\" No, not the temporary paralysis one – I was trying to use the transformation jutsu.",
	touch2 = "So you want to see me restrained, do you?",
	mission = "",
	vote = "",
	drop_descrip = "Ah, Commander... What a predicament you've discovered me in. Hoping to put my skills to the test, I attempted to imitate so-called \"ninjutsu.\" No, not the temporary paralysis one – I was trying to use the transformation jutsu.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Imagine, if you will, that I was a ninja assailant whom you managed to detain. What would you do next in that situation, Commander? Show me, with your own hands, what you might do... Heehee♡",
	main = "You think I don't have to take this role so seriously? Honestly, I'm not sure what part of this you think is \"serious\"...|It is a ninja's duty to come when her lord calls... I see. That must be why everyone is hiding in the ceiling of your office. Haha!|The fact that you seem unmoved makes me wonder... Is this ninjutsu meant to be performed while tied up, after all?",
	touch = "The rope is far too tight. I may have made... a mistake.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 303192,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "I still have much training ahead of me...",
	feeling2 = "",
	login = "This is the ninja sage's ultimate transformation technique... Hyah! Commander, have I failed again...?",
	detail = "I've seen ninjutsu many times throughout my travels, but they were unlike those spoken of in the port. The world is more diverse than I ever imagined... Oh? You think the girls at port are telling me tall tales? Heehee, well, isn't that interesting...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[303200] = {
	hp_warning = "*cough cough*... It seems I've overexerted myself.",
	feeling3 = "Even when subjected to something bitter, you accept your suffering with a smile. That, to me, is truly astounding. Won't you please allow me to gaze more at your beautiful smile?",
	mail = "One must not let useful information slip past. Your letter demands your attention.",
	expedition = "Are you leaving to receive those returning from a commission? Then kindly allow me to accompany you.",
	win_mvp = "For a sideshow, it was quite entertaining.",
	home = "Welcome home. Does anything ail you? Then please do not worry. I have prepared a medicinal meal for you.",
	unlock = "Are you the Commander? I am Asama, and long have I waited for you. *sigh*... Although joyous times are as fleeting as bubbles in water, I still wish to step into this brief dream with you.",
	touch2 = "Mmh... This delight, this affection that we share... It will remain with me for some time.",
	mission = "New missions have been bequeathed unto us. Do not rush – adhere to a plan.",
	vote = "",
	drop_descrip = "Improved Suzuya-class heavy cruiser – Asama.",
	feeling4 = "I will cherish the fleeting present and preserve in my heart even the smallest of happinesses – this truth that you bestowed upon me is more precious than any treasure.",
	lose = "*cough cough*... We lie defeated... as dictated by destiny.",
	feeling1 = "Flowers blossom beautifully, then inevitably scatter off – nothing in this world lasts forever...",
	skill = "Look on with awe, then turn into ash.",
	upgrade = "This strength you've given unto me... I fear losing it.",
	propose = "I see that you've made up your mind. That being the case, I vow to take your hand, now and into eternity. The warmth that your hand imparts... it urges me to stay by your side and, together, behold the passing of the seasons.",
	feeling5 = "Like how cherry blossoms scatter to the wind, all living things are destined to one day become dust. However... it matters not how much time passes, for the memories we've made will always remain in my heart.",
	main = "My mere presence makes you... relax, you say? Perhaps the aroma of my medicine has a soothing effect on your soul.|Commander, do you perchance feel under the weather? Oh, no, that simply will not do. I shall make for you a medicinal dish, so please wait for just a while.|You have never wavered in your path, whether or not you'd be rewarded for it... That takes such strength, and it is so beautiful.",
	touch = "...Dosage makes the difference between medicine and poison, Commander. Please exercise care.",
	voice_key_2 = -1,
	mission_complete = "Thus, your work stands completed. May I propose having a pleasant bath to reinvigorate? It would be you and me, all to ourselves.",
	battle = "Let us bring an end to our foes.",
	id = 303200,
	gift_dislike = "",
	gift_prefer = "True joy is able to leave people speechless... I thank you.",
	profile = "I am Asama – an improvement upon the Suzuya class of heavy cruisers, and a hollow being who never was. Even so, I wish to be with you in this fleeting, beautiful world until my last moment.",
	voice_key = 30320,
	headtouch = "Hm? Are you offering to tie up my hair?",
	feeling2 = "I thought I had seen everything there was to see in this life – until I met you...",
	login = "Hm? Ah, it is you. No, it's nothing. It is good to be in peace.",
	detail = "Just as the water downstream is not the same as at its source, neither are people nor their homes the same as they once were. Do you concur with this notion, Commander?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[303201] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "A most splendid result. Shall we take this chance for a bit of merriment? With a condition that, should you lose... I shall take possession of you.",
	unlock = "Commander? Your expression seems to signal that you are not content with just ghost stories, yes? Ashamed am I to admit that I am still afraid... May I ask you to remain with me? There is something I wish to tell you.",
	touch2 = "Heehee... There is no escaping now, Commander... Mgh... Mmh...",
	mission = "We have been assigned new missions. Please, Commander, do be careful of spider's silk while walking the streets at night.",
	vote = "",
	drop_descrip = "Commander? Your expression seems to signal that you are not content with just ghost stories, yes? Ashamed am I to admit that I am still afraid... May I ask you to remain with me? There is something I wish to tell you.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "It would be nice if one could simply flee from demons and monsters, but such is not the case in reality. Once you return to your senses, you may already be in my grasp. Heehee... Now, will you please come to me gently on this night most wonderful?",
	main = "Hm? You saw an ill-boding thing, you say? Heehee. It was surely just your imagination. There is no one here but you and me.|You're certain that the temari moved? Heehee. Your eyes are merely playing tricks on you. If it bothers you so, then may I suggest closing your eyes in my embrace for a while?|It is said that shadows are reflections of the heart. One must wonder what form my attachment to you, my Commander, may take...",
	touch = "Ah, do you wish to see the mark that you left upon me? Or perhaps... do you intend to give me a new one tonight?",
	voice_key_2 = -1,
	mission_complete = "You've finished a mission? Then let us resume our play.",
	battle = "",
	id = 303201,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Well? Do you feel that you were mistaken now? Heehee. There are no horns on my head after all, are there?",
	feeling2 = "",
	login = "Welcome, Commander. May I interest you in some tea if you're feeling thirsty? Heehee – I shall keep you company tonight.",
	detail = "I've heard a tale... A tale of the spider woman who lures in travelers and then consumes their flesh when the chance arises. You need not fear, however. No such thing will happen to you for as long as I'm here. Heehee...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[303210] = {
	hp_warning = "I... I won't lose!",
	feeling3 = "Commander, I found a new secret realm amidst my travels. I'll show it to nobody but you, so don't tell any of the other girls, okay?",
	mail = "Commander, mail just arrived. Umm... Do you think it could be a map of sacred mountains?",
	expedition = "The commission team has returned home. I hope they'll have many tales for me.",
	win_mvp = "We won, Commander. Let's get back to journeying through new realms~",
	home = "Commander, I just returned from my own wanderings, as well. I'll tell you all about it.",
	unlock = "I am Unzen – the windchaser, the cloudstrider, the one who wanders across the vast horizons... and yet I have somehow ended up floating to your side with a \"fwooosh.\" Hrmm... the deep connection between us is mysterious indeed~♪",
	touch2 = "What are you doing, Commander? It feels... funny...",
	mission = "Commander, our wandering missions are still unfinished.",
	vote = "",
	drop_descrip = "Heavy cruiser – Unzen.",
	feeling4 = "May I... hold your hand on our travels today? I'm not scared, or anything. It's just that... it feels a little warmer...",
	lose = "This is troubling... Can I ask for your help once more?",
	feeling1 = "Commander... Never mind. I'm a capable free spirit now, so I can handle it on my own.",
	skill = "Step aside! Aside!",
	upgrade = "Now I can journey even farther~",
	propose = "Commander, you... want to be with me forever? Of course, I'd be happy to! Your side is the destination of all of my travels. Hehe, I love you so much, Commander!",
	feeling5 = "The map of my travels is full of memories with you, Commander. Heehee, let's keep wandering all over the world and filling it up as we go. It's a promise♪",
	main = "Tonight, I'd like to go on a solo journey into the world of dreams. You'll come and check on me, won't you?|Commander, I wove yesterday's wanderings into a melody for you. Allow me to play it now...|Hmm? You say I just had a snack? That was then's snack – this one is now's snack.",
	touch = "Hold on tight to my hand, Commander. Now you won't get lost when we wander together.",
	voice_key_2 = -1,
	mission_complete = "Your missions are done. We got lots of rare treasures, I see.",
	battle = "You shall not pass.",
	id = 303210,
	gift_dislike = "",
	gift_prefer = "You'd give this to me? It's beautiful...",
	profile = "I'm Unzen, a heavy cruiser. Capable as I am, I am free to roam the port as much as I please, but I'll be sure to call you if I find anything unusual.",
	voice_key = 30321,
	headtouch = "Nngh... You're tickling my ear...",
	feeling2 = "Commander, I found another sparkly treasure... Oh! It was just glass reflecting light, I guess...",
	login = "I memorized the entire geography of the port. Commander, would you join me in the search for new realms?",
	detail = "Commander, I discovered treasure belonging to the Sea God today. They may look like mere seashells, but do you see how they shimmer in the light? Maybe they have powers we've yet to uncover!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[304010] = {
	hp_warning = "Now is the time to make our comeback!",
	feeling3 = "Will Zuikaku be fine on her own...? Mm... I'll watch her from here. From this distance, she probably won't notice me...",
	mail = "Adjust your strategies in accordance with the new information.",
	expedition = "Phew... time to take a break. Commander, does black tea suit you?",
	win_mvp = "To be victorious is to be elegant!",
	home = "Good work out there. Were you able to achieve your tactical goals?",
	unlock = "I am Kongou, lead ship of the Kongou-class battlecruisers. I shall illuminate the path that leads to victory!",
	touch2 = "Hey you, don't tell me you've been subjecting my sisters to such depravity as well!?",
	mission = "Do I need to go do it myself?",
	vote = "",
	drop_descrip = "Kongou-class fast battleship number one – Kongou.",
	feeling4 = "I've heard that people are most likely to reveal their sentiments at twilight... I wonder if you're also like this?",
	lose = "Please rest at ease. This situation can still be salvaged.",
	feeling1 = "You do not deserve victory!",
	skill = "Press the attack!",
	upgrade = "Phew... another trump card to add to my hand.",
	propose = "Since you've put so much effort into pursuing me so passionately, it is only fitting that I give you the proper respect. Come, you've earned my hand.",
	feeling5 = "That Hiei, trying to throw a party again tonight... Commander, do you have time to keep me company there?",
	main = "No way in hell a battleship like me is going to get taken out by some flimsy torpedo! |Come! Let's destroy our enemies, pass through that measly canal, and return to the land where I was born! |I take myself too seriously? No, you take yourself too lightly! |Horns? Oh, these things? They're just decorations on the hat. I wouldn't look much like a member of the Sakura Empire without them, right?",
	touch = "Wh-what is it!? An emergency!?",
	voice_key_2 = -1,
	mission_complete = "Excellent! We're one step closer towards our ultimate victory.",
	battle = "All units, battle formations!",
	id = 304010,
	gift_dislike = "",
	gift_prefer = "Understood. I'll accept this.",
	profile = "Nameship of the Fast Battleships, flagship of the 7th Combined Fleet, and the last Sakura capital ship to be laid down overseas - that is me, Kongou!",
	voice_key = 30401,
	headtouch = "",
	feeling2 = "Commander, please be at ease, for victory shall soon come.",
	login = "Have you had enough rest? The fleet now awaits your orders.",
	detail = "The only value of war is the peace that follows it. I implore you to never forget this.",
	couple_encourage = {
		{
			{
				30402,
				30403,
				30404
			},
