_G.pg.base.ship_skin_words[304011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Good work in your sorties today. If you're hungry, I don't mind splitting my dango with you.",
	unlock = "We must fully live in the present, whether during work or during leisure - this is my mantra. Commander, shall we go for an outing together?",
	touch2 = "You... perhaps you're going to need a remedial course in basic etiquette.",
	mission = "",
	vote = "",
	drop_descrip = "We must fully live in the present, whether during work or during leisure - this is my mantra. Commander, shall we go for an outing together?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Commander, a break is not a break if you're constantly thinking about work. Besides, don't you think it's rude to be so preoccupied when you're supposed to be spending time with me? |I'm used to always going out with my sisters, so to be able to spend time with you outside is rather novel for me. |Commander, when the weather gets a bit warmer, why don't we go enjoy the cherry blossoms with my sisters?",
	touch = "You're awestruck by my beauty? Hehe, something as obvious as that needs not even be said~ ",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Such a tasteless rabble!",
	id = 304011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
