_G.pg.base.ship_skin_words[304013] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "It appears the commission team has returned. Shall we treat them to the tea I bought from the school canteen?",
	win_mvp = "Ah, the tailwind of victory. The very definition of envigorating, is it not?",
	home = "Splendid work. I'd imagine Haruna went off to see her clubmates... As for me? I suppose I'm doing the same this very moment, my fellow going-straight-home clubmate.",
	unlock = "It would be a shame to pass on this lovely weather, Commander. Why have a dull commute by train when you can enjoy a leisurely bicycle ride in the sunlight, hm? Heehee♪",
	touch2 = "Excuse me, have you even considered how you're going to explain yourself to the Morals Committee?",
	mission = "",
	vote = "",
	drop_descrip = "It would be a shame to pass on this lovely weather, Commander. Why have a dull commute by train when you can enjoy a leisurely bicycle ride in the sunlight, hm? Heehee♪",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "There is a number of school-related romantic things I hope to try at least once. For instance, walking home with my beloved, or making a lunch box and savouring it together... Oh, silly me, I've already done those! Heehee♪",
	main = "This outing has reaffirmed to me the reason why we fight – to restore peace to all the world.|Kirishima made this charm in her home economics class. It's quite well-made, don't you think?|It seems the manjuus fell asleep. Heehee, seeing their adorable at-rest faces somehow makes me think of my sisters.",
	touch = "Oh, do I have a petal caught in my hair?",
	voice_key_2 = -1,
	mission_complete = "The fruits of missions form the foundation of victory, as someone wise once said.",
	battle = "I excel in both theory and practice!",
	id = 304013,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Have you had a good rest, Commander? You've got a long day of school and office work ahead of you.",
	detail = "Walking with you and taking in the scenery is quite pleasant, actually. Say, how about showing me that vantage point with an apparently exquisite view Hiei spoke of earlier?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[304014] = {
	hp_warning = "",
	feeling3 = "",
	mail = "A letter... Phew! I managed to keep it from getting wet. Commander, you'd better read it quick.",
	expedition = "Everyone from the commission team is back. Black tea seems a little inappropriate in this heat... Yeah, I think we should bring them ice-cold juice instead.",
	win_mvp = "If only I could be this elegant during practice... O-oh! Don't mind me, Commander!",
	home = "Thanks for all your hard work. How about we take a break and enjoy the sea breeze?",
	unlock = "That was a big wave... I need to balance better on my board, or else... Commander, can I take your hand – Hm? What's slippery? I have no idea what you're... Hyah?! My swimsuit?!",
	touch2 = "Hyah?! Commander, now isn't the time for this...",
	mission = "Relaxing on the beach is nice and all, but you have a pretty big backlog of missions...",
	vote = "拉票描述",
	drop_descrip = "That was a big wave... I need to balance better on my board, or else... Commander, can I take your hand – Hm? What's slippery? I have no idea what you're... Hyah?! My swimsuit?!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I have to apologize. If not for that mishap, you and I could've been having fun surfing right now. ...You think the time we're spending together is more important than surfing? Gosh, do you have to say stuff like that out of nowhere...? *blush*",
	main = "You think it's too soon to practice in the ocean? Heheh, I think I understand being scared of the ocean. But I'm here with you, so don't you worry, Commander.|This board is much too small. Th-there's no way the two of us can... u-unless we stick really together...?|I've shown you such an inelegant side of me... Commander, please keep this a secret just between us! I'll do anything!",
	touch = "Commander, be careful you don't fall into the water.",
	voice_key_2 = -1,
	mission_complete = "Another mission completed. With these rewards... I could buy myself a new swimsuit!",
	battle = "Ride the waves... elegantly, now!",
	id = 304014,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Geez, if you have a free hand to pet me with, use it to hold on to the board instead... Hyah?!",
	feeling2 = "",
	login = "I'm trying to ride the board correctly, but it's really hard... C-Commander, can I lean on you for balance?",
	detail = "I know things can be too sudden to react to sometimes, but next time this happens, please try to help. In service of that, I'm going to have you learn to surf! Now, hold on to my hips, and... H-hey, wait a second!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[304020] = {
	hp_warning = "Commander... It's too early to give up just yet!",
	feeling3 = "That Kirishima... She's actually quite the popular one...",
	mail = "Are all of these new letters? Thank you for your hard work.",
	expedition = "Welcome back, everyone. Hopefully, none of you encountered any suspicious people?",
	win_mvp = "It was no big deal~",
	home = "Welcome back. The tea has just been brewed to the right temperature.",
	unlock = "I am the Imperial Ship Hiei, second of the Kongou-class, reporting for duty. Commander, where shall we go next?",
	touch2 = "Hehe. Commander, have you not gotten enough sleep yet?",
	mission = "Let's finish while we still have the momentum!",
	vote = "",
	drop_descrip = "Kongou-class fast battleship number two – Hiei.",
	feeling4 = "Being able to see everyone's smiles at the banquet makes all the hard work and preparation worth it.",
	lose = "Was I bested...?",
	feeling1 = "What a pity...",
	skill = "Be swept away by the raging waves!",
	upgrade = "Today's breeze feels more pleasant than usual.",
	propose = "So this means... \"We'll always be forever?\" Thank you very much. I'll gladly accept it - however... If anything was to happen to us, I hope that you would consider yourself first...",
	feeling5 = "Commander, after tonight's banquet... will you be free? Hehe, please look forward to it~",
	main = "*Sigh*... Whenever Kirishima comes to a banquet, all those kids that tag along with her usually end up making a mess of things... |When it comes to warfare, wisdom and courage are equally important. We can't count on another miracle if we discard proper planning and rely on blind courage. |Commander, I'll be able to protect you, no matter the situation. Hehe, I am called an \"Imperial Ship\" because I have that capacity after all~♪",
	touch = "I can take you anywhere the ocean reaches.",
	voice_key_2 = -1,
	mission_complete = "Hehe, shall we celebrate by holding a banquet tonight?",
	battle = "Hehe, shall we go enjoy the festivities?",
	id = 304020,
	gift_dislike = "",
	gift_prefer = "Hehe. Just what I like.",
	profile = "I am Hiei, the first Kongou-class battleship born in the Land of the Rising Sun. As an Imperial Ship, I witnessed the growth of our mighty fleet, and led our forces into the Battle of the Solomon Sea. Commander, have you finished your preparations? The banquet is about to begin.",
	voice_key = 30402,
	headtouch = "",
	feeling2 = "Ehehe~ Commander, is there something on your mind?",
	login = "There is nothing more relaxing than a banquet following a battle... By the way, Commander, I'm free after this...",
	detail = "Hehe~ Which do you prefer: matcha, or black tea?",
	couple_encourage = {
		{
			{
				30126
			},
			1,
			"Are you still waiting for your sister?",
			0
		}
	}
}


