_G.pg.base.ship_skin_words[304033] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "How's THAT, Kirishima?! I can battle even in a kimono!",
	home = "Hold the umbrella like this... then turn around and slightly loosen the kimono... Hmm, no, this isn't really my style... How does Hiei pull it off so– Commander?! You're back?!",
	unlock = "My dear Commander, is this dress that my sisters tailored for me to your liking? ...Okay, no, I can't do polite Hiei-speak like she can... So, anyway, h-how do I look?",
	touch2 = "What? Huh?!",
	mission = "You'd best stay focused on completing missions, Commander.",
	vote = "",
	drop_descrip = "\"My dear Commander, is this dress that my sisters tailored for me to your liking?\" ...Okay, no, I can't do polite Hiei-speak like she can... So, anyway, h-how do I look?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Getting dressed was easier than you might think, because I practiced it! See, you start from the bottom and... Oh geez!|When I say I'll do something, I'll do it right! I'll prove that even I can conduct myself elegantly, as one of Kongou's sisters!|I need to go over there, so come give me a hand, Commander... Nice, thanks. I'd rather not get my kimono soaked if I can avoid it.",
	touch = "Watch this, I've got a stylish move for you!",
	voice_key_2 = -1,
	mission_complete = "This isn't so easy to move in, but bringing the rewards here was easy as pie.",
	battle = "",
	id = 304033,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, you should get to work before Kongou gets mad at you.",
	detail = "I knew this kimono looked good, but your approval is what really sealed the deal, Commander. It might not be the best kimono ever, but I'll gladly take a better-than-passing grade from you!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[304040] = {
	hp_warning = "This is it... The beginning of the end!",
	feeling3 = "Haruna and I are twins, but to me she feels more like an annoying little sister.",
	mail = "You have mail. You must be really popular, Commander.",
	expedition = "You're knee-deep in paperwork... Want some help?",
	win_mvp = "When I use all my power, this is only natural.",
	home = "You're doing good work out there, Commander. For the next battle, what do you say about bringing me along?",
	unlock = "I'm Kirishima, the fast battleship! Now, Commander, there's a long road ahead of us, and we should walk down it together!",
	touch2 = "I'm right here, Commander. Face your partner square on if you're going to do that. Ahahah, look at you~ Now it's you who's embarrassed.",
	mission = "Hum, hum. What should I take home with me as a souvenir...",
	vote = "",
	drop_descrip = "Kongou-class fast battleship number four – Kirishima.",
	feeling4 = "You know, my big sisters are both really brilliant. That's why I have to work so hard not to hold them back... You think I'm brilliant, too? Hahahah, I'm happy to receive your approval.",
	lose = "Being able to meet one's demise in a battle of firepower might not be so unfortunate...",
	feeling1 = "Well, guess even you have problems you won't tell others about...",
	skill = "I see your weakness!",
	upgrade = "I wonder what'll become of me if these improvements continue...",
	propose = "I-I never would've expected an attack from you... Well, this is embarrassing... *A-ahem*! Then, to return the favor... Commander, whenever you need a dance partner, I'll be yours.",
	feeling5 = "There'll be a dance at a party Hiei is organizing, so... could you be my dance partner? I mulled over it a bit, but you're really my only choice... Huh? Normally, it's the man who asks his partner for a dance? Ahahah, right, how stupid of me...",
	main = "Searchlights? Ahahahah... The battlefield is no stage.|Why I wear this mask? Hahah, think you can guess why?|Kongou, allow me to help... What? Y-you don't want any help, huh...",
	touch = "Were you starting to feel lonely, Commander?",
	voice_key_2 = -1,
	mission_complete = "Those girls seem exhausted from their commission. Let's go and carry them back to the dormitory.",
	battle = "My cannons will decide this battle!",
	id = 304040,
	gift_dislike = "",
	gift_prefer = "Appreciate it, Commander.",
	profile = "I am Kirishima, the youngest of the Kongou-class fast battleships. I once bombarded Henderson Field and that battleship South Dakota. Searchlights... and Type 3 Shells? ... Aha, hahaha...",
	voice_key = 30404,
	headtouch = "",
	feeling2 = "Hiei manages to always stay calm, no matter the situation...",
	login = "Commander, is there anything I can help with?",
	detail = "Kongou brought me some tea. How about we drink it together?",
	couple_encourage = {
		{
			{
				10514
			},
			1,
			"Prove to me that you're worthy of being known as the Strongest Shield!",
			0
		},
		{
			{
				30401
