_G.pg.base.ship_skin_words[304050] = {
	hp_warning = "Perhaps a change of plans is in order...",
	feeling3 = "Superior tactics can only make up for differences in strength to a limited extent... *cough* *cough* ...That is why becoming stronger is still of paramount importance, Commander.",
	mail = "Commander, you have new mail. Might it be new intel?",
	expedition = "Commander, a commission has been completed. Also, I have some suggestions for potential candidates to send on the next-",
	win_mvp = "Now then, how can we make further use of this victory?",
	home = "Commander, were you able to make use of my strategic plans?",
	unlock = "*cough* *cough* Battlecruiser Amagi, reporting in. It looks like I should be able to fully utilize my abilities here. Commander, would you please brief me on our enemies?",
	touch2 = "Oh, Commander... I was contemplating some other things...",
	mission = "The next mission is...",
	vote = "",
	drop_descrip = "1st Ship of the Amagi-class Battlecruisers, Amagi",
	feeling4 = "*cough* *cough*... Commander, you've already earned my acknowledgment. Why not have a little more confidence in yourself?",
	lose = "Did I... make a miscalculation...?",
	feeling1 = "Swineherds like you are quite hard to find these days.",
	skill = "Ahahaha...",
	upgrade = "My health... seems to have improved a bit.",
	propose = "Commander... so you've chosen me, then? Hehe... From the beginning, I was prepared to lay my life down for your ambitions. But with this being the case, perhaps I should take better care of my body.",
	feeling5 = "Commander, if you truly care about me, *cough* then please keep moving forward with all your might. Your gallant victories and smiling face are the best medicine for me.",
	main = "The road ahead of us is perilous, but I believe that is also what makes the journey worthwhile. |Commander, there is no need to fear failure. As long as I am here, all setbacks are but fodder for our victories. |Akagi turned out... a bit differently from what I expected.",
	touch = "Ehehe... Oh, Commander, I was just thinking about what snacks I'd like to eat.",
	voice_key_2 = -1,
	mission_complete = "Mission rewards... we should think of the most efficient way to utilize them.",
	battle = "All right, let's proceed as planned.",
	id = 304050,
	gift_dislike = "",
	gift_prefer = "I wonder if something good happened to you, Commander? Heehee...",
	profile = "I am the nameship of the Amagi-class battlecruisers, Amagi. Along with Akagi, I was originally supposed to be converted into an aircraft carrier, but that plan was scrapped after a certain natural disaster. *cough* *cough* ... As you can see, my body is not in a great condition, but please do not worry about me too much.",
	voice_key = 30405,
	headtouch = "",
	feeling2 = "Information is a tactician's most valuable asset. Knowing more than your enemy is already half the battle.",
	login = "Commander, I've left today's combat operation plans on the table. Please take a look.",
	detail = "Don't let anyone get injured? Commander, that's quite the tall order, but I'm up for the challenge.",
	couple_encourage = {
		{
			{
				40701
			},
			1,
			"Akagi...? Oh my, I have the wrong person...",
			0
		},
		{
			{
				30701
			},
			1,
			"Akagi, follow the commander's orders, okay?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[304051] = {
	hp_warning = "",
	feeling3 = "",
	mail = "New mail has arrived — yes, it's good news. You need not be concerned.",
	expedition = "Commander, a commission has been completed. Shall I summon the returnees here once they are finished with their preparations?",
	win_mvp = "",
	home = "Thank goodness you're back. Everyone here at port was waiting for your safe return, Commander.",
	unlock = "Commander, are you here to pay me a visit? ...Ah, there is no need to be concerned about me. I made a promise to both you and Akagi that I would be mindful of my health.",
	touch2 = "Commander, I would advise you to pay closer attention to your surroundings before doing things like this...",
	mission = "Please entrust this assignment to Amagi.",
	vote = "",
	drop_descrip = "Commander, are you here to pay me a visit? ...Ah, there is no need to be concerned about me. I made a promise to both you and Akagi that I would be mindful of my health.",
	feeling4 = "",
	lose = "*cough* *cough*... I wonder if I am coming down with a cold...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Kaga's younger sister is quite skilled at drawing... As for my sister, well... Akagi has her own charming points~|I'm sorry for the trouble I've caused you due to my less than ideal health, but I would like to say... Commander, you have my deepest gratitude for looking after me all this time.|Would a light meal be to your liking, Commander? Kaga, Akagi, and I worked together to make this. We chose our dishes assuming that you would also be here to partake in our cooking. Hehe~",
	touch = "I'm not going anywhere, Commander. That's what you and Akagi wished for, after all.",
	voice_key_2 = -1,
	mission_complete = "The mission rewards have arrived. Please look over them.",
	battle = "First, let us assemble our formation.",
	id = 304051,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Oh my, what's this...?",
	feeling2 = "",
	login = "Commander, are you not going to head down to the ocean? There is no need to worry about me, so please enjoy your time with the others.",
	detail = "Is there anything I would like to tell Akagi? Of course, I have many things I would like to impart with her, but perhaps it would be more appropriate that she hears those words from you, Commander. And perhaps, that would be the more interesting way of doing things... Don't you agree? Hehe~",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[304052] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission is complete. Take it easy and relax, Commander.",
	win_mvp = "I'd love to hold a banquet to celebrate everyone's victory. Your thoughts, Commander?",
	home = "You returned right on time. How punctual of you, Commander. Hahaha, I'm just happy that my strategies could help.",
	unlock = "*munch*... Ah. Commander, the banquet isn't over yet. What brings you here? When a host sneaks out, that causes trouble for the person cleaning up after them... Heehee, I didn't say NOT to, now, did I?",
	touch2 = "Mm... I already know what you're thinking and feeling, Commander. Heehee!",
	mission = "Commander, may I accompany you on your next mission?",
	vote = "",
	drop_descrip = "*munch*... Ah. Commander, the banquet isn't over yet. What brings you here? When a host sneaks out, that causes trouble for the person cleaning up after them... Heehee, I didn't say NOT to, now, did I?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "*cough* *cough*... Ah. Commander, I'm just fine. It's not what you think—Oh, thank you. That you've given me tea rather than medicine is proof that you know me well, hehehe.",
	main = "I've heard that in Sardegna, they have banquets where you eat lying down. Why don't you try it out, Commander? Heehee!|Katsuragi, prattling on for too long will only bother the Commander. At least divide your monologue into two... No, four or five segments would be better...|Commander, I know the feast is bountiful, but try not to eat too much, okay? Call it... advice from an expert. Hahaha!",
	touch = "",
	voice_key_2 = -1,
	mission_complete = "Your mission rewards are here. Yes, I think the fruits of our efforts ought to be reflected in the coming banquet.",
	battle = "",
	id = 304052,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Care for some Sakura confections, Commander? Hiei and the others made a whole bunch, and I just can't stop myself... Heehee, I'm sure Akagi will be worried about me again.",
	detail = "Have you already seen Akagi? Heehee, good. She can never settle down unless you're around... No, it's not that she overthinks. I think she's a lot like Nagato, in that she tries to carry all of Sakura Empire on her back. Commander... Make sure you correct her course when she does.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[304060] = {
	hp_warning = "Hiei never leaves a job unfinished!",
	feeling3 = "Hrm... that's not right... Um.... Umm.... Commander? Can you help me with the parts I don't understand?",
	mail = "New mail... don't tell me... it's a summons!?",
	expedition = "Commission complete. I shall go to receive them.",
	win_mvp = "Such a victory goes without saying, 'tis but a trifle.",
	home = "That was a hard-fought sortie... Now then, I didn't make any mistakes, did I?",
	unlock = "Commander? When I grow up, I’m going to serve the strongest lord in the world! Oh... but for now, I don’t mind if you help me sharpen my skills.",
	touch2 = "Shameless pig!",
	mission = "Completing a mission is a glorious thing.",
	vote = "",
	drop_descrip = "Fast Battleship, second ship of the Kongou-class Hiei.",
	feeling4 = "Can I prepare the next party? Really!? I won't let you down!",
	lose = "....urk.... 'tis- 'tis but a trifle! A single defeat! Doesn't bother me at all...",
	feeling1 = "Kongou! I- I never want to see this Commander again in my life!",
	skill = "D- disappear with the waves!",
	upgrade = "Hiei won't let you down!",
	propose = "Surprised, aren't you? Hiei prepared this party just for you! After all, today is a very important day for me, because... welll... you're very important to me! There, I said it...",
	feeling5 = "What did you think of my party, Commander? Did you have fun? Hehe, well, the next one is going to be even better, so you definitely have to come, okay?",
	main = "Make merry? I'd love to! Where are we- oh, no. Now isn't the time for such things!|My sisters went to a place called \"Royal\" to study aboard... abroad? Study abroad. Hmph! I bet you don't even know what abroad is!|If you keep staring at me, I'm going to hit you with this! And it's going to hurt!",
	touch = "Do you have anything that needs doing? I must test myself yet!",
	voice_key_2 = -1,
	mission_complete = "Puff out your chest when receiving such honors!",
	battle = "Hmph! I shan't lose to the likes of you!",
	id = 304060,
	gift_dislike = "",
	gift_prefer = "C-could this be...?! Thank you sooo much!",
	profile = "Once my big sister Kongou comes back, we're going to shock the world! Until then, I need to work hard to become a leader worthy of her! But.... courtly etiquette is really hard.....",
	voice_key = 30406,
	headtouch = "",
	feeling2 = "I can do it myself. You go do something else, Commander.",
	login = "Good da- agh! Wahh... I hit myself with my sword.",
	detail = "Why are you staring at me? ...is my sword too heavy? I- I can take care of myself! It's none of your business!",
	couple_encourage = {
		{
			{
				30402
			},
			1,
			"I feel so warm……",
			0
		},
		{
			{
				30401
			},
			1,
			"Kongou! Please look after me!",
			0
		},
		{
			{
				30511
			},
			1,
			"L- Lady Mikasa! What shall I prepare for today's party...?",
			0
		},
		{
			{
				10117
			},
			1,
			"Little Bunny! I won't lose to you!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[304070] = {
	hp_warning = "Was there an error in my calculations...?",
	feeling3 = "You want to see me grow up healthy and strong? Umm... I understand the importance of this as your subordinate and ship, but... should I be doing anything special?",
	mail = "I wonder if there's any candy inside... Oh, it's just a regular letter...",
	expedition = "Commander, a commission has been completed. Should you be willing, may I propose a suggestion for our next task?",
	win_mvp = "Now then... how shall we press the advantage? Hehehe...",
	home = "Welcome back, Commander. Would you like to try some of our traditional sweets? ...If you'd like, I could also eat them with you.",
	unlock = "Battlecruiser Amagi offers you her humble greetings, Commander. *cough* *cough* ...Ah, I'm fine, I just seem to have caught a little cold... *achoo!* Aww...",
	touch2 = "Hm? Commander, I am currently busy thinking.",
	mission = "Unfinished missions still remain. We must make efficient use of our earnings...",
	vote = "",
	drop_descrip = "1st Ship of the Amagi-class Battlecruisers, Amagi",
	feeling4 = "*Nom*... Shoooo yummy... Oh, Commander, my apologies, I was just eating this bit of mochi... Hm, it's okay to finish it first? If, if you say so...",
	lose = "*cough* *cough*... I can't show something so unsightly to Akagi and the others...",
	feeling1 = "Commander, are you going insane because of my recent poor health...?",
	skill = "Heh heh...",
	upgrade = "I must also become stronger, so that I can protect Akagi.",
	propose = "You musn't, Commander... If you give this ring to me, then Akagi will... Huh, she's fine with it? ...I see, Akagi is all grown up as well... Wait, sorry, I should be focusing on giving you an answer first... But yes, it'd be an honor to accept this!",
	feeling5 = "Commander, it's time to take a break. Though you're always looking out for my health, your words wouldn't be persuasive if you didn't also take care of yourself. Here, I've prepared the bed for you~",
	main = "As expected of the head of the Royal Maids... Even I must stop to admire such an excellent cup of black tea... Mm~ hmm~|Akagi, Commander is your superior, not your subordinate. ...Jeez, if you end up causing even more trouble, you're going to get an earful!|Oops, I mistook the manjuus for dango again... It must be because I'm so hungry...",
	touch = "It's not that my clothes are slipping off, but... Oh, you don't want me catching a cold? Yes, I shall be mindful of that.",
	voice_key_2 = -1,
	mission_complete = "Mission complete, Commander. When can I confirm our next mission?",
	battle = "Let's proceed as planned.",
	id = 304070,
	gift_dislike = "",
	gift_prefer = "A direct attack on my heart... Quite the strategy. I'm impressed. Ehehe~",
	profile = "I am Amagi, battlecruiser from the Sakura Empire. Commander, I hope to grow up big and strong here at this port so that I may protect you and Akagi. In other words... I'll do my best to eat properly and sleep properly.",
	voice_key = 30407,
	headtouch = "Nngh... Commander, p-please stop...",
	feeling2 = "I shall do anything to protect Akagi, the Sakura Empire, and my friends here at this port. Commander, please give me your orders.",
	login = "Commander, I've put today's itinerary here as well as all the documents that need to be looked over. Hm...? I'm perfectly capable of handling this kind of workload by myself.",
	detail = "*cough*... *sniffle*... Ugh... I, I'm okay... I just ate too many sweets, and now I'm not feeling so good... *cough* *cough*... *sniffle*...",
	couple_encourage = {
		{
			{
				30701,
				30709,
				30710
			},
			1,
			"Akagi, don't cause any trouble for the commander.",
			0
		},
		{
			{
				30507,
				30508
			},
			2,
			"I'd better not catch you trying to intimidate the commander.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[304080] = {
	hp_warning = "Ah, I'm losing my balance...",
	feeling3 = "It's time for idol Kongou and the Commander's photo op! This is your special right – better yet, my special service for you.",
	mail = "How about we plan our next performance based on the latest trends?",
	expedition = "Leave afternoon tea preparation to me. Heehee, you do know the commission team has returned, don't you?",
	win_mvp = "An idol's victory must be elegant, after all. Heehee.",
	home = "Commander, wanna sit on these kitty paw cushions together? You'd be surprised how comfy they are.",
	unlock = "I'm Kongou, with the Muse System unit Cyanidin. You'll witness my elegance and idol charms, Commander. Heheh, get ready, because you'll never forget the sight of me on stage.",
	touch2 = "Okay... Don't be so greedy, now, okay?",
	mission = "You have new missions. Want me to go with you? Heehee, if you don't answer quickly, I'll take that as a yes!",
	vote = "拉票描述",
	drop_descrip = "I'm Kongou, with the Muse System unit Cyanidin. You'll witness my elegance and idol charms, Commander. Heheh, get ready, because you'll never forget the sight of me on stage.",
	feeling4 = "You've been taking such good care of our photo together... Heheh, in that case, I'd better take ten photobooks... no, a hundred photobooks of selfies for you! No, I'm sure you'd want a hundred photobooks of us together instead of just me, right?",
	lose = "Is this because I'm still not used to being an idol...? We'll have to retreat.",
	feeling1 = "Geez. You're lacking elegance, Commander.",
	skill = "It's time for the climax!",
	upgrade = "Phew... This show ought to be an easy success.",
	propose = "Oh, this is a... It seems clear that the love in my songs has reached your heart. Of course, your feelings... are clear as day when I hold your hand, too. Heehee♡",
	feeling5 = "Why did I volunteer for the Muse System? Heheh, I thought you might ask. If pressed, I would say that I want to use my singing and dancing to spread love and hope... Pfft, I'm joking. Really, all I wanted to do was show you my most elegant and beautiful side.",
	main = "I have black tea here. Commander, would you like some... Oh. Um, I already drank from that one...|*sniff, sniff*... What is that wonderful smell? Oh, my, it seems to be you, Commander!|You want to touch the ears? That's okay, but... Wait, you meant mine instead of the cat ears?! ...You were interested because they were all red? Th-that's just because my tea is so hot!",
	touch = "Well well, Commander. Do you have any requests?",
	voice_key_2 = -1,
	mission_complete = "Mission completed. As a reward, you may touch my hands... No, not the kitty paws on my rigging. MY hands.",
	battle = "Let our melody resound!",
	id = 304080,
	gift_dislike = "",
	gift_prefer = "Presents are nice and all, but... I'd prefer if you stayed behind as well~♪",
	profile = "I'm Kongou, the first Kongou-class ship. Every idol needs elegance and vigor, so my presence is sure to liven up Cyanidin even more... Heehee, how was that, Commander? Have you been taken in by my charms?",
	voice_key = 30408,
	headtouch = "Your hand is so warm that I find myself wanting to rub my cheeks against it like a cat. Oh... Do you think the kitty ears are influencing my brain?",
