_G.pg.base.ship_skin_words[305012] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Milord, I have brought the mail.",
	expedition = "",
	win_mvp = "Milord, I treasure the time I spend with you above all else.",
	home = "Milord, the last battle must have been very strenuous, yes? In that case, please come lie down and rest for a while.",
	unlock = "Being able to wait for my beloved in this homely attire... Milord, my life has changed so much since meeting you. *giggle*",
	touch2 = "M-Milord...",
	mission = "Milord, I believe it's time to complete your missions. I shall accompany you.",
	vote = "",
	drop_descrip = "Being able to wait for my beloved in this homely attire... Milord, my life has changed so much since meeting you. *giggles*",
	feeling4 = "Milord, I have a small request... but please promise not to laugh. I've always been jealous of the way Akashi jumps into your arms like a spoiled child, but... it's a bit embarrassing to ask... so, um...",
	lose = "",
	feeling1 = "Milord, have you grown tired of me...?",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Milord, being able to spend every day with you like this makes it almost feel like we're a married couple... Ah, um, please forget I said anything!",
	main = "Ah... oh no, look at the time... Milord, time passes so quickly when I'm with you. I forgot that I was supposed to take Yamashiro shopping... |Milord, do you know how to play Hanafuda cards? Ah, was it Souryuu who taught you how to play? Um, in that case... shall we play together? |Milord, the freshly washed blankets sure smell nice. Surely, they'll also be very comfortable to sleep on.",
	touch = "You'd like to take me out? Are you sure? Um, in that case... there are a lot of places I'd like to go with you. Ehehe~",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 305012,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "\"Dating\" is such an incredible word. Milord, even though I've become accustomed to living with you, my heart skips a beat every time I hear that word...",
	login = "Milord, I just made some snacks. Would you like to try some?",
	detail = "Milord, I feel my bad luck melting away when I am with you... Thank you very much.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[305018] = {
	hp_warning = "",
	feeling3 = "",
	mail = "I'll arrange your letters for you so you can read them at your leisure later.",
	expedition = "",
	win_mvp = "Congratulations on your victory, Commander. Heehee.",
	home = "I'll check the combat report for you, Milord. You can come lie down... There you go♪",
	unlock = "For richer, for poorer, in sickness and in health, to love and to cherish... May we be together forever, Milord.",
	touch2 = "If it'd please you, tonight, I could... N-never mind!",
	mission = "Milord, let me help. We can complete these missions together. Heehee.",
	vote = "",
	drop_descrip = "For richer, for poorer, in sickness and in health, to love and to cherish... May we be together forever, Milord.",
	feeling4 = "",
	lose = "This is no curse, but my own ineptitude... I'm sorry.",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "When I wear this outfit, I don't sense misfortune anymore... but I know that such things can't go away that easily. As long as you're by my side, misfortune can be... well, one of the spices of life, I suppose. Heehee, what do you think?",
	main = "We still need to clean up the venue back in the hills, don't we? But it was a once-in-a-lifetime event. I feel awful packing it up...|Milord, today's going to be sunny. Heheh, they say foxes' weddings lead to bad weather – maybe it was you who brightened things up?|By the way, Yamashiro said something about bridal training... You think I don't need that? Well, thank you...",
	touch = "Of course. You can ask me for anything.",
	voice_key_2 = -1,
	mission_complete = "The rewards manifest tells me that tonight's feast will be a luxurious one, Milord.",
	battle = "",
	id = 305018,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Milord, let's show them what we're made of!",
	feeling2 = "",
	login = "Welcome back, Milord. Let us pray for good fortune and begin our daily work.",
	detail = "Let's see, this should... Oh, Milord, thank you for your help! Electronics are still so difficult for me. I don't know if I'll be able to help you much...",
	couple_encourage = {}
}


