_G.pg.base.ship_skin_words[305051] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Commander, do you hunger? Then do partake of this dango.",
	unlock = "I shall be hosting the commander today. Manjuus, I beseech you to help me look my best. I am... *yawn* a bit sleepy... Urghh... what is that ruckus out there? C-Commander! When did you arrive?",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "I shall be hosting the commander today. Manjuus, I beseech you to help me look my best. I am... *yawn* a bit sleepy... Urghh... what is that ruckus out there? C-Commander! When did you arrive?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I-I'm only doing this because... I'm prepared to entrust everything to you, Commander! ...I won't let you take back your word now! I a-absolutely will not allow it!",
	main = "Good timing. I require your assistance in locating my lost clothes... Just so you know, I did not misplace them because I was playing around, understood?! |I sometimes envy Mutsu... Even though I have my freedom now, unlike when I was placed upon a pedestal and worshipped, I can't be carefree like her... |Commander, you should come visit me more often if you're not busy. Though Mutsu and Kawakaze keep me company, this place is still too spacious for my tastes.",
	touch = "Commander, did you plan to invite me out? ... Very well. Our interests happen to be in concordance.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 305051,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "*yawn* Oh... Commander? I desire a few more minutes of respite... Good night...",
	detail = "Commander, what are you going to do on your next day off? I-I would not mind hearing you out.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[305052] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Prostrate yourself before the might of the Sakura Empire!",
	home = "Kawakaze, prepare a cushion for the Commander. It would be inappropriate for only me to be comfortable.",
	unlock = "Perfect, you have arrived. As long as you are here, the usual moon-watching will prove to be much more enjoyable... Why don't you stay here today and rest for a while?",
	touch2 = "Wh-what are you doing?!",
	mission = "",
	vote = "",
	drop_descrip = "Perfect, you have arrived. As long as you are here, the usual moon-watching will prove to be much more enjoyable... Why don't you stay here today and rest for a while?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "C-Commander, I, um... \"th-the moon is beautiful tonight...!\" Gyaaah...! It's way too embarrassing... there's no way I could say that...",
	main = "The moon can be freely enjoyed throughout the year, but there are few opportunities for the two of us to gaze at the moon together... |Mutsu? Let her go out and play. Unlike Kawakaze, she has no awareness of her surroundings... Ah, b-but don't let her hear I said that!|Moon-viewing sake? This has indeed been quite popular, but I... Ah, f-forget it! If you want to drink, then treat yourself! ...after all, I'm not allowed to...",
	touch = "Do you wish to comment upon my attire? Hehe, don't underestimate the skill of the Sakura Empire's craftspeople!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 305052,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "What do you plan to do today? Do call upon me if you need my help.",
	detail = "Th-there's no need to be in a hurry to go outside, right...? It's spacious, quiet, and warm here... and you are authorized to pat my fluffy friend.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[305053] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Mm, the ingredients have been successfully purchased. I know not what delicacies can be made from these, but I am looking forward to the results!",
	unlock = "I heard that it is custom to play a \"sport\" at this kind of event, involving throwing pillows at others. Heheh, then I shall put the might of the Big Seven on display!",
	touch2 = "Hehehe... You alone shall be the target of my pillow barrages.",
	mission = "",
	vote = "",
	drop_descrip = "I heard that it is custom to play a \"sport\" at this kind of event, involving throwing pillows at others. Heheh, then I shall put the might of the Big Seven on display!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "I've been so looking forward to sharing a dinner table with everyone else! ...Y-you should join us as well!|I can't help but to feel like... being so carefree will hinder my work...|Phew... Being able to play with everyone s a lot of fun, but... I am a bit jealous of Mutsu's boundless energy.",
	touch = "A mock pillow fight? Very well, allow me to demonstrate the Big Seven's... Ack! Mutsu, don't start throwing things before I've finished talking!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 305053,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I have been informed that the things known as \"party games\" are quite enjoyable in the company of others. Will you instruct me on how to play them...?",
	detail = "I heard that it is custom to play a \"sport\" at this kind of event, involving throwing pillows at others. Heheh, then I shall put the might of the Big Seven on display!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[305054] = {
	hp_warning = "",
	feeling3 = "",
	mail = "I've brought the mail. Heheh, you may now praise me for my efforts!",
	expedition = "A commission has been completed. Yamakaze, the reports are appreciated, but must you be so loud every time?",
	win_mvp = "Bear witness as I bring absolute victory to the Commander and our friends!",
	home = "So you return. Hehe, if it means greeting one I care about, I am prepared to go all-out regardless of my attire!",
	unlock = "Though this is a splendorous dress befitting the occasion, it is too different from my usual attire... Mutsu and Mikasa have nothing but praise for it? If you say so, then perhaps... I can take your word. Hehe.",
	touch2 = "Do you... find me so irresistibly adorable today...?",
	mission = "These mission briefings... Hmm. Truly, there are many things beyond my own reckoning here.",
	vote = "",
	drop_descrip = "Though this is a splendorous dress befitting the occasion, it is too different from my usual attire... Mutsu and Mikasa have nothing but praise for it? If you say so, then perhaps... I can take your word. Hehe.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Mmh, I am not sure I will be able to maintain my dignity in this outfit... Stop teasing me already! You may think it's fine... b-but at least save it for when we're alone...|Musashi handles most of what I ask of her, but she seems to see my requests as a spoiled child's begging...|Do rest well on this day. I won't abide you pestering me to relax without following your own advice.",
	touch = "Does something trouble you? If it is beyond my power to help, you are free to ask Umikaze or Kawakaze.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 305054,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Oh... *blushes*",
	feeling2 = "",
	login = "Commander! Does my outfit please the eye? I-I changed all on my own, and I'm not sure I did a very good job...",
	detail = "I do not mean to grumble about the attire you chose for me, but... I wonder if Mutsu and the others might get the wrong idea. S-say... What was your motive for making me change into this?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[305055] = {
	hp_warning = "",
	feeling3 = "",
	mail = "New mail? People often send letters bearing their blessings around this time of year.",
	expedition = "I assume the commission fleet has returned? ...I suppose it would be better for you to go greet them first.",
	win_mvp = "",
	home = "Welcome back, Commander. Though I would like to welcome you back personally by taking your hand... that does not seem to be possible currently...",
	unlock = "C-Commander? What brings you here at such a time? I was just... trying to help everyone prepare for the New Year's celebrations... Ngh, why isn't this red string... coming loose at all?",
	touch2 = "Y-you cannot undo this string? Why does it feel like... you might be using it for your own ends...?",
	mission = "I know you have work to attend to, but... this current situation is rather, umm...",
	vote = "",
	drop_descrip = "C-Commander? What brings you here at such a time? I was just... trying to help everyone prepare for the New Year's celebrations... Ngh, why isn't this red string... coming loose at all?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I've heard that red string not only symbolizes good fortune, but also has the effect of bringing people together... In other words, the fact that you and I are bound together by this red string means... Haau... Wh-what am I saying! Were that to be the case, however... I don't think I would mind at all...",
	main = "The Dragon Empery's Spring Festival is truly a lively time of year... I would love to partake in these celebrations with everyone else, but... this red string seems to only be getting tighter and tighter...|There's an Empery saying that goes \"the New Year brings new beginnings,\" yes? Thanks to you, I've learned so many things, including how to be closer to others.|The color of the string pairs well with my outfit? Hmm... Thank you, but... is that why you've been staring so intently at me?",
	touch = "C-Commander... Are you trying to help untie me? Oh, in that case... very well...",
	voice_key_2 = -1,
	mission_complete = "I see you have completed your mission to perfection. As for the rewards... I'm not sure how much I can help you in my current situation...",
	battle = "",
	id = 305055,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "*sigh*... Your hands... are so warm...",
	feeling2 = "",
	login = "You're here, Commander. I was wondering, umm... how do I untie this red string?",
	detail = "I was trying to hang an ornament up to wish you good luck, not expecting that... I'd end up being put on display instead. Commander... would you mind helping me down from here?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[305058] = {
	hp_warning = "",
	feeling3 = "",
	mail = "My familiars helped bring the mail in. Ehehe, they seem to have taken a liking to you.",
	expedition = "A commission has been completed. Shall we take this opportunity to take a walk around the port?",
	win_mvp = "",
	home = "Waiting for a beloved person to come back... is a thing of joy as well, hehe...",
	unlock = "It may be presumptuous of me, but please take care of me from now on... Is that acceptable? S-Somehow, it feels a little embarrassing... Ahaha...",
	touch2 = "Uuhh... p-please, not right there...",
	mission = "I have arranged the tasks in accordance with your instructions.",
	vote = "",
	drop_descrip = "It may be presumptuous of me, but please take care of me from now on... Is that acceptable? S-Somehow, it feels a little embarrassing... Ahaha...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "My name is Nagato. Not the Nagato of the Sakura Empire, but of you only. Because you were the one who reached out to me and pulled me from the depths of my loneliness, I wish to always stay by your side. You... won't reject me, right?",
	main = "I shall fight on! At long last I have discovered, what it is that I fight for! |I shall never forget... the warmth of the hands that pulled me out from the shackles of my armaments... |What will the future hold in store...? For the first time in my life, I want to know the answer.",
	touch = "I never knew that being touched like this... could bring me so much joy...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "For the sake of our futures!",
	id = 305058,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "You are the only one who has the nerve to keep me waiting.",
	detail = "I am able to smile from the bottom of my heart when I am here. Yes, I am very fond of this place!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[305060] = {
	hp_warning = "I want to protect my friends!",
	feeling3 = "I know some things you're happier if you don't know about, but... I still want to know! Besides, aren't there lots of things you're happier if you do know about them?",
	mail = "This must be \"mail\"... I'll write a \"mail\" to you, so send me a \"reply\" later!",
	expedition = "Commander, some people just came back to the port!",
	win_mvp = "Commander, look! I saw a really pretty fish just now! What kind of fish was it?",
	home = "Hold still, Commander! I'm gonna perform an exorcism on you!",
	unlock = "Hello, I'm Mutsu! Nagato's little sister! Um, are you a commander? Why? How do you become a commander? Is it cool to be one? Tell me, I wanna know!",
	touch2 = "Commander, why are you touching me? What's the meaning behind it?",
	mission = "Commander, what's this mission about? ... What about this one?",
	vote = "",
	drop_descrip = "Nagato-class battleship number two – Mutsu.",
	feeling4 = "Commander, can we play? Umm, if you've got work to do, I can come back later. I have so much to ask, and also so, sooo much I wanna tell you!",
	lose = "Commander, it feels like my third turret's gonna...",
	feeling1 = "Commander... Just, why?",
	skill = "Mr. Kitty, hang on tight! I'm gonna get serious!",
	upgrade = "I'll give it all I've got!",
	propose = "So this means we'll be together as one? That's amazing! It really does feel like I'm together with you when I look at this ring! Why's that?",
	feeling5 = "What I wanted to ask was... umm... do you like me? Are my questions annoying? And... Oh, right! I wanted to say that I love you, and I love all the friends I've made here!",
	main = "Why do we need to write like this? Is it wrong to do it this way? Why?|I saw something interesting outside! Can I go check it out?|I wonder where those ants are heading... I wanna find out!",
	touch = "Ahahaha~! That tickles, Commander~! Ahahaha~",
	voice_key_2 = -1,
	mission_complete = "Commander? I put the mission rewards on my turret and brought them here! But don't wake up Mr. Kitty!",
	battle = "Combined Fleet! Uhh... move out!",
	id = 305060,
	gift_dislike = "",
	gift_prefer = "Yaay! Thanksies, Commander!",
	profile = "I'm Mutsu, second ship of the Nagato class! Nagato and I used to swap back and forth between being the Combined Fleet's flagship! Later on, Yamato took on the role, though! Isn't it amazing how much there is to see in the world~? My third turret? Uh... I think it'll be okay this time.",
	voice_key = 30506,
	headtouch = "",
	feeling2 = "Ever since Nagato and I were at Hashira Island, I've wondered... Why is the sky blue? Why can birds fly? Why do we fight? ... There are so many things I wonder...",
	login = "Oh, hi, Commander! Something I don't understand happened while you were away! Why do... (Mutsu began asking a series of questions.)",
	detail = "Commander, help me inspect my third turret!",
	couple_encourage = {
		{
			{
				30505
			},
			1,
			"Nagato~! Let's give it all we've got!",
			0
		}
	}
}


