_G.pg.base.ship_skin_words[305062] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Is this a written order...? Oh! No, this is a letter for you!",
	expedition = "I can hear Yamakaze's roaring! That means the commission team is back, Commander!",
	win_mvp = "I'm gonna give this to Nagato! Ehehe, I'm talking about these sweets, not the MVP!",
	home = "You're back, Commander! Are you hungry? Do you want a snack? Or do you want something else? What kind of drink do you want? I wanna know!",
	unlock = "Hmh? If fah foo, Fummamuh? ...*gulp*. I'm not lazing around! I'm just checking on the pastries that just came in! What are you doing here anyway? To \"taste-test?\" Or is there something wrong with the pastries? Why?",
	touch2 = "Hmm? Are you that hungry? Just give me a minute!",
	mission = "You've got new missions, Commander! Heehee, you'll have to tell me more about our menu later!",
	vote = "",
	drop_descrip = "Hmh? If fah foo, Fummamuh? ...*gulp*. I'm not lazing around! I'm just checking on the pastries that just came in! What are you doing here anyway? To \"taste-test?\" Or is there something wrong with the pastries? Why?",
	feeling4 = "",
	lose = "Sorry, it was m-my fault...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Mikasa! As much as I like our own desserts, I wanna try something new! ...You'll bake something for me? Hooray!|I have a survey for you, Commander! Ready? Okay, so... What do you think about our store? What's your favorite dessert? What drink would you order again? How do you feel about our service? Does the place feel clean? Do you... (Mutsu's questions kept coming for minutes on end).|I love talking to you, Commander! Hang on, I'm gonna call Nagato over! ...Aww, she said she's busy, so maybe next time! How come?",
	touch = "Here's a pastry for you, Commander!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Hombhimed Fheef! Faih fofh!",
	id = 305062,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "What do you wanna eat, Commander? Tell me, tell me!",
	detail = "Commander, you've gotta help me with the– Wait, no! Customers aren't allowed to help the staff! Hang on a sec!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[305070] = {
	hp_warning = "Not bad! You are worthy of facing my full power!",
	feeling3 = "Why do I wish to become stronger? Does that really require a reason? If I had to choose... it would be to defeat Amagi.",
	mail = "Catch, it's your mail.",
	expedition = "A commission has been completed. Speaking of commissions, are they any fun? I'd like to give 'em a try.",
	win_mvp = "Too weak! Come back and face me again once you've had some more training.",
	home = "Nothing is more exciting than defeating a strong enemy, don't you think?",
	unlock = "Hmm... is this the next place for me to flex my might? Very well. I am Kaga - Battleship Kaga. Make no mistake of it.",
	touch2 = "... Let me get a shot in first if you're going to do that!",
	mission = "Missions? If it's not combat-related, don't come looking for me.",
	vote = "",
	drop_descrip = "Tosa-class battleship number two – Kaga. ",
	feeling4 = "Commander, what should I do to become stronger? At first, I thought what I was doing was fine. But after seeing you and Amagi, I realized that it isn't enough.",
	lose = "Kuh! I'll remember your face...",
	feeling1 = "You aren't one of the strong that I seek.",
	skill = "Only the strong have the right to stand on the battlefield!",
	upgrade = "Ahaha! I won't disappoint you!",
	propose = "To be able to trust someone who always has my back, to be able to fight without reservation... this has always been my dream! And for that someone to be you, what more could I ask for?",
	feeling5 = "I sometimes feel like I can only become stronger through following your commands... Hehe, it's not a bad feeling though.",
	main = "Those puny carrier aircraft are \"strong?\" Nonsense. What's more, isn't it utterly insipid to fight without your own two hands? |As a secretary, the most frustrating thing is not having anything to do. Commander, don't you have anything you need me to take care of? |Amagi is a worthy rival, and the one who I respect the most. Even if you asked me to be her support, I would have no objections.",
	touch = "Commander, don't you ever get tired of being in that cramped office all day? Why not come out with me for some fresh air?",
	voice_key_2 = 305073,
	mission_complete = "Mission rewards are here, huh? I'll go grab 'em. I could use a bit of exercise.",
	battle = "A strong enemy? I'm looking forward to it. Don't let me down!",
	id = 305070,
	gift_dislike = "",
	gift_prefer = "How'd you wind up like this?",
	profile = "I'm Kaga, second ship of the Tosa-class battleships. Built as an improvement to the Nagato-class, I was to serve as part of the Eight-Eight Fleet Program. Amagi... I would like to fight alongside her someday. ",
	voice_key = 30507,
	headtouch = "",
	feeling2 = "Realize your weakness is nothing to be ashamed of, as long as you work hard to become stronger.",
	login = "Commander, why don't you warm up a bit before starting work?",
	detail = "Getting stronger isn't a spectator sport. Let me at 'em already!",
	couple_encourage = {
		{
			{
				30405
			},
			1,
			"Amagi, please don't go off to a distant place by yourself again",
			0
		}
	}
}


_G.pg.base.ship_skin_words[305080] = {
	hp_warning = "Hahaha... Battles fraught with suspense are always the most interesting!",
	feeling3 = "You are an odd one, remaining unfazed in the presence of the Sakura Empire's ships. Still, I do enjoy exchanging stories with you. What have you in store for me today?",
	mail = "A letter, eh? I would be grateful if even a third of the information in it is credible.",
	expedition = "You don't expect me to announce when a commission team returns, do you?",
	win_mvp = "It's over already? Hmph, I expected more from them.",
	home = "Did you see anything extraordinary on your expedition? You may find it inconsequential, but I am curious to know what you encountered.",
	unlock = "I am the nameship of the Tosa-class battleships, Tosa. I only serve those who I deem worthy. As for you... Well, I do not believe in making hasty judgments. For the time being, let me first assess your abilities.",
	touch2 = "Acting on a momentary impulse can have deadly repercussions. I do hope you're not getting any outlandish ideas.",
	mission = "A leader chooses their mission, not the other way around. You should take this principle to heart, Commander.",
	vote = "",
	drop_descrip = "Tosa-class battleship number one – Tosa.",
	feeling4 = "When I am alone, I let no rules or regulations restrain me; I push my will through. However, when you are present, I feel compelled to follow the rules and act with prudence. You are really something else, Commander.",
	lose = "Gah, so even I overestimate my abilities at times...",
	feeling1 = "Weaklings belong behind the shorelines. I have no business with someone who cannot handle even a tidal wave.",
	skill = "Bear witness to who reigns supreme!",
	upgrade = "You have an eye for talent, Commander.",
	propose = "Simply being given life in this world would've been enough for me, but now I've even been given a partner to spend said life with... Hmph, life is a long and arduous road, and I am happy that I get to walk it with you.",
	feeling5 = "Your ambitions and dreams are of no concern to me, but I know that you need me. Which, I admit, is also true in reverse. Our fates are intertwined, and we cannot afford to lose one another... Hahahah, isn't that right?",
	main = "Brute force – the most primitive, but also most effective approach. That said, I much prefer fighting with words over swords.|I do not shy away from using any trick required to achieve my goals. I would rather that than play by the rules and end up at the bottom of the sea.|Stay behind if you cannot fight. The weak should know their place from the strong – this is the belief my sister holds.|I am neither as forward-thinking as Amagi, nor as short-fused as my sister. What? What's incorrect? The part about my sister, or my description of myself?",
	touch = "Seeing as you have time to kill, why not practice your swordplay with me?",
	voice_key_2 = -1,
	mission_complete = "A mission has been completed, has it? Then don't loiter around, go and claim the rewards at once.",
	battle = "Hah, my rampage is soon to begin!",
	id = 305080,
	gift_dislike = "",
	gift_prefer = "You knew... I wouldn't be able to turn down something so precious... Hehe, quite the devious one, aren't you?",
	profile = "I am Tosa, the first Tosa-class battleship. My construction began long ago, but its completion never came... I have been an aircraft carrier, a battleship, a weapons testbed, and a target; they worked and reworked me to the bone. But now I am here, in this form, and I will not disappoint you.",
	voice_key = 30508,
	headtouch = "",
	feeling2 = "You are brave, lowering your guard around someone that could take your life at any moment. You say it's because you trust me? Hahahah. Trust. A fine word that is.",
	login = "Give me an engaging task, should you find one, Commander.",
	detail = "I hate the phrase, \"it's how it's always been done.\" The same mistakes will forever be repeated as long as fools keep spouting it.",
	couple_encourage = {
		{
			{
				30507
			},
			1,
			"Together with me now, my sister!",
			0
		},
		{
			{
				30405
			},
			1,
			"I am still no match for you, Amagi.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[305081] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "My sister is still on the way here? Hmph, then I will prepare you some food.",
	unlock = "An inspection? ...You're awfully gung-ho about your work considering how hot it is outside... Surely you wouldn't have some sort of ulterior motive?",
	touch2 = "Try this with my sister instead. Actually, don't; it would likely backfire on you...",
	mission = "",
	vote = "",
	drop_descrip = "An inspection? ...You're awfully gung-ho about your work considering how hot it is outside... Surely you wouldn't have some sort of ulterior motive?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "The shrine maiden and her sister, frolicking in the water... A rare sight to be had.|We could play a round of go if you are bored. I want a new opponent after playing against only my sister for so long.|You're in need of a snack? Sorry, I only just got these from my sister. That said... we could exchange side dishes, I suppose...",
	touch = "",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 305081,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Whew... It's nice to get to play freely, but I must take heed of all the extra attention this swimsuit draws to me...",
	detail = "You should avoid swimming too much as you're so sickly, Amagi. How tragic it is, a ship such as you being so frail...",
	couple_encourage = {}
