_G.pg.base.ship_skin_words[305101] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Good job on your sortie. Go ahead and take a seat anywhere you want. After I take care of the rest of my chores, I shall come serve you personally. Hehe.",
	unlock = "\"Welcome back, Master.\" Rather, that's what all the children at the café were saying to you when they greeted you at the door. Hehe, is this some new custom?",
	touch2 = "Comfort and solace await you in my bosom. No one shall be allowed to disturb you.",
	mission = "Since you're here, put your troubles aside for now. We can worry about your mission later.",
	vote = "",
	drop_descrip = "\"Welcome back, Master.\" Rather, that's what all the children at the café were saying to you when they greeted you at the door. Hehe, is this some new custom?",
	feeling4 = "",
	lose = "I'll have to tidy this mess up first...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "To celebrate this great victory, I shall see to it that our friends are served the finest refreshments. Hehe, naturally, it'll all be free of cost.|The item you ordered was never delivered? Worry not, I think I understand the situation... Sakawa, I'd like to have a word with you.|The girls have been giving it their all to make our pop-up café a success, and a few accidents are nothing we cannot overlook. If anyone feels aggrieved on this basis alone, then it is only fitting to teach them a lesson.",
	touch = "Is someone's service unsatisfactory? I shall go remind her then... That's not it? You just need me to handle an extra order?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Let us expurgate those who would muddy this tidy place!",
	id = 305101,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Would you like a savory appetizer, or perhaps something sweet? Hehe, open your mouth. Allow me to feed you.",
	detail = "Would you also like to help out with our pop-up café? Though, I don't mind if you just stay put over there. I can't help but worry when I am unable to see you...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[305102] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The girls who went out on commission are back. Your welcome, and these prizes, will be a suitable reward for them.",
	win_mvp = "A satisfying victory. Your joy and peace of mind are reward enough for me.",
	home = "Have you gotten a good look around? Then sit, rest, and watch as I break a new record.",
	unlock = "...Hmph. Hitting such a target is but an easy feat for me... Commander, tell me which prize you want. I'll win it, along with all the other ones I've been asked to get.",
	touch2 = "You know what they say about rabbits... don't you?♥",
	mission = "New missions. No matter how treacherous the situation is, a calm response will be more than enough to handle them.",
	vote = "",
	drop_descrip = "...Hmph. Hitting such a target is but an easy feat for me... Commander, tell me which prize you want. I'll win it, along with all the other ones I've been asked to get.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "If you're tired of games, then come and relax with me. I won't bite – in fact, I know plenty of ways to satisfy you... Heehee, good, good♥",
	main = "I'm used to festival shooting games. Heehee, I know how good a shot you are. Why don't we have fun and test our skills together?|Preparing so many waterpark attractions and entertainment for your friends... I admire your efforts, Commander.|Just as you entertain us with this park, we'd like to treat your eyes with these different costumes. Of course, I'm able to offer more services...|It's not the same as thunder-clad sword swings or cannon fire, but that makes it all the more challenging. Don't worry – just point me toward my enemy, and I'll do the rest.|Missed again... This water gun's handling is poor at best. I have to wonder if Akashi made it, rather than Owari...",
	touch = "Are you more interested in my gun... or the fabric of my clothes? Heehee.",
	voice_key_2 = -1,
	mission_complete = "Mission complete. May this bounty and these prizes reward your efforts.",
	battle = "Let's meet them with a threefold assault.",
	id = 305102,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Well met. This bunny outfit I picked to suit your tastes, this water gun... Don't you think they're perfect for this amusement park? I suggest you simply enjoy yourself...",
	detail = "\"The fox falls into the fortunate rabbit's trap,\" was it? Would you consider me the fox or the rabbit right now, I wonder? How fascinating... Heehee♥",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[305103] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "The heroic sight of you as you make your triumphant return shines more lustrously than any light... I hope you will take the time to bask in your glory.",
	unlock = "These garments are a far cry from my habitual formal attire... but changing into them for your triumphant return certainly has its own charm. Commander, allow me to add a touch of radiance to your victory celebration.",
	touch2 = "You are less reserved than usual due to this celebration... I shall gladly receive your passion.",
	mission = "",
	vote = "",
	drop_descrip = "These garments are a far cry from my habitual formal attire... but changing into them for your triumphant return certainly has its own charm. Commander, allow me to add a touch of radiance to your victory celebration.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I offer you all the applause in the world. In return, I ask that you entrust me with everything that you have gained tonight, from the delight of your victory to your exhaustion. I shall show you something to enrapture you more than any triumph. Hehehe...",
	main = "The radiance of this celebration glows solely for you and me. The tumult will eventually fade, leaving only stillness in its wake. I wish for nothing more than to spend that stillness with you.|The choice you faced at that corner and your bold decision to overtake... I bore witness to it all. It was magnificent, Commander.|You have overcome a great trial. Therefore, you may give yourself over to my support and the radiance of this celebration.|I invested all I had into cheering for you, and you seem satisfied by it... How will you reward me for my support of you? Hehehe...",
	touch = "These pom-poms, or an embrace... which is it that you seek at this celebration? Hehehe, I suppose the answer is clearer than any crystal.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 305103,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "You seem especially fond of me today... Hehehe, this is my reward to you.",
	feeling2 = "",
	login = "Well fought, victor. I have prepared a radiant celebration and ovation for you. You are tonight's lead and my sole spectator.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[305108] = {
	hp_warning = "As long as I have a reason to keep fighting...",
	feeling3 = "",
	mail = "A letter... Hmm. From afar, it seems?",
	expedition = "The commission team has returned. As you expected, they bring great spoils. Let's welcome them together.",
	win_mvp = "I offer to you promised victory, my beloved. Hehe.",
	home = "Welcome back. This time, I didn't misjudge the time of your return. Take a bath and relax yourself for now.",
	unlock = "Commander, the contract has been made according to your wishes. From now on, I will be your new refuge. Now, beloved Commander, are you prepared to live up to MY expectations?",
	touch2 = "Heehee... Give me all that you are, my beloved. I'm already prepared to receive you.",
	mission = "",
	vote = "拉票描述",
	drop_descrip = "Commander, the contract has been made according to your wishes. From now on, I will be your new refuge. Now, beloved Commander, are you prepared to live up to MY expectations?",
	feeling4 = "",
	lose = "One mustn't be reckless in battle. Failure is but the foundation of success. Let's reform our offense and try once more.",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Is something wrong? I sense hesitation... Do not be afraid of the hardships of your journey. As someone willing to give you everything, I'm happy to remove all obstacles from your path. All you must do is bravely march on to the promised future.",
	main = "The road may be long and treacherous, but if you keep on marching, you'll make your way to dawn. Only by continuing on, undaunted, can we find true beauty... I will journey with you, be the rock that you can lean on and take shelter behind. It's a blessing for me to be that person to you.|In this long life, it's fun to stop and smell the flowers on the roadside once in a while... This time of year is bursting with life. Why not stop with me somewhere we can forget the 108 vices?|What do you want for dinner? Or would you prefer a taste of romance instead? Don't worry. I won't disappoint you, my dear.|Devote yourself to your ideals and the future you envision... As long as I'm by your side, you can rely on me for anything.",
	touch = "This white dress... It has special meaning to you, doesn't it?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 305108,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Good morning, my beloved. Before you consider your plans for the day, please enjoy a breakfast made with love.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[305110] = {
	hp_warning = "Keep calm! This battle is far from over!",
	feeling3 = "If you don't have a plan to end a war, then you'd better not start one to begin with!",
	mail = "No matter how many medals and honors I receive... Ehehe~♪",
	expedition = "Without robust logistics, even the mightiest fleets will turn into a disorderly mob.",
	win_mvp = "Through righteousness comes prosperity. Such is the will of the heavens.",
	home = "Excellent! The scales of war are tipping in our favor!",
	unlock = "I am the one who braved a hail of bullets and shells to return to my homeland with glory and victory. I am Mikasa, pre-dreadnought battleship of the Sakura Empire and flagship of the 1st Fleet, awaiting your command!",
	touch2 = "You'd like me to be your dance partner at the next banquet? ... I-I suppose I have no choice...",
	mission = "Hmm, I'm in charge of today's fleet operations? Very well... the fate of our country rests... mmf! ... Why aren't you letting me speak?",
	vote = "",
	drop_descrip = "Shikishima-class battleship number four – Mikasa.",
	feeling4 = "Yes, I can tell you've been working hard. B- but! That doesn't mean you get to start goldbricking now!",
	lose = "So this what it must have felt like to suffer through the Battle of Dan-no-ura...",
	feeling1 = "You Showa-born brat!",
	skill = "Let every ship do her utmost!",
	upgrade = "Only the battlefield can separate the wheat from the chaff. ",
	propose = "You still got a long way to go to earn my respect! ... Hehehe, so that's why I better stick by you♪ 'Til you're too good even for me.",
	feeling5 = "You can't fire on all four boilers all the time. Listen, I'm going to look the other way while you take five... You've been wanting to nap on my lap? I-I guess that'd be okay...",
	main = "The victory at Tsushima did not occur by chance. |Royal cuisine? I'll pass... I've had enough of that. |Those things flying through the sky... Err, they're called \"ear-playings,\" right?",
	touch = "Even the most hardworking people sometimes have lapses of judgment. It is my duty to admonish you in times like these.",
	voice_key_2 = -1,
	mission_complete = "Very well. I shall plunder... I mean, receive the spoils of victory!",
	battle = "The fate of our country rests upon this battle!",
	id = 305110,
	gift_dislike = "",
	gift_prefer = "What a nostalgic feeling...",
	profile = "I am Mikasa, a Shikishima-type battleship, and last of the Six-Six Fleet shipbuilding program. I served as the flagship of the Combined Fleet, and won a glorious victory that honored the name of our country across the world.",
	voice_key = 30511,
	headtouch = "",
	feeling2 = "Thinking about how I won't see old friends from back in my day ever again, it's... Well, never mind. I have people who look up to me now, and I can't let them down!",
	login = "Until we've reclaimed our former glory, we must never stop pressing forward!",
	detail = "A flagship must lead from the vanguard. This is a self-evident truth.",
	couple_encourage = {
		{
			{
				70201
			},
			1,
			"We fight together for humanity itself!",
			0
		},
		{
			{
				30706
			},
			1,
			"Steel yourself! And press the attack!",
			0
		},
		{
			{
				30505
			},
			1,
			"Never fear, the Sakura Empire is your ever steadfast ally.",
			0
		},
		{
			{
				30701
			},
			1,
			"Be careful. Misuse that power and we're worm food.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[305111] = {
