_G.pg.base.ship_skin_words[305113] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Have you finished your work? Excellent, then feel free to spend the rest of your day as you please!",
	unlock = "Even I like to dress down and unwind from time to time. Oh? This is new and exciting for you? Well, you are welcome to come see more of it from now on! Hahaha!",
	touch2 = "Hey, hey, you're going to expose me at this rate.",
	mission = "",
	vote = "",
	drop_descrip = "Even I like to dress down and unwind from time to time. Oh? This is new and exciting for you? Well, you are welcome to come see more of it from now on! Hahaha!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "What should I do on this well-earned vacation...? Assembling model ships? Housework? Travel? ...Too many things to do...|Commander, do you think people would consider me slovenly if they saw me like this? No chance of that? Good, I see.|Nagato, do not excessively concern yourself with the opinions of others. Simply set your worries aside and enjoy yourself.",
	touch = "What's the matter? You want to give my clothes a rub? Haha, so you can tell the difference! Very good, very good!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 305113,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Though it is said that spring is the season of restful slumber, sleeping in simply because you feel like it... is no good at all.",
	detail = "Sometimes, Kongou will drop by and talk with me about the Royal Navy while we enjoy the scenery... Commander, would you like to join us next time?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[305114] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Our commission team has returned. Get excited for some new menu items!",
	win_mvp = "Hahaha! Seems like we'll have to jazz up that celebratory menu, eh?",
	home = "Excellent; you've returned in one piece! Ah, I suppose girls these days say, \"Welcome home, Master!\" Hmm... Maybe that sounds a bit too forced...",
	unlock = "Welcome to the Sakura Empire's pop-up café... Oh, Commander! Everyone's waiting for you. Now get your butt in here and experience the full extent of our fleet's hospitality! Don't be nervous, now! Hahaha!",
	touch2 = "Say, what kind of establishment do you think this is...?",
	mission = "I will take care of store management today. Commander, you focus on the mission.",
	vote = "",
	drop_descrip = "Welcome to the Sakura Empire's pop-up café... Oh, Commander! Everyone's waiting for you. Now get your butt in here and experience the full extent of our fleet's hospitality! Don't be nervous, now! Hahaha!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "People will get bored sooner or later if our menu is nothing but Sakura-style confections... Should we add some curry or Western snacks?|Mutsu, please! We all know you've got a sweet tooth, but the café's food is off-limits! We've got staff meals right over there.|Say, I ought to put my skills to the test. What would you like to eat, Commander? It doesn't have to be from the menu either.",
	touch = "Maybe I ought to take your order myself. Hahaha!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 305114,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Mhm, things are nice and tidy as always. On three, everybody! One, two, three... Welcome, Commander!",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[305115] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Oh, the commission team's back? Don't forget to get them some souvenirs while we're here.",
	win_mvp = "",
	home = "Let's stop and take in the peace you've brought us. Getting proper rest between fierce battles is part of your job! Heheh.",
	unlock = "I was worried when you said you wanted to go on a trip with me, but... I do like getting to go sight-seeing and try on new threads. Commander, let's enjoy this to the fullest! Hahaha!",
	touch2 = "Hey! No touching the sash! ...Phew. That scared me, y'know.",
	mission = "You plan the missions, and I'll plan the trip! ...Uh, how do you use this tablet, exactly?",
	vote = "",
	drop_descrip = "I was worried when you said you wanted to go on a trip with me, but... I do like getting to go sight-seeing and try on new threads. Commander, let's enjoy this to the fullest! Hahaha!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Huh, so this is the \"Beauty Looking Back\"... It's really embarrassing to hear you say that about me, though.|They weren't kidding when they said \"no road is long with good company.\" I just hope you're having a good time, too... Hahaha, that's what I like to hear!|Hmm. So there are famous mountains, historical sites, and even temples and shrines... I dunno if we'll be able to see all of this now. I say this calls for a repeat trip!",
	touch = "Hm? You wanna hear the story behind this dress? Then get comfy and prepare for a lecture from your guide, Mikasa!",
	voice_key_2 = -1,
	mission_complete = "Finished your mission? Good timing! I just finished checking out this tourist spot.",
	battle = "Battleship Mikasa is here! Let's do this!",
	id = 305115,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Even a nostalgic town feels different by your side, Commander. Go on; lead the way!",
	detail = "\"It's a little different from the other girls, but that just makes it suit me more,\" huh? Is it just me, or are you getting smoother by the day? Hah!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[305118] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Hehe♪ These medals and awards... are things I obtained with you by my side. Go ahead, burn the sight into your mind~",
	expedition = "",
	win_mvp = "As long as you put your mind to it, there's no war you can't win! Redouble your efforts, and keep up the good work!",
	home = "You brought everyone back safely, without a hitch! Spectacularly done, I must say. Hahaha!",
	unlock = "I, battleship Mikasa, from now until eternity, pledge to you my undying love and devotion. May we help each other, encourage each other, and walk side-by-side on the same path. I hope to meet your expectations, as unworthy as I may be.",
	touch2 = "You're working very hard, so I guess I'll allow this much...",
	mission = "Oi! Don't doze off on me! I promise I'll let you rest after you read through the mission! ",
	vote = "",
	drop_descrip = "I, battleship Mikasa, from now until eternity, pledge to you my undying love and devotion. May we help each other, encourage each other, and walk side-by-side on the same path. I hope to meet your expectations, as unworthy as I may be.",
	feeling4 = "",
	lose = "Are you telling me it's impossible, even with the Commander at my back...?",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "My Commander, don't slack on your studies. If you'd like, I'd be happy to teach you personally.|Tonight's menu... How about I make you naval curry that originates from a port I have an affinity with? Of course, it's simply exquisite.|So those are \"airplanes.\" The true potential of new things are often overlooked for quite some time. Do your best to not do the same.",
	touch = "Urgh, how in the world do you use this cellular phone thing? ...Grrrr...",
	voice_key_2 = -1,
	mission_complete = "Very good. Well done! We're done with the mission! You really should teach Zuikaku and the others how you do it.",
	battle = "Vanquish all evil! Crush the enemy!",
	id = 305118,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I can't get used to calling you \"Dear\" or you calling me \"Honey\"... Calling each other by what we already do would be easier? Very well, as long as you're fine with it...",
	detail = "Well, perfect timing. Hm... It looks like this size should fit you... As the one in charge, you can't neglect stocking up on necessities. Once we're in the middle of battle, even your best clothes can get all torn up in the blink of an eye. Make sure you to get some spares while we're still in the lull of peace.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[305120] = {
	hp_warning = "These guys are tougher than I expected!",
	feeling3 = "Thought as much. I'll help you with your training, then! Come on, out of your room and into the fresh outdoors for some jogging! And later, we'll do some sparring!",
	mail = "A letter, eh? If it's an open duel, then I accept their challenge! Oh, no duel, huh...",
	expedition = "That last commission was kinda mediocre... Still, they deserve a congratulatory moment. Want to come with me?",
	win_mvp = "Victory's ours. Heheh, now that was refreshing all right.",
	home = "I reckon we'll garner more fame by winning battles than by wasting time in port, don't you agree?",
	unlock = "Battleship Kii, reporting for duty! Is it true that I'd be able to fight without holding back over here? Heh, good stuff! I look forward to what the future has in store, and you should keep your eyes on me as well!",
	touch2 = "\"Friendly friskiness,\" is it? Hmm... Sure, I guess?",
	mission = "A new mission? If it's about turning hostiles to scrap, I'll get it done!",
	vote = "",
	drop_descrip = "Kii-class battleship – Kii.",
	feeling4 = "There's no fun in knocking a battle out of the park if nobody's there to witness it. Anyway, once this work is done, I'll go train with Hyuuga. After that, you, I, and Suruga will go for a drink with Ise! Sound good to you?",
	lose = "Dammit... Not enough firepower for the job, huh?",
	feeling1 = "I'm so tired of bosses that can't handle their subordinates, like you.",
	skill = "Let's give 'em a dazzling show!",
	upgrade = "Let's see how strong I've really gotten. Send me into battle!",
	propose = "I mean, we don't need to go that far. We're already dearly important to one another, aren't we? ...Don't worry, I'll still accept it! And of course, I'll keep on keeping you safe, just like I always have!",
	feeling5 = "People say you can push yourself harder if it's to protect someone. Then for everyone's sake, I, Kii, shall become the strongest battleship... Pfft, yeah right! Hahahahah!",
	main = "Tell me if anyone starts picking on you. I'll put them in their place! And I mean it, for the most part, you hear?|Mmghh! I'm feeling stiff after standing up for so long... What's up, Commander? Why are you blushing? ...My bra's coming off?|Hey, Suruga! What do you say to going drinking with me and the gang once work is done? Figures, always so antisocial... When people invite you, you should go with it!",
	touch = "Something on your mind? I might be able to help you with it.",
	voice_key_2 = -1,
	mission_complete = "We're wrapping up these missions nicely! Great!",
	battle = "Let's duke it out, fair and square!",
	id = 305120,
	gift_dislike = "",
	gift_prefer = "Not bad! I'll take it!",
	profile = "I am part of the Eighty-Eight Fleet Program: first ship of the Kii-class battleships, Kii. In short, I never got a chance to shine during the war because reasons... But now I have, and I'm going to use it to its fullest! If you have anything that needs doing, just say the word, Commander!",
	voice_key = 30512,
	headtouch = "",
	feeling2 = "You okay, Commander? You've had this tired, stiff look on you for a while now... You're not getting rusty like Suruga, are you?",
	login = "Look who's finally clocked in, hahahah! My trigger finger's gotten itchy, so let's get on with a sortie already!",
	detail = "Obviously I like being on the center stage with my massive cannons. Performance aside, their size alone boosts morale while intimidating the enemy. You get what I mean, Commander?",
	couple_encourage = {
		{
			{
				30405
			},
			1,
			"You're the brains, I'm the brawn!",
			0
		},
		{
			{
				30514
			},
			1,
			"Don't be shy! Let's do this with flair!",
			0
		},
		{
			{
				30503,
				30504
			},
			1,
			"Let's celebrate with a glass after we get back!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[305121] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Whoa, this drink is really good. Want a taste, Commander? Hehehe~",
	unlock = "Refreshing drinks, delicious food, warm sunshine... and a pool to beat the heat? Heh, isn't this the essence of summer?",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "Refreshing drinks, delicious food, warm sunshine... and a pool to beat the heat? Heh, isn't this the essence of summer?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Akashi sure got that vending machine and stall set up quick... She's ingenious, but only when there's money to be made...|Why the hesitation? It's just a pool. Nothing wrong with just swimming together with me, is there?|Really looks like Amagi, Akagi, and all the rest are enjoying the summer. All thanks to you, Commander. You should be proud.",
	touch = "Want to head to that other area? I'll come with you.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 305121,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "There you are, at last. Want to get something to eat, if you're hungry? Like dumplings, or a rice ball, or something.",
	detail = "Hey Suruga, let's go somewhere– Come on, don't be all \"I like it indoors\" and \"I'd rather not draw attention,\" just come out and enjoy the summer with us!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[305130] = {
	hp_warning = "I'm not 'boutta whine over a little damage and disgrace the Kii class...",
	feeling3 = "If I wasn't doing what I'm doing now, whaddya think I'd be doing? Me, I'd wanna run a shop dealin' in seasonal fruits and stuff... You feel me? We could totally set one up together.",
	mail = "Commander, there's a letter for you. Better check it sooner than later.",
	expedition = "Oh, right, the commish team just got back. Aight, better tell the Commander~",
	win_mvp = "Don't ya dare diss the bonds between us!",
	home = "Oh, 'sup, Commander? You sure look beat... Was the battle that much of a drag? How 'bout we go kick it at the teahouse to unwind?",
	unlock = "I'm Owari, and you must be the boss o' this here fleet... Nah, you're obviously the Commander! Ahahahah! Nice meetin' you!",
	touch2 = "So you get a kick outta touchin' me, huh? Good to know~♪",
	mission = "Huh? You've still got unfinished missions? What's up with that? Hmm... If you've got your hands full, I could help.",
	vote = "",
	drop_descrip = "Kii-class battleship – Owari.",
	feeling4 = "Ain't nothin' in the world people get right on their first try. War is like that, and love too – it becomes natural once you've practiced it... Whaddya mean, \"What do you mean\"? C'mon, Commander, put two and two together!",
	lose = "Maaan. This is seeeeriously lame~",
	feeling1 = "You're, like, kind of a crappy person. I just don't like being let down so much, y'know?",
	skill = "I'll show you hip and trendy~",
	upgrade = "Woah, hot dayum... Is this stuff dope as hell or what?!",
	propose = "God! I just can't stop thinkin' about you, whatever I do, like you're literally stuck in my head... What I'm getting at is: I'm crazy for you! Might as well stop fighting it and... accept it, y'know?",
	feeling5 = "Oh, man... I can't get you outta my head, and I can't focus 'cause of it... I give up... Whenever this kinda stuff happens, ya just gotta do or die and go straight for the goal! Commander, I l-love... *blushes* Wait, lemme get ready first!",
	main = "What? I messed up? Maaan, that's soooo lame... Huh? Commander?! How long 'ave you been there? S-stop lookin'!|An operation? I'm not very book smart, but I'm guessin' you put a lot of thought into it? Alright, I'll get Suruga in here to explain it to me!|You said you'd come 'n eat my home cooking, remember? You can bet yer behind it's gonna be good!|Ughhh, I give up! I don't have any clue how to solve this puzzle! Kii! Come help!",
	touch = "Yeah? You wanna hold hands with me? Sure thing~♪",
	voice_key_2 = -1,
	mission_complete = "What's this? This mission's done and dusted... Unless I'm imagining it? Surely not.",
	battle = "Show me whatcha got! Ahahah♪",
	id = 305130,
	gift_dislike = "",
	gift_prefer = "Woah, this is suuuper cute! Huh? You're giving it to me? Wooow~ you rock~♪",
	profile = "I'm Owari, Kii-class battleship number two! I was originally supposed to get built out, but that never happened for whatever random-ass reasons. Doesn't bother me one bit though. All that matters is, I'm gonna give it my all with you in charge~♪",
	voice_key = 30513,
	headtouch = "Hm? Whatcha doin'? You ain't gonna get three wishes for rubbing my head. Though, it does feel real nice!",
	feeling2 = "Try not to ask too much from Kii 'n Suruga, aight? If you've got a problem, bring it to me first of all! I don't mind one bit.",
	login = "Ah, Commander. Good timing. I just got some crazy fresh veggies. You wanna give 'em a taste?",
	detail = "I let others do the thinking – me, I'm just the brawn, pretty much. Complicated stuff kinda goes over my head... Haha~♪ Bein' dumb has its benefits, y'know!",
	couple_encourage = {
		{
			{
				30512
			},
			1,
			"Hey, Kii, you wanna hang out after this is done?？",
			0
		},
		{
			{
				30514
			},
			1,
			"Man, your smarts are on, like, a whole other level...",
			0
		}
	}
}


_G.pg.base.ship_skin_words[305131] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Heya, Commander! Good goin' out there. Want a towel? A drink? Or maybe... a piece~ of~ me~?",
	unlock = "I love hammocks and water beds 'cause they make you feel like you're floating on waves. It's the most relaxing thing ever~♪ You oughta hop on and try for yourself, Commander~",
	touch2 = "What are ya plannin' to do next? I wanna see where this goes~♡",
	mission = "",
	vote = "",
	drop_descrip = "I love hammocks and water beds 'cause they make you feel like you're floating on waves. It's the most relaxing thing ever~♪ You oughta hop on and try for yourself, Commander~",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "A barbecue's not a terrible idea, but if you ask me, it's fruit 'n ice cream weather right about now.|A vacation on a floating bungalow sounds pretty dreamy~♪ Oh, but wait, what if that turns me into a total couch potato? That'd suck.|I don't think anyone's gonna kill ya if you enjoy a little naptime with me... You down, Commander?",
	touch = "Heheh, you like how that feels, don't ya?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 305131,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Hehe, did I surprise ya, Commander? I think I threw together a pretty stylish bed... Wanna see for yerself?",
	detail = "I don't mind kickin' it with Kii and Suruga, but y'know, we could also keep relaxin' over here. If there's anything you want, these li'l guys will bring it right over~♪",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[305132] = {
	hp_warning = "",
	feeling3 = "",
	mail = "I looked through all the letters addressed to you. They ain't cursed or nothin', so go ahead and read!",
	expedition = "Sheesh! That looks mighty dangerous! Lemme have a look at it. A demoness can handle herself!",
	win_mvp = "Here's the dub you wanted, Commander!",
	home = "You want a break? That's your wish, then? Aight, I'll grant your wish if you gimme a hug♪",
	unlock = "Welcome, guest, to the Dwelling of Demons. I own this place. I will grant you any wish in exchange for a suitable price... Yeah! Recited it all in one go! I'm so goated!",
	touch2 = "Already satisfied? Sure there ain't nothin' else you wanna do? Remember – I'll grant ANY wish you have♡",
	mission = "Work ain't over yet? You shouldn't be workin' down here in the... Whatevs, I'll help ya out! In return, you gotta grab a bite with me after we're done!",
	vote = "",
	drop_descrip = "Welcome, guest, to the Dwelling of Demons. I own this place. I will grant you any wish in exchange for a suitable price... Yeah! Recited it all in one go! I'm so goated!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "You wish for... my love?! Daaamn, Comma– Ahem! My guest! That's nuts, just professin' your love like that to the lord of the house... O-okay, then the price is your lifelong freedom! 'Cause you're never leavin' my side♪",
	main = "The whip? Oh, it's for the naughty kids who don't keep their promises! It's got other uses too, 'course, like for instance... Hm? You wanna try it?|Man, fresh veggies are so delish. You think so too? Cool, then wanna harvest the field with me later? ...What? Demons aren't supposed to eat veggies?!|Huh? You wanna grant MY wish? Pretty gutsy proposal ya got there. Aight, I'm gonna think about my wish for later!",
	touch = "Huh? You sure you wanna get THAT close to me? Aight, then as the lord of this place, I allow you to sit here!",
	voice_key_2 = -1,
	mission_complete = "Huh? Already finished your work? But I haven't lifted a finger yet... Oh well! Time to get some food!",
	battle = "",
	id = 305132,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Watch it so ya don't cut your fingers! If you spill any yummy-yummy blood of yours in the Dwelling of Demons, you're gettin' eaten! Probably.",
	feeling2 = "",
	login = "Welcome back! So, figured out your wish to me yet? Anything's valid, remember that! Don't underestimate my abilities!",
	detail = "I got like, devilish servants creeping 'round in the dark, so you might wanna watch yourself... Keep you safe? Well, it'll cost you. Let's say... some seasonal fruits, how's that?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[305140] = {
	hp_warning = "Oh, for crying out loud! Just my luck!",
	feeling3 = "P-please! Offer your concern to other girls instead of me! You really don't need to constantly check how I'm doing just because I'm serving as your secretary!",
	mail = "It appears you have new mail. I'll confirm it on your behalf.",
	expedition = "The commission team has returned. Shall we set out to greet them?",
	win_mvp = "Fools! I've– I mean, we've won!",
	home = "Nicely done out there. Please don't mind me, go ahead and take some time to relax.",
	unlock = "Battleship Suruga, reporting for duty. It would seem that some threads of fate connect me to this port... No, don't mind my rambling. Please disregard that.",
	touch2 = "Whuah?! What are you doing...?!",
	mission = "I'd like to suggest completing these missions. It is your job to do as the commander, after all.",
	vote = "",
	drop_descrip = "Kii-class battleship – Suruga.",
	feeling4 = "Look, I do appreciate your concern, but you saying that in front of everyone is embarrassing! Could you not put me on the spot like that again? That'd be great!",
	lose = "Whatever, it's done and over now... Look, I don't want everyone to see this!",
	feeling1 = "*Sigh*... I set myself up for disappointment by expecting any decent treatment... Can I at least ask you to not go too hard on me?",
	skill = "I'm gonna smash you to pieces! ",
	upgrade = "It's meaningless to fight if you cannot win. As such, a few enhancements may prove necessary.",
	propose = "You have bizarre tastes in women, Commander... Anyway, this doesn't come as a shock to me; I've known for a long time that your feelings for me are sincere. I, Suruga, hereby accept your oath of love.",
	feeling5 = "*Sigh*...! People have their eyes glued to me wherever I go now, thanks to you... There are plenty of other ways to express your love without embarrassing me, you know! Please, Commander, I'd rather not deal with that again!",
	main = "I believe I'm better suited for a desk job where I can analyze data and draft new plans. The reason being my strengths lie in quickly reading, memorizing, and writing documents.|Reckless hotheads and I don't get along particularly well. So I've learned first-hand through bad experiences with a certain someone... That is not to say I hate those kinds of people, however.|I'm deeply grateful that you've elected me as your secretary. However, I would absolutely welcome the addition of more people to the office, as we're rather short-staffed with just me here.|I'm not a fan of battling, but if anyone picks a fight with me, then a fight they'll get. We were made to wage war, and so that is our responsibility.|Life is so peaceful at this port. For that, we can thank the many girls here who I don't hold as much as a candle to.",
	touch = "I will do as you order me to, Commander.",
	voice_key_2 = -1,
	mission_complete = "I've brought the mission rewards with me. Phew...",
	battle = "The Suruga Fleet w-will not disappoint...!",
	id = 305140,
	gift_dislike = "",
	gift_prefer = "You even figured out what I like?! ...I, I really admire that...",
	profile = "I am Suruga, Kii-class battleship number three. I sadly wasn't constructed in time for that infamous war... It seems some threads of fate have led me to join this fleet, one I shall devote all my soul to. It is my pleasure to serve you.",
	voice_key = 30514,
	headtouch = "I hope my horns were left alone... Phew, they were... Err, no! Never mind I said anything!",
	feeling2 = "I hope to leverage my meager secretary abilities for the betterment of the fleet. I'm always ready for your orders, Commander.",
	login = "Let's focus our attention on our work today. Don't be afraid to ask for my help, should you need it.",
	detail = "I've noticed those Priority ships are strikingly individualis– Pardon, I mean they have striking personalities. Not that I'm jealous, or anything of the sort.",
	couple_encourage = {
		{
			{
				30505
			},
			1,
			"Lady Nagato, I shall defend you!",
			0
		},
		{
			{
				30702
			},
			1,
			"Kaga, please... don't go overboard.",
			0
		},
		{
			{
				30405
			},
			1,
			"Amagi... I wish you could've been there for us...",
			0
		},
		{
			{
				39902
			},
			1,
			"If I wait just a little longer for my plan... No, I guess that's not happening...",
			0
		},
		{
			{
				30129
			},
			1,
			"Shimakaze! It's go time!",
			0
		},
		{
			{
				30512
			},
			1,
			"Let's go, Kii!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[305141] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "I owe my thanks to the girls who prepared this outfit for me. It'll help me get through the holidays without personally standing out. ...It'll have the opposite effect? Huh?!",
	unlock = "Good morning, Commander. Everyone else seems to be dressed up on this day of celebration, so this shouldn't be a problem, right?",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "Good morning, Commander. Everyone else seems to be dressed up on this day of celebration, so this shouldn't be a problem, right?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "You got this, Team Red! Mop the floor with those Team White clowns! ...Do you want to stay and watch TV with me, Commander? This match is definitely worth watching.|I always end up oversleeping on the day after the holiday's over... *Sigh*... Me dropping the ball when it really matters is not funny at all.|\"Treasure every moment of peace you get,\" as someone once said. We're only simple \"people\", after all.",
	touch = "I hardly ever get the chance to put this outfit on. Aren't you glad to see me wearing it, Commander? Hahaha~",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 305141,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Y-you don't need to stare at me...",
	feeling2 = "",
	login = "Good morning, Commander. What do you say we take this day off and relax?",
	detail = "I'm not much of a drinker, but I should at least have a little bit of social sake. What will you have, Commander? I could get you something alcohol-free right away.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[305142] = {
	hp_warning = "",
	feeling3 = "",
	mail = "You've got mail. Maybe next time I'll get Shimakaze to deliver it to you.",
	expedition = "",
	win_mvp = "Yeah! That's proof my strength means something!",
	home = "It's good to see you again. Now, if you'll excuse me, I have reports to read through.",
	unlock = "Oh. Fancy meeting you here... Walk to school together? Uh, sure! I know the way, so please just follow me.",
	touch2 = "A-at least give me a heads-up first!",
	mission = "",
	vote = "",
	drop_descrip = "Oh. Fancy meeting you here... Walk to school together? Uh, sure! I know the way, so please just follow me.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "You should probably not drink on the clock. You're meeting with Kii later today, remember?|I'm a study machine when tests are coming up. Hehehe~ Also, did you know? It's harder to get all questions wrong than to get them all right.|I'll draw unwanted attention if I do too good, so I should get this question wrong on purp– Err, nope, I didn't say anything!",
	touch = "",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 305142,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "If you need my help, please inform me. For what it's worth, paperwork is one of my strong suits.",
	detail = "Stupid Shimakaze... Why hasn't she showed up? She's the one who asked me for supplemental lessons...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[305143] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Let me just... There, all set. Ah, welcome back, Commander.",
	unlock = "This should do it. With how unremarkable my present is, I doubt it'll make any waves when the... Ack! Commander?! Why are you here?!",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "This should do it. With how unremarkable my present is, I doubt it'll make any waves when the... Ack! Commander?! Why are you here?!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Shimakaze! Go get all the destroyers' presents and leave them under the tree!|After a year of hard work, Christmas is finally upon us! And soon it'll be New Year's too! Whew.|Would you like an oversized sock? You can use it when you want a bigger present. Hehe.",
	touch = "No sneak-peeking at what's inside!",
	voice_key_2 = -1,
	mission_complete = "Try to keep an eye out so our presents don't get lost amid all the rewards.",
	battle = "",
	id = 305143,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I've left your present under the tree... Did you prepare a present for me as well?",
	detail = "Where's Kii gone off to? Actually, knowing her, she's spending Christmas drinking with her friends and having a great time. Me, I have better things to do than get drunk! Hehe.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[305160] = {
	hp_warning = "Hmph... I'll have to get serious.",
	feeling3 = "When I compose poetry, I tend to scrutinize every little word so I don't lose the rhythm. But when I get tipsy, I wear my heart on my sleeve. I'd like you to hear that some time, Commander.",
	mail = "Hmm? Did the wine I ordered arrive? Hehe, just kidding. There's mail for you, Commander.",
	expedition = "Oh, are the commission girls back? Hmm... Why don't we welcome them with ample drinks?",
	win_mvp = "Another battle done. Yaaawn... Time to go home, have a drink, and enjoy the scenery with the Commander...",
	home = "Welcome back, Commander. Want to relax with some Sakuran sake?",
	unlock = "Noble and majestic Commander, Oumi is here to serve... Hehe, I just wanted to say that. You don't care about boring formalities, do you? Instead, let's celebrate this meeting with a glass of wine.",
	touch2 = "Heehee~ Commander, does this count as a refined matter?",
	mission = "If you don't finish your work, you'll miss out on nature's beauty. Say goodbye to fun and elegance, I guess.",
	vote = "",
	drop_descrip = "Kii-class battleship – Oumi.",
	feeling4 = "Hehe, it's a beautiful day, and I have the wine you liked so much. Yes, everything's ready for our feast... Now, Commander, sit – Ah. I just used that cup... I guess you wouldn't mind that though, would you?",
	lose = "Life is full of ups and downs. Let's not dwell on every misstep.",
	feeling1 = "You don't really understand my verses lately, do you? Even this fine wine has become too bitter to swallow...",
	skill = "Heehee, the scent of wine can be dangerous~",
	upgrade = "Oh yeah, that feels good. I feel ready to write a tanka.",
	propose = "No matter how bland daily life can be, wine is enough to fill it with poetry. As long as flowers bloom in my heart, the whole world can be like a beautiful painting. Commander, let's keep walking through life's picture scroll together.",
	feeling5 = "I feel as if you and I might have shared a bed last night... Why do I sound uncertain? Hehe, because we were drunk, of course. Our cups were full of moonlight, and flowers were all around... Why, I'd share a thousand cups of wine with you if only to savor that elegant moment.",
	main = "Baijiu is too strong, but red wine is a touch too sour... If you're a drinker, how about you try some Sakuran sake? The aftertaste is to die for.|A haiku suddenly appeared on the wall? Ah... I might've written that while I was drunk and excitable. I don't remember what I wrote... You liked it? Then recite it for me, please.|\"The lights are lit, on the islands far and near: the spring sea.\" How about you and I go on the lake and raise a toast?",
	touch = "Hehe. Ready to while away the time with me, Commander?",
	voice_key_2 = -1,
	mission_complete = "Did you finish your missions? Then let's go out on a boat together. I have the perfect drink for today's scenery.",
	battle = "Hehe... Don't interrupt my reading, please.",
	id = 305160,
	gift_dislike = "",
	gift_prefer = "This is lovely! Close your eyes, Commander, so I can return the favor... Mwah!",
	profile = "\"Unheard of even in the legendary age of the awesome gods: Tatsuta River in scarlet, and the water flowing under it.\" I am Oumi, the fourth Kii-class battleship. Events prevented my completion once upon a time, but I've finally come. Will you be my quilt of autumn leaves, Commander?",
	voice_key = 30516,
	headtouch = "Hmm? How about you wait until I'm a little tipsier?",
	feeling2 = "Which of these two drinks do you think is better? Hmm? They're both fine? Hehehe, so you enjoy tea and wine equally. You understand elegance, Commander.",
	login = "Is that you, Commander? Hehe, I hope you didn't just come because you wanted one of my drinks... The weather is lovely. Let's indulge in the finer things – a boat ride on the lake, drinks, poetry...",
	detail = "\"Beneath the moonlight, shadows of flowers rustling, a path to be tread.\" Come, Commander. Let's walk amidst the flowers under the moon.",
	couple_encourage = {
		{
			{
				30512
			},
			1,
			"I already have the perfect wine to celebrate our coming victory.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[305161] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Oh, you're finally back... Can you untie me this time, please?",
	unlock = "Ngh... Hah... Commander, can you help me for a moment? ...Why don't you say anything? Don't tell me... you prefer me this way?",
	touch2 = "Oh, my... You're certain that I can't move, aren't you? Of course, there's only one thing in this world that can truly bind me – and that's you.",
	mission = "I'd really like to be untied right now, but your missions come first, I suppose...",
	vote = "",
	drop_descrip = "Ngh... Hah... Commander, can you help me for a moment? ...Why don't you say anything? Don't tell me... you prefer me this way?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Come a little closer, Commander. Support me so I can relax... Hehe, got you! As punishment for not untying me right away, you're stuck with me until I'm satisfied.",
	main = "Ugh... Tying the knot was hard enough. I'm amazed that it's even more difficult to untie... Commander, if you untie it for me, I'll teach you an even more enticing way to tie it.|\"In the sea of heaven, the waves of cloud arise. And the moon's ship is seen sailing, to hide in a forest of stars.\" That reminds me of when you and I sailed together. Um... Actually, maybe you should untie me before we reminisce?|Frankly, I'm not sure how we can share a drink in this state. I mean, this posture doesn't lend itself to the act very well... Hehe, you're right! Desperate times do call for desperate measures, no?",
	touch = "I hope you're not plotting anything evil right now...",
	voice_key_2 = -1,
	mission_complete = "Mission accomplished, hmm? How did I know? Come closer, and I'll tell you.",
	battle = "",
	id = 305161,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Hehe... Come over here, and you can touch me more freely.",
	feeling2 = "",
	login = "As you can see, my escape technique isn't quite perfect. Can you get a little closer, please?",
	detail = "I was practicing my escape artistry, but clearly I'm not good enough yet... Would you please come over and help me, Commander? Yep, just like that... Keep going...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[305170] = {
	hp_warning = "Urgh... I must... stay strong for everyone else!",
	feeling3 = "I-if I may be frank, I enjoy myself the most in your presence... But do not let anyone else hear that!",
	mail = "New mail? Hmm... It might be related to the port's resource allocation and long-term plans... I think you should prioritize this one.",
	expedition = "The commission team has returned! Naturally, it was my support from the rear that allowed everything to proceed so smoothly.",
	win_mvp = "With my fortune and martial prowess, victory is but a foregone conclusion!",
	home = "I completed a thorough patrol of the port during your absence, and discovered a place perfect for \"strategic maintenance.\" I-it's not a playroom! Regardless, perhaps you would assist in my inspection if you are not otherwise engaged?",
	unlock = "I am Musashi! Am I correct in thinking you are the Commander? Hmm... I fear I shall have to keep a close eye on you. From now on, I shall defend the peace of this port. As for you... you may simply hide behind me.",
	touch2 = "S-such insolence... Hyah!",
	mission = "A new mission has appeared, Commander. Let us break through with a single push!",
	vote = "",
	drop_descrip = "Yamato-class battleship number two – Musashi.",
	feeling4 = "I am incredibly powerful! But what if... IF a devilishly cunning enemy appeared, and I failed to protect everybody despite my best efforts... Would you think less of me, Commander?",
	lose = "Impossible!",
	feeling1 = "I... really do not want to talk to you right now.",
	skill = "Bear witness to my power!",
	upgrade = "I can protect you all the better now!",
	propose = "Wh-what is the purpose of this stuffy ceremony?! Hrmh... Starting today, I shall make you my most important retainer and... Ahem! What I mean to say is that you are the best that there is! You will stay by my side for all eternity and listen to my every order! Promise me that!",
	feeling5 = "It is my duty to protect everybody. However... if I could do more than protect you... if I could embrace and tend to your every need... perhaps I would be more motivated.",
	main = "Before going out to battle, you must decide which snacks you will eat upon your return to rouse your motivation! That is what it means to win a battle before it is fought!|Yes, another flawless patrol! The slides and swings are as safe as could be! Would you like to see for yourself, Commander?|Everybody in the port is giving their utmost. Commander, let us work just as hard and become examples for all to aspire to!",
	touch = "You wish to play with me? I-I suppose I can spare a little time.",
	voice_key_2 = -1,
	mission_complete = "Did you see that? My presence makes any mission easy as pie!",
	battle = "Follow my lead, everybody!",
	id = 305170,
	gift_dislike = "",
	gift_prefer = "You have brought me a reward? I suppose I can accept it! ",
	profile = "I am the Yamato-class battleship, Musashi! Fear not. I shall look after you, whether during work or play.",
	voice_key = 30517,
	headtouch = "Mmmrgh... What an affront to my dignity! Th-this won't be happening again...",
	feeling2 = "I must act as your guardian, Commander! You must stay close behind me so you do not get lost!",
	login = "Zzz... Uguh?! Oh, it is you! Ahem. The port is perfectly safe, thanks to my presence.",
	detail = "Commander, have you any new commands for me? I-if you wanted to play, you could always say so...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[306010] = {
	hp_warning = "",
	feeling3 = "My eyepatch? Kinda just started wearing it on a whim. Plenty of people out there who dress like pirates, you know?",
	mail = "Doesn't matter if it's a pigeon or a plane delivering your mail, does it?",
	expedition = "I was actually designed with these types of missions in mind...",
	win_mvp = "It was all thanks to my little planes.",
	home = "Planes, up on deck... It's time we all get ready.",
	unlock = "Light carrier Hiyou reporting in. Commander, I won't have you looking down on the Hiyou class just 'cause we're light carriers!",
	touch2 = "D-didn't I tell you I was lightly armored?!",
	mission = "A mission? As long as it ain't in the Marianas, I'll take it on...",
	vote = "",
	drop_descrip = "Hiyou-class aircraft carrier number one – Hiyou.",
	feeling4 = "My opinion of you has improved a little bit. Just a little bit, you hear!",
	lose = "It's pretty hard to ignore the damage done to my planes...",
	feeling1 = "So filthy... What? I'm not talking about you...",
	skill = "Planes... take off!",
	upgrade = "... Seems my technique's gotten more refined.",
	propose = "You've been real good to me, Commander... So, how about I be your lifelong partner from this day onwards...?",
	feeling5 = "I've sent out all my planes. Right now... there's just us two in here.",
	main = "Ah, Izumo... I'd like to meet her one day.|I'm pretty sure mine are larger than Souryuu's...|I'm slow-witted? Hmph, believe it or not, I'm a girl with a lot on her mind.",
	touch = "I'm lightly armored, so, uh...",
	voice_key_2 = -1,
	mission_complete = "If we keep earning honors, one day even I can become a full-fledged carrier...!",
	battle = "In the name of the wings of the sky: take off!",
	id = 306010,
	gift_dislike = "",
	gift_prefer = "Heh, you really get me.",
	profile = "I'm Hiyou, Hiyou-class aircraft carrier number one. I'm a light carrier, but my damage control and loading capacity are just as good as a regular carrier's. After Midway, I was a key part of the Mobile Fleet and fought hard to my very last battle...",
	voice_key = 30601,
	headtouch = "",
	feeling2 = "Junyou is... I know I'm warning you about my own little sister, but she's really dangerous...",
	login = "Heheh... Let's get some good work done today, Commander.",
	detail = "You gonna ask if I wanna go for lunch?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[306020] = {
	hp_warning = "",
	feeling3 = "I know all your favorite things, Commander.",
	mail = "Commander? Didn't I tell you not to write so many love letters~?",
	expedition = "Hmph, those girls need to learn to read the room...",
	win_mvp = "Ahaha, when I feel the Commander's love for me, I can't help but go a bit overboard.",
	home = "I trust you brought my favorite, just ❀like always❀...?",
	unlock = "Oh, Commander, it's gotten so late. You've kept poor Junyou waiting. Let's go home together, ❀like always❀.",
	touch2 = "I know exactly what you're thinking, Commander.",
	mission = "Oh, did you want to go on a date with me ❀again❀, Commander? What can I say...",
	vote = "",
	drop_descrip = "Hiyou-class aircraft carrier number two – Junyou.",
	feeling4 = "Our first time together? I know it was ❀back then❀, but how could you not remember...?",
	lose = "We lost? What are you saying, Commander? Don't you know Junyou ❀always❀ wins?",
	feeling1 = "Commander, don't tell me you want to break up?!",
	skill = "DIE!",
	upgrade = "My planes too...",
	propose = "Commander, you finally remembered... our ❀memories❀ and our ❀promise❀... Ahhh, I'm so touched... Hehe... Well then, just like we promised ❀back then❀...",
	feeling5 = "No! There's nothing wrong with me! I'm not sick! I'm not! It's just everyone else... why don't you remember!",
	main = "I wonder how I can make you remember, Commander...|Ryuujou... Where have I heard that name before...?|It's not funny anymore! You have to remember, Commander! We've been together ❀since the very beginning❀!",
	touch = "Commander? We've known each other for so long, you can be a little more forward...",
	voice_key_2 = -1,
	mission_complete = "That was a rich, full day. Now how about we go on a date somewhere?",
	battle = "You're trying to get between me and the Commander... I'LL KILL YOU!",
	id = 306020,
	gift_dislike = "",
	gift_prefer = "You really remembered what I like!",
	profile = "It's me, Junyou, your oldest friend! After those nasty girls tormented me so much, after all the fighting in the Aleutians, Santa Cruz, the Marianas, I finally got to see you again! I really don't know how you could have forgotten me... but please, hurry up and remember! Eheheh...",
	voice_key = 30602,
	headtouch = "",
	feeling2 = "The Marianas? I really... don't like it there...",
	login = "Commander, I will ❀always❀ be with you.",
	detail = "Don't you think... we're bound to be together, Commander? Ahaha.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[306030] = {
	hp_warning = "Looks like I can't afford to take it easy just yet.",
	feeling3 = "I look a bit like a courtesan? Hehe~ Well then, mister, it seems like tonight shall be our one and only night together. Let us feel the warmth of our embrace, then let the memories fade to nothing. How does that sound?",
	mail = "Commander, there's mail for you!",
	expedition = "Commander, your girls have returned from commission. I'll welcome them back now, but you should hurry over as well.",
	win_mvp = "Commander, will this be enough?",
	home = "Good work, Commander! Would you like dinner? A bath? Or perhaps... a drink first? Hehe~!",
	unlock = "Ah, it's the Commander... My name is Houshou, and I'll be in your care from now on. Please leave the children of the fleet in my care. I won't let you down!",
	touch2 = "Ahh! ... Commander, that's naughty. You can't touch me there.",
	mission = "You've got new missions, Commander. Care for a challenge this time?",
	vote = "",
	drop_descrip = "Aircraft carrier, {namecode:89}.",
	feeling4 = "A prominent person once praised my beauty, but to be honest, I am not so sure about myself. But if Commander was to acknowledge me, perhaps I could find my confidence. So... Commander, am I beautiful?",
	lose = "I'm so sorry, Commander...",
	feeling1 = "Is something the matter, Commander?",
	skill = "It's time for a feast!",
	upgrade = "Now I can help you even more, Commander!",
	propose = "My dream is to one day settle down with the person I love and open a small bar somewhere... Now, it doesn't seem like my dream is so distant anymore. Right, my dear?",
	feeling5 = "Commander, the moon is beautiful tonight, isn't it? I've prepared some drinks... would you like to stargaze together? I wouldn't do this for anyone else - this is a special service just for you, my dear.",
	main = "Having long legs isn't necessarily a good thing. A high center of mass makes it easy to tip over...|Commander, I prepared some snacks for us. Do you want to relax for a while?|It's amazing to see how much my younger sisters have accomplished, but sometimes it makes me a bit sad to see everything they've gone through...",
	touch = "Are you looking for me, Commander?",
	voice_key_2 = -1,
	mission_complete = "Commander is sure forgetful, always needing my reminder just to claim the rewards.",
	battle = "I'm not very skilled in real combat... but I shall not betray your expectations!",
	id = 306030,
	gift_dislike = "",
	gift_prefer = "My, oh my... You know exactly how to make a girl's heart quiver~",
	profile = "I guess you could say that I was the first aircraft carrier ever in the world. You could call me the eldest sister, or mother, of them all! Feel free to consult with me whenever you'd like, Commander. I'm always here for you.",
	voice_key = 30603,
	headtouch = "",
	feeling2 = "Want to take a nap, Commander?",
	login = "Commander, have you eaten yet? No? Let me make something for you. You can't head to work without first preparing your body and mind!",
	detail = "You're like a kid sometimes, Commander... Come over here~",
	couple_encourage = {}
}


