_G.pg.base.ship_skin_words[306040] = {
	hp_warning = "I-it hurts... I, I don't think... I can move for much longer...",
	feeling3 = "I had a feeling something good was going to happen today, and then... you were standing right in front of me! Chirp, chirp~♪ Isn't that lovely?",
	mail = "Your mail's here! I'm sure it's good news!",
	expedition = "You all went on an adventure to a faraway place, right? So, did you bring any souvenirs back? Surely you brought back lots of shiny treasures and gold coins, right~♪",
	win_mvp = "Victory! Looks like today's another lucky day!",
	home = "Welcome back, Commander! Where'd you go today? Did you do anything fun? Chirp, chirp! Tell me, tell me!",
	unlock = "Chirp, chirp! Here comes aircraft carrier Zuihou! I might be a carrier now, but I've also served as a tanker and submarine tender, which means I can do all sorts of useful things for you, Commander! ...Oh, right! This is for you! It's candy that'll bring you good luck!",
	touch2 = "Don't touch there! I'll get angry, you know!",
	mission = "A new mission has been posted! So, where should we go next? And what are we gonna do? In any case, let's head out together right now! Yes, now! This very instant!",
	vote = "",
	drop_descrip = "Zuihou-class aircraft carrier – Zuihou.",
	feeling4 = "Commander, let's play a game! Close your eyes, and open your mouth... Chirp~♪ So, do you know what I just fed you? ...Huh? It wasn't enough for you to really taste anything? Hmm, maybe the spoon I always use is too small...?",
	lose = "Oh no, we've been beaten... I knew it was a mistake to let my guard down...",
	feeling1 = "Commander, are you struggling with negative thoughts? Can you tell me about them? I'll try to help you figure something out!",
	skill = "Fly towards the light!",
	upgrade = "Luck smiles on me again! Thank you so much! In return, allow me to whip you up a tasty homemade meal!",
	propose = "What is this? Huh? You're really giving this to me? It's so sparkly and beautiful~! Hmm? I'm supposed to wear it? Like this? What am I supposed to do with it after putting it on? Eh? As long as I have it on, I'll never get lost?! Wow, I'm so happy I'll always be able to return to your side no matter where I go!",
	feeling5 = "Ehehe... Being together with you, Commander, is the greatest fortune I can ask for! So, I'll share some of my luck with you! Now, you'll be able to get any treasure you want, and all your dreams will surely come true~♪",
	main = "The last time I went to go look for some beautiful flowers, I ended up getting lost in the fog. But then, Unzen showed up and rescued me! Blessed be the Great Sage!|If things ever get dicey, I can just dive into the water! I can totally endure something like that! ...Huh? Why don't I just swim to safety? W-well, umm... that's because I can't swim...|Commander, I had a weird dream about a gourd last night! In the dream, delicious rice kept pouring from the gourd, and no matter how much rice I ate, more would just keep coming out. You know how happy that made me? And then, the gourd was so big that when I crawled inside, I could fit easily!",
	touch = "Chirp~♪ What a warm and fuzzy feeling... Ahhhn... Ehehe~♪",
	voice_key_2 = -1,
	mission_complete = "Mission complete~! Today's a lucky day as well, so let me see what our rewards are~!",
	battle = "Don't worry, I'm prepared for everything!",
	id = 306040,
	gift_dislike = "",
	gift_prefer = "Thank you, Commander! Want to stay for dinner? I'll make some really delicious rice for you!",
	profile = "The port here is so huge! Everywhere I go, there are friends to be made and fun things to do, but I always find myself in new and unfamiliar places without even realizing it... Hmm? You want me to tell you more? Sure thing~♪ Then, come have a seat right next to me. You can listen to my stories while you eat~!",
	voice_key = 30604,
	headtouch = "Chirp, chirp! I knew I could always count on you, Commander~♪",
	feeling2 = "Commander, if there's anything you'd like to do, I'll be there to support you! So, you can tell me about eeeeverything~ Okay?",
	login = "Good morning, Commander! Huh? You didn't eat breakfast yet? Aren't you hungry? Here, I brought you some hot tofu soup and senbei crackers! I can't finish it all on my own, so have as much as you'd like!",
	detail = "Commander, did you find something cool just now? Show it to me, please? Nnnngh...! Aww, I can't see anything... W-would it help if I tried hopping?",
	couple_encourage = {
		{
			{
				30605
			},
			1,
			" If you want to get luckier, you'll have to eat more!",
			0
		},
		{
			{
				30608,
				30609
			},
			1,
			" It's embarrassing when you call me your senior! Let's just play together instead!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[306041] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Commaaaander! Our friends are back! Maybe we'll get better rewards because of these lucky balloons~ Chirp, chirp~♪",
	win_mvp = "",
	home = "Commander, I've been waiting for you? Chirp? Oh, umm... It's not like I chose to stay here because I'm scared of getting lost or anything! >.<",
	unlock = "Commaaaaander~! Over here, over here! I'm right here! Chirp, chirp! Commander, come hand out balloons with me! Did you know these balloons can bring you good fortune? Here you go, the first one's for you!",
	touch2 = "Jeez... Stop that already. Bad Commander.",
	mission = "",
	vote = "",
	drop_descrip = "Commaaaaander~! Over here, over here! I'm right here! Chirp, chirp! Commander, come hand out balloons with me! Did you know these balloons can bring you good fortune? Here you go, the first one's for you!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I wonder, was I able to successfully share a portion of my luck with you, Commander? Ehehe... For some reason, whenever I'm with you, it feels like I'll be happy forever and ever! And this must be the best kind of happiness, right? Chirp, chirp~♪",
	main = "Huh? Fweeeeeh! Th-the balloons are going to carry me awaaaaay!! Phew... Commander, thank you so much!|The balloons are shiny and smooth in the sunlight! I love bright things! Chirp, chirp~♪|Something good is going to happen today! I know because I can feel it! Chirp, chirp~♪ See? I'm holding this lucky balloon, and I get to spend the day with you! And that's a wonderful thing!",
	touch = "Ehehe~ I'm flyyyying! Commander, you'll make sure to catch me, right?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 306041,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Commander~ Ahhn, Commander~ Ehehe♪ Chirp, chirp~♪",
	feeling2 = "",
	login = "Commander, here's your lucky balloon! I'm giving the biggest one to you!",
	detail = "If we give lucky balloons to everybody, then the whole world will be lucky, right? Ehehe~ just thinking about it makes me feel warm and fuzzy inside, so giving out these balloons isn't tiring at all~♪",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[306050] = {
	hp_warning = "",
	feeling3 = "I have no regrets 'bout what happened at the Coral Sea. I read we oughta accept our failures, else we won't learn from our mistakes! Eh? You think I'm amazin'?",
	mail = "Commander! The mail's right above ya~",
	expedition = "A commission's all wrapped up~! Let's go welcome everyone back!",
	win_mvp = "I've got the God o' Fortune by my side! Of course I'm gonna win!",
	home = "Need a rest? How 'bout I give your back a nice thumpin'?",
	unlock = "Commander, Shouhou's the name. I don't have a lotta firepower or planes like those regular carriers, but there's plenty o' stuff I can do that they can't! A real pleasure to meet ya!",
	touch2 = "Nnh... Stuff like this... is better saved for night~",
	mission = "Commander, there's new missions here!",
	vote = "",
	drop_descrip = "First ship of the {namecode:87}-class aircraft carriers, {namecode:87}.",
	feeling4 = "Commander, how do I become mature real fast? ...I'm fine as I am now? Really? But I'm always thinkin' I rely too much on you and my sisters...",
	lose = "How could I lose to those guys?",
	feeling1 = "Commander treats me like a li'l kid too... Yer makin' me sad...",
	skill = "It's show time, y'all!",
	upgrade = "I'm a li'l closer to becomin' an adult!",
	propose = "Eh? Commander, are y'sure this is going to the right girl? Someone as immature as me? ... I see, I've earned yer respect and recognition... Commander, from here on out, I'll do my best, so please continue to care for me!",
	feeling5 = "Mm... I got it now. Relyin' on others ain't such a bad thing! I won't be all jittery about growin' up faster now... Havin' that said though~ Commander, can I rely on ye even more now?",
	main = "Ah, Commander, I'm ready to give it my all t'day as well! Let's go stick it to those bad guys!|My big sis and Kaga are always lookin' after me, but one day, I wanna be more independent!|Commander, the weather's real swell today! What's with the gloomy mug? Let's play together!",
	touch = "I don't really mind, but you shouldn't be doin' that to others.",
	voice_key_2 = -1,
	mission_complete = "I brought the mission rewards!",
	battle = "Sisters, charge! Let's show 'em who's the star o' this show!",
	id = 306050,
	gift_dislike = "",
	gift_prefer = "Wow! This is one of my favorite things! Thank you!",
	profile = "I'm Shouhou, first ship o' the Shouhou-class! \nThe luck's a bit poor, but they ain't a thing I can do 'bout that.",
	voice_key = 30605,
	headtouch = "",
	feeling2 = "My children are all Shikigami - easy to store, but a pain to maintain! Y'all came at the right time - maintenance!",
	login = "I'll protect ya even if it means puttin' my own life at risk, Commander!",
	detail = "Ahh~ the folks always tell me, I'm gonna be a real beauty when I grow up~",
	couple_encourage = {}
}


