_G.pg.base.ship_skin_words[306060] = {
	hp_warning = "My life is burning bright!",
	feeling3 = "Commander, feel free to rely on me as you please. Should you will it, I will execute any command.",
	mail = "A telegram? Oh, it's not a combat report from Headquarters. I suppose there might be some value to reading it then.",
	expedition = "Worldly things are of little significance! The only things that matter are spirit and resilience!",
	win_mvp = "Despair... shall be your final destination!",
	home = "Don't break formation even when we head back to port! The glory of the Sakura Empire is in its meticulousness!",
	unlock = "Milord, I am called Ryuujou, a ranger from the Land of the Rising Sun! I shall lay down my seven lives to mete out justice in your name!",
	touch2 = "Eek!!! Oh, it wasn't Saratoga after all. However, you seem to be even more mischievous than she is.",
	mission = "A new mission is here! Whether it's combat or training, let's knock it out at the speed of sound!",
	vote = "",
	drop_descrip = "Ryuujou-class Light Carrier - Ryuujou",
	feeling4 = "Commander, did you prepare this meal for me by yourself? In that case, I'll be more than glad to dig in! Mm... thanks for the food! Eh? You'll continue to cook for me when I come back!?",
	lose = "Ugh... my body is all beat up...",
	feeling1 = "No matter where you are, the top brass is all the same...",
	skill = "As long as I am here, nothing shall stand in my way!",
	upgrade = "Thank you very much, Milord! Shall we go run a lap to test my new strength?",
	propose = "From now on, no matter what perils we might face, I will protect you with everything I have! Even if I sink to the bottom of the ocean, I will not permit any harm to come to you!",
	feeling5 = "Just being able to see your face before I sortie fills me to the brim with energy and makes me feel like I can't lose to anyone!",
	main = "Odango... these delicacies will cause my heart to waver, so... Um, I suppose I can reward myself a little.... Mmmh! So delicious! |When you're stressed out, you should go watch the fish swimming around peacefully in the aquarium. I'm not sure why, but it always calms me down. |I fight for a just cause! No matter who stands before me, I swear to give it my all!",
	touch = "Milord, please be careful. I am just as top-heavy as Illustrious.",
	voice_key_2 = -1,
	mission_complete = "The mission rewards are here! A bagel? Is this a snack for me? Thank you, Milord. Well then, let's move out!",
	battle = "Now, count up your sins!",
	id = 306060,
	gift_dislike = "",
	gift_prefer = "I would be grateful to receive any gift from you, Milord!",
	profile = "I am Ryuujou of the Sakura Empire, a seasoned warrior who has served in the First through Fourth Carrier Divisions, and participated in campaigns in the Phillipines, East Indies, Aleutian Islands, and Guadalcanal. I don't look the part...? Th-that must be because of that one incident at Iwate that stunted my growth! Milord, just you wait. I'll show you the extent of my capabilities!",
	voice_key = 30606,
	headtouch = "",
	feeling2 = "Milord, when it comes to war, victory is more important than good or evil!",
	login = "A day off? Milord, my week only consists of Monday, Monday, Tuesday, Wednesday, Thursday, Friday, and Friday!",
	detail = "Milord, we cannot survive unless we fight!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[306061] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Milord! C-could you please consider rewarding me with some potato chips?",
	home = "Splendid work, Milord! If you so like, come take it easy with me!",
	unlock = "*yawn*... Finally, a good night's rest... Now, to pick up where I left off on that RPG... M-m-m-milord, why are you here?! I wasn't slacking off or anything, I w-w-was just... Ughh....",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "*yawn*... Finally, a good night's rest... Now, to pick up where I left off on that RPG... M-m-m-milord, why are you here?! I wasn't slacking off or anything, I w-w-was just... Ughh....",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "These games and snacks are a sort of trial for me! Rest assured, Milord! My devotion will not be swayed by the likes of these items!",
	main = "I cannot believe how addictive this technological marvel of a game console can be...! B-but that's not to say it has no merits whatsoever! After all, if we could settle wars through these games, nobody would have to get hurt!|nil|C-can we really allow foodstuffs as devilishly tempting as these deep-fried chips of potato to exist in our society?!",
	touch = "Zzzzz... Milord?! Are we being attacked?! ...I lowered my guard and fell asleep? Forgive me for this shameful display!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 306061,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "*yawn*... O-one moment! I'll get myself in order!",
	detail = "It's good to always be ready for battle, but this isn't... so bad either, wouldn't you agree, Milord?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[306062] = {
	hp_warning = "",
	feeling3 = "",
	mail = "A new electronic message? Could it be an invite to a party?",
	expedition = "",
	win_mvp = "Quest complete! And without using any continues, too!",
	home = "I always strive to do my best, be it with video games or whatever else! My ambition is to be like the legendary L.I.!",
	unlock = "All right! Steady! Steadyyy! Gottem! Hahahah! Now I'll– M-Milord?! I-I'm just, umm... enjoying an after-school break!",
	touch2 = "Whuah! Oh no... Milord, your action just led to my death. Why did you have to do that?",
	mission = "",
	vote = "",
	drop_descrip = "All right! Steady! Steadyyy! Gottem! Hahahah! Now I'll– M-Milord?! I-I'm just, umm... enjoying an after-school break!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Through this game, I've deepened my bond with my friends, and made fun memories with you, Milord... I-I won't deny it came at some cost to my discipline, but even so, I am glad I got into this game!",
	main = "Yes! I dug up a rare material! Haha! It's true what they say about you bringing luck, Milord!|It's so convenient, being able to play a game anywhere you want, whenever you want... But I must have discipline! I must not let myself fall for temptation!|My homework? Rest assured, Milord, I completed it some time ago, as one should!",
	touch = "Do you wish to go on a hunt with me, Milord? Let me move over... There. Please, join me on the bench!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 306062,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "You came at a time most opportune, Milord! I would like you to join me for this Master Rank quest!",
	detail = "The character I've created is a brave and honorable samurai, much like myself!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[306063] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "No! Milord! I understand you want to take the slide again, but please don't cut ahead in line! ...You don't know where the line starts since you just got back from a sortie? Oh, my apologies!",
	unlock = "Milooord! *splash*... Heheh, behold the amusement park's crown jewel – the Meandering Megamanjuu Dragon Slide! If that's too long, it's also known as the Manjuu Octopus Slide. Personally, though, I think the former name is cooler!",
	touch2 = "Milord, just to be safe, hold on to me so you won't– Eek!",
	mission = "",
	vote = "",
	drop_descrip = "Milooord! *splash*... Heheh, behold the amusement park's crown jewel – the Meandering Megamanjuu Dragon Slide! If that's too long, it's also known as the Manjuu Octopus Slide. Personally, though, I think the former name is cooler!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Once I'm done showing you around here, I can take you to another attraction and– *tummy growls*... Oh, take a break, you say? O-of course! A break it is! Ideally, let's go to a place where we can eat while playing a game!",
	main = "Go with the flow like a dragon, ride the waves like a dragon! ...Hm? Is there... not much of a difference between the two?|There are not only submarines in the pool, but also mutant manjuus, you say? Rest assured, I shall make quick work of them!|The stalls in this park sell pretty good food! If you're hungry, Milord, allow me to make a recommendation!",
	touch = "Are you afraid of heights, Milord? If so, please sit behind me! I'll cover your eyes with my tail so you can't see below you!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Watch! This shall be the highlight!",
	id = 306063,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Th-that tickles, Milord!",
	feeling2 = "",
	login = "These slides are quite jumbled together, so reaching the peak without a guide is a very tall order. Milord, if you wish to take the slide again, allow me to be your guide!",
	detail = "Milord, let quickly us move on to the next attraction! Time waits for no one!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[306070] = {
	hp_warning = "Ugh, at a time like this...!",
	feeling3 = "Commander, are you interested in things like commendations or admonishments? ...N-No, it's nothing. I was just curious...",
	mail = "A letter has arrived. I'm curious about its contents... Are you not?",
	expedition = "The commissions have been completed. I shall go ahead and greet them first. ...I hope their bounty is plentiful.",
	win_mvp = "Unperturbed by both victory and defeat. This is my pride as a member of the Sakura Empire... hehe!",
	home = "Good work, Commander. Let's take a short break. ...But you shouldn't rest for too long, because we're going to review some battles right after this!",
	unlock = "Remodeled Taigei-class Submarine Tender, Zuihou-class Light Carrier Ryuuhou, reporting for duty. I will strive to bring you victory, Commander! Yes, this time, I won't be held back by failures on my path to victory!",
	touch2 = "Wicked thoughts, begone!",
	mission = "A new mission... If it's a directive from the top brass, let's take care of it right away.",
	vote = "",
	drop_descrip = "Ryuuhou-class light aircraft carrier – Ryuuhou.",
	feeling4 = "I take pride in the honor I have earned with my two hands. And that honor becomes fuel for further progress. ...Th-Thus, Commander, I implore you to send me out on sorties more often!",
	lose = "I-I shall let you win just this once!",
	feeling1 = "Commander, for some reason, you seem really unapproachable...",
	skill = "Victory is in my grasp...!",
	upgrade = "I'm truly grateful for your kindness, Commander.",
	propose = "I, Ryuuhou, vow to be at your side, through thick and thin... W-Well then, from now on, I will not hide any part of myself from you, so prepare yourself... okay?",
	feeling5 = "Commander, because I have been by your side, I have been able to demonstrate my true ability. Thus, would it be okay to be my true self when I am beside you...? M-My true self usually leaks out quite often? I-Is that so?!",
	main = "Looking after submarines is really rough... Th-This is from personal experience, so please believe me! | It's in my personality to not care what humans may think about me. This is the attitude that us warships ought to have as warriors.|From time to time, I become envious of the standard carriers... If only... I could be as strong as them...",
	touch = "Commander, are you able to fathom this majestic outfit that impeccably balances both beauty and dignity?",
	voice_key_2 = -1,
	mission_complete = "We were able to handle the mission flawlessly thanks to your hard work, Commander.",
	battle = "I've been pent up for a while. You'd better believe I'm going to give you a piece of my mind!",
	id = 306070,
	gift_dislike = "",
	gift_prefer = "Sorry for putting you to such trouble. I appreciate this so very much.",
	profile = "While I was able to set sail many times during my time both as a submarine tender and as a light carrier, in the end, I was unable to take even a single step away from port... No, nothing will happen if I just sit around like this. As I have stated many times, I, Ryuuhou, will bring you victory!",
	voice_key = 30607,
	headtouch = "",
	feeling2 = "The sea of the Sakura Empire is nostalgic, but I also have murky and mixed feelings about it... No, that's got nothing to do with me right now. Focus, focus.",
	login = "You have kept me waiting... No, it's nothing. I can deal with this.",
	detail = "I learned the power of submarines firsthand in that great war. While it's too late to turn back now, I can't help but wonder how I would be perceived if I hadn't been remodeled into an aircraft carrier. ",
	couple_encourage = {
		{
			{
				30601
			},
			1,
			" Let us go together!",
			0
		},
		{
			{
				10707
			},
			1,
			"You're from that time...",
			0
		},
		{
			{
				30603
			},
			1,
			"Houshou! Let's do our best together!",
			0
		},
		{
			{
				8
			},
			1,
			"Ahhhh, please don't hug me right now!",
			1
		}
	}
}


_G.pg.base.ship_skin_words[306071] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "You can leave the purification to me if Fusou and Yamashiro are both busy, all right? After all, I happen to be quite knowledgeable about that subject.",
	unlock = "Commander, everyone seems to be busy with end-of-year preparations. If there is anything I can do to help, please let me know.",
	touch2 = "...W-What are you planning...?",
	mission = "",
	vote = "",
	drop_descrip = "Commander, everyone seems to be busy with end-of-year preparations. If there is anything I can do to help, please let me know.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "The thing about Junyou is... Well, Commander, if something's bothering you, you can consult me, you know? | Because I'm in Shigure's debt, I cook her some food from time to time. She's really a good girl, even if she doesn't always act like one. | Commander, would you like to write an Ema? Even if your wishes don't get fulfilled, it's still great to just be able to write down your thoughts.",
	touch = "Hehe... Commander, are you here to enjoy some sweet sake as well? Don't worry, you won't get drunk...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Full force ahead for the Commander's victory!",
	id = 306071,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Good work, Commander. Please allow me to prepare the hamaya!",
	detail = "I control my carrier-based planes with this charm... A carrier cannot fight a foe face-to-face after all. This katana is merely a last resort.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[306080] = {
	hp_warning = "This is bad... I hope Chiyoda... is alright...",
	feeling3 = "I don't dislike having to pamper Chiyoda... If anything, I might actually find it quite endearing...",
	mail = "There's a letter addressed to you. Please check it out.",
	expedition = "The commission team has returned safely. What a relief.",
	win_mvp = "I'm glad... that I was able to be a help to everyone else.",
	home = "I'm glad you're safe... I made a protective charm for you, and also one for Chiyoda. Please keep it safely inside your clothes.",
	unlock = "I am Chitose, light carrier of the Sakura Empire. Commander, I look forward to receiving your guidance. By the way, is it true that Chiyoda is also here? ...Don't worry, I was merely inquiring.",
	touch2 = "Hah?! Wait, no...!",
	mission = "Here are some more missions. Isn't it bad to let them pile up like this?",
	vote = "",
	drop_descrip = "Zuihou-class aircraft carrier – Chitose.",
	feeling4 = "Cooking, cleaning, even taking care of my things... Chiyoda takes care of it all. ... Basically, it's not that I can't do these tasks. If I put my mind to it, I can do it... I totally can...",
	lose = "We're pulling back. Chiyoda, please be safe...",
	feeling1 = "Commander. Get away from Chiyoda. As far as you possibly can.",
	skill = "Attack force, surround them...!",
	upgrade = "For the time being, thanks, Commander.",
	propose = "If that's how you feel about me, I'll gladly accept your feelings... I'll pray for your safety every day, and be your refuge from your daily hardships. I hope... you'll come look for me whenever you're feeling troubled, because I want to pamper you like I do with Chiyoda...",
	feeling5 = "Commander, won't you rely on me some more? I'm actually pretty good at spoiling people, you know... Oh I know... would you like me to give you a lap pillow, or something...?",
	main = "Isuzu... is quite a scaredy cat, but she's a good girl. But even that side of her is cute.|Chiyoda always insists on doing my hair this way, so I let her. However, I always feel a bit apologetic for making her do so much...|I'm at least confident in my Kagura dancing skills. If you get the chance, please come and watch.",
	touch = "Who?! ... Oh, it's you. I thought it was a prank from that pink-haired Union girl.",
	voice_key_2 = -1,
	mission_complete = "The mission is... complete. That's good.",
	battle = "I have to make sure to be careful...",
	id = 306080,
	gift_dislike = "",
	gift_prefer = "This is really nice. ...Thank you.",
	profile = "Though Chiyoda and I were originally designed as seaplane tenders, during a certain war, we were remodeled into aircraft carriers. Whether it's due to my lack of skill or my inability to oppose the passing of time... I wasn't able to be of much use until the end.",
	voice_key = 30608,
	headtouch = "Do you like touching my bangs like Chiyoda does?",
	feeling2 = "The one thing I hope I never have to see again is the formation of a \"decoy fleet\"...",
	login = "Oh, you're here. There's some red bean jelly from Chiyoda on your desk. Feel free to take some.",
	detail = "Chiyoda and I are partners in carrying out shrine duties. Even though Chiyoda can be pretty annoying at times, there are still times she's fun to be around.",
	couple_encourage = {
		{
			{
				30609
			},
			1,
			"Alright, alright... We'll go together.",
			0
		},
		{
			{
				10703
			},
			1,
			"D-Don't call out to me so endearingly...",
			0
		},
		{
			{
				30205
			},
			1,
			"I'm here. There's nothing to fear.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[306081] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Commander, you're sweating so profusely. Are you okay? ...Here's a towel. Let me wipe you down.",
	unlock = "An order of coconut milk... and grilled sausage. Mm, that should do it. ...Hm? Commander? Are you here to place an order, or to get away from the heat?",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "An order of coconut milk... and grilled sausage. Mm, that should do it. ...Hm? Commander? Are you here to place an order, or to get away from the heat?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Isuzu, who told you that...? There aren't any ghosts here, don't worry. Go out and play.|Chiyoda's quite the sore loser... She's like that even when it comes to building sand castles, so I can't even imagine how worked up she'd get over beach volleyball... If that pink-haired union girl is our opponent, I think I'll just sit out...|The weather forecast says... it'll be clear until the evening... Mmn...",
	touch = "That shaved ice looks really good... I guess there's a good reason cold treats are popular in the summer.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 306081,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "The sun's rays are so harsh... I should go look for some awning to hide under...",
	detail = "Everyone becomes so rowdy when they get to the beach... I hope nothing bad happens today. Please, may enemy aircraft and volleyballs not come flying our way...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[306082] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Even if I'm alone... No, Chiyoda and the Commander are waiting for me...!",
	home = "Are you tired? We still have a banquet to go to tonight, so you should rest while you still can... Oh, don't worry about me, I can get some rest right here... (*blushes*)",
	unlock = "I had this outfit custom-made just for today... Do you like it, Commander? Um, that's good then... (*whispers*) Booyah.",
	touch2 = "D-did you want to take a photo...?",
	mission = "",
	vote = "",
