_G.pg.base.ship_skin_words[307013] = {
	hp_warning = "",
	feeling3 = "",
	mail = "A letter, huh? ...Hey, Commander? Just what kind of uncouth person would go out of their way to get between us at a time like this...?",
	expedition = "Who will you send to greet the commission fleet?",
	win_mvp = "My love shall burn everything away~ Ahahahaha!!",
	home = "A toast to your victorious return, Commander... Hehehe~",
	unlock = "Commander, I've been waiting for you~ What a sinful one you are, to tempt Akagi like this for so long... But at long last, nobody will ever get between us again...♡",
	touch2 = "It's just the two of us here... Yes, Commander, feel free to do whatever your heart so desires~",
	mission = "",
	vote = "",
	drop_descrip = "Commander, I've been waiting for you~ What a sinful one you are, to tempt Akagi like this for so long... But at long last, nobody will ever get between us again...♡",
	feeling4 = "",
	lose = "At least... protect my friends and compatriots...!",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "I will not do anything that would tarnish your reputation, but... if any meddlesome pests insisted on getting in your way... Ehehe...|Indeed. While you were socializing, I made sure to strengthen our bonds with the other factions. At events like these, Shinano is horribly out of place, and if I may say so, the burden may be a bit too great for Nagato.|Commander, why won't you get drunk with me already... Haah, even though Akagi has been so lonely for so long...",
	touch = "Commander, there's a vacant seat right next to me~ Wouldn't you like to come a bit closer~?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "1st CarDiv, Akagi, sallying forth~",
	id = 307013,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Ah?! Commander...?!",
	feeling2 = "",
	login = "Have you awoken, Commander? Akagi will always be at your side~",
	detail = "Commander, I knew you'd be busy at the party, so I waited until the very end for you. Now, your full and undivided attention shall belong to Akagi alone~ Hehe~♡",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[307014] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission team has returned...? Excellent. You may go now.",
	win_mvp = "Nothing brings me more joy than being a cornerstone of the Commander's glory! Ahahahaha!",
	home = "A toast to your splendid victory, Commander... Hehe~",
	unlock = "This banquet is my present to you... and your attendance is the greatest reward I could hope for~ Indeed, I shall not grant you leave tonight until you pass out. Ehehe... Ahahaha~♡",
	touch2 = "Ah, Commander... Ahahaha~♡",
	mission = "",
	vote = "",
	drop_descrip = "This banquet is my present to you... and your attendance is the greatest reward I could hope for~ Indeed, I shall not grant you leave tonight until you pass out. Ehehe... Ahahaha~♡",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "What's the matter, Commander? Hehe, worry not. Kaga will eliminate any pests that seek to squirm into our banquet tonight~|Oh, would you look who showed up... Do remember to be on your best behavior tonight, 5th~ Car~ Div~♪|Hiryuu, you're going to get tired from sitting in a kneeling position all night... As the Commander is perfectly relaxed here, you should also do likewise and enjoy yourself~",
	touch = "Let us partake of each other's drink, Commander~",
	voice_key_2 = -1,
	mission_complete = "This reward... shall serve as an exquisite dessert to the banquet~",
	battle = "I shall burn everything away!",
	id = 307014,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, are you enjoying Akagi's banquet? If it is entertainment you desire... Ehehe. You can ask me for anything, you know?",
	detail = "Tonight, you are not allowed to meet with anyone other than me. Exchanging pleasantries...? Oh, are you not satisfied with \"exchanging pleasantries\" with Akagi alone? Hehehe~",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[307015] = {
	hp_warning = "",
	feeling3 = "",
	mail = "A letter... Heehee, perhaps it's from a girl who's jealous of our relationship?",
	expedition = "I've gotten word that the commission team is back. Yes, I'll arrange for someone to meet them. We wouldn't want to busy you over that, now, would we?",
	win_mvp = "",
	home = "Would you like a cup of tea, Commander? Heehee, of course, I've already brought it—Yes, please. Drink it while it's still warm♡",
	unlock = "Commander, open up. Say ahh... Heehee, heheheheh... You're like a little baby♪ Receiving a lovely new outfit and seeing a different side of you... How blessed am I?",
	touch2 = "Just be patient until we can get a room together, Commander...",
	mission = "",
	vote = "",
	drop_descrip = "Commander, open up. Say ahh... Heehee, heheheheh... You're like a little baby♪ Receiving a lovely new outfit and seeing a different side of you... How blessed am I?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Commander, I made a hotel reservation for us tonight! A town abundant with history, delicious foods, and a hidden hot spring to soothe your fatigue... Heehee, and we'll be sleeping in the same bed, of course!♡",
	main = "Commander, where are we going next? I'd love to go somewhere far away so that we can spend looots of time together~|I'll treasure these clothes you gave me for a lifetime. Thanks again, Commander~|Traveling through cities and nature, enjoying beautiful scenery... Heehee, what an elegant trip. Commander, are you having fun, too?",
	touch = "Oh, you'd like to feed me? Okay! Aah♪",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "I won't allow you to enter the Commander's sight...",
	id = 307015,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Heehee. What's the matter, Commander?",
	feeling2 = "",
	login = "Commander, would you like another? Okay, open up! Say ahh♪",
	detail = "Shall we take a break? There's no rush; your journey is far from over. Of course, I couldn't be happier about that...♡",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[307018] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Oh my, mail has arrived. Mm... it would seem that our superiors don’t suspect a thing.",
	expedition = "Looks like those troublesome nymphs have returned. Commander, Akagi will be right back~",
	win_mvp = "",
	home = "Commander, won’t you try some of Akagi’s hand-crafted tea? I added a little ingredient to make our love even sweeter~!",
	unlock = "We should send out even more invites... This is the best way to rid ourselves of those pesky vixens all at once!",
	touch2 = "Commander, you can’t resist any longer, right? Akagi feels the same way~",
	mission = "As long as we can be together, those commissions and tasks don’t really matter, right? You agree with me, don’t you?",
	vote = "",
	drop_descrip = "We should send out even more invites... This is the best way to rid ourselves of those pesky vixens all at once!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Ahh, Commander, you’re finally awake? Hm? Akagi didn’t do anything~ except lock you in so that we can stay together forever.",
	main = "It would be great if Commander and Akagi were the only people left in the world~|Commander, stop struggling. Akagi made this special chain, just for you~|It’s human nature to want to possess something so special to you, Commander~ Ahaha~",
	touch = "Are you hungry, Commander? Akagi is going to cook now. Don’t even try to run away~!",
