_G.pg.base.ship_skin_words[307023] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Here. I've brought your mail.",
	expedition = "The girls of the commission fleet have returned. Shall I bring some refreshments out to them?",
	win_mvp = "This is the judgment exacted upon the weak by the strong. Live on so that you may forever choke on the bitterness of defeat!",
	home = "A victory, huh? As Akagi's... as my sister's partner, anything less would render you unfit for that honor.",
	unlock = "This statue seems to have been inspired by the teachings of the Iris Orthodoxy. Though I am unfamiliar with this kind of art, gazing upon such majesty... fills one with a sense of piety. Commander, can you feel it as well?",
	touch2 = "It's... just a little hot...",
	mission = "",
	vote = "",
	drop_descrip = "This statue seems to have been inspired by the teachings of the Iris Orthodoxy. Though I am unfamiliar with this kind of art, gazing upon such majesty... fills one with a sense of piety. Commander, can you feel it as well?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Zuikaku, find some way to keep Taihou busy. Can't do much about her clinging to the commander, but there's going to be trouble if Akagi sees her.|The weak shouldn't push past their limits. You certainly don't want to end up like Yorktown over there.|It's not that I don't want to attend the party. If I'm to keep tabs on everything going on, this is the best place to do that from.",
	touch = "You wanna kill some time? Hmph. Very well, how about a round of chess then? I've been wanting to see how your powers have developed... Hehehe...",
	voice_key_2 = 0,
	mission_complete = "",
	battle = "1st CarDiv, Kaga, weighing anchor!",
	id = 307023,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Hm...?",
	feeling2 = "",
	login = "It's time for the star of tonight's show, huh? ...Don't worry, I'll cover for you even if you mess up.",
	detail = "Have you finished making your rounds? As I said, we can always catch up later. There are many others who are still waiting for your words... But since you're already here, might as well take a break if you want a change of pace.",
	couple_encourage = {}
}


