_G.pg.base.ship_skin_words[307030] = {
	hp_warning = "Commander, please calm down.",
	feeling3 = "My past? There isn't much worth mentioning, but if you're interested, I can tell you while we play...",
	mail = "Commander, new mail is here.",
	expedition = "The commission team has returned to port on time. Inspecting results.",
	win_mvp = "Do not make light of an elite aircraft carrier.",
	home = "You have a mountain of paperwork to sort through, but you should get some rest first...",
	unlock = "My name is {namecode:93}. Commander, from now on, please request my permission in writing before doing anything weird.",
	touch2 = "You...! Do you want me to cut off your hands?",
	mission = "Please complete the missions as soon as possible.",
	vote = "",
	drop_descrip = "Aircraft carrier, {namecode:93}.",
	feeling4 = "I’ve lost track of time playing Hanafuda with Commander... Now that I think about it, weren’t you just using it as an excuse to approach me back then?",
	lose = "Impatience is unbecoming. We must reflect on our mistakes upon returning.",
	feeling1 = "Please do your work.",
	skill = "Pig! Deer! Butterfly!",
	upgrade = "I shall repay you with my actions.",
	propose = "Commander, where did you sneak off to with the base’s funds this time? ... A gift for me? Don’t think you can - Eh? A-ahem... just this time, I will let you off the hook.",
	feeling5 = "We started with Hanafuda, and shall continue with Hanafuda. If you win the next round, I shall do anything you ask.",
	main = "Commander, why are you daydreaming? Please, get to work!|Take your missions seriously! Don't get distracted so easily.|All air units, lock onto the Commander and get ready to unleash your bombs!",
	touch = "Commander... please refrain from disturbing people who are working.",
	voice_key_2 = -1,
	mission_complete = "Here is the mission reward list. Please double-check that you have received everything.",
	battle = "I had hoped to avoid meaningless battles...",
	id = 307030,
	gift_dislike = "",
	gift_prefer = "This is exactly the thing I wanted!",
	profile = "I am the first regular aircraft carrier of the Sakura Empire. As such, I served as the prototype for later carrier designs. Please... just don’t mention Midway.",
	voice_key = 30703,
	headtouch = "",
	feeling2 = "What is it, Commander? You want to learn how to play Hanafuda? I don't mind teaching you if you're actually interested... This is Matsu, which means pine... This is Ume, which means plum...",
	login = "Commander, your documents are ready. Please take a look when you have a moment.",
	detail = "If this data can be of some use to you...",
	couple_encourage = {
		{
			{
				30704
			},
			1,
			"{namecode:94}, are you done warming up yet?",
			0
		},
		{
			{
				10705
			},
			1,
			"I can’t stay mad at you.",
			0
		}
	}
}


