_G.pg.base.ship_skin_words[307032] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "She welcomed back the commission team, just like always... She is at the point of her life where she wants to spread her wings and be free...",
	win_mvp = "",
	home = "",
	unlock = "I am Souryuu of the Morals Committee. Our goal is to maintain public decency, increase student motivation, and... *Ahem*! Anyway, please allow me to oversee the school's moral codes!",
	touch2 = "All planes, prepare for takeoff! No, wait, prepare to strike!",
	mission = "",
	vote = "",
	drop_descrip = "I am Souryuu of the Morals Committee. Our goal is to maintain public decency, increase student motivation, and... *Ahem*! Anyway, please allow me to oversee the school's moral codes!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Please don't joke like that. My disciplined, respectful, dependable, good-mannered, and very well-raised little sister would never end up as a dirty delinquent!|Hiryuu's in her rebellious age... *Sigh*... Perhaps it's best to leave her alone for a while...|I have my planes monitoring every nook and cranny of the school. I recommend you don't do anything that would oppose school conduct.",
	touch = "I've been talking to Hiryuu less, yet her mood hasn't improved at all... S-she's not going to run away from home, is she?!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 307032,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I think Hiryuu is in her rebellious age... She won't wear the clothes I picked out for her, and she won't walk to school with me... As her sister, it's making me feel a little bummed out.",
	detail = "I may be in the Morals Committee, but that doesn't mean I want to become a fusspot.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[307039] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "It seems like you no longer require around-the-clock supervision, Commander... However! Do not assume this is a free pass to slack off!",
	unlock = "If I can become stronger through this... Commander, what are you staring at? Don't you still have work to do?",
	touch2 = "... Judgment shall be exacted upon you when work is over. Prepare yourself.",
	mission = "",
	vote = "",
	drop_descrip = "If I can become stronger through this... Commander, what are you staring at? Don't you still have work to do?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Have you finished your work? If not, please redouble your efforts. |You were spacing out again, weren't you? Heh, you can't hide anything from me. |Hiryuu hasn't been her usual self recently. I wonder what's amiss? It's making me worried...",
	touch = "Are you tired? In that case, please take a break. I shall handle the remaining work.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 307039,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Welcome back, Commander. Here are the documents that I have prepared for you. Please make sure to finish them.",
	detail = "No matter what situations may arise, you must always trust your judgment, Commander.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[307040] = {
	hp_warning = "Don't be afraid of gunfire!",
	feeling3 = "About acting more feminine... do you think Souryuu is more attractive because of her cold demeanor? Oh, and her ankles are amazing. It would be great if I could become like her.",
	mail = "Mail! Eh, it’s dangerous to throw them around like airplanes? Fine...",
	expedition = "Commander, your commission fleet should be back.",
	win_mvp = "An expected victory. It’s not even worth mentioning.",
	home = "Here are the combat logs. Let's start reviewing the battle..",
	unlock = "Aircraft carrier, {namecode:94}, awaiting orders! Leave the missions to me. I’ll fight until my dying breath.",
	touch2 = "Commander, before I smack you, I’d like to ask: Do you not see me as a woman?",
	mission = "A mission, huh? I’m looking forward to any kind of challenge.",
	vote = "",
	drop_descrip = "Aircraft carrier, {namecode:94}.",
	feeling4 = "Hmm, feels like nothing has changed. But at least Commander sees me as a woman now. Whenever I’m around you, my heart skips a beat, just like Souryuu described. Is this... girly enough?",
	lose = "Win some, lose some. It's only normal.",
	feeling1 = "Haa! (Her fist stops next to your face) Stay away from me.",
	skill = "Cherry! Blossom... Umm... whatever, Hiyah!",
	upgrade = "Hey! I’m in pretty great shape!",
	propose = "I’m neither gentle like the other girls nor attractive like my sister. The only thing I’m confident about is my combat prowess. Would you still be willing... to accept a girl like me?",
	feeling5 = "Umm, Even though I didn't feel like anything changed.... At least the Commander has accepted to look me as a woman, When I'm by the Commander's side, I also have those girly feelings that my sis mentioned before, is that.... enough?",
	main = "All systems go! Ready to sortie at any time.|Is it strange... that I find Souryuu’s ankle to be elegant?|Commander, if you’re bored, how about we spar?",
	touch = "Be careful. You might get hurt if you get too close!",
	voice_key_2 = -1,
	mission_complete = "Your rewards, Commander. Please take a look.",
	battle = "Victory goes the one who strikes first! Planes, take off!",
	id = 307040,
	gift_dislike = "",
	gift_prefer = "Isn't this the thing I've always wanted? Thanks a lot!",
	profile = "I'm {namecode:94}, a {namecode:93}-class aircraft carrier. Although I'm {namecode:93}\"s sister, we're not actually the same type.\nAs an aircraft carrier, I simply can't afford to let my guard down during battles. Let's advance carefully, and aim for the best possible results in combat!",
	voice_key = 30704,
	headtouch = "",
	feeling2 = "Since I am always thinking about combat, the other girls keep saying that I’m not feminine at all. So, um... that’s what I’m trying to improve here.",
	login = "Eh? Ah! Commander! Watch out!!",
	detail = "Isn’t this pose... super cool?",
	couple_encourage = {
		{
			{
				30703
			},
			1,
			"Big sister's feet are the best in the world~!",
			0
		},
		{
			{
				10706
			},
			1,
			"Simply unparallaled! What an aura!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[307041] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "I won't be able to face all the girls who look up to me if we don't go greet the commission fleet... This school bully will make an exception and welcome the girls back!",
	win_mvp = "",
	home = "",
