	vote = "",
	drop_descrip = "The disciplinary committee wouldn't exist if there weren't bad chicks like me! C'mon, let's totally own this school before my sister catches us!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Playing hooky? I don't think it's right to abandon your duties as a student. F-fighting? Picking on others is even worse!|nil|How am I supposed to become the bad girl counterpart to rival my sister...? I just don't get it...",
	touch = "This... chained club looks pretty scary, right? But it's actually hollow inside so it won't hurt much.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 307041,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "There's a fairy hiding in the library, you say? If she's confined to the library all the time, do you think she's being bullied...?!",
	detail = "I'm supposed to be a bully, but how exactly do you do that...?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[307049] = {
	hp_warning = "",
	feeling3 = "",
	mail = "The mail's here! Not being able to fly feels a bit unsatisfying though...",
	expedition = "",
