_G.pg.base.ship_skin_words[307058] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Another great victory for you... And I was proud of my performance, too♪",
	home = "Welcome baaack♪ How are you feeling? Should I give you a massage? ...Oh? I just wanted to be a little assertive, but I guess that's still too jarring?",
	unlock = "Through building this relationship with you, I've made so many happy memories. Now I think it's time to work toward a new goal! Heehee, I was serious about that, you know. Commander, I look forward to many long years together with you♡",
	touch2 = "I'm happy to do everything you've been waiting for, Commander...♡",
	mission = "I would love to enjoy more peace and tranquility with you, Commander, but please don't forget your missions.",
	vote = "",
	drop_descrip = "Through building this relationship with you, I've made so many happy memories. Now I think it's time to work toward a new goal! Heehee, I was serious about that, you know. Commander, I look forward to many long years together with you♡",
	feeling4 = "",
	lose = "My seniors are going to laugh at me now... I'm sorry, Commander. Can you put in a good word or two for me?",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "At first, I just wanted a shoulder to lean on, but I just can't tear myself away from you anymore. The thought that we'll get to be together forever makes it all worth it, though~",
	main = "I tried making new pastries today. Want to try them out soon? I'm rather confident in them! After all, I've been training hard♪|When you look at me, I feel real joy. Heehee...|Commander, let me play you a song. After our recent union, maybe a love song would be fitting?|Once we're finished here, how about we go see how Akagi is doing? I heard she likes dango, so I'll bring her some!",
	touch = "Do you want to be the one massaging today? How sweet.",
	voice_key_2 = -1,
	mission_complete = "Mission complete. You're as reliable as ever, Commander.",
	battle = "",
	id = 307058,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Hehe♪ Come on, now...",
	feeling2 = "",
	login = "Welcome home, Commander. Heehee... We were only apart for a while, but you missed me so badly, didn't you? I missed you too, of course.",
	detail = "Commander? Commandeeer? Geez, I was trying to tell you about our schedule for today. Were you too focused on staring at me? Hehe, if you want, you can come in for a closer look.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[307060] = {
	hp_warning = "Shoukaku... Is Shoukaku all right?",
	feeling3 = "My fate always seems to be entertwined with Lexington’s... Ah~ Commander, please don’t tell Sara I said that. I can’t handle that girl.",
	mail = "So? Is it good news or bad news?",
	expedition = "If only I had more planes...!",
	win_mvp = "I am the auspicious crane, after all!",
	home = "I’ll need you to perform some maintenance on me. Ah, don’t forget about the planes either!",
	unlock = "I am {namecode:96}, the last elite of the Sakura Empire’s Carrier Divisions. I can only be at my best when I am with my sister {namecode:95}.",
	touch2 = "Commander, {namecode:95}’s are larger and softer...",
	mission = "Is it time for a break? Commander, you should come try some of {namecode:95}’s cooking!",
	vote = "",
	drop_descrip = "Second ship of the {namecode:95}-class aircraft carriers, {namecode:96}.",
	feeling4 = "Whenever I feel irritated or lost, training always makes me feel at ease. Yes, I’ll definitely get stronger and catch up to that Grey Ghost one day.",
	lose = "Am I going to be sunk... again...?",
	feeling1 = "Commander, would you like a taste of the anguish I experienced during the Battle of the Marianas?",
	skill = "As long as Shoukaku is with me~!",
	upgrade = "As a perfected aircraft carrier, I shall not lose to anyone, not even to my seniors or to the Grey Ghost herself.",
	propose = "E-eh?! Th-this is... I’m not misunderstanding you, right? Then... um, from now on, I’ll be in your care, dar... darling? Waaah! Shoukaku is calling me!",
	feeling5 = "Commander, you make me feel just as if I am with Shoukaku. H-huh? That’s not it! I’m not treating you as my sister!",
	main = "{namecode:95} is so cute when she’s embarrassed!|Keep fighting until the last arrow is broken! That is what it means to be an elite!|Wait, Grey Ghost, don’t run away just because you won! Let’s have a rematch!",
	touch = "My least favorite food? Turkey, of course.",
	voice_key_2 = -1,
	mission_complete = "Hmm... Seems like the situation has taken a turn for the better!",
	battle = "A never-ending swarm of enemies? I’m already used to it.",
	id = 307060,
	gift_dislike = "",
	gift_prefer = "Appreciate it~",
	profile = "I’m {namecode:96} from the Fifth Carrier Divison, though I was assigned to the First Carrier Division at one point. Together with my sister Shoukaku, we became the last two elite carriers of the Sakura Empire. We triumphed in bitter battles against Lexington, Hornet, and even Enterprise. That’s right, I was even able to severely damage the Grey Ghost herself, although she proved to be luckier than me. My service came to an end when Lexington, risen from the dead, sunk me. In the end, I still completed my final mission and sank with no regrets.",
	voice_key = 30706,
	headtouch = "",
	feeling2 = "Seniors and juniors... they’re all such a pain.",
	login = "Where are we going today? Pearl Harbor? Or perhaps the Coral Sea?",
	detail = "That Grey Ghost... I’d like to duel her just once.",
	couple_encourage = {
		{
			{
				30705
			},
			1,
			"I'm fearless, as long as my sister is with me!",
			0
		},
		{
			{
				10204
			},
			1,
			"I don't know why, but I just find you terribly annoying...",
			0
		},
		{
			{
				10702
			},
			1,
			"That ties up the score. Next round decides the winner!",
			0
		},
		{
			{
				10703
			},
			1,
			"Uwah! When did you get here?!",
			0
		},
		{
			{
				10706
			},
			1,
			"I never thought I'd fight alongside the Grey Ghost herself!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[307061] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Victory is assured as long as I'm here!",
	home = "Phew... I'm in a pretty good mood, but that was still pretty tiring... Commander, can you bring me something to eat?",
	unlock = "New Elite 1st CarDiv, Zuikaku, reporting for duty! Ahh, I've always wanted to give such a cool introduction! Shoukaku would definitely make fun of me if she heard it, but I wanted to try it while everyone is in a festive mood... Commander, what'd you think? ",
	touch2 = "Uhh... So you wanted to compare mine to Shoukaku's after all?",
	mission = "This is nothing compared to Mikasa's hellish training! I'll be done in no time!",
	vote = "",
	drop_descrip = "New Elite 1st CarDiv, Zuikaku, reporting for duty! Ahh, I've always wanted to give such a cool introduction! Shoukaku would definitely make fun of me if she heard it, but I wanted to try it while everyone is in a festive mood... Commander, what'd you think? ",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "As long as there is someone I want to protect, I won't fear the strongest of enemies or the the sting of defeat. No matter how many times I am knocked down, I will always persevere and claw my way back up. No matter what happens, Commander, I will always protect you and Shoukaku.",
	main = "Akagi isn't exactly a fan of these large gatherings... Wait, could she be antisocial?! Err, that doesn't seem right... |T-Taihou?! You can't do that kind of stuff in public! Commander too, you should keep your distance! Stay hidden until I say otherwise! |Commander, would you like something to eat? Can't grow big and strong without good food, you know~ Hahaha, just kidding!",
	touch = "Huh? What's the matter, Commander? Is there some place you'd like to check out?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Zuikaku, advancing!",
	id = 307061,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, how should we begin our work today? Allow me to aid you!",
	detail = "I'm giving off a different vibe from usual? Hehe, I'll take that as a compliment! As a matter of fact, I do like trying on different outfits from time to time for a change of pace.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[307062] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Ugh... Having to hold this pose for so long is making my shoulders stiff...",
	unlock = "Commander, I volunteered to take this job in order to help you out, but this outfit... did it always require such a high degree of exposure...?",
	touch2 = "Commander, you're not doing this kind of stuff to the other girls, are you...?",
	mission = "",
	vote = "",
	drop_descrip = "Commander, I volunteered to take this job in order to help you out, but this outfit... did it always require such a high degree of exposure...?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Hmm... I just can't pull the look off as well as Shoukaku... Is this the difference in our \"girlish appeal?\" |Is this job just to sit here for the photo ops...? I thought I'd get to drive...|Phew...! Keep it together, Zuikaku... You've gotta look your best in front of the camera!",
	touch = "Hold this position a bit longer...? Mm, can't I ask for a slightly cooler pose...?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 307062,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, it's fine! You don't need to worry about me! I can totally handle something like this!",
	detail = "Oh, Shoukaku was also doing this job, right? Even though she's also wearing the same outfit, she gives off completely different vibes than me... ",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[307063] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Oh, the commission team is back! THAT was pretty darn fast.",
	win_mvp = "Go for the checkered flags and let the engines roar!",
	home = "Welcome back, Commander! Come join me for a break. Ahahah, you might think you don't need one, but people need maintenance, too!",
	unlock = "Sis, how's my car lookin'? \"All clear, ready to go at any time.\" Alrighty, just leave the rest to me! Commander, you're about to witness what I can accomplish from the cockpit!",
	touch2 = "Hey, uh... I want to conserve stamina, so let's save this for later...",
	mission = "Better get those unfinished missions done while you have the chance. You need all the time you can get on the race track!",
	vote = "",
	drop_descrip = "Sis, how's my car lookin'? \"All clear, ready to go at any time.\" Alrighty, just leave the rest to me! Commander, you're about to witness what I can accomplish from the cockpit!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Hey. This is a secret between you and me – I actually care less about my track time and more about seeing you rooting for me... Oh, and don't tell that to Shoukaku!",
	main = "Count down to engine ignition... You're never catching up with me! Oh, Commander, uh, I'm not talking to myself, just... uh, rehearsing some cool-sounding lines... yeah, that's it!|Can I count on you to cheer me on before the start? Heehee. With you rooting for me, I just know I'll win!|You wanna take me out for a ride in your own car later? Sure! You don't mind taking the shotgun seat, do you? 'Cause I'm gonna be the driver! Heheh!",
	touch = "Yeah? Are you thirsty? I've got a drink if you need a sip.",
	voice_key_2 = -1,
	mission_complete = "You finish missions as fast as I drive my car! Hahaha! Now let's get a look at those rewards while we can!",
	battle = "",
	id = 307063,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "There you are! Me and my sis were just having a break and preparing for the next race. \"Heehee. Actually, I'm still running a check on your car.\"",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[307070] = {
	hp_warning = "For my Commander, I have to win...!",
	feeling3 = "... That gift she gave you? Oh, I threw that out. Why wouldn't I? Only my things belong on your desk~",
	mail = "My Commander, you've got mail~ I licked it very tho-rough-ly. It's safe.",
	expedition = "Commission complete... But if you ordered it, my Commander, I would clear all of them for you... I must mean so much to my Commander.",
	win_mvp = "I dedicate this victory to my Commander!",
	home = "Mission accomplished! And let me say how fantastic you looked on the battlefield.",
	unlock = "This heat, and this throbbing... We meet at last, my dear Commander! I am Taihou, unworthy as I am, at your service♡",
	touch2 = "If you touch any other girls like this, I might have to punish you, my Commander.",
	mission = "There's a new mission. Can we go?",
	vote = "",
	drop_descrip = "Taihou-class aircraft carrier – Taihou.",
	feeling4 = "You forgot your coat? Well isn't my Commander forgetful... Don't worry about it, I'll go get your coat for you. Huh? The key to your quarters? Hehehe, you can keep it. Taihou has her ways.",
	lose = "Why aren't you dead... why won't you all just DIE?!",
	feeling1 = "Those insects... Just a second, my Commander, I need to do something about these impudent little insects...",
	skill = "Now you can die happy, ahaha...",
	upgrade = "Ahaha, now I can serve my Commander even better...",
	propose = "It's finally on my finger! You know, I would have thrown this ring out long ago if it didn't have my name on it. Hehehe. Oh? How did I know about it? I tollld you, I know EVERYTHING about my Commander. And from now on I'm going to love EVERYTHING about you too~",
	feeling5 = "The bed and toiletries in your quarters? Of course they're mine. I should have thought of this before~ If you don't want me going in and out of your room all the time, we should just be sleeping together. Hehehe... please be gentle with me.",
	main = "Hehehe, I would pull the moon from the sky for you, if you wanted it, my Commander.|You like small ones, my Commander? Then I'm off to cull the big ones, hehehe...|My Commander, you know you can never EVER lie to me. Or else...",
	touch = "Touch me more!",
	voice_key_2 = -1,
	mission_complete = "Mission complete~ Want to go get the rewards?",
