	propose = "",
	feeling5 = "Even the most glorious magic must fade, in one last spectacular moment... However, if this one weaves this magic into dream, its wonder will be eternal... If you desire, come into my grotto... and we may be together forever...",
	main = "There wasn't much time to prepare, so this one's tail is unbrushed and messy... Please forgive me.|This glass box is rather cramped... Fortunately, it did not affect the performance...|Phantasmal, dancing lights and your passionate gaze... They make this one's self-control futile...|Supposedly, this hand gesture conveys joy... Do you see the joy this one feels in your presence?",
	touch = "Do you... wish to open this box?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 307084,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Hmm...? In this dream realm, this one will not fall asleep...",
	feeling2 = "",
	login = "This one welcomes your arrival... If you wish, you may stay in my grotto. This one will accompany you, of course...",
	detail = "You wish to know why this one has woven such a dream? This one only wishes to indulge in sweet dreams with you, to seek surprise and succor together...",
	couple_encourage = {}
}


