_G.pg.base.ship_skin_words[307090] = {
	hp_warning = "Heheheh... how stimulating....!",
	feeling3 = "You're rather popular for a mere slave, aren't you? Hrrmm... what's this anxious feeling I have...?",
	mail = "New mail... what's this? It's not for me!?",
	expedition = "Slave, the commission's complete... You want to go with me? Oh all right. I can't say no to that face.",
	win_mvp = "Hmph. You insects have no right to bully my slave!",
	home = "Ah what a fantastic job you've done today, slave. Bravo! Bravo!",
	unlock = "So you're the best this fleet has to offer? Well then, to please Amagi I'm going to have to start by dominating you. Hehehe.... How blessed you are. From this day forward, you're Akagi's number one slave.",
	touch2 = "*giggle* Seems I'll have to shackle you...",
	mission = "In the name of the eight million gods, hurry up and polish off a few more missions!",
	vote = "",
	drop_descrip = "Aircraft carrier Akagi.",
	feeling4 = "Hrmmm... he's my slave, but those women won't stop throwing themselves at him... even though he's my slave... and clearly mine alone.....",
	lose = "Hmph... You better not misunderstand, slave! I let them win!",
	feeling1 = "It seems I've been too lenient with you...",
	skill = "How dare you harm my slave!",
	upgrade = "What a well-behaved slave you are~",
	propose = "This means you totally belong to me, and I shall give everything to you, right? Aha... hahahahaha! ...Slave.... I never would have imagined that owning you would make me so happy... Ahahahahahaaaa!",
	feeling5 = "Slave, you know you can always come to me if there's anything wrong. I'll gladly help you ....so don't go to anyone else. Don't talk to anyone else. Just be my slave, okay?",
	main = "With Amagi at my side, there is nothing we cannot do~ You are blessed indeed, my number one slave.|Your profile is quite striking when you're working so diligently. Truly worthy of being my slave!|Slave, while I don't mind you playing with your underlings, you must never forget to whom you answer.",
	touch = "Aren't you a clingy slave. Very well, I'll play with you~",
	voice_key_2 = -1,
	mission_complete = "Mmmhmm, so many rewards, just as I would expect from my slave~",
	battle = "I'm the only one allowed to bully this slave!",
	id = 307090,
	gift_dislike = "",
	gift_prefer = "Good, you should know exactly what your master wants~",
	profile = "I'm a battlecruiser... eh? Now that I mention it, am I no longer a warship? Hm, never mind. I am Akagi, and that's all that matters. Hehe. You must feel so honored to be my slave, hmm?",
	voice_key = 30709,
	headtouch = "",
	feeling2 = "Haha, aren't we proud! From the moment I saw you, I knew you would be my slave!",
	login = "If you sneak off without telling me one more time, I might just have to turn this place into a sea of fire.",
	detail = "It's truly marvelous to be so loved and treasured by this slave. *giggle*",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[307100] = {
	hp_warning = "My love is far stronger than this!",
	feeling3 = "Commander, if you wish it, I would perform forever for your eyes alone~ Indeed, this stage would belong only to my Commander for the rest of time♡",
	mail = "A letter... Oh, Commander? It couldn't possibly be that you sent a fan letter to another girl...?",
	expedition = "The meddlesome pests are back... Commander, please excuse me for a moment?",
	win_mvp = "Oh my, did I incinerate all those fans clamoring for an encore?",
	home = "Commander, what would you say to a performance in your honor? Naturally, only Akagi would participate...",
	unlock = "With the magicks of the Sakura Empire, changing my form like this is a trifle... Hehehe, Commander? Does this Akagi please you?",
	touch2 = "Don't mind the stares of the spectators in the stands. Take me however you please, my Commander... Hehehe♡",
	mission = "Commander, is there a mission I might help you with?",
	vote = "",
	drop_descrip = "With the magicks of the Sakura Empire, changing my form like this is a trifle... Hehehe, Commander? Does this Akagi please you?",
	feeling4 = "We're at the point now that this group doesn't need any other girls... And I think I need to do a bit of \"cleaning\" for my Commander... Hehehehe...",
	lose = "Gah... that was close. I can't let the Commander see me like this...",
	feeling1 = "My Commander's apologetic screams are truly music to my ears... hehehe.",
	skill = "Ahaha, like dust in the wind.",
	upgrade = "Why, this is the strength of my love. Hehehe...",
	propose = "Ahahahaha... all that I am now belongs to my Commander, and everything of my Commander now belongs to me... It will be just like my concerts: your eyes, your ears, even your heart is bound to me... Commander, I will never let you go...",
	feeling5 = "You want to get to know the other members? Hmm, if that is what my Commander wishes, I suppose I could accept it... But in return, Commander, you are only allowed to look at me♡",
	main = "I would like to know~ which girl you cheer for, Commander... I would really, REALLY like to know...|This \"idol\" business is a little different, but it's no matter. Whatever my Commander wishes of me, I can do...|Kaga, please cancel all of our lessons for the rest of the day. My time with my Commander is so precious, I refuse to waste a single second.",
	touch = "Commander, what are you waiting for? I'm ready for you, anytime, anyplace.",
	voice_key_2 = -1,
	mission_complete = "Mission complete. But I do hope that doesn't mean you will leave my side...?",
	battle = "Give my concert your full attention~ Ahahaha!",
	id = 307100,
	gift_dislike = "",
	gift_prefer = "A gift, just for me? That makes me very happy.",
	profile = "Sakura Empire Aircraft Carrier, Akagi, reporting in with a special equipment refit! Commander, things are a little different this time. I'm trying a little \"idol\" style for you. Won't you please be gentle with me? Hehehehe...",
	voice_key = 30710,
	headtouch = "",
	feeling2 = "Commander, did I hear you want to come see my show? I'm delighted~ Kaga, can you prepare a front row seat?",
	login = "Commander, I wonder what's on the schedule for today? Hehehe.",
	detail = "I would do anything for you, my Commander. Yes, including this \"idol\" business... Hehehe.",
	couple_encourage = {
		{
			{
				90503,
				10224,
				40307,
				20225
			},
			2,
			"I work with you out of respect for my Commander.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[307110] = {
	hp_warning = "My Commander is watching...!",
	feeling3 = "Commander♡ My shoulders are sore from all my training~ Could you take me back to my room...? Actually, I think I'd rather rest in your room for a while, my Commander.",
	mail = "A fan letter...? Who else should I talk to but my Commander?",
	expedition = "Commander, won't you go pick up the commission team...? I have a feeling that little Union girl is going to jump out and scare me if I go...",
	win_mvp = "Ahahahaha! Bow down before the power of my love!",
	home = "My Commander♡ Are you here to watch me practice?",
	unlock = "With these clothes, and upon this stage... Ahaha... Ahahaha... Fate has ordained that my Commander shall fall for me here... Commander, please listen to the song of my love until the very end~♡",
	touch2 = "Hehehe, it may be a scandal, but I don't care♡",
	mission = "For the sake of my Commander, I can endure... no, I will gladly take any offer!",
	vote = "",
	drop_descrip = "With these clothes, and upon this stage... Ahaha... Ahahaha... Fate has ordained that my Commander shall fall for me here... Commander, please listen to the song of my love until the very end~♡",
	feeling4 = "Commander♡ I brought you my official idol merch. Of course, it's not something you could buy in a store, it's \"special,\" just for you... Are you wondering what's \"special\" about it? Hehehe♪",
	lose = "Grrgh, miserable insects...!",
	feeling1 = "Are you telling me I can't be an idol...?!",
	skill = "We'll have to get rid of these pests♪",
	upgrade = "I can't wait to show my Commander the results of my special training~",
	propose = "Commander♡ What do you think of my new stage? And my outfit...? I will dazzle you over and over and over again with my beauty until you can't stand it anymore~ Ahahahahahaa!",
	feeling5 = "I have no interest in dazzling the people with my performance. But if my Commander wants to see me like that... Hehehehe♪ I'll do anything for you~",
	main = "Hmph! This dance has some very difficult moves... I'll have to practice a lot more to give my best performance to my Commander!|That Iron Blood girl's \"healing\" business that's all over her promotional materials... that's all fake, isn't it?|My Commander♡ suddenly came to watch me practice... I feel like I could take on the world~!",
	touch = "Hehehe♪ It seems this pose is powerful enough to draw my Commander's eye♡",
	voice_key_2 = -1,
	mission_complete = "Hehehe, I've grown even more powerful from this job...!",
	battle = "Surrender to my charms!",
	id = 307110,
	gift_dislike = "",
	gift_prefer = "Aahh... a present, from your heart to mine... Just as you have always cherished me, I shall keep your gift close to me at all times~",
	profile = "Sakura Empire armored carrier Taihou, reporting in to test the experimental \"Muse System...\" hehehe♡ My Commander need only ask and I will give anything, even my very life~",
	voice_key = 30711,
	headtouch = "C- Commander?! Ooh, you're treating me like a child now... hehehehe♡",
	feeling2 = "To sing and dance for someone other than my Commander is...No, I just need to think of it another way. The idols are all for my Commander, only for my Commander. It's perfect...!",
	login = "Commander~ What would you like me to do today?",
	detail = "I would rather have been a solo act, but I still need to learn more about idols, and my Commander asked me to join the group... So for now, I bide my time... Hehehe♡",
	couple_encourage = {
		{
			{
				40308
			},
			1,
			"Aren't you a little bit too close to my Commander...?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[307120] = {
	hp_warning = "Are you really going to let your all-important aircraft carrier get hit like this?!",
	feeling3 = "Oh, Commander, what are you trying to do? Checking on that packed warehouse? Or just heading out for a stroll? Ah! Don't tell me... you're going on date with someone?! ...Hey, are you listening to me?",
	mail = "New mail has arrived! Now then, is it something important? Perhaps, a mission notice? Or maybe...? Darn it, hurry up and open it up already~",
	expedition = "The commission rewards are in~ I'm only responsible for informing you though, you'll have to carry the goods yourself~♪",
	win_mvp = "Oh~hohoho~ How could you absolute nobodies hope to win against the might of a true aircraft carrier such as myself~",
	home = "Ohh, you're back! So like, something totally weird happened while you were gone. A little bird got lost inside the office and it was really hard for us to guide it back out~ Your place seems to be really popular with the birdies–– Hey, are you listening?",
	unlock = "Hello there, Commander! I'm the Unryuu-class aircraft carrier, Katsuragi. I'm not just a carrier, I'm a full-fledged aircraft carrier, meaning that I can do everything that an aircraft carrier is supposed to do! I'm not telling ya what I don't like, but as for hobbies, I've got a whole buncha those~ For example... (1 minute later) ...So yeah! Hey, Commander, are you still listening?",
	touch2 = "Heheh, I know you don't have the gumption to–– W-wait, stop that! Y-y-y-you're going to have to take responsibility at this rate, don't you know?!",
	mission = "Hrrrrmm... Don't tell me you still have unfinished missions lying around?",
	vote = "",
	drop_descrip = "Unryuu-class aircraft carrier – Katsuragi.",
	feeling4 = "Commander! I happened to discover something amazing! Tomorrow is a holiday, and there aren't many days like it, and by pure \"coincidence,\" neither you or I have anything to do! So basically, I was thinking, what could the two of us do on such a rare and special day when we have nothing else to do? Haah, there are too many possibilities~!",
	lose = "We lost?! Even though I did everything I could?! Ugh... How could things have gone so wrong??",
	feeling1 = "This simply won't do, Commander... I had no idea that the esteemed leader, the shining beacon of the fleet... would be such a decadent individual!",
	skill = "Pay close attention to this!",
	upgrade = "Mhm, that's more like it! I'll offer you some words of praise for recognizing my worth!",
	propose = "You keep squirming away from me but today I'll make sure you absolutely listen to every single word. Got it? Good! Ahem! I, Katsuragi, am bound by oath to you, and swear to always be at your side through joy or hardship! ...Mm, excellent. Now, it's your turn to repeat that back to me!",
	feeling5 = "You know how in those books, if there's someone on your mind, it normally goes something like \"your face gets all red and you can't find the words to say?\" But, like, in my case, I just can't stop talking at all... Ah! I get it now! I'm not the one who's nervous, you are! ...Hey, are you listening to me?",
	main = "Skip bombing? I must admit, it was quite an imaginative tactic. The Eagle Union was even able to give one as cute and strong as me a headache! Ahahaha!|If you're tired, just let me handle the paperwork. Nobody would notice the difference if I forged your signature... Ah, uh, that was obviously just a joke!|I left half a cake for you on your desk. Why only half, you ask? Well, that's because... I already ate the other half! Ahahaha!",
	touch = "What's the matter? Oh, you need me for something? Well, seeing how earnestly you're beseeching my aid, I have no choice but to at least consider it~",
	voice_key_2 = -1,
	mission_complete = "Quite satisfactory! With such abundant rewards, you'll be able to further expand your scope of work and have even more missions assigned to you! But... Hehe, are you able to shoulder that immense workload?",
	battle = "Harrumph! With me at helm, victory is already assured!",
	id = 307120,
	gift_dislike = "",
	gift_prefer = "What a flatterer you are... Hmph! But, I shall accept your gift anyway~♪",
	profile = "Let's give you some tips for how to get along with a cute and cheerful girl: First, you'd better not find any of her conversations boring! Second, don't make her do any lame chores like carrying stuff around! Finally, ask nicely, don't try to boss her around! All right, that's it for the first lesson, but there will be more in the future... Hey, are you listening?!",
	voice_key = 30712,
	headtouch = "You think you can mess with my heart just by patting my head? How naive! ...If you remember to keep it up 365 days of the year, maybe you'll have a shot.",
	feeling2 = "How many times have I had to explain this to you before? I can do everything that an aircraft carrier is supposed to do, but I can't do anything outside of that because that's just what I used to be!",
	login = "Hello there, Commander! Today's workload is looking a bit heavy and I wonder if we might have to do some overtime but I'm sure if we get right down to business we'll be able to finish– Commander??",
	detail = "If you want to keep me company so badly... Well, I just happened to not have anyone to talk to, so you'll have to make do! In any case, let me start by telling you about my favorite kind of azalea––",
	couple_encourage = {
		{
			{
				30602
			},
			1,
			"No, no... I wasn't trying to say that you're wrong, but...! ",
			0
		},
		{
			{
				30607
			},
			1,
			" There's no need to rush. The stream of time will carry victory to us!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[307121] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Victory is mine! That's how a real carrier does things, duh!",
	home = "Woohoo, you're back, Commander! Bring any goodies back for me and the girls? I'm already so excited I can't calm down!",
	unlock = "It's– summer– festival– time–!! Uhh, well, maybe it's a bit too late for a \"summer\" festival, so maybe a regular festival is fine? Well, the important thing is that you have lots of fun, Commander! Because I sure as heck will!",
	touch2 = "",
	mission = "Missions? Can't you let it rest for a day and just enjoy the day off??",
	vote = "",
	drop_descrip = "It's– summer– festival– time–!! Uhh, well, maybe it's a bit too late for a \"summer\" festival, so maybe a regular festival is fine? Well, the important thing is that you have lots of fun, Commander! Because I sure as heck will!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "When the fireworks climb high into the sky and go \"kaboom,\" I can feel my excitement doing the very same thing! Ahahaha!|Commander, are you totally into my getup? You are, aren't you! Aha, I totally knew it! Come and feast your eyes all you want then~♪|nil",
	touch = "",
	voice_key_2 = -1,
	mission_complete = "Excellent! With these earnings, we'll be able to eat as much as we want... Well yeah, I know that! We need to share with everyone else too! ...B-but, I'd be really happy if you treated me to a little something... Please?",
	battle = "",
	id = 307121,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Hellooooo, Commander! Are we starting work today with some of that festive spirit? I didn't just bring my festive spirit with me today, I came ready with the whole package, outfit and all! I'll be happy as long as you can feel that holiday cheer~!",
	detail = "You came here looking for someone to talk to, right? I suppose I can keep you company then, but you should make sure you go around and deepen your bonds with everyone else too! ...Except Junyou, watch out for that one!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[307122] = {
	hp_warning = "",
	feeling3 = "",
	mail = "New mail? I'll go get it... Whoa, whoa, whoa, ack, bad, bad, bad! ...Phew... I slipped and almost dropped the mail in the pool...",
	expedition = "Ooh! The commission team came home! I'd love to let you go and greet them by yourself, but they might think something's up if you go alone dressed like that, so I'll join you♪",
	win_mvp = "Aircraft carrier Katsuragi wins again! ...Ahahaha, my victories are your victories, too, Commander.",
	home = "Hey, you're back! So you're hot, right? Right? Of course you are! It's a little weird to get in the pool right after coming back from the sea, but forget that! Jump right in☆",
	unlock = "Mmmh~ When it gets real hot, whether you're a shipgirl or an ordinary person, the place to go to cool down is always either the mountains or the beach, right? But what if I told you, that when you're at a rooftop pool, you not only get the great views of climbing up a mountain, but also the refreshing coolness of splashing around in the water? Am I right or am I right, Commander? ...Heeeey, are you even listening?!",
	touch2 = "Yeah, I might be a little lacking compared to the other girls... What do you want me to do about it, though?",
	mission = "You STILL have missions left? ...Are you even listening?",
	vote = "",
	drop_descrip = "Mmmh~ When it gets real hot, whether you're a shipgirl or an ordinary person, the place to go to cool down is always either the mountains or the beach, right? But what if I told you, that when you're at a rooftop pool, you not only get the great views of climbing up a mountain, but also the refreshing coolness of splashing around in the water? Am I right or am I right, Commander? ...Heeeey, are you even listening?!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Fire! Drive them back! ...There's no point sitting around in the water all day, so I decided to have the shikigami and manjuu do a mock battle. Wanna join in, Commander?|Want a cold one? Or like a chilly, icy, brain-freezy one? The choice is yours, Commander!|Don't you love this view? You can actually see the beach—and all the other girls in swimsuits—from here, so it's easy to see all the girls looking for you, Commander... Hey, what's wrong?! Did you see something scary?",
	touch = "Aha☆ Fascinated by me and my swimsuit?",
	voice_key_2 = -1,
	mission_complete = "Nice! With all these rewards, we can rebuild the swimming pool until everyone can fit in! ...Shame we can't make it a rooftop pool~",
	battle = "I might be in a swimsuit, but I'm just as strong as ever!",
	id = 307122,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Hello hello, Commander! Boy, it's hot~ Or so I WOULD say, but we're already dressed for the heat. The only cooler places we could go would be your air-conditioned office or a restaurant freezer. So I'm gonna try a different approach! Okay, c'mon in and cool off with me!",
	detail = "Nobody else is around, so I guess you gotta talk to me, Commander! ...Hm? You don't want to take the lead? If I lead the conversation, I might never stop talking, y'know.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[307130] = {
	hp_warning = "Why is that stupid, stupid moron here? Why, why, why?!",
	feeling3 = "I have to get my hands on the key to the office... Oh, hi, my Commander~ Clumsy Taihou left something in your office. Can I borrow your key and go get it? I'll be right back, I promise~",
	mail = "You've received a new letter... Oh, I was just testing it for poison~",
	expedition = "The commission team is back? Since they do it all for you, I'll come along and thank them~",
	win_mvp = "This fate is what befalls all who get between me and my Commander~",
	home = "Back already? Did you miss me that much? Heehee... I know eeeverything about you~",
	unlock = "I've finally found you, my Commander~ Why do you keep avoiding me? Is my love not enough for you? Then take this – a token of my unrestrained love~❤",
	touch2 = "I get it, my Commander. You just couldn't wait any longer❤",
	mission = "A mission? Why should I let something so insignificant detract from my time with you? Just delegate it to someone else~",
	vote = "",
	drop_descrip = "Taihou-class aircraft carrier – Taihou.",
	feeling4 = "My Commander, won't you go on a date with me? I'm only a child, so all those grown-ups would never suspect it's actually a date~ Heehee❤",
	lose = "It's your fault my Commander is sulking... It's ALL your fault!",
	feeling1 = "Is my love still not enough? That's fine. I've got ways to express much, muuuch more of my love...",
	skill = "Would you please perish?",
	upgrade = "You are head over heels for me after all~❤",
	propose = "So you finally admit it~ Even if our relationship stays the same, this officially proves that I've stolen your heart, my Commander~ You are the love of my life, now and forever♥",
	feeling5 = "What's wrong? Is it not a given that you should care for a prepubescent child? It makes sense for us to live in the same room – nobody would bat an eye at that! Heehee~ I won't let anyone take you from me, my Commander♥",
	main = "That Akagi, she sincerely treats you as her slave? Heehee... Let's see if I can't wring an apology out of her~|Has anyone else ever gifted you a toy, my Commander? Oh, no reason... I just thought I'd ask.|My Commander, do tell me when you'd like a break. I'll go and hang an \"on break\" sign on the office door immediately. That will ensure nobody comes and disturbs you~",
	touch = "Ah, a show of affection~ You make me so happy, my Commander❤",
	voice_key_2 = -1,
	mission_complete = "Mission complete. You wanted to finish it with me, didn't you? Heehee~ Getting work done while spending time with me is truly two birds with one stone♪",
	battle = "You'll regret ruining my sweet time with my Commander... Heehee...",
	id = 307130,
	gift_dislike = "",
	gift_prefer = "I'm glad to hear that you love me sooo very much❤",
