_G.pg.base.ship_skin_words[307140] = {
	hp_warning = "Ah...! Th-this one mustn't lose...!",
	feeling3 = "Ngh... This one is too worried to sleep... What problem troubles you so? Fate? Hmm, this sounds complicated... But this one does not believe in it... Well, I don't think I do...",
	mail = "Here is your mail. Messages carried here from distant places must be important.",
	expedition = "*yaaawn*... The commission team has returned... Mm, let this one wash my face first...",
	win_mvp = "An easy win... *yawn*... Off to sleep...",
	home = "Zzzz... Heehee... Fruit candy, cheese, sweet melon... Mm? Oh. You're back... Zzzz.",
	unlock = "You... are the one this one has seen in my dreams. Wonderful... This one feels relaxed around you... But it seems you need this one's guidance, don't you?",
	touch2 = "Sit, you! This calls for a lecture!",
	mission = "Zzzz... If this is a dream, then why has a mission... Ah! A new mission...?!",
	vote = "拉票描述",
	drop_descrip = "You... are the one this one has seen in my dreams. Wonderful... This one feels relaxed around you... But it seems you need this one's guidance, don't you?",
	feeling4 = "Commander, may this one... s-sleep by your side tonight? Lately, nightmares have plagued me... Wh-why are you laughing? You're the one bothering this one about fate...!",
	lose = "I-is this defeat...?",
	feeling1 = "Clearly, this one must educate you...!",
	skill = "Woe, nightmares be upon ye!",
	upgrade = "This one feels a sudden surge of motivation, yet the thought of a sleepless night... Nnh, how troubling...",
	propose = "This... is proof of our vow... Then this one will do everything in my power. Let's see all of our dreams for a happy future come true... together.",
	feeling5 = "With you, this one can feel at ease... Nightmares scare me no longer... Yes, let's keep sleeping together♪",
	main = "Mm... Your office is undoubtedly the perfect place to sleep. Allow this one just five more minutes...|Would you like to dream together? Wonderful... Hm? How do you know that my dream... Could it be?! H-how embarrassing...!|This one cannot sleep... The sound of you flipping pages was just incessant! Come rest with me...",
	touch = "Zzzzz... Heehee... D-do not tickle...",
	voice_key_2 = -1,
	mission_complete = "*yaaaaawn*... Th-this one completed the mission! Please handle the cleanup work... Zzz...",
	battle = "Go forth. This one believes in you all...!",
	id = 307140,
	gift_dislike = "",
	gift_prefer = "Woah! This is really nice!",
	profile = "...Yes, this one is Shinano. Everything else can wait. The world is unpredictable, and the future is unknowable. Let things come as they may, and let this one drift off into the world of dreams...",
	voice_key = 30714,
	headtouch = "Mmm, mmnh, nnh... G-gentle on the ears, please...",
	feeling2 = "Hm? You're here, too... Have you come to take a nap? Oh, you're just here to think about your problems? Mmm... Okay, then this one will nap for a little while you do...",
	login = "*yawn*... Greetings... As you can see, this one is searching for the perfect place for an afternoon nap...",
	detail = "Hmm? You're interested in this one's pillow? That is understandable, but this is actually my rigging... Why do you look surprised?",
	couple_encourage = {
