_G.pg.base.ship_skin_words[308030] = {
	hp_warning = "Seems that I'm being targeted...",
	feeling3 = "\"A journey of a thousand miles begins with a single step?\" Hmm... I suppose I can start by saying hello to her...",
	mail = "Commander, there's new mail... Ah, sorry, I just left the water so I got it wet...",
	expedition = "I wonder what's going on up there on the surface... Ah, Commander, your commission fleet has returned.",
	win_mvp = "Is that all you surface-lubbers are made of?",
	home = "Commander, are the conditions of the waters suitable for me to carry out my activities?",
	unlock = "I-58, reporting in. I usually like hanging out in the water by the docks, so you know where to look if you need me~",
	touch2 = "I mean... I'll admit they're on the small side... but that makes it more hydrodynamic!",
	mission = "New missions? Is there something that I can do?",
	vote = "",
	drop_descrip = "Type-B Mod 2 cruiser submarine – I-58.",
	feeling4 = "Although we can't become close friends that easily, at least we're making some progress... I suppose time will take care of the rest. Commander, thank you so much for your help. As a reward... *kiss*",
	lose = "I've been found, huh... Next time, I've got to be sneakier...",
	feeling1 = "Does this fleet exist only to wage war...?",
	skill = "Can you predict where I'm going to attack from?",
	upgrade = "Mhm, my body feels lighter.",
	propose = "Commander, I'm sure that you will be able to create that world... where everyone can smile from the bottom of their heart... As for me, I can't think of anything happier than being with you right now.",
	feeling5 = "It's hard to let go of the past... but Commander, you've rewritten everyone's futures, to one where we can all move forward together. Commander, I can't be prouder of the fact that I fell for you.",
	main = "It's not like I'll die if I'm taken out of the ocean, but I definitely prefer being in it. *blub blub* |Commander, when it comes to swimming, which stroke is your favorite? Crawl? Butterfly? Breaststroke? |There are a lot of miraculous things in the ocean. Want to go on a dive with me and experience it for yourself?",
	touch = "It's important to warm up before diving. Commander, let's do some exercises together.",
	voice_key_2 = -1,
	mission_complete = "These mission rewards... there's nothing that can be brought underwater...",
	battle = "I'll let the rest of you handle the anti-sub.",
	id = 308030,
	gift_dislike = "",
	gift_prefer = "Commander, in return, I'll let you pick something out from my seashell collection.",
	profile = "Type-B Mod 2 cruiser submarine, I-58. Yup, that's me. I was born towards the end of the war, and participated in several missions. Before the end of things, I managed to sink Indianapolis. Even though it was a great achievement, it's not like it ultimately made a difference...",
	voice_key = 30803,
	headtouch = "",
	feeling2 = "Now that we're all on the same team, I'm going to have to learn to work with Indianapolis... but that sister of hers, bleh... Ugh, maybe I'll just go for a swim instead...",
	login = "Commander, submarines will die if you take them out of the water. I-I was just kidding...",
	detail = "I love the serenity of the night. Nobody ever notices my presence.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[308040] = {
	hp_warning = "Now, this is a bit of a sticky situation...",
	feeling3 = "...Is Commander really not coming today..? I'm going to die of loneliness... ... C-Commander?! Did you hear me just now??",
	mail = "New mail keeps piling up... Commander, you should hurry up and start getting through these...",
	expedition = "Everyone in the commission fleet has returned safely. Hmm... should I reward them with some homemade chocolate?",
	win_mvp = "Heehee, from now on, just leave it to me~",
	home = "Judging by your grin, Commander, you must've had a resounding victory. Hehe, why don't you come here and let me massage your shoulders?",
	unlock = "Phew... I finally found you! Commander, I'm I-25. I hope that I can be a big help to you. Anyway, it's nice meeting you~",
	touch2 = "Commander, do you... like this kind of sensation...?",
	mission = "There are still some missions that need to be completed. Commander, let's finish them together.",
	vote = "",
	drop_descrip = "Type B1 cruiser submarine – I-25.",
	feeling4 = "Commander, sorry to call you out all of a sudden, but I've just been so lonely... I'm quite bold, you say? Ehehe... Well, you know, I did have a bit of experience getting... tangled up with the enemy back then. Want to hear more about it?",
	lose = "Is everyone safe?",
	feeling1 = "Though I am very sorry that it has come to this, I must once again remind you that your poor work ethic has already affected the fleet.",
	skill = "Now's our time to attack!",
	upgrade = "Hehe... Thank you for helping me become even more reliable, Commander~",
	propose = "This is the proof of our oath to each other, Commander... Thank you so much! Finally, I've found my happiness! I'm so glad... we'll get to spend all our days together like this from now on! Ehehe~♪",
	feeling5 = "Ahhn... Commander, you've come to see me again... Today... today, you won't leave my side this time, right? Commander, if you stay with me, I'll never be lonely ever again!",
	main = "Where I'm from, we always offer our respects for the food in front of us before each meal. It's a custom that helps us be at ease. |I hope my sister hasn't been causing too much trouble for you. She's a little ball of energy... there's no way I can keep up with her... |Commander... Commander...? Are you still asleep? I'm getting a bit worried...",
	touch = "Haah... I'm being filled to the brim with your energy, Commander...",
	voice_key_2 = -1,
	mission_complete = "These are the fruits of everyone's efforts. Make sure to receive them with pride.",
	battle = "Sometimes, you've got to stand out!",
	id = 308040,
	gift_dislike = "",
	gift_prefer = "I-is this a gift from Commander? Thank you! This makes me really happy!",
	profile = "I'm the Type-B class cruiser submarine, I-25. I'm at my best when it comes to reconnaissance and disrupting shipping routes. I've also been in some... pretty daring operations. Hehe~ Commander, you can count on me.",
	voice_key = 30804,
	headtouch = "",
	feeling2 = "Commander, thank you for coming to see me today. Because of you, I'll have some extra spring in my step. Hehe~",
	login = "Mmh... Welcome back, Commander. While you were gone, I finished compiling all the reports. Here you go~",
	detail = "Sorry to bother you when you're busy, Commander, but could you please help me test the capabilities of my seaplane?",
	couple_encourage = {
		{
			{
				30802
			},
			1,
			"Try not to get lost, all right?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[308041] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Uuhh... the whole time during class, I was thinking about when you'd come back, Commander... Looks like I-26 is going to make fun of me again...",
	unlock = "Hi there, Commander. Oh, this outfit? I'll be wearing it to school today. By the way, did you want to come sit in on my class?",
	touch2 = "Woahh... Commander...",
	mission = "",
	vote = "",
	drop_descrip = "Hi there, Commander. Oh, this outfit? I'll be wearing it to school today. By the way, did you want to come sit in on my class?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Coral reefs are breathtakingly beautiful, Commander. If you ever want to see for yourself, just let me know. |This might sound strange coming from me, but forest fires are a very serious matter. There will be dire consequences if you don't take that to heart. Just ask the girls of the Eagle Union. |There's nothing wrong with I-19, right... The next time I-26 calls everyone to play, I'll go check on her.",
	touch = "Haah... as long as you're by my side, I feel safe and sound.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 308041,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "D-deep sea fish, attack! Umm, uh... that's not how it works...? I don't seem to be very good at this...",
