_G.pg.base.ship_skin_words[312018] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Commander, you look like you're in need of some comforting, nya. I guess I'll need to do it, nya~ Come here, and I'll give you a nice headpat, nya~",
	unlock = "Commander, because of your continued patronage of my shop, I have no choice but to return the favor with my body, nya~! ...Just kidding, nya. Having that said, I really do love you, Commander. Even more than I love gems, nya~",
	touch2 = "Nyahaha? Did you remember just how charming I am, nya?",
	mission = "Commander, I think this mission has a huge payout, nya!",
	vote = "",
	drop_descrip = "Commander, because of your continued patronage of my shop, I have no choice but to return the favor with my body, nya~! ...Just kidding, nya. Having that said, I really do love you, Commander. Even more than I love gems, nya~",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "As long as I'm here, you can go full steam ahead toward the future without having to worry about supplies, nya! I will support you as your partner, nya!",
	main = "I know you love me, but sometimes you see me only as a shopkeeper, nya! You can't keep treating me like this, nya!|Commander, if anything in my shop catches your eye, feel free to claim it, nya~ I'll deduct the cost from my wallet, nya! Because what's yours is mine, so your wallet is mine too, nya♪ Don't worry, I'll give you some discounts from time to time! ...Probably, nya!|Commander, help me out at my store, nya! In exchange, I'll do my best as a secretary, nya! I'd say that's a good deal, nya!",
	touch = "Mrrr... Commander, I'm getting sleepy, nya... Give me a lap pillow, nya...",
	voice_key_2 = -1,
	mission_complete = "Nyahaha~ Just as I expected from you, Commander. I'll put the mission rewards to good use, nya~",
	battle = "",
	id = 312018,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, let's work hard today to make a pile of gems, nya~",
	detail = "Not more than one pair of these super-premium clothes exist in this world, and they belong to the Commander, nya! ...If you're looking for some other, even more premium clothing, check out my store, nya♪",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[317010] = {
	hp_warning = "I guess this is all a submarine can do...",
	feeling3 = "You think I'm weird, do you? Heheh, maybe I am... Just remember: there are only so many things a regular submarine can do. That's something I learned during my short time in service.",
	mail = "Commander, my Seiran has arrived with mail.",
	expedition = "Hey, Commander, a commission should be done by now.",
	win_mvp = "This victory will be a great help to our other fleets.",
	home = "Nice job on that last mission, Commander.",
	unlock = "Hi, Commander. I'm the aviation submarine I-13. My hobbies include aircraft and gazing up at the sky! Also, this is my friend, my Seiran. I'm glad to meet you.",
	touch2 = "Don't make me pepper you with my Seiran's machine guns.",
	mission = "Remember to give those missions a look, okay, Commander?",
	vote = "",
	drop_descrip = "Type A Mod. 2 cruiser submarine – I-13.",
	feeling4 = "I've gotten closer to the carrier's aircraft now, and it's all thanks to you. I've never been this happy before in my life. Thank you, Commander!",
	lose = "It's not good enough to be an ordinary submarine...",
	feeling1 = "You just don't understand me either, do you, Commander?",
	skill = "Here it comes... Everything I'm capable of!",
	upgrade = "Maybe I can fit a few more Seirans once I get stronger?",
	propose = "A... Hellcat? An Avenger? Even a Hurricane, and all these other planes?! You... went out and borrowed them all just for me? Oh, Commander... I love you so much I can't even think straight...!",
	feeling5 = "I want to repay you somehow for everything you've done for me, Commander. I'll do anything you want! If I can help you, you can then help me back.",
	main = "Don't get the wrong idea about me, Commander. I do love aircraft, but that doesn't mean I hate myself for being a submarine.|The sea is the color of the sky. And the sky is the same color as me!|There's the Type 97 and Type 99, the Suisei, Tenzan, Ryuusei, Saiun, and of course, my Seiran. I know everything there is to know about aircraft!",
	touch = "I'm okay with lending you my Seiran, but it's veeeeery expensive! Break it, and I'll be really angry, okay?",
	voice_key_2 = -1,
	mission_complete = "Commander, my Seiran just came back with the mission rewards.",
	battle = "Let's give it our best shot.",
	id = 317010,
	gift_dislike = "",
	gift_prefer = "Thanks a bunch~",
	profile = "I'm I-13, formally known as the Type A Mod. 2 cruiser submarine model thirteen. Some people call me the fifth of the Type A model, but I was really just an upgraded model that could store Seirans. Sounds cool, doesn't it? Well, sadly, I didn't achieve much of note...",
	voice_key = 31701,
	headtouch = "Mmh... If you're gonna headpat me, just a little is fine…",
	feeling2 = "Welcome to my room, Commander. I've got books on aircraft lying around if you want to read those. Oh, and please be careful around the model plane on the shelf over there.",
	login = "Welcome back, Commander. The skies are ever blue!",
	detail = "There's only so many things a regular submarine can do. To turn the war around, we need more wings in the air.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[317011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "You should come up here. You can really feel the breeze up here. It'll blow all your fatigue away! Come on, I'll help you take off your jacket.",
	unlock = "So high up... But it's okay, Commander – I have a good sense of balance. Anyway, wanna see what's down there?",
	touch2 = "C-Commander! You'll make me lose my balance... It'll really hurt if I fall from here!",
	mission = "",
	vote = "",
	drop_descrip = "So high up... But it's okay, Commander – I have a good sense of balance. Anyway, wanna see what's down there?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "The sky and the sea come together into one up here. Everything's dyed blue. Heehee – I wish we could look at this view forever and ever.",
	main = "The roundy-head's an octopus♪ The longy-head, yes, that's a squid♪ Let's find out what friends we'll meet today♪|Be careful of poisonous fish, Commander. Like the pufferfish, and the striped eel catfish, and the manta ray... Luckily, we don't have to worry about them here!|Can't even find one with my Seiran... Oh, I was talking about clams. I used to do clam-digging at the beach long ago. I remember my feet getting stuck in the mud, which wasn't nice...",
	touch = "What is it, Commander? Do you wanna observe with me?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 317011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Hrmph... I'm standing higher up, so why am I the one getting headpatted?!",
	feeling2 = "",
	login = "Are you heading home, too, Commander? Heehee – alright, then come to me. The view here is mindblowing. You can see all kinds of stuff from up high. Heehee... I took my shoes off so I won't slip, so don't worry about me.",
	detail = "Commander, have you ever done animal observation reports? I swim with fish in the sea all the time, but I've never observed an animal up close like this before... It's really fascinating!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[317020] = {
	hp_warning = "Bloodshed is what makes a battle so sublime!",
	feeling3 = "Diving with you is so much fun. That reminds me, when we were in the water just earlier and a school of pilchards showed up, you were looking at me instead of the fish, weren't you?",
	mail = "A letter's arrived. You'd better stop ignoring it before I sublimely claim it for myself.",
	expedition = "The commission team's back. Seems they got a pretty sublime haul, too... Hm? Precognition? No, no, I just saw them while diving. Telling the future is not one of my abilities.",
	win_mvp = "With sublimity, my enemy was vanquished. Kotama also had fun.",
	home = "Must've been a sublime battle. How do I know? Because I had front row seats in the water and witnessed it from start to finish.",
	unlock = "I'm I-404, Sakura Empire submarine. I crossed depth after depth to answer your call, and now I'm here. Hmph! I demand cheers! Feast your eyes on my glorious wave-spanning might!",
	touch2 = "Heehee. I know exactly what you want. Alright, if you want to make me yours, you've got to do it with your own two hands♪",
	mission = "Look at all these unfinished missions... I think I'm going to go diving!",
	vote = "",
	drop_descrip = "I-400-class large submarine aircraft carrier – I-404.",
	feeling4 = "Spacing is hugely important in the Sakuran arts. From the fingertips stopping for just a moment, to a pause where a breath is taken, there's a thousand words and feelings put into each one. If you wanna learn about my dancing, start by following my steps! Come on, Commander! Let's dance!",
	lose = "This is not the kind of \"going down\" I wanted to do!",
	feeling1 = "Move discreetly and dive stealthily... Can't find me, can't find me...",
	skill = "May your body be pierced into a bottomless abyss!",
	upgrade = "Oho... You're saying I can still get stronger and sublimer?",
	propose = "Heheh. You still don't get it, huh? You are mine even without this ring. Still, this is a great opportunity for you to finally realize it – that my essence is cut into you and your whole body.",
	feeling5 = "Hmm... If you ask me, I think the feeling of love is the world's sublimest miracle. It's like the excitement of finding a beautiful coral reef deep underwater, then turning around to see you right next to me.",
	main = "The clouds today look a bit like sand patterns on the sea floor... I've got it – it must mean the sea is calling for me! Come on, we're going diving once you finish your work!|Knock... Another knock... Is that the sound of someone practicing kagura? I'm going to go and have a look, Commander!|...Ahh! Man, I love diving! Oh, you've been looking for me for a long time? Uh... Ahaha... Oopsie. I forgot the time.|If you're asking what the sublimest place I've seen under the water is... Hmph. That's obviously a secret. If you want to see it, you'll have to spend more time with me and the sea.",
	touch = "Swim or dance? I can do both! But whichever it's going to be, we better start now!",
	voice_key_2 = -1,
	mission_complete = "Were you looking for me? Heheh. I snuck through the water and got here first.",
	battle = "I'm taking the lead? Okay, I'll be sublime about it.",
	id = 317020,
	gift_dislike = "",
	gift_prefer = "Ahaha. Pretty sublime. This is exactly what I wanted! Thanks♪",
	profile = "I'm I-404, Sakuran large submarine aircraft carrier; the biggest, sublimest submarine in the world; the boat that fights alongside a seadrake. I'm also the strongest precisely because I was never completed. Heheh – got anything to say about that?",
	voice_key = 31702,
	headtouch = "Hmgh?! Urgh... Mgh... Don't do that while I'm eating sea urchins!",
	feeling2 = "Mh... Hm?! Hang on, is... Is that first-grade sea urchin you've got there?! Heheh! I knew it was a good idea to come with you! Man, you're the best!",
	login = "What, time for work already? The sea is as sublime as lapis lazuli, and the breeze is calm... Can't we change that \"regular meeting\" in the schedule into a diving session?",
	detail = "Alright, let me reintroduce you – this is Kotama, my seadrake rigging! It deserves part of the credit for my sublime victories. Hm? No, my sublime dancing is solely my own effort!",
	couple_encourage = {
		{
			{
				39906
			},
			1,
			"Dragon God, let us dance!",
			0
		}
	}
}


