_G.pg.base.ship_skin_words[319010] = {
	hp_warning = "It's just a scratch... Don't worry, I can keep going!",
	feeling3 = "I often play with the little destroyers. Like this... I put one on each shoulder and pretend like I'm some giant monster or robot... Yes, it's quite fun~♪",
	mail = "There's a letter on this pile of supplies...? Oh, it's addressed to you, Commander. Here you go.",
	expedition = "The commission team has returned safely. Let's go greet them. Having that said, I'm used to being in their position though, not the other way around~",
	win_mvp = "This sense of elation is rather mysterious... Mm...",
	home = "Phew... Oh, Commander, welcome back. I just finished stashing the supplies that the others brought back into the warehouse. The inventory? Um... please give me a moment.",
	unlock = "Well met, Commander. I am Kashino, munition ship of the Sakura Empire. Hmm... I may be a rather peculiar ship, but... if there's anything I can help with, please entrust it to me... is that acceptable?",
	touch2 = "Eek?! Commander?!",
	mission = "Do you still have missions to complete? Please be mindful of the deadlines.",
	vote = "",
	drop_descrip = "Munition ship – Kashino.",
	feeling4 = "Commander, if you're tired, why not take a bath? Afterwards, if you enjoy some fresh milk, you'll be sure to feel— C-Commander?? What's wrong? Should I take you to the infirmary...?",
	lose = "Ugh... It's hard for me to keep up with the actual warships...",
	feeling1 = "I can bring you all the supplies in the world, but you don't seem to be capable of using them well...",
	skill = "I've brought the supplies!",
	upgrade = "Hmm... Was I supposed to feel different...?",
	propose = "As a munition ship, I may not be very useful in combat. However, as long as you believe in me and cherish me... I'll try to be as useful as I can in other ways...! Mhm!",
	feeling5 = "Phew... Ah, Commander, are you feeling better now? I've brought iced milk, sweets, and everyone's well-wishes. Ehehe~ If you'd like me to wash your back again, just let me know.",
	main = "1, 2, 3... Commander, the supplies you've given me to transport are all accounted for. Hm? It's all right, you don't have to get everyone to help me carry it. It's not very heavy...|♪~ Commander, I brought you your tea. Adding a bit of milk will give it a Royal Navy flair... how about it?|Commander, how about decorating your window with a windchime? Enjoying a refreshing breeze while enjoying this delicate sound will surely make you feel better~",
	touch = "Am I carrying main guns again? ...Ah, sorry, I spaced out a bit...",
	voice_key_2 = -1,
	mission_complete = "Mission complete~ That's one fewer thing to worry about.",
	battle = "Anti-air combat... commencing!",
	id = 319010,
	gift_dislike = "",
	gift_prefer = "This is... for me? Thank you very much!",
	profile = "My name is Kashino. My favorite hobby is relaxing in the hot springs, and my weight and height are... Ack, that's not what I'm supposed to be saying! Excuse me... Um, I was the ship that was created to transport the Yamato-class's 40cm Type 94 gun, but I also participated in various transport missions before finally being sunk by a submarine... Hmm, is that good enough...?",
	voice_key = 31901,
	headtouch = "Oh...! S-sorry, did I hit you with my tail...?",
	feeling2 = "My rigging is a bit different from that of the other girls. Want to learn more...? Mm, why don't you come take a seat on my deck then?",
	login = "Welcome back, Commander. Is there anything I can transport... Err, I mean, is there anything I can help you with...?",
	detail = "My weapon? ...Hyah! Eh? I look really cool? D-don't say that, I barely know how to use it... ",
	couple_encourage = {
		{
			{
				30708
			},
			1,
			"I've brought your armaments!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[319011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "By the way, Commander, there was a letter for you... Sorry, I forgot to report it earlier...",
	couple_encourage = "",
	expedition = "",
	win_mvp = "",
	home = "I've kept the fresh milk in the fridge back there. After you've finished bathing, please feel free to help yourself~",
	unlock = "Ack... Owww... My apologies, Commander, I seem to have slipped on something... At times, it's hard to notice things I'm about to step on... Ugh...",
	touch2 = "Th-they're pretty heavy, right...?",
	mission = "",
	vote = "",
	drop_descrip = "Ack... Owww... My apologies, Commander, I seem to have slipped on something... At times, it's hard to notice things I'm about to step on... Ugh...",
	feeling4 = "",
	lose = "Oww... My luck isn't so good today...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Phew... That feels so good... My shoulders aren't stiff anymore~ Commander, thank you for telling me about this place~ |M-my swimsuit, um... Commander's going to see... Erm, please disregard that!|A nice bottle of milk after a refreshing soak really hits the spot~ Let's get another bottle later~♪ ...Um, I knocked the first one over when I slipped earlier...",
	touch = "Shall I... wash your back for you?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 319011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, are you enjoying the water? Yes, I love the hot springs here~",
	detail = "If there's anything lacking about these hot springs, it's the fact that this place is too small... If you're not careful, it's easy to slip or to bump into various things..."
}


_G.pg.base.ship_skin_words[319012] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Hnnngh... Mail's here! I had to struggle to pick that one up!",
	expedition = "The commission team is back! Uh, umm... I can't exactly greet them like this, can I...?",
	win_mvp = "Phew... I'm glad I took extra-special care to avoid messing anything up.",
	home = "Nnngh! Haah, haah... I just can't get out. They said this store was built well, but this isn't especially reassuring, is it...?",
	unlock = "Hyah?! U-Umm, I can't get out... Oh, Commander?! I'm sorry! I tripped while I was cleaning, and I ended up stuck in here! Umm... What do I do now...",
	touch2 = "Ah, watch your step... (BANG!) Hyah?! C-Commander?!",
	mission = "W-we've been issued a new mission! Commander, let us check at once!",
	vote = "",
	drop_descrip = "Hyah?! U-Umm, I can't get out... Oh, Commander?! I'm sorry! I tripped while I was cleaning, and I ended up stuck in here! Umm... What do I do now...",
	feeling4 = "",
	lose = "Honestly, this outfit is more suited to service than combat...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "How did this happen, you say? Well, um... I'm not too sure, myself. You say this doesn't normally happen? Ooh...|The ingredients are on the shelves, and the snacks are in the fridge. There's cold milk in there, too, so feel free to help yourself.|Honestly, it's really hard to maintain this posture. Umm, b-because they're really heavy... *blush*",
	touch = "Commander?! P-please don't pull on the door right now, or... Hyah?!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Want to see how a maid fights? Get ready!",
	id = 319012,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Oh, I... c-can't get out this way, either...",
	feeling2 = "",
	login = "Commander, if there's anything I can help you with—Oh. Erm, maybe I'm the one who needs help...",
	detail = "Being a maid is a lot harder than I thought... I can do physical labor and simple chores just fine, but deep cleaning never goes well.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[319013] = {
	hp_warning = "",
	feeling3 = "",
	mail = "There's a letter among the gifts...? Oh, it's addressed to you, Commander.",
	expedition = "It looks like the commission team has returned. Umm... May I call them over for a rehearsal...?",
	win_mvp = "Commander, wasn't that perfect?! ...O-only my fighting was?",
	home = "♪~ Sit the body in my lap, hold the neck with my left hand, the bachi in my right... Hm? Commander? Is something about me bothering you?",
	unlock = "♪~ Commander, how'd that sound? Hmm... I just started learning last minute, so I guess things aren't coming together after all... But, why do I sound off-pitch even though I'm playing everything exactly the way I was taught...?",
	touch2 = "F-forgive me... *blushes*",
	mission = "",
	vote = "",
	drop_descrip = "♪~ Commander, how'd that sound? Hmm... I just started learning last minute, so I guess things aren't coming together after all... But, why do I sound off-pitch even though I'm playing everything exactly the way I was taught...?",
	feeling4 = "",
	lose = "Hwah?! I-I accidentally stepped on my kimono...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "*inhale*... *exhale*... Don't think too much, just do as you practiced... You'll do just fine, Kashino...!|By the way, I call this set the geisha party! Hehehe, I put more effort into the name since I was going to invite you♪|You say it's a little hot...? I-I didn't turn up the heat... Maybe it's just because of the lighting and atmosphere...?",
	touch = "You'll show me how to do it right? Thank you, Commander...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 319013,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Ah... *blushes*",
	feeling2 = "",
	login = "♪~ How did you like my performance, Commander? Hehehe, I somehow feel like I'm both making progress and hitting a plateau... What exactly am I doing wrong?",
	detail = "I'm glad you know so much about instruments, Commander~ I didn't know the correct playing posture, so I could never play just right... Y-you say it's not a posture problem?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[319014] = {
	hp_warning = "",
	feeling3 = "",
	mail = "A new letter? *sigh*... I can't be expected to transport things while dressed like this...",
	expedition = "The commission team is back! Oh gosh... I can't face them dressed like this...",
	win_mvp = "How about another bottle to celebrate this victory? Although, it's milk and not champagne, so...",
	home = "Welcome back, Commander. Can I interest you in some milk? It was squeezed and bottled just this morning.",
	unlock = "W-welcome... A bottle of milk is just as good after swimming in the pool as it is after bathing in a hot spring... Umm, should I really be wearing this? You seem to be blushing, Commander...",
	touch2 = "Wh-what should I do?",
	mission = "Umm, Commander... You have unfinished missions.",
	vote = "",
	drop_descrip = "W-welcome... A bottle of milk is just as good after swimming in the pool as it is after bathing in a hot spring... Umm, should I really be wearing this? You seem to be blushing, Commander...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Have fun at the amusement park with everyone else? No, no, I promise I'm already having a lot of fun, entertaining you and the other guests! Also, since I'm dressed like this... at least wait until we're alone, okay?",
	main = "Commander, what would you like to drink after a tour around the park? ...Hm? Anything served by me will be fine? O-oh gosh...|Th-thanks for your order! That's one cold milk, one gomme syrup, and a sprinkle of my love... Wait, what?!|*pant*... *pant*... Standing like this all day is actually pretty hard... No, not because I'm embarrassed or because it's hot, but because the sign is pretty heavy, and so are my... N-never mind, forget it!",
	touch = "C-can I take your order?",
	voice_key_2 = -1,
	mission_complete = "Mission complete. As for the rewards... I-I think I'll wait here while you do it...",
	battle = "Th-this feels so inappropriate!",
	id = 319014,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Whew... That helped me calm down a little.",
	feeling2 = "",
	login = "W-would you like a bottle of milk? Thanks for your patronage! Oh, don't worry about paying – this one's free, as thanks for all you do, Commander.",
	detail = "There are lots of stalls here, so I'll probably fill up pretty quickly if I try the food at just a few... Just exercise and it'll be fine? Well, I suppose so...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[331050] = {
