	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 331050,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "During holidays, everyone always has lots of fun. Of course, Ayanami is also having lots of fun...",
	detail = "Fubuki seems to have drawn \"Misfortune\" at the fortune-telling shrine, but she doesn't really seem to mind... Me? \"Small blessing.\" I'm glad.",
	couple_encourage = {}
}


