	id = 331053,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "",
	detail = "Using qing-gong to fly into the air, or firing huge sword beams... I don't know about other people, but Ayanami can't do stuff like that...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[331054] = {
	hp_warning = "",
	feeling3 = "",
	mail = "There's a delivery order... When I come back, I'd like to bring a portion for Javelin too.",
	expedition = "A new shipment of food has arrived. Ayanami will go help out.",
	win_mvp = "",
	home = "Welcome back, Commander. Here's your large cola, ice-cold. Please enjoy, yes.",
	unlock = "Welcome. Ayanami will be taking your order, yes. Will this be dine-in, or to-go? I would personally recommend the cola.",
	touch2 = "Ayanami... is still working...",
	mission = "Commander, if you're tired from your mission, how about enjoying some cola? Ayanami will treat you.",
	vote = "",
	drop_descrip = "Welcome. Ayanami will be taking your order, yes. Will this be dine-in, or to-go? I would personally recommend the cola.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "If you're not sure what to order, Laffey's favorite Teriyaki Twisters, Zed's recommended french fries, and cola make a great combo.|I like my cola ice-cold. How about you, Commander?|Hm... Does this combo go better with ketchup or barbecue sauce... Do you know, Laffey?",
	touch = "Commander, care for another cup of cola?",
	voice_key_2 = -1,
	mission_complete = "I see, you're all done with your work... Ayanami has to work hard too, yes.",
	battle = "",
	id = 331054,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Come on in, Commander. We're having a special discount campaign today, so... take your pick.",
	detail = "Ayanami messed up the order once... I thought Zed would chew me out, but she ended up encouraging me instead...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[331055] = {
	hp_warning = "",
	feeling3 = "",
	mail = "A message from Akashi? Probably should take it with a grain of salt, yes.",
	expedition = "...Oh. The commission team's back. I'm sure it'll be a Great Success.",
	win_mvp = "Your own body is the mightiest weapon. Javelin has yet to learn this, heh.",
	home = "Welcome back, yes. First, we must cleanse Laffey's debuffs. Oh, she's just sleeping...?",
	unlock = "Ultimate Ability: Dynamic Kick! ...Oh, I used my skill on the wrong target. Sorry, can we try that again?",
	touch2 = "Commander... *blushes*",
	mission = "This quest looks pretty tough, yes. But if we all do our best, I'm sure we'll be able to clear it!",
	vote = "",
	drop_descrip = "Ultimate Ability: Dynamic Kick! ...Oh, I used my skill on the wrong target. Sorry, can we try that again?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "Taste the Demon's jump-kick!",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Sorry about the dungeon repair costs... There goes all of Zed's equipment funds... *sigh*...|By the way, Commander, what kind of role do you want to play? It'd be nice if you could play some sort of healer to support us.|Look at that...! It's a Meowfficer dressed up as a monster! Can you get EXP from defeating it?",
	touch = "Commander, can you help me practice my ultimate ability?",
	voice_key_2 = -1,
	mission_complete = "The bonus rewards are in. We should set it aside for Zed's gear.",
	battle = "When it comes to multi-hit combos, Ayanami has the upper hand, yes!",
	id = 331055,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Ultimate Ability: Dynamic Kick! ...Oh, good morning, Commander. I was just practicing my ultimate ability... Thankfully it didn't hit you, yes.",
	detail = "I've seen through this dungeon's layout, yes. I've honed my senses by training with the legendary L.I., so you can count on me.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[331056] = {
	hp_warning = "",
	feeling3 = "",
	mail = "The mail's here. I wonder who put it here?",
	expedition = "Looks like the commission's done, yes. Shall we head out together?",
	win_mvp = "Please praise me more for this splendid victory, yes...",
	home = "Kyaa~ Ayanami is falling in love all over again... Huh? That kind of line doesn't suit me at all...?",
	unlock = "*fidget, fidget*... Oh, how's the party? Yes, I get a little angsty when I'm without a weapon... I envy your ability to stay calm no matter what.",
	touch2 = "You're also into that... I guess?",
	mission = "There's still work left to do. Commander, let's hop to it after the party's over.",
	vote = "",
	drop_descrip = "*fidget, fidget*... Oh, how's the party? Yes, I get a little angsty when I'm without a weapon... I envy your ability to stay calm no matter what.",
	feeling4 = "",
	lose = "Understood. Retreating immediately!",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "If anything happens, I will protect you with my bare hands. I have a lot of experience playing fighter classes in games.|Did Laffey already go to sleep? Speaking of which, I'm starting to feel drowsy as well... I wanna go back to my room and roll around in bed.|It's good to get my homework done? Oh, this isn't my homework. Umm, it's not like you can get any paperwork done during a party either.",
	touch = "Commander? What's the matter?",
	voice_key_2 = -1,
	mission_complete = "Huh? Mission rewards are here? Commander, did you finish work while chatting with me...?",
	battle = "My rigging... is ready!",
	id = 331056,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Phew... I'll be meeting up with the girls later, yes. Are you also heading back to the venue, Commander?",
	detail = "Commander, would you like to dance? ...Mm, I'll be fine, as long as I follow the beat like a rhythm game. I can handle this, yes!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[401010] = {
	hp_warning = "What are you all afraid of?",
	feeling3 = "Life is short, Commander, and I want to live life on the edge. If you are going to be my partner, you have to keep up. Now, let’s see that smile!",
	mail = "Hey, you have new mail. Don’t drop it!",
	expedition = "A commission has been completed. Straighten up, you have to greet the hardworking girls with your best smile.",
	win_mvp = "Hah hah hah! The great Z1 is unrivaled!",
	home = "Nice expression you've got there. Wasn't that battle simply exhilarating?",
	unlock = "Rejoice, Commander! Allow me, Z1, to handle all your problems from now on!",
	touch2 = "You want some \"hard love,\" is that it?",
	mission = "We have a new mission. How about we take it on together?",
	vote = "",
	drop_descrip = "Type 1934 destroyer – Z1 Leberecht Maass.",
	feeling4 = "Even if the world was coming to an end, I have nothing to fear. As long as you are at my side, I can continue to laugh.",
	lose = "Not bad, fellas...",
	feeling1 = "How disappointing, Commander. You’re no fun at all.",
	skill = "Follow me to glory!",
	upgrade = "Hah, this feels pretty good!",
	propose = "Once you are with someone, you can no longer only think to take care of yourself. Though I can no longer cry or laugh to my heart’s desire, I do not regret becoming yours at all, Commander.",
	feeling5 = "Now that I think about it, the apocalypse is often associated with wild romances, or couples who cling to each other until the bitter end. Commander, why don’t we become as Adam and Eve?",
	main = "Let's see who can do this paperwork faster~!|My full name is Leberecht Maass, but you can call me Z1.|Do your best, Commander. I'll always be by your side~!",
	touch = "Don’t be so wishy-washy if you’re greeting someone.",
	voice_key_2 = -1,
	mission_complete = "Our teamwork is unbeatable! Let’s go check out those mission rewards.",
	battle = "Ride the wind and break the waves! Feuer!",
	id = 401010,
	gift_dislike = "",
	gift_prefer = "Vielen Dank. This is just what I wanted.",
	profile = "I’m not like the other so-called \"big sisters.\" I am Z1, the eldest of all Iron Blood destroyers, and bear countless resposibilities upon my shoulders. Rest assured, Commander, because the invincible Z1 is at your side.",
	voice_key = 40101,
	headtouch = "",
	feeling2 = "What’s up, Commander? Are you enjoying your everyday life with me? I sure am.",
	login = "Come, let us brawl!",
	detail = "Fast and strong, that's me!",
	couple_encourage = {
		{
			{
				40303
			},
			1,
			"Your smile is so fake.",
			0
		},
		{
			{
				10
			},
			5,
			"Ha, follow me, you monkeys!",
			4
		}
	}
}


