_G.pg.base.ship_skin_words[401090] = {
	hp_warning = "Urk... I'll be left behind at this rate...",
	feeling3 = "In this book, the prince and princess get separated... I'd draw a much better ending for them. Do you have any ideas? Umm... Maybe we could draw it together?",
	mail = "I brought your mail. I even sorted it...",
	expedition = "The commission team came back to us. I'll go inventory the supplies!",
	win_mvp = "Phew... I won. Commander, did I help out? H-hehe...",
	home = "Good work, Commander. Umm... I can go on missions, too, you know. I-I'll prepare well so I'm not a bother!",
	unlock = "Greetings, Commander. I'm Z9, a destroyer from the Iron Blood, also known as Wolfgang Zenker... I'll do anything I can to help you. Please, just don't abandon me... *sniffle*",
	touch2 = "Eep?! U-umm... I-is that an order?",
	mission = "Commander, your missions aren't done yet. I can help... No, I'm not tired. As long as I can be with you, I'll never tire.",
	vote = "",
	drop_descrip = "Type 1934A destroyer – Z9 Wolfgang Zenker.",
	feeling4 = "A-am I doing a good job? Really?! Okay... Umm, may I have a hug, then? A reward for my good work. Oh... *sniffle*... It's so very warm in your arms.",
	lose = "Aww... I'll try harder next time, I promise. Don't leave me behind...",
	feeling1 = "Say... Commander, if you're in a bad mood, I could lend you my coat. Hide in there, and nobody will find you...",
	skill = "I'll do this, and I'll do it right!",
	upgrade = "Keep getting better. Never let the Commander down!",
	propose = "Commander? If you're giving me this, that must mean... you'll never leave me, doesn't it? You also want to see me smile more...? *sob*... Ahh, umm, oh no... I need to hold back these tears!",
	feeling5 = "I used to be so worried that I'd never do anything right. But you accept me, praise me, and never abandon me... *sniffle*... I'm going to do my best and get better at my job... as long as you let me stay by your side forever!",
	main = "I-I did the paperwork, but I'd like to look over it again... Show it to you first? Okay... It's perfect?! Oh, thank goodness!|Commander, umm, look at this birdie and rose living happily ever after that I drew... The ending of this book I'm reading was so sad that I wanted to redraw it... Hmm? The bird is right here. Does it not look like one...?|Commander, umm... May I sit here? No real reason, I just wanted to be near you...",
	touch = "Commander, where are you going? Oh... Just getting water? Okay, I-I'll come with you!",
	voice_key_2 = -1,
	mission_complete = "Missions are done... Say, umm, now that you have time, what if we read a book together?",
	battle = "Prepare to launch! I think nothing will go wrong...",
	id = 401090,
	gift_dislike = "",
	gift_prefer = "Ehehe... Thank you, Commander. I really love this...",
	profile = "I'm the Iron Blood's Type 1934A destroyer, Z9, Wolfgang Zenker... I promise I'll fight and work better than I did before, so don't abandon me...",
	voice_key = 40109,
	headtouch = "Pet me more, Commander.",
	feeling2 = "Commander, I'm sorry. I messed up again...! Basically, I tripped up and made a mess of your documents. I'll organize them right away... *sniffle*... Huh? You want to treat my bruises first? Thank you...!",
	login = "Commander... *sniffle* W-welcome back... I thought I'd done something wrong and made you leave forever. Ooh... I'm sorry, it's hard to stop crying once I've started...",
	detail = "C-Commander, of course... *sniffle*... You found me again. I'm okay, just let me be alone for now... Ahh, actually, stay with meee...",
	couple_encourage = {
		{
			{
				40116
			},
			1,
			"You're so cool! I wish I could be like you... *sob*...",
			0
		},
		{
			{
				50107
			},
			1,
			"Fei Yuen... You're so good at art...",
			0
		},
		{
			{
				40102,
				40111,
				40118,
				40119,
				40121
			},
			1,
			"We're going to win... together!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[401091] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Mail for you... I-it's okay! I promise it's not wet!",
	expedition = "Drink supplies just came. I'll bring you the new flavor right away!",
	win_mvp = "",
	home = "Commander, thank you for your hard work! Are you thirsty? D-does it make you want to order a drink?",
	unlock = "Commander, umm... Would you like to try our new drink? It's very sweet and tasty... Ahh, why am I so nervous? I need to do better...",
	touch2 = "Ah?! I-is this because I'm a little different today...?",
	mission = "",
	vote = "",
	drop_descrip = "Commander, umm... Would you like to try our new drink? It's very sweet and tasty... Ahh, why am I so nervous? I need to do better...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Try this one, too, Commander... I left it for last because it's not one of our big sellers, but... I-I wanted to share my favorite one with you. It's sweeter and tastier when I drink it with you... Hehe.",
	main = "Huh? I did a good job? Thank you... *sniffle*... I'm so happy to have your approval...|It's weird... I usually feel relaxed around you, but lately, I'm so nervous... Is it because of this outfit? *sniffle*...|If you want to try our new drink, I'll prepare it right away... Oh, I don't mean the stuff in this glass! I-I'll just go get some fresh stuff...",
	touch = "You don't mind that I'm a little sticky...?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 401091,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Okay... I'll do my very best!",
	feeling2 = "",
	login = "How about a drink before you start work? I-I'll go get... Aaah! I almost fell over... *sniffle*...",
	detail = "You think it's weird for me to dress like this, too, don't you? *sniffle*... J-just don't leave me... Ohh, what do I do? I wanna hide in my coat...",
	couple_encourage = {}
