_G.pg.base.ship_skin_words[401110] = {
	hp_warning = "W-wait, am I anemic?",
	feeling3 = "Finally... I can breathe easy next to the Commander...",
	mail = "I organized your mail... I-I'm doing a great job, aren't I?!",
	expedition = "They're back from their commission...? Oof, being outside all day must be rough...",
	win_mvp = "*pant*... I'm still alive?",
	home = "M-Mandy, welcome home~... I-I'm doing my job, I swear! It's just taking a while.",
	unlock = "Hi hi♪ I'm Z11, the Iron Blood's own Bernd von Arnim! Nice to meetcha, Mandy! ...A-ahahaha... It leaves a good impression if I act really happy to see you, right?! Huh? I-it doesn't tell you anything about me? I'm sorry!",
	touch2 = "Y-you're gonna make me melt...!",
	mission = "Mandy, do your missions, or else... O-or else nothing, I guess...",
	vote = "",
	drop_descrip = "Type 1934A destroyer – Z11 Bernd von Arnim.",
	feeling4 = "If I suddenly faint, I want you to catch me... I'd be so embarrassed that I might die, yes, but if I'm gonna die, I'd like it to be in your arms... No, I didn't mean it like that!",
	lose = "Ahh... This is why I never want to go out...",
	feeling1 = "I think I'm just gonna head out... Hahaha...",
	skill = "Go away, bad things!",
	upgrade = "I-I'm stronger now? Really...?",
	propose = "I-I know this is just a prank... I see it all the time. Things would never go the way I dream they would that easi–y-you're serious?! Ah, aaah... I think I'm having a heart attack... I'm so happy I might die!",
	feeling5 = "I thought I wouldn't have to be nervous with you anymore. But my heart is beating so fast, and I'm so short of breath... Why? Commander, do you know why?",
	main = "Commander... C-can I go home now? I'm sorry... I said I wanted to help, but I really just wanna go home...|Do you like my outfit? Special, isn't it? ...D-do you have to think about it for that long?|I wish I could just play games all day forever. You must agree, right? Then we could stay up all night together, and... Ack! I'm sorry! There I go fantasizing again...",
	touch = "Hyaaaah?! Wh-wh-what's going on?!",
	voice_key_2 = -1,
	mission_complete = "Y-you finished your missions? Did I help...?",
	battle = "Huh? ...What? Me?",
	id = 401110,
	gift_dislike = "",
	gift_prefer = "C-Commander, you even knew all that about me...?! Ahh... ahhh...*blushes*",
	profile = "I'm Z11, Bernd von Arnim of the Iron Blood... M-make me your secretary, Mandy! I can game with you and clean your office! I-I'm not just asking because I hate going outside, or anything!",
	voice_key = 40111,
	headtouch = "Heeeek?! I-I'll do my job, really...",
	feeling2 = "I-I-I'm not nervous! See how I'm smiling like I rehearsed a thousand times... Wait, d-don't stare...",
	login = "Morning, Mandy! Ready already~? I-i-i-if we're working... I've steeled my heart!",
	detail = "Bleugh... The sun is a deadly laser... If it melts me like chocolate, I won't be able to help the Commander anymore...",
	couple_encourage = {
		{
			{
				40109
			},
			1,
			" I-I said leave it to me!",
			0
		},
		{
			{
				40116
			},
			1,
			"What's a demon king? ...My role?",
			0
		},
		{
			{
				40123
			},
			1,
			"Z23, help... I wanna go home...",
			0
		}
	}
}


_G.pg.base.ship_skin_words[401111] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "C-commissions? But I've already worked so hard today...",
	win_mvp = "",
	home = "Ahh... Commander, s-sit anywhere you like! I've been out of my room for so long that I'm totally unstable... I don't wanna work anymore...",
	unlock = "I wanted to help at the pop-up shop so I could buy a special-edition game, but I ended up in debt somehow. Commander, help... I'll do anything...",
	touch2 = "Huh? Y-you like me, even when I'm like this...? Th-thank you...",
	mission = "",
	vote = "",
	drop_descrip = "I wanted to help at the pop-up shop so I could buy a special-edition game, but I ended up in debt somehow. Commander, help... I'll do anything...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "If you like how this looks on me... I-I can wear it again for you. That isn't enough to repay your kindness, though... Ahh, what do I do...",
	main = "I hear that game I want is a two-player game. I-if you want, maybe you and I could...?|Part of the reason I wanted to help out was because the outfit was cute... What do you think? Does it look good on me? Ahh, I'm sorry... I guess now isn't an appropriate time...|You paid off my debts AND bought the game for me? Ah, aaah... Commander, you're too nice to me... How can I ever repay you?",
	touch = "I-I'm sorry... Let me just curl up in a ball and die...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 401111,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "T-touch me all you want...! Consider it my thanks for your help!",
	feeling2 = "",
	login = "C-Commandeeer! You finally came to help?! ...Huh? You paid off all the things I broke? Oh, thank you, thank you!",
	detail = "I wanted to serve you and help here so I could afford a game, but... Work is hard, and I'm losing more money from breaking stuff than I am making money... Thank goodness I have you, Commander. I-I'll do everything I can to pay you back!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[401112] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Mandy? You came... Want a checkup? O-or do you wanna rest with me? I'm game for either... U-umm, as long as it doesn't mean going outside.",
	unlock = "C-cut it out, Mandy! I saw you breaking into the nurse station... and trying to snatch those keys! S-stop resisting and let me examine you... H-huh? Does this mean I can touch you all I want?!",
	touch2 = "Mmm... I-I guess nobody says you CAN'T do this with a nurse, so... I-if you want, then I don't mind...",
	mission = "",
	vote = "",
	drop_descrip = "C-cut it out, Mandy! I saw you breaking into the nurse station... and trying to snatch those keys! S-stop resisting and let me examine you... H-huh? Does this mean I can touch you all I want?!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "My goal was to keep you from leaving this place, but... I-I want to leave with you. I'd rather have a heart than be the protagonist of any story!",
	main = "I-it's time for your examination, so you'll need to take your clothes off for... Umm... I-I actually don't know how to do a medical exam, but just strip for me, okay...?|Don't ever go to the areas marked red on the map, okay?! I-I'm not brave enough to go, myself... Let's just pretend they don't exist.|Commander... Can we play a game together? U-umm, I'm trying to convince myself that this place is safe... because game worlds are scarier...",
	touch = "S-sudden PvP?! I-I-I...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 401112,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "(Bleugh... I'm supposed to stay in character, b-but... who can blame a girl for enjoying a little fun?)",
	feeling2 = "",
	login = "O-outdoor activity time is over! Mandy, can you... be good and come with me for your routine checkup?",
	detail = "I-I'm not taking no for an answer! It's dangerous out there, and you'll be safer and comfier here, getting your checkup... I've got my eye on you, Mandy.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[401130] = {
	hp_warning = "Watch out for depth charges!",
	feeling3 = "See – doesn't my advice work wonders? Heheh. This is just scratching the surface, I'll have you know. Remember: You can always come to me with questions! I'll answer to the best of my knowledge and offer the best solution I can!",
	mail = "I've marked your mail to denote priority and the like! There are seven types in all, and... Hm? There are so many marks that they're effectively useless? Uhh... This is actually just to practice my sorting skills!",
	expedition = "Commander, if you want to solve a financial difficulty, start by considering how your cash flow... Hm? A goods inspection first of all? Um, that's kind of outside the field of consultancy.",
	win_mvp = "An effortless win! You get that and more when you leave it to me!",
	home = "Here, have a taste of my specialty nerve-soothing drink! You see, milk has a calming effect, and tea relieves stress, so... \"That's just milk tea\"? Why, yes, it IS milk tea!",
	unlock = "Heheh, I'm Erich Koellner, otherwise known as Z13. I know you like the back of my hand, Commander, and I've set up some long and short-term stretch goals for you. We'll discuss the details later when we have the time♪",
	touch2 = "Wow, don't you think this is a horrible way of relieving stress? ...I'm kidding! Go on, keep at it!",
	mission = "Commander, a new mission list has arrived. Allow me, your professional consultant, to provide you with some reasonable solutions!",
	vote = "",
	drop_descrip = "Type 1934A destroyer – Z13.",
	feeling4 = "Speaking as your personal consultant, you ought to put your work down for a moment and do some relaxing activities with me. I know you doubt me, but don't give me that look! This is for YOUR sake! Now come on, let's start with a warm hug! How about it?",
	lose = "Defeat? No, no, no – it's called showing them your weakness to then catch them off guard!",
	feeling1 = "*sigh*... Not even you can keep up with the groundbreaking genius of my strategic mind...",
	skill = "Target elimination! Suppressive fire!",
	upgrade = "More or less the same as in my combat simulations. Heehee.",
	propose = "I've been doing a lot of research into the psychology of love, and I think you made the optimum choice by going for me. How can I prove it? Well, right now, I can't! That's because all the love hormones are flooding my head with thoughts of you! Heehee♡",
	feeling5 = "Commander, have you heard of the \"palpitation syndrome\" that's been all the buzz lately? It apparently makes you way more productive. Wanna try it? You put your hand here, like this... Did you feel my palpitations? Hm? Aww, you can be so cute! Let me guess... you feel the same excitement as I do, don't you?",
	main = "Are you drafting the next operation? I think we should start by researching the enemy's psychology... How do we do that, you ask? Ah, well... it's a long-term commitment...|Hey, you, the workaholic! Eat some fruit. It's got vitamins that help soothe your nerves, and it's already washed. Come on, open wide!|I conducted some detailed research on the market's seasonal prices and bought this fluffy accessory! I love it! You can hug it to sleep whenever you want! I recommend it if you want to do just that!",
	touch = "Here's an easy stress relief trick you can do in your office! Start by taking six and a half deep breaths, then... What? How to take half a breath? That's the important part of this trick! Come on, do it with me!",
	voice_key_2 = -1,
	mission_complete = "Mission complete! Exemplary work, Commander. Why don't we wind down by playing a game? ...You think I play games too much? Tsk-tsk-tsk, you're clearly not in the know. Games are an excellent way of relieving stress!",
	battle = "We're going in fast! Focus on their core! Go!",
	id = 401130,
	gift_dislike = "",
	gift_prefer = "I really like this! Commander, did you run a funnel analysis on me?",
	profile = "Iron Blood destroyer Z13, cross-sector consultant, at your service. I offer professional solutions for everything you can think of, from port construction to combat deployments.",
	voice_key = 40113,
	headtouch = "Nice sunglasses, aren't they? They're optimized with funnel analysis!",
	feeling2 = "Commander, make me your development advisor! We'll start by expanding into maritime tourism, leisure industries, and niche food industries. Within three years, I'll turn the port into the world's biggest corporation!",
	login = "I think we should remodel your office using my expertise, heehee. Based on the latest studies on residential environments, I suggest you move your desk 3.5 degrees to the southeast for improved productivity.",
	detail = "Interesting. So this is what they mean by attrition warfare... Ah, it's you, Commander. I was just watching a military TV show. We consultants need to stay up to date on the latest tactics to give innovative advice, you see!",
	couple_encourage = {
		{
			{
				40109
			},
			1,
			" Don't cry now! Wanna talk about it?",
			0
		},
		{
			{
				40116
			},
			1,
			" The plan is... Hey, don't go rushing in!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[401131] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Commander, efficiency matters even when conducting inspections. I've come up with some plans for you and divided the office into four sections and... What? You're not here to watch? So... are you here to see me, then?",
	unlock = "...Yes, I know I'm on the clock, but taking productive breaks helps raise your working efficiency afterward! You should take one, too – come sit and kill time wi– Ahem! I mean, come sit and have a break with me!",
	touch2 = "My cubicle is in a bit of a blind spot, so we can get up to anything we want and nobody will ever know!",
	mission = "",
	vote = "",
	drop_descrip = "...Yes, I know I'm on the clock, but taking productive breaks helps raise your working efficiency afterward! You should take one, too – come sit and kill time wi– Ahem! I mean, come sit and have a break with me!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Hey, Commander! Heehee – you know, we're having drinks and watching a stream – isn't this basically a date? ...What? No, 'cause we're on the clock? Well, we're on a date in secret, then! Doesn't the notion of a secret office romance make your heart race? Heheh.",
	main = "According to the latest research, wearing matching clothes – uniforms, maid outfits, et cetera – sharply increases team synergy! How about we make it a port-wide thing? You, of course, can wear whatever you want.|Do you like this color? I can strategically change my clothes if you're not a fan, but if you are... want me to paint some hearts on your nails, too?|Come on, Commander, you of all people should know how important a work-life balance is! Take a seat already and... Oh, no vacant seats? Alright, then why don't you just take mine and I'll get real comfy on your lap?",
	touch = "You asking to borrow my ID card? Sure thing, although I can't use my hands right now since I'm waiting for my nail polish to dry. Just go ahead and take it by yourself♪",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 401131,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Wear a sleep mask and experience what it's like to have my vision blocked? Sounds interesting. Heehee!",
	feeling2 = "",
	login = "Hm? You here to watch me work? I'm not slacking on the job! This is what's called a strategic break period!",
	detail = "That Long Island, I swear... It's like she doesn't grasp the importance of holding on to areas. I would fire a barrage of advice her way, but getting up would be such a pain... I know! I'll type out a message with my feet!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[401140] = {
	hp_warning = "Urk... I-I don't know if I can take much more...",
	feeling3 = "(The Commander is always so nice to me, accepting me despite all my flaws... How am I ever supposed to repay that kindness?)",
	mail = "C-Commander, you have new mail... Oh, wait. First, I'd better make sure there's nothing wrong with it...",
	expedition = "Commander... I think the commission team is back... Huh? We're going to see them? As in, I have to go, too?!",
	win_mvp = "The enemy's plan was easy to read... Almost too easy. Wait, is this a trap?!",
	home = "(The Commander just yawned... Are you working overtime again? Did I make trouble by not doing enough on my own?! Ah... I-I can't bring myself to ask...)",
	unlock = "C-Commander... I'm Z14, an Iron Blood destroyer... *rumble* Oh! Th-this here is Little Ihn... She can't speak, but she's really smart...",
	touch2 = "Eep?! Wh-what's going on? A-are you doing something weird to me?!",
	mission = "C-Commander, you still have missions to do... Umm, if we combine the two of these, I think our efficiency would go way up...",
	vote = "",
	drop_descrip = "Type 1934A destroyer – Z14.",
	feeling4 = "When I'm with you, I feel more relaxed than ever... It's a strange, but special feeling. I want to be even closer...",
	lose = "*sob*... Commander... L-Little Ihn is still screaming...",
	feeling1 = "Eep?! C-Commander...",
	skill = "Little Iiihn!",
	upgrade = "Is it just me, or is my brain working better, too...?",
	propose = "A-am I dreaming right now? Would someone like you... really fall for someone like me? B-but I've always secretly hoped that this would happen. Ooh... I'm so happy that I... I don't even know what I'm saying anymore... *sob*",
	feeling5 = "I can sleep next to you whenever I'm tired? Wait... You'll even hold me?! I-in that case... could you hold me right now? Hyah! C-Commander... I love you... Zzzz...",
	main = "Someone asked me directions earlier, but I overthought it so much that I couldn't give them a good answer... Little Ihn had to show them the way. If only I could give her a speech module...|A riddle contest? Oh... Yeah, I did win one of those recently. All I did was write down my logical analysis and conclusions for each scenario based on the possibilities...|C-Commander... May I join the physical training today? Um... If I push myself to my limit, it's really easy to fall asleep...",
	touch = "Y-you wanna try petting Little Ihn? I think she's taken a liking to you...",
	voice_key_2 = -1,
	mission_complete = "W-we finished all of those missions... We didn't miss any, right? There aren't any hidden objectives, or...?",
	battle = "E-everyone... Fight according to the plan, please...",
	id = 401140,
	gift_dislike = "",
	gift_prefer = "Huh? F-for me...? Thank you, Commander...",
	profile = "G-good morning, Commander... I'm Z14, a Type 1934A-class destroyer under the Iron Blood... I'm good at things like rapidly memorizing information and decoding ciphers, but... I'm not super great at physical activities.",
	voice_key = 40114,
	headtouch = "Aah?! Commander... Mm, that feels nice... Very relaxing... Zzzz.",
	feeling2 = "Hyah?! S-sorry, I didn't mean to do that... I-I slept so poorly last night, and... Huh? I can sleep in your office? Like... now?",
	login = "Hyah?! *rumble*... C-Commander, how long have you been here... C-close your mouth, Little Ihn! No growling at the Commander!",
	detail = "Every night, I think of all kinds of things... I start to dwell on things, and I overanalyze, and I can't fall asleep... Before I know it, it's morning already.",
	couple_encourage = {
