	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "As long as you're here, I won't be scared! E-even if those seagulls come begging for food again... I'll say no this time!",
	unlock = "Eep... I-I don't have any more food... Leave me alone already, please! C-Commander, help... I'm lost, and these birds won't listen to me!",
