	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Warm sunlight, a nice breeze... When you're not here, I never notice these things. Commander... May I continue to stay by your side?",
	main = "I-I'm still embarrassed walking around in this swimsuit, so... I tried taking a shortcut to our meeting spot, but then I got lost... *sob*|At first, there were only two seagulls... I thought they were hungry, so I shared some of my bread, and then... And then...|Umm... I wanted to use these sunglasses as a disguise... Huh? You can still tell it's me?!",
	touch = "Ah?! Wh-whoooa?! Y-you're bridal carrying me?! Being rescued like this is just... Aaah!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 401141,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "*sob*... Thank you, Commander... C-can you console me a little longer?",
	feeling2 = "",
	login = "C-Commander, where are you...? Oh, Commander... Is that really you?! I'm not dreaming? Thank goodness...",
	detail = "C-Commander... I'm sorry! I picked out a swimsuit and practiced my best smile for you, but you ended up having to save me... Th-thank you so much!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[401150] = {
	hp_warning = "M-my boiler's water supply pipe is failing!",
	feeling3 = "It's really pouring outside... I guess we'll just have to hang out alone in your office... Hmm? You have an umbrella, and you'll walk me home? W-wait... Why'd you get so close?!",
	mail = "Commander, your mail's right heeere♪ Go ahead and take it. Just be careful you don't touch anything else... Hehe!",
	expedition = "Oh, the commission team is almost back... I guess we won't be alone much longer. Too bad... I'm sure neither of us has had our fill yet~",
	win_mvp = "Don't you think top performers like me deserve a little reward?",
	home = "Oh hey, you're back! Hmm? Why am I stuck like this? Well, my ride broke down again... Help me out, please!",
	unlock = "I'm Z15 – a destroyer from the Iron Blood. Just looking at you makes my heart race... Hehe, how about we go somewhere together? We've got so much more to discuss~",
	touch2 = "C-Commander, what's gotten into... Hyah?! I-I'm heating up... My boiler might explode...",
	mission = "Commander, your work isn't done yet. Hurry up and finish it so we can do something more fun!",
	vote = "",
	drop_descrip = "Type 1934A destroyer – Z15.",
	feeling4 = "Um, so... Commander, I think I... Come on, you know what I'm trying to say... Ugh, how can it be so hard to say three little words?",
	lose = "Ugh, I can't move... Why'd it break down all of a sudden?!",
	feeling1 = "If you keep hiding from me, I'm going to lose my patience with you, Commander!",
	skill = "Hot, isn't it?!",
	upgrade = "My power is overflowing~",
	propose = "Haha... Wow, what a good dream that was. The Commander's face, the feeling of that ring... Wait, that wasn't a dream?! Oh, man... Wh-what am I even supposed to say?!",
	feeling5 = "Commander... Do you think love feels like having broken brakes? Like, I know I REALLY need to stop... but I can't stop the urge to crash into you!",
	main = "You'll fix my ride for me? You're totally saying that so you can go home with me, right? I can tell... Huh? Wait, you're actually bringing a toolbox?|You wanna talk in more detail about this tomorrow? Sure~ I mean, we could go really in-depth right now, if you waaanted...|When you're off work, how about you ride home with me? Don't worry – nothing will go wrong this time! I'll take you on my bicycle, so there's no danger at all!",
	touch = "Pure, innocent girls like me have nooo idea what's going on in that head of yours~",
	voice_key_2 = -1,
	mission_complete = "Your rewards are here~ But doesn't it leave you wanting a better reward, maybe from... me? Hahaha, did I guess right?",
	battle = "Get ready to be wowed!",
	id = 401150,
	gift_dislike = "",
	gift_prefer = "You gave me such a nice gift... I'd better find a way to thank you♪",
	profile = "I'm the Iron Blood destroyer Z15. I don't know why, but my ride tends to malfunction a lot... If you don't want me to be in danger, you'd better keep those eyes on me!",
	voice_key = 40115,
	headtouch = "Petting?! If you're doing that... then you'd better be ready to take responsibility!",
	feeling2 = "Feel free to order me to do anything~ Even the most ridiculous request... I'm ready to please♥",
	login = "Aw, you finally came to see me! I await your orders. No matter what you want, I'll do it. Oh... Paperwork, huh?",
	detail = "You've been staring at me for a while... Are you having naughty thoughts? I'm gonna report you... Hahaha, just kidding! I welcome your gaze, Commander~",
	couple_encourage = {
		{
			{
				40114
			},
			1,
			" Don't be scared, don't be scared~ I'm not a baddie~",
			0
		}
	}
}


_G.pg.base.ship_skin_words[401151] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Commander, get in here and play with me! Hehe, once you're inside, I'm never letting you go~ It'll be so much fun to roll around together!",
	unlock = "Commandeeer! I finally made it to you. Seems like there's something wrong with the exit of this ball... Anyway, I'm stuck in here. Can you help me out?",
	touch2 = "Commander~ Feel how bouncy it is when you touch? I can feel your warmth through it, too.",
	mission = "",
