_G.pg.base.ship_skin_words[401180] = {
	hp_warning = "This might not be so good...",
	feeling3 = "A smile is always good, but when cruelty makes someone smile... it's kind of creepy...",
	mail = "Commander, mail for you~ But first, give me a smile~",
	expedition = "The commission team's done~ Shouldn't you go greet them?",
	win_mvp = "Gimme a smile, everyone~",
	home = "Nice work~! Replenish your energy with these snacks and my smile~",
	unlock = "Nice to meet you, I'm Z18! I'm the girl whose smile will reach everyone's hearts~",
	touch2 = "You can't do whatever you want just because I'm smiling! Hmph!",
	mission = "Commander, there's a new mission! Let's get to it~!",
	vote = "",
	drop_descrip = "Type 1936 destroyer – Z18 Hans Lüdemann.",
	feeling4 = "Has my smile reached your heart, Commander? My smile belongs to everyone, but I can smile a little more just for you~",
	lose = "I'll always smile, even when defeated~!",
	feeling1 = "It doesn't look like my smile will reach your heart, Commander...",
	skill = "My smile will reach even the enemy!",
	upgrade = "Now my smile can reach the hearts of more people!",
	propose = "There's no higher praise for my smile than this~ Ehehe, just like always, I will smile for everyone in the fleet, and for you too, Commander!",
	feeling5 = "Your smile has reached MY heart, Commander! It makes me feel so warm and happy!",
	main = "Everyone from Iron Blood are either obsessed with war or say a bunch of stuff that doesn't make sense... and my mission is to make them all smile!|I prescribe a smile to anyone who's feeling afraid~|I believe that, deep down, there's a smile in everyone's hearts! Anyone can smile once they know that!",
	touch = "Do you need anything from me?",
	voice_key_2 = -1,
	mission_complete = "Way to go, Commander! We got so many rewards from that~",
	battle = "I'm rooting for you, everyone!",
	id = 401180,
	gift_dislike = "",
	gift_prefer = "Wow, I've always wanted this! Thank you!",
	profile = "I'm the second Type 1936 destroyer, Z18~! You can call me Hans, although it sounds a little boyish... Hm? I'm really different from other Iron Blood girls? Heheh, a smile makes all the difference~",
	voice_key = 40118,
	headtouch = "",
	feeling2 = "People feel sad and anxious when they lose, right? That's why I'll be there to cheer them up!",
	login = "Welcome back, Commander~ Have you smiled yet today?",
	detail = "Okay, Commander! Let's see aaaa... SMILE!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[401190] = {
	hp_warning = "",
	feeling3 = "Commander, if I get MVP in the next battle, would you take me to a water park on your next day off?",
	mail = "There's new mail, Commander. Surely there's a commendation from the higher-ups!",
	expedition = "Is it finally time for you to play with me?",
	win_mvp = "Z23! This time, I got a perfect score!",
	home = "Could you play with me for a while, Commander? Oh.. you're tired? I guess rest is pretty important too...",
	unlock = "Z19 Hermann Künne, reporting for duty! Commander, I'm prepared to fight until the very end!",
	touch2 = "Please don't pick me up... I'm way too old for that...",
	mission = "Ah, it's already time to get back to work. Commander, let's go complete some missions.",
	vote = "",
	drop_descrip = "Type 1936 destroyer – Z19 Hermann Künne.",
	feeling4 = "Commander, as long as I can see you, my mind is at ease even if you aren't doing anything in particular. Is this what it means to be reliant?",
	lose = "Ugh... Mission... failed. Commander, I'm terribly sorry.",
	feeling1 = "Zero points for you, Commander!",
	skill = "This is the result of all my hard work!",
	upgrade = "Am I one step closer to being an adult?",
	propose = "Can I really have this? Thank you very much... I'll do my best to be a worthy partner!",
	feeling5 = "*yawns* Commander, why haven't you gone back to your room yet? You're sorry for waking me up? No, it's okay... but I only have this single bed here... You want to measure my finger size? Why not turn on the lights... Fuehhh?!",
	main = "I must be more strict with myself now that I'm your secretary.|Commander, if you're free, would you like to play with me?|Commander, I prepared some watermelon for you. Open your mouth~ aah~",
	touch = "Commander, your orders?",
	voice_key_2 = -1,
	mission_complete = "Commander, the missions were done perfectly this time! Full marks!",
	battle = "All ships, at the ready! Aim for the enemy fleet ahead! Feuer!",
	id = 401190,
	gift_dislike = "",
	gift_prefer = "This present gets a full 100 points!",
	profile = "I am the Iron Blood Navy's Z-class 1936-Type destroyer, Hermann Künne. I participated in Operation Weserübung, and met my end during the fierce engagements at Narvik. Things will be different this time around!",
	voice_key = 40119,
	headtouch = "",
	feeling2 = "No matter what skill you have, I'm sure there's a place for it.",
	login = "Commander, skipping breakfast is bad for your body. I've prepared some cereal and toast for you; if you don't mind, would you like to eat together?",
	detail = "Any inquiries, Commander?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[401200] = {
	hp_warning = "",
	feeling3 = "What's wrong? Something bugging you? I promise you'll feel better if we go run a marathon together!",
	mail = "A letter for you, eh? I don't think I should be the one to open your mail.",
	expedition = "Ah, our friends have returned! Let's go welcome them back!",
	win_mvp = "Hahaa! Piece of cake!",
	home = "Good job! Let's go find some place to relax.",
	unlock = "Z20, Karl Galster, reporting in! Where's my welcoming party?",
	touch2 = "Hehe, how do you like my curves?",
	mission = "Let's prepare for the celebrations before we start~",
	vote = "",
	drop_descrip = "Type 1936 destroyer – Z20 Karl Galster.",
	feeling4 = "If you never tell others how you feel about them, they'll never understand. You get that, right?",
	lose = "Oof... even I mess up sometimes... just sometimes~",
	feeling1 = "The moment I saw you, all the fatigue from running kicked in at once. I'm out, time to rest!",
	skill = "Gotta smile during battle as well!",
	upgrade = "Ahaha, I'm feeling even better!",
	propose = "Say, I heard there's a tradition in the East where couples will drink with their arms intertwined. Haha, come on, Commander! Don't be shy!",
	feeling5 = "You idiot... All right, stop blushing and stammering. I like you. So, do you feel the same way about me?",
	main = "Commander, let me teach you the right way to breathe while running. It's good for both attacking and retreating!|As long as I'm in a good mood, I can enjoy any scenery!|Protschny? Don't call me by that name!",
	touch = "Hmm? You want to go on a run with me?",
	voice_key_2 = -1,
	mission_complete = "Marathon, marathon! I'll definitely take first place this time.",
	battle = "I'm the flagship? Fine by me! Everyone, follow me!",
	id = 401200,
	gift_dislike = "",
	gift_prefer = "Ahaha, you sure picked out something nice!",
	profile = "I am Z20 Karl Galster, Iron Blood Z-class 1936-Type destroyer, the sole survivor of the Z17 type destroyers. After being handed over to the Northern Parliament, I was renamed \"прочный.\" Being separated from my sisters and living alone sure was rough...",
	voice_key = 40120,
	headtouch = "",
	feeling2 = "As long as you keep running, you'll leave behind all your hardship and anxiety. Commander, come find me any time you're feeling down.",
	login = "Commander, up for a jog?",
	detail = "I'll make all your concerns go \"poof!\" How's that, Commander? Feel better?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[401210] = {
	hp_warning = "",
	feeling3 = "What kind of stuff do I like? Why should I tell you? Well, I guess those macaroons we had yesterday were pretty good.",
	mail = "There's mail for... help you open it? I... I guess I can do that, reluctantly of course...",
	expedition = "Good work, everyone! Except the one who's always goofing off in port... *ahem*",
	win_mvp = "Well, I suppose you did contribute a little bit...",
	home = "G-good work. Hmph!",
	unlock = "I am Z21, the Z-class destroyer flagship in the Battles of Narvik, Wilheim Heidkamp! Since you worked so hard to find me, I suppose I'll have to follow you home.",
	touch2 = "Ah! What... what are you doing? One more time and I'll really get mad!",
	mission = "You're still not going to work? ...You prefer staying with me? You... you're doing this on purpose, aren't you?",
	vote = "",
	drop_descrip = "Type 1936 destroyer – Z21 Wilheim Heidkamp.",
	feeling4 = "I'm not following you! We just happened to be going in the same direction! Where am I going...? Why... why should I tell you?!",
	lose = "Ugh... I... I'll remember this!",
	feeling1 = "I'm having a bad day... Just stay away from me!",
	skill = "Combat will be no problem, as long as we put in a little effort.",
	upgrade = "Thanks... for nothing! I didn't say anything!",
	propose = "Since you're being so sincere, I'll... accept... reluctantly! But that doesn't... it doesn't mean that I've agreed to anything yet... Ah, alright, don't leave. Yes, I agree!",
	feeling5 = "Is there anything you'd like to tell me, Commander? Eh... nothing? I-i-idiot!",
	main = "You should be more careful if you want me to be your flagship... Don't misunderstand, I'm not actually worried about you.|I'm staying beside you, but only because its my duty as secretary ship!|If you're really tired, I suppose you could rest on my lap for a while...",
	touch = "Didn't we agree that you'd give me a heads up before poking me?",
	voice_key_2 = -1,
	mission_complete = "I-I suppose you deserve a little bit of praise... but only for your hard work.",
	battle = "Come on everyone, let's give it our all!",
	id = 401210,
	gift_dislike = "",
	gift_prefer = "Like this would be enough to make me happy! ...(whispers) I guess it makes me a little happy...",
	profile = "I am Z21, Iron Blood Navy Z-class 1936-Type destroyer. I was the flagship during Operation Weserübung, but was sunk by HMS Courageous. I won't lose next time!",
	voice_key = 40121,
	headtouch = "",
	feeling2 = "I'll fight to protect my sisters... Not you!",
	login = "Commander, you're back! Eh...? It's... it's not like I actually care!",
	detail = "Is there something on my face? Stop staring at me!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[401230] = {
	hp_warning = "I've got to find a way out of this mess...",
	feeling3 = "You’re a bit tired? Very well, getting rest is important. You want a lap pillow? I guess it’s fine... just for a little while...",
	mail = "There’s mail for you, Commander. You sure are popular.",
	expedition = "It’s about time! Please put aside your work, and check on the results of your commissions.",
	win_mvp = "Battles are like exams. Earning MVP is like getting the top score on a test.",
	home = "We still have so much to review about the previous battle...",
	unlock = "Guten Tag, Commander.\nI am Z23. Let’s study hard together and aim for the top!",
	touch2 = "This isn’t something a commander should be doing...",
	mission = "Completing missions is a great way to hone your skills. Don't ever forget that!",
	vote = "",
	drop_descrip = "Type 1936A \"Narvik-class\" destroyer – Z23.",
	feeling4 = "Commander, why are you staring at me? You think I’m pretty when I look serious? I-idiot! Go do your own work...",
	lose = "*sobs* ... No, I mustn’t cry...",
	feeling1 = "Commander, can you not bother me when I’m trying to study?",
	skill = "Take this!",
	upgrade = "Commander, I hope that we'll improve, together!",
	propose = "This is the proof that Commander acknowledges me... Understood. From now on, I shall stay by your side and work hard to ensure that your life is happy and upstanding.",
	feeling5 = "Commander, did you know that the higher you stand, the further you can see, but also the lonelier you will be? I hope that you can rise to great heights one day, but still be as happy then as you are now.",
	main = "Don’t worry, Commander. The fact that you care about me is enough.|I wonder if there’s something I can do for you, Commander. You seem tired lately, so maybe a massage would be good?|See, Commander? You can do it if you set your mind to it!|Huh? What am I in charge of? A-ahaha... I, uh... forgot...|Headpat? You mean like this...?",
	touch = "If you’re free, why not help with some paperwork?",
	voice_key_2 = -1,
	mission_complete = "Commander, the mission rewards have arrived.",
	battle = "Let’s go! It’s time to reap the rewards of our hard work!",
	id = 401230,
	gift_dislike = "",
	gift_prefer = "Thank you very much! *sigh*...If only you could apply yourself to your studies the same way...",
	profile = "I’m Z23, the eldest sister of the 1936A-class destroyers. Unlike my sisters before me, who all had a namesake, my younger sisters and I only had a serial code for our names. It might be a little cold and impersonal, but I believe it’s also more convenient. So please, feel free to call me Z23.",
	voice_key = 40123,
	headtouch = "I’m not the kind of girl who you can fool with just a few headpats. Get back to work, Commander.",
	feeling2 = "Studying is important! A wise man once said, \"knowledge is power.\" ... France is bacon? Jeez... just what is going through that head of yours?",
	login = "There's still quite a lot to be done today. No procrastinating!",
	detail = "If you have the time to stare at me, shouldn’t you go back to your studies? Even I... can get embarrassed...",
	couple_encourage = {
		{
			{
				40125
			},
			1,
			"Z25, let's do our best together!",
			0
		}
	}
}


