_G.pg.base.ship_skin_words[401234] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Look how many invitations you've gotten, Commander. Aren't you popular? Hehehe.",
	expedition = "",
	win_mvp = "I'm doing splendidly today.",
	home = "Commander, you don't mind if I cut a bit loose today, do you?",
	unlock = "Oh, good evening, Commander. I was just looking for Javelin and the others... Say, would you like to keep me company for a bit?",
	touch2 = "",
	mission = "Just for today, Commander, I don't mind you putting off your missions for a while.",
	vote = "",
	drop_descrip = "Oh, good evening, Commander. I was just looking for Javelin and the others... Say, would you like to keep me company for a bit?",
	feeling4 = "",
	lose = "What can I do? ... I don't want to get my dress dirty.",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Erm, well, Commander! I don't usually think about things like this but, you know, tonight, I'm wondering, Commander, when I'm all dressed up like this, do you think I'm... well... pretty?",
	main = "When I see everyone's smiling faces, I can't help but think about all the hard work that got us here. How about you, Commander?|The four of us: Laffey, Javelin, Ayanami, and I... Who would have thought we'd all become such good friends?|Champagne? Oh, heavens no, Commander! This is just sparkling orange juice.",
	touch = "D-D-Dance?! ... Oh my, I never thought it might come to this... Commander, can you teach me how to do it...?",
	voice_key_2 = -1,
	mission_complete = "This is... exactly what I'd expect from my Commander.",
	battle = "",
	id = 401234,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Are you enjoying the party, Commander?",
	detail = "I've been smiling a lot more lately? ... Well, that's because you've gotten so much more respectable.",
	couple_encourage = {}
}


