_G.pg.base.ship_skin_words[401236] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Commander, seeing you work so hard like this makes me realize, I can't slack off either!",
	unlock = "Jeez... Javelin's got what it takes, but I'm really concerned about Laffey and Ayanami. Oh well, I guess it's up to me to manage them... Commander, please don't forget to support me too.",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "Jeez... Javelin's got what it takes, but I'm really concerned about Laffey and Ayanami. Oh well, I guess it's up to me to manage them... Commander, please don't forget to support me too.",
	feeling4 = "",
	lose = "Phew... I'll have to work even harder.",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "I just remembered, Laffey has an audition today... so where is she?! ...Gaaaah!! Sorry, I have something to attend to!|...Recently, more and more girls have been asking me to become their manager. Jeez, I have my own idol activities to take care of!|Commander, I have no objections to your laissez-faire approach towards management, but don't lose sight of our responsibilities. |Commander, I'm heading off to lessons, so don't forget to finish your missions!",
	touch = "Commander, which area should I improve on next?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Whether as an idol or as a warship, I'll be the best I can be!",
	id = 401236,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "If you're going to do something, you've got to do it right! I'm aiming for the top!",
	detail = "I don't mind balancing my work as both a manager and as an idol. As a matter of fact, I think I might actually be well suited to it.",
	couple_encourage = {}
}


