_G.pg.base.ship_skin_words[401238] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Instructor, how many points did my combat performance score? ...Heheh, just kidding~",
	home = "Mm... there really was a lot to consider on that last operation... but most importantly, I'm glad you're safe, Commander.",
	unlock = "Whew... Sorry to keep you waiting. I was having a hard time deciding which outfit to wear... Ah, um... how do I look? ",
	touch2 = "Wait, if you're going to do this kind of stuff, at least save it for after work! Even if I like... I mean, err, d-disregard what I just said!",
	mission = "",
	vote = "",
	drop_descrip = "Whew... Sorry to keep you waiting. I was having a hard time deciding which outfit to wear... Ah, um... how do I look? ",
	feeling4 = "",
	lose = "I-I'm all right... but I'll have to train more after we get back...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Commander, no matter what destination you're aiming for, I'll be with you every step of the way, whether you're at the summit or just setting out, through both joys and disappointments. Mhm, you'll never be alone again, I swear it.",
	main = "Commander, I'll be here reading, so just call my name if something happens. I have to study hard so that I can keep up with you!|You look so cool and hardworking like that... Uh, ahem! Disregard that! A-anyway, would you like a light snack?|How to help the Commander work more efficiently and comfortably... Hmm, it'll be quite the challenge, but well worth it!",
	touch = "Yes, yes, I know I look cute in this outfit, so hurry up and get back to work! Jeez, what am I to do with you, Commander...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 401238,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, did you make sure to eat the meal I made for you? Mmhmm, good, good~",
	detail = "Commander, I can't concentrate on my reading if you're staring at me like that! Gosh...",
	couple_encourage = {}
}


