_G.pg.base.ship_skin_words[401240] = {
	hp_warning = "Can I destroy everything yet...?!",
	feeling3 = "Nothing in existence can stand before me without succumbing to abject terror... or so I thought. Why aren't you afraid of me!",
	mail = "Insight from the Abyss itself... Guhuhu...",
	expedition = "Commission rewards? I have no interest in mortal trinkets... But oh! If there's any black chocolate or black forest cake, you must bring it to me, mortal!",
	win_mvp = "Ahahahaha! Fresh blood and steel, blossom into magnificent fireworks!",
	home = "It's about damn time, human. Tired, so I'm gonna rest. Don't bother me unless it's urgent, or you have dark chocolate.",
	unlock = "Tremble, mortal! Before you is the Fiend of the Crimson Darkness, the Avatar of Fear, the Iron Blood destroyer, Z24! All you need to do is grovel at my feet!",
	touch2 = "Surely you already know the fate of those who dare to disrespect me? Foolish mortal...",
	mission = "Missions? Hurry up and get those unsightly things out of my sight, mortal.",
	vote = "",
	drop_descrip = "Type 1936A \"Narvik-class\" destroyer – Z24.",
	feeling4 = "Are you offering this black forest cake to me? Ehe... Ehehehe... Very well, human. Here, ahhhn... What are you spacing out for? Hurry up and feed me already!",
	lose = "*pant*... *pant*... I don't have to hold back anymore, right? I'll destroy everything... every last bit of it...!!!",
	feeling1 = "Do you know the fate of mortals who have fallen to such depths of depravity?",
	skill = "Kneel before me! Ahahaha!",
	upgrade = "Not bad, human scum! My power grows ever greater!",
	propose = "You seek to form a contract with me, mortal? Ehehehe... very well! I shall reward you for your bravery! From now on, you shall serve me!",
	feeling5 = "Now that you've learned to fear and respect me, mortal, I shall give you the privilege of forming a physical pact with me! Come! ......Hug! It's a hug! Do I have to spell it for you, you fool?!",
	main = "Black is the mark of my infernal nobility— yes, black coffee, dark chocolate, and black forest cake... are all things within my domain! Surely even human scum such as you recognizes this~♪|Aaaahhhhh... I'm sooooo booooored... Shall I teach the next person who walks through these doors the meaning of true fear? ...No good? Tsk... |The ways of the mortal realm have no bearing upon me! Therefore, Zed, I have no need for this \"homework\" stuff. Oww! F-fine, I get it, so stop chewing me out!|You... forgot to bring the offerings? ...Looks like I will have to teach you about the fragility of human life.",
	touch = "These massive claws suit my status as an Archfiend, both in terms of appearance and destructive power! Ahahaha!",
	voice_key_2 = -1,
	mission_complete = "The time of reaping seems to have come once more. Isn't that right, human~?",
	battle = "Let us begin the festival of blood and iron!",
	id = 401240,
	gift_dislike = "",
	gift_prefer = "Your taste is pretty decent, for a mere mortal. Be grateful for my praise!",
	profile = "After Z23, the 1936-class destroyers no longer were given actual names... Why?! Why can't I have a cool and easy-to-remember name like Lebe or Thiele...?!",
	voice_key = 40124,
	headtouch = "Impudent mortal, how dare you wantonly touch my head... W-wait, don't stop, please~",
	feeling2 = "Hrmm... Those planes circling overhead are like flies... annoying and won't go away... Don't you agree?",
	login = "Do you have any idea what time it is? This is why I can't stand you lazy mortals... Get back to work already!",
	detail = "A mortal that does not tremble before my visage? How strange... I thought I did my best to look absolutely hellish... I wonder why...",
	couple_encourage = {
		{
			{
				40305
			},
			1,
			" Let's tear them to shreds!",
			0
		},
		{
			{
				40125
			},
			1,
			" I look forward to seeing your dark arts!",
			0
		},
		{
			{
				40126
			},
			1,
			"You will no longer face the storms alone!",
			0
		},
		{
			{
				40136
			},
			1,
			"Devil, heed my call and destroy our enemies!",
			0
		},
		{
			{
				40123
			},
			1,
			"H-hey, stop lecturing me!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[401241] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "",
	unlock = "Come, human! The rite of festivities is upon us! Come hither, and let us revel in this foreign holiday together!",
	touch2 = "Th-there are some things you just shouldn't do! I hope you're ready for some punishment, foolish mortal!",
	mission = "",
	vote = "",
	drop_descrip = "Come, human! The rite of festivities is upon us! Come hither, and let us revel in this foreign holiday together!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "I shall reward you with a taste of this black fruit! Open your mouth, foolish mortal!|",
	touch = "Do you want to stay by my side tht badly? Heheh~",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 401241,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Are you all rested up? I'll give you the privilege of keeping me entertained today! Consider this your greatest honor, mortal!",
	detail = "Even off duty, I cannot remove this claw, as it is a symbol of my dignity! ...What do I do if I need to pick something up? Th-that's your job, you foolish mortal!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[401242] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Bow down before my might!",
	home = "Whether on the battlefield or inside the stadium, the fruit of victory is sweet indeed! Even a foolish mortal such as you is privy to that knowledge, right? ♪",
	unlock = "Heh heh... As expected, you couldn't even last for a second! Winning too easily takes all the fun out of it... You, the mortal over there, I'll give you the honor of being my next opponent!",
	touch2 = "I, I did not mean THIS kind of reward...!",
	mission = "",
	vote = "",
	drop_descrip = "Heh heh... As expected, you couldn't even last for a second! Winning too easily takes all the fun out of it... You, the mortal over there, I'll give you the honor of being my next opponent!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Not half bad, for a human. It appears that the time has come to unleash my sealed power––|Picking up balls is beneath someone as exalted as me! ...Oww! Fine, fine, I get it! Stop chewing me out already, Zed!|As a r-reward for defeating me, I shall grant you the privilege of giving me directions for the day! Bask in this glory, foolish mortal!",
	touch = "Heh heh... Excellent!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 401242,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Tell me what plans you have for the day, mortal. I've decided – you shall bear witness to my dominion over this stadium, and burn those memories into your eyes!",
	detail = "When facing human opponents, it would hardly be a fair contest if I didn't convert my claws into bandages... It definitely had nothing to do with me breaking a whole bunch of racquets or anything like that.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[401243] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Ah, the commission rewards... Hmph. What I want is a dark chocolate treat of– There is none? Then you will get me one, mortal! ...I don't care if you buy it from Akashi's store!",
	win_mvp = "I did the tricking. You, mortal, should prepare the treat!",
	home = "Oh, you're back, mortal... Hm? Tired, are you? Very well, I permit you to rest at my mansion. Worry not, the beds are surprisingly snug.",
	unlock = "\"Sing your praises to the Fiend of Crimson Darkness, Z24!\" ... Hmm, maybe I should go with \"Bow down in astonishment!\"... Ah, yes! Mortal, you've come at a most opportune time! Hurry and tell me what you think of my new catchphrase! ...Actually, get me down from here first!",
	touch2 = "Whuh?! Th-there's nothing hidden... I-I-I never said I'd play any tricks!",
	mission = "You can't do this mission yourself, pathetic human? Hmph. Fine, I shall do it my– Grrrr...",
	vote = "",
	drop_descrip = "\"Sing your praises to the Fiend of Crimson Darkness, Z24!\" ... Hmm, maybe I should go with \"Bow down in astonishment!\"... Ah, yes! Mortal, you've come at a most opportune time! Hurry and tell me what you think of my new catchphrase! ...Actually, get me down from here first!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Give me tribute if you don't want to get cursed! As for what that entails... I desire whipped cream or a chocolate cream cake!|Dammit, this binding spell holds the Force of my retainers who sleep in the abyss... Never mind. I should avoid using the term \"Force\"...|(If I had my claws, the Commander would point out I could break free on my own... Anyway, it's fine like this! Just need to wait for the mortal to get close before I perform my trick...)",
	touch = "Human, would you have preferred a more witchy design? ...N-no, I'm absolutely not asking about your personal tastes! *blushes*",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 401243,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Behold, mortal! I got this special costume and these ornaments just for this day! The black and red are befitting of the night of demons... What do you mean I \"hardly look different\"?!",
	detail = "Come the night of a thousand demons, the ashen red queen shall rise from the underworld! She will lead an army of lost souls and bring chaos to the world! ...That's the idea, anyway. Well? Do you think it's cool?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[401250] = {
	hp_warning = "I can hang on a bit longer...",
	feeling3 = "Now, all my peers see me as being dedicated and responsible, and want to sortie or go on commissions with me. Commander also feels more at ease when I am around. Mr. Anchor, I've managed to make it!",
	mail = "New mail has arrived... it would be unfortunate if you glossed over something important!",
	expedition = "The commission team is already waiting at the harbor. Shall I welcome them back?",
	win_mvp = "Not bad, let's keep this same tempo going!",
	home = "Good work, everyone. Let's use this time to also check the status of all the equipment.",
	unlock = "Type 1936A destroyer Z25, reporting in. Please be at ease, I shall do my utmost in battle.",
	touch2 = "Oooh! ...If that was on purpose, you'd better grit your teeth!",
	mission = "Don't procrastinate on your missions. Hurry up and get them taken care of!",
	vote = "",
	drop_descrip = "Type 1936A \"Narvik-class\" destroyer – Z25",
	feeling4 = "Recently, I've become more and more conscious of the commander. When we are together, I simply can't seem to calm down. Mr. Anchor... what should I do...?",
	lose = "This battle... I'll have to reflect upon it thoroughly...",
	feeling1 = "Mr. Anchor... I don't want to be here anymore...",
	skill = "Target acquired!",
	upgrade = "Becoming stronger... should allow me to get a little closer to Z23.",
	propose = "So, you heard everything that I said to Mr. Anchor.... Ughh, I'm such an idiot! However, I'm really happy that you chose to give this to me. Th-there's no going back on this!",
	feeling5 = "Ehehe... Haah, it's still no good. Mr. Anchor, sorry for making you act like the commander and practice with me for so long. I give up... just being like this should be good enough... Eh... w-wait... Commander?",
	main = "Z23... is probably engrossed in her studies right now... |Research plans... commission schedule... Ugh... this is no time to be getting sleepy... |This thing here? He- it's really just an ordinary toy!",
	touch = "Zzz.... woah! Sorry, I shouldn't have been daydreaming...",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Well? What are your next plans?",
	battle = "Z25, currently searching for enemy ships!",
	id = 401250,
	gift_dislike = "",
	gift_prefer = "I, I guess I'll take it!",
	profile = "From my sister Z23 forth, we were all assigned code names. However, no matter what I am called or where I am deployed, I shall fulfill my duties!",
	voice_key = 40125,
	headtouch = "",
	feeling2 = "Even though I told the commander not to worry, I still worry that I won't be able to meet expectations or adapt to this new environment. Mr. Anchor, will I be able to perform well?",
	login = "You're right on time. Well then, I should also get fired up.",
	detail = "Mr. Anchor, what must I do to become as outstanding as my sister...?",
	couple_encourage = {
		{
			{
				40123
			},
			1,
			"Sis, let's do our best together!",
			0
		}
	}
}


