_G.pg.base.ship_skin_words[401260] = {
	hp_warning = "I wonder where Z25 and the others went...",
	feeling3 = "Commander, you did a great job, like always! Continue to do your best tomorrow as well! ...You can tell that I'm complimenting you right now, no?",
	mail = "Here's the latest intel! Please give it a look, Commander!",
	expedition = "The commission team is back! They've really done it this time... Nono, I mean, they've done a good job!",
	win_mvp = "Continue making your best endeavors! ...Um, I mean, well done, everyone!",
	home = "Commander, here's some coffee! ...S-sugar? Hmm... I wonder if 10 cubes will be enough...",
	unlock = "I'm the Iron Blood destroyer, Z26! I look forward to working with you! ...All right, that should do just fine as an introduction...!",
	touch2 = "No lewdness allowed! Ever! Full stop!",
	mission = "New damn missions have co– Err, I mean! Commander, please hurry up and check out the new missions!",
	vote = "",
	drop_descrip = "Type 1936A \"Narvik-class\" destroyer – Z26.",
	feeling4 = "Maintaining a good work-life balance is very important! That's why I'll be watching you on your days off to make sure you don't do any work! This is me telling you to get enough rest.",
	lose = "We ended up losing... I'm really sorry, everyone!",
	feeling1 = "Commander, you're a failure!",
	skill = "I'm all ready to go!",
	upgrade = "I'm very grabbed! ...No, I mean, I'm very grateful!",
	propose = "\"I take you, to have and to hold, from this day forward, for better, for worse, for richer, for poorer, in sickness and in health, until death do us part.\" ...I was able to recite it from memory! Now it's your turn... right?",
	feeling5 = "Commander! I was observing your work, and it looks like you can do just fine without my supervision! What a good job you've done. You're stellar! I'm very proud of you.",
	main = "Commander, slacking off is absolutely prohibited! ...You've already finished your work? I-in that case... Well done!|Zed's good at studying, and Lebe's good at sports... so I should aim to... study while playing sports? W-will I manage?|I wonder if Z25's Mr. Anchor is actually alive... I mean, she's always talking to it, so...",
	touch = "If you need assistance, just give me the order! ...Err, I mean, please let me know!",
	voice_key_2 = -1,
	mission_complete = "A mission has been completed! If Zed were here, she'd say... \"Commander, you've done well!\"",
	battle = "All ships, follow the vanguard's lead! Oh, I guess that means follow me!",
	id = 401260,
	gift_dislike = "",
	gift_prefer = "Well done, Commander! I mean, uhh, thank you!",
	profile = "So you want to hear about my history? Absolutely! As the Iron Blood Type 1936A destroyer, Z26, I escorted Hipper and Scheer, and disrupted shipping with Z25 and the others. While doing so, I was defeated... and that's that!",
	voice_key = 40126,
	headtouch = "",
	feeling2 = "What I do when a foe's aiming at me? Well... I pray that they fire at someone else by accident! If they don't, I pray again that their torpedoes don't hit me!",
	login = "Sorry, but only authorized personnel are allowed into the office... Oh, I guess you're authorized to enter. Welcome back! Let's give it our all!",
	detail = "I hate snowstorms. One was the reason I got separated from my allies and captured by the enemy...",
	couple_encourage = {
		{
			{
				40125
			},
			1,
			"Please don't stray too far from me!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[401261] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "You thirsty, Commander? I've got Cola, milk, and even the fizzy stuff Hipper and Eugen drink when they come over to play. They're all in that mini-fridge over there, so take whatever you want!",
	unlock = "Commander, welcome to my pad! Ah, give me a sec, let me go grab all the snacks and drinks and games!",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "Commander, welcome to my pad! Ah, give me a sec, let me go grab all the snacks and drinks and games!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "U96 pwned me again! Maybe I should practice more with Ryuujou before challenging her... Oh, Commander, I'm talking about a fighting game I've been playing with U96 and the others! |If you're tired, you should try hugging Sharky and taking a nap! ...Ah, I meant that Sharky pillow on the bed!|My sisters are always telling me not to spend too much time gaming. But since it's my day off, does it reallly matter how much I play?",
	touch = "Press this button to start a new game! ...Um, Commander, weren't you asking about where the start button is?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 401261,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Sorry to keep you waiting! These are all my belongings! ...I mean, uhh, these are all my snacks and games!",
	detail = "Spee really likes these bugle crunches a whole lot. Do you like them too, Commander? Then, open up, I'll chuck a few in for you!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[401280] = {
	hp_warning = "A fearsome foe... Everyone, be careful!",
	feeling3 = "Did you want to take it easy for a bit? Sure, I don't mind covering for you. But, there's no replacement for the work you do... so please take care of it later~",
	mail = "The little birdies brought me a letter~ Should I read it aloud for you?",
	expedition = "Commission complete! Commander, if you're busy, I'll go welcome back the commission team!",
	win_mvp = "We won! Commander, you're really awesome!",
	home = "Good work, Commander! Here's a hug for your safe return!",
	unlock = "Pleased to meet you, Commander! I'm the one in the exact middle of the Type 1936A destroyers, Z28! My mission is to support you to the best of my abilities!",
	touch2 = "All the girls will hate you if you do stuff like this, you know?",
	mission = "Looks like we have some new missions... Any tasks to go play with Meowfficers?",
	vote = "",
	drop_descrip = "Type 1936A \"Narvik-class\" destroyer – Z28.",
	feeling4 = "Did you finish your work today? Mmhmm! As a reward, I'll give you a hug~♪ Good job, good job~",
	lose = "There's no need to feel down. Since we managed to retreat safely, there will always be a next time!",
	feeling1 = "I'll continue to support you until you reflect on your behavior and regain everyone's trust. Don't give up!",
	skill = "I'm going all-out! Hyah!",
	upgrade = "Mmm... if only they could make my rigging a little cuter as well...",
	propose = "I never thought I'd get something like this from you, Commander... I'm overjoyed! Please dote on me as much as you'd like from now on! No matter what, I'll always be there for you!",
	feeling5 = "Are you tired, Commander? Here, come put your head in my lap. Please lie down and have a pleasant dream, until all your fatigue and worries melt away one by one~",
	main = "I want to play with cute animals all day long~|This big old office feels a bit empty, but it's also refreshing and helps me focus on work!|If you finish all your work on time, I'll make some delicious sweets for you~",
	touch = "Please go to sleep already! You can wait until later to finish the work!",
	voice_key_2 = -1,
	mission_complete = "Another mission completed flawlessly! As a reward, I'll give you a hug~♪",
	battle = "Everyone, please follow my lead!",
	id = 401280,
	gift_dislike = "",
	gift_prefer = "Are you giving this to me? ...Wow, thank you so much, Commander!",
	profile = "As a lead ship, I may not be as qualified as my sisters due to my armament... As a result, I've come to value problem-solving in other ways rather than directly fighting.",
	voice_key = 40128,
	headtouch = "Ehehe, let me pat your head too~",
	feeling2 = "I wonder what the little birdies are talking about from their tree branch up there... I've always wanted to know...",
	login = "Ah... Commander, I'm sure you had your reasons for being late! Anyway, it's fine, don't worry about it! Let's just work hard starting right now!",
	detail = "Commander, look at this torpedo! I drew a funny face on it! Cute, isn't it?",
	couple_encourage = {
		{
			{
				40123
			},
			1,
			"Sis, you're way too strict with Commander~",
			0
		},
		{
			{
				40124
			},
			1,
			" Z24, I have no idea what you're talking about...",
			0
		},
		{
			{
				40125
			},
			1,
			" Z25, shall we go take a look at Mr. Anchor? ",
			0
		},
		{
			{
				40126
			},
			1,
			"Let's calm down and take things one step at a time!",
			0
		},
		{
			{
				40401
			},
			1,
			"Scharnhorst, you look so cool when you're out there fighting!",
			0
