	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "I invited Z36 to come with me, but why does she never take me up on it...? |What better way to kick off the New Year's celebration than with a Konzert! That's right! |If I was to capture the various sights and sounds of the Sakura New Year's celebration and turn it into a show... Ehehe, might just be a great idea!",
	touch = "Commander, do you have any advice for this New Year project?",
	voice_key_2 = -1,
