	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "One of the prizes for this New Year's raffle is a sea mine raffle? Ehh... I don't really want that...",
	detail = "Eheh~ No matter what outfit you put me in, the singing and dancing idol will always function at 100 percent!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[401352] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "It's time for your favorite maid's reminder service! Ding-diiing♪ The commission team's back!",
	win_mvp = "We just made another awesome memory together, Master♪",
	home = "Instead of performing onstage, I'm performing just for you in the pop-up shop, Commander♪ As for what I'll do... Heehee, why don't you give me your order first?",
	unlock = "\"Welcome, my beloved Master♡ Heehee, I've been waiting here for you for sooo long!\" Heheh, did you get good pics this time? My beloved Master♪",
