	propose = "",
	feeling5 = "",
	main = "Once my album is done, Z36's comes next... Ah! Imagine if, as soon as you took a picture of her, new memories appeared out of thin air in her mind...! Pssh, just kidding♪|Tonight, there's gonna be an idol Konzert with me, Z36, San Diego, Guam, and all the C Class girls! Heheh, you're staying with me until then♪|\"Sniffle... Can I, a maid, ever truly be with my Master...?\" Okay, Commander. What should a Master say next?",
	touch = "Whoa, whoa! I'm not a real maid! I don't DO cleaning!",
	voice_key_2 = -1,
	mission_complete = "\"Say, Commander, can you help me with my homework back at my place after school...?\" In return, I'll grab your rewards for you♪",
	battle = "For my memories with the Commander! Heheh☆",
	id = 401352,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "When you're in this restaurant, is it cool if I call you Master instead of Commander? Oh, you think it's not that kind of restaurant? Okay, but still...",
	detail = "Thanks for helping me snap pics for my scrapbook! Heh, we had so much fun together. Did you get good memories out of it, too, Commander...?",
	couple_encourage = {}
}


