_G.pg.base.ship_skin_words[401360] = {
	hp_warning = "Gah... power overwhelming...!",
	feeling3 = "Heheh~ allow me to engrave the seal of the Devilish Idol upon your flesh! W-wait, I'm not done making the stamp yet!",
	mail = "A letter from one of my worshippers? Hmph... it's addressed to you, Commander.",
	expedition = "My long-departed kindred have finally returned to us from their commission. Let us greet them with hearts full of gratitude!",
	win_mvp = "This victory was ordained by the Fates! Yes, that means it was inevitable!",
	home = "Phew... Huff... Why am I so worn out? Heh, that's because I've been practicing my powers of bewitchment! Ahhh, fine, fine! I was practicing for my performance...",
	unlock = "Hm hm~ so you're my Commander? Our meeting must have been ordained by the Fates. By the Iron Blood coursing through my veins, the Devilish Idol Z36 binds herself to your service! Shazam!",
	touch2 = "You'll get hexed for casually touching the Devilish Idol's body!",
	mission = "Aldebaran has illuminated our path forward! Everyone, the time to act is now!",
	vote = "",
	drop_descrip = "Type 1936B destroyer – Z36.",
	feeling4 = "Those who share the seal of the Devilish Idol shall have their fate cosmically bound with mine! That means... I kind of like you! Ehehe~",
	lose = "Ugh... a Devilish Idol never loses...!",
	feeling1 = "My bewitching eyes have foreseen your imminent destruction!",
	skill = "I'll engrave my devilish powers of bewitchment upon your body!",
	upgrade = "My devilish powers of bewitchment... have further awakened within me!",
	propose = "I can feel it... my devilish soul resonating with yours, Commander...! Okay, I've decided! Until the end of time, whether on the battlefield or on the stage, I shall remain by your side, and use my devilish powers for you only! Commander, you'll always stay with me, right?",
	feeling5 = "Gah... Commander, when I'm with you, I can feel endless power welling up from deep within me, even without releasing my seal. Perhaps this is the \"love\" I have for you, ehehe~♪",
	main = "Commander, have you seen Fünf? I granted her some of my devilish powers, but then suddenly lost the ability to detect her with my bewitching eyes... Huh? Oh, she's right there? |Nobody can resist the bewitching songs of the Devilish Idol! |Whether it's on the battlefield or on the stage, once I release my sealed powers, nothing can get in my way~!",
	touch = "W-wait! Even if it's you, Commander, I won't let you unwrap- I mean, unseal my powers! No way! Nuu~!",
	voice_key_2 = -1,
	mission_complete = "The stars have rewarded our efforts. Blink and you'll miss the opportunity, Commander!",
	battle = "Seal... released! Come! I'll burn the power of a Devilish Idol into your retina! Shazam!",
	id = 401360,
	gift_dislike = "",
	gift_prefer = "If this is some new offering... Oh, don't mind if I do~♪",
	profile = "I am the Bremen-born destroyer Z36, known by many as the Devilish Idol! My friends and I travelled throughout the Baltic Sea, but eventually I was dragged into that deep, black abyss... Hmph. In any case, I'll bring you victory with my powers of bewitchment!",
	voice_key = 40136,
	headtouch = "Bear witness to my devilish procession! Wh-what... Commander, I won't grow any taller if you keep patting me like that!",
	feeling2 = "Heheh~ Finally, someone able to see on the same wavelength as the Devilish Idol herself! Now, become my fan!",
	login = "Ohh, you came at just the right time! Hm, want to listen to my brand new song? It's called \"Devilish Overture!\"",
	detail = "Hmhmm~ what do you think about my bewitching heterochromatic eyes? H-hey! They're not contacts!",
	couple_encourage = {
		{
			{
				40135
			},
			1,
			"Let's have our devilish duet! Huh?! Fünf, come baaack!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[401430] = {
	hp_warning = "Kh! My barrier has been broken?!",
	feeling3 = "Plotting, strategies... All of it is so small and frivolous before my eternal demon eye! Like mere ants... Huh? W-wait! I'm not saying YOU'RE like that, Commander!",
	mail = "My demon eye has already seen the contents of your mail... Ack, I'm kidding! I wouldn't peep at your mail!",
	expedition = "Our allies are back from their commission. Heheheh, DR could not foil their mission this time!",
	win_mvp = "The glory of victory is mine – and by extension, yours!",
	home = "Heheheh... My servants, Delaman and Dulce, informed me of your arrival, giving me time to make sweets! Come, eat your fill!",
	unlock = "Heheh... You may approach, Augur of Destiny. Z43, the demon-eyed devil, rebel against evil, she who chases the light even when cursed with wings of dark, welcomes you!",
	touch2 = "C-C-Commander! At this rate, my magic will run wild and destroy the very fabric of the world!",
	mission = "Have caution, Augur of Destiny! If you do not complete your missions, then I will be unable to see my justice done!",
	vote = "拉票描述",
	drop_descrip = "Type 1936B destroyer – Z43.",
	feeling4 = "Behold, Augur of Destiny, the avatar I designed for you! In your left hand, a devil-summoning magical book! With your right, you wield a magic circle that can subvert the laws of this very world! On your back, twin wings of white and black! ...I-it's cool as hell, right?!",
	lose = "Kh... Has this happened because of the stirring of my left eye's seal?",
	feeling1 = "Hmm... So the dark encroaches even into you...",
	skill = "Let them witness our true power!",
	upgrade = "Heheheh... My magic grows ever stronger!",
	propose = "Ahem. Yes, I was trying to get your attention... Huh? You like this, Commander? ...Ack, ahem! Do you wish to renew our covenant? A covenant for all eternity, one that can never be broken–wh-what?! You agreed that easily?!",
	feeling5 = "Come, Augur of Destiny, and place your hand on mine! I will now link our hearts... Oooh! This feeling... Heheheh! I knew it! You cannot resist the charms of this rebel against evil!",
	main = "Interested in why they call me the rebel against evil? Well, I parted ways with the bad guys and dealt a major wound to them... Hm? Who are the bad guys? Sh-shut up! No more questions! I haven't put that much thought into my backstory...|Where are my familiars? Heheh, Dulce has shapeshifted into this bag I'm wearing, and Delaman is the eyepatch that seals my demon eye as we speak. Heheh, cute, right? I designed it all... Ahem, TAMED them myself!|Augur of Destiny, tell me something! When you fight enemies, do you have a... personal boss battle theme? I'd pick something jazzy for you... Yeah! Jazz is great for symbolizing the confidence of the Fellowship of Justice!",
	touch = "Kh! You've broken my barrier?",
	voice_key_2 = -1,
	mission_complete = "Mission complete. The rewards... Mmm, it'll take too long to check all of these... I leave this job to you, Augur of Destiny!",
	battle = "The battle with Dark Requiem is mine to fight!",
	id = 401430,
	gift_dislike = "",
	gift_prefer = "Heheheh... This seems to be imbued with immense magical power...",
	profile = "You may approach, Augur of Destiny! I am the Iron Blood's Z43, most powerful devil in all the world, descended to protect you from Dark Requiem... Heheheh, be proud of this fated encounter!",
	voice_key = 40143,
	headtouch = "Gaaah! Stop touching my head! You're ruining my power to detect darkness!",
	feeling2 = "Augur of Destiny, be aware that the Fellowship of Justice has investigated you and is considering for a leadership position! Hm? Who investigated you? Me, of course!",
	login = "Ooh! Augur of Destiny, come! ...Hey, you're late! H-hurry and help me uncover the evil conspiracies of Dark Requiem, the organization of darkness!",
	detail = "Dark Requiem – DR, for short. Treacherous scoundrels who delight in deceiving the masses... Hm? I mean the enemies we fight with at sea daily, of course.",
	couple_encourage = {
		{
			{
				40136
			},
			1,
			" Huh? Z36, are you supposed to be a devil, too...?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[401431] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Huh? How has mail come when my base is secret? Augur of Destiny, do you wield some sort of mail-collecting magic?",
	expedition = "My demon eye beholds... Ah, yes! The return of our commission-bound comrades!",
	win_mvp = "",
	home = "Welcome back to our own secret base! Umm... M-my math homework is really hard... Can you help me out?",
	unlock = "Why can't I wrap this damn bandage... Hnnngh! Ow, ow, ouch! ...Huh? Comma–A-Augur of Destiny, help me! My magic-suppressing bandages have taken on a mind of their own...!",
	touch2 = "T-time out a sec! Don't tie it theeere!",
	mission = "",
	vote = "拉票描述",
	drop_descrip = "Why can't I wrap this damn bandage... Hnnngh! Ow, ow, ouch! ...Huh? Comma–A-Augur of Destiny, help me! My magic-suppressing bandages have taken on a mind of their own...!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Alone in our secret base... My fantasies have become reality... Aargh, damn it! If not for this stubborn bandage, it'd be perfect... Ugh...",
	main = "I'm just trying to put this bandage on to seal my magic as usual... Why can't I get it on today?! Have the late nights working on homework ruined my control over magic?|The papers on the slide up there? Heheh, those would be my magical sigils, my plan for justice, and a guide to lead lost lambs... h-heeey! Commander, don't leave!|Mmmgh... No matter how I try, I can't do it! Augur of Destiny, hear my command! Wrap my bandages right for me! ...I-I know! This is a TRIAL!",
	touch = "Y-you still don't have it wrapped, Commander?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 401431,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Heed my words, Augur of Destiny! Now that you've discovered my secret base... you may come and hang out any time you want!",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[401460] = {
	hp_warning = "What doesn't kill you only makes you stronger.",
	feeling3 = "Friendship, enmity, love, hate... these are things that I have never experienced prior to coming here.",
	mail = "Receiving mail is proof of the expectations and trust that people have in you.",
	expedition = "Waiting at the harbor for dispatched ships to return... is something I’ve ever experienced before.",
	win_mvp = "Am I too strong? Or are you all too weak?",
	home = "Is the battle over, or has it just begun?",
	unlock = "Are you the one who summoned me? I am... unfortunately, still without a name. You may call me Z46 for now though.",
	touch2 = "If your desire is righteous, then why do your hands tremble?",
	mission = "Unknown beings and new acquaintances... let us sally forth to meet them!",
	vote = "",
	drop_descrip = "Type 1936C destroyer – Z46.",
	feeling4 = "The sea breeze caressing my cheeks, the crashing of waves resounding in my ear. The laughter echoing on the beach, the footprints left in the sand. The rays of summer shimmering overhead, the fluttering sails of ships about to return... What an unforgettable scenery.",
	lose = "Go and boast to the world. Be proud that you have bested me even once.",
	feeling1 = "Perhaps what I seek... cannot be found here.",
	skill = "The unworthy are fated to drown in this world.",
	upgrade = "Though this is but a trivial thing, I'll return the favor for your consideration.",
	propose = "My beloved, I have long awaited this day. What name have you decided to bestow upon me?",
	feeling5 = "To be needed, yearned for, trusted, and loved... \"I\" am a cloth dyed by your color. My beloved, please bestow a name upon me.",
	main = "I have experienced neither failure nor suffering. Consequently, I have accomplished nothing.|A name is not merely a label. It is also proof that one exists in this world.|The things I have yet to experience and understand are as numerous as the countless stars in the night sky.",
	touch = "Being able to be touched is proof of one’s existence.",
	voice_key_2 = -1,
	mission_complete = "Freedom and fortune only favor the hardworking.",
	battle = "For not fleeing upon seeing my visage, I applaud both your courage and your stupidity.",
	id = 401460,
	gift_dislike = "",
	gift_prefer = "With utmost sincerity, I accept your kind wishes.",
	profile = "Iron Blood Z-class destroyer, 1936-C Type. Four other sister ships were planned for construction, but only Z47 and I were built. I wasn’t even completed by the end of the war, and was scrapped without ever being finished. One day, I hope to be called not as Z46, but by a true name.",
	voice_key = 40146,
	headtouch = "",
	feeling2 = "The journey to find a name has lead me to this place.",
	login = "This world is so different that from what I was expecting. How interesting!",
	detail = "Z46 is but a codename, not my actual name. For a ship, something like a name should be unimportant, but...",
	couple_encourage = {
		{
			{
				40701
			},
			1,
			"After this battle ends, please teach me to make today's lunch.",
			0
		},
		{
			{
				40135
			},
			1,
			"Ill suited as I am for an idol's name... Please do not try to call me something cutesy.",
			0
		},
		{
			{
				40123
			},
			1,
			"Do remember, trying too hard can sometimes backfire.",
			0
		}
	}
}


