_G.pg.base.ship_skin_words[401520] = {
	hp_warning = "Is my Thunderheart broken or something?",
	feeling3 = "I applied for the port's parkour contest! Be there and cheer for me! All I need is you in the audience and that first-place spot will be in the bag!",
	mail = "Whoosh! Here I am with your letter, Commander!",
	expedition = "The commission team's back! Let me go with them next time! I specialize in long-distance missions, so I swear I'll be useful!",
	win_mvp = "Whaddya think? Blows you away how awesome I am, right? Heheh!",
	home = "Where'd your sortie take you this time? Ohh, that's a place I've never been before... So, saw anything fun? Had any good food? I can zip-zoom over and have a look!",
	unlock = "Z52, reporting for duuuuaaahh! Shouldn't have run so faaast! ...Phew. Hah! So you're the Commander? You look capable enough! Just throw me your orders when you want someone for work or for a fight!",
	touch2 = "Wh-what?! Why are you so keen on touching this?",
	mission = "You've got new missions, Commander... Hey, how do you do this thing?",
	vote = "",
	drop_descrip = "Type 1944 destroyer – Z52.",
	feeling4 = "Regensburg tweaked Thunderheart a bit and now it can read people's minds! Right now, you're thinking about... Huh... Why's it not showing anything? Maybe I gotta get closer... Um, uh, why are you hugging me?",
	lose = "Are we sortieing, Commander? They run all they want – I'll still catch up and whoop 'em good!",
	feeling1 = "Listen! You can't keep skipping out on exercise!",
	skill = "Thunderheart, burn and send 'em flying!",
	upgrade = "There's no obstacle I can't run through!",
	propose = "Oh gosh! I'm the happiest girl alive! Thank you, Commander! I'll treasure it always! ...Commander? Hellooo? Was I too fast with my super happy spin? Oh no! Sorry! I shouldn't have gotten so excited! Sit down and I'll get you some water!",
	feeling5 = "I'm here, Commander! Need anything? ...So what if it's not a big deal? I'll come running as soon as you call for me, and that's that!",
	main = "What's that on the ceiling? A bug I've never seen before? Lemme climb up and have a look at– What? DON'T climb the bookshelf?|Hey! Commander! There's this dessert that's exploded in popularity! You should try it! I got curious, so I went and bought some from the shopping district! ...Yeah, obviously I ran there!|Takeoff! And landing! How was that, Commander? The Kong Vault is pretty sick, huh? Heheh! ...Well, yeah, I'm just practicing. I know I'm not allowed to do parkour in your office!|Let's open the window and get some fresh air in. Good air brings good vibes, and good vibes bring... Ow! I got sand in my eye! ...You'll blow it out for me? Umm, thanks... *blushes*",
	touch = "What is it? Found any fun stuff? Let me have a look!",
	voice_key_2 = -1,
	mission_complete = "Great work! I already checked the rewards, so you just lie down and... Huh? I did it wrong? Ugh, alright, then show me how it's done!",
	battle = "Thunderheart, unleash the burst!",
	id = 401520,
	gift_dislike = "",
	gift_prefer = "Ooh... What is it? Can I open it up right now?",
	profile = "I'm Z52 from Iron Blood, and long-distance ops are my specialty. I didn't get to fight in the war, but I've done plenty of combat sims! Heehee. Now I'm here to help you out!",
	voice_key = 40152,
	headtouch = "Did my Thunderheart here catch your eye? Heh, it's a mask that lets me see the essence of everything! Pretty sick, huh? ...How does it do that? I'm, uh, trying to figure that out myself!",
	feeling2 = "Do you play any sports? ...Ohh, that one! I'm pretty dang good at that, so we should totally play together sometime!",
	login = "Oh, you're here! So is all this stuff work that you have to do? Let's see here... Hey, this looks kinda fun! Let me take a shot at it!",
	detail = "Are you a rigging geek, by any chance? I love that stuff, so tell me all you know! ...Uh-huh. Huh? What? Whoa, slow down! You're making it too complicated for me!",
	couple_encourage = {
		{
			{
				40116
			},
			1,
			"Rawr! How'd I sound?",
			0
		},
		{
			{
				10515
			},
			1,
			"Whoa! What energy drink do you drink?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[401521] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Did you just get here? ...What? You wanted to check if I'd gotten lost? Um, well... Thanks!",
	unlock = "Let's see... Where's the shop again? It should be... Oh, Commander! I'm not late, am I? I ran here as fast as I could!",
	touch2 = "Th-that's where you stick the tape? I thought it should go on my clothes...",
	mission = "",
	vote = "",
	drop_descrip = "Let's see... Where's the shop again? It should be... Oh, Commander! I'm not late, am I? I ran here as fast as I could!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I'll go with you wherever you want – to the shop to chat, on a ride, or even to the raffle! As long as you're jumping for joy by the end of tonight, that's all I care about!",
	main = "I've never worked wearing this outfit before, so it's pretty novel. Wonder what the job itself is about... Hm? You're making a face like you know what! C'mon, tell me!|I've wanted to see what it feels like to ride a motorcycle, so I took a ride on one! Buuut... I think I prefer going fast with my own two legs.|Oh, these? They're raffle tickets. I brought some, hoping we could check out the raffle event later. Speaking of which, what prizes does the raffle even have?|Here! Pick a drink. Z47 said they're both tasty as heck, so I bought one of each!",
	touch = "You'll carry my stuff for me? Thanks!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 401521,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Is my hair all ruffled up 'cause of my helmet?",
	feeling2 = "",
	login = "Uhh, just a sec. I'm putting on this anti-slipping silicone tape on my clothes... Yup! I went to the shopping district to buy this stuff, and that's why I was late!",
	detail = "Motorcycles are pretty cool – and more fun than I thought! You should ride with me after I finish work!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[401522] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome back, Commander! The sunlight is strong today – let's go snorkeling! See? I brought diving gear, too!",
	unlock = "Whoooa! Commander, watch out! Phew... Good thing I didn't crash into you. Good reflex... Oh! Since we're here, why don't you come play in the water with me?",
	touch2 = "Whoa?! C-Commander?! Th-this isn't how you play in the ocean...",
	mission = "",
	vote = "",
	drop_descrip = "Whoooa! Commander, watch out! Phew... Good thing I didn't crash into you. Good reflex... Oh! Since we're here, why don't you come play in the water with me?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Don't worry, Commander! Even if you come empty-handed, I'll have everything you could ever need! Ehehe, let's keep speeding ahead together from now on!",
	main = "What do you feel like doing now, Commander? Roller skating, surfing, or snorkeling? Oh, hey, let's just do all of them! Go, go, go!|Can we try tandem surfing together? Just relax and hold on to my waist. Here we go!|If you go fast enough, you can leave all your troubles in the sea! Let's pick up the pace, Commander! ...Huh? Did you say something? I'm going too fast! I can't hear you!",
	touch = "Which gear do you want? Hurry and choose so we can go!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 401522,
	gift_dislike = "",
