_G.pg.base.ship_skin_words[401992] = {
	hp_warning = "",
	feeling3 = "",
	mail = "A new letter? I'll go and get it for you if you'll help me with... Huh? You just want me to read it aloud to you?!",
	expedition = "",
	win_mvp = "",
	home = "You're finally back, Commander! So, did you find a way to help me with this? You didn't? Okay, well... Huh?! Why do you need me to tell you why I bound myself up?!",
	unlock = "Urgh... I can't get them off... Huh?! C-Commander?! When did you get here?! This just, um... It just kind of happened! Help me get loose!",
	touch2 = "Eek! H-how could you do this to someone who's in need of help?!",
	mission = "",
	vote = "",
	drop_descrip = "Urgh... I can't get them off... Huh?! C-Commander?! When did you get here?! This just, um... It just kind of happened! Help me get loose!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "I should be able to break free now that I'm stronger... Okay, that's tight!",
	propose = "",
	feeling5 = "",
	main = "Why there's a pillow on the sofa? I think it's pretty obvious! It's so my head won't hurt while holding this pose and... Wait, were you goading me into saying it?!|Commander! You've been staring for a while now! Have you still not figured it out?|(Ugh. It's so humiliating to be seen like this. I doubt I'll be able to free myself, so I'll just have to rely on the Commander... but I don't want it to be known how I ended up like this. What should I do?!)",
	touch = "So you finally figured out what to do! I knew I could count on... What? Why am I bound even tighter than before?!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Y-you're telling me to fight like THIS?!",
	id = 401992,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Huh?! I know you did that on purpose! And I'm powerless to resist... Stop ruffling up my hair!",
	feeling2 = "",
	login = "Commander! Why are you just staring? Long story short, I ended up like this by accident! There's no kinky reason for it! Ugh! Stop wondering about it and just undo these binds!",
	detail = "Hrrnngghh! Agh... This dumb tape gets tighter the harder I try to break it! Commander, I'm gonna tire myself out if you don't help me soon!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[402010] = {
	hp_warning = "",
	feeling3 = "And I thought you were a good child, Commander... I guess you can still be trained... Hehe...",
	mail = "Remember to read new mail as soon as possible. It’s rude to make people wait.",
	expedition = "The girls have returned from commissions. Please welcome them back in a timely manner.",
	win_mvp = "Hmph, so that’s all they amounted to.",
	home = "Good work, Commander. Let’s quickly review the previous battle.",
	unlock = "So you’re the commander? You have such a cute face! Hehe... let big sister take \"good care\" of you from now on~",
	touch2 = "Oh my? That’s not how you do it. Should I teach you the proper way to touch a girl?",
	mission = "Let's see what mission is up next.",
	vote = "",
	drop_descrip = "Königsberg class light cruiser, Königsberg.",
	feeling4 = "Hmm? I do you like you very much, in many different ways... I'm going to teach you all kinds of things from now on... Hehe...",
	lose = "Tsk... Do we still not have enough anti-air?",
	feeling1 = "Alright, time for me to punish you.",
	skill = "Hmm, do you want some lessons from me too?",
	upgrade = "I think I get the hang of it! Commander, come with me for a second!",
	propose = "Commander, you’re the best! The best what? Pet? Companion? Or maybe... lover~?",
	feeling5 = "To train someone, the trainer must also give the trainee some love, otherwise... Yes, Commander, I love you. Come, let's continue. What should we try next?",
