_G.pg.base.ship_skin_words[402050] = {
	hp_warning = "Ah... Oww...",
	feeling3 = "You want me to teach you how to make Brötchen? I don't mind, but I must warn you that I have high standards... Wait, are you perhaps using this as an excuse to get closer to me...?!",
	mail = "You have new mail, Commander. I hope it's not a glitter bomb...",
	expedition = "A commission has been completed. You should know what to do without me reminding you, right?",
	win_mvp = "Huh? I'm number one? That's rather... unexpected, isn't it?",
	home = "I know you're tired from your sortie, Commander, but please hang in there a bit longer for everyone else's sake... I mean, if you could...",
	unlock = "I am the second ship of the Leipzig-class, Nürnberg. Starting today, I shall serve you to the best of my abilities... Is that acceptable?",
	touch2 = "Aaah?! Wh-what are you doing all of a sudden, Commander?!",
	mission = "There's a new mission, Commander. Did you get the previous one sorted out yet?",
	vote = "",
	drop_descrip = "Leipzig-class light cruiser – Nürnberg. ",
	feeling4 = "Commander, we've been spending more and more time together recently... Ugh, you really were planning something weird after all... At this rate, I... I'll be... Fine with it...?",
	lose = "How could this happen... It surely must've been my fault... I'm so sorry...",
	feeling1 = "You... really are an eyesore...",
	skill = "P-please don't get back up!",
	upgrade = "I hope all this hard work pays off...",
	propose = "I, I know already... I'll do whatever you say... so please don't look at me! It's embarrassing... So embarrassing that it's driving me crazy... I, I wish this would end already! ...Hauu...",
	feeling5 = "Now that I think about it more, Commander, you haven't tried doing anything weird to me. If anything, you've treated me really nicely and it's somehow reassuring to be with you... Even if you tried to have your way with me, I don't think I'd... Wh-wh-wh-what am I saying?! P-please forget I ever said anything...!",
	main = "Commander, do you like Brötchen? I see... Th-then, if work goes well, I... I'll make some for you!|I wonder if there's anything that can be done about Leipzig always collapsing... Ph-physical exercises, you say? Commander, are you planning to do something weird to Leipzig?!|Am I being too hard on you? What should I do... If I was to make you upset with me... W-well, I'm sure it's fine, since you're probably thinking up all kinds of weird things right now...!",
	touch = "Are... are you trying to condition me to be less cautious by touching me...?!",
	voice_key_2 = -1,
	mission_complete = "Did you finish all your missions? As expected of the commander...",
	battle = "Everyone, p-please exercise your own judgment...?",
	id = 402050,
	gift_dislike = "",
	gift_prefer = "It looks so expensive... Are you really giving this to me?",
	profile = "Though I received many modifications during the war, I never was able to put any of it to good use... But, there aren't many ships in the Iron Blood with longer service histories than me? I, I can't even believe it myself...",
	voice_key = 40205,
	headtouch = "Eek?! Suddenly touching my head like that... Commander, you're thinking of doing something weird, aren't you...?! Am, am I wrong?",
	feeling2 = "I wonder if Leipzig fell down somewhere... Commander, let's go look for her... I mean, would you like to come with me?",
	login = "It is time to begin working. C-Commander, please give it your all...!",
	detail = "Why are you here by yourself, Commander? ...W-were you perhaps waiting for everyone else to leave...?! Oh, you weren't?",
	couple_encourage = {
		{
			{
				40204
			},
			1,
			" Let's focus on the fight!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[402060] = {
	hp_warning = "I take hits like this for breakfast! Try harder!",
	feeling3 = "To what do I owe this cuppa joe? ...The paperwork I did earlier? Ahahah, thanks! I'll have just a dash of milk.",
	mail = "New mail, yo! You really oughta make it a habit to check your mailbox.",
	expedition = "Heads up, Commander! Commish team's back, so you know what that means!",
	win_mvp = "Hell yeah! This calls for a victory somersault!",
	home = "Sweet, you're back. Run into any tough foes out there?",
	unlock = "Yo! Iron Blood light cruiser Magdeburg here! Gimme a fistbump to celebrate us becomin' homies! Wait, uhh... Got these metal gauntlets on, so go easy for your own sake.",
	touch2 = "I'll choose to believe that was just an accident...",
	mission = "Guess what – new missions just dropped. We doin' 'em, or?",
	vote = "",
	drop_descrip = "M-class light cruiser – Magdeburg",
	feeling4 = "Let's not think in terms of favors-for-favors and just help each other out when we need it, like homies do! Nice and simple that way, too!",
	lose = "Welp, guess this one's fubared. My bad...",
	feeling1 = "You're pissin' me off to no end. Either sort yourself out, or leave me the hell alone!",
	skill = "Open up for a knuckle sandwich! ...Err, I mean a cannon volley!",
	upgrade = "Send me into battle and we'll find out if I really got stronger or not!",
	propose = "Honestly, I didn't plan for this at all... I doubt I've even got the kind of charm you deserve. No, no, I'm not turnin' you down! I absolutely love you, it's just... Well... Ahh, to hell with it! I can't find the right words!",
	feeling5 = "Nobody matches my wavelength better than you. You and I, we're the OTP... Oh, guess that also makes us the port's number one power couple!",
	main = "Hooh! Hah! And just for good measure... Whupah! Suddenly felt like doing a backflip, that's all. Hope I didn't startle ya there.|If I catch you slackin', your forehead's getting a whackin'. Relaaaax, I'll be gentle.|I just want the next chapter of this comic I'm reading to come out! But it's a weekly release, so all I can do is wait...",
	touch = "You wanna bump fists? Aight! Bam!",
	voice_key_2 = -1,
	mission_complete = "Mission complete! You gonna do the math for my share of the rewards next? Hahah.",
	battle = "Go get 'em! Follow my lead!",
	id = 402060,
	gift_dislike = "",
	gift_prefer = "Woah, you're giving me something real amazing! I'll have to think of some way to return the favor.",
	profile = "I'm Magdeburg, Iron Blood light cruiser. Don't got much of a record to boast about, but meh, what matters is the fact I'm here right now. If you need a problem fixed or someone's ass kicked, hit me up!",
	voice_key = 40206,
	headtouch = "Huh? The hell are you doin'?",
	feeling2 = "Swamped with work, I'm guessin'? Need a hand? Fighting's not all I'm good for – I can do simple paperwork too, y'know.",
	login = "Aw yeah, I'm feelin' it today! Let's knock out all the paperwork in one go!",
	detail = "Why do I run like that? Ah, well, I was inspired by a comic I read. Makes me look pretty badass, doesn't it?",
	couple_encourage = {
		{
			{
				40124,
				40125,
				40305
			},
			1,
			"Gauntlet gang, represent!",
			0
		},
		{
			{
				30109,
				30127
			},
			1,
			"You know ninjutsu? The real deal?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[402061] = {
	hp_warning = "",
	feeling3 = "",
