_G.pg.base.ship_skin_words[402070] = {
	hp_warning = "If you wish to defeat Emden, you must use your every drop of strength♪",
	feeling3 = "Insistent on being a disobedient little human, aren't you? \"I like seeing a sweet human struggle so. Heehee.\"",
	mail = "You have a letter, dear human. Would you be good and read it aloud to Emden?",
	expedition = "New supplies have arrived. A traveling swan needs sustenance – when her stomach growls, she has little choice but to \"borrow\" food from a passerby.",
	win_mvp = "The battle is over. All you who are out of Emden's range may now take your leave.",
	home = "You've returned to safety, now won't you close your eyes and rest? It's important that you get your beauty sleep, my darling human.",
	unlock = "Heehee, it is you that summoned Emden, isn't it, my darling human? I shall make real your every desire if only you surrender yourself. \"Heehee. Submit to Emden. Submit to us.\"",
	touch2 = "Is this your way of saying that you long to be put in a cage? \"Do you wish to be flayed 'til your skin gives way to bone?\"",
	mission = "New orders from your superiors. Supposing that someday no one is left to give you orders, where will you go then, dear human?",
	vote = "",
	drop_descrip = "Dresden-class light cruiser – Emden.",
	feeling4 = "\"In truth, Emden has wanted to shackle you down from the outset, human.\" Obedience gained by force is worthless. I shall patiently wait for you to submit to me of your own accord, my darling human.",
	lose = "One can hardly call this a desired outcome, dear human. \"I get the impression you ordered a sortie without a moment of preparation.\"",
	feeling1 = "Oh dear. It seems Emden got carried away. Such a pity... Her only darling human, broken by her own hands.",
	skill = "Heeheehee♪",
	upgrade = "Thank you for this strength, my darling human. \"You make good decisions sometimes! Heeheehee♪\"",
	propose = "Have you at long last learned your place? Heehee, as much as I enjoy seeing your cute struggling, you're more lovely when you submit♡ Now, lie in my cradle of love and embrace an eternal slumber. \"Emden will cuddle you forever and ever. You won't want to leave♥\"",
	feeling5 = "One finds the world's greatest comfort not in a cage of steel, but in a cradle of love and submission. Have no fear, my darling human. Give your body and soul to Emden, and your woes and troubles will all disappear in due time♡",
	main = "Trying to make a human submit through force only gains you its resentment. Only by breaking the human's spirit can you make its whole being your own.|\"When you're at a loss, how about you get up and move instead of just sitting in your chair?\" Emden cannot bear to see you rack your brains all day, dear human. Heehee.|You, my dear hardworking human, deserve a reward. You are hereby granted the privilege of massaging Emden's shoulders. Use neither too little nor too much force, and henceforth, kindly do it without me telling you to first.",
	touch = "You would use force to subjugate a defenseless girl? Heehee, unfortunately for you, Emden stands on top, and you crawl down below, dear human. This is an unchangeable fact.",
	voice_key_2 = -1,
	mission_complete = "Ah, mission rewards. Emden need not tell you how best to use them, right, my darling human?",
	battle = "An entertaining battle awaits us♡",
	id = 402070,
	gift_dislike = "",
	gift_prefer = "You certainly know how to work for my affection now, my darling human~",
	profile = "I am the Swan of the East, also known as Emden, the Dresden-class light cruiser. \"And I am Emden of the Königsberg class – member of the High Seas Fleet. We are Emden. Remember our name.\"",
	voice_key = 40207,
	headtouch = "Why do you stroke my head? That is something a master does to her pet. Perhaps what you did was the inverse of this idea?",
	feeling2 = "A lovable pet should not be unwaveringly obedient, but rather a source of continued delight to its master. \"Fawn on me in a way I enjoy, my sweet human♪\"",
	login = "Welcome home, my darling human. Where shall your conquest take you today, and what foes shall you smite?",
	detail = "\"Don't assume I'm fond of you, pitiable human.\" You have the sweet scent of a bud that wishes to blossom, dear human. The kind of scent that Emden adores.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[402071] = {
	hp_warning = "",
	feeling3 = "",
	mail = "There is a letter for you. Emden shall read it first, then you may take it after, my darling human.",
	expedition = "The errand girls have returned. Let us see what they've brought... \"Well, well. These aren't half-bad spoils.\"",
	win_mvp = "",
	home = "It matters not whither you flee, for you will inevitably return hither, my dear human♡ \"After all, a human that's wholeheartedly submitted to Emden can never truly escape. Heehee♥\"",
	unlock = "Raise your head, my darling human. O lost soul, you have three options – become Emden's meal, become Emden's prisoner... \"Or become Emden's vassal. Our vassal♥\"",
	touch2 = "Close your eyes and let Emden show you a dream. A rapturous dream wherein all is possible. \"A paradise of perpetual night.\"",
	mission = "A new mission has come in. Have no fear, my darling human. The night shall show you the way.",
	vote = "",
	drop_descrip = "Raise your head, my darling human. O lost soul, you have three options – become Emden's meal, become Emden's prisoner... \"Or become Emden's vassal. Our vassal♥\"",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Vampire hunters... A rather barbarous kind, aren't they? \"They will learn who truly rules the night.\"|You may borrow my human if you wish, Yorck. Please do keep in mind, though, that you are only BORROWING my human.|By all means, use your holy artifacts as a means of meager resistance. \"I will savor every moment as I slowly crush your rebellious spirit♥\"",
	touch = "Embrace the night, and the night shall embrace you. \"Now, are you ready to offer yourself?\"",
	voice_key_2 = -1,
	mission_complete = "Mission completed. You have done well, my darling human. You are hereby given the privilege of sharing a toast with Emden.",
	battle = "",
	id = 402071,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "\"You have some gall, human.\" Emden can tolerate a dash of self-indulgence♡",
	feeling2 = "",
	login = "\"You're late, human.\" How will you make recompense for the time you kept Emden waiting, hmm? My darling human♡",
	detail = "What you see is not theatrics, my darling human. Emden has merely adopted a more suitable form for handling a vassal. Vampirism has nothing to do with it. Heehee♡",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[402072] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Those commission girls have returned. \"Rejoice, human, for Emden is content with this alone.\"",
	win_mvp = "\"You really thought the likes of you could best Emden?\" Neither you nor my dear human could dream of overcoming Emden. Heehee♡",
	home = "My darling human♡ Why don't you have a peaceful slumber beneath the moonlight? \"Sleep, and we will cosset you in your dreams♥\"",
	unlock = "Welcome, my darling human. Are you looking for something? If it is Emden you seek, you have already found her. \"We, Emden, are before your very eyes.\"",
	touch2 = "You seem to believe you're in control of Emden... \"When in fact it's Emden who controls you♥\"",
	mission = "You've received new missions. Accept your fate and carry them out. You may defy your superiors, but you cannot defy Emden.",
	vote = "",
	drop_descrip = "Welcome, my darling human. Are you looking for something? If it is Emden you seek, you have already found her. \"We, Emden, are before your very eyes.\"",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Emden aches with eagerness when you let your indecision show, my dear human. \"How I wish I could grab and drag you under the water♥\"|\"You've earned a reward, my sweet human.\" Open your mouth and savor Emden's nectarous taste♡|Look down and inspect your reflection closely, my dear human. Much unlike Emden, you must carve out your own path if you're to survive. Heehee.",
	touch = "Much like attempting to top me, grasping for the moon within a lake's reflection is a futile endeavor. Heehee.",
	voice_key_2 = -1,
	mission_complete = "What a well-behaved pet you are. Have yourself a reward, my darling human.",
	battle = "",
	id = 402072,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "You're so endearing when you're scared, my darling human.",
	feeling2 = "",
	login = "Welcome, my darling human♡ Have you come, hoping to see Emden? \"Or have you come to answer Emden's summons? Heehee♥\"",
	detail = "The scent you exude smells sweeter and richer than all the flowers here, my dear human. Your fragrance is one I adore so much.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[402073] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Supplies have arrived, dear human. I urge you to claim them at once. \"You will need them on your voyage. Use them carefully.\"",
	win_mvp = "A victory just as planned. Heehee. You're very talented. \"Do you seek to pursue all-out war next?\"",
	home = "Welcome back, my darling human♡ \"Emden shall give you a peaceful dream♥\"",
	unlock = "Welcome, my darling human. We are Emden, the receptionists that shall guide your way. You can go anywhere you'd like... as long as you give us an offering♡ \"Even to an unsullied paradise that is not of this world\"♥",
	touch2 = "\"Come with Emden♥\" Clear your mind completely and relish in the paradise Emden has created♡",
	mission = "",
	vote = "拉票描述",
	drop_descrip = "Welcome, my darling human. We are Emden, the receptionists that shall guide your way. You can go anywhere you'd like... as long as you give us an offering♡ \"Even to an unsullied paradise that is not of this world\"♥",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Emden arranged this cruise just for you, my darling human. Let Emden guide you and feel the joy of letting Emden take care of everything♡ \"Don't resist it. Revel in the ultimate bliss that Emden provides♥\"",
	main = "You look lost, my darling human. Do you really find my schedule table that interesting? \"Or are you simply engrossed in the service that Emden provides?\"|Are you unsure where to go, dear human? Emden shall assist you. \"Know that this is a kindness done unto you, human.\"|\"You must beg Emden if you want to know when and where this cruise will change course. If Emden finds your appeal satisfactory, I'll consider telling you. Heehee♥\"",
	touch = "Emden stands on top of you even whilst serving as receptionists, dear human. \"And still, you boldly try to take a step further.\"",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 402073,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Heehee, has our change in standing perhaps emboldened you? \"Or do you actually think this will curry favor with Emden?\"",
	feeling2 = "",
	login = "We are ready for you now, my darling human. Would you like to a whole new world today? \"Or perhaps you want to search for the end of the known world?\"",
	detail = "You give off a scent of curiosity and expectation, dear human. \"Such a sweet and delectable smell. Heehee. It gladdens me.\"",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[402074] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "To reward you for a triumphant return, Emden will spend some quality time with you~♡ \"But be sure to stretch and warm up before you go into the water~♥\"",
	unlock = "Were you drawn here by the seaspray and my alluring figure, my darling human? Heehee... From now on, your lens and your gaze belong to Emden only~♡ \"Revel in this great honor, human~♥\"",
	touch2 = "Such an audacious pose... You're looking for an angle that brings out both light and shadow, are you? \"Heheh... Emden will grant you that which you desire~♥\"",
	mission = "There's a new mission. Shall we handle it now, or finish this photoshoot first? \"The choice is yours, but be sure to make a decision that will please Emden.\"",
	vote = "",
	drop_descrip = "Were you drawn here by the seaspray and my alluring figure, my darling human? Heehee... From now on, your lens and your gaze belong to Emden only~♡ \"Revel in this great honor, human~♥\"",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "From now on, my darling human, Emden shall be all you ever see. You are fated to stay by Emden's side, forever... \"Fated to be enthralled by Emden's presence, forever~♥\"",
	main = "The light is growing dimmer... Now is the time, my darling human. Use your lens to drape this golden veil over Emden.|Try for a slightly lower angle... Yes, like you're looking up at Emden... \"Only by following Emden's advice shall you snap the perfect masterpiece.\"|\"Your attention is drifting again...\" Are you charmed by Emden's beauty? Or perhaps thinking about how to take the photo that would please Emden the most? Heehee, you need not say it. Your eyes tell me everything~♡",
	touch = "You wish to direct which pose I'll take? How bold of you, my darling human~♡ \"Show Emden what pose you have in mind...♥\"",
	voice_key_2 = -1,
	mission_complete = "Mission complete. But, forget the rewards. Emden is more curious about the photos you took.",
	battle = "",
	id = 402074,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "\"Is this some attempt at flattery, or your way of comforting me?\" Either way, Emden will gladly accept it~♪",
	feeling2 = "",
	login = "Which Emden would you prefer to take a picture of right now, my darling human? \"Make sure your photos do Emden's beauty justice.\"",
	detail = "The dusklight's glow on the water's surface, the way your eyes are fixed on Emden alone... \"'Tis the picture of undeniable perfection.\"",
	couple_encourage = {}
}


