_G.pg.base.ship_skin_words[402083] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "(The commission team is back. So I'll have to stay like this while the Commander goes and greets them... Oh, gosh...)",
	win_mvp = "",
	home = "Did you get the photos printed? Oh, you don't need to show me! They'll stop being cute if I get too excited about them...",
	unlock = "G-good day, Commander. I'm ready to be your model... Ugh, there's probably going to be an accident if I wish that you'll take cute photos... Better clear my head just to be sure.",
	touch2 = "Th-this angle might be a liiittle bit... *blushes*",
	mission = "",
	vote = "",
	drop_descrip = "G-good day, Commander. I'm ready to be your model... Ugh, there's probably going to be an accident if I wish that you'll take cute photos... Better clear my head just to be sure.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "This lantern wards off evil spirits, so I should make a wish? Oh... I won't, because my good and bad luck will probably just offset each other, so wish on my behalf... No, don't tell me your wish or it won't come true. Just wish for what your heart wants... *blushes*",
	main = "(The Commander's staring so much... No, probably at the camera moreso than me... So it's okay... Oh gosh...)|What about me do you think is so cute? I-I'm not saying I AM cute... Whew... I-if you want to take pictures, just go ahead...|You'll share your Lunar New Year luck with me? Th-thanks... I'll do my best to live up to your hopes this year!",
	touch = "Look into the camera with a confident smile? L-like this?",
	voice_key_2 = -1,
	mission_complete = "Hey, mission rewards have arrived. I'm fine staying like this, but are you?",
	battle = "As long as I'm fighting I won't have to have weird thoughts!",
	id = 402083,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Have we already started, Commander? ...You're looking for an angle to get a cute shot of me? M-me... cute... Oh, gosh... *blushes*",
	detail = "Lunar New Year is a day that brings good luck, because even a girl like me gets to be with you... Huh? It's nothing to do with luck, and entirely because I worked so hard for it? T-true... *blushes*",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[402100] = {
	hp_warning = "I shall not... be defeated by lesser beings!",
	feeling3 = "You're not half bad for a human. Even I acknowledge that, which is why I deign to obey your orders. What of it, you ask? I hope you don't think of me as below you in anything but name only.",
	mail = "We've got a new message. What did Eisen break this time, Regina? ...Oh, it's something else?",
	expedition = "(Roooar!) Silence, Regina! ...What's that? The commission team is back?",
	win_mvp = "(Roooar!) Now do you understand where you sit on the food chain?",
	home = "Tch, putting me through all this... No, I'm not talking about you. This is a problem between me and my rigging.",
	unlock = "I am the Iron Blood light cruiser Regensburg, wielder of the Darksteel Dragon— and I already know all of your tricks. Hahaha, do not think I will be so easily manipulated like the other girls! (Roooar!)",
	touch2 = "Someone needs to be disciplined...",
	mission = "Let your superior do the fighting, and in the meantime, you may do your so-called missions. It's decided then.",
	vote = "",
	drop_descrip = "M-class light cruiser – Regensburg.",
	feeling4 = "I won't accept it... I won't! I refuse to believe that commands from someone like YOU would draw out more of my power—What? You say this is your power, not mine? No... Do you mean to say... You're stronger than me?!",
	lose = "How could I lose to this... trash?!",
	feeling1 = "In the end, you humans deserve to be on the collar side of the leash. Know your place!",
	skill = "Roar, Regina!",
	upgrade = "Heheh. Are you sure you want to consolidate my power at the top of the food chain even further?",
	propose = "Kh! Why am I... unable to refuse a lower being such as you...? Damn it, how did you become... stronger, and more superior? ..A ring? Do you mean to tie me down?!",
	feeling5 = "To think that I, Regensburg, would lose to this... this Commander! What manner of monster are you?! If I continue to let you draw out my strength, that will make me your subordinate... This can't be!",
	main = "(Roooar...) What, Regina? Is it feeding time? Shouldn't you be taking a break as well?|Our balance sheet is... What kind of operation are you running here? Don't tell me you think it's okay to overlook such wastefulness.|Every faction has its own ways of breaking in their rigging. It's something you also might want to pick up on, just in case. Even if they won't help you fight, they might come in handy some other way.",
	touch = "Want to try petting Regina?",
	voice_key_2 = -1,
	mission_complete = "Rewards? Shame you won't get the chance to hoard them. Hahahaha!",
	battle = "Deploying rigging! Now, tremble in fear!",
	id = 402100,
	gift_dislike = "",
	gift_prefer = "Step aside, Regina. This is Commander's gift to me. ...Good grief, is it really that precious?",
	profile = "Iron Blood light cruiser, Regensburg. While I have no particular history to speak of, I'll prove that I'm not so easily controlled by you. Regina, let's show our inferiors what we're made of! (Roooar!)",
	voice_key = 40210,
	headtouch = "Wha?!",
	feeling2 = "Hahaha! I never thought it would be so funny to see an inferior being pushing their luck. Do not misunderstand; me disciplining my rigging and you giving me orders are two very different things.",
	login = "Hey, you're right on time. I wonder if you were born dutiful, or if someone had to whip it into you... Either way, get to work.",
	detail = "Well, well. So even you have a hard time handling my rigging. Unsurprising, a mere human cannot tame its great power. Heehee.",
	couple_encourage = {
		{
			{
				40206
			},
			1,
			" Support us, Regina!",
			0
		},
		{
			{
				49905
			},
			1,
			" Your sorcery isn't needed. Just leave this to me!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[402101] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "(Grooooowl...) Oh, is the commission team back already?",
	win_mvp = "",
	home = "Looks like Regina's having a good time with its friends. Why don't you take a break as well? Surely you're not trying to test the limits of your weary body.",
	unlock = "Wanted to feast your eyes on this, didn't you? Haha, there's no point trying to deny it. All your petty desires are clear as day to me, so why not just be honest about it?",
	touch2 = "Huh?! Wh-why do you know where my weak spot is...?!",
	mission = "A job? What job could be more important than enjoying your time off at the beach?",
	vote = "",
	drop_descrip = "Wanted to feast your eyes on this, didn't you? Haha, there's no point trying to deny it. All your petty desires are clear as day to me, so why not just be honest about it?",
	feeling4 = "",
	lose = "If only Regina were here, I wouldn't be bested by... the likes of you!",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "(You're looking at girls other than myself? Impossible! I'm clearly best-suited to be your... Huh?! What the hell am I thinking? How could I be... experiencing jealousy?!)",
	main = "Hm? What are you trying to... Hyeep?! G-get your hands off my tail this instant! Didn't you hear me?!|(Rooooar...) Looks like Regina's gone pretty far out to sea. Hope it doesn't run into any trouble.|Since you're here at the beach, surely you have a thing or two you'd like to do? Come on, let yourself loose already.",
	touch = "(That's right! Bare your weaknesses to me as I pretend to be subservient...!)",
	voice_key_2 = -1,
	mission_complete = "One can never get enough rewards. Same is always true regardless of what form they come in.",
	battle = "",
	id = 402101,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Hehe, even someone like you is powerless before my allure. Those ruled by their emotions are easy to control, just like riggings.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[402102] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Put the supplies the commission team brought here for now. We'll inventory the old stuff, and then we can sort them out.",
	win_mvp = "",
	home = "You got home and came straight here? How obedient. Check this area for me, then.",
	unlock = "Hmm... Who knew this stuff was in a warehouse, of all places? Heh, I think this will help quite a bit with disciplining that rigging that gave you so much trouble.",
	touch2 = "Tch! K-keep this up, and I...!",
	mission = "",
	vote = "",
	drop_descrip = "Hmm... Who knew this stuff was in a warehouse, of all places? Heh, I think this will help quite a bit with disciplining that rigging that gave you so much trouble.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Heh. You know, this style of discipline might work on lesser beings such as yourself, too... What?! You think I'm the one who needs to be disciplined?! U-unthinkable! I am superior – surely I can't lose to you again...!",
	main = "More pocket change... I've found quite a bit. Go find a piggy bank to put all this in, Commander.|I'd best go check on Regina. I had to leave her outside given how cramped it is in here... You ought to take a break, too. Go out for fresh air, if you want.|...Leave that stuff for now. It might be useful for disciplining naughty rigging.",
	touch = "What? Do you require my teachings as your superior?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 402102,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "A-a greater being such as I need no flattery!",
	feeling2 = "",
	login = "You're the one who offered to help me clean this place, so work! Or do you need discipline, too?",
	detail = "If we discipline the rigging as such, even if they do not become fully subservient... Hey, are you listening? Wh-why are you staring?!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[402110] = {
	hp_warning = "I can't let the Commander see me like this!",
	feeling3 = "(Hmm... The Commander's been a little cold to me lately. Does my makeup look bad, or...) Huh? O-oh, aren't you supposed to be reading paperwork? Why are you staring at me now...?",
	mail = "Hmm? Was that sound an unread mail notification?",
	expedition = "The commission girls are back. I hope they brought some fun gifts!",
	win_mvp = "All thanks to everyone's help, heheh♪",
	home = "Welcome back, Commander~♪ Did anything cool happen today? Come on, you know you wanna gossip.",
	unlock = "Well, well, we finally met. Commander, right? I'm Duisburg. Let's be great friends, okay? Heheh♪",
	touch2 = "C-Commander... No, I won't believe you if you say that was an accident.",
	mission = "You still haven't done your work? Heheh♪ About time you asked me for help, don't you think?",
	vote = "",
	drop_descrip = "M-class light cruiser – Duisburg.",
	feeling4 = "Huh? You think I suddenly look cuter? ...Heheh, I might've used a little magic... Just kidding♪ All I did was fix my makeup when you weren't looking. Do you like this lip gloss more? Get a closer look, if you want.",
	lose = "What the hell? This is the worst day EVER!",
	feeling1 = "Ahaha... I-I don't really get what you're saying. Should I look it up?",
	skill = "I'm not down yet!",
	upgrade = "Well, well. You made me stronger AND cuter!",
	propose = "Do you already wanna use the reward I promised you before? Heheh, feels like a bit of a waste, doesn't it? After all, I'd do whatever you wanted even without you using up your token... But it's too late to go back now. Let's get even closer♥",
	feeling5 = "Hey, Commander~ I hear there's a way to test someone's willpower. See, if I sit in your lap like this and give you a hug... If you last long enough, I'll give you a little reward♥",
	main = "You want to see my nails? Okay... Let's intertwine our fingers... Your skin tone looks great complimented by mine, Commander.|Liverpool told me about this popular restaurant's new drink menu. Gee, I sure wish I had someone to go with me♪ ...Aww, you will? Thank you!|I want to open my own shop someday, but I don't know what kind... Oh, you're interested? Then how about we brainstorm together?",
	touch = "Ooh, what is it? Got some gossip for me?",
	voice_key_2 = -1,
	mission_complete = "Ooh. Finished your missions, huh... Wanna check those rewards while they're still fresh in your mind?",
	battle = "I'm not losing, not today.",
	id = 402110,
	gift_dislike = "",
	gift_prefer = "I see you've been quietly observing my preferences? Thank you...",
	profile = "I'm Duisburg of the Iron Blood, and I've got all kinds of hobbies. Good-looking and good-tasting food, collecting cute and elaborate accessories... I'd love to open my own little shop one day. But right now, I only have eyes for you, Commander♪",
	voice_key = 40211,
	headtouch = "Huh? ...Whuh? What's gotten into you?",
	feeling2 = "I'm kinda bored. I had plans to go out with Dido, Zara, Pittsburgh, and Hipper later... You wanna come with, Commander?",
	login = "You came right on time. It kinda feels like we're meeting up for a date, huh?",
	detail = "Whoa~ So you're the kind of person to pry into someone's private junk right off the bat? Heheh♪ I don't mind sharing with you. You just have to tell me your own secrets in return.",
	couple_encourage = {
		{
			{
				30513
			},
			1,
			"Can you teach me to do my makeup better?",
			0
		},
		{
			{
				10324,
				20234
			},
			1,
			"How about we check out that shop we were talking about?",
			0
		},
		{
			{
				20204,
				20220
			},
			1,
			"Maid work sure is tough~",
			0
		},
		{
			{
				10328
			},
			1,
			"You should try this new juice I got!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[402111] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "O-obviously, I only won because of the Commander... I-I'm just telling the truth! That wasn't part of the training!",
	home = "Welcome back, Master. What drink would you... *sigh*... As if. We barely have any left at this time of day.",
	unlock = "C-Commander... Huh? If we're training, I should call you Master...? M-Master... You don't have to stare. Let's just get started, please...",
	touch2 = "You did that because I'm \"too cute\"? Bad excuse! I won't let you get away with saying that a second time... Okay?!",
	mission = "",
	vote = "",
	drop_descrip = "C-Commander... Huh? If we're training, I should call you Master...? M-Master... You don't have to stare. Let's just get started, please...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I know I'm only calling you Master during training, but... i-if you like it... I could keep doing that? Even after I finally open that shop I want... I'll say it whenever you want me to...",
	main = "M-Master... I'm okay. I'm the one who came up with this idea, anyway... Please keep training me, f-for the sake of the pop-up shop... Okay?|Don't you think this outfit's going a little TOO far? I know I'm the one who picked the wrong box of clothes, but surely you've noticed I'm not wearing this intentionally, right?!|W-wait... You want me to serve you drinks like this? No way, I can't do it...! I can't!",
	touch = "Ah?! ...I-if it please you, Master...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 402111,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Feels good, doesn't it? Yeah, I thought you might think so.",
	feeling2 = "",
	login = "Welcome back... Master. Huh? More passionately? I-I get it...! P-please continue to train me...",
	detail = "",
	couple_encourage = {}
