_G.pg.base.ship_skin_words[403010] = {
	hp_warning = "",
	feeling3 = "Huh? Worried about me? Having an idiot like you worry about me doesn’t make me happy at all.",
	mail = "Are you too stupid to realize that you have new mail?",
	expedition = "You idiot! You still haven’t remembered what you forgot about yet?",
	win_mvp = "Hmph. Just today, I shall allow you to praise me a little.",
	home = "Idiot! If you had already returned, why didn’t you come to see me? Hah? Who would be worried about you?",
	unlock = "Huh? You are the commander? Is the war effort going so poorly these days that they’re letting anyone become a commander?",
	touch2 = "Huh?! You stupid, moronic, block-headed idiot! Go die! Sink yourself in the Kiel Bay right now!",
	mission = "Don’t get distracted in the middle of a mission, you idiot!",
	vote = "",
	drop_descrip = "Admiral Hipper-class Heavy Cruiser, Admiral Hipper",
	feeling4 = "Huh? Who would ever have a crush on you? I’m only tagging along because Eugen wanted to have dinner with you. Don’t get the wrong idea, idiot!",
	lose = "C-c-c-curses! I can’t stand this, ahh!",
	feeling1 = "You piece of trash! I told you to stay out of my sight!",
	skill = "Huh? Who gave you permission to resist?",
	upgrade = "Hah? Did you think something like this would impress me?",
	propose = "Huh? Why must I wear something like this? Whatever... I’m in a good mood for a change. You’re going to take care of me forever? Hmph! Isn’t that what you’re supposed to do?",
	feeling5 = "Huh? Who would ever fall in love with you? I’m only here to drop off something I found during sortie, per regulations. Huh?! A ring? Who would wear something like that?!",
	main = "Blücher, I will definitely protect you this time.|Hah? A novice like you wants to challenge my cruiser-commanding skills?|Hah? Are the Schweinshaxe and beer ready yet? How many servings do we need? Idiot! Is your brain just an ornament?",
	touch = "Huh? Did I give you permission to touch me?",
	voice_key_2 = -1,
	mission_complete = "Idiot! Hurry up and collect your rewards! Why are you showing it off to me?",
	battle = "Compared to Jutland, a battle like this is mere child’s play.",
	id = 403010,
	gift_dislike = "",
	gift_prefer = "Haah?! You think something like that would make me happy?!",
	profile = "I am Admiral Hipper, the Iron Blood heavy cruiser named after the undefeated Admiral Franz von Hipper. I have participated in countless battles and given them my all. The Barents Sea? That only happened because Admiral Kummetz was even dumber than you.",
	voice_key = 40301,
	headtouch = "",
	feeling2 = "Huh? You can’t even do something like that? Are you an idiot?",
	login = "Idiot, so you rolled out of bed? Haah? What are you fantasizing about? I only happened to bump into you while patrolling the port.",
	detail = "What are you looking at, idiot? Get out of my room!",
	couple_encourage = {
		{
			{
				40303
			},
			1,
			"Who are you calling flat?!"
		},
		{
			{
				20114
			},
			1,
			"Please begin your performance, Glowworm!"
		}
	}
}


_G.pg.base.ship_skin_words[403012] = {
	hp_warning = "",
	feeling3 = "",
	mail = "There's a letter for you. Wow, that's a nice postcard... Never mind that, just read what it says already!",
	expedition = "Let me guess, you still haven't realized what's escaped your memory? ...Wrong! It's the commission, not which stores I want to visit!",
	win_mvp = "We won. Heh, I'm willing to give you the credit for the victory today.",
	home = "Whew, we're back. Time to dig in to some food before heading back to the onsen. You're worn out, and I'm just as worn out as you are!",
	unlock = "W-well? Does this kimono look good on me? ...R-really? Duh, I know it looks GREAT on me! Who really cares what you think... C-can't be me... No, I didn't say anything!",
	touch2 = "Yeah, I figured you'd like the pattern of– What the–?!",
	mission = "I don't care what spots you want to check out, focus on your damn missions! You're keeping ME waiting too, remember?!",
	vote = "",
	drop_descrip = "W-well? Does this kimono look good on me? ...R-really? Duh, I know it looks GREAT on me! Who really cares what you think... C-can't be me... No, I didn't say anything!",
	feeling4 = "",
	lose = "This isn't much of a story to tell the others... Ugh...!",
	feeling1 = "",
	skill = "",
	upgrade = "Isn't this much to be expected?",
	propose = "",
	feeling5 = "For the record, I never wanted to go here. This trip is for you – to reward all your hard work and give you a break... Huh? Me, enjoying my time with you? Wh-who decided it's got anything to do with you? I have the right to enjoy my visit irrespective of you!",
	main = "I've heard this type of kimono is famous. Makes sense, considering how much skill an artisan needs to create patterns and colors this complex.|It's wonderful feeling the breeze on your skin after getting out of the hot spring. It's so soothing, so cooling. You know what I mean, right?|Hmph! Eugen can poke fun at me all she wants – this is NOT a date! She's not gonna be so smug when I gloat about how great the hot springs were. \"It was sooo good! I left feeling like a new person,\" and so on!",
	touch = "Huh?! Grabbing a girl's hand without warning is a great way to startle her! At least tell me first!",
	voice_key_2 = -1,
	mission_complete = "Whoop-de-doo, you finished a mission. Good for you. Stop dawdling and go collect the rewards!",
	battle = "Thanks for making me work up a sweat!",
	id = 403012,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Which onsen do you want to go to today? I'd like to visit as many as possible so I can tell Eugen and the others all about the fancy places we've been to.",
	detail = "I can feel your gaze, you know... Would you stop ogling me like a painting? ...Huh?! \"You can't take your eyes off me\"? You say the stupidest damn things!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[403019] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "You're FINALLY back? ...What? I-I wasn't worried about you, no, you stupid, clumsy dummy! If you come back late again, I'll give you something to REALLY worry about!",
	unlock = "Hmph. Don't look at me like you missed me, or something! All I did was get my retrofit and come back stronger than ever... I-I wasn't waiting around for you to come looking for me! I was just passing through, you dummy!",
	touch2 = "Idiot! Big dummy! How dare you... I-I'm gonna feed you to the fishes!",
	mission = "",
	vote = "",
	drop_descrip = "Hmph. Don't look at me like you missed me, or something! All I did was get my retrofit and come back stronger than ever... I-I wasn't waiting around for you to come looking for me! I was just passing through, you dummy!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Only a huge idiot like you could get me to hang around... D-don't get a big head about it! I just think it's not so bad fighting alongside you! ...Aaargh, look what you've got me saying! Just wait until I get my hands on you!",
	main = "What? You wanna know if I'M ready? Don't be stupid! As if I'd ever slack off – you're the one who needs to get off your butt and keep up with me!|I left some food on your desk, so you'd better check it out! You don't get to neglect yourself just because you're busy!|Come over here, dummy. You look pale. Are you okay? Don't get any weird thoughts – I'm just worried because we need you in top condition for the next battle!",
	touch = "Hey, if I'm the one who got retrofitted, why are YOU the one acting overconfident? Going around touching me all willy-nilly... I'd better teach you a lesson!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Know your place, or get out of my sight!",
	id = 403019,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "H-hey, who gave you permission to touch me?! Wh-why, you... You're going to pay for that one!",
	feeling2 = "",
	login = "What're you dawdling there for, dummy? I didn't get stronger just so you could laze around! Get up and get this battle situation sorted out! I'm not waiting any longer!",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[403020] = {
	hp_warning = "Anything's possible when you have love!",
	feeling3 = "Heheh☆ Every time we touch, my heart beats so fast and I swear I could fly! Oh wait, my rigging actually does take me higher♪",
	mail = "Heheh☆ You've got new messages... including a love letter from me! Don't forget to read it!",
	expedition = "The commission team is back~ Wonder if they found any goodies out there?",
	win_mvp = "Heheh☆ Crushiiing victory!",
	home = "Heheh☆ Welcome back, Commander! Gimme a hug~! Ehehe~",
	unlock = "Heheh☆ It's me, Blücher, reporting in to serve my sweet, sweet Commander♪",
	touch2 = "Heheh☆ No comparing me to anyone else~♪",
	mission = "Heheh☆ It's time we started practicing the art of love, Commander!",
	vote = "",
	drop_descrip = "Admiral Hipper-class heavy cruiser – Blücher.",
	feeling4 = "I need hugs from you to get the energy to do anything... Heehee~ Hold me closer~ Clooooooooser!",
	lose = "Bweh... Only a kiss from my Commander can get me back on my feet...",
	feeling1 = "Something's wrong with you... but I still love you!",
	skill = "Look what my love for my Commander can do!",
	upgrade = "Heheh☆ Have you fallen even deeper in love with me?",
	propose = "Heheh☆ I've waited forever for this day! So, are you ready to embrace every last bit of me, Commander? Me... I'm as ready as can be♪",
	feeling5 = "Heheh☆ I love you so, so, soooo much, Commander! When can we go on a date again? Next month? Next week? Tomorrow? I can't wait that long, so let's go on one in five minutes! Hehehehe~",
	main = "Hipper, don't you wanna cuddle with the Commander too?|Aim for the Commander's heart aaand... all-love assault!|Being able to meet you is like a dream come true! Mmhmm, I've never been happier!",
	touch = "It's me, the girl who's more in love with you today than she was yesterday~",
	voice_key_2 = -1,
	mission_complete = "Heheh☆ Another unforgettable memory made with you!",
	battle = "As long as you keep your eyes on me, I'm toooootally invincible!",
	id = 403020,
	gift_dislike = "",
	gift_prefer = "Heheh☆ It smells like Commander!",
	profile = "Heheh☆ I'm Blücher of Iron Blood, second ship of the Admiral Hipper class~ Yup, I'm the one who got totally whooped by fortress guns in Operation Weserübung! And you, Commander, are the source of my endless happiness~",
	voice_key = 40302,
	headtouch = "",
	feeling2 = "Heheh☆ What a beautiful day~ Hop on my rigging and we'll go have a wild time, Commander!",
	login = "Heheh☆ Doesn't seeing me make you all happy?",
	detail = "I only joined this fleet 'cause I'm so in love with you, Commander! You feel the exact same way about me, don't you~? Heheh☆",
	couple_encourage = {
		{
			{
				40301
			},
			1,
			" C'mon, Hipper! There's nothing wrong with admitting you're in love!",
			0
		},
		{
			{
				40303
			},
			1,
			" Heheh☆ I'm gonna make you a blondie!",
			0
		}
	}
}


