_G.pg.base.ship_skin_words[403022] = {
	hp_warning = "",
	feeling3 = "",
	mail = "New letter for... No, no, no! Don't use your fire breath on it! My love letter to the Commander is in there!",
	expedition = "Hmm... Being on this dragon gives me a great view of where everyone is! Let's go say hi to the girls!",
	win_mvp = "",
	home = "I-I'm back, and I'm still alive...",
	unlock = "Heheh☆ I'm Blücher, dragon knight of the Demon King's army! ...Not riding the dragon so much as being dragged along by it? Well, I guess... Whoaaah! The dragon won't obey me! Commander, heeelp!",
	touch2 = "Huh?! You wanna do it NOW? A-at least wait until my dragon has taken off smoothly...",
	mission = "Heh, heheh☆ Come on, get those missions done and come rescue me!",
	vote = "拉票描述",
	drop_descrip = "Heheh☆ I'm Blücher, dragon knight of the Demon King's army! ...Not riding the dragon so much as being dragged along by it? Well, I guess... Whoaaah! The dragon won't obey me! Commander, heeelp!",
	feeling4 = "",
	lose = "Hrmgh... Being a dragon knight is sooo hard! Commander, the only way to cure my hurt feelings is for you to kiss me!",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "You wanna visit all kinds of places with me,? Heheh♡ Of course we can! Where do you wanna go, my super sweet sweetheart? My dragon can take us anywhere in this vast, vast world! Whenever you're ready, let's go!",
	main = "You don't think I FEEL like a soldier of the Demon King? Hmph. I do wanna learn to look like one, but– No, no, no! I'm gonna fall again!|Heheheh☆ You're safe with me, my number one sweetie! How's that? Don't you feel super duper safe around me? ...Not at all? Aww...|Dragon's breath! Did you feel the heat? Heheheh☆ My love for you burns just as bright as the dragon's– Whoa, whoooa!",
	touch = "Commander, do you wanna steer the dragon? I'll let you do anything you want! Well... probably!",
	voice_key_2 = -1,
	mission_complete = "Heheh☆ We made a nice, new, and slightly chaotic memory together!",
	battle = "Dragon knight! Los, los!",
	id = 403022,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Heh, heheh... Commander, you ready to mount the dragon and feel the breeze?",
	detail = "I've wanted to soar the skies together with you before, but I never imagined we'd be doing it on a dragon. Heheh☆ Hold on to me tightly, Commander! You might fall off if you– Whoooah!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[403023] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Heheh☆ Commander, I studied reeeally hard today! Take me on a date after school as a reward for my hard work!",
	unlock = "Heheh☆ I KNEW you'd come to see me, Commander! Next time, you don't need to rush to my side after getting my message, okay? I'll give you as much time as you need, because the last thing I wanna do is tire you out, my super-duper mega sweetheart!",
	touch2 = "Eek! We're still in class, you know... Heehee – if that's how you want it, then two can play at that game!",
	mission = "",
	vote = "",
	drop_descrip = "Heheh☆ I KNEW you'd come to see me, Commander! Next time, you don't need to rush to my side after getting my message, okay? I'll give you as much time as you need, because the last thing I wanna do is tire you out, my super-duper mega sweetheart!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Commander, you can always rest your head on my lap whenever you feel tired. My thighs are a VIP seat exclusively for you, my super-duper mega sweetheart! ...But it's late? Doesn't matter to me! As long you're with me, I'm fine with staying here until morning!",
	main = "Commander! Look! The sunset is so beautiful today! We can't just let something so picturesque go to waste – come here and let's take a selfie! Three, two, one – cheese!|Surprise examination! Let's see what your note on my contact profile says... Huh? You didn't write anything?! Well, in that case... Write \"I love you so, so, so, sooo much, Blücher\"!|Commander, lower your head for a sec. I'm gonna wipe your sweaty forehead. Hm? My hanky? I use this thing all the time, y'know! You can have it if you want it!",
	touch = "Heehee! This massage is... kinda making me feel ticklish! Ahahah! Hey, not there! Ahahahahaha!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 403023,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "I won't settle with just some headpats for my reward! Okay, as punishment for you, you have to let me hug you for 10 minutes straight!",
	feeling2 = "",
	login = "Heheh☆ Commandeeer! Why are you sitting all the way over there? Come closer! Closer, closer! There we go! Now I can give you a biiig hug!",
	detail = "Commander! I've still got time, so let's go somewhere! How about downtown? Or the arcade? Or maybe... Huh?! You're gonna go home and do homework of all things?!",
	couple_encourage = {}
}


