	login = "\"Welcome back. What'll be your order?\" Is that what you were expecting? Heehee.",
	detail = "Would you like me to call you something else? Hmm, how about \"mein Schatz♡\"—Well? Hehehe♪",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[403036] = {
	hp_warning = "",
	feeling3 = "",
	mail = "A message? At a time like this?",
	expedition = "The commission is done? I wonder if they brought those electrolyte drinks I asked for...",
	win_mvp = "",
	home = "*sigh*... Hnngh~ Welcome back, Commander. I just finished my training, and I'm all sweaty now... Heheh, hey, wanna go clean up in the shower together?",
	unlock = "*pant*... Quarterback Prinz Eugen scores a touchdown. I can't believe I'm the one charging in now... Commander, can you bring me water and a towel? I'm getting a little sticky from all this sweat...",
	touch2 = "Commander, I'm still in the middle of the game. At least control yourself until half-time♥",
	mission = "Hmm, it looks like you've got some unfinished training tasks. Want me to check them out with you?",
	vote = "拉票描述",
	drop_descrip = "*pant*... Quarterback Prinz Eugen scores a touchdown. I can't believe I'm the one charging in now... Commander, can you bring me water and a towel? I'm getting a little sticky from all this sweat...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "You've been staring for a while now... Commander, was getting invited to practice all a part of your plan? Okay... Then let's practice our \"touchdowns\" together even more, why don't we?♥",
	main = "Phew... I am tired, but it's not that bad. After all, my reliable Commander is here to soothe me! How? With a kiss, of course♥ Heheh!|Hey, do we have any cooler clothes? I always get really sweaty during games... It's fine because you'll wipe it up for me? Well, isn't that reassuring?|Do you think we can use touchdowns in any other situations? For example, if I get on top of you like this... Heheh, ahahaha! Look at you blushing. I guess I scored, huh?",
	touch = "A massage? I'm fine. Besides, wouldn't it bother you that I'm so sweaty?",
	voice_key_2 = -1,
	mission_complete = "Mission rewards might not be as glamorous as winning the big game, but don't forget to grab them, too.",
	battle = "",
	id = 403036,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Phew... Commander, there you are. Hey, can my touchdown song go like this? \"Mutig, stark, siegesklar!\"",
	detail = "This sport is a lot more taxing than I thought... I'm in such breathable clothes, and I'm still soaked from sweat. Commander, do you have any bright ideas?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[403037] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "We should pop a bottle to celebrate. You won't let a single drop go to waste, right, Commander?",
	home = "Oh, you're back. Let's pick up where we left off. I've selected several brands of whiskey. Which one will you be trying first?",
	unlock = "You sure seem to be enjoying yourself, Commander. Heehee – what amusing thing will you do next, I wonder? ...Me? Don't pay me any mind. I just want to see what you're like when you're drunk!",
	touch2 = "So you finally feel like revealing your true self? Nicht schlecht♪",
	mission = "",
	vote = "",
	drop_descrip = "You sure seem to be enjoying yourself, Commander. Heehee – what amusing thing will you do next, I wonder? ...Me? Don't pay me any mind. I just want to see what you're like when you're drunk!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Es ist interessant... Heehee. You know, it's unusual for a person not to have a second side like you. Come here. I need to \"watch\" you on a deeper level.",
	main = "Well, well, look who doesn't seem drunk in the slightest. Let's see if you're really made of stronger stuff♪|Pretty nice mood in here, don't you think? Also... We're all to ourselves. No need to hold yourself back any longer.|I've heard drinking several alcohols mixed together gets you wasted easily, but don't even think about trying it. Heh – I'll be happy with just seeing you tipsy.",
	touch = "Seems we got physically close without realizing it... Heh. This is the perfect distance for watching you.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 403037,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Hoping to distract me? Heheh. You're gravely mistaken if you think it'll be that easy.",
	feeling2 = "",
	login = "You've seen me drunk before, haven't you? Well, now it's time for ME to see YOU drunk.",
	detail = "You honestly hold your liquor much better than I expected... Ah, no, I'm your personal bunny girl – heehee. By the way, want another glass?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[403038] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Receiving a lot of mails….after all, you're the Commander, a really popular one, huh.",
	expedition = "",
	win_mvp = "",
	home = "Commander, the bathtub has been filled with hot water, so who goes first, or…?",
	unlock = "If fate brought us together, then it has my thanks… I look forward to our future together~",
	touch2 = "",
	mission = "All these missions….you pick Commander...I’m ready for them all~",
	vote = "",
	drop_descrip = "If fate brought us together, then it has my thanks… I look forward to our future together~",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Ugh... my body suddenly feels so weak... I’d only recover if you give me a kiss, Commander. | Don’t overstretch yourself at work ~ otherwise… my loneliness will drive me to tease you.| I feel so lucky right now --- why you ask? Take--a--guess, dear?",
	touch = "I know what’s on your mind, Commander...but we need to focus on work right now.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 403038,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, you did not happen to peek at other girls while on the way here, right? ~~",
	detail = "In Ironblood, we also use animal nicknames to call our lovers, like teddy bear or little bunny or something else. So Commander, do you want me to call you teddy bear or little bunny?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[403040] = {
	hp_warning = "Do not underestimate the great Deutschland!",
	feeling3 = "Lowly animal, root around for all you are worth to find something worthy of my attention. Ahahahaha~",
	mail = "You've received a letter in that lowly animal language of yours. Fetch~",
	expedition = "Hmph, so our little lambs managed to complete their commission. What a pleasant surprise.",
	win_mvp = "Even though the enemies were no big deal... what a pompous affair.",
	home = "Pay attention, you idiot! Just because we're back at port doesn't mean that you're done.",
	unlock = "From now on, you are Deutschland's servant! You should feel honored. Also, don't answer me with \"mhm.\" You will answer me with \"yes, ma'am\" from now on. Are we clear?",
	touch2 = "Hmm? It seems like you're enjoying yourself... do you get off to this kind of stuff?",
	mission = "Mission! There's no entry for \"incomplete\" in my dictionary!",
	vote = "",
	drop_descrip = "Deutschland-class armored cruiser, Deutschland.",
	feeling4 = "A lion doesn't concern itself with the bleating of sheep. But... I do find you interesting for a lowly animal. If you amuse me some more, maybe I will listen to your wishes.",
	lose = "I'd sink to the bottom of the ocean before surrending to you animals!",
	feeling1 = "I have no interest in you anymore... I should find myself a new pet.",
	skill = "Cruel and lovely, ahaha...",
	upgrade = "Aren't you the obedient animal~",
	propose = "I never thought the day would come when I pledge myself to a lowly animal. I've never felt anything like this before... but it's unexpectedly fun. Ahahaha~! From now on, you're my vehicle number two! You should be grateful!",
	feeling5 = "For keeping me amused this long, I shall grant you the privilege of holding me. Why are you still standing there? Have you never heard of a princess carry? Princess~ carry!",
	main = "It seems like I must speak in a way that even lowly animals can understand.|Hahaha! I didn't even need to fire my gun to scare off those cruisers~|If you insist on standing around like an idiot, I'm just going to leave.",
	touch = "You just never learn, do you? Do you want to taste my whip again that badly~?",
	voice_key_2 = -1,
	mission_complete = "Hurry up and fetch the rewards for me~",
	battle = "I'm going to enjoy mopping you all up~",
	id = 403040,
	gift_dislike = "",
	gift_prefer = "Hmm~♪ Not too bad!",
	profile = "Hmph! I'm Deutschland, the first ship of the Deutschland-class! A prestigious individual such as myself wouldn't be sent into smaller battles. As such, it's only natural that I don't have many of these petty achievements. It's called spiritual leadership! Hmph! Lützow? ...Shut up! Like I'd care about that!",
	voice_key = 40304,
	headtouch = "",
	feeling2 = "There is no thrill like waging war with a grin on your face! There's no way a lowly animal like you could ever understand that! Ahahahaha!",
	login = "You sure took your sweet time. Just where were you rooting around?",
	detail = "It's times like these... where I simply must punish you.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[403041] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Scream in agony! Tremble in fear! Kneel before me! Ahahaha! ",
	home = "You've done well for a slave. Come forth, I shall give you a little reward.",
	unlock = "For such a lowly animal, your taste is not bad... That's right, I am Deutschland, Demon Princess of the Iron Blood and Mistress of the Night! Plebeians, no, my slaves, I shall grant you an opportunity to swear fealty to me with a kiss!",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "For such a lowly animal, your taste is not bad... That's right, I am Deutschland, Demon Princess of the Iron Blood and Mistress of the Night! Plebeians, no, my slaves, I shall grant you an opportunity to swear fealty to me with a kiss!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Imbecile! I only wore this costume as a hobby. Who gave you permission to serve me such a repulsive beverage? |nil|Slave, help me get off my throne. Shorty? You imbecilic swine, do you think this is funny?",
	touch = "Slave, offer your neck to me so that I may feed... Ahahaha! Imbecile, surely you didn't take me seriously!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "I shall engrave my name into your bones!",
	id = 403041,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "",
	detail = "Slave, come here... Do not fear, these little bats won't hurt you.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[403042] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "What's with that lax expression of yours as soon as you get back... Ho ho, do you need your master to \"tighten up\" those loose morals of yours?",
	unlock = "One must not neglect sunscreen during the summer... Plebeian, if you wish to serve your master, prostrate yourself and yell \"I beg of you, Queen Deutschland\" three times, and I might consider giving you an opportunity. Ahahaha~",
	touch2 = "Ho ho, it looks like this lowly swine cannot even control its basest desires.",
	mission = "",
	vote = "",
	drop_descrip = "One must not neglect sunscreen during the summer... Plebeian, if you wish to serve your master, prostrate yourself and yell \"I beg of you, Queen Deutschland\" three times, and I might consider giving you an opportunity. Ahahaha~",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Plebeian, fetch those two towels over there and wipe my body dry. |If your eyes wander any lower, they will get detached from their sockets. I say, there is no remedy for being uncultured swine~ |A lifebuoy? What would I use that for? Plebeian, were you not going to carry me on your back while swimming?",
	touch = "To think that a plebeian would look at me with such a hungry, bestial expression. A lewd beast like this needs a thorough flogging.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 403042,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Way! Too! Slow! Are you trying to get my pristine skin sunburnt?",
	detail = "Lazy swine, don't cut corners. Anything less than a perfectly uniform application of sunscreen is unacceptable! ",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[403043] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Getting mail right now sure spoils the mood. Let me see those!",
	expedition = "",
	win_mvp = "You should feel honored to have the privilege of being ravaged by the one-and-only Deutschland while she is in a good mood!",
	home = "Let's be clear here, I was not waiting for you. I simply can't show off the full extent of my grandeur as a master without the presence of my lowly animal.",
	unlock = "I seem pleased? Of course I am. Why wouldn't I be when my sweet little sister will be joining us at the party? Now shape up and entertain your master, you lowly animal! Ahahahaha!",
	touch2 = "",
	mission = "Missions? What mission could possibly be more important than accompanying your master to the banquet?",
	vote = "",
	drop_descrip = "I seem pleased? Of course I am. Why wouldn't I be when my sweet little sister will be joining us at the party? Now shape up and entertain your master, you lowly animal! Ahahahaha!",
	feeling4 = "",
	lose = "I have a banquet to attend, so I have no time to let myself get dragged through the mud by you lot~",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Lowly animal, you may offer your opinion about me and Graf Spee's dresses. Hmph, I bet your vocabulary doesn't include anything beyond \"cute,\" ahahaha! |Ehh? Graf Spee is actually talking to people from other factions...? I hope she's not being bullied... I'll have to give them a stern warning just in case... |Tell me, lowly animal, why does everyone greet me instead of cowering in fear? ...Because they like me? R-really... Hmph. As a spiritual leader, it's only natural to be respected by all!",
	touch = "Dancing? Aha~ I just knew you'd come to me with this request, so I prac... err, prepared beforehand!",
	voice_key_2 = -1,
	mission_complete = "Hmph... After seeing these rewards, I'll let you live.",
	battle = "",
	id = 403043,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Still sluggish as always. But because I'm in a pretty decent mood today, I'll forgive you!",
	detail = "What belongs to my lowly animal also belongs to me. Therefore, the stronger my lowly animal's fleet is, the clearer the proof of my excellence is.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[403044] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "You lowly animal! For how long do you intend to ignore me?!",
	unlock = "Why are so many people out and about during a holiday? ...That's it! Lowly animal, was it your idea to prepare all this to surprise me...?! Heh... Hehe, that's right, don't you dare disappoint me!",
	touch2 = "Hahah, do you yearn for my punishment that badly, lowly animal?",
	mission = "",
	vote = "",
	drop_descrip = "Why are so many people out and about during a holiday? ...That's it! Lowly animal, was it your idea to prepare all this to surprise me...?! Heh... Hehe, that's right, don't you dare disappoint me!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "If Spee wasn't so dear to me, I would've never even *considered* building a snowman!|Oh lowly animal, your master is hungry. I've heard that the Dragon Empery's cuisine is very delectable... You know what to do now, yes? Ahahahahah!|So much noise... Oh lowly animal, go outside and check what happened!",
	touch = "Are you trying to touch my stole? I have no memory of granting a lowly animal permission to do that!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 403044,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "There you are, lowly animal. Now help me take off these heels! Strolling around in these things is so tiresome...",
	detail = "The decor in here is truly sumptuous... Hahahah! It further raises the pedestal of eminence atop which I sit! Isn't that right, lowly animal? Ahahahaha!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[403050] = {
	hp_warning = "I have to hold out just a little longer...!",
	feeling3 = "These hands are for grasping victory... Even though I will never again be able to hug the people important to me, what's done is done.",
	mail = "This letter... Thank goodness, it has nothing to do with Renown.",
	expedition = "A commission has been completed? That means they weren't ambushed. Thank goodness.",
	win_mvp = "How long will this victory actually last...",
	home = "Commander, you've confirmed the port isn't being blockaded, right?",
	unlock = "No matter where I go, the war never ends... Deutschland-class armored ship number 3, Admiral Graf Spee, reporting for duty.",
	touch2 = "Commander, may I hug you, even though my hands are like this?",
	mission = "Once we've been assigned a mission, we must complete it, no matter what it is.",
	vote = "",
	drop_descrip = "Deutschland-class armored cruiser number three – Admiral Graf Spee.",
	feeling4 = "Commander, rather than sink all alone, will I be able to face my final moments together with you this time?",
	lose = "We've lost... But I'm not giving up! It's not over yet!",
	feeling1 = "No matter how you treat me, Commander, I will obey you...",
	skill = "In the name of all that is dear to me!",
	upgrade = "So this is... power...",
	propose = "Although I cannot hug you, you can hug me... Hey, Commander, just for a little longer... hold me tight like this...",
	feeling5 = "No matter how much I fight, I can't fill the void in my heart... And being away from you is the reason why...",
	main = "Wars don't exist for mindless slaughter, they exist for victory.|One's first battle being their last... That sort of thing isn't all that unusual for us Iron Blood ships.|Give talking to people... a try? I've always been alone, so what am I supposed to talk about...",
	touch = "It's sunny today? Yeah... just like it was back on the Río de la Plata.",
	voice_key_2 = -1,
	mission_complete = "I see that, unlike me in the past, you actually finished your mission.",
	battle = "For the honor and prosperity of Iron Blood, and for even greater glory!",
	id = 403050,
	gift_dislike = "",
	gift_prefer = "Thank you... It's perfect for a long journey.",
	profile = "Admiral Graf Spee, Deutschland-class armored cruiser number 3 of the Iron Blood Navy. I was attacked by Royal Navy cruisers and then took refuge in Montevideo, but in the end I scuttled myself... Commander, this time I'm going to fight! To the very end!",
	voice_key = 40305,
	headtouch = "Commander, could you not ruffle up my hair like that...?",
	feeling2 = "I sailed alone, fought alone, and sunk alone... Although I am who I am, didn't I still contribute to Iron Blood's cause?",
	login = "I will fight for you till the very end.",
	detail = "No matter how poor the odds are, I will always head for the battlefield. ...That way people will admire me.",
	couple_encourage = {
		{
			{
				20401
			},
			1,
			"Stay away from me...",
			0
		},
		{
			{
				20203
			},
			1,
			"You're still a dirty sadist, I see.",
			0
		},
		{
			{
				40401,
				40402
			},
			1,
			"It's an honor to fight alongside you again.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[403051] = {
	hp_warning = "",
	feeling3 = "",
	mail = "This mail... it's not another one of Ajax's pranks, is it?!",
	expedition = "",
	win_mvp = "",
	home = "",
	unlock = "I sailed alone, fought alone, and then I was sunk while being alone. Now I found a new beginning... Hmm? Commander, you've been staring and laughing at me since the beginning… do you want to eat this?",
	touch2 = "...You're making me angry.",
	mission = "",
	vote = "",
	drop_descrip = "I sailed alone, fought alone, and then I was sunk while being alone. Now I found a new beginning... Hmm? Commander, you've been staring and laughing at me since the beginning… do you want to eat this?",
	feeling4 = "",
	lose = "Can I... count on you...?",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Does getting a hug from me like this cheer you up a little, Commander?",
	main = "My pantyhose? Ajax gave me them as an enrollment gift... I examined them very thoroughly and didn't find anything weird, but I doubt they're just a normal pair of stockings...|Viersechs doesn't like picture books? I see... Everyone else in the Z-class seems to like them, though...|Hipper? Want some snacks? I get it. \"Not really\" means \"yes\" in your dictionary. Okay, say \"aah.\"",
	touch = "Deutschland? Could you stop using your megaphone to shout \"people who harass the girl with my phone will be expelled\"... It's embarrassing, and more importantly, it's really distracting...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Don't go around disturbing the girls at the academy.",
	id = 403051,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Eugen taught me how to use makeup, but... does it actually make me look pretty...?",
	detail = "I'm trying hard to learn about everyday things. Living a normal life is not so simple, compared to fighting...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[403052] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Prinz Eugen is surprisingly clumsy with this kind of stuff. She's still chicken-pecking with one finger.",
	expedition = "",
	win_mvp = "Commander, can you take a picture to celebrate me getting MVP? I want to show it to my friends!",
	home = "Welcome back! Cellphones are totally amazing, aren't they? No matter where we are, we can contact each other with the press of a button!",
	unlock = "I never dreamt that I'd be able to don this outfit and live a normal, peaceful life... Thank you, Commander...",
	touch2 = "Commander, I want to give you a hug too~",
	mission = "",
	vote = "",
	drop_descrip = "I never dreamt that I'd be able to don this outfit and live a normal, peaceful life... Thank you, Commander...",
	feeling4 = "",
	lose = "I knew it... this totally reduces my fighting capabilities...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Ajax... You're not pulling my leg this time, are you?|Hipper is a totally different person on the internet compared to how she is in real life. Maybe she just has trouble expressing herself around people she cares about...|Miss Illustrious, could you teach me how to make tea? Admiral Hipper invited me to a tea party between the Royal Navy and Iron Blood, but I've never brewed tea before...",
	touch = "Thanks to Juustagram, even people like me who aren't very sociable can still chat with everyone... Oh look, Graf Zeppelin just made a new post!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "To protect everyone who has shown me so much kindness... I won't let you take a step closer!",
	id = 403052,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Welcome back, Commander! Um... I heard from Ajax that you have a very \"special\" hobby... but what kind of hobby is it?",
	detail = "I'm so glad that I can finally practice cooking! I want to give something back to all the kindhearted people here!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[403053] = {
	hp_warning = "",
	feeling3 = "",
	mail = "I know the party is still going on, but you still have to check your new mail.",
	expedition = "",
	win_mvp = "",
	home = "Not everyone in the Royal Navy is like Ajax. I can actually have a productive conversation with most of them...",
	unlock = "It's so fancy, so formal... Is this a \"party\"? I'm not sure I'll be able to fit in... But if you'll go with me, Commander, I'll give it a try!",
	touch2 = "Commander, people are staring at us.",
	mission = "",
	vote = "",
	drop_descrip = "It's so fancy, so formal... Is this a \"party\"? I'm not sure I'll be able to fit in... But if you'll go with me, Commander, I'll give it a try!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Thanks to all the friends I have now, I don't feel lonely anymore. And my encounter with you might be the happiest moment of my life. Ahahah~",
	main = "Ajax... She's not planning something weird for the party, is she?|Everyone here is having so much fun... I could never even imagine my past self being at a place like this.|Commander, my friends are calling for me. Could you excuse me for a bit?",
	touch = "Commander, am I in time with your steps?",
	voice_key_2 = -1,
	mission_complete = "",
