_G.pg.base.ship_skin_words[403054] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Commander, I got a new offer. Should I take it?",
	expedition = "",
	win_mvp = "Commander, can we go home now?",
	home = "\"Commander, you did so well...! Commander, keep at it...!\" That should be idolish enough, right?",
	unlock = "My sister just wouldn't stop bugging me, so I finally caved and agreed to do this... Anyways, all I have to do is get up on stage and sing, right?",
	touch2 = "Commander, have you forgotten what my hands can do?",
	mission = "",
	vote = "",
	drop_descrip = "My sister just wouldn't stop bugging me, so I finally caved and agreed to do this... Anyways, all I have to do is get up on stage and sing, right?",
	feeling4 = "",
	lose = "Have we been spending too much time on idol lessons...?",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "There was a time when I wanted nothing more than to break these claws off my hand. But now, I feel pretty good about all this \"idol\" stuff... Commander, I never thought it could ever live like this. Hehe.",
	main = "Um... Maybe it's because I'm so used to working with everyone, but I feel like it's actually pretty easy being onstage.|Commander, do you think you can stop my sister from getting everyone to hold up those \"World's♡Cutest\" signs when I go on? It's really embarrassing...|Idols are there to make people smile... I never thought I could do something like that.",
	touch = "These hands are no longer weapons of war, but for returning the admiration of my fans. Right, I can do this...!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "We're not done with the lesson yet...",
	id = 403054,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, do you mind if I practice here?",
	detail = "My sister's always pushing this \"for the glory of Iron Blood\" stuff onto me. Can't she do this idol stuff herself...?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[403070] = {
	hp_warning = "I'm not done yet!",
	feeling3 = "Here, my schedule... Huh?! Look, anyone can do this kind of simple bookkeeping. It's not like I need you or anything!",
	mail = "Huh? Shouldn't you be in charge of vetting the fanmail?!",
	expedition = "What are you spacing out for? The commission fleet is back, and you're coming with me!",
	win_mvp = "If that's the best you can do, I should've just stayed home!",
	home = "Haah?! You big idiot, you took so long to come back that I was getting worr... Wait, what the heck am I saying?!",
	unlock = "Huh? Why are you staring at me like I'm some weirdo? I'll have you know, it's not like I wanted to do this or anything!",
	touch2 = "H-haah?! You did that on purpose, didn't you?!",
	mission = "Mission or offer, it's all the same to me. Let's just get it out of the way!",
	vote = "",
	drop_descrip = "Huh? Why are you staring at me like I'm some weirdo? I'll have you know, it's not like I wanted to do this or anything!",
	feeling4 = "Ahh, ahh... I'm doing pretty good today... H-huh?! Who gave you permission to watch me?! I just happened to have some free time, that's all! Go away and take care of your own work!",
	lose = "Gaaah! I'll remember this!!",
	feeling1 = "Huh? There's no way I'd be able to work with an imbecile like you!",
	skill = "I'll have you pay close attention to my performance!",
	upgrade = "Eugen, just you wait! I'll show you what I'm capable of!",
	propose = "H-huh?! Who would want a ring like this... Guh...! F-fine, you can p-put it on... Happy now? Let's wrap this up already. The stage we're aiming to be on is much loftier than this!",
	feeling5 = "So, what's next on the agenda? You should already know, right? ...If you know, then hurry up and spit it out! Screw you! Stop teasing me already...!",
	main = "Hey idiot, tell me what's next on my schedule! How long do you intend to keep me waiting? |Deutschland, it's fine to be proud of your sister, but have some self-control! ...Jeez, you're so lucky to have such a reliable sister... Meanwhile, look what I'm stuck with... |Huh? Who asked you to be my publicist? I'll earn my own fans!",
	touch = "Haah? Who gave you permission to touch me?!",
	voice_key_2 = -1,
	mission_complete = "Rewards, huh... It'd be better if Eugen wasn't constantly trying to get on my nerves...",
	battle = "I'm gonna show you what I'm made of!",
	id = 403070,
	gift_dislike = "",
	gift_prefer = "You know exactly what I want, huh? Thank you~♪ Mwah~",
	profile = "I'm the mightiest heavy cruiser in the world, Admiral Hipper of the Iron Blood. It's not like I wanted to do this or anything, I just had no say in the matter.",
	voice_key = 40307,
	headtouch = "",
	feeling2 = "I'm just laying this out there - if we're going to do it, then we're going to do it properly! I don't want a half-baked job... Hey, pay attention!",
	login = "Lessons are finally done for the day. Good grief, why'd I ever agree to do this...!",
	detail = "...My guitar sounds a bit off today... Huh, try tuning it? Nah, that's not it, I just have to warm up a bit more...",
	couple_encourage = {
		{
			{
				90503,
				10224,
				30710,
				20225
			},
			2,
			"You'd better not drag me down!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[403080] = {
	hp_warning = "You're in the way... and you will pay!",
	feeling3 = "I feel a certain emptiness after working at this idol thing for a while... Maybe it's the combat... could it be because I can't sink as many as I used to...?",
	mail = "You've got mail~ I wonder what's inside?",
	expedition = "The commission girls are back. Would you like to try, Commander? Line up for hugs, everyone~",
	win_mvp = "Oooh this feeling... when I tear them to pieces...!",
	home = "Well fought. I got you a little something to eat, just as a way of saying thanks for all the training~",
	unlock = "Heavy cruiser Roon, reporting for idol activities and associated experimental equipment testing. Today, we fight not with fire and sword, but with the power of song.",
	touch2 = "Let's enjoy some \"intimacy\" a little later~",
	mission = "A combat mission? Yes! I'd love to join~",
	vote = "",
	drop_descrip = "Heavy cruiser Roon, reporting for idol activities and associated experimental equipment testing. Today, we fight not with fire and sword, but with the power of song.",
	feeling4 = "Knowing that the Commander is watching me sing brings some fulfillment to my empty heart. Maybe... as you give me your time, you also give me your life... is that the feeling?",
	lose = "Hm... I still think we should be fighting with conventional weapons.",
	feeling1 = "Would you like to be my \"enemy,\" Commander...? Hehehe... hehehehehehe...!!!",
	skill = "Get out of my way...!",
	upgrade = "There is something intruiging about using sound as a weapon~",
	propose = "\"Something too perfect and beautiful to destroy.\"――I never knew my concert could be so great. I want to perform more, to shine more, to take more and more of your time, Commander... until it runs out♪ Hehehe...",
	feeling5 = "I thought slaughtering my enemies was the only way to make me feel better, but you taught me another way, Commander. I never thought you'd be able to change me. You really must... pay for that♡",
	main = "First I heal everyone with my soothing song, then I shred them with its power. Hehehe, I know how it works.|That Sakura girl, she's fragile; she can't take many hits... What can I do to help her?|I must pour my heart into my song... I may not be very good, but I'll try my best.",
	touch = "You want a hug? Sure, any time~",
	voice_key_2 = -1,
	mission_complete = "You've been working just as hard as me. Good job, Commander~",
	battle = "You stand in our way...? Then you will suffer!",
	id = 403080,
	gift_dislike = "",
	gift_prefer = "Wooow! Thank you so much!",
	profile = "I am Iron Blood Cruiser Roon. I'm currently equipped with special \"Muse System\" rather than my usual loadout. It's definitely \"special,\" but it is combat ready, and I can't wait to tear something apart with it. Thank you for this, Commander.",
	voice_key = 40308,
	headtouch = "Headpats, is it~?",
	feeling2 = "Everyone is working so hard at this idol business, for your sake~ Me? Of course I am~ My smile and my joy, it's all for you, Commander... Hehehe♪",
	login = "Commander, what am I doing today? Orders please.",
	detail = "Everyone is enjoying these idol activities, but aren't you forgetting about our weapons? I shouldn't worry about them...?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[403090] = {
	hp_warning = "I'm not done for just yet!",
	feeling3 = "I just love listening to people talk about their history. Wish I had one... If I did, what'd it be like? I'm having fun just imagining it!",
	mail = "Bad Eisen! Stop munching on the mail! The Commander will get in trouble!",
	expedition = "The commission team's back! Put me on the next one, please? Come on, coach!",
	win_mvp = "Sweet victory! Not to mention MVP! Hahahah!",
	home = "Sortieing sounds a heck of a lot more fun than rusting away in port, don'tcha think? Take me out on the next one, come on!",
	unlock = "Hello there, Commander~! I'm the P-class armored ship, Prinz Heinrich. My little friend here is called Eisen... Hey, Eisen! Introduce yourself to the commander normally... Wait, how many times have I told you not to chew on others' clothes?!",
	touch2 = "Stop RIGHT there! This is where I draw the line!",
	mission = "A new mission? Say no more! I'll kerpow all the enemies to kingdom come!",
	vote = "",
	drop_descrip = "P-class armored ship – Prinz Heinrich. ",
	feeling4 = "Tell me more about yourself, Commander! Tell me what it's like to lead a fleet, or some funny mistake you've made! Come on, tell me, I wanna know!",
	lose = "Wait, we lost? How the heck?!",
	feeling1 = "I don't know what made you this way, but if nobody else is gonna fix you, then I will! Just shut up and grab hold of my hand!",
	skill = "My intuition tells me to just do it!",
	upgrade = "I feel the powah!",
	propose = "Hmm, I think you're supposed to follow the ring up with something else... Oh, now I remember what! *kiss*... Hahahah! I'm so glad to be with you, Commander!",
	feeling5 = "You down to go on another date today? When? Sometime later, I guess? Where? We'll cross that bridge when we get to it! No point in planning everything in advance! C'mon, with me!",
	main = "My gut tells me the papers you're looking for are right here! ...Aww, I was wrong?|There's plenty girls in other factions who don't have a history, huh! I thought it was just an Iron Blood thing.|Sure, Peter gives me a lot of flak, but honestly, I dunno how I'd manage to get anything done! Hahahah!",
	touch = "Mmmhh! Aahhh... Don't you ever get restless, working as much as you do, Commander? Get up and we'll take a jog down the hall!",
	voice_key_2 = -1,
	mission_complete = "So much paperwork and signing-off just for finishing one mission... My soul's boutta leave my body... Anyway, here's the rewards...",
	battle = "Let 'em have it, girls! Los! Los!",
	id = 403090,
	gift_dislike = "",
	gift_prefer = "Woah, I've always wanted this! Thanks a bunch!",
	profile = "An introduction? You got it! My name's Prinz Heinrich, I'm a P-class armored ship. What else is there... Hmmmm... Eisen! Hey, Eisen, any ideas what to tell the Commander?",
	voice_key = 40309,
	headtouch = "Woo!",
	feeling2 = "A past free of regrets paves the way for the future! Wow, that makes me sound super sophisticated! Hahahah! Am I right, Eisen? Right, Commander?",
	login = "Welcome back! Let's get fired up and do this thing! Hahahah!",
	detail = "What's a good way to make Eisen look less threatening... Hmm, maybe some cute stickers would do the trick?",
	couple_encourage = {
		{
			{
				40204,
				40205
			},
			1,
			"Bad Eisen! Stop trying to scare people!",
			0
		},
		{
			{
				40304,
				40305
			},
			2,
			"Team Armored Ships, comin' at ya!",
			0
		}
	}
}


