_G.pg.base.ship_skin_words[403093] = {
	hp_warning = "",
	feeling3 = "",
	mail = "There's a letter for you. Do you think it's a love letter, or a challenge to a brawl?",
	expedition = "",
	win_mvp = "Now do you get who owns this place?",
	home = "How's the school doing? If you see anyone trying to pick a fight, tell me, Commander. Heh!",
	unlock = "Listen up, Commander! I'm the one in charge of this school's seedy underbelly here at this port, so you'd better do what I tell you to! In return, I'll offer you my protection! Ahaha~♪",
	touch2 = "Commander?! Hrmh, you picked the wrong girl to mess with!",
	mission = "",
	vote = "",
	drop_descrip = "Listen up, Commander! I'm the one in charge of this school's seedy underbelly here at this port, so you'd better do what I tell you to! In return, I'll offer you my protection! Ahaha~♪",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "The banners say, \"Undefeatable – The world is mine.\" Basically, I'm as tough as they come, 'cause I rule this school!|Aw, crap! It's Strasser... No, wait, it's the Morals Committee! Please, no more catch-up lessons!|If I find any juvies, I'll whoop their butts! Hey, wait a sec... Aren't we juvies, too? Hiryuu! Explain this to me!",
	touch = "Hm? You got me bread from the canteen? Thanks~",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 403093,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Morning! ...Come on, Commander, say it like you mean it! Lemme hear you put some diaphragm into it!",
	detail = "The stage set's taken a real beating, but that's not entirely my fault. You could kinda say Eisen threw a fit, and... yeah.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[403094] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission team's back? Eisen, go with the Commander and give 'em a warm welcome!",
	win_mvp = "",
	home = "Great timing, Commander. I was just about to start singing! Since you're already here, stick around and listen♪",
	unlock = "Alrighty, I'm gonna sing a song for you now! Surprised by how jazzy and womanly I can be, are you? Ahahah!",
	touch2 = "Whoa! You're dead drunk, aren'tcha? Eisen, fetch the bouncer!",
	mission = "",
	vote = "",
	drop_descrip = "Alrighty, I'm gonna sing a song for you now! Surprised by how jazzy and womanly I can be, are you? Ahahah!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "No one told me I'd sing for THIS big a crowd! Strasser, bail me out!|What?! Bismarck and Tirpitz are in the crowd?! Oh shoot, this is nerve-racking! Commander, do you know any quick ways to calm down?!|Where'd Ulrich go? She's supposed to provide accompaniment! ...Hm? What'd you say? Our genres don't mesh?",
	touch = "Has my dress got you bewitched? Heheh~ You'll make the other girls jealous if you keep ogling me~",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 403094,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Welcome, Commander. The party's already started. Quick, grab a chair and sit down! You too, Eisen!",
	detail = "The idol girls sing before a crowd all the time, which takes serious guts! Do you think I've got what it takes to be an idol, Commander? Not quite? Why the heck not?!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[403100] = {
	hp_warning = "My comeback is-a coming in round two!",
	feeling3 = "Heya, Commander, I got those documents you asked for... Took longer than you expected? Yeah, uhh... I ran into Magdeburg and went jogging with her, then Heinrich and I played with Eisen, and after that... Yeah, I kinda lost track of time...",
	mail = "Yo, your mailbox is full. Want me to empty it for you?",
	expedition = "Hello? A commission's done. The girls brought back a ton of stuff, so I helped them out with it.",
	win_mvp = "K.O.! The enemies are all down for the count!",
	home = "Ever thought about setting up an outdoors office space, Commander? The warm sunshine and fresh air's waiting for you outside!",
	unlock = "Made it safely to port! Time to have a look around. Question is, where to start... Hm? Are you the Commander? All right. 'ello, nice to meet you, and all that jazz. See you around~",
	touch2 = "You can't go 'round doing this to girls, Commander.",
	mission = "The mission list grows ever longer... I say we just put it through the paper shredder, honestly.",
	vote = "",
	drop_descrip = "P-class armored ship – Prinz Adalbert",
	feeling4 = "Seeing other people happy makes me happy too~ That's why I love both helping people and hanging out with 'em equally. Other girls have said we're the same in that regard, you and I. You just love seeing people happy too, right?",
	lose = "Retreating already? Guess I'll do the same...",
	feeling1 = "You're such a lame-ass... I'm gonna go hang with someone else.",
	skill = "Adalbert, coming at ya!",
	upgrade = "Woo! Yeah! Feeling stronger already!",
	propose = "Does this mean we're like, super duper besties? ...Even more than that? Huh... Super duper ultra mega besties then? Let's go with that, and promise each other we'll always be together~",
	feeling5 = "Sooo, how 'bout say we look around for people in need of a helping hand? There ain't no problem we can't solve together. And if nobody needs help, we can just hang out instead.",
	main = "This hourglass is real neat. Let's reset it and watch the sand go again. And again... Welp, that got old fast. Now 'scuse me while I go rummage through your desk for other cool gadgets.|Sheesh, that's a crazy amount of paperwork on your desk. Wait, can't we just feed 'em to the shredder and be done with it? ...No? Fine, I won't do it then.|Don't you ever feel fed up, doing the same task for hours at a time? I'd give up after like, thirty minutes.|You know how Heinrich nicknamed her rigging \"Eisen\"? I'm thinking about naming mine too.",
	touch = "Mind helping out with my training, Commander?",
	voice_key_2 = -1,
	mission_complete = "Hey, Commander, the mission rewards are piling up at the pier.",
	battle = "Ho-kay! Warm-ups done, now let's do this thing!",
	id = 403100,
	gift_dislike = "",
	gift_prefer = "Woahhh, it's lovely! Thank you, Commander~",
	profile = "Heya, I'm P-class armored cruiser Prinz Adalbert. All P-class ships are a force to be reckoned with, at least according to Heinrich. So yeah, if you need some nasties taken care of, just gimme a call~",
	voice_key = 40310,
	headtouch = "Huh? I don't recall doing anything to earn a headpat, but okay.",
	feeling2 = "Let's start by checking out the depot. There's bound to be peeps there who need a hand or just wanna hang out.",
	login = "Come on. Time to get motivated, Commander.",
	detail = "Why're you always staring off in the distance, Commander? Got something on your mind? Maybe I can help you with it.",
	couple_encourage = {
		{
			{
				40309
			},
			1,
			"Smash through 'em, Heinrich!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[403101] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Mail always finds its way to you wherever you go, huh?",
	expedition = "Those girls you sent out are back? I'll whip up some drinks for them later.",
	win_mvp = "",
	home = "We're meant to be closed for the day, but I'm all ears if you've got any requests~",
	unlock = "Zzz... Huh? Did I doze off? I just meant to rest my eyes for a sec after closing up, but look how long I slept... Hang on, why are you still here, Commander?",
	touch2 = "This stuff won't fly during open hours, ya hear?",
	mission = "We've still got missions to do! See? You do need my help~",
	vote = "",
	drop_descrip = "Zzz... Huh? Did I doze off? I just meant to rest my eyes for a sec after closing up, but look how long I slept... Hang on, why are you still here, Commander?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Taking orders, moving dishes, and cleaning tables, that's this job in a nutshell. Never gets boring as long as you do 'em in rotation!|Honestly, not a fan of the liquor menu. All the drinks on there make my head spin...|Earlier today, I was caught gawking at my coworkers while they were mixing drinks. I was so distracted that Bismarck herself called me out for it.",
	touch = "I'm no marionette, ya hear!",
	voice_key_2 = -1,
	mission_complete = "Finished a mission, huh? I say you've earned yourself a drink.",
	battle = "",
	id = 403101,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Welcome, Commander! It's kind of odd saying \"welcome\" when I'm lying down, but hey.",
	detail = "How'd I end up here, lying down on the counter...? Think I closed up shop then got all sleepy... *yawn*... Truth be told... I'm still pretty sleepy.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[403102] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Huh? What's a letter for you doing in here? Aw crap! It's gonna get soaked!",
	expedition = "A commission's been completed? So that's why they brought a new basket. Anyhow, check this out, Commander!",
	win_mvp = "",
	home = "Hey, don't rush your way into the tub. Take it slow so you won't slip like I did.",
	unlock = "Oh, good timing. Pass me the shampoo bottle over– Whooooaaaa! Ow, oww... Hey, uh, Commander, could you help me get back up on my feet?",
	touch2 = "Is this the kind of scenario that gets you fired up?",
	mission = "The mission list? Oh, I almost forgot. What can I say? It got too wet to read.",
	vote = "拉票描述",
	drop_descrip = "Oh, good timing. Pass me the shampoo bottle over– Whooooaaaa! Ow, oww... Hey, uh, Commander, could you help me get back up on my feet?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "Wow! Doubt I'll be tripping again now!",
	propose = "",
	feeling5 = "Man, it's good you were here! I always knew we could overcome any adversity as long as we were together. Well, maybe calling falling over \"an adversity\" is a bit much... Hey, uh, why are you staring daggers through me?",
	main = "Mgh! Hngh! This soap is so bubbly! I'm gonna need your help to wash them away.|You can stop it with that concerned look already. My rear don't hurt anymore. Also, sitting to wash is pretty comfy – you should give it a try.|What's the rush, Commander? Take it easy. If you start to trip, I'll catch you.",
	touch = "You'll scrub my back? Go on.",
	voice_key_2 = -1,
	mission_complete = "It's fine 'cause you finished that mission? Oh. Then someone's gotta go claim the rewards!",
	battle = "",
	id = 403102,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Hm? You wanna wash my hair? Cool. Go right ahead!",
	feeling2 = "",
	login = "Boy, am I glad you're here, Commander... even if I definitely won't trip again. For sure.",
	detail = "I tripped 'cause I was playing with bubbles. I got so engrossed that I covered the whole bathroom in the stuff, and you know the rest. I've learned my lesson now!",
