	drop_descrip = "Alright, little one! Now that we have some time off, why don't we play a game? If you win, I might just give you... the reward of love♥",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Heehee, you're a greedy but lovable little rascal. Seems playing a game with me just isn't enough – you want ALL of my love! Well, you'll get it! All the pleasure and love in the world belongs you to, my dear little one.",
	main = "My, my, you REALLY want to win. Are you that thirsty for my love reward?|Does playing this game with me make you happy? ...Oh? You could play this all day? Me too♥|It's lovely how our tastes in video games are so similar. This must be what they mean by \"lovebirds of a feather flock together.\"",
	touch = "You better not be thinking you'll win through cheap tricks!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 403141,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Heehee. Mischievous as ever, aren't you?",
	feeling2 = "",
	login = "Great timing, dear little one! Heehee, I just got done setting up the game. Do you wanna play?",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[403142] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Ah, you're finally here, little one. I feel like I'm drying out from the heat of the sun and my love...",
	unlock = "Are you ready, my beloved little one? I'm giving you all of me, so apply your love – the sunscreen – ever so thoroughly, so gently, please.",
	touch2 = "There, too...? Well, love does need to be applied evenly♥",
	mission = "Missions? Under the blazing sun? Spreading the word of love is a difficult path...",
	vote = "",
	drop_descrip = "Are you ready, my beloved little one? I'm giving you all of me, so apply your love – the sunscreen – ever so thoroughly, so gently, please.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "The bed's already soaked with sweat. I'll have to lie on my back... Don't forget to apply your love here, too, little one♥",
	main = "*sigh*... I just want to jump in... No, I need to wait, or else the sunscreen will go to waste.|Hmm? Didn't you just put some on me? Is the heat making you lose your wits, little one? Heehee.|If you're tired, then lie down with me. Is it too cramped? I'm sure the power of love can fix that little problem♥",
	touch = "Be a little bolder, if you want. Heehee♥",
	voice_key_2 = -1,
	mission_complete = "Mission rewards~ See if there's anything that can cool me down in there.",
	battle = "",
	id = 403142,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Mmm... I feel the love slipping between your fingers. It's even hotter than the scorching sun...",
	detail = "Even the power of love might not be able to beat the summer heat... Well, that's not true. Your love saved me from the heat, after all. Love wins again♥",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[403150] = {
	hp_warning = "Heh... You're nothing but noise to me.",
	feeling3 = "Commander, I notice you're keeping your distance today. You can't guide me from that far away, can you? Come closer. Take in the sight of my movements, my gaze, and every little change in expression.",
	mail = "New mail, huh? Think it's fan mail? I don't care much about your average fan mail, but if it's a love letter from you? Then I'm interested.",
	expedition = "The commission is complete? Sounds like fun is waiting just around the corner. I'll go greet them with you.",
	win_mvp = "Maybe we should ramp up the difficulty of those lessons...",
	home = "Commander, what do you want to do now that I have a break between lessons? Go on a date? Or maybe throw in some... private instruction?",
	unlock = "I am heavy cruiser idol Prinz Eugen, a participant in the Muse System experiment. You look interested in my outfit, Commander. Heheheh... You can expect my usual exploits and more!",
	touch2 = "Touching an idol? I'd better scream for help... Just kidding! As you wish, I'll let you get a little taste... Heheh♥",
	mission = "Are you just gonna keep staring at me instead of checking on your missions? Heheh... Are an idol's charms just that irresistible?",
	vote = "",
	drop_descrip = "I am heavy cruiser idol Prinz Eugen, a participant in the Muse System experiment. You look interested in my outfit, Commander. Heheheh... You can expect my usual exploits and more!",
	feeling4 = "Liiisten, Commander... *exhale*... What was I doing? I'm just practicing my breathing for when I sing. Now, one more tiiime... *exhale*... You feel the force of my breath on your neck, don't you?♥",
	lose = "Maybe I should put more effort into being an idol...",
	feeling1 = "If you don't get your job done, I'll punish you... Kidding! Hm? You wanna know how you'll get punished? Keep thinking weirdo thoughts like that, and you won't get to be our producer anymore.",
	skill = "The opening performance isn't over yet!",
	upgrade = "Hard work doesn't lie... This is the result of my training, for sure.",
	propose = "Directly confessing to a subordinate, and an idol at that... You're not much of a producer, Commander. Haha! As for whether I'll accept this... You've known the answer for a long time now, right? Keep those eyes fixed only on me from now on!",
	feeling5 = "Ever since the day you became my producer, our fates became one. Keep supporting me forever from now on, okay? My singing, dancing, and performances are all just for you, Commander. Heehee♥",
	main = "Try and give me a stage I can shine even better on. I'll reward you handsomely♪|Luck and ability are both important to idols. Of course, I've got both!|When you hear my voice, don't you feel me... engulfing your heart and soul?|Oh? There's peeping, and then there's this. If you wanna see me that bad... then look all you want. Heehee.",
	touch = "Commander? Have you fallen head-over-heels for my idol form?",
	voice_key_2 = -1,
	mission_complete = "Your mission rewards won't run away, but don't think I'll let YOU get away without checking them, got it?",
	battle = "Aufführung beginnt!",
	id = 403150,
	gift_dislike = "",
	gift_prefer = "You know exactly what I want, huh? Thank you~♪ Mwah~",
	profile = "Third ship of the Admiral Hipper-class ships, Prinz Eugen. Right now, I'm a member of the idol group Alizarin, too. Heheh, do you love me more than ever now? Well, keep your head on straight until my performance starts!",
	voice_key = 40315,
	headtouch = "Hmph, someone went and messed up my hair and makeup... You're gonna pay the price for that later.",
	feeling2 = "You've been working hard these days. Yeah... I can reward you for that. For example, an idol's massage...? Oh, you don't want to trouble me? You're such a little sweetheart, Commander.",
	login = "You sure showed up early today, Commander. Are you here to observe us rehearse, or were you that desperate to see me? Surely you don't expect me to believe that this was for \"educational purposes\"~",
	detail = "I'm in top form right now. If you insist, though, what part of me do you want to examine? My voice? My stage performance? Or my general \"condition\"?",
	couple_encourage = {
		{
			{
				20714
			},
			1,
			" You should cut back on the sweets a little.",
			0
		},
		{
			{
				30224
			},
			1,
			" Heheh, if you're amping up the energy, then I won't be bested either!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[403160] = {
	hp_warning = "This is nothing for me!",
	feeling3 = "Commander, let's play hide-and-seek! It'll be your super-special trial!",
	mail = "Huh? A new letter? Can you read it out to me?",
	expedition = "The commission team is back? I hope they brought some fun toys along.",
	win_mvp = "Hahaha! Do you get it now? That's the power of the god of the sea! ...Hm? Why are you laughing, Commander?",
	home = "Heheh. You're back, huh? Have you brought offerings for the god of the sea? ...I'm talking about that! The juice in your hand!",
	unlock = "Heheh! I'm gonna show you how amazing the god of the sea is! ...Huh? Why are you laughing! Stop it! Don't you treat me like some kid!",
	touch2 = "Whoa! Th-there's a limit to how much rudeness I'll tolerate! I'm going to smack you with my treasured sword!",
	mission = "You still have unfinished work to do, don't you? You're not allowed to be lazy! Go get it done then come play with me!",
	vote = "",
	drop_descrip = "Large cruiser – Ägir.",
	feeling4 = "Aww... Where'd you go, Commander? My kingdom needs you...",
	lose = "They cheated, that's all... It... It had nothing to do with my short feet or being unable to catch up with them!",
	feeling1 = "Hmph! You're a meanie who won't even drink juice with me. I'm sending you to toy prison so you can think about what you've done!",
	skill = "Feel the power of the god of the sea!",
	upgrade = "I've grown stronger! Time to celebrate with some juice! ...*cough cough*! I drank too fast and it got in my lungs... *cough*...",
	propose = "Today is a special day! I've made up my mind – you're not just gonna be my servant, you're also gonna be my trusted knight! Your job will obviously be to protect me, your lord, but also... to always play with me!",
	feeling5 = "I've come to a decision, Commander! You're going to play with me forever and... No, wait, you're going to be my servant and serve me forever! Got it?",
	main = "This juice is so sweet. It's so much better than those adult drinks, isn't it? Heheh! It has to be!|Commander, come walk with– No, I mean, tour my kingdom with me!|You've not given me enough snack offerings, Commander. Hm? I'll get cavities if I eat too much? I-I don't care! I'm not scared of cavities!",
	touch = "Hm? Do you have an offering for the god of the sea?",
	voice_key_2 = -1,
	mission_complete = "And this is why I picked you, Commander. Go get your rewards. Oh, and pour me some juice to celebrate!",
	battle = "Set sail! Protect the abyssal kingdom!",
	id = 403160,
	gift_dislike = "",
	gift_prefer = "Wow, you're giving this to me? ...I-if you insist, I suppose I wouldn't mind. Heheh~♪",
	profile = "All the territory I can see from up on my throne belongs to me! That includes you, obviously! Now kneel before me! Ahahahaha!",
	voice_key = 40316,
	headtouch = "Hmph! The god of the sea doesn't yield so easily... Mrgh... Ah...",
	feeling2 = "You want my approval that much? Okay, then start by giving me some yummy snacks and fun toys to play with!",
	login = "Oh, it's you! Do you wanna see my toy– I mean, my abyssal kingdom?",
	detail = "Commander! How do you like my kingdom? It's still pretty small, but with your help, it will become something truly legendary!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[403170] = {
	hp_warning = "Heheheh... I'll survive this, even if you don't!",
	feeling3 = "An infinite hallway in front of the infirmary, making it so you can never leave? Commander, is it real?! Where is it? I gotta see it right now!",
	mail = "New mail?! It's not from the spooky never-ending medical record cabinet, is it? Even head nurses need their rest!",
	expedition = "Commander, the commission team returned. I wanted to ask them about that paranormal commission, so do you want to come with?",
	win_mvp = "Heeehehehe, how disappointing! I can hardly feel anything from you!",
	home = "Are you injured? I can wrap up your wounds just like a beautiful gift... Hm? Do I actually know how to treat wounds? Oh, I have some secondhand knowledge.",
	unlock = "I'm Prinz Moritz, lover of ghost stories and a P-class armored ship under the Iron Blood banner. Oh, and I have another title... the Nurse of Nighttime Spooks! Ready for a full physical, Commander? Heeehehehe!",
	touch2 = "Huh?! Aaah! I-is this... Wait, do you feel that way about me? Whaaat?!",
	mission = "Commander, missions just came in. Heeehehehe!! Let's go see if they're scary!",
	vote = "",
	drop_descrip = "P-class armored ship – Prinz Moritz.",
	feeling4 = "Aah, hahaha... I dreamed of that dark, scary infirmary... Yeah, the one you were telling me about! I could feel everything, even the fear and suffocating feelings you described... I love it... Heeehehehe!",
	lose = "No! I'm not done yet!",
	feeling1 = "*siiigh*... I'm tired of your stories, Commander. They aren't scary at all.",
	skill = "Heeehehehe... Hahahaha!",
	upgrade = "Ooh... Now I can write scarier stories!",
	propose = "I see... So this is the oath of love. I totally get it! Hahaha! Commander! Let's create a world of scary stories, full of chills, thrills, and love! Heeehehehe!",
	feeling5 = "Hmm... Why does my heart race whenever you're near? Could it be... that I'm in a trance from a real-life ghost story?!",
	main = "Commander, have you heard the tale of the head nurse without a shadow who floats in the night? Bristol and the others run away every time they see a white nurse uniform now. Heeehehehe!|What kind of story could scare you, I wonder... Let's find out right now!|An elegant upper-class demon... Hmm, I think a head nurse with a scary laugh is way better. Z9 gave me that descriptor personally! Hahaha!",
	touch = "These are just the necessary props to play my role. What role, you ask? The spooky nurse, of course.",
	voice_key_2 = -1,
	mission_complete = "Mission accomplished! Hm... Are there any ghost stories about finishing missions?",
	battle = "It's time for your physical!",
	id = 403170,
	gift_dislike = "",
	gift_prefer = "Ooh! How did you know I needed one of these? Now I can research even more urban legends!",
	profile = "I'm Prinz Moritz. P-class armored cruiser, Iron Blood. I guess that makes me an upper-class demon? It doesn't matter if you know who I am. I much prefer researching and writing spooky stories over engaging with high society. Heeehehehe!",
	voice_key = 40317,
	headtouch = "Hmm?! Commander... Are you trying out that old urban legend about how getting headpats makes you stop growing?",
	feeling2 = "Heeehehehe! It's Nurse Moritz, making her midnight rounds! I'll keep you nice and safe, Commander~",
	login = "Roooar! Hahaha! Did that scare you? You'd better toughen up those nerves, Commander. How about I help you... through desensitization? Heeehehehe!",
	detail = "If you were in a hospital ghost story, who would you be happiest to see show up? Girls like me, of course! Right?! Hahaha! I knew you and I thought alike!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[403171] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome back. Ready to grant my wishes yet? Huh? I still haven't told you them? Heeehehehe! But wishes never come true if you speak them aloud, remember? Use that brain of yours!",
	unlock = "Are you the one who summoned me? I'm the genie of the lamp, and I thank you for freeing me. As a reward... let's play a game together.",
	touch2 = "Huh?! H-h-how did you know what my wish was?!",
	mission = "",
	vote = "",
	drop_descrip = "Are you the one who summoned me? I'm the genie of the lamp, and I thank you for freeing me. As a reward... let's play a game together.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Heeehehehe! I'd best begin preparing for my ultimate wish~ Commander, have you thought of a way to satisfy me? A fun ghost story, or getting nice and close, or perhaps even... Mwah!",
	main = "Commander, I wish you'd stop staring at the night sky! Oh... Wait, that didn't count.|Want a hint? Well, too bad! I could consider it if you came over and entertained me, though. Heeehehehe!|That story you told me was pretty good. I suppose I could count that as a wish granted... Heeehehehe! Nobody said I only had one wish, though~",
	touch = "The secret to getting your wishes granted is to please me! Heeehehehe!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 403171,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Heheh, there you go... Now you're getting the hang of it!",
	feeling2 = "",
	login = "Since time immemorial, I've granted countless wishes... So this time, you'll be the one to grant mine! Fun, right? Heeehehehe!",
	detail = "Prinz Moritz? No, no – that was my last incarnation's name. My true name is... irrelevant! Call me Miss Genie.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[404010] = {
	hp_warning = "I shall fight until the last bullet!",
	feeling3 = "You've got a pretty nice fleet here. Being here makes me feel like giving it my all.",
	mail = "You've got mail, Commander. You're quite the popular one, aren't you?",
	expedition = "A commission has been completed. Seriously, you ought to let me and my little sister handle this stuff.",
	win_mvp = "If there's anything worthy of my trust, it's my cannon!",
	home = "Not bad at all. Seems like you're getting used to battle.",
	unlock = "In Scharnhorst's dictionary, the word \"retreat\" simply doesn't exist! You're the Commander? Let me see what you've got.",
	touch2 = "Stand right there, Commander. If you can take a shot from me, I'll forgive you... ",
	mission = "Missions? Let's take care of them in one fell swoop.",
	vote = "",
	drop_descrip = "Scharnhorst-class battlecruiser, Scharnhorst.",
	feeling4 = "Hey there, Commander! I just went to train with the other girls. Everyone is full of energy, all thanks to how reliable you are. I'm really taking a liking to this place.",
	lose = "I won't lose next time!",
	feeling1 = "Cowards have no right to stand on the battlefield!",
	skill = "Anton, Bruno, Caesar... Cannons at the ready!",
	upgrade = "I'm looking forward to the next battle!",
	propose = "Don't worry. For the fleet, and for you, Commander, I'll learn to protect myself and be less reckless than before. But, as always, please continue counting on me for combat!",
	feeling5 = "I've never retreated - not because I'm fearless, but because I've always had a reason to keep fighting. In the past, it was for the Iron Blood. Now, it's for your sake, Commander... I mean, your fleet's sake!",
	main = "Those lightweight aircraft carriers simply can't match our combat abilities!|Do me a favor and remind our friends not to sail directly in front of me... I might not be able to resist firing at them...|\"The Ugly Sisters\"? Hmph, it's not a bad name... Sounds like a good name for this war, too...",
	touch = "I'll never back down!",
	voice_key_2 = -1,
	mission_complete = "Rewards? Hah, now that's what I'm looking forward to.",
	battle = "Let us trample the shattered remnants of our enemies!",
	id = 404010,
	gift_dislike = "",
	gift_prefer = "You've got good taste. Thank you.",
	profile = "I’m Scharnhorst. I will stand until the last moment of any battle. This is my determination, as well as my pride. Leave all the fighting to me!",
	voice_key = 40401,
	headtouch = "",
	feeling2 = "If only I didn't need to care about anything other than becoming stronger or defeating more enemies. But, reality isn't so simple...",
	login = "You're back? Good timing. I'm just about to test my guns.",
	detail = "Only those who have not been scarred would laugh at someone else's.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[404011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Looks like you're busy as ever, even during the holidays.",
	unlock = "A festival, huh? Going for days without fighting is boring, not to mention not my style. C'mon, Commander, isn't there *something* exciting I can do during this \"Lunar New Year\" festival?",
	touch2 = "Well, well, guess you're raring to play with my grimalkin.",
	mission = "",
	vote = "",
	drop_descrip = "A festival, huh? Going for days without fighting is boring, not to mention not my style. C'mon, Commander, isn't there *something* exciting I can do during this \"Lunar New Year\" festival?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Whenever I stop and think about what I can *do*, besides charging into battle, it makes me feel just slightly uneasy... But I believe I'll find the answer someday, as long as I'm with you.",
	main = "Firecrackers? If you need something flashy and loud, why not do it with a cannon salute instead of those toys? It's more impressive, to boot.|I'm really fond of the intense gaze my grimalkin has. Hahah, relax, she's a good girl. Just don't get on her bad side.|The Royal Maids are helping out with the cooking? Hmph, that head maid sure has a finger in every pie.",
	touch = "If a *snowball* fight is all we're doing then I'll pass.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Just so happens I'm bored. You maggots are gonna fix that!",
	id = 404011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Haahh... Guess it *is* true that sitting for too long makes you feel tired...",
	detail = "Gneisenau \"convinced\" me to wear this dress and do \"something unrelated to fighting for once.\" She didn't really let me decline. That's the long and short of it. ",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[404020] = {
	hp_warning = "All ships, remember to stay alert!",
	feeling3 = "\"The Ugly Sisters...\" Though we were given that epithet for our achievements, it still hurts a little. Commander, do you think I'm ugly?",
	mail = "Commander, there's mail for you. I'll leave it here.",
	expedition = "A commission has been completed! Care to inspect the results?",
	win_mvp = "Sorry, this is war. There's no room for mercy.",
	home = "Welcome back. Please take it easy for a while.",
	unlock = "Hello, Commander, I'm Gneisenau. Though my big sister is a bit reckless, we're actually an invincible team. I hope I will be able to sail with her as often as possible!",
	touch2 = "Commander, Anton is locked on, you can't escape now. ",
	mission = "A mission? Let me do some planning for you...",
	vote = "",
	drop_descrip = "Scharnhorst-class battlecruiser, Gneisenau.",
	feeling4 = "Without realizing it, I've come to enjoy supporting both my sister and you, Commander.",
	lose = "I let my guard down...",
	feeling1 = "I assumed you were more intelligent, Commander...",
	skill = "... Now you're in range!",
	upgrade = "It's fine as long as you haven't let power cloud your judgement...",
	propose = "A promise, huh? Long ago, I would have despised the notion of being tied down to emotions... but it doesn't seem so bad now.",
	feeling5 = "The present flies by like an arrow, but the future always arrives too late. I hope that one day, I will be able to see the future that you and I create.",
	main = "You mustn't put off until tomorrow what you can do today. Please take that to heart.|One forgets the cruelty of war after being at peace for too long. The opposite... is true as well, isn't it?|Looking back at it, it's unbelievable that I would mistake that prideful princess as an old-fashioned knight.",
	touch = "Isn't it amazing how different people can come to different conclusions about the same topic?",
	voice_key_2 = -1,
	mission_complete = "Rewards distributed. Please accept them when you have a moment.",
	battle = "Truth only exists within the guns' range.",
	id = 404020,
	gift_dislike = "",
	gift_prefer = "Your kindness is much appreciated.",
	profile = "I'm Gneisenau. Though I'm not as bellicose as my sister, I'm still confident about my combat capabilities. As some of the best ships the Iron Blood has to offer, we hold the record of being the only battlecruisers to sink a standard aircraft carrier. Your faith in us will not be misplaced.",
	voice_key = 40402,
	headtouch = "",
	feeling2 = "Is it urgent? I prefer simple and effective forms of communication.",
	login = "Welcome back. Ready to get back to work? I've prepared everything you need, Commander.",
	detail = "My duty is to support my big sister who is always charging too far ahead. Admittedly, it gets a little irritating at times.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[404021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "You say you see ghosts and goblins all around me? ... I think you need a break. Getting into the Halloween spirit is all well and good, but you can't overdo it.",
	unlock = "These Halloween festivities are quite interesting, in a good way. Getting dressed up in these costumes isn't such a bad experience either. Commander, what do you think of my costume?",
	touch2 = "Eek?! Commander, does someone want to be \"punished?\"",
	mission = "",
	vote = "",
	drop_descrip = "These Halloween festivities are quite interesting, in a good way. Getting dressed up in these costumes isn't such a bad experience either. Commander, what do you think of my costume?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "If only my sister were here... Now if we had some sort of pumpkin-smashing gunnery competition, that would have gotten her attention.|This holiday certainly is well suited to us \"Ugly Sisters,\" isn't it?|My tail? Oh it just came with the costume... Still, I'd prefer if you didn't touch it.",
	touch = "While I haven't prepared any candy, I do have a \"treat\" for you to enjoy. Would you like to try? I'm afraid there may be some pain involved... Hehehe...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 404021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "At first I was too embarrassed to wear something like this, but I went along with it and after wearing it for a while, I must say I'm starting to see things in a different light...",
	detail = "Everyone wants to be a witch for Halloween, so I chose something a little bit different. After seeing your reaction, Commander, I think I chose correctly. Hehehe...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[404030] = {
	hp_warning = "Miladies! Take cover behind me!",
	feeling3 = "I have complete faith in your decisions. Except... the worry that my service isn't all you hoped for lingers in the back of my mind. But, rest assured, it will not hinder me in combat!",
	mail = "Salute! I've brought your newly-arrived letter!",
	expedition = "The commission team has returned to port! Commandant, please have a look!",
	win_mvp = "Commandant, your in-person commanding was a thing to behold! Frankly, however, I don't believe I can say the same of my own performance...",
	home = "A salute to your return, Commandant! Phew... I take it your battle was an honorable one, as always?",
	unlock = "Salute, Commandant! Iron Blood battlecruiser Seydlitz reporting in! Inexperienced though I may be, as of today I am proud to serve this port in the pursuit of honor and glory!",
	touch2 = "C-Commandant?!",
	mission = "You have unfinished missions, Commandant! It may be wisest to do the newest ones first.",
	vote = "",
	drop_descrip = "Battlecruiser – Seydlitz.",
	feeling4 = "Spend my day off however I want...? While that does sound nice, I'm not sure what I want to do is good in your eyes, Commandant... But if that's your order, I will follow it!",
	lose = "I failed by not following my orders... What a disgrace!",
	feeling1 = "This is all because I'm a worthless maggot... Commandant, I beg for your forgiveness!",
	skill = "You will not sink me! I won't allow it!",
	upgrade = "You've made me stronger, Commandant! You have my thanks!",
	propose = "While I am overjoyed by your offer of marriage, I'm worried if my answer won't be to your– No! Of course I'm not turning you down! What I mean is, I don't know whether to say \"gladly,\" or \"I love you.\" You may decide if you'd like, Commandant!",
	feeling5 = "Y-you wish to go on a date? With me, of all people? ...Forgive me, I should not question an order from you, Commandant! I will make every step towards ensuring a thoroughly enjoyable date!",
	main = "Lützow! Stop that before you distract the Commandant! ...Well, Commandant, I do believe getting distracted is a bad thing...|I've no grand ambitions of being hailed as a hero. My heart's only desire is to serve you faithfully, Commandant.|People who doubt their comrades deserve to be shunned. If they must doubt anyone, it should be themselves.",
	touch = "Salute! Your orders, Commandant!",
	voice_key_2 = -1,
	mission_complete = "You have received mission rewards! Whew... I'm glad it went off without a hitch. Outstanding work, Commandant.",
	battle = "Achtung! Reduce them to scrap!",
	id = 404030,
	gift_dislike = "",
	gift_prefer = "Commandant?! Wh-why are you giving me something so precious out of the blue...",
	profile = "I am Seydlitz, Iron Blood battlecruiser! My tenacity is my pride, my conquests are my glory, and executing your orders is my mission! I await your orders, Commandant!",
	voice_key = 40403,
	headtouch = "Salute! What are your orders?",
	feeling2 = "If you'll forgive my audacity, I have a request. Commandant, please give me more orders! I will do anything you require of me!",
	login = "Salute! I put my faith in your guidance as always, Commandant!",
	detail = "Commandant, I do understand our mission at this port, but I hope to one day move up and fight for humanity's– Forgive me, I should have held my tongue.",
	couple_encourage = {
		{
			{
				4
			},
			2,
			" Miladies! Allow me to protect you!",
			3
		}
	}
}


_G.pg.base.ship_skin_words[404031] = {
