_G.pg.base.ship_skin_words[404033] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Ah, you've received a letter, Commander.",
	expedition = "",
	win_mvp = "Streetwear is not only comfortable, but visually striking as well. Whew... Do you share my view, Commandant?",
	home = "Welcome back from your patrol, Commandant! Allow me to pour you a drink!",
	unlock = "Salutations, Commandant! ...You think I look like a totally different person? Haha! You're right – I decided to change up my look for once. Oh, today looks like a hot day, so I brought drinks. Take one!",
	touch2 = "Th-this isn't exactly how I pictured our day off...",
	mission = "",
	vote = "拉票描述",
	drop_descrip = "Salutations, Commandant! ...You think I look like a totally different person? Haha! You're right – I decided to change up my look for once. Oh, today looks like a hot day, so I brought drinks. Take one!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Go on a date wearing this? Heehee, I will take that to mean you like seeing me in such a novel outfit. Then please, go ahead and ask me on a date! I will do all I can to live up to your hopes and give you an unforgettable experience!",
	main = "In case you're wondering... I did indeed pick out this streetwear by myself. Now that you have this information, what do you make of it, Commandant?|The graffiti, you ask? I thought I'd opt for a backdrop that complemented my outfit! You asked to see me in a fresh look, and I answered to the best of my abilities.|Commandant, please have a drink. The last bottle was much too cold, but this one is just the right temperature... I thought of everything, you say? Th-thank you!",
	touch = "Commandant, won't you take a picture with me? This feels like a great occasion for it!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Time to exert all my strength and individualism!",
	id = 404033,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Just a moment... There, I've struck my pose! Awaiting your next orders, Commandant!",
	detail = "Whew... Wearing clothes like this is quite new to me. Oh, but rest assured, Commandant – I will strive to become one with the streetwear! ...Just be myself, you say? Understood!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[404034] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Commandant, where were you?! We need to escape now, before the– Police sirens?! Oh no... Were you an undercover officer this whole time?!",
	unlock = "You're the person the Organization sent to extract me, Commandant? Great. The plan went smoothly and I got the goods. We can evac using the planned route.",
	touch2 = "Mgh... A strip-search does not need to be THIS thorough...",
	mission = "",
	vote = "",
	drop_descrip = "You're the person the Organization sent to extract me, Commandant? Great. The plan went smoothly and I got the goods. We can evac using the planned route.",
	feeling4 = "",
	lose = "We've got a rat! The deal's off!",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "You want me to abandon my mission? Because it's \"not too late to change my ways\"? Thank you, Commandant... I'll place my trust in you.",
	main = "Once this matter is done with, I'm going to leave the Organization and return to a normal life. Would you like to come with me, Commandant?|Commandant, I know missions always come to an end, but the bond we've forged will never break... right?!|...And that concludes my contingency plans for everything that may happen. Have I lived up to your expectations, Commandant?",
	touch = "I modified this motorcycle myself. It can even catch up to a carrier's aircraft if I go full throttle!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Hold on tightly! I'm turning the speed up to the max!",
	id = 404034,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "My sunglasses? Oh, they're not for hiding from the police, I just wear them because I think they're stylish... They make me look really reliable?! Ahaha, that's good to know...",
	feeling2 = "",
	login = "You've come. Allow me to verify the code phrase. \"Mission impossible\" – what comes next? ...Okay, your code is correct. I can lower my guard, then. Whew... Here I thought the police had shown up.",
	detail = "(*sigh*... Why did I have to get the role of a villain? It's so cruel to have me be betrayed by the Commandant...)",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[404040] = {
	hp_warning = "Nuh-uh, I don't feel a thing!",
	feeling3 = "You follow a schedule? It's all about getting into habits, huh... I getcha. Can you show me what yours is like?",
	mail = "Here's your mail. No need to thank me, I just picked it up on the way.",
	expedition = "The commission team is back. We don't have to go out and meet them, do we?",
	win_mvp = "Zzz... Ahh, I'm so sleepy. Is the battle over yet?",
	home = "You're back! It's kinda boring when you're not around.",
	unlock = "*yawn*... Hm? Who are you? Can you point me to the Commander? ...YOU'RE the Commander? Heehee, all right, saves me the effort of looking for you. I'm Lützow, Iron Blood battlecruiser. Since we're done here, I'm gonna take my leave~",
	touch2 = "Geesh, you're more daring than I took you for. Imagine that.",
	mission = "A mission? Miss me with that. You'll be fine on your own anyway.",
	vote = "",
	drop_descrip = "Derfflinger-class battlecruiser – Lützow.",
	feeling4 = "Can't you, you know, ignore a schedule if there's a ton of work on it? ...No? A schedule sounds pretty awful then. Just do like me and do whatever you want~",
	lose = "Welp, we lost... This blows. I'm heading home.",
	feeling1 = "Ugh... I hate this place. I hate this place so much.",
	skill = "I guess maybe I'll try.",
	upgrade = "Hm? Am I stronger now? Doesn't feel like it, honestly.",
	propose = "Carefree as I am, we're stuck together now~ Stuck together by means of this ring, anyway. You're the only person I'll take orders from, and I expect you to do me a few favors in return~",
	feeling5 = "Hey, Commander, how about we run away together? ...I'm just kidding with you. Don't get all worked up. All I want is for you to forget all your troubles when we're alone together~",
	main = "Why won't you let me sleep in the office? Because that interferes with your work? Huh... And that's a bad thing?|Hey, show me what you're working on... It's just a bunch of random charts and numbers. 'Kay, have it back.|If you can't find me in the office, I'm likely out and about somewhere. Don't worry, I'll be back before you know it. Probably.",
	touch = "You wanna hug this fella? Go ahead. Only a quickie though, okay?",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Why're you giving me that look? You're the one who got it done, not me.",
	battle = "Ugh... What did I do to deserve this big-ass responsibility...",
	id = 404040,
	gift_dislike = "",
	gift_prefer = "Hm? What's this? ...If you're giving this to me, then don't expect to get it back. Is that alright with you?",
	profile = "Hey, I'm Iron Blood battlecruiser Lützow. I was part of the High Seas Fleet, and... I forgot what I was gonna say. Eh, whatever, I'll probably remember after I've had a nap.",
	voice_key = 40404,
	headtouch = "I'm not sleepy. That was just a li'l yawn... *yaaawn*...",
	feeling2 = "Don't feel like doing a dang thing today... Hey, Commander, what do you do to get through the day when you've got no energy?",
	login = "G'morning. Hey, can I sit down a li'l longer? This chair is just too comfy.",
	detail = "Could you NOT call me without a reason? ...You know what, on second thought... If you're bored, chat with me.",
	couple_encourage = {
		{
			{
				20501
			},
			1,
			" Queen of the Royal Navy? Uh-huh, I see...",
			0
		},
		{
			{
				40403
			},
			1,
			" You know the drill – safety first!",
			0
		},
		{
			{
				40304
			},
			1,
			" Who cares what your name is anyway?",
			0
		},
		{
			{
				40602
			},
			1,
			" I'm a good girl. Unlike you.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[404041] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "You brought this upon yourselves, opponents. Why must you make me spill blood?",
	home = "You're under my complete control, and will always come back to me... Heehee, I call this plot device \"the curse of Dracula's Castle.\"",
	unlock = "\"Have you come to accept your fate, human? Heehee~\" ...Don't just stand there, Commander. Say something!",
	touch2 = "When a human feels bliss, that's when their blood tastes sweetest♪",
	mission = "",
	vote = "",
	drop_descrip = "\"Have you come to accept your fate, human? Heehee~\" ...Don't just stand there, Commander. Say something!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Gaze into my eyes, Commander... Yeah, the script says I have you under my spell, so just keep gazing~ By the way, vampires drink blood through the neck, right? 'Cause I want a taste~ Nom♪",
	main = "Garlic? Crosses? Those don't work on me... Those are meant to repel a vampire? Well then, I'm throwing those weaknesses right out the window.|Seydlitz, the key to acting is to fully immerse yourself in your role. You don't have to think about it too hard.|Hrmph. I'm trying my absolute best here, and you're not even looking, Commander... I'll just have to MAKE you pay attention!",
	touch = "Aww, come ooon. I'm comfy right where I am – don't make me get up.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 404041,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Welcome back, Commander. Now where's my crimson elixir? As in, my daily glass of wine~",
	detail = "This looks kinda like a ball dress, doesn't it? So make like at a ball and ask me for a dance. Whether I accept or not hinges on your ability to persuade, though~",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[404042] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "One more to recharge my batteries! Nom!",
	home = "Your food's gone cold. You gonna heat it up, or end up burning it? Either way, it's your move♪",
	unlock = "Om, nom... Hmm. Hey! This is pretty good! I mean, of course it's good – it's Empery cuisine! Commander, open wide and I'll give you a dumpling alley oop. Say \"aah\"!",
	touch2 = "Sooo~ You saying you wanna eat me, too?",
	mission = "",
	vote = "",
	drop_descrip = "Om, nom... Hmm. Hey! This is pretty good! I mean, of course it's good – it's Empery cuisine! Commander, open wide and I'll give you a dumpling alley oop. Say \"aah\"!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Eww, you're gonna drink coffee with that, Tallinn? Here, lemme educate you a little. See, you're meant to have this with a cold glass of beer. Heehee♪|I'm eating, so save the work talk for later. No food for you until your job is done, okay?|Ahahahah! Deutschland seriously can't handle hot food? C'mon, Commander, go blow on it for her. Meanwhile, I'll keep your food safe and secure in my belly♪",
	touch = "You want seconds? I'll order some in a bit.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 404042,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "*yaaawn*... Yeah, what? Eating makes me sleepy. You're not seriously gonna do paperwork today, are you?",
	detail = "Invite Seydlitz and the gang next time? I mean, if you want their company, do it yourself. You're the only person I wanna invite. Heehee.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[404048] = {
