	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome back. Come here and I'll take good care of you♪",
	unlock = "*yawn*, finally, I get to lie down. Tell you what, I'm gonna have a nap... Hm? The ceremony's still not over? Hrmh... Look, it's not important. You should just come lie next to me, Commander!",
	touch2 = "I'm... I'm sleeping, so I don't mind... *murmur*...",
	mission = "",
	vote = "",
	drop_descrip = "*yawn*, finally, I get to lie down. Tell you what, I'm gonna have a nap... Hm? The ceremony's still not over? Hrmh... Look, it's not important. You should just come lie next to me, Commander!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Geesh, the schedule looks packed. If you ask little ol' me politely I might give you a hand... Huh? O-okay, let's start with this document... Bleh, I feel like I just dug my own grave.|It's weird. I'm just watching you go through your paperwork... and yet I don't feel bored in the slightest...|*yawn*, I may not be bored, but I'm so tired I can't move a muscle. I want the princess treatment, Commander.",
	touch = "My dress has come loose~ Fix it please~",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 404048,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Oh. You knew I was just pretending to sleep?",
	feeling2 = "",
	login = "Good luck with your work today. Me? I'm just gonna lie here and relax. Bride's privilege, you know? Hehehe~",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[404050] = {
	hp_warning = "Hardly even a scratch.",
	feeling3 = "My love for antiques is akin to a yearning for something one cannot have. \"If I were born in that era, how would my life have been different\"...I wonder if thinking this way is just human nature?",
	mail = "Here's some mail for you. Oh... Don't mind me. I suddenly felt like putting pen to parchment for some reason...",
	expedition = "The commission team has returned to port. Hurry and go see them - you made a promise, and ought not to break it.",
	win_mvp = "I won't let anyone down, regardless of who it may be.",
	home = "Have you returned safely? The battlefield is cruel indeed. Do not allow a single victory to make you forget that fact.",
	unlock = "I am battlecruiser Brünhilde, Walküre of the Iron Blood. As fellow bearers of great responsibility, let us hone one another as we press forward.",
	touch2 = "I wonder when I'll be able to fix this nasty habit of yours.",
	mission = "We've been issued a new mission. Let us strive to not let the other party down.",
	vote = "",
	drop_descrip = "O-class battlecruiser – Brünhilde.",
	feeling4 = "Have you ever wanted to go back in time? To feel nostalgia from your youth, experience something again, or resolve something you regret..? Do you ever think about those things?",
	lose = "Valhalla will have to wait... For now, we retreat!",
	feeling1 = "Further displays of weakness will only earn you more contempt from me.",
	skill = "I'll run you through!",
	upgrade = "Thank you. Call upon me for your next sortie.",
	propose = "One day, when I look at this ring engraved with the runes of time, I may remember the moment we first met. Let us hone one another as we press forward, as bearers of the same great responsibility...",
	feeling5 = "So your desire for a better future outweighs your nostalgia for your past? Quite the astute answer. Then, promise me this—don't stop until you reach that future you dream of. If you ever feel like giving up, I'll be there to remind you of this promise you made with me.",
	main = "I would like you to hold on to the armaments I've used instead of throwing them out. That way, when I look upon them, I will be able to remember those who fought at my side.|Let me check that list one more time. I'd like to prevent any failures from small mistakes getting overlooked.|That object on your desk looks like quite the antique. Where did you get it? Oh, it's no big deal, it just happened to catch my eye...",
	touch = "Cut to the chase. I prefer keeping things to the point.",
	voice_key_2 = -1,
	mission_complete = "Done with the mission already? You work pretty efficiently.",
	battle = "The smell of gunpowder... Yes, I have returned to the battlefield once more!",
	id = 404050,
	gift_dislike = "",
	gift_prefer = "Quite tasteful. Where did you get this?",
	profile = "I am the Iron Blood battlecruiser, Brünhilde. I am a Plan Z ship that was never completed, just like some of my fellow ships you've met already. I shall fulfill my duties to the utmost of my abilities, so you need not worry when entrusting missions to me.",
	voice_key = 40405,
	headtouch = "",
	feeling2 = "I love antiques. When I look at them, I feel as if I'm being transported back to a bygone era. But, for me, the word \"past\" refers to something far, far more distant.",
	login = "Looks like you showed up to work on time. Though it may be your duty, your strength of will is admirable.",
	detail = "This music box? Ah, it lost its voice many years ago, but I figured it'd be a shame to throw it out, so I held onto it.",
	couple_encourage = {
		{
			{
				49905
			},
			1,
			" Hmm, let's go for a drink when we return.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[404051] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Heh. This point now belongs to me!",
	home = "...What an interesting texture. ...Oh, Commander, thanks for setting the bread up again.",
	unlock = "Hah! This donut now belongs to Brünhilde! Alright, now for the finish line... C-Commander? Sorry, but there's no time for chit-chat... I'll be going now!",
	touch2 = "You're really such a... Once you untie this binding, I'm going to give you a piece of my mind.",
	mission = "",
	vote = "",
	drop_descrip = "Hah! This donut now belongs to Brünhilde! Alright, now for the finish line... C-Commander? Sorry, but there's no time for chit-chat... I'll be going now!",
	feeling4 = "",
	lose = "I guess even I have my off-days...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Ägir, why don't you try this bread-eating race? Don't say you can't do it, do it for the Commander, won't you?|Was that... Isuzu and some Meowfficers that just sprinted past us? What kind of event are they participating in...?|Racing is a sport that originated a long time ago. Try as I might, however, I can't understand all of the weird rules that have been added to it...",
	touch = "I'm grateful that you brought me something to drink, but I can't exactly bring it up to my mouth right now...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Victory at all costs!",
	id = 404051,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Oh, you're back? Judging from how much you're sweating, your battle must've been grueling as well... In any case, want to help untie this rope first?",
	detail = "Not only are we supposed to run with our hands tied behind our backs, but we're also supposed to jump and carry bread in our mouths while we're at it... This so-called \"sports meet\" is probably more entertaining for the crowd than for us.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[404060] = {
	hp_warning = "This is within the expected range of damage. Continue the battle!",
	feeling3 = "(The Commander replaced the flowers in the office with calla lilies today. We're the only ones in and out of the office lately. Is this your attempt at getting me to deduce the meaning of those flowers? Calla lilies mean \"pure and pious love\"... Eep!)",
	mail = "You have new mail. Beyond the contents of the mail, there's much to be gleaned from the sender's name and address, the ink they used, their handwriting, and more.",
	expedition = "The personnel in charge of the commission are back at port. I made a reward list for you.",
	win_mvp = "A victory based on thorough calculation and deduction.",
	home = "Hmm? Why did you return at a time inconsistent with my calculations? Give me details... It took extra time for you to buy me a gift? Oh... I-I see...",
	unlock = "I'm Alvitr, O-class battlecruiser and Walküre of the Iron Blood. My name symbolizes ultimate wisdom, and I plan to prove the worthiness of that name. You may rely on me – I will manage your affairs now.",
	touch2 = "I... couldn't have predicted this... *blush*",
	mission = "Commander, do your missions in the order of priorities I've assigned. Ensure they do not affect other plans adversely.",
	vote = "拉票描述",
	drop_descrip = "O-class battlecruiser – Alvitr.",
	feeling4 = "(The Commander said my name 93 times today. Upon staring at me for up to a minute without looking away, the Commander's uncertainty and body heat rose. I knew it... You're in love with me!)",
	lose = "Did I overlook something...?",
	feeling1 = "You've strayed so far from my calculations. Hmph... Fine. I'll devise a stricter plan to get you back on track as soon as possible.",
	skill = "Pierce and penetrate!",
	upgrade = "Changing the present means changing the future.",
	propose = "You think I didn't calculate this moment long ago? W-well... You're right. I was so focused on your every little move that I'd already removed this possibility from my deductions... Phew. Basically, umm... What a welcome surprise!",
	feeling5 = "Hm? Why did I call you here so suddenly? Based on your recent behavior, I judged that now was your ideal time to confess to me... Huh? You just happened to change the flowers that day? And when you stared at me and heated up, that was just because overtime had you exhausted? N-no, that can't be...!",
	main = "All so-called foreknowledge and omniscience are simply the result of finding every last detail and applying adequate analysis and deduction. From my point of view, you're very capable of the same.|I monitor every last one of your movements, specifically because I have the responsibility to protect you and look after you, though I must accept that my own desires differ... Yes. I trust you understand.|Here's the file you were looking for, Commander. Hm? How did know? I saw your gaze shift to the desk, and then unconsciously moved to gather the scattered documents. Simple as can be, no?",
	touch = "There's dust on me? ...Thank you. (whispering) So this is how the Commander justifies touching people...",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Please accept your rewards quickly... Also, I should thank you for following the proposal I made.",
	battle = "A Walküre's spear points the way to victory!",
	id = 404060,
	gift_dislike = "",
	gift_prefer = "Did you figure out what I like from watching me? I like that.",
	profile = "I am Alvitr of the Iron Blood, a warrior come to serve you and a companion come to accompany you. How do I know so much about you? Heheh... That would be the result of analyzing existing information, efficient and precise observation, and rigorous deduction.",
	voice_key = 40406,
	headtouch = "How cute.",
	feeling2 = "My desire is for you to rely on me. Hmph, this doesn't come just from confidence in my own abilities, but also because I exist for you to rely on me.",
	login = "Good morning, Commander. I've already prepared a daily action plan for you. Feel free to reference it.",
	detail = "The daily action plans I provide should be 99% consistent with the plans you make yourself, not because of predictive powers, but because I've tracked your actions. A logical conclusion based on analysis of ample data.",
	couple_encourage = {
		{
			{
				49905
			},
			1,
			" Don't underestimate how important minor details can be.",
			0
		},
		{
			{
				40405
			},
			1,
			" Walküres, form up! Today, we seize victory!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[404061] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Hmm... Off again. Did you have detention, or something? Oh, that thing in your hand... I see. You bought ice cream for me.",
	unlock = "Oh, Commander. You may have noticed that the air conditioner is busted. I surmised from its volume levels that it was at its limit, but now that it's broken... life has become a struggle.",
	touch2 = "Just as impatient as I expected... *blush*",
	mission = "",
	vote = "拉票描述",
	drop_descrip = "Oh, Commander. You may have noticed that the air conditioner is busted. I surmised from its volume levels that it was at its limit, but now that it's broken... life has become a struggle.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Sometimes, using our limited ingenuity to play little tricks on someone we love can make life more fun. Huh? You've been waiting outside the door for me to get ready with exactly that in mind? A-aah...",
	main = "You also noticed the sound the air conditioner was making and brought a toolbox to come fix it? ...You're getting more and more conscientious, Commander.|The heat makes it impossible to think straight. For example... I can't tell if how you're reacting is because of the heat, or because of seeing me like this...|I have one question for you to ruminate over, Commander. Did I predict that you'd come to the staff room at this time?",
	touch = "I think you should take off your jacket, too.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 404061,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "You'd tie up my hair for me? Thanks.",
	feeling2 = "",
	login = "You're just in time. Let's start reviewing today's lesson results. Heh, I'll be the perfect aide for you.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[404070] = {
	hp_warning = "It's all under control!",
	feeling3 = "Your tactics come so far out of left field that they throw my strategy into disarray. What a Commander you are... Let me think! I'll turn the tables here, I promise!",
	mail = "Commander, it's time to check your mail. Please begin as soon as possible.",
	expedition = "The commission fleet is back on schedule, and their goods have been inspected. Here's the list for your perusal.",
	win_mvp = "Perfect. The rest of the operation should go just as I planned.",
	home = "Commander, you're home later than expected. Did you run into any issues? Huh? You were just taking a little walk? D-did my schedule unduly stress you? I'll fix it right now!",
	unlock = "Battlecruiser Admiral Zenker reporting for duty. I've put together a strategy based on the port's current conditions, so if you'd take a look at that first... Huh? You want me to go on a tour first?! W-wait, this doesn't fall under the twelve potential scenarios I planned for!",
	touch2 = "W-wait, not that yet... M-my heart isn't ready!",
	mission = "Commander, please finish your missions soon. Else they'll conflict with other work I have scheduled for you later.",
	vote = "拉票描述",
	drop_descrip = "Type 1928 battlecruiser – Admiral Zenker.",
	feeling4 = "It's hard to focus on work when you stare at me... Umm... I guess that's my own problem, though...",
	lose = "The situation has changed?! I-I'll revise my strategy right away...",
	feeling1 = "You do nothing but disrupt my plans. It's troubling.",
	skill = "Dance in the palm of my hand!",
	upgrade = "These power-ups are, of course, all part of the plan.",
	propose = "I've rehearsed every little word and action of this little moment so many times now, but when I'm faced with you, I realize it was all unnecessary... There are so many things I want to say to you, but I don't know where to start. Commander... Please, let me take my whole lifetime to share it all with you!",
	feeling5 = "All of my plans fall into disarray when it comes to you lately... It's not your fault! I just can't control my feelings well. I need to calm down more, but just thinking about you drives me crazy... You must understand, surely.",
	main = "Commander, I've planned our next mission's defensive deployments and offensive routes. There are six things I need you to check on, though, so please take a look.|You need a pen? You can have the grey one in the blue pen holder... Put it back when you're done, please.|I've simulated this strategy countless times. It should be theoretically perfect... Ugh, I still need backup plans.",
	touch = "Commander, your next affair is... a last-minute appointment? Okay, I'll handle your work... Wait, it's a date with me?! I-I wasn't informed of thiiis!",
	voice_key_2 = -1,
	mission_complete = "Finished ahead of schedule? Then you've earned a good break until our next assignment.",
	battle = "All according to plan... Commence combat!",
	id = 404070,
	gift_dislike = "",
	gift_prefer = "Oh... Goodness, I love it, thank you! I never thought you'd get me this...",
	profile = "I'm Admiral Zenker, a battlecruiser for the Iron Blood. My birth here was unexpected, but as you've given me a reason to exist, I plan to live up to your lofty expectations of me.",
	voice_key = 40407,
	headtouch = "Huh?! D-don't do that without warning, please!",
	feeling2 = "Commander, I've finished preparing a battle plan for your review. Please provide any revisions in the next thirty minutes.",
	login = "Commander, I sorted files for review by priority. Just check them in order, and you'll be fine.",
	detail = "I already simulated this move in my brain. Next, you'll... W-wait, that's not what I thought you'd... I have to recalculate this... A-am I going to lose?!",
	couple_encourage = {
		{
			{
				40406
			},
			1,
			" Let's seize a perfectly planned victory!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[404071] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Commander, isn't it your break time? Are you sure you can change your plans just to help me practice lines? ...You just wanted to be with me? Heh, you always know just how to surprise me...",
	unlock = "You want me to spill the beans? Heh. Hate to disappoint you... Phew... Did that sound good? I thought up other responses I could try, too.",
	touch2 = "Ack?! Are we ad-libbing?! U-umm, let me think of how to react to this... Hmm...",
	mission = "",
	vote = "",
	drop_descrip = "You want me to spill the beans? Heh. Hate to disappoint you... Phew... Did that sound good? I thought up other responses I could try, too.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Why won't I look you in the eye? Umm... The script does say that I should, but when I do, I suddenly forget my lines. Um, let me try again... Nope! Not happening...",
	main = "There are a whole lot of people out there who wanna see you dead. Why waste time on little old me? I'll never give you my true identity.|You know your measly interrogation isn't enough. This will amount to nothing.|This is my first time being in a movie. It's fun to prepare and perform with everyone. I just wish people would stop being late and disrupting plans.",
	touch = "You can leave the cuffs as they are – they don't hurt. It's easier to get immersed in the role, too... Are you worried about me, Commander?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 404071,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Too bad for you, you'll never get a look inside my mind. Heh.",
	feeling2 = "",
	login = "Urgh, the light... Ah, you're here. Still haven't given up yet, I presume? Wait, I don't think that came out right. It's hard to be mean when I'm dealing with you.",
	detail = "You think my lines and performance are perfect? Well, I did practice a lot on my own... This is the first time anyone's ever taken my rehearsals seriously.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[405010] = {
	hp_warning = "Everyone, get behind me.",
	feeling3 = "You're not a bad commander... What? Is it so strange for me to give compliments? ... You're simply overreacting.",
	mail = "Be diligent about checking your mail.",
	expedition = "... The commission team has returned. I'll go greet them first.",
	win_mvp = "Such honors may please a weakling, but I am strong.",
	home = "You've done well. You've earned your rest.",
	unlock = "Guten Tag, I am Bismarck. I have fought many foes on many fronts. You may call upon me whenever there is a problem.",
	touch2 = "I... am not good at expressing myself. Please do not tease me on purpose...",
	mission = "Those who cannot finish their missions have no right to stand on the battleground.",
	vote = "",
	drop_descrip = "Bismarck-class battleship – Bismarck.",
	feeling4 = "Why are you staring at me? Do I have something on my face? I'm pretty, you say...? Um, thank you...",
	lose = "For tarnishing my pride... next time, you will pay with your lives.",
	feeling1 = "Stay out of my sight.",
	skill = "Truth can only be found within our range!",
	upgrade = "Danke.",
	propose = "... Commander, what kind of expression should I have at a time like this? I should... just smile?",
	feeling5 = "I... know that I'm not the best with words, but.. I want you to know that... I enjoy being at your side...",
	main = "Is there a problem? Perhaps my combat experience could prove useful? |\"Operation Rheinübung?\" I don't have fond memories of it... |Such a slovenly expression, Commander. Now! Lift your chin, puff out your chest, and let me see those eyes! Hut!",
	touch = "Keep your hands to yourself.",
	voice_key_2 = -1,
	mission_complete = "I'm leaving the mission rewards over here...",
	battle = "Follow me, not Eugen. Come – we shall face our opponents, no matter how numerous they may be!",
	id = 405010,
	gift_dislike = "",
	gift_prefer = "Why, this is...! Danke schön!",
	profile = "I am the Iron Blood battleship entrusted with the name Bismarck. Allow me to prove that Iron Blood engineering is the finest in the world, no matter the battlefield. Eager to see for yourself?",
	voice_key = 40501,
	headtouch = "",
	feeling2 = "I am not so easily impressed.",
	login = "I look forward to working with you.",
	detail = "Is there something on my face?",
	couple_encourage = {
		{
			{
				40502
			},
			1,
			"Tirpitz... forgive me...",
			0
		},
		{
			{
				40303
			},
			1,
			"Eugen, don't go overboard with your games.",
			0
		},
		{
			{
				4
			},
			5,
			"No one can stop the march of the Iron Blood.",
			3
		}
	}
}


_G.pg.base.ship_skin_words[405011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Even at the most lavish banquet, it is your responsibility as commander to be well-informed should the situation change.",
	expedition = "Once the commission fleet has finished dropping off their supplies, let's invite them to the banquet as well.",
	win_mvp = "",
	home = "Let us raise our glasses to the heroes who have returned from battle.",
	unlock = "My sincerest apologies for the delay, Commander. Ah, excuse me... as the fleet leader of the Iron Blood, I'm expected to wear this outfit to various formal occasions. Just putting it on seems to make me inadvertently change the way I speak...",
	touch2 = "C-Commander... don't tease me like that...",
	mission = "Having unfinished work will turn even the finest wine into vinegar. Isn't that right, Commander?",
	vote = "",
	drop_descrip = "My sincerest apologies for the delay, Commander. Ah, excuse me... as the fleet leader of the Iron Blood, I'm expected to wear this outfit to various formal occasions. Just putting it on seems to make me inadvertently change the way I speak...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "In front of my compatriots, I always had to be adamant, solemnly spearheading the march of the Iron Blood. To be the leader of the Iron Blood's indomitable fleet, I had to lock away the Bismarck that struggled to express herself... But when I'm with you, Commander, I can set aside that burden, just for a little bit...",
	main = "Commander, would you invite Tirpitz for me? Apologies, I'm... still not sure how to ask her myself. |I can keep a lot of people satisfied merely by sitting here with a smile... but only because of my status as the fleet leader of the Iron Blood. |As a leader, I must sometimes say and do things that I do not believe in. Commander, I hope you never lose sight of who you are.",
	touch = "A dance...? Oh, no, I wouldn't turn one down, I just haven't been asked until now...",
	voice_key_2 = -1,
	mission_complete = "A decoration for the banquet? Splendid work.",
	battle = "",
	id = 405011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "How's your work coming along, Commander?",
	detail = "Apologies, Commander. Am I acting differently from usual? At times, I don't even know which is the real me...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[405012] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Here's your mail. I... hope it's not an order of coffee from Mainz...",
	expedition = "Looks like the fleet has returned from their commissions... Thiele, I'll leave them to you.",
	win_mvp = "Data collection is complete. Take solace in the fact that you'll be useful after your demise.",
	home = "This cup is a prize for the hero who has graciously returned from the battlefield.",
	unlock = "Welcome, what would you like to order? ...If you want, we can drop this charade. I'm not used to being a waiter anyway, so I prefer it this way. Hehe.",
	touch2 = "...*sigh*...",
	mission = "A new mission... I wonder who would be the best fit for it.",
	vote = "",
	drop_descrip = "Welcome, what would you like to order? ...If you want, we can drop this charade. I'm not used to being a waiter anyway, so I prefer it this way. Hehe.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I never thought I'd be standing in front of you in this outfit like this. Still, whether it was fated or not, I'm glad that you were able to see a different side of me... Hm. This cup's on me. Please, enjoy yourself, hehe.",
	main = "Truthfully speaking, this outfit feels more like that of a waitress than that of a maid... Though, I've been told there's not really much of a difference...|Tirpitz, compile today's sales data and send it to Friedrich. Figuring out what to do with the data we've collected is her specialty.",
	touch = "Eugen did tell me she wanted me to try this \"physical contact\" thing with you.",
	voice_key_2 = -1,
	mission_complete = "The remunerations for the missions we've completed are here. I'm sure Graf and the others will be ecstatic to hear.",
	battle = "I can take on any number of them!",
	id = 405012,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Oops, I almost wrote down \"the usual\" for your order... Ahem, what would you like?",
	detail = "I feel far more at ease here than when I'm busy with research or the Iron Blood. I really hope that you feel the same way that I do.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[405013] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Did your letter come with a seasonal greeting card?",
	expedition = "Please receive the commission team on my behalf. Dressed like this, well...",
	win_mvp = "",
	home = "Outstanding work, Commander. Take a break, then once you're done, could you help me here?",
	unlock = "C-Commander? Well, as you see, I was wrapping your Christmas present, but now the surprise has been spoiled. I suppose this moment calls for a \"Merry Christmas,\" hmm?",
	touch2 = "Although my present turned out half-baked, as long as you're happy with it...",
	mission = "Share the burden of your unfinished missions with me. The sooner they're done, the longer we can enjoy this holiday.",
	vote = "",
	drop_descrip = "C-Commander? Well, as you see, I was wrapping your Christmas present, but now the surprise has been spoiled. I suppose this moment calls for a \"Merry Christmas,\" hmm?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Even with Eugen's advice, I had to rack my brains to come up with a way to express my love through actions. Unfortunately, it also ended in failure... Close your eyes, will you? *smooch*... Now it's all good. Frohe Weihnachten.",
	main = "I'll admit, I've had a little to drink. It's my first time doing something like this, and a bit of alcohol helps me feel more natural and empowered, I suppose?|This was my chance to give you a surprise... If only I hadn't made that noise, this would've gone very differently.|Do you like this outfit? As long as you like it, it has done its job as a present.",
	touch = "Do you want my help with the unwrapping?",
	voice_key_2 = -1,
	mission_complete = "Is it just me, or are our rewards better than usual?",
	battle = "",
	id = 405013,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Consider this a thank-you for tying up my hair.",
	feeling2 = "",
	login = "Wrapping myself up right in front of you... It's rather odd, don't you think?",
	detail = "Why I chose this? Because of Eugen's advice – \"If you're bad at expressing your feelings with words, do it with actions instead.\" I simply did what she suggested.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[405018] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Read your new letter. It no doubt contains equally important information to me.",
	expedition = "Let's speak to the commission te– Wait, no, I can't go out looking like this. They'll be shocked.",
	win_mvp = "I offer you this brilliant victory – to decorate our journey of glory.",
	home = "You okay? Didn't push yourself too hard? ...I'm only imitating the way you show concern for me. I suppose I failed to pull it off at all. Heehee.",
	unlock = "You've arrived, Commander – or rather, my sweetheart in eternal vow. I know I can't wear a stiff expression forever, but when I think about the days to come under your guidance, I feel so needy all of a sudden. Yes, it's like you say... just keep smiling.",
	touch2 = "Bride dresses really do make you... No, never mind. Um, continue... *blushes*",
	mission = "",
	vote = "",
	drop_descrip = "You've arrived, Commander – or rather, my sweetheart in eternal vow. I know I can't wear a stiff expression forever, but when I think about the days to come under your guidance, I feel so needy all of a sudden. Yes, it's like you say... just keep smiling.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I thought getting wed would make it easier for me to make expressions – as it turns out, that's not the case. That said, I feel more true to myself, and I've gotten more feelings I want to express... Fine just the way I am? That's good... because I like you this way, too... *blushes*",
	main = "Being the leader of Iron Blood, I'm used to walking the red carpet. This occasion, however, is a first for me. I am wholly reliant on your help for this entire day. Heehee.|Don't rush yourself – follow the path of your ideals at a steady pace. There is plenty time for both of us.|It's incredible that there's always something we can both talk about. Not just fighting or leadership, but also music, hobbies, and daily life. It's embarrassing to admit, but there aren't many people I can have such profound conversations with.",
	touch = "The ring you gave me is right here. Do you want to... touch it?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Gather under our banner!",
	id = 405018,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "There doesn't need to be only one leader. The position of assistant to you is very important. So am I, you say? Yes, you're right.",
	detail = "Have you decided where we'll go on our honeymoon? Oh, I'm not trying to rush you, I just thought I'd offer some advice if you couldn't decide. Maybe that's being too... proactive of me.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[405020] = {
	hp_warning = "No one would protect those who asked for their own destruction.",
	feeling3 = "Those who have nothing to lose also have nothing to fear... But is this kind of bravery really anything to be proud of?",
	mail = "More mail for you... Ah, I'm envious.",
	expedition = "The commission seems to be complete... Next time, why don't you let me go? I'm a little curious.",
	win_mvp = "So this... is the taste of victory.",
	home = "Commander, you should show your face on the battlefield more often. If you stay behind your desk for too long, you may one day forget the meaning of life.",
	unlock = "I was imprisoned in the north for so long, unable to return home, and now you want me to follow you? ...Very well. It is up to you to show me the world.",
	touch2 = "I'll think of how to deal with you later.",
	mission = "Finish your missions properly. Perhaps you will one day realize the joy of having any purpose at all.",
	vote = "",
	drop_descrip = "Bismarck-class battleship, Tirpitz.",
	feeling4 = "The worst feeling in the world is not knowing whether to continue waiting or to give up hope. Commander, are you someone worth waiting for?",
	lose = "So this is... the frustration that comes from failure and fear.",
	feeling1 = "In the end... are you just another incompetent fool, unable to command me?",
	skill = "Checkmate.",
	upgrade = "If you have no opponents, all the might in the world is meaningless.",
	propose = "Ahh... so this is the warmth of one's beating heart... It's melting the cold and despair remaining within me. Danke sehr, Commander. The \"Queen of the North\" is no longer alone.",
	feeling5 = "Ahh... I see. I thought I was used to the cold and embraced it, but that was just because I had forgotten the joy of human interaction and the warmth of being with someone... But now I remember...",
	main = "Big sister... Now that you mention it, I think I might actually have one... Ah... I've already started to forget.|Can you comprehend how it feels to watch the battlefield from afar, unable to do anything but lament the cruelty of war?|Strategic reasons? I was installed with cannons... but they were never meant to be fired. Ironic, isn't it?",
	touch = "Are you cold?",
	voice_key_2 = 405023,
	mission_complete = "Mission rewards... how nice.",
	battle = "Commander, I shall fight for your sake.",
	id = 405020,
	gift_dislike = "",
	gift_prefer = "This feeling of joy is... Thank you.",
	profile = "It's a bit hot... Ah, sorry. I am Tirpitz. Because I was stuck in the north by myself for so long, people suddenly started calling me the \"Lonely Queen of the North.\" If you think it's a good nickname, then you do not fully understand... how soulless those words are.",
	voice_key = 40502,
	headtouch = "",
	feeling2 = "I have already grown used to the cold solitude of the North. At this point, it's natural for me to have no expectations.",
	login = "Once you get used to waiting, you lose sight of what you were waiting for.",
	detail = "Choose your enemies carefully, Commander.",
	couple_encourage = {
		{
			{
				40501
			},
			1,
			"Sorrow is a mask unbefitting your countenance, sister.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[405021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "",
	unlock = "In the past, I never saw summer as more than a hot and humid slog... But now? My outfit probably says it all... Let's go, everyone's already waiting for us at the beach.",
	touch2 = "Even though it's summer... there are still some things you shouldn't do...",
	mission = "Even I can't get fired up about doing missions during the summer... because it's too hot...",
	vote = "",
	drop_descrip = "Summer... In the past, it was always just a hot and stifling season... But now...? Doesn't my outfit tell the whole story? Let's get going, there's bound to be a lot of people on the beach.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "As long as you're by my side, even looking off into the horizon is meaningful. |Some of my colleagues seem to mistake me for some unapproachable ice queen... Perhaps playing beach volleyball with them would help... |The sunset and the beach at night are wonderful views. When you're done with work, want to accompany me for a walk along the shore?",
	touch = "It's a bit stuffy... Commander, would you mind turning up the air conditioner?",
	voice_key_2 = 0,
	mission_complete = "",
	battle = "",
	id = 405021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, there's no need to rush yourself. There is meaning in simply waiting for you.",
	detail = "Commander, enjoy yourself to the fullest. Our hard-fought battles are for the sake of peaceful moments like these... and our hard-earned breaks provide us with will to keep fighting.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[405022] = {
	hp_warning = "",
	feeling3 = "",
	mail = "We're getting all these requests to dance with you, Commander. Maybe I should put in one as well?",
	expedition = "Commander, it seems like another commission has been completed. Go ahead and take care of it; I'll be waiting for you right here.",
	win_mvp = "If she was here... how would she have fought this battle?",
	home = "Commander, do you wish to know how I feel about Bismarck?",
	unlock = "I bet Bismarck must've been thinking about how to invite me to the party, but ended up asking you to do it, Commander. Hehe... Let's get going soon. It's best not to keep her waiting.",
	touch2 = "",
	mission = "Do we have new missions? Don't worry, Bismarck won't mind waiting a bit longer.",
	vote = "",
	drop_descrip = "I bet Bismarck must've been thinking about how to invite me to the party, but ended up asking you to do it, Commander. Hehe... Let's get going soon. It's best not to keep her waiting.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "In the past, the word \"sister\" meant nothing to me. But the moment I laid eyes on her, I knew in my heart... Yes, she is indeed my sister. |Behold, she basks in everyone's adoring gaze as they orbit around her upon the resplendent firmament of the stage, as if she is the center of the universe... But you and I both know, that is not where she wants to be. |Waiting for her to find us instead of taking the initiative to find her might be a bit of my nasty streak showing, but I'm still the little sister here. I have that right, don't I?",
	touch = "",
	voice_key_2 = 0,
	mission_complete = "Commander, we don't have too many of these banquets, so don't get too anxious about work. Let's have something to eat first.",
	battle = "",
	id = 405022,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "So you've come, Commander. Don't be anxious, the night is still young.",
	detail = "Truthfully, I still have a hard time conversing with Bismarck... But at least now, time is on our side. There will be plenty of things for us to talk about in the future, wouldn't you agree?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[405023] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "",
	unlock = "They have a peculiar way of wishing a happy New Year in the Sakura Empire. In line with their traditions, I've put on this new outfit. I hope it doesn't... look strange on me. ...You like it? I see... That being the case, I'll keep wearing it for the time",
	touch2 = "*sigh*... Could you please mind your manners in public?",
	mission = "",
	vote = "",
	drop_descrip = "They have a peculiar way of wishing a happy New Year in the Sakura Empire. In line with their traditions, I've put on this new outfit. I hope it doesn't... look strange on me. ...You like it? I see... That being the case, I'll keep wearing it for the time",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "I must give my regards to my sister... But how I should face her, I do not know. Could you come with me, Commander?|Alabama proposed playing a type of badminton enjoyed around New Year's. I suppose that could be fun. ...The loser will have ink rubbed on their face? On second thought, I will pass.|I've long been used to the cold, but sometimes, I find myself reaching out towards the warmth... Commander, can I... come a little closer? ",
	touch = "It feels warm... A nice change of pace.",
	voice_key_2 = 0,
	mission_complete = "",
	battle = "",
	id = 405023,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I waited for you, Commander. Now let us go and wish everyone a happy New Year, before aircraft come chasing after us.",
	detail = "My Sakura Empire friends told me that the pine tree is like an anchor point for the gods. Much like what you are to me, Commander... Oh, just talking to myself. Hahah.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[405024] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "This ends now.",
	home = "Welcome back, Commander. While I'm used to being kept waiting, being kept in suspense is something I can scarcely put up with.",
	unlock = "It's all right, I just got here myself. I will say, it's strangely reassuring to know I'm not the only one nervous on this day.",
	touch2 = ".........",
	mission = "",
	vote = "",
	drop_descrip = "It's all right, I just got here myself. I will say, it's strangely reassuring to know I'm not the only one nervous on this day.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Having you all to myself fills my heart with joy, even when we're simply killing time.|I used to envy Hipper's and Eugen's closeness. Now Bismarck and I get along better than ever, thanks to you.|Indeed, this is a happy reunion. Having something to look forward to can warm the heart on even the most frigid winter nights.",
	touch = "You should sit down if your feet ache. It's true Bismarck overexerts herself, but that's no reason for you to do the same.",
	voice_key_2 = 0,
	mission_complete = "",
	battle = "",
	id = 405024,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "No need to rush, Commander – we have plenty of time. If there's one thing I'm used to, it's waiting.",
	detail = "I cannot picture Bismarck going out on a date... I know I'm the one who asked you to come, but I didn't foresee she and I both would be so lacking in social grace.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[405025] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Heehee. This glory belongs to you who gave it your all. I merely did what was expected of me.",
	home = "Your lap time is getting better and better... I need to pick up the pace as well.",
	unlock = "Congratulations on your new record, Commander. This glory alone has given meaning to my time spent waiting. Now, rest assured while I do maintenance on your car.",
	touch2 = "At least save it for after the training...",
	mission = "",
	vote = "",
	drop_descrip = "Congratulations on your new record, Commander. This glory alone has given meaning to my time spent waiting. Now, rest assured while I do maintenance on your car.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "It's almost showtime. Whether you will earn new glory or face setbacks, I'll be here, waiting for the start of your next journey.",
	main = "A change of tires will let you exhibit your fullest potential. Give me a minute... I'll be done before you know it.|Your invitation to enter the race together thawed the frost inside my heart... Ah, this brings back memories.|Whew... This is a bit tricky... Hm? You'll give me a hand? Okay, then give me your hands. Don't let go... until I tell you to.",
	touch = "Don't worry. It's just moving a tire. I can do it.",
	voice_key_2 = 0,
	mission_complete = "",
	battle = "",
	id = 405025,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Park your car here, Commander. Your next tires are ready, so let's get them swapped out.",
	detail = "I will become your biggest supporter so you may run with all you have.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[405030] = {
	hp_warning = "If you don't plan on dying here, then focus up!",
	feeling3 = "Working for you is not the same as trusting you. The fact that you can command so many people... Or rather, be adored by so many, means you of all people should understand.",
	mail = "There's some mail. Looks like it contains confidential information... I see.",
	expedition = "The fleet's returned from their commissions. Hurry up and decide whether you or I go and greet them.",
	win_mvp = "...Piss off, weaklings. Just thinking about the amount of ammo I've wasted on you sorry lot makes me want to vomit.",
	home = "Everyone made it back, huh? Not bad.",
	unlock = "I am Ulrich von Hutten, the symbol of the Iron Blood's hopes and regrets. Whether my arrival is a cause for celebration or for despair is up to you to decide. I shall respond in kind.",
	touch2 = "I'm not sure whether I should praise you or teach you your place...",
	mission = "Missions, huh? Whether we do them or not is up to you. That is your freedom.",
	vote = "",
	drop_descrip = "H-class battleship – Ulrich von Hutten",
	feeling4 = "You spineless fool who doesn't even know how to doubt others... I've come to realize that you've spread deeper and deeper through me, just like a poison. Tsk... I'll return the favor, mark my words.",
	lose = "I'll back off since we lost, but don't count on it happening again.",
	feeling1 = "You sowed these seeds yourself. It's your mess to clean up, not mine.",
	skill = "Get lost, you're in the way.",
	upgrade = "In order to create a peaceful world where power is not needed, what you need is power. How paradoxical... Oh, don't mind me.",
	propose = "Embrace it, drown in it... Just as you put the curse of trust on me, I'll place it on you. Trust... Let the poison called affection consume you. Become just like me. Don't you know? You and I are already one.",
	feeling5 = "I told you I'd return the favor. Yep, I'll suck the poison out of you before it has a chance to spread throughout your body. This is my duty... my responsibility, for the person who did the same for me. But maybe I'm already too late? Hehehe...",
	main = "You want to know more about my rigging? Sure, I can move it like I want to, but there are times when it's pretty troublesome.|The Mysteries of the Port? Just leave it as it is. That's the only way it'll continue to keep your curiosity piqued, isn't it.|Think for yourself... Though you can't live selfishly, you need to live for the sake of something you really desire. That way, even if you die, it won't be in vain.|It might be a surprise for you, but I do have hobbies I enjoy. And it's not like I become a different person when I do.",
	touch = "If you've got something to say, spit it out. I'll hear you out.",
	voice_key_2 = -1,
	mission_complete = "The rewards have arrived. Kick back and enjoy the moment. You're going to miss out on it if you don't, and all that'll be left is emptiness.",
	battle = "...Tsk. This ammo is wasted on you lot!",
	id = 405030,
	gift_dislike = "",
	gift_prefer = "Turning this down would be a terrible waste. Hmph.",
	profile = "My name is Ulrich von Hutten. So long as you call me that, that is who I am. A name is nothing more than that.",
	voice_key = 40503,
	headtouch = "Hmph. You don't make any damn sense.",
	feeling2 = "Trust is like a poison—once it enters your body, it destroys you. The only way to protect yourself is to be wary of others.",
	login = "You're here. See that massive pile of paperwork on your desk? The two of us will be spending lots of quality time here until that's taken care of.",
	detail = "If you want peace of mind, just don't bother worrying about anyone else. We may be born into this world, but our keels and souls aren't at the mercy of others.",
	couple_encourage = {
		{
			{
				49902
			},
			1,
			"Looks like you and I are dancing to different tunes.",
			0
		},
		{
			{
				20705
			},
			1,
			"If you're interested in something, just face it head-on, young lady.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[405031] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Looks like things worked out just fine.",
	home = "*Glug, glug* ...Ahh, that hits the spot. Tsk, it's already empty... Sorry, mind grabbing me another can?",
	unlock = "*sigh* Do you really have to bother me during my break? ...It's a joke, no need to take it so seriously. I was looking for someone to kill some time with anyway.",
	touch2 = "Tsk... Again with that shit just 'cuz we're here? What a pain in the ass...",
	mission = "So, you accept a mission and then immediately begin procrastinating...? What a piece of work you are. Want me to do the same thing to you?",
	vote = "",
	drop_descrip = "*sigh* Do you really have to bother me during my break? ...It's a joke, no need to take it so seriously. I was looking for someone to kill some time with anyway.",
	feeling4 = "",
	lose = "Tsk, they got me...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "I really need to head back, but the little'un just... *sigh* what a pain in the ass.|The fan outside is so frickin' loud, but I really need my alone time... Huh? Who put these damn stickers here...?|You already know what I'll do to people who start shit inside, don't you? ...Yep. I'll give them their one warning.|I'm not really worried about Elbe causing trouble. Surprisingly, she knows when to stop. ...Well, at least she's not my main source of worry.",
	touch = "\"Welcome back, Master. May I take your order?\" ...You happy with that?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 405031,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "The little'uns really like when you do this to them.",
	feeling2 = "",
	login = "What's going on with you today? Spill it.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[405032] = {
	hp_warning = "",
	feeling3 = "",
	mail = "A letter... Just go check it and don't mind me.",
	expedition = "The commission team is back. Now go talk to them. Cheering them on is your job.",
	win_mvp = "Hope this will be a good morale boost.",
	home = "You look like you're in good shape. Hmph, so I worried for nothing.",
	unlock = "That was a pretty good race – reckon you'll get first place next time, though? ...Hmh. Easier said than done. You know they won't settle for second place – and hopefully neither will you, Commander.",
	touch2 = "Hmph. You're a hopeless case.",
	mission = "",
	vote = "",
	drop_descrip = "That was a pretty good race – reckon you'll get first place next time, though? ...Hmh. Easier said than done. You know they won't settle for second place – and hopefully neither will you, Commander.",
	feeling4 = "",
	lose = "Just hope the girls rooting for us won't be disappointed by this... Tsk. I hate putting up appearances.",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Seeing as you've got nothing better to do, go give the girls some refreshments. It'll cheer 'em up, knowing that you're here.|Maintaining hardware is one thing we Iron Blood excel at. We're expert tamers, both of machinery and riggings.|Wonder when we're gonna rehearse for the victory party performance... I should go talk to Hipper and Eugen after my shift's over.",
	touch = "Are you gonna race, too? Then I'll at least give you some pointers and support.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 405032,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Make it clear – do you want support, or a scolding? Standing around doing nothing isn't my style.",
	detail = "Listen. Don't let other people distract you when you're on the track. Forget about overtaking others and just focus on driving the best you can drive. You'll finish with fewer regrets that way.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[405033] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Go check on the commission first. Don't worry, I won't leave.",
	win_mvp = "",
	home = "You look tired. Did you run into trouble out there? I'm happy to listen, if you'd like to talk.",
	unlock = "Hm? You look like you've seen a ghost... Oh, you thought I'd have gone home by now? Heh... Who cares? It's not like I've got anything better to do.",
	touch2 = "Just because nobody's here... Is this what you were after all along?",
	mission = "Hm? Another reminder? Did an urgent mission come up, or something?",
	vote = "",
	drop_descrip = "Hm? You look like you've seen a ghost... Oh, you thought I'd have gone home by now? Heh... Who cares? It's not like I've got anything better to do.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Living a simple life, going home with you every day and staying by your side... Heh. If this is a dream, I never want to wake up. Guess I'm addicted to you now.",
	main = "Yeah, I got your message. \"I'm busy, so I'll be late.\" The \"go home without me\" part was unnecessary.|I found a few shops you might like. If you want, we could take a detour... Not that you'd ever refuse.|You must be tired, but if I let you lie in my lap right now, we'll get home even later... Or was that what you wanted all along?|I'm not mad. I just waited a little... but if you'll treat me to something to make up for it, I won't say no.",
	touch = "Is this how seniors are supposed to treat younger students?",
	voice_key_2 = -1,
	mission_complete = "Looks like you're being rewarded after being worked so hard.",
	battle = "",
	id = 405033,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Doing whatever you want just because you're my senior, huh... Pfft, heheh.",
	feeling2 = "",
	login = "Got any plans today? You don't have to answer right away – we'll have time to talk on the way home.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[405038] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Doing okay? Even in this attire, I can always rush to your aid... What? You want a cup of coffee first? Fine. Come to my room, and you can have it... It's just instant coffee, though.",
	unlock = "Hmph, so the day has finally come... I'm not surprised. I knew from the day we met that this would happen. After all... the poison called love is both a blessing and a curse.",
	touch2 = "Hmph... Why do you still test me? Or is this just the kind of foreplay you like?",
	mission = "",
	vote = "",
	drop_descrip = "Hmph, so the day has finally come... I'm not surprised. I knew from the day we met that this would happen. After all... the poison called love is both a blessing and a curse.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "It all started out with simple eye contact. We went from there to trust, to acceptance, and finally, to unstoppable free-fall. Before I knew it, I'd already swallowed the poison called love. Now, even the closest intimacy is just a temporary fix for me. But I must have it... All we can do now is keep indulging in it.",
	main = "Are you taken by the sight of me? Heh... Seeing that look on your face made all this effort worthwhile.|Got a problem? Let me know, and I'll get rid of whatever obstacles are in your way.|Want to know where I put my rigging? Heh, I don't really need it right now. Or else... is there something you want to try with it?|Fate tied us together long ago. Call it the red string, the silver string, whatever – it binds us forever now.",
	touch = "Take my hand and fall into this web with me.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Tch... Causing trouble for the Commander, are you?",
	id = 405038,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Want to feel more? Just watch out for these hairpins.",
	feeling2 = "",
	login = "Oh, you're here? You're all mine today. Work? Leave it for once. Nothing is more important than you and me right now.",
	detail = "Now you want to escape? It's too late. Once caught in a web, a butterfly has no escape. You've poisoned me, and now, it's time I return the favor.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[405040] = {
	hp_warning = "You're quite skilled, but I won't fall that easily!",
	feeling3 = "I might not approve of all of your decisions, but I do admire your resolution. You are exactly as a commander should be.",
	mail = "Here's some mail. I'd like you to check on them as soon as possible... Later, you say? Well, I don't think there's anything urgent here, so that sounds fine with me.",
	expedition = "The girls have returned from their commissions. I'm sure the morale of the girls at the port will go up if you go out and greet them personally.",
	win_mvp = "Seems we've taken far less damage than I'd anticipated. How fortuitous.",
	home = "Good work out there. Will you take a break? Or are you planning on getting right back to another mission? Either way, I'll be here for you.",
	unlock = "It is a pleasure, Commander. I'm Thüringen, battleship of the Iron Blood. Before I formally sign on, there's one thing I want to ask – what role, exactly, do you have in mind for me? Hahah! No, I'm not testing you, I simply want a grasp of your moral compass.",
	touch2 = "Hmph! This is payback for your insolent behavior. There's no need for me to continue being a doormat for you.",
	mission = "A new mission? I think it's a good idea to get started on it right now, but you're the Commander. I'll follow your plans.",
	vote = "",
	drop_descrip = "Helgoland-class battleship – Thüringen.",
	feeling4 = "Commander, how are your plans looking today? ...Ah, I'm not talking about work, but about your personal matters. Frankly, I simply wished to invite you to tea if we both happened to be free.",
	lose = "I'll be back with some payback. Nobody likes to stay a loser.",
	feeling1 = "I'll serve my duties as your subordinate, but don't expect me to be all smiles while doing so.",
	skill = "This is it!",
	upgrade = "Hmm. Much obliged.",
	propose = "This kind of proposal works best when our feelings are reciprocal—basically, we accept each other as partners. When we have differing opinions, as long as we work together, hand-in-hand, we can overcome any obstacle that stands in our path! Ahaha!",
	feeling5 = "Maybe because we have good chemistry together, but I feel very comfortable being around you, whether for work or for personal matters. Even if we disagree on something, we come to understand each other's positions very quickly. I hope we can continue getting along just as well as we have.",
	main = "Be more confident with your opinions and openly state your opinions. If anyone dares to boo you down, I'll teach them something about manners.|Mm... I'll have to disagree on this. Of course, your word goes, but would you mind hearing my thoughts out first?|What's wrong? Got something against being watched? Ahaha, you don't have to be all tense. I wasn't keeping watch over you, I just wanted to observe your response.",
	touch = "The things I tell you are merely suggestions to you. Ultimately, you call the shots here.",
	voice_key_2 = -1,
	mission_complete = "Mission complete. I'll let you decide who you want to send to pick up the rewards.",
	battle = "Adequate preparation is half the battle.",
	id = 405040,
	gift_dislike = "",
	gift_prefer = "For me personally, this is a most wonderful gift indeed.",
	profile = "Didn't I tell you I was the Iron Blood battleship Thüringen when we first met each other? You want to know more about me? Everything, even? Ahaha, then let's look for a nice place where we can sit and talk. I'll tell you everything, starting from my time in the High Seas Fleet.",
	voice_key = 40504,
	headtouch = "",
	feeling2 = "Nobody, not even I, can meddle with your thoughts. Of course, due to our differences in standing, values, and information, I may disagree with you from time to time. But I will never disparage your authority over me.",
	login = "Hm, I'm glad to see that you're as chipper as ever. Keep it up.",
	detail = "All troubles that occur either have a reason or a trigger. Unless there are innocents tangled up in the problem, it's best to lay low and wait.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[405041] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Nice work. I was just about to take a break myself. Would you like me to help you with anything?",
	unlock = "You, mop the floor. You, take care of the windows. Once that's done... Ah, Commander. Excuse us, we're in the middle of cleaning the area. If you have need of me, I must ask you to wait.",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "You, mop the floor. You, take care of the windows. Once that's done... Ah, Commander. Excuse us, we're in the middle of cleaning the area. If you have need of me, I must ask you to wait.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Speaking of which, what is this set even used for... well, I guess it's fine. It's not something for me to worry about.|That poor-looking Royal Maid taught me how to clean things up... Ahaha, it's not the kind of cleaning that you're thinking about, just regular cleaning.|Lützow, I'm not telling you not to play with the manjuu, but make sure you carry those things to Akashi once you're done, you hear?",
	touch = "Though you shouldn't be helping me clean... if you insist, there's no way I'd turn you down.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 405041,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Welcome back, Commander. I'd like to warn you—the floor is wet, so please be careful.",
	detail = "This set is unbelievably big... Ahaha, there's no way I'd have any complaints. However, I definitely want the girl who prepared this set to experience what cleaning this humongous space feels like.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[405050] = {
	hp_warning = "None shall tarnish Iron Blood's honor!",
	feeling3 = "There are times I wonder what I would do if you were ever to become my enemy. Of course, it's just a thought experiment, but it helped me realize– I'm glad we're on the same side.",
	mail = "A letter for you, it seems. Give it a read, promptly. You wouldn't want to miss potentially vital information.",
	expedition = "Munitions have arrived. Come, let's not waste any time. Those girls would like nothing more than a warm welcome from you.",
	win_mvp = "Excellent, the path before us has been cleared. Forward!",
	home = "You're back. If you have the time, could you compile an after-action report? In the meantime... I'll put myself in our foes' shoes and see if I can't develop a better strategy.",
	unlock = "Guten Tag. I am Iron Blood battleship Bismarck. While this may not be our first meeting, perhaps you find my new attire surprising? As a fellow idealist, I'm happy to once more fight by your side.",
	touch2 = "Are you purposely trying to get under my skin?",
	mission = "A new mission? Let me have a look. I can lend you a hand.",
	vote = "",
	drop_descrip = "Bismarck-class battleship – Bismarck.",
	feeling4 = "I'm comfortable discussing anything with you, from office matters to coffee break gossip. Being this sincere, this forthright, is something a leader conscious about appearances strives for. Heehee. I always enjoy my time with you.",
	lose = "I do not intend to shoulder all the responsibility myself... but I will ensure our safe retreat!",
	feeling1 = "I thought you a brilliant leader and followed your example. I now see that I was misguided.",
	skill = "Truth can only be found within my range!",
	upgrade = "It's time for routine maintenance. Geryon, be quiet now.",
	propose = "I know about your resolve, your feelings. What I don't know... is how to meet your expectations for this unforgettable ceremony. Let this be a rare case where I ask for a favor and say... could you take the lead? Heehee.",
	feeling5 = "I hope you will remain by my side, as more than an ally and close friend you can talk to about... *sigh*, never mind. It's all good as long as you know what I'm trying to say. See, I'm... I'm still not used to speaking my heart...",
	main = "The two of us have much in common, as leaders who bear the expectations of their peers. If there's anything you have difficulty confiding to others, feel free to turn to me.|Geryon is being rather rowdy... Regensburg, how'd you manage to calm him down the last time? Mind showing me again?|While you could call Eugen my right-hand woman, she can often be frustratingly difficult to read... You think so, too? Heh, I'm glad we're on the same page.|With this new power, I finally have the opportunity to leave my regrets behind in the past. Wait, we're going to a café with Tirpitz? Right now? Umm... give me a moment to sort out my emotions...|I like slow classical music– it helps me relax. As for the war... Yes, there will come a day when that, too, is history.",
	touch = "Has my sword caught your eye? You may hold it if you want.",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Remember to claim your rewards. They belong in your hands.",
	battle = "That sheer courage to stand in my way is worthy of applause.",
	id = 405050,
	gift_dislike = "",
	gift_prefer = "Heh. Not bad. I appreciate it.",
	profile = "My lust for power once dragged me down to the depths of hell. No matter how much I regretted it, it was already too late... I never dreamed that I would be given new life in this manner. Much seems to have changed during my slumber, but I am now ready to take on everything. Having you, a fellow leader, show me the way forward is the best thing I could ask for.",
	voice_key = 40505,
	headtouch = "Want to try my cap on? ...Hehe, it suits you well.",
	feeling2 = "I do not want any preferential treatment. All I ask is that you treat me as you would any of our other colleagues. That's right, Commander. I look forward to working with you in the days ahead. I'm sure we'll become the best of friends.",
	login = "Let's get to work, Commander. A port this vast requires a leader's management.",
	detail = "A private workspace? No, that's alright. I don't need preferential treatment– simply being able to work with you is enough.",
	couple_encourage = {
		{
			{
				40303
			},
			1,
			"That's the Eugen I've always known.",
			0
		},
		{
			{
				40502
			},
			1,
			"Join me in battle, Tirpitz.",
			0
		},
		{
			{
				970401,
				970402
			},
			1,
			"I'm not the Bismarck you know, but I seek your aid all the same.",
			0
		},
		{
			{
				40804
			},
			1,
			" I haven't forgotten your knightly promise.",
			0
		},
		{
			{
				970801
			},
			1,
			" Whatever happens, I will always protect you.",
			0
		},
		{
			{
				49902
			},
			1,
			" How long has it been since we last fought together?",
			0
		},
		{
			{
				40503
			},
			1,
			" I shall lead Iron Blood towards a glorious future. To do that, I need your help.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[405051] = {
	hp_warning = "",
	feeling3 = "",
	mail = "A letter? Why in here, of all places... Dry your hands before you open it.",
	expedition = "",
	win_mvp = "All enemies have been dealt with. I hope this will go swimmingly for at least a while.",
	home = "The swimming pool floor is slippery, so watch your step, Comma– *sigh*... I told you so. Be more careful.",
	unlock = "Ah, you've already gotten changed, Commander? I'm just... Well, I need to do something about my hair before I go back in the water.",
	touch2 = "To follow my heart in this scenario or not, that's the question...",
	mission = "",
	vote = "",
	drop_descrip = "Ah, you've already gotten changed, Commander? I'm just... Well, I need to do something about my hair before I go back in the water.",
	feeling4 = "",
	lose = "I wanted to tune up today, but unsurprisingly, you can't fight when you're not fully prepared...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "U-556 told me that submarines love playing in the pool. While I agree it is a fun time, I wish she'd understand why I can't exactly mingle with submarines...|My swimsuit? Why yes, I chose it myself. In truth, I did ask Eugen for suggestions, but all the swimsuits she picked out were... the kinds that draw undesirable attention. Let's just say that..|Incidentally, would you consider what we're doing here a date? ...Thinking of it like that makes me feel a bit tense...",
	touch = "If you want a break from swimming, we can always sit on the deck like this.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Emergency sortie, Geryon. Come with me.",
	id = 405051,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Hold on. My hair is still soaked.",
	feeling2 = "",
	login = "The water feels perfect. Commander, come join me after you finish your warmup exercises.",
	detail = "I reserved this whole swimming pool. We all want to be left undisturbed sometimes. Especially now, when... You know what I mean, don't you?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[405052] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Yes... The water is the perfect temperature. It washes away filth and fatigue alike.",
	unlock = "This necklace's glimmer and texture in the steam is truly splendid... Oh, Commander. Would you care to come in and share in this scene you've gifted me?",
	touch2 = "Heehee. Let us immerse ourselves in this wonderful scenery.",
	mission = "",
	vote = "",
	drop_descrip = "This necklace's glimmer and texture in the steam is truly splendid... Oh, Commander. Would you care to come in and share in this scene you've gifted me?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I'm bad at expressing my emotions, and I struggle to naturally show my feelings toward you... Still, I want you to view it like this necklace: As long as you look with your heart, its splendor should reveal itself to you.",
	main = "Flower petals, music, and aromas. Heehee – even I have a sense for romance.|I feel weak... I must've soaked for too long. Commander, could you... wrap the towel around me?|The necklace feels vaguely warm to the touch... Care to feel it for yourself, Commander?",
	touch = "You wish to see it from a different angle? Of course. Go ahead.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 405052,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Hm? Is there a petal stuck to my hair?",
	feeling2 = "",
	login = "Most people would take off their necklaces before going into the bath, but I'm reluctant to. I want to remember this feeling.",
	detail = "Look, Commander – the light reflecting off of the water makes my necklace glow all the more. I'm very fond of this gift of yours.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[405060] = {
	hp_warning = "Hmph... A final cadence?",
	feeling3 = "Hmm... In what unexpected ways will the courage that wells up on the battlefield affect this movement?",
	mail = "Mail for you, my child. Oh? There's a postcard that plays music.",
	expedition = "Our friends are back from their commission. Shall we play a song of celebration?",
	win_mvp = "Victory's encore has only just begun.",
	home = "Welcome. Heehee, I'm devising a glorious symphony to celebrate your triumphant return, my child.",
	unlock = "Welcome, my child. What would you like to enjoy together today? Your talents? Glory? Or youth? Heheh, you may surrender it all to me.",
	touch2 = "Heehee, is this your decision?",
	mission = "Trading actions for the things you desire... Heehee, is a mission really anything more?",
	vote = "拉票描述",
	drop_descrip = "Battleship – Friedrich der Große.",
	feeling4 = "Why don't we do something fun, right here and now? For example... We both bite into opposite ends of a pretzel and see... where things end up? Heehee.",
	lose = "An unharmonious trill... I'll need to tune things better.",
	feeling1 = "Hmm. Ah... This performance is a little disappointing...",
	skill = "Let us play the Fifth Symphony!",
	upgrade = "I feel radiant.",
	propose = "This is... Heehee, do you understand what this means, my child? As you wish, I will entrust my very life to you. And I will see yours given to me, as well...",
	feeling5 = "Do you want me to pamper you, my child? Or do you want to pamper me? Heehee, either way, today is your only chance♪",
	main = "The phonograph was ahead of its time. Thanks to this, even music can be something that contains dear memories... Would you like to preserve some dear memories together?|Logic, sensibility... Heehee, just like the balance discovered in a melody.|Heehee, let's play. Let your emotions gush out like hot magma...",
	touch = "Hm? What do you want to hear today, my child?",
	voice_key_2 = -1,
	mission_complete = "Go get your mission rewards, okay? Hmm... I wonder what song I would need to play to be rewarded with you.",
	battle = "Fade with the music!",
	id = 405060,
	gift_dislike = "",
	gift_prefer = "",
	profile = "Friedrich der Große, mysterious melody of the Iron Blood fleet, happy to meet you. What music shall we play together, my child?",
	voice_key = 40506,
	headtouch = "How fun. Now I want to do the same to you, my child.",
	feeling2 = "\"What is real is rational,\" said one philosopher. Don't think too much about why I'm here – just immerse yourself in my melody.",
	login = "Today's performance is about to begin. Sit, my child.",
	detail = "Do you want to hear my performance, my child? It might bring your confused state of mind back to order.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[405070] = {
	hp_warning = "It's time for my counterattack!",
	feeling3 = "You look quite relaxed, Commander. Does this mean we can finally dispense with all these tedious pleasantries?",
	mail = "Shall I screen your mail for you? Just understand that if I see anything \"suggestive\" in there, I might end up hiding it♪",
	expedition = "The commission team has returned. I've made the logistical arrangements, so all that's left is for you to welcome our weary friends.",
	win_mvp = "This concludes the day's etiquette lesson.",
	home = "Thank you for allowing me to sit in on such a masterful hunt. Leave the cleanup work to me while you rest.",
	unlock = "Guten Tag, Commander. I am Götz von Berlichingen. Sooner would I offer you a rose than my blade, and sooner would I dance with you under the moonlight than amidst the smoke of battle.",
	touch2 = "Commander, treating a noble lady so roughly is far from a wise move.",
	mission = "Commander, you must understand that unfinished work is like ladies at a ball, waiting for you to invite them to dance. One mustn't keep them waiting.",
	vote = "",
	drop_descrip = "H39-class battleship – Götz von Berlichingen.",
	feeling4 = "Commander, why do you think roses have thorns? It isn't just to protect their delicate petals... but to allow only the worthy to possess them.",
	lose = "Hehe, they only think they've won. Commander, let's make our move!",
	feeling1 = "Goodness. What a disappointing blunder, Commander.",
	skill = "Every rose has its thorns.",
	upgrade = "Your favor is noticed and appreciated. I promise to repay you.",
	propose = "Dear silly Commander of mine, you ought to know by now that I'M the one who pursues. If you'll offer your blood unto me and let me trace it all the way back to your beating heart... then I promise that I will plunge alongside you into this eternal dream♥",
	feeling5 = "Veiling my intentions in poetry, concealing my sharpness with etiquette, dancing in the night in search of just a drop of passion... Do you consider me dangerous, Commander?",
	main = "Your collar's a bit crooked. Heehee, people will look down on you if you aren't properly groomed. Especially given your position...|I've prepared some refreshments for this evening's banquet. It's only ripe tomato juice, but listen, Commander... Appearances can be deceiving.|My Iron Blood colleagues are unaccustomed to showing passion in front of others. In my opinion, though, their devotion is quite endearing. Heehee!|The sight of you so earnestly devoted to your work at all hours of the day... only makes me want to drag different emotions out of you.",
	touch = "Oh, my. The blood in your neck is coursing faster... Are you enjoying our duet?",
	voice_key_2 = -1,
	mission_complete = "The missions are complete. Shall we raise a glass in celebration?",
	battle = "Let's see which one of us has the more impeccable etiquette.",
	id = 405070,
	gift_dislike = "",
	gift_prefer = "Thank you for the gift. Next time we dance, I might just have a surprise for you.",
	profile = "You'd like to know my secrets, would you? Hehehe, then let me warn you: you must never let Götz von Berlichingen touch alcohol. Rumor has it that, when she gets tipsy, she can become one haughty woman... Goodness, what a handful she must be.",
	voice_key = 40507,
	headtouch = "Such unexpected intimacy... Have I spoiled you, Commander? Heehee.",
	feeling2 = "The discipline of the Iron Blood, elegance of the Royal Navy, and vitality of the Eagle Union... Being able to bring together such diverse individuals and make them dance on the same floor is a testament to your innate charisma, Commander.",
	login = "Greetings, Commander. Oh, are you taken by the sight of my wings furling? Hehehe, well... I wouldn't mind if you took a closer look.",
	detail = "Do you like poetry, Commander? Hehe, such beautiful rhyme and meter can effortlessly bewilder and entice prey into your clutches.",
	couple_encourage = {
		{
			{
				40503
			},
			1,
			" I'll lure them close while you strike them down... It's a pleasure to work with you!",
			0
		},
		{
			{
				20123
			},
			1,
			" Well, well. Aren't you cute?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[405071] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Do you like the dream I made just for you, Commander? Heehee, then let's continue...",
	unlock = "Oh? You've finally noticed my presence, human? I've been waiting within arm's reach for a long while now.",
	touch2 = "Heehee... I'll have my fill of you before long, my beloved♥",
	mission = "",
	vote = "",
	drop_descrip = "Oh? You've finally noticed my presence, human? I've been waiting within arm's reach for a long while now.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "When the blood moon sets and dawn breaks, you may notice a mark on your neck. It will continue to ache, never fading... Heehee, that's my lifelong memento for you.",
	main = "An upside-down succubus for an upside-down world... One where we can cast aside morality, accept this sweet curse, and indulge in our mutual desire forever...|The blood moon's ode to depravity... Hehe, such a wonderful illusion. I don't know if I can hold myself back for much longer♡|Beloved Commander, you have to hold on just a little longer. Soon... Soon, I will be right by your side♥|Perhaps only in the moment when our fingers touch can we truly discern what is reality and what is a reflection of our yearning hearts... Come closer, that we may find out♥",
	touch = "How will you entertain this hungry succubus, Commander?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 405071,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Are you worried that I'll fall? Heehee, don't be. I have wings to fly with – and a tail to coil tightly around you, as well.",
	feeling2 = "",
	login = "If it isn't you, Commander♪ Shall we begin our wonderful dream together?",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[406010] = {
	hp_warning = "It's not yet time to panic.",
	feeling3 = "Peter is quite brilliant, but she can also be quite dreary. I wish she'd loosen up about time and planning and all, and learn to just have fun sometimes.",
	mail = "There's some mail for you. If it's nothing urgent, just read them later.",
	expedition = "The commissions team is back? We shouldn't leave them waiting there like that... Should I go ahead and greet them first?",
	win_mvp = "Victory, just as I expected.",
	home = "Being a commander truly takes a surprising amount of work... How about taking a quick breather right about now?",
	unlock = "Heavy cruiser, Seydlitz... Rather, escort carrier Weser, has arrived. You're wondering why I have two names? Don't be in such a rush... I'll be sure to teach you later, slowly.",
	touch2 = "Your spirited enthusiasm... You might want to change the way you convey it.",
	mission = "New missions? There's no need to hurry. We can check them after you finish whatever you're doing right now.",
	vote = "",
	drop_descrip = "Aircraft carrier – Weser. ",
	feeling4 = "I believe that the way we live isn't influenced by our environment, but rather the choices we've made. That's why I've always lived by my own tempo. What do you think about the way I live my life?",
	lose = "Ugh... I wonder if I'm still not used to my planes...",
	feeling1 = "Commander, I've got one word of advice for you. If your condition isn't great, make sure to take a break and sleep soundly. It won't do to have everyone else see you in bad shape.",
	skill = "The time has come!",
	upgrade = "It looks like I'll get to use some more powerful equipment. Thanks, Commander.",
	propose = "This ceremony... Surely you didn't have to be in such a rush? It's not like I'll run off somewhere or forget our promises together. Or... is it that you don't have any faith in me? Hehe, I'm just messing with you. For the future everlasting, I'll be yours, Commander.",
	feeling5 = "Have you matched your stride to my tempo, or have I matched mine to meet yours? Putting all that aside, you know, having you by my side makes me feel comfortable and relaxed. Hehe.",
	main = "The Iron Blood doesn't have as many aircraft carriers as the other factions, so I can't help but worry that we'll be at a disadvantage during practice exercises.|The Unsinkable Battleship...? Oh, I know who you're talking about. I wonder if I'll ever be able to meet my renowned predecessor, Seydlitz, at some point?|Hipper, Eugen... I can't believe I'm able to fight by their side like this. It's all thanks to you, Commander.",
	touch = "If you're tired, just set everything else aside and get some rest. I'll wake you up if somebody comes around.",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Don't worry, it's not like the rewards will run off somewhere. You just need to make sure to collect them later.",
	battle = "Keep calm and persevere. Victory will surely come to us.",
	id = 406010,
	gift_dislike = "",
	gift_prefer = "Thank you. I'm rather fond of this.",
	profile = "Whether as the 4th ship of the Admiral Hipper class, Seydlitz, or as the escort carrier, Weser, I was never completed over the entirety of that war. ...Over here, I should have more than enough time to do everything I've always wanted to do. That way, I'll be able to bury my regrets, one by one.",
	voice_key = 40601,
	headtouch = "",
	feeling2 = "The battlefield is a place where the unexpected occurs. If you simply insist on following the orders given to you by the higher-ups, you'll never be able to achieve victory.",
	login = "Before you hurry off to do your work, why not first take a seat and enjoy a cup of coffee?",
	detail = "Commander, are you free? Do you have time to help me practice with my planes?",
	couple_encourage = {
		{
			{
				49902
			},
			1,
			"I wonder what your plan might be?",
			0
		},
		{
			{
				40303,
				40301
			},
			2,
			"Head forth without worry, we've got you covered.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[406011] = {
