	mission_complete = "",
	battle = "",
	id = 406011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Have you already decided what we'll do today? If not, take your time. The goddess of time is a patient one.",
