_G.pg.base.ship_skin_words[406032] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Hmm? My concert livestream? It ended a while ago now... I can't believe you really missed it. Haha, I'm kidding! It hasn't even started yet♪",
	unlock = "That's right, I'm the witch Jade, the most famous idol in all the world! Did you come running when you heard my name, hero? I was just about to broadcast my new song, so you'll be the perfect helper. Heheh♪",
	touch2 = "What a wicked hero you are♪ Are you planning to do naughty things to me?",
	mission = "Concert preparation is important, but so are your quests. Or were you neglecting them specifically to bait me into helping you?",
	vote = "拉票描述",
	drop_descrip = "That's right, I'm the witch Jade, the most famous idol in all the world! Did you come running when you heard my name, hero? I was just about to broadcast my new song, so you'll be the perfect helper. Heheh♪",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "What am I doing after my concert? Joining you in your adventures, of course. Those weren't just pretty words. You're the one who came to see me, and I plan to return the favor. Besides, you can't progress without my magic, can you? Heehee!",
	main = "Adventure? As a witch idol, I have no interest in that. Though I could consider it if you hold an even flashier concert for me!|Atmosphere is important, so I should use magic after all. Hm? What magic do I want to use? Heehee... Mwah! This spell makes your heart flutter♡|For the concert, I need... new speakers, a magic phone for the livestream, candles, glow sticks, and my own hero to put to work... Heehee, that last one was a joke.",
	touch = "Oh, you want these glow sticks? Then hold out your left hand! Now your right! Heehee, you're so obedient. Here you go~",
	voice_key_2 = -1,
	mission_complete = "You have so many quest rewards waiting. Make sure they're all accounted for!",
	battle = "",
	id = 406032,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Heheh, I've got just the hat for today... Whoa whoa! Don't take my hat!",
	feeling2 = "",
	login = "So even the great hero can be late? Did someone decide to be naughty and stay up late last night? Heehee!",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[407010] = {
	hp_warning = "The smell of steel and blood...",
	feeling3 = "Does prayer really work? Will God ever respond? Nein. Gods are called as such because they are merciless.",
	mail = "Treasure the time you have to speak with your loved ones, for that time is about to draw to an end.",
	expedition = "Ah, so they have returned... Just seeing those faces filled with joy...",
	win_mvp = "My enemies belong in their graves.",
	home = "All your fights, all your struggles, are nothing more than fodder for the End.",
	unlock = "You're my Commander? I am Graf Zeppelin. Since it appears that all the conditions have been met, let the final movement begin.",
	touch2 = "Quite brave, aren't you? As expected of the one I chose.",
	mission = "Is the person who gave you this mission really who you want to fight for?",
	vote = "",
	drop_descrip = "Aircraft carrier, Graf Zeppelin.",
	feeling4 = "I have never been one to believe in fate, but if meeting you was also predestined... Hmm... How ironic. For the gods to have given me the worst past but also the best future... what purpose does my hatred then serve?",
	lose = "Next time, I shall grant you despair even worse than death.",
	feeling1 = "You again...?",
	skill = "Die... Funebre!",
	upgrade = "Ah, if only strength alone was enough to determine everything.",
	propose = "Oh? Have you finally decided to make the entire world your enemy? What? You just want to be with me? Hmph, very well. Eradicating everything that stands in our way doesn't sound bad either.",
	feeling5 = "As long as you are here, the world does not feel so insipid and detestable. Rest easy; even if the world was to become your enemy, I would happily fight by your side. As a matter of fact, I eagerly await this day.",
	main = "I prefer the high ground, because I can see everything... everything that shall be destroyed...|Easy come, easy go... Aren't things like that better off not existing in the first place? |Life is akin to playing cards with a stacked deck. Doesn't it make you want to smash the entire table?",
	touch = "I despise everything.",
	voice_key_2 = 407013,
	mission_complete = "Rewards... take them away.",
	battle = "Let us begin our symphony of destruction.",
	id = 407010,
	gift_dislike = "",
	gift_prefer = "You knew all along... Thank you.",
	profile = "I am Graf Zeppelin. Though this name is worth little, you may call me by it if you wish. My only desire? To end the world. I shall not ask for your help though... as you are already a part of my plans.",
	voice_key = 40701,
	headtouch = "What is the meaning of this action?",
	feeling2 = "Ahh, so sweet. Sweet things cannot last for long. The only thing that endures forever is ice-cold hatred.",
	login = "The black goat's horn has already sounded. Quell your anxiety and wait at ease.",
	detail = "If gods truly exist in this world, let us begin our slaughter with them.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[407011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "",
	unlock = "So the Second Movement is a Lento of the summer and the sea? So be it... Since we will arrive at the Finale eventually, I suppose I can enjoy this moment of fleeting peace with you.",
