_G.pg.base.ship_skin_words[407012] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "I saved some wine for you. Come and drink with me. When you're tipsy, you can lie down and rest... with me, of course.",
	unlock = "Finally, you've come. Even if it meant dying tomorrow, it's a worthy trade to enjoy this moment with you.",
	touch2 = "Nnh... Close the window first.",
	mission = "",
	vote = "",
	drop_descrip = "Finally, you've come. Even if it meant dying tomorrow, it's a worthy trade to enjoy this moment with you.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Once upon a time, I hoped that annihilation would come to this dull world. Somehow, I feel as if I've found my home amidst these lights... Maybe your existence is the glimmer of hope I needed.",
	main = "Hmm. You think I'll catch a cold if I don't put more clothes on? Do you consider this lightly dressed? Then what do you call what everyone else is wearing?|Why are you staying so far away? Do you not want to be next to me? Is my bed too small? I'm sure you can squeeze in... Come over here already.|Emperian wine hits so different... The intense, straightforward spiciness of it only makes me more thirsty.",
	touch = "Maybe YOU'RE the drunk one. I could drink hundreds of glasses, and I would still be able to face the end with the clearest mind of all.",
	voice_key_2 = 0,
	mission_complete = "",
	battle = "",
	id = 407012,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Nnh... Again, I'm not drunk. This heat is just... a natural physiological reaction...",
	feeling2 = "",
	login = "The view outside is wonderful. If you miss it, I suppose I'll be forced to invite you over again.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[407020] = {
	hp_warning = "Hm-hmph! Like hell I'd lose!",
	feeling3 = "You fool, if you wanted my help, you should have asked... Since I'm able to eat delicious cake like this every day... maybe I wouldn't object to staying a little longer!",
	mail = "Huh, you're missing a piece of mail? R-really...?",
	expedition = "Hey, I think you have people coming back into the harbor.",
	win_mvp = "Heheh, planes are the strongest after all!",
	home = "I didn't expect you to be this capable. Maybe you are worthy of being my commander!",
	unlock = "State your name! And this location! I see now... you’re also one of those goons conspiring against me! I’ll let you know, I am Graf Zeppelin, the one destined to become the first carrier of the Iron Blood! To think that you’d carry me off when I was distracted... taste my wrath!",
	touch2 = "Filthy, taste my wrath!",
	mission = "Huh? You have to finish your work first. Isn't that common sense?",
	vote = "",
	drop_descrip = "Aircraft carrier Graf Zeppelin",
	feeling4 = "Hey Commander, what's for dessert today? Huh, it's about going home? Well, um... th-that's right! It will be a while until I'm grown up enough to realize my destiny, so I can probably keep the Iron Blood waiting a bit longer! Hmm, I'm sure they won't be angry!",
	lose = "It's n-not my fault! I-I just didn't get enough to eat!",
	feeling1 = "Hmph. Stay away from me. I'll find a way home by myself!",
	skill = "Let's end this!",
	upgrade = "I-I won't be bribed so easily!",
	propose = "I hate you, you big dumb idiot! If you give me something like this, how am I going to say goodbye? Uwahh... *sniffle*... Th-then promise me this... If I ever have to go back, swear that you'll come find me, got it? It's a promise!",
	feeling5 = "You turned out to be a pretty good person after all, and everyone here has treated me well... When I grow up to become a mighty carrier, I wouldn't mind coming back to live here~",
	main = "*sniffle* ... *sniffle*... Waaah... Why are you still working and ignoring me?! Taste my wrath! |Hmph. No matter how hard you try, I will never yield to you! ...Desserts? Gimme... |Hmm... this should go here... No, no, maybe like this...? Hey! Wh-what are you doing! I didn't ask for your help! |I like high places! That way, I can see really far! |Despair and hatred mean nothing to me! I believe that as long as you don't give up, you can make any dream come true!",
	touch = "Don't just randomly touch me! Taste my wrath!!",
	voice_key_2 = 407023,
	mission_complete = "Look at all the rewards!",
	battle = "Allow me to show you the true power of planes!",
	id = 407020,
	gift_dislike = "",
	gift_prefer = "Wow, this looks fun!",
	profile = "I am none other than Graf Zeppelin, the first carrier of the Iron Blood! Heh. Don't be so surprised. The next era of naval warfare will definitely be decided by aircraft, and I will stand as its most brightly shining star! So, let me go back! ...Huh, I can't? ...Taste my wrath!!",
	voice_key = 40702,
	headtouch = "",
	feeling2 = "What's with that expression? I'm only unable to find my way back home because this place is too big! Hmph, I'm sure you made it that way on purpose, you goon!",
	login = "Where did you suddenly run off to?! Taste my wrath!",
	detail = "Why are there other Iron Bloods here, and why are they so... big? It's a bit scary...",
	couple_encourage = {
		{
			{
				40701
			},
			1,
			"I love all of this!"
		},
		{
			{
				20218,
				30406,
				30709
			},
			1,
			"I'm not like you bunch!"
		},
		{
			{
				40146
			},
			1,
			"Bow down to my superior engineering!"
		}
	}
}


_G.pg.base.ship_skin_words[407030] = {
	hp_warning = "Everything... is still under control.",
	feeling3 = "Officer, the clock in your bedroom was off by two minutes. ...Oh, there's nothing for you to worry about, I've already taken care of it. You can't use the excuse that your clock is off anymore",
	mail = "Officer, there's mail for you. Make sure to check it at your earliest convenience.",
	expedition = "The commissions have been completed. Yes, I'll have to praise them for their efficiency considering their station as your subordinates.",
	win_mvp = "Hah! Took care of them faster than I thought.",
	home = "The more complex the machine, the more time it takes to maintain it. All the more for humans. Make sure you don't forget to rest up.",
	unlock = "It is I, the never-completed Graf Zeppelin-class \"Aircraft Carrier B,\" otherwise known as Peter Strasser. There is much for us to do and little time to do it... No time to waste. Let's begin.",
	touch2 = "Officer, if this helps raise your efficiency, I don't consider it time wasted.",
	mission = "Here are the new missions. Instead of rushing to finish everything at once, use your time wisely and plan out your endeavors properly.",
	vote = "",
	drop_descrip = "Graf Zeppelin-class aircraft carrier – Peter Strasser. ",
	feeling4 = "Devoting your time to one person is a waste of time. That is, unless you get something worth it in return... Don't you think so too, Officer?",
	lose = "Time is far better spent contemplating how to avoid being destroyed, rather than foolhardily charging into destruction again and again.",
	feeling1 = "Officer, you're not worth my time.",
	skill = "Your time is up!",
	upgrade = "Strengthening complete. Yes, it seems as if I've spent my time wisely.",
	propose = "A ceremony to ensure the time I've spent doesn't go to waste... well, since you've said this much, I'll take your words as proof of your vow, Officer. We still haven't spent as much time and emotions on each other we want to after all, right...? Hehehe.",
	feeling5 = "Officer, you'll pay me back for all of the time I've spent for you...? Interesting. Let me check the details first, hehe.",
	main = "The more precise your plan is, the less time you'll have to waste hesitating on what you need to do. Why not give it a try, Officer?|Heinrich, your documents for your training program are here. Make sure not to forget them next time.|It's so nice to see all of the tasks be completed, just as planned. Hehehe.",
	touch = "What is it? You've still got time left until your break ends.",
	voice_key_2 = -1,
	mission_complete = "I'm glad the rewards for the missions correspond to the amount of time it took to complete them. Hehehe.",
	battle = "Let me test this tactic on you.",
	id = 407030,
	gift_dislike = "",
	gift_prefer = "Oh my, how considerate you are~",
	profile = "I am Aircraft Carrier B, one of the Graf Zeppelin-class carriers that suffered an unfortunate fate, having had my construction halted without ever getting to set sail. But... doesn't the name \"Peter Strasser\" have a much nicer ring to it than \"Aircraft Carrier B\"...?",
	voice_key = 40703,
	headtouch = "",
	feeling2 = "Time is a precious commodity. State what you need me to do as concisely as possible.",
	login = "Did you just get here? Heheh. Make sure you work efficiently on your duties today, as always.",
	detail = "The expression of the passage of time as the hands of a clock ticking—don't you think it's just fascinating?",
	couple_encourage = {
		{
			{
				40701
			},
			1,
			"Before you go and destroy the world, destroy the enemy in front of you first."
		},
		{
			{
				40309
			},
			1,
			"Don't just rush in. ...H-hey!"
		},
		{
			{
				40402
			},
			1,
			"Gently now. Hehehe."
		},
		{
			{
				20705
			},
			1,
			"Ehem... Time is not on your side."
		}
	}
}


_G.pg.base.ship_skin_words[407031] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commissions have been completed. Please leave their reception to me. There's no need for you to waste your time, Officer.",
	win_mvp = "",
	home = "Go take a break, and leave the deliberation to me. It's not yet time for you to make your appearance, Officer.",
	unlock = "Eugen, you said that this was is a ceremonial outfit from the Sakura Empire? Surprisingly, it does seem to suit me rather well. Oh, I'm supposed to offer my well-wishes for the New Year at this time, yes? ",
	touch2 = "Officer, are you telling me that this much is enough for you to not be able to hold back?",
	mission = "",
	vote = "",
	drop_descrip = "Eugen, you said that this was is a ceremonial outfit from the Sakura Empire? Surprisingly, it does seem to suit me rather well. Oh, I'm supposed to offer my well-wishes for the New Year at this time, yes?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "I hear this is the time of year when New Year's gifts are handed out. Officer, would you rather be the one handing out the gifts or receiving them?|Eugen, Heinrich, there's a limit to how much rucku... teasing you should do.|Graf Zeppelin, why don't you try studying the Sakura Empire's shrines? Even if you don't pay your respects to their gods, the Sakura Empire's amazake seems quite interesting.",
	touch = "The plan already takes the holidays into account. There won't be a problem even if you take some time off to rest, Officer.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 407031,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "So you're working over the holidays. How commendable of you.",
	detail = "The sands of time pile up to become a mountain; The passing of time eventually becomes history. Hehehe, how interesting.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[407032] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commissions are complete. I sent Heinrich to go welcome them back. After all, she'd be out of place here.",
	win_mvp = "",
	home = "You need some rejuvenation? Hmm... Should I lend you my lap? Or would you prefer my chest, instead?",
	unlock = "You already know, don't you? Since I spent so much of my precious time changing into a dress for your sake... Heh, I'll be taking plenty of your time in return. Hehehe.",
	touch2 = "How very like you. Hehe♪",
	mission = "You have new missions. Hurry up and take care of them.",
	vote = "",
	drop_descrip = "You already know, don't you? Since I spent so much of my precious time changing into a dress for your sake... Heh, I'll be taking plenty of your time in return. Hehehe.",
	feeling4 = "",
	lose = "Time waits for no one. Not even for you.",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "The \"Unhulde,\" you say? ...Officer, keep your eyes on me. I shan't let her steal your attention or your time.|Viersechs, Zeppelin is over there. Hehe, how cute. Don't you think so, too?|I'll bring some drinks over. ...Are you trying to show off? Go make your rounds with the others first.",
	touch = "...Phew. (whispers) Umm, drinking beer at a party is a bit out of place, isn't it...",
	voice_key_2 = -1,
	mission_complete = "Hehe. These rewards... Well worth the time spent, right?",
	battle = "Come–– The time of our destruction is nigh.",
	id = 407032,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I'll have you escort me tonight. Quickly now, come take my hand.",
	detail = "If you have nothing else to do, go read a book. Much can be learned from the experiences of people past—in essence, earning time.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[407033] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Am I ready to greet our comrades? Of course. As long as I consider it time with you, it's hardly any effort.",
	win_mvp = "",
	home = "Look at you, working your butt off during a festival. I don't mind lending you my lap, you know. I'll even throw in a relaxing massage.",
	unlock = "Heheheh, it may be a new year, but don't forget to be punctual. Just as you've refurnished this study into a Dragon Empery style, I've changed clothes to match. This little book club is just for the two of us, and I mean to suit the mood.",
	touch2 = "You want to do something more \"productive.\" Heehee♪ I totally understand.",
	mission = "",
	vote = "",
	drop_descrip = "Heheheh, it may be a new year, but don't forget to be punctual. Just as you've refurnished this study into a Dragon Empery style, I've changed clothes to match. This little book club is just for the two of us, and I mean to suit the mood.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Invest time, reap companionship... I spent so much of this festival with you, so will I receive something worthy of my time? Heheh, while I do appreciate your companionship, there's something more that only you can give me...",
	main = "I've been reading up on New Year traditions, and they're all so complex... In my opinion, all that matters is that you have fun.|Do you listen to music when you read? ...Heheh, I'm okay with anything. Pop, jazz, rock, you name it.|After we finish reading... We could talk about life, or something. Or if you'd like, there are ways to make better use of our time together♡",
	touch = "All you have to do is touch Dragon Empery clothes, and you can tell how comfortable they are.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "The bells and drums of the new year ring. Begin the attack!",
	id = 407033,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "You're finally here. Come, let's begin today's reading – now, you don't have to be so impatient. Nobody's going to come and bother us today.",
	detail = "What's so important that you have to come and whisper to me about it? ...Oh? I think I can satisfy this little request of yours.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[407040] = {
	hp_warning = "I will turn this battle around!",
	feeling3 = "It's time for a break, Commander. Drop your work immediately. Foolhardily working for longer will, by itself, only halve your productivity. What you require now is rest.",
	mail = "Only by reading your letters can you guarantee the timeliness of their contents, Commander.",
	expedition = "A commission has been completed. You should begin writing that report.",
	win_mvp = "An exceedingly ordinary victory. Continue working hard, Commander, lest you get complacent.",
	home = "Commander, reflect on your previous battle once your quick rest is over.",
	unlock = "Guten Tag, Commander. I am Rumey. You've surely read my file. Forget the pleasantries – just tell me all the details of our next operation.",
	touch2 = "Sort yourself out, Commander.",
	mission = "New mission objectives have been relayed to us. Begin drafting a plan, Commander.",
	vote = "",
	drop_descrip = "Grossflugzeugkreuzer (large aviation cruiser) A Type II – Fritz Rumey.",
	feeling4 = "You had many highlights in our war game today... However, by going to such lengths to avoid ally casualties, you exceeded the time limit and failed. Mind you, I'm not saying your strategy was bad. I'll improve upon it, then we'll switch sides next time.",
	lose = "The operation is a failure. All units, retreat in an orderly fashion!",
	feeling1 = "Your lack of discipline is a shame upon our navy. Shape up! Only you can redeem yourself!",
	skill = "Advance! Onward!",
	upgrade = "Gut.",
	propose = "I already know why you summoned me here. I will gladly take this vow. As you surely know, I have many feelings that I struggle to put into words. Put this ring on my finger – how my hand trembles is my answer to your question.",
	feeling5 = "You reversed the situation of last time and then employed specific countermeasures in this war game... I have to admit, your strategy posed a serious threat to me, which is good. Remember this feeling – and know that I am eager to witness your performance next time.",
	main = "What are you fighting for, Commander? You need not answer. You need only know the answer in your heart.|Sometimes, I carry out missions alone. While it is dangerous, the greater risk comes with corresponding gains.|Organizing and reviewing combat records is child's play. My finished work will be distributed to your subordinates in your name later.|Commander, here is the finalized operation plan. Give it a final overview, just to be safe.",
	touch = "Now is not the time for rest. At attention! Your service has not concluded!",
	voice_key_2 = -1,
	mission_complete = "You got it done on time, did you? Good work.",
	battle = "Advance and annihilate the enemy!",
	id = 407040,
	gift_dislike = "",
	gift_prefer = "This gift... I only hope you carry over these same observational skills to your work.",
	profile = "By pairing aerial superiority with immense firepower, one can repel the enemy even when surrounded and without relying on aircraft. This is the concept for which I was designed. Far-fetched though it seemed then, now, my existence is proof of its feasibility.",
	voice_key = 40704,
	headtouch = "Is something the matter?",
	feeling2 = "Reach the top, Commander. Then you will see the most beautiful sight, with no one to block your view.",
	login = "For one who commands, punctuality is the bare minimum of what's expected of you. Try to arrive sooner so you may serve as an example for others.",
	detail = "Smooth talk does not yield victories, and wild aspirations alone cannot achieve success. Be pragmatic, Commander – that is the quickest way to achieve these things.",
	couple_encourage = {
		{
			{
				40701
			},
			1,
			"Equal devastation to all our foes!",
			0
		},
		{
			{
				40703
			},
			1,
			"Time is of the essence. Blitzkrieg!",
			0
		},
		{
			{
				40501,
				40505
			},
			1,
			"I am deeply honored to fight alongside you.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[407041] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Commander, get a feel for the service in our shop. Naturally, I will take notes of your feedback.",
	unlock = "Hm? It's you. Surprised by my appearance? Hmm... My apologies. I was thinking about how to rectify discipline inside the shop. At any rate, welcome.",
	touch2 = "I do admire your bravery, but...",
	mission = "Another mission. I will help you with it. You cannot afford to be lazy.",
	vote = "",
	drop_descrip = "Hm? It's you. Surprised by my appearance? Hmm... My apologies. I was thinking about how to rectify discipline inside the shop. At any rate, welcome.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I never thought I'd be told by you of all people to slow down and take my time. Very well – I'll consider your suggestion... What? You want to stand watch while I rest? But there is no one else here... Ahem. It's nothing. Allow me to rest, then!",
	main = "I'm scaring people, you say? Well... As the manager, I don't at all mind being strict if it can better your experience at our shop.|The experience Lord Bismarck imparted unto me has made my job significantly easier. I must thank her when I get the chance.|Stealing food from the kitchen, leaving work early when they see you're not coming... Such terrible work ethics. It's high time I established a set of strict rules for the employees.|As our single and very important customer, you should stay and rest up. Whether you're a soldier or a paper pusher, your work must be balanced with rest.",
	touch = "",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 407041,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "These ears don't look like rabbit ears to you? I see...",
	feeling2 = "",
	login = "Punch the clock when you start and finish work. Be on time, and don't leave early... Oh, Commander. That wasn't aimed at you.",
	detail = "I am the head of our pop-up shop – its \"boss bunny,\" in other words. I uphold discipline to ensure your comfort in... Just take it easy, you say? No! Every aspect of your experience must be perfect!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[407042] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "We're here. It's some ways out, but we were able to shake off the paparazzi. This restaurant is quite a place. Let's enjoy a candlelit dinner together.",
	unlock = "I'm afraid I kept you waiting, Commander. I've made all the necessary reservations for tonight, so all you need to do is be the special guest you are. Just relax, follow my lead, and allow me to show you the finest hospitality.",
	touch2 = "You don't want to get out of the car? Then close the door... and continue.",
	mission = "",
	vote = "",
	drop_descrip = "I'm afraid I kept you waiting, Commander. I've made all the necessary reservations for tonight, so all you need to do is be the special guest you are. Just relax, follow my lead, and allow me to show you the finest hospitality.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I know you're the type to be fully prepared for anything. Still, I want you to leave everything to me tonight. Don't think about a thing, and I will fulfill your every desire.",
	main = "You're nervous? That's to be expected. I always felt the same way before drills. The right amount of tension can sharpen your senses and shorten your reaction time. That said, your mission tonight is keep away from complex thought.|There is a strong wind. My coat is in the back seat. You may wear it if you get cold. I don't need it, and I only prepared it just in case.|Yes, this nightscape really is beautiful. I would like us to put our all into enjoying it together, if that's alright with you.",
	touch = "Could I ask you to fasten this strap for me, Commander?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 407042,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "You're worried I might bump my head, aren't you? I thank you.",
	feeling2 = "",
	login = "Get in. This is a rare day off for you. I am taking you on a drive as a change of pace before the main event.",
	detail = "You find my car too flashy? I am here to show you the best hospitality – such expenses are nothing. Now, follow me. You will see that this nightscape makes for the perfect drive and change of pace.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[408010] = {
	hp_warning = "Dammit... I'm gonna have to dive real deep...",
	feeling3 = "Not to brag, but I have a pretty stunning service record. Go on, let me hear your applause!",
	mail = "Isn't it nice having a letter waiting for you when you come back to port~?",
	expedition = "Hmm? Commission team's back. Mind if I go greet 'em? I could use a quick dip in the harbor.",
	win_mvp = "Now you know the power of U-boats!",
	home = "Here's a towel, Commander. Wipe that sweat off.",
	unlock = "Heheh, now I too have a commander! I'm U-81, I love playing hide-and-seek. If you can't find me, just shout \"U-81, I admit defeat!\" and I'll probably come out of hiding.",
	touch2 = "Whoah?! I warned you about doing that, Commander! My torpedoes almost just went off...",
	mission = "Commander, you've got a new mission.",
	vote = "",
	drop_descrip = "Iron Blood Type VIIC submarine – U-81.",
	feeling4 = "Hmm? Found me again, huh. You've been finding me a lot lately...",
	lose = "Damn... The Commander will avenge me for this!",
	feeling1 = "Enttäuscht...",
	skill = "Angle looks good! Fireeee!",
	upgrade = "Feels like I've gotten more dexterous!",
	propose = "This... must be what \"getting hitched\" means! Hehehe~ I'm happy, but also kinda embarrassed... O-of course, I love you very much, Commander!",
	feeling5 = "I just realized something big. That your bed is ridiculously warm! I'm gonna sleep with you from now o... What? Did I say something strange?",
	main = "I'm gonna go check around the office for places to hide. Hehehe...|Adjust firing parameters... check the compass and scales... Clank, clunk... *Giggle*...|How about a game of hide-and-seek, Commander?",
	touch = "Bombers?! Aaaahhhh! Commander, there are some things you just can't joke about!",
	voice_key_2 = -1,
	mission_complete = "The mission rewards are here! If you don't want 'em then I'll just help myself!",
	battle = "Quietly... sneakily... infiltrating the battlefield...",
	id = 408010,
	gift_dislike = "",
	gift_prefer = "I... really like this!",
	profile = "I'm U-81, Type VIIC submarine of the Iron Blood Navy. I have a ton of sisters who can be pretty unruly sometimes! ... Also, I have the sinking of Ark Royal under my belt! She's a weird woman... I can't properly explain what makes her weird, though...",
	voice_key = 40801,
	headtouch = "",
	feeling2 = "Heheh, I love hide-and-seek! It's also my specialty!",
	login = "So you're finally back, huh. I thought I was gonna die of boredom.",
	detail = "Booooom! Did I scare ya there, Commander?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[408011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "I'm right here, Commander. ... Not hiding for once? Well, it's not like I can! Nobody could play hide-and-seek in this gaudy frickin' dress...",
	unlock = "*Ugh*... I figured this bulky dress would be hard to move in... Huh? I look pretty? Aha, ahaha... You're makin' me blush...",
	touch2 = "Hey! You did that on purpose, didn't you?!",
	mission = "",
	vote = "",
	drop_descrip = "*Ugh*... I figured this bulky dress would be hard to move in... Huh? I look pretty? Aha, ahaha... You're makin' me blush...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "S-some people told me a serenade is a perfect love song... so I did some practice. Y-y-you wanna hear it? Whuah! Just don't laugh if it sounds bad!",
	main = "This isn't wine, it's a soft drink! Don't believe me? Then have a sip for yourself! C'mon!|Err, you wanna dance with me...? B-b-b-but I have no idea how to dance...|This here kitty is my personal butler! Whaddya think? Is that awesome or what?",
	touch = "You wanna hear me play the piano? Errm... I-in a bit, so just hold on a few...!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 408011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "You're LATE, Commander! Just how long are you gonna keep me waiting?!",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[408012] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission team's back! Our circle of friends to celebrate with grows!",
	win_mvp = "Alright! Let's sail back to port and celebrate.",
	home = "We're lucky the skies are clear today! We wouldn't get to see a full moon for another month if it had been cloudy.",
	unlock = "Over here, Commander! I came because you said we were going to go moon-viewing together! I even brought tea and mooncakes.",
	touch2 = "Commander! Now's NOT the time for this!",
	mission = "",
	vote = "",
