_G.pg.base.ship_skin_words[408020] = {
	hp_warning = "You can't be serious.",
	feeling3 = "So like, I can't really help with your work at all... But you'll let me stay here... You don't mind?",
	mail = "New report is in... I hope the enemy doesn't crack our codes...",
	expedition = "Looks like the commission team is back... There's a lot of them. I don't want to go...",
	win_mvp = "That's how it goes.",
	home = "So many people here now... It's so loud...",
	unlock = "Type VIIB submarine, U-47. I don't like crowds... If that's all, I'll be in my room.",
	touch2 = "You looking to take a nap at the bottom of Scapa Flow?",
	mission = "There's another mission...",
	vote = "",
	drop_descrip = "Iron Blood Type VIIB submarine – U-47.",
	feeling4 = "I can visit anytime I want? Thanks... But... For some reason, I feel like I can't really relax here... I'm always on edge...",
	lose = "So this is how it ends...",
	feeling1 = "Give me some space.",
	skill = "Auf Wiedersehen...",
	upgrade = "Enhancing... sounds good.",
	propose = "I'm meant for more than just voyaging through the cold, dark oceans. My place is here, at the port, by your side... When I'm with you, even just sitting in silence, I feel... happy.",
	feeling5 = "I've spent thousands of hours swimming through the dark depths of the ocean... But lately all I can think about when I'm out on a mission is the warmth and light of your office... I think... I think I need to be with you, Commander.",
	main = "Enemies nearby? Welp...|If you need someone to patrol, I'm good to go anytime.|Such a quiet office... I approve.",
	touch = "Inspecting my equipment?",
	voice_key_2 = -1,
	mission_complete = "Rewards are in... You don't want to see them?",
	battle = "This is where you'll all sleep!",
	id = 408020,
	gift_dislike = "",
	gift_prefer = "I'll cherish it...",
	profile = "I'm U-47. I went behind enemy lines at Scapa Flow and sunk Royal Oak. I'm going to go out, sink the enemy, and come back. Just like I did then.",
	voice_key = 40802,
	headtouch = "",
	feeling2 = "Your office is very quiet. I like it here.",
	login = "Oh. You're back.",
	detail = "Are you sending me out? I can handle it by myself.",
	couple_encourage = {
		{
			{
				40801,
				40803
			},
			2,
			"Wolfpack... the hunt is on!",
			0
		}
	}
}


