_G.pg.base.ship_skin_words[408022] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "They're looking for me? Tell them to stop worrying. I'm fine.",
	unlock = "Sigh... I'd much rather be in a nice, quiet place like this over the din and clamor of the venue... Wouldn't you agree, Commander? I see. Well, come sit here then.",
	touch2 = "Should I sober you up?",
	mission = "",
	vote = "",
	drop_descrip = "Sigh... I'd much rather be in a nice, quiet place like this over the din and clamor of the venue... Wouldn't you agree, Commander? I see. Well, come sit here then.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "It's nice to be left alone, but the feeling I get when I'm with you... it feels almost addictive.",
	main = "I'm a little more talkative now? Huh... I just find I have more to talk about with you.|The party...? I wouldn't know what to do with myself out there.|I'm always stuck with a bunch of noisy girls: U-73, U-81, U-101... But even though I like it quiet, I really don't mind them that much.",
	touch = "Here's to you, for taking good care of me.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 408022,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "...You found me. Of course.",
	detail = "Another sortie? I'll be right out. ...It's fine, I can go dressed like this.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[408023] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Is this... an order? Oh, it's just new mail for you.",
	expedition = "Commission rewards, huh... Sorry, can't fit those in my backpack.",
	win_mvp = "I'm done cleaning, I guess.",
	home = "Check out the Iron Blood's shop when you're craving pastries. It's laid-back and comfy... (Plus you'll get to see me...)",
	unlock = "Coming through! Steer clear! Oh, it's you, Commander. Talk to you later – I've got coffee to deliver.",
	touch2 = "No more service from me today, then.",
	mission = "I see new delivery missions have come in.",
	vote = "",
	drop_descrip = "Coming through! Steer clear! Oh, it's you, Commander. Talk to you later – I've got coffee to deliver.",
	feeling4 = "",
	lose = "Need to hurry back...!",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Wanna hang after my shift's over? I'm thinking we could, uhh, go somewhere and unwind. Dunno where yet... Open for suggestions.",
	main = "If that's all, then I'm off for another delivery. It's nice, working solo.|Hey, um... You okay, Icarus? Sorry, I didn't mean to scare you...|Here, our phone number. Call us and we'll deliver to your office in 1 minute or less.",
