	mission_complete = "That's... a lot of mission rewards.",
	battle = "",
	id = 408023,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Welcome back, Master... You'd like to talk? About what?",
	detail = "Why the outfit? It's our theme, I guess. Isn't this what maids wear?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[408024] = {
	hp_warning = "",
	feeling3 = "",
	mail = "The bats outside the window are screeching again... Oh, they've brought a letter.",
	expedition = "Our commission team is back. Go say hi to them for me. Oh, and don't tell anyone I'm here.",
	win_mvp = "Better head home now before dawn breaks.",
	home = "Heya, Commander. You tired? I can get up if you need to lie down.",
	unlock = "An empty study with a cushy couch. The perfect place to relax. Whew... Go ahead and read a book if you want, Commander. If that'll be all then I'm gonna take a nap.",
	touch2 = "You're just asking for a bite to the neck.",
	mission = "Another mission just came in? ...Five more minutes, then I'll do it.",
	vote = "",
	drop_descrip = "An empty study with a cushy couch. The perfect place to relax. Whew... Go ahead and read a book if you want, Commander. If that'll be all then I'm gonna take a nap.",
	feeling4 = "",
	lose = "Overextended, huh... Figures.",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I read this love story featuring a vampire and a human. It was actually pretty good. If you're free, we could read it together.",
	main = "I'm so not cut out for the role of a vampire's servant. Chilling in a corner is more my thing...|You interested in this tome on vampire myths, Commander? ...What about me? Meh.|U-73, why are you coming up to me with this weird potion? ...Garlic juice? Thing is, I'm not a real vampire, so...",
	touch = "I can help, as long as it's nothing too crazy.",
	voice_key_2 = -1,
	mission_complete = "Rewards from a mission just arrived. Want me to have a look?",
	battle = "Hope this will end quietly again...",
	id = 408024,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Mgh... Did they find me? Oh, it's just you. Welcome back, Commander.",
	detail = "\"It is I, U-47, servant of the Mistress\"... Okay, that's pretty cringe to say out loud...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[408025] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "A happy victory for a happy new year, I guess.",
	home = "There you are. Heehee... I heard you're meant to take it real easy today. Hope we can do that together...",
	unlock = "Nice. I've found a legendary luck-bringing carp, like... Oh. I almost had it, too... Sorry, Commander.",
	touch2 = "Woah! (U-47 got pulled back the moment before you could touch her.) Oh, s-sorry. I promise I wasn't trying to get away.",
	mission = "",
	vote = "",
	drop_descrip = "Nice. I've found a legendary luck-bringing carp, like... Oh. I almost had it, too... Sorry, Commander.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "This Dragon Empery dress is cozy and flexible. Lets me do anything with ease. Commander, if you have a New Year's wish, let me know.|The Four Unbreakables are making something? Like, food? If not that, then what?|Couldn't catch a carp, but Akashi's lightning-quick manjuu team caught tons of other fish we can have tonight... Am I miffed? Not really.",
	touch = "You want a closer look? One sec... Huh? You didn't mean the fish?",
	voice_key_2 = -1,
	mission_complete = "So, rewards. Can I take some? Lots of stuff there, the banquet won't use up everything.",
	battle = "Going underwa– Hey, stop pulling!",
	id = 408025,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I'll try again and catch a feisty one. Wait here, Commander.",
	detail = "Lützow digs the kitchen. Me, I'm content to just gather ingredients... You doubt that? The kitchen's much more work than this.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[408030] = {
	hp_warning = "How unfortunate...",
	feeling3 = "You wanna be friends with me? But I'm a bad luck magnet, and that might be annoying for... Nnh, why are you patting me on the head all of a sudden...",
	mail = "Commander, mail for you.",
	expedition = "Commander... a commission's done, by the looks of it.",
	win_mvp = "Victory... Is this what they mean by \"the tides turning\"?",
	home = "Commander, you made it back safely! Thank goodness...",
	unlock = "Type VIIC submarine, U-557, reporting in. I'm a bad luck magnet, so feel free to forget about and ignore me... As far as missions go... I'll give them my best shot.",
	touch2 = "What... was that... It felt weird...",
	mission = "Commander, I'm pretty sure we've got new missions... Probably, I think...",
	vote = "",
	drop_descrip = "Iron Blood Type VIIC submarine – U-557.",
	feeling4 = "My true feelings are the most important...? I... want to be of service to you... because you're always so nice to me...",
	lose = "Sigh... I'm used to it...",
	feeling1 = "It's just my luck to run into a commander like you...",
	skill = "Let's hope these hit their target...",
	upgrade = "Maybe this'll improve my luck too...",
	propose = "The most fortunate time in my whole life was when first I met you, Commander... If we're together, I'm sure I'll be able to gain some more luck. I'm kind of... excited about that.",
	feeling5 = "I always thought it'd be best if I stayed away from people so my bad luck doesn't bother them. But you want to stay with me regardless... That makes me so happy... I love you... Commander.",
	main = "I've only heard about \"The First Fun Time\" from my predecessors... I wasn't around for it.|When you're a bad luck magnet, you probably shouldn't get close to people. That way, you won't cause them trouble...|I'll try to be the best secretary I can. It's the one thing... I don't want to fail at...",
	touch = "What is it, Commander...? Wait, don't tell me... I've messed up again...?",
	voice_key_2 = -1,
	mission_complete = "Here are the mission rewards, Commander.",
	battle = "I hope I don't mess this up...",
	id = 408030,
	gift_dislike = "",
	gift_prefer = "Commander, what's gotten into you?",
	profile = "I'm U-557, Iron Blood Type VIIC submarine... I went on four sorties during the war, sinking six merchant ships plus Galatea. The day after I sank her, an allied ship mistook me for a Royal Navy ship and collided with me... I had a few accidents before that too, so maybe I'm just cursed with bad luck...",
	voice_key = 40803,
	headtouch = "",
	feeling2 = "You need something, Commander?",
	login = "Commander, nothing bad happened to you before you got here, right?",
	detail = "Pennies are said to bring good luck, so I saved a bunch in my piggybank... but that didn't seem to do much for me...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[408040] = {
	hp_warning = "D-don't lose control at a time like this!",
	feeling3 = "Commander, you wanna see how I dive? Heh heh, Lord Bismarck said it looked pretty good. I'm proud of myself too.",
	mail = "Beepbeepbeep! U-556 has received new information!",
	expedition = "The girls are back from commission! Should we go greet them?",
	win_mvp = "Ha-haa! Nike stands with us!",
	home = "Commander, I took out a whole bunch of books while you were gone and I kiiinda forgot where they go... Erm, sorry... Eheheheh...",
	unlock = "Ahoy! Type VIIC submarine U-556 here! This is my home port, no question! Oh, right, is Lord Bismarck here?",
	touch2 = "Hey! Commander, don't run away!",
	mission = "Ugh, there's still a mission to do.",
	vote = "",
	drop_descrip = "Iron Blood Type VIIC submarine – U-556.",
	feeling4 = "Waaahh! Why won't Lord Bismarck hug me? She said I'm too childish! ... Hey, do you wanna sub in for her, Commander? — Eheheh, you really understand me!",
	lose = "I won't fail like I did before... never again!",
	feeling1 = "Please don't make that face again... okay?",
	skill = "Too late!",
	upgrade = "The open sea. I have arrived!",
	propose = "I hereby declare before Neptune that I will protect the Commander, no matter the place, no matter the challenge! ... Heh heh. I believe you'll find I'm more reliable than you think, Commander!",
	feeling5 = "Commander, you and Lord Bismarck are the most important people to me! Without you, I would lose all will to fight... so if you could stay with me forever, that would make me happy...",
	main = "Commander, if you don't play with me I'm just going to go find Lord Bismarck|Commander, let's go swimming! Don't worry, I'll keep you safe!|Commander, sitting too long is bad for your health!",
	touch = "Come on, Commander. Can we go play with Lord Bismarck?",
	voice_key_2 = -1,
	mission_complete = "Mission complete! So can we go play now?",
	battle = "There is no escape!",
	id = 408040,
	gift_dislike = "",
	gift_prefer = "Ehehe~ Vielen Dank, Commander!",
	profile = "I swore an oath to Neptune himself, that I would protect Lord Bismarck from danger, no matter where she encountered it! ... But there are still some things I can't handle by myself. Ahahaha...",
	voice_key = 40804,
	headtouch = "",
	feeling2 = "Lord Bismarck! I'm here to play! Oh, huh...?",
	login = "Welcome back! Don't you feel super pumped on a day like this?",
	detail = "Grrryyeeaaaargh! Come at mee!! Haaaah... haaaah... sometimes I get stuck in war mode and need to calm myself down. Ahahahahaa!",
	couple_encourage = {
		{
			{
				40501
			},
			1,
			"Lord Bismarck! Let's give the enemy a beautiful thrashing!",
			0
		},
		{
			{
				20702
			},
			1,
			"Sorry, I don't really want to be around you...",
			0
		},
		{
			{
				40502
			},
			1,
			"Tirpitz! Watch this!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[408041] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Where are you always running off to, Commander? Come play with me!",
	unlock = "It's me, U-556, all prettied up! Eheheheh, we're gonna have lots of fun at this party, Commander! Come on, let's go!",
	touch2 = "Hmph! Don't think you're gonna get away with that!",
	mission = "",
	vote = "",
	drop_descrip = "It's me, U-556, all prettied up! Eheheheh, we're gonna have lots of fun at this party, Commander! Come on, let's go!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Awww, it's lights out after the party? But I'm not done playing. ... Hey, Commander, won't you play with me a bit more? Eheheh~ I love you, Commander!",
	main = "Don't give me that face, kitty. Here, look, it's my finger. It's over here! ... Now it's over here!|Commander, have you seen Lord Bismarck? Can we go look for her?|Om nom nom. Delicious! This is really good! Here, Commander, try some!",
	touch = "Where should we go next?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 408041,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I've heard parties are suuuuuuuuuuper fun! I can't wait!!",
	detail = "Hey, Commander, can we go check out the kitchen? ... Oh, they're really busy in there? I guess we better not get in their way...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[408042] = {
	hp_warning = "",
	feeling3 = "",
	mail = "I've got a wanted poster with a bounty right here! Just kidding. Take a look at your new mail!",
	expedition = "Any scoundrels out there who'd try to steal from the commission team? Probably not! Commander, the girls are back!",
	win_mvp = "Oh yeah! We shook 'em off! Let's get back to our original course, Commander!",
	home = "Let's see... Commander! You can rest inside the carriage if you're tired! Just hope you don't mind it being a bit cramped and bumpy. Heehee.",
	unlock = "I'm still Parzival of the Seas, even on land! Lord Bismarck entrusted me with these goods and I'm gonna keep them safe! Now step up and try your luck, hooligans!",
	touch2 = "Whoa, whoa! C-Commander, that was risky! *blushes*",
	mission = "",
	vote = "",
	drop_descrip = "I'm still Parzival of the Seas, even on land! Lord Bismarck entrusted me with these goods and I'm gonna keep them safe! Now step up and try your luck, hooligans!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Nobody's ever gonna steal my precious treasure from me – by that I mean you! Heehee! Wherever you go, I'll always protect you, just like I swore – at sea, on land, or in the sky!",
	main = "Bleh... Eagle Union coffee is so bitter... Is this even real coffee? Hm? Take this chocolate as a palate cleanser? Thanks, Commander!|No manjuu's gonna stop me! Follow me, Commander! We just have to ride to the next campsite and we'll be fine!|Riding a horse is easy peasy compared to riding a rigging! Heheh! I'll EASILY live up to your and Bismarck's expectations!",
	touch = "Now to reload while still holding the reins... Whoaaa! Oh man, this is really hard...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Like a torpedo, I always hit my mark!",
	id = 408042,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "\"Heheheh! Either ya keep the goods or ya keep yer lives!\" How was that? Don't I play a villain perfectly? Heh, then I can act just fine if the situation calls for it!",
	detail = "Ahahaha! Riding a horse is fuuun! If you ever need any help, Commander, just say the word! I'll teach you how to ride like a pro!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[408050] = {
	hp_warning = "Mein Leben! Better perform emergency maneuvers...",
	feeling3 = "The wild U-73 approaches quietly, waiting for her chance, and then POUNCES! ... Hahaha, I caught you, Commander!",
	mail = "Mail's just arrived~ Oh, do you want me to read it on your behalf?",
	expedition = "Commission complete! Great job, everyone!",
	win_mvp = "Heheh! Did you see how strong I am?",
	home = "Good to see you! Let me handle things for you while you get some rest~",
	unlock = "U-73 of the Iron Blood, reporting for duty! If there's anything that needs doing, just leave it to me!",
	touch2 = "Uh-huh. So, Commander, how many gut-punch torpedoes do you want for dessert?",
	mission = "So, we've got a mission. Let's do it together, Commander!",
	vote = "",
	drop_descrip = "Iron Blood Type VIIB submarine – U-73.",
	feeling4 = "I suppose you've fallen for me at last? Then stay by my side forever, Commander!",
	lose = "Oh nooo...! Ahaha... How the heck could we lose...",
	feeling1 = "Uh... My friends are waiting for me, so sorry, gotta scamper.",
	skill = "Wolfsrudeltaktik, commence!",
	upgrade = "Now my shots will be even more on point! Heh heh~",
	propose = "Ahah, I didn't think this would happen so fast, but now you're a part of me! Relax, just let me handle everything for you! I'll take care of you for the rest of your life~",
	feeling5 = "True, I can't guarantee I'll be speedy when I dive... but no matter what, you'll be mine, Commander! Especially your heart! Hahah!",
	main = "When you're underwater all day, sometimes you just wanna resurface and smash through the waves! ... Hey, Commander, wanna go for a quick dive in the ocean?|I'd rather be diving in the ocean and feeling the thrill of being near the enemy than stuck at port staring into space all day...|Isn't it fun to hear what's on somebody's mind and help them with it? ... Maybe I ought to open a psychiatric booth. Anyway, Reichspfennig for your thoughts, Commander?",
	touch = "What is it? Got something I could help with? C'mon, tell me something.",
	voice_key_2 = -1,
	mission_complete = "With my support, we could finish these missions with our eyes closed!",
	battle = "The leader of wolfpacks, that's me!",
	id = 408050,
	gift_dislike = "",
	gift_prefer = "This is all for me? You sure know how to make a girl happy, Commander~♪",
	profile = "I'm U-73, the Iron Blood submarine that completed lots of missions and served as the leader of several wolfpacks!",
	voice_key = 40805,
	headtouch = "",
	feeling2 = "Oh? Finally managed to catch a break, Commander? Then let's go for a quick stroll, shall we?",
	login = "Howdy-do, Commander! Welcome back! I'm all good to go and ready to sortie! Just give me the order.",
	detail = "Now, now, Commander, don't stress over everything~ I'm sure it'll all go fine.",
	couple_encourage = {
		{
