_G.pg.base.ship_skin_words[408052] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "",
	unlock = "In today's chemistry lesson, we'll learn how to make a warming cup of tea and an optional concoction to enhance its flavor! Will you do the honor of taste-testing it, Commander?",
	touch2 = "Seems you desire a \"special\" kind of concoction, huh.",
	mission = "",
	vote = "",
	drop_descrip = "In today's chemistry lesson, we'll learn how to make a warming cup of tea and an optional concoction to enhance its flavor! Will you do the honor of taste-testing it, Commander?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "And for the last step, we raise the heat a few degrees. See, brewing tea is like doing science – it takes precision.|Might it be possible to make tea from a chemical concoction? Hmm... It wouldn't really feel like tea if you made it that way... So that's tricky...|You think I seem more ladylike than usual? Heh! That's exactly what I set out to do!",
	touch = "You'd like a refill? Coming right up!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Looks like I've found the ingredients for my concoction!",
	id = 408052,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "You wanna learn the formula? Sure thing! First you mix the contents of these beakers, then... Wait, are your hands shaking? Hahaha! Come on, it'll be fine – I'm right here!",
	detail = "Decided I'd try on this Dragon Empery dress, in light of the season! Does it look good on me? Hehehe~",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[408060] = {
	hp_warning = "Looks like I've gotta pick up the pace...!",
	feeling3 = "Y'know, I really want to have an all-out race with the other factions' subs. I just know it's gonna get my blood pumping! How about it, Commander, wanna do me a favor? ",
	mail = "Hello! Your local courier U-101 has new mail for you~ Hahaha!",
	expedition = "The commission fleet is back? All righty, I'll go pick 'em up!",
	win_mvp = "Booyah! Number one!",
	home = "Commander, want me to drop you off at the dorm so you can get some rest?",
	unlock = "Hey! You! That commander over there! How 'bout coming for a ride on my Great Shark? I'll show you a real thrillin' time!",
	touch2 = "...Commander?! Sic 'em, Great Shark!",
	mission = "You have a new task? Want me to take you to where you need to go?",
	vote = "",
	drop_descrip = "Iron Blood Type VIIC submarine – U-101.",
	feeling4 = "Commander, hurry up and hop on! There's a school of incredibly rare and beautiful fish passing by today! Who knows how long we'd have to wait if we missed this opportunity!",
	lose = "Couldn't get out of the way in time...",
	feeling1 = "I'm going for a ride! Tschüss~",
	skill = "All boat torpedoes, launch! ",
	upgrade = "I feel the need for speed!",
	propose = "Don't worry, Commander. As long as you're somewhere Great Shark can get to, call me any time. I swear I'll come for you!",
	feeling5 = "Commander, look who's back! Hehe, seems like you've fallen in love with Great Shark, huh? All right, get on. Today, I'm going to show you a real special place!",
	main = "Ah, Commander, wait just a sec. I've gotta finish fine-tuning Great Shark. We can go afterwards. |Great Shark is land-capable, you know. Well, just not as fast. Don't ask why it works that way! |What kind of music do you like to listen to on trips, Commander? Have any recommendations?",
	touch = "Hop on, Commander, and make sure to hold on to my waist tight! It won't be my fault if you fall off~",
	voice_key_2 = -1,
	mission_complete = "Commander, I've brought the rewards!",
	battle = "My boat torpedoes are ready!",
	id = 408060,
	gift_dislike = "",
	gift_prefer = "Woow... You're a nice person, Commander!",
	profile = "I'm U-101, one of the Iron Blood's 7th U-Boat Flotilla. I took part in four wolfpack operations. You could say that disrupting the enemy supply lines is my specialty - I even received a Knight's Cross! My hobby is going on long rides with Great Shark. Commander, wanna come with me?",
	voice_key = 40806,
	headtouch = "",
	feeling2 = "When I put in my headphones and rev the engines, I can outrun all my worries. Lemme tell you, Commander, it's one hell of a feeling.",
	login = "Commander, just hit me up next time and I'll give you a ride, okay?",
	detail = "You know about those Union girls who call themselves \"Solomon Knights\" or something? Well, it has a nice ring to it... All righty, Commander, I'm an \"Undersea Knight\" from now on, got it?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[408061] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "It's pretty far from here to the piers. Commander, how about we take Great Shark out for a spin?",
	win_mvp = "",
	home = "Good work out there, Commander. Let's put on something chill~",
	unlock = "Commander, welcome to the school band! Why'd I join the band? The reason's simple – there's no Motorbike Club at school, haha! Just kidding~! Actually, I'm quite fond of music as well, heh.",
	touch2 = "Woah! I almost smashed this over your head...",
	mission = "Commander, there's a ton of homework today.",
	vote = "",
	drop_descrip = "Commander, welcome to the school band! Why'd I join the band? The reason's simple – there's no Motorbike Club at school, haha! Just kidding~! Actually, I'm quite fond of music as well, heh.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I don't know why, but when it's just the two of us in the band room, my chest starts fluttering like I'm sick... but I'm so glad... Aghh!! I'm gonna go take Great Shark out for a spin!",
	main = "Commander, I recently started learning the trombone, hehe. I'm not very good at it, but it's still pretty interesting. Wanna listen~? |If I was able to play this thing underwater, I'd be able to perform for the fishes! Too bad, though... Guess I'll have to settle for the fish in the aquarium!|Even though we U-boats hang out together regularly, studying together at school feels rather special!",
	touch = "Commander, how about becoming the band conductor?",
	voice_key_2 = -1,
	mission_complete = "Commander, I'm all done with my homework. Let's go for a ride!",
	battle = "",
	id = 408061,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, let's put on some music!",
	detail = "It feels nice to kick back and enjoy some good music!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[408070] = {
	hp_warning = "You're not half-bad...",
	feeling3 = "Hey, you're pretty chill~ I'm feelin' like this is the start of a good relationship~",
	mail = "Commander, got news for ya from headquarters~",
	expedition = "Commission team's back safe and sound~ Let's go check out those rewards.",
	win_mvp = "That's all? Laaaame. I wanna have more fun~",
	home = "Mumph... Oh, you're back? Want some corned beef?",
	unlock = "Hmm... you're the commander 'round here, eh? I'm U-522, Iron Blood submarine, reporting for duty. Anyhoo, heard this here port's like a party. I'm eager to join in on it. Heheheh~",
	touch2 = "Tail - no touch! Bad Commander! That's my sensitive spot!",
	mission = "Ya figure we got any new missions, possibly involving hunting?",
	vote = "",
	drop_descrip = "Iron Blood Type IXC submarine – U-522.",
	feeling4 = "Commander, your cunning plans won't work on me. Cause 9 times outta 10, I know just what you're thinking.",
	lose = "Oopsie... Guess I messed up a calculation...",
	feeling1 = "Sure can't count on you, huh, Commander. Guess that's cute in a way, though?",
	skill = "Victory blitz!",
	upgrade = "Sehr gut!",
	propose = "I'm kinda worried about your future, what with how dang easy it is to read you, Commander~ But it's cool, I'll always be with you, so do keep counting on me, 'kay? Ahahahah~",
	feeling5 = "I think we oughta get to know each other more intimately~ Whaddya say, Com-man-der? Ahahahah! Look at you, blushing! Oh, that's hilarious!",
	main = "This tail connector's not just for show. When plugged into my rigging: bam, gives me perfect control.|When I'm fighting, you can stare at me to your heart's content, y'know? Hehehe~|I just LOVE seeing my enemies squirming about, trying to get away from my attacks~ Ahahahah~!",
	touch = "You feelin' like some hide and seek? I'm game. I always win, y'see.",
	voice_key_2 = -1,
	mission_complete = "Commander, check out this mound of rewards we got~!",
	battle = "Oh boy, here we go! Listen up, folks! It's lunchtime!",
	id = 408070,
	gift_dislike = "",
	gift_prefer = "Oh, wow. You really do know what I'm into! You deserve a little reward~",
	profile = "I'm U-522, Type IXC sub, from the glorious 2nd U-boat Flotilla. You need long-distance commerce raiding, I'm your girl. Anti-sub escorts do put me in one helluva pickle, though. Anyways, keep those eyes peeled for my combat performance~",
	voice_key = 40807,
	headtouch = "",
	feeling2 = "You want a fun hunt, ya need good chums, else it's not happening~",
	login = "Always happy to see ya, Commander. Today's lookin' like it'll be fun.",
	detail = "Hehe, been oglin' me for some time, haven'tcha, Commander? I noticed ages ago!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[408080] = {
	hp_warning = "U-110's awesoooome. I'm not giving uuuuup.",
	feeling3 = "Believe it or not, this hairstyle was born with meeeee. Mhm, I'm a shaaaark. Raaaawr!",
	mail = "I'll take care of your encrypted maaaail.",
	expedition = "Commander, someone's come back to pooort.",
	win_mvp = "Raaaawr. U-110 scared the enemies awaaaay.",
	home = "Commander, your office is so booooring.",
	unlock = "Raaaawr. U-110 is a shaaaark. Fear meeee. Mess with me and I'll bite yooouuu.",
	touch2 = "Nom! (U-110 bit your finger.)",
	mission = "Commander, once your mission's doooone, let's plaaaaay.",
	vote = "",
	drop_descrip = "Iron Blood Type IXB submarine – U-110.",
	feeling4 = "Bulldog's really smart. Playing with her is fun. Next time, you should come play with us tooooo.",
	lose = "Codebooks, where are my codebooks... Goodie, they're safe...",
	feeling1 = "Why won't you play with me...",
	skill = "Raaaawr!",
	upgrade = "U-110's super scaryyyyy.",
	propose = "Commander is so nice to me. I love you. U-110's gonna bite anyone who messes with you. U-110's scaaaryyy. Raaaaaawr!",
	feeling5 = "The Commander is my friend. I'll give you some of my codebooks. That way it'll be fine even if I forget mine. Yup-yup.",
	main = "Codebooks, codebooks... Oops, I forgot them in the dorm.|Commander, let's plaaaaay. Leeeeetttt'ssss plaaaaaayyyy.|I got lectured for pretending to be a shark... But I still had fun.",
	touch = "Commander, I'll give you a swirly-whirly if you play with meeee.",
	voice_key_2 = -1,
	mission_complete = "Rawr! I've brought the mission rewaaaaards.",
	battle = "I'm a shaaaark. Raaaawr.",
	id = 408080,
	gift_dislike = "",
	gift_prefer = "Commander, friend.",
	profile = "I'm U-110, Iron Blood Type IXB submarine, and I'm really good at commerce raiding. The Enigma machine I've got in my backpack is awesome. I'm awesome too, I just left my codebooks and charts behind...",
	voice_key = 40808,
	headtouch = "",
	feeling2 = "You mean my Enigma machine doesn't have any use anymore? Okey-dokey, then let's play a game of decipheriiiing.",
	login = "Commander, did you bring swirly-whirly candies?",
	detail = "I'm not a garlic bulb, I'm a shaaaark. Fear meeee. Raaaawr.",
	couple_encourage = {}
}


