_G.pg.base.ship_skin_words[408084] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Let's build a snowman. Or a shiver of snowshaaarks. ...There's no such thing as a snowshark?",
	unlock = "Commander, happy new yeeear. I'm no bunny, I'm a shaaark. Not a cute shark, but a crimson, scaaary shark. Raaawr.",
