_G.pg.base.ship_skin_words[408091] = {
	hp_warning = "",
	feeling3 = "",
	mail = "A new notification?! Oh, it's just your mail. I thought I was getting a challenge from L.I. or something.",
	expedition = "",
	win_mvp = "",
	home = "Right, so, I just read up on this new strat. You should help me practice it!",
	unlock = "Nice timing. I just finished an intense battle. The result...? Of course I won. What? Did you want to have a match against me?",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "Nice timing. I just finished an intense battle. The result...? Of course I won. What? Did you want to have a match against me?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "If you wanna beat me, go practice for a few years and then come back, Warrior from the Land of the Rising Sun. Ahaha~|Um... wait a sec, I think I heard some weird noise. Don't tell me U-81's bunch snuck into my room again while playing hide-and-seek...|I'm a pretty big fan of the Dragon Sisters, y'know? How should I put it... They work hard, and you can't ever hate 'em. Isn't that right?",
	touch = "How about another match? All right! There's gonna be a punishment for the loser~",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 408091,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "The snacks and drinks are on the side. Go ahead, help yourself to whatever you want. No need to be polite.",
	detail = "This getup's real comfy and easy to move around in. Plus, I'm in my own room, and it's not like it matters if you see.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[408092] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Commission team's back. Guess we'd better go get into gear.",
	win_mvp = "Victory iiis... mine!",
	home = "Try to lift somethin' too heavy and it'll only hurt ya. Not like I'm worried you'll do literally that – choose your enemy, is all I'm saying... Hah, guess I am worrying after all...",
	unlock = "Mmgh... Guh... Ahhh! These things are heavier than they look... Oh, there you are. You work out too, do ya? Feel free to join me if you've not just come to tease me.",
	touch2 = "I'll remember that... You're getting what's coming to ya later!",
	mission = "",
	vote = "",
	drop_descrip = "Mmgh... Guh... Ahhh! These things are heavier than they look... Oh, there you are. You work out too, do ya? Feel free to join me if you've not just come to tease me.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Is that Northern Parliament girl using just one hand...? I'm frickin' speechless. What kinda crazy workout routine has she been doing?|Hey, you'll get outta shape if ya sit on your ass all day. Want me to show ya how it's done?|Grit is the name of the submarine game. I can work out here every day, no problem. I can coach you every day too, if ya want.",
	touch = "",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 408092,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I'm gonna get it this– Ah! Whew... Always showing up at just the wrong time... To hell with it. Let's get started on our workout.",
	detail = "Yeah, what? You fancy how an exercising U-boat looks?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[408093] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Heh. Open another bottle of champagne for me when we get back, will ya?",
	home = "Hm? You tryna reward me? Hang on, why should I be rewarded when YOU just got back from a sortie? Should be the other way 'round, no?",
	unlock = "Sup. If it isn't our Commander. Got bored already because you shattered all your previous records? Or, did you run into some mechanical issues? ...Huh, you're here to ask for my support? Did the butterscotch get to your brain or what? Despite the way I look, I've been on the sidelines cheering you on this whole time.",
	touch2 = "I swear, people like you... Huh? Oh, you went for THOSE... *blushes*",
	mission = "",
	vote = "",
	drop_descrip = "Sup. If it isn't our Commander. Got bored already because you shattered all your previous records? Or, did you run into some mechanical issues? ...Huh, you're here to ask for my support? Did the butterscotch get to your brain or what? Despite the way I look, I've been on the sidelines cheering you on this whole time.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "What, you want me to root for you to pump you up? Is that why you made me wear all this? Fine. C'mon, you can do it. You're the best Commander there ever was. Now get out there! Pedal to the metal from start to finish!",
	main = "I'm not worried 'cause I know you're gonna win. But, if you were to lose, don't worry – I'll win in your stead. Hahah!|I can root for you anywhere and everywhere. On the stage, on the track, even on this bad boy – so, got a particular place in mind?|Should I be cool, or just do like usual and be tough... Hm? Nah, it's nothin', I'm just thinking about what kind of cheering on will make ya the happiest.",
	touch = "No boots? Yeah, 'cause it'd get hot as hell, standin' around in those. You oughta take that suit of yours off if you're sweating, too.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 408093,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Yo. Here for an inspection? Or to spectate? Or maybe you wanna cheer on the gals with me? Do whatever you wanna.",
	detail = "I'm no shut-in or nothing, but standing all day in the blazin' sun is gonna be the death of me... You feel the same? Then do me a solid and gimme a massage in a bit.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[408100] = {
	hp_warning = "Oh crap! Might be time to dive back down and hide...",
	feeling3 = "Check out my massive rigging, it's big enough for two people! Hop on and I'll take ya some place far away!",
	mail = "Look at that, new mail! Wonder if it's from across the pond.",
	expedition = "Commission team's back? I'll go greet 'em! Better that than be bored to death in this office!",
	win_mvp = "We are so throwin' a party when we get back!",
	home = "The deep sea hunter's back, baby! Didn't score any prey, but I just caught me an slacking commander! Heheh!",
	unlock = "I'm the hunter that prances across the open seas, U-37! ...Huh? Is the commander here always this spaced out? Well, I've given you my name already, so catch ya later~!",
	touch2 = "You got a kink for submarines or somethin', Commander? Well, well...",
	mission = "New mission, huh? I'm on it! ...What? We're not disruptin' cargo lanes?",
	vote = "",
	drop_descrip = "Iron Blood Type IXA submarine – U-37. ",
	feeling4 = "When ya go on missions in remote oceans, ya gotta live with being alone for days in a row... But I've got this photo of you in your sleep to help stave off the loneliness! Heheh~",
	lose = "Well damn. Better luck next hunt, huh...",
	feeling1 = "Miss me with your lame ass! Laterrr!",
	skill = "You ain't gettin' through me!",
	upgrade = "Now that's a nice boost to my swimming skills!",
	propose = "I knew this day was comin', but I'm still feeling all giddy! Thank you for this, my lazy but adorable Commander! I'll always be with you from this day onward!",
	feeling5 = "Sometimes I just wanna be right beside you, sometimes I just wanna hide and watch ya struggle to find me. Y'know, I think I'm in love! You made me feel this way, and you'll own up to it, won'tcha? Hehehe~",
	main = "Can't I get a free pass if just say the paperwork's up and vanished? No? Figures.|They say teamwork makes the dream work! So let's round up some more peeps to do this paperwork!|Touch my tail without warning, and I'll whip your ass with the tail end of my rigging! ...Hey, I'm kidding! Hahahahah!",
	touch = "How d'ya like my glossy, wet skin~?",
	voice_key_2 = -1,
	mission_complete = "Mission's been completed! Guess I didn't have much to do with it though... Lame.",
	battle = "Wanna hazard a guess where I'll appear from~?",
	id = 408100,
	gift_dislike = "",
	gift_prefer = "Huh? Is this for me?! No givesies backsies, alright?!",
	profile = "Difference between us Type IX's and the Type VII's is that we're bigger and can go farther! We hide where they'll least expect us... then BAM! Torpedo 'em to smithereens! ...The what in Hudson Bay? They just made that up for that movie! The real me was still alive and kickin'!",
	voice_key = 40810,
	headtouch = "",
	feeling2 = "So here's the dorm, here's the academy, and here's the office... Gotcha. Now I've got a pretty good idea of where everything is!",
	login = "Oh, hey! I'm going out, so call if ya need somethin'! Gonna go for a dive!",
	detail = "My rigging's got bits that'll hurt ya, so watch yourself if ya wanna feel it.",
	couple_encourage = {
		{
			{
				40801,
				40802,
				40803,
				40804,
				40805,
				40806,
				40807,
				40808,
				40809
			},
			2,
			"Wolfpack, let's mess 'em up!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[408101] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "All right, I'm goin' out to– Oh crap, oh no! ...Phew, thanks, Commander. Nearly tripped right there... Mad respect to the Sakura Empire girls who can walk around in this stuff like it's nothing...",
	unlock = "Now then, please lend your ears to this song I shall offer you... Wait, Commander, are you spacing out again? Even though I went through all this trouble to learn this song from my friends in the Sakura fleet... Please pay attention, okay? I'm starting over...",
	touch2 = "Whoa there, lost all self-control, have ya, Commander~?",
	mission = "",
	vote = "",
	drop_descrip = "Now then, please lend your ears to this song I shall offer you... Wait, Commander, are you spacing out again? Even though I went through all this trouble to learn this song from my friends in the Sakura fleet... Please pay attention, okay? I'm starting ov",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Playing music's a way for you to express your feelings... I, uh, might still only be able to play beginner songs, but... you feel the emotion in 'em, right?",
	main = "These clothes keep slippin' off... Annoying for me, but just the way you like it, am I right~? Heheh~|My U-boat buds agreed to play this thing called \"hanetsuki\"! U-110 sure seems excited about it... Hang on, can I even play in these tight clothes?|An electric guitar would really be more my style, y'know? Would kinda clash with this getup, though. Ahah.",
	touch = "Hehehe~ I've got pretty slick skin if I do say so myself.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 408101,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Hey! Happy New Year, Commander! Lessee here... Just tryin' to think of a fitting New Year's song...",
	detail = "Now then, my dear visitor, I would like to play for you a little song... Heheh, go figure, I'm good at this whole mimicry thing!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[408102] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Nice, nice! You did some damn good work today. Hop on and I'll drive ya back home. And don't worry – it's a movie prop, sure, but I AM licensed to drive it!",
	unlock = "There ya are, Partner! I'm tellin' ya, these punks running around the port are getting bolder and bolder. It's time someone cracked down on 'em! Anyway, I'll handle this stuff like usual – you go and do your thing, Partner.",
	touch2 = "Heehee, real bold – you askin' to be put in cuffs?",
	mission = "",
	vote = "",
	drop_descrip = "There ya are, Partner! I'm tellin' ya, these punks running around the port are getting bolder and bolder. It's time someone cracked down on 'em! Anyway, I'll handle this stuff like usual – you go and do your thing, Partner.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Hell yeah, Partner, gimme five! Bangin' job on completing the mission! ...Click! Heh! You can't get away from me now that we're cuffed together! ...Huh? We don't have the key? Heehee, well, then we'll just spend the rest of our lives chained together!",
	main = "Take these gloves, Partner. The two of us'll bring back peace to the port's streets! ...Heh, me talkin' all seriously for once must be a nice change of pace for ya.|I'm not 'boutta lose in a race to some punks off the street! C'mon, get on, Partner! We're gonna show 'em how committed we are to maintaining road safety!|All streets bow to the king that is road safety! Whenever you're chasin' down thugs, remember to stay safe, Partner!",
	touch = "Pretty tight fit, ain't it? Makes me look like a real true and blue cop.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 408102,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Hey, take it easy. I'll take off my hat so ya can pat my head all ya want.",
	feeling2 = "",
	login = "You're here early, Commander! Let's go for a ride before the shooting starts. Remember to hold on tight to me, and don't let the high speeds freak ya out.",
	detail = "Partner, our top-priority mission for the near future is to keep a real close look on some punks: The Spark Speeders, and the... the Loosey Boozers... Pfft. Their races have been gettin' wilder and wilder, and it's time we did somethin' about it. Heheh, that name tickled my funny bone...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[408110] = {
	hp_warning = "No more playing nice...!",
	feeling3 = "Patience is the most valuable trait a submarine can have. What lengths would you go, how long would you wait for someone dear to you, Commander? Hehehe~",
	mail = "Letting your mail pile up just to read through it all at once might feel rewarding, but it's not very productive.",
	expedition = "The commission team has come back in one piece. That's nice to see.",
	win_mvp = "You'll need to do better than that, my surface ship friends.",
	home = "Haste makes waste. Take it easy, yeah?",
	unlock = "Formally, I'm the Type VIIC submarine U-410. But you, Commander, can call me whatever resonates with your heart. You heard that right: just let your heart decide. Hehehe~",
	touch2 = "Are you saying you find my body \"too good to pass up?\"",
	mission = "Do you find it thrilling to put off your missions until the last minute?",
	vote = "",
	drop_descrip = "Iron Blood Type VIIC submarine – U-410.",
	feeling4 = "I've got someone on the hook. What do I mean by that? You'll have to wait to find out. That's part of what being patient is about.",
	lose = "There's no turning this battle around... We should probably retreat.",
	feeling1 = "I just don't know what to do with inconsiderate jerks like you.",
	skill = "Watch your back~",
	upgrade = "Bolstering your combat abilities is always a good move.",
	propose = "Ooh, I see you've been preparing something of your own. So, have you made your mind? You'll live the rest of your days happily with me? ...Great, then we're all set♪",
	feeling5 = "Why don't we start dating, Commander? ...What's this out of the blue? I've taken my sweet time preparing, and this is the time to strike! Hehehe, now give yourself to me~♡",
	main = "Sauerkraut juice is a great pick-me-up. Give it a try and see for yourself.|Penelope? Oh right, she works here too. Take good care of her, you hear?|You can't figure out what that report says? Let me see... What, I'm too close to you? Hmm... Well, my bad~",
	touch = "Just give me the signal when you wanna slack off. Hehehe~",
	voice_key_2 = -1,
	mission_complete = "Accomplishing a mission can be the reward in and of itself. Receiving tangible things is a nice bonus, though.",
	battle = "There's nothing to worry about. Just take it easy.",
	id = 408110,
	gift_dislike = "",
	gift_prefer = "I'm a little curious how long you agonized over this gift.",
	profile = "For an Iron Blood \"wolf,\" I don't have much to boast about. I went on a few patrols and the odd rescue mission, but that's about it... I just wish my career would've ended out at sea instead of docked at port.",
	voice_key = 40811,
	headtouch = "",
	feeling2 = "A submarine must be slippery, elusive. You know, an unknown threat lurking beneath the surface. Hehehe...",
	login = "Oh, you're back. Ready to start chipping away at this mountain of paperwork?",
	detail = "I think it's good for a submarine to act a bit more mysterious. Wouldn't you agree, Commander?",
	couple_encourage = {
		{
			{
				40801,
				40802,
				40803,
				40804,
				40805,
				40806,
				40807,
				40808,
				40809,
				40810
			},
			2,
			"There's no escaping the wolfpack!",
			0
		},
		{
			{
				20229
			},
			1,
			"Yeah, that's it! Draw the enemy closer!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[408111] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Take it nice and easy. No point stressing out on a holiday.",
	unlock = "Happy Lunar New Year. Have you cooked up a scheme for this year's festival? Hehehe~ I'm of course talking about giving out New Year's gifts and hanging up decorations. I've devised a master plan of my own.",
	touch2 = "Whoa there. A little too excited from all the festivities, aren't we?",
	mission = "",
	vote = "",
	drop_descrip = "Happy Lunar New Year. Have you cooked up a scheme for this year's festival? Hehehe~ I'm of course talking about giving out New Year's gifts and hanging up decorations. I've devised a master plan of my own.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "We were playing hide-and-seek earlier, and get this: U-81 hid herself inside a snowman. That girl is on a completely different level.|I wonder what Penelope's up to... I might just go and check.|It's really hard to hang these up on my own. Would you let me ride your shoulders, Commander?",
	touch = "Is this your idea of a New Year's gift?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 408111,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "While there's no huge stack of paperwork awaiting you, there's no shortage of other things we need to do.",
	detail = "Can't think of a good present? Hmm. Might I suggest a handwritten letter? I think that gets your feelings across pretty well.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[408112] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Aren't I supposed to be cheerleading, not taking the lead? Heehee.",
	home = "Did my cheerleading before the sortie do its job?",
	unlock = "And for my finishing move... maybe something like this? Heehee. What do your eyes think, Commander?",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "And for my finishing move... maybe something like this? Heehee. What do your eyes think, Commander?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "As long as you know someone is rooting for you, be it through cheerleading or whatever, you'll perform better than you would otherwise.|Keep it up! Keep it up! Coooommander! Heheh! How was that? Do you at least feel a little supported? ...You don't want it look like you're staring? Oh, sorry about that♡|You want me to do a peppy holler and hoot? I... Yeah, I dunno about that...",
	touch = "Oh, so my cheerleading is \"distracting\" you, is it?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 408112,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Thanks for the backing, Commander.",
	feeling2 = "",
	login = "Welcome back, Commander. Are you ready to practice with me?",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[408120] = {
	hp_warning = "Ow, ow, ow! Stop hitting me!",
	feeling3 = "If only I had a button that autocompleted one day's work. If I did, I'd press it for you every single day... No, don't be greedy, Commander! One press a day is all you'd get!",
	mail = "You've got new mail! I'll open it for y– Oh... I guess should've asked you for permission first...",
	expedition = "The commission team is back! I'll go say hi!",
	win_mvp = "We did it! Wait, shouldn't I get some sort of prize for being the MVP?",
	home = "Welcome back, Commander! Hmm... Wouldn't it be nice if we could just push a button to open your office door remotely?",
	unlock = "Commander! Yeah, you! Get back here! You're supposed to greet me! Listen up, I'm the Iron Blood submarine U-1206, and I'll be serving here starting today! And don't forget next time!",
	touch2 = "Huh? Are you having dirty thoughts right now?",
	mission = "Oh geez, so many missions... I'll help you with them so we have more time to play later! Let's go!",
	vote = "",
	drop_descrip = "Iron Blood Type VIIC submarine – U-1206",
	feeling4 = "Remember how you said we'd do something together next time you're free? You don't? Hrmph... You definitely did, though! Whatever, we're doing it now! We're going surfing!",
	lose = "Oh fudge! I'm gonna push the emergency resurface button! They're not watching me, are they?!",
	feeling1 = "You'll have to become a saint if you want my forgiveness! To start with... Lemme think... Okay, first of all, you've gotta get on everyone's good side.",
	skill = "Fire torpedoes! ...Oops, wrong button! There!",
	upgrade = "My intuition just got keener!",
	propose = "Hehehe~ I'm so happy right now I can't even think straight! I could just fall right into your arms! You make me feel like the happiest girl in the world! Hehehehe~",
	feeling5 = "Commander, would you mind if we did... everything together? You know, working, eating, swimming, napping... Everything! Please? ...Wahoo!",
	main = "Can I push this button? ...No? What about this one? Also no? Laaame...|Oh, someone's at the door! Hello? Who is it? ...Huh? There's nobody here? Maybe I was just hearing things...|Your documents are printed and good to go! ...The cover and back are swapped around? Oops, uh... I'll go look for the manual...",
	touch = "Out of things to do, Commander? Then it's time to have fun with me!",
	voice_key_2 = -1,
	mission_complete = "I heard you finished a mission! That means more time for us to hang out, right? Hehehe~",
	battle = "Now's my time to shine!",
	id = 408120,
	gift_dislike = "",
	gift_prefer = "Whoa! This looks really fun!",
	profile = "You've heard about Iron Blood's wolfpacks, right? Guess what: I'm a wolf, too! Or I was, until the day I had a little accident... Wait, no, forget I even said that! I'm still a deadly predator! Keep your expectations high for me!",
	voice_key = 40812,
	headtouch = "There's no button on my forehead, so stop that!",
	feeling2 = "I don't understand this instruction manual! But that's okay, I'll just go with my gut until I figure it out!",
	login = "Hi, Commander! What are we doing today? I'm fired up and ready to do some work!",
	detail = "The manual for this industrial-grade AC says... Hmm. Let's just skip to pushing this big red button... Oh no, what's happening?! How do I turn it off?!",
	couple_encourage = {
		{
			{
				40801,
				40802,
				40803,
				40804,
				40805,
				40806,
				40807,
				40808,
				40809,
				40810,
				40811
			},
			2,
			"The wolfpack rides into battle on their riggings!",
			0
		}
	}
}


