_G.pg.base.ship_skin_words[408130] = {
	hp_warning = "Oookay, this is getting dodgy...",
	feeling3 = "You don't know what this is? It's able to capture any and all sound in your quarters and your office. It's essential to ensuring your safety!",
	mail = "Check complete. Your letter is perfectly safe! Buuut, I had to confiscate a few ones that came in suspicious pink envelopes♪",
	expedition = "Oh, the commission team is back. Let's head out and meet them together! That way you can do your thing, and I can keep you in my sight.",
	win_mvp = "Woe is me for being so dang strong!",
	home = "Welcome back. You sit over there and I'll go lock the door! Hm? Why lock the door? It's to keep you safe, duh!",
	unlock = "Ahah! You must be that \"Commander,\" right? I felt all fidgety inside the moment I saw you. You and I are gonna be SUCH close friends♡",
	touch2 = "You best not be thinking anything rude like, \"I wish they were bigger\"!",
	mission = "Oh, Commander, you've got unfinished missions. Before you ask – of course I'll help!",
	vote = "拉票描述",
	drop_descrip = "Type VIIA submarine – U-31.",
	feeling4 = "Y'know, I picked up you saying some weird things in your sleep. Wanna know what? Give me a nice hug and I'll tell you♪",
	lose = "H-hey! Didn't they use weapons that're against the rules?!",
	feeling1 = "I feel like taking a leave from being your personal bodyguard.",
	skill = "Sink to the bottom of the sea!",
	upgrade = "I've gotten even stronger! And I couldn't have done it without your guidance.",
	propose = "The time is finally here. I've been holding myself back for so long! Heehee. I've been pondering ways to pop the question, only for you to get to the finish line first! Gosh, I'm so happy I can't think straight. You'll just have to take the lead and do as you please♡",
	feeling5 = "I've got plenty of strengths as it stands, but maaaybe I could stand to be a little more mature. You don't think so? Ahah! I see, I see. I'm in your strike zone, is what you're saying. I knew you had an eye for quality, Commander♪",
	main = "Yup, there're shifty girls trying to approach you alright. But that's no biggie. I'll keep my eyes on you and make sure nobody pulls anything on you!|Hold it, Commander! Stay right there! *sniff sniff*... Hmm. You've got a smell on you – but whose? Ahah! It's just mine!|For a while now, I've been feeling lazy during the day but then full of energy come nighttime. I should pick up the night shift... and keep you safe from right by your bedside♪",
	touch = "Is this a sign, asking for your daily security check?",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Want a reward? Or would you rather have me?",
	battle = "Heheh! You're getting no mercy from me!",
	id = 408130,
	gift_dislike = "",
	gift_prefer = "Ooh! You mean I can really have this? Hooray! I'll give you a special reward tonight~",
	profile = "Name's U-31. I'm an Iron Blood VIIA-type submarine. Fighting and ensuring your safety are my middle names! Let me be your personal bodyguard for now. I'll keep any shifty girls at arm's length from you!",
	voice_key = 40813,
	headtouch = "Heeey, you can't be content with JUST a headpat. You wanna go further, don'tcha?",
	feeling2 = "What kind of hair do you like? Twin ponytails? Straight and long? Or maybe side ponytails like mine are your favorite?",
	login = "Hey, you're here! Hold still for a sec. I'm gonna give you a smell check, then a patdown... Alright, looks like nobody's wiretapped you.",
	detail = "It's time for your security check! You can never be too sure when it comes to these things. Hold still, now. I'm gonna give you a full-body search!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[408131] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "This is a cozy little spot. You oughta come lie down if you're feeling tired. There's no rush for us to get home, y'know.",
	unlock = "Why I didn't leave after classes were over? 'Cause I wanted to wait for you to come pick me up, duh! And I waited a looong time! Heehee, now that we're alone... maybe we could do something fun together!",
	touch2 = "Do you like the way I look?",
	mission = "",
	vote = "拉票描述",
	drop_descrip = "Why I didn't leave after classes were over? 'Cause I wanted to wait for you to come pick me up, duh! And I waited a looong time! Heehee, now that we're alone... maybe we could do something fun together!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "It's not easy, chasing off naughty girls who wanna mess with you while also attending classes every day. I wanna stay here and relax for a bit before we head home. You don't mind, do you? Think of it as a reward for my hard work!",
	main = "Ahah! You look like you're about to pass out! Want some candy to wake you up? Right in your mouth, like... this! Pretty sweet, huh?|Man, it's kinda hot in here. I suppose they do they turn off the AC after classes are over... Anyhoo, it's just you and me now – you don't HAVE to keep your coat on, just so you know.|Try and guess what flavor this candy is. Get it right, and I might give you a \"treat.\" Ahah! Don't act like you don't know what I mean by \"treat.\"",
	touch = "Mgh... Want me to shift over a bit?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 408131,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Mmh! Heehee. Keep going if you wanna.",
	feeling2 = "",
	login = "Maaan, you know how to keep a girl waiting! Make it up to me by fanning me. I wanna cool off a bit.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[408140] = {
	hp_warning = "Dammit... Let my guard down... but I'm still in the game!",
	feeling3 = "I recently realized that I get less time to unwind after working with you... What's weird is it makes me tired, but I'm fine with it. Pretty novel feeling for me. I'll have to read up about this!",
	mail = "Commander, new letter's here. I'm only gonna notify you about this once since it's such a chore.",
	expedition = "Commander, a commission's done. I'll hold the fort while you go and collect the stuff.",
	win_mvp = "Heh! Did you see that? My fighting skills are outta this world.",
	home = "Mission complete. Just in the nick of time. 'Kay, so, let's go find a sunny place and have a little break.",
	unlock = "*yawn*... Guess it's work day again. Or maybe you and I can skip work together. Either way, gimme your orders.",
	touch2 = "C-Commander?! Don't do that while I'm resting!",
	mission = "Yo, Commander, you've got a boatload of unfinished missions. It's a lot of effort, I know, but someone's gotta do 'em before things get real bad.",
	vote = "",
	drop_descrip = "Type VIIC submarine – U-552.",
	feeling4 = "Here, I made you some hot chocolate... Hm? Tastes sweet? Yeah, I added some syrup I've been reading about... Ah, never mind the deets! I just took some measures to efficiently replenish your energy 'cause you looked drained.",
	lose = "Hmm. Can't afford to get too sloppy, eh. I'll take it a little more seriously next time. Dealing with the aftermath sucks, and I'd hate to make you do that, Commander.",
	feeling1 = "Ugh... So tiring. Seriously, working with you is exhausting. Since I don't even get basic time to kick back, I'm gonna have to reconsider this job.",
	skill = "This is how you fight in power-saving mode!",
	upgrade = "Hmm. Feels like I'm lighter on my feet.",
	propose = "Hm? Wedding? Man, formal occasions are such a chore... Eh, it's a vow shared with you, so I'll take it seriously. Let me be with you, now and forever.",
	feeling5 = "I thought being in love would take too much time and effort to be worth it. With you, though, I don't think that at all. If anything, I naturally feel like giving even more to you.",
	main = "Commander, your office couch is placed perfectly for me to take a nap in the warm sunlight. Mind if I borrow it? It won't interfere with your work, promise!|Check out this best desserts list I just found. This pudding looks like the perfect thing for recharging my batteries. Will you buy some for me? In exchange, I'll do some good work... for five minutes.|Your working efficiency still stands to be improved. I mean, look, you could change your schedule to this and free up an hour for rest. A healthy work ethic ensures long-term combat ability, you know?",
	touch = "Hey, I'm in a comfy spot here, so don't ruin it for me.",
	voice_key_2 = -1,
	mission_complete = "Not in a rush to collect those mission rewards, huh? Looks like we're both the laid-back type.",
	battle = "Wait, I'm the flagship? I don't like the responsibility, so let's get this over with!",
	id = 408140,
	gift_dislike = "",
	gift_prefer = "Hm? You bought this just for me? Wow... You remembered just what I like.",
	profile = "I was part of all kinds of operations, and that busy bee lifestyle just wasn't for me. That's why I'll be taking things at my own speed at this port. I'm gonna rest when I want to and wrap things up quickly when I gotta fight. The perfect, comfy rhythm of life!",
	voice_key = 40814,
	headtouch = "Mmh... Your hand is so nice and warm.",
	feeling2 = "You've got an interesting work ethic, Commander. Could be more efficient, but hey. Teaching you my energy-saving method would be too much work, so it's fine the way things are now.",
	login = "Whew. Nice work. Man, I really gotta find a cozier place to lie down than the bottom of the sea. Mmgh...",
	detail = "Whenever you wanna raise efficiency or save energy, I'm your girl. I can even teach you my tricks to recharge your batteries in a flash.",
	couple_encourage = {
		{
			{
				40810
			},
			1,
			"I wanna get this done quickly so we can take it easy!",
			0
		},
		{
			{
				40801,
				40802,
				40803,
				40804,
				40805,
				40806,
				40807,
				40808,
				40809,
				40810,
				40811
			},
			2,
			"Heh! The wolfpack comes when you least expect it!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[408141] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Dear passenger, the latest edition of Tourist's Digest is here. I've sorted it for you, putting the most important destination info at the very top.",
	expedition = "",
	win_mvp = "",
	home = "It's finally over... Having to act like this is so exhausting. I guess it's not so bad if you think of this like a special date between you and me. I still want a more laid-back role next time, though.",
	unlock = "Ahem... Excuse me, since you've come aboard on our special sightseeing tour, please do try to keep up with me. Rest assured, this bus is perfectly safe and I can promise you a good time.",
	touch2 = "C-Commander! You can't do that now! ...Hey, cut it out!",
	mission = "Pardon me, but you can't put your feet up yet. You still have missions to be focusing on, no?",
	vote = "",
	drop_descrip = "Ahem... Excuse me, since you've come aboard on our special sightseeing tour, please do try to keep up with me. Rest assured, this bus is perfectly safe and I can promise you a good time.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I may not look it, but I'm overjoyed to be in the same play as you. Although, playing a secret agent pretending to be a tour guide... Ugh. It's so much work. At least you're covering for me, so all my hard work feels worth it. Hey, what do you say we... go on a real date next time?",
	main = "This uniform sucks... Just gotta bear with it so I don't get found out. Hey, do you think I look like a proper tour guide?|The next stop is... Psst, I'll take you to that secret base before they catch on to us. But first, want some sweets?|Are you still thinking about the script? Hmm... You could add a scene with some chemistry between the tour guide and the customer. I think it'll make the \"trip\" more natural.",
	touch = "Mmh... This uniform doesn't fit right... Dear passenger, this is not the time or place for this!",
	voice_key_2 = -1,
	mission_complete = "Oh, you finished a mission? Great, but my mission's still ongoing.",
	battle = "",
	id = 408141,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Ahem. Pardon me, I'm supposed to be working right now...",
	feeling2 = "",
	login = "Hello and welcome aboard our sightseeing bus. Today, we'll be... Ugh. I've had enough. No one's here yet anyway, so can't we just keep it real? This \"trip\" is gonna get interesting soon.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[408150] = {
	hp_warning = "Oww... I got hurt...",
	feeling3 = "Sometimes... I hear whale song... It's such a rare thing, but none of it compares to your voice, Commander... I must record more... [o(*//▿//*)q]",
	mail = "I canceled out all that extra noise, Commander... [Time to check your mail! >w<]",
	expedition = "The sound of the homecoming horn... Should I go with you to record your reunion?",
	win_mvp = "Do you... like the sounds of victory?",
	home = "Good work today, Commander... I recorded something while I was waiting. [The sound of the waves! >w<]",
	unlock = "Commander... I'm U-2501. I'm recording the audio of our first meeting... to be an important part of my collection. Here's a note for you... [I'm really happy to meet you, Commander! >w<]",
	touch2 = "Nnh... It's going to capture my voice, too... [Recording permissions not unlocked yet! o(*//▿//*)q]",
	mission = "Mm... Missions... [Hurry! ☆(>o<)]",
	vote = "",
	drop_descrip = "XXI-class submarine – U-2501.",
	feeling4 = "Commander, this track is corrupted... Twenty-four seconds of it are blank now. When I can't hear your voice, time feels ever so slow... [っ ̯ -。]",
	lose = "Bawww... [っ ̯ -。]",
	feeling1 = "U-umm... I prefer to be alone... [<(_ _)>]",
	skill = "Noise... canceled!",
	upgrade = "My audio library grows... [>w<]",
	propose = "Yes... [I do!] From now on, even the shared silence between us... will be all mine. Nobody can ever erase it... It'll be safe forever.",
	feeling5 = "Listen... Your greetings, idle chatter, commands, and even your heartbeat and breathing... All of my world is filled entirely with you... [o(*//▿//*)q]",
	main = "Commander, I heard you yawn just now... Did you not sleep well last night? If so, umm... [Can I sleep with you? o(*//▿//*)q]|Commander, what sounds will you make for me today...? [>w<]|Do you like this melody? Then stay here... and listen to my song.|Am I recording? Yeah, I am... I got the sound of you breathing... [(o°▿°)o]",
	touch = "Mmm... My heart is pounding... [o(*//▿//*)q]",
	voice_key_2 = -1,
	mission_complete = "Rewards... What do you want, Commander? [A day with me, maybe?! >w<]",
	battle = "Silence spreads...",
	id = 408150,
	gift_dislike = "",
	gift_prefer = "Thank you... [I looove it! >w<]",
	profile = "I'm known as U-2501, Iron Blood's blade of the deep... I was born to bring new tactics to life. Let me dedicate all that I am... to you.",
	voice_key = 40815,
	headtouch = "Mm... More... Mooore... [o(*//▿//*)q]",
	feeling2 = "Commander... Talk more, please? [Voice capture progress: 25%! >w<]",
	login = "I'm happy... to see you again. Oh. Here's a note... [Can I record the sound of you breathing, please? >w<]",
	detail = "My audio library has all of the sounds I've collected... and some of my own. You can listen any time you want... [I recorded them just for you~ o(*//▿//*)q]",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[408151] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "I hear the sounds of the sea, sun, and wind coming from you... Come closer and let me help you get changed... [☆(>o<)]",
	unlock = "Commander, I'm changing clothes... You don't have to look away. Open up the curtain of water, and I'm right here... [o(*//▿//*)q]",
