	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "This curtain of water may blur the scenery... but it makes sounds even clearer for me... Close your eyes, open your ears. Listen to the sound of the water parting... and my heart beating just for you... [o(*//▿//*)q]",
	main = "Hush. The sound of the water... and your stifled breathing... I've got it now.|Commander... Treasures don't normally surface on their own, but this time, I'll make an exception for you... [o(*//▿//*)q]|The water is chilly, but your hands are warm... Hold me. [Hold me suuuper tight! >w<]|Commander, are you more focused on the water curtain... or the sound of my heart? [o(*//▿//*)q]",
	touch = "Did I not put this on right...? [☆(>o<)]",
	voice_key_2 = -1,
	mission_complete = "You can claim your rewards... however you like, Commander... [o(*//▿//*)q]",
	battle = "",
	id = 408151,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Since you're here... I won't have to worry about my hair getting caught while I change clothes... [>w<]",
	feeling2 = "",
	login = "Hum hum♪... Hmm? Commander... Would you like to listen to the water with me?",
	detail = "",
	couple_encourage = {}
