_G.pg.base.ship_skin_words[431233] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Look how many invitations you've gotten, Commander. Aren't you popular? Hehehe.",
	expedition = "Why don't we check on the status of our commissions before the dance?",
	win_mvp = "An invitation to dance? ...Sure, I'd be glad to! Heehee~♪",
	home = "We still have time before the dance. Let's take it easy and relax for a while, Commander.",
	unlock = "Sure, I've worn black dresses in the past, but this time I decided to incorporate a bit of red and white, per Eugen's suggestion. This is sure to invite the Commander to dance wi– C-Commander?! Did you just get here? I see. Uhh... How do you like my dress?",
	touch2 = "Th-this isn't something that a tactful person would do.",
	mission = "Just for today, Commander, I don't mind you putting off your missions for a while.",
	vote = "",
	drop_descrip = "Sure, I've worn black dresses in the past, but this time I decided to incorporate a bit of red and white, per Eugen's suggestion. This is sure to invite the Commander to dance wi– C-Commander?! Did you just get here? I see. Uhh... How do you like my dress?",
	feeling4 = "",
	lose = "Looks like I wasn't prepared enough... Aww...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Everyone's out there livening up the party. It's a little weird to read or work all alone, don't you think...?|Is Javelin doing okay? During our last rehearsal together—Oh, I'm so worried. I'm gonna practice a little more!|Dancing isn't something you can learn to do just from reading a book. You have to experience it yourself, and prepare for any problems that might arise. That's right– I've done everything I needed to in advance, and am ready for your invitation at any moment.",
	touch = "Commander, would you like something to drink?",
	voice_key_2 = -1,
	mission_complete = "This is... exactly what I'd expect from my Commander.",
	battle = "",
	id = 431233,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Commander... Do you realize how hard it is to style my hair like this?",
	feeling2 = "",
	login = "It's almost time for the dance to start. Commander, are you ready? Leave it all to me today.",
	detail = "Dress, ready. Hair, done. Accessories... all set. Hmm? I should be more relaxed? That won't do, Commander. If we're going to be dance partners, everything must be in perfect order!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[431234] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "See? I told you I could write well!",
	home = "Welcome back, Commander! Hm? You want to see my writing? G-give me a little longer! I'll get the hang of it soon!",
	unlock = "Oh, Commander? Do you want to practice calligraphy with me? ...You think it looks more like drawing than writing? G-geez!",
	touch2 = "You're gonna show me how to use a brush? W-wait... Where do you think you're putting that thing?!",
	mission = "I can practice just fine on my own. Don't you think you should pay more attention to your unfinished tasks?",
	vote = "",
	drop_descrip = "Oh, Commander? Do you want to practice calligraphy with me? ...You think it looks more like drawing than writing? G-geez!",
	feeling4 = "",
	lose = "Ugh, this is hard... Maybe I should go back to the beginner's books.",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Huh? You think I'm cute when I'm practicing calligraphy...? Geez... The important part is what I'm writing, not me!|Neat handwriting is essential... Want to join me, Commander? I'll grind up more ink, so sit down right here for me.|The Emperians taught me that, if you can be calm and focused, the brush will naturally paint the image in your mind... Ah, dang it! Why did I draw you?!",
	touch = "Oh, did I get this part wrong? Urgh... This is harder than I thought it would be.",
	voice_key_2 = -1,
	mission_complete = "You finished your work? Umm... I'm almost done, too! I think.",
	battle = "",
	id = 431234,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Are you trying to comfort me? I-I'm fine! I'll have this mastered in no time!",
	feeling2 = "",
	login = "Commander, I was just... Ahem! Getting used to using a brush, that's all! Now I'm getting serious!",
	detail = "My outfit? Javelin and the others picked it out for me. They said it would help me stay calm... Did I look more focused than usual just now? Y-you mean it?!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[501010] = {
	hp_warning = "Commander, concentrate and be extra careful!",
	feeling3 = "Even if the day comes when I am no longer needed on the battlefield, I still want to watch over the Bohai Sea. I want to always be able to see the waters, dyed a shimmering vermillion in the sunset.",
	mail = "Commander, you have new mail. Should I unseal it for you?",
	expedition = "Great, everyone returned home safely!",
	win_mvp = "Commander, being able to help you out is the greatest!",
	home = "Why don't you take a break? It's not good to be too stressed out.",
	unlock = "Destroyer, An Shan, reporting for duty! I shall protect my sisters and you, Commander!",
	touch2 = "Hey-! My sisters are going to see us...",
	mission = "Protecting the peace isn't just about fighting - you'll have to do these missions too.",
	vote = "",
	drop_descrip = "An Shan-class destroyer, No. 1 - Anshan (101)",
	feeling4 = "Commander, rest assured that wherever you go, I will be there to protect you. Huh? Isn't it obvious, you're mine after all...",
	lose = "Everyone, regroup. We can't retreat like this!",
	feeling1 = "Commander, it's bloomring season for the hawthorne I grew around the Bohai Gulf. Can we go back and take a look?",
	skill = "Let the protection of heaven surround the brave!",
	upgrade = "Now I'll be better equipped to deal with ruffians like De Haven...",
	propose = "Commander, my body and soul, all of my life, belongs to you from now on. Make sure to take responsibility properly.",
	feeling5 = "I'm so blessed to have met you, Commander. I've made so many friends and so many memories... Hey, Commander, once I complete my duty as one of the \"Four Unbreakables,\" let's go travel around the world together!",
	main = "Woah, this is my first time seeing a battleship! |Where did Fu Shun run off to? Would it really kill her to do as I say every now and then? |My sisters - Fu Shun, Chang Chun, and Tai Yuan - are all my pride and joy!",
	touch = "Commander... Hehe~ doing this occasionally is not all that bad.",
	voice_key_2 = -1,
	mission_complete = "Keep up the effort, don't slack off just yet!",
	battle = "What are you all fighting for?",
	id = 501010,
	gift_dislike = "",
	gift_prefer = "Thank you, Commander. I wanted something just like this.",
	profile = "I am the nameship of the An Shan-class destroyers, and one of the Dragon Empery's first-generation \"Four Unbreakables.\" As the flagship, I participated in many naval exercises, carried out surveillance, and engaged in confrontations, leaving behind lasting achievements that I can be proud of. Though I never participated in live combat, I am the destroyer with the most miles under her belt in the entire world!",
	voice_key = 50101,
	headtouch = "",
	feeling2 = "Commander, we have to fight to protect the things we care about. This isn't really a question of personal preference.",
	login = "Wow! Today's schedule looks packed. Let's work hard today!",
	detail = "Commander, what would you like to know?",
	couple_encourage = {
		{
			{
				50102
			},
			1,
			"Stop running around, and stay by my side!",
			0
		},
		{
			{
				50103
			},
			1,
			"Remember, you can never be too careful on the battlefield.",
			0
		},
		{
			{
				50104
			},
			1,
			"Let's see those guts! Great! Just like that!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[501012] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Who's over there? ...Oh, it's the commission fleet! They're back!",
	win_mvp = "Seize victory from the evening's light!",
	home = "",
	unlock = "\"Boundless is the beauty of evening's glow, but alas––\" ...Oh, that doesn't have any special meaning, I've just been hanging around Hai Tien too much. (*whispers*) But, it's true... Our time together is far too short, just like the evening light...",
	touch2 = "The sunset sure is beautiful, huh? Ahaha~",
	mission = "",
	vote = "",
	drop_descrip = "\"Boundless is the beauty of evening's glow, but alas––\" ...Oh, that doesn't have any special meaning, I've just been hanging around Hai Tien too much. (*whispers*) But, it's true... Our time together is far too short, just like the evening light...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "I wonder how my sisters are doing... Oh, right... I've got to set that stuff aside when I'm with you.|Commander, are you awake? Hehe, you look just like Gremyashchy when you're sleeping~♪|Are you done with your drink already? Well, you can have some of mine– Wait, oh... Um, don't worry about it though! I'd hate for you to go thirsty! ...S-seriously, I don't mind...",
