	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "There's a lot of work to get through today, but it's nothing the two of us together can't handle!",
	detail = "You want to know more about the four of us, huh? Fu Shun's a bit of a daredevil, Chang Chun has too many \"great ideas,\" and Tai Yuan should really put herself out there a bit more. ...Hm? Me? Well... What do you think about me? Hehe~",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[501020] = {
	hp_warning = "Tsk... Looks like I'll have to show them my final form!",
	feeling3 = "*slaps rocket* Commander, this bad boy will take you all the way over the sky. Isn't it a beaut? I made it myself. Coming down? Don't worry about that, Chang Chun and I will be there to catch you. ",
	mail = "It doesn't look important, so I won't bother Commander.",
	expedition = "All the stuff that I wanted? I brought them back with me. Uhh, this doesn't count as smuggling, right?",
	win_mvp = "Hehe~ this isn't even my final form!",
	home = "Well then, let's continue investigating the mysteries of the port~ Chang Chun, you coming?",
	unlock = "Destroyer Fu Shun, reporting in! Uhh... where's Chang Chun? She was clearly behind me just a minute ago...",
	touch2 = "Woah! Commander, are you frisking me? I'm not hiding anything!",
	mission = "Go forth and complete those quests!",
	vote = "",
	drop_descrip = "An Shan-class destroyer No.2 - Fu Shun (102)",
	feeling4 = "Commander, good morning! Ehh, what was I doing last night? Why are you asking me? I didn't do anything bad! Your office looks like a werewolf got loose in it? No, no, it wasn't me. It was probably, uh, a werewolf!",
	lose = "Ugh... Sis'... where are you?",
	feeling1 = "Yikes! Chang Chun, Tai Yuan, Commander is coming!",
	skill = "Let the flames of heaven dazzle all in our way!",
	upgrade = "My power level can keep going up!",
	propose = "Commander, so we're a family now... Well then, can I borrow the keys to the warehouse? I'm begging you! Just for one day!",
	feeling5 = "My secret base lies right over yonder. Pretty, huh? This is my most important secret! Eh? I just happened to tell you on a whim! I definitely wasn't planning anything.",
	main = "If I give this to Tai Yuan, I'm sure she will be very happy! |A ghost ship that emerges from the frozen waters of the Arctic at midnight? Certainly, I've heard this rumor before. |Although Chang Chun is my younger sister, she has taught me a lot!",
	touch = "Woah! Um... I just happened to be, uh, scratching my back! Yeah, I'm definitely not hiding anything!",
	voice_key_2 = -1,
	mission_complete = "Quest complete! There's a black smoke coming from the port? Are you sure, Commander? I don't see anything~",
	battle = "Sis', it's not a drill this time!",
	id = 501020,
	gift_dislike = "",
	gift_prefer = "Hahaha! Imagine the things I could do with this!",
	profile = "The name's Fu Shun, second ship of the An Shan-class destroyers and one of the first-generation \"Four Unbreakables.\" Rezkiy? That was my birth name. Even though I accomplished a lot, I unfortunately never experienced actual combat. The closest I got was that one time, when An Shan and I almost opened fire! Anyway, please let me fight to my heart's content on the battlefield!",
	voice_key = 50102,
	headtouch = "",
	feeling2 = "What's up, Commander? No no, I didn't break anything... Eh, all the windows in the academy broke? Uh... I think it's the doing of one of those evil spirits... probably?",
	login = "Today's Fu Shun is all fired up and ready to go!",
	detail = "Commander, if there's something you want to find out, I'd be glad to investigate with you~",
	couple_encourage = {
		{
			{
				50101
			},
			1,
			"I have nothing to fear as long as my big sister is here!",
			0
		},
		{
			{
				50104
			},
			1,
			"Tai Yuan, did you manage to learn it?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[501021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Looks like there was some all-purpose flour included in the rewards... Are the girls planning to make baozi skins from scratch?",
	win_mvp = "",
	home = "Shh! An Shan is coming this way... If she finds out, it's game over for us!",
	unlock = "Heh-hey! Just hooked us another baozi~! We're in for one heckuva haul today! ...Eh? Huh, Commander?! Th-this is, uhh... yeah, we're just playing a normal game... totally...",
	touch2 = "Wh-whooooa! If we fall off, our cover's gonna get blown!",
	mission = "",
	vote = "",
	drop_descrip = "Heh-hey! Just hooked us another baozi~! We're in for one heckuva haul today! ...Eh? Huh, Commander?! Th-this is, uhh... yeah, we're just playing a normal game... totally...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "How am I going to get down from here? Please, these heights are nothing! Oh, actually, umm... Commander, I might need some help from you after we're all done here after all...|Chang Chun shot me a glance just now... It's fine; given her personality, no chance she sells us out!|Hahaha! Commander, this baozi is for you! Enjoy the taste of the spoils of victory! ...Huh? It's super spicy? How could that be? The one I grabbed isn't spicy at all...",
	touch = "Wanna give it a try, Commander? Nothing's more fun than successfully pulling off a prank!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Nobody will care if we make a ruckus beating up on the enemy, right?",
	id = 501021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Happy New Year, Commander! Wait, hold on a minute! How did you get up here without a ladder?!",
	detail = "\"Mysteries of the Port – Case of the Disappearing Baozi!\" ...How did rumors like that start circulating already?! Well done! ...I, I'll explain things to everyone later!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[501029] = {
	hp_warning = "Hmph! It'll take more than that to beat me!",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Heheh! I return to you with victory in hand, Commander!",
	home = "Good timing, Commander! Now the port's whole mystery-solving gang has gathered!",
	unlock = "Fu Shun – retrofitting complete! Reporting in! Commander, if something happens and you need someone reliable, I'm your girl!",
	touch2 = "Heeey! I told you I'm not hiding anything! There's a limit to how careful you should be!",
	mission = "",
	vote = "",
	drop_descrip = "Fu Shun – retrofitting complete! Reporting in! Commander, if something happens and you need someone reliable, I'm your girl!",
	feeling4 = "",
	lose = "Nooo! They beat us, Commander! I'll get 'em next time, I swear!",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Commandeeer! Commander! I renovated my secret base! I even had a table and chairs custom-made for you! Come on, sit down! ...My secret base looks an awful lot like your office? Heheheh... That's good ghost story material right there! I dig it!",
	main = "I heard they found the footprints of some kind of cryptid! I'm gonna go see what they– Hey, what are you doing? You didn't just notify An Shan, did you?!|Heheh! With access to this much firepower, solving even the biggest mysteries will be a breeze!|An Shan, Chang Chun, Tai Yuan, and you, my most treasured commander – I will protect you all!",
	touch = "My outfit's changed a lot, don't you think? If I had to sum it up, I'd say it's gotten easier to adventure in!",
	voice_key_2 = -1,
	mission_complete = "Mission complete! ...Huh? You just heard an explosion? ...Th-that was probably your fault!",
	battle = "Sic 'em all!",
	id = 501029,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Bet you think I've gotten stronger, too! Heehee!",
	feeling2 = "",
	login = "Commander, tell me what my tasks are for today! I'll get 'em done in a jiffy then head out on an adventure!",
	detail = "Check it out! My new rigging looks sooo overpowered, doesn't it? Yeah, I agree!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[501030] = {
	hp_warning = "Now things are getting interesting~",
	feeling3 = "Hey Commander, how'd you get in here? Secret base? Ehehe~ I have no idea what you're talking about~ Oh, by the way, have you seen my snacks? W-wait, you can't eat that!",
	mail = "New mail, huh? Seems like the perfect thickness to stick under this wobbly table.",
	expedition = "Commisson complete! Looks like someone has snacks for me!",
	win_mvp = "Clear skies and calm waters today as well~",
	home = "I'll help give everyone a massage! Pain, pain, fly away~",
	unlock = "Destroyer Chang Chun has arrived~ No, I'm not afraid of the cold~ I just like being warm and cozy~",
	touch2 = "Commander, is this the type of person that you are?",
	mission = "Missions... are also very important.",
	vote = "",
	drop_descrip = "An Shan-class destroyer No. 3 - Chang Chun (103)",
	feeling4 = "Commander, the beach behind the academy is perfect for swimming. Uh, I wasn't making plans or anything! I was just playing around with my binoculars when I saw the swim ring that Commander had bought, ehehe~",
	lose = "Wow, I think I goofed up~",
	feeling1 = "Commander... that's unacceptable...",
	skill = "Let the seven heavenly mansions align for the coming of the white tiger!",
	upgrade = "When do I get missiles?",
	propose = "If you never leave my side, I can consider your request~ Just kidding! Your gullibility is a good thing though~",
	feeling5 = "You want me to take off my cosplay? Ehehe~ I suppose I can, but you'll have to do what I say!",
	main = "The four of us are authentic noblewomen, you know~ |During the summer, Tai Yuan will make a breezier version for me, so there's no problem. |Fu Shun, I heard that terrifying monsters appear in the academy after the sun goes down.",
	touch = "Commander, if you like this outfit, I'll ask Tai Yuan to make a set for you as well.",
	voice_key_2 = -1,
	mission_complete = "Next up is... Ehh? What's that burning smell coming from the warehouse? Ah, my snack...",
	battle = "Why must we... fight each other?",
	id = 501030,
	gift_dislike = "",
	gift_prefer = "You're cute, Commander~",
	profile = "I am Chang Chun, the third ship of the Dragon Empery's An Shan-class destroyers, and one of the \"Four Unbreakables.\" As one of the pillars of the Empery's navy, I played a pivotal role in the training of personnel. Eh? Fu Shun is getting into trouble again? An Shan is going to be worried...",
	voice_key = 50103,
	headtouch = "",
	feeling2 = "I heard that Prince Rupert's drops can be used to ward off the evil monsters that come out at night, so I told Fu Shun. The windows at the academy are gone? I-I have no idea what you're talking about~",
	login = "Good morning, Commander~ Ehehe, looks like it's not even morning anymore though~",
	detail = "I definitely am not hiding the stuff that Fu Shun secretly bought.",
	couple_encourage = {
		{
			{
				50101
			},
			1,
			"Understood, I'll intercept the enemy with everything I have!",
			0
		},
		{
			{
				50104
			},
			1,
			"Don't just flail around, if you get scared, just hide behind your big sis!",
			0
		}
	}
}


