_G.pg.base.ship_skin_words[501032] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Did we get new mail? Looks like a New Year's postcard came in too. Let's check it out, Commander!",
	expedition = "Has the commission team returned? Want me to bring some baozi over to them? Oh right, I'll let you in to a little secret – I know how to tell between the regular kind and the super-spicy kind~",
	win_mvp = "",
	home = "Hmm, we don't have very many of Fu Shun's super firecrackers left... Commander, got any interesting fireworks on you?",
	unlock = "Commander, hurry up and plug your ears! Th-this isn't a joke! Um... Seriously, that big ol' doozy over there is about to blow!",
	touch2 = "Eep! Cold! Stop bullying people, Commander!",
	mission = "Hmm? You still have work during Lunar New Year? ...In that case, I'll give you the same mission that An Shan gave me: \"Don't stay in your room through the entire holiday!\"",
	vote = "",
	drop_descrip = "Commander, hurry up and plug your ears! Th-this isn't a joke! Um... Seriously, that big ol' doozy over there is about to blow!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Fu Shun's always loved setting off firecrackers, but she wasn't there with that crowd this year. Heehee, do you want to know why, Commander?|Please continue to look after An Shan this year as well. Oh, right, should I give you a little \"assistance\" in that regard? Heehee~|Stremitelny's challenging me to a snowball fight? Hmm... I think I'll pass. Getting soaked in this outfit would be a huge pain in the butt...",
	touch = "Feels great when you floof these ears, right? Tai Yuan was the one who made these. I'm glad I have such a resourceful little sister~",
	voice_key_2 = -1,
	mission_complete = "All done with the mission? Then... wanna head back inside and chill?",
	battle = "",
	id = 501032,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, Happy New Year~! My next line is... got any red envelopes for me? Ehehe~",
	detail = "Today, I'm a bunny, not a tiger. When the time is right, I can pull these big floofy ears over to cover my own ears~ But of course, they'll pop right off if you tug too hard.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[501039] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Good job out there, Commander. Need me to do that \"pain, pain, fly away\" thing again?",
	unlock = "All done with my retrofit~ Now, time to test out my new toys... Err, I mean, time to test the firepower of my new armaments! Oh, watch your head, Commander! Wouldn't want one of the missiles to lock onto you.",
	touch2 = "Y'know, Commander... I always knew this was the kind of person you are...",
	mission = "",
	vote = "",
	drop_descrip = "All done with my retrofit~ Now, time to test out my new toys... Err, I mean, time to test the firepower of my new armaments! Oh, watch your head, Commander! Wouldn't want one of the missiles to lock onto you.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "Missiles, huh... I wonder if I'm stronger now.",
	propose = "",
	feeling5 = "",
	main = "Fu Shun, if An Shan finds out that you're making micromissiles, she's gonna be so pissed.|Hmm... It does feel rather breezy behind my head without my hood...|Missiles versus naval guns? Eh, there's no point comparing things from two different eras~",
	touch = "My gear's not the only thing different about me! I've got a new look too! Heh~",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 501039,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, y'know what they say about a day's plans starting in the morning, but that adage is probably true even if it isn't morning.",
	detail = "If we were to put this into video game terms... It's like I just got epic SSR gear! That's why you can count on me even more, Commander!",
	couple_encourage = {}
