_G.pg.base.ship_skin_words[501040] = {
	hp_warning = "Eh...? U-um... what should I do...",
	feeling3 = "Commander, other than my sisters, you're my first friend. S-so, um, whatever you do, please do not get inside Fu Shun's home-made missile!",
	mail = "C-commander, there's new mail. Perhaps Fu Shun should... um, never mind...",
	expedition = "Eek! Someone came back... Oh, An Shan, I'm fine...",
	win_mvp = "Um... is this good enough?",
	home = "I can finally settle down. W-wait... Fu Shun, where are you dragging me off to?",
	unlock = "I... I'm Tai Yuan, a destroyer. Commander, have you seen my sisters?",
	touch2 = "W-w-woah... C-commander, please don't do that...",
	mission = "This mission... looks quite difficult. Will we be able to do it?",
	vote = "",
	drop_descrip = "An Shan-class destroyer No. 4 - Tai Yuan (104)",
	feeling4 = "Commander, are you in here? Eh? I'm not just walking around.. Um, I just got a little lonely... and wanted to see your face...",
	lose = "Um... as expected, I still have a long way to go...",
	feeling1 = "An Shan, I... I'm a bit scared...",
	skill = "Let the heavens focus our minds, so we can adapt to any situation!",
	upgrade = "U-um... it's still a bit scary...",
	propose = "Thanks, Commander... Even though I'm still not very reliable, from now on, you can count on me!",
	feeling5 = "Commander... even though I'm immature, I will work harder. So, um... please wait for me... Y-you'll be waiting for me to surpass my sisters? Th-thank you!",
	main = "F-Frank Knox? I don't want to run into her again... |An Shan is so hardworking... When can I be of help to her? |What am I reading right now? \"Miscellaneous Morsels from Youyang.\" Chang Chun gave it to me...",
	touch = "Commander, what kind of books do you like to read?",
	voice_key_2 = -1,
	mission_complete = "D-does this mean I've matured a little?",
	battle = "L-live combat... I have to do my best...",
	id = 501040,
	gift_dislike = "",
	gift_prefer = "C-can I really have it?",
	profile = "Um... I'm Tai Yuan, fourth ship of the An Shan-class and a first-generation member of the Dragon Empery's \"Four Unbreakables.\" I originally was named \"Ji Lin.\" My sisters and I were the mainstay of the Empery's navy for decades, serving in many operations and helping rebuild the strength of the navy. The \"Nuclear Physics Hypothesis\" is a very interesting book... It would be nice if my sisters liked it too...",
	voice_key = 50104,
	headtouch = "",
	feeling2 = "Comm... Commander? Um, sorry, Chang Chun needs me for something right now!",
	login = "H-hey, Commander. I was too absorbed in reading that I lost track of the time...",
	detail = "Fu Shun just asked me to tell her about the Philadelphia Experiment. Commander, would you like me to tell you about it too?",
	couple_encourage = {
		{
			{
				50101
			},
			1,
			"To help An Shan, I have to do my best...",
			0
		},
		{
			{
				50102
			},
			1,
			"Fu Shun, you're charging up too fas- Ahh!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[501041] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Ah, Commander, welcome back... I'm making a lantern... Would you mind helping me hang it up?",
	unlock = "O-on behalf of the An Shan class, we wish a prosperous, happy, and healthy new year to Commander, and to everyone here at port... Umm... even though I made this outfit, I feel a bit embarrassed wearing it... Eh? It looks good on me? Um... th-thank you...",
	touch2 = "C-commander... if you keep messing around, someone's going to get mad!",
	mission = "",
	vote = "",
	drop_descrip = "O-on behalf of the An Shan class, we wish a prosperous, happy, and healthy new year to Commander, and to everyone here at port... Umm... even though I made this outfit, I feel a bit embarrassed wearing it... Eh? It looks good on me? Um... th-thank you...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "During the Spring Festival, relatives will all gather to celebrate a reunion. Th-this year, I'd like to have a reunion with my sisters and you, Commander... is that okay?",
	main = "F-Fu Shun, it... it's dangerous to take apart firecrackers like that... Eh? You're doing an experiment? |This year's couplet... Um, Commander, can you help me brainstorm ideas? |Chang Chun, it's a once-in-a-year occasion, it's not good to stay inside your room all day...",
	touch = "I made this outfit myself. My sisters all said it looks good, ehehe...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 501041,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Fu Shun gets really excited around the Spring Festival, and will even drag Chang Chun and me around...",
	detail = "Commander, did you know? The Dragon Empery has an ancient legend about the monster known as the \"Nian.\" During the Spring Festival, every household will hang up couplets and set off firecrackers to ward it off.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[501042] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Are you tired? If so, this is a good time to rest... U-umm, I think we might be a little too close...?",
	unlock = "Commander? Did Ting An tell you to try out this ergonomic cushion, too? Okay, I'll make room... There, okay! Come lie down with me!",
	touch2 = "Mmm... Hyah?! C-Commander, umm... Maybe not here...",
	mission = "",
	vote = "",
	drop_descrip = "Commander? Did Ting An tell you to try out this ergonomic cushion, too? Okay, I'll make room... There, okay! Come lie down with me!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "The closer we get... the louder my heart beats, and the hotter I feel... You think that's normal? O-okay... That's a relief.",
	main = "You can use this as a pillow or a cushion, so it's like two birds with one stone. Come and try it already!|Commander, I read this book called The World Inside a Pillow. It's about a pillow that gives you good dreams... You want to know more? Okay, I'll tell you all about it!|I made the pajamas and headband myself! Ah... You wanna get a closer look? O-okay! I'm just a little nervous, that's all...!",
	touch = "Yeah, it feels really good to hug it like this~ You should try it... Hwuh?! I-I don't think I'm as huggable as the cushion...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 501042,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "I'm still not sleepy. Let's chat for a little while!",
	feeling2 = "",
	login = "Zzzz... Hm? Commander... Ah, the bed and cushion are so soft that I fell right asleep...",
	detail = "Very comfy, very supportive, just the right size... Hmm, is this too casual for my report? What do you think, Commander?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[501049] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Mm. A victory well within my calculations.",
	home = "...Phew, you're back safe and sound. What a relief.",
	unlock = "Phew... Tai Yuan, retrofit complete. Thanks for supporting me this whole time, Commander. With this new equipment, I'll be able to get one step closer to catching up to my sisters.",
	touch2 = "Oh, wow... C-Commander, so this is what you were into after all...",
	mission = "",
	vote = "",
	drop_descrip = "Phew... Tai Yuan, retrofit complete. Thanks for supporting me this whole time, Commander. With this new equipment, I'll be able to get one step closer to catching up to my sisters.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "\"A job well-done begins with the proper tools.\" ––A good first step, if I must say so myself!",
	propose = "",
	feeling5 = "Now that I've some time to think things through, surpassing my sisters is only just the first step. Beyond that, the road ahead is incredibly long... Commander, will you walk with me to my next destination?",
	main = "I may have acquired new equipment, but that's actually given me more things to be mindful of... Hmm? That's part of what it means to be thoughtful and contemplative? Hmm... what an enlightening point of view.|As I am now, I surely have the power to fight alongside An Shan! My next goal is... Well, I'm still in the process of thinking about it!|The more you know, the more things you have to be worried about... Hmm? Only confident people have the self-awareness to harbor such doubts? Ehehe~ Thank you for the encouragement.",
	touch = "",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Allow me to demonstrate Xuanwu's true power!",
	id = 501049,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Good morning, Commander. I'm ready to resolve any crisis with you.",
	detail = "\"To tread Xuanwu's path is to be as tough as steel yet flexible as grass.\" ––Therefore, to truly be strong requires not only physical prowess, but also a keen intellect. Would you agree, Commander?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[501050] = {
	hp_warning = "Bweeeehhh! It's going to burn!!",
	feeling3 = "...You really enjoyed my cooking? Oh, uh, thank you very much... Well then, um, would you like to try some other stuff? I have Buddha's Temptation, cabbage in supreme soup, and–– Huh? It's too much effort? For the important task of serving you, is this not completely appropriate?",
	mail = "There's mail addressed to you, Commander. Don't forget to read it–– Hm, I wonder if we got any letters with recipes inside...",
	expedition = "The commission team is back, huh... I'll go prep a banquet. Everyone's gonna be able to eat to their heart's content.",
	win_mvp = "We won...? Phew... Now, I'll be able to head back and research new recipes...",
	home = "Welcome back, Commander... Umm, are you hungry? ...You are, but you don't know what to eat? Then, how about a full course of the Eight Great Cuisines?!",
	unlock = "The name's Lung Wu... Dragon Empery destroyer. Um... uhh... have you seen Hu Pen around? Also... which way is it to the kitchen?",
	touch2 = "...Steamed, stir-fried, deep-fried, or pressure cooked. Take your pick.",
	mission = "We've got new work. Are you sure you want to leave it for later? Can you just take care of it now? I'll have dim sum waiting for you when you're done.",
	vote = "",
	drop_descrip = "Vulcan Stettin 1,000-ton torpedo destroyer – Lung Wu.",
	feeling4 = "I can prepare any dish for you, seasoned any way you want it! I've always heard that cooking exists to bring joy to others, and I want to do my very best to make you happy!",
	lose = "Ugh... That was a bust... Was it because I wasn't able to adjust the heat properly?",
	feeling1 = "Commander... You have no appreciation for my cooking...",
	skill = "The quest for supreme flavor never ceases~",
	upgrade = "Did it work...? Mm, good... Oh! I've gotten even better at controlling the heat now!",
	propose = "Th-this is... Really?! G-give me a moment to get my thoughts straight... I mean, I can't do anything other than cook... *huff* *huff*... Alright, Commander... If you don't mind, I'll be in charge of all your meals from now on, and make sure everything is healthy and delicious!",
	feeling5 = "I've packed your lunch. Ehehe, you'll find a new surprise waiting for you. I made it just for you, based on your favorite ingredients and flavors–– It's super delicious? Phew, glad to hear that! Then, umm... would you mind if I made it for you every day~?",
	main = "...Me, go on a vacation outdoors? Ehh... I think I'll pass. Not really interested in that... What AM I interested in, you ask? Researching recipes, of course! Recently, I've come across a method of making red-braised pork belly even more delicious! Wanna give it a try, Commander?|Xiaolongbao with chocolate filling? Mapo tofu with strawberry jam?! ...Gaaaaah, I've had it! From now on, only people with business here are allowed inside the kitchen!|...You want to observe me while I cook? That's fine and all, but if you pull any funny business like Fu Shun... I'm being too strict? Nonsense! You're being too lax, Commander! The kitchen is a battlefield!",
	touch = "Feeling peckish? I have spring rolls right here. That ought to fill you up a little bit.",
	voice_key_2 = -1,
	mission_complete = "Mission rewards are in. Don't forget to pick 'em up. As for what's inside... we'll probably be able to buy all sorts of fancy, high-end ingredients~♪",
	battle = "Combat... calls for great firepower, just like cooking!",
	id = 501050,
	gift_dislike = "",
	gift_prefer = "Whoa! Is this for me? That's amazing!",
	profile = "Dragon Empery destroyer, Lung Wu. I'll pass on the fighting and paperwork stuff, but if you need anything food-related, just leave it to me! So, what's your favorite type of cooking? Grilling, frying, stir-frying, broiling, steaming? You name it, I'll cook it!",
	voice_key = 50105,
	headtouch = "H-how am I supposed to read the recipe like this...",
	feeling2 = "Hungry? I've prepared osmanthus cake, roast duck, crawfish, pan-fried bao, and... Hmm? Where'd I get all this food? Uhh... just business as usual for me, you know?",
	login = "...Uhh, welcome? You wanna see today's menu? Here you go! Just lemme know if anything catches your eye! Recommendations? Uhh, I have so many specialties, I'll have to think about that one...",
	detail = "Tips for stir-frying? You need high heat, and oil! That's how you get that rich, wok hei flavor!",
	couple_encourage = {
		{
			{
				50106
			},
			1,
			" Would it kill ya to stop trying to drag me outside...",
			0
		}
	}
}


_G.pg.base.ship_skin_words[501051] = {
	hp_warning = "",
	feeling3 = "",
	mail = "So many messages... Are they all cards wishing you a happy new year?",
	expedition = "",
	win_mvp = "",
	home = "Welcome back! Want some tanghulu? Ning Hai and Ping Hai brought some over. They're really tasty~",
	unlock = "Happy New Year, Commander... Having that said, the others said they had a surprise for me, but then ended up banning me from the kitchen... I didn't do anything bad, did I? I'm real worried... Can't I at least take a look at what's going on there? Ugh... How about you go check it out in my stead? P-pretty please, Commander!",
	touch2 = "Commander... H-Hu Pen can still see us...",
	mission = "New missions, huh? Let's work together to get things taken care of. The food's gonna go cold if we take too long.",
	vote = "",
	drop_descrip = "Happy New Year, Commander... Having that said, the others said they had a surprise for me, but then ended up banning me from the kitchen... I didn't do anything bad, did I? I'm real worried... Can't I at least take a look at what's going on there? Ugh... How about you go check it out in my stead? P-pretty please, Commander!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Commander, on this special day of coming together as a family... You kept us company, and we enjoyed a delicious feast together and watched the fireworks... You have no idea how happy that makes me~♪",
	main = "What in the world is this baozi?! The texture of the dough, the exquisite flavor of the filling! I hate to admit this, but it's better than what I can make! I, I need to research this later...!|Commander, I hope everything goes well this coming year~ Ehehe. Please let me handle all of your daily meals as well. I'll make sure everything is delicious and healthy~♪|Heehee~ I snuck into the kitchen earlier to make those spring rolls I put on your desk. ..Too spicy? Spicy is good! You're supposed to welcome the new year with a bang! Ugh, my head is spinning... Who swapped out all the cooking wine in the kitchen with Hua Tiao wine?",
	touch = "Hmm? Commander, want some baozi?",
	voice_key_2 = -1,
	mission_complete = "Mission complete! Let's count up the rewards, then head back to enjoy a nice New Year feast!",
	battle = "",
	id = 501051,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Nngh... If my hair gets all messy, you'll be responsible for combing it back...",
	feeling2 = "",
	login = "Happy New Year, Commander. Hmm? Lucky money present for me? Thank you very much... That makes me very happy~♪",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[501052] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Looks like the commission team is coming back. Hrmm... I can't cook anything for them right now...",
	win_mvp = "We won! Phew... I hope I'll get to enjoy the ocean with Commander now...",
	home = "Hmm? You've been picking up the trash around here to help protect the coral reefs? Thanks for doing that! I'll treat you to some delicious food when we're back~♪",
	unlock = "Woah, the corals look so pretty as they swish and sway... There's a whole world of color underneath the sea... I can come visit again any time I'd like? Thank you so much, Commander!",
	touch2 = "S-slowly, please... T-try not to bump into the corals, okay? *blushes*",
	mission = "",
	vote = "拉票描述",
	drop_descrip = "Woah, the corals look so pretty as they swish and sway... There's a whole world of color underneath the sea... I can come visit again any time I'd like? Thank you so much, Commander!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "For someone like me who spends all day in the kitchen, getting to see this beautiful aquatic landscape and these magnificent corals is such a rare experience... Thanks to you, my most, most, most beloved Commander... I, I was able to see something so wonderful...",
	main = "Please be considerate of the delicate ecosystem of the corals and all the other marine life, and don't go around touching things carelessly... Huh? Oh, um, it's something I learned while talking to the submarine girls.|Since you're the one who invited me, I had to do my part and dress up a bit... Huh? I look c-cute? ...Oh, um... th-thank you... *blushes*|To keep this ocean scenery as beautiful as always, let's do our best to clean up all the garbage! If we work at it enough, we might even be able to improve the environment one day!",
	touch = "Eek... Commander, could you go grab my hat?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 501052,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Commander, my hat's going to get washed away...",
	feeling2 = "",
	login = "Commander, you're finally here! Let me help you adjust your diving mask!",
	detail = "I didn't think you'd invite me to go diving with you... Well, umm... the world beyond the kitchen is surprisingly fun... *blushes*",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[501060] = {
	hp_warning = "Crap, that wasn't supposed to happen!",
	feeling3 = "Mwahaha... I know about all sorts of rumors, Commander~ What do you wanna hear about first? That one time I made a total mess of the kitchen? Sure, you got it–– Eeehhhh? Ehhhhhh?!",
	mail = "I've got mail for you, Commander!",
	expedition = "The commission team is back! Time to call up the kitchen!",
	win_mvp = "This tiger is strong! Grooar!",
	home = "Welcome back~ I whipped up some snacks for you! Come on over and give 'em a taste!",
	unlock = "Gooooood morning, Commander! I am Hu Pen of the Dragon Empery! Yeoooowch! Gah, just stubbed my freakin' toe...",
	touch2 = "Woooah! ...Woaaaooaaaaoaaah!",
	mission = "Horses might be respectable opponents, but there's nothin' respectable about horsing around on the job! That's why you've gotta finish your missions on time!",
	vote = "",
	drop_descrip = "Vulcan Stettin 1,000-ton torpedo destroyer – Hu Pen.",
	feeling4 = "\"There are lots of talented girls at this port, so I should try learning from them\"? I mean, you're not wrong, but a tiger's gonna do as a tiger pleases! Hehe, I'm sure you'll support me, won't you?",
	lose = "Oopsies... Looks like I goofed up a little... Teehee~☆",
	feeling1 = "Hmph! Who are you calling grumpy? I'm not grumpy! ...Eh? You'll give me a stuffed tiger doll? Hooray! Thanks, Commander!",
	skill = "Tiger Thrasher!",
	upgrade = "I'm freakin' awesome! Groooooar!",
	propose = "Ehehe, I can tell that you're always helping me out! You're the only person who has the patience to sit down with me and teach me things over and over again... So that's why you're a super-important person to me!",
	feeling5 = "Speaking of talented girls at the port... I'm definitely one of them! Commander, thanks for believing in me and supporting me! I'll continue to work even harder from here on out!",
	main = "Roooooar! When the tiger roars, forests shiver and mountains quake! ...Huh? I'm not a real tiger, and the only forest here is a few stalks of bamboo? Ehh, let's not sweat the small details. What matters most is the vibes!|Lung Wu's a bit too obsessed with food, don'tcha think? Maybe I should go help give her a hand... Huh? What do you mean I'm too helpful for my own good?!|Anyways! Here's the plan: I'm gonna help Lung Wu finish up her dishes, and then we're gonna go outside and play! You help as well, Commander!|Why'd I go with Kitty Kabam Punch instead of Tiger Kabam Punch? Well, uhh, it doesn't roll off the tongue the same way...",
	touch = "Oh, um, about that! Can you please keep that whole sleeping-in thing a secret from my sis? Thanks a million, Commander! You're the best~!",
	voice_key_2 = -1,
	mission_complete = "The mission rewards are in! Hurry up and go take a look!",
	battle = "Hu Pen, charging straight ahead!",
	id = 501060,
	gift_dislike = "",
	gift_prefer = "Wooow! You can really tell what a tiger's thinking, huh, Commander?",
	profile = "The name's Hu Pen, and I'm a member of the Dragon Empery's Lung Wu-class destroyers! This tiger can handle any task for you, no matter how trivial! ...Heehee~ What'd ya think? Did I come off as having the awesomeness of a tiger?",
	voice_key = 50106,
	headtouch = "Pat a tiger on the head, and nothin' but good fortune will follow you! Ehehe~",
	feeling2 = "Commander, have you heard the news? Apparently, the mold for the key to your office has been going around for quite some time! The other day, I saw... Hwuuuuh? When'd the wall grow freakin' ears?!",
	login = "Quietly now, stealthily... Fwaaah! C-Commander, g-good morning! Just gettin' this out of the way, but I totally didn't oversleep, you hear?",
	detail = "Kitty Kabam Punch, at the ready! Huuuh? That name's already taken? Seriously, there are girls here with the same naming sense as me??",
	couple_encourage = {
		{
			{
				50105
			},
			1,
			" Lung Wu, let's do this together!",
			0
		},
		{
			{
				50103
			},
			1,
			" Twin tiger combo! Rooooar!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[501061] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
