_G.pg.base.ship_skin_words[501070] = {
	hp_warning = "Lady Yuen's great adventure... isn't going to end here!",
	feeling3 = "Commander~ Come play with me! You can't because you have work? Why's that? C'mon, come play, come plaaaay! Lady Yuen abandoned today's adventure to play with you, you know? So, set all that work aside and come play with me!",
	mail = "All of these are letters addressed to you, Commander! Don't forget to read them!",
	expedition = "Our friends in the commission fleet have returned! Ehehe~ I wonder what sort of souvenirs they've brought back for Lady Yuen~",
	win_mvp = "Hmmhmm~ And this is what happens to those who look down upon Lady Yuen~",
	home = "Hmm? Oh, you've returned. Did you remember to bring a souvenir for Lady Yuen?",
	unlock = "Fei Yuen of the Dragon Empery's Chang Feng-class destroyers is at your service! And, you're supposed to be my Commander? Heheh~ Then, please refer to me as Lady Yuen from now on~♪ Do so, and I shall protect you and take you on grand adventures!",
	touch2 = "Commander... Did you break?",
	mission = "W-woaahh... What a crazy long list of missions... Commander, Lady Yuen shall assist you!",
	vote = "",
	drop_descrip = "Chang Feng-class destroyer – Fei Yuen.",
	feeling4 = "Commander! Lady Yuen has finished tidying the bookshelf! ...Hm? You pulled those books out because you were planning to reference them? S-sorry! I didn't do it on purpose... I, I was just trying to be helpful... *sniffle*",
	lose = "It, it's just one little loss... Lady Yuen would certainly not cry over something as minor as that!",
	feeling1 = "Commander, at this rate... Lady Yuen isn't going to want to take you on adventures anymore...",
	skill = "Behold Lady Yuen's magnificence!",
	upgrade = "Woooooah! I can feel power coursing through me!",
	propose = "You're giving this to me? Ehehe... That makes me so happy! There's a lot I still don't understand about this, but basically, you'll play with me forever and ever as long as I put this around my finger, right? See, it's on already! So, stay with me forever, Commander!",
	feeling5 = "Commander! Would you like to go on an adventure with Lady Yuen? ...Hm? You still have work left to do? I shall patiently wait for you to finish then! ...You'll treat me to a reward for being on my best behavior, won't you? Ehehe~ You're the best, Commander~♪",
	main = "Commander~ Come take a look! Master Hai Tien taught me how to draw this! Hmm? I'm good at drawing monsters? B-but... I was trying to draw a picture of you... *sniffle*...|Commander~ Let's go on an adventure together! What is an adventure, you ask? Hmm... for example, a quest to replace all the sugar in the kitchen with salt? No, it's not just a prank!|Lady Yuen shall assist you in placing all these sorted documents onto the shelves... Hwaah?! Owww... Everything's a total mess now... I'm sorry, Commander, I was just trying to help...",
	touch = "Hmm? What's the matter, Commander? Oh, did you finally decide to accompany Lady Yuen on an adventure?",
	voice_key_2 = -1,
	mission_complete = "Commander! A whole bunch of supplies are piling up in front of the port! Hurry up and pick up the rewards so you can buy a present for Lady Yuen!",
	battle = "Let us embark on an epic adventure!",
	id = 501070,
	gift_dislike = "",
	gift_prefer = "Yay, a present! Hehe, you're the best, Commander.",
	profile = "I am Lady Fei Yuen, Chang Feng-class destroyer. Despite my appearance, I'm quite an adept \"adventurer\"! If you're interested, Commander, I would not mind passing down my knowledge! Of course, I wouldn't snitch on you either, heehee~",
	voice_key = 50107,
	headtouch = "T-to think that you'd pet Lady Yuen's head without her express permission... But, that feels nice... S-so, I shall allow you to continue that for a bit longer!",
	feeling2 = "Oh, Commander. I was about to go out on an adventure with Fu Shun. Hmm? Don't go overboard with the pranks? Pranks? What could you possibly be talking about? I have no idea...",
	login = "La la la~♪ Have you returned? Then, shall we begin with today's work? Naturally, Lady Yuen is already good to go!",
	detail = "Mmrp... Hrnnh... Zzzzz... Gah! L-Lady Yuen would not just randomly fall asleep! Hey, I said I wasn't sleeping!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[501071] = {
