_G.pg.base.ship_skin_words[501080] = {
	hp_warning = "Ugh... It hurts... and my skirt's getting dirty too...",
	feeling3 = "Commander, I put some snacks on your desk. Please make sure you wash your hands first before eating, though. If there's anything else you'd like to have, just let me know. I'll cook anything you want~♪",
	mail = "There's a letter addressed to you, Commander. Don't forget to reply~",
	expedition = "The commission fleet has returned. It's a tough job out there, so I'll go bring some tea and snacks out to them.",
	win_mvp = "A clean victory! I'm so happy for you~!",
	home = "Commander, thank you for your hard work. I've prepared a fresh change of clothes for you, so please get changed at your convenience and rest awhile~",
	unlock = "Good day, Commander. I am Chang Feng, name ship of the Chang Feng-class destroyers. It is a pleasure to make your acquaintance. Should you need anything done, be it missions or housework, please leave it to me~♪",
	touch2 = "Hwuh?! P-please don't do something like that so flippantly... I, I'll have you take responsibility, you know!",
	mission = "Commander, you still have some missions left to complete. I've compiled them all here, so please work through them as soon as you can~",
	vote = "",
	drop_descrip = "Chang Feng-class destroyer – Chang Feng.",
	feeling4 = "Oh, just give me a minute to finish folding your laundry— Huh? Th-this is your, umm... Oh my.... *blushes*",
	lose = "It's hard to see through the fog... I'm so sorry...",
	feeling1 = "...You really ought to tidy up your office more.",
	skill = "You're not going anywhere!",
	upgrade = "May I wield this power to be of even greater service to you.",
	propose = "I suppose this makes us loving members of a new family now... From now on, I'll keep the house nice and clean for you every day, waiting for you to come home to me. Heehee~",
	feeling5 = "Commander, I've finished washing your sheets and airing out your mattress. I hope you'll be able to sleep well tonight, accompanied by the fragrance of the sun... And maybe, you'll even carry my sincere sentiments towards you into your restful slumber... Ehehe~",
	main = "Commander, I've brought you tea and snacks. They might not be anywhere as good as Lung Wu's, but please don't hold that against me. I'm also working hard to improve my cooking!|Commander, Fei Yuen and Fu Po aren't roughhousing around in your office, right? Phew... I'm just glad they're not causing you trouble.|Um... Commander, would you happen to have a ladder or something of the sort? I'd like to... dust off some of the cobwebs on the ceiling. Hmm? You'd like to help too? Okay~ I'll grab you a rag and a duster.",
	touch = "My apron's still dusty from all the cleaning, so maybe it's best not to touch me too much right now...",
	voice_key_2 = -1,
	mission_complete = "Mission complete. I washed and hung out the blankets and sheets, so now you'll be able to enjoy a good night's rest~",
	battle = "Very well. Everything has been prepared to perfection~♪",
	id = 501080,
	gift_dislike = "",
	gift_prefer = "Thank you, Commander. How can I possibly return the favor... Give me some time to think about it!",
	profile = "I am Chang Feng, lead ship of the Dragon Empery's Chang Feng-class destroyers. Word has it that my sisters have been quite a handful for you, so I do believe a scolding is called for~",
	voice_key = 50108,
	headtouch = "Heehee. Isn't this scarf-folded-into-kitty-ears cute~?",
	feeling2 = "Though Fei Yuen and Fu Po tend to leave a mess in their wake and I have to pick up after them, they're still so, so adorable~♪ What do you think about those two, Commander?",
	login = "Commander, please give me a moment? I'm still tidying up the room... I know it's already sparkly clean, but... I just can't help myself!",
	detail = "Oh, Commander... I've been posting videos on Juustagram giving people housework tips, and the responses have surprisingly been very positive! I'm really glad I've been able to do something to help others!",
	couple_encourage = {
		{
			{
				50107,
				50109
			},
			1,
			" Don't cause trouble for the others, okay~?",
			0
		},
		{
			{
				20208
			},
			1,
			" Huh? Cleaning, with a gun?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[501081] = {
