	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Phew... And now, for the finishing stroke... Ehehe, Commander, this little heart is for you. Thanks for all your hard work~",
	unlock = "Oh, Commander~ Please give me a moment; Fei Yuen, Fu Po, and I are still finishing up our spring cleaning. Why don't you come inside for now and have some warm tea?",
