	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 501081,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Mhm! I'll give this spring cleaning my all!",
	feeling2 = "",
	login = "Commander, the New Year is just around the corner, isn't it? Hm? You haven't started on your spring cleaning yet? Well, I'd be more than glad to lend you a hand~",
	detail = "There's a lifehack when it comes to wiping windows, so I'll make a Juustagram post about it later. Oh, but Commander, if you ever need a window wiped down, just let me know~",
	couple_encourage = {}
