_G.pg.base.ship_skin_words[501082] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Commander, please have some tea. It's just the right temperature to be enjoyed~",
	unlock = "Commander, this is the new Ru-ware tea set I just purchased. Absolutely beautiful, isn't it? We have a custom to bring out the best things for those you care about, which is why I decided to invite you~♪",
	touch2 = "Oh my.... *blushes*... Commander, could you please... put the teacup down first...?",
	mission = "I thought we'd be able to share a relaxing afternoon together, so I didn't expect there to be a mission... It must be hard having your job, Commander. Please let me know if there's anything I can do.",
	vote = "",
	drop_descrip = "Commander, this is the new Ru-ware tea set I just purchased. Absolutely beautiful, isn't it? We have a custom to bring out the best things for those you care about, which is why I decided to invite you~♪",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Even though I have tasted this tea every day, it somehow seems different today~ Mellower, sweeter, with a gentle aftertaste... Could it be that this tea set has imbued the tea with greater fragrance than usual... or, is it thanks to you being here that this moment is sweeter and more joyous?",
	main = "Commander, please take a look at this~♪ Don't you think these flowers match perfectly with this Ru-ware vase? Ru-ware ceramics are very hard to make, which is why we must put even more effort into picking out the perfect flowers and arranging them to bring out its beauty!|I've been fascinated with Ru-ware celadon as of late, so I've been reading up on them. Commander, would you like to read about them together?|Commander, I see you've been appreciating this Ru-ware tea set with great care. Have you taken a liking to it? ...I had a hunch you'd like it, so I bought an identical set just for you~♪",
	touch = "\"After the rain's passing comes blue skies, after the cloud's parting comes new hues.\" ...The colors of the glaze on Ru-ware celadon are truly beautiful. In fact, I've drawn inspiration from them for this outfit. Do you like how I look?",
	voice_key_2 = -1,
	mission_complete = "Finally, the mission has been completed. Are you hungry? Would you like me to make something?",
	battle = "",
	id = 501082,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Yes, this is my cat-eared scarf. I thought you'd like it, Commander. Ehehe~",
	feeling2 = "",
	login = "Commander, I've finished preparing the tea and snacks. Yes, this is the Ru-ware tea set I told you about the other day! A wonderful work of art, wouldn't you agree?",
	detail = "Once I've finished cleaning and my sisters settle down a bit, I usually enjoy making some tea and taking time to enjoy the scenery. You don't find that boring, do you?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[501090] = {
	hp_warning = "Owww! Stop hitting me! Waaah!!",
	feeling3 = "Waaah... Commander, sis chewed me out again... and said that I'm not allowed to play pranks on people anymore... Waah! (Wait a sec, what if I peel down the inner layer of Commander's cap and slip a little froggy inside...)",
	mail = "Commander, your mail is— WoooOOOah! Phew, nearly slipped and fell... Ugh, who the heck splashed water here?! ...Oh, maybe it was me...",
	expedition = "The commission team is back! Go greet them right away! ...And in the meantime, I'll... I-it's nothing, I didn't say anything!",
	win_mvp = "Ehehe~ That's the ever-so-clever Fu Po for you!",
	home = "...Commander!! Boo!! Hehe, did I scare ya? Huh? N-not at all? Because my shadow gave it away?! No freaking waaaay!",
	unlock = "Heya, Commander! Fu Po, cleverest of the Chang Feng-class destroyers, is reporting in! One look at this place, and my brain's already overflowing with prank ideas... Err, I mean, uh, plans! Battleplan ideas!",
	touch2 = "You're a meanie, Commander!",
	mission = "Commander, hurry up and finish up your missions! I put your itinerary in the desk drawer— Wait, huh? You went and got it just like that?! But what happened to all the balloons?!",
	vote = "",
	drop_descrip = "Chang Feng-class destroyer – Fu Po.",
	feeling4 = "All done! Look, Commander! I've finished drafting an epic adventure plan for Fei Yuen and Fu Shun! Pretty amazing isn't it? ...Hm? It'd be better if I did it this way? ...Huh, you're totally right... Wait, Commander? Since when could you decipher my drawings?!",
	lose = "Uwaaaaah! Sis, Commander, help meeeee!",
	feeling1 = "You're going to chew me out again, aren't you...? W-well, in that case, maybe I just won't play with you anymore...",
	skill = "Ehehe, I just came up with a GREAT idea!",
	upgrade = "I'm suuuuuuper strong now! ...I think!",
	propose = "Is this some kind of new prank item or something? Lemme see... Wait, huh? Is this what I think it is? HUH?! It's for ME?!",
	feeling5 = "...How'd you spoil my prank yet again?! W-wait, stop going through my pockets! ...Here, it's just my favorite candy! I'll share some with you!",
	main = "AHHHH!! Commander! What are you doing with my notebook?! Give it back to me! All my secret plans are in it... Hey! It's not a doodle pad!!|Ehehe~ Well, well. Aren't you the most perfect plan I've ever cooked up. I'll just wait until sis goes to do her cleaning to sneak away, then— Huh? Commander?! Why did you bring Chang Feng here?!|While you're busy with work, I'm gonna tie your shoelaces together~ Wait, huh?! You don't have any laces?!",
	touch = "AHH! You stuck something weird on me! Where is it?!",
	voice_key_2 = -1,
	mission_complete = "It's all thanks to me and my plan, right? Ehehe~ Wh-what do you mean, my scribbles made no sense to you at all?!",
	battle = "Heh heh~! My plan is PERFECT! Let's freakin' gooooo!",
	id = 501090,
	gift_dislike = "",
	gift_prefer = "Oh, this! I've had my eyes on this! Thanks, Commander!",
	profile = "I'm Fu Po, second of the Chang Feng-class destroyers! Ehehe~ By the way, I stuck a little surprise on you— Wait, huh? Why's it on the ground... I'll go pick it up... How come a bug toy is running so fast!?",
	voice_key = 50109,
	headtouch = "Ehehe... Step one: get you to lower your guard~ Heehee~",
	feeling2 = "It's not my fault the cup fell over! The wind from the AC was just too strong! ...Okay, okay! I get it! Stop looking at me like that! It was my fault! I'll go clean it up...",
	login = "You're here, Commander! Here's a nice and soft cushion for you to sit down on~ Hurry up and sit down already! ...Huh? Why isn't the cushion making a sound?!",
	detail = "Now I'll glue this to the Commander's fountain pen... Whuh? Commander?! When'd you get here?! N-nothing, I wasn't doing anything at all! Wait, why's my hand... stuck to my clothes? Commander, help meeee!!",
	couple_encourage = {
		{
			{
				50108
			},
			1,
			" Sis, I'm heading off!",
			0
		},
		{
			{
				50107
			},
			1,
			" Ehehe~ Let's sneak over to the kitchen later!",
			0
		}
	}
}


