_G.pg.base.ship_skin_words[502023] = {
	hp_warning = "",
	feeling3 = "",
	mail = "There's so many fan letters...! Being an idol is so exhausting...",
	expedition = "The commission's done? Okay then, take five. Commander, you should probably go out and meet them.",
	win_mvp = "It feels... even better than I expected.",
	home = "Nice work out there, got a request you want me to sing?",
	unlock = "We haven't had to worry as much about things like food since we joined the fleet, but that doesn't mean we can just throw money around...! Anyway, I'm the older of the \"Dragon Sisters,\" Ning Hai! Great to be here!",
	touch2 = "Roundhouse kick!",
	mission = "A new offer...? Heh, hehehehe... Sure, I'll keep packing in as much work as my schedule can take!",
	vote = "",
	drop_descrip = "We haven't had to worry as much about things like food since we joined the fleet, but that doesn't mean we can just throw money around...! Anyway, I'm the older of the \"Dragon Sisters,\" Ning Hai! Great to be here!",
	feeling4 = "",
	lose = "Oh, my outfit...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Sigh... turns out the more idol stuff I have to do, the less time I get to spend with the Commander... Commander, um, say...? Do you think you could be our manager...?",
	main = "C- Commander... \"Jia you! ☆\" Was that cute enough...? Don't look at me like that! This is serious business right here!|After studying all that kung fu, Idol dancing is a piece of cake for me and Ping Hai! Hah hah!|Oh, right! Commander, next time me and Ping Hai put out a single, we'll definitely save you one.",
	touch = "Don't worry, I'm wearing shorts underneath. And anyway if somebody tried something gross, I've got a roundhouse kick with their name on it!",
	voice_key_2 = -1,
	mission_complete = "The fans make me really happy, sure, but next time I'll have to teach them how to save money!",
	battle = "Is making me sing during a battle some kind of weird fetish thing?!",
	id = 502023,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Thank you very m–! It's you, Commander.",
	detail = "Look, all this idol stuff is just work, okay! Don't start thinking I actually enjoy it!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[502024] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "You're willing to go *any* lengths to anger me, aren't you?",
	home = "You're late! We're going to the next tourist attraction right now!",
	unlock = "Commander, what are you spacing out for? Over here! They say that you'll have good fortune if you give this thing a shake!",
