_G.pg.base.ship_skin_words[502027] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Commander, you've got mail. At this time of year, it's probably New Year's well-wishes, right? It'd be rude of you not to reply~",
	expedition = "The commission team is back. Perfect, just in time for a get-together meal!",
	win_mvp = "",
	home = "You couldn't have picked a better time to get back~! The baozi are fresh off the stove, so if you're hungry, grab a basket!",
	unlock = "Woah! Da Bao, lend me a hand here! Don't let that octopus get away! ...Oh, Commander, Happy Lunar New Year! Uhh, the kitchen prep's going fine... Huh? You're gonna help? Heheh~ don't worry about us! Just leave everything here to me 'n Ping!",
	touch2 = "...H-hey, mind the time and place, okay? Ping Hai is here, you know?!",
	mission = "Hmm? New mission? So, what's the plan, Commander? Gonna take care of it now?",
	vote = "",
	drop_descrip = "Woah! Da Bao, lend me a hand here! Don't let that octopus get away! ...Oh, Commander, Happy Lunar New Year! Uhh, the kitchen prep's going fine... Huh? You're gonna help? Heheh~ don't worry about us! Just leave everything here to me 'n Ping!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Today's main dish is drunken octopus! Here's the Shaoxing wine, but... Drunken octopus, drunken octopus... Woah! The octopus is jetting away?!|Do you like how my outfit looks? Heehee~ This was the New Year's present that everyone picked out for me, and I gave it a little unique touch! I'm still missing a stocking? Th-this modification is just to make it easier to record the orders!|Hmm? I made too much food? ...Nonsense! I might encourage being thrifty every other day of the year, but I'm going all-out today! It's the New Year after all, and you don't mess around with the New Year's banquet. So, I'm going all out!|Commander, look forward to the lavish banquet I'm going to prepare for you! ...Don't worry, I've got things under control. S-seriously, I said I can handle this!",
	touch = "Hyeep?! H-hold on, the bowls are gonna fall! ...Jeez, this isn't the time to start clinging to me!",
	voice_key_2 = -1,
	mission_complete = "Mission rewards, collected and accounted for! Hmm... What's this... I think I can incorporate this into my banquet menu?",
	battle = "",
	id = 502027,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Oh, a customer! ...Uhh, I mean, welcome back, Commander! Got work today? Well, let's get it taken care of so we can enjoy our New Year's banquet!",
	detail = "",
	couple_encourage = {
		{
			{
				50203
