_G.pg.base.ship_skin_words[502041] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "A~ job~ well~ done~♪ ...Hehe, did you like that?",
	home = "In the warm spring breeze, snow melts and life blooms anew. Spring is the season of life.",
	unlock = "Happy New Year, Commander. I've come to deliver you blessings for this coming year... Next, you're going to ask for a red envelope, right? Hehe, just teasing~",
	touch2 = "The excitement of the festival seems to have gone to your head. Hehe~",
	mission = "",
	vote = "",
	drop_descrip = "Happy New Year, Commander. I've come to deliver you blessings for this coming year... Next, you're going to ask for a red envelope, right? Hehe, just teasing~",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Miss Yat Sen, I'll help you prepare the food for tonight's reunion dinner. What about the fish? I'll start it up if you'd like.|I never thought I'd be able to enjoy the company of my sister and all our friends like this... Yes, it's all thanks to you, Commander.|Fu Shun, if you throw any more firecrackers into the pond... I'll change your seat to be right next to that lotus~♪",
	touch = "Since it's the Spring Festival, how about taking a break?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 502041,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "The warmth of spring often lulls many into oversleeping... But, Commander, it seems like you're accustomed to waking up early?",
	detail = "Chao Ho thinks up the couplets, and I write them down. Don't you think we make a good team? Besides, seeing Chao Ho's brows furrow in thought is super cute... Anyway, let's think up some lines together later.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[502042] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Got some mail for you, Commander, but it's not easy for me to move right now. I'll just leave it on the table for you.",
	expedition = "",
	win_mvp = "",
	home = "Nngh~ My legs sure are sore... Oh, Commander, you're back. Say... would you mind helping me out a little?",
	unlock = "Commander, Happy New Year! Chao Ho and I are preparing for this year's Spring Festival, and as you can see... we're in the middle of a little \"intermission.\" Hehe, don't worry, there's nothing you need to help out with. Just take a seat over there and enjoy the show~",
	touch2 = "Commander, are you sure you want to do this with Chao Ho watching? I never knew you had kinks like that...",
	mission = "",
	vote = "",
	drop_descrip = "Commander, Happy New Year! Chao Ho and I are preparing for this year's Spring Festival, and as you can see... we're in the middle of a little \"intermission.\" Hehe, don't worry, there's nothing you need to help out with. Just take a seat over there and enjoy the show~",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I already apologized to Chao Ho about what happened today. Oh right, Commander, do you have some time to spare after the evening banquet? I have some things to tell you, but only if we're alone! Because, it's a little embarrassing... Ah, but I'll have to apologize to her again for making a move behind her back, heehee~♪",
	main = "What's the matter, Chao Ho? Still haven't been able to get your stuff back? ...I tricked you? What could you possibly be talking about?|We're almost completely out of ink for our Spring Festival couplets. Commander, mind helping me grind up the inkstick? I'm a bit busy right now, but I'll make a cup of tea for you later.|The goods Akashi sent over sure are convenient. There's the mechanical errand-running Manjuus, the automatic fireworks launchers, and the lion dancers as well... I'm sure Fu Shun and her gals would have an absolute blast with these.",
	touch = "You also want to try playing a prank on Chao Ho? Sure, but don't go too overboard~",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 502042,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "An old saying goes, \"it's better to be lucky than it is to be punctual.\" Since you've come at quite the fortuitous moment, why not come sit next to me and enjoy the show? As for what's going on over here, don't sweat the small details~♪",
	detail = "This year, Hai Tien is in charge of coming up with the Spring Festival couplets, I'll be doing the calligraphy, and Chao Ho is handling the decorations. An all brawn, no brain job like that is perfect for my sister, isn't it? Heehee~♪",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[502043] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Phew... You're back. You look tired, so sit down with me and just feel the water on your skin for a while.",
	unlock = "Heehee, if it isn't the Commander. Your timing is perfect~ I was thinking I might take a break here... While you're here, why don't you rest in the pool with me?",
	touch2 = "Keep doing that with me, and you'll face serious consequences... Oh, I mean falling into the pool, of course♡",
	mission = "",
	vote = "",
	drop_descrip = "Heehee, if it isn't the Commander. Your timing is perfect~ I was thinking I might take a break here... While you're here, why don't you rest in the pool with me?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Commander, we're reflected in the pool. Heehee, can you try coming a little closer? I want to see your reflection snuggling close to me. And... I want to see if you only have eyes for me♪",
	main = "Isn't this swan float just adorable? If you like it... then come and sit next to me♪|Hm? Commander... Your eyes are practically glued to me. Do you prefer this outfit?|Sunshine, a pool, and you... I wish every day could be this relaxed. If only I could keep you... Ahem... How am I supposed to express my feelings without pen and paper?",
	touch = "Heehee... I could lose hours watching the ripples with you.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 502043,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Ah... Commander, you got my hair wet...",
	feeling2 = "",
	login = "Welcome back, Commander. Do you have any plans? Heehee, if you've got the time... come join me for a game in the pool!",
	detail = "Chao Ho and I picked out this swimsuit together. It shows off my curves... Ahem, forget I said that. Anyway, do you like it?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[502049] = {
	hp_warning = "",
	feeling3 = "",
	mail = "You have mail. I suppose your period of rest is coming to a quick end... Would you like me to sort them out first?",
	expedition = "",
	win_mvp = "",
	home = "Welcome back, Commander. If you have any entertaining thoughts today, I'll be your best listener. Hehe, but first, take a break... Tell me all about it after.",
	unlock = "My retrofitting is complete! Don't I look a little stronger than before? Regardless, I hope you'll guide me as you always have, Commander.",
	touch2 = "Well, well. I've caught you red-handed again. Hehe, if you want me to keep quiet... then you'll have to spend the entire weekend with me.",
	mission = "Let's get these missions done before Chao Ho finds out. Otherwise, she'll start nagging you like a mom again.",
	vote = "",
	drop_descrip = "My retrofitting is complete! Don't I look a little stronger than before? Regardless, I hope you'll guide me as you always have, Commander.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "There are so many things I want to say that I'll probably take up all of your free time... Hehe, anyway, where should I begin?",
	main = "It's not as if your work will ever end. Put down your pen for a moment and try the tea I made, would you?|I'd be happy to teach you about the Four Treasures of the Study. My brushwork is much steadier now, and I've gotten better at teaching!|Chao Ho is secretly practicing her dance steps again. Wanna go watch with me? Heehee!",
	touch = "Hehe, is that all you've got? Personally... I'm willing to go much further~",
	voice_key_2 = -1,
	mission_complete = "Missions complete! All that's left to make the perfect day is to eat together, take a bath, and go right to sleep... What do you think, Commander? Heehee.",
	battle = "",
	id = 502049,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "You want to pat my head? That's fine by me, but in return, you'll have to brush my hair for the next two weeks.",
	feeling2 = "",
	login = "You're very punctual, as usual. If you're in the mood to play hooky at all... I could help you get your work done early?",
	detail = "Don't you think I've become even more reliable? Hehe, there's no need to say it. I can already tell from the look in your eyes.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[502050] = {
	hp_warning = "It's time to get serious! I'll make them pay for underestimating me!",
	feeling3 = "Commander! Ying Swei... Ying Swei... she threatened to not share Ning Hai's steamed buns with me! And said I have to clean the room today! H-hurry up and do something about her!",
	mail = "Commander, hurry up and check your mail before it starts growing moss!",
	expedition = "The commission fleet's back? Y-yeah, we did send one out earlier, huh... Wh-what, I didn't forget about that!",
	win_mvp = "Hmph! I'll say this again! Don't you dare violate our oceans!",
	home = "All right, nobody's here, right? Maybe I'll practice my dance steps a little... Ehh?! Huh... Wh-when'd you get back?!",
	unlock = "I'm Chao Ho, lead ship of the Chao Ho-class cruisers! Don't you forget it! Oh, and no matter what Ying Swei says, don't let her trick you into thinking I'm the little sister!",
	touch2 = "Eeek?! Y-y-y-y-you pervert! Degenerate!",
	mission = "We've got new missions! Hurry up and take a look! Otherwise, Ying Swei is going to complain about me nagging again!",
	vote = "",
	drop_descrip = "Chao Ho-class protected cruiser – Chao Ho.",
	feeling4 = "Um, Ying Swei said you don't like short-tempered girls, so I'll try to act a bit mellower! So, um, please don't hate me... Hey, wh-what are you laughing for?! Don't get all uppity with me!",
	lose = "Guh... Am I still not strong enough yet...?",
	feeling1 = "Don't talk to me like you know me!",
	skill = "Be captivated by my song and dance!",
	upgrade = "H-hey, I look a bit more reliable now, don't I?",
	propose = "At a time like this, I'm supposed to say \"may we hold hands and hope to live forever with one another\" or something like that, right... Ahh, I can't remember this stuff! A-anyway, you have to take good care of me from now on! Got it?!",
	feeling5 = "About my new dance, um... I want you to name it, since you'll be the first person who gets to see it. So... how about it? Y-you don't have to come if you don't want to! ...Ugh! I mean, you have to come! No matter what! Even if you don't want to! Jeez!",
	main = "Let Ying Swei handle the public side of things! I, uh, I'll support her from the sidelines! ...Wait, wouldn't that make me seem like the little sister then?!|H-how long are you going to keep dawdling around in front of me? Can you just sit down and get your work done?! Eh? ...What the heck are you saying?! It's not like I really care what you're doing or anything...!|Only through perseverance can we reach our desired outcome! ...Th-those are Ying Swei's words, not mine!",
	touch = "...What are you trying to do?!",
	voice_key_2 = -1,
	mission_complete = "That mission was a piece of cake! ...W-well, I suppose your efforts helped!",
	battle = "P-purge all evil... Ah, screw it, will you die already?!",
	id = 502050,
	gift_dislike = "",
	gift_prefer = "It's mine now! I'm not giving it back!",
	profile = "I'm the name ship of the Chao Ho-class protected cruisers, Chao Ho! As for my history... who the heck knows! Specs? Dunno about that either! Stop asking about this stuff already!",
	voice_key = 50205,
	headtouch = "Ahhhh!! You're gonna mess it up, so stop touching already!",
	feeling2 = "I still haven't practiced my dance today... Commander?! I, I won't let you peek!",
	login = "H-hey, you're late! I was worried about you, darn it!",
	detail = "Why do people think Ying Swei is the big sister?! ...Am I that immature in comparison?! Commander, what's your take on this?",
	couple_encourage = {
		{
			{
				50204
			},
			1,
			"Let's do this thing!",
			0
		},
		{
			{
				50101,
				50102,
				50103,
				50104
			},
			1,
			"I'm glad we have such stalwart companions!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[502051] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Don't worry, this tree is real sturdy and won't break with just one person on it... Hey, wait, are you calling me fat?!",
	unlock = "Happy New Year, Commander! This red envelope is my gift to you... after all, that's my responsibility as a big sister! Anyway, hurry up and take it!",
	touch2 = "Y-you're gonna get eaten up by the Nian beast!",
	mission = "",
	vote = "",
	drop_descrip = "Happy New Year, Commander! This red envelope is my gift to you... after all, that's my responsibility as a big sister! Anyway, hurry up and take it!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "My performance for the Spring Festival banquet? ...I-i-it's not like I'm nervous or anything! I've practiced over and over!|I wish my sister was as demure and well-behaved as Tai Yuan... Yeah, Ying Swei, I'm talking about you! Stop laughing!|Commander, it's really cold tonight around the time of the banquet. If you catch a cold, um, I'm going to have to take care of you, and that would be a hassle... So, um, yeah!",
	touch = "...D-don't scare me like that!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 502051,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "You're late, Commander! Jeez, we're all supposed to get together for the New Year, so stop running around!",
	detail = "That Ying Swei... Even though she knows I'm not good with the literary stuff, she still made me think up spring couplets... If it wasn't for her sake... Commander, come here and help me think of lines as well!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[502052] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Why's there a letter addressed to you in a place like this? Did you misplace it or something?",
	expedition = "",
	win_mvp = "",
	home = "Ugh, my back and legs are all sore... Commander, hang in there a bit longer for my sake, alright? I'm done for... I need to rest first...",
	unlock = "Happy... New Year... Commander... Gah, this isn't the time for pleasantries! And you, help me catch the dumb fluffball that ran off with our ornaments! Jeez, why is this happening when I'm in the middle of getting ready for the Spring Festival?!",
	touch2 = "Y-y-y-y-y-you pervert! I can't believe you'd take advantage of another person's misery like this...!",
	mission = "",
	vote = "",
	drop_descrip = "Happy... New Year... Commander... Gah, this isn't the time for pleasantries! And you, help me catch the dumb fluffball that ran off with our ornaments! Jeez, why is this happening when I'm in the middle of getting ready for the Spring Festival?!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Umm, you don't need to be that worried about me. I'm used to Ying Swei playing pranks on me by now, and besides, she already said she's sorry... Well, if you insist on apologizing on her behalf, um... then, go on a date with me after this! ...You're fine with that? Heehee, I'm gonna make Ying Swei soooo jealous for what she did to me today~♪",
	main = "Ying! Swei! I know you're behind all this, so get these little guys to knock it off already!|Commander, um... Can you try to make things less awkward? You know, the two of us hiding under a table like this, umm... might cause some serious misunderstandings...|I wonder how the decorations for the other parts of the port are coming along... Huh? You've already taken care of everything? W-wow, you're pretty reliable, huh...",
	touch = "I, I didn't touch you on purpose, okay? I'm sorry! It's all because this little bugger here made me do it...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 502052,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Almost got it... Huh? Commander, what are you doing here all of a sudden? Hey, get back here, you dumb bird! Now look what you did! It got away because of you! Ughhh, why is this even happening?!",
	detail = "Ahhhhh jeez, what's wrong with these pipsqueaks?! I swear they're running from me on purpose... I knew it! This is all Ying Swei's fault! I knew she had an ulterior motive for assigning an \"easy\" job like decorating to me...!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[502053] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Phew... Finally back? That must have been a rough battle. I'll make room for you, so get some rest in.",
	unlock = "H-hey, you, warn me before you come in next time! I was just looking for my swimsuit... F-forget it, okay? I'm not trying to chase you out! If you're coming in, then come in already!",
	touch2 = "Mmh?! Don't touch me out of nowhere... What if I fall?!",
	mission = "",
	vote = "",
	drop_descrip = "H-hey, you, warn me before you come in next time! I was just looking for my swimsuit... F-forget it, okay? I'm not trying to chase you out! If you're coming in, then come in already!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "You're right next to me, but I can't bring myself to do anything... Huh? You noticed it right away?! Y-you didn't have to politely look away every time, then... You can look at me all you want...",
	main = "My swan float? I mean, it's cute, isn't it? If you want to sit... Promise you won't turn toward me, and I'll let you!|(You've been staring for a while... Do you know? What do I do if you know? This is way too embarrassing!)|The pool is nice, the sunshine is pleasant, and I have you... I should be so happy right now. Why did this have to happen right now?!",
	touch = "Oh, man... Ack! I was just looking at the ripples in the water!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 502053,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "(Wh-what do you think you're doing? That almost blew my cover!)",
	feeling2 = "",
	login = "You're back? Then relax here for a while, if you want. ...You want to play with me? Sure... Huh? My swimsuit! N-no, now isn't a good time!",
	detail = "Where on earth did it go... Ahem. We can play later, okay? I'm in the middle of something important... Geez! I'm not going anywhere, and my swimsuit DEFINITELY won't disappear into thin air!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[502059] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Oh? You're back? ...No, I was NOT waiting for you! I just happened to finish my drills!",
	unlock = "Chao Ho's back, and she's better than ever! Hmph! Now my strength and my authority as the older sister are unquestionable!",
	touch2 = "Hyah?! Wh-wh-what are you doing, dummy?! Now isn't the time to be doing that!",
	mission = "You have new missions! I'll keep an eye on everything. Get them done quickly so you can get some rest!",
	vote = "",
	drop_descrip = "Chao Ho's back, and she's better than ever! Hmph! Now my strength and my authority as the older sister are unquestionable!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "New clothes, new steps, and it's all for you... That's why I staked my pride on making it all perfect! I mean, you know that, don't you?! If you tease me and act like it's not perfect... I'll never forgive you!",
	main = "Why are you looking at me like that? Don't tell me... Heheh, you've finally realized how awesome of an older sister I am?|Hey... If anything is bothering you, you could... you could talk to me about it... I-I'm not worried about you. I just don't want it to affect your work!|Your documents are a mess! Yeah, yeah, I'll clean it up for you. But I'm not doing it for your sake!",
	touch = "Hyah?! Wh-why are you getting so close to me?!",
	voice_key_2 = -1,
	mission_complete = "Easy-peasy! I was totally reliable, wasn't I? O-of course, you deserve most of the credit...",
	battle = "",
	id = 502059,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "H-honestly, you're too much... Okay, but just a little.",
	feeling2 = "",
	login = "Hmm, right on time. Very nice. As the older sister, I have to commend your punctuality.",
	detail = "Do I look more like an older sister now, Commander? Hmph! Now nobody will think Ying Swei is the older one! H-hey, quit laughing!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[502070] = {
	hp_warning = "The fog's rolling in...?!",
	feeling3 = "There are many forms of poetry, including the bold and uninhibited \"Boundless Waves\" style, as well as the gentle and reserved \"Country Jade\" style. Which do you prefer, Commander?",
	mail = "Every word and letter written on this paper is a deep thought from far away...",
	expedition = "It looks like the girls have returned from their commissions. Make sure you show them your gratitude.",
	win_mvp = "\"War stains the land for a thousand miles, bullets salting the earth in its wake.\" ...When will the flames of war finally be snuffed out?",
	home = "Commander, good work in your operation. I have prepared some nutritious tremella lotus soup for you. Please dig in... Um, did I make it too sweet...?",
	unlock = "Pleased to meet you, Commander. I am Hai Tien of the Dragon Empery. As a newcomer who knows not the customs of this place, please bear with me should I make any blunders.",
	touch2 = "H-how shameless of you...!",
	mission = "Commander, please make sure you remember to complete all your missions today.",
	vote = "",
	drop_descrip = "Hai Tien-class protected cruiser – Hai Tien.",
	feeling4 = "*Sigh*... Oh, my apologies, Commander. I'm perfectly fine. It's just that... I recently read some excellently-composed poems about \"reminiscence.\" I suppose I found them to be... extremely relatable.",
	lose = "I see... \"Even horses can stumble.\"",
	feeling1 = "Please do not talk to me. I wish to be alone.",
	skill = "\"Even mountains will move before an unbreakable spirit!\"",
	upgrade = "\"To do a good job, a craftman must first have the right tools.\" Thank you very much, Commander.",
	propose = "\"Being able to find one's soulmate in the flowing river of time is the greatest blessing in life.\" Wait, um, that means we're more than just good friends.... Err, umm, I'm okay with that too... I mean, wait, give me a second to sort out my thoughts... P-please, just a moment!",
	feeling5 = "As a commander, the winds of war may one day take you far, far away... But no matter where you are, please remember –– we will always be together under the same night sky.",
	main = "Looks like Hai Chi is just as energetic as always. Oh... Is she a bother to you, Commander?|I left a manuscript of poetry on your desk, Commander. If you would please peruse it when you have the time.|What shall we do for dinner? Hmm... How about some mapo tofu?",
	touch = "Oh, my apologies... I was thinking about the book of poems I was reading earlier. What can I do for you?",
	voice_key_2 = -1,
	mission_complete = "Good work completing your missions. I'm sure the rewards will be great as well.",
	battle = "Is the only way to end war... through more war?",
	id = 502070,
	gift_dislike = "",
	gift_prefer = "I swear, I will repay this kindness someday!",
	profile = "I am Hai Tien, a Hai Tien-class protected cruiser from the Dragon Empery. There's not much to say about my past except perhaps... that fate was unkind to me.",
	voice_key = 50207,
	headtouch = "Hm? I feel perfectly fine though?",
	feeling2 = "The beautiful part about poems is not only their rhymes and coupling, but also the many thoughts hidden between the lines... Do you have an interest in the path of poetry, Commander?",
	login = "\"Time is worth its measure in gold.\" Commander, if you don't start your work by now, you'll end up wasting the entire day.",
	detail = "\"It is easier to relate with the despair of a wilting flower than the beauty of a blooming flower.\" ...Do you think I'm being too sentimental?",
	couple_encourage = {
		{
			{
				50208
			},
			1,
			"Don't worry, I'll be fine.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[502071] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "\"Lotus flowers blooming in a clear pond, clouds flowing through the air, a sage descends from their dwelling, playing music and dancing about.\" ...Hehe, Hai Chi's dance is something worth appreciating. If that sounds interesting to you, why don't we go watch her together?",
