_G.pg.base.ship_skin_words[502072] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Hai Chi's special dance lessons should've helped out a little bit... What do you think, Commander?",
	unlock = "Through dance of gossamer silk, the apsaras' grace soars... Oh, I'm simply reciting something I just happened to pick up on. What do you think, Commander? If I've captured your attention, I suppose this was worth our while~",
	touch2 = "I-it's not very courteous of you to take advantage of another's vulnerability...",
	mission = "",
	vote = "",
	drop_descrip = "Through dance of gossamer silk, the apsaras' grace soars... Oh, I'm simply reciting something I just happened to pick up on. What do you think, Commander? If I've captured your attention, I suppose this was worth our while~",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Huh? Y-you want me to try making this pose as well? Um, Hai Chi, I'm not sure about that... Can't we go with something a bit easier?|If only I were a real apsaras who could fly freely through the skies... Hmm, maybe those are the kinds of wishes that gave birth to airplanes.|Eep! Why'd the wind pick up all of a sudden?! ...Come to think of it, this apsaras outfit is rather... breezy... *blushes*",
	touch = "Umm, I'll be alright. I can endure this. If you agree that I'm not a weak little girl, please put up with my wilfulness a bit longer.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 502072,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "I put quite a bit of time and effort into making these hair ornaments. They're pretty, aren't they?",
	feeling2 = "",
	login = "Commander, umm... Next, I would like to humbly offer you a dance... Sorry, but, umm... I'm still a bit nervous about this...",
	detail = "I know a thing or two about playing the pipa, but holding this position is rather difficult... not to mention, embarrassing...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[502073] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Commander, need a little pick-me-up? I happened to make some extra shaobing earlier–– Oh, they're too sweet?",
	unlock = "Sorry to keep you waiting. It took quite some time to prepare my dress as well as this lantern... Yes, when you said we would go on a \"night stroll,\" I made some preparations in accordance to what my ancestors once did. Now then, shall we set off?",
	touch2 = "S-so this is what you were after the entire time, Commander?!",
	mission = "Today is a day to rest our weary wings, so why don't we set aside work for the time being?",
	vote = "",
	drop_descrip = "Sorry to keep you waiting. It took quite some time to prepare my dress as well as this lantern... Yes, when you said we would go on a \"night stroll,\" I made some preparations in accordance to what my ancestors once did. Now then, shall we set off?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "\"Upon the water's surface, algae intersects with shadows of bamboo and cypress.\" Gods and ghosts aside, an outing during a night like this is certainly an experience to remember. And what's more, you're here too...|Vampires, Frankenstein, and witches... No matter where you go, there will always be so many legends of oddities and monsters. Isn't that interesting?|So basically, if the kids say \"trick or treat\" to me, I have to give them candy? I see... Do you think these shaobing will suffice?",
	touch = "H-hold hands...?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 502073,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "The scenery tonight is wonderful, is it not? The two of us sneaking off under the hustle and bustle of the festivities to enjoy some alone time... Doesn't it feel a bit like a tryst?",
	detail = "Strange rumors seem to have surfaced that \"a ghostly woman has appeared in the forest, floating upon a strange-sounding wind\"... Um, Commander, why are you staring at me like that...?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[502074] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Thanks for your hard work today, Commander. I brought pastries. ...Oh? The sweetness level is perfect? I'm glad to hear that♪",
	unlock = "Welcome back, Commander. I made some tasty pastries for you. ...Huh? You want the one in my chest? Th-that doesn't count.",
	touch2 = "Th-that isn't mochi...",
	mission = "You have unfinished missions, you know. Do your best to finish them, and I'll give you a reward.",
	vote = "",
	drop_descrip = "Welcome back, Commander. I made some tasty pastries for you. ...Huh? You want the one in my chest? Th-that doesn't count.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "\"Delicious foods are common, but a true friend is rare. Even more, a lover you can spend the good times with...\" Hm? That look on your face... Heehee, it looks like you understand how I feel.",
	main = "The old philosophers tell us to eat finely ground grain and finely chopped meat. In other words, all foods – including pastries – should be healthy and intricate.|Did you know that being \"not TOO sweet\" is one of the highest praises for sweets? Heehee, do my pastries suit your palate, Commander?|\"Even if your teeth fall out, eat pastries without reserve.\" Never be ashamed to enjoy what you like, Commander.",
	touch = "Oh... Are you still hungry?",
	voice_key_2 = -1,
	mission_complete = "Heehee, you did your missions! How about I feed you my newest pastry in return?♪",
	battle = "",
	id = 502074,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Umm, you're not supposed to knead me like I'm dough...",
	feeling2 = "",
	login = "Today's afternoon tea time will combine crispy pastries and sencha-brewed green tea... Phew, I'm already excited for it.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[502078] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "\"An end to all wars, when peace prevails over the seas.\" The future you desire will come to pass, and I shall witness it with you.",
	home = "Welcome back, Commander. I've prepared a nutritious medicinal decoction of mountain yam and goji berries for you... but this time, I made it sweet enough to suit your tastes!",
	unlock = "\"Dragon-shaped jade comb in hand, tied is her hair with gold ribbons and phoenix's hairpin\" ...Thank you for waiting for me, Commander. Long have I dreamt for this moment to come true... Please allow me to remain by your side forevermore. N-now then, I believe the next thing for us to do is... c-consumate... *blushes*",
	touch2 = "C-Commander, I, I'm ready for this...!",
	mission = "Commander, don't forget to finish your work. I'll be right here to help you.",
	vote = "拉票描述",
	drop_descrip = "\"Dragon-shaped jade comb in hand, tied is her hair with gold ribbons and phoenix's hairpin\" ...Thank you for waiting for me, Commander. Long have I dreamt for this moment to come true... Please allow me to remain by your side forevermore. N-now then, I believe the next thing for us to do is... c-consumate... *blushes*",
	feeling4 = "",
	lose = "I already promised... to never give up.",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "\"Pity unto the mandarin ducks, cherished are the years. The earth aged, the skies desolate. Yet nevertheless, life after life, together they come, to fly as a pair.\" ...Commander, do you understand the meaning of my words?",
	main = "Commander, is there anything you'd like for dinner? ...Hm? You'll go with my recommendation? Well, umm... How about something nourishing, like oysters, or mutton?|Umm... I r-recently wrote a short story, and the main characters are the two of us... W-would you like to give it a read?|\"At dawn I gaze at the sky and at dusk, the clouds. Whether in motion or at rest, I find your countenance on my mind.\" ...Huh? A t-translation? Oh, umm... it means, that I, umm... that I'm thinking about you at all times! *blushes*",
	touch = "You want to hold hands with me? Then, umm... Please do so, firmly.",
	voice_key_2 = -1,
	mission_complete = "Have you finished your missions? I'll help you record down the rewards.",
	battle = "\"A war to end all wars\" ...Even if this idea is futile, it is all I can do to protect the people I love!",
	id = 502078,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Hmm... Commander, I wonder why you look so brave and gallant today... P-perhaps it is because I am at your side?",
	feeling2 = "",
	login = "You're here, Commander. To commemorate this auspicious day, I've brought some mutual-joy cakes. I hope you find them to your liking.",
	detail = "At some point, I started to find myself filled with happiness whenever I was around you. Perhaps this is the true essence of \"sharing drinks, holding hands, growing old together, so that the years flow by harmoniously.\"",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[502080] = {
	hp_warning = "Gah... Don't you dare underestimate me!",
	feeling3 = "If I'll ever have to make a tough life decision, I'll face it with solemn courage and thrust forward, like a river current cleaving through land! ....Hoo! Haah!",
	mail = "Commander! A horseback messenger brought this – a letter for you!",
	expedition = "Those girls you sent out have returned! I've readied a small meal for them. An army can't march on an empty stomach, you know!",
	win_mvp = "\"When I take the reins, none may stand before me!\"",
	home = "Welcome back, Commander! Did the sortie take you far from home? Did anything interesting happen? Come on, I wanna know!",
	unlock = "You're the Commander? Hahah, I've heard all about you! Oh right, I forgot to introduce myself! I'm Hai Chi, Hai Tien-class cruiser. My two favorite things are traditional opera and going on trips! ...But, let's cut the chit-chat. You'll learn more about me soon enough anyway!",
	touch2 = "Oh, you are so gonna get an earful from my sister for this!",
	mission = "You've got new missions! I'll do the navigating!",
	vote = "",
	drop_descrip = "Hai Tien-class protected cruiser – Hai Chi.",
	feeling4 = "We have a saying in the Dragon Empery, \"the time spent sharpening your axe is made back multifold on the job.\" In other words, taking some time to rest makes you more productive in the end! So, with that in mind... How about we go on a journey right now?",
	lose = "Bweh... I'll get you for this!",
	feeling1 = "Hmph. Everything you've done and said, I'll hold against you forever!",
	skill = "Hi-yah! We'll scatter you like petals in the current!",
	upgrade = "\"Spare no expense. Even a dull blade can shine bright,\" right?",
	propose = "Oh my gosh! Is this for me? Hehehe~ Know that you're in safe hands with me. I promise you're not gonna regret this decision! If you didn't know, I'm the world's best housewife, bar none! Now, with our vows made, let's get started packing our belongings and go on a productivity-boosting honeymoon!",
	feeling5 = "If I've put you off with my habit to say whatever pops into my mind, then... sorry! Then again, you've known me for so long you must be used to it by now. Right? Hehehe~",
	main = "Do you have any interest in Dragon Empery's traditional opera? In that case, I'd be glad to show you an example. What sort of piece would you want me to perform?|My sister's pretty reserved, but I don't shy away from speaking my mind. Comes as naturally to me as breathing!|The Dragon Empery has a proverb that goes, \"it is never too late for the noble to take revenge,\" but personally, I disagree! If you don't set wrongdoers straight right away, they'll only be emboldened!",
	touch = "Commander, if there's anything on your mind, just say it to me straight away!",
	voice_key_2 = -1,
	mission_complete = "Mission complete! Might I interest you in a dramatic performance during breaktime?",
	battle = "Forward in formation! \"Let not a single scrap of armor remain of our enemies!\"",
	id = 502080,
	gift_dislike = "",
	gift_prefer = "Commander, thank you for the gift! Hmm... I wonder how I can return the favor...",
	profile = "I'm Hai Chi, Hai Tien-class protected cruiser number two. With how different we are, you almost wouldn't believe Hai Tien and I are sisters. She likes staying indoors and reading, while I prefer getting out and going places! \"Wiser is she who travels ten thousand miles than she who reads ten thousand books,\" after all!",
	voice_key = 50208,
	headtouch = "You like my hair ornament? Thanks, but no touching, please.",
	feeling2 = "I wonder what gift I should buy for Hai Tien on my next trip... Wait, I've got it! The same as usual – a yummy snack!",
	login = "\"A sharp mind is honed through diligence and dulled by indolence.\" Commander, you'd better get ready to give it your all today!",
	detail = "Are you a cat person, Commander? Cats are actually quite clever. If you're ever struggling to choose between two things, just let a cat decide. The results may surprise you!",
	couple_encourage = {
		{
			{
				50207
			},
			1,
			"Stay focused, sis!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[502081] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "\"Clouds of fog sail the air as pond lotuses bloom. The mountain recluse descends from the sky to play a melody.\" My sis composed this little poem on the spur of the moment and I wrote it down!",
	unlock = "Look, Commander! I've become a goddess from the Dragon Empery's folklore! Hehehe! Let me perform for you a song and dance number I just learned!",
	touch2 = "Ugh, Commander! This is NOT how you treat a goddess!",
	mission = "",
	vote = "",
	drop_descrip = "Look, Commander! I've become a goddess from the Dragon Empery's folklore! Hehehe! Let me perform for you a song and dance number I just learned!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "This act – known as the \"behind-back pipa\" – takes serious skill. You can't pull it off with half-baked effort!|Allow me to play you a song on my pipa! Full disclosure though: I only started learning it a while ago. If something sounds off, don't be afraid to point it out!|Struggling with poetic rhymes? Ask my sis, she can produce ten verses without even thinking about it! No, seriously!",
	touch = "You've fallen for my goddess-like looks, haven't you~? Hehehe, it's okay to come out and admit it~",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 502081,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Welcome, Commander! I'll be performing a Dragon Empery dance at the port later today. Wanna come watch?",
	detail = "For this part, I guess I should pose like... this? Ah, you're back, Commander? Perfect! Could you watch for a sec and tell me if my moves are on-point?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[502090] = {
	hp_warning = "This has gotten rather troublesome...",
	feeling3 = "Even though I choose to be everyone's listener, there's a reason why I don't make suggestions or decisions for them. \"True knowledge lies in knowing that there are things you do not know.\" Heehee... Commander, this is an adage you understand well, right?",
	mail = "There's new mail for you. Oh, looks like my cookbook has arrived as well~",
	expedition = "The girls from the commission team have returned. Naturally, you should go express your gratitude to them. Cultivating harmonious relationships is important, you know?",
	win_mvp = "Strategies devised in the command tent can determine the outcome of battles waged thousands of miles away~♪",
	home = "Welcome back, Commander. Oh, your collar's all messed up... Heehee. That should do the trick.",
	unlock = "Greetings. I am Chi An, light cruiser of the Dragon Empery. Now that we've gotten these stiff introductions out of the way... Commander, should you ever have any worries on your mind from now on, you can always turn to me~♪",
	touch2 = "Oh... My, oh my... Heehee. How wonderfully daring of you~♪",
	mission = "Commander, please remember to complete your missions. The greatest advantages begin with small steps taken daily.",
	vote = "",
	drop_descrip = "CNT Shipyard 1,800-ton small protected cruiser – Chi An.",
	feeling4 = "Oh my... Did you want to vent your frustrations? I'm glad you remembered what I said. Heehee. In return, you wouldn't mind if I try to get to know you a bit more... intimately, would you?",
	lose = "Soldiers know well both the sweetness of victory and the bitterness of defeat. The more important thing is to try again.",
	feeling1 = "Jeez... I know I said you could always come to me if you had any worries on your mind, but... If this is how you're going to be... *sigh*, oh well...",
	skill = "The flow of battle is mine to control!",
	upgrade = "Mm. That feels pretty nice~♪",
	propose = "An important discussion, hmm? Heehee. Is this what you meant? My, I suppose I was caught off guard this time by your bold and decisive move. Though, I do hope you've prepared yourself, because my counterattack is going to be even more passionate~♡",
	feeling5 = "...By the way, Commander, do you think you'd be willing to lend me an ear now? I won't take too much of your time. Umm... Actually, this time, um... it's about plans for this year's Qixi festival...",
	main = "It is said that war is the art of deception, but in reality, the resources at your disposal are limited. Do you seek to make micro-level changes, or do you seek macro-level stability? This.... is the difference between a tactician and a strategist.|I do enjoy a good game of Go. ...No, I don't particularly care for the tense clash of wits. It's just nice to have a pleasant conversation with my opponent.|...Now, this is quite unfortunate. Even Fu Shun doesn't want me going into the kitchen. Do you think you could help me improve my cooking skills, Commander?",
	touch = "Oh my, are you interested in trying some of my home cooking? \"Anything but that\"? Aww...",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Slowly but steadily, this is how great advantages are accrued.",
	battle = "Strike while the iron is hot~♪",
	id = 502090,
	gift_dislike = "",
	gift_prefer = "Aww, isn't that cute?",
	profile = "I am Chi An of the Dragon Empery. I am a light cruiser created through an improvement upon the design of the Novara-class cruisers. As for how I came to be... Have you ever heard of the designation, CNT-65? Hehe, I'm actually a lot more knowledgeable than you would expect~♪",
	voice_key = 50209,
	headtouch = "Why don't you let me pat your head instead, Commander~",
	feeling2 = "The girls are saying that I can make any problem melt right away? Heehee... I think they're exaggerating a bit. I'm simply a good listener, nothing more~",
	login = "Good day. You seem to be in high spirits today, heehee. I'm sure today's work will go smoothly.",
	detail = "What's on your mind? If you're ever feeling indecisive, lost, or anxious about the future... you can always come talk to me~",
	couple_encourage = {
		{
			{
				50601
			},
			1,
			" You certainly have a different way of doing things.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[502091] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Oh my, the rivers converge here once more. Now then, Commander, what sights did you witness along your particular route? I'm simply dying to know~",
	unlock = "May blessings reach you this coming spring. Hm? My outfit? Heehee. Since the ever-so-busy Commander came to see me on this special occasion, I naturally had to put in some effort too– Now then, set aside all your worries, and come enjoy this wonderful evening with me~♪",
	touch2 = "Oh my... I know exactly what you're thinking~♪",
	mission = "",
	vote = "",
	drop_descrip = "May blessings reach you this coming spring. Hm? My outfit? Heehee. Since the ever-so-busy Commander came to see me on this special occasion, I naturally had to put in some effort too– Now then, set aside all your worries, and come enjoy this wonderful evening with me~♪",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "You've made me a very happy girl, you know? Look, we got to enjoy this wonderful scenery, and also shared this night cruise together... Hah, how nice it would be if we could be together like this... forever.",
	main = "Um... Ehh? There's a branch in the river up ahead? Should we go left... or right? I can't believe a strategist such as myself can get lost like this... Ugh, stop making fun of me already and help me figure out which route will be more interesting to traverse~|Come to think of it, the flower lanterns floating down the river are said to contain everyone's wishes for a smooth year to come. Seeing all the lanterns gathering around us like this makes me think that our relationship will follow suit as well... Heehee~♪|Oh, look~ There's a row of food stalls next to the pier over there. I have a feeling we'll be able to find lots of novel food! Want to head over there in a bit and buy something? Of course, I'd share with you~♪",
	touch = "Hmm? You'd like to share a flower lantern with me? Of course that's fine, but... you'll have to come sit in my lap~",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 502091,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, you're right on time. Hurry, let's enjoy a night cruise along the lively river~♪",
	detail = "How do you think our lovely little cruise will end? In the festive and bustling streets, in a wondrous display of fireworks, or amidst the endless lanterns illuminating the river? Let's take in all the sights and sounds until the very end, together. How does that sound? Heehee~",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[502092] = {
	hp_warning = "",
	feeling3 = "",
	mail = "You've got new mail... A call to new adventure, perhaps?",
	expedition = "The commission team is back. Let's get back to this after we've welcomed them, okay?",
	win_mvp = "",
	home = "You must be tired from your journey. Don't be afraid~ There's a soft, fluffy bed with your name on it right here.",
	unlock = "Phew... Fancy seeing the person of my dreams AFTER I've woken up! Heehee, if this is as fate decrees... Weary traveler, come to me and rest your tired legs.",
	touch2 = "Oh, my... This traveler is a naughty one.",
	mission = "Do you still have unfinished tasks? Heehee, then let me help you take care of them all. Then we can resume our fun...",
	vote = "",
	drop_descrip = "Phew... Fancy seeing the person of my dreams AFTER I've woken up! Heehee, if this is as fate decrees... Weary traveler, come to me and rest your tired legs.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Heehee... Destined partner, traveler from my dreams... If the fates so favor our love, then why don't you turn this sojourn into a permanent one? Let us weave a future together in this palace.",
	main = "I know you've seen much in your travels, but surely you must need a peaceful place of rest. Maybe here is the place for you to unload your burdens.|If you find this exposition plain, then why don't we do it over a game or an exotic meal... Oh? You don't want my cooking? Aww, but why?|Everything here is so perfect, yet I know that you will someday leave... Ah, how I wish you could stay...",
	touch = "Hm? Do you have a question for me? I'm happy to answer~",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 502092,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Your tenderness always warms my heart, Commander.",
	feeling2 = "",
	login = "Oh, it's you. Heehee, even the winds and sands can't stop my destined partner's arrival.",
	detail = "Oh? Do you find this whole \"traveler and nobility\" shtick a little awkward? But everyone dressed up for it! Relax and role-play a little, Commander.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[502100] = {
	hp_warning = "You dare underestimate me? I'll have you know, I drank ginseng root coffee this morning!",
	feeling3 = "Commander, are you trying to make coffee by any chance? Make sure the water doesn't get any hotter than 96 °C, or else the brew will go bitter. Wh-what are you looking at?! I just don't you to waste the coffee!",
	mail = "Commander, there's new mail for you. I'd urge you to read and reply as soon as possible.",
	expedition = "Looks like the commission fleet has returned. Shall I go bring them the sweets that I made?",
	win_mvp = "It's only natural that the victory is mine. Y-you were watching me closely, right?",
	home = "Welcome back, and good work out there. H-huh? Why am I being so nice to you all of a sudden?! I just wanted to say something nice b-because it looked like you were having a rough time! ...Hmph! I knew I should've just kept being strict with you!",
	unlock = "Please to meet you. I am Hai Yung. If you really are a first-rate commander, I assume you already know who I am? Huh? You don't? Hmph... Well, I'll have you understand sooner rather than later! In any case, if you need anything done, just leave it to me!",
	touch2 = "Eek! P-please stop that! They're not going to get any bigger no matter how much you touch! Even I know that!",
	mission = "Commander, you're not done with your missions, are you? ...It, it isn't because I'm concerned about you or anything! ...That's right! I have to keep a close eye on you because you're a known slacker!",
	vote = "",
	drop_descrip = "Hai Yung-class protected cruiser – Hai Yung.",
	feeling4 = "I've been craving sweets a lot recently, so let's look into why this might be happening... Craving sweets is often associated with falling in love...? Huh? Wait, does this mean I'm falling in love with the Com— Commander?! H-how long have you been here?!",
	lose = "Is everyone okay? Please pull back to avoid further damage!",
	feeling1 = "S-stop staring at my forehead already! I'll have you know, it's a trendy hairstyle! Got a problem with that? Hmph!",
	skill = "Watch me carefully, Commander!",
	upgrade = "Heh. Look, I'm even stronger than before. Try not to rely on me too much, got it? Well, umm... actually, it's okay to rely on me just a little bit!",
	propose = "I fully understand what you're trying to convey by giving me this gift. Which means, during these moments, I need to seriously and carefully consider your feelings and respond to them... So yes, I'd be glad to accept this. Thank you for accepting me for who I am... b-but it's too late for take-backs now, got it?! So hurry up and put it on already! Hmph!",
	feeling5 = "You want me to try being nicer to you? It's not like I'm trying to be particularly harsh with you or anything... Like, I'm pretty normal in front of everyone else, but when it comes to you... I get all nervous and my heart starts pounding real fast, and even if I try to be nice to you, I can't... I'm not normally like that at all, so it has to be all your fault! Hmph!",
	main = "The creativity of the desserts in this cookbook makes them all look so appetizing... What, you want to try them? O-of course I don't mind making these to share. M-maybe I'll make some for you too! Hmph!|Apparently, certain colors are associated with different emotions, so I've color-coded your files to help you organize them more effectively. See, watch me find exactly what you need— Wait, huh? No way... Is this method not useful after all...?|Hmph! Stop staring at me and focus on your work! Huh?! I wouldn't notice if I wasn't also staring at you? Wh-who would ever want to stare at you?! Hmph!",
	touch = "That's right, I came up with this fashionable ensemble all on my own! If you want some advice... maybe I could lend you an ear!",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Let's take it easy for now and have some honey water. I've been keeping this super-special honey stashed away for years! ...Huh? Expiration date? Honey doesn't expire... does it?",
	battle = "Commander, I... I want you to pay close attention to us!",
	id = 502100,
	gift_dislike = "",
	gift_prefer = "Th-this is so thoughtful... Hmph. Thank you.",
	profile = "I am Hai Yung of the Dragon Empery. I hope to be on good terms with everyone in this port. You? O-of course I intend to b-be on good terms with you! Just professionally, though! It's not like I want to be friends with you or anything! Hmph!",
	voice_key = 50210,
	headtouch = "Ermm... Wh-what's your deal? You're messing up my hair... H-hey, stop staring at my forehead!",
	feeling2 = "Chi An said that I'm always talking about you...? N-nonsense! Wh-why would I be going on and on about you in public anyway? Hmph!",
	login = "Welcome back, Commander. I hope you came to work ready to give it your all. Naturally, I'm already in tip-top condition.",
	detail = "I heard washing pots and pans with lemon water is good for removing stains... Huh? It'll just make them corrode faster?",
	couple_encourage = {
		{
			{
				50301
			},
			1,
			" So, help a girl out? What's trendy and fashionable these days?",
			0
		},
		{
			{
				19901,
				40211,
				20234
			},
			1,
			" Wanna go hang out after this?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[502101] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "There you are, Commander. I was just reading up on how a wider aperture lens is good for enhancing the atmosphere, making it easier to take close-up shots. Want to try taking some photos?",
	unlock = "Very well, Commander, I'll leave the photography to you. I entrust you to capture my grace and elegance and record it into memory! Just so you're clear though, th-this is just an outfit that's in vogue... It's not like I chose to wear it for you or anything!",
	touch2 = "D-did the design of my clothes catch your eye?",
	mission = "",
	vote = "",
	drop_descrip = "Very well, Commander, I'll leave the photography to you. I entrust you to capture my grace and elegance and record it into memory! Just so you're clear though, th-this is just an outfit that's in vogue... It's not like I chose to wear it for you or anything!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I've been putting a lot of effort into researching fashion and photography recently, and I look pretty good today as a result of that hard work, right? B-by the way, I heard that photos taken under maple leaves symbolize eternal love... I-it's not like I planned this out or anything! It's just something I happened to notice!",
	main = "Commander, why don't we take a photo together? Come a little closer then. The lighting here is the best... I-it's not like I made preparations for this or anything! Isn't that obvious? Hmph!|This place really is breathtaking, huh? Next time, I should invite the others as well... Hey, I never said I wasn't going to invite you! It's just... I already brought you here the first time, right?|You know what they say... \"You have to get closer to really make your photos pop.\" So, umm... Hey, Commander, can you come a bit closer? Just for the sake of the photos...",
	touch = "Oh, are you f-fixing my clothes? Thanks...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 502101,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Did you only notice my hairstyle? You really ought to appreciate my clothes more too! ...I, I just want to make sure my aesthetic sense isn't off, that's all! Hmph!",
	feeling2 = "",
	login = "You came at just the right time, Commander. The scenery here is quite wonderful, so how about going on a stroll with me to soak it all in? Though, umm... It might be a bit hard to move around in this dress... Wh-what do you think?",
	detail = "Hmm... If I raise my arms a bit and turn slightly to the side, I'll probably look slimmer...? Wh-what? I-I didn't say anything! I was just thinking of how to get the photo to come out better!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[502120] = {
	hp_warning = "Finally, a \"smell\" that stirs my interest.",
	feeling3 = "Perhaps I'll look different from what you imagine once I take off my silken mask. Heehee. Watch closely. This is my everything laid bare...",
	mail = "A letter has arrived from afar. Will you read it now?",
	expedition = "Commander, the commission team has brought back smells from afar.",
	win_mvp = "The aroma of victory is always so intoxicating.",
	home = "Stress causes one to emit an astringent, bitter odor akin to overly concentrated aromatic oil. You must rest adequately so your scent may return to its mellow state.",
	unlock = "I am Hai Chou, a perfumer from the Dragon Empery. The scent upon your person... is quite intriguing. I do hope our cooperation is fruitful.",
	touch2 = "Heehee... This is my favorite spot to test fragrances on. Do you not believe me? Then try smelling your fingertips.",
	mission = "There are missions awaiting your \"mixing,\" Commander.",
	vote = "",
	drop_descrip = "Hai Yung-class protected cruiser – Hai Chou.",
	feeling4 = "*sniff sniff*... Mmh... You have a deep and unique complexity, yet your essence is so warm... Truly, I can't get enough of it.",
	lose = "Gunpowder smoke and rust... Such bitter smells.",
	feeling1 = "My silken mask can block off not just unwanted smells, but pushy individuals as well.",
	skill = "Sink below the waves...",
	upgrade = "The line between perfume and poison is drawn by a minuscule difference in dosage.",
	propose = "Mmh... I wish to apply both my mixed perfume and my concocted \"poison\" on you... Hmm? The antidote? Why, that's me, of course♡ Ahh...",
	feeling5 = "My scent has already seeped into every little inch of your skin... There's no escaping it anymore.",
	main = "You smell exceptionally delicious today, Commander.|Turning a lethal poison into an alluring perfume – that is the art of a perfumist, Commander.|Now, repeat after me. Breathe in and let the fragrant mist diffuse... then slowly exhale. Feel my scent with your heart♡",
	touch = "Say, have you noticed that my fragrance has already filled the air around you?",
	voice_key_2 = -1,
	mission_complete = "A mission has been successfully \"mixed.\" Now just to take in the rewards.",
	battle = "This scent can chew through bone.",
	id = 502120,
	gift_dislike = "",
	gift_prefer = "This is a lovely present. I should make it up to you somehow... Heehee.",
	profile = "I am Hai Chou, a perfumer. No secrets elude my sense of smell. For instance, it tells me that your heart is throbbing right now, and that your body is releasing a sweet pheromone. I want it all to myself.",
	voice_key = 50212,
	headtouch = "Commander, if you continue this, I fear I may... Heehee♥",
	feeling2 = "It will take a little while for our scents to fully combine into one.",
	login = "You're here. Come closer... and let me imprint your scent upon my memory.",
	detail = "My silken mask? It blocks off unwanted smells and protects my olfactory sense. Thanks to it, I can better focus on your smell when I remove it.",
	couple_encourage = {
		{
			{
				50210
			},
			1,
			" Care to try my freshly made perfume?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[502121] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission team has returned. I've made a calming perfume, so bring it to them as a gift.",
	win_mvp = "",
	home = "You look rather tired. Since we have time, I'll keep you company a while longer. Now, come here...",
	unlock = "You're awake? Judging from your appearance... I wonder if our previous rendezvous has left you unsatisfied?",
	touch2 = "Since you're so passionate... I'll let you have your fun one more time♡",
	mission = "",
	vote = "",
	drop_descrip = "You're awake? Judging from your appearance... I wonder if our previous rendezvous has left you unsatisfied?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "Now... we can have all the fun we want.",
	propose = "",
	feeling5 = "Your love, your trust... It all serves as crucial inspiration for me, and I will let no one else have it. No one but me is allowed to fulfill your whole being♡",
	main = "I know that look. The fragrance of my specially made perfume has captivated you.|Something smells dangerous yet alluring, you say? Well, was it the danger that drew you in, or did you stay because of the allure?|You can try to feign composure, but your expression betrays you. Look here and here... You remember everything that I did.",
	touch = "Are you this clingy? Keep this up, and I won't be able to let you go... Commander♡",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 502121,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Huh? I'd just finished with my hair, and now you do this... Is it perhaps because you find me more alluring with my hair down?",
	feeling2 = "",
	login = "Did the curious smell on your person bring you back? ...Hm? You wish to savor it some more? Heehee. Your wish is my command...",
	detail = "The wrinkles on the bed, the lingering scent of perfume... They silently recount what took place prior, Commander♡",
	couple_encourage = {}
}


