_G.pg.base.ship_skin_words[503010] = {
	hp_warning = "It will take more than that to defeat me.",
	feeling3 = "I don't chat with you because I want to. I'm just concerned that you may not grasp my fashion principles. Still, I'll admit that having conversations with you is enjoyable.",
	mail = "It's time to check your mail. Don't forget.",
	expedition = "The commission team has returned on time. I'm concentrating on designing new fashion, so kindly fetch and inspect the supplies by yourself.",
	win_mvp = "It's over already? That was more fun than I anticipated.",
	home = "You've returned earlier than expected, so I assume your mission went quite well. Similarly, I've finished most of my work. I just need to review a few more... Oh, get me a cup of coffee, would you?",
	unlock = "It's a pleasure to meet you. I am Chien Wu. I take it you're this port's Commander? I see you're wearing a fairly elegant uniform, although it could be improved in a few ways. We have 30 minutes left for this meeting... That's just enough to tailor you a new set of clothes.",
	touch2 = "Interested in this, are you? Do you want to go a step further? Then you'll have to work for it♥",
	mission = "My schedule for later is packed, so make it snappy with those missions of yours.",
	vote = "",
	drop_descrip = "CNT-68 armored cruiser – Chien Wu.",
	feeling4 = "I'll fix your uniform, so hold still for a second. After all, I understand your appeal better than anyone else. There. Now you're all good.",
	lose = "Uncultured swine. This is not over, you hear me?",
	feeling1 = "Your naval cap is poorly shaped, your uniform's shoulders don't fit, and your pants are sagging... God, your fashion sense is just... Here, a list of proposed improvements. Take it and leave.",
	skill = "You're going nowhere, swine!",
	upgrade = "Allow me to demonstrate the perfect combination of fashion and power.",
	propose = "For me? It'll go well with my attire... Heehee. I suppose I've rubbed off on you, because your tastes are getting better all the time. Go on, don't just stand there – put it on my finger.",
	feeling5 = "As the times change, so do people's aesthetic tastes. I was once ready to chase the ever-changing trends of fashion... then you showed me something different: The truth that there is some unchanging beauty in the world.",
	main = "I'm busy. Whatever you want, it'll have to wait. Also, Commander, your schedule says that you should be focusing on your paperwork, not sitting here lounging around.|You want some fashionable and comfortable clothes, do you? Find someone else, then. It's not in my style to compromise for the sake of comfort.|Perfect clothing not only changes your outward appearance, it also gives you inner strength. As a professional, my every stitch and every thread must be flawless.",
	touch = "Is this your way of complimenting my attire? It's gorgeous, I know. I went through great pains to cut the cloth just... Pardon? It was ME you were complimenting?",
	voice_key_2 = -1,
	mission_complete = "Impressive – you finished your missions on time. A reward, you say? Heehee. I suggest finishing your work ahead of instead of on schedule next time. If you can manage that... Well, I'll consider a reward.",
	battle = "Our enemies? You mean those tasteless rubes?",
	id = 503010,
	gift_dislike = "",
	gift_prefer = "Thank you. You have good taste.",
	profile = "I am Chien Wu, of the Dragon Empery. Yes, I have little to speak of in the way of service history, but never mind that – just see me for who I am now.",
	voice_key = 50301,
	headtouch = "Is squandering time like this a hobby of yours?",
	feeling2 = "The moment you had the best sense? Good question. When you appointed me as your secretary, perhaps?",
	login = "You've arrived. I'll say, your fashion sense has improved somewhat. Keep wearing my suggested outfits and you'll be like a new person in no time. Heehee.",
	detail = "I'm designing the next season's fashion – do you have something to discuss with me? ...Not really? Alright, then could you fetch me the fashion magazine lying over there? Since you have nothing better to do.",
	couple_encourage = {
		{
			{
				90107
			},
			1,
			"You call those old rags \"clothing\"? Get rid of them and let me tailor something for you!",
			0
		},
		{
			{
				50104
			},
			1,
			"When designing clothes, you ought to incorporate new elements.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[503011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "I can't believe you're still this busy before the party. *sigh*... Take a break. There's some free real estate on your tuxedo, so I'll go get some accessories for you.",
	unlock = "There's still time. Let's set out once I've finished adjusting my dress... If you have nothing better to do, at least put on some tea.",
	touch2 = "If you want it that badly, wait until after the party. There'll be plenty of time then♥",
	mission = "We'll be late to the party at this rate, so get those missions done quickly. I'll help you... depending on how sincerely you ask for it, I suppose.",
	vote = "",
	drop_descrip = "There's still time. Let's set out once I've finished adjusting my dress... If you have nothing better to do, at least put on some tea.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "My outfit looks different to what you're used to? Well, I'm coming with you this time, so naturally I need to dress accordingly. While on the topic... Your tuxedo being eye-catching isn't as important as it matching my look♥",
	main = "If you have something to say, now's the time. I'm almost finished here, so I could certainly have a chat with you.|Oh? The train of my dress is a mess? It's hard to fix if I have to reach behind me, so give me a hand.|Tired, are you? While you're free to rest on the bed, you'll first have to take off your tuxedo. So it doesn't... get wrinkles, you know?",
	touch = "Are you trying to help adjust my outfit? Or... were you doing something else?",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Let's get going now.",
	battle = "",
	id = 503011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Do you like this accessory? I'll make a brooch version of it for you. It would go perfectly on that empty breast pocket on your tuxedo.",
	feeling2 = "",
	login = "You're here quite early. Judging by that look, this design of mine is a hit. Heehee♪",
	detail = "This perfume is your favorite? Good taste. It goes well with my dress for tonight, so I'll be sure to use it.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[503012] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Your tuxedo has too much going on, making it hard to take off? Sounds like a you problem. Fine, I'll help you take– Hey, you feel warm to the touch... Is that because you've drank, or is it... something else?",
	unlock = "Don't just stare – help me... Look, I meant that in the \"help me balance\" sense... Are you trying to take my shoes off?",
	touch2 = "Careful, or you'll ruin my... Hah! Kidding. The party has ended, so I'll let you have your way this time♥",
	mission = "Yet another mission? What a mood-ruiner... I'll give you 30 minutes. Finish it before then.",
	vote = "",
	drop_descrip = "Don't just stare – help me... Look, I meant that in the \"help me balance\" sense... Are you trying to take my shoes off?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Since we don't often get to spend time together, we should make the most of... Hmm? I stepped on my dress's train? Yes, I suppose keeping the dress on is inconvenient... Heehee. Were you expecting something different?",
	main = "Anything you want to do during our break? Depending on your answer, I might even let you do it to me♥|I put on high heels and sacrificed comfort for looks, so standing around for extended periods is pretty tiring... If you're not busy, might I ask for a foot massage, hmm?|You want to peel off my stockings? Ah, you and your tedious ideas... Fine, come here♥",
	touch = "Huh? Are you trying to mess with me? My, you've grown quite bold.",
	voice_key_2 = -1,
	mission_complete = "I see you completed a mission. Now your time is mine♥",
	battle = "",
	id = 503012,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Well, I'm off duty anyway, so I guess it's fine to be a little dishevelled.",
	feeling2 = "",
	login = "There is no work to be done, so I'm going to rest tomorrow... Say, if you're not busy, how about you stay the night?",
	detail = "Hey, Commander, you smell like my perfume... Perhaps we mingled a little too closely at the party.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[503013] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "You're a little late. Oh well – I used the time to tweak a few minor things anyway. Now, tell me what you think. I want to hear your first impression.",
	unlock = "Come here instead of staring blankly at the door. It took me all night to tailor-sew these details. It should perfectly meet everything you requested... Come closer and I'll listen to your important feedback before anything else.",
	touch2 = "Mgh... Seems I've more than met your expections...",
	mission = "Don't you still have missions left? Go and get them done. I'll reserve your observation session for when you come back.",
	vote = "",
	drop_descrip = "Come here instead of staring blankly at the door. It took me all night to tailor-sew these details. It should perfectly meet everything you requested... Come closer and I'll listen to your important feedback before anything else.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "If you don't have any feedback, then could you acknowledge this special permission I've granted you? Carefully memorize the aesthetic, the texture, and the feel in your heart and on your fingertips... Okay?",
	main = "Designing the back straps took quite a lot of work. Now, I'll give you a chance – feel it with your fingers, then give me your appraisal.|Why aren't you saying anything? Can't find the right words? Or are you so content that you're left speechless? Use your words. I don't like having to guess.|Take a seat and observe again from this angle. Appreciate how it fits and how it looks from new angles and different lighting. Oh, and don't rush it with your feedback. We have plenty of time.",
	touch = "Heehee... You have a keen eye. Yes, I paid special attention to this design.",
	voice_key_2 = -1,
	mission_complete = "You finished your missions? Excellent. Let's resume our observation session, then.",
	battle = "",
	id = 503013,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Hah... Is this your way of expressing affirmation? I'll graciously turn a blind eye to it this time.",
	feeling2 = "",
	login = "Finally, you're here. Do you know what you should do? Put on some coffee, first of all. Straighten up. You don't have all the time in the world to watch from the side.",
	detail = "Come closer... That's it – you can see all the fine details at this distance. Heehee. Seems like you grasp the meaning of the hidden design elements – right, Commander?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[503020] = {
	hp_warning = "A maidenly jewel shatters – bone-chilling cold awaits.",
	feeling3 = "They say that warm jade is smooth and soft... It reminds me of you.",
	mail = "Mail? I hope the jade I ordered came in...",
	expedition = "I prepared hot water and food for the commission team. It may not be much, but I hope they understand... it's the thought that counts...",
	win_mvp = "Even stones with natural beauty must be carved to reveal their true splendor.",
	home = "Are you tired? Come, lean on me and rest for a while... May my warm embrace ease your weariness, if only a little.",
	unlock = "I am Chang Wu, a jade carver from the Dragon Empery. Having crafted countless pieces of jade, I considered myself wise and knowledgeable... until I glimpsed your elegance and eminence. Thus, I have come to realize... that what I considered treasures, are naught but stones.",
	touch2 = "Commander, um... Moderation, you know...",
	mission = "Commander, there are still some uncut jade waiting for you to carve them.",
	vote = "",
	drop_descrip = "6,000 ton-class cruiser blueprint – Chang Wu.",
	feeling4 = "I carved this pendant while recalling the warmth of your hands. Do you think I've managed to replicate your warmth?",
	lose = "Broken jade can still be carved anew... and this failure is much the same.",
	feeling1 = "A dust-covered jade can be polished, but what of a neglected heart? Ugh... Forget it.",
	skill = "With one stroke, a gem is carved – its brilliance revealed.",
	upgrade = "There's no need to hide the sharpness of my skills any longer.",
	propose = "The contract is sealed. Now I shape not jade, but a heart – I'll be by your side forever, bringing warmth and comfort like a treasured jewel...",
	feeling5 = "An uncut gem requires a master's touch to truly shine. Tell me, Commander... Do you know the passion you've ignited within me?",
	main = "Commander, new jade has just arrived on the market. Care to appraise it with me? If you find any you like, I'll negotiate on the price.|This jade is lustrous and radiant, like your eyes when you're lost in thought... Ah, I'm sorry. I misspoke...|My jade collection could fetch a very pretty penny, but I would never give them to someone who doesn't know their true value. Basically... Umm, could you help me bear the expenses of maintaining my collection?",
	touch = "Even when appreciating fine jade, one must adhere to certain principles...",
	voice_key_2 = -1,
	mission_complete = "Mission complete. I'm sure the rewards won't disappoint.",
	battle = "This battle is but part of the carving process...",
	id = 503020,
	gift_dislike = "",
	gift_prefer = "Excellent quality. I knew you were a fellow connoisseur, Commander.",
	profile = "I am Chang Wu, a heavy cruiser of the Dragon Empery. Tell me, Commander – in your eyes, am I worthy of being considered a precious gem?",
	voice_key = 50302,
	headtouch = "Your touch... Are you trying to share your warmth with me, a cold jade?",
	feeling2 = "Pardon me... When I see a true gem of a person, I can't take my eyes off of them.",
	login = "The tea's aroma is just starting to fade, but the leaves are still warm. You came at the perfect time, Commander.",
	detail = "Commander... Are you looking at me as a person, or are you sizing me up like a jewel?",
	couple_encourage = {
		{
			{
				50301
			},
			1,
			" I don't need such elaborate accessories. A single jade pendant will suffice.",
			0
		},
		{
			{
				51901
			},
			1,
			" I understand, budgeting is important... but how can I say no to a gem that touches my heart?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[503021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission team is back. Commander, go and greet them now... but don't forget about the romantic mood in here, okay?",
	win_mvp = "",
	home = "When I saw the sky getting dark, I knew you'd come back soon.",
	unlock = "Serene is this room, and pleasing is this plum-blossom fragrance, yet... why are you yet to come inside? Here, the aroma of flowers is rich, only awaiting the arrival of the spring breeze—",
	touch2 = "Even for an appraisal, this is... Ah... Mm...",
	mission = "",
	vote = "",
	drop_descrip = "Serene is this room, and pleasing is this plum-blossom fragrance, yet... why are you yet to come inside? Here, the aroma of flowers is rich, only awaiting the arrival of the spring breeze—",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "See the fallen plum blossoms... Commander, will you cherish them? This scenery, this night, and our feelings...",
	main = "Which seems more disheveled? The branches by my bed, or my hair...?|Commander, would you say... that the scenery before you is worthy of a closer look?|I've guarded these plum branches from dusk 'til night, such that you might view them... and me as well, of course...",
	touch = "Hmm? That technique... Are you trying to polish your favorite jewel?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 503021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Your hands are always so warm...",
	feeling2 = "",
	login = "Which will you embrace, Commander? These plum blossoms, or me?",
	detail = "Forget work for a while... Let's watch the plum blossoms scatter and enjoy a moment's peace together.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[504010] = {
	hp_warning = "...Surely I can muster more than this!",
	feeling3 = "Heehee. It's rare to see you have spare time on your hands... Would you like to enjoy some sweet osmanthus wine with me? Though, this particular cup has been made to suit my tastes– C-Commander?! How come your eyes are glazing over after just one sip...?! Even though I only added half a jar of sugar...?!",
	mail = "I've sorted through the mail for you. I've set the important material aside, so please make sure to look over it.",
	expedition = "Commander, you should go welcome back the girls in the commission fleet. I've prepared some thank-you gifts for them, and would appreciate if you... I-it's not like I'd be too embarrassed to deliver them myself!",
	win_mvp = "And thus, heaven's will be done. A splendid victory indeed.",
	home = "Kun above, Zhen below. Obstacles give way, and good fortune arrives. ...See, I performed a divination for you, and you've returned safe and sound.",
	unlock = "I am Huan Ch'ang, battlecruiser of the Dragon Empery. And you must be the Commander I've heard so much about? Now that I've seen you in person... Heehee. Does your mettle measure up to your vaunted name? Very well. Allow me to be the judge of that.",
	touch2 = "Today's reading said that prurient acts shall be met with terrible fates. Are you sure you wish to continue with that?",
	mission = "Here's a list of today's missions. You said you intended to knock everything out right away, so–– Where shall we begin?",
	vote = "",
	drop_descrip = "1913 Naval Expansion Project 26,000-ton battlecruiser – Huan Ch'ang.",
	feeling4 = "Sometimes, I wonder if I, as an unfinished ship that was nothing more than a plan, can truly be of use... With no history to speak of, I often feel as if this power I possess is nothing more than a fleeting dream... Will I truly be able to protect everyone? Will I truly be able... to protect you?",
	lose = "...What a miscalculation. I was one step behind.",
	feeling1 = "Looks like you're not what you were chalked up to be. Though, I never should've expected anything greater in the first place.",
	skill = "Break their formation, and cut off their command!",
	upgrade = "Heehee. This power... shall become your sturdiest pillar.",
	propose = "This has to be... some kind of prank, right? Wait, no... Xun above, Gen below... To a young lady, congratulations are in order... Huh? Are you serious? W-wait, give me a moment to process this... Um, ahem... C-Commander, thank you... For accepting my weaknesses, for taking my hand and granting me new strength... F-from now on, we'll always be together, until the icy depths do us part.",
	feeling5 = "I try to come off as strong and confident to others, but around you, I can finally take my mask off and reveal my weaknesses and insecurities... How strange it all is... Commander, do you mind if I stay like this for a bit longer? Your embrace... is so very warm.",
	main = "Though I use these hexagrams to divine heaven's will, such results are not to be believed blindly. After all, there exist special individuals who can challenge destiny. And you, Commander, are one such individual.|Remain patient, and do not sway even in the face of change. As the situation develops, your opportunity will inevitably arise... Huh? You don't think this reading is accurate? You want to know how it pertains to the r-relationship between us? ...Th-the result probably wouldn't change!|Fu Shun and Fei Yuen are such energetic girls... It's n-not like I'm trying to dote on them or anything. ...Huh? I always give off different vibes around them than when I'm with you? I mean, those girls are my family, and you, umm... I guess you kind of count too?",
	touch = "...If you don't need anything from me, I will return to my training.",
	voice_key_2 = -1,
	mission_complete = "Here are the rewards for completing our objectives. Please take a look, Commander.",
	battle = "From glyphs sixfold, all principles arise. Master them, and all of creation is yours to command.",
	id = 504010,
	gift_dislike = "",
	gift_prefer = "Hm. You went all-out just to flatter me...",
	profile = "I am Huan Ch'ang, battlecruiser of the Dragon Empery. Though the past cannot be rewritten... Kun above, Kan below – success in all things to come... Heehee. I took this opportunity to divine the future, and I see only good things to come.",
	voice_key = 50401,
	headtouch = "...Ahhn~ W-wait, I'm not some child who needs to be comforted...",
	feeling2 = "Commander, I've brought you today's itinerary. Please take a look– Why, yes. Underneath that is my personal schedule... Hmm? Why do I have so many additional training sessions? That's because... it's far too soon to start becoming complacent.",
	login = "You've returned? I've already placed today's itinerary on your desk, and stand ready for any operation– Hm? I've done well to prepare for a rainy day? It seems rather inappropriate to praise me with such words given the situation at hand?",
	detail = "You'd like to get to know me better...? Just know that what I am about to tell you can be either fact or fiction. One's heart is not something that can be penetrated so easily~",
	couple_encourage = {
		{
			{
				59901
			},
			1,
			" Harbin, hands off my osmanthus wine!",
			0
		},
		{
			{
				50105
			},
			1,
			" Shhh! Don't tell the Commander that I don't like bitter or spicy food!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[504011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Alas, how can the light from fireflies above rotten grass ever compare to the brilliance of the moon above?",
	home = "Congratulations on the successful operation, Commander. Let me do a quick inspection... Mm. Everything looks fine. Just a bit of soot on your clothes, but otherwise... thank goodness you've returned safely.",
	unlock = "Happy New Year, Commander. Hmm? I look a bit different from usual? Why of course, it's because it was chosen to suit your tastes by none other than Chi An. Even this mask is brand new. I look \"like a fairy from the sacred mountains,\" you say? I wonder... who taught you to say something like that?",
	touch2 = "Heehee~♪ Right here? How bold... and awfully reminiscent of a certain Empery ghost story~",
	mission = "",
	vote = "",
	drop_descrip = "Happy New Year, Commander. Hmm? I look a bit different from usual? Why of course, it's because it was chosen to suit your tastes by none other than Chi An. Even this mask is brand new. I look \"like a fairy from the sacred mountains,\" you say? I wonder... who taught you to say something like that?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Hmm? Am I cold in this outfit? Not particularly~ See, take my hands – warm, aren't they? That's just how I'm built. If you're cold, however... You're always welcome to come give me a hug~",
	main = "Hm? Why did I choose this spot? ...B-because, it's embarrassing to be in this outfit! I wanted to go somewhere without a lot of people, but before I knew it, I made the place seem as if it was haunted...|You brought me some warmed osmanthus wine? Ehehe... I'll be helping myself then~ Eep! Hot! D-don't say a word about this to anyone, you hear? I totally do not have a sensitive tongue!|I made some new masks to match my new outfit, but I can't decide on which one to wear... Oh, I know! Why don't you help me pick one out?",
	touch = "Hmm? If there's anything you need me for, please do not hesitate to let me know. Anytime, anywhere.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 504011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Welcome back, Commander. Hm? You think that I tend to give off rather... grim vibes? My apologies. I'll try to be more mindful of that in the future...",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[506010] = {
	hp_warning = "Nothing ventured, nothing gained...!",
	feeling3 = "War isn't fair. Backstab your enemy. Think two or three steps ahead of them, read their every move. Then... BAM! Victory comes just like that. Hehe.",
	mail = "A competent commander should never neglect potentially important information.",
	expedition = "The commission fleet is back, huh... Increasing our stockpiles, replenishing our forces, adding another card to our hand. A good play indeed.",
	win_mvp = "The enemy has lost their will to fight. Heh, guess that's all they had to show.",
	home = "Good job on making it back in one piece. I went over your last battle, and while it was excellent overall, there are many areas that can still be improved... So let's review those right now?",
	unlock = "So you're the brains behind the operation here, huh? ...Hehe, I finally get to meet the legendary Commander face-to-face. It's an honor to be able to work with you. I trust you'll live up to your lofty expectations?",
	touch2 = "You certainly have guts.",
	mission = "Don't forget to finish up your missions. When it comes back to bite you in the ass, it'll already be too late.",
	vote = "",
	drop_descrip = "Seaplane carrier - Chen Hai.",
	feeling4 = "I'm starting to get bored of our regular old sessions of Go. Let's spice things up a little bit... I know just the thing. How about, if you can take a game off me, I'll grant you one wish.",
	lose = "Ugh, just one move behind... While I hate conceding defeat, there won't be a next time. Hehe...",
	feeling1 = "Seems like I set the bar too high for you.",
	skill = "Exploit their weaknesses, and catch them by surprise!",
	upgrade = "I prefer being the one pulling the strings, but fine.",
	propose = "What's this? ...Hehe, I didn't expect this sneak attack from you... Or rather, you're the only person who could pull something like this off. Looking at it that way, maybe I had predicted this all along... right?",
	feeling5 = "Oh my, how could a seasoned strategist like me make such a silly blunder... Hehe, in any case, congratulations on your win. As promised, I'll grant you your one wish. Anything goes. Hehehe...",
	main = "Are you deep in thought about something? Or... just spacing out? Oh, I see. You're trying to look cute, hehe.|My eyes look a bit scary when I'm thinking about something? ...How do you know that isn't just one of my many faces?|Feign strength if you must, feign weakness if you must. Whatever the case, do not ever let your enemy see through your trump card.",
	touch = "What's the matter? ...You're not here just to have a little chat, are you?",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Now that you've removed another obstacle in front of you, what will your next move be?",
	battle = "The moment the enemies let their guard down–– is the moment you strike!",
	id = 506010,
	gift_dislike = "",
	gift_prefer = "This gift comes from the heart, doesn't it? I shall graciously accept it.",
	profile = "I am the Dragon Empery's first seaplane carrier, Chen Hai. I've received many other \"firsts,\" but those aren't exactly honors. I still have a long way to go before I can match up to real aircraft carriers.",
	voice_key = 50601,
	headtouch = "I must say... this behavior is rather unexpected.",
	feeling2 = "The more you win, the harder it'll be for you to review your own moves objectively. Even if you're winning, never forget to continue studying your past experiences.",
	login = "How's the port supposed to run when the decisionmaker's seat is vacant? C'mon, sit down already.",
	detail = "If you're not busy, then... come here, let's play a match of Go? No need to have a turn timer or keep track of winners and losers. Let's just kill some time, hehe.",
	couple_encourage = {
		{
			{
				50204,
				50205,
				50208
			},
			1,
			"My, some familiar faces.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[506011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "A letter arriving at a time like this? Talk about spoiling the mood...",
	expedition = "",
	win_mvp = "",
	home = "\"Yes, excellent. Just stick to the plan, just as I told you.\" Oh, welcome back. That phone call...? It's a secret~",
	unlock = "You're here, Commander, just as promised. How do you like the atmosphere in here? Hehe, take a seat and enjoy the tea slowly. After all, we have plenty of time~",
	touch2 = "It would appear that you need a reminder as to who the host is here.",
	mission = "Commander, you're currently my guest. The fact that you're still preoccupied with work does not impress me.",
	vote = "",
	drop_descrip = "You're here, Commander, just as promised. How do you like the atmosphere in here? Hehe, take a seat and enjoy the tea slowly. After all, we have plenty of time~",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Do you know what I value most of everything inside this room? It's not the luxurious interior or my opulent collections – Indeed, it is none other than you, Commander~♪",
	main = "I already have a worthy opponent in front of me, but too bad we don't have a Go board and some pieces to play with... Ah, but worry not, I'll fetch them later.|Commander, what's your favorite collection here? Porcelain? Jade? Calligraphy? Or perhaps... this entire estate? Hehe~|Hai Chi's flower spear and Chao Ho's solo dance... Tonight's performance will be spectacular indeed. It would be nice to have someone accompanying me who has a fine eye for the arts... Do you understand what I'm getting at, Commander?",
	touch = "Would you like to try this rotary dial phone? You might not be used to operating something like it, so try to be careful not to make mistakes.",
	voice_key_2 = -1,
	mission_complete = "Oh my, when did you complete your missions? Not too shabby, Commander.",
	battle = "",
	id = 506011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Do be mindful of who the host is, and who the guest is~",
	feeling2 = "",
	login = "Now that you're here, please make yourself at home. Don't worry, Commander, this one's on me.",
	detail = "Did my collection catch your eye? Hehe, very well, there's a lot more of that in the back room. I wouldn't mind showing you around if you'd like~",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[506012] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "You're completely soaked with sweat... I see, the sweltering heat outside must've taken its toll on you. Come in, and cool off.",
	unlock = "Oh my, if it isn't the Commander... Have you also come to escape the heat? What a serendipitous meeting... Or, did you perhaps have some other goal in mind? Heehee...",
	touch2 = "Oh my, Commander. You're a bit lacking in self-control~",
	mission = "",
	vote = "",
	drop_descrip = "Oh my, if it isn't the Commander... Have you also come to escape the heat? What a serendipitous meeting... Or, did you perhaps have some other goal in mind? Heehee...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "...So, do you have any plans today? No games, no bartering. Just the two of us - alone on a day off. You have all the initiative in your hands, Commander. You're not going to let it go to waste, are you? Hehe...",
	main = "Come with an open heart, and leave fulfilled. Now that you've freed yourself from the shackles of the daily grind, clear your mind and enjoy this occasion to the fullest~|Hai Chi? I'm sure she's playing in the water with some friends she just met. Did you want to go look for her?|Ripples in the water, the glow of the autumnal sun, and the flickering of rainbows... If Hai Tien were here, I'm sure I would be hearing one of her poems.",
	touch = "What's the matter? If it's about work, let's save it for later, alright?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 506012,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "During this moment of respite, set aside all your plans and calculations. Once you've rested sufficiently, you can always pick up where you left off.",
	detail = "Few things are more blissful than a refreshing soak on a sweltering day. Your clothes might get wet, but... don't you think it's well worth it?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[506013] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Good work, Commander. Once I'm done with my handiwork here, I will play for you a song of victory.",
	unlock = "Oh, Commander, have you come to see me? Yes, as you can see, I've been studying the art of embroidery– Just like Go, it helps me organize my thoughts and see things from a broader perspective. Why don't you give it a try as well, Commander? Heehee~",
	touch2 = "You still require some work when it comes to self-discipline.",
	mission = "",
	vote = "拉票描述",
	drop_descrip = "Oh, Commander, have you come to see me? Yes, as you can see, I've been studying the art of embroidery– Just like Go, it helps me organize my thoughts and see things from a broader perspective. Why don't you give it a try as well, Commander? Heehee~",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "The embroidery I hold here is my \"gift\" to you. I'm not good at expressing my emotions, so I'd like to take the opportunity to do so using this handkerchief... Hm? You'll carry it with you at all times? Heehee. I'm overjoyed to hear that.",
	main = "Maybe playing Go in a serene place like this will allow me to hone my skills even further... Commander, if you have time later, would you mind having a match with me?|\"Beautiful embroidery draws the orioles from their willowy perches\" ...How profound. I still have a long way to go when it comes to this art.|The art of embroidery requires the patience to make precise stitches, just as strategizing requires the patience to make precise decisions...",
	touch = "Hmm? Are you interested in my Three-Azures embroidery?",
	voice_key_2 = -1,
	mission_complete = "Looks like you've completed your mission with no issues. Please rest here for a moment. I'll have your gift ready shortly.",
	battle = "",
	id = 506013,
