_G.pg.base.ship_skin_words[506018] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome back, Commander... A strategist such as I ought to act with moderation, but I could not hold back the desire to see what face you would make when you lay eyes on me... And yes, I saw just what I expected I would. Heehee.",
	unlock = "With the red veil lifted, join me and let us sip of this nuptial wine to celebrate our union. As for how we are to spend the rest of this day... I leave that to your discretion, Commander. What say you?",
	touch2 = "A strategist such as I must never be taken off guard... But this time, it's my turn to be on the offensive.",
	mission = "",
	vote = "拉票描述",
	drop_descrip = "With the red veil lifted, join me and let us sip of this nuptial wine to celebrate our union. As for how we are to spend the rest of this day... I leave that to your discretion, Commander. What say you?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "They say the wise must never allow themselves to be held captive by love. I used to agree... but now, nothing brings me greater joy than planning the rest of my life by your side. I look forward to our future together, my Commander... My beloved.",
	main = "\"May I be your star, and you be my moon, our lights shining bright together every night...\" Have my feelings gotten through to you, Commander?|I have simulated many possible futures with you by my side, Commander... But the way my heart is racing now defies all of my calculations.|I once thought myself an unrivaled strategist. Yet I now realize my most brilliant scheme of all... was making your heart throb for me alone...",
	touch = "My only wish is for us to grow old together, hand in hand...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 506018,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "You are allowed to lift this red veil only once... Because what comes after that is what truly matters.",
	feeling2 = "",
	login = "I have been expecting you, Commander... This is a touch different from how I usually carry myself... Heheh, I am glad you like it.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[506019] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Phew... Finally, peace and quiet can return once more.",
	home = "A triumphant return. Your commanding back there was simply unparalleled. Now then, Commander, please unwind while enjoying this tea.",
	unlock = "Just as promised, I present myself before you in a brand new form. Heehee... Since we have plenty of time, why don't you come take a seat, enjoy the fragrance of tea with me, and envision our future?",
	touch2 = "Ahaha... I can't believe I'm being manhandled in such a frivolous manner... Commander, I'll have to extract some \"compensation\" from you in return~",
	mission = "",
	vote = "",
	drop_descrip = "Just as promised, I present myself before you in a brand new form. Heehee... Since we have plenty of time, why don't you come take a seat, enjoy the fragrance of tea with me, and envision our future?",
	feeling4 = "",
	lose = "Haha... You may have bested me fair and square this time... But next time, your luck won't last.",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "You know, I've been thinking... If I really went to live in the mountains, I'd like the two of us to find a nice place with beautiful scenery, build a home of our own, and grow old together in a peaceful world. We'd enjoy tea between rounds of Go, spending our time leisurely without a worry in sight... It might be a bit early to contemplate these things, but I look forward to that day with all my heart.",
	main = "In retrospect, triumphing over others and triumphing over yourself are two completely different things... Simply scratching the surface of my \"self's\" limits was enough to give me an awakening.|I would like to see with my own eyes what kind of world the peaceful paradise you envision is like.|A world in turmoil calls for a schemer with a number of tricks up her sleeve. A world at peace, however, calls for honest, hardworking builders. When that day comes, I will take my leave and retire to the mountains. Such a life suits me better. Haha...",
	touch = "Commander, care for a round of Go? Just treat it as some light entertainment on the board game known as \"life,\" okay? Heehee.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 506019,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Hmm...? My, it looks like I've finally caught you dozing off, Commander. Heehee. So, how was it? Did you have sweet dreams? If you don't mind, I'd love it if you could share what you saw with me~",
	detail = "Heehee... With so many reliable allies here, victory or defeat start to seem less important to me than the contents of tonight's menu.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[506020] = {
	hp_warning = "Ugh, I let my guard down...",
	feeling3 = "So, not too long ago, I went to a haunted house with my friends for the first time. Pretty cool and all, but the best part was seeing the looks of panic on everyone's faces. Tell me, Commander, are ya 'fraid of ghosts?",
	mail = "New mail's in. Come to think of it, Commander, don't you get invited to all sorts of events? Think you can bring me along next time?",
	expedition = "The friends from the commission fleet are back. Wanna throw a little party for them?",
	win_mvp = "Heh. The character \"Jah\" in my name symbolizes number one. Quite apropos if I must say so myself.",
	home = "Hmm? Commander, what were you doing just now? Don't tell me you were off partying behind my back... Heehee, just kidding~",
	unlock = "Commander, it is an honor to meet you. I am Hwah Jah of the Dragon Empery. Now that it's just the two of us here, I'll get straight to the point – Ahem... Is there, um... anything, y'know, super exciting or fun going on around these parts?",
	touch2 = "So basically, I'm allowed to exercise self-defense now, right?",
	mission = "I've heard that some missions can be quite fun. Commander, mind if I tag along next time?",
	vote = "",
	drop_descrip = "Seaplane carrier – Hwah Jah.",
	feeling4 = "After hanging out with my buddies for a while, I've come to realize that it's pretty hard to stand out from the crowd... But, maybe there's some way of getting a head start– Hmm? Oh, I was just talking to myself, so don't worry too much about it. By the way, Commander, you interested in what the girls have been saying about you lately?",
	lose = "I'll remember this humiliation... and pay it back twofold!",
	feeling1 = "No matter what happens, life must continue on. Just let it go...",
	skill = "If you won't listen to reason, then you can talk to my fist!",
	upgrade = "I won't let you down, Commander. Not after the goodwill you've shown me.",
	propose = "I don't expect to occupy the front and foremost spot in your heart; but seeing as how the two of us have exchanged vows, I will be very, very angry should you run around and desert me. So angry, in fact, that I have no idea what I might do. Heehee. But, it's simple, really. Just be good to me, Commander~",
	feeling5 = "After knowing me for so long, you should already be aware that I'm not actually that well-behaved. As for the reason why... That'd be your fault, Commander. Aren't you the one who introduced me to so many ways of \"acting up?\" Heehee~ In other words, I'll need you to take responsibility~",
	main = "Commander, how do you normally reward yourself? Maybe binge out on a sumptuous meal? Or stay up late playing around? As for me, I... Err, I just wanted a point of reference, yeah!|Be courteous to others so that they will listen to you respectfully. As for those unwilling to give you that respect, there are always more \"direct\" methods you can employ~|Mapo tofu? There are hundreds of ways of preparing tofu, and there's no rule saying it has to be spicy. Besides, I'm not great with spicy food...",
	touch = "Meh, don't sweat it. Even if I slack off right now, nobody's gonna find out.",
	voice_key_2 = -1,
	mission_complete = "Mission complete. So, does that mean I can shoot the breeze for a while?",
	battle = "In other words, we can go all-out now, right?",
	id = 506020,
	gift_dislike = "",
	gift_prefer = "I'll always remember this kindness.",
	profile = "I am a seaplane tender of the Dragon Empery, just like Chen Hai. Unfortunately, my treasured blade was never completed, and I was condemned to a life of mediocrity... But let's not dwell on my dark past. Commander, didn't you promise that the two of us would find lots of fun things to do?",
	voice_key = 50602,
	headtouch = "Commander? Is this my reward for being a good girl? Heheheh...",
	feeling2 = "People are always gonna be hesitant to let someone barge into their group, no matter how cordial you try to be. Luckily, I know someone who can help me make some inroads with the folks here. Isn't that right, Commander? Help a buddy out, won'tcha?",
	login = "Commander, are you still working? ...C'mon, let's play hooky. A little bit of fun won't kill you~",
	detail = "That reminds me, a while ago, I raised my hand to try to join one of the Eagle Union girls' parties, but they all looked at me like I was crazy... Is there anything wrong with that?",
	couple_encourage = {
		{
			{
				50601
			},
			1,
			" Would you please teach me how to use a seaplane?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[506021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Boo! ...Guess I couldn't spook you at all, Commander. Maybe I should take a page from Fu Shun's playbook next time and bring a flashlight...",
	unlock = "I am Hwah Jah, now in zombie form. It is an honor to see you– hmm? What's wrong, Commander? Everyone else is getting dressed up for the occasion, so I figured I'd get in on the action too... Is there something wrong with that?",
	touch2 = "You're gonna be cursed if you remove the seal...",
	mission = "",
	vote = "",
	drop_descrip = "I am Hwah Jah, now in zombie form. It is an honor to see you– hmm? What's wrong, Commander? Everyone else is getting dressed up for the occasion, so I figured I'd get in on the action too... Is there something wrong with that?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "The mandarin duck hotpot, as its name implies, is a special hotpot for couples... Just kidding. Actually, this partition is just to accommodate people's different tastes.|Hmm? Hai Tien made an incredibly spicy baozi? I sure hope she marked it properly...|The jiangshi in the movies all hop around due to the whole rigor mortis thing. So, it's kinda like this... hip, hop. Err, umm... this feels a little inappropriate.",
	touch = "I'm not actually dead, y'know, so I can't just make my hands turn ice-cold.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 506021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "You're back? Let's go find our other friends and see if they're up to anything interesting.",
	detail = "Hmm? You think this outfit's a bit too revealing? Weird. I thought it's pretty in line with what everyone else is wearing... Besides, what's wrong with standing out a little?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[506022] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "I'm wondering what accessory would go best with this outfit. Do you have any suggestions for me, Commander?",
	unlock = "Oh, Commander. I'm just doing some last-minute tidying up before the trip. By the way, I've never shown you this lacquered jewelry box, have I? It's one of my most prized possessions. Go on and take a look. Shall we go on a deep dive into its many wonders together?",
	touch2 = "Hyah... Try not to jostle the table, okay?",
	mission = "",
	vote = "",
	drop_descrip = "Oh, Commander. I'm just doing some last-minute tidying up before the trip. By the way, I've never shown you this lacquered jewelry box, have I? It's one of my most prized possessions. Go on and take a look. Shall we go on a deep dive into its many wonders together?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Lacquerware cradles pearls and jade just as the courtyard cradles the splendor of spring. Similarly, I made space in my heart for a one-of-a-kind treasure... I mean you, of course.",
	main = "The true beauty of lacquerware lies in the time and care it takes to bring forth its captivating sheen... It's a lot like human relationships, don't you think?|\"Though I've scored a thousand trees in pursuit of lacquer, my jar has yet to fill.\" Collecting lacquer demands great effort – we must cherish each and every artisanal piece.|Do I look excited for our next trip? That's because I am! You and I might just discover the perfect view for my next lacquerware piece, after all!",
	touch = "Come and feel the texture of this lacquerware for yourself. I think you'll love it♪",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 506022,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Whoa... You're even more mischievous than me, Commander~",
	feeling2 = "",
	login = "You've got a sharp eye, Commander – you noticed my treasure in no time. It took over a hundred polishings and the addition of powdered shells and gold leaf to bring out such refined, understated luster.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[506029] = {
	hp_warning = "",
	feeling3 = "",
	mail = "New mail? Hopefully we get an invitation to do something fun and exciting, rather than the usual boring administrative stuff. Wanna go through it together, Commander?",
	expedition = "The commission team's back? Perfect, I've just finished preparing their thank-you presents. Pretty awesome timing on my part, huh?",
	win_mvp = "",
	home = "Finally back, Commander? So, I found a fun-looking place that seems pretty promising... If you're not too busy, wanna come with? I think we could both go for a change of pace, right?",
	unlock = "As you can see, Commander, I've completed my retrofitting. So, umm, are you surprised by my new appearance? Don't worry, though. I'll always be the same Hwah Jah you know and love~ Though, if I had to pick something different about myself... I might be a bit more open towards some fun and exciting things~♪",
	touch2 = "Um... Are you testing how \"open\" I'm willing to be?",
	mission = "Got something fun and exciting for me to do? Lemme give you a hand, just as always~♪",
	vote = "",
	drop_descrip = "As you can see, Commander, I've completed my retrofitting. So, umm, are you surprised by my new appearance? Don't worry, though. I'll always be the same Hwah Jah you know and love~ Though, if I had to pick something different about myself... I might be a bit more open towards some fun and exciting things~♪",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I might have changed in certain regards, but you like me this way as well, right? Heehee. After all, this is what I've picked up from following your \"guidance\"~♪ Now then, I hope you'll continue to take on the responsibility of looking after me in the future, yes?",
	main = "Oh, Commander! If I ever get the opportunity to open a teahouse, I'd like to incorporate some elements of street performance, like fire jugglers! Wouldn't that be a great way to attract customers? Huh... you think that'd spoil the entire atmosphere?|I still believe in treating others with courtesy and speaking with sincerity, just as always. However, I think I can be a bit more \"persuasive\" now towards those who don't want to sit down and have a civil discussion~|Ultra-spicy hotpot? Haha... Sure, I did say I'm more receptive to new experiences than before, but... I'm afraid I'll have to pass on that one...",
	touch = "Hmm? Wanna head outside and shoot the breeze?",
	voice_key_2 = -1,
	mission_complete = "Hmm? All done with work? Heehee. In that case, if you have nothing else scheduled, how about letting me suggest something?",
	battle = "",
	id = 506029,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Oh my... Does this mean I've been an extra good girl recently? Heehee, just kidding~",
	feeling2 = "",
	login = "Commander, I know your job is important and all, but like, can we please do something a bit more fun and exciting?",
	detail = "Oh, right! So, I've recently discovered the joys of throwing house parties. I get to bounce all kinds of crazy ideas and opinions off with everyone else, and it's created a brand-new explosion of possibilities~♪",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[519010] = {
	hp_warning = "Hmm... With this, I might have to consider some higher-risk options...",
	feeling3 = "Are any of your friends interested in some of the Dragon Empery's collectibles? If so, I'd appreciate it if you could introduce them to me~♪",
	mail = "Your mail's here, Commander. The contents might seem useless, but you never know where business opportunities lay hidden.",
	expedition = "A commission has been completed. It seems we've gotten some equipment in addition to the regular awards. Hmm, let me appraise it to see how much it's worth...",
	win_mvp = "Another sailing route made safe. Hmm... maybe I can use this opportunity to establish a new trade route...?",
	home = "Well done on your sortie. During your absence, I took it upon myself to seek out the items in need of restocking discussed earlier... Please take a look at the details here.",
	unlock = "So you're the Commander, yes? I've heard your name whispered far and wide. I am Ting An of the Dragon Empery; may our relationship be a fruitful one. Oh, this mountain of stuff next to me? Just consider it... a little business gift of sorts?",
	touch2 = "Jeez... If you keep this up, I won't give you any more advice...",
	mission = "Commander, you've got a new mission. I suppose this is a \"primitive\" form of capital acquisition...?",
	vote = "",
	drop_descrip = "Munition ship – Ting An.",
	feeling4 = "This is my present to you, as thanks for helping me out a while ago. Go ahead and take it – there's no need to be polite. It's not like I'm planning anything in particular; I just wanted to return the favor, that's all. Everything here is pretty mundane stuff helpful in your daily work, so there's nothing for you to worry about.",
	lose = "Hmm... I must say, these losses are rather severe...",
	feeling1 = "As the old saying goes, time reveals the character of one's true heart. No matter how well you wear your disguise, you will be seen through sooner or later.",
	skill = "It's time to close up shop!",
	upgrade = "I will not let the Commander's \"investment\" go to waste.",
	propose = "When it comes to relationships, you can't deal in profits and losses, or expect returns on your investments. I'm sure you thought carefully before deciding to give this to me... Yes, I understand. And my answer to you is, I accept. Allow me to repay your feelings with my eternal devotion~♡",
	feeling5 = "Once the war is over, I want to open a little shop and sell antiques and paintings. Heehee, by combining my sharp business senses with your connections, we should be able to live pretty laid-back lives. How does that pitch sound to you, Commander?",
	main = "Pay close attention to your checkbook, and remember that a penny saved is a penny earned. Hmm? There are too many people here who always want it all? ...Ahaha, how awfully capricious of them...|Were you planning to upgrade the equipment in your office any time soon? If so, would you mind letting me take care of it? I'll be sure to meet all your needs at the lowest budget.|Commander, have you read today's news? Keeping your eyes out for the latest developments puts you in a prime position to capitalize on opportunities of all sorts, in business and battle alike.",
	touch = "What about my outfit? Oh, hmm... I suppose they are rather breezy...",
	voice_key_2 = -1,
	mission_complete = "The mission rewards have arrived. Heehee, now how should we use them to turn a greater profit?",
	battle = "Fight to your heart's content. I shall watch your backs, everyone.",
	id = 519010,
	gift_dislike = "",
	gift_prefer = "You have a discerning eye. Heheh, I'll gladly accept it.",
	profile = "I am Ting An of the Dragon Empery's First Fleet. I once served as a seaplane tender before being converted into a transport ship. Outside of that... Oh, I wonder if little Yat Sen is here? I'm sure that girl must've grown a lot since I last saw her. Heehee~",
	voice_key = 51901,
	headtouch = "",
	feeling2 = "Woah... Commander, you have decorations from every corner of the world in your office... Were they all gifts from your friends around the port? Heehee, you must be quite the charmer~",
	login = "Welcome back, Commander. Heehee, please make the important decisions while you're still clear-headed.",
	detail = "Akashi has a monopoly on this port's commerce, and she seems to have some unscrupulous dealings every now and then. Now, if I could muscle my way into– Hmm? These are the regulations? Boo...",
	couple_encourage = {
		{
			{
				50201
			},
			1,
			" Don't worry. We're all with you now.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[519011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome back. Take these presents as a token of my appreciation for helping me out. Please, I don't want to feel like I'm always in your debt.",
	unlock = "I see, so this is how you're supposed to knead dough... Hmm? Commander? As you can see, I'm currently trying to make baozi. Would you like to help out?",
	touch2 = "Ugh, now there's flour all over me...",
	mission = "",
	vote = "",
	drop_descrip = "I see, so this is how you're supposed to knead dough... Hmm? Commander? As you can see, I'm currently trying to make baozi. Would you like to help out?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "For the last step, I had Ning Hai and Ping Hai steam the baozi. Though I did learn a few things from watching them, the amount of heat and length of cooking time still seem hard to master...|Hai Tien said she wanted some baozi stuffed entirely with chilies... But if Hwah Jah were to get her hands on one, I'm sure that scene would be a total disaster...|Oh right, I heard that some Dragon Empery antiques arrived at Akashi's shop. If you're worried about buying counterfeits, I can come with you.",
	touch = "Commander, do you also know how to make these? Wow... You really know how to do everything...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 519011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "*pant* *pant*... Phew. I didn't know that kneading dough took so much physical endurance... Urgh, I'm all sweaty now...",
	detail = "Why does this store have to make dough from scratch instead of using premade wrappers? ...Why is this sort of commitment necessary...?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[519012] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "I think the commission team is back. Commander, umm, try not to take too long when you go... *pant*...",
	win_mvp = "We won! Oh, maybe I should show off this new swimsuit at the victory party!",
	home = "Good work, Commander! Ahaha, isn't it hard to go out without anyone noticing? If not for this convenient room, I doubt we'd even be able to meet up like this... Phew.",
	unlock = "Umm... Alright, time to take a photo in the on-set mirror and send it to Commander... And there. Just as Commander said, it'd be disastrous if my new swimsuit's design were to get leaked... B-but if I don't do this, our plans will totally be ruined!",
	touch2 = "*pant*... Commander, if we make any noise, someone will... Hyah?!",
	mission = "When you complete missions, everyone doing business at the port profits. We appreciate all you do.",
	vote = "",
	drop_descrip = "Umm... Alright, time to take a photo in the on-set mirror and send it to Commander... And there. Just as Commander said, it'd be disastrous if my new swimsuit's design were to get leaked... B-but if I don't do this, our plans will totally be ruined!",
	feeling4 = "",
	lose = "*pant*... It's really hard to fight without blowing my cover...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "After we check things out here, where will we go next? ...You'll show me around all the rides? Hmm, that does sound like a good rehearsal for when I wear this swimsuit around you again... Ah... N-no, I promise, I'll do my best!",
	main = "Don't worry, Commander. Everyone else should be asleep right now, and the girls on patrol won't notice us... right? Eep...!|(The Commander and I are just doing market research... Yeah! It's necessary for business! Surely I'm not awakening to something and getting pleasure out of this... Surely!)|C-Commander? If you're cold, we could huddle under my coat? I'm also a little... Achoo!",
	touch = "Sh-should we snap another pic?",
	voice_key_2 = -1,
	mission_complete = "Mission complete! Where should I invest next...?",
	battle = "Urk... I need to be careful!",
	id = 519012,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "*pant*... It's not that far, but just walking has me exhausted... Is it because I was putting so much effort into staying undercover?",
	detail = "*sigh*... To win a share in the swimsuit market, you need to do more than just come up with the perfect design and cost. You also have to try them on yourself and experience real use-case situations to suit customers' needs... I-isn't that right, Commander?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[520000] = {
	hp_warning = "Commander, concentrate and be extra careful!",
	feeling3 = "Even if the day comes when I am no longer needed on the battlefield, I still want to watch over the Bohai Sea. I want to always be able to see the waters, dyed a shimmering vermillion in the sunset.",
	mail = "Commander, you have new mail. Should I unseal it for you?",
	expedition = "Great, everyone returned home safely!",
	win_mvp = "Commander, being able to help you out is the greatest!",
	home = "Why don't you take a break? It's not good to be too stressed out.",
	unlock = "Destroyer, An Shan, reporting for duty! I shall protect my sisters and you, Commander!",
	touch2 = "Hey-! My sisters are going to see us...",
	mission = "Protecting the peace isn't just about fighting - you'll have to do these missions too.",
	vote = "",
	drop_descrip = "An Shan-class destroyer, No. 1 - Anshan (101)",
