_G.pg.base.ship_skin_words[601020] = {
	hp_warning = "This isn't how it was supposed to be...",
	feeling3 = "Commander, if you plan on going out, please let me be your bodyguard!",
	mail = "Commander, the mailbox seems to be filling up.",
	expedition = "The commission team has returned! I'm so glad that everyone came back safely.",
	win_mvp = "Victory is ours!",
	home = "Commander, an inquiry arrived while you were gone. Do you want to look it over?",
	unlock = "Flagship Veneto's escort, Carabiniere of the Sardegna Empire, reporting for duty! As your subordinate, I will carry out your orders and complete any mission!",
	touch2 = "P-please don't tease your subordinates like that!",
	mission = "Commander, there are still tasks that need to be finished. Do you require anything of me?",
	vote = "",
	drop_descrip = "Soldati-class destroyer – Carabiniere. ",
	feeling4 = "Commander, I'm really flattered that you treat me so well... You feel safe when I'm by your side? Understood. Your subordinate shall work harder in that regard!",
	lose = "Ugh... th-this subordinate will accept any punishment!",
	feeling1 = "Commander, I don't think that... Nevermind, your subordinate shall follow your order.",
	skill = "Locked on! ",
	upgrade = "I shall definitely become a better subordinate!",
	propose = "From now on, this subordinate shall serve you for life! ...That's not what it means? Um, then... I see! B-but, can someone like me really be your partner?",
	feeling5 = "Commander, are you heading out? Do you need a bodyguard... Oh, it's just a civilian errand? N-no! Even if it's just across the street, y-you never know what hazards lie in wait... S-so, let's go together!",
	main = "Royal submarines have always been elusive and mercurial. They've gotten the better of me in the past... |My gun? I'm telling you, it's real! I just don't have it loaded. |\"Don't disturb during work hours.\" I put this sign up so you can have your peace of mind!",
	touch = "Sì!",
	voice_key_2 = -1,
	mission_complete = "The missions are done, and we have quite the rewards to show for it. If there were some non-material rewards though...",
	battle = "In Commander's name, I sortie!",
	id = 601020,
	gift_dislike = "",
	gift_prefer = "Th-thank you very much!",
	profile = "As a member of the Soldati-class destroyers, I served as the leader of the 12th Destroyer Squadron and led my compatriots through many battles. No matter when or where, I shall give it my all to complete any mission!",
	voice_key = 60102,
	headtouch = "",
	feeling2 = "Rest assured, Commander. This subordinate shall always be loyal to you.",
	login = "Salutations! Carabiniere welcomes you, Commander!",
	detail = "Commander, I'm currently on patrol. Do you have any new instructions for me?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[601021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "",
	unlock = "Lady Veneto advised me to enjoy my time off by changing into something befitting the occasion... Um, Commander, I d-don't look strange, do I?",
	touch2 = "",
	mission = "Wouldn't it be better to finish the missions first...",
	vote = "",
	drop_descrip = "Lady Veneto advised me to enjoy my time off by changing into something befitting the occasion... Um, Commander, I d-don't look strange, do I?",
	feeling4 = "",
	lose = "Ugh... I s-suppose I'm not cut out for this after all...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I once said I wanted to be your bodyguard, but when we're walking together like this, it feels like you're guarding me instead. Would this be dereliction of duty...? Ah! I wasn't saying that I disapproved of it! *sigh*...",
	main = "If you're thirsty, I brought some water. Here you go! |The warm sunlight, the gentle breeze, and an ice pop to beat the heat! That's the spirit of midsummer! |Commander, I heard from a friend that all girls have multiple facets... When I changed into this outfit that I'd absolutely never wear normally... it, it was as if something awakened within me...",
	touch = "Commander! Err, I mean, good day?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 601021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Welcome back, Commander. W-would you like to accompany me on a walk while we both have some time off? S-sorry, I hope I'm not being pushy...",
	detail = "I can't help but to feel a little different when I put on these clothes. I know it's supposed to feel light and refreshing, but instead I feel defenseless and nervous...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[601030] = {
	hp_warning = "Oh no! Deploy smokescreens!",
	feeling3 = "I was born in the historic port of Livorno, a dreamy city on the gorgeous Sardegnian west coast! You should visit it with me if you ever get the chance, Commander!",
	mail = "Here, I brought your mail, Commander.",
	expedition = "The commission team has returned!",
	win_mvp = "Hehe, easy as pizza pie! Err, I mean... Of course, just as expected! Nothing to get excited over!",
	home = "How about a victory hug for everyone? Would that make me seem more mature?",
	unlock = "I am Vincenzo Gioberti of Sardegna! ...Eh, my name's hard to remember? ...Hmm, how about just \"GB\" then? That's a bit easier, right?",
	touch2 = "Whuah?! You're a real creep, Commander...",
	mission = "Hm? New mission directives? But I'm not ready yet... Oh, they're not for me?",
	vote = "",
	drop_descrip = "Alfredo Oriani-class destroyer – Vincenzo Gioberti.",
	feeling4 = "You only find my floundering endearing and cute because you make me flounder so much! ...Th-th-that said, I'm perfectly fine with being called c-cute...",
	lose = "Dangit... You won't discourage me so easily!",
	feeling1 = "Sadly, there's no cure for your chronic hopelessness, Commander.",
	skill = "I'm going all-out!",
	upgrade = "One step closer to blooming into a gorgeous signorina!",
	propose = "You want to... get engaged with me?! B-b-b-but I...! Calm down, GB! Don't get too excited, be cool and graceful like a big sister and respond with grazia! Okay, now... I say, Commander, would you be a darling and put the ring on my finger?",
	feeling5 = "If you and I had met under different circumstances, like as classmates... then maybe we'd be in a typical romantic relationship... J-just thinking out loud, that's all!",
	main = "S-Simoom isn't around here, is she? Ahem! Not to imply I'm afraid of her, my question simply stems from a sincere desire for amity and courtliness.|Oh goodness! Seriously, could you not pull weird faces while I'm trying to work?|Commander, would you care for a delectable dessert? I personally recommend tiramisu!",
	touch = "Huh? I've not done anything weird, have I?",
	voice_key_2 = -1,
	mission_complete = "Mission completed. Now where's the rewards report?",
	battle = "Rest easy knowing I won't let you down, Commander!",
	id = 601030,
	gift_dislike = "",
	gift_prefer = "Ooh! This is... Ahem! Thank you, Commander!",
	profile = "I'm Vincenzo Gioberti, the second Alfredo Oriani-class destroyer. I stood shoulder-to-shoulder with valiant cruisers in many battles across– Huh? That's not quite right? Okay, my completion was a bit behind, but I was second to be launched among my siblings, so I do qualify as a bona fide big sister!",
	voice_key = 60103,
	headtouch = "H-hey! I've grown out of headpats! They don't work on me, nuh-uh!",
	feeling2 = "Hmm... I wonder how long it'll be before I become a fine lady like Veneto...",
	login = "It's the start of a lively day! Keep at it, Commander! I-I'd better get ready for work too!",
	detail = "Anything GB can help you with? I'm the oldest among my siblings and can do absolutely anything! Go on, let's hear it!",
	couple_encourage = {
		{
			{
				60102
			},
			1,
			"You don't need to be so formal with me, you know.",
			0
		},
		{
			{
				20502
			},
			1,
			"*gasp*! W-we're on the same side now, right...?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[601032] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "I'm a signorina – I do of course understand if you're too busy for pleasantries, Commander. Having said that... You should at least tell me before you go out, all right?",
	unlock = "\"To refuse a fair signorina's invitation would be most uncouth\"... Hehe~ Now, Commander, would you like to partake in some refreshments? Rest assured, they're all non-alcoholic♪",
	touch2 = "You'll never receive another party invitation from me again!",
	mission = "",
	vote = "",
	drop_descrip = "\"To refuse a fair signorina's invitation would be most uncouth\"... Hehe~ Now, Commander, would you like to partake in some refreshments? Rest assured, they're all non-alcoholic♪",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "This \"for adults only\" drink has gott my attention... Could I at least have a taste?|Commander, as this is an informal gathering, you are free to say whatever you please! I am a grown lady, and I can handle it!|We have some lovely tiramisu resting on the counter, Libeccio! Call over Maestrale and we'll all savor it together!",
	touch = "Fare un brindisi! Indeed, this is how a signorina raises a toast.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 601032,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "A refill, if you would, Manjuu waiter! Likewise for the Commander's glass, please! Now let me just... Hup... Ugh, these bar stools are sure are tall...",
	detail = "You may drink to your heart's content today! Worry not, just put it on my tab! ...Huh? The drinks were free to begin with?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[601040] = {
	hp_warning = "What should I do...? What should I do?!",
	feeling3 = "Commander... Please look over this. It's a table of our recent mission earnings... I hope it can be of help to you...",
	mail = "The mail, where'd I put the mail...? Phew, I almost forgot it after all the time I spent organizing it...",
	expedition = "A commission has been completed. The dockhead is looking rather crowded...",
	win_mvp = "My thoughts about getting MVP? ......Uh, umm, it's nice...?",
	home = "How to make tea... Um, take the teabag and steep it in hot water... Commander, p-please let it sit for a few minutes...",
	unlock = "Now lift the rim of your skirt and bow... Ahem! I'm Maestrale, d-destroyer from the Sardegna Empire. Greetings to you and your fleet, Commander. I hope I did that right...",
	touch2 = "...Wh-what is the meaning of this?!",
	mission = "Are you going to... continue working on your high-priority missions? Err, I mean... let, let me help you!",
	vote = "",
	drop_descrip = "Maestrale-class destroyer – Maestrale.",
	feeling4 = "...Commander? Why'd you come all the way... t-to talk to me? Um, right now, I'm a bit... err, I mean, yes, I'm available! I'm available, but I can't... Sorry...!",
	lose = "I've been defeated... What should I be saying...?",
	feeling1 = "Keep your distance from me! Shoo, shoo...!!",
	skill = "N-now it's my turn!",
	upgrade = "Shelling, torpedoes, and reloading... I must become stronger in all aspects...",
	propose = "Wh-what should I be saying during a wedding ceremony? ...Um, I don't need to say anything at all? Well then... *kiss* Th-that's fine too, right...?",
	feeling5 = "Um, Commander, please take this...! Libeccio told me that if there ever was something I'd never be able to say... to put it down in a picture book! P-please take a look...!",
	main = "What do I think of Libeccio? ...She's my precious little sister. She can be a bit of a klutz at times though, ehehe...|The documents I was just working on are over here, and the already-finished ones are here... Ah, it's not that I couldn't find them, I just thought it'd be more efficient to remind myself out loud... S-sorry... *blushes*|Commander, you must be tired... Ahh, just thinking about it makes me nervous...",
	touch = "D-did I say something inappropriate?",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Umm, should I go help you confirm the rewards after all...?",
	battle = "As the flagship... I've got to boost everyone's morale... Roar...!",
	id = 601040,
	gift_dislike = "",
	gift_prefer = "Goodness... Th-thank you! Oh, I don't even know what to say...",
	profile = "I am the name ship of the Maestrale-class destroyers, Maestrale. During that war, I remember hitting a naval mine and having to return to port for repairs... The rest of my history? Umm, I, I don't think there's anything else...",
	voice_key = 60104,
	headtouch = "Wh-what's going on...?",
	feeling2 = "Libeccio, please don't bother the commander in the middle of work hours... Here, I'll make a syllabus of the times when the commander is available. Mm, that should be right... hopefully.",
	login = "Greetings, greetings... G-good morning to you, Commander...",
	detail = "If only Libeccio was here... I wouldn't have to agonize over how to talk to the commander...",
	couple_encourage = {
		{
			{
				60105
			},
			1,
			"Libeccio, w-w-wait for me...!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[601041] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	couple_encourage = "",
	expedition = "",
	win_mvp = "",
	home = "Commander, did you come all the way here to see me? Th-thanks for your concern...",
	unlock = "It's way too crowded on the beach... I'd much rather be– Oh, Commander? Are you not good with crowded places either...?",
	touch2 = "P-please stop that...!",
	mission = "",
	vote = "",
	drop_descrip = "It's way too crowded on the beach... I'd much rather be– Oh, Commander? Are you not good with crowded places either...?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Veneto's Colosseum is truly spectacular... I wish I could fill in the other half...|Libeccio, stop trying to drag me around.. You can go hang out with the commander instead.|The letters I etch into the sand are immediately washed away by the waves. I see, this is what they mean when they say \"write your worries on the beach\"...",
	touch = "Commander, did you want to get buried in the sand just like these manjuu? I'll see what I can do then...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 601041,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Greetings, greetings... Err, umm, Commander, w-want to sit down?",
	detail = "Though I'm not able to build the Colosseum like Lady Veneto can, when it comes to the Leaning Tower, a cathedral, or a basilica... Um, I can kind of get the rough shape down!"
}


_G.pg.base.ship_skin_words[601050] = {
	hp_warning = "Woah! An enemy ambush!",
	feeling3 = "Commander, I'm here to play! You're not busy right now, right? Ehehe, after all, Maestrale made this... silly-bus for me? In any case, it seems right!",
	mail = "Mail time! Mail time! Whooooo~!",
	expedition = "Commission complete! Duuuuude, look at the loot!",
	win_mvp = "The MVP is all mine! Commander, gimme a reward!",
	home = "Commander, look! Lookie lookie at what I found! It's the teabags that my sis always uses to make you tea! I wanna try it too!",
	unlock = "Ciao! The name's Libeccio! It's a pleasure to meet you, Commander! Let's be real good friends from here on out!",
	touch2 = "Smooth and flat, huh? Just like my big sis!",
	mission = "It's mission time! All I have to do is check off the box next to 'em, right... Of course that was a joke!",
	vote = "",
	drop_descrip = "Maestrale-class destroyer – Libeccio.",
	feeling4 = "Ehhh... Spend more time with me, Commander! What do I even want to do...? I don't care! Anything!",
	lose = "Starting emergency rescue procedures! Commander, make sure you keep me safe!",
	feeling1 = "Knock knock! Yeah, I'm gonna keep thwacking you around until you behave!",
	skill = "Let's have some fun over here~!",
	upgrade = "Such powerrrr! Time to show off to Maestrale!",
	propose = "What a beautiful ring! If I put this on, it means that I'll be able to cling to you as much as I want, right? It's a promise!",
	feeling5 = "Commander! I'm here to play again! I don't care what you're doing! I'm gonna cling to you today no matter what! Heh~ heh~!",
	main = "Maestrale's super good at organizing documents, isn't she? When I try to do it, they just end up messier and messier~|My hair's silver on the outside and blue on the inside! Beautiful, isn't it?|Commander, look over here! Kapow! Whew, a direct hit~! Ahaha!",
	touch = "Hey, what's the matter? Did something happen~?",
	voice_key_2 = -1,
	mission_complete = "The mission rewards huh... I may or may not have helped myself to a little when Maestrale wasn't looking... Ehehe~",
	battle = "I'm the flagship! Everyone, lesgooooo~!",
	id = 601050,
	gift_dislike = "",
	gift_prefer = "Ooh, yeah, I love this! Thanks!",
	profile = "During that war, I was the pride and joy of the Sardegna Empire, Libeccio! ...Eh, I was the first of my sisters to retire? Booo! Commander, why do you have to rub salt in the wound!",
	voice_key = 60105,
	headtouch = "Hold your horsies, Commander! Lemme take my hat off first... Now, pat me!",
	feeling2 = "I wish I could get Maestrale some more friends! Commander, got any ideas?",
	login = "Ciao! Commander, let's give it our all today as well!",
	detail = "Now that I'm here, Maestrale's gonna make a whole lotta friends! ...Oh, right, Commander! Are you getting along with my sis?",
	couple_encourage = {
		{
			{
				60104
			},
			1,
			"Sis, follow my lead!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[601051] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Glub... Blub...! Blehhh, it's so salty... My kickboard flipped over in the blink of an eye... I guess I really shouldn't head out until the waves calm down a little!",
	unlock = "Libeccio's heading towards the sea! Commander, let's go to where all the excitement is!",
	touch2 = "Commander, what kind of game is this~?",
	mission = "",
	vote = "",
	drop_descrip = "Libeccio's heading towards the sea! Commander, let's go to where all the excitement is!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Sailor Libeccio, ready to head out! Captain da Recco, when do we begin the timber-shivering?|How can I get Maestrale to join us in the fun and games? ...Hmm, take some beautiful conch shells over to her?|Commander, look at that! So many footprints in the sand along the beach... Huuuh?! Th-they got washed away just like that...",
	touch = "Get on, Commander! We're going on a field trip!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 601051,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Yes, pat me to your heart's content!",
	feeling2 = "",
	login = "One, two three, four... All righty, I'm all done warming up! Time to head down into the water~!",
	detail = "How the heck do you make a sand castle? Like this? Or maybe... like this...? Gaaaah! I give up!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[601060] = {
	hp_warning = "Oops!",
	feeling3 = "By Neptune's name! Look, Commander, there's an uncharted area on our map! Who knows what secrets it holds! We should go there on our next voyage!",
	mail = "New mail's come in! Maybe it's got info on the latest course developments?",
	expedition = "A commission's been completed! What do you say we try a different course for the next one?",
	win_mvp = "That's that annoying bunch dealt with! Now we can explore in peace!",
	home = "Let's see, where should I plot a course to next...",
	unlock = "The port's newest arrival, that's-a me! Fun-sized navigator Nicoloso da Recco salutes you, Commander! Andiamo, towards uncharted waters!",
	touch2 = "I may be short, but I'm stacked! Bada bing!",
	mission = "Get those missions done, on the double! I'll be stuck idling in port forever otherwise!",
	vote = "",
	drop_descrip = "Navigatori-class destroyer – Nicoloso da Recco.",
	feeling4 = "\"If you help me out enough, I'll consider taking that route\"? Whoa, you mean it?! Sign me up as your assistant!",
	lose = "Err, what? Did I take us on the wrong course?",
	feeling1 = "I'm going on a voyage! Without you! Buh-bye!",
	skill = "Wind direction accounted for! Fireeee!",
	upgrade = "To the horizon and beyond!",
	propose = "What's it mean to \"link our hearts\"? Will I know where you are when I'm out at sea, without even using a compass? Ahaha! If only it were so easy, am I right?",
	feeling5 = "We've got a date coming up, you and I! Since I am the veteran navigator here, I'll do the course plotting... I mean, itinerary planning! ...You wanna do that yourself? Hmm... All right, I'll leave it to you!",
	main = "Commander, got any maps lying around? I'm not gonna mess with them, I just wanna draw some lines, plot a few courses, that sorta stuff!|Hey, could I have a look at your medal collection? I'm just curious which and how many you have!|Why does everyone just take the same exact route over and over? There's so, so much ocean to see out there!",
	touch = "Will you check out the course I plotted after I finish this work? Sweet! I'll have it done in no time!",
	voice_key_2 = -1,
	mission_complete = "Mission complete! Can we go on a voyage now? What do you mean?! I thought we had a deal!",
	battle = "Captain da Recco, setting sail!",
	id = 601060,
	gift_dislike = "",
	gift_prefer = "Bravo! Thank you, thank you!",
	profile = "I'm a navigator, and let me tell you, I'm phenomenal! I fought hard alongside lots of my friends, and even made it through the war in one piece. My run-in with Force Q though, that was just blind luck!",
	voice_key = 60106,
	headtouch = "Ow! Don't pull on my hairband!",
	feeling2 = "Ahoy, Commander! Today's a perfect day to go on a voyage! First, we just have to plot a course!",
	login = "Ahoy! Good to see you again, Commander! Let's have a look at today's cruising plans!",
	detail = "This course is a no-go because there's no resupply point along it? Okay, then how about this one? ...Also a no-go; ocean currents are too strong? Stop being such a darn naysayer, Commander!",
	couple_encourage = {
		{
			{
				20215,
				20220
			},
			2,
			"Eep! You again...",
			0
		},
		{
			{
				29904
			},
			1,
			"Andiamo, to uncharted waters!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[601061] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Woohoo! Good thing I smashed that melon! ...Huh? What do you mean it's not a ceremony to boost your luck?",
	home = "Ahoy! Wanna join my sister here under the sand?",
	unlock = "I know this one! It's that Sakura Empire watermelon-smashing game! Just put the melon over there, Commander! ...Relax, it'll be fine! Have some faith in my navigator's intuition! Ready? Then let's go!",
	touch2 = "Oh shoot! Watch out – airborne bat!",
	mission = "",
	vote = "",
	drop_descrip = "I know this one! It's that Sakura Empire watermelon-smashing game! Just put the melon over there, Commander! ...Relax, it'll be fine! Have some faith in my navigator's intuition! Ready? Then let's go!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Oh, I've gotta put on a blindfold too? No problem! I'll still nail that watermelon! Just make sure it stays in place!|I remember hearing the Dragon Empery's got something similar to this, just with a rock instead of a melon!|Remember to stay hydrated! Just because you're near the ocean doesn't mean you won't get thirsty!",
	touch = "Wanna pick up a bat and try for yourself?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 601061,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "The weather's perfect for a voyage, but Captain da Recco's seaside funtime takes precedence! Come on over and we'll play a game, Commander!",
	detail = "Be sure to stop by later, Commander! We'll split a melon and each have a slice!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[601070] = {
	hp_warning = "No big deal! I can keep going!",
	feeling3 = "You came at just the right time, Commander! You see, um... Thing is, I could use a lot of help. I simply don't have enough time to run all those errands I promised to... I know, I know, but you'd be helping everyone out, not just me!",
	mail = "Your trusty secretary brings you new mail, right on schedule!",
	expedition = "Commission supplies have arrived! Allow me the honor of processing them!",
	win_mvp = "Captain Pompey the Great has once more led her allies to a spectacular victory!",
	home = "Dammit... I've barely gotten anything done while the Commander was out... This is gonna reflect so badly on me... Ahem! Commander! Welcome back!",
	unlock = "Captain Pompey the Great has arrived at port! ...Err! Ahem! Good day to you, Commander! I am Pompeo Magno of the Sardegna Empire! Assign any and all work to me and I'll have it done in the blink of an eye!",
	touch2 = "I-I-I am NOT some easy girl!",
	mission = "I'll take care of all these new missions, Commander! ...Wh-what's with that look? Wait... You're signaling that you doubt my ability, aren't you?!",
	vote = "",
	drop_descrip = "Capitani Romani-class ship – Pompeo Magno.",
	feeling4 = "Phew... Without your help, I would've fled the port out of sheer shame before nightfall, fated to forever roam some cold corner of the ocean... Truly, I thank you from the bottom of my heart, Commander!",
	lose = "We're defeated... My dignity has been destroyed and the fleet's reputation will plummet, dooming it to fade into obscurity... Oh, err, I didn't say anything!",
	feeling1 = "You're a terrible Commander, but if I can produce results in spite of you, people will think I'm really talented! There's always a silver lining, I tell you!",
	skill = "Nothing is impossible for Captain Pompey!",
	upgrade = "The greater your ability, the more responsibilities you deserve!",
	propose = "Just as the capital wasn't built in one day, it takes time for people to form close bonds. Okay, I know that's an odd example! Basically, what I'm saying is: I'll make a concentrated effort to spend quality time with you so we'll become better acquainted! Otherwise I'll feel like you wasted this ring on me!",
	feeling5 = "Now I get it! I can earn more recognition if I focus on you, plus then I won't have to worry about breaking promises. So with that in mind, will you let me take care of all your problems whenever they arise? ...I'm begging on my knees here, please don't turn me down.",
	main = "Hmm, how should I process these documents... It's okay, I know what I'm doing, Commander! Seriously, just let me handle it!|I'm going out for a while, Commander! When you've got a schedule as packed as Captain Pompey's, you can't afford to sit around on your butt all day!|If I do a bad job here, the Commander's gonna make me resign and then ostracize me... Uh, I didn't say anything! Just dealing with a minor problem here! Y-yeah, that's all!",
	touch = "When you need my help, just grab my hand and hold it tight!",
	voice_key_2 = -1,
	mission_complete = "Mission complete! ...And unsurprisingly, I could've never accomplished it alone... Ahaha...",
	battle = "Have faith in my orders! They will lead you to victory!",
	id = 601070,
	gift_dislike = "",
	gift_prefer = "Thank you, Commander! Heheh, it's good to see my hard work being recognized for once~",
	profile = "I'm Pompeo Magno of the Capitani Romani-class from the Sardegna Empire! My speed and firepower make me suited for any kind of mission, and what I lack in protection I more than make up for with agility!",
	voice_key = 60107,
	headtouch = "My cap is NOT just for show!",
	feeling2 = "I've accepted a plethora of errands and consultations with other girls today. Soon I will be the talk of the port, and every– What do you mean this schedule is infeasible? Don't you know? Nothing is impossible for me!",
	login = "Welcome back, Commander! I am ready to begin my secretarial duties and take on work from you!",
	detail = "Look, I know most people would panic if they were suddenly told to manage every last facet of a fleet, but I'm one of those few who have what it takes... Right?",
	couple_encourage = {
		{
			{
				80101,
				80107,
				90111
			},
			1,
			" You don't have a monopoly on speed, you know!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[601071] = {
	hp_warning = "",
	feeling3 = "",
	mail = "New mail? Might be our performance evaluation... C-come here and let me have a look at it!",
	expedition = "The commission team brought back new components, and there are way too many to sort through... But that's okay! I like a challenge!",
	win_mvp = "Victory! ...Wait, I just realized, we played for fun and still won!",
	home = "Zzz... I've gotta finish all the errands I took on before the Commander gets back... Zzz...",
	unlock = "*yawn*... Nothing's impossible when you've got Captain Pompey... Hmm? Commander? Wait, I fell asleep? Seems I did... Drat, I forgot what I even came here for...",
	touch2 = "For the last time, there's not enough room for both of us! PLEASE get it into your head!",
	mission = "There are new missions? Okay, I'll note that down and sort those out later!",
	vote = "",
	drop_descrip = "*yawn*... Nothing's impossible when you've got Captain Pompey... Hmm? Commander? Wait, I fell asleep? Seems I did... Drat, I forgot what I even came here for...",
	feeling4 = "",
	lose = "I'm dead tired... Commander, lower the top for me... I need a break from real life right now...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Remember to get the literature Impero asked for... and the picture books for Maestrale and Libeccio... and to buy soda for Archerfish... Zzz...|Do you know how to play the piano, Commander? Err, this is just a model piano. The keys don't work.|I remember now! Someone asked me to reorganize this place! And since you're already here, you should help me– I mean, help all of us by tidying up with me!",
	touch = "Wait, stop! There's not enough room for both of us!",
	voice_key_2 = -1,
	mission_complete = "Mission complete! ...And I've not even gotten started on them yet... Wait, did you finish ALL the missions before I could attempt them?!",
	battle = "",
	id = 601071,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "What's with the kiddy treatment?!",
	feeling2 = "",
	login = "Hi, Commander! I'm fully rested, as you can see. So, it's time to go looking for people who need a hand and do them some favors!",
	detail = "If I'd known the Commander would find me like this, I would've hid under the piano top before I dozed off... Err, nothing! Just talking to myself!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[601080] = {
	hp_warning = "D-don't lash out at me just 'cause I'm a journalist!",
	feeling3 = "Just between you and me, info about you is currently worth... this much! Heheheh! Interested? Then lemme interview you some more~",
	mail = "A confidential letter... It'd make for a juicy story, but top-secret stuff has to stay that way!",
	expedition = "The commission team is back! I'm gonna go snap some group photos!",
	win_mvp = "First question: how does it feel to be the– Wait, what? I'M the MVP?!",
	home = "Cheese! Welcome back! I snapped a photo of you and the fleet looking badass out there! It's gonna blow up in the news! ...In a good way! Heehee!",
	unlock = "Whoa! Here comes the mastermind behind the curtains, the one mark I really want to use all means possible to investigate – the legendary Commander! Let's get on to the interview, but first, allow me to introduce myself! The name's Alfredo Oriani! I'm a journalist, as you see!",
	touch2 = "Whuah! ...Dammit, I didn't have time to snap an incriminating pic!",
	mission = "New missions? If we're talking quick errands, I can do 'em!",
	vote = "",
	drop_descrip = "Oriani-class destroyer - Alfredo Oriani.",
	feeling4 = "Hm? You like me? Ahahahah! I'm nobody special, I'm just a smalltime journalist who loves gossip~ Forget about me – who else do you fancy? That's valuable information!",
	lose = "I-I guess I'll hide this blunder at the back of the newspaper...",
	feeling1 = "I-I-I'm so sorry! I'll stop with my journalism if it offends you! Just please show mercy!",
	skill = "Smile for the camera!",
	upgrade = "Nice! Lens aligned, picture perfect!",
	propose = "Hold up! This doesn't make any sense! I'm just a gossip-loving, devil-may-care, occasionally ill-mannered journalist, Commander! You have zero reason to marry someone like... Nononono! I'm not saying I hate you in any way! Oh geez, if I don't cool off now I'm gonna frickin' explode! I accept the ring, okay?! We'll talk later!",
	feeling5 = "The more I learn about you, the less I wanna share my knowledge with others... even though I could make big bucks by selling it... I think I might've fallen for you, Commander! S-s-settle down, Alfredo! G-g-get a hold of yourself!",
	main = "Wherever you'll find scoops, you'll find me! Heehee~|You feel like you're being watched? Weeell, I'll bet that's just your fatigue speaking! Yup, hundo percent sure of it!|So you wanna become a mature big sister, do ya, GB? Heh, I've got heaps of pics of girls like that. Although, I guess photos won't really help you achieve that goal.",
	touch = "My camera's inner workings are top secret! No peeking!",
	voice_key_2 = -1,
	mission_complete = "A mission has been completed! ...So, Commander, what are your thoughts on this latest development?",
	battle = "We're live, so remember to look photogenic!",
	id = 601080,
	gift_dislike = "",
	gift_prefer = "Hmm... I might have to put in a few good words for you in my next article...",
	profile = "It's-a me, Alfredo Oriani, name ship of my class of destroyers! Conserve vowels and just call me Alfredo! Go ahead and send me to the front where all the action is – I've covered world wars, you know! Heheh!",
	voice_key = 60108,
	headtouch = "What's this? You trying to score points with me?",
	feeling2 = "Commander~ Think you could make some time for a Q&A later? It'll be basic stuff! You know, hobbies, likes, your taste in girls, things like that!",
	login = "Morning, Commander! It's the perfect day for a close cov– I mean! For work! In more ways than one. Heheh...",
	detail = "If you wanna know others' secrets, you gotta give me something of equal value. Don't worry 'bout getting duped – I deal fair and square!",
	couple_encourage = {
		{
			{
				10105
			},
			1,
			" Let's see who can snap the best photos!",
			0
		},
		{
			{
				30303
			},
			1,
			" Hey, you wanna trade scoops?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[601081] = {
	hp_warning = "",
	feeling3 = "",
	mail = "A new letter? It might be a personal invitation for you! Let's find out!",
	expedition = "",
	win_mvp = "",
	home = "Oh yes, this is a good angle! This photo's gonna make a good... C-C-Commander?! When'd you get here?! I'm not up to anything, nuh-uh! I-I need to get back to rehearsing my dance!",
	unlock = "Found you, Commander! How would you grade this outfit of mine? ...No, no, I wasn't asking if it looked cute or pretty, I wanted to know if I was wearing it right in the first place! You know what though, I think I'll take those compliments~",
	touch2 = "I'm not hiding anything! There's nothing I CAN hide to begin with! Use your common sense!",
	mission = "",
	vote = "",
	drop_descrip = "Found you, Commander! How would you grade this outfit of mine? ...No, no, I wasn't asking if it looked cute or pretty, I wanted to know if I was wearing it right in the first place! You know what though, I think I'll take those compliments~",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Let's see today's hottest article... \"You Won't Believe Who's the Commander's Dance Partner\"... W-wait, it's ME?! It's over... This is gonna spread around the port like wildfire... \"It's fine, I'm here with you\"? Um... Excuse me, I need to go cool off my burning hot face!",
	main = "There are crowds of girls vying to be your partner, Commander! That heartwarming piece of info comes from yours truly♪|GB! I snapped a bunch of photos of ladies being ladies! Here! Feel free to reference it~|Commander! I've got gorgeous pics of Sardegnian girls mid-rehearsal! Interested? ...Then you know what I want in return. Heehee~",
	touch = "Aha! So I move my feet like... Hang on, why am I here learning dance moves from you?!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "This is Alfredo, reporting live on– Hey, the battlefield's no place to fret over dresses!",
	id = 601081,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "You typically ask for a dance by holding someone's hand, not by patting their head...",
	feeling2 = "",
	login = "Commander, tell us who you'd most like to dance with today! ...You can't say? Figures it wouldn't be so easy... Well, we'd better find you a dance partner soon!",
	detail = "Tadah! Heehee, what'd ya think of my dance? I got advice from my Sardegnian friends on how to blend in with the crowd while gathering scoops! Although I may have gone a bit overkill with it...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[601090] = {
	hp_warning = "I mustn't drag the others down...",
	feeling3 = "A telescope makes it possible to see things clearly even from a distance... From a place far, far away, where I won't bother anyone...",
	mail = "You've got new mail. It's from... somewhere I can't see... Hrmm, someplace far, far away?",
	expedition = "Our friends from the commission team have returned. Look, they're over there––",
	win_mvp = "Did we manage to win? That's a relief...",
	home = "......Oh. Sorry, I was taking in the scenery outside and didn't notice you returning...",
	unlock = "I'm the Sardegnian destroyer, Emanuele Pessagno. Umm... Commander, you look way different in-person than through my telescope... Must be because I can get a closer view.",
	touch2 = "P-please stop that...",
	mission = "There are still missions that need doing. Commander, you seem to be having a rough time... Need to take a little break?",
	vote = "",
	drop_descrip = "Navigatori-class destroyer – Emanuele Pessagno.",
	feeling4 = "Imprinting a beautiful scenery into your memory after seeing it once is already good enough... But, sometimes, the more you see something, the more you want to touch it, feel it...",
	lose = "Excuse me, um... Commander, you don't need to feel too down about it.",
	feeling1 = "I'm sorry, but please leave me alone...",
	skill = "I see you...!",
	upgrade = "Am I able to see farther now...?",
	propose = "Eh? Th-this is for me? Thank you... I'll make sure to treasure it, no matter what... Ehehe, I don't have to keep gazing from a distance anymore... After all, happiness is within my reach...",
	feeling5 = "Umm... Commander, do you have any free time next week? There's a place I really want to go to... Um, I want to take you sightseeing... Is that okay? I-it's always been really important to me...",
	main = "I like to gaze out into the distant scenery. What your eye can perceive... is so much greater than what your fingertips are able to touch.|There should be a lot of great observation spots around the port, right? I'd like to jot them all down when I get the chance.|Da Recco, if you're going to go out, wouldn't it be safer to take a more... charted route?",
	touch = "You want to try looking through my telescope? ...Um, sure, but be careful...",
	voice_key_2 = -1,
	mission_complete = "Here's the mission completion report... Need help looking over it? If a typo slipped its way into the final submission...",
	battle = "Enemy spotted... Commencing attack!",
	id = 601090,
	gift_dislike = "",
	gift_prefer = "I-I'll treasure this!",
	profile = "I am the Navigatori-class destroyer, Emanuele Pessagno. Back then, I managed to serve Sardegna commendably, but if only I had been more careful during that final escort mission...",
	voice_key = 60109,
	headtouch = "Is there something wrong with my ribbon?",
	feeling2 = "Commander, you've tried looking through the telescope, right? ...So, what do you think is the difference between seeing something through the lens and seeing something up-close?",
	login = "Hrmmmm... Yeah, you really do look nothing like what I saw through the telescope... N-nevermind. Welcome back, Commander.",
	detail = "You have to take good care of telescope lenses... Otherwise, they might get scratched up, and that's a huge problem.",
	couple_encourage = {
		{
			{
				60106
			},
			1,
			" O-on to a new journey... Ugh, I can't say it after all...",
			0
		}
	}
}


_G.pg.base.ship_skin_words[601091] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Commander, can you grab a comb for me? There should be one in the next drawer over...",
	unlock = "Eek! Wh-why are you guys tugging at my stockings... P-please stop that... C-Commander, please... Hurry and come help me! Waah...",
	touch2 = "Y-you shouldn't do something like that...",
	mission = "",
	vote = "",
	drop_descrip = "Eek! Wh-why are you guys tugging at my stockings... P-please stop that... C-Commander, please... Hurry and come help me! Waah...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Commander, umm, can we go somewhere together? I want to see some familiar scenery before the performance begins, to relieve some of my nerves... And, whenever I'm with you, I feel even more at ease.",
	main = "I have to stand up there in front of everyone as a part of the set... Just thinking about it is making my heart pound like crazy...|If you're talking about my telescope, I let my friends hold on to it. Y-you want to use it to look at me since you're sitting pretty far back...? P-please stop teasing me...|Now that I think about it, this outfit is pretty risqué... I wonder why Laffey doesn't seem to mind at all...",
	touch = "I, I can put these shoes on myself. There's no need to bother the Commander...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 601091,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Th-the microphone isn't clipped on crooked, right...?",
	feeling2 = "",
	login = "Th-thank you... for coming all this way to see me... Phew... I've finally managed to calm down a little, and I don't think I'm as nervous as before...",
	detail = "Commander, um, can you ask Alfredo to put me in some inconspicuous corner when she's writing her review? ...I, I don't want to stand out too much...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[601100] = {
	hp_warning = "Whoa, whoa! I'm gonna lose to the baddies...!",
	feeling3 = "Commander, look! Here's the White Bunny, here's the Black Bunny, and here's Duke Monochrome Bunny! Captain Kitty and the Manjuu Guard are here, too! Everyone, let's have fun with the Commander!",
	mail = "Commander, you got a letter! I'm like a bunny delivering mail!",
	expedition = "The older girls brought lots of stuff back! Were they out adventuring?",
	win_mvp = "We won! My friends and I really trounced those baddies!",
	home = "Commander, you're back! Hey, did you meet the Dolphin Knights and Captain Shark? I wanna know all the fun stuff you've been up to outside of our castle!",
	unlock = "Vowed to protect me forever, and bound by the red string... You are my fated knight, Commander! Finally, I found you! Hehe, go on—welcome me to your castle!",
	touch2 = "Hahahahaha~ Th-that tickles~",
	mission = "What's a mish-shun? Does that mean I'll get a reward if I help with work?",
	vote = "",
	drop_descrip = "Capitani Romani-class large destroyer – Attilio Regolo.",
	feeling4 = "The Black Bunny and White Bunny play every day, so they're the bestest friends! You and I play every day, too, which also makes us the bestest friends!",
	lose = "F-forget that just happened! Next time, you and I are gonna teach them a lesson!",
	feeling1 = "C-Commander, are you actually a minion of the Onion Monster?!",
	skill = "I'm not gonna lose!",
	upgrade = "I'm getting stronger!",
	propose = "Hehe, I love you, Commander! Hey, can you squat down for a sec? There you go... Now I can give you a big kiss on the cheek! Mmm-mwah! We're gonna live together forever, just like the princes and princesses of fairy tales~",
	feeling5 = "All the good people should be happy, all the bad people should get punished and learn to be better, and everyone who loves each other should end up together... That's what I want. What about me? Hehehe, as long as I'm with you, I already have what I want!",
	main = "I hope the Onion Monster and Evil Pepper don't show up in my lunch tomorrow... B-but I know you'll save me, Commander!|Commander, I'll rub your shoulders for you! Let me and the cute bunnies soothe you together.|I love your castle, Commander! I can play with the bunnies and kitties whenever I want, I don't have to go anywhere far, and I don't have to be in the sun!",
	touch = "Come play with me and the bunnies!",
	voice_key_2 = -1,
	mission_complete = "Commander, our rewards came! Let's go take 'em into our castle!",
	battle = "Watch this! I'll drive off all those baddies!",
	id = 601100,
	gift_dislike = "",
	gift_prefer = "Whoa! You mean this is for me? It's so cute!",
	profile = "My name is Attilio Regolo, and I'm a Capitani Romani-class destroyer from the Sardegna Empire! Don't you think a shipgirl and her Commander are like a fairy tale princess and her knight? Though some seem to think we're the knights, while you're the princess...",
	voice_key = 60110,
	headtouch = "Ehehe... Squishy...",
	feeling2 = "Mr. Birdy, come down here! I'll give you some tasty dried fish! ...Hmm. Why do they always fly away as soon as they're done eating?",
	login = "Commander, I lined up your paperwork like paper soldiers for you! Now you just gotta knock 'em out!",
	detail = "Commander, you gotta protect all of our friends in the castle, too! You're so cool and strong, I know you can do it!",
	couple_encourage = {
		{
			{
				60107
			},
			1,
			" You go, Captain Pompey! You're the coolest knight in the castle!",
			0
		},
		{
			{
				30102,
				30129,
				10117,
				10116
			},
			1,
			" Whoooa, you've got bunny ears! Can I touch them?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[601101] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Commander! Y-you're good at computers, right? It's not working... D-did I make it mad, or something?",
	unlock = "Welcome to my humble abode! Bunnies, kitty-cats, and the Commander... The gang's all here! Today's tale is gonna be a wild one!",
	touch2 = "Hahahaha, haha... Haha... C'mon, that tickles!",
	mission = "",
