	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "If you turned into a kitty, I'd be able to snuggle and pet you all I wanted... Heehee!|Vice Captain Pen, it's up to you! Aww, I wish you could just draw in my place...|Kitties and bunnies, get along, okay? Whoa! Don't scratch the bunny's ears! And no jumping around my desk, either!",
	touch = "Hey, what is a princess carry like? I wanna be princess carried!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 601101,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "You're just in time, Commander! Sit right there, okay? I wanna draw you all chibified and cute! It won't take long.",
	detail = "You write the words, and I'll draw the pictures! We'll make a really happy story together!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[601102] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Commander, you've got letters! Don't I look like a mail delivery girl now? Heheh!",
	expedition = "",
	win_mvp = "",
	home = "Commander, welcome back! Heheh, what do you think? I bet you never get tired of seeing me float down from above!",
	unlock = "I wanted to try making a fairy-tale entrance. Did I look good, Commander? When you saw me come down from the sky, did you sense destined romance?!",
	touch2 = "Ahahaha... Come on, that tickles! I'm gonna lose balaaance!",
	mission = "",
	vote = "拉票描述",
	drop_descrip = "I wanted to try making a fairy-tale entrance. Did I look good, Commander? When you saw me come down from the sky, did you sense destined romance?!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "For me, being with you is the greatest joy of all! My heart feels even fluffier than a cloud... Hehe... This is the kind of love you see in fairy tales, isn't it?",
	main = "I've been practicing a lot so you can see my cutest side! ...You think I look like a real angel? Hehehe~|Whoa, my parasol's making a weird noise... Am I gonna fall if it breaks?|With Duke Monochrome Rabbit~ We part the clouds and light up the day~ To my fated one, I'm on my way~",
	touch = "Floaty, airy... Commander, do you like this? Wanna try it?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 601102,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commandeeer! Heheh, it's time to jump into fairy tales. Hurry up and take my hand!",
	detail = "Hmm... Y'know, I think it would be cooler if we could swap how we appear. Seeing you descend from on high... Heheh, just imagining it is exciting!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[601110] = {
	hp_warning = "I'm fine. I can still fight!",
	feeling3 = "Welcome to my personal collection. As you can see, I've divided literary works into sections by faction... What do I do with books in languages I can't read? Well, learning the language and trying to translate it is a perfectly enjoyable challenge.",
	mail = "There's mail addressed to you, Commander. Wait, not that one... That's a poem I was in the middle of writing. Ahem... You may see it once it's done.",
	expedition = "Commander, the commission fleet is back. I checked the material manifest, and nothing seems to be out of line, but some of the terminology seems inaccurate...",
	win_mvp = "To you I offer a hymn of honor and glory.",
	home = "Dropping anchor, mooring... No, we can do better... Hm? Commander, you're just in time. I'm trying to write a poem about returning to port. You must know more about this than me. May I borrow your knowledge for a bit?",
	unlock = "I'm Giosuè Carducci, a Sardegnian poet. Pleased to meet you. Should I get to work right now? If I have time before I start, I'd love an opportunity to visit the port library first.",
	touch2 = "That one's going into my Collection of Boorish Acts.",
	mission = "You're worthy of a poem even when you're acting slovenly, but is now really the time? Brace up and handle your work, Commander.",
	vote = "",
	drop_descrip = "Oriani-class destroyer – Giosuè Carducci.",
	feeling4 = "I use this page to analyze your linguistic habits. Why do I analyze even simple small talk? Even the simplest of phrases can undergo all kinds of subtle modifications!",
	lose = "We must retreat. It's not too late to sort out our findings and try again.",
	feeling1 = "If I were to write your words just now into a poem, I would have to express it as akin to verbal vomit...",
	skill = "The shudderings of Etna and whirlwinds of the Alps upon you!",
	upgrade = "Inspiration is surging within like never before!",
	propose = "You felt the same way all along? Thank you... I promise to love you with every breath, every smile, and every tear for all my life – and even after I've been sunk, if it may be...",
	feeling5 = "\"From you have I been absent in the spring... Yet seem'd it winter still, and, you away, as with your shadow I with these did play.\" Commander, I made a bookmark for you. I wanted to present it along with one of my favorite poems.",
	main = "This document... Hmm. There's a typo on the word \"commission\" here. It's a small problem, but we should fix it.|Curious about my notebook? I've collected and analyzed everyone's linguistic habits in it... Oh, this page is yours. I'm still collecting yours.|Watching da Vinci's experiments reminds me of purgatory as written in poetry... Well, frankly, purgatory seems more promising than her works.",
	touch = "Phew... Finally, the archive is perfectly organized. ...Hm? Did you call me, Commander?",
	voice_key_2 = -1,
	mission_complete = "It looks like your missions are done. Good job, Commander. Take a break while you can... Oh, me? I just happened to get a flash of inspiration, so I'm jotting it down before I forget.",
	battle = "Preparations are complete. Let us depart.",
	id = 601110,
	gift_dislike = "",
	gift_prefer = "Thank you. I really like... No, I think it would be more accurate to say that I love it.",
	profile = "Giosuè Carducci. Third Poeti-class destroyer. Affiliation: Sardegna. This introduction ought to be more convenient for a written report, no? ...Hm? This isn't meant to be written?",
	voice_key = 60111,
	headtouch = "This is a laurel wreath – the utmost honor to a poet.",
	feeling2 = "You found my notebook?! Thank you... It's full of many of my favorite phrases. If you hadn't found it, I'd... Well, thank you.",
	login = "Commander, this document seems to be in need of revisions. For example, here and... Ahem. Sorry for rushing you. Please, sit down.",
	detail = "...Hm? Commander, how long have you been here? Sorry, I was a little too engrossed in my book. This is a Royal Navy poetry collection – want to join me? Lovely! Let's read it together.",
	couple_encourage = {
		{
			{
				60108
			},
			1,
			" Alfredo, you should put your articles through another revision phase... or three.",
			0
		},
		{
			{
				50207
			},
			1,
			" Hai Tien, I brought a collection of poems for you in return.",
			0
		},
		{
			{
				89903
			},
			1,
			" It's an honor, Brest. I adore your poetry!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[601111] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Would you like to dance with me? Oh, you'd like me to teach you... I'm happy to, but these are the only moves I know. I hope that's okay...",
	unlock = "Traveler from afar, allow me to pen a welcoming verse with this dance... Why'd I stop? Umm... S-silence is golden, as they say...",
	touch2 = "I'm losing balance!",
	mission = "",
	vote = "",
	drop_descrip = "Traveler from afar, allow me to pen a welcoming verse with this dance... Why'd I stop? Umm... S-silence is golden, as they say...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "The time I've spent dancing with you here in this palace... no, every moment we're together has been special. My dance may leave some to be desired, but I'd like to commemorate this with a poem. When it's done, I'll share it with you.",
	main = "Dance and poetry are a lot alike. They both have a rhythm and tempo you need to adhere to... It's just a little harder when it comes to dancing.|I may not be able to do the whole dance, but if you only looked right now, wouldn't you call me beautiful?|It's just like writing poetry. Careful use of empty space can rouse the imagination... So I'll leave the rest of the dance to your imagination, Commander!",
	touch = "You'd like to see other dance moves? Sorry... I may not be able to do that.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 601111,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Shall I remove my veil?",
	feeling2 = "",
	login = "Traveler, enjoy this banquet. Delicious food and wine, supplemented by bewitching dance... A moment frozen in time.",
	detail = "\"The grace of one's advance, such is the true beauty of dance...\" Sorry, that may have been too pretentious. I'll work on it.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[601120] = {
	hp_warning = "I'll never abandon a patient!",
	feeling3 = "Commander, you'll need ample sleep and lots of vegetables to stay healthy! If I happen to see you sneaking work into your bed at night... I-I'll start watching you to make sure you sleep!",
	mail = "You have mail... Yes, yes, very \"healthy\" mail. It's safe for you to open.",
	expedition = "The commission is done. I'll go ask if they need help unloading.",
	win_mvp = "N-nobody is hurt, right?",
	home = "Thanks for all your hard work, Commander. Let me take a look at you... Hmm. Your uniform and hat are in good \"health\"... You must take such good care of them!",
	unlock = "N-nice to... meet you. My name is Ugolino Vivaldi, and I'm from the Sardegna Empire. Everyone calls me Nurse Ugolino... Keep me by your side, and I'll keep you healthy and at ease!",
	touch2 = "Hyah?! Th-thank you for your concern...",
	mission = "You do have tasks that need doing, but you should really take care of your health, Commander.",
	vote = "",
	drop_descrip = "Navigatori-class destroyer – Ugolino Vivaldi.",
	feeling4 = "The thought of you actually being sick makes me feel awful... Am I the one who's suffering from some strange illness now?",
	lose = "It's okay. We'll try harder together next time.",
	feeling1 = "If your body is unhealthy, it'll affect your mind, as well... May I heal you before it's too late, Commander?",
	skill = "For the sake of everyone's safety!",
	upgrade = "I'm the very picture of good health now! Thank goodness.",
	propose = "Y-you'd really let me have something so valuable? I see... I'll care for it just as lovingly as I do for you.",
	feeling5 = "If you're feeling unwell, tell me right away! I want to help you! Even if it's just a little... It would make me so, so happy. S-so rely on me more... please?",
	main = "When you're getting a shot, don't stare at the needle. If it hurts, focus your attention on me, and the pain will go right away!|Your books might \"catch a cold\" if they're left out of the bookcase, just like you. Let's go outside and get you some sun, okay?|Plasters, bandages, disinfectant... and the candy you gave me, of course! These are all essential supplies!",
	touch = "I love this uniform! It's both comfy and durable.",
	voice_key_2 = -1,
	mission_complete = "Another mission done. I'll go check on the rewards. Oh, you can just rest here while I do.",
	battle = "I-I'll take care of everyone!",
	id = 601120,
	gift_dislike = "",
	gift_prefer = "Oh, you're too generous... Thank you, Commander.",
	profile = "I'm the Sardegnian destroyer Ugolino Vivaldi. Umm, I hear you have \"paperwork-itis.\" I'll get you fixed up right as rain in no time!",
	voice_key = 60112,
	headtouch = "You and I care for each other and look after each other... just like family!",
	feeling2 = "Ugh, why do I keep tripping... Has something gone \"ill\" in my shoes? Hmm? You want to hold hands and walk slowly? Thank you... That's very comforting.",
	login = "Commander, let me diagnose you! Hmm... You're in perfect health!",
	detail = "Huh? Oh, m-my health? Sorry for making you worry... I just bandaged up a few little scratches, that's all... I'm really okay!",
	couple_encourage = {
		{
			{
				60106
			},
			1,
			" Here's a first-aid kit. Take it with you on your adventures.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[601121] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Did you find a way to get me out of here?! Huh? Why do you have a camera...? T-to document this and prevent it from happening again? Um, w-well, I suppose that makes sense...",
	unlock = "E-examination complete... This \"sick\" claw machine seems to have mistaken me for a plushie... O-or did it realize how much I wanted the Commander to take me home?",
	touch2 = "C-Commander, you'd take advantage of me right now...?",
	mission = "",
	vote = "",
	drop_descrip = "E-examination complete... This \"sick\" claw machine seems to have mistaken me for a plushie... O-or did it realize how much I wanted the Commander to take me home?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I-if you really want to take me home as your rare prize... I'm not one to deny your wishes. In that case... p-please take good care of me!",
	main = "C-congratulations... You caught a kitten... O-ooh, this is too embarrassing...|The rare prize...? B-but I'm not a plushie! Goodness, Commander...|These plushies are so soft and fluffy... If you hadn't caught me, I might've fallen right asleep on them.",
	touch = "You wanna take a picture of me because you think I look cute...? I-if you really like this outfit... then I'll do my best to look good in it!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 601121,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Ah... Thank you, Commander. You know just how to make me feel better.",
	feeling2 = "",
	login = "Ah... I-I'm not a plushie. Commander, can you help me?",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[602010] = {
	hp_warning = "As long as I can still fight, I will!",
	feeling3 = "Don't fret over each and every obstacle you face, Commander. Your subordinates will do all in their power to help.",
	mail = "You have a letter. Whoever wrote it is brutishly uncourteous... It's what? From Naval HQ? I see.",
	expedition = "The commission team has returned to port. It is part of your job to acknowledge their efforts, is it not, Commander?",
	win_mvp = "I am the Empire's splendor – Duca degli Abruzzi! Etch this name into your memories!",
	home = "If you need rest, now is the time to get it, Commander. We will have much to do afterwards.",
	unlock = "I am light cruiser Luigi di Savoia Duca degli Abruzzi, Sardegna's splendorous dignitary. I've waited for the day to fight under your banner, Commander.",
	touch2 = "What has gotten into you?!",
	mission = "Say the word, and I will complete these missions for you.",
	vote = "",
	drop_descrip = "Duca degli Abruzzi-class light cruiser – Luigi di Savoia Duca degli Abruzzi.",
	feeling4 = "I am not just a soldier at your disposal, Commander. I am someone with a desire to understand and support you to my utmost. This desire has nothing to do with rank or status.",
	lose = "Alas, we must shamefully turn our backs on our foes...",
	feeling1 = "You've proven yourself a spineless imbecile. Get out of my sight!",
	skill = "Witness my full potential!",
	upgrade = "Now the question is, how to make the best use of my new abilities?",
	propose = "This ring could only mean one thing. You want my support till death do us apart, no? Then I will oblige. After all, there is no greater joy than knowing you want me by your side forever. Hahaha.",
	feeling5 = "What do you want to discuss today, Commander? One cannot do much without the aid of loyal supporters, and I strive to be your biggest one. Hahah. It's the least I can do to return the recognition you've given me. ",
	main = "How can you sit idly like this, Commander? We dignitaries must set an example for others to follow.|It matters not how strong your adversary is as long as you are stronger. That is what war boils down to.|Hmm. Climb Mount Niitaka? I see I'm not alone in the desire to mountaineer... What? That's not what the message means?",
	touch = "What do you need, Commander? I can perform some of your duties in an official capacity.",
	voice_key_2 = -1,
	mission_complete = "Mission complete. It's time you looked over the rewards.",
	battle = "To battle! My splendor shall be proven!",
	id = 602010,
	gift_dislike = "",
	gift_prefer = "I accept. You have my gratitude, Commander.",
	profile = "I am the Condottieri-class light cruiser Luigi di Savoia Duca degli Abruzzi, from the Sardegna Empire. I fought valiantly alongside my esteemed allies during the war. My ambition now is to achieve lustrous feats as the Empire's splendorous flagbearer!",
	voice_key = 60201,
	headtouch = "",
	feeling2 = "My name is Luigi di Savoia Duca degli Abruzzi. You find that too hard to memorize? Then you may shorten it to Duca degli Abruzzi, but no less than that. My dignity won't allow it.",
	login = "Greetings, Commander. The Empire's splendor radiates as brightly as ever.",
	detail = "I am the final development from a class of treaty cruiser. With the performance enhancements I received, victory is but guaranteed in any battle I partake in.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[602011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Is the water temperature satisfactory? You must not come here much, so make the most of your visit. If you want something, just ask for it.",
	unlock = "Good evening, Commander. Here to unwind after a day's work, I take it? Even dignitaries desire a bit of luxury sometimes. Hahaha.",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "Good evening, Commander. Here to unwind after a day's work, I take it? Even dignitaries desire a bit of luxury sometimes. Hahaha.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "What do you think of this neon-lit cityscape? It doesn't start to compare to the idyllic vistas of Sardegna, but it has its own merits.|You truly are dependable to the utmost, obliging my younger sister with your company like this.|Valiant? I'm not sure where she is. Which is concerning, as I don't believe she's a good swimmer...",
	touch = "Enjoy your time here. Let others take care of any bothersome chores in the meantime.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 602011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "",
	detail = "Fixated on my younger sister, hmm? You lend credibility to the adage that heroism breeds virility. Hahah!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[602020] = {
	hp_warning = "Knock it off...!",
	feeling3 = "It's not like a dignitary's duty is too much for me or whatever. I'd look like a fool if it was. I'm just easygoing – don't you wanna be that too, Commander?",
	mail = "A letter? Open and see what it says.",
	expedition = "Hey, you completed a commission. You should remember that, even if I forgot.",
	win_mvp = "I've won. My name is light cruiser Giuseppe Garibaldi. Easy to remember, right?",
	home = "Oh, you're back. Go ahead and take a seat. What for? The after-action review, obviously. Were you expecting something else?",
	unlock = "Is everyone doing well? Now, let's put our hands together for the port's latest arrival – light cruiser Giuseppe Garibaldi of Sardegna! ...Oh, Commander? I was just updating my shipgirl profile... And that does it! Who am I? Didn't you just hear me say Giuseppe Garibaldi?",
	touch2 = "Well, I'll be damned.",
	mission = "We've got new missions. Time to do what you signed up for.",
	vote = "",
	drop_descrip = "Duca degli Abruzzi-class light cruiser – Giuseppe Garibaldi.",
	feeling4 = "Leading and protecting your friends is what's important, not petty etiquette or manners. I've known that since day one. Heck, I'm protecting you right now... Well, in my own way.",
	lose = "Hmph, so you got us good this time. I'll be back.",
	feeling1 = "You call yourself the Commander, but you're really just a nobody. Hmph.",
	skill = "Here's what I can REALLY do!",
	upgrade = "Pretty good. Nothing to complain about and much to love. Like my new firepower.",
	propose = "I'm guessing you want me to look after you forever and ever? You got it. Simply always being there for you is a total breeze when you're Abruzzi's sister.",
	feeling5 = "Can't you take it easy at least for today? You have all these supportive girls by your side – rely on them for once. Think of it like this: I'll never be able to fulfill my duty as a dignitary of protecting you if you're always working around the clock.",
	main = "My duties as a dignitary? Ehh, don't give a rat's ass about 'em. My sis and I are worlds apart in that regard.|If what you're doing isn't hugely important, just wing it. If you mess up, someone will come and fix it.|I usually go to tea parties with like-minded people. You interested, Commander?",
	touch = "Obbedisco! Just tell me what you need.",
	voice_key_2 = -1,
	mission_complete = "Mission complete... Which is to say, you've performed your duty as a dignitary.",
	battle = "Let's get this done in a flash.",
	id = 602020,
	gift_dislike = "",
	gift_prefer = "I'll take it then~",
	profile = "I'm the final variant of a line of treaty cruisers... I think? Anyway, my time in the limelight was after the war rather than during it, for various reasons. You still wanna know more about me? Like what – my achievements, or the stats of my weaponry?",
	voice_key = 60202,
	headtouch = "",
	feeling2 = "I'll follow your orders no problem, but please don't demand more of me than that. It's just easier for us both that way. Besides, you don't like being a slave to formality like Abruzzi, do you?",
	login = "Good morning, Commander. Phew... Sardegna's splendor is shining as brightly as ever today~",
	detail = "What are you standing there all stiff for? Make yourself comfortable. I'm not gonna punish you for it. You're not the type who fusses over a noble's manners, are you?",
	couple_encourage = {
		{
			{
				60201
			},
			1,
			" I'll do as a dignitary and take the lead!",
			0
		},
		{
			{
				50101,
				50103
			},
			1,
			" Sweet rigging. I want one like that.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[602021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Watching me dance ballet is fine and all, but I think it's time you do your after-action review. People are waiting, you know.",
	unlock = "I am the evil swan Odile! Where oh where is my prince? ...Oh, it's you, Commander. My lines aside, pretty good performance, right?",
	touch2 = "It's no big deal, but something feels off about this...",
	mission = "You've got new missions. Wonder if one of them is like, make a lovers' pact and you'll be rewarded, or something?",
	vote = "",
	drop_descrip = "I am the evil swan Odile! Where oh where is my prince? ...Oh, it's you, Commander. My lines aside, pretty good performance, right?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Both the white and black swan are meant to be played by the same person, right? Doesn't that make Roma and me rivals?|Da Vinci's the kind of girl who really gets into her role, unlike me. Good for her if she enjoys it. Me, I just can't do it.|Is Abruzzi watching me? Aw crap, then I'll have to do hardcore practice or she'll chew me out. She should play a role herself if it's so damn important...",
	touch = "Will you swear your love to me? Heehee~",
	voice_key_2 = -1,
	mission_complete = "A dignitary never goes back on their promise. Mission complete.",
	battle = "",
	id = 602021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "It took getting through a storm to finally clock in, eh?",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[602030] = {
	hp_warning = "I'm fine. An injury like this isn't even worth writing in the report!",
	feeling3 = "When I work with you, I feel oddly... giddy. Oh, I-I just mean I'm happy that my efficiency has improved, of course! Nothing else... N-no hidden meaning at all, nope!",
	mail = "Commander, you've got new mail. Shall I sort it out for you?",
	expedition = "The commission fleet has returned to port. I've summarized their mission for you in this report here. Please have a look.",
	win_mvp = "Heh. When I serve as the front-line staff officer, victory is but a matter of course.",
	home = "Your missions are going well, I see. Ah, I've already compiled the combat report. Detailed notes and addendums are – oh, this? I-I only use pretty fonts to make it more engaging for you...",
	unlock = "I am Bartolomeo Colleoni, staff officer and mission support for the Sardegnian fleet. Don't worry – when it comes to tactical analysis and combat deployment, I... Oh, there I go again. Umm, I look forward to working with you, Commander.",
	touch2 = "Th-this is inappropriate. Please stop at once!",
	mission = "Commander, you have missions that still need to be handled. As your staff officer, I suggest you get to work immediately... But of course, if you're too tired at this moment, I'm willing to do them for you.",
	vote = "",
	drop_descrip = "Giussano-class light cruiser – Bartolomeo Colleoni.",
	feeling4 = "Maybe the strategy in my novel will work...! A-ahem, Commander, do you have a minute to join me for tea, or... N-no, I just wanted a meeting to discuss our strategy for the next battle...!",
	lose = "N-no way... Were my plans incomplete?",
	feeling1 = "You've disappointed me today, Commander. As a soldier, you should maintain basic discipline.",
	skill = "Calculation complete. Commencing annihilation!",
	upgrade = "I'll use this power to the fullest for the Commander's sake.",
	propose = "Hmm? Is this a document you need me to work on... Wha? Whaaat?! A-a contract?! I've imagined this so many times, but I don't feel ready at all...! Oh, my hands are shaking so much... Wh-where do I sign? I can hardly hold the pen steady. Help me, Commander!",
	feeling5 = "When I'm with you, it seems like I don't need to be so uptight... Mmm... How long has it been since I felt so relaxed? Maybe... Love really does change a person, just like in my romance books... O-oh goodness, I didn't just say that!",
	main = "Commander, I've finished today's plan... Oh, I'm sorry. Already talking about work again. You said it's okay to relax once in a while, right...?|Hm? What am I reading? Th-this is a book about how commanders and their subordinates can improve their relationships! U-umm... It's just for the sake of teamwork...|Do you think I'm well-dressed today? As a soldier, personal grooming is the most basic of basics... C-Commander?! Why are you coming so close?!",
	touch = "Hm? Do you need something?",
	voice_key_2 = -1,
	mission_complete = "Well done. I finished my report, so make sure you get your rewards... Huh? I doodled in the corner?! Pretend you didn't see that, please!",
	battle = "With my military pride on the line, I swear, I will bring the Commander victory!",
	id = 602030,
	gift_dislike = "",
	gift_prefer = "Ah! C-Commander... You don't have to be so considerate of me, you know. We have a lot of work to do... b-but let me be clear, the gift does make me very happy. Thank you!",
	profile = "I'm Bartolomeo Colleoni, staff officer and mission support of the Sardegnian fleet. I've put a lot of time into studying tactical analysis and combat deployment... Really, don't you think it's better for a soldier to be seen as uptight? Umm... You disagree? O-okay. I'll try to be better...",
	voice_key = 60203,
	headtouch = "Huh?! C-Commander, this is hardly appropriate for two military folk... But I actually don't mind that much...",
	feeling2 = "I appreciate your cooperation, Commander, but we really should keep a professional distance given our working relationship...",
	login = "Good morning, Commander. I've finished preparing the materials for today's strategy meeting... Oh? Am I being needlessly uptight? I-I'm simply presenting the professional front that any officer should!",
	detail = "My colleagues say that I'm too uptight, but on the battlefield, a moment's inattention can beckon death. ...Though when I'm up late at night writing reports, I do enjoy the occasional break with milk tea and romance novels... Ahem! Milk tea is just a tactical drink for replenishing my energy! And the novels... Umm... Don't tell anyone about those, please.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[602031] = {
	hp_warning = "",
	feeling3 = "",
	mail = "New mail? That's weird... I don't remember that being part of the plan.",
	expedition = "I'll go take care of the commission team... \"Commander, you may remain here where you belong – in my chamber.\"",
	win_mvp = "",
	home = "Welcome back. Umm, please wait a moment. I prepared fruits for your return... Ugh, where did I put them?!",
	unlock = "Hrmm... Romance novel analysis shows that this pose is the most likely to succeed... Ah. C-Commander, there you are... Ahem. \"What business do you have in my private chambers?\"",
	touch2 = "The book says I should be bolder, but this is just... Ooh, it's too much...",
	mission = "I know role-playing is fun, but don't forget your work. You have missions that need doing, Commander.",
	vote = "",
	drop_descrip = "Hrmm... Romance novel analysis shows that this pose is the most likely to succeed... Ah. C-Commander, there you are... Ahem. \"What business do you have in my private chambers?\"",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "You know... I spent a lot of time secretly putting together this outfit and room. I might seem clumsy or indiscreet, but this was my plan to show you a different side of me and conquer you, in a word... Umm, basically... I did this because I hoped it would make you like me more...",
	main = "Do you like my outfit, Commander? Is it too different from the usual? Maybe I should change... Huh? You think it's cute? Th-then I'll keep it on! Behold a soldier's tenacity!|According to my schedule... You and I should be in bed having... P-pretend I didn't say anything! Commander, do NOT look at this schedule!|Some fruit, Commander? Ahem... \"I-I bequeath this reward unto you. Partake, lest you disappoint me!\"",
	touch = "Huh? N-no, I'm not spacing out! What was... I supposed to do next?",
	voice_key_2 = -1,
	mission_complete = "\"Graciously accept the mission rewards I've bestowed upon you...\" Ugh...",
	battle = "",
	id = 602031,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Heh... Heheheh... \"H-how bold of you.\"",
	feeling2 = "",
	login = "Welcome, ahem... to my... chamber. Urk, th-this is just too embarrassing to stand!",
	detail = "Staff Officer Bartolomeo reporting! Whoops, right, I'm supposed to be playing the part of an empress... It's hard to give bedroom eyes the whole time, though.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[602040] = {
	hp_warning = "NOW things are getting interesting!",
	feeling3 = "Dearest Commander, might I suggest a little challenge? Relax and take my hand... in an unknown, wonderful, and exhilarating dance! Ooohohoho!",
	mail = "You have new mail! Will there be acrostic poems? Riddles, perhaps? Leave any puzzles to me – oh... I-I don't get this one. Ohohoho...",
	expedition = "The commission team has returned. Do you think they've brought unexpected treasures?",
	win_mvp = "I won! Dearest Commander, I humbly await your ample praise.",
	home = "What inspiring triumph, dearest Commander! Next time, let's fight an even more formidable foe!",
	unlock = "Ooohohoho! Did my magnificent dancing captivate you, dearest Commander? Consider it an official greeting from yours truly, Alberto di Giussano! Why, I'd dare wager that you will fall for me in the very near future!",
	touch2 = "O-oohohoho...! Is this a test? Well, I'll show you that I can withstand anything!",
	mission = "Let's finish these trivial tasks before we challenge ourselves. In fact, why wait? Why not see who can complete this work more efficiently?",
	vote = "",
	drop_descrip = "Giussano-class light cruiser – Alberto di Giussano.",
	feeling4 = "How can I win your heart? This has become my sweetest challenge yet. Heehee, I just know that solving it will be beyond satisfying. Prepare yourself, dearest Commander, because I'm going to put my all into making you mine. Ooohohoho!",
	lose = "Geez! We were so close! If we do it again, I just know I can win...",
	feeling1 = "Should I just work without you for a while, dearest Commander? It would certainly be a new challenge.",
	skill = "Ooohohoho! Your defeat is certain!",
	upgrade = "Now that I'm stronger, I must aim for greater heights.",
	propose = "Ooohohoho! I, Alberto di Giussano, have won the most precious wager of my life! Dearest Commander, are you ready for your next challenge? That would be... spending the rest of your life with me!",
	feeling5 = "Maybe I'm impossible to satisfy. That's why I keep dancing, dancing, and dancing more... But when I think of you, I feel oddly content. Your light is dazzling, a source of warmth that holds me instead of making me chase after it. Is this what they call love?",
	main = "Ooohohoho! Dearest Commander, behold my dazzling dance steps! Or else... all my time spent practicing will be for naught!|Dearest Commander, let's play a game. I bet I can complete our next mission with my eyes closed... What if I lose? Then you may do whatever you want with me, of course! As if that would ever happen.|Oh dear, have you seen through me? Yes, I know some challenges can be especially difficult. But with your help, maybe Lady Luck will smile upon me!",
	touch = "Oh? Are you testing my sense of balance?",
	voice_key_2 = -1,
	mission_complete = "See how quickly you've finished your missions thanks to my help? Awaiting your compliments now! Ooohohoho!",
	battle = "Ooohohoho! Bring me the strongest enemy!",
	id = 602040,
	gift_dislike = "",
	gift_prefer = "Goodness! How did you know my favorite? I'd be delighted to have it.",
	profile = "Greetings, dearest Commander. My name is Alberto di Giussano! Simple victory doesn't suit me – I prefer a triumph marked with difficulty, one that will earn me looks of admiration from my peers. Working with you should give me plenty of opportunities, I trust?",
	voice_key = 60204,
	headtouch = "Ah?! What is this nervous, ticklish feeling... M-my face is burning!",
	feeling2 = "Did my glorious dance moves leave an impression? Ballet is an art that involves making mistakes and picking yourself up every time. Ooohohoho!",
	login = "Dearest Commander, are you even more captivated by me today than you were yesterday? Huh? No...? Well, that just gives me something to strive for!",
	detail = "Do you think I'm really easy to read? When I win, I get excited. When I lose, I get angry. But I'd say that just makes me worthy of being favored by victory!",
	couple_encourage = {
		{
			{
				60203
			},
			1,
			" Forget the little details. Let our results speak for us!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[602041] = {
