_G.pg.base.ship_skin_words[603020] = {
	hp_warning = "My armor... will hold!",
	feeling3 = "Despite her appearances, Pola is a really sensitive girl, you know? And anyone who dares to hurt her... even you, Commander, would not be easily forgiven.",
	mail = "Commander? The mail is here. If you don't get to it soon, I could always read it out loud for you? I wonder if there are any love letters, hehehe...",
	expedition = "Commander, you must profusely thank all these girls for ensuring the safe delivery of these supplies.",
	win_mvp = "I've brought you victory and glory, just as I promised.",
	home = "An exhausting mission, was it? Why not relax with a glass of wine?",
	unlock = "Ciao. It's a pleasure to meet you, Commander. I'm the heavy cruiser, Zara, and I look forward to bringing victory and glory to your fleet. ",
	touch2 = "Eeek?! ... Ahem! There is more to me than my armor plating, you know? Maybe you would like a taste of my guns as well?",
	mission = "Is this mission giving you trouble? Here, let me take a look.",
	vote = "",
	drop_descrip = "Zara-class heavy cruiser – Zara. ",
	feeling4 = "Now that we're finally alone together, was there something you wanted to do, Commander? ... You want me to clean your ears? Well, all right... Come, put your head right here~ And please, try to relax, okay? I'm going to very gently, very slowly, clean your ears♪",
	lose = "Ugh... Don't make me recall the humiliation I endured that night...!",
	feeling1 = "Terrible... There's absolutely nothing about this commander anyone could ever find appealing...",
	skill = "Don't think you can pierce my armor so easily! ",
	upgrade = "Grazie! Now my main guns are an even greater threat to the enemy.",
	propose = "You really think you can bind me to you with nothing but a cheap little ring? This isn't nearly enough~ ... Hehe, don't give me that face... Haha, I'm only joking~ Don't worry, Commander. I'll be with you forever.",
	feeling5 = "Commander, after all this time together, you should already know what I'm thinking before I even open my mouth. Hehe, so who am I thinking about right now? Of course it's you, Commander, that's too easy. Hehehe♪",
	main = "Tenacemente, that is, fighting to the bitter end, no matter the odds, is my personal motto.|Looking up at the night sky, admiring the countless glimmering stars, it's really nice, actually. But it's better enjoyed from inside... don't you think?|By the way, I've actually got kind of an eye for fashion. How about I help dress you next time, Commander?",
	touch = "You like my sword, Commander? Or could it be... something else you're interested in?",
	voice_key_2 = -1,
	mission_complete = "Mission complete! My my, that's quite a big reward there, isn't it? Well done, Commander~",
	battle = "I'm used to being flagship. All ships, get into formation! Tiro!",
	id = 603020,
	gift_dislike = "",
	gift_prefer = "Did you prepare this just for me? Grazie! I'll keep it well cared for.",
	profile = "I am the first ship of the Zara class of heavy cruisers, Zara. I was born to be a marine battery, with my magnificent guns and armor plating. I served as the flagship of my squadron, at least until that fateful night...",
	voice_key = 60302,
	headtouch = "",
	feeling2 = "Is there something bothering you, Commander? Let's hear it then.",
	login = "Welcome back. I've gathered everyone up and we're awaiting your inspection.",
	detail = "Now, Pola and I are often praised for our beauty, but aren't you worried that all this ogling might cause some unsavory rumors?",
	couple_encourage = {
		{
			{
				20502
			},
			1,
			"We're allies now, huh... I'm counting on your fire support then!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[603021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Legs straight, calves stretched– Ah, welcome back, Commander. I suppose you can tell I've been teaching the others to swim. Would you like me to teach you as well? ",
	unlock = "Phew... It's a perfect day for swimming. Oh my, Commander, did you come to swim too? Or... perhaps you had something else in mind? Ehehe~♪",
	touch2 = "Really now, Commander? I understand your eagerness, but there's a time and place, no?",
	mission = "",
	vote = "",
	drop_descrip = "Phew... It's a perfect day for swimming. Oh my, Commander, did you come to swim too? Or... perhaps you had something else in mind? Ehehe~♪",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Hey, no horseplay in the pool!|I really like swimming, but the submarines and destroyers are always faster... Why is that, Commander...?|Speed is one thing, but I'm quite confident in my stamina. How about it, Commander? Want to try me?",
	touch = "Your eyes are wandering. Hehe, what's on your mind? You can tell me.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 603021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, please be careful swimming in the deep end, okay?",
	detail = "Did you do your stretches? You don't want your legs cramping up in the water.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[603030] = {
	hp_warning = "My turret won't move? Why... at a time like this...?",
	feeling3 = "Commander, focus on what you need to do. I'll take care of any annoying little obstacles in your way.",
	mail = "Commander, there's mail for you from the Naval HQ. You might miss some important information if you drag your feet~",
	expedition = "The commission fleet has returned. All your girls are such hard workers.",
	win_mvp = "MVP? Why, that's only natural. Enemies of this caliber aren't even worthy of staining my mantle.",
	home = "Welcome back, Commander. Bring back any juicy gossip for me?",
	unlock = "I'm Pola, heavy cruiser from Sardegna. And you're the commander of this fleet? I see. Well, don't let me down, okay? Hehe~",
	touch2 = "You surely didn't do the same kind of stuff to Zara, right?",
	mission = "You've got to stay motivated and finish your work... Or, were you expecting me to give you some \"motivation?\"",
	vote = "",
	drop_descrip = "Zara-class heavy cruiser – Pola.",
	feeling4 = "So, between Zara and me, who do you like better? Well... you wouldn't know the answer to that unless you tried, right~? Hehe~♡",
	lose = "My mantle's all dirty now. What a shame...",
	feeling1 = "A commander that acts in this manner is in need of some \"re-education.\"",
	skill = "Let's have a little bit of fun~",
	upgrade = "Oh? Some interesting developments.",
	propose = "Commander, once you've become my chosen partner, you must be prepared to be bound with me for a lifetime. Are you willing to sign this \"contract\" with me?",
	feeling5 = "Because you're so kind, I worry about you too, just like with Zara. But... because of your kindness, we also know that we can entrust you with our futures.",
	main = "All these \"conventions\" and \"treaties\"... Things that do not consider the feelings of actual people should disappear from this world.|A true fighter does not fear any danger. I won't back down even in the face of a heavy storm.|The feeling of being enveloped by a searchlight... makes me a bit uneasy.",
	touch = "My rapier is not simply for show, you know.",
	voice_key_2 = -1,
	mission_complete = "All done with the missions, huh? That's what I want to see. ...I haven't forgotten about the reward. Mind waiting there for a bit? Hehe~",
	battle = "The small fry never seem to learn their place.",
	id = 603030,
	gift_dislike = "",
