	vote = "",
	drop_descrip = "These stockings are so annoying to wear... Mmrgh... *sigh*. You can't give up already, Gorizia. If you want the Commander's attention... this is what you have to do!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "(I think I've put on weight again... Why did I bluff about it and let Zara pick a size that's too small for me...)|Once I wrap this task up, I'm going to muster my courage and ask out the Comma– Huh? You're working overtime today?|It's just me and the Commander now... If it wasn't for these damn stockings I could try to make a move... *sigh*...",
	touch = "Y-you'll show me how it's done? ...Hm? On the contrary; you need my help?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 603061,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "(Working late into the night while my beloved boss just... Gosh, enough of that! I need to finish my tasks quickly so I can chat with the Commander!)",
	detail = "I can help if you have too much work on your plate, my dear Commander. Just say the word. Even if we can't finish everything, I'll stay right here with you!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[603062] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "I still won even while tied up like this. It's no big deal. *stares princessly*...",
	home = "D-did you come back so soon because you worried about me? Oh, right! I definitely wasn't scouring the room in secret, and I certainly didn't put any confidential data on this USB stick.",
	unlock = "Oh nooo, how aaawful, I've been captured, and my suit is toootally in pieces... W-wait, why can't I break free? This ruins my plan of intentionally getting caught to perform an investigation...",
	touch2 = "I-if you push me any further, I'll... Eek!",
	mission = "",
	vote = "",
	drop_descrip = "Oh nooo, how aaawful, I've been captured, and my suit is toootally in pieces... W-wait, why can't I break free? This ruins my plan of intentionally getting caught to perform an investigation...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Th-this won't do! A professional spy shouldn't let her heart race as soon as her target walks into the room!",
	main = "This isn't exactly what I planned, but it's not so bad since I get to chat with you face-to-face... If nothing else, your eyes are glued to me now.|*stares princessly*... (What are you doing, Commander? Have you noticed me? I'm here! Look at me!)|Huh? My USB stick! It's going to slip out! *huff*... *puff*... Ugh! This is getting out of hand!",
	touch = "You're going to untie me? ...Wait, why did you pull your hands back?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 603062,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "I'm only not fighting back because I'm tied up. Th-this totally doesn't feel nice or anything... Are you really not going to touch me anymore?",
	feeling2 = "",
	login = "...This is the part where you look down at me with that penetrating gaze and say, \"Gorizia, all your efforts were in vain,\" and... Huh? My dear Commander, why are you laughing?",
	detail = "*stares princessly*... You're gathering intel on me, and I'm doing the same on you, my dear Commander.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[605010] = {
	hp_warning = "You hope to defeat me? With attacks this lackluster?",
	feeling3 = "Strenuous efforts on everyone's part will be necessary to spread the Empire's splendor across the world. That includes you, of course, Commander. Heehee~",
	mail = "May I offer a bit of advice? Choose your friends carefully.",
	expedition = "Were my tortellini to your tastes? I must make more to give to the returning commission team, you see.",
	win_mvp = "Sardegna's hope, faith, and love shall be felt all across the world's seas, with our fleet as its emissaries.",
	home = "I have lunch planned later with ladies from the Royal Navy. Are you interested in joining us, Commander?",
	unlock = "It's a pleasure to meet you, Commander. I am Vittorio Veneto, Eternal Flagship of the Sardegna Empire. Forgive me if I sound discourteous, but are you confident in your ability to command me?",
	touch2 = "Let it be known that this sort of behavior is abjectly inappropriate, no matter your motive for it.",
	mission = "Allow me to give you a reminder, Commander. You are in your right to delegate missions to me, your secretary.",
	vote = "",
	drop_descrip = "Vittorio Veneto-class battleship – Vittorio Veneto.",
	feeling4 = "I see not only my Sardegnian friends, but all members of the fleet, beaming with joy. How you managed this feat, I don't know, but it fascinates me to no end.",
	lose = "The enemy overpowering you by sheer force is the most easily acceptable reason for a defeat...",
	feeling1 = "It seems I must reassess the Empire's future...",
	skill = "Witness the Empire's prowess!",
	upgrade = "A most wise decision, Commander.",
	propose = "Do you comprehend the significance of this vow? Our futures are henceforth interconnected. I would normally not have accepted your proposal so easily, but your sheer passion won me over. Heehee.",
	feeling5 = "I have gained many things in our time together – power, allies, and peace of mind. Please, Commander, I'm dying to know – what is it you desire from me in return? I can offer anything you seek...",
	main = "The power of a cannon cannot be gauged by its caliber alone. Any who underestimate my 15-inch battery will pay dearly for their misjudgment.|I joined this fleet for two reasons – to achieve world peace, of course, and to further the Empire's influence. The latter of which I would like your assistance with, Commander.|Allow me to be curt, Commander. If you had the power to crush your opposition, would you still choose the path of passive deterrence? Would you choose a fleet in being?",
	touch = "Even I – the flagship of the Empire's fleet – enjoy leisure breaks from time to time. There will always come some downtime, no matter how tirelessly one works.",
	voice_key_2 = -1,
	mission_complete = "Heehee. I think I know what you're thinking, Commander. \"These missions are a cakewalk.\"",
	battle = "Eternal Flagship Vittorio Veneto, sallying forth!",
	id = 605010,
	gift_dislike = "",
	gift_prefer = "Oh, my. Have you been looking into my favorite things behind my back?",
	profile = "Expectations of me were high already at my birth, when I inherited the flag following a horrific night. Ultimately, I failed to lead my loyal friends to victory... My past isn't all that bright, is it? But that is why I have high hopes in you, Commander.",
	voice_key = 60501,
	headtouch = "",
	feeling2 = "I never would've thought one day I'd sit down for teatime with Illustrious of all people. Fate is truly a strange thing, I suppose.",
	login = "May I offer you some succulent tea and a biscuit before you start your work for the day?",
	detail = "This may be unbecoming for me to say, but nevertheless... It would delight me if you used one of our baths. It would let you fully appreciate the splendor of our Empire.",
	couple_encourage = {
		{
			{
				7
			},
			2,
			"It is reassuring to have the backing of such capable allies.",
			1
		},
		{
			{
				6
			},
			3,
			"Bow to the Empire's splendor!",
			3
		},
		{
			{
				20703,
				20704,
				20705,
				20403,
				20501,
				20505
			},
			1,
			"May your battle go fortuitously.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[605011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Would you care to sunbathe with me? It's delightfully pleasant, I assure you.",
	unlock = "Nngh, haah... It's awfully sunny today... How long was I asleep, Commander? Oh, it's already lunchtime? In that case, I'll get started on some food. Would you like something as well?",
	touch2 = "Commander? I'm still awake, for your information.",
	mission = "",
	vote = "",
	drop_descrip = "Nngh, haah... It's awfully sunny today... How long was I asleep, Commander? Oh, it's already lunchtime? In that case, I'll get started on some food. Would you like something as well?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Only when you take the time to recline can you truly take in the beauty of the vast, blue sea. One day, we will have finally reclaimed it in its entirety. Won't we, Commander?|Are you going fishing, Commander? I see, then if you don't mind, I will take my leave for a while. I'd like to finish building my sand Colosseum.|Please do come and spectate our beach volleyball game later in the evening, Commander. If luck is on our side, you may get to see us go up against the Royal Navy's team.",
	touch = "Littorio said I am terrible at photography and now she prohibits me from using the camera. Why, I've never heard something so rude before... Commander, would you ask her to let me take a picture?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 605011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Basking in the sunlight, feeling the sea breeze, and listening to the sound of the waves... Ahh, it's wonderful to have a relaxing day off.",
	detail = "A shipgirl gazing out at the sea from atop a ship... It sounds almost like the setup for a joke! I'll have to tell Littorio about it later. Hehehe~",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[605020] = {
	hp_warning = "Don't give in yet, Pugliese system!",
	feeling3 = "Be more confident in yourself, Commander. To serve as the commander of Littorio means that have earned the trust of the most glorious ship in all the world. Aren't you proud?",
	mail = "It appears there are more letters addressed to me than to you.",
	expedition = "You need not worry, Commander. For as long as I am here, your commission rewards will be superb.",
	win_mvp = "Trying to oppose me was your greatest mistake.",
	home = "Rejoice, Commander, for I am here to bid your return welcome.",
	unlock = "Rejoice, Commander! For you have gained an indomitable ally in Littorio, but more importantly... let's put a smile on that cute face of yours.",
	touch2 = "Commander, it's understandable that you would fall for me... but... this is not the time nor place for debauchery.",
	mission = "Commander, there is value to be found in all missions, so they should be carried out in earnest. Am I wrong?",
	vote = "",
	drop_descrip = "Rejoice, Commander! For you have gained an indomitable ally in Littorio, but more importantly... let's put a smile on that cute face of yours.",
	feeling4 = "Commander, I must admit that you have the qualities to become as glorious as me. That is a wonderful thing, for though I have always wanted a partner to journey with, none were capable of it until now.",
	lose = "Defeated? No, we are simply not victorious yet.",
	feeling1 = "I apologize, Commander. I only wanted to push you in the right direction, but it seems that all I did was impede your progress...",
	skill = "Arrivederci!",
	upgrade = "Your ability to see my true potential proves that your perception is superb.",
	propose = "I simply cannot understand. I was convinced that nobody would be worthy of placing this ring upon me, yet here you are before my eyes, having captured my very heart... Tell me, Commander, how did you successfully win me over?",
	feeling5 = "When you give to the world, the world gives back to you. So put your mind at ease. Pursue the object of your desire and grab hold of it. Because I, Littorio, deem you worthy.",
	main = "There are two kinds of people in the world: those who are Littorio, and those who are not.|Isn't it lamentable, Commander? There are so many places in the world that yearn for light, but there is but one Littorio.|There is no denying that, though battleships once ruled the seas, aircraft have ushered in the beginning of a new era. This is a fact that not even I can refute.",
	touch = "Chasing after others is a novel and interesting experience, is it not?",
	voice_key_2 = -1,
	mission_complete = "Contact your superiors for me. Tell them these paltry rewards do not satisfy me.",
	battle = "Did the enemy wander here by mistake? That's too bad for them.",
	id = 605020,
	gift_dislike = "",
	gift_prefer = "Promise me you'll be this nice to the other girls, okay?",
	profile = "I am Littorio, Vittorio Veneto-class battleship number two; the Mediterranean's mightiest battleship. During the war, I strutted about the ocean as if it was my garden, and that shall not change even now. Now, let us strike fear into the hearts of our enemies, Commander!",
	voice_key = 60502,
	headtouch = "",
	feeling2 = "You want my autograph? I will give you it for free, as a special favor... Just kidding. Hahaha!",
	login = "Waiting is tedious, but waiting for you is anything but, Commander.",
	detail = "That Veneto, she's not half bad for a fleet flagship... However, if she wants to move forward, she must learn from me. Hahahaha!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[605021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Heheh, I say you deserve some \"eye candy.\" Interested, Commander?",
	unlock = "A visit to the beach with me? Then you must try your hardest to stand out. Otherwise the eyes of the world will be on me alone.",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "A visit to the beach with me? Then you must try your hardest to stand out. Otherwise the eyes of the world will be on me alone.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "There are two kinds of people in the world: those who are bewitched by Littorio's swimsuit, and those who are not. Which one are you, Commander?|The Mediterranean Sea is thing of beauty in summer, but this sea surpasses it in sheer bustle. I prefer this one; it lets my glamor reach the hearts and minds of many more.|What? That damned Veneto is going to play beach volleyball?! ... I must help her, to ensure the Sardegna Empire's glory remains unsullied...",
	touch = "Donning swimwear to display one's glamor for all to see – isn't it fantastic, Commander?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 605021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I see you've returned, Commander. Hmph, today my glory shines brighter than even the sun.",
	detail = "Veneto? Don't expect much from her... No, I don't mean her swimsuit. She's the type that would spend the entire day building a sand Colosseum.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[605022] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Let us have a grand toast to the triumphant return of our hero. Alla salute!",
	unlock = "Welcome to Littorio's personal suite. Are you here to issue me a challenge of who can romance the most girls? Hahahah, I'm joking of course! There'd be no fun in a game I would win every single time.",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "Welcome to Littorio's personal suite. Are you here to issue me a challenge of who can romance the most girls? Hahahah, I'm joking of course! There'd be no fun in a game I would win every single time.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Commander... you are an unlabeled bottle of fine riserva with more charm than meets the eye – your taste enchanting, maddening, and making one possessive over you. And I – Littorio – am no exception, tesoro mio.",
	main = "Now, who will be the lucky recipient of Littorio's rose this time? Oh, but of course, Commander. If you want it, maybe you'll get it?|There are two kinds of parties in the world: those with Littorio in attendance, and those without.|I personally picked out all the various furnishings in here. It is no exaggeration to call this suite \"La Littorio\" itself. How do you like the sound of that, Commander?",
	touch = "To be frank, I've been to so many parties that I've grown a bit tired of them. Let's do something interesting for a change, shall we, Commander?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 605022,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "None but you are permitted to keep me waiting, Commander.",
	detail = "As proud as we are of our wonderful Sardegnian thermae, and as befittingly charming it is when Veneto conducts foreign relations from them, the fact remains that diplomacy should be left to the pros. Wouldn't you agree?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[605023] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Look who's back. Hang up your coat and make yourself at home. Then I can get comfortable too.",
	unlock = "Hello there. You'll have to forgive the loungewear; I have scarcely any reason to wear extravagant clothes in my private space away from the public eye.",
	touch2 = "When put before a stunning treasure, few could be satisfied with only watching from afar.",
	mission = "",
	vote = "",
	drop_descrip = "Hello there. You'll have to forgive the loungewear; I have scarcely any reason to wear extravagant clothes in my private space away from the public eye.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Come on now, stop and smell the roses. Care for a cup of cappuccino? Actually, no, it would keep you awake through naptime.|Hmm? Tired, are we, Commander? A bath in the thermae would rejuvenate you splendidly. I could go for one myself, in fact.|Veneto is a tad too formal, wouldn't you agree? She really ought to do like me and take time to unwind more often.",
	touch = "My cardigan is made of woven silk. You can appreciate its quality just from touching it, no?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 605023,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "You certainly took your sweet time... It's not every day I let a person see the casual side of me, you know.",
	detail = "As a leader, part of my duty to my people is to make the decisions that lead to tranquil days where everyone may rest easy.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[605024] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Once the rain's stopped, I'm going to take a nice, long bath. What about you, Commander? You could join me in the thermae if you'd like.",
	unlock = "Talk about bad luck, we're caught in a rainstorm right now. Unfortunately, it seems we'll have to wait it out here, Commander.",
	touch2 = "To be frank with you, I WOULD say this isn't the time for this, buuut...",
	mission = "",
	vote = "",
	drop_descrip = "Talk about bad luck, we're caught in a rainstorm right now. Unfortunately, it seems we'll have to wait it out here, Commander.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "What is it? ...I'm soaked through and through? Well, look who's talking. We're both dripping down to our ankles.|Knowing Impero, she'd run outside barefoot without a care in the world about getting wet if she was caught in the rain. She wouldn't let anyone stop her, either.|You could go to work in the rain, or kick back and relax while you wait for it to stop. When the weather gives you a free pass, why not seize the day, after all?",
	touch = "Oh? Feasting your eyes on the rare sight that is me in rain-soaked clothes, are you?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 605024,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Going somewhere, even though it's still raining? You could simply stay with me instead. Hahaha!",
	detail = "Should've brought an umbrella, you say? ...Let's forget how that wouldn't help in a massive downpour and focus on enjoying this providential quiet time we have, shall we? Hahaha!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[605030] = {
	hp_warning = "Where is my legion?!",
	feeling3 = "Commander, which do you find more gratifying – conquering land, or conquering hearts and minds? ...Both, about as much? I see you're an insatiable soul.",
	mail = "A new letter? Perhaps it is a declaration of surrender from afar.",
	expedition = "Commission rewards have arrived. Splendid. We need these for our next plan.",
	win_mvp = "But of course. The foundation of my glory is built upon those who stood in my way.",
	home = "Now is a good time to assess which place to conquer next.",
	unlock = "I am Roma, the inheritor of Romulus' will. Commander, Protector of the Seas, Guider of the Port, Leader of Our People – how would you like me to address you?",
	touch2 = "You needn't be shy to admit whether or not Roma has conquered your heart, Commander. I already know the answer.",
	mission = "Mission instructions, you say? I do not appreciate having orders imposed upon me.",
	vote = "",
	drop_descrip = "Vittorio Veneto-class battleship – Roma.",
	feeling4 = "Why did you intervene when I took wares from the store earlier? ...It's against the store's rules? Hmph, is the purpose of great power not to rewrite the rules?",
	lose = "Commander, I'm afraid I need more legionaries.",
	feeling1 = "Beacon of Incompetence, the Loathsome One, or the Savage Brute – which title do you feel suits you best, Commander?",
	skill = "I shall liberate you from the toils of war.",
	upgrade = "The key to defeating a strong enemy is to be even stronger.",
	propose = "You and I are now as one, bound together unto eternity. In other words, defiance against you is defiance against me... Be a little more considerate of others, you say? Very well. If that's what you wish... then I shall try.",
	feeling5 = "How tragic it would be to conquer a world and have no one to share it with. Commander, should I meet an unfortunate fate, it shall be you who inherits Roma's splendor.",
	main = "Have you ever gazed out from the port's highest vantage point? If not, I suggest you try it sometime.|Negotiate with the enemy? I'd rather not waste my time. However, I can gladly draft a declaration of war if you so wish.|I do not fear danger, because I am more fearsome than danger itself. Hah!",
	touch = "What do you seek from Roma? Come, offer your tribute.",
	voice_key_2 = -1,
	mission_complete = "You've completed a mission? It may be time to grant you the title of \"Fulfiller of Duties.\"",
	battle = "Be crushed by Roma's exalted light!",
	id = 605030,
	gift_dislike = "",
	gift_prefer = "This is an interesting gift. I like it.",
	profile = "I am battleship Roma. Sadly, I did not get to enlighten the world with my splendor during the war. You've given me a second chance, and for that, I'm in your debt. A favor to me is a favor to Roma, and Roma always repays her allies.",
	voice_key = 60503,
	headtouch = "Do you wish to obtain my blessings, Commander?",
	feeling2 = "Are you apprehensive of me? Good. I do not get along with frivolous people who act unnecessarily friendly around others.",
	login = "The clock is ticking, Commander.",
	detail = "Veneto's idea of a thermae party is one that I adore. When people strip naked, they unconsciously lower their guards and let their secrets slip. Furthermore, bathing itself is quite enjoyable.",
	couple_encourage = {
		{
			{
				60107
			},
			1,
			" Show me a battle worthy of Captain Pompeo's name!",
			0
		},
		{
			{
				60702
			},
			1,
			" Yes, Impero is great.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[605031] = {
	hp_warning = "",
	feeling3 = "",
	mail = "You have a new letter. I believe it's a ballet invitation. Shall we attend, or are you too busy? I shall dispose of it if so.",
	expedition = "New commission rewards have just arrived.",
	win_mvp = "Nobody is allowed to disturb the peace tonight.",
	home = "I told you to stay here, didn't I? To make up for leaving, you shall spend twice as long rehearsing a pas de deux with me.",
	unlock = "You seem to have known that I would be here. Then stay and spend the night with me. Just the two of us.",
	touch2 = "",
	mission = "New missions? I'm afraid now is not the right time for those.",
	vote = "",
	drop_descrip = "You seem to have known that I would be here. Then stay and spend the night with me. Just the two of us.",
	feeling4 = "",
	lose = "Hmph... The flames of war have sullied my gorgeous tutu.",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "You wish to see me perform on the stage? I'd be happy to if it would spread Romulus' splendor... However, I ask that you be patient until I've perfected my dance.|While the cursed princess-turned-swan can only reassume her human form at midnight, I can dance whenever I please.|Garibaldi, despite the nonchalance she ordinarily displays, plays the black swan quite well. I sincerely acknowledge her skill.",
	touch = "This is what a pas de deux is like? How novel.",
	voice_key_2 = -1,
	mission_complete = "A mission has been completed. Strange, as I could've sworn you've been here from the start... Are you able to clone yourself? Heehee.",
	battle = "",
	id = 605031,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Our march fades into the blackness on nights with dim moonlight. That is likely the reason I why couldn't detect your presence here.",
	detail = "A bath is a great way to wash off the fatigue of dancing. I say that not just for myself, but for both of us.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[605032] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "",
	unlock = "",
	touch2 = "",
