_G.pg.base.ship_skin_words[605050] = {
	hp_warning = "Everyone, stay vigilant!",
	feeling3 = "Commander, what do you think about when you gaze up into the night sky? I always think back to that night... when the skies were ablaze with what looked like countless meteors.",
	mail = "New mail has arrived... I'm not your butler, and you're perfectly capable of getting it yourself. Look, it's by your right hand.",
	expedition = "The commission squad has returned to port. Were you sending this bunch to a parade or something?",
	win_mvp = "One will never tire of victory.",
	home = "A hard fought battle. Next, there are many missions that you must attend to... Oh my, it would appear that I've accidentally finished everything. Do have some tea and rest for a while.",
	unlock = "I am the dreadnought, Conte di Cavour. There is much that I can do for you, Commander, but that depends on whether or not you are trustworthy.",
	touch2 = "Just how little do you think of me?",
	mission = "Hmm... The number of missions you've completed seems to be lower than the number of missions you were given. Commander, may I ask why?",
	vote = "",
	drop_descrip = "Conte di Cavour-class battleship – Conte di Cavour. ",
	feeling4 = "Long live the glory of the Sardegna Empire... Forget it, it's all in the past now. I'm getting used to being in this fleet, so let's look ahead.",
	lose = "Ngh... Must I also bow my head to the passage of time...?",
	feeling1 = "You will eventually pay the price for your arrogance.",
	skill = "This volley... shall not be my last! ",
	upgrade = "Thanks for your consideration.",
	propose = "You're giving such an important thing to me...? I... this is... ahh! I'm sorry, I can't keep my composure, but I'll try my best to say it... \"I do!\" How's that? P-please let this embarrassing ritual be over already...",
	feeling5 = "I said \"let's look ahead,\" right? In that case, I'll cover your back. That way, no matter what happens, you can always keep your eyes ahead of you and leave the rest to me.",
	main = "A gown? I have no interest in things like that. Nor will I ever. |Commander, if I ever get invited to one of those Royal tea parties, please tell them that I am too busy with secretary work. |Some people used to hold me to lofty expectations, but it feels natural to see the next generation surpass me.",
	touch = "Allow me to say this: judging people by their appearance will be your downfall.",
	voice_key_2 = -1,
	mission_complete = "One more name off my list... Oh, I was talking about the list of unfinished missions.",
	battle = "It is time to clad yourselves in courage and wisdom!",
	id = 605050,
	gift_dislike = "",
	gift_prefer = "You put more thought into this than I'd expect.",
	profile = "I witnessed the ascendancy of the Imperial Fleet as well as its decay into powerlessness. Commander, I pray that you, as the leader of the fleet, will never repeat the tragedies of the past.",
	voice_key = 60505,
	headtouch = "",
	feeling2 = "As one of Sardegna's veterans, I have ample experience ranging from communication to fleet management. If you need any advice, feel free to ask me.",
	login = "Save your breath. Let's begin today's work.",
	detail = "Leonardo da Vinci... had that tragedy not occurred, she surely would've fought to the last breath for the glory of the Sardegna Empire, just like Cesare.",
	couple_encourage = {
		{
			{
				20502
			},
			1,
			"A Royal Knight, huh? I never expected to fight alongside someone like you.",
			0
		},
		{
			{
				60506
			},
			1,
			"Cesare, follow me!",
			0
		},
		{
			{
				6
			},
			3,
			"The glory of Sardegna... yes, it used to shine brighter.",
			3
		}
	}
}


_G.pg.base.ship_skin_words[605051] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	couple_encourage = "",
	expedition = "",
	win_mvp = "",
	home = "My \"ammo\" is about to run out... Commander, fetch me more water!",
	unlock = "Commander, take this. Good, for the time being, you are a now a disciple under my command. It is time for us to mete out punishment to the unruly.",
	touch2 = "Y-you traitor...!",
	mission = "",
	vote = "",
	drop_descrip = "Commander, take this. Good, for the time being, you are a now a disciple under my command. It is time for us to mete out punishment to the unruly.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Huh?! Where'd that sneak attack come from? I've gotta answer back...!|Cesare, this is the only time we'll be fighting on the same front. Let's do this!|Not as much as a damn molehill on this beach... Where's a soldier supposed to hide herself...?",
	touch = "You've helped me a lot. Thank you.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 605051,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Curses... I can't believe people are seeing me in this soggy, ugly mess... What, I'm cute? Wh-what kind of sick joke is that? Come help me already!",
	detail = "It's always the normally quiet types that end up making the boldest statements at the beach..."
}


_G.pg.base.ship_skin_words[605060] = {
	hp_warning = "You won't break my spirit so easily!",
	feeling3 = "A little bit of harsh discipline is the right medicine for slouches who can't obey orders. \"It's not that simple\"? Well, I thought I was making a good suggestion...",
	mail = "There's a letter for you. Assuming it's no private matter, you don't mind if I open it, do you?",
	expedition = "Isn't that the commission team? Why not go say hello to them, Commander?",
	win_mvp = "Veni, vidi, vici.",
	home = "Triumphant once again, yes? It's written all over your face.",
	unlock = "I'm Giulio Cesare, battleship of the Sardegna Empire. Prove to me your talent in commanding a fleet!",
	touch2 = "If you plan on toying around with me, don't blame me when you get burned.",
	mission = "You can honestly skip missions you'd rather not take on.",
	vote = "",
	drop_descrip = "Conte di Cavour-class battleship – Giulio Cesare. ",
	feeling4 = "A little bird told me you're free, and I've got two tickets to the opera, so what do you say? I'd say you're due for something you haven't experienced before.",
	lose = "Am I out of my depth...?!",
	feeling1 = "Seems you lack the mindset to be a worthy commander.",
	skill = "All shall bow before my might! ",
	upgrade = "I've yet to hit my own limits!",
	propose = "*Sigh*... The romantic vacation I booked was all for nothing... \"With who\"? With you, shouldn't that be obvious?! ... \"Just ask me next time\"? But I booked it just for you in the first place... F-fine, I will...",
	feeling5 = "You can rest easy, Commander. For as long as I have your back, you can keep your eyes on the path ahead and continue moving forward. I'll take care of everything else for you!",
	main = "Office work? Cavour is better at it than me... but I'll still do it. As any secretary should.|Commander, be decisive. Hesitation wastes time, and wasted time is gone forever.|A good leader doesn't micromanage or mediate, they issue clear orders and make firm decisions. Isn't that right, Commander?|Cavour, don't be so overly formal around the Commander! No one wants to be treated like an old-timer!",
	touch = "Mh... Mm? Sorry, I zoned out for a bit... Were you worried about me, Commander?",
	voice_key_2 = -1,
	mission_complete = "On the topic of completing missions, does it even affect the war situation?",
	battle = "As per the Commander's orders, we depart for the front!",
	id = 605060,
	gift_dislike = "",
	gift_prefer = "Is this for me? Th-thanks...",
	profile = "Memories that haunt me? None but that dreaded battle. I had to retreat from the Battle of Punto Stilo after taking a single hit... Things would've gone differently, had I only gotten to strike first...!",
	voice_key = 60506,
	headtouch = "",
	feeling2 = "Cavour always stresses the importance of courtesy and diplomatic discourse, but I believe in simply speaking one's mind. Doesn't it sound dreadful to obsess over some idea of formality?",
	login = "You're right on time... Naturally. I'll admit your timeliness is the one thing I could learn from.",
	detail = "At last I can have a rematch with Warspite on equal terms. I've been waiting for this!",
	couple_encourage = {
		{
			{
				20502
			},
			1,
			"Our battle isn't over yet!",
			0
		},
		{
			{
				60505
			},
			1,
			"Cavour, worry about yourself instead!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[605061] = {
