_G.pg.base.ship_skin_words[605062] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Are you charmed by my prowess in battle, or just me? Haha~",
	home = "Want some ice with your Sardegnian liqueur? It's best downed in one gulp when it's this cold.",
	unlock = "Tired already? For goodness' sake, I thought you'd be more reliable than this. Don't go burning all your energy at once, we still have a whole day of recreation ahead of us.",
	touch2 = "Surely you know what consequences await you for doing that.",
	mission = "",
	vote = "",
	drop_descrip = "Tired already? For goodness' sake, I thought you'd be more reliable than this. Don't go burning all your energy at once, we still have a whole day of recreation ahead of us.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Warspite's taking part in the beach volleyball tournament? You should've told me so sooner!|Trento and Pola are out for you, so you came here to lie low, didn't you? ...No?|This is not a playground, Cavour! Take your watergun fight elsewhere! ...I'll be right back, Commander. I'm going to have a word with that wannabe commando!",
	touch = "I do like this bikini, though it doesn't quite match up to Veneto's.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 605062,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Hey, Commander. I hope you're not tired already, or else you'll be branded as unreliable.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[605070] = {
	hp_warning = "H-hold steady just a while longer!",
	feeling3 = "Something on your mind, Commander? It's not healthy to bottle up your emotions... How did I know? Heehee. Because you're like me – when you feel bad, it shows in your expression.",
	mail = "There's a new letter. Maybe the milk I ordered has arrived already?",
	expedition = "Commission complete. Let's go give our thanks to those hardworking girls.",
	win_mvp = "I hope my results will inspire others.",
	home = "A few girls stopped by while you were gone. Oh, and I wrote a note of what they wanted to tell you. You can read it, if you'd like.",
	unlock = "Greetings, Commander. I am Andrea Doria, Sardegna Empire battleship. I'm honored to be working with you. Oh, and if anyone in your fleet needs a helping hand, I'll support them as best as I can.",
	touch2 = "N-now you're being naughty...",
	mission = "You have a new mission. Why not leave it to someone else as a bit of practice?",
	vote = "",
	drop_descrip = "Andrea Doria-class battleship – Andrea Doria.",
	feeling4 = "*sigh*... Am I doing the \"cool role model\" thing right? I feel like people don't think I'm someone they can rely on... You think I'll find out by instead relying on them for a while? Okay, in that case... Can I rely on you, Commander?",
	lose = "It's okay. We might have lost this time, but next time, the Commander will lead us to victory!",
	feeling1 = "What happened to you, Commander? If it's help you need, I'm here for you.",
	skill = "Don't come any closer!",
	upgrade = "That's right, a role model can't afford to fall behind!",
	propose = "For you to acknowledge me in this way is the highest honor in my opinion... Will things stay the same, moving forward? Of course! I'll do whatever you ask, whenever you ask! Maybe I'll even ask you for something from time to time... Heehee♪",
	feeling5 = "It's exhausting always trying to be there for everyone... But, as long as I have you, I'll always get back up whenever I'm near my breaking point. It's like you, uhh, refill my energy and confidence... I suppose? Heehee~ You're my bosom buddy, Commander♪",
	main = "Do you want more hot milk? I'll heat up some more right now. Enjoy it while it's warm.|Sometimes I just want to relax, but I can't let my guard down in case someone comes by... *sigh*... Do you ever have that problem, Commander?|Commander, am I doing a good job keeping up appearances? I'm not too nice to people, am I? I'm bad at self-evaluating...",
	touch = "Mmh... Do you find this relaxing, Commander?",
	voice_key_2 = -1,
	mission_complete = "Mission complete! I'm glad to see everyone doing so well.",
	battle = "I won't embarrass myself in front of the people who look up to me.",
	id = 605070,
	gift_dislike = "",
	gift_prefer = "For me? Oh, it's not that I don't like it... Quite the opposite, I love it! H-hehe...",
	profile = "I'm Andrea Doria, the lead ship of my class. While I don't have any accomplishments to brag about, I really try to look after those close to me! S-so, come to me if you need help.",
	voice_key = 60507,
	headtouch = "",
	feeling2 = "There are all kinds of shipgirls at this port, some of whom are naughty and cause you headaches, I'm sure. But when you're at your wits' end, you can rely on me.",
	login = "Getting to work this soon, Commander? Why not have a hot cup of milk before you begin?",
	detail = "*sigh*... Commander, do I seem dependable to you? I don't want those who look up to me to see me as incompetent... Yeah, exactly. I have to be a role model to people.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[605071] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission team has come back? Let's bring them some drinks as a show of thanks!",
	win_mvp = "",
	home = "What the...? Is this compartment broken? The door won't close... Commander, could you help me out there?",
	unlock = "\"I'm your stewardess, Andrea Doria, here to ensure you have a pleasant flight\"... Did I sound natural, Commander? ...Still a bit on the stiff side, huh? *sigh*, this job really isn't easy for first-timers...",
	touch2 = "I told you to stop being naughty, Commander...",
	mission = "",
	vote = "",
	drop_descrip = "\"I'm your stewardess, Andrea Doria, here to ensure you have a pleasant flight\"... Did I sound natural, Commander? ...Still a bit on the stiff side, huh? *sigh*, this job really isn't easy for first-timers...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "\"I'll now demonstrate how to use a life jacket\"... Erm, Commander, how do I do this again?|What drink would you like – juice, coffee, or soda? I have hot milk as well, of course.|You there, please keep quiet on the aircraft! I'll get the Commander if you don't simmer down.",
	touch = "Give me a call if you ever need anything.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 605071,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, we're landing soon, so fasten your seatbelt. Should I take your bags and stow them away for you?",
	detail = "\"Thank you for flying with us today\"... Uhh, do you think my delivery is okay? I'm new to this and I don't wanna screw up...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[605080] = {
	hp_warning = "Hmm. Getting kinda fed up here...",
	feeling3 = "I'm sorting through my refs, and it's going well! You know, every single thing you do really DOES inspire me! I'mma draw every last one of these then hang 'em all over your office while you're out.",
	mail = "New letterino! Hey, why don't we fold it up into a paper boat and send 'er down the river?",
	expedition = "Commission complete! I'll go say hi with you! Promised the girls I'd draw the moment you meet up with them, y'see!",
	win_mvp = "A perfect victory, and a perfect source of inspo!",
	home = "Ah, back you are! Hold on a sec... There! Your side profile looks suh-frickin'-preme from this angle!",
	unlock = "You're that famous Commander, huh? Lemme get a reeeal close, intimate look at you... Oh, excuse me! Yet to introduce myself, haven't I? I'm Raffaello of the Sardegna Empire, and I am NOT a freak! Hope you don't mind if I make every beautiful moment in your life into a painting! I'm gonna paint all the less flattering ones too, just so you know.",
	touch2 = "Ohhh... Oh, frick yeah... You got my heart pumping now!",
	mission = "Hey, you've still got missions to do. Mind if I sit beside you and draw while I wait? I'll pour you some coffee while I'm at it!",
	vote = "",
	drop_descrip = "Type UP41 battleship – Raffaello.",
	feeling4 = "Seems you've gotten used to me observing you – from your first cuppa joe in the morning, to how you grimace while reading paperwork at night... It still ain't nearly enough for me, though! Lemme put a microcamera on your collar – I need my fix! What? Is that a step too far?",
	lose = "Fiddlesticks. I won't hold back next time!",
	feeling1 = "You were a blank sheet with so much potential, and you turned into an old painting you can't change... Man, what a disappointment.",
	skill = "Get a load of the power of ART!",
	upgrade = "Props for building me! I'll be sure to draw many, many more masterpieces of you♪",
	propose = "Finally... Finally this precious moment has come. The gentle touch of your fingers will forever be imprinted upon my heart... Heehee. Allow me the honor to depict every moment of our lives together from now on, using the most pious brushstrokes!",
	feeling5 = "I'm happy to report that after extensive, detailed, and intimate observations, the conclusion I've come to iiis... you really are my endless source of inspo! O flawless God of Inspiration of mine, let me depict every little part of you♪",
	main = "The natural lighting in your office is just perfect! Can I make this my temporary studio? I already brought my sleeping bag! ...Huh? You're worried I'll get carried away and not go outside for a whole week again? I mean, I go outside when I've got no inspo. When I do, though, I draw 'til the well's completely dry!|You've been getting reports of some weirdo hanging out on rooftops 'round the port? I was just... drawing in different places, that's all. Is that not allowed? Even if I do it for free?|A casual observer might say you've made the same serious look while reading papers today, but I counted at least seven different types of gazes! When you're reading something especially unreasonable, you unconsciously look up and to the right...You knew I've been observing you this whole time? Well, you're welcome!|Imagine if we covered all your office walls with mirrors – then I could observe you from dozens of different angles! Hm? That'd make it harder for others to navigate? That's kinda what I was going for, you kn– Err, I mean! It's all for the sake of art!",
	touch = "Oh, Commander, next time you wanna get my attention, can you form a cross with your index and middle fingers? From my point of view, that composition will look so peak!",
	voice_key_2 = -1,
	mission_complete = "Lessgo! Mission complete! Let's balance these pens on our chins and run 'round the office for a change of pace! ...No? I'll do it just by myself, then!",
	battle = "Let's go! I'm gonna make a masterpiece as destructive as a meteorite strike!",
	id = 605080,
	gift_dislike = "",
	gift_prefer = "Ooh... I-I've never been given such a perfect gift. Have you been watching me, Commander? YES? Hahaha☆",
	profile = "Grazie, my beloved Commander! I'm Raffaello, a Sardegnian girl who cares little about hierarchies and stuff and more about defining herself as an artist committed to capturing beauty. My plan is to draw every single moment we spend together in painstaking detail – and especially to draw the little things even you yourself don't notice!",
	voice_key = 60508,
	headtouch = "Oohh! The inspo is kicking in! Ogh, ohh!",
	feeling2 = "Still doesn't feel like we're that close, you and I... Be calm, though! My methods guarantee we'll get closer! Oh, also, it feels like our pace is faster than usual today... Dynamic beauty like that still makes for a good painting, though!",
	login = "Heyo! There you are, my wellspring of inspiration and favorite research subject. I can't wait to see what fun encounters you and I will have today☆",
	detail = "A-ha, you wanna know more about me, don'tcha? Well, be my guest – ask all the questions you want! Later, I mean – 'cause I've been staying up and drawing for a whole week straight and my head isn't on straight right now. Let me just make a staw-and-cup telephone and we'll do some direct brain-to-brain communication instead!",
	couple_encourage = {
		{
			{
				69901
			},
			1,
			"Have you cooked up some new scheme? Can I hear about it?",
			0
		},
		{
			{
				60503
			},
			1,
			"Mmhh, this atmosphere... It's Roma!",
			0
		},
		{
			{
				60802
			},
			1,
			"We're gonna make works of art that transcend time!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[605081] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Ah, a commission from the mortal world? I shall permit you to briefly leave this place, then!",
	win_mvp = "",
	home = "No matter where you run, you'll always return to me in the end. That's your bound fate, my dear collection piece♪",
	unlock = "Heheh! You were not invited to this place, and as its guardian, I must punish you by... Oh, wait, wait, stop! This angle... This outline... It's simply perfect! Turning you into stone would be a waste, so just stay here and let me observe you every day!",
	touch2 = "Ohh... This behavior is so blasphemous... but so good!",
	mission = "How dare a lowly intruder leave an unfinished mission in the domain of a god? Unacceptable!",
	vote = "",
	drop_descrip = "Heheh! You were not invited to this place, and as its guardian, I must punish you by... Oh, wait, wait, stop! This angle... This outline... It's simply perfect! Turning you into stone would be a waste, so just stay here and let me observe you every day!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Despite you being a hapless invader in a god's domain, I knew from first glance that you were the perfect collection piece I've been searching for... As the Protector of Love and Beauty, I shall bind you to this place forever! Yes, because you're worth drawing for all of eternity!",
	main = "You wanna leave, huh? Heh. You've entered my domain, my eternal tra– You know the drill! You're the best ref I could ask for, and I'm gonna draw out each and every one of your expressions!|Whoa there, intruder! You're in my holy domain, so you must remain under my watchful gaze! Heehee. This is a great chance to draw some art, so hold real still!|A common invader means nothing to the Protector of Love and Beauty – but I didn't expect a mortal to show me such beauty... Heehee. You're staying by my side from now on!|I'll let you go if you manage to drink all the liquid in this pot. Hm? You keep drinking but it never runs out? Heehee! The gifts of God are endless!",
	touch = "Hmm? Want a refill?",
	voice_key_2 = -1,
	mission_complete = "Something just arrived... Oh, since I laid eyes on these mission rewards, they're mine now!",
	battle = "",
	id = 605081,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Hmm? I'll forgive that transgression just because you're so beautiful!",
	feeling2 = "",
	login = "What's this? Trying to escape today? Sorry, that's not gonna happen until you finish this Eternal Beverage. Be good and stay put so I can observe you♪",
	detail = "Don'tcha agree that the role of Protector of Love and Beauty fits me like a glove? Presiding over a holy domain, watching an eternal collection... Ooh, just putting it into words is giving me tons of inspo!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[605082] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome your very own art magic~ Come and immerse yourself in this world I weaved from my warmth and color☆",
	unlock = "Welcome to the Circus Art Roadshow! What do you think, Commander? Did my present make your heart race? I used everything I have to complete this art... And I mean EVERYTHING♪",
	touch2 = "Can't restrain your creative urges anymore?♪",
	mission = "",
	vote = "",
	drop_descrip = "Welcome to the Circus Art Roadshow! What do you think, Commander? Did my present make your heart race? I used everything I have to complete this art... And I mean EVERYTHING♪",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I thought this artwork lacked soul, so I decided to liven it up into a trick painting and made it truly complete by incorporating myself as part of the art... Just kidding☆ What it was really missing was you! My inspiration, my muse, my beauty incarnate, the miracle in my magic♡",
	main = "Nhaaa! The paint splotches you left behind just gave me a flash of inspiration...!|Are your eyes fixed on me, Commander...? Come, get a little closer♪|Isn't the painting's background lovely, Commander? Reach your hands out to me... Ahaha☆ Did you touch it?~|Would you like to add a stroke on me with your own hands? Let beauty guide you and leave your own unique, creative mark on your favorite spot♪",
	touch = "Are you curious about how the colors you apply blend together? If you wanna know, you should try it once and see for yourself♪",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 605082,
	gift_dislike = "",
	gift_prefer = "",
	profile = "Being a work of art is really hard! I can't move, so if I ever get an itch... I'm gonna need you to touch me right here, real gentle. Aaah♡ A bit higher~ Yes, just like that♪",
	voice_key = 0,
	headtouch = "Please don't touch the art without permission...! But keep giving me inspiration please♪",
	feeling2 = "",
	login = "Oooh! Seeing my perfect Commander step into my painting melts my heart away♡ Come, join my magic, and join my art☆",
	detail = "Being a work of art is really hard! I can't move, so if I ever get an itch... I'm gonna need you to touch me right here, real gentle. Aaah♡ A bit higher~ Yes, just like that♪",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[605090] = {
	hp_warning = "Ugh... So irritating! Your voice, Commander! I need to hear your voice!",
	feeling3 = "Your existence renders unnecessary my restraints... Is this really how it ought to be?",
	mail = "A new letter has arrived. Could it be news of a victory, or judgment for me?",
	expedition = "The commission team has returned with spoils... and turmoil from the outside.",
	win_mvp = "Let the filth be returned to dust.",
	home = "I suppose... this is what it means to wait.",
	unlock = "I am Francesco Caracciolo, the magistrate of the Sardegna Empire. If you do not fear my power, then please allow me to pursue a moment of peace by your side.",
	touch2 = "Give me peace... Give me love.",
	mission = "Commander, you have new missions. Do not let business unfinished become a waking nightmare.",
	vote = "",
	drop_descrip = "Francesco Caracciolo-class battleship – Francesco Caracciolo.",
	feeling4 = "I've walked through darkness with no stars to guide me. I hear it now... The sound of your voice, in the wind's whispers from afar.",
	lose = "Fate eventually strips us of everything...",
	feeling1 = "Why do you linger here? Nothing remains... within this shadow.",
	skill = "Heehee... Now... Let all fall into the abyss!",
	upgrade = "Commander, I implore you to \"discipline\" me in your own way. Keep me bound to your side.",
	propose = "This vow is greater than the eternal night, and more beautiful than the faint light of dawn... This whole body of mine I surrender to you. Please forevermore show me the way.",
	feeling5 = "I used to hold that life was a series of winters, until I met you... That's when I knew true warmth for the first time.",
	main = "Your fingers bring me greater reassurance... than the cold of the chains.|Say something, won't you? Even an offhand comment can subdue the power that itches within me...|Tsk... So irritating... Commander, let me hear your voice... I want you!",
	touch = "So you seek to get to know me better... Curiosity killed the cat.",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Let us return to the embrace of silence.",
	battle = "I shall judge your sins.",
	id = 605090,
	gift_dislike = "",
	gift_prefer = "An item imbued with your sentiments, is it? I will treasure it.",
	profile = "I am Sardegnian battleship Francesco Caracciolo, the bound magistrate awaiting the dawn that shall never come in the eternal night.",
	voice_key = 60509,
	headtouch = "Well... If this helps you relax, then so be it.",
	feeling2 = "My true strength, you ask? It rests within this bound body of mine. Even I have never seen it in its entirety before.",
	login = "When you're here, the turmoil within my mind quiets down.",
	detail = "You so easily pierce through my defenses... Is this a blessing, or a different form of judgment?",
	couple_encourage = {
		{
			{
				60111
			},
			1,
			" To think that poetry could be as sharp as a blade...",
			0
		},
		{
			{
				60508
			},
			1,
			" The sacred light that you depict... It's so radiant.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[605091] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Hm? A good angle, you say? Then let's continue.",
	unlock = "Now it is laid bare before you... The shadow that even the sun's light cannot pierce. This is my complete, unfiltered confession to you.",
	touch2 = "Mgh... In darkness that even the light avoids, what do you ascertain?",
	mission = "",
	vote = "",
	drop_descrip = "Now it is laid bare before you... The shadow that even the sun's light cannot pierce. This is my complete, unfiltered confession to you.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Once all pictures have been developed, you will find the answer that lies hidden in each and every one – that I have long since given you my true self.",
	main = "You say that this will capture my true self... What am I to do, Commander? Will you assist me?|The tether that coils around my body is a gentler one... Or is it, truly?|Adjust the hem? One moment... How's this?",
	touch = "What did the camera capture – my pious confession, or proof of my sins?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 605091,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Mgh... My hair is in the way... Could you straighten it for me again?",
	feeling2 = "",
	login = "...Do you wish to see more of my \"truth,\" Commander?",
	detail = "My attire? I merely changed from a heavy restraint to a gentle bind. Do you think it suits me?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[607010] = {
	hp_warning = "I'm not some frail young miss who'll go down in a single blow...!",
	feeling3 = "Miss Graf Zeppelin? In terms of our history, I'm quite similar to her, right? In that case, \"I shall hope that we may forge the bonds of camaraderie\"... Eheh~",
	mail = "There's new mail, my Commander. Please choose your words carefully when replying.",
	expedition = "A commission has been successfully completed! Good work, everyone! My Commander, make sure to offer them words of praise as well!",
	win_mvp = "Oh my, I won! Hehe, was this victory to your satisfaction, my Commander?",
	home = "My Commander, should I assist you in turning down any troublesome requests?",
	unlock = "Good day to you, my Commander. I'm Aquila, aircraft carrier from the Sardegna Empire. Our meeting today is no mere coincidence. No, it must be a gift from Fortuna herself, I'm sure of it.",
	touch2 = "My Commander, I do apologize, but... may I refuse this kind of behavior...?",
	mission = "We've got a mission direct from the Naval HQ... It might be pretty tough...",
	vote = "",
	drop_descrip = "Aircraft carrier – Aquila.",
	feeling4 = "My Commander, look out! ...Phew, thank goodness. By the way, why did you come visit me in the middle of my aircraft training? Did you... perhaps want to see me at my most vulnerable?!",
	lose = "Ugh... Did I make a mistake somewhere...?",
	feeling1 = "My Commander, are you still alive? ...Well, if I keep doing this, I'm sure you will come back to your senses...! *thwack*!",
	skill = "I do believe it is time to say goodbye~",
	upgrade = "I feel more experienced now... As long as I do as I practiced in battle, I'm sure everything will be fine!",
	propose = "I've prepared many, many words for today's occasion, but first, I'd like to hear your words of love, my Commander~♪ After all, you're the one who proposed to me. Hehe, what do you think I should do?",
	feeling5 = "There's been something on my mind recently... \"Just how should I make myself more appealing to you, My Commander?\" ...What do you think? Please, teach me all sorts of things~♪",
	main = "Sleeping on the job is not something that an excellent commander would do. My Commander... *poke* *poke*... Care to wake up?|My Commander, you should try using gentle words to get an emphatic point across. You'll find the results quite remarkable.|My Commander, will you allow me to organize the warehouse with the help of my planes? ...The previous accident? Well, that was just a one-off thing~ Ahaha...",
	touch = "My Commander, did you need me for something?",
	voice_key_2 = -1,
	mission_complete = "My Commander, I just knew you'd complete your missions without a hitch! Thank goodness~",
	battle = "Mm, hmm! Yes, this is how it's supposed to be... Fly, my aircraft, fly!",
	id = 607010,
	gift_dislike = "",
	gift_prefer = "I graciously accept this.",
	profile = "My \"history\"...? Hmm... I do feel a longing for something like that. If only I had been finished a little sooner during that war... My Commander, don't you think I would've had an enviable service history?",
	voice_key = 60701,
	headtouch = "",
	feeling2 = "My Commander, have you already completed today's missions? And did you finish checking off the documents? This is just a friendly reminder from Aquila~ Mhm, no need to thank me~",
	login = "We're going to have a busy day. Thanks in advance, my Commander.",
	detail = "So this is how you're supposed to launch carrier-based planes... I think I've got the hang of it... Hyah! ...Oh no, I guess it really is nothing like launching seaplanes...",
	couple_encourage = {
		{
			{
				40701
			},
			1,
			"I do hope we can get along, Miss Graf Zeppelin.",
			0
		},
		{
			{
				20703,
				20704,
				20705
			},
			2,
			"Well met, fair ladies of the Royal Navy~",
			0
		},
		{
			{
				60502
			},
			1,
			"Wow, as dashing as ever today~",
			0
		},
		{
			{
				30601,
				30602
			},
			2,
			"Have a nice trip~ Uh... Did I get something mixed up?",
			0
		}
	}
}


