	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Yummy treat~ Become sweet and replete~♪ Commander, I've prepared a little magic spell to make your tea that much tastier~♪|Shall we invite Carabiniere as well next time? I'm sure she'll be quite surprised~♪",
