_G.pg.base.ship_skin_words[607020] = {
	hp_warning = "If I must exercise my brilliance, so be it...!",
	feeling3 = "Have you finally decided to pledge your loyalty to me? ...Hm? I suppose you are a brilliant Commander, but I am also brilliant. How about we swear an oath of mutual loyalty, then?",
	mail = "Seems the wind brought this letter straight to your desk. Oh, you saw me bring it in? Welp.",
	expedition = "The commission team's back. Go give them my regards.",
	win_mvp = "Daring to pick a fight with the brilliant Impero isn't heroic. It's just foolish.",
	home = "You've returned. Now where's my thank-you for getting up to bid you welcome back?",
	unlock = "I'm Impero of the Vittorio Veneto class. Introduction over – now back to sleep... By the way, I'm brilliant. So you don't need to boss me around... Just give me my space and we'll be good. Night.",
	touch2 = "...Sleazebag.",
	mission = "Missions, hmm? Completing them is key to furthering Sardegna's splendor.",
	vote = "",
	drop_descrip = "Aircraft carrier – Impero.",
	feeling4 = "I could do nothing – not even lift a finger – and I'd still contribute to Sardegna. To serve you, however, I have to put in real work.",
	lose = "They caught wind of my spaghetti planes? I see... Sorry. This is my fault.",
	feeling1 = "Get out of my sight. I've no need for a snake like you.",
	skill = "Kneel before me!",
	upgrade = "*yawn*...",
	propose = "Hm? Is this a ring? You want to marry me? I should probably tell Veneto about this first... Oh, I can do that later? All right, good. I love being free of responsibility because I'm so brilliant. I'll leave the formalities to you, Commander.",
	feeling5 = "I did a task for you. It was sloppy, but I'm not used to doing work, so cut me some slack. Nobody's born knowing how to work, are they? My point is... Exactly. I appreciate the compliment.",
	main = "Is Veneto still up? She has this splendrous aura when she's awake. It's dazzling, genuinely.|The only things I need in life are bread and my smartphone. Wait, Oxy-cola too. Oh, and warm baths...|You could build a slide outside the office window that leads to my dorm room for quick access. Great idea, right?",
	touch = "Ready to kneel before me yet?",
	voice_key_2 = -1,
	mission_complete = "Mission complete, at the cost of nearly all my precious energy... Take it from here.",
	battle = "Gaze upon Sardegna's splendor – MY splendor!",
	id = 607020,
	gift_dislike = "",
	gift_prefer = "Hmm. Not bad at all.",
	profile = "I'm Impero, fourth ship of the Vittorio Veneto class. Kneel and pledge your loyalty to me, now. Why? Because I'm brilliant, so I deserve special treatment.",
	voice_key = 60702,
	headtouch = "...You really like playing with my hair, huh?",
	feeling2 = "There needn't be a reason why I'm brilliant. Brilliance is inherent, self-apparent, and unmistakable for anything else. Veneto said that, so yeah.",
	login = "Evening. *yawn*... I'm going to sleep. Wake me when it's sortie o'clock.",
	detail = "Need something? Come back in 3 hours after I've had my bath. But, if it's urgent, join me in the bathtub and we'll discuss it.",
	couple_encourage = {
		{
			{
				30708
			},
			1,
			" You awake, sleepyhead?",
			0
		},
		{
			{
				60501
			},
			1,
			" I've got the skies covered, Veneto.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[607021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Now I can read another three pages. Awesome.",
	home = "Ah, you're back. You hungry? I'm kind of famished, so let's hit the cafeteria in a few.",
	unlock = "Seems school uniforms are all the hype. Veneto picked this one out for me. What are you dressed as, Commander? A teacher? A classmate?",
	touch2 = "...Mgh. Hm? Huh?",
	mission = "",
	vote = "",
	drop_descrip = "Seems school uniforms are all the hype. Veneto picked this one out for me. What are you dressed as, Commander? A teacher? A classmate?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Bookmarks are a genius invention. They save me the effort of remembering how far into a book I am.|Zzz... Oops, I nodded off. If you wanna borrow a book, go ahead. Anyway... *yawn*... Hang on, what page was I on again?|It's practically impossible to stay awake in class. But you manage, Commander. Keep on being a brilliant student.",
	touch = "You here to return a book, or...?",
	voice_key_2 = -1,
	mission_complete = "These mission rewards let me read a few minutes more. Brilliant.",
	battle = "",
	id = 607021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Evening. Here's what I'm doing to further Sardegna's splendor today... Zzz...",
	detail = "Do you like reading too, Commander? ...Yeah, I do, 'cause I dream of the comfy stories I read. Do you?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[607022] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "The skewers at this bar are pretty delish. Have a li'l bite, Commander! ...Huh? Why do you have two heads?",
	unlock = "Ugh... I don't wanna work... I don't wanna work... I don't wanna work... Commander? Finished your overtime shift? Great timing... Come and drink with me!",
	touch2 = "Mmh... Oh yeah... I want more...",
	mission = "",
	vote = "",
	drop_descrip = "Ugh... I don't wanna work... I don't wanna work... I don't wanna work... Commander? Finished your overtime shift? Great timing... Come and drink with me!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Whew... I'm just so glad to forget about work. I feel like I'm floating on a cloud... Commander, I want every day to be like this – carefree, no need to work... Pretty please... From now on, you're in charge of my happiness... Zzz...",
	main = "I'm hungry, but I don't wanna move... Feed me, Commander. Nom...|I'm thirsty, but I don't wanna move... Pour a drink into my mouth, Commander. Mmh...|My uniform's too tight... Who the hell came up with this cumbersome design? I'm requesting permission to come to work in a dressing gown... Zzz...",
	touch = "Drink up, Commander. The day only really starts after you've clocked out...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 607022,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "That's good... Keep going... Stroke me more...",
	feeling2 = "",
	login = "My job is so exhausting... I don't wanna work ever again... You do the heavy lifting, Commander – I'll be sleeping...",
	detail = "Listen, Commander, I was so brilliant today... I worked a bunch, I went to observe the thermae, then I went to observe the public bath... I'm running on fumes...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[608010] = {
	hp_warning = "I wanna get out of the water...",
	feeling3 = "Yuubari said thanks? I just gave her an idea for a c-cannon modification, that's all... Now she wants my help with it, too? Uhh, I'm gonna pass...",
	mail = "There's mail for you. I've made sure nobody's read it but me... Hehe, hehehe...",
	expedition = "The commission team's back? I couldn't care less... You're gonna go see them? I-I'll tag along then...",
	win_mvp = "Can I come up now? Okay, I-I'm heading back now... Hehe, hehehehe...",
	home = "I know this scent... When I smell it, it means you've come b-back... Hehe, hehehehe...",
	unlock = "You've gotta be the commander... My name is T-Torricelli, here to claim this room for myself... Don't worry about me, I'll just be sitting in some quiet corner... Hehe, hehehehe...",
	touch2 = "I guess this means I've c-caught your interest...",
	mission = "Missions? Ugh, I hate missions... Could we just pretend they don't exist...",
	vote = "",
	drop_descrip = "Brin-class submarine – Torricelli.",
	feeling4 = "Commander, can I come a step c-closer? Hehe, hehehehe... Your hand feels so nice and warm... Hehe...",
	lose = "I-I'm resurfacing and going back...",
	feeling1 = "You're even edgier than I am... Hehehe...",
	skill = "Stealthily...",
	upgrade = "My guns could use an upgrade too...",
	propose = "Hehe, hehehe... Now you're obliged to provide for me forever... That was j-just a joke... So, what comes next...?",
	feeling5 = "I'm glad I have somone as d-diligent and charitable like you to count on... Hehehe... Y-you want me to give you a hand sometimes? I-I'll try...",
	main = "You're awful busy today, Commander... You want my help? Umm... I-I'll think about it...|It's safe and quiet under the surface... I'd love to have you down there with me... Hehe, hehehehe...|Could you... c-close the curtains, please? The sunlight... it burns...",
	touch = "Mine don't hold a candle to the massive mounds of some other girls... Hehe, hehehe... Sorry if that disappoints you, Commander...",
	voice_key_2 = -1,
	mission_complete = "Leave the mission rewards alone for too long and shrooms might start growing on them... Hehe, hehehehe...",
	battle = "Do whatever, it doesn't matter, I just wanna get this over with quick...",
	id = 608010,
	gift_dislike = "",
	gift_prefer = "Is this for me? Heh, hehehe... I-I accept.",
	profile = "I'm Brin-class submarine Torricelli... Just remember my name, and I'll be happy... My battle with the Royal Navy? It taught me a lesson about what happens when you underestimate your enemies... Hehehehe...",
	voice_key = 60801,
	headtouch = "Ooohh... Ahh, hehehe... M-more...",
	feeling2 = "Like I said, don't worry about me... I'm right here, out of sight, out of mind... Hehehehe...",
	login = "Ehh?! C-could you not pop in out of the blue like that... It scares me...",
	detail = "Wh-why are you looking at me...?",
	couple_encourage = {
		{
			{
				80801
			},
			1,
			"Your personality is my k-kryptonite...",
			0
		},
		{
			{
				30805
			},
			1,
			"I'm not sure we're on the same wavelength...",
			0
		}
	}
}


