	main = "Don't be scared, little turtle... I won't hurt you, I just wanna watch... Hehe, hehehehe...|I need this straw hat to protect me, or else the sunlight would melt me...|A letter in a bottle? The ocean currents must've brought it here... Hehe, it's the plight of a poor girl who'll never be real... Hehe, hehehehe...",
	touch = "You're not p-planning something, are you...? Hehehe...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 608011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Eep! H-how do you keep appearing out of nowhere...",
	detail = "I'll trade you this shell for a coconut, Commander... Hehe, hehehehe... You have only to g-gain from this deal, don't you see? Hehehe...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[608020] = {
	hp_warning = "Think, da Vinci! How will you get out of this pickle?!",
	feeling3 = "Whenever I get a new idea, I sketch it down and store it in my satchel. I love keeping a physical record of all the inspiration I get!",
	mail = "Got a letter for you! I brought it here at max speed♪",
	expedition = "Commission rewards have arrived! With fresh materials come brand spanking new ideas~ Heheheh♪",
	win_mvp = "Talk about a cakewalk! Well then, my search for inspiration continues♪",
	home = "Awesome work out there! ...You're running on fumes, huh? Unfortunate. I'd give you half my energy if I could~",
	unlock = "Heya, Commander. I'm the Sardegnian submarine Leonardo da Vinci, but you can just call me da Vinci. Now that I'm finally here at the port, I hope every new day is a wellspring of inspiration!",
	touch2 = "Whuh?! Wh-where do you think you're touching?",
	mission = "New missions, you say? Let me at 'em! I can do it all, from drafting to completion! ...What? It's a task only you can get done?",
	vote = "",
	drop_descrip = "Marconi-class submarine – Leonardo da Vinci.",
	feeling4 = "Are you free, Commander? Then have a look at this blueprint as well as this, this, and this and tell me whatcha think. Two heads are better than one, and I want your feedback!",
	lose = "Crap, I goofed that one up...",
	feeling1 = "I should probably build some sort of gadget that sounds an alarm when you're nearby...",
	skill = "Let's see how you like THIS!",
	upgrade = "Mhm! I'm getting all sorts of new ideas here♪",
	propose = "What you're saying with this is that you love me, correct? It goes without saying that I love you too♪ On another note, looking at this shiny ring is giving me an idea... Namely, a ring that literally glows! Let's make one, Commander!",
	feeling5 = "Commander! You free again? Like they say... Look below you for ideas, look around you for inspiration! Time: from dawn 'til dusk – place: every nook and cranny of the port! Heheh! I'm bound to come up with something new this way!",
	main = "I've got an idea for an automatic seal stamper! You just put it on a ready document and it stamps it for you, saving both time and energy♪|Take a break? But I don't need one! I'm just fine. Besides, my brain fires on all pistons when I'm searching for inspiration♪|Whoa, my mind just birthed a fresh idea... Commander, let me borrow your pen! And your ruler and compass! Okay, it's something like this... *scribbles*|This little guy's my Autonomous Dive-Bombing Sneak-Attacker Minisub! Huh, you think that's too long? Then, uhh, let's go with Canguro! Make sure the two of you get along!",
	touch = "I see there's a blueprint here! Time to see whether it can be built or not, Commander!",
	voice_key_2 = -1,
	mission_complete = "Mission complete! Surf the waves of accomplishment to the next challenge♪",
	battle = "I've already worked out an angle of attack!",
	id = 608020,
	gift_dislike = "",
	gift_prefer = "Ooh, yeah. I'll keep this one safe!",
	profile = "I'm Leonardo da Vinci, the Marconi-class submarine who completed many patrol missions! My hobby is inventing fun things! Like this little lion – just push the button here and a flower pops out of it!",
	voice_key = 60802,
	headtouch = "Ah... I just came up with a new idea! Commander, keep it up!",
	feeling2 = "Now, Torricelli, behold my latest invention! ...Huh? Where'd she go? Don't tell me she went hiding in some dark corner again!",
	login = "Welcome back, Commander! Me? I've been here all morning. Heheh, stunned by my sheer vitality, aren't ya?",
	detail = "Behold, Commander! My latest invention – the mechanical spaghetti winder! It saves two minutes per serving, so assuming two servings a day, you save 1,460 minutes over a year! Hah-hah! Am I a genius or what?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[608021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Hey, I rehearsed a bit while you were out! Though I'm still nowhere near Roma's level.",
	unlock = "Here to watch me rehearse just like these deer, Commander? Isn't it wonderful being surrounded by the beauty of nature? For a performance based on a fable such as this one, ambiance is key. Ehehe~♪",
	touch2 = "D-d-d-don't sneak up on me like that!",
	mission = "",
	vote = "",
	drop_descrip = "Here to watch me rehearse just like these deer, Commander? Isn't it wonderful being surrounded by the beauty of nature? For a performance based on a fable such as this one, ambiance is key. Ehehe~♪",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "If only there was a device that could accurately translate the cries of these deer... Guess I have to invent one myself, eh?|Do you reckon I could fly with these wings if I scaled them up? Imagine the midair dances I could do. They'd be stunning!|Watch closely, Commander! Here comes my grand fouetté en tournant♪ Wheee... Oh god, that made me dizzy... Th-that was kinda overkill...",
	touch = "Ballet's actually not hard. Come on, just take it slow and repeat after me~",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 608021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Dancing among the beautiful flora and fauna makes me feel like I'm becoming one with nature.",
	detail = "If ballet and invention have anything in common, it's that they both take inspiration from animals. So, dancing among animals is a great way to get new ideas♪",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[608022] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "What an easy win~ And I get lots of applause and inspiration as my reward♪",
	home = "Welcome back, Commander! Would you like to watch my swinging tricks? Or maybe just relax together?♪",
	unlock = "Ah, Commander! I got a flash of inspiration when I swung to the top just now! Let the magic show begin now!",
	touch2 = "Eek?! Commander, you're such a tease. Are you looking for inspiration in the middle of a performance?♪",
	mission = "",
	vote = "",
	drop_descrip = "Ah, Commander! I got a flash of inspiration when I swung to the top just now! Let the magic show begin now!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "So long as you're watching me, I know I could pull off any magic trick, even in the middle of a high swing. This sense of safety... that matters more than any inspiration♪",
	main = "Maybe we should make a portable swing? That way I'll be able to whoosh around wherever I go!|This sense of weightlessness, of speed, it's completely different from when I'm lost in inventing... Ah, I just came up with a new idea!|Si cominica! Commander, next up... Waaah?! All the cards in my hat... they all turned into design sketches?!",
	touch = "Are you just going to watch? Come on, gimme your hand! Let's fly high enough to touch the stars♪",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 608022,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Heheh, don't forget to fix my ears back the way they were♪",
	feeling2 = "",
	login = "Commander? Did you see me perform just now? I was just testing a little theory. I wanted to see if being suspended in midair makes one's inspiration a bit \"lighter\"♪",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[608030] = {
	hp_warning = "Is this the time I finally sink? Yeah, right!",
	feeling3 = "You've been pretty interesting as of late. You finally understand me, don't you? Heehee.",
	mail = "I have a letter for you, Commander. Heehee, I didn't do anything to it. Nope, nothing at all!",
	expedition = "A commission's been completed. What do you say we go and receive the girls?",
	win_mvp = "Heheh. Told you that an improvisational fighting style is more efficient!",
	home = "Hey, Commander, I didn't follow your orders the other day, did I? You know what that– It worked out in the end, so no punishment for me? Dang...",
	unlock = "Ciao, Commander. I'm Maggiore Baracca, but just call me Baracca. Heehee, you look like you're lots of fun. Let's be friends♪",
	touch2 = "Mgh... You're an audacious one, Commander... Oh, is this your way of punishing me? Okay, continue...♥",
	mission = "Seems you have new missions. Wanna try completing them under a time limit?",
	vote = "",
	drop_descrip = "Marconi-class submarine – Maggiore Baracca.",
	feeling4 = "Lately, it's been making my heart race whether you scold me or smile at me... I've never felt it beat this fast before...♥",
	lose = "Well, safe to assume the Commander will punish me for this...",
	feeling1 = "Even after all my blunders, you still won't get mad at me... How disappointing.",
	skill = "Let's make this more dangerous!",
	upgrade = "Heehee. Someone's in for a world of pain... Oh, I was talking about the enemy, that's all!",
	propose = "Oh, you're serious this time? Oh, dear... You really caught me. You're awful, scolding me while presenting that thing to me. What if I said no? Will you be harder on me? This is a tough choice... but my answer is yes!",
	feeling5 = "Even just spending time with you gets my heart pumping now... but I still wanna tease and prank you. Heehee. I can't help it, it's just so cute when you lecture me♥",
	main = "Hm-hmm-hm♪ Hm? Where I went? Well, there's a crevice here that leads to the attic. It gives a great view of your office. Wanna go have a look? ...What? You don't? Alright, then I'll keep the best seat.|These missions today are so plain. How about something more exciting? Like if I were to intentionally miss my torpedoes during today's exercise... I'm not participating in any exercise? I guess not...|Commander, I organized your work files. The ordering might be a little different from what you're used to... That's reason enough for you to punish me, right?",
	touch = "Commander... You're gonna have to be more forceful than that.",
	voice_key_2 = -1,
	mission_complete = "You completed a mission. About those rewards... Will you punish me if I hide them somewhere?",
	battle = "I'm the flagship? But I might suddenly appear or disappear!",
	id = 608030,
	gift_dislike = "",
	gift_prefer = "Hey, Commander... There's something I want even more than this, you know...",
	profile = "I'm Maggiore Baracca. I may have a penchant for stimulating experiences, but I stop just short of getting into actual danger, so don't worry about me. And yes, I've been pranking you lately to get you mad at me. It's more exciting than playing with danger. Of course, I know my limits – I just want to see you scowl at me!",
	voice_key = 60803,
	headtouch = "Huh? What a letdown... I mean, thanks for the headpat! I guess...",
	feeling2 = "Oh, doesn't look like you really react to my pranks. I suppose I'll have to take them a step further, then!",
	login = "Oh, you're here early, Commander. Heehee. I tried to \"sort\" your paperwork while you were gone, but, well... Now that you know who did it, it's time to punish me♥",
	detail = "Commander, you wanna come with me and see if the port has any restricted areas or buildings you can only reach by scaling a wall? Don't worry about you getting hurt, because I'll be there!",
	couple_encourage = {
		{
			{
				40602
			},
			1,
			" You'll have to try harder if you want the Commander's punishment... That's not what you're after?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[608031] = {
	hp_warning = "",
	feeling3 = "",
	mail = "You've received new messages? Heehee. Don't even think about asking for help. It's just you and me in here.",
	expedition = "Oh, the commission team is back? Hmm... Alright, I'll come with you – partly to make sure you don't escape.",
	win_mvp = "",
	home = "Ah, welcome back. Want a taste of these offerings to God? You are eligible to take a bite.",
	unlock = "Oh, I wasn't expecting that you'd come here, Commander. As the God of Death, I will have to pass \"judgment\" on you♪",
	touch2 = "Oh dear... I am a God, and yet you're so violent with me... Heehee. It's exciting... and novel.",
	mission = "You have unfinished missions. Why don't we incorporate them into a game of sorts? Then it'll be easier to beat me.",
	vote = "",
	drop_descrip = "Oh, I wasn't expecting that you'd come here, Commander. As the God of Death, I will have to pass \"judgment\" on you♪",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Heehee. I'm not surprised YOU were able to beat a God like me... You think I lost on purpose? That I did. What can I say? I want to be punished so badly♥",
	main = "Heheh... This is pretty comfortable. Do you wanna lie next to me? Sure – if you can beat me at a game. Win, and I'll let you do whatever you want!|Oops... I \"accidentally\" squirted fruit juice at you. How will you punish a God such as me, I wonder?|Weighing your soul and passing judgment accordingly is so trite. To spice things up, I came up with a few exciting games. Heehee. Since you're here, why not play with me? You're certainly not getting away if you don't!",
	touch = "Hmm? Do you want me to judge you that badly?",
	voice_key_2 = -1,
	mission_complete = "Maybe I hid the mission rewards here... You'll have to come closer to find out!",
	battle = "",
	id = 608031,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Hm? Such blasphemy, headpatting a God... Oh well, it's you, so I'll let you off the hook!",
	feeling2 = "",
	login = "You came at just the right time. I just found out about a fun game... Yes, the loser has to take a punishment. Wanna play with me?",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[701020] = {
	hp_warning = "I haven't had enough to drink...",
	feeling3 = "Always I get told to stay away from strange people, but you're not strange, comrade Commander. Meaning it should be fine to accept food from you.",
	mail = "There's nothing odd about me delivering your mail, comrade Commander. We all take turns doing it, after all.",
	expedition = "Comrade Commander, I will go to the pier ahead of you. I'm eager to meet everyone who's returned.",
	win_mvp = "хорошо. Now I'm getting warmed up... Huh? It's over already?",
	home = "Comrade Commander, want some borscht and hot cocoa?",
	unlock = "здра́вствуйте, comrade Commander. I am Gnevny-class destroyer Grozny, reporting for duty... What is the matter, comrade Commander? The item in my right hand? This is my lovely кролик. It's a cute убийца.",
	touch2 = "кролик bites when it gets angry. Well, not so much bite as slice... I guess.",
	mission = "\"She who does not work, neither shall she eat,\" seems to be the rule here. With that in mind, we should finish these missions now so we may drink tomorrow.",
	vote = "",
	drop_descrip = "Gnevny-class destroyer – Grozny.",
	feeling4 = "It's not decent to ask you to share your food all the time, comrade Commander. That's why I'm going to start sharing mine with you. Here, want a drink?",
	lose = "Blahh... I've had a few drinks too many...",
	feeling1 = "You're strange, comrade Commander. Everyone tells me not to talk to strange people, but wouldn't you be lonely then...?",
	skill = "кролик, грызть! (Sic' em, Królik!)",
	upgrade = "I much prefer the Northern Parliament's drinks! *burp*!",
	propose = "I think I like me a drink more than a ring. Here, drink this, and we'll become family, comrade Commander. Hm? You might be right; aren't we already like family...?",
	feeling5 = "*burp*... We've drunk all there is, comrade Commander. It feels like my drinks taste better when we enjoy them together. Let's have some more another time... *yawn*... But now, I need some sleep...",
	main = "*burp*... Say, comrade Commander, do you know anyone else who drinks this? One with bunny ears? Interesting...|Those \"Four Unbreakables\" are a cool bunch. I wish I could join them, but that's not possible 'cause that would ruin the naming convention. Very unfortunate.|I don't like foxes or invaders, 'cause they both try to take my home from me. Once they show up, you must drive them away.",
	touch = "Comrade Commander, is this snack my reward for my hard labor...?",
	voice_key_2 = -1,
	mission_complete = "Well done, comrade Commander. Now we have all the ingredients for tonight's soup.",
	battle = "I dunno what to say. Let's go with... Ураааа!",
	id = 701020,
	gift_dislike = "",
	gift_prefer = "It smells good... May I open it, comrade Commander?",
	profile = "I am Gnevny-class destroyer Grozny. I was part of convoys, laid mines, and provided shore firing support at one point. Call for me if you have orders, comrade Commander. And if you'll let me indulge in some drinks, I'll be delighted.",
	voice_key = 70102,
	headtouch = "",
	feeling2 = "Everyone tells me that is getting food from strange people is one thing, but making strangers *into* food is not okay.",
	login = "*burp*... Hello, comrade Commander. You followed my scent? Then how about a drink?",
	detail = "Lifting my lovely кролик really does make comrade Commander behave. Just as Chapayev said.",
	couple_encourage = {
		{
			{
				30154,
				10127
			},
			2,
			"Are you a bunny? That's cute.",
			0
		}
	}
}


