_G.pg.base.ship_skin_words[701030] = {
	hp_warning = "Looks like it's time for me to get serious!",
	feeling3 = "Ahaha... Comrade Commander, we're already friends, right? So, uh, when they come to collect debts, could you... Hey, wait, why are you running!",
	mail = "Ah, um... Just give me a minute to come up with an explanation as to what I'm doing in this room full of mail...",
	expedition = "Commission complete! Hehe, first, we have to welcome everyone back!",
	win_mvp = "How's that? My power is surging! That's right, don't get jealous!",
	home = "I can't control my overflowing inspiration! Even though you just came back, I can't...",
	unlock = "Ура! How's that, what'd ya think? Huh? Where I'm from, they said you're supposed to surprise the people you're greeting! What, I'm the one being welcomed?! Sorry, I mixed something up!",
	touch2 = "Eh...?! Is this revenge for something I did?!",
	mission = "Comrade Commander, wait until you hear about the latest idea I got! Hey, wait, don't run away!",
	vote = "",
	drop_descrip = "Leningrad-class destroyer – Minsk.",
	feeling4 = "Comrade Commander, I thought you were a real hardass, but turns out, you're actually quite interesting! You have quite a lot of ideas of your own... and most importantly, you don't chew me out when I mess up! Hahaha!",
	lose = "Woah, woah, time out! I'm not ready to retreat yet! Waaah!",
	feeling1 = "Comrade Commander, you're really quite an insipid person. You won't score any admirers that way.",
	skill = "It's my turn! Fiiire!",
	upgrade = "Woahh! I'm getting inspired again!",
	propose = "This means we've signed off a lifelong contract! Comrade Commander, we'll always be together from here on out! Don't worry, don't worry, I'll be gentle!",
	feeling5 = "All right, I finally understand now! I've finally reached a conclusion as to why I'm always thinking about you! So here's my hypothesis: I'm in love with you! Hehe, does that sound right?",
	main = "Gangut...? Err, I mean, Comrade Gangut? Hmm, she kind of scares me... |My fighting spirit, just like my inspiration, is unbreakable! That's right, I'll stand back up again! |When I mess up, I make sure to apologize profusely! That way, everyone will forgive me... hopefully.",
	touch = "Hm? Did you stumble into your own inspiration, Comrade Commander?",
	voice_key_2 = -1,
	mission_complete = "Long live the rewards! Err, so, where's my share?",
	battle = "Can you keep up with me? Ура!",
	id = 701030,
	gift_dislike = "",
	gift_prefer = "Спасибо! You get me, Comrade Commander!",
	profile = "I'm the Project 38 destroyer, Minsk. I fought in the Great War alongside my sisters! Comrade Commander, expect great things from my inspiration... and my hard work!",
	voice_key = 70103,
	headtouch = "",
	feeling2 = "Comrade Commander, if you want people to like you, you've gotta be an interesting person yourself! In other words, what you need is a dose of inspiration!",
	login = "Comrade Commander, you came at just the right time! I just had a flash of inspiration and came up with a new strategy! Come test it out with me!",
	detail = "Heheh~ Comrade Commander, have you come to participate in my new inspired experiment?",
	couple_encourage = {
		{
			{
				70201
			},
			1,
			"Woah, Avrora, you're totally inspir... I mean, shining today!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[701031] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Prisoner, exercise time is over! Hurry up and get back into the office!",
	unlock = "You've violated the Minsk Protocol, comrade! Therefore, the sentence appropriate for you is imprisonment! Until when? Obviously, until your jailor is satisfied~♪",
	touch2 = "Congratulations, you've earned yourself a one-way ticket to a Siberian potato-digging trip! Sign right here, and enjoy~!",
	mission = "",
	vote = "",
	drop_descrip = "You've violated the Minsk Protocol, comrade! Therefore, the sentence appropriate for you is imprisonment! Until when? Obviously, until your jailor is satisfied~♪",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Congratulations, Comrade Commander, you've completed your sentence~ Well, even without your sentence, I'll still be supervising you for the rest of your life. After all, your next sentence is \"staying with Minsk forever!\"",
	main = "If you try to escape again, I'll slap more time onto your sentence? Huh? You weren't given a sentence in the first place? Eh, don't sweat the details~ |Hehe, you think you can stage a jailbreak? I'd like to see you try, Comrade Commander! |When I'm not patrolling, I'm writing reports... this jailor business is super boring! Hey, one of you prisoners, write the reports for me!",
	touch = "Heheh~ Do you want to get tased that badly~?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 701031,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Entrust your faith with god, and entrust your body with me! That's right, you're in my jail now! ",
	detail = "Fools, dance for your overlord~♪",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[701040] = {
	hp_warning = "I won't concede defeat!",
	feeling3 = "With a nickname like \"the Blue Cruiser,\" you'd expect me to be someone who's cute and well-behaved right? People are always disillusioned as all hell after meeting me... and, well, I can't blame them. What do you think, dear comrade?",
	mail = "I brought the mail. You don't have to thank me for it or anything.",
	expedition = "Dear comrade, did you forget about the commissions? Are you dumb? Even I remembered.",
	win_mvp = "Ура! Did you witness my true power!",
	home = "Welcome back. ...Tea? Nah, I have vodka though.",
	unlock = "I'm Tashkent. Some call me the Blue Cruiser. Another comrade who wants to woo me? It's just about recruitment...? I see. What a hopeless fellow you are.",
	touch2 = "Eh...? What are you trying to do? Are the puffy balls on my outfit that interesting?",
	mission = "Missions? Is there anything that looks interesting?",
	vote = "",
	drop_descrip = "Tashkent-class destroyer – Tashkent.",
	feeling4 = "I'm just a normal girl. I don't want special treatment or anything. The same goes for you, dear comrade, I'm sure of it...",
	lose = "Curses! Tashkent can still fight!",
	feeling1 = "Stay away from me, moron.",
	skill = "I'll have you witness my true power!",
	upgrade = "It's my turn to fight? ...Is that so? Fine, I'll do it.",
	propose = "So, this was the important thing you were telling me about? ...Sure, I'll take it. ...What, didn't I already tell you before that I like you? So, nothing wrong with us getting married, right?",
	feeling5 = "I don't really know anyone here, but everyone seems to genuinely like me. That's even after knowing what kind of person I am, so I want to be better. Of course I feel the same way about you, dear comrade. After all, I like you!",
	main = "I was born in Sardegna, so I'm quite familiar with their cuisine. Well, it's not like it matters if the people here like that kind of food. |Why is so g'damn hot here? Dear comrade, go turn the air conditioning on for me?♡ |How strange... It's not like I make any effort to be friendly or sociable, so why do people end up liking me more? Hey, do you know why that might be, dear comrade?",
	touch = "What is it? Oh, you have work for me? Is that so... Fine, I'll take care of it.",
	voice_key_2 = -1,
	mission_complete = "Mission rewards, huh... Lemme take a look. So...? Is there any food?",
	battle = "Let's beat them to a pulp! Ура!",
	id = 701040,
	gift_dislike = "",
	gift_prefer = "While it doesn't compare to the honor of receiving my guard's commission, I am happy to accept this.",
	profile = "I'm Tashkent, flotilla leader destroyer from the Northern Parliament. There are three other... actually, nevermind. I'm called the \"Blue Cruiser\" because of my Sardegna-style construction. Of course, I'm a destroyer, and I have nothing against that. I'll put up results just like I did during the Battle of Sevastopol, so look forward to it.",
	voice_key = 70104,
	headtouch = "",
	feeling2 = "Do you need me for anything, dear comrade? I'm busy, so make it quick... Oh, is that so...? You just wanted to play? Well, I suppose I have some time to burn, so...",
	login = "Is it that fun staring at Tashkent? ...Is that so? Well, do as you please.",
	detail = "Did you come to watch me practice? ...So, are you staying or what?",
	couple_encourage = {
		{
			{
				30401
			},
			1,
			"Unlike you, I don't have anyone to enjoy Sardegnian cooking with...",
			0
		},
		{
			{
				90111,
				80101
			},
			1,
			"When we get serious, nothing can keep us down!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[701041] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "You can't lift the mission rewards? ...Is that so? What a wimp. Here, I'll do it for you. I can leave it over here, right?",
	win_mvp = "Heheh, not a bad display of power, right?",
	home = "Welcome back. We're all throwing a big party tonight. ...I'm not lying! I'm going to invite everyone from the Northern Parliament over!",
	unlock = "...*Sigh*, I never thought I'd get captured by these little guys... Dear comrade, does Tashkent really have to play along with this?",
	touch2 = "Wait, I'm not okay with this role reversal! I should be the one touching you, dear comrade!",
	mission = "",
	vote = "",
	drop_descrip = "...*Sigh*, I never thought I'd get captured by these little guys... Dear comrade, does Tashkent really have to play along with this?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "I knew there was something... wrong about that chocolate... I never thought this would happen to me... my head's still spinning... |When I was talking to Zara, she said I look more appealing in this outfit. So... what do you think, dear comrade? |I'm not like Avrora. I can't drink at all... Ah, wait, I'm not talking about vodka!",
	touch = "",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 701041,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Dear comrade, do you really think you can keep me bound like this? ...Is that so? Naive fool. Hehe~",
	detail = "Dear comrade, how long are you going to keep me like this? ...Is that so... Ehh? Forever?!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[701042] = {
