_G.pg.base.ship_skin_words[701070] = {
	hp_warning = "I've been hurt. Mm, that's all...",
	feeling3 = "You might fool Gromky, but you can't fool me. If I catch you doing anything questionable, I won't hesitate to whack you with this thing. Mm, that'll be all.",
	mail = "Check your mail, yadda yadda. If you don't, I'll just throw it away. Mm, that's all.",
	expedition = "Commission team's come back. I kind of expected that you knew that already.",
	win_mvp = "That takes care of the enemies. I guess that's all.",
	home = "Here, some cookies Gromky made. As your reward for a job well done.",
	unlock = "Gremyashchy, Northern Parliament destroyer. I'll do what I need to do, so don't bother me for the other stuff. Mm, that's all.",
	touch2 = "Th-that confirms it, you're a creep...",
	mission = "That's a whole lot of unfinished missions...",
	vote = "",
	drop_descrip = "Gnevny-class destroyer - Gremyashchy",
	feeling4 = "You're awfully good at putting on faces. Unless... you're actually an honest, decent person after all? I guess I'll give you the benefit of the doubt for now. Mm, that'll be all.",
	lose = "Ugh... That was a pretty garbage battle...",
	feeling1 = "...Why exactly are you still here?",
	skill = "...Out of my way.",
	upgrade = "Thanks for making me stronger. Yeah, that's all.",
	propose = "I've sailed through bad weather and finished countless tough escort missions. If I can do that, then I can promise to follow you anywhere you go, Commander. Mm, that'll be all.",
	feeling5 = "All right, you're a decent person, I'll give you that. Huh? You want me to... be with you, forever? Ummmm... I-I need to think about, that's all...",
	main = "One whack with this thing dispatches any and all bugs and creeps. Mm, that's all.|Bad things happen to people who anger Gromky. Watch yourself, Commander.|Slacking on the job, huh... Maybe I'll tell Gromky about this.",
	touch = "...You need something?",
	voice_key_2 = -1,
	mission_complete = "Mission complete. You know the drill, claim the rewards. Mm, that's all.",
	battle = "I'm good on fuel. Only thing left to do is dispatch the enemy!",
	id = 701070,
	gift_dislike = "",
	gift_prefer = "Thank you. I'll take it.",
	profile = "I'm Gremyashchy, Grozny-class destroyer. I didn't just do escort missions, I squared off with enemy destroyers and rescued allies too. I've done almost everything, save for dealing with aircraft carriers, so I'm fit for pretty much any mission. Mm, that's all.",
	voice_key = 70107,
	headtouch = "Cut it out. My hat's gonna fall off.",
	feeling2 = "I've always got my eyes on you. Mm, that's all.",
	login = "You've got lots of work to do. Like, that huge stack of papers on your desk.",
	detail = "What are you ogling me for? Are you some sort of creep?",
	couple_encourage = {
		{
			{
				20211
			},
			1,
			"I'll protect you.",
			0
		},
		{
			{
				70108
			},
			1,
			"Don't be reckless, huh... You too.",
			0
		},
		{
			{
				40124,
				40125,
				40126
			},
			1,
			"Friends...",
			0
		},
		{
			{
				70102
			},
			1,
			"C-can I have some of that?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[701071] = {
	hp_warning = "",
	feeling3 = "",
	mail = "There's a letter for you. Can I keep the stamp? Mm, thanks.",
	expedition = "",
	win_mvp = "",
	home = "So many books lying around... Oh, Commander, I could use your help returning these books to the shelf when you come back.",
	unlock = "Wh-who gave you the right to just barge in? ...I did? Huh. Well, seeing as you're here, I guess we could read a book together. Mm, that's all.",
	touch2 = "I-I knew it! You are a creep...!",
	mission = "You could fill a whole book with all these unfinished mission drafts...",
	vote = "",
	drop_descrip = "Wh-who gave you the right to just barge in? ...I did? Huh. Well, seeing as you're here, I guess we could read a book together. Mm, that's all.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Wanna read this book with me, Commander? This one. It's called \"The Happy Lovebirds.\" If we read it together, I might just be able to figure out what it's about. Mm, that's all.",
	main = "If you wanna lounge around, do it over there. Mm, that's all.|Mmmh... *yaaaaawn*... Huh?! Oh no, don't tell me I dozed off... You didn't see anything, got it? I mean, of course you didn't!|Retivy... I mean, Tai Yuan, and I shared our recommended book lists. It turns out we've got pretty similar tastes. Heheh.",
	touch = "Want me to read aloud for you, or...?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 701071,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I got up to this part just the other day. Time to read the rest. Mm, that's all.",
	detail = "Gromky's looking for me? Ugh... I don't wanna go outside. But I'd feel bad about telling her to buzz off, and pretending to be sick would worry her... Hrmmm...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[701080] = {
	hp_warning = "T-There's a crack in the rigging?!",
	feeling3 = "Have you been getting along with Gremyashchy? She's a bit rough to get along with at first, but if you're patient enough with her, I'm sure you'll be able to get along with her just fine in the future! I believe in you, Comrade Commander!",
	mail = "Here are some letters! Is there anything you were looking forward to?",
	expedition = "They're coming back with some precious supplies over there!",
	win_mvp = "It's all thanks to everyone's hard work!",
	home = "Nothing's better than some blini to fill up your weary and hungry belly! Which would you like, honey or jam?",
	unlock = "Goooood morning, Comrade! I'm the Northern Parliament destroyer, Gromky! It's an honor to serve alongside everyone in this fleet!",
	touch2 = "I swear, I'll get mad at you, Comrade Commander!",
	mission = "Let's start with the easier missions! Here, I'll help out too!",
	vote = "",
	drop_descrip = "Gnevny-class destroyer—Gromky.",
	feeling4 = "Comrade Commander! Do you prefer food when it has a deeper taste, or do you prefer it if it's lighter? Mmn, alright. I'll try to make sure the borscht I make next time is just to your tastes, Comrade Commander!",
	lose = "Owww... I didn't think the enemy would be this organized...",
	feeling1 = "Comrade Commander... Are you a bad person...?",
	skill = "Take this! Unity is strength!",
	upgrade = "As long as I can be of more use to everyone...!",
	propose = "I can feel the warmth of happiness radiating from the ring...! Ehehe~ Comrade Commander, thank you very much! I'll continue to be by your side from here on out!",
	feeling5 = "Comrade Commander, great work today! Here's a piping hot drink... along with some bliny... and... hehe, a warm hug from me!",
	main = "Comrade Commander, you musn't slack off! I swear, I'll get mad at you!|For troublesome issues, let us all gather to face it together! That's the way we do it at the Northern Parliament, after all!|Comrade Commander, if your hands are cold, feel free to use my sleeves! They're nice and warm, aren't they~",
	touch = "There there, what a good commander you are~ Hmm? Isn't this what you wanted?",
	voice_key_2 = -1,
	mission_complete = "Mission complete! Unity is strength!",
	battle = "All our powers, combined into one!",
	id = 701080,
	gift_dislike = "",
	gift_prefer = "Thanks, Comrade Commander!",
	profile = "Just so you know, I've done missions with ships from both the Northern Parliament and the Royal Navy! I've also escorted icebreaker ships, and rescued ships along with Gremyashchy! Yep, may we always have fair winds and following seas!",
	voice_key = 70108,
	headtouch = "Hehe, Comrade, did you also want to play with my little buddy?",
	feeling2 = "Comrade Commander, how were you able to build such a cohesive fleet? Please teach me your ways!",
	login = "Woah! Comrade, you sure are early today! You know, you can get a bit more rest if you'd like...",
	detail = "Eh? What's wrong, Comrade? Why are you staring at me like that... Did I do something weird?",
	couple_encourage = {
		{
			{
				70106
			},
			1,
			"Hey, Snezhok! Let's get this snowball fight started!",
			0
		},
		{
			{
				50101,
				50102,
				50103,
				50104
			},
			1,
			"How nostalgic!",
			0
		},
		{
			{
				70107
			},
			1,
			"Calm down! ...That goes for me, too!",
			0
		},
		{
			{
				70102
			},
			1,
			"Is that borscht on the inside?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[701081] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Here are some letters! Comrade Commander, hurry up and take a look at them!",
	expedition = "",
	win_mvp = "",
	home = "Comrade Commander! You musn't fall back asleep! Don't. Fall. Back. Asleep. You. Stupid. Commander!!!",
	unlock = "Comrade! The morning is already here! Look how high the sun is in the sky!! C'mon, a wonderful day is calling to us~!!",
	touch2 = "Comrade Commander~ Take a seat! Don't you dare try to run away! Stay still, right over there, until I finish talking to you!",
	mission = "Comrade Commander, let's do our best to take care of these missions! Yay!",
	vote = "",
	drop_descrip = "Comrade! The morning is already here! Look how high the sun is in the sky!! C'mon, a wonderful day is calling to us~!!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Hey, Snezhok! Don't just sit there in the room and play games all day! Come on, get a move on it, will you?|This paper crane is supposed to be Reshitelny... Chang Chun was the one who taught me how to make these! Hehe~|When I'm standing here, I can reach your head, Commander! Good job, Comrade Commander! Ehehe~",
	touch = "You want to know if I'm cold right now? I'm totally fine! Look, the weather's so nice right now!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 701081,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "I don't hate it when you stroke my hair so... Hold on, you're doing it too roughly!",
	feeling2 = "",
	login = "Good morning, Comrade Commander! Hehe, my little friend here is greeting you too!",
	detail = "Comrade Commander, what did you do to make the paper airplane go so fast? That's so cool!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[701090] = {
	hp_warning = "Th-th-this is mechanically impossible!",
	feeling3 = "Hmgh! Hurmph! ...What am I up to? Working on my rigging, obviously. Don't worry about the parts rough around the edges – I'll just sandpaper those down later! Ahh-ha-ha-haah!",
	mail = "New mail has arrived! ...WHAAAT?! The parts I ordered are STILL in transit?!",
	expedition = "Commission supplies! Let's see what we have... Hmm, this steel container looks strong... I could find some use for it! Hah-ha-haah!",
	win_mvp = "Ahh-ha-ha-haah! Dispatching you cretins was as easy as tightening a screw!",
	home = "Exemplary work, everyone! Is anyone in need of rigging repairs, by any chance? I'll fix and improve it so it works as good as new – guaranteed!",
	unlock = "Ahh-ha-ha-haah! Comrade! I am Soobrazitelny, the Northern Parliament's genius mechanic! Look no further than me for all matters related to machinery!",
	touch2 = "Th-this is no way to treat a girl...!",
	mission = "We've received new missions! Listen, Comrade - they may look hard, but that's no excuse to put them off!",
	vote = "",
	drop_descrip = "Project 7U-class destroyer – Soobrazitelny",
	feeling4 = "Would you be interested in building a small device, Comrade? I don't mean rigging repair tools, I mean something practical you yourself could use! Of course, you'll have a genius to teach you every step of the process!",
	lose = "How come I've stopped moving?! Come on, rigging! Why aren't you working?!",
	feeling1 = "Others can fix your machines when they break, but only you can make up for the mistakes you've made, Comrade!",
	skill = "Prepare to be blown away!",
	upgrade = "Rigging upgrade: complete! My genius knows no bounds! Hah-hah-haah!",
	propose = "My prediction was spot-on – I knew you'd make the first move! Heheheh! I love you too, Comrade! One might say... My love for you is as strong as the hardest steel! ...Maybe that analogy doesn't make sense, but you know what I'm trying to say! Hahahah!",
	feeling5 = "It's true I talk about machinery all day, and yes, I build and tinker day in and day out, but that doesn't mean I'm a mechaphile or that I want to date a robot... Y-you see what I'm getting at, right?!",
	main = "Strain your ears and listen closely! The rotations of the bearings, the tension in the levers, the rigging's rhythmic ticking! The beat of an enchanting machine!|Plastic? Absolutely NOT! Who in their right mind would make components out of a material with zero reliability compared to metal?!|Clean though your office may seem at a glance, I can tell there is dust hidden all over! It's time to do some cleaning, Comrade!",
	touch = "Don't be shy! Pet it to your heart's content! ...What? You weren't talking about my rigging?",
	voice_key_2 = -1,
	mission_complete = "Whew! That's that mission completed! All thanks to my peerless genius! Hah-ha-haah!",
	battle = "Now we shall all find out whose equipment is superior!",
	id = 701090,
	gift_dislike = "",
	gift_prefer = "This is incredible! I'll repay you, Comrade, mark my words!",
	profile = "I am Storozhevoy-class destroyer Soobrazitelny, present mechanical mastermind and former member of the Black Sea Fleet! I've survived battles against numerous relentless adversaries, all through my sheer ingenuity and just a hint of luck!",
	voice_key = 70109,
	headtouch = "Being a genius mechanic, I of course made these safety goggles myself! They provide flawless eye protection while I'm building!",
	feeling2 = "In contrast to the beauty of Mother Nature, the beauty of machinery lies in its unique status as the culmination of millennia of humanity's technological development! That is why I'm so in love with it all!",
	login = "Splendid – you're back, Comrade! ...What's that noise you're hearing? Oh, it's nothing! I'm just giving your office machinery some ingenious upgrades!",
	detail = "Dust is a mechanic's mortal enemy! But, I have managed to prevent its spread by cleaning every nook and cranny of my workshop daily! My foresight is impeccable! Mwah-ha-ha-haah!",
	couple_encourage = {
		{
			{
				10148
			},
			1,
			"What do you say we build something together?",
			0
		},
		{
			{
				70103,
				70504
			},
			1,
			"Whoa! A spark of ingenuity!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[701091] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Time to gather data! ...Um, what exactly am I meant to do?",
	home = "Welcome back, hun~♡ Could you give me a hand with this experiment? ......That cold stare of yours is hurting my feelings.",
	unlock = "Yes, these data and results are quite interesting... Though they mean nothing to me! I am a genius mechanic, not an analyst! Ahh-ha-ha-haah!",
	touch2 = "Mhaahh♡ I-I told you, I won't do anything crazy!",
	mission = "",
	vote = "",
	drop_descrip = "Yes, these data and results are quite interesting... Though they mean nothing to me! I am a genius mechanic, not an analyst! Ahh-ha-ha-haah!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Quite the useful fish tank we have here... Or, is it technically an aquarium? I confuse the two sometimes...|This outfit makes me look both intelligent and sexy at the same time. What an ingenious combination! Mwah-ha-ha-haah!|The screen went black again! So be it... Hurmph! Owwww! I forgot I'm not wearing my regular gloves!",
	touch = "Has anything got you stumped? I can give you a lesson – assuming it's within my sphere!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Go forth, my Mechajuu minions!",
	id = 701091,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "What is it, Mechajuu? ...Ah, Commander! I've been waiting for your arrival!",
	detail = "Nuoooo! I spilled your cup of coffee, Comrade! This is bad! Terrible, even!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[701100] = {
	hp_warning = "I'll stop at nothing for the Commander...!",
	feeling3 = "More people are willing to talk to me than before... I think that's thanks to you, Commander. Thank you.",
	mail = "There's mail for you. I think it's important. Are you fine with me fetching it?",
	expedition = "Our commission comrades are back. Seeing all their smiling faces makes me envious...",
	win_mvp = "All foes are down. Commander, did I, um... do alright?",
	home = "Commander! Oh, uhh... I know you're safe and sound, I just wanted to see you again as soon as possible... That's fine, right?",
	unlock = "I'm Kiev, Project 48-class destroyer of the Northern Parliament. From now on, I'll be assisting you with all manner of things, Commander... W-was that, umm, a good enough introduction?",
	touch2 = "My chest feels... so warm...",
	mission = "This mission sounds tough... Can you handle it, Commander?",
	vote = "",
	drop_descrip = "Project 48-class destroyer – Kiev",
	feeling4 = "I've made many new friends with your help... But you're my first, and still closest friend. I want to get even closer to you. Are you fine with that?",
	lose = "Abandoning my comrades to save myself... I refuse to do that!",
	feeling1 = "Am I the cause of your sadness? Would you cheer up if I simply... disappeared?",
	skill = "We're fighting on MY terms now!",
	upgrade = "We can't forego routine maintenance and upgrades. Right?",
	propose = "To think I'm taking an oath with the one I love... I'm overjoyed, blissful, warm inside, thawing like snow under the sun into a puddle... Commander, is it fine if I... melt in your arms?",
	feeling5 = "Whenever we're apart, or whenever you're about to leave, my heart aches like it's being torn in two... I want to always, always be with you. Will you stay with me?",
	main = "Huff, puff... There... Ah, I just thought I'd write something on the window.|I'll show no mercy to anyone that tries to harm you. Assisting you and protecting you are one and the same to me.|Growing flowers are way beyond me. The only plants I can be trusted with are cacti... They can survive even if you neglect them.",
	touch = "I wanna come closer... Is that fine?",
	voice_key_2 = -1,
	mission_complete = "Someone should claim these mission rewards... Is it fine if I do it?",
	battle = "There's no ice I cannot break through!",
	id = 701100,
	gift_dislike = "",
	gift_prefer = "I've always wanted this... Can I really have it?",
	profile = "My name is Kiev. I was to be a Project 48-class destroyer, but I was never born for a number of reasons... I'm glad to have you as my first-ever Commander.",
	voice_key = 70110,
	headtouch = "I love it when you pet me. I need more... Please?",
	feeling2 = "Do you think I'm cold? Or unapproachable? That's something I want to change about myself, but I don't know how...",
	login = "Commander, umm... Is it fine if I wait for you outside the office next time, too?",
	detail = "Are you free, Commander? Do you wanna... hang out?",
	couple_encourage = {
		{
			{
				70104
			},
			1,
			"We fight together, for the Commander.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[701101] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "All foes are down. Nobody spotted me. Job well done, right?",
	home = "Commander! Where've you been? We should stick together, since it's easy to get lost in here. Is that fine with you?",
	unlock = "Seeing you here puts me at ease. I know this stakeout will go smoothly as long as you're here. Mhm, all is fine.",
	touch2 = "Commander... Not in public, please...",
	mission = "",
	vote = "",
	drop_descrip = "Seeing you here puts me at ease. I know this stakeout will go smoothly as long as you're here. Mhm, all is fine.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "There's no one suspicious in sight... But we must keep our eyes peeled.|I feel safe when I'm with you, and I don't wanna leave your side... It's fine if we stick together, right?|Wonder how it's going for the others. Kronshtadt said to maintain radio silence, which... I'm fine with, since you're here.",
	touch = "Hold hands? Okay. Is this fine?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "...They've caught on to us? Then I'll fight head-on!",
	id = 701101,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Everything is in order. Ready to set off, Commander?",
	detail = "My black clothes let me blend in, but my silver hair does the opposite... The net result is that I stand out.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[701102] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Our friends in the commission fleet have returned. Commander, once you're done greeting them... Yes, I'll be waiting right here for you.",
	win_mvp = "All the enemies have been defeated. I fought just the way you told me too... Mhm, just the way it should be.",
	home = "You want to go ice skating with me? ...You should get some rest first, since you're tired... Mm, you're fine with that, right?",
	unlock = "Since you're a beginner at this, Commander, let me show you the ropes. Somehow... it feels like I skate better than usual when you're around. I'm pretty good at ice skating, aren't I? This... should be fine, right?",
	touch2 = "Oh no! ...Phew, Commander, please be more careful, okay?",
	mission = "",
	vote = "",
	drop_descrip = "Since you're a beginner at this, Commander, let me show you the ropes. Somehow... it feels like I skate better than usual when you're around. I'm pretty good at ice skating, aren't I? This... should be fine, right?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Commander, the way you're skating looks really dangerous, and I'm getting worried just watching you... How about we practice while holding hands? Is that fine?|Even if you get better, make sure to invite me again next time, okay? I want to always be able to do this with you... Is that fine?|The air outside is so nice and crisp, it feels so great... Commander, are you cold? Are you going to be fine if we stay outside?",
	touch = "Are you still scared? Here, hold on to my hand.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Everything I do is for you, Commander, now and always!",
	id = 701102,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "While you were practicing, I organized your documents for you. Only if you have no work left to do, it's fine if I take a moment of your time for myself... right?",
	detail = "It's supposed to be cold today, but when you're here by my side, everything seems so much warmer. ...\"This is the Commander's power? Ah, is that so...\" Um, how was that? Did I sound like Tashkent at all?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[701110] = {
	hp_warning = "Oh no! My power is dropping!",
	feeling3 = "There aren't many decorations around your office. Do you really prefer it that way, Commander? Because after today's work is done, we could buy some stuff and I'll spruce the place up for you!",
	mail = "New letter♪ New letter♪ Are these all for you, Comrade Commander? There aren't any for me? Aww...",
	expedition = "The big girls are back from their commission! I've got a bunch of cute decorations ready to give out, so let's go talk to them!",
	win_mvp = "That's why you don't mess with cuteness!",
	home = "Oh! You're back, Comrade Commander! Will you take me with you next time, please? It's so, sooooo painful to just sit here and wait!",
	unlock = "Hi, Comrade Commander! I'm Ognevoy, Project 30K destroyer of the Northern Parliament! Check out my rigging! Isn't it the cutest you've ever seen?",
	touch2 = "...You want me to shoot you, is that it?",
	mission = "Comrade Commander, we got word of a new mission! We should give it a look!",
	vote = "拉票描述",
	drop_descrip = "Project 30K Ognevoy-class destroyer – Ognevoy.",
	feeling4 = "Excuse me! I know you're really busy, it's just... could I come with you the next time you decide to go out? I won't be a nuisance, I promise! ...I'm asking because I really, reeeally didn't like being all alone in your office!",
	lose = "Comrade Commander, we should retreat quickly for everyone's safety!",
	feeling1 = "Hmph! You're not ever getting a hug from me again!",
	skill = "Cute heart, fire!",
	upgrade = "Am I stronger now? Then can I put more cute stuff on my rigging?",
	propose = "Whoa! So cute! Is this for me? Heehee, thank you! ...Huh? Wait, what was that about \"getting married\"? You? And me? We're getting married? Oh gosh... I'm feeling lightheaded... B-but if this will make me never feel lonely again, then please put it on! I'm ready!",
	feeling5 = "If my hugs make you feel not alone, then I'll hug you tightly wherever and whenever you want! I'll always, always be right by your side, Comrade Commander!",
	main = "Comrade Commander, if you're feeling down, let me give you a hug to cheer you up!|These ribbons are for my quarters, these butterflies go on my rigging, and these plushies are presents for... Oh! I'll cute up your office while I'm at it!|Why I like hugging people? Umm... It makes me feel all warm inside! It warms both me and the person I'm hugging, so it's really like that \"two birds with one stone\" thing!",
	touch = "What is it? Do you need a big hug?",
	voice_key_2 = -1,
	mission_complete = "Hmm... Looking at this goods list... It's probably fine! Comrade Commander, please review it!",
	battle = "Firepower at full throttle! Let it rip!",
	id = 701110,
	gift_dislike = "",
	gift_prefer = "Aww, cute! Thank you for the present, Comrade Commander!",
	profile = "I'm Ognevoy, Project 30K-class or Ognevoy-class destroyer! I didn't get to fight in the war for a myriad of reasons! Also, I don't like violence! But don't be alarmed, Comrade Commander! I'll still do what my job demands!",
	voice_key = 70111,
	headtouch = "...I'm gonna ruffle YOUR hair too after this! Hmph!",
	feeling2 = "Comrade Commander, have a look at my new weapon! Heehee! What do you think? Isn't my rigging the cutest ever? All these ornaments are brand new!",
	login = "*yaaawn*... I'm still sleepy... Do you always arrive this early, Comrade Commander?",
	detail = "I don't like wrecks! They're not cute, and the smoke they emit makes me cough! But, if I have to leave wrecks in my wake to protect my friends, then I won't hesitate to pepper my foes!",
	couple_encourage = {
		{
			{
				70112
			},
			1,
			"Let's show them the power of cuteness!",
			0
		}
	}
}


