_G.pg.base.ship_skin_words[701120] = {
	hp_warning = "You're fine, Svirepy! Just a little more!",
	feeling3 = "Only by pushin' myself and never stopping can I live up to my name – \"Fierce\"! ...Huh? I shouldn't go crazy with it 'cuz I'm already doing great? A-are you serious? ...Hey, I know you're just recognizing my hard work. Thanks.",
	mail = "I left the letter on your desk. Just... remember to actually read it, got it? Don't go missin' out on important stuff.",
	expedition = "Hey, you, get out there and greet the commission team. They're back now! Tch... Don't make me remind you about every little thing!",
	win_mvp = "Ahahahah! You losers should be honored that I whooped your asses!",
	home = "You're back. Props for not gettin' hurt out there.",
	unlock = "Storozhevoy-class destroyer. Name's Svirepy. Heh, I don't respect you just 'cuz I've heard of you before. If you wanna be tough like me, you've got some catchin' up to do!",
	touch2 = "Seriously? You trying to get cut or what?",
	mission = "What're you lookin' at? Supplies ain't gonna pop outta thin air. If ya want goods, do some damn missions!",
	vote = "拉票描述",
	drop_descrip = "Project 7U-class destroyer – Svirepy.",
	feeling4 = "Zzz... Wait and see... I'm gonna prove how capable I am... Whoa! Wh-why was I sleeping?! ...Whuh? Why're you pattin' my head totally unprompted? Wait... Don't tell me I said somethin' weird in my sleep!",
	lose = "Didn't try hard enough... Next time, though! Next time is gonna be it!",
	feeling1 = "God's sake... Did I mess up and pick the wrong person or what?",
	skill = "Spray paint! Paint 'em red!",
	upgrade = "Hmph! ...Heh, this ain't bad. These fangs got a nastier bite now, know what I mean?",
	propose = "Hm. Guess this doesn't look half-bad on my finger... What? An oath ring? Whoa, whoa, hang on! That can't be... What? It's for me? You serious?! Thank go– Ahem! Okay, thanks! I'll always, aaalways be with you!",
	feeling5 = "I'm self-centered, I'm rude, and I get sick often 'cuz I'm not used to these waters... However you cut it, people just don't like bein' around me. But you, you always treat me warmly, you acknowledge me, you compliment me... L-look, if you like bein' with me... then I'm cool with hanging out with you.",
	main = "Cute? The graffiti on my rigging? Damn right it is! That's 'cuz this Northern Parliament symbol was drawn by a world-class graffiti master – me!|I've had three plates of torpedo tempura, two plates of naval curry, and five glasses of honey beer, sooo... some snacks and oxy-colas should stave off the hunger during my late-night studies.|I get sick all the time 'cuz the water here isn't what I'm used to! I frickin' hate it! When am I ever gonna get to show off how nasty I am?!",
	touch = "Yeah? You checkin' out my gun-axe here?",
	voice_key_2 = -1,
	mission_complete = "Checked the rewards. Ya better have another look at... \"Thanks for the help\"? Ahem... I just... It was nothing.",
	battle = "Fight me, assholes!",
	id = 701120,
	gift_dislike = "",
	gift_prefer = "You know exactly what a girl likes! Guess I'll have to repay you somehow...",
	profile = "I'm Svirepy, Storozhevoy-class destroyer. I'm an evolution of the Gnevny class and pack not just nutty firepower, but also... \"Sensitive to low temps and prone to catching colds\"? Only 'cuz I'm not used to these environs and I ain't got enough rest! Get off my case!",
	voice_key = 70112,
	headtouch = "Eeeeeek! The hell are you doing?! Hands off!",
	feeling2 = "I always thought I slept late, but you go to bed even later than me. Man. Is your job THAT big a drag? ...What do I do to stay up so late? Hey, that's something else entirely!",
	login = "Finally back? Better get your act together quick, 'cuz a new challenge is coming!",
	detail = "Ah... Achoo! ...Why're you lookin' at me like that? Damn nose got itchy, is all! It's not a cold, alright?! ...Stop dressing me up! You dumb or what?! *blushes*",
	couple_encourage = {
		{
			{
				70111
			},
			1,
			"MY graffiti is the cutest!",
			0
		}
	}
}


