_G.pg.base.ship_skin_words[702025] = {
	hp_warning = "",
	feeling3 = "",
	mail = "A letter? But you have more important things to do now, like keeping your eyes on me♡",
	expedition = "Commander, I think a commission just got done! Not that it matters, because you're supposed to be helping me pick out clothes!",
	win_mvp = "",
	home = "Whew... You're back, Commander. Didn't think trying on clothes could be this tiring. Get me some juice in a bit so I can get my energy back! This is your obligation – got it?",
	unlock = "Over here! So, Commander, which outfit do you think looks cuter – the left or the right one? Heehee – you better choose carefully, 'cause I'm gonna wear it!",
	touch2 = "Eek?! H-hey, I'm still trying these on... Clearly, you just can't resist my charm♡",
	mission = "Ugh. Forget about your missions and help me decide on an outfit!",
	vote = "",
	drop_descrip = "Over here! So, Commander, which outfit do you think looks cuter – the left or the right one? Heehee – you better choose carefully, 'cause I'm gonna wear it!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "To be honest with you, I've already tried almost everything in this place. I just wanna know which one you'd choose for me! 'Cause, you know, we're going to the beach, and I wanna wear the outfit you like best! Shhh, don't tell anyone that – it's our little secret♡",
	main = "This outfit you picked, it's... uhh, not exactly my number one favorite, but since you chose it, I'll wear it anyway♪|Hey, Commander, what should you pack when going to the beach? For starters, sunscreen, a beach parasol... Oh, and little old me, the most important thing of all!|Heheh. I've actually got another, more revealing outfit around here! If you really, really wanna see it, I'll give you a little preview♡",
	touch = "Oh, you're gonna help adjust my fit? Thanks!",
	voice_key_2 = -1,
	mission_complete = "Mission complete! Your rewards or whatever can wait – for now, could you bring me some more clothes?",
	battle = "",
	id = 702025,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "This is no time to mess around!",
	feeling2 = "",
	login = "Yoohoo, Commander! Finally, you're here. You're gonna help me get ready for our next outing, so perk up!",
	detail = "Check it out! The white one's pure and adorable, but the black one's alluring too... Hm? Commander, that look in your eyes... Don't tell me you were imagining me wearing these, weren't you?",
	couple_encourage = {}
}


