	main = "Do you know what song was just playing at the party? Hahaha, you're very knowledgeable, Commander. Then... What was I just playing?|I'm amazed that Kuybyshev learned such a complex piece... That would be one of her strengths, I suppose.|Relax as much as you want. See? I'm relaxing here, too. No confining others, or letting them confine you, until the party's over.",
	touch = "Would you like to play, too?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 702034,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, what do you want to do? Would you like to hear a song? Or practice dancing with me, maybe? Don't hold back; just say the word.",
	detail = "Conductors are people who must hold the reins of the performers. What of you, Commander? Will you accompany our movement until the end?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[702040] = {
	hp_warning = "No! I am far, far from finished!",
	feeling3 = "Splendid, Comrade Commander. You've chosen a path of your own. Now follow it and see where it takes you!",
	mail = "You have mail. Read it through at once. The more comrades, the better. Always.",
	expedition = "A commission has been completed. We must head out and greet the returnees. Our comrades deserve recognition for their efforts.",
	win_mvp = "Our advance will stop for nothing and nobody!",
	home = "Well fought, Comrade Commander! Your valor warrants the front page spot in the port's newspaper!",
	unlock = "I am the child of a union between our unprecedented country and a free spirit! Now, Comrade Commander, let us achieve great things together!",
	touch2 = "This is no time for this sort of depravity, Comrade Commander.",
	mission = "It is time to embark on a mission, Comrade Commander.",
	vote = "",
	drop_descrip = "Kirov-Class cruiser—Kirov",
	feeling4 = "I will always watch over you. Should you ever lose your way, I will be the hand that shoves you back on the right path. Only look ahead, never stop advancing!",
	lose = "Gah...! I cannot and will not succumb until our ambitions have been realized!",
	feeling1 = "It pains me to say, but I no longer consider you my comrade.",
	skill = "Hear me! I am Kirov!",
	upgrade = "This strength will further our cause!",
	propose = "Only a fool chooses between protecting either the world or their lover. There is but one correct answer: protecting them both. We have both the will and the means to do just that. Come, Comrade Commander, let us march onwards!",
	feeling5 = "To fight not just for your motherland but also for your soulmate, that is what love is... I understand it now. Passion is the fuel of my fighting spirit. And as long as I have you, nothing is impossible!",
	main = "The strong must always march onward. Holding the line is what the weak do.|Glory is what sustains and strengthens us, and is what will leave our mark on history.|I march onward in the name of a tomorrow where everyone is safe and smiling.",
	touch = "Lead the way, Comrade Commander.",
	voice_key_2 = -1,
	mission_complete = "I knew you would pull through for us, Comrade Commander! Here are the rewards.",
	battle = "To arms, comrades!",
	id = 702040,
	gift_dislike = "",
	gift_prefer = "Oho! Thank you, Comrade Commander.",
	profile = "Salutations, Comrade Commander. I am Kirov. My appearance, rigging, and class are all unimportant in the greater scheme of our ambitions. What matters is that we work together to achieve a future of red glory.",
	voice_key = 70204,
	headtouch = "",
	feeling2 = "Never let but's or if's misguide you, Comrade Commander. You alone decide what is right and true.",
	login = "Good to see you again, Comrade Commander! Let us once more set out to teach our enemy the meaning of unity and solidarity.",
	detail = "Neither fate nor evil can hamper our ambitions!",
	couple_encourage = {
		{
			{
				7
			},
			2,
			"Onwards, Northern Parliament comrades!",
			3
		},
		{
			{
				70301
			},
			1,
			"I have your back,Tallinn!",
			0
		},
		{
			{
				31201,
				20501
			},
			2,
			"You may be bourgeois swine... but today, we fight together!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[702041] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Here, taste my signature blend of coffee. It has a dash of vodka to keep you on your toes.",
	unlock = "Comrade Commander, you've come at a good time. I've recently taken a liking to this blend of coffee. Want some as well? No need to be shy.",
	touch2 = "Use your energy for more productive things, Comrade Commander.",
	mission = "",
	vote = "",
	drop_descrip = "Comrade Commander, you've come at a good time. I've recently taken a liking to this blend of coffee. Want some as well? No need to be shy.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Hmm, I should find a way to improve my special blend somehow...|Drinking coffee in tandem with listening to music is the most effective way to combat drowsiness. Let us start with a song that kindles your fighting spirit!|The weather is splendid today. Perfect for some outdoor exercise. ...Change my outfit? All I need put on is a pair of shoes.",
	touch = "You want to talk about coffee? I know countless facts and trivia about it. Go on, ask me something.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 702041,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Don't be nervous. Make yourself at home and relax.",
	detail = "We relax only so we can march even further. Do not get too comfortable now, Comrade Commander.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[702042] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Keep your eyes on the greater goal! Do not let our comrades' sacrifices blind you with rage!",
	home = "Comrade Commander, you've done well in leading our efforts. Our streets are much safer as a result.",
	unlock = "Halt! You have nowhere left to run!! ...Well done, Comrade Commander, what a thrilling chase we had on our hands! What, you think I'm well-suited for this job? You tease too much, bahaha!",
	touch2 = "",
	mission = "Comrade Commander, a new mission has arrived. I'll let you decide when to start.",
	vote = "",
	drop_descrip = "Halt! You have nowhere left to run!! ...Well done, Comrade Commander, what a thrilling chase we had on our hands! What, you think I'm well-suited for this job? You tease too much, bahaha!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Wanna take this thing out for a spin, Comrade Commander? Oh, but not right now though. Gotta make some special adjustments first before you can ride it.|Tallinn, Kirov reporting. I'll be there shortly. Now, Comrade Commander, come with us.|Did Kronshtadt flank our mark already? She sure loves doing the flashy stuff...",
	touch = "Come on, hold on tight! We're about to blow this joint!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Drop your weapons!",
	id = 702042,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Bystreye! Yet more enemies of the Revolution lurk in the shadows!",
	detail = "How should I punish these naughty fellas... What, I'm just having them help me out a little. How 'bout coming by to get some exercise as well, Commander?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[702043] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "I can hardly believe my new record made it next to your victory in the port newspaper... Actually, that is something of an affront to you...",
	unlock = "...Hmph! Just short of a new personal best, huh? But make no mistake, Comrade Commander. Keep watching me and your patience WILL be rewarded with a breathtaking record!",
	touch2 = "Look out! ...Phew. Be careful – a collision from this height seriously hurts.",
	mission = "",
	vote = "",
	drop_descrip = "...Hmph! Just short of a new personal best, huh? But make no mistake, Comrade Commander. Keep watching me and your patience WILL be rewarded with a breathtaking record!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Never overestimate your physical ability. That is a skill – one that has been built on the learnings of countless people over centuries.|Why not try this yourself, Allen? Same for you there – yes, the Sakura Empire girl. I'll reposition the bar for you so don't be scared.|This feat is the product of routine practice. You can do it too if you set your mind to it, Comrade Commander... You think it's impossible? Don't give up before you even try!",
	touch = "Hah! Be awed at the sight of my athletic skill!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 702043,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Are you ready to challenge yourself, Comrade Commander? Then watch my maneuvers closely!",
	detail = "Alright, all appears in order. Comrade Commander, give me the order – then watch as I push the boundary of what is humanly possible!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[702050] = {
	hp_warning = "Ugh! I must... withstand this!",
	feeling3 = "Fancy meeting you here again. Aren't you cold? I don't just mean your body; I want your heart and mind to be warm and healthy evermore... Heehee.",
	mail = "Your mail has arrived. Why don't you reply to it while the feelings behind them still burn?",
	expedition = "The commission team has returned. I'll escort them back to port.",
	win_mvp = "What a wonderful, heart-warming victory.",
	home = "Welcome back. You got a little wet during that last battle, didn't you? Best change your clothes before you catch cold. Here, give me your hand.",
	unlock = "It is an honor and a joy to meet you, Commander. I am Kuybyshev, light cruiser of the Northern Parliament. Let us steel our hearts to weather the war ahead.",
	touch2 = "Tell me, are you familiar with the phrase \"summary offense?\"",
	mission = "Unfinished missions await. If there's anything I can do to help, don't hesitate.",
	vote = "",
	drop_descrip = "Chapayev-class light cruiser – Kuybyshev.",
	feeling4 = "There, there. You can go back to being the Commander everyone leans on tomorrow. Until then... You may stay here with me.",
	lose = "It doesn't matter if I fall, as long as my comrades make it out!",
	feeling1 = "Perhaps I must discipline you as Chapayev would.",
	skill = "Can you take the heat?!",
	upgrade = "We must be ready for our next battle.",
	propose = "Take this to heart, Commander. If humanity ever betrays you, do not be saddened or angered. I will stay by your side and keep you warm until the snow stops and the sky is clear.",
	feeling5 = "Isn't the moon beautiful tonight? You know... I only feel this heartwarming sensation when I'm with you. You've shared your worries and vulnerabilities with me... I don't want to take my eyes off of you. Heehee, but don't turn to me; keep your eyes fixed on the moon for just a while longer.",
	main = "Nnh... I'm fine. Today's document review is another behemoth. Thank you for all you do.|*blows*... That should do it. Here's your coffee, Commander. Warm yourself while it's still hot.|Believe in yourself. Your accomplishments in bringing peace to these blue seas are more than worthy.",
	touch = "Worry not. I am here for you.",
	voice_key_2 = -1,
	mission_complete = "Back from another mission? Why don't you rest with a warm bowl of borscht?",
	battle = "Fear me! Then, follow my lead!",
	id = 702050,
	gift_dislike = "",
	gift_prefer = "You didn't have to put yourself out for me... Thank you.",
	profile = "Project 68-K, Chapayev-class cruiser Kuybyshev, at your service. My construction was halted before the war, robbing me of my opportunity to contribute. I have to admit that I have my regrets, but I plan to do all I can now to make up for it. You have my full support, Commander.",
	voice_key = 70205,
	headtouch = "I'm fine. Your concern is much appreciated.",
	feeling2 = "The port is chilly at night. You must have some reason for being here at this hour. Would you be willing to share why?",
	login = "Ahh... Good morning, Commander. If you find yourself cold, come to me. I can warm you with my rigging.",
	detail = "I'm not afraid of being hurt. If it means protecting you and the others, I'll take that bargain every time. Heehee.",
	couple_encourage = {
		{
			{
				70203
			},
			1,
			"Chapayev, I'll take the lead!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[702051] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "I'm glad this victory was worthy of celebration.",
	home = "Why not kick back and enjoy the music? There's no need to overwork yourself today.",
	unlock = "...Thus marks the end of this tune. The Dragon Empery has graciously allowed me to perform in their Spring Festival celebration. Are you here to listen, Commander? In that case... How did you like the song? Heehee.",
	touch2 = "No touching allowed, Commander.",
	mission = "",
	vote = "",
	drop_descrip = "...Thus marks the end of this tune. The Dragon Empery has graciously allowed me to perform in their Spring Festival celebration. Are you here to listen, Commander? In that case... How did you like the song? Heehee.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Can't sleep, hm? Have some warm milk and put on classical music, and I'm sure you'll drift right off. Today is a day to be with family, so why don't I stay here with you until you're sound asleep? Heehee♪",
	main = "The subtle serenity of life as winter, the radiant merriment of fellowship as spring... The Dragon Empery's music is so delightfully expressive.|Are you lost, Miyuki? Don't worry; we'll see you home to your dorm, isn't that right, dear Commander?|Today, we forget the fighting and savor song and music instead. Commander, you should try and relax, too.",
	touch = "Speak up if you have any requests, okay? Heehee!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Tighten up! This is a battlefield!",
	id = 702051,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Though they say spring has come, the wintry wind has not yet left. Be careful you don't catch a cold, okay?",
	detail = "Oh, you're curious about my bandages? I hit my head while I was decorating... Sorry to worry you.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[702052] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Heheh. You're back safely. These wounds of mine are unimportant. Your and everyone else's well-being matters more.",
	unlock = "Commander... You smell like rain. Let me warm you. The bandage? It's a part of the service. Take a guess as to how it's used... Heehee.",
	touch2 = "Mmh... This part of me is unscathed. Or... are you looking for some other kind of \"injury\"?",
	mission = "Commander, it looks like you have some unfinished missions.",
	vote = "",
	drop_descrip = "Commander... You smell like rain. Let me warm you. The bandage? It's a part of the service. Take a guess as to how it's used... Heehee.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "I suppose... this will let me shoulder more of your burdens.",
	propose = "",
	feeling5 = "While it's true this outfit may just be a part of the set dressing, my desire to be embraced by you is completely genuine. Heehee. Do you want to prove it, Commander?",
	main = "This outfit really catches the eye, doesn't it? If it's managed to surprise or relax you, then I'm happy.|What do you want to start with? Snacks? Music? Or perhaps you'd like to inspect my \"injuries\" first?|You look a little tired, Commander. Make yourself at home and I'll read a story for you. Or I could simply quietly keep you company for a while – that's fine by me.",
	touch = "Commander, if you're wondering... this bandage is just decorative. Not sure why you're so curious about it...",
	voice_key_2 = -1,
	mission_complete = "Nice work on completing that mission. Now you can focus entirely on receiving my care. Heehee.",
	battle = "",
	id = 702052,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Are you comforting me? I should be the one doing that to you...",
	feeling2 = "",
	login = "Welcome back, Commander. Let your humble Kuybyshev wash away the day's fatigue for you.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[702060] = {
	hp_warning = "Aww, these tails took a lot of work to make...",
	feeling3 = "Oops, sorry, I lost track of time while chatting with a friend, and I forgot I was meeting with you today... Did I make you feel sad? I'm really sorry.",
	mail = "You have new mail~",
	expedition = "The team has come back~ Should we offer them a few warming shots of vodka?",
	win_mvp = "We won~! Fighting comes naturally to me~",
	home = "Good to see you back~ I've left a refreshing drink and a juicy tangerine on your desk~",
	unlock = "Zdravstuvuyte, Comrade~ I'm the Omaha-class light cruiser, Milwaukee, reporting for duty~ Oh, did I slip up? ...Ahaha, sure did. I'm Murmansk, from the Northern Parliament. It's a pleasure to meet you~",
	touch2 = "Ummm, I've got just a teensy qualm about you touching me this way...",
	mission = "You've still got missions~ Would you like me to pester you about them the next time you forget?",
	vote = "",
	drop_descrip = "Omaha-class light cruiser – Murmansk",
	feeling4 = "Hmmhm~♪ Once I start chatting with you, it's really hard to stop~ Is that a problem for you, in regards to work? Aww, that's a shame...",
	lose = "We lost the battle... I'm sorry for messing up...",
	feeling1 = "Is there something wrong? I'm worried about you...",
	skill = "Vperod~!",
	upgrade = "I've gotten stronger~",
	propose = "Taking this oath means we will share an eternal bond, right~? Wonderful! Then from this day forward, I promise I will see you every day, without it causing you any trouble~",
	feeling5 = "Today is my watch-only day, but tomorrow we can chat to our heart's content. This should fix our little time-schedule problem~ ...It doesn't make much difference in the end? Oh, I see...",
	main = "Are we going on a rescue mission today? I really love helping people~|Pirouette and a spin~ To my right is a fox, and a bunny to the left~♪|Whew... Hmm~♪ Staaare... Aha!",
	touch = "Hmmhm~♪ Oh, do you want to chat? Why, sure thing!",
	voice_key_2 = -1,
	mission_complete = "Mission complete~ Now let's tackle another job while we're in high spirits~",
	battle = "I'll open fire on the enemy~",
	id = 702060,
	gift_dislike = "",
	gift_prefer = "I'm so happy~",
	profile = "I'm the light cruiser Murmansk. In terms of my history, I used to be an Omaha-class cruiser, doing rescue and escort missions. Then after becoming part of the Northern Parliament, I took part in some training missions~",
	voice_key = 70206,
	headtouch = "",
	feeling2 = "I might not have many special skills to boast about, but I'll do my best to live up to your hopes~",
	login = "Good morning. Sorry that I'm late, I ran into a friend along the way and stopped to have a chat.",
	detail = "How do you like my tails? They're super fluffy and feel nice in your hands~ By the way, I made them myself♪",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[702061] = {
	hp_warning = "Oh gosh! Silly me, I need to focus...!",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Easy as porridge in the morning~",
	home = "Welcome back~! A warm beverage would be perfect right now~ Like vodka, perhaps?",
	unlock = "...Achoo! Uhh, good morning... Snow? Yeah, it is snowing today... Woah, it's really coming down hard... Ahaha~",
	touch2 = "You won't find any tails down there today~",
	mission = "",
	vote = "",
	drop_descrip = "...Achoo! Uhh, good morning... Snow? Yeah, it is snowing today... Woah, it's really coming down hard... Ahaha~",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Have you seen my favorite pillow? It's \"just down pillow\"...?|Apparently, Pamiat Merkuria likes lazing around too~ I find that surprising, but also kind of unsurprising at the same time...|Whew... I can't help but admire how well everyone's holding up in this snowy weather~",
	touch = "",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 702061,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Mrmm... *yaaawn*... Good morning... Sho shleepy...",
	detail = "I'm spending the whole day lazing around indoors, so I don't really need to get dressed~ You can change into loungewear too if you want, Commander~",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[702062] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Even the mail smells good... *sniff*... Very nice~",
	expedition = "",
	win_mvp = "",
	home = "Welcome baaack~ This incense has calming aromatherapeutic effects, so come and rest your weary bones.",
	unlock = "Hello there, Comrade Commander~ Come take a deeeep breath of this. Sniiiff... Can you smell this room's fragrance? Hm? You can't tell? Oh. Uh, my incense may have stopped burning.",
	touch2 = "I don't think this room is designed for that...",
	mission = "",
	vote = "",
	drop_descrip = "Hello there, Comrade Commander~ Come take a deeeep breath of this. Sniiiff... Can you smell this room's fragrance? Hm? You can't tell? Oh. Uh, my incense may have stopped burning.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "*yaaawn*... The incense smells so good that... I'm getting sleepy. Come to think of it, one of the Empery girls said it had a soporific effect... Heehee, wanna sleep together~?",
	main = "You've been staaaaring for a while now♪ I take that to mean you love the dress?|\"One, two, three, four, five, foxes love potatoes~\" That's an old Dragon Empery nursery rhyme, you know! Hmm? Isn't it? Maybe I'm remembering wrong~|Staaare... Oh, nothing~ Just observing you, that's all. Heehee.",
	touch = "Huh? My tails are on the floor? It's okay~ I can just wash them later~",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 702062,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "My hair accessories and outfit match perfectly, don't you think?",
	feeling2 = "",
	login = "I can't exactly run around in this outfit, but as you can see, I made it on time. Heehee♪",
	detail = "I wonder. Should I drape my tails over my shoulders, or should I keep them fixed at my back? What do you think?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[702070] = {
	hp_warning = "Hang in there... Just a little more...!",
	feeling3 = "I often read books on tactics to gain inspiration for my plans. If you have any interest, Comrade Commander, I could lend you a few. For example, this volume: \"Using Neglect Play to Make Your––\" ...Ermm, sorry. Wrong one...",
	mail = "Comrade Commander, you should check your mail. The sender may not be so patient with us.",
	expedition = "Huh? It's already that time? ...Th-thank you for letting me know. I almost forgot that the commission team was coming back...",
	win_mvp = "As long as your information is ample and your strategy is thorough, there's no chance of failure.",
	home = "Sort the delivered documents, deal with any and all minor issues, and I'll be all ready when Comrade Commander— Oh. When did you get back?",
	unlock = "We finally meet, Comrade Commander. I am Voroshilov, light cruiser of the Northern Parliament. Hm? I don't think I was waiting that long... I mean, it was only a few hours. That's not so bad, is it?",
	touch2 = "D-don't act like you get to touch me whenever you want...",
	mission = "The piled-up snow may melt, but your missions won't do the same. Comrade Commander, perhaps we'd best get them done?",
	vote = "",
	drop_descrip = "Kirov-class light cruiser – Voroshilov.",
	feeling4 = "Comrade Commander, how is your mission progress? ...You've finished all of them? What of the commissions? You've arranged them, too? I see. You're doing quite well. (whispering) My plan to get us closer ends in failure again...",
	lose = "I'm sorry, Comrade Commander. Allow me to rectify my mistakes by my hands...",
	feeling1 = "You and I just aren't on the same wavelength, Comrade Commander. I'm sorry.",
	skill = "Melt!",
	upgrade = "Absolute power is an effective insurance policy for our subsequent missions.",
	propose = "(whispering) Was my \"Conquer the Commander\" strategy a success? ...O-oh, ignore that! I'm happy you and I seem to feel the same way. Huh? Y-you always knew?! I see... I should've been more straightforward to begin with...",
	feeling5 = "Comrade Commander, what's the matter? I'm the same as ever, so I don't think there's any reason for you to be extra worried... (whispering) It's okay. I'll keep on waiting until you look my way. My \"Conquer the Commander\" master plan must succeed...",
	main = "There is a saying about Kirov and me: \"As hot as an inferno, yet as cold as ice.\" O-or... something like that.|Comrade Commander, what time is it? ...Phew, thank you. So I haven't missed it.|Ways to kill time? I like to put ice down and watch it melt... How about you, Comrade Commander?",
	touch = "You're going out? Do you wish I wait here, Comrade Commander?",
	voice_key_2 = -1,
	mission_complete = "Comrade Commander, the mission is complete. According to our plans, the next task is...",
	battle = "I've undergone countless practice drills. I won't fail!",
	id = 702070,
	gift_dislike = "",
	gift_prefer = "Ah, I've had my eye on this for a while... Never mind. Thank you.",
	profile = "Kirov-class cruiser of the Northern Parliament, Voroshilov, at your service. Do you already know Kirov? I make the plans, and she carries them out... Oh? You say we give off completely different impressions? Fair; our comrades often say the same.",
	voice_key = 70207,
	headtouch = "Why would you do that?",
	feeling2 = "If you don't have any business with me, don't waste time looking for me. We should just do our own jobs and keep an appropriate distance. Wouldn't that be best?",
	login = "Welcome back, Comrade Commander. I didn't know when you'd return, so I've been standing by here... Is that not part of the secretary's job?",
	detail = "From here to there, and then... Oh, Comrade Commander. I was just devising an emergency escape route from your office. Would you like to look over it? It may come in handy someday.",
	couple_encourage = {
		{
			{
				70204
			},
			1,
			" With Kirov here, I know this will work out!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[702071] = {
	hp_warning = "",
	feeling3 = "",
	mail = "New mail? Mm, who could possibly be planning to cause Comrade Commander trouble at a time like this?",
	expedition = "",
	win_mvp = "",
	home = "The Sakura Empire girls brought over some dango. You came just in time, Comrade Commander. How about we give them a try?",
	unlock = "Comrade Commander, is the bath to your liking? I'm glad. Heehee, it's a good thing I trusted that \"Top 10 Dates for Snowy Days\" article and chose this secluded hot spring.",
	touch2 = "Should I get a little closer? Well, okay...",
	mission = "A new mission, hm? I'll add it to our to-do list for later.",
	vote = "",
	drop_descrip = "Comrade Commander, is the bath to your liking? I'm glad. Heehee, it's a good thing I trusted that \"Top 10 Dates for Snowy Days\" article and chose this secluded hot spring.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Somebody once told me that people are more honest when they're in a hot spring. Heehee, that means this is my chance... Comrade Commander, I've always had feelings for you. I thought that keeping a distance from you would make you more interested in me, but... I suppose when people say \"awkward,\" they're referring to people like me...",
	main = "The cold wind blowing through, the steamy water... They could be likened to fire and ice, couldn't they? Heehee.|You say I'll get dizzy if I soak for too long? Maybe I'm an exception... After all, I'm used to waiting. But Comrade Commander, don't hesitate to say something if you're not feeling well.|What would I do right now if there was an emergency? Oh, I shouldn't waste this date thinking about such things...",
	touch = "I hear you're supposed to hold hands on dates. Comrade Commander, should we...hold hands?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Don't worry. I've gone through my fair share of emergency battle drills!",
	id = 702071,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Hm? Is there snow on my head or something?",
	feeling2 = "",
	login = "It's cold enough to snow, but the hot spring will warm us up in no time. Let's not dally, Comrade Commander. The hot spring awaits.",
	detail = "Gangut and Sevastopol went inside with vodka. I hope they don't seriously plan to have a drinking contest in the hot spring... Comrade Commander, we'd best stop them before it's too late.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[702072] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Congratulations on a successful mission. Are you hurt? Sick at all? And your mood? Umm... I mean whether you're in the mood for your \"physical.\"",
	unlock = "Don't move, please. You're playing the patient, and I'm playing the nurse, so it's only natural that the distance between us is different from usual... Hm? What does that have to do with this pose? Ahem. Now that you mention it, umm...",
	touch2 = "Comrade Commander... I'm ready for you...",
	mission = "Leave your mission correspondence to me, Comrade Commander. You just hold tight.",
	vote = "",
	drop_descrip = "Don't move, please. You're playing the patient, and I'm playing the nurse, so it's only natural that the distance between us is different from usual... Hm? What does that have to do with this pose? Ahem. Now that you mention it, umm...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I'd gladly take advantage of the opportunity to make you mine if you DID fall ill, but I'm not the kind of girl who'd want that to happen. My plan will have to go undeployed for now, forever a fantasy... Ah! *blush* You'll make it reality... for me?",
	main = "It feels like you're on fire, and then you're freezing? Hmm... Such severe symptoms demand a much more thorough examination...|Comrade Commander, can you come closer? I can't measure your heart rate from this far. Or if you can't come to me, may I come to you?|My plans? Hmm... I'll stay with you until your fluid transfusion is done. Don't worry, counting the drips is enough to entertain me for hours... But we could chat, if you'd like.",
	touch = "It's just going to feel like a little pinch. Relax, okay?",
	voice_key_2 = -1,
	mission_complete = "You finished your missions? Good. Now we can focus on your physical.",
	battle = "",
	id = 702072,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I plan to use medical equipment, of course, but no physical is complete without direct questioning and physical contact. Your body may have been tampered with, so I must be thorough.",
	detail = "I've already studied many texts and learned a lot from my friends. All that's left is to treat you and receive your evaluation... Heehee, go easy on me, okay? I'll do the same for you.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[702080] = {
	hp_warning = "Egads! My flame of inspiration is gonna go out!",
	feeling3 = "The knob on your office door is so normal and dull. Its security aspects leave much to be desired as well... Would you like me to give it an identification and automatic counterattack system? If some ne'er-do-well touches it, it'll administer an electric shock, and then...",
	mail = "Ooh, my letter-bringer birdie has brought your mail! ...Hm? The letter's caught in its beak? Roger-dodger, I'll go fetch a wrench right away!",
	expedition = "Yahoo, the commission team is back! Which is to say, my adorable components have come home, yes?! Let me go see! I promise I only need a tiny handful of components!",
	win_mvp = "Heheh... These components are all mine now!",
	home = "Whoa, Commander! You're back! Pray tell, what new and shiny components have you brought back to me? Believe me when I say I have a BOATLOAD of ideas I wanna give form to!",
	unlock = "Oh. Ohhh... If it isn't my test product evaluator... No, I mean my Commander! Heheh. I am Oleg, an ingenious scientist capable of turning components into fabulous inventions! Pleased to be working with you.",
	touch2 = "Nooo! Y-you touching me without warning made me drop the circuit board that I JUST welded! *sob*... My precious...",
	mission = "Hey, Commander! The mission reminder birdie I made has been buzzing for ages! What that means is you've got super-important missions left to do!",
	vote = "",
	drop_descrip = "Bogatyr-class protected cruiser – Oleg.",
	feeling4 = "*sob*... Commander, my invention just won't work! I'm at my limit here – please charge my batteries up with a hug... Heehee, your embrace is so warm... I think I got my motivation back!",
	lose = "Guhhh... My inspiration has eluded me...",
	feeling1 = "You don't seem very interested in my invention. A failure though it may be, I still put a ton of work into it... Oh well. It's okay. I still have a bunch of other ideas to develop on!",
	skill = "This is my creation, brimming with chaos!",
	upgrade = "Whoooa! Feels like my inspiration circuit has opened! Ah, wait, no – my toolbox has merely gotten lighter...",
	propose = "Whoooa! I've never seen something so shiny before! You're giving it to me? Heehee, I'll gladly accept! I'm of course aware of the implications of this. I'm going to add a heartbeat and body temp sensor to this and it will keep our minds connected forever and ever!",
	feeling5 = "I've learned how to classify components thanks to you, and my inventions have become considerably more practical. Ah, yes, as thanks, allow me to sing you my invention song! Spin-spin goes the drill♪ Being an inventor's such a thrill♪ My love's by my side and I'm fulfilled♪",
	main = "Wahaa, Commander! I repurposed those junk components I found in the depot into a mechanical canary that can sing! ...What? What's it used for? Tsk, tsk, your eyes do not see. Inventions are not bound by the need to be useful!|Mmh... While I may LOOK unoccupied, the truth is, I am busy as can be. If you need a hand with something, I might just have to use my feet instead.|\"Junk\"? How rude! All of these components are treasures with limitless potential inside of them! They each have their own destiny and will shine if just given the chance!",
	touch = "Hmm? Hrrmm... I'm jogging my noggin at present, you see...",
	voice_key_2 = -1,
	mission_complete = "Looks like SOMEONE hasn't claimed their mission rewards! Do you not need them?! If so, I'll gladly take them!",
	battle = "C-combat?! But I've been so busy all week that I haven't had a wink of sleep!",
	id = 702080,
	gift_dislike = "",
	gift_prefer = "*sob*... It's so sparkly... Is it really all for me?!",
	profile = "I am Oleg! The port's one and only genius scientist specializing in bringing components back to life! Give me some parts and I can make miracles happen! Things may sometimes blow up along the way, but explosions are the mother of invention, so it's fine!",
	voice_key = 70208,
	headtouch = "Fascinating... The temperature, grip, and headpatting tempo of your hand are all quite pleasant... Hold it! I must make a mechanical hand that replicates this sensation!",
	feeling2 = "Oh, hang on a moment, I need to make a note of an idea I just got... Huh? Octopus? No, this is no octopus! It's a mechanical arm that sorts paperwork automatically! Do you want me to explain what all these symbols mean?",
	login = "Woohoo! You've arrived, Commander! I was just sorting out the equipment I'll bring with me today. Let's see... Extendable claw, portable collector, screwdriver kit – all good! Want me to examine your stuff, too, Commander?",
	detail = "Fusing wires with my hands and adjusting gears with my feet whilst enjoying a chat with you – that is the kind of efficiency a genius possesses. Controlling the flow of water with my feet to make tea? I certainly haven't tried that yet, but perhaps if I put the teapot on a rotating platform...",
	couple_encourage = {
		{
			{
				60802
			},
			1,
			" Whoa... Whoooa! Such a disposition full of love for inventing!",
			0
		},
		{
			{
				79902
			},
			1,
			" Do you need a hand optimizing your program?",
			0
		},
		{
			{
				70202
			},
			1,
			" Care to try my latest neck massager?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[702081] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Have you considered answering your mails with an automated reply system? ...Huh? That won't fly?",
	expedition = "Hmm? Oh, that commission is finished... Right now, though, I just wanna be with you... and watch a movie on the couch...",
	win_mvp = "",
	home = "Buhhh... Whuh? Did I... doze off? Oh, are you still on the clock, Commander? Your laptop screen is still on, so...",
	unlock = "*yaaawn*... Nothing beats relaxing after a nice bath! Now that I've changed into my warm pajamas, what should we do next? Hm? Go to sleep? No, no, it's too early. I only yawned because I was getting comfortable!",
	touch2 = "C-Commander, I'll have to bathe again if you get me sweaty... Unless this is how a vacation... should be?",
	mission = "My mission reminder birdie is chirping again... Dang it, maybe I shouldn't have brought it along!",
	vote = "",
	drop_descrip = "*yaaawn*... Nothing beats relaxing after a nice bath! Now that I've changed into my warm pajamas, what should we do next? Hm? Go to sleep? No, no, it's too early. I only yawned because I was getting comfortable!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Hm? It's bedtime already? But the movie isn't over yet... It's all your fault. It was so late by the time I got out of the bath... Look, we're finally on vacation, and I don't wanna waste it! ...What? We can go on vacation together another time as well? Alright, I'll hold you to that... Heehee.",
	main = "Whew... The fireplace is so nice and cozy... And so are you... I think I might... *yaaawn*... Mmmgh, no! I can't doze off now!|It's pretty nice and fulfilling, just being with you on vacation and not thinking about inventions at all. I've never done this before!|Everyone tells me that giving you a lap pillow will make your affinity for me skyrocket... Personally, I think giving you a tummy pillow should raise it by twice as much! I mean, tummies are squishier than thighs after all!",
	touch = "Mgh... Mmff... No, I'm not sleeping... I wouldn't doze off on our vacation... Sleeping it away would be such a shame...",
	voice_key_2 = -1,
	mission_complete = "Can't you just... claim your mission rewards later? I can make a machine that'll claim them for you tomorrow.",
	battle = "",
	id = 702081,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Mgh... Mmhh... I'll fall asleep again if you won't... stop doing that...",
	feeling2 = "",
	login = "Come here and have a seat, Commander. Heehee, how do you like this cabin outfitted with my personal choice of automated systems? I just fine-tuned the temperature control and safety program on the fireplace, so now it's perfectly safe and pleasant!",
	detail = "These pajamas look light on the surface, but they're fitted with temperature regulation systems on the inside! I also installed an emotion sensor on the tail so I can express my feelings for you without even saying a word♪",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[702090] = {
	hp_warning = "Ouch... Oh, Commander...",
	feeling3 = "What do I fear most? Hmm... Being pranked, maybe? I scream really loud when I get scared... Yours are fine, though. In fact... I'd let you scare me more, if you wanted!",
	mail = "Commander, I sorted out your new mail. Don't forget to check it.",
	expedition = "The commission team is back. I'll go organize the supplies they brought.",
	win_mvp = "I didn't even have to break a sweat.",
	home = "Ah... Even from far away, I feel your gaze. It's like a sweet caress... *pant*... A-ahem! W-welcome back, Commander!",
	unlock = "I am the cruiser Krasny Kavkaz, serving the Northern Parliament. Thank you for welcoming me. *peeks*... Hm... You look VERY reliable.",
	touch2 = "Eep?! C-Commander... This mental training routine of yours is even more... stimulating than I dared hope. Aah...",
	mission = "Commander, would you please entrust your remaining work to me? Ahem. Once in a while... I'd like to experience the feeling of being crushed by a mountain of work...",
	vote = "",
	drop_descrip = "Admiral Nakhimov-class light cruiser – Krasny Kavkaz.",
	feeling4 = "Y-you've never seen me in the midst of mental training? W-well, I prefer to do it alone... with nobody else around. B-but I guess it wouldn't be so bad to let you watch... Hehe...",
	lose = "I'll focus more next time...",
	feeling1 = "C-Commander, I have mental training to get to. Could you leave, please...?",
	skill = "I see you...",
	upgrade = "The world is clearer than ever before now!",
	propose = "I have so many feelings I want to share with you, but my words can't keep up with my emotions. You take up all of my thoughts, and you've seized my heart. I want to be with you... forever...",
	feeling5 = "*sigh*... I don't know why, but when you're around, all these strange thoughts pop into my head. I start to feel all hot... T-take responsibility and cool me down...",
	main = "Do you know about mental training? Close your eyes and focus, and it'll amplify even the tiniest sensations that you'd usually miss. Ah, it's so much fun...|Mmmph! (I-I can't talk... Commander, don't look at me like that!)|Ugh... I shouldn't have agreed to go to the debate tournament with Pamiat'. I spent the whole time stammering... So embarrassing.",
	touch = "Eep?! Commander... When you touch me out of nowhere, I... Ah! I'm not saying I don't like it! I-in fact, it makes me so happy...!",
	voice_key_2 = -1,
	mission_complete = "The work's aaall done. It was a lot... but my training has been working out great!",
	battle = "Enemy... found!",
	id = 702090,
	gift_dislike = "",
	gift_prefer = "Oooh... You know everything I like, don't you?",
	profile = "I am the cruiser Krasny Kavkaz, serving the Northern Parliament. I was supposed to be as towering and impregnable as the mightiest mountain, but you conquered me in no time, Commander... *peeks*... Wh-what am I saying? Let me start over, please!",
	voice_key = 70209,
	headtouch = "Ah... You want to see the color of my eyes? Now isn't a good time to remove my blindfold, but if you insist... I'll show you next time there's an opportunity!",
	feeling2 = "Your warmth, your heartbeat, your emotions... All of them are so special to me. Even when you're in a crowd, I can sense you clearly, like... like a bonfire atop an icy field.",
	login = "The tempo of your footsteps, how you move when you open doors, the amount of force you use... Ah, I can feel every bit of it... Eep?! C-Commander? N-never mind...",
	detail = "Ah, there's no need to worry... I'm wearing a blindfold, but I can see everything through more... primal means. Including you, Commander...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[702091] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Commander, you've kept me waiting. Remember how we agreed that the loser gets punished? I've been so excited... Ahem! I mean worried sick, waiting for you...",
	unlock = "It's time to begin our blind mahjong practice. This is another part of mental training, after all... Heehee.",
	touch2 = "Ah... Aaah... There are too many pieces. I need to touch them all carefully, or I won't be able to tell which is which... Oooh...",
	mission = "",
	vote = "",
	drop_descrip = "It's time to begin our blind mahjong practice. This is another part of mental training, after all... Heehee.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I finally got to play a game with you, and I lost right away... Goodness, it's just too hard. Well, Commander... Are you ready to give me my ultimate punishment? Hehe... Heehee...",
	main = "Heehee... Rubbing the bumpy tiles against my body, trying desperately to endure the chilly stimulation to tell them apart... is such wonderful training...|Oh? Wrong again... This is all I have left on, though... Hm? But my tights...? Ooh?! My legs are gradually being exposed! Oooh...|Pfft... Hahaha... N-not right there! It's too much... If you tickle me, I won't be able to tell which is which... Hahaha!",
	touch = "I specifically picked out this outfit, you know... It's really form-fitting, and it's perfect for tactile training...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 702091,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Mm... Is this my reward? Heehee...",
	feeling2 = "",
	login = "This outfit is chilly, but when I think of practicing together with you, I can't help but get all hot...",
	detail = "I've memorized all the tiles... Oh? You have, too? Then are you ready for a game? The loser gets punished with... hmm... having to take off an article of clothing, say?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[702100] = {
	hp_warning = "Switching to power-saving mode.",
	feeling3 = "Analysis complete. After ingesting black tea, I've seen a significant improvement in my mobility. Commander, may I have more?",
	mail = "My assistance robot brought your new mail in.",
	expedition = "When did the commission team leave, again...?",
	win_mvp = "Assessing robot companion combat effectiveness... Results: highly effective.",
	home = "Reading new robotic runtime structure... Commander? Did you just get back? But when did you leave...?",
	unlock = "I'm the robotics engineer for the Northern Parliament, Bogatyr. Good morning, Commander. I'm in the middle of uploading interactive data to optimize this robot's behavioral logic. Reading data... Please wait.",
	touch2 = "What kind of feedback would make the Commander happy? I need... more data...",
	mission = "Tasks requiring completion have been detected. Dispatching work assistance robot.",
	vote = "",
	drop_descrip = "Bogatyr-class protected cruiser – Bogatyr.",
	feeling4 = "*stare*... *staaare*... Hm? When I'm observing you as such, my system efficiency doubles, making my processors heat up... An error has occurred. System overheating.",
	lose = "Robot companion damage rates exceeding expectations. Preliminary analysis suggests discrepancy between design environment and combat environment.",
	feeling1 = "Commander, do you need help from a housework robot? You seem to be struggling.",
	skill = "This will make for good combat data.",
	upgrade = "Energy exceeding threshold... Requesting activation of root cause analysis program.",
	propose = "Let me think for a moment before the ceremony. When I think about our future – the mornings, afternoons, and nights we will spend in each other's arms... I feel hope and joy. Yes... My thoughts have converged on one answer: I love you, Commander.",
	feeling5 = "Thinking about you generates so much uninterpretable data... System overload imminent. Commander, catch me...",
	main = "The solution to this problem is complicated... A data processing overload triggered a forced circuit breaker flip. Restarting... Ah. Sorry, Commander, I just lost consciousness. I'm glad you were there.|I leave housework to my housework robots. Oh, you wish you had one, too? I'd be happy to give you one.|On the way here, I ran a performance optimization on my interactions with you. I did bump into a door one time and trip and fall once, but... Ah. I'm okay. That won't affect my performance whatsoever.",
	touch = "Hm...? I just finished synchronizing data. What's the matter, Commander?",
	voice_key_2 = -1,
	mission_complete = "Huh? You finished your missions? When in the world...",
	battle = "Initiating collection of robot companion combat data.",
	id = 702100,
	gift_dislike = "",
	gift_prefer = "A present from the Commander... I love it.",
	profile = "Welcome to my laboratory. I am Bogatyr, the robotics engineer. My robots primarily assist in research and combat, but they are also outfitted with features such as cooking, cleaning, and shopping. They're very convenient.",
	voice_key = 70210,
	headtouch = "Core temperature rising. Overload imminent...",
	feeling2 = "Wrench, please... Pliers, too. And the blowtorch... You don't know where they are? I'll send you the map of my lab now.",
	login = "Adjusting robot movement functions. Current progress 79%... New access request detected. Oh... Commander?",
	detail = "This is a charging station designed for my robots. It's safe, portable, provides stable power output, and supports multiple charging interfaces. Would you like a demonstration?",
	couple_encourage = {
		{
			{
				70208
			},
			1,
			" Your inventions... show good taste.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[702101] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Scan 56% complete... Welcome back, Commander. I'll be ready soon...",
	unlock = "System error detected. Abnormal data is being generated at a rapid pace, and energy consumption exceeds normal values. Initiating emergency diagnostic protocol. Commander... stay with me until the root cause is found, please...",
	touch2 = "Ah, ahh... So much abnormal data is flooding in...",
	mission = "",
	vote = "",
	drop_descrip = "System error detected. Abnormal data is being generated at a rapid pace, and energy consumption exceeds normal values. Initiating emergency diagnostic protocol. Commander... stay with me until the root cause is found, please...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Abnormal data analysis complete. It isn't a hardware malfunction or a system error. It all points to a new prime directive: I want to be with you, Commander.",
	main = "Self-checking diagnostic failed... Commander, I require a more in-depth scan. Please connect to me...|Ah... Mm... An electric current is stimulating my depth sensors... Commander, help me stand up straight...|Mobility functions offline. Commander, hold my hand... I need help.",
	touch = "Please do not touch my cable. I may run out of energy...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 702101,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "As my energy levels decrease, my scan efficiency is... increasing?",
	feeling2 = "",
	login = "Restart complete... Commander, I'll find the source of the abnormal data right away. Just stay a little longer...",
	detail = "When you come close, the abnormal data increases exponentially... Commander, am I going to break?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[703010] = {
	hp_warning = "Urgh... What kind of monsters are they?!",
	feeling3 = "Don't like my scoldings? Then do better! You're not about to tell me you actually ENJOY being scolded, I hope.",
	mail = "A letter has come in. I wonder who sent it...",
	expedition = "Your job now is to go and show your gratitude to the returning commission team. Do it well and in a timely fashion.",
	win_mvp = "Look at that, we won. Victory comes naturally if you just follow what you trained for.",
	home = "Good work out there. Keep it up.",
	unlock = "The name's Tallinn, heavy cruiser from the Northern Parliament. Don't expect me to blindly take orders from you just because you're the commander. Use that head of yours to think things through first, then we'll talk.",
	touch2 = "Ngh...?! Now you've done it...",
	mission = "It is imperative that missions be completed. This was true during my time in the Iron Blood, and is still true now.",
	vote = "",
	drop_descrip = "Heavy cruiser - Tallinn.",
	feeling4 = "I'm surprised you've actually taken my scoldings to heart. Hehe, hahaha... Since you like it when I tell you what to do, I'll be more exact from now on.",
	lose = "...Tsk, all because of some small mistakes...",
	feeling1 = "Use your head before ordering me around. If you can't even do that much, then I won't lift a finger for you.",
	skill = "Fire all cannons! Don't stop shooting!",
	upgrade = "Just as it should be.",
	propose = "All you need to do is sign this document, and I'll take care of everything else. Now to put on the ring and make it official with a kiss... So, how did my lips feel? Hehe~♪",
	feeling5 = "Are you sure you're fit to be a commander, considering how you take orders from your secretary? Don't worry, I'll keep telling you what to do so you can keep your job. I've started enjoying it, actually. Hehehe~",
	main = "Focus on your work. ...What, you need a break? If you've got the energy to complain, you've got the energy to work.|How do Tashkent and Murmansk manage to fit in with the others so well... What? Nothing important. Focus on your work.|I think I'll have a beer after work. Vodka? No thanks. I'll pass.",
	touch = "What do you need? Don't even think about making me do grunt work just because I'm your secretary.",
	voice_key_2 = -1,
	mission_complete = "Hello? Confirm the mission rewards. Don't keep us waiting forever.",
	battle = "Imbeciles! Stop the pointless struggling and surrender!",
	id = 703010,
	gift_dislike = "",
	gift_prefer = "Sure, I'll take it off your hands. You're pretty thoughtful.",
	profile = "I'm Tallinn, Northern Parliament heavy cruiser, formerly known as Lützow under the Iron Blood. I fought in the war under the name of Petropavlovsk as well. In the end, I never did get to unleash my full potential, but I trust your commanding to make good use of me.",
	voice_key = 70301,
	headtouch = "Wha...?! Keep your hands off my head!",
	feeling2 = "If you want me to follow your orders, then prove yourself a capable commander first. I can handle myself if you can't.",
	login = "You're astonishingly late. Did you want me to discipline you that badly?",
	detail = "No matter how many of my cannons are disabled, even should I get turned into a floating turret, as long as I am still able to fight, I shall fight until my last breath. That is my duty and my obligation.",
	couple_encourage = {
		{
			{
				70204
			},
			1,
			"Kirov, I'm counting on you!",
			0
		},
		{
			{
				40301,
				40303,
				40601
			},
			1,
			"Hehe, things are looking pretty good~",
			0
		},
		{
			{
				40304
			},
			1,
			"I've always thought your name was a little funny.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[703011] = {
