_G.pg.base.ship_skin_words[703012] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "It's your duty as the Commander to show your gratitude to a returning commission team. Go on, don't keep them waiting.",
	win_mvp = "We won. Given enough training, victory is par for the course.",
	home = "Wow, you solved that one quick. Keep it up.",
	unlock = "You've reached the Bureau of Investigation... Oh boy, another case. Commander, finish up your paperwork ASAP. We've got witnesses to interview.",
	touch2 = "Huh...?! Now you're really asking for it...",
	mission = "Missions and inquiries alike deserve our undivided attention. Wherever you are, this still rings true.",
	vote = "",
	drop_descrip = "You've reached the Bureau of Investigation... Oh boy, another case. Commander, finish up your paperwork ASAP. We've got witnesses to interview.",
	feeling4 = "",
	lose = "...Tsk. You little rats!",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "This case is going to be a pain... It may be time to ask Chapayev for assistance.|Look, little Manjuu, I can't understand you through your sobbing. Take a deep breath, calm yourself, and then speak.|Well done, Commander. Care to go for a drink? I know a place that specializes in mulled beer.",
	touch = "What is it? I already told you – you're not ready to be a phone operator.",
	voice_key_2 = -1,
	mission_complete = "You've completed a mission, now go claim your rewards. Chop-chop, we're on the clock here.",
	battle = "Hmph. I'll just have to teach you how pointless it is to struggle.",
	id = 703012,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "You're cutting it very close here. Five minutes early to everything – that's something you should practice.",
	detail = "Always work at flank speed – the momentum you build up will keep you going. If you ever forget that, I'll remind you as many times as it takes.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[703013] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Looks like the moon welcomes you. Just for tonight, take it easy. Oh, and don't think about anyone but me tonight♪",
	unlock = "I'm not letting my guard down, even when dressed like this. Take your eyes off me for just a moment and I'll escape to the moon. With you, of course, heheh. Someone has to keep pushing you forward, after all.",
	touch2 = "Now you're pushing it... I can still teach you a lesson even in these clothes!",
	mission = "",
	vote = "",
	drop_descrip = "I'm not letting my guard down, even when dressed like this. Take your eyes off me for just a moment and I'll escape to the moon. With you, of course, heheh. Someone has to keep pushing you forward, after all.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "What was going through the mind of that fairy who journeyed to the moon on her own? I suppose I just wouldn't get it. I'm firmly tied to you, after all. Heehee.",
	main = "Ah, I got so caught up in looking for the best moongazing spot that I completely forgot how chilly this place is... Commander, could you come a little closer? Relax, I'm not going to take off your clothes. Not yet, at least.|As if putting on this bunny ear hairband wasn't enough, now you want me to hop around... You've got some nerve to ask for that!|Crap, I forgot to bring the beer... Luckily, we still have plenty of the osmanthus wine I got for you. Say, how about we exchange drinks? I'll take the osmanthus wine, and you'll drink the beer I forgot. I think that'll go perfectly with this outfit of mine. Heehee.",
	touch = "Ah! Whew... Yes, it obviously makes me jump when you touch me in this outfit! Ugh, fine, just pick up my shoes! Do that, and I'll overlook your little bold move.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 703013,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "What, do you like my rabbit ears that much? I can give you them, but what will I get in return? A kiss, maybe?",
	feeling2 = "",
	login = "Ready to go to the moon, Commander? Hold on tightly to me so you don't fall... What, you thought I was serious? Heheh. You're a funny one.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[703020] = {
	hp_warning = "The thrill of walking the line between life and death... Give me more, more!",
	feeling3 = "I'm not so much a lone wolf, I just choose not to get involved with people. I operate on efficiency and ruthlessness, so I steer clear of cowards and weaklings for their sake, not mine.",
	mail = "Left a letter for you on the desk. I don't care what it's about, so check it yourself.",
	expedition = "Commission completed. Enjoy the job-well-done party yourself – I'll pass.",
	win_mvp = "Ahh... The smell of gunpowder and victory. Just what I like.",
	home = "Oh, you're back... Did you win?",
	unlock = "You're the boss around here? Good. Don't bother trying to tell me what I can and can't do; I'll prove my worth to you my own way. That's all I wanted to say.",
	touch2 = "What are you trying to do?",
	mission = "You need my help with this new mission? Fine, you rest in the meanwhile. I'm not a team player.",
	vote = "",
	drop_descrip = "Heavy cruiser – Kursk.",
	feeling4 = "People say I'm cold, but I just don't feel the need to pay attention to every little shift in other people's moods. Getting caught up in emotions is a waste of everyone's time.",
	lose = "Urgh... My hunt can't end in a place like this...!",
	feeling1 = "Stay away from me.",
	skill = "I'll rip you to shreds!",
	upgrade = "The thrill of gaining power... makes me crave more.",
	propose = "...You serious? You want ME, the lone wolf of the tundras? Heheh. Let's see if you have what it takes to tame me.",
	feeling5 = "Even though I've adapted to solitude, I somehow don't feel repulsed when I'm around you. Maybe... Maybe you've rubbed off on me.",
	main = "Hunters are loners by nature – only helpless prey form groups. I walk a solitary road for that reason.|Tactics? Those are a chore. I follow my gut instincts. Nothing can tamper with that.|Snow, huh... I love when it snows. Makes it easy to cover up my tracks. It's as though it was made for ambushing.",
	touch = "Something urgent? I'll do it, if you want.",
	voice_key_2 = -1,
	mission_complete = "Mission rewards have come in. Go check 'em. Everything that's there, you've earned.",
	battle = "The hunt is on!",
	id = 703020,
	gift_dislike = "",
	gift_prefer = "It's almost unsettling how well you know my preferences... I'm saying it's a good gift. Thank you.",
	profile = "I'm Kursk, a hunter from the snowy tundras of the North... That's too brief? Ugh, what a waste of time... I hate socializing. If you want to get along with me, then keep your distance.",
	voice_key = 70302,
	headtouch = "Why are you acting like we're that close? I don't get you people...",
	feeling2 = "Swords become dull if not sharpened. It's why I still go back to the tundra and hunt like I used to – skills, like swords, need to be maintained.",
	login = "Morning, boss. I was going to leave you a note before I left, but decided to just tell you in person after all.",
	detail = "I'm used to working solo. Even if it doesn't snow here, I can still cover up my tracks... if I want to.",
	couple_encourage = {
		{
			{
				49901
			},
			1,
			" You smell of danger... Interesting.",
			0
		},
		{
			{
				10313,
				20120
			},
			1,
			" There won't be enough prey to go around with this many hunters.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[703021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "I left your letter in a less humid spot. Don't want your important papers getting wet, do we?",
	expedition = "",
	win_mvp = "",
	home = "Where have you been? ...You didn't want to pass out from dizziness? Don't worry about that. Worst case scenario, I'll just carry you back home.",
	unlock = "This steamy hot spring... is a rather novel experience. I left a spot for you, so come sit down already – Wait, why haven't you taken your clothes off yet?",
	touch2 = "You want to get up close and personal, huh? Heheh.",
	mission = "A new mission just got handed down. Go ahead and take a look – we'll have plenty of time to relax later.",
	vote = "",
	drop_descrip = "This steamy hot spring... is a rather novel experience. I left a spot for you, so come sit down already – Wait, why haven't you taken your clothes off yet?",
	feeling4 = "",
	lose = "Seems I'm still wet behind the ears...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Seems the Sakura Empire has the most hot spring enthusiasts. Not that I don't want to bathe with them, but as you know... I'd rather be alone.|The hot steam causes the cold air to fog up, impeding visibility and making this an ideal place to set up an ambush... Heh. Don't worry. I'm right here.|How's the temperature? If you want, I can turn up the heat using my rigging.",
	touch = "While I hate rubbing shoulders... I can tolerate you being around.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "There's no reason I cannot go into battle like this. The hunt is on!",
	id = 703021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Hmh... The water's nice. What are you waiting for, Commander? Get in.",
	detail = "...Am I cold? Not really. If I can handle an ice bath, a hot spring is nothing. You, on the other hand, should be careful of the night breeze.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[703022] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Alright, you don't sound hurt. Seeing you safe and sound makes me happier than hearing you win or lose.",
	unlock = "I prefer talking face-to-face, but if you really insist... Heavy cruiser Kursk sits in an office chair, donning a Dragon Empery dress. What's next, Commander?",
	touch2 = "Well, well. You want me to change my pose? Can do.",
	mission = "",
	vote = "拉票描述",
	drop_descrip = "I prefer talking face-to-face, but if you really insist... Heavy cruiser Kursk sits in an office chair, donning a Dragon Empery dress. What's next, Commander?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I'll admit, this new approach is interesting, but I've never done it with you before. Who will top who? We'll find the answer shortly. Heehee.",
	main = "Boisterous parties are not my thing. Still, I changed into an Empery dress to fit in with the festive mood. Yeah, it's a high slit, up to the waist. Can you guess what I'm doing now as we speak?|I've put my legs up to get more comfortable. Yeah, it's exactly what you think... \"Not a very Kursk pose\"? It's called changing strategies to catch valuable prey.|...Nice fireworks. If I can hear the booms from over here, we mustn't be very far apart. Keep searching, Commander, and you might just get a look at me.|Hm? You're coming back already? The prey yearns to be caught, it seems.",
	touch = "I like honesty in both words and actions. If you want something, just tell it to me straight.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 703022,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "...If you're going to pat my head, say it to my face.",
	feeling2 = "",
	login = "Welcome back. You don't need to count me in at the party. If you start missing me, just give me a call.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[703030] = {
	hp_warning = "Don't lose focus! Victory is almost within reach!",
	feeling3 = "You ask if I ever feel lonely. The port is where you are, Comrade Commander, so the answer is naturally \"no.\"",
	mail = "Is that the latest battle report? Read it quickly – our comrades on the front lines are waiting for our answer.",
	expedition = "Our comrades are back from their commission, bringing substantial spoils. They've done well.",
	win_mvp = "Victory is ours! This is the fruit of our collective labor.",
	home = "I bid you welcome back, Comrade Commander. To protect the peace and seize victory – these are the things we set sail for.",
	unlock = "Northern Parliament Project 66 heavy cruiser Moskva. Greetings, Comrade Commander. In your eyes I see the glimmer that can make our dreams come true. Allow me, as your strongest sentinel, to temper your will.",
	touch2 = "...Does \"friendship\" include doing such intimate things?",
	mission = "Comrade Commander, you still have missions to accomplish. Do you want me to help rank them by priority?",
	vote = "",
	drop_descrip = "Project 66 heavy cruiser – Moskva.",
	feeling4 = "As I understand it, a friend is someone you share time and space with. Ergo, it makes sense for me to stay by your side.",
	lose = "Comrade Commander, evaluate the casualties and prepare for the next battle.",
	feeling1 = "The port's temperature is too comfortable. Sometimes, a cold breeze is needed to keep you sharp.",
	skill = "Face the end!",
	upgrade = "No blizzards will impede me on our next expedition.",
	propose = "Is this ring a proof of friendship? Very well. Then from now on, you are my one and only best friend. We'll always be together now, won't we?",
	feeling5 = "You said you'd be my friend forever, did you not? In that case, there should be no problem with us standing this close, holding hands, heads pressed together – right?",
	main = "Everyone gathers at your side and chats like it were the most natural thing in the world. How do you create such an approachable atmosphere? Have I been too strict with others?|I can always offer consultation if you have any concerns over strategy. It's also my professional duty.|I'm especially fond of winter swimming on snowy days. One can better temper their spirit in cold climes, you see. Have you considered trying it, Comrade Commander?|Excuse me, Comrade Commander... How does one initiate topics unrelated to work?",
	touch = "Is this something that friends do? My understanding isn't wrong, is it?",
	voice_key_2 = -1,
	mission_complete = "Mission rewards have arrived. Your hard work has paid off.",
	battle = "For freedom! For our ideals! Uraaa!",
	id = 703030,
	gift_dislike = "",
	gift_prefer = "Did you get this just for me? Thank you.",
	profile = "I am Moskva, Northern Parliament heavy cruiser. My hobbies are winter swimming and skiing. A little eccentric, you say? That's true. Still, this spirit of pushing through the snow and wind is what allows us to aspire for our ideal world.",
	voice_key = 70303,
	headtouch = "Comrade Commander, our relationship has taken another great step toward the highest level of friendship, hasn't it?",
	feeling2 = "You want to call me \"friend\"? This is the first time anyone has called me that.",
	login = "Ready to get to work, Comrade Commander? Excellent. You are our role model.",
	detail = "You wish to get to know me better? Sure. I can tell you anything, be it my tactical thinking, my rigging structure, or even personal things about me.",
	couple_encourage = {
		{
			{
				70502
			},
			1,
			" I didn't see you there. Now, our defense is unshakeable!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[703031] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome back, Comrade Commander. I just figured out how to exploit the state you left the board in. Look forward to seeing it.",
	unlock = "The extent of one's true wit is revealed within the 19 lines on the board. Ever since I began learning to play Go, I've desired a match with you. Observe now, as this next move will determine the outcome of the game.",
	touch2 = "Mmh... Not where you meant to put it? No, since it's come to that, I will respond in full force.",
	mission = "",
	vote = "",
	drop_descrip = "The extent of one's true wit is revealed within the 19 lines on the board. Ever since I began learning to play Go, I've desired a match with you. Observe now, as this next move will determine the outcome of the game.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Fighting spirit, positioning, resourcefulness... Only you can match me to the end in these aspects. It's wonderful to have a worthy opponent, and I'm convinced that this game has further heightened the feelings we share.",
	main = "Your opening move may have seemed mindless, but it was packed with meaning. Before long, I noticed you had me going all out...|Your turn. If you're unsure of what move to make, then I know a way to clear your mind quickly.|Seems it's my turn. Since one can't undo a move, I'd better consider the board state and act cautiously... Give me a moment to think of how to respond to your move...|Ah, what a move... You caught me, let's say, pretty off guard.",
	touch = "Mgh... That's where you wanted to put your stone?",
	voice_key_2 = -1,
	mission_complete = "Mission rewards have come in. Shall we have a look at them after we finish this game?",
	battle = "",
	id = 703031,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "You messing with my hair isn't going to impede my judgment.",
	feeling2 = "",
	login = "Ah... You're here. I'm reviewing the last game we played. That move of yours was utterly sublime...",
	detail = "Want to see how I placed my stones? You can even come a little closer. My plan from the start was to enjoy this game with you anyway.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[705010] = {
	hp_warning = "Ahahahaha! At last, this is a battlefield that I am meant for!",
	feeling3 = "I hope you don't take this the wrong way, comrade, but this fight is not just for all of us. It's also yours. Never settle with the status quo, and always seek to keep improving.",
	mail = "You have a letter, comrade. It would be best to open it soon.",
	expedition = "Hopefully our comrades will return bearing good news, unlike that bitter Ice Cruise. Come on, let's go welcome them back.",
	win_mvp = "Rejoice, for we have earned this privilege! May this celebration become the bread that sustains us until our next victory!",
	home = "O comrade, do you return bearing news of glorious victory? Ah, but it matters not, for the thing that matters most is that you fought with all your strength! ",
	unlock = "Hahaha! Not bad, comrade! Come, let us fight for the safety of these azure lanes! Fight until your last breath!",
	touch2 = "What are you doing, comrade? Are you not aware of how we handle lawbreakers in the Northern Parliament?",
	mission = "Missions exist for the sake of preserving the order. We should complete them as soon as possible.",
	vote = "",
	drop_descrip = "Gangut-class battleship – Gangut.",
	feeling4 = "Ahahahaha! Well done, comrade! No matter how strong the enemies we may face, we now join each other courageously, prepared to give everything in pursuit of greater challenges! What could be more revolutionary than that?",
	lose = "Comrade, consider this not a defeat, but rather a warning. A sign that we are losing sight of our revolutionary spirit.",
	feeling1 = "There is no future for those who mistake recklessness with courage, comrade.",
	skill = "The revolution blesses you!",
	upgrade = "Comrades! You are also strong! Let our souls shine out brilliantly!",
	propose = "A pledge, huh? While this act is symbolic in nature, it is also undeniable proof of the bonds we've formed. A toast, comrade. Please continue to guide me in the future.",
	feeling5 = "Let's get to the point! Comrade, I was struck by your brilliance, and thus I fell for you! And now, I face the challenge of how to express my feelings for you! Here, comrade, accept my embrace!",
	main = "Comrade, how about a few drinks? ...What? Don't tell me you can't even handle a swig of vodka! |O comrade, aren't those stories about the exploits of sailors absolutely riveting? You see, that is the very spirit of revolution, humanity in all its glory! |An easy victory? What a stupid thing to say, comrade! How are you supposed to draw out your full power if you have nothing worthwhile to fight? Send me to a more dangerous battle next time!",
	touch = "What about my rigging? Isn't fully utilizing everything at your disposal a wonderful and pragmatic ideal? Why would I consign myself to weakness for the sake of showmanship?",
	voice_key_2 = -1,
	mission_complete = "Excellently done! This reward will help pave the next step of our revolution!",
	battle = "Show me your mettle!!",
	id = 705010,
	gift_dislike = "",
	gift_prefer = "Hahahaha! Are you testing me? Very well! Then I will just have to give YOU a gift of equal value! Just you wait, Comrade!",
	profile = "I am Gangut, a dreadnought from the Northern Parliament. My equipment may be outdated, but don't underestimate me. Both humans and ships are alike in their quest for greater power, to protect what they otherwise would not be able to. That is революция, the revolution I strive for! From the Bering Sea to Leningrad, only by rising up in the face of humiliation was I able to become a beacon for the light of glory!",
	voice_key = 70501,
	headtouch = "",
	feeling2 = "I am Battleship Gangut, also known as Oktyabrskaya Revolyutsiya. However, my name is less important the what I've achieved. Don't dwell too much on it and just call me what you want.",
	login = "Comrade, what sort of strong enemy will we face today? I, Gangut, shall stand with you!",
	detail = "Know this, comrade. Even if I am battered and bruised, muddied by defeat, I will rise each time to reclaim the glory of mankind! Yes, that is the революция I desire, the only heaven that exists for me!",
	couple_encourage = {
		{
			{
				30511
			},
			1,
			"Ahahaha! Finally, I have the privilege of fighting by your side, Mikasa!",
			0
		},
		{
			{
				70201
			},
			1,
			"For the light of revolution!",
			0
		}
	}
}


