	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "This outfit resembles something that you'd wear in the Eagle Union or Iron Blood, right? If I chose something more imposing, I'd scare off the kids! |\"This is Gangut... Everything's fine over here, so stay on patrol.\"|Care for a drink, comrade? Come on, it's good stuff. I just happen to have a little bit of free time.",
	touch = "Are you curious about this medal? You can make as many replicas as you'd like!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 705011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, did you come to inspect the exercise? Hahaha! Feel free to ask away!",
	detail = "Comrade, it is too soon to confess to your sins! Struggle for your freedom, and resist until you are about to break! That is the true path to growth!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[705012] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "My room is a total mess, you say? I suppose it is, yes. If I am to clean it, the question becomes, where do I start? The bottles? The magazines?",
	unlock = "...Bwahaah! I've had all kinds of liquor, but nothing beats the stuff back home! Comrade, let's have a toast to the coming off-duty days!",
	touch2 = "You're drunk out of your mind, aren't you, comrade? No worries, you may use the couch! Go on, lie down!",
	mission = "",
	vote = "",
	drop_descrip = "...Bwahaah! I've had all kinds of liquor, but nothing beats the stuff back home! Comrade, let's have a toast to the coming off-duty days!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Comrade, you must always be ready to fight, even in times of peace. If you get complacent with the status quo, then who else will stand up in the event of a crisis?|The Sakura Empire is home to a few drinkers too, I've learned. Ise and Hyuuga, I think their names were? I'll invite them over the next time I'm enjoying some liquor!|Ugh! I've had enough of this! Get up, comrade! We'll round up some more comrades and go for some target practice!",
	touch = "Drink, comrade! Have another shot! You'll have to do much better than that to get me plastered!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 705012,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I take it you've come to share a drink with me, comrade? Ahahaha! What a coincidence, I just received this bottle of vodka from Avrora. Two shots, coming right up!",
	detail = "Have you read the article in this magazine, comrade? It's a great piece on how the working class is the reason for our ever-improving quality of life.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[705020] = {
	hp_warning = "Where did my plan go awry?",
	feeling3 = "I won't become closer with people merely by listening to them. I know that, but I'm terrible when it comes to talking about personal matters. Comrade Commander, please, give me a hand. You have the tools to help develop my interpersonal skills.",
	mail = "This letter is for you, Comrade Commander. Here, use this letter opener.",
	expedition = "The commission team has returned. You should go speak to them, Comrade Commander. I... Seeing me may stress them out, so I'll stay here.",
	win_mvp = "Great. This is going just as expected.",
	home = "You're back, Comrade Commander. I put new wood in the fireplace. It should dispel the chills you're feeling from the weather out there.",
	unlock = "I am Sovetsky Soyuz, flagbearer of the Northern Parliament's will. I hope extending a simple greeting doesn't make you too anxious, Comrade Commander. Let us henceforth work together and fight side by side.",
	touch2 = "Comrade Commander, if you want to deepen our relationship... it will take a toll on your spirit, and especially your body.",
	mission = "Here is the mission list... Let's focus on efficiency. I'll handle the logistics while you concentrate on the missions themselves.",
	vote = "拉票描述",
	drop_descrip = "Sovetsky Soyuz-class battleship – Sovetsky Soyuz.",
	feeling4 = "The relationship with you I seek is something deeper than an acquaintanceship or alliance... but I feel like it's selfish of me to want it. Why is that? Because becoming friends with me carries much, much more weight than you think.",
	lose = "How unfortunate. Our plans will need to be revised.",
	feeling1 = "It seems I have no choice but to show you my strictest side, Comrade Commander.",
	skill = "United as one!",
	upgrade = "Thank you, Comrade Commander. This concludes my maintenance.",
	propose = "At last, this time has come. I know I specifically asked to deepen our relationship, but... to be frank, I always feared I wasn't returning your feelings properly. I've felt this the whole time, but now, there is no longer any doubt in my heart, heehee. Yes, this is the future I wished and hoped for. From this day onward, we walk together.",
	feeling5 = "We've reached the point where I can call you a close friend, Comrade Commander. I'd like to take our relationship even further, though... Don't be so surprised. Knowing you, I'm sure you understand what I mean.",
	main = "Planning and efficiency. The two things you need to make it in the world... No, I believe they are important, but I wouldn't go as far as saying that they are everything. Rest assured, there is more to life.|You feel I'm more like a reliable colleague than a serious manager? No one else has described me like that before. Most of my comrades view me as one of the latter.|Not much to talk about outside of work and combat, you say? Yes, there aren't very many situations where I can offer input. All the more reason why I should focus on listening to what others say rather than speak myself.|Rossiya, Belorussiya... Or should I say, my sisters. They're doing so well. One day, they will surely surpass me.",
	touch = "Yes? Do you have a new production adjustment proposal?",
	voice_key_2 = -1,
	mission_complete = "Mission rewards have arrived. They have been reviewed already.",
	battle = "Onward. No turning back.",
	id = 705020,
	gift_dislike = "",
	gift_prefer = "This is very thoughtful. How could I say no?",
	profile = "I am the first ship of Project 23, Sovetsky Soyuz. Like my sisters, I was a centerpiece of the Northern Parliament's naval strategy. Now my strength is all yours to wield, Comrade Commander. Your decisions have my support, as always, because I have full confidence in your ability.",
	voice_key = 70502,
	headtouch = "Well... This is unexpected, coming from you. Still, I'll allow it. This contact is a morale booster for your troops, after all.",
	feeling2 = "...A solemn ruler, or a curt decision-maker? What I want to be is a listener, a person whom others confide in. Changing people's views of me in that direction is quite difficult, however.",
	login = "I take it you're ready, Comrade Commander. It's time to get started on today's tasks.",
	detail = "Why I'm fond of Arctic hares, you ask? Don't you think they look adorable when they stand up, Comrade Commander? ...You really don't see it? Their bodies are so round, yet their little arms and legs get so long when they stretch! Isn't the contrast just so shockingly cute?",
	couple_encourage = {
		{
			{
				70505,
				70504
			},
			1,
			"Onwards we march, together.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[705021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Excellent work. How's the stage-setting going? ...Oh, the camera was rolling. Please send that take to the cutting room floor.",
	unlock = "This is Agent Sovetsky Soyuz, codename Polyarnaya Zayats, commencing infiltration. I'd hate to spend long on breaking through the security, so please just surrender now. It's not too late.",
	touch2 = "So you like roleplay, do you, Comrade Commander?",
	mission = "",
	vote = "拉票描述",
	drop_descrip = "This is Agent Sovetsky Soyuz, codename Polyarnaya Zayats, commencing infiltration. I'd hate to spend long on breaking through the security, so please just surrender now. It's not too late.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Ah, yes, agents creating a family does sound like an interesting theme. Would you like to... give it a try, Comrade Commander?",
	main = "Did you think you could escape justice by hiding in a fortified skyscraper? You banked on a naive hope – which I'm now going to crush.|That was a pretty visually stunning take, wasn't it? ...Hm? You're worried your performance as my rival won't be that good? I understand. Once we're done filming, let's go find a place for you to rehearse.|Changing careers and trying a different life... It's more fun than I expected. I'd love to do this again if I ever get the chance.",
	touch = "My way in is... Rappel down from the roof, then break directly into the room with the objective. A plan full of highlights, it seems.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 705021,
	gift_dislike = "",
	gift_prefer = "This is very thoughtful. How could I say no?",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Perfect timing, Comrade Commander. Everything is prepped and ready. Give the order to sortie.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[705022] = {
	hp_warning = "",
	feeling3 = "",
	mail = "There's a letter for you, Comrade Commander. You should be able to easily open it if you make adept use of these strings.",
	expedition = "The commission team has returned on time. Find a suitable time to meet them to ensure the plan doesn't fall through.",
	win_mvp = "",
	home = "Mgh... Are you going to disable the trap already, Comrade Commander? You don't need to, as I can maintain this pose without trouble.",
	unlock = "Curses... To think I'd fall for such an elementary trap... I take it you're going to \"interrogate\" me now, Comrade Comander? Oh, no, it's just... if you don't know the proper technique, I could assist you.",
	touch2 = "Ahh... Apologies, my body has gone numb, impairing my tactile sensitivity...",
	mission = "To ensure you can begin your mission as soon as possible, I'll– Mmh!",
	vote = "",
	drop_descrip = "Curses... To think I'd fall for such an elementary trap... I take it you're going to \"interrogate\" me now, Comrade Comander? Oh, no, it's just... if you don't know the proper technique, I could assist you.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Despite being in a pinch, I strangely feel as though I can be open with you, Comrade Commander. Come to think of it, I've never been in a situation where I'm entirely at someone else's mercy, unable to do anything... You're free to do with me as you please. I trust in your strength and our bond.",
	main = "There's no need to worry about me. My only issue... mmh... is that it's hard to see you in this position.|Any further delays will negatively impact the plan. Using force to extract information is an option at your disposal, Comrade Commander.|My outfit being as flexible as it is has backfired. I'm tied up in such a way that... I can't free myself with my own strength...|When viewed another way, this is a chance for us to share secrets and deepen our relationship... Ah, no, I didn't say anything.",
	touch = "Comrade Commander, that's my– Ah! No, I'm fine...",
	voice_key_2 = -1,
	mission_complete = "Mission rewards have arrived. One of our comrades will surely claim them for us.",
	battle = "",
	id = 705022,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Comrade Commander?! Ahem! How shameful of me to be caught... No, actually, this may very well be a blessing in disguise.",
	detail = "A little chat to start with? Yes, let's. Although I'm fine, I imagine it's hard for you to stay calm in this situation. Let's talk about how cute Arctic hares are when– Oh, save that topic for another time, you say?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[705023] = {
	hp_warning = "",
	feeling3 = "",
	mail = "There's a letter for you, Comrade Commander. This is an excellent chance to test the precision of my cuts.",
	expedition = "The commission team is back on time. I should... Actually, no, you're better suited to receive them than I am currently.",
	win_mvp = "",
	home = "Excellent work, Comrade Commander. The night is still young, and I will be making good use of your body until morning.",
	unlock = "So here you are, Comrade Commander. You're usually so well-guarded, yet now you're all by yourself – something I can only describe as careless. I, Sovetsky Soyuz, shall take you on.",
	touch2 = "What you just did... was it due to my outfit?",
	mission = "You need only surrender and I'll take on your missions for the day... Is that not enough?",
	vote = "",
	drop_descrip = "So here you are, Comrade Commander. You're usually so well-guarded, yet now you're all by yourself – something I can only describe as careless. I, Sovetsky Soyuz, shall take you on.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I can do whatever I like to you if I get you to surrender... Heehee. I'm sure you can imagine what a tempting proposition that is. Even so, you're still willing to cooperate – is that because you trust me? Or is it, perhaps, because deep in your heart, you want me to be dominant with you?",
	main = "Cease your futile resistance and give me the rest of your time – how does that sound? A good deal, wouldn't you think?|No matter how well one person prepares, the collective wisdom and efforts of the many will easily trump the few. You lose, Comrade Commander.|Hmm – you're approaching me? Instead of running away, you're coming right to me? Are you, too, perhaps actually well-versed in swordsmanship?|Even should you make a choice with many irrational aspects, I will still gladly accept it since it's your choice, Comrade Commander. Heehee – the same goes for this outfit.",
	touch = "Come at me whenever you're ready, Comrade Commander.",
	voice_key_2 = -1,
	mission_complete = "Mission rewards have arrived. We should examine them in just a bit.",
	battle = "",
	id = 705023,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "There is nowhere left to run, Comrade Commander. Now, as planned... I mean, as fate dictates, allow me to attack you one time.",
	detail = "While improvising is easy, playing the role of your assailant is hard. Oh, no, I don't mean that attacking you is hard, but rather that it's hard for someone like me to seize the initiative and... well...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[705040] = {
	hp_warning = "The battle is still under our control!",
	feeling3 = "Oh, so you don't mind losing a bet if it means you get my help? I see. Well, regardless, it doesn't matter who wins a bet made on the spur of the moment. Now, what do you need assistance with, Comrade?",
	mail = "A letter? I welcome correspondence, assuming it is an enthralling read.",
	expedition = "Interested in a bet, Comrade? Do you think the commission team has returned with bountiful rewards, or few at all?",
	win_mvp = "This comes as no surprise. All I did was nudge those fools toward the annihilation they so desired.",
	home = "Do not be so lenient with the enemy next time, Comrade.",
	unlock = "Comrade, are you sure you're ready to have me under your command? Very well! Let us join hands and lay waste to our enemies — using my methods, of course!",
	touch2 = "You chose the most depraved of ways to prove you have guts, Comrade.",
	mission = "Comrade, sure we should not allow the glorious advance of our fleet to be delayed by such trifling missions.",
	vote = "",
	drop_descrip = "Sovestsky Soyuz-class battleship - Sovetskaya Belorussiya.",
	feeling4 = "If you ever tire of managing the fleet and planning battles, I will take over for you. You can rest easy, knowing I will bring you good reports on the daily. Although, knowing your devotion to your job, I doubt you'd ever delegate it to get some rest.",
	lose = "Everyone makes mistakes, I suppose...",
	feeling1 = "I don't care. You are absolutely nothing to me. Just stay out of my way.",
	skill = "Cease your pointless struggling!",
	upgrade = "We will curb the enemy with our superior firepower! Hahaha!",
	propose = "You hope this ring will forever connect me with you, do you? Then I believe it will, because I believe in you. Only you are capable of standing at the top of the world together with me. Do not let me down, Comrade.",
	feeling5 = "You don't mince your words, do you? I will say I do prefer a forthright confession of love over beating around the bush. Standing at the top of the world, gazing at the horizon, with you by my side – I like the sound of that. Ahahaha!",
	main = "It's much more entertaining to lure your foes into a trap one at a time than to crush them all at once. Am I right?|Seems it's all quiet on the western front... Don't you have any palpitating news?|There is no greater pleasure than decimating your enemy with minimal losses. Wouldn't you agree?",
	touch = "Let me guess, you are simply poking me for your own amusement, and not because you need something done. Am I wrong?",
	voice_key_2 = -1,
	mission_complete = "Fantastic. With HQ's missions complete, we can finally continue with our own plan.",
	battle = "Crush the enemy! Break their spirits, then their bones!",
	id = 705040,
	gift_dislike = "",
	gift_prefer = "You've figured out my taste with perfect precision, Comrade Commander!",
	profile = "My sisters and I were devised as part of Project 23, but we never saw the light of day, much less fought in the war... But on the other hand, it would've been ludicrous to sail into battle equipped with second-rate armaments. Now though, I would be content with just getting to perform at full capacity under your command, Comrade.",
	voice_key = 70504,
	headtouch = "Your little hand gestures have no effect on me.",
	feeling2 = "How about a bet, Comrade? Do you think your job will only be accomplished thanks to my help, or regardless of it?",
	login = "Aha! I knew you'd be back right at this hour, Comrade! Rossiya doubted my intuition.",
	detail = "If excellency is what you seek from the Sovetsky Soyuz class, I am your best and only true option!",
	couple_encourage = {
		{
			{
				70505
			},
			1,
			"Dropped some screws? I'll gather them up for you!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[705041] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "I see you've all returned in one piece. Your reputation has further improved as a result.",
	unlock = "To pass the time by proactively reading, or by passively enjoying the company of others... Ah, good morning, Comrade, I've been expecting you. Hahaha!",
	touch2 = "What, did my revealing outfit cause you a lapse of judgment?",
	mission = "",
	vote = "",
	drop_descrip = "To pass the time by proactively reading, or by passively enjoying the company of others... Ah, good morning, Comrade, I've been expecting you. Hahaha!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Anyone's life can be enriched by having many diverse interests. Even I enjoy the odd girly hobby or two.|Oh please, don't toot your own horn, Comrade. I know several destroyers who read advanced literature too.|I need to get up and move around a bit. My joints start aching if I sit down for too long.",
	touch = "",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "There's no point in betting on a sure outcome! Onwards!",
	id = 705041,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Take it easy. There are many ways to kill time. Just pick one which feels sound.",
	detail = "What's your favorite book, Comrade? I'm asking out of curiosity, and to have something to recommend to Soyuz and Rossiya.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[705042] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Hm? A letter? I hope it's nothing that will ruin the moment...",
	expedition = "The commission team has come back? I have a feeling that the spoils will far exceed your expectations. Hahaha!",
	win_mvp = "",
	home = "Welcome back. Wish to spend your break time with me, do you? Hahaha! Then you should cherish this moment we have to ourselves.",
	unlock = "Haha! Did you not expect this to be our rendezvous spot? Oh please, even I wish to unwind in the sand sometimes. Since you're here, accepting my invitation, won't you keep me company to kill some time, Comrade?",
	touch2 = "I'll need to bind you with this veil and punish you for this, Comrade.",
	mission = "Finish your missions so we can stroll along the beach and enjoy the weather. I'm raring to feel the breeze.",
	vote = "",
	drop_descrip = "Haha! Did you not expect this to be our rendezvous spot? Oh please, even I wish to unwind in the sand sometimes. Since you're here, accepting my invitation, won't you keep me company to kill some time, Comrade?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "It wasn't the sea breeze that loosened me up – my feelings for you did. I promise you, Comrade, that you will not forget this profession of love for the rest of your life.",
	main = "This breeze really is lovely. Ah, I know – care to make a wager? If you're able to grab hold of this veil, I'll treat you to a reward, Comrade.|It's nice, just staring at the sea with you. It makes even me want to stay here forever.|Wouldn't you agree I look pretty sexy, Comrade? ...Haha! You can't fool me with those halfhearted words. I picked out this swimsuit carefully. Stare as much as you like.",
	touch = "Oh? You thought I'd lowered my guard? You were in over your head if you believed that.",
	voice_key_2 = -1,
	mission_complete = "See? Do as I told you, and even missions will become no more than a way to kill time. Now help yourself to the rewards.",
	battle = "",
	id = 705042,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Are you asking to be tied up in my veil?",
	feeling2 = "",
	login = "Your time of arrival is nearly precisely what I estimated, Comrade. The winds are fair, so let us feel the breeze.",
	detail = "The fact that my prominence is unrivaled remains true even in leisurely settings. Now, let this beach serve as a new stage for you and me.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[705050] = {
	hp_warning = "It's not fatal damage...!",
	feeling3 = "Comrade Commander, what is this? You wish to deepen your relationship with me as an individual, not a representative of the Northern Parliament? Well, such subjective decisions are acceptable.",
	mail = "Mail. Comrade Commander, you must read it quickly before the next one comes bringing another letter.",
	expedition = "Military commissions? They are part of the logistical aspect of proper fleet management.",
	win_mvp = "Kill confirmed. You cannot stop the Northern Parliament... You cannot stop our righteous liberation!",
	home = "Rest. And tell me now of what glorious victory you have won, or how you turn defeat to our advantage.",
	unlock = "I am called \"Sovetskaya Rossiya,\" and as the mightiest of all the Northern Parliament's battleships, I am her ultimate weapon. I will press onward to eliminate all obstacles that stand between you and the Revolution.",
	touch2 = "This is not polite behavior. ",
	mission = "We have a mission. I will handle the clerical work. You must be clear to focus on your duties as a commander.",
	vote = "",
	drop_descrip = "Sovetsky Soyuz-class battleship – Sovetskaya Rossiya.",
	feeling4 = "Mm, this food is well made... Comrade Commander, thank you for serving me this meal, but I have to wonder, is this more than simple social etiquette? C- could you have some ulterior motive for this charm offensive?",
	lose = "Gah, how humiliating... to think a material defect would surface at a time like this...!",
	feeling1 = "This negative attitude is unacceptable. You must be forcibly reeducated.",
	skill = "Blow them away!",
	upgrade = "An excellent strengthening. The next one should be so good.",
	propose = "So long as I draw breath, I labor to carry out my mission. Not only as a member of this fleet, but also in service of the bonds you have forged... This is not a product of rational thinking alone, but also a decision born of my subjective opinion.",
	feeling5 = "Gah, well done...! I have no choice but to place the pride of the Northern Parliament on the line and face defeat at the hands of Comrade Commander's charm offensive! Now then, Comrade Commander, you face the full power of my love offensive!",
	main = "A report I submitted went missing? Pardon my negligence. I'll make it up, so... please don't tell the others about this matter. |I hope that you can command from a global perspective. After all, the responsibility on your shoulders is much greater than just that of an individual. |When I was inspecting my rigging, I noticed a few more screws than last time... Hm, an unexpected \"increase in resource allocation?\" That's a good thing, right? |Your tactics are too conservative! As long as it has not been sunk, it can repaired, learned from, strengthened, and optimized... Continuing this cycle is the best way of fighting.",
	touch = "You want to deepen our camaraderie? Very good, let us start by making a firm handshake part of our regular routine.",
	voice_key_2 = -1,
	mission_complete = "Hm? Something missing from the reward manifest...? It should be generally correct...",
	battle = "Commence bombardment! We will bury them!",
	id = 705050,
	gift_dislike = "",
	gift_prefer = "Oho. Should I take this as a simple token of your goodwill?",
	profile = "I am Sovetskaya Rossiya, of Project 23. I was part of a strategic plan during the war, but for several reasons never came to be. I see though that I can prove my value here in this fleet with a series of decisive victories.",
	voice_key = 70505,
	headtouch = "",
	feeling2 = "Your fleet must be an iron curtain... Hm, it's a metaphorical expression... My meaning is that I hope to see this fleet stand united, just like our Northern Parliament.",
	login = "Comrade Commander, you are late. You must not forget your proletarian values.",
	detail = "Is that you, Comrade Commander...? I'm afraid the office is a bit messy. But we must make sacrifices to achieve our goals.",
	couple_encourage = {
		{
			{
				29901,
				29902,
				39901,
				39902,
				49901,
				89901,
				19901,
				19902,
				39903,
				39904,
				49902,
				99901
			},
			1,
			"This is no time to ponder the meaning of life. Just show us your strength!",
			0
		},
		{
			{
				70204
			},
			1,
			"Kirov, aid me!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[705051] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "",
