_G.pg.base.ship_skin_words[705060] = {
	hp_warning = "My maintenance is lacking? Impossible...!",
	feeling3 = "Ugh... I'm dog-tired... Ah, Commander. Haven't you been working yourself into the ground too? Just don't go completely overboard, okay?",
	mail = "Attention: a letter has arrived! It's for you. Do give it a read.",
	expedition = "Attention: the commission team has returned! Now, to pour something that warms the body – not tea, but vodka.",
	win_mvp = "Victory is mine. Heh, not that I ever had any doubts about the outcome.",
	home = "So you've returned. Now you must reflect on your battle, review your results, and inspect your ships for damage... But first, have some tea while it's still warm.",
	unlock = "I am battleship Arkhangelsk. Hehe, being plainspoken with me is exactly what I like. I see quite a bit of potential within you.",
	touch2 = "Wh-what are you doing–?!",
	mission = "Attention: we've received new missions! Give them a look, Commander!",
	vote = "",
	drop_descrip = "R-class battleship – Arkhangelsk",
	feeling4 = "(Hehehe, what impeccable concentration. I knew you had potential. If you weren't so reliable, I wouldn't be ready to entrust my future to...) Oh, you heard that?",
	lose = "All ships, withdraw! ...You haven't seen the last of us!",
	feeling1 = "You're a disgrace to your position! Apply yourself!",
	skill = "Brace for some revolutionary swordsmanship!",
	upgrade = "How about a complete modernization and retrofit next time, hmm?",
	propose = "Hoho. This is what I wanted to see. An occasion this special calls for more ladylike behavior... Or rather, that I return your affection. Of course I gladly accept! I trust you with my future – take good care of it!",
	feeling5 = "Well, the cat is out of the bag! Commander, I'm going to leave my future in your capable hands. To that end, you must learn how to issue me orders without my input! Understood?",
	main = "It's delightful to see you're still excelling, Lady Warspite. You live up to your name as a royal knight.|While I'm far from the only Northern Parliament battleship at this port, I strive to be the best. Those aren't empty words – I mean it!|Have you finished your work? Ready to start on the next task? ...That's the spirit. Once that's done, we're onto the next, and then the next after that!",
	touch = "Being excessively polite is no different from simply being rude. Speak to me as you would any other.",
	voice_key_2 = -1,
	mission_complete = "Attention: the mission has been completed! Spasíbo! I'm pleased you did them before I had to.",
	battle = "The battlefield knows only one sovereign - me!",
	id = 705060,
	gift_dislike = "",
	gift_prefer = "Very nice! So this is how a real gentleman chooses gifts, eh?",
	profile = "I'm Arkhangelsk, Northern Parliament battleship. I began life in the Royal Navy, taking part in convoy escorts and engagements with the Sardegna Empire. I did also have a period of, let's say, diminished strategic usefulness. But that is in the past – I stand here now to deliver you the victories befitting a capital ship!",
	voice_key = 70506,
	headtouch = "",
	feeling2 = "While I appreciate your courtesy, do remember that I'm not some noble lady, I'm a soldier. Likewise, you're my Commander, so try to act like it!",
	login = "To your desk! Chop-chop! Let's get through today's tasks quickly!",
	detail = "You can lead the fleet as a whole, but in the field, I'll take command. By covering for each other, victory will be certain. Having said that... I wouldn't mind being the one to make decisions around the port every now and then~",
	couple_encourage = {
		{
			{
				60506
			},
			1,
			"If you want to surpass Warspite, you must first beat me!",
			0
		},
		{
			{
				7
			},
			3,
			"Teamwork, everyone! Teamwork!",
			3
		}
	}
}


_G.pg.base.ship_skin_words[705061] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Attention: the commission team has returned! You'd best go out and greet them, Commander!",
	win_mvp = "",
	home = "I'd kill for some tea after work. Say, would you have the time for a tea party, Commander?",
	unlock = "Your choice treasure now belongs to master thief Arkhangelsk! Think you can arrest me? Then stop gawking and come get me!",
	touch2 = "Eek!",
	mission = "",
	vote = "",
	drop_descrip = "Your choice treasure now belongs to master thief Arkhangelsk! Think you can arrest me? Then stop gawking and come get me!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "The right way to spend a vacation is to maximize your moment-to-moment fun. That's the reason I've brought you along, Commander.|Our next objective is to... Ah, we have to bring this over to Kiev to finish our mission. Nice and easy.|Despite my appearance, the fact is that I am a soldier with knowledge of everything from avoiding security to moving stealthily. Shipgirls usually aren't proficient in those? I mean... Doesn't it vary from person to person?",
	touch = "You're coming in loud and clear! What do you need?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 705061,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "We're taking off in just a moment, Commander! Get over here, quick!",
	detail = "I'll be taking this treasure, if you don't mind! Heheh! Royal Navy grace with Northern Parliament dexterity is not a combination to be trifled with.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[705062] = {
	hp_warning = "",
	feeling3 = "",
	mail = "I picked up this letter addressed to the hero. You should really read it.",
	expedition = "The commission team has returned! ...\"A spell that can warp you to the harbor\"? No such thing exists.",
	win_mvp = "",
	home = "Welcome back. You control your mana better than I expected. I'll have to revise my estimates... Don't be anxious. Settle down and have a cup of tea.",
	unlock = "I am Arkhangelsk, the royal sorceress who resides in the tower to the north. So, you wish to study magic to defeat the Demon King? Very admirable... You're deserving of the title of \"Hero.\" I will be equally sincere and impart my teachings to you sternly.",
	touch2 = "W-wait... Are you serious about this?! I'm playing your TEACHER right now!",
	mission = "You've received a new mission from the Mages' Guild. This is the perfect time to prove the fruits of your training.",
	vote = "拉票描述",
	drop_descrip = "I am Arkhangelsk, the royal sorceress who resides in the tower to the north. So, you wish to study magic to defeat the Demon King? Very admirable... You're deserving of the title of \"Hero.\" I will be equally sincere and impart my teachings to you sternly.",
	feeling4 = "",
	lose = "Are you really sure Revenge wouldn't play the sorceress better than me? It doesn't take much stamina, you know.",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Join your party to kill the Demon King? And that's not a request, it's an order? What a bold way to ask your teacher for help. Heehee, that's why you're my disciple. I will join, just don't expect to always be the party leader.",
	main = "You must learn the foundation of magic before you can pursue its greater mysteries. Start off by studying every last book in my library!|The thing floating above me? Heehee, it's just a decorative spell I stumbled upon. It has no practical use... but then again, vanities are inevitable on the road to new things.|Today, we are going to test the limits of your mana! You're going to create water, freeze it, and fire off ice shards a thousand times in a row... What's that? Out of motivation before we've even started?|Go to the tavern after the studying is done? Sure thing. But no vodka! I'm not like Poltava or her sisters!",
	touch = "Oh, do you want to study a new spell?",
	voice_key_2 = -1,
	mission_complete = "I see you've collected your mission rewards. Good. You're on the right path.",
	battle = "",
	id = 705062,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Alright, time to start today's training! The pursuit of magic does not allow even a moment of idleness!",
	detail = "The fun of studying magic lies in taking the knowledge of previous generations and using it in new, innovative ways. You've done this well. Soon, perhaps you'll mature into someone who can pursue the very roots of magic with me.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[705070] = {
	hp_warning = "Urgh...! I'm not even drunk!",
	feeling3 = "I don't know what those battle-addled idiots think of you, but if nothing else, you might make for a fine drinking partner. Heh, don't get too carried away; keep on applying yourself.",
	mail = "Comrade Commander, there's mail for you. If you plan to reply, do it promptly. We don't want to make them wait.",
	expedition = "Transport of goods, especially to battlefields, is a difficult thing. You should be thankful for the efforts of your commission team.",
	win_mvp = "Ahahaha! All who seek to obstruct the revolution are fated to fall!",
	home = "In celebration of our comrades' victory... A toast of vodka! Ack! *chokes*... I-I'm fine!",
	unlock = "Ahahahaha! So you're the Comrade Commander. I'm the Northern Parliament battleship, Sevastopol. Revolution doesn't happen on tea parties alone, comrade. Think of me as any ordinary young lady, and you'll regret it!",
	touch2 = "Comrade Commander... What exactly do you think you're doing?",
	mission = "You have a new mission. Do your best, and keep your eyes on the prize: a celebration full of vodka!",
	vote = "",
	drop_descrip = "Gangut-class battleship – Sevastopol.",
	feeling4 = "*hic*... C'mon, you haven't even finished half your glass yet. Pfft, heheheh... Waiting for me to drink myself under the table, are you? Well, too bad... No matter how much I drink... *hic*... I'm not goin' down...",
	lose = "As long as I have not sunk, I will continue to stand time and time again! That is the meaning of revolution!",
	feeling1 = "You certainly have the qualifications to be a proletariat, but you don't quite understand the revolutionary spirit...",
	skill = "Glory to the revolution!",
	upgrade = "What revolutionary growth. Hahahahaha!",
	propose = "...Mm? Where am I? Oof, I might've drank too much. Comrade Commander, what's with this ring? You mean I... snatched it from you and put it on my self? I-I really did that?!",
	feeling5 = "*hic*... Comrade Commander, I like you. Hell, I love you. If I win this, I'll be your eternal partner and join you in the final battle. Now, I'm not dead-drunk yet. How about you just... accept defeat?",
	main = "Comrade Commander, join me for a drink! Waaait, you're not telling me you don't know Northern Parliament tradition, are you? ...You don't like vodka? Crappy excuse, sorry. See? We've got wine, too!|Carrier-based aircraft? Let me just say, bring 'em on. We'll see if they can beat Sevastopol!|Social standing matters not when it comes to revolution. Heh, as long as we share the same willpower, we're comrades through and through!",
	touch = "We are two comrades. I will gladly exchange a handshake with you!",
	voice_key_2 = -1,
	mission_complete = "Ahahahaha! Another step closer to revolution! M-maybe I'd better tone down the drinking for today...",
	battle = "If you don't want to die, stand aside!",
	id = 705070,
	gift_dislike = "",
	gift_prefer = "I like it! I-it is for me, isn't it?",
	profile = "Dreadnought of the Northern Parliament and flagship of the Black Sea Fleet, Sevastopol, has arrived. Hahah, I am the very ironclad willpower of the revolutionary vanguard, always under attack but never falling! Got it?",
	voice_key = 70507,
	headtouch = "Huh?! H-hands off!",
	feeling2 = "I could trounce you with ease, but as people with similar goals, I will treat you as an equal. Heh, you should be thankful that you've become an ally of the Northern Parliament instead of sinking beneath our iron billows.",
	login = "Good morning, Comrade Commander. Come and show us who we will do battle with today!",
	detail = "Well met, comrade. Would you like to learn more about my revolyutsiya? Heheh, you hardly have to ask. I know you like the back of my hand, comrade.",
	couple_encourage = {
		{
			{
				70501
			},
			1,
			" Ooh, I smell vodka...",
			0
		},
		{
			{
				70506
			},
			1,
			" Politeness? Pssh, who cares about that?!",
			0
		},
		{
			{
				30511,
				70201
			},
			1,
			" Don't get too full of yourself now~♪",
			0
		}
	}
}


_G.pg.base.ship_skin_words[705071] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission team is back. Think it's their turn to come in after us?",
	win_mvp = "",
	home = "(This hot spring is so comfy... I didn't even realize I was drunk until the Commander arrived.)",
	unlock = "Phew... This is... Comrade Commander? Fancy meeting you at this time of night. Me? Heh, heheheheh... You wouldn't believe me if I said I got too drunk and went in first, would you?",
	touch2 = "I'm soaked? ...Haha, well, yeah? I was bathing in the hot spring, so duh...?",
	mission = "A new mission... Once it's over, how about we celebrate with wine instead of vodka?",
	vote = "",
	drop_descrip = "Phew... This is... Comrade Commander? Fancy meeting you at this time of night. Me? Heh, heheheheh... You wouldn't believe me if I said I got too drunk and went in first, would you?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "(I-I'd better not tell the Commander... that I wandered over to this hot spring alone after Gangut got me drunk! Urk...!)|Voroshilov? Don't worry about her. I don't know if she gets by through grit alone, but she's the kind to never get dizzy in a hot bath.|The joy of getting out of a hot bath? Umm... How about you go first, comrade? Erm, I'm just feeling a little, y'know...",
	touch = "(The wind feels nice... O-oh, right! I need to put on a cool front so the Commander doesn't notice I'm drunk!) ...Achoo?!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 705071,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Aww, you just got here? Hell, I guess I wouldn't mind going back in with you, Comrade Commander...",
	detail = "Come to think of it, when did I even put this on... I-I mean, gotta dress right for a hot spring bath, right?! See? Look, I even tied the sash right!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[705080] = {
	hp_warning = "Things are getting dire... I need to be quick!",
	feeling3 = "...Yes? There is no more than meets the eye to these chains. And don't worry, I don't have a kink for wrapping things up in them.",
	mail = "Time is valuable. I'll sort your letters and you just stay focused on your work.",
	expedition = "Those girls who went out on a commission are back. It's your job to welcome them back, so start getting your things in order.",
	win_mvp = "Every second matters. On to the next fight.",
	home = "You've returned, Comrade Commander. Come, sit down next to me... I'm not asking you, I'm telling you to.",
	unlock = "Mmh. You're Comrade Commander, aren't you? I'm Poltava, Northern Parliament battleship, and I'll be aiding in your work starting today. Since you're the face of this port, I will hold you to a high standard of conduct and etiquette. Hope you're ready♪",
	touch2 = "Heehee... Should I interpret this as a formal invitation?",
	mission = "These incomplete missions are piling up... I won't stand for this. I suggest you stop slacking before I have to discipline you.",
	vote = "拉票描述",
	drop_descrip = "Gangut-class battleship – Poltava.",
	feeling4 = "I tie my bagage down tightly because I don't want it collapsing. Same with my furniture and ornaments so they don't fall. I want them to be stable... You don't get it? That's fine, heehee. You'll know what I mean when trouble befalls you.",
	lose = "Even in defeat, you should have order in mind as you retreat. Because if you don't... Heehee♪",
	feeling1 = "Heehee... It seems I must take firmer measures to discipline you.",
	skill = "Yield to my chains!",
	upgrade = "My chains are even stronger now. How lovely♪",
	propose = "Oh my... This is a statement, saying you want to be together forever. And if you're giving it to me, you must be ready to forever be connected. Heehee. Whatever comes next, we'll get through it together... sweetheart♡",
	feeling5 = "Heehee, you've figured it out, my smart comrade. Love is a kind of chain. A chain that wraps around us both. A chain that links and keeps us together when the world wants to separate us.",
	main = "Manners aren't things you do to appear cultured, they're a mindset of paying attention even to the littlest things. Yes, it's about whether you have an eye for details or not. Remember that.|Sometimes you need to be strict to get a person to take something in earnest. What are your thoughts on that, Comrade Commander?|How time flies... Why don't we have dinner together? Heehee. Oh, and do try not to drink too much.",
	touch = "Curious about my rigging, are you? Heehee, it may look rough on the outside, but it's sophisticated and industrial on the inside.",
	voice_key_2 = -1,
	mission_complete = "You've completed every last mission? How excellent. Your pluck and focus bring a throbbing to my heart♪",
	battle = "Follow orders and neutralize them in order!",
	id = 705080,
	gift_dislike = "",
	gift_prefer = "How sweet of you. I accept.",
	profile = "I'm Poltava, Gangut-class battleship of the Northern Parliament. While Gangut herself may be more famous, my abilities will not disappoint you. Got a work issue, a personal issue, or any issue at all? Just come to me!",
	voice_key = 70508,
	headtouch = "My, how assertive. I like it♪",
	feeling2 = "A single nail was misplaced, and thus a war was lost. What I'm telling you is not merely a fun story, Comrade Commander.",
	login = "Someone still looks sleepy. You need to shape up... or I'll be displeased. Heehee♪",
	detail = "Making problems disappear is what I do best. From requests that came out of the blue, to brutes who have no manners... Think of it as a part of learning, heehee.",
	couple_encourage = {
		{
			{
				70501
			},
			1,
			"After this is over, wanna go for a drink?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[705081] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Heehee. Another huge and historic victory for Queen Poltava.",
	home = "Thanks for setting up all the props, Comrade Commander. Now... how about a nice full-body massage from Queen Poltava?",
	unlock = "Heehee... Oh, are you ready for your audience with me? Remember the important thing – minding your manners. Queen Poltava's time is very, very precious indeed.",
	touch2 = "Heehee... I might have to add an improv scene♥",
	mission = "",
	vote = "拉票描述",
	drop_descrip = "Heehee... Oh, are you ready for your audience with me? Remember the important thing – minding your manners. Queen Poltava's time is very, very precious indeed.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "\"You don't treat me as a friend and you refuse to call me 'Queen'\"... What an impactful line.|If you want to strike a deal, come up with a reason I can't refuse. Heehee, my character is quite the arrogant one.|So, who is playing my rival? ...Sovetsky Soyuz? Heehee. Her, against a mafia queen... They gave her quite the important role.",
	touch = "Heehee. A drink, Comrade Commander? The glass may be a prop, but the liquor is the real deal.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Oh my, the oranges are in the frame with you.",
	id = 705081,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Heehee. Great timing, Comrade Commander. I got my hands on the script for the next scene. Want to go through it with me?",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[705090] = {
	hp_warning = "This is nothing... I can take it for the Commander's sake!",
	feeling3 = "Could you tell me who made the tea on your desk? The teacup has a gorgeous design, sure, but I want you to drink MY tea. I know better than anyone else the kind of warmth you like... Oh, forgive me – did I cross a line there?",
	mail = "Commander, a letter came in. Will you read it after a quick rest? I'll leave it here for now, then.",
	expedition = "Commander, let us go and receive the commission team. Hrmh... No, I'm not peevish, I just want to look after you more.",
	win_mvp = "Heehee. This is naturally how powerful my feelings for you are, Commander.",
	home = "Ah, welcome back. Get some rest... is what I would say, but first I need to check your forehead temp. Heehee, don't be embarrassed, it's just some family bonding.",
	unlock = "I'm Kazan of the Northern Parliament, here to serve you. My job from now on is to make you snug and cozy – indeed, that's the sole thing I live for.",
	touch2 = "Hm? Are you feeling cold? ...Okay, then come into my arms.",
	mission = "Hmm... While I don't want to burden you too much, you do need to finish your missions. Heehee... Would you like me to help reformulate your plans?",
	vote = "",
	drop_descrip = "Type 21 battleship – Kazan.",
	feeling4 = "Once in a while, I wonder if I should let you be more independent... then every time I see how tired you look, I can't help but feel like I need to be there to protect you. Do you know what that's like?",
	lose = "Retreat right away... I have your back.",
	feeling1 = "I'm disappointed in you, Commander. Not because you did anything wrong, but because you don't understand that you need my warmth... This needs to change.",
	skill = "Don't you dare take one step further.",
	upgrade = "Nicely done, Commander. I'll get you a hot treat as a reward.",
	propose = "I see... You love me just as I love you, and you want to protect me. I understand. From this day on, I'll do more than just protect you – I will support and warm you as your partner, and you'll do the same for me. What do you say we build a loving, warm family together?",
	feeling5 = "Over time, my desire to protect you changed and gave birth to a new kind of emotion... Be that as it may, I still want to protect you and keep you warm. That, to me, is the peak of happiness.",
	main = "Commander, you should use my blanket if it gets cold at night. It's incredibly soft, and if you wrap yourself up in it, it'll feel like I'm giving you a big hug. Heehee.|You slept soundly last night, didn't you, Commander? Oh, how did I know, you ask? Because I went to check on you. You looked so at ease – you must've been having a wonderful dream.|I made some hot milk for you to warm yourself up with. Whew... Let me check the temp before you drink it... Hm? You're not a kid? Heheh, well, in my eyes, you'll always be a sweet little child... Here you are – enjoy!",
	touch = "I'll warm your hands for you.",
	voice_key_2 = -1,
	mission_complete = "Commander, you have yet to claim your mission rewards. They're all the recompense of your hard work. Heehee.",
	battle = "Let's begin. I won't any danger come even close to the Commander.",
	id = 705090,
	gift_dislike = "",
	gift_prefer = "Ah... You remembered what I like. Hehe, I just want to hug both you and your gift really tight~",
	profile = "I'm Kazan, shipgirl of the Northern Parliament. I have cozy blankets and warm tea or hot milk all ready for you. Stay by my side forever, and I'll protect you from threats and the cold alike. For you see, that is my duty and my desire.",
	voice_key = 70509,
	headtouch = "Ahh... It's my job to look after you, and yet you're so kind to me... It fills me with joy.",
	feeling2 = "Doesn't look like you've accepted my tender care yet... Don't worry, everything I do is for your sake. In cold lands such as these, warmth is the one thing everyone needs the most.",
	login = "Ah, Commander. How was the weather outside? If you're chilly, I can make tea and hot chocolate for– Hm? You'd prefer vodka? Well, if that's what you want, alright.",
	detail = "Sometimes, I worry that I'm a bit too involved with your day-to-day life. From managing your meals, to your sleep schedule, and even your room's temperature... it's all because you mean a lot to me. I just don't want to overstep my boundaries or come across like a... guardian.",
	couple_encourage = {
		{
			{
				70701
			},
			1,
			" You can't go on being such a klutz.",
			0
		},
		{
			{
				70501
			},
			1,
			" Do NOT do anything that might endanger the Commander.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[705091] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Excellent work, Commander. Does the nice smell of breakfast help you relax? Maybe you want something to drink?",
	unlock = "Ah, you're up, Commander. Heehee. Good morning. It's so sunny today that even the kitchen is a bit hot. That's okay, though – I've made a refreshing breakfast for you. Go wash your face, then it's time to dig in.",
	touch2 = "First thing in the morning? Seems you've gotten a bit clingy with me. Heehee.",
	mission = "",
	vote = "",
	drop_descrip = "Ah, you're up, Commander. Heehee. Good morning. It's so sunny today that even the kitchen is a bit hot. That's okay, though – I've made a refreshing breakfast for you. Go wash your face, then it's time to dig in.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Making breakfast for you every morning, feeling the temperature in the kitchen, watching you eat with a smile on your face... This casual happiness is my irreplaceable treasure, the one I've been after for so long.",
	main = "I thought you might be getting tired of just drinking hot milk lately, so I made some coffee this time... What's that? You're suddenly craving milk now?|Let me know if there's anything you want to eat. I'll cook it up for... Hm? That's spoiling you a little too much? Heheh, making food is for granted, I'd say.|Need a hand? Sure, just sit there and wait a minute. I absolutely love taking care of you, so don't sweat it and let me handle it for you.",
	touch = "Oh my... Are you asking me to spoil you by any chance? Heehee.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 705091,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Heheh... It's a little embarrassing, but it does make me really happy.",
	feeling2 = "",
	login = "Here just in time for breakfast... Oh, hang on a second. Let me check your forehead temp... Heheh, no, there's no real reason for it. I just wanted an excuse to come close to you.",
	detail = "Heehee. In truth, I've always wanted to be by your side with a more homely look. For instance, like this... in the kitchen in the morning, welcoming a new day together as family...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[707010] = {
	hp_warning = "The final victory... will be ours!",
	feeling3 = "Commander~ Want some vodka? Oh, you can't drink during work hours, huh... Well, just let me know when you're done here~♪",
	mail = "You've got a letter~ Wouldn't it be nice if your friends are inviting you to do something fun?",
	expedition = "The commission fleet has returned! I'll go take lunchboxes out to them~",
	win_mvp = "Our march forward is unstoppable! We shall endure, no matter what, until the final victory is ours!",
	home = "Commander, thanks for your hard work~ Operation debriefing? Let's leave that for later and have some food with the others first?",
	unlock = "You don't look so good... Have you been eating properly lately? And how about your sleep? Hmm... Maybe it has something to do with emotional stress, or relationship problems? ...Oh. My name's Volga, Volga of the Northern Parliament. Oh my, did I really forget to introduce myself until now?",
	touch2 = "If that's how you feel about me, then... Huh? It was an accident??",
	mission = "We've got new missions, huh? Try to pace yourself and not overdo it, Commander.",
	vote = "",
	drop_descrip = "Project 72-class aircraft carrier – Volga",
	feeling4 = "Hey, why don't you treat yourself to something nice today? Hmm, if I had to pick out a reward for my hardworking Commander... What do you think it'd be? Hehe~",
	lose = "So this is defeat... But, the final victory will eventually be ours!",
	feeling1 = "A nice person doesn't cause trouble for their friends, got it?",
	skill = "Now's the time to give it our all!",
	upgrade = "I'm a REAL aircraft carrier, after all~",
	propose = "I'm here, Commander! What's wrong? ...Huh? Umm, this ring... It's for me? Really? W-won't the other girls be jealous though? ...Ehehe, this makes me so happy, it really does... *sniffles*",
	feeling5 = "So you want me to reward you with a headpat? Sure, I can do that~ Yes, yes, who's a good Commander? Now, come lie down over here~ You can fall right asleep if you want~♪",
	main = "Arkhangelsk, can I bring vodka to the next tea party? Ehh, I can't? Aww...|Hum hum~♪ It's fun thinking about what I want for dinner while cleaning your office~ Oh right, Commander, do you have any recipes you'd like to share with me?|Heh heh~ I might not look it, but I sure pack a punch on the battlefield! ...Huh? The \"might not look it\" part is unnecessary?",
	touch = "I'm coming~ Did you need something from me?",
	voice_key_2 = -1,
	mission_complete = "Owwie... I tripped while bringing the mission rewards over... Commander, would you mind lending me a hand? Ehehe, thank you very much~",
	battle = "I'll do my best to offer air support!",
	id = 707010,
	gift_dislike = "",
	gift_prefer = "A gift for me? Really? Hehe, you're gonna make me blush~",
	profile = "I'm here, I'm here! My introduction, right? I'm Volga, Northern Parliament aircraft carrier. Named after our homeland's life-giving river, I'll do everything I can to support our friends, from sea or sky! Just make sure to be extra nice to me, Commander~♪",
	voice_key = 70701,
	headtouch = "W-wait, I'm supposed to be the big sister here, right? I, I'm sure of it!",
	feeling2 = "You can't have an unhealthy lifestyle, okay? I know you're busy, but nothing is more important than your health.",
	login = "I'll do my best today as well~ Hehe, Commander, that goes for you and the other girls too. Let's all work hard together~♪",
	detail = "In case of an emergency... Um, I mean, you can always rely on me, emergency or not!",
	couple_encourage = {
		{
			{
				7
			},
			3,
			" Let's do our best, everyone~",
			3
		},
		{
			{
				10709,
				10711,
				10714,
				10717,
				10738
			},
			1,
			"Wow, so you're also real carriers...?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[707011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "(*grumble*) You heard something just now? Uh... I'm sure it was just your imagination! Yeah, nothing at all!",
	unlock = "Volga here. I'm currently tracking an important witness. *gurgle* ...Is my stomach rumbling because this AR game requires so much stamina? Ugh, lost track of the witness just now...",
	touch2 = "Ahhhn?! W-wait, now's not a very good time...",
	mission = "",
	vote = "",
	drop_descrip = "Volga here. I'm currently tracking an important witness. *gurgle* ...Is my stomach rumbling because this AR game requires so much stamina? Ugh, lost track of the witness just now...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Belorussiya told me that the bar there serves really good drinks... Oh, yeah, focus, focus!|The time it takes to get from here to the next stakeout point is... Commander, hold on tight!|Kirov should be lying in ambush on the other side... All right, this is where I show you what I'm made of!",
	touch = "Now we wait... Ugh, my cover's been blown... There goes the mission...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 707011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Shh, I'm in the middle of a mission!",
	feeling2 = "",
	login = "Do I turn left or right at this next juncture... Oh, hey there, Commander! If you haven't eaten yet, take this– ...Uhh, oh! Right, I've got to focus!",
	detail = "All right, I've got myself some conclusive evidence this time. Please loop around that way. After that... Oh, before I forget, take this in case you get hungry~",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[718010] = {
	hp_warning = "Do not panic! Focus! Focus!",
	feeling3 = "One person can only do so much alone. I have my comrades to thank for having made it this far. Likewise, Comrade, if you need my assistance, I'm absolutely willing to give it.",
	mail = "You have a new message. Read it, and I'll dispose of the letter aftewards, if it's of a confidential nature. I'll ensure there's no trace left of it.",
	expedition = "So, the commission team has returned. Exactly when the report said they would.",
	win_mvp = "Hahah! Victory is determined not by random chance, but by a cascade of certainties.",
	home = "Huh?! ...Oh, it's just you. You put yourself in great danger by suddenly approaching me from behind. At least call out to me first... Don't be ridiculous! You didn't startle me!",
	unlock = "I'm Kronshtadt, Northern Parliament cruiser. Firepower isn't my only merit – I have many more than that. I'm sure you'll discover them for yourself as we clash with our enemies, Comrade.",
	touch2 = "I will not tolerate you – or anyone else – mistreating me... Stop that, right now!",
	mission = "I've compiled a list of all available missions. Strike them through one by one as you complete them, Comrade.",
	vote = "",
	drop_descrip = "Project 69-class cruiser – Kronshtadt",
	feeling4 = "I have no issue giving something greater than intel to those I consider as trustworthy as you, Comrade. But, by accepting it, you may be inviting danger into your life. Are you prepared for that, hmm?",
	lose = "It's all my fault this happened! Dammit... I apologize for my poor judgment!",
	feeling1 = "If you hope to gain my trust, you're putting in quite a lackluster effort, Comrade.",
	skill = "I've found your weakness!",
	upgrade = "Who could pass on more firepower, am I right?",
	propose = "Oaths and ceremonies? I've no need for such grand wastes of time. We have but one thing to do once you've slid on this ring. Close your eyes, Comrade, and forever memorize what I am about to do!",
	feeling5 = "Our relationship goes beyond mere \"trust,\" as I'm sure you know, Comrade. So, ahem... Allow me to give you something purer, more intense, and unquestionably greater than my trust – my love! ...Wh-why are you laughing?!",
	main = "I left a note on your desk with a summary of all of today's tasks, Comrade. What? You can't read my handwriting? Fine, then I'll read it out for you. Let's see... This says...|Who am I making such frequent calls to, you ask? Be patient – you'll learn in due time.|I never repeat something I've explained before. The more information is repeated, the greater the risk of leaks... Hmm? You didn't catch that? Okay, as I was saying...|Strange... My transceiver isn't working. How am I supposed to contact my comrades now? Screw it, brute force it is... Gah! It burst into smoke!|What's essential during stealth missions is that you leave no trace. What this means is: before you go in, cannons booming, you should first create an even bigger boom to distract from– Huh? That's not how you do it?",
	touch = "If you need my assistance, just come forth and ask for it, Comrade.",
	voice_key_2 = -1,
	mission_complete = "Your efficiency in completing missions is quite admirable, Comrade... Goodness, you completed another just as I said that!",
	battle = "Comrades! We march towards victory, heads held high!",
	id = 718010,
	gift_dislike = "",
	gift_prefer = "Wait, how'd you know what I... I've never told anybody that I wanted this, so if YOU knew, then... Gah! An information leak?!",
	profile = "I'm Kronshtadt of the Project 69 cruiser designation. Bravery alone does not win battles – gathering intel while denying your enemy it does. And, just as your fleet's power is not to be underestimated, neither is mine. Understood?",
	voice_key = 71801,
	headtouch = "Comrade, what are you... \"Returning my efforts with intimacy?\" I, I see... You've quite the straightforward methodology. I'll be doing the same the next time.",
	feeling2 = "So, I did some research into your past before coming here, Comrade... Oh, please. You can infer what I found based on the fact I'm conversing with you right now and addressing you with the word \"Comrade.\"",
	login = "Morning, Comrade. I always warmly welcome one who practices punctuality. Hmm? The workday hasn't begun yet?",
	detail = "My comrades should be contacting me soon. Let me open my– Huh? Don't move! ...Comrade?! Don't you know to knock before you enter? ...You already knocked? Oh. I see...",
	couple_encourage = {
		{
			{
				90401,
				30401,
				30402,
				30403,
				30404,
				40401,
				40402
			},
			1,
			"Your firepower still does not trump mine!",
			0
		},
		{
			{
				70204
			},
			1,
			"Covert missions are my forte!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[718011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Arrest the suspects! Move!",
	home = "",
	unlock = "Listen up, assholes! We have you surrounded! I'm Kronshtadt, squad leader of the Northern Parliament Special Forces! You have only one option: come out with your hands in the air and surrender!",
	touch2 = "Well, well. Time to test how sturdy these handcuffs are... by trying them on you. Heehee...",
	mission = "",
	vote = "",
	drop_descrip = "Listen up, assholes! We have you surrounded! I'm Kronshtadt, squad leader of the Northern Parliament Special Forces! You have only one option: come out with your hands in the air and surrender!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "What's wrong with using indiscreet methods as means to an end? I quite like how much simpler this job is than information warfare.|It was a smart move to set up a barricade. This way, Kirov's squad can catch any suspects that try to flee the scene.|Copy that... Arkhangelsk is on the move. It won't be long before this is over.",
	touch = "You turn the megaphone on with this button. Want to try it, Comrade?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 718011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "The perimeter has been secured, Comrade. Should I brief you on the situation, or do you want to see for yourself?",
	detail = "They've taken Manjuu hostages? God dammit, then we've no other choice... Squad, prepare to storm the building!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[718012] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Eek! G-greeting from behind would've been dangerous, you say? Well, this and that are completely different situations!",
	unlock = "When you said \"special animal costume,\" I was expecting some sort of mascot costume... not whatever this is! B-but don't worry, Comrade Commander! This is no big deal for an agent of the Northern Parliament!",
	touch2 = "I feel a little numb... or a little anxious... *blushes*",
	mission = "",
	vote = "",
	drop_descrip = "When you said \"special animal costume,\" I was expecting some sort of mascot costume... not whatever this is! B-but don't worry, Comrade Commander! This is no big deal for an agent of the Northern Parliament!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "While I do trust you, I just can't keep a cool head in this situation. If I could at least distract myself with... I've got it! Since I can't help but be conscious about this outfit, I might as well lean into it... Comrade Commander, could you assist me?",
	main = "Wh-what? Intelligence work is inherently risky, so if I must dress like this for the job, then that's... Ugh! No, this is way too much!|Of all things, it had to be this animal... Say, Comrade Commander, do you also like to have milk in the morning? ...N-never mind.|\"Why not recommend this outfit to others\"? A good point. If we all wear it, I'll blend in with the crowd compared to... Wait, what?!",
	touch = "Comrade Commander, wh-what are you doing?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 718012,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I-I've been waiting for you, Comrade Commander. Uh, no, this outfit is not meant to tempt you or any such... Look, in short, it's not about that!",
	detail = "Ah, seems it's almost time for my regular check-in with my comrades. Today's message and topic are... Huh. \"Preparing for the Upcoming Event\" and... \"Costume Verification\"?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[801010] = {
	hp_warning = "The outcome... still isn't set in stone!",
	feeling3 = "In order to realize their ideals and ambitions, even family members may part ways and eventually meet each other on the battlefield... It's so tragic...",
	mail = "It feels nice to be celebrated by someone you don't know, doesn't it?",
	expedition = "Why don't you let me handle the next one? I'll get it done the fastest.",
	win_mvp = "You'll find that the speed of the Le Fantasque-class is not easily matched!",
	home = "That was a hard-fought battle, Commander. Would you like to have a cup of tea before you resume work?",
	unlock = "Oh my, Commander, what a pleasure it is to meet you. I am Le Triomphant, an elegant large destroyer from Iris Libre, yours to command. The power of the Le Fantasque-class shall exceed your wildest fantasies.",
	touch2 = "Eek! To think that you're even faster than the Le Fantasque class... you're not one to be taken lightly, Commander.",
	mission = "New missions have been issued.",
	vote = "",
	drop_descrip = "Le Fantasque-class destroyer – Le Triomphant.",
	feeling4 = "Familiarity with hardship and suffering cultivates an appreciation of life and death. At least that's what I think...",
	lose = "Sometimes... things like this can happen as well...",
	feeling1 = "So... I guess this is the kind of person that you are, Commander...",
	skill = "Pour la liberté!",
	upgrade = "I feel strength rippling from my sword and shield... Commander, thank you.",
	propose = "Finally... this day has come at last... Commander, you truly are my fated partner. I, Le Triomphant, willingly offer you my sword, my shield, and my body.",
	feeling5 = "Commander, as long as we're together, I feel like I can easily overcome any adversity... that's what I truly believe.",
	main = "My sword and shield? Oh, they stop feeling heavy after a while. Well, I also am quite strong. |If I was with my sisters at that time... would things have happened differently...?|Whether someone is friend or foe... is not something set in stone.",
	touch = "Commander, you'll be missing out if you treat me and my sisters as regular destroyers.",
	voice_key_2 = -1,
	mission_complete = "Commander, here are the fruits of your labor.",
	battle = "In the name of Iris Libre, let us break their lines!",
	id = 801010,
	gift_dislike = "",
	gift_prefer = "How did you know my favorite? Thank you.",
	profile = "I am Le Triomphant, a Le Fantasque-class Destroyer from Iris Libre. It is an honor to meet you. My sisters and I were in the 8th Light Division before the fateful Battle of Jutland. After that, our paths diverged...",
	voice_key = 80101,
	headtouch = "",
	feeling2 = "Don't you think Noblesse Oblige is an elegant idea?",
	login = "My, I see you've returned? What shall your orders be today? I am ready to accept any assignment - commission or sortie!",
	detail = "If you have any questions, feel free to ask away. I will respond to each one.",
	couple_encourage = {
		{
			{
				20704
			},
			1,
			"Let us bring victory to the Commander!",
			0
		},
		{
			{
				90111
			},
			1,
			"I'm glad we can fight together, my sister!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[801020] = {
	hp_warning = "This fight's not decided yet!",
	feeling3 = "Why do I spend so much time training with the sword? Well, it's true that I don't plan on using it during sorties, but being able to keep myself sharp and in shape is surely an asset on the battlefield!",
	mail = "A letter...? Wonder if someone's challenging you to a duel...",
	expedition = "Commission complete! Next time, let me go as well. I swear I'll do better!",
	win_mvp = "I'm one step closer to becoming a knight!",
	home = "Welcome back, Commander. Don't worry, nothing happened when you were gone.",
	unlock = "I am Forbin, a squire from Iris Libre. I may not match up to the stature of my seniors, but please offer me your guidance!",
	touch2 = "I didn't mean to draw my sword upon someone unarmed... I am very sorry.",
	mission = "Commander, I believe that it is your duty to complete these missions.",
	vote = "",
	drop_descrip = "L'Adroit-class destroyer – Forbin.",
	feeling4 = "Commander, did you know that I've always had two dreams? The first was to become a worthy knight like my seniors. The second was to find someone worthy of swearing fealty to... I never expected that my second dream would come true first~",
	lose = "I swear... to take this defeat to heart!",
	feeling1 = "If the knights found out that I had sworn fealty to a person like you... I don't know if they'd blame me or pity me...",
	skill = "How's this?",
	upgrade = "My odds of victory have improved!",
	propose = "This I do swear - my sword shall be your shield, Commander. In return, please promise to guide me down the correct path... I don't ever want to experience that ever again...!",
	feeling5 = "Commander, please believe in me. The only time someone will be able to hurt you is when the last shell has been spent and I am no longer able to lift my sword.",
	main = "Iron Blood or Royal Navy, I don't care who it is, I just want to learn more about them! |When will I become as strong and cool as the knights? |I don't want my life to end without having accomplished anything... so this time, I'll give it my all!",
	touch = "Commander, did you know that there are many different kinds of swords? For example, there are rapiers, sabres, flamberges, and so on...",
	voice_key_2 = -1,
	mission_complete = "Don't let these mission rewards go to waste, Commander.",
	battle = "All right! I'll surely be able to win in this condition!",
	id = 801020,
	gift_dislike = "",
	gift_prefer = "This is... Wow, thank you so much!",
	profile = "I'm Forbin, a L'Adroit-class destroyer from Iris Libre. For various reasons, I was stuck in port for two years, but after returning to service, I was able to get a lot done and make up for some of that lost time on the battlefield.",
	voice_key = 80102,
	headtouch = "",
	feeling2 = "There are all kinds of amazing people gathered here. There's just so much to learn... Ahh, I've gotta work even harder!",
	login = "Hooo! Haah! Oh, Commander, let's do our warm-up exercises together!",
	detail = "Hooh! Haah! Oh, great timing, Commander! Let's practice some swordplay!",
	couple_encourage = {
		{
			{
				90101
			},
			1,
			"Le Mars, stay in formation!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[801021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "",
	unlock = "It's good to be able to stop and smell the roses every now and then. Um, Commander, would you be able to accompany me a bit longer?",
	touch2 = "Eep! N-next time, I won't hold back!",
	mission = "",
	vote = "",
	drop_descrip = "It's good to be able to stop and smell the roses every now and then. Um, Commander, would you be able to accompany me a bit longer?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "If only this peace could last forever... Nay, as long as we work together, this won't merely be a dream. Right, Commander? Hehe~",
	main = "We don't usually get such fresh apples and tomatoes, so how about a mixed juice? It's good for your health! |No more fighting, no more wars... That's the peace that we're fighting to reclaim. |Commander, I heard that aromatherapy can help you recover from fatigue. Why don't you try growing some flowers?",
	touch = "I know the other knights went out of their way to pick this dress for me... but I'm not used to all the frills and whatnot...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "I hope... I don't get these clothes dirty...",
	id = 801021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "",
	detail = "Would you like some fresh fruit, Commander?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[801022] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Commander, what do you say we have lunch together, if you have time?",
	unlock = "Even though I'm an Iris Libre squire, I'm currently working hard to have a rich student life. Um... maybe this is a bit too laid back?",
	touch2 = "S- such filthy, immoral behavior... You can't do this, Commander!",
	mission = "In study as in war, we must always remember the mission. Isn't that right, Commander?",
	vote = "",
	drop_descrip = "Even though I'm an Iris Libre squire, I'm currently working hard to have a rich student life. Um... maybe this is a bit too laid back?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Commander, have you seen Le Mars? If she's slacking off again, I don't know how she thinks she's going to pass the exam...|Study is much like swordsmanship, you have to take it seriously if you want to improve.|Commander, your collar's all twisted. Hold still, I'll get it— There, that's better!",
	touch = "Aie! The wind! ...Erm!? Commander!? You, you didn't see anything, did you?",
	voice_key_2 = -1,
	mission_complete = "",
