	feeling2 = "",
	login = "",
	detail = "I joined the Kendo Club. I'm thinking it'll be good to hone my swordsmanship skills against my peers and build up my streng— Huh? What do you mean it's a different kind of sword!?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[801023] = {
	hp_warning = "",
	feeling3 = "",
	mail = "A letter... Um, what kind of letter was it...",
