_G.pg.base.ship_skin_words[801033] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Letter, letter, coming thro– Oops! I almost threw your letter!",
	expedition = "Commission complete! You girls must be real tired, so go ahead and take a breather!",
	win_mvp = "",
	home = "Welcome, welcome, back to base! How was that, Commander? Did you like my surprise welcome dance? Heehee♪",
	unlock = "Let's go, let's go! Allons-y! Whew... Heehee, you here to watch me rehearse, Commander? Okay, and how was my performance just now? Did that manage to motivate you?",
	touch2 = "Nooooo! You're gonna make me fall! ...Wait, would you prefer it that way?!",
	mission = "Commander, mission! I'll be cheering you on from here, so go get 'er done!",
	vote = "拉票描述",
	drop_descrip = "Let's go, let's go! Allons-y! Whew... Heehee, you here to watch me rehearse, Commander? Okay, and how was my performance just now? Did that manage to motivate you?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I should be the one rooting for you, yet YOU'VE given ME so much support! ...Huh? But you haven't done anything? Well... Heehee, just you being here fills me with courage! You keep being here for me, and I'll keep doing my best!",
	main = "My cheerleading dance looks great! As it should, 'cause I worked hard on it! ...It's good that I've got so much energy? Heehee, well, yeah!|Ooone, twooo... Whuah, look out, Commander! I didn't hit you, did I? If you're hurting, tell me where so I can kiss the boo-boo! That'll make the pain go away!|Mmmh! I can do this all day! Until I've become a praiseworthy cheerleader, I'll keep at it liiike... this!",
	touch = "Come on, move your body with me! It's bad for your health to sit around all day!",
	voice_key_2 = -1,
	mission_complete = "Mission, mission, cooom-plete! Heehee! Hope you liked that!",
	battle = "",
	id = 801033,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commandeeer! It's a new daaay! Your cheerleader's here to root for you!",
	detail = "This is the best part and you're watching, so I've gotta really put some energy into it! Shipgirls, shipgirls, out at sea! Lead us all to victory!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[801040] = {
	hp_warning = "I refuse to admit defeat so soon! B-but how am I going to win?!",
	feeling3 = "Watch this coin closely, Commander. Left... right... left... right... Yes, you're feeling veeery sleepy... Oh. I suppose my hypnosis didn't quite work on you...",
	mail = "I present to you this mail brought by hand; no levitation spell used. Here you go.",
	expedition = "Our commission teams sure make magic happen.",
	win_mvp = "Hm? We won? I'm happy to know that my efforts led to this victory.",
	home = "Well done, Commander. Would you like a soft drink, rather than a spell, to reinvigorate with?",
	unlock = "I'm the destroyer L'Opiniâtre, a so-called \"magician\" from Iris Libre. It's a pleasure meeting you. Umm, actually, please forget the \"magician\" part.",
	touch2 = "Please stay where you are. I must go look for a spell that'll turn you into a rabbit.",
	mission = "Do I have a spell that automatically completes missions...? Sadly, I don't. Please do your best, Commander~",
	vote = "",
	drop_descrip = "Le Hardi-class destroyer – L'Opiniâtre.",
	feeling4 = "Please give me your hand, Commander. Okay, now put it over mine, like this... Wait, why isn't this working? The book said I'd be able to see into your mind if I do this...",
	lose = "If only I had a spell that could protect us all...!",
	feeling1 = "I wonder if there's a chant that'll turn you invisible...",
	skill = "Attaque!",
	upgrade = "It would be nice to have a spell that does my training on my behalf.",
	propose = "I had never even dreamed of partaking in a ceremony as sacred as this... Commander, I promise to treasure this feeling and remain beside you, forever and ever.",
	feeling5 = "You know, I always get so worked-up and feel my heart race just by being near you, Commander... Have you cast a sort of spell on me?",
	main = "Let me tell you... Miss Dunkerque's sweets are truly magical.|Poke. Hm? Oh, don't mind me. I just got a sudden urge to poke you with my wand. Pokey-poke.|If someone told you they'd grant you one wish, what would you ask for, Commander?",
	touch = "Feeling tired, Commander? Then would you like me to cast an awakening \"spell\" over your head with my wand?",
	voice_key_2 = -1,
	mission_complete = "I wonder if there's a way to increase our mission rewards...",
	battle = "Keep it together, me! I can pull through with just my own powers...!",
	id = 801040,
	gift_dislike = "",
	gift_prefer = "Wow. Are you a mind-reader, Commander?",
	profile = "I saw many things during the war, though my construction never finished. But now I get to lead a new life as a part of this fleet... This is a gift from the magic realm... or rather, a gift from destiny.",
	voice_key = 80104,
	headtouch = "",
	feeling2 = "Do you believe in magic, Commander?",
	login = "I knew you'd be back right about now, Commander. Hm? Oh, well... I made that prediction based on your day-to-day activity.",
	detail = "This book lists hundreds upon hundreds of powerful spells... In my imagination, that is. It's just a regular old book of fairy-tales. No, really, that's all.",
	couple_encourage = {
		{
			{
				80103
			},
			1,
			"You're overextending yourself, Tem!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[801041] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Everyone was saying how they wanted to head to the beach because of how hot it is, but it doesn't seem any cooler out here... Ugh...",
	unlock = "It is said that the summertime sea holds an extraordinary enchantment over people... but the only supernatural thing I'm feeling is this accursed heat... Am I missing something?",
	touch2 = "Do you want to be turned into a starfish?",
	mission = "",
	vote = "",
	drop_descrip = "It is said that the summertime sea holds an extraordinary enchantment over people... but the only supernatural thing I'm feeling is this accursed heat... Am I missing something?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "If only there was a spell to make it cool down... maybe something to blot out the sun? Hehe, just kidding. A cold drink will suffice. Commander, what would you like? |The sheer number of people gathered here... is this the mystical allure of the summertime beach? |Commander, have you seen Temeraire? ...She's playing beach volleyball with the others? Hehe, I see she's as full of energy as ever.",
	touch = "Commander... you didn't get heatstroke, did you?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 801041,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Jeez, how'd my glasses end up in the sand... Um, where's my handkerchief... ah, there it is! Oh, Commander, when did you get here?",
	detail = "It is undignified to stare so much at a maiden's swimsuit. B-besides, it's really embarrassing...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[801050] = {
	hp_warning = "Now watch as Peureux retaliates!",
	feeling3 = "Why do you always conduct yourself so casually around me? You should bow before me. Yes, that's it. Lower. There we go. Remember: Always look up at me in reverence like this!",
	mail = "A letter's arrived. I sent Peureux out to get it. Why didn't I go, you ask? Well, you know, because I'm just a frail little girl...",
	expedition = "The commission team is back? Okay, let's go, then. I'm willing to try my best when it comes to making new friends.",
	win_mvp = "Mmh, ahh... We won? Didn't even have time to go easy on them.",
	home = "You're back already? You really are the best in the world! Please keep me under your protection.",
	unlock = "I'm Le Hardi, the lead ship of the Le Hardi-class destroyers. I'm nowhere near as big or strong as anyone else, so I'm probably going be reliant on you for all sorts of things... Huh? I just said I'm reliant on you... Aren't you gonna look after me?",
	touch2 = "Eek! I'm so weak that I don't know how I could possibly impede you... Huh? Why'd you stop? Did I not make it clear that you can do as you please?",
	mission = "New missions? Just let Peureux sort them out. You're not gonna leave frail little Hardi all by herself, are you?",
	vote = "",
	drop_descrip = "Le Hardi-class destroyer – Le Hardi.",
	feeling4 = "When things get dangerous, you're the only one I can rely on... Well, I say that, but if it ever gets TRULY dangerous, I will step up to the plate and protect you.",
	lose = "They beat us... Ugh. I had a feeling this was coming.",
	feeling1 = "Commander, did you know? If someone grows too weak, they might vanish one day without a trace.",
	skill = "This is what you get for underestimating me!",
	upgrade = "Becoming stronger just increases the burden on your shoulders...",
	propose = "Whoooa... You're actually using glitzy jewelry to please me! Heehee. Okay, as a special privilege, I will allow you to remain by my side and serve me for many long years to come♪",
	feeling5 = "Gosh, I... Ahem! I'm NOT swooning, and my heart is NOT racing! If you wanna get me to admit such things... you'll need to work much harder!",
	main = "...Everyone loves cute girls. I'm a good example of that – everyone likes me, and we all have fun.|You're so huge that it's annoying, Peureux... People shouldn't be able to see a weapon from a mile away. It affects how they view me... Hey! St-stop eavesdropping!|Um, Commander... I was feeling hungry, so I ate your lunch. You're not gonna punish me, are you? ...You won't? Oh, that's great! Next time you're hungry, I might just whip up something for you.",
	touch = "Eek. You're so mean, Commander. You could have made weak little Hardi trip with just a small touch.",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Whew, I feel like I'm gonna pass out from exhaustion... I hope you'll reward me well for this, Commander...",
	battle = "Eek, oh nooo, I'm so scared.",
	id = 801050,
	gift_dislike = "",
	gift_prefer = "You've made me happy. Keep on doing that, okay...?",
	profile = "I'm Le Hardi, lead ship of the Iris Orthodoxy's Le Hardi class of destroyers. As you see, I'm just a regular, frail little girl... Oh, and this is Peureux, my weapon. I know it looks imposing, but I'm not lying when I say I'm weak.",
	voice_key = 80105,
	headtouch = "Mmh... I'll permit you to touch me a little longer. That's how I reward subservience.",
	feeling2 = "Why are you looking at me like that? It's scaring me and making me feel faint... \"Just looking a normal amount\"? There's no way it's \"normal.\" I look irresistibly cute when I'm weak.",
	login = "It's such a pain for me to walk. Commander, can you carry me? ...I mean, I'll give you a loving hug in return, obviously? And don't say you \"don't need it.\"",
	detail = "I suppose I'm so weak that you simply can't leave me be. Fine – I'll permit you to attend to me for a short while.",
	couple_encourage = {
		{
			{
				90501
			},
			1,
			" If you need help, just say the word.",
			0
		},
		{
			{
				90106
			},
			1,
			" Bleh... I'll never reach that level...",
			0
		}
	}
}


_G.pg.base.ship_skin_words[801051] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Commaaandeeer! Are you back to protect me and my precious milk?",
	unlock = "Gulp, gulp... Ahh! That hits the spot! Cold and refreshing... There's nothing in the world like a glass of cold milk after steaming in the sauna.",
	touch2 = "If you go any further, I really will start screaming, \"Help! Heeelp!\"",
	mission = "",
	vote = "",
	drop_descrip = "Gulp, gulp... Ahh! That hits the spot! Cold and refreshing... There's nothing in the world like a glass of cold milk after steaming in the sauna.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "When... did you stand up? You haven't been peeking at my chest, have– You haven't? O-okay, then come closer... That's it. Heehee. This is my favorite kind of... scenario♪",
	main = "Wheeew, I'm so sweaty... Hey, don't I look even weaker than usual when I'm drenched in sweat?|Heheh! Surpriiise! Did I spook you? ...Hm? That's odd... We both left at the same time, so how come you're so dry? Rub, rub♪|I'm so sticky... Is it because of all the sweat? Ugh, it's even dripping off of me... Why don't we take a shower together afterwards?",
	touch = "Want some of my milk? ...Oh, you were just trying to wipe off some that I spilled? Oh nooo! Look away, look away! Don't look!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 801051,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "My hair's so wet and heavy... Mind holding it for me, Commander? I need to dry it after I'm done with this milk. Heehee, yes, like that. This way, I can go slow and savor the taste♪",
	feeling2 = "",
	login = "Ahhh... Feels like my head's about to start fuming... Commander. Hey, Commander! Could you bring me some cold milk? Yeah, I want all of it!",
	detail = "Bweeeh... I used the sauna for so long that I can't stand up... Sorry, but I can't do anything unless you hold me♪",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[801060] = {
	hp_warning = "I'm too hungryyy!",
	feeling3 = "Watch closely, Commander~ Hmmm... Haah! Pretty good swordplay, huh? If you wanna eat well and fast, you need swordsmanship and passion!",
	mail = "Mail caaall! Let's see if it's good news, Commander!",
	expedition = "Everyone just got back! I've got meat on the barbecue, so bring them over for a big meal!",
	win_mvp = "We won! Let's celebrate with a feast – I'll do the grilling!",
	home = "Welcome hooome! I grilled meat for you, so hurry up and eat... Oooh, that smells good. Can I have some? Just a bite...",
	unlock = "Meat's done! *blow*... *munch*... Hmm? Oh, Commander, hello! My name is L'Intrépide, and I'm with the Iris Libre... Huh? You want more details? Mm... Can it wait until I finish this?",
	touch2 = "Whoa! You're so forward, Commander... Not that I mind!",
	mission = "Ah! Commander, you have new missions to do. If we do them together, we'll be done before dinnertime!",
	vote = "",
	drop_descrip = "Le Hardi-class destroyer – L'Intrépide.",
	feeling4 = "*blooow*... Perfect! Open up, Commander. I've been watching this meat closely, so it should be cooked just right! Did it taste good? Hehe, glad to hear it.",
	lose = "*sigh*... I'm sooo hungry. Can we cook the baddies, you think?",
	feeling1 = "Sorry... There isn't any meat left for you.",
	skill = "Let's roast 'em!",
	upgrade = "Phew... I cooked and ate a lot~ Now I'm satisfied.",
	propose = "Wait... This is a ring! Huh? Wha? Whaaaat?! For ME?! Yes, of course! I'd be happy to! I'll cherish you for the rest of my life, Commander!",
	feeling5 = "You smell really good lately, Commander... Am I just imagining it? *sniff sniff*... Mmm... Huh? No, I'm not gonna eat you!",
	main = "Alright, the pineapple barbecue is almost ready~ Hm? You think eating barbecue every day is bad for my nutritional balance? Don't worry – I eat different side dishes every time!|Commander, have you seen my ribbon? I thought I brought it... Oh! It's already on my head! Hahaha!|Phew... I ate a ton... Commander? Why are you looking at... Oh! Did I accidentally eat yours?! Sorry! I'll make it up with double... no, TRIPLE for you!",
	touch = "Whoa! Commander! You scared me...",
	voice_key_2 = -1,
	mission_complete = "Everything finished on time! You're amazing, Commander!",
	battle = "Let's go carve us some meat!",
	id = 801060,
	gift_dislike = "",
	gift_prefer = "I LOVE it! Thank you so much, Commander!",
	profile = "Report! Iris Libre destroyer L'Intrépide is here and full of energy! Whether it's cooking, eating, OR fighting, you can leave it all to me!",
	voice_key = 80106,
	headtouch = "Ooh... The moment you gave me headpats, my tummy started rumbling. Is that magic?",
	feeling2 = "Eating meat together is the first step to becoming fast friends. Get over here and eat with me, Commander!",
	login = "Welcome back, Commander! I tried roasting meat with a new blend of spices. Come and give it a taste. Can't work on an empty tummy!",
	detail = "Hmm? You wanna know about my barbecue magic? Or... are you waiting for the food to be ready? Aww, you don't have to be shy~ Come and eat before it gets cold!",
	couple_encourage = {
		{
			{
				80104
			},
			1,
			" Here we go! Chaaarge!",
			0
		},
		{
			{
				30114
			},
			1,
			" Barbecue? Barbecue, barbecue!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[801061] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Commander, you're back just in time for the opening act! There will be owls performing today. You'd better find a seat so you don't miss the action!",
	unlock = "Heheh, here comes the grand finale! Watch in amazement as I snatch the meat from that ring of fire and put the finishing touch to tonight's feast! Don't blink, Commander!",
	touch2 = "Whoa! You really like this spot, don't you?",
	mission = "",
	vote = "",
	drop_descrip = "Heheh, here comes the grand finale! Watch in amazement as I snatch the meat from that ring of fire and put the finishing touch to tonight's feast! Don't blink, Commander!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Give me a hug, Commander! Why now? Because I want you to feel my burning passion, of course. Are you ready? Here I cooome!",
	main = "Commander, come closer~ Just a little more... Hah, got you! Can you feel my sizzling passion and energy?|That was the BEST! I had so much fun... Let's do it again! Join me, Commander!|Success! We've got medium grilled meat! See how the inside is still a vibrant red? Do you wanna eat it as-is, or would you like to try my special black pepper spice blend?",
	touch = "Heheh, don't get burned by the heat of my passion!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 801061,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Good morning, Commander. You're looking great today! Wanna try out this super-fun fiery trail with me? Don't worry – if you keep up with me, you won't get hurt at all... I think! Hehehe!",
	detail = "Did you like my fiery dance just now? If you still want more... I'll use my barbecue magic to set the whole stage on fire for you!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[801070] = {
	hp_warning = "The Holy Iris will protect us!",
	feeling3 = "You'd like to have a chat? Let's see then... Between life, freedom, and love, which is most important to you, Commander? Hehe, don't be alarmed that I suddenly sprang that question on you. I simply wanted to see how you'd react~",
	mail = "Commander, if you're unable to locate your mail... it's because I've already brought it over here. Heh heh~♪",
	expedition = "Coins, oil, and supplies... I wonder if the rewards for this commission will also be abundant.",
	win_mvp = "Do not deny yourself the pride that you righteously deserve. The path to victory has been paved by God, but it is you who shall lead us down that path, Commander.",
	home = "Here are the materials you've requested, as well as the tea and light meal. Please note that the tea may be a bit hot. Hmm? It's cooled down?",
	unlock = "I am Le Terrible, the elegant large destroyer who protects the teachings of Iris Libre. I have come in pursuit of your ideals. Commander, please show me the reason for which you fight.",
	touch2 = "I do say, Commander, how generous of you to reveal your weaknesses to me one after another~",
	mission = "Commander, have you come across a mission so difficult that it's even making you furrow your brow? ...My my, I see~♪ Ahem, I mean, I would be more than glad to lend my assistance, should you desire it––",
	vote = "",
	drop_descrip = "Le Fantasque-class large destroyer - Le Terrible.",
	feeling4 = "Now then, moving on to the next question. Commander, do you prefer to be bound by someone else, or would you rather be the one doing the binding? Hehe, assume there are no other options~",
	lose = "The warriors of Iris Libre must not falter.",
	feeling1 = "If you wish to make a confession, better to turn to the Cardinal rather than to me.",
	skill = "Bloom forth, hallowed Iris!",
	upgrade = "To claim to be the strongest... is not something that should be stated haphazardly. Don't you agree, Commander?",
	propose = "Sorry to make you buy a ring for me, but I can't deny these feelings any longer–– Heh, heheh... Ahahaha~♪ Yes, with this sacred ritual, no longer will I be teasing you. Indeed, from now on, I pledge myself to you, fully and forever.",
	feeling5 = "If I was to cross the threshold of death's door one day, would you pull me back–– Hmm, I suppose that question's a bit too easy. I'm not trying to toy around with you, I simply wanted to hear how you feel. Heheh~",
	main = "That little incident I had with Le Malin? Yes, I've already apologized to her, but her mind seemed to be on something else...|My, Commander, look at you over there with that derpy face–– Ahem, what I meant was, it's not good to slack off. You should try to learn a thing or two from Le Triomphant.|Those who seek to spread the wings of hope are too often shackled by trivial matters. Commander, do you have the ambition to break your chains?",
	touch = "You may pray to the Holy Iris, or offer me a confession in person. Speak your piece.",
	voice_key_2 = -1,
	mission_complete = "Are you sure you're able to sort out all these rewards yourself, Commander? Heh heh... Perhaps you could look for another person to work with you~?",
	battle = "What is it that you are fighting for?",
	id = 801070,
	gift_dislike = "",
	gift_prefer = "Commander... I'm not worthy of such a gift!",
	profile = "As a part of the 10th Scout Division of the Brest Fleet, I carried out escort missions as well as participated in the withdrawal from Strasbourg. As one who served the Iris Orthodoxy, I was finally shown the light of victory. Ah, how blessed I must be.",
	voice_key = 80107,
	headtouch = "Please refrain from touching my hat.",
	feeling2 = "You're here neither for prayers nor confessions? I see. In that case, I'll also have to find something else to do to pass the time... Hmm, hmm...",
	login = "My, you seem to be in high spirits today, Commander. Do you have any orders for me?",
	detail = "I have no interest in fighting pointless battles, but there seem to be some individuals here who place excessive pride in their speed... Of course, I was more than glad to put them in their place. More importantly, I made quite a few friends in the process. Not too bad, right?",
	couple_encourage = {
		{
			{
				90111
			},
			1,
			" If you keep slacking off... I'll have to inform Le Triomphant~ Heh heh.",
			0
		},
		{
			{
				80101
			},
			1,
			"Let us do battle together, my beloved sister!",
			0
		},
		{
			{
				80501
			},
			1,
			"Your orders, Cardinal?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[801071] = {
	hp_warning = "",
	feeling3 = "Zzzzz",
	mail = "Please remember... to check your mail...",
	expedition = "Our commission went wonderfully... I saw that in my dream...",
	win_mvp = "*Yawn*... I'm still a bit sleepy... I can't even properly savor the aftertaste of victory like this... Zzzzz...",
	home = "Zzzz... Black tea... should be left until it's a bit cooler than room temperature...",
	unlock = "Zzz... Commander...? Sorry... for showing you this unsightly side of mine... I'm just, not a morning person... Zzzzz...",
	touch2 = "Nngh... Mmh...",
	mission = "The missions... We haven't finished them all yet...",
	vote = "",
	drop_descrip = "Zzz... Commander...? Sorry... for showing you this unsightly side of mine... I'm just, not a morning person... Zzzzz...",
	feeling4 = "Zzzzz",
	lose = "I knew it, I'm just not good enough... Unlike some of those Eagle Union destroyers...",
	feeling1 = "Zzzzz",
	skill = "",
	upgrade = "It'd be nice... if I could get stronger after waking up...",
	propose = "",
	feeling5 = "Commander's derpy face... Ehehe... I've always wanted to see this... Just let me rest a while... at your side... Zzzzz...",
	main = "Le Triomphant... You're not the most photogenic sleeper...|Commander... Give me another couple hours... And then...|Nooo, I'm going to get pranked... Ehehe... I won't hold it against you though, so please...",
	touch = "But if you could stop at scribbling on my face... that'd be nice...",
	voice_key_2 = -1,
	mission_complete = "We have mission rewards... waiting for us...",
	battle = "Well then... I guess I'll fight...",
	id = 801071,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "Zzzzz",
	login = "Le Malin... It's time to get to work... Make sure you don't drag the Commander down... Zzzzz...",
	detail = "Le Malin, Le Triomphant... We'll be together forever...... Zzzzz...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[801072] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Commander, if you're talking about the mail, I think Le Malin has it... Hehe~♪",
	expedition = "Oh, it appears the commission fleet has returned.",
	win_mvp = "",
	home = "Splendidly done. Would you like to hold a tea party by the beachside, Commander? Indeed, something with ice would be nice~♪",
	unlock = "How goes your day, Commander? Hehe, are you looking for my clever sister, Le Malin? If so, you would do well to search somewhere less... popular~♪",
	touch2 = "My, oh my~♪",
	mission = "",
	vote = "",
	drop_descrip = "How goes your day, Commander? Hehe, are you looking for my clever sister, Le Malin? If so, you would do well to search somewhere less... popular~♪",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Miss Ark Royal? Hmm, you're asking if she comes across as helpful or troublesome? Perhaps a bit of both, I must say...|The Cardinal plans to go surfing? Commander, I think you should keep an eye on her.|If a big wave comes... Hmm... Uhh... That's probably not going to bode well for me...",
	touch = "If you find it too hot, why not take off another layer~? Hehe~♪",
