_G.pg.base.ship_skin_words[801080] = {
	hp_warning = "I cannot and will not succumb...!",
	feeling3 = "Lord Commander, if you ever feel anxious before a battle, simply put your hands together and pray, like... \"Iris, watch over our souls,\" and you'll be fine!",
	mail = "New mail... The information inside is sure to be of paramount significance!",
	expedition = "The commission team hath returned! Heheh. The rewards would've been greater if you'd entrusted the job to a Templar Knight like me...",
	win_mvp = "There you have it! That was a display of a Templar Knight's might!",
	home = "Exemplary work, Lord Commander! Although I guess it would have been a cakewalk for the Cardinal!",
	unlock = "Destroyer Maillé Brézé, Templar Knight of the Iris Libre, has arrived! Thou there, plebeian, thou may now sleep soundly knowing I'll defend thy lanes! ...What? Y-you're the Lord Commander?! F-f-forgive my grave disrespect just now!",
	touch2 = "Are you that enamored by my sheer magnificence?",
	mission = "What about these unfinished missions? You'd better do them before the Cardinal scoldeth you.",
	vote = "",
	drop_descrip = "Vauquelin-class destroyer – Maillé Brézé.",
	feeling4 = "It's not enough to protect just my Iris comrades. I must fight for all my friends here at port too... Oh, the burden on my shoulders doth grow ever bigger... Cardinal, Lord Commander, how will I carry this weight...?",
	lose = "Th-thou may crush my body, but my spirit will live on...! Wait, that doesn't sound right...",
	feeling1 = "We both have goals to work towards! I'll strive to be a full Templar Knight, and thou should strive to be a half-decent commander!",
	skill = "Feel my holy might!",
	upgrade = "Another step on my journey to full knighthood!",
	propose = "To whom do I deliver this ring, Lord Commander? ...I-it's for me?! You're serious?! I-I accept. I just worried for a bit whether you truly wanted me...",
	feeling5 = "If we share the burden of protecting everyone, then we can manage this feat together! The Cardinal told me that! On my sword, I vow to work harder than ever!",
	main = "Our next battle is important, and I will not neglect my training in preparation for it!|Vauquelin! Thou must eat thy veggies! ...G-green peppers, however... Yes, it's a bad vegetable! Thou may pass on that one!|The Cardinal herself will be spectating our next exercise?! Oh goodness, oh dear... I must practice more!",
	touch = "It won't be long before I'm dubbed a full-fledged Templar Knight!",
	voice_key_2 = -1,
	mission_complete = "Mission complete! It's time to reap the rewards, Lord Commander!",
	battle = "Onwards, girls! Holy is the war that we wage!",
	id = 801080,
	gift_dislike = "",
	gift_prefer = "Oooh! Thank you, Commandeeer!",
	profile = "I am Maillé Brézé, Vauquelin-class destroyer! I am renowned for my ability to escort, patrol, transport, and to fight off submarines! ...Ultimately, though, it didn't save me from sinking... Aww...",
	voice_key = 80108,
	headtouch = "Stunning hair ornament, am I right?",
	feeling2 = "I may still be a way's off from full knighthood, but I would still give my life for our holy crusade! Give me orders, and I will execute them, Lord Commander!",
	login = "Sound the trumpets, for I am here! ...Ah, morning salutations, Lord Commander!",
	detail = "Do you understand, Lord Commander? The Cardinal herself is with us in this war. Therefore, it's a holy war! You should feel honored to be part of it!",
	couple_encourage = {
		{
			{
				90103
			},
			1,
			"On me, Vauquelin!",
			0
		},
		{
			{
				90302
			},
			1,
			"Why, it's you, Algérie!",
			0
		},
		{
			{
				80501
			},
			1,
			" I-it's an unimaginable honor fighting alongside you, Cardinal!",
			0
		},
		{
			{
				90301
			},
			1,
			"Wouldst thou try and take this seriously, Foch?!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[801081] = {
	hp_warning = "",
	feeling3 = "",
	mail = "G-g-go check your mail, right now!",
	expedition = "",
	win_mvp = "S-see?! No monster can scare me as long as I have the Iris' protection!",
	home = "You're back! You're finally back! I was sooooo scared, Lord Commandeeeer...!",
	unlock = "H-h-halt, intruder! Thou art intruding in the domain of an Iris Libre Templar Knight, a crime punishable by... Eek! I'm begging you, spare my life! ...It's you, Lord Commander?!",
	touch2 = "Could you stay here until I fall asleep...?",
	mission = "",
	vote = "",
	drop_descrip = "H-h-halt, intruder! Thou art intruding in the domain of an Iris Libre Templar Knight, a crime punishable by... Eek! I'm begging you, spare my life! ...It's you, Lord Commander?!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Why am I afraid of monsters under the bed...? I-I-I'm not!|Eek! I heard a weird noise coming from outside! I'm sure of it! Help meeee, Lord Commander!|It's times like these when I envy Tartu so much...!",
	touch = "I-I was merely pretending to be spooked!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 801081,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "I can't t-take this anymore!",
	feeling2 = "",
	login = "Wh-what is it, Lord Commander? As you see, I'm simply guarding my room...",
	detail = "Those things in the dark were just... Manjuus? N-n-no, impossible! Those little creatures could never frighten me so!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[801082] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "There is nothing as sweet as a celebratory dessert!",
	home = "Outstanding! You are permitted to treat yourself to my desserts!",
	unlock = "Enjoying sweet pastries in a lovely dress – heehee, such bliss! ...I care not how unbecoming this is of a knight! I saved these desserts for my holiday! Let me enjoy myself, would you!",
	touch2 = "You will have NO desserts if you're going to be like that!",
	mission = "",
	vote = "",
	drop_descrip = "Enjoying sweet pastries in a lovely dress – heehee, such bliss! ...I care not how unbecoming this is of a knight! I saved these desserts for my holiday! Let me enjoy myself, would you!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "This pastry is for thee, Vauquelin! Savor it thoroughly as it's a gift from the Cardinal! Thou must eat it with dignity!|C-Cardinal?! Thank you dearly for these gifts – such lavish treats are much more than I deserve!|I do not have any donuts, Tartu. However, I do have macarons, the next best thing.",
	touch = "You would touch my unarmored body?! A cowardly attack, I say!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 801082,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Won't you join me for teatime, Lord Commander? This is too much to eat alone. I... I am not asking for your help at all! Partake only if you wish! Be grateful for my magnanimity!",
	detail = "It's blissful to have such many desserts just within arm's reach! More blissful yet is that they art a gift from the Cardinal herself! Heheh♪",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[801090] = {
	hp_warning = "Oh no! I went off-key!",
	feeling3 = "Commander! Whew... How's that? Have I gotten more elegant? Heehee! I've been rehearsing SO hard to get to this point!",
	mail = "There's a letter for you! Buuut you can always read it later! Heehee!",
	expedition = "We could welcome back the commission team with a song and dance! What do you say, Commander?",
	win_mvp = "Now you know what makes me so great!",
	home = "Welcome back, Commander! Now have a break. Heehee, you need regular breaks if you wanna deliver your best performance!",
	unlock = "I am the Le Hardi-class destro– Wait, no! Right now, I'm Tem, AKA Le Téméraire, an idol with the unit Cyanidin! Keep your eyes peeled for my debut performance, Commander!",
	touch2 = "Eep! Commander, I've got a concert soon! This isn't the time to mess around!",
	mission = "Commander, you have a new mission! Let me help you with it!",
	vote = "拉票描述",
	drop_descrip = "I am the Le Hardi-class destro– Wait, no! Right now, I'm Tem, AKA Le Téméraire, an idol with the unit Cyanidin! Keep your eyes peeled for my debut performance, Commander!",
	feeling4 = "Commander, are you free today? I don't need a favor from you or anything, I've just been working extra hard on some moves that I wanna surprise you with a demonstration of... Oh no! I gave the surprise away!",
	lose = "Dang it... Back to rehearsals for me...",
	feeling1 = "Commander... Has the stress been getting to you?",
	skill = "Louder, for the audience!",
	upgrade = "My rehearsing has paid off!",
	propose = "Heehee. Honestly, I've wished for this ever since the day I became an idol. In my dreams, you've already put the ring on my finger a thousand times... but now that it's happening for realsies, I'm feeling tense. Could we just... hold hands for ever and ever?",
	feeling5 = "You think I look like a real star up on stage? Heehee, you say that, but if you ask me, the real star here is you! ...When I put it like that, maybe you're actually better suited to be an idol than me!",
	main = "Commandeeer! Heehee! I've got a surprise present for you – a biiig and warm hug! Feeling charged up on energy now?|Ow-ow-ow... Got a leg cramp. This choreography is so tricky... Whoa! Commander, how long have you been here? ...You'll give me a leg massage? Oh yeah... Heehee, I think that's helping a bit!|What's beyond the door? Ahaha! A room where these huge mushrooms grow. Pretty cool, right? Even if it's just stage dressing!",
	touch = "You want to be part of my performance? Yippee!",
	voice_key_2 = -1,
	mission_complete = "Mission complete, Commander! The rewards have been claimed, so let's go have fun!",
	battle = "The concert's starting!",
	id = 801090,
	gift_dislike = "",
	gift_prefer = "Is this for me...? Yay♪",
	profile = "I'm Le Téméraire of the Le Hardi class! Just you wait – I'm gonna give you the best, most elegant performance you'll ever see from Cyanidin!",
	voice_key = 80109,
	headtouch = "",
	feeling2 = "Commander, my concert is just around the corner! It's gonna be amazing and elegant and you don't wanna miss it!",
	login = "I'm gonna try to be the best idol I can every day!",
	detail = "I've been working on a new dance the whole day... Tired, you ask? Heehee, I can take it if it means putting on a great concert for you!",
	couple_encourage = {
		{
			{
				30408
			},
			1,
			" I've got your back!",
			0
		},
		{
			{
				10232
			},
			1,
			" Let's up the tempo a bit!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[802010] = {
	hp_warning = "It seems I'm not in pace with the battlefield...",
	feeling3 = "Because we focus on the details, we can see the beauty of everyday things. I believe a true romanticist values even the smallest of life's beautiful things.",
	mail = "Commander, here's your mail♪",
	expedition = "Commander, look towards the harbor! The commission team has returned.",
	win_mvp = "Merci pour tout~ Thank you for your time♪",
	home = "Commander, if you feel tired then some rest would do you good. Taking breaks is important.",
	unlock = "Bonjour~ I'm Émile Bertin of Iris Libre. You can just call me Émile~ I want to make friends with everyone here~",
	touch2 = "Commander, if you're asking me for a dance, you need to do it more courteously~!",
	mission = "We've been relayed new missions? Then let's get them all done at once♪",
	vote = "",
	drop_descrip = "Light cruiser – Émile Bertin.",
	feeling4 = "Dancing when one wants to – that is what's known as the courage to express one's love of life. Commander, I believe a romanticist must sometimes show courage and express their feelings in some way. Like this– *Kiss*... What do you believe, Commander?",
	lose = "Oh, dear... Perhaps I left my guard too low.",
	feeling1 = "I can't feel any passion coming from you, Commander...",
	skill = "Let us dance!",
	upgrade = "Ohoh, my steps feel lighter now~",
	propose = "I want to express my feelings in this joyous moment through a dance and a kiss... Commander, could you indulge me?",
	feeling5 = "The gorgeous radiance of yesterday, the heart-throbbing excitement of today, the overflowing hopes of tomorrow! Every day is so wonderful! Each passing day, my love for you grows even stronger!",
	main = "The Land of Gold – the Sakura Empire! Fantastique! I do hope to see it one day!|Compared to those 2 years at Fort-de-France... it's wonderful to be able to dance freely beneath the blue sky~|Commander, is there anything I can help you with? Whatever it is, I'd love to.",
	touch = "Are you worn out, Commander? Shall I perform my energizing dance for you?",
	voice_key_2 = -1,
	mission_complete = "Oh, was that the commission complete notification? You should give it a look, Commander.",
	battle = "Allow me to have this dance~",
	id = 802010,
	gift_dislike = "",
	gift_prefer = "Merci~ I love it!",
	profile = "I'm Émile Bertin of Iris Libre~ In days of old, I worked hard laying mines... and leading destroyers. I also transported gold, took part in Operation Dragoon, and participated in a few other missions, so you could say I got through the war unscathed... I suppose?",
	voice_key = 80201,
	headtouch = "",
	feeling2 = "I often hear people say that we of Iris Libre are romantics, but the way I see it, we simply focus on life's little details.",
	login = "Bonjour~ Commander, before we get to work, I say we do some stretches~",
	detail = "I love dancing because it brings joy to people♪",
	couple_encourage = {}
}


