_G.pg.base.ship_skin_words[802040] = {
	hp_warning = "Trying to steal from me? You're in for it now!",
	feeling3 = "Hmm? Why do I take things instead of just purifying them? Well, impure items must be kept safe to minimize their negative effects. You do understand what I mean, yes?",
	mail = "There's mail for you. Please read it yourself – I'll see if there's anything I can swipe... er, I mean, purify.",
	expedition = "Our friends are back with many spoils. I wonder what treasures they've brought... Heehee. Don't disappoint me, now!",
	win_mvp = "Haha♪ What a beautiful harvest!",
	home = "Welcome back, Commander. Stand there a moment... There. I've used my gaze to purify you. Now that my job is done, I'll gladly take my share of the rewards.",
	unlock = "By the guidance of the Holy Iris, Duguay-Trouin has come to serve. Do you seek sacred protection? I already know the answer to that. The devil's essence resides in your epaulet – shall I begin by purifying it?",
	touch2 = "Oh, Commander, you're so bold today... You'd better come close and give me a good confessional...",
	mission = "This mission is sure to yield precious goodies! Let's do it! Now!",
	vote = "",
	drop_descrip = "Duguay-Trouin-class light cruiser – Duguay-Trouin.",
	feeling4 = "Commander, I've finished purifying this batch. See if any of it is yours... Oh, all of it was? What a funny coincidence! Look at me, being all helpful and kind. Go on – take it. Don't forget to reward me for my efforts, though!",
	lose = "Aaargh! That wasn't just a loss – it was a downright disgrace! God ****ing dammit, everything's ****ed!",
	feeling1 = "Boooring. You don't have ANYTHING good?",
	skill = "If I just kill you, the treasure will be all mine!",
	upgrade = "OOOH, HOT DAMN! This power feels too ****ing good!",
	propose = "To think that I would be the one giving up my valuables... Heehee... My heart may be yours now, but I'm not satisfied yet. I'll take your heart and body alike... Prepare yourself, Commander♥",
	feeling5 = "Commander? You haven't listened to my prayers for a long time... Why, I think it's been a whole day at least! I'm so very lonely... Hmm? You'll let me hold you while I pray? Th-then I'll do just that... Okay? U-umm... Right, how does the prayer go, again...",
	main = "Commander, can you start prepaying for your purifications? Hmm? Yes, I purify your things, and you reward me in return – do you have a problem with this arrangement?|The ominous auras that occasionally fill others are warnings from the Holy Iris. You don't need to worry, though – by confessing and handing over your impure goods, you can avoid evil.|Heehee, children are too easy to deceive. Simple wordplay was enough to get me so much treasure... Hmm? Ark Royal is looking for me, you say?",
	touch = "Don't worry about who's around. Be bold with me!",
	voice_key_2 = -1,
	mission_complete = "I just knew you'd come back with valuable loot, Commander. I'll help you identify it right away.",
	battle = "Destroy the devil's army at once! Then, plunder them dry!",
	id = 802040,
	gift_dislike = "",
	gift_prefer = "Heehee. You know exactly what I'm into, Commander!",
	profile = "I am Duguay-Trouin. The Holy Iris guided me to this land in order to take possession of all impure items, and I do mean ALL. Relax, Commander. Hold out your hands and let me purify them now.",
	voice_key = 80204,
	headtouch = "Curious about my treasures, Commander? Heehee, that's right – it's all hidden in my wimple.",
	feeling2 = "Aah... I just can't resist temptation. This must be the devil's influence! Commander, I must have the warehouse key – it demands purification by tomorrow!",
	login = "Long time no see, Commander. I've already helped countless others in need today... Oh, you saw me sneaking into the warehouse? Lies. The devil deceives you... Come to me and repent, before it's too late.",
	detail = "Remember to bring valuables when you come to confess. I'll examine them closely, and if any are impure, I'll gladly relieve you of them.",
	couple_encourage = {
		{
			{
				31201,
				30118
			},
			2,
			" Heehee, I'll be taking your impure wares.",
			0
		},
		{
			{
				90107
			},
			1,
			" Er, you want me to take your cloak? I'll pass, thank you!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[802041] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "We've come this far – there's no need to keep up appearances. Why not... take off that towel?",
	unlock = "Commander, this is where we'll be praying today. Nobody can disturb us here... You already know what to do, I'm sure?",
	touch2 = "Aaah... You want to do this on the shore? We could hide in the water, but you'll do it out in the open instead? Heehee, of course I don't mind...",
	mission = "",
	vote = "",
	drop_descrip = "Commander, this is where we'll be praying today. Nobody can disturb us here... You already know what to do, I'm sure?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "*sigh*... I'm heating up awfully fast. Is it just the hot water, or is it my restraint melting away...? Commander, do you know what predators do when they're at their hungriest? Keep playing dumb, and you might get eaten up...",
	main = "Worried that my wimple will get wet? Then you can take it off for me. This is an important ceremony, so I trust you'll treat it with the gravity it deserves.|Oh, should we warm up before we get in? I thought you only do that before swimming. Or... Are you expecting a bit of roughhousing in the hot spring? Heehee, my, my!|The wind is bitingly cold! Don't you think we should \"warm up\" together in the water?",
	touch = "Oh, are you finally going in with me? Would you like to take me by the hand, or will you carry me instead?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 802041,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "What is it about my hair that attracts you so? Go on, my covetous Commander... Indulge all you want.",
	feeling2 = "",
	login = "Ah, Commander, I can't see anything through this steam! Heehee... If you tried anything right now, I'd have no way to stop you. Getting excited yet?",
	detail = "You'd confess before a naked nun, now of all times? Incredible... You know, Commander, this is a rare opportunity. Don't you think we should be doing something more... special?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[803010] = {
	hp_warning = "A Templar Knight does not tremble!",
	feeling3 = "Assisting with your work, protecting you when a battle breaks out... Yeah, the stuff I can do for you is pretty much the same as anyone else... What can I do to stand out?",
	mail = "You've got a letter. By the Holy Iris, let this be good news... Okay. You can open it now.",
	expedition = "The commission team's back with rewards. Go on and accept 'em, Commander.",
	win_mvp = "See? The Suffren class means business! Ahahah! I'm always happy to assist♪",
	home = "Great work on that sortie! Sit down and have a think about the battle! Your documents are right– Uhh, I... I don't know where they are... Ahaha...",
	unlock = "I'm Suffren, Iris Libre Templar Knight! You can finally rest easy, Commander! There'll be no more problems ever again now that your lady knight in shining armor has arrived!",
	touch2 = "That's weird... Could've sworn I was about the same size as Foch...",
	mission = "Ah, missions... Get 'em done quick, Commander! I don't want you working late into the night; it's bad for you.",
	vote = "",
	drop_descrip = "Suffren-class heavy cruiser – Suffren.",
	feeling4 = "Gimme just a minute, Commander. Your fair and reliable Suffren is gonna cook you a delicious– Oh nooo! I burned the ingredients! And I forgot to turn off my vacuum cleaner! Commander, help!",
	lose = "Commander, it's time for a tactical retreat! We'll get 'em another time!",
	feeling1 = "I don't want to lash out at you, Commander. Get your act together.",
	skill = "Now's your chance if you want to surrender!",
	upgrade = "Thanks, Commander! I'll do my best to live up to your hopes♪",
	propose = "You wanna exchange vows? Perfectly fine by me♪ Heehee~ I get to look after you for the rest of our days, and you can enjoy being spoiled rotten – it's a total win-win! ...Sounds completely focused on you? Well, I love you, so I can't help it!",
	feeling5 = "I'm an elegant Templar Knight and a reliable big sister – it takes more than one little failure to break my spirit! So, Commander, tell me what you need! I want to show you how far I've come!",
	main = "*yaaawn*... Mgh... The port on the whole is pretty great, but I wish I could sleep in a hammock rather than a bed... Hmph. I like hammocks more than beds, that's all.|What's nice about being a Templar Knight is how few rules dictate what and when you can eat. You can't fight on an empty stomach, after all.|Commander, know that I'm right here if you need to get something off your chest. You and Iris Libre will always have a friend in me♪",
	touch = "Commander? You got something you wanna tell me?",
	voice_key_2 = -1,
	mission_complete = "Mission rewards have arrived. Hope dinner tonight is gonna be something special♪",
	battle = "Get ready to cross swords with a Templar Knight!",
	id = 803010,
	gift_dislike = "",
	gift_prefer = "Wow! How'd you know I liked this so much? A-am I that easy to read...?",
	profile = "I'm Suffren, the lead ship of my class. There are a few minor differences between me and my sisters, but that doesn't really matter since we're all Suffren-class at the end of the day! Always a pleasure to chat with you, Commander!",
	voice_key = 80301,
	headtouch = "Whuh?! Stop whatever you're doing!",
	feeling2 = "Feels kinda weird that you're looking after me. I mean, I don't hate it or anything... It's just, y'know, I'm usually the one looking after others, since I'm a big sister figure and all.",
	login = "*yaaawn*... Whuh? Commander? W-wow, so you're an early bird! I'm proud of you!",
	detail = "While I'm usually super nice, I've earned the nickname \"Admiral Satan\" from how terrifying I am when I'm ticked off! Like this – grrr! Isn't that scary?",
	couple_encourage = {
		{
			{
				90301
			},
			1,
			" Foch, be careful when you throw that thing!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[803011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission team is back? Let me get changed real– Uhh, my zipper's stuck...",
	win_mvp = "They served us this elegant victory on a platter! Heheh!",
	home = "I know you're not peeping, but this still feels weird... Hey, wait, there's no point in leaving NOW!",
	unlock = "Hm? The door's open! ...Commander? Oh, ahaha... Silly me, I should've put up a card with \"occupied\" on it... Then again, I... I guess I don't mind if you're the one who sees me~",
	touch2 = "C-cut it out, Commander! I can't undress while you're doing that!",
	mission = "",
	vote = "",
	drop_descrip = "Hm? The door's open! ...Commander? Oh, ahaha... Silly me, I should've put up a card with \"occupied\" on it... Then again, I... I guess I don't mind if you're the one who sees me~",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Commander, are you good or bad at sports? Not any one in particular; I mean on the whole. I'm just curious.|Oh, I know. Since you're already here, you should get changed and exercise with me! Then nobody will suspect anything! ...You doubt it?|Dunkerque is an evil woman... She's always making tons of delicious pastries, I tell you! She has no idea how hard I have to fight the urge to eat them! It suuucks!",
	touch = "I'd be lying if I said I don't mind this at least a little... but it's just you, so it's fine! I think so, anyway...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 803011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Hang on, Commander! You can't go out now, or you'll look so suspicious! For now, uhh, you should just lock the door and wait it out in here!",
	detail = "Thoughts, Commander? You don't get to see me in this outfit any day. Heheh. Truth be told, I'm just as fashion-savvy as Foch or Algérie!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[803012] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Commission rewards have arrived? Then let's go speak to theEEEEM! Geesh, I nearly tripped!",
	win_mvp = "I feel a bit different today, don't I? Heh!",
	home = "Oh, Commander! You must be tired after that sortie! You should fetch that wine and steak for me so I... I-I mean so YOU can eat it! I'm not saying I want to, not at all! Probably not...",
	unlock = "Oh, Commander. Were you waiting for little old me? You've gotta take your time sorting out your dress if you wanna look snazzy! Heheh, feast your eyes on this cute little kni– Uhh, how are you supposed to tie this thing?",
	touch2 = "C-Commander?! Y-you know, it's pretty cramped if we both sit here...",
	mission = "",
	vote = "",
	drop_descrip = "Oh, Commander. Were you waiting for little old me? You've gotta take your time sorting out your dress if you wanna look snazzy! Heheh, feast your eyes on this cute little kni– Uhh, how are you supposed to tie this thing?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "You're so cool and reliable, and I need to act all pretty and adorable to match that! Come on, picture it – me, taking you by the hand and leading you to... Wait, what? How come even I can't imagine it anymore?!",
	main = "If I'd known you'd see me in an embarrassing spot like this, I would've asked Foch or someone else for help... I really fumbled this one...|You think I look like something out of a painting? In that case... Heehee♥ How does this look, then? Is that pushing any of your buttons?|Having a few is fine and all, but don't drink TOO much, okay? ...Yeah, partly for the obvious health reasons, but mainly because I don't wanna have to carry you home in this outfit!",
	touch = "Hey, you, Commander! I'm ready to hear what you think about my dress!",
	voice_key_2 = -1,
	mission_complete = "As reward for all your hard work... how about a night together with your charming knight?",
	battle = "",
	id = 803012,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "H-hey! I JUST got it to look good!",
	feeling2 = "",
	login = "C-Commander! Give me a minute! Your knight needs to make herself look pretty for... Dammiiit! Forget it – help me ooout!",
	detail = "If you need to rest, you can come and do it here. Your charming– I mean, your dependable Templar Knight will shield you! ...That's not what you need?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[803020] = {
	hp_warning = "Is this... a trial?!",
	feeling3 = "Do I seem a little too tense? Well, the final battle approaches... Of course I understand what you want to say, Swordbearer. \"Life goes on, and you need to enjoy the present,\" right?",
	mail = "Swordbearer, there's mail... Hm? There's a pink envelope in here...",
	expedition = "The commission is complete. Let us witness our allies' triumphant return together.",
	win_mvp = "And so it ends, in unceremonious silence.",
	home = "Welcome back. The quivering strings have settled – well done.",
	unlock = "My name is Brennus. I am the sword born of oceans of fantasy in order to usher forth change in this world. Now, Swordbearer of prophecy, answer this question of mine – are you prepared for change?",
	touch2 = "...Nh?! P-people like you are just... *blush*",
	mission = "There are missions that require your attention, Swordbearer. Our deeds today serve as the foundation for tomorrow – do not forget that.",
	vote = "拉票描述",
	drop_descrip = "C5-class heavy cruiser – Brennus.",
	feeling4 = "I do feel a sense of fulfillment pushing that rock up that hill, but... You're right. As long as I fight on, the resistance is never truly over.",
	lose = "Urgh... I won't give up...",
	feeling1 = "It seems you'll need to apply yourself before you're ready to bear any sword...",
	skill = "Accept your judgment!",
	upgrade = "The strings have become even more taut.",
	propose = "This is... Of course I know what that is you're holding! Then you're asking me for... Hm? You think I'm attractive when I'm lost in thought? I-I... O-of course, I'd be happy to –Nnh?! A-aaah... You didn't even let me finish my sentence!",
	feeling5 = "I see. As you claimed, the human world is full of fighting spirit, too. Then I accept your invitation – \"amusement parks\" must be bursting with fun, no?",
	main = "The sounds of strings may be intangible, but for me, they are tangible things that can be woven together. Even something as fine and delicate as thread can be used to hurt others.|I can't always be flawless... You do have a point, Swordbearer. Maybe there are times when I should rest, too...|Through the strings' vibrations, nothing becomes something before once again returning to nothing. The world walks atop one vibrating string, ever waiting for the sound of bells...",
	touch = "Hm? You're interested in how I hold my sword? ...Then allow me to play you a verse now.",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Ensure that your reward list contains no errors.",
	battle = "Now, behold my pure wrath.",
	id = 803020,
	gift_dislike = "",
	gift_prefer = "Hmm. I didn't know such fascinating things existed.",
	profile = "I am Brennus, a C5 cruiser designed to protect against a new threat. Swordbearer of prophecy, I will fight on to the end for your sake.",
	voice_key = 80302,
	headtouch = "...Hmm. Is this the stress reduction method you mentioned?",
	feeling2 = "Do you know the trial of Sisyphus? The final battle I look to is the same, pushing a rock up a hill only to see it roll back again. Anxiety-inducing, indeed...",
	login = "How do you do, Swordbearer? What string do you wish to pluck today?",
	detail = "...To be reborn in the material world, one must first remove their fetters. The stage for decisive battle will soon appear. Swordbearer of prophecy, hold your sword tight.",
	couple_encourage = {
		{
			{
				40301,
				40302,
				40303,
				60302,
				60303,
				60306
			},
			1,
			" Fighting side-by-side with former enemies... How interesting.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[803021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome back... What song would you most like to hear now?",
	unlock = "Swordbearer, you've come at the perfect time. I need your help. Hm? What's with that look on your face? You didn't expect it would be a difficult feat to arrange the clothes you requested I wear, did you...?",
	touch2 = "...C-come, then. I'm ready...",
	mission = "",
	vote = "拉票描述",
	drop_descrip = "Swordbearer, you've come at the perfect time. I need your help. Hm? What's with that look on your face? You didn't expect it would be a difficult feat to arrange the clothes you requested I wear, did you...?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "My goal is still far away, so I need a breather now and then... Swordbearer, permit me to hug you and enjoy a dreamy night together with you...",
	main = "The fireworks are being set off so close by, but strangely, it calms the heart. Yes, I feel a state of perfect peace... But of course. You're here, after all.|Wearing the \"Wielder of Twin Swords – Underwater Performance\" makes tuning a more formidable challenge. Making music that moves the heart will prove a difficult task...|Now is the perfect time to confirm the effects of this outfit. Shall I play you a song? The mood is just right...",
	touch = "Hmm? You want to help me because I look like I'm struggling?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 803021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "...Mm. If you want to touch me, wait until after I finish tying, please.",
	feeling2 = "",
	login = "Good evening, Swordbearer. The night is beautiful. Come sit with me, and let's watch the fireworks.",
	detail = "Indeed, I call this outfit \"Wielder of Twin Swords – Underwater Performance.\" ...You think I should just call it a swimsuit? I refuse.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[803022] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Clamorous strings, now as still as water... Welcome back.",
	unlock = "An encounter under the moonlight – the work of fate, or the very laws of their world? Ah, Swordbearer... Those weren't rehearsed lines, but a simple greeting to you.",
	touch2 = "Mm... Y-you didn't tell me there would be ad-libbing...",
	mission = "",
	vote = "",
	drop_descrip = "An encounter under the moonlight – the work of fate, or the very laws of their world? Ah, Swordbearer... Those weren't rehearsed lines, but a simple greeting to you.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "The boundary between reality and fantasy can shift based on one's will. Even with the awareness that this is a fleeting dream, we must savor it until we wake. Swordbearer, my one true love... do you feel the same way?",
	main = "A distant realm, illuminated by moonlight... Though it is very literally a mere stage, there's no limit to what stories may play out with you.|I am accustomed to redefining my existence depending on the role I must play. Umm... In short, I'm an experienced actor.|Existence can only manifest in limited forms in a closed time-space continuum. Swordbearer, you exist as my lover for now, so please act like it.",
	touch = "Is this moon real, or a mere reflection upon the water?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 803022,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "You've done well to come here, Swordbearer. Let us enjoy the moonlight, accompanied by my melody.",
	detail = "If you wish to restore the material world, then your resolve must be firm. The stage is set. Swordbearer who leads the army of salvation, are you prepared to overcome the countless difficulties awaiting you?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[803030] = {
	hp_warning = "Prepare for retreat. I shall guard the rear. Worry not, for this duty is ours to bear.",
	feeling3 = "It is to me a blessing of the highest order to stand shoulder to shoulder with a commander as accomplished as you. I ask for your continuing permission to undertake missions great. I swear that I will not disappoint you.",
	mail = "It appears a new letter has come in. Is it perchance the postcard I sent to you in my journey prior?",
	expedition = "It seems the commission team has returned to us. What heroic tales bring they back with them this time, I wonder?",
	win_mvp = "With your command, nary a soul can impede us.",
	home = "Salutations, Commander. Yes, I'm having fine tea from the port of Casablanca. Its flavor invigorating, it quenches thirst and clears the mind. Help yourself.",
	unlock = "A view so fair and a townscape so welcoming... Ah, apologies. I am Duquesne, Templar Knight. Think of me as a pilgrim who fancies scrumptious food. If you'd ever like to hear about the Mediterranean's culture and geography, come and see me.",
	touch2 = "Commander... Will the scenery unfolding around me... leave an imprint upon your memory? *blushes*...",
	mission = "A new mission, you say? I shall aid you. The diligent execution of plans is my strong suit.",
	vote = "",
	drop_descrip = "Duquesne-class heavy cruiser – Duquesne.",
	feeling4 = "The understanding of what a person needs in the moment is the greatest dish, and one's heartfelt feelings are the greatest seasonings. What flavor do you crave in this moment? I may very well know.",
	lose = "A sword broken still carries more dignity than a cannon rusted.",
	feeling1 = "This place is no more than another stop on my journey. I beg your pardon, for I must go.",
	skill = "Line up! Charge!",
	upgrade = "This power will give peace of mind to my comrades in arms.",
	propose = "I once witnessed during my travels a particular matrimony. Amidst sands unbounded, in a region of cactused forests and the sunset's alluring glow – there, sacred vows were exchanged... This moment that we've arrived at together is the most blessed in all of my life. I have now but one possible place to be – by your side.",
	feeling5 = "Once, my journeys were made alone. I walked beneath the dome blue and circular of a church in a town of pure white; I crossed a field of lavenders dancing purplishly in the wind; I left imprints upon the dusty floor of an old lighthouse symbolizing hope... Now, what I look forward to most is my next journey with you in accompaniment.",
	main = "You've come. I'm presently recreating a dish I savored long ago in a foreign land. Ground beef is added to clarified butter with spices and gently cooked, its flavor most rich when it reaches medium rarity. Would you care for a taste?|Are you familiar with Demera? When I visited the port of Addis Ababa, I witnessed the people setting alight a giant bonfire after nightfall. That moment, when the flames rose and the entire plaza burst in excitement, is ever etched onto my eyelids.|The extent to which I've grown astounds me... Whew... This gauntlet of challenges is precisely the journey I've longed for.",
	touch = "I offer you these photographs. They're of a city I visited whilst touring the Mediterranean. Beautiful, are they not?",
	voice_key_2 = -1,
	mission_complete = "A mission has been completed. Aye. It pleases me to be of service.",
	battle = "We stand at the front lines.",
	id = 803030,
	gift_dislike = "",
	gift_prefer = "I can feel the love you put into this, Commander. Allow me to express my sincere gratitude.",
	profile = "I am Duquesne, Templar Knight. My time spent on the field of battle is likely longer than you suspect. My hobby is to roam in search of sceneries new and specialties local. That should suffice for an introduction. If you thus desire, I shall be your glaive that cuts through the raging waves.",
	voice_key = 80303,
	headtouch = "This is certainly one way to convey one's feelings...",
	feeling2 = "Flattered am I at times that you put this much trust in me... No, it's nothing. Wherever you go, I shall always be in tow.",
	login = "Ah, you've come early. I've laid out the paperwork that requires your attention. Oh, you flatter me. I did only what's expected of an adjutant.",
	detail = "I am packing my luggage for my next journey. Clothing, food, coinage... Yes, one person's worth. Journeying alone allows one to choose destinations on the spot. It's much more flexible than traveling with a caravan.",
	couple_encourage = {
		{
			{
				10713
			},
			1,
			" An adventure? My apologies, but I prefer my food cooked.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[803031] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "You're back, Commander. This place, I believe, is a worthy reward for your labor.",
	unlock = "This wine bath mustn't be wasted. One must strip off their clothes and submerge themselves deeply in this rich bath of life. Be not so reserved, Commander, just... Huh?! N-no, I would never peek whilst you got changed!",
	touch2 = "If you're thirsty, Commander, then I offer myself. Drink of me until you're quenched.",
	mission = "",
	vote = "",
	drop_descrip = "This wine bath mustn't be wasted. One must strip off their clothes and submerge themselves deeply in this rich bath of life. Be not so reserved, Commander, just... Huh?! N-no, I would never peek whilst you got changed!",
	feeling4 = "",
	lose = "Wine that has turned sour deserves not to be drunk...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Grapes are picked, crushed, and fermented, thus sublimating the sweetness into a rich wine aroma. After a lengthy period spent growing closer, the fruit most precious may be harvested. It's just like our relationship...",
	main = "Mmgh... Basking in your gaze invokes strangely a warmth in me... W-would you turn around if just for a moment? Whew... I all but forgot how to breathe there...|This Cabernet Sauvignon wine seems to be one of the treasures of this place. What a fragrance, so mellow and enticing. Would you care for a taste, Commander?|One, two, three... Why are there three of you, Commander?! P-perhaps... I am already inebrious.",
	touch = "Is the wine getting to you as well, Commander? Ah... Weakness is supplanting strength within my body...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 803031,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Hmm. I feel as though I slightly better understand your thinking now.",
	feeling2 = "",
	login = "This pool of crimson mist – beautiful, is it not? I will wholeheartedly etch into my mind this time we spend together.",
	detail = "A wine bath is not made merely by pouring red wine into hot water – rather, residue from the winemaking process is suitably added so that one will not get drunk so easily. Supposedly.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[804010] = {
	hp_warning = "Ugh... My strength's running out... I need some snacks...",
	feeling3 = "Commander, this one, this, and this – they're all delicious. See? I collected their packaging to show you. Hm? They're already in your drawer? Open it up and let me see... Just a look-see, that's all.",
	mail = "You should give me a hug before you read your letter. It'll turn all the contents into good news.",
	expedition = "Commander, the commission team is back. Their haul of goodies looks really appealing... Yeah, I have a feeling there's some delicious food in there.",
	win_mvp = "Oh. It's over. Did I even do anything?",
	home = "It's you... *growl*... I smell something yummy. Is all that food for me? Wonderful – everything should go perfectly for you today. As long as you stick around me, that is.",
	unlock = "You're the Commander... Uhh, do I have to follow your orders? Okay. I mean, I'll try... By the way, could I have some of those snacks you got in your pocket? They look really yummy.",
	touch2 = "Ahh... Hahh... Will this... bring you good fortune?",
	mission = "You've got missions. If you're not gonna do them, hang out with me.",
	vote = "",
	drop_descrip = "Type 1913 battlecruiser – Masséna.",
	feeling4 = "I've been looking for your missing badge ever since you told me about it. I ate all the snacks I bought with my spare change, and I still couldn't fit it... I don't understand why... Can you hug me, Commander? Because I feel like I've just tasted something gross...",
	lose = "Huh? We lost? There's no way.",
	feeling1 = "Ugh. You don't smell like tasty food anymore...",
	skill = "Blessed be my power!",
	upgrade = "Hmm... You should keep following my gut feelings. Victory comes more easily when you do.",
	propose = "I will give myself to you and protect your future. Your wishes are my wishes, and your commitments are mine as well. When you need me, I'll come running... even if there's a pile of snacks in front of me!",
	feeling5 = "What you want most is to keep winning forever? Then you have to keep hugging me forever. Your biggest wish should come true that way. Hm? You already have what you want most? ...You mean me? Okay... Hey, can I take a small bite out of you? Nom... I love you, Commander...",
	main = "I found loads of coins while at the beach today, so I used them all on snacks and... Oh, right, I also found a button. It's the one you said you lost the other day, right?|Hm? Okay... I see... Whew... I listened to the whole thing. To your battle plan. Can I have the snacks in your pocket now?|Shoot. I won't make it in time for the apple pie... Hm? Are you eating apple pie right now? Nom. I made it in time. Heehee.",
	touch = "What? ...My \"power\" can help you? Then use it as you like!",
	voice_key_2 = -1,
	mission_complete = "You completed a mission. That took you a while. Can we enjoy ourselves now?",
	battle = "Let the battle begin! Victory's all but guaranteed.",
	id = 804010,
	gift_dislike = "",
	gift_prefer = "Thank you, Commander... Can I take a bite now?",
	profile = "I'm Masséna, Iris Orthodoxy battlecruiser... I guess. People say I've been blessed way too much and need to taste what failure's like. It probably tastes bad, so I'm not too keen to experience it. If you hate the taste of failure, too, then I know a way to avoid it – just bring me wherever you go.",
	voice_key = 80401,
	headtouch = "Uhh... Does doing this grant you a blessing? It does feel pretty nice, so it's not like I have a problem with it.",
	feeling2 = "I'll help you fix the things that trouble you. As long as you give me snacks or hang out with me, at least.",
	login = "You're here. I was just getting bored. Are we doing holy tasks again? Why don't we do something fun before that? I think we'll have an easier time after.",
	detail = "Eat yummy food and fight battles you can win. Food that's yucky to you is still somebody else's favorite food. When you end up in a losing battle, there'll be reinforcements coming to help. Hmm... That's me in a nutshell, I guess? If you think this covers me well enough, I can accept that.",
	couple_encourage = {
		{
			{
				50105
			},
			1,
			" Smells good... Can I have a bite? Just one!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[804011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Come here, Commander... I see you brought snacks for me. I'll just dig right in! Nom♪",
	unlock = "Commander, this spring has a sweet taste to it. You should try it.",
	touch2 = "D-don't take away my lucky blessing, or I won't be able to stand up...",
	mission = "Splash, splash... Blub-blub-blub... You got a new mission in the middle of a bath?",
	vote = "",
	drop_descrip = "Commander, this spring has a sweet taste to it. You should try it.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Commander, my face feels so warm, and my heart's racing... but I think we're the same temperature. Heehee. Your heart's racing, too, and your face... looks so yummy. It must taste sweeter than a cherry. Heh. Nom♪",
	main = "My towel doesn't do much if I use it like this, you say? Well, could you adjust it for me?|Just gonna lie on my stomach... Ahh, that's good... I wonder – if my body turns as soft as a marshmallow, will I taste good?|These cherries are sooo sweet. Ahh... Wow, they're so sweet it feels like I'm on a cloud... Hm? And now I've fallen into your arms? Heehee – the water must have made me dizzy.",
	touch = "Your hand feels colder than the water. You should warm it up.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 804011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "This one tuft of hair just won't flatten out, even in the bath.",
	feeling2 = "",
	login = "Ooh... This spring feels so nice. It's a bit too hot, though... Commander, could you fetch me a cold towel?",
	detail = "Come into the water, Commander. It'll sweeten you up and make you delicious, I think.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[805010] = {
	hp_warning = "There is... still hope...!",
	feeling3 = "Commander, please have a seat. What would you like to drink? ...There's no need to be on guard. Even someone like me lives an ordinary life when not on duty or performing religious rites. A person cannot live on faith alone. Sometimes, you just need a drink or two. Hehe.",
	mail = "Letters are blessings from other people.",
	expedition = "I'd like to report that the commissions have been safely completed, and that fleet operations are running smoothly. You've done a good job, Commander.",
	win_mvp = "May the wandering souls drifting about the battlefield find eternal peace and salvation... Amen...",
	home = "Mission complete. The fleet has safely returned to the port. Good work, Commander.",
	unlock = "I am Richelieu, Cardinal of Iris Libre. If you too will fight for freedom and faith, then I shall bring you victory, Commander.",
	touch2 = "If nothing else, your audacity is commendable.",
	mission = "Missions may be called a kind of trial. If you take them on with the proper attitude, there is no need to worry.",
	vote = "",
	drop_descrip = "Richelieu-class battleship – Richelieu.",
	feeling4 = "You've come by again. Haven't you been getting too friendly with me? ...Just kidding. I'm truly grateful to have another person that I can chat casually with. I hope that you feel the same way, too.",
	lose = "Is this... also a trial from Heaven...?",
	feeling1 = "Those who refuse to stop marching shall face the path of ruin... Make sure you keep that in mind.",
	skill = "Accept your divine judgment!",
	upgrade = "At times, might is needed to guide others on the right path. I give you my thanks.",
	propose = "As the one who guides Iris Libre, I cannot make an oath solely to you. However, I vow to protect and support you for as long as I live. This, I vow, on the holy name of Iris...",
	feeling5 = "The feeling of distance between people is an interesting thing indeed. A superior officer and their subordinate. The leader of a fleet and the highest post of the organization. A warship and... Hehe. For the time being, let's let the others continue misunderstanding our relationship, okay?",
	main = "I believe that any obstacle can be overcome with fervent faith and untiring efforts.|Those round little creatures... If I recall correctly, Algérie told me they're called \"Meowfficers.\"|Have I met the Royal Navy yet? Yes. I hope to deepen our bond, so I'm bringing some wine to the next tea party.|Please make use of my precious allies, the Iris Templar Knights, at your discretion. After all, one of their missions is to fight for peace.|The relationship between those from the Eagle Union and those from the Iris Libre is a bit... Well, I get the feeling that Jean Bart would get along with them just fine, though.",
	touch = "Please listen to our prayers closely, Commander.",
	voice_key_2 = -1,
	mission_complete = "The reward for those who work hard is Heaven's grace. Let us accept it gratefully.",
	battle = "All ships, prepare for combat! For liberty and glory! Aux armes, marchons! ",
	id = 805010,
	gift_dislike = "",
	gift_prefer = "This is for ME? Merci beaucoup, hehe.",
	profile = "I am Richelieu, the lead ship of the Richelieu class. During my history as a ship, I lived through good times and bad times, and I also witnessed the rise and fall of my homeland... This time, I hope to protect all that is dear to me up until the end. Together with this fleet, I strive for liberty and peace...",
	voice_key = 80501,
	headtouch = "May Heaven confer upon you its blessings.",
	feeling2 = "The one you are talking to was once despisingly called many things: the calamity that brought on war, the fearsome Cardinal, and the maniac possessed by religious fervor. I ask of you: when you look at me, what do you see in me?",
	login = "Bonjour, Commander. Please relax and drink this tea while I carry out my morning prayers.",
	detail = "Place your faith in me. Follow my lead. Offer up your prayers. Seek the Lord. Only then will the path of God be opened...",
	couple_encourage = {
		{
			{
				80101,
				80102,
				80103,
				80104,
				80201,
				80202,
				80701,
				80801
			},
			5,
			"As long as we have Heaven's divine protection, we have nothing to fear!",
			3
		},
		{
			{
				10703
			},
			1,
			"It seems that we fight together once again.",
			0
		},
		{
			{
				90501
			},
			1,
			"Please fight to your heart's content. I have your back.",
			0
		},
		{
			{
				90101,
				90102,
				90103,
				90111,
				90201,
				90302,
				90401,
				90501
			},
			5,
			"Brethren! Assemble under the banner of righteousness!",
			3
		},
		{
			{
				90201,
				10140
			},
			1,
			"Bring down judgment upon the nonbelievers.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[805011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "We have a really good view from up here. I can even see a commission group starting to return out there.",
	win_mvp = "",
	home = "I don't wish for my absence to become a burden on you, Commander. If there's anything I can help with, please let me know.",
	unlock = "This swimsuit... Yes, the one Émile picked out for me, seems a bit skimpy... I didn't think she'd be the type to trick me into wearing something like this, but... Commander, where are you looking?",
	touch2 = "If you know what's good for you, I wouldn't assume that a girl is defenseless just because she's in a swimsuit.",
	mission = "",
	vote = "",
	drop_descrip = "This swimsuit... Yes, the one Émile picked out for me, seems a bit skimpy... I didn't think she'd be the type to trick me into wearing something like this, but... Commander, where are you looking?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Walking together on the beach like this while basking our ears in the sounds of the sea... Agréable. Hehehe, this is quite a rare experience. Commander ... Thanks for being with me. I'll cherish this moment.",
	main = "Commander, I'll be heading to the beach for a bit. ... Hehe. Indeed, this is a bit different from how I am usually. Would you like to come along with me? | Frozen treats are most effective against hot and humid weather like this... Shall we ask Dunkerque to prepare some more next time? | Jean Bart... Perhaps it's better to spend some more time with her... Sigh... |nil|nil",
	touch = "My... Where are you taking me, Commander?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 805011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Scenery that calms the heart... Commander, you've got good taste.",
	detail = "Iris' teachings do not go as far as to forbid its followers from spreading their wings. Let us enjoy today with everyone to our heart's content. Consider this as yet another of Heaven's many blessings.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[805012] = {
	hp_warning = "",
	feeling3 = "",
	mail = "So this is what the Sakura Empire's New Year's greeting cards look like... How interesting. Hehehe.",
	expedition = "It seems the commissions team made it back safely. This counts as good fortune, doesn't it?",
	win_mvp = "",
	home = "Please calm down and ponder what we should do. I'll be waiting right over here.",
	unlock = "Commander, I wish you a Happy New Year. May you avail yourself of the period of repose that follows the culmination of the year's duties. I pray that you and everyone else may receive the blessing of the Heavens.",
	touch2 = "Is this a greeting... for the New Year?",
	mission = "",
	vote = "",
	drop_descrip = "Commander, I wish you a Happy New Year. May you avail yourself of the period of repose that follows the culmination of the year's duties. I pray that you and everyone else may receive the blessing of the Heavens.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Settle down. Let us pray together. If I listen to your prayers and you listen to mine, you will come to understand that we are heading toward the same goal. Let us walk toward the light. You and I, together...",
	main = "nil|nil|What these fortunes tell may be your fate. Even so, is it not mankind's strength to overcome fate?|Shh. Lower your voice. I'm trying to get this one to warm up to Jean Bart.|Béarn, is it already time? ...Yes, I made a promise earlier to visit the shrine with everyone else. How would you like to come with us?",
	touch = "You'd like to sit by my side? Up we go... Good kitty... Alright, here you go, Commander.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 805012,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "It looks like you went out to take a glimpse of the morning sun. I look forward to being in your company today, Commander.",
	detail = "Believe, atone, and pray. Seek a new day... that you may grasp hold of your happiness, and the road to the light.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[805020] = {
	hp_warning = "Please, give me the strength to overcome this peril!",
	feeling3 = "Rituals and ceremonies often become complex as a direct result of the feelings in them. We know in our hearts that such things are unnecessary, but we can't stop ourselves from trying to show off. Maybe that's just what it means to be human.",
	mail = "You have mail. I pray that it's good news.",
	expedition = "Our fellows who left on a commission have returned. Commander, you confirm the rewards, and I shall thank them for their work.",
	win_mvp = "Please forgive me, merciful Iris, for I need this strength to topple our foes.",
	home = "Our victory is all thanks to divine guidance. Before we look back upon our victory, let us offer a prayer of gratitude.",
	unlock = "May the Iris's absolving light be upon our fleet, and may its solemn judgment find our sinful foes– I, battleship Lyon, hereby rush to your aid, Commander. I pray that the Iris's blessings reach you, wielder of powers unsanctified.",
	touch2 = "What are the motives behind this action? I'd love to know.",
	mission = "Uncompleted missions await you. I think you'd best clean them up quickly.",
	vote = "",
	drop_descrip = "Lyon-class battleship – Lyon.",
	feeling4 = "I admire you as much as anyone else, so I understand the desire to work hard and earn your attention. Hahaha, don't think too much of it. No matter how it ends up happening, I'm certain that your love will come across just fine.",
	lose = "Remain calm and withdraw. Our sacred duty has only just begun.",
	feeling1 = "Do not deviate from the righteous path. If the time comes when I must destroy you, I will show no mercy.",
	skill = "All I do is for the sake of destroying the enemies of the Iris.",
	upgrade = "I'm stronger now. You have my gratitude, Commander.",
	propose = "Now, we must exchange eternal vows in this blessed place and tie our sacred bond with a kiss. Don't be so nervous, now. I'm excited, too, because I get to perform this ceremony for myself for once... Heehee.",
	feeling5 = "Commander, did you get a glimpse of my feelings for you? Heehee, I won't let you lie about that. If you value appearances so much... then I'm happy to stick to you like glue all day and night.",
	main = "By performing good deeds, showing gratitude to others, and being compassionate to the weak... You, too, can be saved even without faith, Commander.|You look like you're struggling with some difficult dilemmas... Should we perform the rite of wisdom? It might be able to help you.|Holy knight Saint Louis... She may be skilled at arbitration, but I think I have her just barely beat in that regard. Heehee!",
	touch = "Yes? I'm happy to offer you guidance.",
	voice_key_2 = -1,
	mission_complete = "You have rewards waiting. Ensure that you do not forget to offer gratitude upon receiving them.",
	battle = "Let the Festival of Lights commence!",
	id = 805020,
	gift_dislike = "",
	gift_prefer = "Ooh! Ah... I'm sorry. I seem to have lost my composure upon seeing this.",
	profile = "The Iris has guided me, Battleship Lyon, to shepherd the lost and banish the wicked. Let us fight together—and prevent the scourge of the great war that once plagued us from ever occurring again.",
	voice_key = 80502,
	headtouch = "",
	feeling2 = "Sincere and righteous deeds will be repaid, both in prayer and in everyday relationships. Even without complex rituals, others will feel your love for them.",
	login = "Good day. Would you like to hear the teachings of the Holy Iris?",
	detail = "There may be little demand, but if anybody from the port wishes to repent... Rather, if anyone needs guidance, please let me know. Hm? You already have others doing the same thing? I'm happy to hear that.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[805021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The girls out on commission should return soon. If you'd like, we could go and greet them together once we're done here...?",
	win_mvp = "",
	home = "(The Commander is out of breath, too... I may be tired from battle, but I'm still happy to be able to sweat with you. Um... I just hope you don't mind the smell...)",
	unlock = "Mmh... Pilates may be easy to learn, but it seems difficult to master... Are you still okay, Commander? Me? I-I can keep going...",
	touch2 = "Ah?! ...Commander, no more of that, please...",
	mission = "Missions...? Of course. Once we're done here, let's check them out right away.",
	vote = "",
	drop_descrip = "Mmh... Pilates may be easy to learn, but it seems difficult to master... Are you still okay, Commander? Me? I-I can keep going...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "(The neck is fine, but it's a little tight around my chest... Am I doing something wrong...?)|(Now that I really think about it, this pose is really embarrassing. But the Commander is watching, so I can't just stop... Should I stay like this...?)|(The Commander took time out to exercise with me, so it'll all go to waste if I yield first... Okay. I'll just wait for the Commander to suggest we take a break.)",
	touch = "(Hmm... How long is it going to take before I can do this stretch correctly...?)",
	voice_key_2 = -1,
	mission_complete = "Mission rewards? Aren't these a touch too luxurious as a reward for simple effort? Heehee.",
	battle = "",
	id = 805021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Do you have it in you to keep going, Commander? If it gets too strenuous, just say the word...",
	detail = "Did you know that this exercise is also called Contrology? It's all about using ideal posture and exercise to control your body and mind... I can see why it's such a profound field.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[805030] = {
	hp_warning = "Activate reserve tanks!",
	feeling3 = "One has had no hardware upgrades, yet this one's operating efficiency is steadily increasing... Is this because of your daily staring? Have you... Have you been secretly exposing this one to your brainwaves?!",
	mail = "Thus one reports – a new letter has arrived. Speaking of which, this one should send you a letter sometime.",
	expedition = "Thus one declares – the commission team has returned. One believes they bring a good haul.",
	win_mvp = "Holy task has been carried out. One will return to designated area.",
	home = "(To carry out a holy task so swiftly... You are everything they say and more, Commander.)",
	unlock = "This one is battleship Alsace – Sacrament of the Unified Orthodoxy, an unreachable dream, and guardian of the Holy See. Commander, let us work together to cleanse the world of evil.",
	touch2 = "Status report... I feel... h-hot and bothered... I-I'm gonna burst!",
	mission = "A mission? Delegate it upon this one and... Hm? You'll handle it yourself? B-b-but... But then what am I supposed to do?",
	vote = "拉票描述",
	drop_descrip = "Alsace-class battleship – Alsace.",
	feeling4 = "*stares robotically*... Yes? What is this one doing, you ask? Reply: I'm trying to beam my brainwaves into you!",
	lose = "Gah... I couldn't... This isn't my fault...",
	feeling1 = "Commander... I don't know how to talk to you anymore after all you've done.",
	skill = "Judgment hath come!",
	upgrade = "One grows stronger. Perhaps this newfound strength will bring us a little closer together.",
	propose = "Seems I didn't need to connect to your emotion module to see what's inside your heart... Are you zapping me with your brainwaves again? Y-you can't, not after making me put this ring on! I feel like my emotion module will explode just from looking at you! Fine, if that's how it's gonna be... L-let's f– Let's get freaky!",
	feeling5 = "Da-dim... Da-dum... Da-dim... Attempting indirect connection with Commander's emotion module... Connection attempt failed. Attempting direct physical connection. Commander, please help! This, umm, connection task is really important!",
	main = "Commander, it seems evil has gone into hiding out of fear of you. Today, we may lower our guard for just a while.|The purpose of this mask is to deepen one's calm and raise one's efficiency... a-and to scare enemies, too, of course.|Battleship Alsace – the noble blade of the Orthodoxy and your protector – hath arrived! How's that? D-do you think that sounded cool?|One observes. One protects. One awaits your orders.",
	touch = "Would you mind giving one a physical inspection, Commander?",
	voice_key_2 = -1,
	mission_complete = "Thus one announces – a holy task has been accomplished. Commander, forget not to claim the spoils.",
	battle = "Behold the Sacrament's manifestation!",
	id = 805030,
	gift_dislike = "",
	gift_prefer = "I-I love this almost as much as I love you!",
	profile = "This one is Battleship Alsace – Sacrament of the Unified Orthodoxy, an unreachable dream, and guardian of– This one already said that? No matter. One's introduction is memorable and thus bears repeating. Take the mask off, you say? Um... I-I can't... Or else my emotion module will overheat and explode...",
	voice_key = 80503,
	headtouch = "Hm? Commander, what are you doing?",
	feeling2 = "Maintenance complete. Emotion module functioning as norm– This isn't normal at all! Ugh, god... Commander, you keep doing this! My emotion module has nearly blown up so many times because of you!",
	login = "One is ready following a full system reboot. When does our holy task begin?",
	detail = "Commander, why do you gaze upon this one for so long? Is it the mask? Well... You shouldn't, because... This one's emotion module– Er, I mean, my heart isn't ready for this!",
	couple_encourage = {
		{
			{
				80501
			},
			1,
			" One shall bring you victory, Richelieu of the Holy See!",
			0
		},
		{
			{
				99901
			},
			1,
			" Allied frame detected. Providing holy assistance.",
			0
		},
		{
			{
				99902
			},
			1,
			" Forge a path to the Orthodoxy's future!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[805031] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Your letters would just get wet if I brought them... Pl-plus, I'd make you... you know.",
	expedition = "The commission team is back? I can't leave the pool now, so... You do the reception thing, please.",
	win_mvp = "One shall bring a bikini-clad victory!",
	home = "Wheeew... Okay, one needs to stay in the water to keep one's emotion module regulated. Just don't think of the Commander... Commander... Ahh... Hahh... ♡",
	unlock = "Thish one ish battleship Alsace – a-artifact of the unifuh... guardian of the Holy See, donning summer clothes... One's frame is overheating and the only fix is submersion in water... Aahhh...",
	touch2 = "Ahh... Commander... I won't stop you if you wanna do it here... ♡",
	mission = "Commander, there are still holy tasks awaiting you... This one's talking \"like that\" again? Yes. The temperature has decreased slightly in one's emotion module.",
	vote = "拉票描述",
	drop_descrip = "Thish one ish battleship Alsace – a-artifact of the unifuh... guardian of the Holy See, donning summer clothes... One's frame is overheating and the only fix is submersion in water... Aahhh...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "You think this one looks even hotter than usual in the summer sun? Ahh... Don't say another word or I WILL overheat and stop working!",
	propose = "",
	feeling5 = "One is in a bikini and underwater, thus one's cooling capabilities are at their all-time highest. You can come closer if you want– Ahh! Identification error has occurred in vision module, and logic pathways have shortcircuited... Why is my Commander resistance value still at zero?!",
	main = "Me, fuming even more than usual? Well, yes, because this cruise with you is just that fun... You've rendered my barely-serviceable emotion module completely nonfunctional.|You think this bikini looks cute on me? N-now you're going out of your way to make me overheat! And it's working so well it's making me all dizzy! Ahh... Give it to me already... ♡|W-wait! My brainwave interceptor fell off... Thank you... Aahh... Am I imagining it, or is the pool heating up all of a sudden?|S-so, we're the only ones here... Try not to lose control of yourself like I do, okay? Ahh, hahh... Oh god... Just thinking about having you all to myself is making me have all kinds of wild thoughts... ♡",
	touch = "It doeshn't make senshe... I'm underwater, and I'm shtill sho hot...",
	voice_key_2 = -1,
	mission_complete = "A holy task has been accomplished. One needs to get back in the pool immediately... *pant*... Before the temp gets too high...",
	battle = "I need to do this quickly, or I'll be late to see the Commander!",
	id = 805031,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "A headpat? One doesn't particularly need it... W-wait, one must turn on the Commander brainwave interceptor... Aahh! Hahh... N-nooo... Don't beam me so hard! You're making me hot even in the water!",
	feeling2 = "",
	login = "Goodness, you're panting and drenched in sweat... Did my bikini do this – making you hot and craving action in broad daylight? ...N-no, Alsace, you mustn't harbor these thoughts!",
	detail = "Wheeew... Aahhh... Huh? H-how did you know I was sending brainwaves into you? I'm still wearing the brainwave interceptor...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[805032] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Message received: The commission team has returned. One shall get down and– Mgh?!",
	win_mvp = "",
	home = "Commander, let us drink every drop of this sake... Ahh. Your heroic performance has been duly logged in– Gah! Th-the cup!",
	unlock = "This one is Battleship Alsace – the Sacramental Blade, the Swordbearing Oni Protector of the Backwoods. One has awaited your arrival. *burp*... Um, pretend that didn't happen, Commander...",
	touch2 = "Eek! This one's sensors are... overheating! Detecting sudden temperature increase!",
	mission = "You carry out your holy tasks... So, too, shall this one fulfill one's role.",
	vote = "",
	drop_descrip = "This one is Battleship Alsace – the Sacramental Blade, the Swordbearing Oni Protector of the Backwoods. One has awaited your arrival. *burp*... Um, pretend that didn't happen, Commander...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Detecting error in sensor functioning... But you're not even touching this one, so how– Eek! M-my sensor's sensitivity is acting up, so you shouldn't touch me there... Hahh, ahh... You'll make me turn into a real oni and attack you!",
	main = "You needn't fuss over form when atoning for a sin. Doing good deeds and accomplishing holy tasks are one and the same.|This one adorned this mask to suppress one's emotions and act in adherence to one's role... a-and also because it looks cool... *blushes*|About the alcohol you recommended – it wasn't sake, but rather Armagnac... which is causing problems for one's emotion module...|Maintaining this pose is a simple task thanks to one's balance function... M-my clothes, on the other hand... Oh, god...",
	touch = "Are you checking this one's ventilation function?",
	voice_key_2 = -1,
	mission_complete = "Do not forget to claim the rewards of your holy task. And to give this one a reward.",
	battle = "",
	id = 805032,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Hahh... Eek! C-Commander! My mask!",
	feeling2 = "",
	login = "Welcome, Commander. The holy task awai– Mrgh! N-no, it's... It's nothing...",
	detail = "(I'm powerless to resist anything the Commander does to me in this pose... I thought I'd get to flaunt my cool side, but I just can't stay composed around the Commander... Oh, god... My emotion module... Drinking this sake has made its temperature go up... Ugh...)",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[806010] = {
	hp_warning = "There are still people in need of help... Back to work!",
	feeling3 = "I've done all of the trivial work available, so that should lighten the load on you for... Zzz... Ah! No, I didn't do an all-nighter. I just stayed a little extra...",
	mail = "Mail's here. I'll get it... Say, don't you think you rely on me too much now? Is that really what you want?",
	expedition = "Break time is over. Let's go greet the commission team.",
	win_mvp = "Outstanding victory, everyone. Nnh... Sorry, I fell asleep. Let's make arrangements for our next battle.",
	home = "Thank you for your efforts. We still have many sacred duties... Nnh... Okay, that's everything! Hm...? Oh, we just started? Sorry... I must've dreamed of finishing it all.",
	unlock = "Bois Belleau. I handle logistics and care for the Iris Orthodoxy. I also keep an eye out for everyone's health – particularly yours, Commander. Keeping you healthy and sane is the most sacred of my duties.",
	touch2 = "Wh-wh-what are you doing?! How unholy, how... You can't DO that in the midst of our sacred duties! It's obscene!",
	mission = "New missions have arrived and require urgent attention. I'll help you, so don't worry.",
	vote = "",
	drop_descrip = "Independence-class light aircraft carrier – Bois Belleau.",
	feeling4 = "Looking good. I feel my efforts are working... Hmm? You're actually following my health advice? That's great. Ideally, you'll put the same effort into your sacred duties. I'll be there to help you, of course.",
	lose = "...We lost? This is going to double my work... Tch, whatever. What matters now is a timely retreat.",
	feeling1 = "I'm limiting our communications solely to work situations. Is that a problem for you?",
	skill = "One after another, endlessly... Time to finish this all at once!",
	upgrade = "With greater power comes more plentiful responsibilities... Tch, whatever. I guess that's what I'm here for.",
	propose = "What is it that makes me want to be so close to you? We were only together for work, but we've become so intimate. It's as if you're caring for me... How did you turn the tables like that? *sigh*... I'll keep performing my sacred duties for you and take better care of you than ever from now on.",
	feeling5 = "Wait, I'll finish my work right away so we can talk... Argh, I messed up! Stupid... I know I can't balance sacred duties and physical affection at the same time, but I still try... Hm? You'll be with me to help? Haha... I didn't think you'd be the one taking care of me this time...",
	main = "Your work environment meets health standards. Continue your sacred duties without worry. I'll be here to help in case you have any problems.|Hm hm♪... Soft music is good for relaxation. Try it out, Commander. Sleep well, and have good dreams... I'll take care of the remaining work.|Staying late again? Okay. I'll work with you and try not to suddenly fall... Zzz... Hnh?! It's okay. I'm definitely... not... falling asleep...",
	touch = "What's the matter? Do you need health counseling, or... is there work you need me to do?! (Why am I so flustered? It was just a light touch. Calm yourself...)",
	voice_key_2 = -1,
	mission_complete = "I'm glad we've finished our sacred duties on time. Now I can finally sleep...",
	battle = "I'm not done yet. We will win.",
	id = 806010,
	gift_dislike = "",
	gift_prefer = "You went through the effort of finding out what I like? Thank you for the thought.",
	profile = "I'm Bois Belleau, a light aircraft carrier under the Holy Iris banner. But I'm more interested in you... Strip for me so I can examine you, please. Why? As I recall, I already told you that ensuring your health is my most sacred of duties...",
	voice_key = 80601,
	headtouch = "Nnh... I'm not sleeping. Wh-what do you want?",
	feeling2 = "Among my sacred duties, the most important is caring for you – that is, maintaining your health. But don't mistake that for meaning that you can neglect regular medical examinations.",
	login = "...Ah! Right, let's begin today's work.",
	detail = "Tch, more and more sacred duties... Hm? You're going to work overtime? That isn't necessary – leave it all to me, and you can go home and rest.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[806011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Zzz... Ah?! I-I could've slept until morning... Long baths really do make me sleepy.",
	unlock = "Finished your sacred work? I looked into hot spring therapy a little to help you relax a little. It's the warmest and most pleasant healing method I've ever seen. Would you... come in with me?",
	touch2 = "Your heartbeat is quickening... Is your blood pressure spiking? Is it because of the hot spring... You're certain it's not? O-oh...",
	mission = "",
	vote = "",
	drop_descrip = "Finished your sacred work? I looked into hot spring therapy a little to help you relax a little. It's the warmest and most pleasant healing method I've ever seen. Would you... come in with me?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "You think... just being with me is enough to relax you? It sounds as if you're denying medical science... but if what you say is true, then would this be a kind of \"couple's\" hot spring therapy? While the hot spring soothes you, I myself am soothed BY you...",
	main = "Your deliverables still aren't done? Well, if you work while you bathe, you probably won't get tired... I know that's impossible for you, though.|Ugh... My legs are numb from sitting like this for so long. Commander, we should get out for a while. Umm... Can you carry me?|It's easy to slip in here. Can you pull me up – Hyah?! Ah...",
	touch = "I'm not giving you a massage in the hot spring. Try all you like, but I'm not indulging you this time...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 806011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Mmm... Ah, now you've gone and healed ME, Commander...",
	feeling2 = "",
	login = "After your hot spring treatment, you should be able to focus more on your work than before. Now, let's get to it. Want me to play some calming music?",
	detail = "Can you feel it? The water's warm, soft embrace... Your mind sinking into a sea of clouds, drifting away quietly... This hot spring therapy is incredible. It's so comfortable, I can't help but feel like I'm healing alongside you.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[806020] = {
	hp_warning = "Nkh... This is starting to hurt.",
	feeling3 = "I might not look like it, but I know how to be elegant! For example, I can... curtsy? Umm, is that what it was called?",
	mail = "Ooh! This mail... must be an invitation to a dance party! Hurry and open it.",
	expedition = "Things are getting lively over there... Our commission team must be back~",
	win_mvp = "Huh? I just finished warming up, and it's already over?!",
	home = "Ooh, welcome back, Commander! Did you like my triple backflip? Pretty cool how I landed square in front of you too, right?",
	unlock = "Hello, hello! Nice to meet you, Commander! I'm the acrobatic dancer of the Iris Libre, Arromanches! Rumors of a lively port brought me here! Come on – time to show me around my new home!",
	touch2 = "Hyah?! You sneaky little... Take this! And this!",
	mission = "Mission alert, mission alert! Let's get it done, Commander!",
	vote = "",
	drop_descrip = "Colossus-class light aircraft carrier – Arromanches.",
	feeling4 = "Commander! I dunno why, but I really want to hear your opinion now! Give me feedback on my performance today, okay? If you like it... I'll be walking on sunshine all day!",
	lose = "I've got so much energy, but nothing to do with it...",
	feeling1 = "Sorry, I'm busy!",
	skill = "Marteau Tornadooo!",
	upgrade = "Power up!",
	propose = "I love you more than anything! I love you so much that I could do ten somersaults right now! But if I did that, I'd make a mess of the room... so I'll go for something simpler and more direct! Huuuug!",
	feeling5 = "I knew it... You're the perfect audience! You take my performance seriously, and you give me sincere feedback... Hehe, I love you, Commander!",
	main = "Hehe, I won a prize in another competition today! What kind? Hmm... I don't remember... Hahaha! I joined partway through!|Look, Commander! Five turns in midair, followed by a 720-degree spin, and finally, a steady landing with Marteau... Whoa! I made a crater in the ground!|Commander, I stopped a fight today! All I did was stand there with Marteau, and suddenly, they calmed down...",
	touch = "Commander, you wanna high-five? Awesome! Let me just charge up, and... HYAAAH!",
	voice_key_2 = -1,
	mission_complete = "Mission complete! Let's wrap it up with a high-energy acrobatic performance!",
	battle = "Time for Marteau to shine!",
	id = 806020,
	gift_dislike = "",
	gift_prefer = "Oooh, a present from the Commander?! Yay!",
	profile = "Arromanches, the Colossus-class aircraft carrier, takes the stage! Wherever excitement goes, I follow! Apart from combat, I'm great at acrobatics – a real pro, you know! Hey, don't call me wild!",
	voice_key = 80602,
	headtouch = "Oh, wooow! Your encouragement is making me feel more energetic than ever, Commander!",
	feeling2 = "Com-man-der! Let's do gymnastics together! I'll show you the ropes, so... Hey, don't be so nervous. As long as I'm around, you won't get hurt! Relax, relax~",
	login = "Woohoo! It's another high-energy day, Commander! Let's do some gymnastics together to warm up!",
	detail = "Commander! Wanna see my warm-up spins with Marteau? ...Hmm? You think that's too much effort for a warm-up? The word \"tired\" doesn't exist in my dictionary! All I know is \"again\"!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[806021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Hahaha! Perfect precision!",
	home = "Urk... Keeping this position is starting to make my feet cold... I know! Commander, hold my feet and use them to draw the bow! It'll help me practice AND warm up my feet – that's two birds with one stone!",
	unlock = "Focus your core, keep your center of balance... Draw the bow, and... Huh? Great timing, Commander! I was just looking for an assistant for my new performance!",
	touch2 = "Hyah?! S-stop that, or I might collapse...",
	mission = "",
	vote = "",
	drop_descrip = "Focus your core, keep your center of balance... Draw the bow, and... Huh? Great timing, Commander! I was just looking for an assistant for my new performance!",
	feeling4 = "",
	lose = "I-I'm gonna fall!",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Aww yeah, my aim is perfect! Hmm? You say I didn't fire any arrows? Heheh, well... I wasn't shooting at the target – I shot your heart! Did you feel how I pierced it right in the center? Hehehe!",
	main = "There's a lot of stuff I had to learn: how to keep my balance, how to draw a bow while doing a handstand, and how to aim with my feet!|Are you trying to see if I can keep my balance while you're distracting me? That's not ne... Ack! D-don't touch my hair! If you do that, I... Nkh! Hahaha?! Don't tickle my feet, either! I'm gonna drop the arrow!|Commander, can you aim the bow and arrow for me? Then, all I'll have to do is draw it and... Whoa?! I pulled too hard and broke the bow!",
	touch = "Hmm? You wanna see if my posture is stable? Heheh, I promise you... Whoa?! Hey, that didn't count! I'm not ready yet!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 806021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Huh?! Is this supposed to help me calm down? There's no way that'll... Huh. I do feel calmer now...",
	feeling2 = "",
	login = "Drawing a bow while reciting my lines... i-is actually really hard! Only I can pull this off!",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[807010] = {
	hp_warning = "I have sustained damage, but it is under control...",
	feeling3 = "A \"grimoire\"? Hmm... And you say L'Opiniâtre told you this? It's certainly an amusing allegory. Now, I'm afraid I must take my leave for a while, as I have business to attend to.",
	mail = "Reporting in. I have a newly arrived letter for you, Commander.",
	expedition = "Transport commissions and cargo escorts are vital, of course, but let's not forget the important safety of our docks.",
	win_mvp = "How would you say I did? Was my performance satisfactory?",
	home = "You would like something sugary in preparation for your mental labor? It so happens I have a list of our stock of confectionaries. Please have a look.",
	unlock = "Béarn, Iris Libre's very first aircraft carrier, reporting for duty. It is an honor to fight by your side. I eagerly await your orders, Commander.",
	touch2 = "Do you lack the knowledge of what being a decent person entails, or are you simply unable to control yourself, Commander?",
	mission = "Commander, I have received word of new mission directives from headquarters. I shall go and make some arrangements.",
	vote = "",
	drop_descrip = "Aircraft carrier – Béarn.",
	feeling4 = "This \"grimoire\" topic again? I do not appreciate your insistence on it. \"A sacrament from the Iris Libre can perform all sorts of miracles\"... Assuming that were even true, how would you utilize such great power, Commander?",
	lose = "I sincerely apologize, Commander. I take full responsibility for this defeat.",
	feeling1 = "\"You are the most outstanding, exceptional commander I have ever met.\" – You can only hope to hear me say these words in your most outlandish dreams.",
	skill = "Let's proceed as planned.",
	upgrade = "Your kindness will not go unrewarded, Commander.",
	propose = "If there are sacraments that can emotionally move and unite people, then this so-called \"marriage\" must be the most powerful of its kind. Ah, this bliss, this feeling of butterflies in my stomach... Now I understand how it feels to take an oath. It's quite enjoyable, actually. Hehehe~",
	feeling5 = "Commander, all of today's clerical tasks have been completed right on schedule. This is a good opportunity to... Indeed, as you've requested, I will teach you about the so-called \"sacrament of love.\"",
	main = "If I may be so blunt, Commander, it would be very unwise of you to read my book. I am not exaggerating or joking about this.|Are you daydreaming, Commander? You may continue to fantasize if you so wish; we have enough free time in today's schedule to accommodate for it.|I shall attend to our official business and schedule management. You need only focus on the work on your desk, Commander.",
	touch = "I am right here, Commander. Do not hesitate to give me your orders.",
	voice_key_2 = -1,
	mission_complete = "A mission has been completed. That's one burden off our minds.",
	battle = "Now, as outlined in our briefing, prepare for combat!",
	id = 807010,
	gift_dislike = "",
	gift_prefer = "Commander, do you ever feel as if you're putting too much thought into me? It's okay to be more relaxed around me.",
	profile = "My name is Béarn, I am the Iris Libre's first aircraft carrier, converted from the unfinished 5th Normandie-class dreadnought. I lived to see the end of the strife between Iris and Vichya... A tragedy I pray will never happen again.",
	voice_key = 80701,
	headtouch = "",
	feeling2 = "Are you curious about this book? It is just a notepad, more or less. Rest assured, there is nothing remarkable about it. And it is certainly not something you need look at.",
	login = "Here is today's schedule, Commander. Read it at your leisure.",
	detail = "An improvement in operational code and tactical variables... This sequence should be useful. I shall write this down in my notebook.",
	couple_encourage = {
		{
			{
				80201,
				80202
			},
			2,
			"I'd love to transport fascinating items with you.",
			0
		},
		{
			{
				80501,
				90501
			},
			2,
			"I am profoundly honored to fight by your side.",
			0
		},
		{
			{
				20601,
				30603
			},
			1,
			"Allow me to show you an Iris sacrament.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[807011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "You were out at sea? Here, have a towel.",
	unlock = "Are you perhaps feeling unwell, Commander? Oh, I see, you're just looking for a shaded place to rest? Acknowledged. In that case, you may sit here if you'd like.",
	touch2 = "I suspected you would engage in obscene behavior as soon as you distanced yourself from onlookers, Commander...",
	mission = "",
	vote = "",
	drop_descrip = "Are you perhaps feeling unwell, Commander? Oh, I see, you're just looking for a shaded place to rest? Acknowledged. In that case, you may sit here if you'd like.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "One can seek cover from the sun, but cannot escape the heat. As I'm on lifeguard duty, perhaps I should've brought an electric fan with me.|This ice cream is going to melt if nobody eats it. Say, Commander, would you like a taste?|Both Vichya and Iris girls enjoying the summer on the same beach... A lovely sight, in my opinion.",
	touch = "Your praise honors me, but I can easily imagine that you praise everyone here for their swimsuits.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 807011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Would you like a swim ring, Commander? It could be useful if you plan on playing with the girls by the beach.",
	detail = "Everyone seems to be enjoying themselves at the beach. What do you say about playing beach volleyball, or building a sandcastle, Commander? Me, I would rather remain here and observe.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[807020] = {
	hp_warning = "Answer my prayers...!",
	feeling3 = "Please accept this blessed lucky item. ...Yes, I'm certain that it'll bring you good fortune!",
	mail = "New mail... *sigh*... I hope it's good news.",
	expedition = "Our commission team is back. I sent them off with today's lucky item, so I'm sure they bring great results!",
	win_mvp = "Our prayers... have been answered.",
	home = "I've been praying here ever since you left, Commander. ...Oh, and I prepared drinks and snacks, too. Would you like to partake together?",
	unlock = "I am the second Joffre-class aircraft carrier of the Iris Libre, Painlevé. It is a pleasure to meet you... May you and your companions receive the Iris's protection.",
	touch2 = "S-sorry! I don't really want that right now...",
	mission = "Missions... I wonder if there's a lucky process to them. Oh, what I mean is, maybe there's a specific order you can do them in to make good things happen, or... something.",
	vote = "",
	drop_descrip = "Joffre-class aircraft carrier – Painlevé.",
	feeling4 = "You always know exactly what I'm thinking, Commander. Hahaha, you know... I don't mind the feeling of having someone see through me without so much as a word.",
	lose = "Why...? Were my prayers not enough? Did I miss some sort of ill omen?",
	feeling1 = "Ever since I met you, I've noticed so many more ill omens. Why could that be...?",
	skill = "This, too, is the Holy Iris's wish–",
	upgrade = "Umm... if this is your wish...",
	propose = "I have more wishes than I can count, but right now... Heehee, there's only one on my mind, and it's about to come true. Commander, thank you for making my dream a reality. I'm so glad... I came to love you.",
	feeling5 = "Whenever I pray, images of you well up in my mind. I always end up looking forward to it... Wh-what am I saying right now?!",
	main = "Commander, making wishes isn't all-powerful. Don't make too many wishes, or you may invite divine retribution...|Commander? The thing is, I... No, never mind. Forget I said anything...|Astrology, tarot cards, tasseography, bagua... Which one should I choose today?",
	touch = "Commander... Is there something you want me to do?",
	voice_key_2 = -1,
	mission_complete = "Our missions are all done. Did my lucky process work for you? Maybe you got more rewards than usual, or...?",
	battle = "Today is a lucky day, I'm certain... Everything will be okay!",
	id = 807020,
	gift_dislike = "",
	gift_prefer = "I've never said that I wanted this, so how did you... Th-thank you very much!",
	profile = "I am aircraft carrier Painlevé, and I stand here only because of wishes. Making our wishes come true isn't easy – it comes with sacrifices and regrets. But despite all that, we can never stop wishing.",
	voice_key = 80702,
	headtouch = "",
	feeling2 = "Ah... Umm... Yes, I understand your wish. As for me, I'd prefer to maintain an appropriate distance...",
	login = "Oh, Commander... I'm not done praying yet. If you don't mind... could you please wait a bit?",
	detail = "Only by truly wishing for it can we continue to reach greater heights. Commander, as someone who travels with the blessing of the Holy Iris at your back, do not forget this.",
	couple_encourage = {
		{
			{
				90701
			},
			1,
			" Our trial... has begun!",
			0
		},
		{
			{
				90302,
				90113,
				90401
			},
			1,
			" T-to the Templar Knights' triumphant return!",
			0
		}
	}
}


