_G.pg.base.ship_skin_words[818010] = {
	hp_warning = "What chaos... Now I'm getting excited! Heheheh!",
	feeling3 = "I heard there's a new scratcher at the convenience store. If you get the super-rare heart pattern, you can turn it in for a mystery prize... Isn't that thrilling? Anyway, I bought a thousand. Let's get scratching!",
	mail = "You have new mail~ What could it be? I'm dying to know.",
	expedition = "The commission team has brought back a veritable mountain of supplies! Heehee... It's actually an illusion. Aww, now I can't bring myself to dispel it, seeing how happy they are.",
	win_mvp = "Victory becomes boring the moment it's guaranteed... Let's get to our next battlefield.",
	home = "That was a hard-fought battle. Relax those tense nerves, alright? I know a lot of fun places to go, and I'd be happy to show you around, hehehe~",
	unlock = "Are you the Commander? Greetings from Cherbourg, Illusionist of the Iris... Oh? Things are getting lively out there. Mind if I go take a look? I hope you and I can get to know each other better later on... Hehehe.",
	touch2 = "What a sudden attack... You know just how to entertain me, don't you? Heehee.",
	mission = "I've put together a list of your unfinished missions. Take a look... Oh? You think I added that last one myself? Goodness, how easily you pierced my illusion...",
	vote = "",
	drop_descrip = "Naval treaty specification 23,333 long ton protected cruiser – Cherbourg.",
	feeling4 = "Hmmm? Why am I following you? Don't worry about it. I'm just... discovering a new hobby of mine, hehehe.",
	lose = "Oh my, don't be sad~ Sometimes, the roulette wheel of fate just lands on red.",
	feeling1 = "Boring.",
	skill = "Don't blink, or you might miss it! Heheheh!",
	upgrade = "The line between reality and illusions blurs even further~",
	propose = "Marriage? Why, I'd be happy to~ Just imagining the unpredictable future that we share makes me shiver with excitement... Never ever bore me, you got that?",
	feeling5 = "Every decision you make opens up new possibilities for me... It fills me with more excitement than anything else. I'm totally addicted to you now, Commander.",
	main = "Oh, you're finally awake. We're on a snowy mountaintop! ...Oh, you think the snow is an illusion? What if the blanket's warmth is the illusion instead?|The boredom of these monotonous times drives me crazy... Commander, entertain me. I'll take ANYTHING♡|It's almost time for the girls' \"Grand Adventure\" to begin. Would you like to watch? These are the best seats in the house!",
	touch = "Oh? What will you do next? I can't wait to find out.",
	voice_key_2 = -1,
	mission_complete = "Mission complete... Are you SURE you're not interested in the special mission I planned for you?",
	battle = "Let's cause some chaos in their ranks!",
	id = 818010,
	gift_dislike = "",
	gift_prefer = "Unwrapping a gift is always such an exciting experience~",
	profile = "I'm Cherbourg, a naval treaty specification 23,333-long-ton protected cruiser under the Iris banner. As for who I am? A believer in chance, a connoisseur of chaos, and an illusionist... In this ever-changing world, I think it's a little silly to hold on to a fixed identity.",
	voice_key = 81801,
	headtouch = "You're petting me? Well, this is novel...",
	feeling2 = "Why are there a dozen coffee cups on your desk? Pssh, as if I would know... Try taking a drink, and you might find out. But if you pick wrong... Your coffee might just pounce on you like a cat!",
	login = "*yaaawn*... Your daily schedule is so rigid that it puts me to sleep. I put some thrilling surprises in your daily schedule... You'd better look forward to those. Hehehe.",
	detail = "One choice, one path, with countless possibilities swirling at your fingertips... Fact and fiction are irrelevant. All are simple hallucinations that disappear in the blink of an eye. What drives our choices, then? Fun, of course.",
	couple_encourage = {
		{
			{
				80602
			},
			1,
			" I know the secret to becoming elegant. Just do as I say, and you'll get there in no time.",
			0
		}
	}
}


