_G.pg.base.ship_skin_words[901010] = {
	hp_warning = "It's just a flesh wound! I'll tough it out!",
	feeling3 = "Commander, you'll help me study? Yay! Thank you so much! I'll be sure to... Huuhh? Wait, I have to memorize all this?! S-sorry, I have a stomachache!",
	mail = "Mail's here~! I already brought it all with me, ehehe~",
	expedition = "Everyone's back! I'm gonna run down to greet them! Be right back!",
	win_mvp = "I'm in first place...? Très bien! Ehehe~!",
	home = "Commander, you've gotta sweat to burn off fat!",
	unlock = "Eh? Who are you... Ah! Right, you're the Commander! I'm the L'Adroit-class destroyer, Le Mars! A pleasure meetin' you!",
	touch2 = "Th-this place also needs a massage? Um... it feels a little strange...",
	mission = "We're not done with the missions quite yet. Let me handle the errands!",
	vote = "",
	drop_descrip = "L'Adroit-class destroyer – Le Mars.",
	feeling4 = "I think I'm starting to get it, but maybe not... But, I'm so glad that you're patient enough to teach a dummy like me. Thank you, Commander!",
	lose = "Merdé! Time to retreat!",
	feeling1 = "Woah, Commander... I, I think I'll be training solo today!",
	skill = "Time to do this~!",
	upgrade = "I grow stronger yet again! Thanks, Commander!",
	propose = "Um... I haven't learned what I'm supposed to do at a place like this yet... Ah, um! In any case, p-please continue to take good care of me in the future!",
	feeling5 = "Even though I still don't quite understand this stuff, there is one thing that's certain - when it comes to learning things about you, Commander, I function twice as well!",
	main = "Commander, I'll teach you some stretches for those long days!|Being a commander sure is tough, isn't it? Having to micromanage this and that... My head would start spinning... |Studying just isn't my strong suit... I obviously can read all these words, but they just don't make any sense to me when put together...",
	touch = "My shoulders were starting to get stiff too... Thanks a ton, Commander!",
	voice_key_2 = -1,
	mission_complete = "Mission complete! Huh...? I still have to tally the rewards?",
	battle = "Warm-up exercises are all done! I'm setting out~!",
	id = 901010,
	gift_dislike = "",
	gift_prefer = "Ah! I've always wanted one of these!",
	profile = "Back then, I wasn't able to fulfill my duties, but... Commander, this time, I'll show you what I'm capable of!",
	voice_key = 90101,
	headtouch = "",
	feeling2 = "To be an outstanding knight, it's not enough to just have the strength to protect others. You must also become wise through learning! But... I always start dozing off when I'm studying... *yawn*",
	login = "Commander, you finally made it! What's on the training regimen today?",
	detail = "To be honest, I'm a little jealous of Forbin. Back then, we both weren't able to move, but she made more of the situation than me...",
	couple_encourage = {
		{
			{
				80102
			},
			1,
			"Forbin, shall I take the lead?",
			0
		}
	}
}


