	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 901041,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "*gasp*... *gasp*... A prayer to the Holy Iris. Please... let this day be a peaceful one... and give the Commander... boundless energy...",
	detail = "After a run, my daily prayers... Commander—Oh, you're going back to your office? I-I see... Your mornings are busy, after all, so we can't... A-actually, may I come with you?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[901042] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "I'd better keep this creature in check until the commission team returns... Whoa whoa?!",
	win_mvp = "Oooh... We managed to win, but I'm so dizzy... I think I'm about to faint...",
	home = "Welcome back, Commander. Th-things seem to be fine right now, but if it gets out of hand later... I hope you'll be willing to help again... Oh, me...",
	unlock = "C-Commander, p-please hurry and stop this creature! Otherwise! You might! Get hurt! ...WoooooOOOOAH! Phew... That was a close one... Haah... Praised be the Holy Iris... Urgh...",
	touch2 = "I-I can't move another inch...",
	mission = "Changing the hay, cleaning the stable, the daily milking... There! A complete list of today's holy duties!",
	vote = "",
	drop_descrip = "C-Commander, p-please hurry and stop this creature! Otherwise! You might! Get hurt! ...WoooooOOOOAH! Phew... That was a close one... Haah... Praised be the Holy Iris... Urgh...",
	feeling4 = "",
	lose = "*pant*... It finally calmed down... Ugh, I can't believe this happened...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "It may be hard work, but caring for animals is another holy duty. Besides, if it means helping you... I-I'm always happy to put my heart and soul into any task!",
	main = "I hear this is an Eagle Union matador's costume... But it's so unlike Europa's. Have we verified that claim...?|You seem even more worried about me since I changed into this outfit. What a sin I've committed...|I should have discussed this with Lady Clemenceau first. If only I knew caring for animals was such a difficult task... No. This must be a trial given to me by the Iris... Right? Right?!",
	touch = "Do you have a confession? O-okay! If you don't mind that I'm dressed like this!",
	voice_key_2 = -1,
	mission_complete = "Phew... That holy duty was a tough one. Thank you for your efforts, Commander.",
	battle = "",
	id = 901042,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, watch out – Hyah?! Why did it calm down as soon as it saw you...? Either way, thank you...",
