_G.pg.base.ship_skin_words[901050] = {
	hp_warning = "Oww... That really hurts!",
	feeling3 = "I'm \"surprisingly well-behaved\"? What's that supposed to mean?! I've always been more principled than mischievous! I take my job as a Templar Knight seriously!",
	mail = "Commander, there's a letter for– What? You're worried it's boobytrapped? Come on, who do you take me for?!",
	expedition = "A commission's been completed. Head out and talk to the girls!",
	win_mvp = "Nice and simple! This is easier than practicing my telepathy trick!",
	home = "Welcome back! I took a leaf out of someone else's book and made you tea. Don't worry, I didn't add anything to it – enjoy your perfectly normal tea!",
	unlock = "I'm Fleuret, Le Hardi-class destroyer and Templar Knight of the Vichya Dominion. And you must be the Commander, heehee. We're gonna get along juuust fine, you and I!",
	touch2 = "Eeek! Stooop! Touching a lady like this is criminal! ...Ahahaha! You should've seen the look on your face!",
	mission = "Still got holy tasks you need to do, huh? C'est la vie. Let me help you out!",
	vote = "拉票描述",
	drop_descrip = "Le Hardi-class destroyer – Fleuret.",
	feeling4 = "I can do more than just write cards. Tadah! Have a rose! Heheh, surely you of all people know the meaning a single flower can hold.",
	lose = "Hrmh... Clearly, I wasn't fast enough.",
	feeling1 = "Hrmh. You're hopeless the way you are now. Then again, hopeless people still have their charm. Heehee.",
	skill = "You're annoying!",
	upgrade = "This'll let me pull great tricks!",
	propose = "Ahahaha... I-I didn't think you'd actually do it. Come on, don't stare daggers through me as a way to get an answer... That's playing dirty! L-look, my answer is: yes, happily!",
	feeling5 = "You've gotten to the point where you can't imagine life without me, haven't you? You've got to make a move on me already, or there will be consequences!",
	main = "You've been giving me suspicious looks as of late, Commander. VERY suspicious looks by Orthodoxy morals. Heh, do you have a crush on me? Yeah, right... Huh? I was right? I think I've actually developed telepathy!|Where'd I leave the documents that were on your desk? I disposed of 'em all. Hah, just kidding! I processed them and put them right here.|How about instead of performing magic, we play \"greater than less than\" with cards next time? And whoever loses has to be the winner's mount!",
	touch = "Heh! You wanna see a new kind of magic, do you?",
	voice_key_2 = -1,
	mission_complete = "Heheh! Mission complete! See? I knew you needed my help!",
	battle = "Heheh, you small fries are in for a bad time!",
	id = 901050,
	gift_dislike = "",
	gift_prefer = "Wow. I've never told you what I like. This is really impressive, Commander!",
	profile = "I'm Fleuret, Le Hardi-class destroyer and the Vichya Dominion's flower. Don't dismiss me just 'cause I've got a cute name, 'kay? I can handle anything you throw at me, from being a Templar Knight to serving as your bodyguard!",
	voice_key = 90105,
	headtouch = "Heehee, aren't I cute? Feel free to keep patting!",
	feeling2 = "Loooser, loooser! You're a loser! ...There, happy now? You really make weird requests sometimes.",
	login = "Ah, here comes the Commander of our Dominion! Heehee, do you wanna play a game? How about... card guessing? You pick a card, and I'll sus out which one it is.",
	detail = "I always look forward to doing magic with you. You have such funny reactions to every trick I show you! Ahahah!",
	couple_encourage = {
		{
			{
				90106
			},
			1,
			" Keep it together for at least a minute!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[901051] = {
	hp_warning = "",
	feeling3 = "",
	mail = "You got a message? Fine, you can check your phone. Normally, that would be cheating, but I'll tolerate it in this case.",
	expedition = "Whoa, the commission team is back. There's no rule saying you can leave in the middle of our game, but I'll allow it this time!",
	win_mvp = "",
	home = "Welcome back, Commander! Once you're ready, take a card! Relax, we're not playing a game – this is magic!",
	unlock = "Welcome, welcome! I'm Fleuret, your game master. Are you ready to make a wager? Heehee!",
	touch2 = "Eeek! I'll have you know there are hidden cameras in here! Not really, but I bet you bought it!",
	mission = "",
	vote = "拉票描述",
	drop_descrip = "Welcome, welcome! I'm Fleuret, your game master. Are you ready to make a wager? Heehee!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Ahaha! This is great! I thought about using card magic, but I didn't need even it to easily beat you! Heehee, now, as the winner, what should I ask from you?",
	main = "Commandeeer, you ready yet? Staring at the cards won't transform them into new ones. Well, probably not. Maybe they will!|Look at you, eyes darting around! I don't blame you, though. You did lose your every last chip to me. How will you pull yourself outta this one?|If you're feeling tired, come here and lie down. You won't get my cushions, but you're free to rest your head on my thighs.",
	touch = "Commander, you're only meant to touch the cards in my hand.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 901051,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Heheh, you trying to butter me up to make this easier for you?",
	feeling2 = "",
	login = "You took an awfully long time shuffling the deck, Commander. Huh? You suspect my cards are marked? Why, I'd never do anything like that!",
	detail = "Really, Commander? I explained all the rules of the game and you're still spacing out. Is it my outfit? Is it distracting you? Heh, just kidding. You're a sweet little bean, Commander.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[901060] = {
	hp_warning = "I don't wanna accept defeat...!",
	feeling3 = "I've been studying more ways to help you out, Commander! You wanna see the results? O-okay! First, how to clean up your clothes... Oh. Ooooh... I tore them to shreds again...",
	mail = "There's mail for you, Commander! Ack... I'm really worried that I might have dropped any mail that is really important...",
	expedition = "*staaare*... C-Commander, may I come with you to greet the commission team...?",
	win_mvp = "Phew... I'll help lead you all to victory!",
	home = "Commander, welcome back! I-I'm really glad you're not hurt... Huh? I shouldn't run? Why – Aaah! Aww, I fell just like that...",
	unlock = "Phew... Deep breaths, now... You can do this, Épée... Haaaah! C-Commander! I'm Épée, a Templar Knight of the Vichya Dominion! Nice to meet you! I-I dunno... Will that be good enough?",
	touch2 = "I-if it's fun for you, Commander...!",
	mission = "Commander, you have unfinished missions... D-did you leave them undone because I'm such a nuisance? That must be it...",
	vote = "拉票描述",
	drop_descrip = "Le Hardi-class destroyer – Épée.",
	feeling4 = "*staaaaare*... (Whoa?! Whoawhoawhoa?! W-we made eye contact! Urk... My heart pounds so hard when I look into the Commander's eyes...)",
	lose = "Th-this is just too much for me...",
	feeling1 = "C-Commander... It's totally my fault you turned out this way, huh? Ugh...",
	skill = "Stay out of my way!",
	upgrade = "Do you think I can help you more now?",
	propose = "Y-you mean it? You'd give a ring to someone like me... Someone who's not fun, or charming, or skilled... Me, of all people? W-waaaah... I'd be happy to be with you forever, and ever, and ever, Commander!",
	feeling5 = "C-Commander, why are you staring...? Huh? You wanted to try talking with your eyes like I do...? Ah! Whawha?! C-Commander, you knew all this time? Oooooh, this is really embarrassing...",
	main = "*staaare*... Huh? Is there something I wanna say? N-no... I just couldn't stop myself from staring at you, is all...|E-excuse me! I wanted to wash your clothes, but when I was scrubbing them, they started tearing... Oh, Commander, I'm sorry...|I-I might not be helpful to you yet, but... I'll do my best! A-after all, I want to be a knight who can protect you... Hehe...",
	touch = "Umm... If there's anything I can do for you, don't hesitate to ask...!",
	voice_key_2 = -1,
	mission_complete = "Thank goodness! A successful mission... I can't wait to find out if I helped at all...",
	battle = "I-I'll try not to make it hurt!",
	id = 901060,
	gift_dislike = "",
	gift_prefer = "*sniffle*... You really remembered... I'm so happy!",
	profile = "Greetings from Épée, Vichya Dominion Le Hardi-class destroyer... A-as you can see, I'm a little scatterbrained, but I do my best every day to get better... I-I hope I can cause as little trouble for you as possible...",
	voice_key = 90106,
	headtouch = "H-hey, so, I don't mind if you mess up my hair...!",
	feeling2 = "*staaare*... (Th-the Commander can't tell I'm watching, right? Urk... I can't take my eyes off of you when you're working so hard...)",
	login = "C-Commander, welcome back! It took a while, but I got aaall of your important documents together... Hehe...",
	detail = "I have a holy duty to protect you and make you happy... Right! I might cause a little bit of trouble for you now, but I'll do my very, VEEERY best...!",
	couple_encourage = {
		{
			{
				90105
			},
			1,
			" Fleur, b-be careful...",
			0
		}
	}
}


