	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I hate it when you get sick, but I do love an opportunity to practice like this♥ Although, if you keep staring at me like this... I think I might cave in to temptation before you do♥",
