	touch = "Commander... There's no one but us here, so you don't have to hold back♥",
	voice_key_2 = -1,
	mission_complete = "Mission complete? Wait, when did you do that missions?",
	battle = "",
	id = 901072,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Ahah♥ Now pull me into bed with you...",
	feeling2 = "",
	login = "*sniiiff*...♥ *sniiiff*... ♥ This is a physical... or should I say, olfactory checkup, so it's perfectly fine. God, you smell so good, Commander♥",
