	id = 901073,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Mmm... Haaah! No matter how strong the wind gets, it'll never erase your scent on me... Hahh... Aah♥",
