_G.pg.base.ship_skin_words[901120] = {
	hp_warning = "There's no way I could dance like Émile...!",
	feeling3 = "Lessons, offers, training, and rehearsals... There's too much stuff to do... I can't deal with this anymore! I'm gonna pass out at this rate... Just looking at the schedule is making me want to crawl back into bed... Maybe I should do just that today~",
	mail = "It's work-related. Look it over please.",
	expedition = "The commission fleet has returned... Phew! That means I get to chill!",
	win_mvp = "Long live the glory of the Iris! Rejoice! Weep!",
	home = "Good work out there. Would you like to enjoy a most elegant cup of tea?",
	unlock = "I am the Iris's shining sword, Le Malin. As the shimmering idol who chases the waves, may your souls be healed by my songs of prayer.",
	touch2 = "Hwuh?! Wh-what are you doing?!",
	mission = "We got a job offer... Hopefully we can take care of it quickly and efficiently...",
	vote = "",
	drop_descrip = "I am the Iris's shining sword, Le Malin. As the shimmering idol who chases the waves, may your souls be healed by my songs of prayer.",
	feeling4 = "Haah, haah... How's that? My performance was pretty on-spot, wasn't it? If you think so, let me take a break already! All right, I'll be heading off! Or, uhh, if you could prepare some tasty snacks for me...",
	lose = "There's no time for regrets...!",
	feeling1 = "This... must be carte blanche to loaf around as much as I want...",
	skill = "Light, heed me!",
	upgrade = "The Iris's miracle manifests here!",
	propose = "The fact that I'm standing upon this shining stage right now is due to all the support from you and my friends. Now, place that ring upon my finger, and may our vow preserve this radiance forevermore!",
	feeling5 = "Commander, on my day off, promise you'll take me on a date? I mean, uhh, sorry, I'll just head back to... Huh? Really?! Yaay! I can't wait to loaf around together— Ah, ahem... First, this concert...!",
	main = "An \"idol\" is something that people worship and exalt. As the word suggests, we mustn't do anything that would shorten that distance.|Jean Bart told me to just enjoy myself, but... the expectant gazes of Le Triomphant and Richelieu... it burns!|That little girl from the Royal Navy.. . Not only does she act all innocent, she also sings about \"prayer.\" Hehe, as if I'd let her steal my thunder~",
	touch = "Thanks for always cheering me on~",
	voice_key_2 = -1,
	mission_complete = "F-finally, that's taken care of... Now all that remains is the collect the reward, elegantly... ",
	battle = "Harken! Hear my prayer!",
	id = 901120,
	gift_dislike = "",
	gift_prefer = "I-is that...",
	profile = "I am the Le Fantasque-class destroyer, Le Malin, reporting for duty. Heheh... Just watch, I'll do an amazing job on this idol mission. J-just to be clear, it's not like I was looking forward to this!",
	voice_key = 90112,
	headtouch = "Huh...? What is it?",
	feeling2 = "I am the dazzling Iris idol, Le Malin— Now, provide me the most elegant of instructions!",
	login = "Good morning. What will today's lesson be?",
	detail = "I didn't really want to do this, but I'll see this idol mission through. I will bring the elegance of the Iris to the world stage.",
	couple_encourage = {
		{
			{
				89902
			},
			1,
			"Please make the lyrics easier to understand!",
			0
		},
		{
			{
				90503
			},
			1,
			"Let's do our best onstage!",
			0
		},
		{
			{
				90501
			},
			1,
			"You know... it really does feel better to just enjoy myself!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[901130] = {
	hp_warning = "You underestimate this proud Templar Knight!",
	feeling3 = "You follow the example set by my sisters Le Triomphant and Le Malin... What of Le Terrible? She is wise, yes! But do not be like her and go around asking people impossible questions!",
	mail = "A letter for you. Well, well, this is an exquisite wax seal.",
	expedition = "I've finished inspecting the commission goods. Grateful for my help, hmm? Hah! It's par for the course!",
	win_mvp = "MVP? Woohoo! ...Ahem! My wish is to see hard work be duly rewarded.",
	home = "Magnificent commanding, pleb! Keep it up if you hope to earn my recognition!",
	unlock = "L'Indomptable – Le Fantasque-class large destroyer and Templar Knight of the Vichya Dominion – has arrived! Have you the honor befitting someone of your status? ...Hmph, save your breath! I shall judge you through your conduct, not your words.",
	touch2 = "Y-y-you vile barbarian!",
	mission = "I am a Templar Knight with honor! I do not let missions gather dust unlike you, pleb!",
	vote = "",
	drop_descrip = "Le Fantasque-class destroyer – L'Indomptable.",
	feeling4 = "I, I must admit, you have quite some elegance for a pleb... Hm? You appreciate my efforts in observing you? It's hardly worthy of praise. In fact, I'm enjoying mys– No, I mean...! Flattery won't get you anywhere with me!",
	lose = "Grrr... My knightly pride has been tarnished...",
	feeling1 = "Hmph. A donkey like you would flee like a coward once we encounter real danger anyway.",
	skill = "You will be judged in the Vichya's name!",
	upgrade = "The greatest equipment belongs only in the hands of the greatest wielder!",
	propose = "Is a ritual like this required for me to become yours? And I even have to wear this ring too? ...Very well. Then let us move on to exchanging vows! ...Hold hands? Then go on a date? Wh-wh-what are you talking about? Y-y-you've tricked me, haven't you?!",
	feeling5 = "Hmph. You've earned my recognition, pleb! I will be your knight. You have my loyalty, and my heart! ...What about it? What I just said is completely ordinary coming from a Templar Knight!",
	main = "I strive to always conduct myself with confidence and elegance, like my role model, Le Malin! ...What are you grinning for, pleb?|A reward for a job well done, you say? I'll have some macaro– Ahem! No, a proud Templar Knight needs no rewards!|The Le Fantasque class is renowned for its speed. And any who think it comes at the cost of firepower is in for a world of pain!",
	touch = "Hahah! Revere my lance 'til you've had your fill! It is my weapon and my badge of honor!",
	voice_key_2 = -1,
	mission_complete = "Mission completed. Let's see the rewards... This is all...? N-no, I said nothing!",
	battle = "I'll teach you what painful things happen to those who cross the line!",
	id = 901130,
	gift_dislike = "",
	gift_prefer = "I-I guess I could accept a gift from you... once in a while.",
	profile = "I am Templar Knight L'Indomptable, Le Fantasque-class large destroyer. As my name states, this proud knight shall neither cede a single step, nor back down before any foe!",
	voice_key = 90113,
	headtouch = "Hmph! You think your pleb tricks will work on– Hehehehe... Oohh...",
	feeling2 = "Prove your honor and sense of duty to me, then I will treat you fairly! A proud Templar Knight is true to her word!",
	login = "You're late! One in command of the whole fleet must always be first to arrive at the office!",
	detail = "My black lance? Hmph! As if a pleb like you would understand the majesty and power of this rigging that befits me!",
	couple_encourage = {
		{
			{
				90111
			},
			1,
			" Le Malin, join me in battle!",
			0
		},
		{
			{
				80101
			},
			1,
			" Noblesse oblige indeed!",
			0
		},
		{
			{
				80107
			},
			1,
			" I'm not keen to have you along...",
			0
		},
		{
			{
				80108
			},
			1,
			" Heheh! I am the chivalrous one between us!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[901131] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission team has returned. Don't keep them waiting over at the pier.",
	win_mvp = "You reaped what you sowed by scoffing at a Templar Knight!",
	home = "\"Are you my Grandmamma?\" – Hah, Little Red Riding Hood is a fool! If I were her, I'd say \"I saw through your disguise with one glance, Big Bad Wolf! Prepare to meet your maker!\"",
	unlock = "What a farce, making a proud Templar Knight portray a helpless little girl... Why am I lying here, you ask? Hmph. Because Le Malin asserted this is the best way to get in touch with my \"vulnerable side\"...",
	touch2 = "Y-y-you're making me mad!",
	mission = "New missions have come in. I'd rather be doing those than playing this role that ill suits me.",
	vote = "",
	drop_descrip = "What a farce, making a proud Templar Knight portray a helpless little girl... Why am I lying here, you ask? Hmph. Because Le Malin asserted this is the best way to get in touch with my \"vulnerable side\"...",
	feeling4 = "",
	lose = "Urgh. Playing a feeble character must've turned me genuinely feeble...",
	feeling1 = "",
	skill = "",
	upgrade = "I feel ever so slightly stronger...",
	propose = "",
	feeling5 = "If I were to ever lose my strength and become a helpless little girl... would you stay with me, even if I'd be a hindrance to you? ...If it comes to that, you'll become MY sword?! Th-th-th-that doesn't exactly delight me, not at all...!",
	main = "I'm infinitely more suited to play a gallant knight than a defenseless little girl... But, I'm sure Le Malin has her reasons for promoting this role to me.|How should I act to appear helpless? ...Hm? When I encounter evildoers, my first instinct is always to send them packing with my lance.|Sleeping Beauty is apparently the role Le Malin most wants to play. Fitting, seeing as she's skilled at feigning sleep!",
	touch = "Do you want this sweet, juicy apple? ...No, it's not poisoned, it's merely a tasty apple!",
	voice_key_2 = -1,
	mission_complete = "You finished the mission? H-here I thought I could assist you after my rehearsal...",
	battle = "It's your funeral if you think my helplessness is any more than an act!",
	id = 901131,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "C-careful with my hair!",
	feeling2 = "",
	login = "So soft and cushy... Mmh, this is the dream... *yawn*... *gasp*! Rats! I got dangerously close to dozing off...!",
	detail = "Am I really meant to lie here and do nothing, Le Malin? ...It's part of getting into the role? I see. Then lie I will!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[901132] = {
	hp_warning = "",
	feeling3 = "",
	mail = "A note of correspondence... Oh. It's addressed to you.",
	expedition = "",
	win_mvp = "Behold! L'Indomptable, the black lancer of Vichya, shall cater the victory banquet!",
	home = "It's faster to take that route? Thank you! Your guidance serves me well both in the port and on the battlefield!",
	unlock = "Hmm... Traveling by foot from here would be quickest. Ah... It's snowing. Hmph! A little snow and wind can scarcely faze a noble Templar Knight! I'll be back shortly!",
	touch2 = "Stop that lest you make me drop the food, pleb!",
	mission = "A mission, much like Dragon Empery cuisine, is best to take in hand posthaste.",
	vote = "",
	drop_descrip = "Hmm... Traveling by foot from here would be quickest. Ah... It's snowing. Hmph! A little snow and wind can scarcely faze a noble Templar Knight! I'll be back shortly!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "The elegant Le Fantasque class performs stunningly in all manners of missions! Yes, even including food delivery!|You're willing to assist? I-I'll be fine! I'm still perfectly capable of handling a delivery! ...I will call for your help when I truly need it!|This is the third time Le Malin has ordered food just today... Granted, it is an Empery holiday. Elegance is a luxury ill-afforded in hectic times...",
	touch = "A positive review, you say? I gladly accept a commendation that speaks to my honor as a Templar Knight, if... You're simply referring to your delivery experience?!",
	voice_key_2 = -1,
	mission_complete = "I have brought your mission rewards. Inspect them before they turn cold.",
	battle = "",
	id = 901132,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Haa... Haa... Ahem! You made it to the office ahead of schedule! Eat up while it's still warm!",
	detail = "Ah... Achoo! ...Why do I wear such light clothing when it's snowing? Le Terrible recommended it, and, well... I-I have no reason whatsoever to doubt her wisdom!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[901133] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Heheh! My mission has been completed flawlessly! This is nothing for an exemplary Templar Knight!",
	home = "",
	unlock = "A masquerading-and-eavesdropping mission is a walk in the park for a Knight of the Dominion! Finding evidence of my target's crimes will take no time at all!",
	touch2 = "W-wait! What you're doing now... ruins my ability to complete my mission!",
	mission = "Attention! Your missions remain undone!",
	vote = "",
	drop_descrip = "A masquerading-and-eavesdropping mission is a walk in the park for a Knight of the Dominion! Finding evidence of my target's crimes will take no time at all!",
	feeling4 = "",
	lose = "Curses! The target is getting away!",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "How delectable and sweet it smells... *gasp*! Curses! I licked up the cream! Damn it... My disguise will surely fail now!|Comma– Ahem! Youthful stranger, how are you today? ...That greeting gives nothing away, does it?|Seeing as you've seen through me, we'll just need to keep going like this! We are but an ordinary couple on a date at this café – understood? Good! Nothing can go wrong now!",
	touch = "H-how did you see through my disguise, Commander?! I could swear that it was flawless...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 901133,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Whuah?! You're undoing my disguise!",
	feeling2 = "",
	login = "Oh, Commander. Have you also come to enjoy a sip of– No, wait! I am not L'Indomptable! I have no recollection of your identity!",
	detail = "There is cream stuck to my lips? Hmph – I was told by Le Malin that this would greatly better my disguise. Although it may itch a tad, she is a professional, and her advice cannot be wrong!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[901140] = {
	hp_warning = "I can take it!",
	feeling3 = "The closer I get to you, the more I realize my own shortcomings. However, the more I find, the more I feel like I'm growing! For you, Commander, are my idol, and so every step closer I get to you is proof of my own growth!",
	mail = "You've received a new letter! Here – I fetched a letter opener for you!",
	expedition = "The commission team has returned, Commander. They returned with these rewards. A flawless victory, I'd say.",
	win_mvp = "You fought risking life and limb to the very end... This, I respect!",
	home = "Excellent work, Commander. Your commanding was truly a sight to behold! You never cease to amaze!",
	unlock = "I am L'Audacieux, Chevalier of the Holy Iris. Commander, are you this blade's new master?",
	touch2 = "C-Commander? Is this a part of a Chevalier's duties?",
	mission = "You have new missions, Commander. Shall I prepare anything in advance for you?",
	vote = "",
	drop_descrip = "Le Fantasque-class destroyer – L'Audacieux.",
	feeling4 = "To be worthy of a place by your side, I must become stronger and better! Or else I will end up a Chevalier abandoned by the master she pledged herself to... I will not let that happen!",
	lose = "I will hold off the enemy's pursuit. Everyone else, fall back!",
	feeling1 = "You've turned your back on the Holy Iris and fallen far, but I will never give up on you!",
	skill = "Justice is here!",
	upgrade = "Yes, I feel a surge of new strength. It is for you, Commander, that I continue to swing this blade!",
	propose = "Does this signify that... we've made vows to one another? I would still protect you, with or without having received this ring... What? This ring means that we've officially become wife and... Wait, whaaat?! That's what it signifies?!",
	feeling5 = "If I may be abrupt, I've been having these feelings lately... I don't merely want to pledge myself entirely to you, I also want to be with you forever... Huh? Th-this is what they call \"love\"?",
	main = "I seem to have my act together, you say? Why, yes! Ahem... A level head and a sound heart are foundational for a Chevalier.|It feels as though I've been treated like a child again today... A Chevalier won't be so easily fooled.|One with strength but no wits is no more than a hothead. With wisdom comes true courage. Through deliberate thinking do you seize true victory. These, Commander, are the learnings of the Chevaliers!",
	touch = "Commander, do you need any help?",
	voice_key_2 = -1,
	mission_complete = "Mission complete... and I was on guard duty yet again... It's okay! Endurance is one of the Chevaliers' virtues... I think!",
	battle = "Tremble before the might of the Holy Iris!",
	id = 901140,
	gift_dislike = "",
	gift_prefer = "A-a gift? For me? W-wow!",
	profile = "I am L'Audacieux. I strive to be a bold and courageous Chevalier worthy of this name. Will you bear witness to my growth?",
	voice_key = 90114,
	headtouch = "I will say... this does feel pleasant...",
	feeling2 = "Nearly everyone at the port has nothing but glowing things to say about you. This could only mean you're an exceptional and strong individual! Perhaps you're even suited to be a Chevalier!",
	login = "You've arrived, Commander. Now, what is our schedule for today, pray tell? Rest assured, your loyal Templar Knight shall be with you throughout any and all matters!",
	detail = "Humility, honesty, mercy, courage, justice, self-sacrifice, spirituality, and honor – these are the eight virtues of the Chevaliers that I uphold. Upon my name as a mighty Templar Knight, I shall protect all our comrades!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[901141] = {
