_G.pg.base.ship_skin_words[903020] = {
	hp_warning = "I'm telling you, the constraints of the treaty are still too suffocatingly restrictive...",
	feeling3 = "Commander, won't you drink a little with me? Are you perhaps bad at holding your alcohol? That's alright. Just take a little sip, like this... and try slowly tasting it with your throat... That's it... Don't you taste it?... The cool, rich flavor of maturity.",
	mail = "Reading a letter allows you to peek into the hidden heart of the person who sent it... Hehehe, how exciting! Here, Commander, some new mail's come in for you.",
	expedition = "The girls from the commission team have come back. I wonder if I can guess which girl's carrying the most important goods?",
	win_mvp = "If only you realized the situation you were in a little sooner, you might've been able to avoid this outcome... but what can you do at this point?",
	home = "Good work planning out the operation, Commander. How would you like some freshly brewed coffee?",
	unlock = "Bonjour. From today, this heavy cruiser of the Vichya Dominion shall now be serving at this port. It's a pleasure to meet you, hehe. If it's not too much to ask, I hope that we can get along well.",
	touch2 = "Commander~? No matter how nice the other person may be, you shouldn't get too carried away. Hehe.",
	mission = "We've just received a new directive from the higher-ups. Oh? It seems that you're just as busy as always... As much as I'd like to do some of this work in your stead, I suppose I wouldn't be able to?",
	vote = "",
	drop_descrip = "Algérie-class heavy cruiser – Algérie.",
	feeling4 = "You know, I actually really, really like cute things. Those trinkets, those squishy furballs, making sweets... Hehe, don't you think it's nice for an adult to enjoy cute things?",
	lose = "It seems that I lost... But don't worry, Commander. Let's prepare carefully and try again.",
	feeling1 = "Oh, Commander. I've been looking into the documents that need to be prepared for your formal retirement. Are you ready to start the process?",
	skill = "It's too late to run~",
	upgrade = "Shattering the confines of the treaty... is rather pleasurable. Hehehe~",
	propose = "Thank you. Henceforth, I vow to dedicate my whole heart and body to you. Together, let us enjoy - slowly and surely - just how sweet our future will be. My partner, my beloved...",
	feeling5 = "Commander... would you like to rely on me? ...If it's you, I'd be happy to let you rely on me, and I'd always be supporting you from your side. Hehe, in exchange... I hope you'll show me just how much you can achieve, with me by your side.",
	main = "Even if I don’t have any honors or decorations, my strength can speak for itself. | Oh, Commander. How about enjoying some wine with me later? Hehe, only after you finish up the rest of your work though, alright? | Gold...? Oh, were you interested in that story? Hehehe. At that time, the Iris were... | My hobby is touring cat cafés, but this port doesn't... Oh, that's right. Even at this port, there are plenty of adorable creatures... Yes, how lovely! | The Royal Navy are now allies who fight together with us. Furthermore... even yesterday's enemies are today's allies. What an interesting life this has been... Hehehe.",
	touch = "Oh my, did you want to slack off for a bit? Hehe, I won't tell anyone else, so take some time off, okay?",
	voice_key_2 = -1,
	mission_complete = "Have you finished the mission? Good work. Please leave the report to me and go get some rest.",
	battle = "It'd be nice if the battle goes the way we want it to.",
	id = 903020,
	gift_dislike = "",
	gift_prefer = "Thank you for this gift. I love it, hehehe.",
	profile = "I'm the flagship of the Vichya's First Cruiser Fleet, Algérie of the Templar Knights. In my history as a ship... I was called the best-designed treaty cruiser. Accordingly, I've been through plenty of interesting escapades... Hehehe. How do you feel about me, Commander?",
	voice_key = 90302,
	headtouch = "Are you trying to see if I have a fever...?",
	feeling2 = "Are you a bit scared of me? Hehe, don't worry, Commander. I wouldn't harm an ally.",
	login = "We're on great terms after all. I would've been fine waiting a bit longer.",
	detail = "When it comes to history, relying on second-hand accounts is not enough to sift fact from fiction. You must conduct your own research.",
	couple_encourage = {
		{
			{
				90103,
				90101
			},
			1,
			"There's nothing to fear. The Vichya Dominion rises up to face any crisis.",
			0
		},
		{
			{
				60302
			},
			1,
			"We've finally got a chance to compete, Zara. Wanna see who's better?",
			0
		},
		{
			{
				10117,
				70102,
				70501
			},
			1,
			"Hehe, what a nice smell. Will you let me tag along for a bit?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[903021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Wine... would be a little bit out of place here. Hehe. Commander, will some tropical juice suffice?",
	unlock = "Oh my, hehe... Are you enjoying the warmth of the sunlight here? I'm glad that you're finding some time to relax here, but wouldn't you rather come play with everyone else?",
	touch2 = "Huh?! I wonder, do these clothes make the Commander more impertinent...?",
	mission = "",
	vote = "",
	drop_descrip = "Oh my, hehe... Are you enjoying the warmth of the sunlight here? I'm glad that you're finding some time to relax here, but wouldn't you rather come play with everyone else?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Commander, if I buried you in the sand neck-down, you wouldn't be able to move, and I'd be able to do whatever I want to you~ Hehehe, I'm joking. Or, would you like to do that to me? Hehehehe.",
	main = "Here, a sun cap. If you want to play out on the beach, please make the proper preparations against the sun's rays first.|A beach volleyball match between the Vichya and Royal Navy... Sounds fun. How about watching it together?|nil|Writing words on the beach and waiting for the waves to wash them away... Hehe, seems like it'd be fun~ What shall we write?|Sigh... It's seriously quite hot... Commander, don't push yourself, you hear? Please let me know if you start to feel worse.",
	touch = "You want some coconut juice...? Alright, wait there for now. I'll bring some over.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 903021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Even if you've already applied some sunscreen, you still need to take care to not get sunburns.",
	detail = "Hehehe. Commander, it seemed like you enjoyed being surrounded by so many cute girls. Who caught your attention the most?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[903022] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Feeling tired? If you'd like a drink, I'll have one of the \"little attendants\" bring it over.",
	unlock = "Oh my, it seems that the one who ended up coming wasn't little Alice, but you instead... Do you plan to defy me as well, Commander? If so, I'll have to put you on trial for your sins... How was my acting just now? Hehe~",
	touch2 = "Shall I call the soldiers? ...Just kidding, hehe.",
	mission = "",
	vote = "",
	drop_descrip = "Oh my, it seems that the one who ended up coming wasn't little Alice, but you instead... Do you plan to defy me as well, Commander? If so, I'll have to put you on trial for your sins... How was my acting just now? Hehe~",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "It's quite troubling playing the role of a villain. Should I act in a way that people will like me, or in a way that people will hate me...?|The rabbit who's supposed to lead the way in the story ended up getting lost in the set... Commander, shouldn't you go help that little'un?|Good triumphs over evil... In fairy-tale stories like this, there's no better ending than that. Like a storytale for pure, innocent children.",
	touch = "If you'd like to try your hand at being the \"Evil Ruler,\" I'm perfectly willing to hand over the throne to you, hehehe.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 903022,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "You're finally here, Commander. Have you decided how you'll continue the plot?",
	detail = "The Cheshire Cat? A bit foul-mouthed, but still a good kitten nevertheless. Oh, considering my current role, maybe I should be more annoyed?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[903030] = {
	hp_warning = "I'm really not cut out for this stuff!",
	feeling3 = "When I'm with you, I can't help but relax and end up depending on you... Ugh, I can't be like this! I need to be the kind of woman you can depend on!",
	mail = "Mail for you. Commander, you should check it soon. Don't forget, you got that?",
	expedition = "The commission is complete, Commander. Here's the list of materials they received. Look over it for me.",
	win_mvp = "We'd better get back while the battle is fresh in our minds. I can write up a good report on this...",
	home = "Welcome back, Commander. I did some of your work for you to match what I did of my own. Let's use this extra time to rest. It's already break time, so...",
	unlock = "I am Dupleix, concierge for the Vichya Dominion. Doesn't look like time's on our side today, Commander... Now then, here's today's timetable. Shall we get started on our sacred duties?",
	touch2 = "C-Commander, where do you think you're putting your hands?!",
	mission = "New missions... Don't you think you have too much work to do? Share some of the burden with me.",
	vote = "",
	drop_descrip = "Suffren-class heavy cruiser – Dupleix.",
	feeling4 = "Commander, wanna make a bet? If I can finish my holy duties ahead of schedule, I get aaall of your break time... You mean it?! Okay! I'm definitely gonna win this!",
	lose = "Reviewing the loss, accounting for lost materials... H-hahaha... So much for my sleep and our date plans...",
	feeling1 = "I found the cause of all my extra work... It's you. You're at fault, aren't you, Commander?!",
	skill = "Don't underestimate a clerical worker!",
	upgrade = "My hands and feet feel so warm... It's nice.",
	propose = "Commander, what's gotten into you? Coming to me as soon as you finished your holy duties... You want me to close my eyes? Okay, but why... Huh? I-is this... for me?! I-I feel like I'm about to cry... Oh, finally... Finally, I get one of these...",
	feeling5 = "So our contest starts in earnest tonight... My plans are as perfect as can be... W-wait, why am I getting more holy duties at a time like this?!",
	main = "Holy duties, holy duties, holy duties holy duties holy... Gah, there's another. How am I supposed to handle all of this... Eep?! Ahem, Commander? How long have you been there?|Not there, either... I can't find the stuff I just bought... C-Commander, help. What do I do?!|If I had Lady Clemenceau's aptitude for planning, I could secure break time for you... Sorry.",
	touch = "Oh, my... Is this how you relieve stress? Very unique...",
	voice_key_2 = -1,
	mission_complete = "Mission compleeete! Strike one holy duty off the list... In no small part thanks to you, Commander.",
	battle = "Disappear without a trace, please, so that you don't add even more to my sacred duties!",
	id = 903030,
	gift_dislike = "",
	gift_prefer = "Heehee, aren't you sweet, Commander.",
	profile = "I'm Dupleix, a Suffren-class heavy cruiser and a concierge for the Vichya Dominion. Commander, let's get our holy duties done together.",
	voice_key = 90303,
	headtouch = "Work-life balance, huh... Are you saying you want me to take a break? Thanks, Commander.",
	feeling2 = "You impress me, Commander. Even faced with so many holy duties, you don't look worried at all. I should be a little stronger, too. After all, I'm... I'm like your big sister now!",
	login = "We're getting today's work done, TODAY. I hope you're ready, Commander.",
	detail = "Not finishing today's sacred duties can ruin your time-efficiency and poses a risk of a snowball effect the next day, so I won't rest until the day's work is done. You know how you feel when your work never ends, and you hate yourself because you really need to take a break from it? That's the worst, isn't it?",
	couple_encourage = {
		{
			{
				80301
			},
			1,
			" Suffren, wanna go out next time we're off, or...",
			0
		},
		{
			{
				90301
			},
			1,
			" I'll back you up, Foch.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[903031] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Thanks for all your hard work, Commander. I just reached a pause in my duties... Shall we take a breather?",
	unlock = "Good timing, Commander. There are some parameters I need you to check... Come on, this is safety we're talking about. As an inspector, I can't just ignore them. Anyway, come sit next to me so we can get started.",
	touch2 = "Hyah?! Commander, at least wait until I'm done here...",
	mission = "",
	vote = "",
	drop_descrip = "Good timing, Commander. There are some parameters I need you to check... Come on, this is safety we're talking about. As an inspector, I can't just ignore them. Anyway, come sit next to me so we can get started.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Work has been busy, but the memory of seeing you on the racetrack gives me the energy to accomplish anything. That doesn't mean I wouldn't like a reward, though... You'll take care of me, won't you, Commander?",
	main = "Even after the race, we'll have never-ending work... Just thinking about it tires me out.|(After this inspection, I'm gonna find the best spot to watch the race. No shot I'm missing the Commander's race!)|It's hot... Hm? For me? Th-thanks... That was really nice of you, bringing a drink just for me.",
	touch = "After the race, things are going back to usual, huh? Say... Commander, what would you say to a date before we're inundated with work again?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 903031,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Seat belts, check... Fire extinguisher, check. All should be well, Commander.",
	feeling2 = "",
	login = "When did this checklist get so... C-Commander?! Wait a second, I'm just finishing up!",
	detail = "As a vehicle inspector, it's my duty to inspect as thoroughly as I can before the race. Everything has to meet safety standards, and that includes your equipment, Commander.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[904010] = {
	hp_warning = "I'm only getting warmed up...",
	feeling3 = "Back then, none of us had a choice... so I don't blame the Royal Navy for what happened. Quite the contrary - if it wasn't for them, we might not be fighting together now.",
	mail = "Commander, I've finished sorting your mail, so don't forget to take a look.",
	expedition = "Oh my, it looks like the commission fleet has returned. Perfect timing - I'll invite them to try my new confections.",
	win_mvp = "Let's keep up this pace.",
	home = "Commander, would you like to try my freshly baked gâteau?",
	unlock = "The day when we can all stand together has come at last... It's an honor to be here, Commander. I am Dunkerque - please allow me to become a part of this magnificent fleet. ",
	touch2 = "What am I going to do with you...",
	mission = "There's no shortage of new missions for us to get through... Hard work is important and all, but let's not overwork ourselves.",
	vote = "",
	drop_descrip = "Dunkerque-class battlecruiser – Dunkerque.",
	feeling4 = "Commander, you're quite the conversationist. Do you find me interesting to talk to? Hehe, I make sure to remember all your preferences. Sit tight for a moment, and I'll bring some cake out for you.",
	lose = "T'en fais pas... a defeat here is not the end.",
	feeling1 = "Ça faisait longtemps, Commander. There's no need to worry about me; I've been doing fine.",
	skill = "Let's do it just like we practiced...!",
	upgrade = "Every little bit matters.",
	propose = "If I only was able to meet you in the present because of my suffering in the past, I won't say things like \"I wish I had met you sooner.\" However, I do hope that in the future, I will always be able to find solace in your embrace. Commander, can I stay by your side forever?",
	feeling5 = "True strength is not measured by our capacity to suffer in silence, but by our courage to open up to others. Commander, that's why... if you ever feel like crying, my bosom is always available for you.",
	main = "There are things in this world that you might never be able to accomplish, but that is no reason to give up hope.|It's not nice to sit around idly in port, but... Strasbourg, who took my place in leading the fleet, must feel even worse about what happened... if only the Army was able to hold out a little longer... *sigh* |Ahh~ Sweets can really take a girl to heaven... C-Commander?! How long have you been here?!",
	touch = "Commander, shall we make some confections together? My home country is world-famous for our sweets, you know?",
	voice_key_2 = -1,
	mission_complete = "Hm? I see, the mission rewards are here. Commander, I'll go get them.",
	battle = "Apologies. I have no mercy to spare for my enemies.",
	id = 904010,
	gift_dislike = "",
	gift_prefer = "Merci beaucoup~",
	profile = "I am Dunkerque, 1st Division of the Line of the Vichya Dominion. As you already know, there is no glory in my service history - there is no hiding this fact. However, if you are still willing to use me, I will not let you down.",
	voice_key = 90401,
	headtouch = "",
	feeling2 = "Glad you could make it, Commander. One moment please - the dessert is ready, I just have to make tea. Today, let's unwind and chat a little.",
	login = "Commander, did you get enough rest?",
	detail = "What should I make... Macarons, or Mont-Blanc? Oh my, Commander, you came at just the right time. Why don't you help me decide what confection to make?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[904011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Who wants to have some crullers? I made more than enough for everyone~",
	home = "Commander, would you like some ice cream? I brought several different flavors of syrup.",
	unlock = "I've been waiting so long for summer... and it's so worth it - the sun, the sand, the waves, and everyone's laughter. Commander, why don't we take this opportunity to enjoy some crullers together?",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "I've been waiting so long for summer... and it's so worth it - the sun, the sand, the waves, and everyone's laughter. Commander, why don't we take this opportunity to enjoy some crullers together?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Ice-cream based desserts are delicious, but they melt too easily... I might have to bring a cooler with me next time...|It's been a long time since I last was able to enjoy scenery like this without any worries...|Commander, are you done changing? The others are calling for us, let's go play with them!",
	touch = "Want to try gazing into the ocean horizon together? It always puts my mind at ease.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Enemies...? Way to spoil the scenery...",
	id = 904011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, are you done changing into your swimwear~?",
	detail = "Everyone looks like they're having so much fun... I couldn't ask for anything more.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[904012] = {
	hp_warning = "",
	feeling3 = "",
	mail = "We have new intelligence? Well, don't worry about me. Please, check it at once.",
	expedition = "Commander, the commission is complete... Hehe, no matter the time or place, I suppose I'm still your secretary ship.",
	win_mvp = "",
	home = "No need to rush, Commander, I don't mind waiting for you.",
	unlock = "Don't you simply adore the atmosphere in this place? It's one of my favorites. The desserts here are to die for. Would you like a taste?",
	touch2 = "",
	mission = "Is it a very important mission? Well then, I'll go with you.",
	vote = "",
	drop_descrip = "Don't you simply adore the atmosphere in this place? It's one of my favorites. The desserts here are to die for. Would you like a taste?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "The warm sunlight, the peaceful atmosphere, the soothing music, all embracing me as I relax and chat with one so dear to me. If this is a dream, I hope to never wake up...",
	main = "......der, Commander! Look at you, staring at me and spacing out again, am I really so captivating? Did the ice in your drink melt?|Commander, shall we go for a stroll? How often do we get to go out on a date? Let's not waste this one sitting around chatting.|When I sit here like this, I sometimes forget I'm a warship... But, to fight for these little moments, that's not such a bad motivation, is it, Commander?",
	touch = "Just relax, Commander, we still have plenty of time. ",
	voice_key_2 = -1,
	mission_complete = "Commander, some mission rewards are available. Shall we head back to the office?",
	battle = "",
	id = 904012,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Here you are, Commander. Oh? Don't worry, I've only just arrived myself.",
	detail = "What's your favorite dessert? I can make it for you, Commander.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[904020] = {
	hp_warning = "Agh... Has something gone awry?",
	feeling3 = "(Whew... Okay, I got that out of my system. Hm? Who's that at the door?) ...C-Commander?! Why are you here? ...You heard terribly violent music playing? Wh-why, yes, that was me.",
	mail = "There's a new letter for you. I've left it over here. You'll do the wise thing and read it at once, no?",
	expedition = "The commission team has returned to us. The inventory list I made is right here. Do read it, Commander. G-good job, you say? W-well, I won't refuse a compliment...",
	win_mvp = "The performance has ended.",
	home = "You've returned. Shall I play a melody to mellow out your tense nerves? ...No, that was not an expression of affection for you. I-I said it's not, so it isn't!",
	unlock = "I am Strasbourg, Knight-Virtuosa of the Tribunal. And you must be the one who I've heard so much about. I see. Heehee, I look forward to seeing what you're capable of, Com~man~der~♥",
	touch2 = "Well, well... Want to know what it feels like to have both your arms tied up in strings?",
	mission = "You have new missions. Seems you have your work cut out for you, no?",
	vote = "",
	drop_descrip = "Dunkerque-class battlecruiser – Strasbourg.",
	feeling4 = "I found out that nobody has been using this room, so I converted it into my private music room. W-wipe that look off your face! We all have our secrets... and this is mine, the secret no one else knows. From now on, you must bear my secrets and my stress together with me.",
	lose = "This can't be! I... never lose...",
	feeling1 = "I don't see you as a listener, and you don't see me as a player. Thus, we are at an impasse.",
	skill = "I offer you this mercy.",
	upgrade = "Good. I'm not opposed to power.",
	propose = "For... For me? Really? Why? You have no shortage of other admirers... Wait, let me just confirm this one last time! It's me – I'm the one you want, yes? Because if so, I will really stop holding back, embrace you tightly, and make sure nobody can ever take you from me.",
	feeling5 = "*sigh*... Commander, when I look at you, do I really see the person who I adore so much? I've grown so attached I can't deny it anymore. I'm in love with you. Do your eyes see the love in me? Gaze upon me, and don't look away... Please...",
	main = "Though I'm not a judge, I've learned much from my Tribunal colleagues who perform the \"dirty work\"... Though, one thing I'd like to know is, how on earth your espionage skills have come to rival that of our intelligence officers.|Dunkerque made this dessert for me. And this one is for you, heehee. Now you owe me.|So, what did you think of my improv piece today? ...You REALLY liked it? You don't need to be THAT direct with your words... Still, thank you... *blushes*",
	touch = "What, pray tell, is your goal with this intimacy?",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Wonderful – like a song played to perfection.",
	battle = "Open your ears for this requiem is for you.",
	id = 904020,
	gift_dislike = "",
	gift_prefer = "Th-this is for me? What do you want in return? You can ask for anything!",
	profile = "I'm Strasbourg, member of the Tribunal. I am both a listener and a player. As my coworker, try not to bore me.",
	voice_key = 90402,
	headtouch = "You're hopeless, Commander... *blushes*",
	feeling2 = "The song I played had a mellow sound to it? Why, thank you for your kind words. Playing the music that suits the listener's tastes is, after all, an instrumentalist's job – quite similar to how we interact with people, don't you think?",
	login = "Greetings, Commander. Oh, I'm surprised you've already started your holy task.",
	detail = "The domain of music is free of lies and treachery. There, I and my instruments can become logical and perfect beings. How fantastic it is to swim in the sea of melody and harmony – wouldn't you say so?",
	couple_encourage = {
		{
			{
				90401
			},
			1,
			" Will you... make more desserts for me?",
			0
		},
		{
			{
				8
			},
			1,
			" The Tribunal shall support you.",
			3
		},
		{
			{
				9
			},
			1,
			" Here we shall play. Lead the charge.",
			3
		}
	}
}


_G.pg.base.ship_skin_words[904021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "The race is over, Commander. Want a cold drink? Or maybe a bucketful of cold water over your head? Or maybe you want...♡",
	unlock = "Commander? I can't believe you found me... As you can see, I'm finishing up this car's pre-race checks. If you have time to spare, would you mind lending me a hand? Oh, and of course, keep this a secret between the two of us. I can count on you for that, yes?",
	touch2 = "Are you THAT eager to do it? Alright, but let's continue this INSIDE the car♡",
	mission = "",
	vote = "",
	drop_descrip = "Commander? I can't believe you found me... As you can see, I'm finishing up this car's pre-race checks. If you have time to spare, would you mind lending me a hand? Oh, and of course, keep this a secret between the two of us. I can count on you for that, yes?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Cheering on the racers together, getting ready for a race together, playing the piano together... The track is brimming with my memories with you. Now there's only one thing left to do. Why don't you take the wheel of the vehicle known as... me? ♡",
	main = "Race cars are like instruments – they have a clear logic to them, their physical framework is evident, and they warrant studying... Buuut, as soon as you arrived, all my attention went straight to you.|Everything's ready. Should be good to go... You know, we're starting to get REALLY synchronized, you and I. Let's keep this up.|I'm so tired... Stay still, will you? Don't move so much or I might trip and get stuck. Heehee, you've made me like this – will you take responsibility for it? Come closer so our bodies may touch♡",
	touch = "Oh? Need my help?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 904021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Hey! C-Commander! Leave my headphones alone.",
	feeling2 = "",
	login = "Commaaander – what are you looking at? I said, \"what are you looking at\"? Heehee... Have you fallen under my spell within moments of arrival, hmm?",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[905010] = {
	hp_warning = "That all ya got?",
	feeling3 = "Stop looking so intimidated. Long as you won't betray me, I won't betray you.",
	mail = "Got some mail for ya. Picked it up on the way here.",
	expedition = "Guess your rackety team's come back.",
	win_mvp = "Your endeavors were touching... but when you pick the wrong fight, that's all they'll ever be.",
	home = "You finished plundering? Coulda gotten it done in no time if you'd brought me.",
	unlock = "I'm Jean Bart, the Vichya Dominion's last cutting-edge battleship. Guessing you'll be plotting my course from now on... Hmph, I'll see for myself how good a job you'll do.",
	touch2 = "... You better not regret this later.",
	mission = "A job's a job. Whining won't make it go away.",
	vote = "",
	drop_descrip = "Richelieu-class battleship – Jean Bart.",
	feeling4 = "I can't stand hearing those babies cry when you get hurt... So use me as a shield. I don't mind.",
	lose = "My payback comes with interest... Before long, you'll know how much!",
	feeling1 = "Seems you've mistaken a wolf for a dog... Hmph, don't start crying if you get bit cause of it.",
	skill = "Playtime's over!",
	upgrade = "Feeling great. Wanna give it a shot?",
	propose = "The path I walk is an unforgiving, dirt-ridden path where you can't even see the future lying ahead of you. But ya still wanna go with me? ... Hmph, your stupidity amazes me. And for your foolishness, I offer you the rest of my days.",
	feeling5 = "It's like the mood eases up when you're with me... I'mma get some rest right here... And don't you leave me...",
	main = "The era of battleships is over? Hah, the hell you mean? MY era is just getting started!|Insincere preaching about faith and beliefs is no different from idle sleeptalk.|Idiots just don't ever wisen up, do they... What drives 'em to pray to a made-up being that won't even respond?",
	touch = "Stop trying to hit on me.",
	voice_key_2 = -1,
	mission_complete = "... Pish, them's some shabby rewards.",
	battle = "Don't bother with courtesy! Just bunch up and come at me!",
	id = 905010,
	gift_dislike = "",
	gift_prefer = "Hmm? Give something to a pirate like myself, and you'll never get it back. Are you sure you want to give this to me?",
	profile = "I'm Jean Bart, the battleship. I was named after a certain \"renowned\" privateer... You what? Never heard of privateers? They're pirates with legal permission to pillage, fighting for a just cause.",
	voice_key = 90501,
	headtouch = "",
	feeling2 = "Your smile makes me think of her... She's someone I wanna hate, but can't bring myself to.",
	login = "Go figure... you're busier than I expected. If ya need a hand with something, just gimme a shout.",
	detail = "If some dumbass sticks their nose where it doesn't belong, they got only themselves to blame when they're hanging from my cannons.",
	couple_encourage = {
		{
			{
				80501
			},
			1,
			"That's enough praying. Prepare to fight!",
			0
		},
		{
			{
				10519
			},
			1,
			"You're not gettin' ahead of me a second time!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[905011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "A commission fleet has returned? Let's head down to greet them together then. I needed some fresh air anyway.",
	win_mvp = "Mmm... the wind on the battlefield... now that's what I'm used to.",
	home = "Did you just come back from battle? Here, cheers.",
	unlock = "The guest of honor shouldn't be wandering around looking for girls drinking alone... Hmph, might as well have a drink while you're here anyway.",
	touch2 = "",
	mission = "You still have missions to do even now? ... Need my help?",
	vote = "",
	drop_descrip = "The guest of honor shouldn't be wandering around looking for girls drinking alone... Hmph, might as well have a drink while you're here anyway.",
	feeling4 = "",
	lose = "Hmph. Still better than going to that banquet...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I loathe red tape, nor do I have any desire to stand here like a flower vase for people to stare at... But I'm doing all of this for you, because you make me feel like it's all worth it. You've committed quite the serious offense, mon amour...",
	main = "Letting go of everything and losing yourself to the merriment of song and dance... that is what a banquet should be about. Not this pompous farce that makes even wine taste bad. |The one thing that this banquet has going for it is the fact that everyone's smiles are genuine and heartfelt... Look, I'm praising you, can't you tell? |Commander, I'm not going to exchange pleasantries with you. C'mon, it's not like we just met for the first time, right?",
	touch = "Cheers... Hmph. I never asked for the \"blessing\" of being someone's sister, but I've already gotten used to what that entails.",
	voice_key_2 = -1,
	mission_complete = "C'mon, put all that stuff aside and have a drink with me.",
	battle = "",
	id = 905011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "You... look awfully bored, Commander. Hmph, what a coincidence. That makes two of us.",
	detail = "I'm more willing to listen to Dunkerque than a lot of others. She's a lot more in touch with the masses.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[905012] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Would you stop comin' here right after returning to port? Don't want people catching wind of this place and turning it into a playground.",
	unlock = "You damn scalawag... You don't just sneak into someone's hideaway without consequences, ya know. Though, I found this place by pure chance too. Don't go tellin' anyone else about it!",
	touch2 = "You're not the only one who can do whatever ya want just 'cause nobody else will come here. I can, too. Understand?",
	mission = "",
	vote = "",
	drop_descrip = "You damn scalawag... You don't just sneak into someone's hideaway without consequences, ya know. Though, I found this place by pure chance too. Don't go tellin' anyone else about it!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Man... The sun's crazy bright out today... What, you're still here? How long are ya gonna hang around? Hmph, you're real good, both at making me happy AND making me mad, you know that?",
	main = "Sorry, but this hammock's only big enough for one of us. Ya wanna relax, get your own. I ain't your personal servant.|Just how much damn work do you have if you're even bringin' it up here...? You just like being with me...? Tsk...|Wha–? Is... Is that Surcouf? The hell... How'd she end up dozing off in here? That girl's a real piece of work.",
	touch = "Ack! Don't put your damn ice-cold soda on me! You're on thin ice, buddy...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 905012,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Don't you go touchin' my stuff without permission! I'll knock ya out cold.",
	detail = "You wanna go lookin' for treasure? There's no damn treasure 'round here. But one day... Hmph, one day, when we've achieved a boring peace, I'll give you a taste of what a real treasure hunt is like.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[905013] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "I'm not the type to underestimate anyone.",
	home = "You're back? Seems you've got girls queuein' up to meet you. Me, not so much...",
	unlock = "Bonne année... Or rather, I should say \"Happy New Year\" here, yes? A year of peace and prosperity passes, and we are here to welcome another... and I must thank you for making that possible.",
	touch2 = "Umph! What now?!",
	mission = "",
	vote = "",
	drop_descrip = "Bonne année... Or rather, I should say \"Happy New Year\" here, yes? A year of peace and prosperity passes, and we are here to welcome another... and I must thank you for making that possible.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Not to say I've grown soft, but I have gotten too used to you bein' around. I don't mind it – hell, I like it. I'm all but dependent on you, that's just how important you are to me.",
	main = "Sakura Empire-style badminton? Sounds fun. I'll knock that shuttlecock beyond the horizon!|I hate it when people approach me to either give or get a hug. Never asked for their damn compassion.|Wagashi, for me? Thanks. Dunkerque sure is considerate as always. ",
	touch = "What, you wanna see me brandish one of these?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Forward! Quarter them!",
	id = 905013,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Hmh...",
	feeling2 = "",
	login = "Work, same as always, huh? Tell me if there's anything I oughta know.",
	detail = "Aid with getting dressed? This is nothing compared to a ceremonial Iris dress. Not to mention it suits me better. Don't ya agree?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[905014] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Got a letter for you here... No, I didn't go looking for it. I just happened to find it.",
	expedition = "That rowdy bunch is back. Heheh. They're right at home with this holiday spirit.",
	win_mvp = "",
	home = "Look who's back. So, what should I do? It's not that I DON'T want your approval, I just want to do my best.",
	unlock = "What're you starin' daggers through me for? Are ya that excited about this new outfit? Alright, then feast your eyes on my fashion sense. Yeah, I didn't put it together just for your sake this time – more like to demonstrate my tastes.",
	touch2 = "You sure you ain't getting carried away? It being the New Year isn't an excuse to... Actually, do whatever you want.",
	mission = "Remember, you've got work waitin' for ya. It being a holiday ain't an excuse to slack off.",
	vote = "",
	drop_descrip = "What're you starin' daggers through me for? Are ya that excited about this new outfit? Alright, then feast your eyes on my fashion sense. Yeah, I didn't put it together just for your sake this time – more like to demonstrate my tastes.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "It's a new year... As long as you'll be here, I'll have something to look forward to. Is this what those Empery girls're talking about when they wish for \"peace in the years to come\"? Although, I'd hate it if I started becomin' reliant on you for... Nah, forget it. What matters is – I'm counting on you for another year, Commander.",
	main = "Sure, this is more fun than I thought, but I can't go 'round cheering like a little kid... You wouldn't mind it if I let my inner kid out? Well, I'll be the one to decide what I do.|A red envelope? Oh, is that how you give blessings to someone? Heheh. Alright, then how 'bout showing me how sincere you are?|A new year and a new beginning... So they say, but every day's new to me. What makes it different from the past ones is the fact that I have you now.",
	touch = "Don't get too ahead of yourself, now...",
	voice_key_2 = -1,
	mission_complete = "Looks like your rewards're ready. You're not gonna tell me to go and fetch 'em, are ya?",
	battle = "",
	id = 905014,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "I swear, people like you... Ugh. It's a holiday. I'll pretend you didn't do that.",
	feeling2 = "",
	login = "You're here. Well? Does this attire meet your standard? ...No, just asking out of curiosity.",
	detail = "While I do like this holiday spirit, don't expect me to dress up every single year... You'll help take photos next time around? Hah. You sure know how to get someone's hopes up.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[905020] = {
	hp_warning = "Oh my, I seem to have let my guard down.",
	feeling3 = "I see you're on your guard, just as always. Perhaps Jean Bart told you a little thing or two? ...Heehee, just as I thought. Speaking of which, Commander, how did the two of you get on such good terms? I expected her to be quite difficult to get along with, no?",
	mail = "A new letter has arrived. It's not urgent, so you can take a look after you've finished what you're working on right now.",
	expedition = "Take these gifts over to the girls in the commission fleet, won't you? ...Hm? When did I prepare them? Why, is that something you absolutely have to know? Heehee~♪",
	win_mvp = "With this one additional weight... the scales of victory tip ever in our favor.",
	home = "Shall we review our previous operational strategy? If time permits, why not try to ascertain an alternate possibility?",
	unlock = "If it isn't the Commander! I, Vichya Dominion battleship Clemenceau, am honored to fight by your side. I'm essentially a nobody compared to you and your world-renowned deeds. Now... Before we get to business, do you have any questions for me?",
	touch2 = "Hmm? Commander, do you really want me to exploit your weakness so badly?",
	mission = "There's still work left to finish. I'd assume it has already made its way onto your itinerary, yes?",
	vote = "",
	drop_descrip = "Richelieu-class battleship – Clemenceau.",
	feeling4 = "If you don't mind, Commander, could you tell me about some of your likes and hobbies? That way, I would be able to cater to you in all sorts of ways~ Heehee. Even if you don't feel like telling me, I could always ask some of our friends.",
	lose = "Oh my, it seems that I've been bested... But just so you know, I'm the type to hold on to grudges... Heehee~",
	feeling1 = "I see now. So, the upstanding Commander is just a made-up facade? Hmm... Au contraire, I actually find that quite dull.",
	skill = "Attendre et espérer.",
	upgrade = "Commander, don't forget to keep improving yourself as well, alright?",
	propose = "I'm an evil woman. Which is why I can do things like this without a second thought... For example, orchestrating a date, creating a time and place just for the two of us, or getting jealous over who you've been with– Heehee, can you handle someone like me?",
	feeling5 = "This port is truly a battlefield in its own right, seeing as how many of your companions are vying for you. By the looks of things, I won't be able to win over your attention without some ingenuity... Heehee. Commander, I do wonder, what do you think the odds of me winning are?",
	main = "Commander, you are both the director on the stage, as well as the staff working behind the scenes. Which role do you enjoy playing more? Or... does our Commander actually wish to be just another spectator? Heehee~|Enjoying one of the Royal Navy's elegant tea parties or downing vodka with the Northern Parliament are both effective methods of bridging the distance between parties. Though, vodka... can be a bit of a struggle...|Those who do not scheme enjoy the levity that comes with having nothing to worry about, whereas those who do enjoy the fruit borne by their plans. Having that said, it is not my place to judge. Regardless of who we are, we all have our ways of getting along with one another... Wouldn't you agree?",
	touch = "Oh my, Commander. You look like you want to ask something~",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Yet another item on the itinerary dispatched efficiently... So this is the Commander in work mode.",
	battle = "The curtains rise on a splendid play.",
	id = 905020,
	gift_dislike = "",
	gift_prefer = "How charming. Where did you learn to do this? Heehee.",
	profile = "I am the third of the Richelieu class, the never-completed Clemenceau. Unlike Richelieu and Jean Bart, who made a name for themselves, I was abandoned during that great war. However, my lack of history or honors is also my greatest asset – that's right, nobody ever notices the shadow lurking behind the curtains. Heehee~",
	voice_key = 90502,
	headtouch = "",
	feeling2 = "A person who is worthy of praise and adulation, yet is not revered as an idol... Is it because you walk alongside your troops? Hmm... how thought-provoking.",
	login = "Welcome back, our ever-so-sought-after Commander. Heehee, is there anything I might be able to help you with?",
	detail = "Whenever I want to play with the cute little Meowfficers, they naturally gather around. And as soon as I need to do something else, they will also leave on their own. Heehee... I suppose this is one aspect of me that makes Richelieu and Jean Bart green with envy~",
	couple_encourage = {
		{
			{
				80501
			},
			1,
			" I appreciate the prayer. Now, let us focus on the enemies in front of us.",
			0
		},
		{
			{
				90501
			},
			1,
			" Jean Bart, how long are you going to keep wearing your grumpy face?",
			0
		},
		{
			{
				69901
			},
			1,
			" Marco Polo, let's try not to get too ahead of ourselves~",
			0
		},
		{
			{
				90202
			},
			1,
			" Fighting angel Marseillaise, pass judgment upon the Holy Iris's enemies!",
			0
		},
		{
			{
				90201,
				90701,
				80107
			},
			3,
			" Seize victory, the Tribunal's way.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[905021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "You've received the commission rewards? Excellent, let's see if there's anything we can put to use.",
	win_mvp = "Phew, problem solved. I won't let any uninvolved parties get in the way of our leisure time.",
	home = "",
	unlock = "The skies are blue and the wind is calm, a perfect day for golfing... Commander? I didn't bring you here just to watch the scenery, you know? Brace yourself, because you're in for a long day with me.",
	touch2 = "Oh my, Commander. Your hands don't seem to be able to calm down.",
	mission = "",
	vote = "",
	drop_descrip = "The skies are blue and the wind is calm, a perfect day for golfing... Commander? I didn't bring you here just to watch the scenery, you know? Brace yourself, because you're in for a long day with me.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Commander, when I'm with you, I feel a sense of safety that makes all the thoughts in my head go poof. ...Oh, you too? What if I told you, I was just telling you what you wanted to hear? Heehee. Hey, Commander... Don't let yourself get fooled by the sweet flattery of other bad girls~",
	main = "Hmm? I'm measuring the wind speed. Or, would you rather me say... that I'm enjoying the warm, gentle breeze?|Don't worry too much, and play however you see fit. This isn't a competition, so relax a bit.|Richelieu holds back too much, worrying about where the ball might fly off to. Jean Bart swings too hard, without worrying about anything at all. Looks like fun, doesn't it?",
	touch = "",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Looks like our precious leisure time will be cut short.",
	id = 905021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Let's start from here. Why don't you show me what kind of condition you're in today?",
	detail = "If you're getting tired of swinging the golf club, why don't we take the cart around and enjoy the scenery? Heehee, and of course, you'll be the one driving.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[905030] = {
	hp_warning = "Combat protocol engaged.",
	feeling3 = "Emotional activity was detected during musical performance on stage. Requesting investigation into origin of this phenomenon.",
