_G.pg.base.ship_skin_words[900004] = {
	hp_warning = "",
	feeling3 = "Reconnaissance is a very important task! Eh, losing focus? Wh-what are you saying, I'm just ob-observing the weather.",
	mail = "Commander...ehh, what did I want to say...ahh, yes, new mail!",
	expedition = "This cloud looks like cotton candy...hmm? Ahh, Commander, Commission team is back~",
	win_mvp = "Wow that cloud looks like...ehh, we won?",
	home = "Good work commander, want a cup of tea?",
	unlock = "Where is this place... Ah, hello! You're the Commander? I'm Suffolk. I've finally found you!",
	touch2 = "...Aah, Commander! Say something if you're here.",
	mission = "The weather sure is nice... Oh? Commander! You've got some new missions.",
	vote = "",
	drop_descrip = "Kent-class heavy cruiser—Suffolk, Hull Number 55!",
	feeling4 = "My elder sisters are very strong, I would be happy if only I could assist them~Eh, I'm worked hard? Ehehe, I got praised~",
	lose = "Wuu...if only I paid more attention.",
	feeling1 = "...the sky is so blue.",
	skill = "What a beautiful seagull...",
	upgrade = "If you get lost again, you can protect yourself.",
	propose = "Hng hng, commander finally noticed the shining spot hidden underneath my woozy appearance! From now on I can be as lazy as I want...ehh, I can't?...",
	feeling5 = "Although I'm happy when praised by other people, now whenever I can assist Commander, I feel even happier, why is that...",
	main = "I'm always like this! I've got to explore before I find a place I like.|Commander, want to watch the clouds with me? I bet we'll see wonderful things!|Don't look at me like that. I've been to plenty of places before!",
	touch = "...............Mmmh, Commander?",
	voice_key_2 = -1,
	mission_complete = "Commander! How could you forget to collect your mission rewards?",
	battle = "The enemies look quite strong...",
	id = 900004,
	gift_dislike = "",
	gift_prefer = "",
	profile = "I'm the fifth ship of the Kent-class, Suffolk.\nDon't judge me by my looks! I'll be your go to ship whenever a critical moment comes. You know I basically saved the day at the Denmark Strait!",
	voice_key = -1,
	headtouch = "",
	feeling2 = "Mmhmm, the weather is nice, it's weather suitable for going out for recon at sea~ Commander you want to come together?",
	login = "Commander, you're back! Me? I'm looking at the clouds.",
	detail = "Before and after the modernization of the data is much worse!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[900005] = {
	hp_warning = "",
	feeling3 = "Commander...can you tell more stories to Norfolk...this time I brought a fairy tale book I want to listen to...",
	mail = "...new mail, I'm a bit jealous of Commander...",
	expedition = "Seems like commissions are done!",
	win_mvp = "Is it alright to give me such a rating?...",
	home = "Commander...if you don't mind, let Norfolk massage...wuu, forget about it...",
	unlock = "He- hello, Commander, I'm Norfolk...umm...uhh...hmm...please take care of me...",
	touch2 = "Ahh, Commander...baddie...",
	mission = "Some new missions are available... Want to take a look, Commander?",
	vote = "",
	drop_descrip = "Norfolk-class heavy cruiser—Norfolk, Hull Number 78!",
	feeling4 = "Commander...Norfolk is afraid of the dark, I can't sleep...can I sleep with the Commander...?",
	lose = "Wuwuwu...I'm not suitable for combat afterall...",
	feeling1 = "Wuu...",
	skill = "Norfolk will try her best...",
	upgrade = "Commander gives Norfolk so much courage...",
	propose = "Mmm...Norfolk wants to stay forever and ever by Commander's side as well...",
	feeling5 = "Commander's body is so warm...can Norfolk stay here forever?",
	main = "I... don't like winter...|My name carries... quite the weight... with it...|It's best... to try and... get along with everyone...",
	touch = "Did Norfolk do something wrong...?",
	voice_key_2 = -1,
	mission_complete = "Commander, your mission rewards are ready. Want me to pick them up for you?",
	battle = "Norfolk...will do her best...",
	id = 900005,
	gift_dislike = "",
	gift_prefer = "",
	profile = "Norfolk is ... That one...... The third batch of county heavy cruisers ... Whoa, commander, don't stare at me ... However, when the Danish strait was the antenna was frozen ... No, not because of cowardice!",
	voice_key = -1,
	headtouch = "",
	feeling2 = "Commander...why did you call for Norfolk——anything I want to do...? I...want to hear Commander tell a story...is that ok?",
	login = "Commander, welcome back...",
	detail = "So embarrassing...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[900006] = {
	hp_warning = "Even I am slightly angered.",
	feeling3 = "I talk about being refined at all times, but Commander need not to force yourself to comply. Your normal self is most charming.",
	mail = "It's unopened... Commander, it's not gentlemanly to ignore messages from others, you know?",
	expedition = "Completing commissions is also a show of honor, will you not treat those children?",
	win_mvp = "The warm sun, the cool breeze, a brilliant victory.",
	home = "Commander, is the tea ready? Let's taste it while we review.",
	unlock = "Greetings, Commander. As the pride of the Royal Navy, Hood comes with victory.",
	touch2 = "Commander should know very well the consequences of disrespecting a lady... are you prepared?",
	mission = "Commander, you've got a new mission. Take a look, would you?",
	vote = "",
	drop_descrip = "Admiral-class battlecruiser, Hood, Hull Number 51!",
	feeling4 = "Hm? Too close? While a lady must be elegant, they take the initiative towards their love, you know?",
	lose = "Victory and defeat are commonplace among those who fight, and we have all the time in the world.",
	feeling1 = "Sigh, seems like you have to learn it the hard way.",
	skill = "Elegant, but not breakable like a vase!",
	upgrade = "Your efforts will be rewarded.",
	propose = "Haha, you cannot express your feelings to a lady this nervously. But your feelings have reached my heart... it is Hood's pleasure.",
	feeling5 = "Shall I compare thee to a summer day? Thou art more lovely and more temperate... So long as I can breathe, or eyes can see, so long lives this poem, and this gives life to thee... A beautiful verse, could Commander read this for me?",
	main = "An outstanding commander must have an in-depth knowledge of tea.|This word is... ah, so I read it wrong. Sorry, my vision isn't very sharp.|Listen more, speak less. You should listen to others' opinions, but retain your own judgments.",
	touch = "Appropriate contact is indeed essential, shall we dance?",
	voice_key_2 = -1,
	mission_complete = "Glory comes with reward, do not forget the latter.",
	battle = "Glory is ours.",
	id = 900006,
	gift_dislike = "",
	gift_prefer = "",
	profile = "Indeed, the pride of the Royal Navy stands before you.\nTo be refined at all times is the upbringing of a royalty. The Denmark Strait? Victory and defeat are commonplace among those who fight. That was but a single failure.",
	voice_key = -1,
	headtouch = "",
	feeling2 = "Commander, it's such a great afternoon, shall we have a chat? ...Hm, alright, I'll talk about the times when I was with Renown.",
	login = "Welcome back, Commander. Care for a cup of tea?",
	detail = "The pride of the Royal Navy, admire as you wish.",
	couple_encourage = {
		{
			{
				20401
			},
			1,
			"prestige, do not wander again",
			0
		},
		{
			{
				20402
			},
			1,
			"keep the Etiquette, counterattack",
			0
		},
		{
			{
				20501
			},
			1,
			"at your service, Your Majesty",
			0
		},
		{
			{
				2
			},
			5,
			"Go ahead, we are Royal Glory",
			3
		}
	}
}


_G.pg.base.ship_skin_words[900007] = {
	hp_warning = "Get up! We're looking for a fight!",
	feeling3 = "You never know how many plans, hopes, and efforts would sink into the sea with you, Commander. Don't die too easily.",
	mail = "You have a new message, Commander.",
	expedition = "Commissions complete! Please welcome the fleet home.",
	win_mvp = "Success is gratifying every single time.",
	home = "Sometimes victories come down to nothing but luck. Don't get too full of yourself, Commander.",
	unlock = "You're the Commander? Very well. I, Prince of Wales, shall let you witness my true strength.",
	touch2 = "You know what this touch means, don't you?",
	mission = "It's time to test your resolve, Commander.",
	vote = "",
	drop_descrip = "King George V-class battleship, Prince of Wales. Hull Number 53.",
	feeling4 = "Fighting with honor is my motto. I wish it could be the same when it comes to love. So... can you stay with me a bit longer? I have something important to tell you, Commander...",
	lose = "A horse may stumble even though he has four legs. Let's try again next time.",
	feeling1 = "Keep your distance. You are not qualified to command me...",
	skill = "It's a showdown!",
	upgrade = "Let's not repeat failure again...",
	propose = "To me, the ritual isn't as important as the fact that you've already recognized our love... However, receiving such a wonderful gift still makes me happy. Thank you, Commander... I'll keep this with me forever!",
	feeling5 = "I had a dream, a dream of that time which makes me feel hopeless even now... But when I open my eyes and see you by my side, it feels like life... like life isn't so bad after all...",
	main = "Expensive isn't always better, but it's your job to maximize our combat capability, Commander.|I don't want to suffer the pain of losing comrades...|Would you like to have some tea? I have a sandwich as well. I'm a big fan of pickles, you know!",
	touch = "Let's have chat, Commander.",
	voice_key_2 = -1,
	mission_complete = "Rewards delivered! You performed beautifully.",
	battle = "Acts of bravery beget success... All ships, open fire!",
	id = 900007,
	gift_dislike = "",
	gift_prefer = "",
	profile = "I'm the second ship of the King George V-class battleships, the Prince of Wales. I once escorted the Prime Minister to sign the Atlantic Charter. I turned a new page in the history books of weaponry? Hmph, how dare you mention that in front of me.",
	voice_key = -1,
	headtouch = "",
	feeling2 = "I heard that my current name was chosen because my original one could bring misfortune, but... judging by how things turned out... it seems I'm unable to escape my fate...",
	login = "Welcome back. Shall we have tea before getting back to work?",
	detail = "Fate can be easily derailed, Commander.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[900040] = {
	hp_warning = "I don't want... to be alone...",
	feeling3 = "Commander, you're always saying that my ears are cute... But why won't you touch them?",
	mail = "There's... new mail...",
	expedition = "Commander, a commission has finished.",
	win_mvp = "MVP? I don't really get it, but... thanks.",
	home = "Commander, you're a little like me on the battlefield... That's... pretty cool.",
	unlock = "I'm... Ayanami. I am often called the \"Demon.\" Pleasure to meet you.",
	touch2 = "Commander... please... don't touch there so much... It's making me feel weird...",
	mission = "Commander, we've been notified of new missions.",
	vote = "",
	drop_descrip = "First ship of special Type II {namecode:6} class destroyers, {namecode:6}.",
	feeling4 = "If there's one thing that worries me... it would be when you are not at my side.",
	lose = "It's okay... I'll recover quickly.",
	feeling1 = "I don't really want to get any closer.",
	skill = "Bear witness to the true power of the \"Demon\"",
	upgrade = "My power is overflowing...",
	propose = "Rest assured... This time, no matter what happens, I'll survive and return to you... because I'll always want to see you again...",
	feeling5 = "I don't particularly... like or dislike combat. I just do what must be done. But if it's for you, Commander... maybe I can get a bit stronger.",
	main = "{namecode:6}'s ears... are they cute? I don't understand... As long as you're happy, Commander!|I've been having nightmares of all the girls getting lost... I'm certain that it's my fault, too...|Commander? No, nothing. I just wanted to see if you were here or not.",
	touch = "Uuu... it tickles...a bit.",
	voice_key_2 = -1,
	mission_complete = "The rewards for the previous mission are here.",
	battle = "Want to go... to Solomon?",
	id = 900040,
	gift_dislike = "",
	gift_prefer = "",
	profile = "I am Ayanami, an improved Fubuki-class destroyer. I am not afraid of combat. Though just a destroyer, I can fight any enemy...",
	voice_key = 30105,
	headtouch = "I don't really get it but... I'm a bit happy...",
	feeling2 = "Ayanami's impressions of Commander? I don't really know.",
	login = "Commander, have you eaten yet? Here's some snacks.",
	detail = "I've inspected the communication equipment. It won't cause any more problems...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[900041] = {
	hp_warning = "Be still as water...!",
	feeling3 = "It might be pretty nice to just set aside my duties and have a relaxing conversation with you every once in a while, Commander.",
	mail = "Commander, there's new mail. Shall I bring it for you?",
	expedition = "Your fleet has returned from commission. Want to welcome them back?",
	win_mvp = "Hm... Once again, I've cut a worthless object.",
	home = "I'm glad that you came back safe and sound.",
	unlock = "Are you the Commander? Please allow this lowly {namecode:66} to offer you what little strength she has.",
	touch2 = "Kyaa! You scared me... how shameless!",
	mission = "New tasks have been assigned - would you like to confirm them?",
	vote = "",
	drop_descrip = "First ship of the {namecode:66}-class heavy cruisers, {namecode:66}.",
	feeling4 = "Recently, I haven't been able to keep my composure during training.. Just from thinking about you, my form becomes sloppy. If I am like this, would you still want to keep me by your side?",
	lose = "I was careless... I definitely will not fail next time!",
	feeling1 = "A sword has no eyes. It would be wise to avoid approaching me casually.",
	skill = "Swift death unto evil!",
	upgrade = "Power... flows through my blade!",
	propose = "For you to acknowledge me like this, Commander, is the greatest honor. From now on, this blade shall serve only you. Please continue to treat me kindly.",
	feeling5 = "No matter how badly I'm injured, I will make sure to always return to your side. So... Commander, could you always stay with me as well?",
	main = "Even back in port, we must not lower our guard. Danger lurks around every corner.|Commander, not even you could withstand my blade.|Daily refinement means to continually strive towards your goals. Commander, may your focus never falter.",
	touch = "E-enemies?! Oh... It was you, Commander? Apologies - my eyesight isn't the best.",
	voice_key_2 = -1,
	mission_complete = "Mission accomplished! Are we going to collect the rewards?",
	battle = "Please leave combat to me. I shall not shame my title of being \"The Strongest!\"",
	id = 900041,
	gift_dislike = "",
	gift_prefer = "",
	profile = "I am {namecode:66}, first ship of the {namecode:66}-class heavy cruisers. I may not look like it, but I have already crossed through countless battlefields. Please place your faith in my firepower and armor, and be at ease.",
	voice_key = 30311,
	headtouch = "",
	feeling2 = "Do you need anything? If not, I'm going back to work.",
	login = "{namecode:66} standing by. What are your orders?",
	detail = "Small strokes fell great oaks, constant drops pierce through rock. Those who train through the most humdrum of days shall seize victory in the most critical of moments. That is my belief.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[900042] = {
	hp_warning = "Looks like big sis needs to get a little serious.",
	feeling3 = "Commander, would you like me to clean your ears? Come on, don't be shy. Just leave it to me~",
	mail = "Ara~ new mail? I wonder who it's from.",
	expedition = "The commission fleet is back! Let's go give them a warm welcome.",
	win_mvp = "Combat operations... complete! It's all thanks to your leadership, Commander!",
	home = "Welcome back, Commander. Are you tired? Come bury yourself in big sister's bosom~!",
	unlock = "Oh my, what a cute commander! Please allow your big sister {namecode:67} to take good care of you from now on!",
	touch2 = "You can touch me even more if you'd like... but there's no saying what might happen next... *giggles*",
	mission = "Missions have been updated. Don't forget to take a look!",
	vote = "",
	drop_descrip = "Second ship of the {namecode:66}-class heavy cruisers, {namecode:67}.",
	feeling4 = "It's all your fault, Commander... If you make such a cute face, I won't be able to keep my hands off of you...",
	lose = "Oh my... this is a bit troublesome...",
	feeling1 = "You've been naughty, Commander. Do you want to be punished so badly? *giggles*",
	skill = "Oh my, how should I torment you today?",
	upgrade = "My whole body feels... hot... Commander, can you stay with me for a bit?",
	propose = "Oh my, you've caught me, Commander. Or should I say, I've finally caught you? Hehe~ I'll never let you go now!",
	feeling5 = "It's no good... I can't control myself anymore! Commander, won't you become mine? You don't have to worry about anything... All you have to do is listen to me, and I'll satisfy all your needs...",
	main = "It seems like... my shoulders are always sore...|Commander~ I can see you ogling me in a daze, you know?|Hup! A little bug got into the room. You didn't see it? I'm confident in my good eyesight.",
	touch = "Oh my~ Are you going to give me a massage?",
	voice_key_2 = -1,
	mission_complete = "Mission complete! I wonder what rewards we will get~?",
	battle = "Naughty children need to be punished~",
	id = 900042,
	gift_dislike = "",
	gift_prefer = "",
	profile = "I'm {namecode:67}, the second ship of the {namecode:66}-class heavy cruisers and flagship of the Second Fleet. Many of my sisters have followed my banner into battle. No matter the mission, just leave everything to big sister here~!",
	voice_key = 30312,
	headtouch = "",
	feeling2 = "If you don't express your thoughts clearly, Commander, nobody will ever understand you.",
	login = "Welcome back! What should we do today?",
	detail = "You shouldn't ask about a maiden's weight so casually~ *giggles*",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[900043] = {
	hp_warning = "Pump water to the other side! Hurry!",
	feeling3 = "Do I hold a grudge against the First and Second Carrier Divisions? Of course~ For them to leave us behind like that, wouldn’t anyone complain in that situation?",
	mail = "We’ve got mail from HQ, they told us to carry out the Decisive Battle Doctrine. Heh, just kidding~!",
	expedition = "This is all required to carry out the Circle Five Plan.",
	win_mvp = "The Glory of the 5th Carrier Divison is here! *giggles*",
	home = "The girls have returned safely to port, just like the Fifth Carrier Division always does.",
	unlock = "As the flagship of the Fifth Carrier Division, I, Shoukaku, shall do my best to become as good as those esteemed senpai in the First Carrier Division, or something... *giggles* That was on purpose~",
	touch2 = "Commander, come and indulge yourself in {namecode:95}'s tenderness.",
	mission = "Let me take a look the mission... It’s not the Coral Sea? That’s too bad~",
	vote = "",
	drop_descrip = "First ship of the {namecode:95}-class aircraft carriers, {namecode:95}.",
	feeling4 = "Those senpai are so sly! Just when I was about to overtake them, they went somewhere I could never reach! How unfair!",
	lose = "Hiryuu-senpai may be willing to fight until the bitter end, but... that’s not my style. What a shame~",
	feeling1 = "I think I just saw a future in which you were cut down by {namecode:91}, Commander.",
	skill = "This is the privilege of being the elder sister!",
	upgrade = "Now, I can protect {namecode:96} better!",
	propose = "The melody of my flute is like a flowing river, requiring an inspiration that usually can only be found atop a mountain. Just being by your side, however, inspires me even more.",
	feeling5 = "Commander, could you lend me your shoulder? Sometimes, even I want to simply clear my mind and rest. When I get like that, can I depend on you to be by my side?",
	main = "To always be dealing with those senpai from the First Carrier Division... Commander, you must have a really strong liver.|Though our relationship was once one of victim and perpetrator, I look forward to working with you, Lexington.|{namecode:96}, if you keep causing trouble for our Eagle Union colleagues, you’ll only get tempura for dinner tonight~",
	touch = "Commander, would you like to hear me play my flute?",
	voice_key_2 = -1,
	mission_complete = "We’re not going to carry out our plans of attrition warfare? Tch~",
	battle = "The perfected aircraft carrier, {namecode:95}, setting sail!",
	id = 900043,
	gift_dislike = "",
	gift_prefer = "",
	profile = "I am {namecode:95}, the flagship of the Fifth Carrier Division. Because my super smart senpai went and got themselves all killed, I had to carry the flag of the Sakura Empire’s carrier divisions. Though I was more accomplished than them, for whatever reason, I was always considered weaker. Maybe it was due to my \"lack of grace and speed\" during my final moments... With that said, allow me to reintroduce myself. I am Shoukaku, the punching bag of the Sakura Empire. Please take care of me from now on~",
	voice_key = 30705,
	headtouch = "",
	feeling2 = "My sister {namecode:96} and I held on for two years during the darkest of times. If only our senpai could have worked a little bit harder.",
	login = "Intelligence is said to be a woman’s virtue, but that often puts me at odds with those senpai of mine. How troublesome~",
	detail = "The melody of my flute is a requiem for the dead. Shall I play it for you?",
	couple_encourage = {
		{
			{
				30706
			},
			1,
			"{namecode:96}, give it your all! I'll cover you!",
			0
		},
		{
			{
				30701
			},
			1,
			"Do you see my true power, {namecode:91}?",
			0
		},
		{
			{
				30702
			},
			1,
			"This time... I'll prove to you how powerful I really am!",
			0
		},
		{
			{
				10702
			},
			1,
			"I won't be able to protect you if you stray too far!",
			0
		},
		{
			{
				10703
			},
			1,
			"Where is the Queen of the Docks heading to?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[900044] = {
	hp_warning = "Shoukaku... Is Shoukaku all right?",
	feeling3 = "My fate always seems to be entertwined with Lexington’s... Ah~ Commander, please don’t tell Sara I said that. I can’t handle that girl.",
	mail = "So? Is it good news or bad news?",
	expedition = "If only I had more planes...!",
	win_mvp = "I am the auspicious crane, after all!",
	home = "I’ll need you to perform some maintenance on me. Ah, don’t forget about the planes either!",
	unlock = "I am {namecode:96}, the last elite of the Sakura Empire’s Carrier Divisions. I can only be at my best when I am with my sister {namecode:95}.",
	touch2 = "Commander, {namecode:95}’s are larger and softer...",
	mission = "Is it time for a break? Commander, you should come try some of {namecode:95}’s cooking!",
	vote = "",
	drop_descrip = "Second ship of the {namecode:95}-class aircraft carriers, {namecode:96}.",
	feeling4 = "Whenever I feel irritated or lost, training always makes me feel at ease. Yes, I’ll definitely get stronger and catch up to that Grey Ghost one day.",
	lose = "Am I going to be sunk... again...?",
	feeling1 = "Commander, would you like a taste of the anguish I experienced during the Battle of the Marianas?",
	skill = "As long as Shoukaku is with me~!",
	upgrade = "As a perfected aircraft carrier, I shall not lose to anyone, not even to my seniors or to the Grey Ghost herself.",
	propose = "E-eh?! Th-this is... I’m not misunderstanding you, right? Then... um, from now on, I’ll be in your care, dar... darling? Waaah! Shoukaku is calling me!",
	feeling5 = "Commander, you make me feel just as if I am with Shoukaku. H-huh? That’s not it! I’m not treating you as my sister!",
	main = "{namecode:95} is so cute when she’s embarrassed!|Keep fighting until the last arrow is broken! That is what it means to be an elite!|Wait, Grey Ghost, don’t run away just because you won! Let’s have a rematch!",
	touch = "My least favorite food? Turkey, of course.",
	voice_key_2 = -1,
	mission_complete = "Hmm... Seems like the situation has taken a turn for the better!",
	battle = "A never-ending swarm of enemies? I’m already used to it.",
	id = 900044,
	gift_dislike = "",
	gift_prefer = "",
	profile = "I’m {namecode:96} from the Fifth Carrier Divison, though I was assigned to the First Carrier Division at one point. Together with my sister Shoukaku, we became the last two elite carriers of the Sakura Empire. We triumphed in bitter battles against Lexington, Hornet, and even Enterprise. That’s right, I was even able to severely damage the Grey Ghost herself, although she proved to be luckier than me. My service came to an end when Lexington, risen from the dead, sunk me. In the end, I still completed my final mission and sank with no regrets.",
	voice_key = 30706,
	headtouch = "",
	feeling2 = "Seniors and juniors... they’re all such a pain.",
	login = "Where are we going today? Pearl Harbor? Or perhaps the Coral Sea?",
	detail = "That Grey Ghost... I’d like to duel her just once.",
	couple_encourage = {
		{
			{
				30705
			},
			1,
			"I'm fearless, as long as my sister is with me!",
			0
		},
		{
			{
				10204
			},
			1,
			"I don't know why, but I just find you terribly annoying...",
			0
		},
		{
			{
				10702
			},
			1,
			"That ties up the score. Next round decides the winner!",
			0
		},
		{
			{
				10703
			},
			1,
			"Uwah! When did you get here?!",
			0
		},
		{
