_G.pg.base.ship_skin_words[900249] = {
	hp_warning = "",
	feeling3 = "I love my sister, but she's a bit too quiet sometimes. Milord, I like spending time with you more because you'll play with me!",
	mail = "Milord! Milord! Your mail is here!",
	expedition = "Milord, the girls have returned from commissions!",
	win_mvp = "Milord, did you see that? Did you?",
	home = "Welcome back, Milord, I made you some tea... Woah! Watch out!",
	unlock = "Woah! It's Milord! Milord in person! Um... I'm Yamahi-, {namecode:79}! I am pleased to make your acquaintance.",
	touch2 = "Woah! Watch out, Milord! I'm about to fire my main gun!",
	mission = "Milord! New missions!",
	vote = "",
	drop_descrip = "Second ship of the {namecode:78}-class battleships, {namecode:79}.",
	feeling4 = "Your Majesty, do you know this mask? It's a fox mask used in Kagura. Hehe, I'm actually about to practice my Kagura dance now. Do you want to watch?",
	lose = "Uu... Sister... where are you? *sobs*",
	feeling1 = "You're so boring, Milord. I don't want to play with you anymore.",
	skill = "Ammo storage looks good... Alright!",
	upgrade = "I've gotten stronger... I think!",
	propose = "Milord? You're going to give this to me? ...Even though I am slow-footed and far from perfect? Milord, you are far too kind. I love you too.",
	feeling5 = "I know how hard my big sister works, so for her sake, I know that I should allow myself to be happy. That way, I can share my happiness with her. Now that you are here, Milord, I think I'll finally be able to do that. I feel so happy every time I see you!",
	main = "",
	touch = "Milord... that tickles!",
	voice_key_2 = -1,
	mission_complete = "Milord, milord! I've brought the rewards... Oops!",
	battle = "Everyone, go~! Waaah?! My guns fired on accident!",
	id = 900249,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 30502,
	headtouch = "",
	feeling2 = "Milord, come play with me! Ah... I forgot to bring stuff to play with... what should we do?",
	login = "Milord, milord! What shall we do today?",
	detail = "Milord, you smell really nice~",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[900250] = {
	hp_warning = "Sisters, hold on!",
	feeling3 = "If you’re only going by appearances, every child in this fleet looks cute. But in terms of personality, they all have their unique quirks. To be honest, I am a bit envious of them. (strokes chin).",
	mail = "You’ve got new mail~",
	expedition = "The commission is over, they should be back soon~",
	win_mvp = "If the Commander gives me a few praises, then I will be very happy~",
	home = "Ah, hold on, your collar is all messed up. Stand still while I fix it... there you go~ (waves).",
	unlock = "North Carolina here, awaiting your dispatch. Although I may seem to have a bland personality compared to my sisters. But as the saying goes, no personality is still a personality, hehe. Anyways, awaiting your orders, sir.",
	touch2 = "Not good...",
	mission = "It’s not good to leave tasks unfinished.",
	vote = "",
	drop_descrip = "North Carolina class battleship— North Carolina, hull number BB-55.",
	feeling4 = "I always believe there is nothing wrong with being ordinary. But after meeting you Commander, I want to change myself a little... after all, my sisters are all so charismatic~ Well.. Commander, are you fond of bunny girls?~",
	lose = "Not so successful... let's try again next time.",
	feeling1 = "Commander, I'm gonna get angry.",
	skill = "Never let your guard down.",
	upgrade = "I'll try to work a bit harder~",
	propose = "Well, your trust deserves to be rewarded... umm... Commander, do you like bunny girls?~",
	feeling5 = "",
	main = "",
	touch = "Do you need help with something?",
	voice_key_2 = -1,
	mission_complete = "The mission rewards were sent out, are you not going to pick it up?",
	battle = "Don’t be overconfident, and try not to be so nervous while focusing on winning~",
	id = 900250,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 10512,
	headtouch = "",
	feeling2 = "Commander remembers me~ Not that I’m boasting or anything, but I still have confidence in my low sense of existence. (smiles wryly)",
	login = "Welcome back~",
	detail = "Being stared like that makes a bit shy...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[900251] = {
	hp_warning = "I won't let go of victories to my enemies!",
	feeling3 = "No, no, that’s not right. If we do it this way, won’t it end much the same like in the past? … Don’t try so hard? You sometimes say stuff like that… Hmm? That was a good smile from me just now?",
	mail = "Hey, your mail.",
	expedition = "Your memory can’t be worse than mine, right? The commission fleet has returned, won’t you go greet them?",
	win_mvp = "Sure enough, I am happiest when all the foes are annihilated~",
	home = "I’m glad that you didn’t get hurt—— What?! I don’t have feelings for you!",
	unlock = "Hello, Commander, I am Washington... my sister told me that I cannot be so rough once I join the fleet, so I am practicing my smile. Darn, why must I listen to her...",
	touch2 = "...You wish to die? (Smiles)",
	mission = "A new mission? Haha, now my blood is boiling.",
	vote = "",
	drop_descrip = "North Carolina class battleship— Washington, hull number BB-56.",
	feeling4 = "Lately, my smile has become more natural? Emm, huh (scratches head), I was recently trying to find a new hobby. While I was searching, I realized that being with you is not so bad… (whispers)",
	lose = "Oh, I will not forget you!",
	feeling1 = "You are too weak, it’s no fun playing with you, go practice some more.",
	skill = "Out of my way. I'm ready to fight!",
	upgrade = "It feels so good to become stronger.",
	propose = "Wait wait! We’re doing “that”, right? Is this your new way of teasing me!... Damn, you bastard, I’m not sure if I should cry or laugh about this...",
	feeling5 = "",
	main = "",
	touch = "Don’t touch me as if you’re trying to be intimate with me.",
	voice_key_2 = -1,
	mission_complete = "Go grab the reward yourself, I’m not interested.",
	battle = "Ok, let’s work out. (Snickers)",
	id = 900251,
	gift_dislike = "",
	gift_prefer = "",
	profile = "North Carolina class ship no. 2. I am Washington! The thing I like to do the most is to destroy my enemies. Recently, I am practicing on my smile. —— Battle record? I don’t really show off with such things, all in all, how’s my smile?",
	voice_key = 10513,
	headtouch = "",
	feeling2 = "What must I do to possess a good smile... think about the things I like? If so, I feel very happy even at the thought of winning against South Dakota... muahahaha...",
	login = "Welcome back... how does my smile look? (Forcibly smiles)",
	detail = "Hmm, you want to know how well I fight?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[900252] = {
	hp_warning = "Interesting...!",
	feeling3 = "All the lights in the sky are stars, just as all the lights on the seas are enemies... Commander, will there be a day where there's no more fighting?",
	mail = "Commander, it's a new mail.",
	expedition = "I've been on the battlefield for a long time, so I know about the importance of logistics. Commander, let's greet the girls who work hard behind the scenes.",
	win_mvp = "Commander, tell me. How many more do I have to sink?",
	home = "It's one battle after another, huh...",
	unlock = "Second ship of the Yorktown class, Enterprise, reporting for duty. I will neither sympathize nor hold back with my enemies, and instead, I go all out. Such is my way.",
	touch2 = "What the...?!",
	mission = "Commander, your missions are not yet completed.  Hurry up and set off!",
	vote = "",
	drop_descrip = "Yorktown-class aircraft carrier ー Enterprise, Hull Number CV-6!",
	feeling4 = "There's no meaning in being peerless. As long as you are here, Commander, I can draw upon all of my strength. Let us end this war.",
	lose = "I've lost after giving my all. I'm not regretting this...",
	feeling1 = "...Commander, you don't seem to have enough courage",
	skill = "It's over!",
	upgrade = "I will show you... what lies at the end of power",
	propose = "I carry with me the hopes and wills of the countless battlefields and goodbyes that I have experienced. Commander, are you prepared to shoulder them all? …I see. Then let us walk together until the end of our lives.",
	feeling5 = "What do you want to do after the war? --Me? I'll probably stick with you. I feel the safest out of battle when I'm with you. Will you... take me along with you?",
	main = "",
	touch = "What is it? Sortie time?",
	voice_key_2 = -1,
	mission_complete = "Commander, the rewards are here.",
	battle = "Venture forth!",
	id = 900252,
	gift_dislike = "",
	gift_prefer = "",
	profile = "I am the Yorktown class aircraft carrier, Enterprise. \"Grey Ghost\" is one of the many nicknames I have. My smoke-covered and bloodstained battle record is a reminder of my mission. I will continue to be victorious until the war ends.",
	voice_key = 10706,
	headtouch = "",
	feeling2 = "It is my wish to live honestly and sincerely. That's why I'll speak my mind if I have something to say. You too should do the same without holding back.",
	login = "You've come. If it's fighting, I'm ready for it any time.",
	detail = "Want to look at my medal collection?",
