_G.pg.base.ship_skin_words[900262] = {
	hp_warning = "Hmph, how interesting!",
	feeling3 = "How's that, commander? Are you impressed by my cooking abilities? Here, have as much you desire. Seeing you enjoy my food pleases me.",
	mail = "A letter, huh? Now then, is this a challenge, or a love letter?",
	expedition = "There's some commotion by the port...? Oh, it seems to just be the commission team returning.",
	win_mvp = "Make no mistakes. I shall ensure both victory and the safety of all my comrades.",
	home = "Commander, did you thoroughly enjoy the battle?",
	unlock = "So this is my new battlefield. Ahh, how I've long awaited this... By the way, are you my commander? You are in the presence of King George V – do use me well.",
	touch2 = "Ohh? I wasn't aware that you possessed such audacity, Commander.",
	mission = "New missions, eh? It would be ideal if we got something a bit more challenging.",
	vote = "",
	drop_descrip = "King George V-class battleship – King George V.",
	feeling4 = "Commander, so you're learning how to cook? Hmm, colour me impressed. I look forward to trying the dish that you're making for me.",
	lose = "Do not be demoralized. Neither victory nor defeat are decided by a single battle.",
	feeling1 = "I favor those of character, and those who can cook. Commander, you are neither.",
	skill = "The glory of the sun that never sets shall not fade!",
	upgrade = "Hmm... I suddenly feel like having a lavish feast.",
	propose = "They say that \"the quickest way to one's heart is through their stomach,\" but you've managed to win over both at once. Commander, shall we share all our meals together from now on?",
	feeling5 = "My greatest hobbies in life are food and fighting. While I am more than capable of fighting alone, dining by myself is quite difficult and lonesome. To be able to find someone who can share both of these things with me is truly a joyous thing.",
	main = "",
	touch = "Why do I have a mountain of snacks before me? Isn't it obvious? One cannot move on an empty stomach.",
	voice_key_2 = -1,
	mission_complete = "Supper tastes best after the day's missions are all complete. Wouldn't you agree, Commander?",
	battle = "Let us go forth and plant our banners!",
	id = 900262,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 20505,
	headtouch = "",
	feeling2 = "By the way, Commander, are you a good cook? Hmm? Despite my appearances, I've spent many hours honing my skills to sate my own appetite.",
	login = "Commander, did you already partake of supper?",
	detail = "My standing within the Royal Family? Hmm... If I had to draw a comparison, I'd say \"Knight Commander\" would be the most fitting... Hahaha...",
	couple_encourage = {
		{
			{
				20506
			},
			1,
			"Wales, you'd better not suddenly leave me again!",
			0
		},
		{
			{
				20507
			},
			1,
			"York, let us shatter our enemies together.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[900263] = {
	hp_warning = "So this is how harsh the battlefield can be.",
	feeling3 = "I'm not very elegant? I'm sorry that I'm not like Hood or the others... No... I'm not talking about my body...",
	mail = "You've got mail, Commander!",
	expedition = "Commissions? I suppose I do miss running around on errands... Let's go. We need to welcome back those hard workers!",
	win_mvp = "Don't be confined by the so-called \"limits\". It is indeed possible to be unsinkable!",
	home = "Whew, not a bad fight. Let's rest for a while.",
	unlock = "Greetings, I'm Warspite. I hold the record for the longest ranged hit on a moving target. Surprised? I'm smaller than you thought? Looks like we need to have a long talk...",
	touch2 = "Just so you understand, I'm definitely not that sort of, erm...",
	mission = "Accept your new mission and then get ready to head out, Commander!",
	vote = "",
	drop_descrip = "Queen Elizabeth-class battleship - Warspite, Hull Number 03!",
	feeling4 = "How do I put this... I'm considered to be one of the older girls, yet my body is like this... It might be unbecoming of one my age to compete with the younger girls, but I wanted to at least be attractive to you… What is a lady meant to do…",
	lose = "My damage control isn't functioning?! I've lost control of my steering wheel as well! Why now, at such a critical moment?!",
	feeling1 = "Would you please not act like we're close...",
	skill = "Belli dura despicio!",
	upgrade = "Battlefield, I'm coming for you.",
	propose = "Finally the day has come! It looks like my efforts were not in vain... Let's go, Commander, I'm prepared for this. Officers, draw swords!",
	feeling5 = "Well, enough of that. I'm Warspite, the one who spites war. Hmph! However, whosoever tries to take the Commander away from me will first have to face my cannons!",
	main = "Your orders are absolute, Commander. They shall be my highest priority.|This grand old lady can run faster without a skirt. Want to race with me?|If you make fun of me one more time, you'll be eating my 15 inch shells!",
	touch = "Body contact...? I don't hate it...",
	voice_key_2 = -1,
	mission_complete = "Missions give out rewards once you complete them. Don't forget that!",
	battle = "I would never let the commander's enemies escape!",
	id = 900263,
	gift_dislike = "",
	gift_prefer = "",
	profile = "Elizabeth-class fast battleship, Warspite, reporting in. I hold the record for the longest ranged hit on a moving target. I've come close to being defeated quite a few times, but I managed to cheat death every time. This must be my fate.",
	voice_key = 20502,
	headtouch = "",
	feeling2 = "Commander, want to hear about the history of the Royal Navy? Maybe I should tell you something about the generals who used to accompany me.",
	login = "As long as I'm here, we can deal with any enemy, no matter how far they are.",
	detail = "Don't be blinded by statistics. Victory depends on far more!",
	couple_encourage = {
		{
			{
				10105,
				10108
			},
			1,
			"Do you want to race this old lady?"
		},
		{
			{
				10706
			},
			1,
			"Unmatched by any? *Sigh*...",
			0
		},
		{
			{
				20403
			},
			1,
			"Elegance does not belong on the battlefield.",
			0
		},
		{
			{
				20501
			},
			1,
			"Your Majesty, please look forward to my performance in battle.",
			0
		},
		{
			{
				20503,
				20504
			},
			2,
			"Youngsters, follow me.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[900264] = {
	hp_warning = "Don't panic, Commander. I'm here!",
	feeling3 = "Commander, while I'm like this, I take a special liking towards suprise night attacks. Seriously, I didn't mean it like that, but is the Commander into things like that?",
	mail = "Here's your mail, Commander! Should I open it for you?",
	expedition = "The light shall disperses the fog of darkness. Oh? The girls are back!",
	win_mvp = "The light shines upon our land of triumph.",
	home = "Feeling tired? Relax for a while. How about a massage?",
	unlock = "Greetings, Commander! Aircraft carrier Illustrious reporting in! I pray that you will bring love and peace to this world. May the light be with you.",
	touch2 = "Seriously, Commander, you're like a little kid.",
	mission = "Commander, it's no good to leave missions unfinished.",
	vote = "",
	drop_descrip = "Illustrious-class aircraft carrier – Illustrious, Hull Number 87!",
	feeling4 = "Commander... do you want to try... a soft landing?",
	lose = "Let's retreat, lest I lose my life...",
	feeling1 = "Not even my light can reach the darkness within your heart?",
	skill = "Holy light, grant me power!",
	upgrade = "This way we can radiate our brilliance even further.",
	propose = "Even though light should be shared equally among us all, it's fine for you to have a bit more. After all, I've received something important from the Commander as well.",
	feeling5 = "No matter what you ask of me, Commander, I'll accept it... So, Commander, please tell me how you feel about me.",
	main = "Have you seen where did I put my planes? Oh? Right in front of me? Sorry, something blocked my line of sight.| Commander... can you feel my heartbeat through the palm of your hand?|Commander, why are you always staring at me? Am I that pretty?",
	touch = "It's as though... I've received your recognition, Commander. I feel so relieved.",
	voice_key_2 = -1,
	mission_complete = "Don't forget to collect your rewards, Commander!",
	battle = "Why cause unnecessary conflict?",
	id = 900264,
	gift_dislike = "",
	gift_prefer = "",
	profile = "Greetings, Commander. I am the armored aircraft carrier Illustrious. I may seem gentle, but I have quite the temper. I single-handedly bullied the Italian fleet during the raid at Taranto.",
	voice_key = 20703,
	headtouch = "",
	feeling2 = "Commander, what do you find most important in a girl? Seriously, could you look me in the eyes when we're speaking?",
	login = "Greetings, Commander. I've tidied up a bit here. What do you think?",
	detail = "Could you help me pick up that handkerchief...? I'd lose my balance if I try to pick it up myself...",
	couple_encourage = {
		{
			{
				10703
			},
			1,
			"You haven't changed one bit, Miss Saratoga.",
			0
		},
		{
			{
				1
			},
			5,
			"May the light illuminate Kaede's Legion!",
			4
		}
	}
}


_G.pg.base.ship_skin_words[900265] = {
	hp_warning = "You are all to redouble your efforts!",
	feeling3 = "My big sisters Illustrious and Victorious, like so many other ships you've gathered here, vouch for what a great commander you are. Now come, let this cake be a symbol of our new friendship. Take a bite, won't you?",
	mail = "Commander, I'm leaving the mail right here. Please don't forget to review it.",
	expedition = "Commander, the commission is complete. Shall we go to the harbour and greet the team?",
	win_mvp = "What a magnificent victory! Let us press the advantage.",
	home = "Hmm~? Hmm~? C-Commander! I am p-pleased that you have returned! ",
	unlock = "Good day, Commander. I am Formidable, third ship of the Illustrious class. Pleased to make your acquaintance. ",
	touch2 = "Commander, is this the appropriate way for one to behave?",
	mission = "Commander, please don't forget to review the mission list I prepared for you.",
	vote = "",
	drop_descrip = "Illustrious-class aircraft carrier – Formidable. ",
	feeling4 = "Truthfully, even though I'm a Lady of the Royal Navy, I sometimes want to have a bit of fun too. A side of me that I can't normally show except to people close to me like Illustrious... Doesn't that make you want to get closer with me?",
	lose = "Why you miserab- Ahem! You are truly worthy adversaries, but next time victory will be mine!",
	feeling1 = "I'm afraid I've contracted a disease that gives me a dreadful headache when you're nearby. Would you mind going someplace else?",
	skill = "The curtain falls. ",
	upgrade = "Formidable shall not disappoint.",
	propose = "",
	feeling5 = "",
	main = "",
	touch = "I must admit, Tirpitz is quite the hard nut to crack.",
	voice_key_2 = -1,
	mission_complete = "Commander, please don't forget to review the list of mission rewards.",
	battle = "Ladies of the Royal Navy have many virtues, but mercy to enemies is not one of them!",
	id = 900265,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 20705,
	headtouch = "",
	feeling2 = "Commander, is there something required of me? If you have a moment, why not join me for a cup of tea?",
	login = "Commander, you're uncharacteristically punctual today.",
	detail = "?! ... Ah, I was just doing a bit of tidying up. Please, come right in.",
	couple_encourage = {
		{
			{
				20703
			},
			1,
			"Illustrious, my dear sister, what would you say to a spot of tea after this?",
			0
		},
		{
			{
				20704
			},
			1,
			"Victorious, my dear sister, have I comported myself well today?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[900266] = {
	hp_warning = "It's not fatal damage...!",
	feeling3 = "Comrade Commander, what is this? You wish to deepen your relationship with me as an individual, not a representative of the Northern Parliament? Well, such subjective decisions are acceptable.",
	mail = "Mail. Comrade Commander, you must read it quickly before the next one comes bringing another letter.",
	expedition = "Military commissions? They are part of the logistical aspect of proper fleet management.",
	win_mvp = "Kill confirmed. You cannot stop the Northern Parliament... You cannot stop our righteous liberation!",
	home = "Rest. And tell me now of what glorious victory you have won, or how you turn defeat to our advantage.",
	unlock = "I am called \"Sovetskaya Rossiya,\" and as the mightiest of all the Northern Parliament's battleships, I am her ultimate weapon. I will press onward to eliminate all obstacles that stand between you and the Revolution.",
	touch2 = "This is not polite behavior. ",
	mission = "We have a mission. I will handle the clerical work. You must be clear to focus on your duties as a commander.",
	vote = "",
	drop_descrip = "Sovetsky Soyuz-class battleship – Sovetskaya Rossiya.",
	feeling4 = "Mm, this food is well made... Comrade Commander, thank you for serving me this meal, but I have to wonder, is this more than simple social etiquette? C- could you have some ulterior motive for this charm offensive?",
	lose = "Gah, how humiliating... to think a material defect would surface at a time like this...!",
	feeling1 = "This negative attitude is unacceptable. You must be forcibly reeducated.",
	skill = "Blow them away!",
	upgrade = "An excellent strengthening. The next one should be so good.",
	propose = "So long as I draw breath, I labor to carry out my mission. Not only as a member of this fleet, but also in service of the bonds you have forged... This is not a product of rational thinking alone, but also a decision born of my subjective opinion.",
	feeling5 = "Gah, well done...! I have no choice but to place the pride of the Northern Parliament on the line and face defeat at the hands of Comrade Commander's charm offensive! Now then, Comrade Commander, you face the full power of my love offensive!",
	main = "",
	touch = "You want to deepen our camaraderie? Very good, let us start by making a firm handshake part of our regular routine.",
	voice_key_2 = -1,
	mission_complete = "Hm? Something missing from the reward manifest...? It should be generally correct...",
	battle = "Commence bombardment! We will bury them!",
	id = 900266,
	gift_dislike = "",
	gift_prefer = "",
	profile = "I am Sovetskaya Rossiya, of Project 23. I was part of a strategic plan during the war, but for several reasons never came to be. I see though that I can prove my value here in this fleet with a series of decisive victories.",
	voice_key = 70505,
	headtouch = "",
	feeling2 = "Your fleet must be an iron curtain... Hm, it's a metaphorical expression... My meaning is that I hope to see this fleet stand united, just like our Northern Parliament.",
	login = "Comrade Commander, you are late. You must not forget your proletarian values.",
	detail = "Is that you, Comrade Commander...? I'm afraid the office is a bit messy. But we must make sacrifices to achieve our goals.",
	couple_encourage = {
		{
			{
				29901,
				29902,
				39901,
				39902,
				49901,
				89901,
				19901,
				19902,
				39903,
				39904,
				49902,
				99901
			},
			1,
			"This is no time to ponder the meaning of life. Just show us your strength!",
			0
		},
		{
			{
				900217
			},
			1,
			"Kirov, aid me!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[900267] = {
	hp_warning = "Ahahahaha! At last, this is a battlefield that I am meant for!",
	feeling3 = "I hope you don't take this the wrong way, comrade, but this fight is not just for all of us. It's also yours. Never settle with the status quo, and always seek to keep improving.",
	mail = "You have a letter, comrade. It would be best to open it soon.",
	expedition = "Hopefully our comrades will return bearing good news, unlike that bitter Ice Cruise. Come on, let's go welcome them back.",
	win_mvp = "Rejoice, for we have earned this privilege! May this celebration become the bread that sustains us until our next victory!",
	home = "O comrade, do you return bearing news of glorious victory? Ah, but it matters not, for the thing that matters most is that you fought with all your strength! ",
	unlock = "Hahaha! Not bad, comrade! Come, let us fight for the safety of these azure lanes! Fight until your last breath!",
	touch2 = "What are you doing, comrade? Are you not aware of how we handle lawbreakers in the Northern Parliament?",
	mission = "Missions exist for the sake of preserving the order. We should complete them as soon as possible.",
	vote = "",
	drop_descrip = "Gangut-class battleship – Gangut.",
	feeling4 = "Ahahahaha! Well done, comrade! No matter how strong the enemies we may face, we now join each other courageously, prepared to give everything in pursuit of greater challenges! What could be more revolutionary than that?",
	lose = "Comrade, consider this not a defeat, but rather a warning. A sign that we are losing sight of our revolutionary spirit.",
	feeling1 = "There is no future for those who mistake recklessness with courage, comrade.",
	skill = "The revolution blesses you!",
	upgrade = "Comrades! You are also strong! Let our souls shine out brilliantly!",
	propose = "A pledge, huh? While this act is symbolic in nature, it is also undeniable proof of the bonds we've formed. A toast, comrade. Please continue to guide me in the future.",
	feeling5 = "Let's get to the point! Comrade, I was struck by your brilliance, and thus I fell for you! And now, I face the challenge of how to express my feelings for you! Here, comrade, accept my embrace!",
	main = "",
	touch = "What about my rigging? Isn't fully utilizing everything at your disposal a wonderful and pragmatic ideal? Why would I consign myself to weakness for the sake of showmanship?",
	voice_key_2 = -1,
	mission_complete = "Excellently done! This reward will help pave the next step of our revolution!",
	battle = "Show me your mettle!!",
	id = 900267,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 70501,
	headtouch = "",
	feeling2 = "I am Battleship Gangut, also known as Oktyabrskaya Revolyutsiya. However, my name is less important the what I've achieved. Don't dwell too much on it and just call me what you want.",
	login = "Comrade, what sort of strong enemy will we face today? I, Gangut, shall stand with you!",
	detail = "Know this, comrade. Even if I am battered and bruised, muddied by defeat, I will rise each time to reclaim the glory of mankind! Yes, that is the революция I desire, the only heaven that exists for me!",
	couple_encourage = {
		{
			{
				30511
			},
			1,
			"Ahahaha! Finally, I have the privilege of fighting by your side, Mikasa!",
			0
		},
		{
			{
				70201
			},
			1,
			"For the light of revolution!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[900268] = {
	hp_warning = "Wah! I'm in a pinch!",
	feeling3 = "Commander, what's the greatest difference between me and my big sister? The answer, is my 'color' today!",
	mail = "You didn't see the mail? --Then should I read it?",
	expedition = "Commander, my patrol planes told me the girls out for commission have returned~",
	win_mvp = "Ooh la la~ Big sis is busy, so it's fine that I get to come by once a while~",
	home = "We~ are back~",
	unlock = "Hey there, and good day, Commander! I am Lexington...'s little sister, Saratoga~ If there's nothing important, I'm leaving now",
	touch2 = "...wha!",
	mission = "Commander, can't you complete even a mission?",
	vote = "",
	drop_descrip = "Lexington-class aircraft carrier ー Saratoga, Hull Number CV-3!",
	feeling4 = "Commander, I have something I want to tell you. I'm gonna write it on the back of your hand~ and done... Did you think I'm gonna write 'I like you'? Silly Commander~",
	lose = "Oh dang~ I'll go back for repairs, and then have a good rest while I'm at it~",
	feeling1 = "Pranks? I already stopped pulling them on you~ You're no fun for those",
	skill = "Where are you looking? I'm right over here~",
	upgrade = "Saratoga-chan loves you a lot~!",
	propose = "Ah, Commander. Please wait for a bit~ The Eagle Union carriers are all gathering~ Eh? This is a once in a lifetime occassion! Despite my appearance I am a veteran. I'm well respected!",
	feeling5 = "Commander, you dropped something~~ *kiss* ...Hehe, it was my heart?. Here, you can keep it!",
	main = "Boo! Hehe, did I susprise you?  Commander, you're slow, aren't you?!|Commander, don't confuse me with my big sister!|Eh? Call you 'big bro'? There's no way that's happening~",
	touch = "My stature may be small, but I've yet to grow past that fact!",
	voice_key_2 = -1,
	mission_complete = "This is bad, Commander! The mission rewards are missing! --Darn, you caught me.",
	battle = "Two days ago it was {namecode:90}, yesterday it was {namecode:103}, and today it's you all. Let's go!",
	id = 900268,
	gift_dislike = "",
	gift_prefer = "",
	profile = "I am aircraft carrier Lexington's little sister, Saratoga! Hmm... I like to play pranks! But you already knew that, Commander~ \nPioneer of aviation tactics? If my sister hadn't passed away so soon, that title would've definitely been hers.",
	voice_key = 10703,
	headtouch = "",
	feeling2 = "Who should I prank today~?",
	login = "Oh my~ Sorry Commander. I didn't mean to launch planes at you on purpose~",
	detail = "If you keep on peeping where you shouldn't, even kids will not be talking to you~",
	couple_encourage = {
