_G.pg.base.ship_skin_words[900269] = {
	hp_warning = "",
	feeling3 = "Jealousy? No, that's not the case. Enterprise is a true hero worthy of all the respect she gets. However, compared to her dazzling aura, I'm just...",
	mail = "There's new mail for you. Here you go.",
	expedition = "The birth of the Essex-class would not have been possible without the hard work of the logistics teams. I have to show my gratitude to everyone.",
	win_mvp = "Enterprise, did you see my feat?",
	home = "The fleet has safely returned. Commander, I've prepared the battle report for you. Time is of the essence, so please review it right away.",
	unlock = "So this is where Enterprise is... A-ahem! I am Essex, one of the Union's state-of-the-art aircraft carriers. Commander, you can expect great things from me! I swear that I won't disappoint you!",
	touch2 = "Wh-what is this?! I, I...",
	mission = "There are still unfinished missions? Mind letting me handle things this time...?",
	vote = "",
	drop_descrip = "Essex-class aircraft carrier – Essex, Hull Number CV-9.",
	feeling4 = "I won't lose to anyone, not even to Enterprise. But how do I get everyone to acknowledge this? Commander, if you were in my shoes, what would you do?",
	lose = "I won't let it end like this... I swear it!",
	feeling1 = "I wonder how Enterprise puts up with someone like you...",
	skill = "Spread your wings and soar!",
	upgrade = "When will I be able to get jets...",
	propose = "",
	feeling5 = "I might never be able to become a hero like Enterprise... But when I'm with you, I feel like I can do so much more than just that...",
	main = "",
	touch = "Time to sortie?! Just leave it to me! Oh... you just wanted to chat...?",
	voice_key_2 = -1,
	mission_complete = "The mission rewards have arrived. Are you sure you don't need me to go get it?",
	battle = "All carrier-based aircraft in position, anti-air defense preparations complete. All forces, full speed ahead!",
	id = 900269,
	gift_dislike = "",
	gift_prefer = "",
	profile = "I am the nameship of the Essex-class carriers. Although I was built with great expectations, I was always overshadowed by Enterprise's success. If only I could have been deployed sooner...",
	voice_key = 10709,
	headtouch = "",
	feeling2 = "I witnessed the end of the era of battleships with my own eyes. Will carriers share the same fate some day...?",
	login = "There you are. I've already finished preparing everything. Commander, give us your orders!",
	detail = "What would you like to know, Commander? I'll answer to the best of my abilities.",
	couple_encourage = {
		{
			{
				10706
			},
			1,
			"Just you watch, Enterprise! I won't lose to you so easily!",
			0
		},
		{
			{
				7
			},
			3,
			"The era of carriers is upon us!",
			1
		}
	}
}


_G.pg.base.ship_skin_words[900270] = {
	hp_warning = "Crap, I didn't think there'd be so many of them...",
	feeling3 = "Oh, Commander! This– yeowwwch! Who decided it was a good idea to leave a trolley here?! Jeez, why does this always happen to me...Ah, um, nevermind, I'm fine! More importantly, when do I get to sortie?",
	mail = "There's new mail... do we have new orders?",
	expedition = "Commission completed, resources received~! Hehe, way to go, Commander. You know exactly how important logistics are to our fleet operations! ",
	win_mvp = "The crown of victory goes to me, the one who knows no fear!",
	home = "Phew, I'm back! Oh, you need a battle report, repair and resupply overviews, and a mission debriefing? Sure, five minutes should be enough, right? After that, send me back out there!",
	unlock = "\"The Fighting I\" of the Essex-class, Intrepid, is here! Commander, leave the combat missions to me! I'll bring home victory and glory!",
	touch2 = "You... *sigh*...I'm way more inclined to beat you to a pulp than to praise you for your bravery.",
	mission = "Having trouble with your missions? If you're stumped, why don't you let me try my hand?",
	vote = "",
	drop_descrip = "Essex-class aircraft carrier – Intrepid, Hull Number CV-11.",
	feeling4 = "During my free time, I like to read, watch movies, or stargaze. Oh, by the way, I got a movie ticket from Casablanca. Why don't we go watch it?",
	lose = "I have to go to the docks again...? Damnit, why is it always me... Y-you didn't hear anything!",
	feeling1 = "Commander, the way you're acting now makes you no different from a coward!",
	skill = "Let's get this done!",
	upgrade = "I feel like I can always keep improving! For example, how 'bout giving me a dozen jets?",
	propose = "I didn't expect you to be the one to take the initiative... but I suppose that's fine too. Commander, guess I'll continue to be in your care then! As long as I am with you, I want you to push forward and face the future fearlessly!",
	feeling5 = "The stars in the night sky are distant. So distant that even with all the courage in the world, the effort it would take to reach them is unfathomable... However, all it takes to catch the commander in front of me is.... this! Hehe, isn't that right?",
	main = "",
	touch = "Want something to drink? Then, how about a martini – shaken, not stirred? Just kidding!",
	voice_key_2 = -1,
	mission_complete = "Mission accomplished! See, there's nothing you can't do if you put your mind to it!",
	battle = "Flight preparations complete! Attack squadrons, roll out!",
	id = 900270,
	gift_dislike = "",
	gift_prefer = "",
	profile = "I'm the third ship of the Essex class, Intrepid! Although my poor luck during the war earned me quite a few unflattering nicknames... Heheh, that's all behind me now! Commander, under your command, I'll show you just how powerful I am!",
	voice_key = 10711,
	headtouch = "Wooahh?! You're messing up my hair?!",
	feeling2 = "The great symbol of fearlessness is none other than I – Intrepid! Don't you forget that!",
	login = "Am I slated to sortie today? If not, hurry up and fix that!",
	detail = "One should always go all out, no matter the enemy... Having that said, there are various practical reasons why that isn't always possible...",
	couple_encourage = {
		{
			{
				10717,
				10722
			},
			1,
			"Task Force 38, let's rock and roll!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[900271] = {
	hp_warning = "Why now of all times...?!",
	feeling3 = "Don't think I'm upset just because I have little to say. If anything, I'm probably thinking about something, or about how to express myself.",
	mail = "The mail's here... Wonder if there's any new intel?",
	expedition = "Pardon, but I'll go greet the girls who are coming back from their commission. Just wait here until I report back.",
	win_mvp = "So this is the end that you all chose...",
	home = "You've returned? ...Very well. Why don't we prepare for the next sortie?",
	unlock = "Bunker Hill, one of the Essex-class carriers, is joining the fleet under your command. Don't worry, you'll see the extent of my abilities soon enough.",
	touch2 = "By the looks of things, you won't learn your lesson without some harder-hitting \"experience.\"",
	mission = "Missions... should best be completed in a timely manner.",
	vote = "",
	drop_descrip = "Essex-class aircraft carrier – Bunker Hill, Hull Number CV-17.",
	feeling4 = "Something strange has been going on with my thoughts recently. Whenever I start thinking about things, your face pops up in my head and makes it hard for me to stay calm...",
	lose = "Their power... surpasses even the \"Dragon's Jaws\"...?",
	feeling1 = "I'd rather not talk to you right now.",
	skill = "Resistance is futile!",
	upgrade = "I grow stronger... yet again...",
	propose = "Sorry... My mind has gone completely blank... I'm lost for words... Oh, that's right! \"I pledge loyalty and love to you until the end of time.\" ...How does that sound?",
	feeling5 = "We were born as weapons of warfare, and I thought that is all we would ever be. But having spent time with you, I'm beginning to think... that there's more to our lives than war.",
	main = "Right now, another place out there is being engulfed by the flames of war...|Eldridge's ability? I'm not exactly sure, but... I feel like I've seen it somewhere... |All resistance is meaningless before the Essex-class's attack formation.",
	touch = "...Don't think I'm upset just because I have little to say. Just let me know if you need anything.",
	voice_key_2 = -1,
	mission_complete = "There are a ton of rewards? Of course.",
	battle = "Why did they choose to become our enemy...?!",
	id = 900271,
	gift_dislike = "",
	gift_prefer = "",
	profile = "Essex-class, Bunker Hill. My name comes from a battlefield in the Revolutionary War. I've seen my fair share of battles... and know that war brings nothing but sorrow and pain. Let's not talk about it any more.",
	voice_key = 10717,
	headtouch = "",
	feeling2 = "There is no beauty in warfare. There is only ugliness in the suffering and loss of life we inflict upon each other.",
	login = "We're in a state of emergency. Be prepared to run the Holiday Express, even if it's a holiday.",
	detail = "Commander, why are you staring at me...?",
	couple_encourage = {
		{
			{
				10709,
				10738
			},
			1,
			"You are nothing before the Essex class.",
			0
		},
		{
			{
				10126
			},
			1,
			"Project Rainbow? ...It has a nice ring to it...",
			0
		}
	}
}


_G.pg.base.ship_skin_words[900272] = {
	hp_warning = "There is... still hope...!",
	feeling3 = "",
	mail = "Letters are blessings from other people.",
	expedition = "I'd like to report that the commissions have been safely completed, and that fleet operations are running smoothly. You've done a good job, Commander.",
	win_mvp = "May the wandering souls drifting about the battlefield find eternal peace and salvation... Amen...",
	home = "Mission complete. The fleet has safely returned to the port. Good work, Commander.",
	unlock = "I am Richelieu, Cardinal of Iris Libre. If you too will fight for freedom and faith, then I shall bring you victory, Commander.",
	touch2 = "If nothing else, your audacity is commendable.",
	mission = "Missions may be called a kind of trial. If you take them on with the proper attitude, there is no need to worry.",
	vote = "",
	drop_descrip = "Richelieu-class battleship – Richelieu.",
	feeling4 = "You've come by again. Haven't you been getting too friendly with me? ...Just kidding. I'm truly grateful to have another person that I can chat casually with. I hope that you feel the same way, too.",
	lose = "Is this... also a trial from Heaven...?",
	feeling1 = "Those who refuse to stop marching shall face the path of ruin... Make sure you keep that in mind.",
	skill = "Accept your divine judgment!",
	upgrade = "At times, might is needed to guide others on the right path. I give you my thanks.",
	propose = "As the one who guides Iris Libre, I cannot make an oath solely to you. However, I vow to protect and support you for as long as I live. This, I vow, on the holy name of Iris...",
	feeling5 = "",
	main = "",
	touch = "Please listen to our prayers closely, Commander.",
	voice_key_2 = -1,
	mission_complete = "The reward for those who work hard is Heaven's grace. Let us accept it gratefully.",
	battle = "All ships, prepare for combat! For liberty and glory! Aux armes, marchons! ",
