_G.pg.base.ship_skin_words[900273] = {
	hp_warning = "I have sustained damage, but it is under control...",
	feeling3 = "A \"grimoire\"? Hmm... And you say L'Opini?tre told you this? It's certainly an amusing allegory. Now, I'm afraid I must take my leave for a while, as I have business to attend to.",
	mail = "Reporting in. I have a newly arrived letter for you, Commander.",
	expedition = "Transport commissions and cargo escorts are vital, of course, but let's not forget the important safety of our docks.",
	win_mvp = "How would you say I did? Was my performance satisfactory?",
	home = "You would like something sugary in preparation for your mental labor? It so happens I have a list of our stock of confectionaries. Please have a look.",
	unlock = "Béarn, Iris Libre's very first aircraft carrier, reporting for duty. It is an honor to fight by your side. I eagerly await your orders, Commander.",
	touch2 = "Do you lack the knowledge of what being a decent person entails, or are you simply unable to control yourself, Commander?",
	mission = "Commander, I have received word of new mission directives from headquarters. I shall go and make some arrangements.",
	vote = "",
	drop_descrip = "Aircraft carrier – Béarn.",
	feeling4 = "This \"grimoire\" topic again? I do not appreciate your insistence on it. \"A sacrament from the Iris Libre can perform all sorts of miracles\"... Assuming that were even true, how would you utilize such great power, Commander?",
	lose = "I sincerely apologize, Commander. I take full responsibility for this defeat.",
	feeling1 = "\"You are the most outstanding, exceptional commander I have ever met.\" – You can only hope to hear me say these words in your most outlandish dreams.",
	skill = "Let's proceed as planned.",
	upgrade = "Your kindness will not go unrewarded, Commander.",
	propose = "",
	feeling5 = "Commander, all of today's clerical tasks have been completed right on schedule. This is a good opportunity to... Indeed, as you've requested, I will teach you about the so-called \"sacrament of love.\"",
	main = "",
	touch = "I am right here, Commander. Do not hesitate to give me your orders.",
	voice_key_2 = -1,
	mission_complete = "A mission has been completed. That's one burden off our minds.",
	battle = "Now, as outlined in our briefing, prepare for combat!",
	id = 900273,
	gift_dislike = "",
	gift_prefer = "",
	profile = "My name is Béarn, I am the Iris Libre's first aircraft carrier, converted from the unfinished 5th Normandie-class dreadnought. I lived to see the end of the strife between Iris and Vichya... A tragedy I pray will never happen again.",
	voice_key = 80701,
	headtouch = "",
	feeling2 = "Are you curious about this book? It is just a notepad, more or less. Rest assured, there is nothing remarkable about it. And it is certainly not something you need look at.",
	login = "Here is today's schedule, Commander. Read it at your leisure.",
	detail = "An improvement in operational code and tactical variables... This sequence should be useful. I shall write this down in my notebook.",
	couple_encourage = {
		{
			{
				80201,
				80202
			},
			2,
			"I'd love to transport fascinating items with you.",
			0
		},
		{
			{
				80501,
				90501
			},
			2,
			"I am profoundly honored to fight by your side.",
			0
		},
		{
			{
				20601,
				30603
			},
			1,
			"Allow me to show you an Iris sacrament.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[900274] = {
	hp_warning = "I can't... falter now!",
	feeling3 = "Are you tired, Commander? Under the weather, perhaps? Heh, well, a nice cookie can fix that. Just eat one of these and you'll be right back to normal.",
	mail = "We've received what looks to be mail addressed to you.",
	expedition = "Do you need someone to escort the commission team home? I'm quite the experienced escort, I'll have you know.",
	win_mvp = "Heheh, I'm in top shape today!",
	home = "Nicely done out there. If you've got the energy to spare, perhaps you could write an after-battle report?",
	unlock = "It's a pleasure meeting you, Commander. I'm Howe of the King George V-class. I hope we can build a healthy relationship.",
	touch2 = "Umm... What are you doing?",
	mission = "Oh, missions? Are there any I can help with?",
	vote = "",
	drop_descrip = "King George V-class battleship – Howe (HMS Howe.)",
	feeling4 = "Come visit the dorm next time we're having cookies, Commander. We'd all love to have you, and I especially want to spend some quality time with you.",
	lose = "Next time... victory will be ours.",
	feeling1 = "A kind deed to others is a kind deed to yourself – or so I was naive enough to believe...",
	skill = "My aim shall not waver!",
	upgrade = "Phew... I'll return your gesture with valour on the battlefield, Commander.",
	propose = "Thank you for your sincerity, Commander. I will gladly be yours. I won't ask of you to share all your joys and sorrows with me, as I'm more than happy with just being by your side. Ah, that didn't sound like what I would say, did it? Well, hehehe~",
	feeling5 = "Bah, being indirect is just not like me. I adore you, Commander. Both as the leader of the fleet, and as my beloved special someone. I wish to know... do you adore me as well?",
	main = "",
	touch = "Do save the massage for later. I'm not tired yet.",
	voice_key_2 = -1,
	mission_complete = "A mission's done. I can take care of claiming the rewards, no problem.",
	battle = "Heheh, there'll be no mercy for you!",
	id = 900274,
	gift_dislike = "",
	gift_prefer = "",
	profile = "Prior to my being sent to the Pacific, I always worked side by side with George. But aside from the one time we escorted our Sardegnian friends, I suppose I don't have too many notable feats to my name.",
	voice_key = 20509,
	headtouch = "Hm...?",
	feeling2 = "\"Shape the world into God's vision\" – if there is a God, what is his ideal world? It can't be one of perpetual war, that's for sure.",
	login = "How nice to see you. Now, let's get to work on today's tasks.",
	detail = "To your friends, show no cowardice; to your foes, show no mercy – that is my creed. Hehehe~",
	couple_encourage = {
		{
			{
				60502
			},
			1,
			"Allow me to witness your true might.",
			0
		},
		{
			{
				20505,
				20506,
				20507
			},
			2,
			"Let us show the world what we're made of.",
			0
		},
		{
			{
				20701
			},
			1,
			"Cookies are great, don't you know? Do you really not want one?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[900275] = {
	hp_warning = "H-hey, hurry up and do something about this...!",
	feeling3 = "Y-you're better than I expected... F-fine, I won't go easy on you next time...!",
	mail = "Tsk... Why is all the mail for you...",
	expedition = "Heheh, it seems that the commission team has been doing well. Do send them my best regards in my stead.",
	win_mvp = "A heroic battle commanded elegantly by the Commander— now this is the kind of flawless victory that befits me.",
	home = "My attendant, how fares the combat situation? Do tell me in detail.",
	unlock = "To be Valiant is to be me. Remember this face, for it is the face of a fleet leader! ...Speaking of faces, who are you? The Commander? Very well! I shall treat you as my personal servant!",
	touch2 = "What's the meaning of this?! Grrr... As a charismatic, generous, and VERY patient person, I will forgive you just this once!",
	mission = "I'll leave this these trifling quests to you.",
	vote = "",
	drop_descrip = "Queen Elizabeth-class battleship – Valiant (HMS Valiant.)",
	feeling4 = "H-hold up! Chess is like a real-world exercise, so you have to consider all the various external factors! Th-that's right! That last match was a fake! A fluke! Doesn't count! Cancelled! Got it?!",
	lose = "Ugh... H-how is this possible...",
	feeling1 = "I had great expectations for you...",
	skill = "Everything dances within the palm of my hand!",
	upgrade = "Not bad, my attendant~ Do you want a reward?",
	propose = "Well done! You've gained my recognition as my trustiest spear in the arsenal! To reward you for your continued loyalty, I shall allow you to stay at my side and bask in my charisma! May this ring be a symbol of our bond~?",
	feeling5 = "",
	main = "",
	touch = "Speak your mind, my attendant. You have my ear.",
	voice_key_2 = -1,
	mission_complete = "Even the most trivial quests at least deserve some rewards.",
	battle = "Heed my command! Forward!",
	id = 900275,
	gift_dislike = "",
	gift_prefer = "",
	profile = "Queen Elizabeth-class battleship, Valiant. Hehe, this fleet is known from Jutland to the Far East for its heroic majesty, and I am the reason for that! Now, Commander, you shall become my assistant so that you may prove your worth as a subordinate.",
	voice_key = 20510,
	headtouch = "Wh-what are you doing?!",
	feeling2 = "Good, you came. If you have no other work to do, play me in a game of chess.",
	login = "It's about time! Now, show me today's itinerary!",
	detail = "Look, isn't Elizabeth acting a bit too spoiled? And Warspite and the others are totally enabling that. I knew I should have been the one in charge... Huhh? I'm more or less the same...? Wh-what did you say?!",
	couple_encourage = {
		{
			{
				20501,
				20502
			},
			1,
			"Feast your eyes upon the might of the noble Queen Elizabeth-class!",
			0
		},
		{
			{
				20502
			},
			1,
			"M-make sure you observe my every move!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[900276] = {
	hp_warning = "...I can't afford to mess around, huh.",
	feeling3 = "If you ask me, people should be able to say whatever they want... Oh, hello there, Commander. Just talking to myself.",
	mail = "You've got mail. Nope, didn't bring it with me. Next time, ask, and I'll consider it.",
	expedition = "Look, Commander... No, I'm not angry, I was just going to tell you a commission is done.",
	win_mvp = "Looks like the enemy will have to, uh, try harder next time.",
	home = "One quick battle, and you're knackered already, Commander? You have the stamina of a beached whale.",
	unlock = "I'm Perseus, from the Royal Navy. You can pronounce it \"Per-see-us\" if you want though... Well, whatever. Are we done here? Great. Nice meeting you.",
	touch2 = "You must really want a seat at the naval jailhouse dinner table, huh?",
	mission = "What kind of lazy cat are you, just lounging around all day instead of doing missions?",
	vote = "",
	drop_descrip = "Colossus-class light aircraft carrier – Perseus (HMS Perseus.)",
	feeling4 = "I'm a total moron... Why am I so rude to the Commander when I just want to be friends... I'm so, so stupid...",
	lose = "Damn, we lost... Sorry.",
	feeling1 = "You really are like a can of rancid surstr?mming.",
	skill = "I've got this.",
	upgrade = "Thanks a bunch... Well, yeah, didn't you want a thank-you?",
	propose = "Obviously I don't hate you, Commander. How could I, when I adore talking to you and being patted on the head? L-look, I'm trying to say... I love you. I mean it...",
	feeling5 = "How would I describe you? I dunno, I guess like a storm in the middle of a peaceful voyage... No, no, I didn't mean it like that... Sorry, what I meant to say is, um...",
	main = "",
	touch = "Maybe try finishing your work before you \"chat me up\" or \"interview me\" or however you wanna sugarcoat it?",
	voice_key_2 = -1,
	mission_complete = "Those mission rewards will expire if you don't claim them. Maybe.",
	battle = "Careful, now. The battlefield is no place to worry about fuel economy.",
	id = 900276,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 20606,
	headtouch = "...Yeah?",
	feeling2 = "I can hear just fine, Commander, so don't go yelling in my ear, thanks...",
	login = "There's some saying that goes, \"the early bird catches the worm.\" ...If that's true, I guess you'd starve, Commander.",
	detail = "The big mirror in my room? What about it? If I told you, \"I just like mirrors,\" would that satisfy your curiosity?",
	couple_encourage = {
		{
			{
				30201
			},
			1,
			"Time for a new experiment?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[900277] = {
	hp_warning = "A warrior of the Royal Navy won't back down so easily!",
	feeling3 = "",
	mail = "There's mail for you. Don't forget to give it a look.",
	expedition = "Commission complete. Let's go and offer the returning team some biscuits. Don't worry about me, I can do without.",
	win_mvp = "To show compassion to your foe is to put the safety of your allies at risk.",
	home = "My body weight's still the same as it w– Oh! Commander! Didn't think you'd be back so soon. A-anyway, you'd better give our next mission plan a look!",
	unlock = "The name is Eagle. I intend to serve your fleet to the utmost of my abilities as a proud warrior of the Royal Navy.",
	touch2 = "You see, this is the reason why we have to teach people proper etiquette.",
	mission = "There's still unfinished missions, Commander. We should get them done sooner rather than later.",
	vote = "",
	drop_descrip = "Eagle-class light aircraft carrier – Eagle (HMS Eagle.)",
	feeling4 = "Despite my low-calorie diet and daily rigorous exercise, my weight stays the same... *sigh*, I guess my past status as a battleship defines me more than I think... But why?! How does everyone else manage to lose weight just fine?!",
	lose = "Tsk, I've taken damage after fighting for so long... I'll need repairs when we return.",
	feeling1 = "You're betraying everyone's trust in you by acting like this. Pull yourself together, for god's sake!",
	skill = "You're mine!",
	upgrade = "Enhancements, huh... I just wish they wouldn't affect my weight...",
	propose = "I once met my final obstacle in the Suez Canal... But if you ever need saving, I will overcome any obstacle to get to you, Commander. This is my promise not just as a warrior, but as your lover.",
	feeling5 = "You are irreplaceable to me. Whatever becomes of me... Scratch that. I'll stay the way I am now, just for you. Because I think this is what made me equally irreplaceable to you. Am I right?",
	main = "",
	touch = "What is it? An invitation to get lunch? Hmm... Sorry, but could you go in my place?",
	voice_key_2 = -1,
	mission_complete = "Now that's the face of an accomplished commander. Good job.",
	battle = "The battlefield... Heh, I'm getting all fired up!",
	id = 900277,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 20701,
	headtouch = "",
	feeling2 = "People say I'm not great at socializing, a fact that I begrudge. But my social skills aside, I do know my manners.",
	login = "Great to see you! Based upon your punctuality, I can already tell that you're a responsible commander.",
	detail = "There are many Royal Navy ships named \"Eagle,\" and I will go great lengths to maintain its honourable reputation.",
	couple_encourage = {
		{
			{
				20703
			},
			1,
			"Let us fight side by side!",
			0
		},
		{
			{
				90401
			},
			1,
			"Hrmh! Try as you wish, you won't beat me!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[900278] = {
	hp_warning = "The decisive battle is upon us!",
	feeling3 = "I should spend more time with the others? Even if I tried to do that, I would not know how to behave, and they would be afraid of me all the same... Hey, what are you doing... why are you taking off my riggings?!",
	mail = "What is this piece of paper? \"Mail?\" I see, it's mail. Shall I read it?",
	expedition = "The commission fleet has returned... H-Hey, I managed to remember the time. Have you no words of praise for me?",
	win_mvp = "Impudent fools... why did they have to provoke me?",
	home = "I have never had to welcome anyone before. Perhaps I shall do so by firing my cannons?",
	unlock = "I am called Nagato, flagship of the Sakura Empire's Combined Fleet. Are you the one known as the Commander? I shall bear witness to whether or not you have the ability to unite this world.",
	touch2 = "... H-How uncouth!",
	mission = "Is it acceptable to arrange the itinerary in this manner? I do not quite understand how to do it yet...",
	vote = "",
	drop_descrip = "Nagato-class battleship number one – Nagato.",
	feeling4 = "I see! I am less intimidating with my riggings taken off. I certainly do feel lighter... but why does it feel like I've lost something... like when I appointed Yamato to take over as flagship?",
	lose = "Ugh... I have failed once again...",
	feeling1 = "Your wish... is to repeat the errors of the past once more? Very well... I see...",
	skill = "I am called Nagato... Nagato of the Sakura Empire!",
	upgrade = "I hope... to be able to welcome the day when we can all beat our swords into plowshares...",
	propose = "When I cross the river after the war ends, what awaits me is not a searing white light that engulfs everything, but rather, your warm embrace... There is nothing more that I could ask for...",
	feeling5 = "It is enough to be treasured by one person? Since you were the one who brought me out... I shall have you take responsibility... that is, umm, in other words, I command you to... treasure me... if that is acceptable?",
	main = "",
	touch = "...! N-No one has ever dared to lay hands on me in such a manner...",
	voice_key_2 = -1,
	mission_complete = "The mission rewards... Ngh...! Phew... is it acceptable to leave them here?",
	battle = "Yet another... tragic battle.",
	id = 900278,
	gift_dislike = "",
	gift_prefer = "",
	profile = "I am the manifestation of the soul of the Sakura Empire, the pride and glory of her warrior spirit. As a Big Seven, I am also the symbol of an era. Open your eyes and bask in my radiance... You may stop basking now, I'm getting a bit sleepy...",
	voice_key = 30505,
	headtouch = "",
	feeling2 = "What do you require of me? Hmm? I am not doing anything in particular. After I handed the work to Yamato, there is little to do except fight.",
	login = "Welcome ba... oww, I bit my tongue...",
	detail = "Everyone's faces are full of laughter here... I think I am rather fond of this place!",
	couple_encourage = {
