_G.pg.base.ship_skin_words[900279] = {
	hp_warning = "",
	feeling3 = "Commander, you are a capable child if you are put into action. I feel a little happy.",
	mail = "You've got mail. Do you want me to hold your hand through teaching you how to reply? AAH! Not literally!",
	expedition = "Mr. Commander~ You forgot to check the results. You might see the girls become angry at you.",
	win_mvp = "Commander, you must not become worn out quickly like the enemy-- Oh no... not like that!",
	home = "Have you finished your homework? Alright. Then as promised, I'll give you a reward~",
	unlock = "",
	touch2 = "D-don't tell anyone about this! You'll embarrass me!",
	mission = "Finish your missions properly. Otherwise, there will be catch up lessons!",
	vote = "",
	drop_descrip = "Ranger-class aircraft carrier ー Ranger, Hull Number CV-4!",
	feeling4 = "T-T-Teacher-student relationships?!! I've never thought about such things; I've never even read those kinds of books before. I totally, totally never look forward to that!",
	lose = "I can't let you see me like this, Commander.....",
	feeling1 = "Maybe I should quit teaching...",
	skill = "Ranger, striking!",
	upgrade = "I, Ms. Ranger, am going to teach you some more things",
	propose = "*cries*... Receiving such a precious thing from a student, and getting so happy to the point of shedding tears... I, Ranger, am a failure as an educator...",
	feeling5 = "Commander, you're really helpless without me. S-so... I-I'm... I'm holding you back for another year!",
	main = "What I teach besides fighting is human se... I-I mean... physical education!|The Sakura Empire? ...Uh, Uhhh... I- I don't know enough to teach you about that!|If you don't listen to what I say, I'll punish you!",
	touch = "Hwaa!? Commander... S...Stop... is what you want me to say?!",
	voice_key_2 = -1,
	mission_complete = "The compensation... is nothing major, but it's not good to neglect it either.",
	battle = "Everyone, the one with the lowest results will get extra lessons~~",
	id = 900279,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 10704,
	headtouch = "",
	feeling2 = "Why are kids today thinking about weird things all the time...!",
	login = "Can I conduct combat operations since the weather is so nice today, Commander?",
	detail = "D-don't look at me inappropriatly! And do your work properly! \n--Y-Y-You were just looking at my bridge?! ...Ahaha...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[900280] = {
	hp_warning = "It’s time for a death match! Heheh- hehehe!",
	feeling3 = "Should you be defeated one day, it simply means that you were too weak. That much is a fact of nature. Though... because you are mine, I would at least avenge you.",
	mail = "Your mail is here. Try not to forget it next time.",
	expedition = "The girls on commission have returned. Go on ahead, I will prepare some refreshments for them.",
	win_mvp = "Such is the fate of the weak. Death, nothing more.",
	home = "A fitting reward for the ears of our enemies. Let us enjoy the spoils of war leisurely.",
	unlock = "Will I be able to find a worthy foe here? Very well. I’m yours. Perhaps this, too, is destiny.",
	touch2 = "... Fine. If you say it helps you relax...",
	mission = "Commander, stop slacking around. There are still missions to complete.",
	vote = "",
	drop_descrip = "Aircraft carrier, {namecode:92}.",
	feeling4 = "I cannot comprehend these emotions... is this some sort of primal instinct?",
	lose = "This pain... I shall return it tenfold!",
	feeling1 = "It seems like you're not the hero I was looking for...",
	skill = "Only the strong may survive on the battlefield!",
	upgrade = "Not bad. I’ve come up with some new combat techniques.",
	propose = "... Is this for me? Hm... perhaps it is fate for the strong to be drawn to each other. If that is the case, I shall follow my instincts then. Hehehe~",
	feeling5 = "I have so much I want to say, but I forget them all the moment I see your face...",
	main = "I shall conquer all, no matter who stands against me.|Our enemies may be strong, but that is what makes them worth crushing. Heheh...|The girls of the Fifth Carrier Division? They might amount to something if they work hard enough.",
	touch = "Is there a problem?",
	voice_key_2 = -1,
	mission_complete = "Here are the rewards, the fruits of your labor.",
	battle = "Entertain me with your final struggles. Hehehe...",
	id = 900280,
	gift_dislike = "",
	gift_prefer = "",
	profile = " I am {namecode:92}, from the First Carrier Division. I was originally designed to be a battleship, but fate had different plans or me. Enemies? I simply slaughter them, but only because it is my duty, not for fun.",
	voice_key = 30507,
	headtouch = "",
	feeling2 = "The weak will be eliminated. If you cannot accept that, then simply become stronger.",
	login = "Justice and righteousness are for the strong only. The weak can only weep in vain.",
	detail = "Commander, if you keep looking at me like that, you’ll be eaten up.",
	couple_encourage = {
		{
			{
				30405
			},
			1,
			"Amagi, please don't go off to a distant place by yourself again.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[900281] = {
	hp_warning = "Looks like I can't afford to take it easy just yet.",
	feeling3 = "I look a bit like a courtesan? Hehe~ Well then, mister, it seems like tonight shall be our one and only night together. Let us feel the warmth of our embrace, then let the memories fade to nothing. How does that sound?",
	mail = "Commander, there's mail for you!",
	expedition = "Commander, your girls have returned from commission. I'll welcome them back now, but you should hurry over as well.",
	win_mvp = "Commander, will this be enough?",
	home = "Good work, Commander! Would you like dinner? A bath? Or perhaps... a drink first? Hehe~!",
	unlock = "Ah, it's the Commander... My name is Houshou, and I'll be in your care from now on. Please leave the children of the fleet in my care. I won't let you down!",
	touch2 = "Ahh! ... Commander, that's naughty. You can't touch me there.",
	mission = "You've got new missions, Commander. Care for a challenge this time?",
	vote = "",
	drop_descrip = "Aircraft carrier, {namecode:89}.",
	feeling4 = "A prominent person once praised my beauty, but to be honest, I am not so sure about myself. But if Commander was to acknowledge me, perhaps I could find my confidence. So... Commander, am I beautiful?",
	lose = "I'm so sorry, Commander...",
	feeling1 = "Is something the matter, Commander?",
	skill = "It's time for a feast!",
	upgrade = "Now I can help you even more, Commander!",
	propose = "My dream is to one day settle down with the person I love and open a small bar somewhere... Now, it doesn't seem like my dream is so distant anymore. Right, my dear?",
	feeling5 = "Commander, the moon is beautiful tonight, isn't it? I've prepared some drinks... would you like to stargaze together? I wouldn't do this for anyone else - this is a special service just for you, my dear.",
	main = "",
	touch = "Are you looking for me, Commander?",
	voice_key_2 = -1,
	mission_complete = "Commander is sure forgetful, always needing my reminder just to claim the rewards.",
	battle = "I'm not very skilled in real combat... but I shall not betray your expectations!",
	id = 900281,
	gift_dislike = "",
	gift_prefer = "",
	profile = "I guess you could say that I was the first aircraft carrier ever in the world. You could call me the eldest sister, or mother, of them all! Feel free to consult with me whenever you'd like, Commander. I'm always here for you.",
	voice_key = 30603,
	headtouch = "",
	feeling2 = "Want to take a nap, Commander?",
	login = "Commander, have you eaten yet? No? Let me make something for you. You can't head to work without first preparing your body and mind!",
	detail = "You're like a kid sometimes, Commander... Come over here~",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[900282] = {
	hp_warning = "Can I increase my firepower?",
	feeling3 = "Commander sure is gentle, always slowing down to match my pace when we're taking walks... I'm moved by details like this.",
	mail = "I've brought your new mail, Commander.",
	expedition = "Hehe, Commander. The girls are back from commission!",
	win_mvp = "Hmm, I think I accidentally wasted a lot of ammunition...",
	home = "Let me make a cup of tea~",
	unlock = "Hello, I'm Rodney. I shall be in your care from this day forward.",
	touch2 = "Please don't do this in the command room...",
	mission = "Commander, shall we complete our new mission?",
	vote = "",
	drop_descrip = "Nelson-class battleship – Rodney, Hull Number 29!",
	feeling4 = "Not respecting the chain of command can mean big trouble, it has happened before……Of course it's ok for us since we're so close~",
	lose = "I can still fight... but we should probably retreat, for now...",
	feeling1 = "Even I'm a bit disappointed...",
	skill = "There's no need to be polite when dealing with enemies.",
	upgrade = "I hope you're looking forward to my performance from here on out!",
	propose = "Everyday I spend with the Commander is a special day, I hope days like these will last forever.",
	feeling5 = "Commander, want to have dinner together tonight? I'll make your favorite dish... Hmm? it's not a holiday or something like that... I just thought of it just now... If you want, Commander, we can do it every night~.",
	main = "I'm here to help you with anything you need.|If the Commander doesn't mind, please allow me to keep you company!|Commander, if you keep slacking off, even I will get angry.",
	touch = "What is it?",
	voice_key_2 = -1,
	mission_complete = "Here are your mission rewards. Let's take a look!",
	battle = "Mmm... I'm looking forward to everyone finishing their work too~!",
	id = 900282,
	gift_dislike = "",
	gift_prefer = "",
	profile = "I'm Nelson's little sister, Rodney! Um... us sisters are pretty famous right?\n Erm, you've heard that my fighting style is unbefitting of my appearance? Well well, Commander, such rumors are, of course, false~",
	voice_key = 20504,
	headtouch = "",
	feeling2 = "The weather is pretty nice. Want to take a walk, Commander? Let's relax and chat for a while. What do you think?",
	login = "Ah, Commander, you're back! I was just tidying up the documents, please have a look.",
	detail = "Need me to explain the details?",
	couple_encourage = {
		{
			{
				20403
			},
			1,
			"Hood, you must not waver.",
			0
		},
		{
			{
				20503
			},
			1,
			"You shouldn't underestimate your opponents, dear sister.",
			0
		},
		{
			{
				1
			},
			5,
			"Kaede's Legion? Let's do our best together!",
			4
		}
	}
}


_G.pg.base.ship_skin_words[900283] = {
	hp_warning = "",
	feeling3 = "I love my sister, but she's a bit too quiet sometimes. Milord, I like spending time with you more because you'll play with me!",
	mail = "Milord! Milord! Your mail is here!",
	expedition = "Milord, the girls have returned from commissions!",
	win_mvp = "Milord, did you see that? Did you?",
	home = "Welcome back, Milord, I made you some tea... Woah! Watch out!",
	unlock = "Woah! It's Milord! Milord in person! Um... I'm Yamahi-, {namecode:79}! I am pleased to make your acquaintance.",
	touch2 = "Woah! Watch out, Milord! I'm about to fire my main gun!",
	mission = "Milord! New missions!",
	vote = "",
	drop_descrip = "Second ship of the {namecode:78}-class battleships, {namecode:79}.",
	feeling4 = "Your Majesty, do you know this mask? It's a fox mask used in Kagura. Hehe, I'm actually about to practice my Kagura dance now. Do you want to watch?",
	lose = "Uu... Sister... where are you? *sobs*",
	feeling1 = "You're so boring, Milord. I don't want to play with you anymore.",
	skill = "Ammo storage looks good... Alright!",
	upgrade = "I've gotten stronger... I think!",
	propose = "Milord? You're going to give this to me? ...Even though I am slow-footed and far from perfect? Milord, you are far too kind. I love you too.",
	feeling5 = "I know how hard my big sister works, so for her sake, I know that I should allow myself to be happy. That way, I can share my happiness with her. Now that you are here, Milord, I think I'll finally be able to do that. I feel so happy every time I see you!",
	main = "Milord, Milord! Waah~! ...Thank you, milord. I have always tipped over easily, but I am used to it now.|Milord, do you want to jog with me? I want to become a little faster.|The vase in the hallway broke... It wasn't me, I swear! It just jumped off right as I walked past it...",
	touch = "Milord... that tickles!",
	voice_key_2 = -1,
	mission_complete = "Milord, milord! I've brought the rewards... Oops!",
	battle = "Everyone, go~! Waaah?! My guns fired on accident!",
	id = 900283,
	gift_dislike = "",
	gift_prefer = "",
	profile = "Um... I'm big sister {namecode:78}'s little sister, {namecode:79}! Neither of us have really had good fortune since we were born, but I've grown up well thanks to big sis! Please don't judge me by my looks... I was once the flagship of the Combined Fleet! Planes...? What are those? Can I eat them?",
	voice_key = 30502,
	headtouch = "",
	feeling2 = "Milord, come play with me! Ah... I forgot to bring stuff to play with... what should we do?",
	login = "Milord, milord! What shall we do today?",
	detail = "Milord, you smell really nice~",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[900310] = {
	hp_warning = "Bulin?! I'm in trouble, bulin!",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Bulin! I've successfully buli buli'd the enemies!",
	home = "Are you not letting me sortie because I'm too OP, bulin?",
	unlock = "Bulin? Did I just get an upgrade? Now, I can fight too, bulin!",
	touch2 = "Bulin! I'm about to activate my skill all over you!",
	mission = "",
	vote = "",
	drop_descrip = "Bulin? Did I just get an upgrade?! Now I can fight too, bulin!",
	feeling4 = "",
	lose = "Ehh? I thought I was supposed to be stronger, bulin?",
	feeling1 = "",
	skill = "Within my equipment is the power to end all creation!",
	upgrade = "(I can't believe it... Even with my newfound powers, there's no way to undergo enhancement...)",
	propose = "",
	feeling5 = "",
	main = "This bulibulin has become even strongerer, bulin!|Even though I look a bit like my sis now, she's still the only one in charge of super rares, bulin~ |I never get tired! But, Commander, you seem to get tired all the time... does that mean you're weak, bulin?",
	touch = "Bulin? Commander, did you wanna learn how to bulin?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Witness the power of my new rigging, bulin!",
	id = 900310,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I want to try out some experimental equipment here in your office, bulin!",
	detail = "That green cat said something about this new equipment being \"experimental,\" bulin. Not sure what that means, but since it looks like my sis, it must be super strong!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[900311] = {
	hp_warning = "",
	feeling3 = "I'll let you in on a little secret. My little sister keeps telling people that she's smarter than me. But truth is, she's dumber! I try to be nice and let her feel good about herself, like a big sister should. Ha!",
	mail = "Purin! Secret skill: Drill Translation!",
	expedition = "Yaaaay~! Commander! The girls who went out on a commission have come back! Let's drill something to celebrate!",
	win_mvp = "Purin~! I'm the strongest!",
	home = "Let's run around and relax! Purin~!",
	unlock = "Purin~! The herald of good fortune has arrived! Are you ready? Raise your hands and follow me... Purin~ purin~!",
	touch2 = "Purin~ purin~! (Prototype Bulin MKII continues to spin faster)",
	mission = "Purin~! The next mission has been chosen for you!",
	vote = "",
	drop_descrip = "Prototype Bulin MKII. Can be used to limit break all Super Rare ships.",
	feeling4 = "Whee~! I'm flying! So~ high! Hey, don't move! You'll have to catch me if I fall!",
	lose = "So why am I on the battlefield anyway, purin?!",
	feeling1 = "You're pretty amazing to have gotten on my bad side! But I won't get angry just to appease you! Haha! Enjoy your emptiness!",
	skill = "My drill is the drill that will pierce the heavens!",
	upgrade = "[Cannot be enhanced]",
	propose = "As a simple Bulin, I'm meant to just help strengthen your other ships... But you gave me this ring... You're a strange one! I like you! Come, let's raise our hands together and say purin~ purin~!",
	feeling5 = "You're not an average commander if you managed to conquer my heart. But I won't be shy or blush! Instead I'll give you a growl! Graaaah!",
	main = "Purin~! It's so big in here! There's so much room to run around!|Oh right, it's not my job to just run around, is it? Purin~!|Purin~? I'm too loud? Hmph, who cares what you think!",
	touch = "Purin~ You can't catch me!",
	voice_key_2 = -1,
	mission_complete = "I'm just heading out to fetch your rewards, purin! I promise I won't break them!",
	battle = "Purin~! Don't stop until they kneel and cry!",
	id = 900311,
	gift_dislike = "",
	gift_prefer = "",
	profile = "Hahaha! It's your lucky day now that you've met me! We can purin together from this day forward! What for? To make everyone stronger, obviously! How do you purin? Like this! Purin~! Purin~!",
	voice_key = 10001,
	headtouch = "",
	feeling2 = "My sister is so dumb. When people talk about our colors, it's not about our hair, it's about ra... rari... ah, now I remember! Reality TV!",
	login = "Righty tighty, Lefty loosey, Stay calm and Purin on!",
	detail = "Staring at me all day won't turn you into an expert!",
	couple_encourage = {}
}


