_G.pg.base.ship_skin_words[1101010] = {
	hp_warning = "I'm okay. I can treat these wounds myself.",
	feeling3 = "This moss is growing much faster than expected. See how the sporangia develop 37% faster than the control group... Hm? Why are you looking at me like that? Did I use too many big words? ...You like seeing me smile?",
	mail = "You have mail. Don't forget to check it.",
	expedition = "The commission group is back. This destination... seems ripe for research. Commander, let me go there next time.",
	win_mvp = "We won. Very good.",
	home = "You're going right back to work even though you just got back? I'll use magic to cure your fatigue. Sit still, please.",
	unlock = "Hmm. Are you the Commander? I'm Evertsen. ...Wait. We can talk after I finish recording this data.",
	touch2 = "Aah?! Please stop... This is embarrassing.",
	mission = "Don't forget your missions, Commander. Shall I spruce you up with a little magic first?",
	vote = "",
	drop_descrip = "Admiralen-class destroyer – Evertsen.",
	feeling4 = "Commander, don't touch the plants in this room. They contain trace toxins as part of an experiment... Ah, there it is. I made this balloon flower bookmark for you... It explains the language of that flower on the back.",
	lose = "Is anyone hurt? I'll help treat you.",
	feeling1 = "Quiet, Commander. I'm busy observing this moss.",
	skill = "Be reborn.",
	upgrade = "My magic grows stronger...",
	propose = "Commander, I brought a bunch of baby's-breath for you. I'll preserve it in its most beautiful state with magic so that it never withers... Yes, like my love for you, it will remain eternal.",
	feeling5 = "May I sit next to you and work on my latest observational data? Okay, thank you... Huh? Does it bother you how close I am? But this is the only place I can sunbathe while I work... If you don't mind being just \"bothered\" a little, then it's fine if I stay, yes?",
	main = "Commander, focus on your job rather than my plants, please. ...Hm? I did just call them all plants for simplicity's sake, but if you're really curious, I can introduce you to each. AFTER you finish your work, of course.|Does the mini pine tree look healthier than before? Well, I did use magic on it. I also wrote care instructions on a sticky note and put it on the pot.|Want to look at this through a microscope? This thallus has a darker color than usual, indicating a higher chlorophyll content... One of nature's many mysteries.",
	touch = "Perfect timing. My growth experiment needs an assistant. Can you come and help me?",
	voice_key_2 = -1,
	mission_complete = "Your missions are all complete. Well done, Commander.",
	battle = "When you're ready, let's get going.",
	id = 1101010,
	gift_dislike = "",
	gift_prefer = "I love it. Thank you for the thoughtful gift.",
	profile = "I am Evertsen, an Admiralen-class destroyer of the Kingdom of Tulipa. I'm currently observing and researching the ecosystem of this port. If you're interested in my findings, then come along – quietly, please.",
	voice_key = 110101,
	headtouch = "Is this a kind of healing magic?",
	feeling2 = "This is a miniature tropical rainforest ecosystem. If you're interested, come and observe data with me.",
	login = "Work efficiency trends upward in environments with a lot of greenery, so I've brought a few pots of air plants and cacti. They're easy to care for... Stop staring and focus on your work, please.",
	detail = "Quiet, please. I'm observing this club silverline butterfly laying eggs.",
	couple_encourage = {
		{
			{
				110201
			},
			1,
			" The parrot tulips aren't growing very well... Can you take a look at them?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[1101011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "This data has a few abnormalities. Let's do another control... Ah, Commander. I'll get you water – oh, my experiment? It's no hurry. We can do it after.",
	unlock = "Commander, relax wherever you like. ...Why so far? You won't get any sun there.",
	touch2 = "By the window is a little, umm, embarrassing...",
	mission = "",
	vote = "",
	drop_descrip = "Commander, relax wherever you like. ...Why so far? You won't get any sun there.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "This is my first time doing something like this... just relaxing and basking with someone I love. It's comforting. Don't look so confused, Commander – the person I love is YOU, of course.",
	main = "What are you looking at? Are you interested in the regular deviations of monarch butterfly migration paths? I'll gladly tell you all about it.|This is just an ornamental plant. It isn't poisonous, and it won't bite, so look closely if you'd like... Here. I made room for you to view it.|Are you still not used to seeing me on days off? Even I need breaks, you know... and so do you. Relax a little, why don't you?",
	touch = "Why not join me and change into pajamas? You'll be comfier.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 1101011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Hm? You want to be next to me?",
	feeling2 = "",
	login = "Let's sit by the window together. Ah... Watch your step. I have notebooks, um, lying about.",
	detail = "There's no need to be quiet today, so... shall we chat? I want to know more about you...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[1101012] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "I'm taking water samples. Come over here if you're interested. I'll teach you how to do it.",
	unlock = "Do you see where the little egrets descended, Commander? That is where the mangroves we planted together are. And now, they are a home for the birds.",
	touch2 = "The animals are watching...",
	mission = "",
	vote = "",
	drop_descrip = "Do you see where the little egrets descended, Commander? That is where the mangroves we planted together are. And now, they are a home for the birds.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Mangrove roots are special. They intertwine, supporting one another without ever letting go. I want us to be like that, too... supporting each other, and becoming one.",
	main = "I resemble the guardian fae of the mangroves, you say? Then, would you perhaps like to join me in protecting them, Commander?|The mangroves' roots have spread farther since the last time I was here. Would you like to see them up close? I'll give you a detailed explanation.|Are you too hot? Then come over here and we'll dip our feet in the water together. Let's give ourselves over to the pleasant breeze while we're at it... Well? It feels lovely, doesn't it?",
	touch = "What's the matter? If you're worried about the stability of this perch, then please hold my hand.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 1101012,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Come here and take a rest next to me. It's nice and cool...",
	feeling2 = "",
	login = "Let's do some deep breathing together. Mmmh... Haaah... The crisp air around the mangroves does much to uplift one's mood.",
	detail = "There's only so much that healing magic can do. Yet, these mangroves not only provide a habitat for marine organisms and migratory birds, but also protect the ecosystem. They're even more impressive than magic.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[1102010] = {
	hp_warning = "Ngh. Is everyone okay...?",
	feeling3 = "I'll give the white one, Klein Witje, to Evertsen. She likes little flowers... Do you, Commander? Okay, then I'll grow one for you as well~",
	mail = "Commander, there's new mail... You want me to read it to you? Umm, this is how you open the menu, right... H-huh? Where'd the mail go?",
	expedition = "Commander, the girls who went out on commission are back. Go see them, okay? I'm sure they all miss you.",
	win_mvp = "Thank goodness we won... It's all thanks to you, everyone!",
	home = "Welcome back. Umm... Can you take a look at the coffee machine for me? I followed the manual, but when I pressed start, smoke started coming out...",
	unlock = "Hello there. I'm De Zeven Provinciën, a light cruiser from the Kingdom of Tulipa. It's a pleasure to meet you... Heehee, the plants of the port are so properly maintained. I can tell you take good care of them!",
	touch2 = "Do you like? Heehee, if it excites you... then touch more. I don't mind~",
	mission = "Commander, there are new missions for you to handle... It's not too many, so just keep at it for a little while. Give it your best~♪",
	vote = "",
	drop_descrip = "De Zeven Provinciën-class light cruiser – De Zeven Provinciën.",
	feeling4 = "Commander, I prepared the garden. Are you free later? I made flower herbal tea, so let's have a little tea party there to celebrate.",
	lose = "It's okay. Let's regroup and try again.",
	feeling1 = "Commander... You should really be more considerate of everyone.",
	skill = "May this battle end swiftly.",
	upgrade = "This power didn't come easy... I'll use it to the fullest!",
	propose = "Commander, come closer for me... I want to see your smile and feel your warmth, so that I can remember the most important day of my life forever...",
	feeling5 = "Commander, I grew these roses for you... Heehee, aren't they pretty? I raised them with sooo much love! That is... love for you♡",
	main = "Commander, can I turn the space behind your office into a little garden? If I just plant some flowers and the like, they'll be right there to help you relax.|Why isn't the printer working... Huh? It's just out of paper? I see...|Why did I give Klein Groentje such a difficult name? Well, I don't think it's difficult. It just means Little Green, actually.",
	touch = "Are you feeling down? You can tell me about it. Oh, but not if you don't want to. I'll just stay here by your side, okay?",
	voice_key_2 = -1,
	mission_complete = "Good work, Commander. Leave the rest of the work to me while you unwind.",
	battle = "Let's press on. We can win this!",
	id = 1102010,
	gift_dislike = "",
	gift_prefer = "Aww, how kind of you. I'll treasure this~",
	profile = "De Zeven Provinciën, Kingdom of Tulipa's own light cruiser, speaking. Would you like to know about my home? It has colorful flower fields, spinning windmills... I think you'd love it. Oh, you want to know about ME? That's fine... Heehee, how about we walk and talk?",
	voice_key = 110201,
	headtouch = "Are you tired? Let's go to the park and take a relaxing stroll. It's okay, you don't have to worry about me~",
	feeling2 = "I could clean so much better if I could handle a robot vacuum, but I just can't figure it out... Push here, maybe? Or... *cough* *cough*! Wh-why is there so much dust...",
	login = "Good morning, Commander. Klein Groentje welcomes you, too... Who am I talking about? Heehee, my little plant here. For you~",
	detail = "Hum hum... Ah, Commander. I was just watering Klein Groentje here... Hm? Did you like the song I was humming? Heehee, then I'll keep going for you~",
	couple_encourage = {
		{
			{
				110101
			},
			1,
			" Can I offer you any plants for your newest experiments? Or any help whatsoever?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[1102011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Stay in bed for a while~ I'll go make breakfast. Will milk and toast do? Oh... Right, I broke the toaster yesterday...",
	unlock = "Good morning, Commander. Did you sleep well? Oh, there are petals in your hair. I'll get them for you~",
	touch2 = "Hm? You want to go another round? Geez, did you really recover so fast?♡",
	mission = "Commander, you have new missions. We can't lie around for much longer... Oh! Can you work from bed?",
	vote = "",
	drop_descrip = "Good morning, Commander. Did you sleep well? Oh, there are petals in your hair. I'll get them for you~",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "You've been too busy lately. You finally have time off, so come and have sweet dreams with me... Heehee, close your eyes... Mwah.",
	main = "I'll get you a glass of water. ...Is something wrong? Oh, you don't want me to leave? Hmm... Okay, the water can wait~|Do you like my sleepwear? Heehee, how about you pick for me next time?|You wanna close the curtain? Is the sun too bright? ...You're worried people will see? It's okay; we're surrounded by greenery. Nobody knows a thing♪",
	touch = "You want to get closer? Be my guest~ I'll share half my pillows!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 1102011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Do you want me to stay, too? I'd be happy to sleep with you for a while longer♪",
	feeling2 = "",
	login = "Are you awake? ...Why didn't I wake you? Hmm... Because you looked too cute in your sleep. How could I take my eyes away?♪",
	detail = "How happy I would be if I could wake up next to you every day... Commander, if you like this place, then why not stay a few more days?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[1199010] = {
	hp_warning = "Don't be alarmed. Nature will inflict this pain back on our enemy!",
	feeling3 = "Commander, if you ever need a break, I can take on some of your work for you. Mother Nature's powers can fix anything, so don't hesitate.",
	mail = "Did you receive a new letter? Tell me what it's about later.",
	expedition = "What's this? The commission team has come back. Come with me and we'll go see them, Commander.",
	win_mvp = "Trying to resist nature? This simply won't do.",
	home = "Oh, our champion returns. How about a quick break? Give yourself to the sun's brilliance, the birds' chirping, and the fragrance of the flowers. It may very well have a surprising benefit.",
	unlock = "Heehee. It was you who brought the sound of nature here, yes? I hope this gift may warm your heart and soothe your body. Now, close your eyes... Become one with the sound of harmony and embrace a world of peace.",
	touch2 = "Aahh... You may want to reconsider... before my vines tie you up.",
	mission = "Commander, it's time to do some missions. If you're too tired, come here and I'll look after you.",
	vote = "",
	drop_descrip = "Heavy cruiser – Gouden Leeuw.",
	feeling4 = "Look, Commander – I conjured an illusion of you! Sadly, it doesn't have the warmth of your hands, and its heart doesn't thump like yours... I much, much prefer the real version of you!",
	lose = "This is nothing but a minor setback. It's fine. Just relax and we'll give it another try.",
	feeling1 = "Goodness gracious. If something's upset you, why don't you speak to nature? It may just ease your mind.",
	skill = "Listen... to this lullaby of life.",
	upgrade = "Would you like an up-close demonstration of my improved strength, Commander?",
	propose = "It seems we've walked into the hidden realm of love whilst blessed by nature... My time spent with you is like a vine in the nourishing sunlight, and our love grows and grows more with time... Take my hand, Commander, and let us listen to the song of nature as we walk into tomorrow.",
	feeling5 = "Goodness, I was hoping you'd be wholly reliant on me, and yet I'm the one who can't get enough of you... Well, it is how it is. We are both in nature's embrace, completely inseparable from one another. Isn't that right? Heehee.",
	main = "Why don't we take a walk? There are so many trees growing here. I can escort you through the quiet and vivid woods♪|Aww, Commander, are you pulling another all-nighter? That's really not in tune with nature at all. Come on, you've worked enough. Let this firefly guide you home.|Those children are ruining nature's beautiful sounds... Commander, if you keep ignoring them, my vines will take things into their own hands and punish them.|What are you listening to, Commander? A \"sounds of nature\" playlist? So merely listening is good enough for you? You can't even smell the flowers and plants... If it's the sound of nature you wish to hear, why not do so in my embrace?",
	touch = "Be gentle. I'm a bit ticklish, you see. Heehee.",
	voice_key_2 = -1,
	mission_complete = "My, you're incredible! Come here for a hug. Heehee – is this the kind of reward you prefer?",
	battle = "Alright, Commander – it's time to show you what I'm made of.",
	id = 1199010,
	gift_dislike = "",
	gift_prefer = "You have such a way of always giving me what I want~ How can I possibly return the favor?",
	profile = "I am Gouden Leeuw of the Kingdom of Tulipa. Vines come from nature, and magic comes from light. Look here – I can use light magic to conjure illusions of animals. Interesting, no? I do this as a reward for children who behave.",
	voice_key = 119901,
	headtouch = "Heheh. Yes, this is quite pleasant. Like the gentle warmth of the sun on a spring day.",
	feeling2 = "Heheh, the nights have been oddly quiet lately, you say? That's because I've been lulling the troublemakers to sleep with my vines.",
	login = "Ah, Commander. Welcome. Letting my vines stretch too freely, you say? My apologies. I was concentrating on my breathing and didn't notice... Heheh, it's a wonderful feeling, so why don't you try it with me? Huff... Puff...",
	detail = "Heehee. Just as the warm winds of spring are a part of nature, so, too, are the cold streams of winter. Mother Nature deserves respect in all her forms... Oh? You say my control over nature's powers deserves respect as well? My, my... I think your efforts are better spent on vigilance than flattery.",
	couple_encourage = {
		{
			{
				110101
			},
			1,
			" Have you made any new discoveries? Tell me about them.",
			0
		},
		{
			{
				110201
			},
			1,
			" Singing to your plants – that's so lovely!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[1199011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome back. It's time we got you cleaned up. This time, I'll be the one doing it to you.",
	unlock = "After all that messing around in the bathroom, it's time to clean myself. Commander, would you please assist me? I'll be still for you, of course. For instance... How about this position, hmm?",
	touch2 = "Ahh... Ohh... Naughty-naughty, Commander. What should I do with you?",
	mission = "",
	vote = "",
	drop_descrip = "After all that messing around in the bathroom, it's time to clean myself. Commander, would you please assist me? I'll be still for you, of course. For instance... How about this position, hmm?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Is the cleaning done already? Heehee – you, however, don't seem to have had enough. Allow me to repay your efforts now, then. Aahhh... It's true – other than nature, you are the only thing that helps me relax.",
	main = "What sorts of aroma do you like? The fragrance of ripe fruit? The smell of a quiet forest? ...The scent of my body soap? Well, then why don't you come closer?|Oh dear, I'm all covered in bubbles... You didn't have to go THAT far, Commander.|This spot next. We should be nearly done. Don't worry, I'll hold still. Heehee – you're so well-mannered, Commander.|...If there were any vines here, I'm sure they'd constrict you right up.",
	touch = "Commander, could you clean this spot for me?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 1199011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Well, if you wish to do it this way... Ahh... Yes, that feels lovely.",
	feeling2 = "",
	login = "I do wonder what part of me you'll clean first. Yes, start with whatever you like. You're mine to spoil right now, after all.",
	detail = "Since you'll be cleaning me, get on top of me. Please, I insist. Be thorough and meticulous, and don't miss a spot anywhere from my toes to my chest... or my hair and my skin. Heehee.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9600010] = {
	hp_warning = "Let's find out who fortune favours!",
	feeling3 = "Even to this day, lots of people go wild for pirate treasure! I suppose very few can resist the alluring shimmer of gold and silver, eh... Hm? Where do ya find said treasure? Sorry, no hints! If you want treasure, you gotta find it yourself~",
	mail = "A letter? Ahah! Is it a wanted list? Say, if you had a bounty on your head, how much do you reckon it'd be worth?",
	expedition = "The commission team is back with a boatload of booty! They're waiting for you to divvy it up, so get going!",
	win_mvp = "Heheh~ Time to feed these scalawags to the sharks!",
	home = "You made it back! Brought back any exciting tales of your adventures? You know, like being caught in a storm, chased by sharks, and swept away by the waves before finally escaping with your life?",
	unlock = "You're looking at the mysterious, heartstopping Royal Fortune! ...Hm? Scared you, did I? C'mon, don't be so uptight! Now, where are we headed? The fabled Treasure Coast? The cursed Black Reef, littered with shipwrecks? I don't care where we're going; let's just hoist the sails!",
	touch2 = "Between drinking lethal poison, a sword through the neck, or being thrown overboard... which one would you prefer? ♪",
	mission = "New missions, eh? Let's have a gander... This one's high risk, but high reward too... Alright, let's do it!",
	vote = "",
	drop_descrip = "Sailing frigate – Royal Fortune.",
	feeling4 = "You don't sail the seas with me just to find treasure, do ya, Commander? I don't think you're in it just for the novelty either... It can't be ME you're after, right? I mean, there's no way... Woah, you're not gonna deny it?",
	lose = "Grah! I hate swallows! Shoo with the lot of you!",
	feeling1 = "Ugghh. If this were the olden days, I would've fed you to the sharks or dumped you off on a deserted island.",
	skill = "I'll blow you all to bits!",
	upgrade = "Now that I'm stronger, shall we set out for a more thrilling, heart-throbbing adventure?",
	propose = "Sooo... you're sure about this? Living with me's not gonna be easy. You can't just change your mind later, ya hear? ...Well, alright, then take my hand and put the ring on. Once we're done, get on my ship and hoist sails!",
	feeling5 = "Since you don't have a destination in mind, why don't I plot your course for you? For instance... to that deserted island said to have buried pirate treasure I've heard about. Heheh, don't you worry – worst case scenario, we only end up stranded and have to live there, right? C'mon, let's go!",
	main = "Movies! Video games! Ah, modern entertainment is bloody amazing! It's easier than ever to stave off boredom even while not out at sea!|Gambling simply boils down to a test of who's luckier. It's not about winners or losers – it's about scamming poor sods who aren't as lucky as they thought.|Even we pirates have our own code of conduct. How are you supposed to keep people in line without rules? Speaking of which, what kind of rules do you have?",
	touch = "Hahaha, tired of boring ol' paperwork and ready for an adventure? I'm always ready to sail with ya♪",
	voice_key_2 = -1,
	mission_complete = "Mission complete! Speaking of which, what's the secretary's cut of the rewards?",
	battle = "Go, go! Fortune favours the fleet-footed!",
	id = 9600010,
	gift_dislike = "",
	gift_prefer = "Whoa, bloody amazing! I'll take that!",
	profile = "My history? Well, I was a rough and tough pirate just like in the stories, bullying those I didn't like and ne'er living two days the same way~ Then I got into a fight with a real tough bastard and that was game over for me. Bad luck, that's what it was.",
	voice_key = 960001,
	headtouch = "Hey! I don't like it when people touch my hat without permission!",
	feeling2 = "Living in the moment means doing what you enjoy and forgetting all your troubles and concerns! ...That still doesn't mean I have the right to plunder? Laaame!",
	login = "Ahahaha! There you are, Commander! Hurry up and finish your work so we can set off on another grand adventure!",
	detail = "Alright, lassies, it's time to go night-night. The pirate bedtime stories will have to be another time. Hm? You wanna hear them too, Commander? Then maybe an adult story would be more to your tastes, huh? Hahahaha♡",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9600011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Who did this?! Who put liquor fondue on my desserts?! Urgh... It's hitting me hard... I'm gonna go lie down a bit...",
	unlock = "Tonight's dessert is not a cake or a pastry... What are you looking around for? YOU'RE my dessert! Heheh, scared you, didn't I?",
	touch2 = "Wh-wh-whaddya think you're doing?!",
	mission = "",
	vote = "",
	drop_descrip = "Tonight's dessert is not a cake or a pastry... What are you looking around for? YOU'RE my dessert! Heheh, scared you, didn't I?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Mmm! Sho good! Desserts are a rare luxury out at sea, you know! This sweetness will linger in my head for a looong time!|Would be cool if we lived in a world where monsters are real! I get pumped just imagining what it'd be like!|That Janus girl sure has got a spicy costume for how shy she seems... Aha, does that happen to be one of your weaknesses, Commander?",
	touch = "You're in too deep to pull out now~",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 9600011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Happy Halloween! On this frightening night, I am Royal Fortune the naughty succubus! Ahahah! I'm on the hunt for a tasty treat!",
	detail = "Hey, hold it! Get back here! Commander, don't just stand there! Catch these thieving birdies and get me back my desserts!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9600012] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Commission team just got back! Let me handle 'em.",
	win_mvp = "",
	home = "Oi, what happened to spending the WHOLE day with me? Other girls can have their turn later! Heehee, caught you♪",
	unlock = "Hell of a proposition, this. Keeping an eye on your booty for the whole day so nobody steals it. But I said I'd do it, and a real Tempesta always keeps her word. You're all mine for today♪",
	touch2 = "You've just earned yourself a kicking! Take this! And that!",
	mission = "",
	vote = "",
	drop_descrip = "Hell of a proposition, this. Keeping an eye on your booty for the whole day so nobody steals it. But I said I'd do it, and a real Tempesta always keeps her word. You're all mine for today♪",
	feeling4 = "",
	lose = "Urgh... That drink was NOT non-alcoholic...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Hm-hmm-hmm♪ There's a million ways to have fun at the beach! And the pirate's way is pretty widespread, eh? Brilliant!|A cocktail? Whoa, it looks so vibrant and tasty! ...The hell?! It's got alcohol in it! Are you trying to get me hammered, Commander?!|Port law article eleven! On holidays, everyone should let loose during the day, then feast, sing, and party during the night! And participation is mandatory, Commander.",
	touch = "So, what're we doing next?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 9600012,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Back, eh? Let's continue, then♪ \"Continue what\"? Our daylong date, duh!",
	detail = "You're my golden treasure today, so don't you go anywhere♪ That's right, stay where you are if you don't wanna get grabbed by my tentacles! Ahahah!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9600020] = {
	hp_warning = "I can still... hold steady!",
	feeling3 = "I offer prayers for victory and peace whenever I embark on a campaign. Commander, I will pray for you too, and grant you the golden light's blessings.",
	mail = "A new letter? Hmm... Actually, it's best if you read it yourself, Commander.",
	expedition = "The campaign fleet has come back, returning the treasure to its rightful place.",
	win_mvp = "The golden light shall shine upon the path of victory.",
	home = "Now that you've returned, let me examine you... Arms and legs are fine. You're in perfect health.",
	unlock = "São Martinho – the Invincible Tempesta, flagship of the Armada, and retainer of the golden light – greets you. Whereto is our next grand campaign, Commander?",
	touch2 = "Why do I feel warm...?",
	mission = "A new mission? Very well. Remember to perform a hull inspection and repairs before you embark.",
	vote = "",
	drop_descrip = "Sailing frigate – São Martinho.",
	feeling4 = "A storm is coming. Commander, take shelter under my wings and... Hm? Rubbing shoulders, you say? Well, that is to be expected...",
	lose = "Let us await the opportunity for redemption.",
	feeling1 = "I thought you had promise as a fellow head of a fleet... It seems I overestimated you.",
	skill = "O Invincible Armada, heed my order!",
	upgrade = "Gracias.",
	propose = "I swear to you this oath upon the golden light. My lance shall pierce your foes, and my wings shall keep you from harm, even at the cost of breaking them if there is no other choice.",
	feeling5 = "Commander, I've located a calm anchorage where we can be alone and... \"Return treasure to its rightful place\"? No, a-all I want is some private time with you...",
	main = "These wings are a sacred gift from the golden light. Do you wish to touch them?|You wish to hear the Invincible Tempesta's many poems? Then you need only wait. Come the battle with our despicable enemy, my sails shall tell you my tales.|Pay close attention to fleet logistics, and in particular, the rations supply line. I say this based on my own experience.|I will under no circumstances sail when a storm is raging. Hm? No, not because I'm afraid, but rather... because rain makes my wings heavy.|You must hold your tongue even in the face of pain. Showing strength is important, because neither storms nor foes are merciful on the weak.",
	touch = "Is this a physical examination?",
	voice_key_2 = -1,
	mission_complete = "I do hope these mission rewards were worth the effort of our expedition.",
	battle = "Let us play a melody of destruction for our foes!",
	id = 9600020,
	gift_dislike = "",
	gift_prefer = "It's clear that you have good taste. I'll give this pride of place, don't worry.",
	profile = "Turn your gold into the most magnificent palaces – turn your battles into the most valorous poems. Bathed in the glorious golden light, the Invincible Armada continues its campaign to this day.",
	voice_key = 960002,
	headtouch = "",
	feeling2 = "Commander, I ask you to stay close to me during our expeditions. The golden light will protect us all.",
	login = "Commander, what grand undertaking shall we begin with today? ...This paperwork, you say?",
	detail = "I am the inheritor of the Invincible Armada's glory. You surely know the burden I carry, Commander, you being the head of a fleet just as I.",
	couple_encourage = {
		{
			{
				960003
			},
			1,
			" I would never have imagined I'd sail with Golden Hind.",
			0
		},
		{
			{
				960001
			},
			1,
			" All fortunes must return to their rightful place.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[9600021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "The shadow follows the golden light's course.",
	home = "Welcome back to the port. I will keep a keen eye open to see who out there is able to hurt you.",
	unlock = "Here you see the opposite side of the retainer of the golden light. Be not afraid. I am still me, and my feelings and my beliefs have not changed. Still, if it unnerves you, perhaps you should get to know me again?",
	touch2 = "What a delicious feeling...",
	mission = "",
	vote = "",
	drop_descrip = "Here you see the opposite side of the retainer of the golden light. Be not afraid. I am still me, and my feelings and my beliefs have not changed. Still, if it unnerves you, perhaps you should get to know me again?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "You wonder how differently the light and dark versions of me feel about you? Regardless of appearance, the retainer of the golden light loves you, Commander. From start to end, I am me, and my feelings for you remain the same.",
	main = "The golden light casts a shadow. This shadow is indispensable to our glory's continued existence.|I've dyed you in my own color... Heehee, no, this darkness is only meant to protect you.|This hunger, it yearns to be quelled... with lots of food. Hm? I mean a loooot of food, Commander.|You wish to see me fight in my dark form? Hmmmm. It almost sounds like you prefer the way I look now.|The \"old\" São Martinho? Silly you. I am still me; I'm not a fallen angel or corrupted by the dark. There is no \"old\" or \"new.\"",
	touch = "I feel you've become more reliant on me. Good.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 9600021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Not to say you're late, but I did wait some time. My heart ached for you.",
	detail = "I am the shadow cast by light, I am the dark inversion, and I am São Martinho, retainer of the golden light. This fact will never change.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9600030] = {
	hp_warning = "I can't regenerate quickly enough to keep pace...",
	feeling3 = "I can come closer, you say? Heehee, I feel the passion emanating from you~ *squish squish* Heehee. Is this better, my darling Commander? Can you feel MY passion? ♡",
	mail = "Here's your letter, darling~ *squish* ...It's sticky? Heehee, think of it as my liquid passion for you~♡",
	expedition = "A commission's been completed. Would the team mind bringing me the enemy's remains?",
	win_mvp = "Now the victors have the right to do whatever they please~",
	home = "You're finally back, my darling~ How rude of you to leave me behind, when I prefer taking the lead rather than lying down... Oh? What's this mango? A treat for me? Heehee~ Why, how kind of you~♡",
	unlock = "Greetings, my darling Commander. I am Golden Hind. I've heard much about you and am pleased to meet you at last... Heehee, my, what a rousing body you have~♡ *squish squish*",
	touch2 = "You've finally caught on, Commander... *squish squish* Now, come to me. I will take everything you have to give♡",
	mission = "Heehee, my darling~ You must read the fine print carefully before you sign the pact♡",
	vote = "",
	drop_descrip = "Sailing frigate – Golden Hind.",
	feeling4 = "Too close? Heehee, my urge to top you has only grown stronger since I laid eyes on you, my darling... There's no escaping your fate now♡",
	lose = "It's alright, my darling Commander. My severed parts will grow back in no time~",
	feeling1 = "Your body is the only good thing about you... What a shame.",
	skill = "Join the others in my collection!",
	upgrade = "This will help me procure more remains♪",
	propose = "Is this...? Heehee, I see now~ It's a promise about a home, isn't it, my darling? Heehee... I've roamed freely up to this point, going wherever my whims dictated, but now I have a place that accepts me. Well, Commander, what are you waiting for? It's time we indulged in each other, forever and ever♡",
	feeling5 = "Oohh, so this is how you answer... You get dominant when you want to affirm your feelings, I see♡ If I'd known this when we first met, I would've done something more... Heehee, never you mind~ I can't wait to experience our future together♡",
	main = "My apologies~ It seems some of my ooze got stuck on you.|Are you interested in my remains collection? Don't you worry, I'll tell you aaall about it and the stories behind it in thorough detail♡ *squish squish*|Movies, games, books... There are so many pastimes at this place~ I wonder, though... would you be interested in an onboard concert?",
	touch = "What is it? Do you want to feel my tentacles? Heehee... Go ahead~",
	voice_key_2 = -1,
	mission_complete = "As a reward for completing your mission, I invite you to my bosom♡",
	battle = "I will add you lot to my collection♡",
	id = 9600030,
	gift_dislike = "",
	gift_prefer = "Thank you, Commander. This will be the pride and joy of my collection♡",
	profile = "Caught you~ Heehee. What do you wish to know about? My name? My eternal beings, or should I say, my adorable tentacles? Well, my tentacles have been to the end of the world once~ There is no end of the world? Whatever you say♡",
	voice_key = 960003,
	headtouch = "You're quite gentle with those hands, my darling...♡",
	feeling2 = "I brought these lychees with me on a recent cruise~ Heehee, they're juicy, sweet, and delectable~ Want to try one? Let me just peel the skin and take out the annoying core, then I'll bring it to your mouth using my tongue♡",
	login = "There you are, my darling. Heehee, I have fresh meat and vegetables, hand-squeezed juice and liquor, everything you can think of, if you want a taste~♪ *squish*",
	detail = "You really do have a stunning body, my darling~ Heehee♡",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9600031] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "The tentacles are for rewards, the axe is for punishment~",
	home = "Welcome back, my darling Commander~ ...What am I doing with the axe? Why, I'm looking for a way into your office without the key~♡",
	unlock = "How do you feel about this look, my darling? ...Not scary enough? How odd... I thought Mary Celeste had the right idea. Wait, I know~ What if I hold this axe, hmm? ♡",
	touch2 = "A lonely newlywed in a deserted castle... This is how our loving starts, my darling♡",
	mission = "",
	vote = "",
	drop_descrip = "How do you feel about this look, my darling? ...Not scary enough? How odd... I thought Mary Celeste had the right idea. Wait, I know~ What if I hold this axe, hmm? ♡",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "...Why not give all my tentacles an axe? Heehee, you sure get funny ideas, my darling~ That would turn this into a Halloween comedy, not a horror flick.|Hm? Hmm? Seems my tentacles got ooze on my clothes... Wouldn't you say that's an upgrade, though, my darling Commander?|\"You cheated on me! Die!\" ...Hahahah! Was that a bit too intense? Now I'm curious what kind of Halloween bride you do like♡",
	touch = "Could you re-tie the knot on my skirt, please? Heehee, of course, you'll need to untie it first... ♡",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Heeere's Hindey~♡",
	id = 9600031,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "My veil hardly covers anything because of this antler... Oh, you think it suits me perfectly? Thank you, my darling♪",
	feeling2 = "",
	login = "I've been waiting for you this whole time, Commander♡ ...Did I run into anyone while you were gone? Heehee, you're so sweet when you're agitated♡",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9600040] = {
	hp_warning = "Wh-where's the fire?!",
	feeling3 = "You want me to stop hiding like a ghost and reveal myself out in the open? Hmm, that's honestly a lot to ask... What? You're telling me to do it right now, in the office?!",
	mail = "Let's say your new letter floated into the office by itself – how do you feel about that? ...It would scare the younger shipgirls? Now that you mention it, I suppose so...",
	expedition = "Commander, we ought to set up a fright for the girls who just returned from their commission!",
	win_mvp = "Mwahahaha! Another victory with no surviving witnesses!",
	home = "You're back! Admirably done, Commander! Let's start you off with a chilling hug! ...It looked like I was waiting for you? Heh, yes, because I'm always watching you.",
	unlock = "Hmm, so you're the Commander? I'm Mary Celeste – the fabled ghost ship. And this one's name is... Argo, for short. Hahah! Don't be scared of her. She's just fond of this busy world, just as I.",
	touch2 = "Hahah! Your hands are so warm.",
	mission = "Hmm... It's been untold years since someone relied on me. Makes me feel cherished – something I miss.",
	vote = "",
	drop_descrip = "Sailing frigate – Mary Celeste.",
	feeling4 = "It's weird, but I've developed this need to be around you in order to feel peace of mind... Huh? You noticed I've started caring about my appearance? Uh, thanks...",
	lose = "We'll be fine. The enemy cannot pursue us.",
	feeling1 = "Hey, Commander... Are you lonely? It's alright. I'll be here with you.",
	skill = "Where's Mary? Right behind you!",
	upgrade = "Heh. From the dark is where I protect best.",
	propose = "You're giving this to me? It's like saying you want to spend your life with me... Hahah! I'll gladly do that. From this day onward, you walk the same path as me. Your heart will be my home, from which I will always receive warmth.",
	feeling5 = "I'll let you in on a secret, Commander. Us ghost ships have our own place to call home. Where, you ask? *hug*... Th-there, is that a good enough answer?",
	main = "I suggest wearing warm clothes if you want to hang around a ghost ship like me, Commander.|Eeek! A-a fire?! ...They're just cooking barbecue? Ugh... I'm going to vanish for a while, Commander!|People say I'm friendly? I don't know about that... I'm so used to living alone that I've just become a good listener, I think.",
	touch = "Hmm? I'd be wary of frostbite if I were you, Commander.",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Now come here and I'll pat you on the head! Good, good~ ...Hahah! My touch is nice and cold, isn't it?",
	battle = "There's no fleeing from a ghost!",
	id = 9600040,
	gift_dislike = "",
	gift_prefer = "For me? Well, thank you. I'll repay you.",
	profile = "I am Mary Celeste, a seaborne ghost birthed by a storm. Hmph, the legend surrounding me... It's merely one of the truths you can't see with the human eye.",
	voice_key = 960004,
	headtouch = "My horns've caught your eye, eh?",
	feeling2 = "From the shadows, I emerge... Eek! St-stop putting firewood into the stove at once! ...Ahem! C-Commander, just so we're clear, you did NOT hear that... Got it?",
	login = "Ah! You've returned, Commander! What would you like? A cup of hot tea, or coffee? Or perhaps you yearn for my ghostly embrace?",
