_G.pg.base.ship_skin_words[9600041] = {
	hp_warning = "The spider lilies bloom... for me?!",
	feeling3 = "",
	mail = "I had the bats bring your letter. They don't get lost even in pure blackness.",
	expedition = "",
	win_mvp = "",
	home = "Nicely fought! Yours truly has been waiting for you! ...Sorry for being late? It's fine. Loneliness never had a chance to take hold, because I knew you'd be back.",
	unlock = "I am Mary Celeste, the silent reaper of the moonless night... Aye, this attire befits a ghost ship such as I.",
	touch2 = "Mhh... Hahh... Hey, should I really be wearing an outfit like this?",
	mission = "",
	vote = "",
	drop_descrip = "I am Mary Celeste, the silent reaper of the moonless night... Aye, this attire befits a ghost ship such as I.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "It really is more heartening to walk the earth with you than to wander through the dark night alone.|Wow, these bats remind me of Argo in that they're very docile. So, Commander, be nice when you give them orders.|Bats hate fire, and vampires hate fire as well, so it makes perfect sense that I hate fire. Aye.",
	touch = "Do you like my wings? ...They make me look even cooler than before? Oh... Th-thank you... *blushes*",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "I bring death to all turncoats.",
	id = 9600041,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "The red thing on my head? It's a spider lily petal... Probably.",
	feeling2 = "",
	login = "Hahahah! Welcome to the rim leading to the afterlife! I will protect you on this moonless night! ...Hm? N-no, I wasn't feeling lonely, I swear.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9600050] = {
	hp_warning = "I never should've left home...",
	feeling3 = "Warm sunlight over a peaceful port... Yeah, that's the good stuff. So good it makes me want to take a nap... Commander, wanna join in? Nothing beats basking in the sunlight right next to the window.",
	mail = "New mail's here... What a pain... Sorry, Commander, but can you check it yourself?",
	expedition = "Looks like the commission team's back. Go greet them for me, yeah? *sigh*... I seriously don't wanna get up... Commander, how about you just take some crisps to them for me...?",
	win_mvp = "We won? *Yaaaaaawn*... Finally, time to go home.",
	home = "*Yaaa↗aaa↘aaa↗aaaa↘wn*... Welcome back... Did you run into a storm? Sure must suck going outside... Huh? It'll be fine if we go together? Wh-what are you even... *sigh*... What a pain...",
	unlock = "*Yaaaaaawn*... Surrender all your valuables to meeeee... Oh, I was just saying random stuff. No need to take it so seriously... *sigh*... What a pain...",
	touch2 = "Th-that place is off limits...! Even if you try bribing me with cola!",
	mission = "Commander, it might be a good idea to knock those missions out quickly. When too much troublesome stuff piles up, you'll eventually give up altogether.",
	vote = "",
	drop_descrip = "Sailing frigate – Whydah.",
	feeling4 = "Some girls are real junkies for treasure hunting, but it's way too dangerous out there with the storms and hurricanes and whatnot. If you want treasure, Commander, you can get it straight from me... as long as you trade me lots of crisps of all kinds of different flavours.",
	lose = "A storm? ...What a pain... I never shoulda left my room...",
	feeling1 = "*sigh*... Guess I'll just go play games in my room...",
	skill = "So I can go back home sooner and get my beauty sleep... Sink!",
	upgrade = "Am I stronger now...? What a pain...",
	propose = "How strange. Whenever I'm with you, I don't feel scared anymore... If I put this on, does that mean it's okay for me to rely on you even more from here on out? ...Okay then. In return, I'll share my crisps and my treasure with you. Mhm, we'll be together forever from now on, right?",
	feeling5 = "Before I knew it, we ended up in a dating relationship, and you're asking me where I want to go...?! How about just staying in my room... No good? How about the nearest fast food restaurant then? But then I'd have to go outside and interact with all those people... Wait, but what if I bought the store and moved in next door? Th-that way, I'd be able to go on dates with the Commander AND drink cola every day!",
	main = "I may be a pirate, but I'm also a pacifist. *siiiigh*... That's because fighting's a huge hassle...|Bweh... Back to work again? How about I hand all my treasure over to you and go back to lying down?|Commander, mind hooking me up with a lifetime supply of crisps? No good, huh. What if I buy it with my own money? What do you mean that's also a no-go? ...I'm not growing any taller because my diet's too imbalanced? ...Why you...!|You want to make an exhibition out of the stuff I collected? ...I guess that's fine, as long as you don't make me show up. Huh? You'll buy me a new gaming console? Hrmm... Fine, I guess that's not the worst deal in the world...",
	touch = "*YaaaaAAAAawn*... Commander, you're really good at back rubs... It feels so nice I'm drifting off to sleep...",
	voice_key_2 = -1,
	mission_complete = "Woah... Didn't think you'd get this motivated to finish all your work... But, don't forget the most important thing: the rewards! Otherwise, you won't be able to buy crisps for me, right?",
	battle = "...Another fight? Can you swap the little guys in for me instead?",
	id = 9600050,
	gift_dislike = "",
	gift_prefer = "This is even more tempting than potato chips! I'll trade you some treasure for it! Huh? It's free? Thank you...",
	profile = "I've got no interest in swashbuckling and plundering like other pirates. Storms are scary, so I'm fine just chilling back at port. Plus... the pillow is real cushy...",
	voice_key = 960005,
	headtouch = "You're gonna stunt my growth... *sigh*... Well, saying no is too much of a hassle... so I guess just do whatever you want?",
	feeling2 = "I normally send the little guys to run errands for me, so I can just lie down and have crisps delivered straight to me... But, I guess I am still a Tempesta pirate at the end of the day, and doing some stuff on my own... is probably a good thing?",
	login = "Welcome back, Commaaaaaander... Fwuh? You brought me a new flavour of crisps? You sure know how to get on a girl's good side, huh...",
	detail = "*Yaaaaaawnnnn*... Commander, you also interested in the legendary pirates' treasure? Hmm... Since you brought me crisps and cola, I suppose I could hand it over to you. But it's been such a long time... and picking it all up's gonna be a huge hassle...",
	couple_encourage = {
		{
			{
				960002
			},
			1,
			" You get it! Storms are totally scary, aren't they?",
			0
		},
		{
			{
				960001
			},
			1,
			" An adventure? ...Nah, I think I'm good.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[9600051] = {
	hp_warning = "",
	feeling3 = "",
	mail = "New mail... I wonder if a new game just released?",
	expedition = "",
	win_mvp = "",
	home = "Welcome back, Commander~ That's right, what you see before you is Whydah of Tempesta, completely drained after changing into a Halloween costume and now unable to go outside... Well, since you're already here, why not play some games with me?",
	unlock = "You've summoned the angel of tricks and treats... Huh? Why am I dressed like this? Meh, it's too much of a pain to answer that... In any case, gimme candy or else! Commander, time is of the essence here. The sooner I can go home, the sooner I can continue my gaming session...",
	touch2 = "Commander... I can't concentrate on my game at all if you do that...",
	mission = "",
	vote = "",
	drop_descrip = "You've summoned the angel of tricks and treats... Huh? Why am I dressed like this? Meh, it's too much of a pain to answer that... In any case, gimme candy or else! Commander, time is of the essence here. The sooner I can go home, the sooner I can continue my gaming session...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Shoo, shoo. Go on now, go outside and play... Oh, coming! Commander... Um, are you free today? I just got my hands on a new two-player co-op game. Wanna give it a try with me? ...Oh, and if you get tired, we can always lie down together...",
	main = "Fluffy... pillows... and the Commander is even lying down next to me... *yaaaaaaawn*... Zzzzzz...|Want some crisps, Commander? I've got every flavour you can imagine. Go ahead and take your pick.|Candy, crisps, and cola... Perfect. Now, I'll never have to leave my room ever again.",
	touch = "Woah! That was a close one... My hairband almost fell off... Jeez, Commander. I told you not to mess with my halo.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 9600051,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Oh? Ohhh? ...Noo, just a tiny bit short! ...Commander? Hurry up and sit down already. Put the work aside for now – it's gaming time~",
	detail = "Hmm... You want to see some spooky Halloween pirate treasure? But, you're empty-handed right now, so in theory, that's a no-go... But saying no to you is always such a hassle... Well, whatever. I guess I'll take a look around...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9600060] = {
	hp_warning = "You will NOT put the noose on me!",
	feeling3 = "I feel relieved when I return to port and drop my anchor at the pier, like I've come home. Maybe... it's because I know you're waiting for me, Commander.",
	mail = "Check your new letter while you're ahead. Also, don't tell anyone else what it says.",
	expedition = "The commission team is back. Be sure to review the booty thoroughly.",
	win_mvp = "You have some damn nerve, trying to steal MY treasure!",
	home = "Look who's finally home. Nobody turned on you mid-journey, I hope?",
	unlock = "I'm Adventure Galley. I've got nothing else to tell you. Then again, you're letting me stay at this port, so I guess let's get along, Captain. Sorry... \"Commander,\" was it?",
	touch2 = "Huh. More interested in me than my fortune, are you?",
	mission = "You have a new mission. Let's get it done with people we can trust.",
	vote = "",
	drop_descrip = "Sailing frigate – Adventure Galley.",
	feeling4 = "Until very recently, I always thought the only one I could TRULY trust was myself. You've changed me, Commander. It's really nice, having someone you can put your faith in...",
	lose = "Where did I go wrong? No, don't tell me... I've been betrayed again?",
	feeling1 = "My trust is worth more than gold, and you betrayed it...",
	skill = "May the sea bury your ambitions and doubloons!",
	upgrade = "I can better protect my fortune with this new firepower.",
	propose = "Of all the treasure I've gathered, this is by far the most precious. In exchange, I offer my body, my soul... and my unconditional trust. Take them all, and please, store them in a safe place!",
	feeling5 = "I'm considering moving my treasure to this port and building a secret treasury for us. \"Am I sure\"? Why shouldn't I be, when it'll always be under your watchful gaze?",
	main = "Oh, pardon me for staring. It's just, I've made a habit of keeping tabs on people around me... I'm not singling out you in particular.|You promise nothing I'm worried about is going to happen here? You sound certain. Perhaps this place will be good.|While I have worked with pirates, there is no trust between us, only the desire for profit. It's nothing like this fleet you lead, Commander.",
	touch = "What do you want from me?",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Surely booty is considered legal income, right?",
	battle = "I will plunder all you have with these iron claws!",
	id = 9600060,
	gift_dislike = "",
	gift_prefer = "Nice gift. I love it! I'll just go store it with my treasure.",
	profile = "Someone in your position must know at least SOME of my history. Yes, I've sailed with pirates, but don't lump me together with them. I've never seen myself as one, you know...",
	voice_key = 960006,
	headtouch = "Wh-what are you...? Ehh...",
	feeling2 = "My treasure still rests where I left it. Alas, it cannot stay there forever – someday, I need to relocate it to a safe place... Who knows, maybe that will be this port?",
	login = "You're back. Here's your schedule for today. Try not to let others know about it – nothing good will come of it.",
	detail = "These chains? They follow me like the memory of when I was deceived and betrayed, whispering to me – \"you can't trust people\"...",
	couple_encourage = {
		{
			{
				960001
			},
			1,
			" Let's race to see who can seize all the treasure the quickest!",
			0
		},
		{
			{
				960004,
				960005
			},
			1,
			" Stay away from me...",
			0
		}
	}
}


_G.pg.base.ship_skin_words[9600061] = {
	hp_warning = "",
	feeling3 = "",
	mail = "\"A letter? The writer of it will be my next kill...\" Actually, this might be an important letter. You should check it now.",
	expedition = "",
	win_mvp = "",
	home = "\"Welcome home, Master! I've been waiting with bated breath for you this whole time and sharpening my blade, like this – shwing, shwing...\"",
	unlock = "\"Ahahahah! I've finally found yooou, Master! Dinner is ready, so just follow me to the... You're not hungry? Aww, but the meat is fresh off the bone...\" Commander? Why are you backing away?",
	touch2 = "\"You still love me, despite how much I've changed... Heehee...\"",
	mission = "",
	vote = "",
	drop_descrip = "\"Ahahahah! I've finally found yooou, Master! Dinner is ready, so just follow me to the... You're not hungry? Aww, but the meat is fresh off the bone...\" Commander? Why are you backing away?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "\"I want to be with Master forever and ever... But how... Oh, I know! If we just eat each other... Heehee...\" Cut! How did that sound? Hm? That wasn't ALL acting, you know. I meant at least a little... What about the eating each other part? W-well, THAT was obviously just my line!",
	main = "This set is brilliant for building atmosphere. Ahem, let's see... Ahh! There you are!|How can I get you to love me and me alone? ...Aha! I'll just take my blade and cut up anyone who stands between you and me... Hehe, hehehe♪|\"I'm so sorry, Master. The screams of our to-be-dinner must be annoying. I'll go make them quiet down... Oh, but don't come and look, okay?\"",
	touch = "\"Yes, Master? What can I do for you?\"",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 9600061,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "What was that for?! There goes the mood I'd set up!",
	feeling2 = "",
	login = "\"Welcome home, Master! I've prepared dinner for you, loaded with savoury meat. If you're still left feeling hungry... I can find more meat for you.\"",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9600070] = {
	hp_warning = "My remedy won't reach me in time!",
	feeling3 = "You're free to take whatever you like out of my storage, be it treasure, art, or whatever else. You needn't even ask for my permission. Frankly, I don't remember what is in there!",
	mail = "I've brought all your letters, Commander. Read them at your leisure. I'll be waiting right here.",
	expedition = "Are those girls your entourage? My, they're so cute!",
	win_mvp = "Heehee. Underestimate not the might of a storm.",
	home = "Welcome back, Commander. I see your mission went well. May I come with you sometime? I'd love to see the sights along the way. After the mission is complete, of course.",
	unlock = "Greetings, Commander. I'm Ganj-i-Sawai. It's a pleasure! Is this place your port? My, it's so much bigger and grander than I expected! Do you mind if I walk around? And if you could join me, that'd be even lovelier. Heehee.",
	touch2 = "Hmm. Commander, this is rather poor manners.",
	mission = "Shall we begin on the day's work, Commander? Delaying won't do you any good.",
	vote = "",
	drop_descrip = "Sailing frigate – C Ganj-i-Sawai.",
	feeling4 = "So, are you feeling better? By putting our foreheads together, I can direct my healing energy to you! Oh, why are you blushing all of a sudden? Don't be shy, now!",
	lose = "O rain, heal our wounds and ease our pain.",
	feeling1 = "I'm off to look at that unique building over there! By myself, I mean. You just focus on your own business.",
	skill = "O storm, sweep away all disasters!",
	upgrade = "My command over the wind grows stronger!",
	propose = "I've already started picturing our future together! We'll hoist sails and embark on far-flung voyages, we'll sleep in a curious and magnificent building we built ourselves, and we'll sing and we'll dance... Regardless of what the future has in store, I'm excited to be experiencing it with you!",
	feeling5 = "I shall be your closest companion, and you shall be mine and mine alone... There, I cast a spell of love on you. Now we will always be together, no matter what may happen!",
	main = "La-laa-la-laa♪ Do you like it, Commander? I've been studying some, um, \"modern\" music, I suppose?|*sniff sniff*... This scent... It could use some spices to really take it to the next level. Some black pepper, some cardamom, ginger, prickly ash, turmeric, cinnamon, cayenne pepper... That should be plenty!|I read about all sorts of interesting ancient ruins in the port's travel brochure! Let's go visit them sometime. Pleeease? Come with me!|Top ten classic wine bottles? There's no way this magazine is right. I have heaps upon heaps of bottles like that in my storage.",
	touch = "Ah, do you wish to see my dance? Certainly!",
	voice_key_2 = -1,
	mission_complete = "Mission rewards? Where? Oh, you mean these? I thought they were random things just left there... You must forgive me. Please don't be mad!",
	battle = "O storm, grant me strength!",
	id = 9600070,
	gift_dislike = "",
	gift_prefer = "Thanks! I love this gift! What about you, Commander? If there's anything you want, it's all yours~",
	profile = "Well met. I am Ganj-i-Sawai – I'll be docking here for the foreseeable future. In the name of the wind, blessings be upon you and your port. May our days together be filled with bliss and wonder!",
	voice_key = 960007,
	headtouch = "Oh? Is this your way of conferring blessings? Thank you kindly!",
	feeling2 = "I yearn to build a grand, beautiful palace in this port! Won't you look at my blueprints? ...Looks good? Thank you. Then while we're at it, could I receive your approval?",
	login = "I made you some coffee, Commander. I also threw in some spices. How does it taste? Personally, I can't get enough of this stuff!",
	detail = "I was just drafting a renovation plan for your office. It's the most important place in the port, and I believe it should feel more special. For instance, by adding a dome to the ceiling and inlaying it with gemstones.",
	couple_encourage = {
		{
			{
				960005
			},
			1,
			" Ah, yes, having too much treasure truly is a burden.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[9600071] = {
	hp_warning = "",
	feeling3 = "",
	mail = "You're still in touch with the outside world? Heh... That's okay. Soon, you'll be mine.",
	expedition = "Your entourage has entered the area? And they're transporting goods for you? You should go speak to them, then! Oh, but don't tell them about me.",
	win_mvp = "",
	home = "You seem rather tired, Commander. It must be the influence of a disaster... I'll protect you, but you must undo the seal on me first!",
	unlock = "You heard my song? Thank goodness... Someone has finally come for me! Say, could you please remove the seal on me?",
	touch2 = "Eep! M-my, that's quite bold... You will pay for doing this! I hope you're prepared!",
	mission = "Go ahead and do your work. I'll be here, waiting.",
	vote = "",
	drop_descrip = "You heard my song? Thank goodness... Someone has finally come for me! Say, could you please remove the seal on me?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Why are you making that face? Soon you will be one with me, one with the disaster... Heehee. Merging to be forever together is just another form of love!",
	main = "Oh. The bandages around my arms came loose. They have nothing to do with the seal! Only YOU can undo it!|Once you've undone the seal, I'm going to search the undersea ruins, then... Hm? You want to come with me? Sure, but by then you'll already be– Err! Never mind I said anything!|Hm? You adore my singing? Ah, then I will keep singing for you! I'll sing for you forever... and ever... and ever...|Destiny has chosen you to rescue me, so it will be child's play for you to undo the seal. N-no, there's nothing dubious about it all!",
	touch = "Curious about the body of a mermaid? Come closer and have a better look. That's it, take it aaall in.",
	voice_key_2 = -1,
	mission_complete = "Are you finished with your work? You look exhausted – come here and rest by my side. I'll sing a song to ease your heart.",
	battle = "",
	id = 9600071,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "I'd hate to let go of such a reassuringly warm hand...",
	feeling2 = "",
	login = "My energy wanes further and further. Please undo the seal quickly... Hm? You think I look full of energy? Well, that's because I'm happy to see you!",
	detail = "I put a seal on myself for fear of being taken by the disaster, and when I awoke, my powers had purified the sea, yet I could not undo the seal. Please, traveler who heard my song, I have no one else to turn to! Help meee!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9600072] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "This machine is amazing... Oh, Commander, you should try it, too. I've let you look inside me, so it's only fair that I get to know all about you~",
	unlock = "Welcome, my fellow sufferer of sickness~ This machine can reveal the true nature of things... Hahaha, why don't we show each other what we've got? Everything about me... and everything about you that I can't stop thinking about.",
	touch2 = "Thump, thump, thump... My heart is racing... Huh? Can you see it?",
	mission = "",
	vote = "",
	drop_descrip = "Welcome, my fellow sufferer of sickness~ This machine can reveal the true nature of things... Hahaha, why don't we show each other what we've got? Everything about me... and everything about you that I can't stop thinking about.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "You've been staring at me for a while... It's my turn to see through you now, Commander, until you're all mine~ This is the real me... the Ganj-i-Sawai who wants you all to herself~",
	main = "Do you think the silhouette onscreen is my true self? Don't you wanna know more?|Commander, I can show you around the hospital after this exam. But when I do... don't you dare let go of my hand~|The truth as viewed through the machine, and the truth as felt through direct touch... Want to find out how they differ, Commander?",
	touch = "Don't you wanna get closer and see things more clearly? Heheh, then let's get this machine out of the way~",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 9600072,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "When you touch me... it feels like you're seeing something deep inside me.",
	feeling2 = "",
	login = "Hmm... I'm not feeling so well. Can you help me find out what's wrong? Yes, take a veeery close look♪",
	detail = "Don't you think this silhouette is just beautiful? Who knew life was bursting with such passion and energy? Commander... Do you find it beautiful, too?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9600080] = {
	hp_warning = "Hm? Heehee. You must really want to be torn to pieces.",
	feeling3 = "You smelt nice yesterday. You feel nice today. You– Hm? No, I'm not going to eat you. If I do, I won't know what you'll be like tomorrow.",
	mail = "A letter? Heehee. I'm curious how you engage with other humans.",
	expedition = "That commission team is like a school of fish, swimming from place to place.",
	win_mvp = "Repulsive. Not even worth a taste.",
	home = "Do you want a good drink to wash away your fatigue?",
	unlock = "Good morning, human. I am Fancy. If I'm to follow your customs, I suppose I should call you... \"Commander\"? Yes. I'm glad you don't seem to fear me, even though I'm known as a \"being of the abyss.\" I'll be watching you to see what sort of human you are.",
	touch2 = "Mm... Is this... another custom of yours? Okay then.",
	mission = "You still have missions to do. Get to it.",
	vote = "",
	drop_descrip = "Sailing frigate – C Fancy.",
	feeling4 = "Remember, Commander – I wear this mask to protect you. Acting on your curiosity to see the \"real me\" will only hurt you.",
	lose = "We were just messing around, no? Should I take this more seriously?",
	feeling1 = "You bore me, human. I'm starting to think food is all you're good for.",
	skill = "Cling clang. Turn to scrap.",
	upgrade = "Commander♡ Commander♡",
	propose = "I can't understand you, and yet, without you I would dry like I hadn't had water, atrophy like I hadn't eaten food, and tire like I hadn't slept. Therefore, my instincts tell me to accept this from you. Heehee. Now we'll be together forever.",
	feeling5 = "You still want to see the \"real me\"? If the truth is worth more than your life, then I'm not one to deny you it... There, happy? Did it scare you? Do you regret it? Can you only tremble in fear as you wait for the end? ...No to all of those? Now I see those eyes you've been looking at me with the whole time... my Commander.",
	main = "Commander! Oh, Commander! Heehee. Does it make you happy when I call you like this?|I won't treat you as prey anymore. Are you happy? This isn't because you're inedible, it's just... Hmm... I still need time to determine which category to put you in.|My interests? What does that mean? What is there beyond surviving and eating? For a human commander, you sure say funny things.",
	touch = "Hm? You want to see my eyes? No.",
	voice_key_2 = -1,
	mission_complete = "There's not a single edible thing among these mission rewards...",
	battle = "Roll up the waves and tear the sea apart.",
	id = 9600080,
	gift_dislike = "",
	gift_prefer = "I feel weird. What should I say... Thank you?",
	profile = "Nice to meet you. Hm? Is that not what you say on your first meeting? I see. Your explanation is quite interesting... As are your body temperature, body odour, form, mass, and texture, too...",
	voice_key = 960008,
	headtouch = "Hm? What is it?",
	feeling2 = "If nothing fun happens soon, I will raze your port to alleviate my boredom.",
	login = "Welcome back, Commander. That's okay, right? Heehee, don't worry. I'll keep your \"nest\" safe while you're away.",
	detail = "Some predators use their gorgeous looks and beautiful voices to lure prey in. Heehee. Me? I'm simply following my instinct as a being of the abyss to communicate with you... Truth be told, even I don't really know whether I'm a monster or something else.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9600081] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Come inside and lie down with me. I'll massage you from every which side.",
	unlock = "Oh... You've found me. This is horror fashion, and I've heard it's pretty popular. Boo. Scared?",
	touch2 = "Ahh... Even I've started to... derive pleasure from you doing this...",
	mission = "",
	vote = "",
	drop_descrip = "Oh... You've found me. This is horror fashion, and I've heard it's pretty popular. Boo. Scared?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I've heard that you can imprint yourself upon humans' hearts by giving them various kinds of stimuli. This must be true of you as well. That's why I'll continue scaring you to make you remember me.",
	main = "Heehee. I'm now going to launch a surprise attack on you as the incarnation of fear. A fear that follows you like your shadow. Are you ready to shake in your boots?|Oh. Am I still not scary enough for you? Fine, time for something else. My tentacles and I will teach you the fear of being hunted by a predator.|By the way, what even is \"fear\"? Despite everything I've done, you're still not afraid. Was there something wrong in the knowledge I learned?",
	touch = "Heehee. Do you dare to... stick your finger inside?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 9600081,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Heehee. I'm even more frightening than usual, and you still want to touch me?",
	feeling2 = "",
	login = "I'm once again going to show you my frightening side today to get you to pay more attention to me.",
	detail = "Heehee. How do I look? Does this assortment of horror elements send terrifying chills down your spine? ...Hm? Explain them to you? Well, there's the mummy bandages... and that's about it. Hahaha.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9600090] = {
	hp_warning = "If that's how it's going to be...",
	feeling3 = "Let's leave together when your work is done. The port is a vast place, and I'm liable to get lost on my own. Heehee, that's not an excuse, I'm serious! Come on, let's go together.",
	mail = "Commander, I've brought a letter for you. How will you reward me, hmm?",
	expedition = "The commission team is back. Let's go and see if they've brought back anything good.",
	win_mvp = "This was child's play – yet again.",
	home = "Welcome back, Commander. Heehee, I see you've brought back a real haul. Bravo!",
	unlock = "Ahh, Commander. I'm Amity. Here's hoping we'll get along. So, let's cut to the chase and get to know each other, shall we?",
	touch2 = "Do that one more time and I'll stab you with my horn.",
	mission = "You've got a lot of missions. Better get started. That work isn't gonna do itself.",
	vote = "",
	drop_descrip = "Sailing frigate – C Amity.",
	feeling4 = "I've come up with a way you can thank me for helping you earlier. How about you come with me on a seaside stroll after work is over? ...Ah, wonderful. Then get your work done and clock out on time! Naturally, I'll help you along the way.",
	lose = "Since things are looking dire, let's fall back.",
	feeling1 = "Oh, could you keep your distance? I think that'd be best for both of us.",
	skill = "Sink!",
	upgrade = "Ooh, getting stronger feels nice.",
	propose = "I've got the ring, so it's too late for second thoughts. You're mine, which means there's no getting away. Of course, I'm also yours, so you better hold my hand so I can't run off.",
	feeling5 = "Hm? You look like someone who wasn't expecting to see me here – am I right? I've been waiting here for ages, and I'm starving. You'll do the right thing and join me for a late-night snack, won't you?",
	main = "Here, Commander. You were looking for these papers, no? I found them for you. \"How did I find them\"? Don't you dare assume that I walked off with them by mistake.|What? Your juice tastes quite bitter? Oops, that's my fault. I accidentally got you iced coffee instead of juice! Excuse me while I go and get you the right drink.|I'll gladly help with your work if you'll do me a little favour. I haven't thought of what the favour is yet, but I'll figure it out later.",
	touch = "Commander, could you open this bottle for me? ...No, you see, I'm asking for help because I really can't get it open. I'm serious.",
	voice_key_2 = -1,
	mission_complete = "Commander– Whuah! Don't freak out! All I did was nudge your face with this drink I brought for you.",
	battle = "They've taken the bait.",
	id = 9600090,
	gift_dislike = "",
	gift_prefer = "Commander, thanks for the present~ I really like it!",
	profile = "Feigning a shipwreck while loading your cannons, then once your targets get close, you take them by surprise and sink them all in one fell swoop – don't you think that kind of strategy suits me just perfectly?",
	voice_key = 960009,
	headtouch = "How does it feel to touch my silky-smooth hair, hmm?",
	feeling2 = "If you've got nothing better to do, tell me about yourself. I'll tell you all about me in return. It's only fair that we both know one another, no?",
	login = "I've brought all your papers, Commander. Eeevery last one. Time to get to work!",
	detail = "My trick to making friends, you ask? There isn't one. I just read the room, gauge reactions, and say what sounds right... What was it called? \"Getting on their good side,\" was it?",
	couple_encourage = {
		{
			{
				960008,
				960010
			},
			1,
			" What are we hunting this time?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[9600091] = {
	hp_warning = "",
	feeling3 = "",
	mail = "I'll be taking this letter of yours!",
	expedition = "If you're going to keep ignoring what the commission team brought back, I'm just going to take it.",
	win_mvp = "",
	home = "Wow! You're on my tail. I've been looking forward to the day that you finally catch me!",
	unlock = "Well, well, look who's got nowhere left to go. Kidding, kidding. I win again, so I'll be taking your treasure! Follow me down if you're brave enough to jump.",
	touch2 = "Can't keep your hands in check, hmm? Heheh, you must really want to be tied up.",
	mission = "",
	vote = "",
	drop_descrip = "Well, well, look who's got nowhere left to go. Kidding, kidding. I win again, so I'll be taking your treasure! Follow me down if you're brave enough to jump.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "You yourself clearly made the choice to jump off – and the fact is, you've played right into my hand. Have you still not figured it out? I stole the treasure to make you chase after me. All this time, the real treasure I was after was you.",
	main = "Why don't you come with me, Commander? Then I won't run away again even if you catch me!|You can just about make out the streets below... How does it feel to overlook everything, hmm?|Go on, guess which is more precious to me – the treasure I stole, or you.",
	touch = "Come cloooser, Commander. You'll never catch me from that far away!",
	voice_key_2 = -1,
	mission_complete = "Your mission is over, and yet you're still going to chase after me?",
	battle = "",
	id = 9600091,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Do you want me to take off my hat?",
	feeling2 = "",
	login = "I've been waiting, Commander. Think you'll manage to catch me this time, hmm?",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9600100] = {
	hp_warning = "Hey! You're pissing me off!",
	feeling3 = "Mornin', Commander! Mind if I step in as the secretary? Been wanting to just be around you lately, so, y'know... Bein' a secretary entails tons of paperwork? Ugh... Urggghhhh!",
	mail = "Got a letter... Readin' too many words affects my appetite, so you take care of it.",
	expedition = "Oh! Commission team's back! Let's go rob 'em! ...Oh, they're on our side? Right! Silly me, I forgot!",
	win_mvp = "Cough up them valuables, now!",
	home = "Yo-ho! Back on land I see, Commander! Betcha brought back a huge haul, judgin' by that smile! Need a hand inspecting all them goods?",
	unlock = "Yooo! You that Commander I've heard tons about? Damn, you look pretty capable. So, where we goin'? My eyes're set on claiming not just you, but all the treasure in the whole wide world! Mwahahaha!",
	touch2 = "This how you make friends 'round here? Lemme give it a shot♥",
	mission = "Still got unfinished missions, don'tcha? C'mon, no laziness allowed on the path of conquest and plunder!",
	vote = "",
	drop_descrip = "Sailing frigate – C Portsmouth Adventure.",
	feeling4 = "What the sticky black stuff all around my body is? It's my miracle remedy! Ya can drink it or rub it on yourself, and it's got all kinds of mind-blowin' benefits! Oh yeah, said your back hurt the other day, didn'tcha? Well, I can spread some of this on there 'n' give ya a massage with my feet!",
	lose = "This is just as frustratin' as when I get a smaller share of the booty!",
	feeling1 = "You're NOT gonna make it out to sea with me if ya don't get it together!",
	skill = "I'm unstoppable on the open ocean!",
	upgrade = "Ahahaha! I'm plenty mighty as it is!",
	propose = "Huh? What's this? I'm guessin' this is, like, proof of our buddyship? On the finger it goes, then! Oh yeah, I'm in an amazing mood now! So, what do I do now! The choice is all yours! We're buddies who sail the seas together, after all!",
	feeling5 = "Tonight, we're having a sleepover at your place to deepen our bonds, my bestest buddy! Also, I roll A LOT in my sleep, so I miiight end up squishin' ya with my– *grumble*... Man, I'm hungry! Let's look around 'n' find some grub 'n' drinks!",
	main = "Try THIS! Mwahaha! Betcha can't breathe while you're caught between my legs! This is my new knockout move! Ain't it– Wait, what? You passed out?|Gaaahhh! I'm done being a frickin' secretary! *chug chug*... Can't believe you do this crap day in, day out... *chug chug*... I pity you! So much I just wanna eat you up! Heehee♥|Check it out! I busted my butt gettin' my hands on this stupidly expensive but tasty booze! First sip goes to me! *chug chug*... PFFFT! THAT'S SOUR AS HELL! It's worth the price, but it's not my thing... Here, it's yours!",
	touch = "Heeey, I've only had a feeew! Hehehehe... Y'want some booze too?",
	voice_key_2 = -1,
	mission_complete = "Finished a mission? Well, I didn't do nothin', so the spoils're all yours!",
	battle = "Hahaha! I'mma show you what it looks like to break through the seas!",
	id = 9600100,
	gift_dislike = "",
	gift_prefer = "A gift from you? Mine now! All mine! Thanks!",
	profile = "Ya wanna get to know me? Takes guts to just ask like that, so I'll tell ya whatever ya want. I much prefer outspoken folks like you over stiff bluecoats! ...So when're we talkin'? Oh, when I've got time and plenty of booze and food on my hands, THEN we'll talk!",
	voice_key = 960010,
	headtouch = "Yeah? This hat's proof of my might. If ya want it, ya gotta work for it!",
	feeling2 = "*yaaaaaawn*... Sooo bored... Let's have a strength contest! You win, ya get a box full of gold! ...What? Ya care more 'bout what's in my bottle? Yeah, we're not gonna discuss that.",
	login = "There go Commander 'n' Portsmooouth♪ Set sail for great treasure forthwiiith♪ – that'll be our sea shanty next time we sail!",
	detail = "Booty! Booze! Grub! I want as much as I can get! Didn't think there was a like-minded person out there who could satisfy me, but you might just be the one! So, whaddya say you 'n' I go on an endless adventure to appease them desires, eh?",
	couple_encourage = {
		{
			{
				960008
			},
			1,
			" Fancy, cut it out with those weird noises! It's creepy!",
			0
		},
		{
			{
				960009
			},
			1,
			" That's what you mean by \"getting along\"?",
			0
		},
		{
			{
				960011
			},
			1,
			" It's piratin' time!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[9600101] = {
	hp_warning = "",
	feeling3 = "",
	mail = "You're gonna read letters NOW? Fine... Just watch yourself so ya don't end up like me.",
	expedition = "The commission team's back? Well, I can't do much like this...",
	win_mvp = "",
	home = "Grrr... Can't move... It was supposed to be the Commander getting stuck like this... Oh, hey, haha... Welcome back, Commander...",
	unlock = "Wait, Commander?! You're here way ahead of time! N-no, this is NOT what my special surprise is supposed to be!",
	touch2 = "Eek! W-well, if this'll help ya pull harder, then go ahead...",
	mission = "A new mission? Yeah, you bet! Your new mission is to help me!",
	vote = "",
	drop_descrip = "Wait, Commander?! You're here way ahead of time! N-no, this is NOT what my special surprise is supposed to be!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "I'm stronger, but I'm still stuck!",
	propose = "",
	feeling5 = "Ugh... Help me loose here 'n' ya can do whatever ya want to me! ...Huh? You can do anything to me right now anyway? Well, I guess that's true... Hey, wait! Wait a sec!",
	main = "Pretty nice idea for a trap? Uh, thanks? Forget about that! When are ya gonna help me get unstuck?!|If you're gonna pull, start from my legs. If that doesn't work, my waist... L-leave my head for last, alright?|Ugh... Are ya even gonna try to help me? You BETTER not be thinkin' about leaving me like this! We won't be able to sail the seas!",
	touch = "You're gonna have to try harder!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 9600101,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Th-the horns look real scary, don't they? ...That's not an invitation to grab 'em!",
	feeling2 = "",
	login = "I'm NOT in the mood to sing right now! ...Wait until my mood improves? Hey, how about HELPIN' me here, huh?",
	detail = "Grrr... This trap was supposed to immobilise you, but I tripped and, well... Is this karma for tryin' to prank my best buddy?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9600110] = {
	hp_warning = "Owch... It's okay. I'm not out of the fight yet!",
	feeling3 = "You can pick any key from my hat you want. They each open up a different chest filled with my treasure. As for where the chests are, the fishies will show you where!",
	mail = "Hm? Is this one of those \"e-mails\"? How do you open it? ...Whoa. I didn't peek, though.",
	expedition = "The commission team is back with treasure. Yup, I was right about that spot!",
	win_mvp = "We won! Did pretty well, didn't I? Let me hear a bit of praise!",
	home = "I knew you were back! I heard it from all the way over here. Seriously! I can hear sounds from super duper far away! ...How? Well, that's just my special ability! Heehee.",
	unlock = "Hmm? Are you that Commander everyone's been talking about? Pleasure meeting you. I'm Dolphin. Now let's do a handshake of friendship! Glad to be working with you.",
	touch2 = "Whuh?! What are– Hey! You can't do that!",
	mission = "Keep at it, Commander! There's still work to do.",
	vote = "",
	drop_descrip = "Sailing frigate – C Dolphin.",
	feeling4 = "Look, Commander! I used my special ability to make the fishies form a big heart! I made it just for you, heehee. Do you like it?",
	lose = "It's okay! We'll win next time! At least we're all okay!",
	feeling1 = "Sorry, I'm not in a good mood. You should stay away for a while...",
	skill = "Found you!",
	upgrade = "Whew! You made me stronger. Wait until you see me in action!",
	propose = "I accept this unique ring, and the thing that's more valuable than any treasure in the world – your love! I'm going to treasure this dearly! Come here! I'm spreading my arms because I want a hug, silly. Heehee. Hold me in your arms!",
	feeling5 = "Hey, Commander, these fishies will point you to my most valued treasure... Hm? Why did they all gather around you? Gosh, I have no idea! Heehee. Can you guess why?",
	main = "*yawn*... *yaaawn*... Oh, look at the time! Boy, these games are all so fun. Just gonna play a little longer... Do you wanna join me, Commander?|Alrighty. You can eat this octopus, or keep it as a pet if you want. It's all yours, Commander! Oh, eww, my hands got all slimy... I'm gonna go wash them!|It's so fun, being able to talk to the fishies at the aquarium. We should go there again sometime, Commander!",
	touch = "Heehee! You're not gonna be able to surprise me, Commander! I can hear every sound you make from a mile away.",
	voice_key_2 = -1,
	mission_complete = "Job done! Let's check the rewards... I've never seen gold and items like these before.",
	battle = "Focus, girls! We're setting off!",
	id = 9600110,
	gift_dislike = "",
	gift_prefer = "Treasure! Thanks, Commander~",
	profile = "I'm Dolphin, and I'm a pirate, but it might be more accurate to say I'm a treasure hunter. Anyway, if you can call it a treasure, I can locate it! If you come up with any treasures you want, let me know. I'm an expert at tracking treasure down!",
	voice_key = 960011,
	headtouch = "Hm? Is my hat the real deal? Uhh... I dunno. I just wear it 'cause it's cute.",
	feeling2 = "Hmm... You're fun to look at, but my eyes will tire if I stare all day. I'm gonna rest my eyes for a bit and... It's obvious I'm peeking through my hands? Heehee, you're right. You got me.",
	login = "You've arrived. Let's get started on today's work. Hmm, there's quite a lot, but it's only half as much if we split it. We can do this!",
	detail = "This is a fossil of a weird creature with five tentacles and three eyes! Bristol asked me to find it! If there's any treasure YOU want, just let me know. I can find anything in the world with my special ability!",
	couple_encourage = {
		{
			{
				960001,
				960002,
				960003,
				960004,
				960005,
				960006
			},
			1,
			" I know where the treasure is! Follow me!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[9600111] = {
	hp_warning = "",
	feeling3 = "",
	mail = "A letter for you? Weird. Where was it sent from? How did it make its way here?",
	expedition = "",
	win_mvp = "",
	home = "Fooound you, Commander! Heehee. I said I'll always find you no matter where you go, remember? I have an ability that lets me pinpoint your location!",
	unlock = "*yaaawn*... Was it you who awoke me? Heehee, thanks. Oh, don't be scared! Sure, rising out of a coffin is a bit creepy... but still, I'm not going to hurt you. Promise.",
	touch2 = "Wanna hear my heartbeat? ...Hm? You don't hear anything?",
	mission = "A mission? What kind? Let me have a look.",
	vote = "",
	drop_descrip = "*yaaawn*... Was it you who awoke me? Heehee, thanks. Oh, don't be scared! Sure, rising out of a coffin is a bit creepy... but still, I'm not going to hurt you. Promise.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "The rain stopped? No, it didn't. It'll keep raining as long as I'm awake. See? It started again. Now be good and stay here. Now that I'm awake, I don't wanna be left alone again.",
	main = "Why was I sleeping in here? Probably due to the curse... What's your guess? Because I have no clue. I don't remember anything that happened before I fell asleep.|Look at that spider on the ceiling! Heehee. I've never seen one that weird before! Do you want me to go and catch it for you?|The rain still hasn't stopped. If you're feeling bored, how about we look around for secret treasure in here? Places like these always have treasure! Sometimes!",
	touch = "Thanks. Keep hugging me and the pain will all disappear.",
	voice_key_2 = -1,
	mission_complete = "Is this mission done? That didn't seem so hard. Let me have a shot at the next one.",
	battle = "",
	id = 9600111,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "The screw on my head? I think it's just decorative. I'm not too sure, myself!",
	feeling2 = "",
	login = "The rain isn't stopping anytime soon, so we just have to wait it out. Have a nap, if you wanna. How do I know it's not stopping? Umm, instinct, I guess? A prediction? I'm not sure either. Heehee.",
	detail = "Owch... These stitches kind of sting... The pain will go away if you give me a warm hug, though!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9600120] = {
	hp_warning = "You got my dress dirty... I won't even spare you the time to write a will!",
	feeling3 = "You look deft at cleaning up a mess... Help me out with this. It'll be done in five minutes. If you want me to do it, well... I think you know which option is the best.",
	mail = "Saw a letter addressed to you just a minute ago. If you don't go looking for it now, you may never find it again.",
	expedition = "Time to go and greet the commission team. If they found any glittering treasure, bring it all to me.",
	win_mvp = "Heh. I lay claim to everything.",
	home = "Oh. You're back in one piece. Say, isn't my makeup terrific today? Then bloody say something good about it already.",
	unlock = "I'm Queen Anne's Revenge, and brilliant treasures are my favourites. Hm... You're the Commander, no? Then help me pack up this pile of stuff. I want to admire it later tonight.",
	touch2 = "You couldn't resist how beautifully I was dressed? Heheh... Are those your final words, then?",
	mission = "Hankering for a break when you've not even finished your missions? Go on. Treasure doesn't grow on trees.",
	vote = "",
	drop_descrip = "Sailing frigate – Queen Anne's Revenge.",
	feeling4 = "Quiet. I just need another 30 bloody minutes. It takes time to get into a dress as posh as this. If you're so keen, why don't you come in and give me a hand, eh?",
	lose = "Meddlesome sods... Next time, I will sink you all myself.",
	feeling1 = "If you whinge any more about my plans, your documents won't be the only things getting burned.",
	skill = "You'll be fish food when I'm done with you...",
	upgrade = "Heh. Now I can sink all of my foes...",
	propose = "I've finally got it... The glittering oath ring I've seen in my dreams. Heehee. It goes perfectly with my beauty, doesn't it? Once you put it on, you'll never get to regret it for the rest of your life... You wouldn't dream of regretting it? Heh. Good.",
	feeling5 = "You can have this ring. No, it's nothing special. I've got loads, so pick whichever you like. But first, answer me this: Crows covet sparkling things, so... do you want me in that same way?",
	main = "Impeccable makeup, flawless fashion, and a perfect Queen Anne's Revenge. I'm right chuffed. Hm? No, I'm not planning on going out.|If I encountered someone like you whilst pirating, Commander... Heheh... Now that would be exciting.|There's STILL a water leak in the bathroom? Heh. Heheh... I'm going to send the mechanic to the bottom of the sea.",
	touch = "I'm drop-dead gorgeous, I know. Now will you adjust my bloody hems?",
	voice_key_2 = -1,
	mission_complete = "Is that everything? I know a way to make more dosh quickly, if you're interested. Heheh...",
	battle = "What a bother... Can't I just give orders from home?",
	id = 9600120,
	gift_dislike = "",
	gift_prefer = "Such an exquisite treasure... I'll take good care of it.",
	profile = "I'm Queen Anne's Revenge. The name's written on my stern, so read it your bloody self. Don't nark me if you don't want to end up on the seabottom. Heheh...",
	voice_key = 960012,
	headtouch = "As long as you don't mess up my hair ornament. *sigh*... Don't worry. There's nothing naff about making friends with octopuses in the sea.",
	feeling2 = "Clean my room? If it nags you so much, then do it yourself, why don't you? I've got better things to do.",
	login = "You've come. I'm preparing to go out, so I'll be just another minute. If you're free, then bloody clean the place up.",
	detail = "Look, it's just a giant bother. If I wanted to go outside, I'd have to dig my room key out of my treasure chest, then find the way from my bed to the door. That said, I do go out when there's something valuable for me to collect.",
	couple_encourage = {
		{
			{
				960015,
				960016
			},
			1,
			" You'll get your share when we divvy up the booty.",
			0
		}
	}
}


