_G.pg.base.ship_skin_words[9600130] = {
	hp_warning = "I won't back down just because of a few wounds.",
	feeling3 = "This is now the fourth time you've slid your cap today. Do you like it when I stare at you or something?",
	mail = "New letters have arrived, Commander. Do you need me to sort them?",
	expedition = "A commission has been completed. I'll report the details to you later.",
	win_mvp = "Where's the next battlefield?",
	home = "Commander, did you find leads on the enemy? I see. Then I'll go on another patrol.",
	unlock = "Wait... Alright – the safety level is acceptable within this zone. Greetings, Commander. I'm Lyme. I will fight by your side from now on. Your orders?",
	touch2 = "Commander, this outfit is special... Only I can take it off.",
	mission = "New missions have been added. I await your orders, Commander.",
	vote = "",
	drop_descrip = "Sailing frigate – Lyme.",
	feeling4 = "You've defeated me again. There must be some way to clear this more efficiently... Hm? Games are meant to be relaxing, so I shouldn't take it so seriously? Maybe so, but I don't like being defeated.",
	lose = "We lost? I will correct this mistake.",
	feeling1 = "Commander, I'm going to reevaluate the necessity of your orders.",
	skill = "Face your fate!",
	upgrade = "I'm getting stronger. Good.",
	propose = "So this is a pledge of love. I see. I, Lyme, accept your pledge, and I swear with my strength the following oath: Your whole being is irreplaceable to me.",
	feeling5 = "To more efficiently carry out your orders, I need to get to know you better and be able to guess what you're thinking. Then, once I manage to defeat you, that will be definite proof that I'm able to carry out your orders. Probably.",
	main = "I've finished defining a new workflow. Take a look, Commander. If you find any issues, I'll deal with them.|Stacks of papers are put so close together that they risk getting mixed up, and ornaments are placed around seemingly haphazardly... Has your working environment always been like this, Commander?|One more time, Commander! I'll finish the mock battle faster, with better results this time! Give me another chance!",
	touch = "Commander, are you nervous about our coming battle? Don't be. You'll be fine as long as I'm here.",
	voice_key_2 = -1,
	mission_complete = "All objectives have been met and exceeded. The mission was completed flawlessly.",
	battle = "Commencing annihilation.",
	id = 9600130,
	gift_dislike = "",
	gift_prefer = "This is a good present. Thanks.",
	profile = "I'm Lyme, a monster hunter. My technique is to calmly and adeptly deal a crushing blow to my target. Needless to say, your orders take precedence. I won't interfere with your plan.",
	voice_key = 960013,
	headtouch = "Commander, physical contact outside the battlefield makes me lower my guard.",
	feeling2 = "Commander, it's most optimal when the things on your desk follow the centre line, so I went and organised them. I adjust the balance and angle so it ought to be perfect.",
	login = "I'm right here, Commander. I'll keep watch so you can work with peace of mind.",
	detail = "What are your orders for today? Hunt monsters? Or help organise your workflow? ...You want me to play sports with you? Of course. I won't let you win so easily.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9600131] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Where did you come fro– No, stay back! I don't know what you're after, but you won't get to do as you want with me!",
	unlock = "Ugh... Where am I? Why do I feel so weak? Did I... trigger a trap that corrupts its prey? Grgh! Was it you who laid the trap? You will pay for this!",
	touch2 = "The corruption is advancing... It's... taking over me...",
	mission = "",
	vote = "",
	drop_descrip = "Ugh... Where am I? Why do I feel so weak? Did I... trigger a trap that corrupts its prey? Grgh! Was it you who laid the trap? You will pay for this!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "You've come to help, but I... I can't control myself... Come... Come closer! I can't bear this feeling any longer!",
	main = "This is the enemy's stronghold, so why are you the only one here? Where are the other captives? What did you do to them?!|The enemy was wiped out, and all the captives were rescued? So you actually were the reinforcements... Does that mean I'm saved, too?|Hmm. I've memorised all my lines, that's fine, but having to act in this position does make things awkward...",
	touch = "Come any closer and I'll... I'll bite you if I have to! Urgh! Argh!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 9600131,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Urgh... I know it's my power that you're after. Don't assume you're going to break me... so easily!",
	feeling2 = "",
	login = "Are you here to save me? Wait, no! You're clearly the boss of my enemy! You cannot fool me!",
	detail = "Was it necessary to make such an elaborate set just for an act? Where did you even get these tools? And these restraints... They're so hard to break out of...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9600140] = {
	hp_warning = "Lower your weapons. This is your final warning.",
	feeling3 = "Commander, don't you think these pearls look like miniature moons? They're all for you! I hope they'll watch over your sleep when the moon cannot.",
	mail = "Commander, you just got a delivery. Should we check on it?",
	expedition = "The commission fleet has returned with a bountiful harvest. I hope nobody got hurt...",
	win_mvp = "Could this lead to true salvation?",
	home = "You've returned safe and sound. Give me your hand... I'll always be supporting you. Never forget that.",
	unlock = "It must be fate that brought us together in this sea of pearls. My name is Pearl. I pray that hope and purity forever light your path.",
	touch2 = "Is this... how you communicate your feelings? It's novel, I'll give you that...",
	mission = "Your workload is... troubling, to say the least. Allow me to help you!",
	vote = "",
	drop_descrip = "Sailing frigate – Pearl.",
	feeling4 = "Commander... I want to be a part of your world. It's my belief that there are no real walls between fellow people. If you are willing to accept me, then... you and I...",
	lose = "I will fight on – until all of our allies have made it to safety.",
	feeling1 = "Ah, Commander... I can't help but cry when you get like this.",
	skill = "May this gentle glow soothe all the world's pain.",
	upgrade = "Gentleness and strength. Are they contradictory, or are they intrinsically linked?",
	propose = "Is this the physical embodiment of love? Everything else pales in comparison to it. I'll treasure it and protect it forever, so that it shines eternally.",
	feeling5 = "I used to think that love was selfless and fair to everyone. But now I realise... Sometimes, you find that a special someone has stolen your heart. Do you know what I mean, Commander?",
	main = "Commander, did you see my collection display shelf? Isn't the conch pearl in the middle just beautiful? I had to search long and hard for that one.|Angel? Some do call me that, yes... It's rather odd when you do, though.|My pearl jewelry and crafts are all handmade – by me, of course. Do you happen to like any of them...?",
	touch = "Your palms are so warm, Commander. Every time we touch, I feel special power well up in my wings...",
	voice_key_2 = -1,
	mission_complete = "What kinds of rewards did you get? Any rare jewels, maybe?",
	battle = "Surrender now, and the goddess may still forgive you yet.",
	id = 9600140,
	gift_dislike = "",
	gift_prefer = "What a thoughtful gift! I love it, Commander.",
	profile = "Greetings – I am Pearl. May this encounter help you overcome your suffering... Commander, let's walk together from this point on.",
	voice_key = 960014,
	headtouch = "Is this your gentle side, Commander? Heehee, I like it!",
	feeling2 = "Victory isn't won through hurt. Only through wisdom and charity, only through finding a way to make both parties happy, can we achieve a loving victory.",
	login = "I bring the blessings of moonlight and pearls. May this moment of peace dispel all your worries!",
	detail = "Good and evil, truth and falsity... Our world is a chaotic one. If you cannot understand yourself, then how can you demand understanding from others?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9600141] = {
