_G.pg.base.ship_skin_words[9600150] = {
	hp_warning = "Oh, owch... Now things are getting fun...",
	feeling3 = "Did you hear the news, Commander? Someone caught a humongous octopus! It was thiiiiiis big! I want to see it for myself!",
	mail = "A new letter has arrived! Alright, let's open it! You never know if it might contain a treasure map!",
	expedition = "The commission team has returned! Wonder what interesting places they'll go to next... We should follow them in secret!",
	win_mvp = "Easy peasy. I already popped a bottle of victory champagne! I've still got some left, so help yourself!",
	home = "You're back! You probably had all sorts of wild encounters out there, eh? You should bring me along next ti– No, right now!",
	unlock = "Ahoy! Over here! It's me, Royal James, touching down! No time for explanations, Commander, let's just set off! ...Set off where, you ask? Hmm. I'm not sure quite yet. Never mind that – anywhere that's fun is fine by me!",
	touch2 = "A-ha! I knew it! You've got funny stuff on your mind!",
	mission = "Commander, why do you think we need to finish missions as soon as possible? The answer is: Because fun things wait for no one!",
	vote = "",
	drop_descrip = "Sailing frigate – Royal James.",
	feeling4 = "You work overtime way too much, Commander! How will you have the energy to have fun with me if you never get proper rest?",
	lose = "Let's have another go, Commander! One more time! Right now!",
	feeling1 = "*sigh*... I can't be bothered to do anything when it's this boring...",
	skill = "Boooring! Take this!",
	upgrade = "Hang on, getting stronger is THIS easy?!",
	propose = "Didn't you say there was a fight between barnacles to watch? Wh-what's this talk about a marriage? Only a nutter would answer such a sudden question with, \"Yes, I do\"! ...Huh?! I didn't say I WON'T say that! If it means becoming an item with you, then... I guess I'm fine with being a nutter!",
	feeling5 = "Ahahaha – even though it's true that I often cause a lot of trouble, my happiest times are when I can say \"oopsie\" with you! Hm? What do you mean, \"I'm the only one making an oopsie\"? You're there making it with me!",
	main = "Commander, I heard there's a fight on the beach between scallops and starfish! I wonder which side is stronger! Let's go and have a loo– Oh, the toilet in the dormitory exploded?! That sounds fun, too!|Commander, looking at this plan, I feel like it's lacking originality! Want me to think of something? I'll make it look completely new!|How does ramen taste if you eat it with your nose? Now I'm curious! Let's find out! *snort*... That's odd! The flavour's hardly any different!",
	touch = "Here comes the takoyaki! Whoosh! ...I-it looks weird to you? Okay, have another!",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Boooring... I'm fed up with this stuff.",
	battle = "Whoa-oh! They won't know what hit 'em!",
	id = 9600150,
	gift_dislike = "",
	gift_prefer = "Whoa! I'm having fun just looking at this present!",
	profile = "I'm Royal James! Where there is fun, you'll find me! Whenever you encounter something interesting, let me know immediately!",
	voice_key = 960015,
	headtouch = "Ooh. Who'd have thought getting headpatted would be so interesting?",
	feeling2 = "The hardest choice to make in this world is between two things you want to do at the same time! How do I decide? Please help me out, Commander!",
	login = "Wow, you are here only now? That must mean you DIDN'T stuff your alarm clock into your stomach!",
	detail = "You found a fun place?! Well, what are we waiting for? Let's go! Uhh, \"submit a departure request\"? When did we add that stinking buzzkill of a procedure?",
	couple_encourage = {
		{
			{
				960012,
				960016
			},
			1,
			" Let's go treasure-hunting!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[9600151] = {
