_G.pg.base.ship_skin_words[9600160] = {
	hp_warning = "Aaaah! T-t-too much danger, too much danger!",
	feeling3 = "Have you heard the story of the three little pigs? They got eaten because they didn't predict danger coming!",
	mail = "I made sure the mail is safe. You can read it now.",
	expedition = "The commission team is back! Should we send someone to keep guard over the rewards, or something?",
	win_mvp = "Phew... I think we got a lucky win!",
	home = "Hyah?! O-oh, it's you... You scared the hell out of me. I thought I was about to get my throat slit, or something.",
	unlock = "Commander, is this the new place you got for me? It's bigger than I expected... Hey, where are all the security measures?! Can I get you to install some alarms?",
	touch2 = "Ack! Y-y-you just touched me! I knew this outfit wasn't safe!",
	mission = "Hmm... You don't have any adventuring or exploring missions? Those could be fun!",
	vote = "",
	drop_descrip = "Sailing frigate – Adventure.",
	feeling4 = "Commander! I found this great hiding spot, so I'm building a new house there! Nobody gets to know but you... Hmm? Why not just keep living where I am? It isn't safe to live in the same place forever!",
	lose = "Gaaaah, th-th-this place is too dangerous for me! Let's leg it!",
	feeling1 = "This place is unsafe... I'd better move out...",
	skill = "I'd better eliminate these threats!",
	upgrade = "If I get stronger, will that make my bunker safer, too...?",
	propose = "Commander, will you stay with me forever? Every minute of every day? You won't ever regret it? Phew... Good. To celebrate finding the safe harbor I've always dreamed of... Put that ring on my finger, you!",
	feeling5 = "Hmm... Y'know, I think the safest place for me is right next to you! Is it because of the port's top-notch defences, or is it because you make us all feel safe...?",
	main = "Adventure's on an adventure♪ Saving the day between missions♪ Finding little hideouts all over while she looks for a home♪|Can you make the safest doomsday bunker ever? Please! I wanna live there!|Commander, I installed a tripwire alarm right here. It'll let me know right away if there's danger!",
	touch = "This is a tool I use in my adventures! You can see it if you want, Commander.",
	voice_key_2 = -1,
	mission_complete = "Commander! Hurry up and grab your rewards! You don't want someone stealing those.",
	battle = "Time for a brand-new adventure!",
	id = 9600160,
	gift_dislike = "",
	gift_prefer = "Ooh! I like this. No, I love it!",
	profile = "Good to meet you, Commander. I'm Adventure, and these are my new digs! If you wanna come over, you have to tell me ahead of time! Or else you'll fall into one of my traps, and trust me, you do NOT wanna do that.",
	voice_key = 960016,
	headtouch = "Heheheh... That's weirdly calming.",
	feeling2 = "Huh? I don't get to move homes?! I just wanna live somewhere safe. Isn't that plenty reasonable? Come on, Commander, pleeeease?",
	login = "*tremble tremble*... Th-th-this place is giving me the heebie-jeebies. Is something targeting me? Commander, we gotta run before it gets us!",
	detail = "I-I'm not paranoid, okay? I'm just trying to ward off threats effectively! Check the record – you'll see I've never fallen victim to an attack, not ONCE. That means I'm right!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9600161] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Well, well... You trespassed into private property, and now you're face to face with its owner. Did you think this is a coincidence?",
	unlock = "There you are... Don't think I didn't notice you skulking around my castle! Can't believe you made it here without triggering my traps... Does that mean I'm not safe here, either?!",
	touch2 = "Stay here, you. That's an order from the master of this castle...",
	mission = "",
	vote = "",
	drop_descrip = "There you are... Don't think I didn't notice you skulking around my castle! Can't believe you made it here without triggering my traps... Does that mean I'm not safe here, either?!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Oh, what a conundrum. I'm not the kind of person who can be persuaded by excuses, you know, but I've changed my mind! Your stories fascinated me. From now on, you'll live here and entertain me with more stories.",
	main = "Ooh, now THAT'S a fascinating tale of adventure! Yet its protagonist fell into my clutches so easily... What could it all mean?|Even in such peril, you make calculated decisions and well-reasoned hypotheses... Heehee, now you've really got my interest.|Storyteller... Heheh, do you mind if I call you that? If you're thirsty, I have a wine fountain to wet your throat.",
	touch = "Oh? You're approaching me? Instead of running away, you're coming right to me? You're either brave or stupid... Interesting.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 9600161,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Tell me, powerless intruder, why you've come to my castle! For the treasure? Or for the life of its beautiful master?!",
	detail = "Let you go? Oh, gladly. As long as you can prove that you wandered in here by accident and don't pose a threat! That should be easy, shouldn't it?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9701010] = {
	hp_warning = "Gah... I must calm myself!",
	feeling3 = "Hm? You're here just to see me? You didn't have to – I'm well used to lonesome returns... Regardless, thank you.",
	mail = "You have a new letter. Read it, lest crucial information pass you by.",
	expedition = "The commission team is back. Those lassies – you can count on them.",
	win_mvp = "Henceforth we face the real threats. Be on your guards.",
	home = "You're back. In one piece, I presume? Then relax and rest your weary bones.",
	unlock = "Greetings, Commander. I'm Hunter. I hunt, as you might've surmised. Is this place... my new base?",
	touch2 = "I don't understand the point of this...",
	mission = "New missions, eh? Who will you pit me against this time?",
	vote = "",
	drop_descrip = "Greetings, Commander. I'm Hunter. I hunt, as you might've surmised. Is this place... my new base?",
	feeling4 = "It feels almost like... my body and soul rejuvenate when I return here. I think this base has become my sanctuary...",
	lose = "Even the hunter becomes the hunted in due time...",
	feeling1 = "I give up... You are an untrustworthy Commander.",
	skill = "Rest in peace.",
	upgrade = "My weapons grow sharper... Good.",
	propose = "Mh. I understand your feelings. If you don't mind a pitiable soul, I'd like to be with you until my final threat is felled... No, even beyond that, I want to walk beside you.",
	feeling5 = "Whew... I've never overslept anywhere but here before. Either my sense of danger is waning, or I'm losing my touch... but I doubt it's either. Perhaps I'm just... at peace.",
	main = "Not everyone can calmly deal with a sudden threat. But you lead us all, Commander. You must stay composed no matter what.|Ah... Is this the paper you're looking for? I've memorised the spots you routinely use – as any hunter would.|What's this? Tea and biscuits? Whew... I've seldom tasted such lavish food, nor have I sat idly in one place for this long.",
	touch = "Weary, are you? Go on and rest. I'll watch your back.",
	voice_key_2 = -1,
	mission_complete = "Another mission completed. Be that as it may, the hunt is not over.",
	battle = "I'll take the lead. Someone must.",
	id = 9701010,
	gift_dislike = "",
	gift_prefer = "Sure... I'll take it.",
	profile = "I'm a hunter, and I'm under your command. Give me orders as you see fit. What do I hunt, exactly? You'll see, sooner or later.",
	voice_key = 970101,
	headtouch = "",
	feeling2 = "So this shall be my base... Alright. It's not so bad, having a place to rest and resupply.",
	login = "Oh, it's you. Resuming the perpetual cycle of paperwork? Good luck to you.",
	detail = "Should I ever become a monster... put a swift end to my life. Please.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9701020] = {
	hp_warning = "Don't make me... use this power...!",
	feeling3 = "If the goddess of fortune truly exists, there are so many things I do not understand that I'd want to ask her... But in reality, whether or not those questions can be answered means so little to me now...",
	mail = "Commander, there's new mail waiting for you... Um, unfortunately, I cannot hand it to you myself...",
	expedition = "It appears that a commission has been completed... Unfortunately, I don't think I'll be able to help you in my current state, sorry...",
	win_mvp = "Did fortune favor me, or perhaps...",
	home = "Another mission completed successfully. Commander, it appears that the trajectory of your fate seems to extend to a more fortuitous future...",
	unlock = "Well met, Commander. My name is Fortune. Please don't worry about these ch-chains... They're there to... keep my power in check.",
	touch2 = "Mmgh... Is this... yet another trial imposed upon me by fate...?",
	mission = "Commander, um... Just in case you forgot... There are still missions we have not yet completed...",
	vote = "",
	drop_descrip = "Well met, Commander. My name is Fortune. Please don't worry about these ch-chains... They're there to... keep my power in check.",
	feeling4 = "Whenever I am with you, Commander, I can feel the wheels of fate turning, taking me in a new direction... It's a light, airy feeling I cannot describe well, but it also fills me with warmth...",
	lose = "No, no... It shouldn't have been like this... How could this be? How could this be?!",
	feeling1 = "Please get away from me...! I, I'm so sorry, I don't know if I can control myself...",
	skill = "P-please forgive me...",
	upgrade = "My control... seems to be improving...",
	propose = "I'm so sorry... that I am accepting your ring in this pitiful form of mine... But, I'm also so thankful that you still accepted who I am despite all that! Commander, being able to meet you is truly the happiest event on the trajectory of my fate.",
	feeling5 = "I now entrust my future and my fate to you, Commander. Even if I veer away from the correct trajectory, you'll be there to guide me back, right? Um, is it really alright for me to stay at your side?",
	main = "Fate is said to both be immutable, but also something you carve out with your own two hands... What, then, is truly the nature of fate?|This uncontrollable power... is surely a trial imposed upon me by fate. It is not something I can allow to flow freely...|Commander, do you ever get the inclination that something is destined to happen to you? Oh, um, that was just my curiosity speaking, nothing more...",
	touch = "Umm, if these interest you that much, I suppose it's fine for you to touch them... I am capable of restraining myself...",
	voice_key_2 = -1,
	mission_complete = "Mission complete... I'm sure everything will be fine from now on...",
	battle = "Is there no other way...?",
	id = 9701020,
	gift_dislike = "",
	gift_prefer = "I-is this for me? Ah! Um... Sorry, I got a little excited...",
	profile = "I was given the name of \"Fortune,\" but in the end, it was I who was dragged down by fate... Um, if you insist on asking about these chains... They're, um, a self-imposed failsafe so that I do not harm those close to me...",
	voice_key = 970102,
	headtouch = "",
	feeling2 = "Our meeting surely must have been ordained by fate... right? I wonder where the winds of fortune will take me this time...",
	login = "Commander... Umm, welcome back...? That is the proper way to greet you, right?",
	detail = "There's no need for you to worry yourself over me... More importantly, um, thank you very much...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9701030] = {
	hp_warning = "You're sending the fleet into the tiger's den, you know.",
	feeling3 = "You're getting on well with your subordinates. Seems I won't need to lecture you on that... Hm? Am I getting along well with them? I told you before – you should keep your distance from METAs.",
	mail = "I left the new letter for you on your desk. If you're to make me do this again, I want to add some conditions. Heheh, don't you worry. I won't shake you down over a little legwork.",
	expedition = "Commission complete. While I could claim the rewards for you, I can't make you complacent. You've got arms – use them to do some lifting.",
	win_mvp = "A splendid victory. Next time, we could be more ruthless.",
	home = "There's things to be learned from successes and defeats alike. I'm sure you've heard that a million times, though. Now let's begin.",
	unlock = "You're helpless... So helpless it's worrying me. Oh, also, no need to concern yourself with who I am. Just think of me as the one who'll help you get your act together.",
	touch2 = "*sigh*... I swear with you younglings these days...",
	mission = "Well, you look satisfied. Completed a mission, did you? But if you didn't... I don't need to say the rest, do I?",
	vote = "",
	drop_descrip = "You're helpless... So helpless it's worrying me. Oh, also, no need to concern yourself with who I am. Just think of me as the one who'll help you get your act together.",
	feeling4 = "I considered making you a good luck charm, but didn't; my hands would curse it. So, I'll content myself with watching you from the shadows as your elder.",
	lose = "*sigh*... You will reflect long and hard on this blunder once we're home.",
	feeling1 = "Seems my hopes were misplaced... Now the question is – how to get through that skull of yours?",
	skill = "Be witness to your demise!",
	upgrade = "Maybe you should focus on yourself rather than worry about me?",
	propose = "You really are an odd one. Why go these lengths for the likes of me? Fine. I will accept your love so as to not disappoint you, youngling... \"It's about you, not me,\" you say? Speak such nonsense again and I will smack you on the forehead – got it?",
	feeling5 = "I've adapted to a life of solitude. Me helping others for my own selfish reasons, avoiding people – it's all normal to me. But, after spending time with you, I've begun thinking it's not so bad having someone I can rely on. For this, I blame you.",
	main = "Inspiration is like an oasis mirage – it appears and disappears. Those who don't come upon a real oasis can only live with their thirst. If it's water you want, I could find a way to procure it for you.|I've frightened people? I have no memory of doing such a thing. All I've done is stand my ground against a few cheeky younglings.|Hm? Another request from a youngling... Good timing. Let us see to it together, you and I. We must not be indifferent to the plights of others.",
	touch = "Something the matter? Need a hand? Heheh, know that that's no excuse to slack off.",
	voice_key_2 = -1,
	mission_complete = "Ah, you've completed a mission. Then you may have a break. A short one, of course.",
	battle = "Everything is up to you now, Commander.",
	id = 9701030,
	gift_dislike = "",
	gift_prefer = "Oh? How'd you know I was interested in this?",
	profile = "If it's a name you want... I am Hatakaze. Are you satisfied now? Because I don't care to tell you more than my name. However, I will say this – you should keep your distance from METAs.",
	voice_key = 970103,
	headtouch = "",
	feeling2 = "I am not a \"good girl.\" I did say I'd whip you into shape, but I have my motives for doing so. Heheh, if you're curious about them, use your head first.",
	login = "Have you made your plans for the day? I see. It's good to see I don't need to remind you anymore.",
	detail = "You look like you have something to say. If you need a favor, just spit it out. Next time I see you hesitate, I'll clobber you over the head.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9701040] = {
	hp_warning = "Hmph. The smell of death...",
	feeling3 = "Please stop trying to change me. You can't unbecome who you are, and neither can I. Focus on the present, which is this – I am your sword, a mere weapon that exists to do war.",
	mail = "A letter for you. It may be a report that warrants a quick response. You should read it soon.",
	expedition = "What a huge return... This will let us sustain the war.",
	win_mvp = "This was the expected outcome... The spoils were horrifically damaged? Then I leave the battlefield cleanup to you.",
	home = "One battle may end, but then another begins. Are you ready to leap into the fray once more?",
	unlock = "I am Kimberly of the Fletcher class, ready to serve. That should do it for introductions. What's important is that I am your sword – all you need to do is tell me what to cut.",
	touch2 = "...Do you really like girls who smell like blood and smoke that much?",
	mission = "Commander, we've received a mission to complete at once!",
	vote = "",
	drop_descrip = "I am Kimberly of the Fletcher class, ready to serve. That should do it for introductions. What's important is that I am your sword – all you need to do is tell me what to cut.",
	feeling4 = "Zzz... A world without light... without hope... Don't let it happen again... Don't become like me... Commander... Zzz...",
	lose = "I'll let you enjoy what little is left of your life...",
	feeling1 = "Heehee... The eternal war has changed you, too, Commander. Claimed your soul, did it? ...Liar.",
	skill = "I'll tear you all to shreds!",
	upgrade = "A blessing received from the war without end...",
	propose = "A gift for me? Isn't this an oath ring? ...It's obvious what it is when you formally summon me and present a small jewelry box. Hah! You set yourself up for disappointment. But enough teasing now... I hear you and I accept. I love you.",
	feeling5 = "...My answer still hasn't changed. To me, war holds no meaning... \"Then cut it out and stop fighting\"? But I... Um... I was taught war will one day give way to peace. I've believed that for as long as I can remember...",
	main = "What meaning does war have to me, you ask? Why are you trying to find meaning in war to begin with?|War breeds more war, and death begets more death... That's how it is. What about it?|Dreams and ambitions? As someone who struggles just to survive, those are some very lofty words.|What I'll do after the war is over? ...You actually believe this war will end?",
	touch = "War is a fact and nothing more. As long as it continues, I will keep fighting. That's all there is to it.",
	voice_key_2 = -1,
	mission_complete = "Mission objective achieved. The frontlines can rest easy for a while.",
	battle = "Executing annihilation order. Leave no survivors!",
	id = 9701040,
	gift_dislike = "",
	gift_prefer = "This doesn't seem useful for combat. You can have it back.",
	profile = "I don't want to brood on the point behind this war that has gone on so, so long. Don't ask about it, Commander. You'll give orders, and I'll execute them as best as I can. No more than that, please.",
	voice_key = 970104,
	headtouch = "...My hair is stained by blood and smoke. I'm surprised you like it this much.",
	feeling2 = "...Why do I keep fighting when war is meaningless, you ask? To that I say, \"Is there any reason NOT to fight?\" It's all I can do, anyway... Go for a walk around the port? Sounds like a damn waste of time.",
	login = "Commander, here is a list of areas we'll be sweeping today. Please have a look.",
	detail = "My equipment maintenance is done. Let's have a breather and... Commander? Did we get assigned a new mission?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9701050] = {
	hp_warning = "Kh, this is rough...",
	feeling3 = "Bookshelf... Under the pillow... Under the bed... Hm? N-nothing...? Have you gone crazy from loneliness?",
	mail = "Mail for thee, not for me! Speaking of, one of my love letters is in there. Guess which one it is!",
	expedition = "The commission team you sent out has returned. Go welcome them~",
	win_mvp = "Thou'rt a thousand years too inexperienced to challenge me!",
	home = "Heheh, that triumphant look on thy face... What historic victory didst thou seize today?",
	unlock = "The adorable Vampire, messenger of the dark night, graces thee with her presence. Hehe, thou smellest sweet♪ Thou art certainly the one I've dreamed of♡",
	touch2 = "Eek! Pervert! Lecher! Lolicon! Heheh, is that what you wanted to hear?",
	mission = "Missions? Heh, I know that. Get to it, chop-chop!",
	vote = "拉票描述",
	drop_descrip = "The adorable Vampire, messenger of the dark night, graces thee with her presence. Hehe, thou smellest sweet♪ Thou art certainly the one I've dreamed of♡",
	feeling4 = "This is wine that I've let age for a looong time. The moon is so pretty tonight, why, it's the perfect time to open it... Yeah, yeah. Stop being so stuffy and just sit down!",
	lose = "As long as everyone is safe... Pride is a small price to pay, anyway.",
	feeling1 = "You really are a dummy... Do you think this can continue?",
	skill = "Kneel before my true power!",
	upgrade = "...I don't look like I've grown much? That's just because I have big POTENTIAL, dummy!",
	propose = "Nnnh... *yawn*... This is how you promise me you want to be together forever? How crude... But on my name Vampire, I give thee my eternal blessing. Heehee!",
	feeling5 = "While I drank with thee on that beautiful night, I found myself... Ahem! There I go, almost telling you how I feel! I'm drunk, so take me back to my dorm!",
	main = "Dost thou ever think thou tryest too hard? Most things in the world are out of our control. Of course, I'm happy to help a little out of deference for your struggles.|Ah, calm seas! You can really see some unexpected sights here. So, how do you plan to make up for keeping this place to yourself for so long?|I've always wondered why you're so interested in my \"colour\" of the day? ...Because I'm wearing it now? Geez~ Even I get embarrassed, you know!",
	touch = "Heheh, thou must want to go further. Your mind is like an open book to me.",
	voice_key_2 = -1,
	mission_complete = "Finished thy missions? What wilt thou do next? I shall join thee.",
	battle = "Ohohoho! Bold of you to appear before Vampire!",
	id = 9701050,
	gift_dislike = "",
	gift_prefer = "Very tasteful. I accept~",
	profile = "So, what dost thou wish to know? My past? Future plans? Heehee, I can answer all, but prepare thyself first!",
	voice_key = 970105,
	headtouch = "Mm, sometimes, being a kid isn't so bad after all~ Ahaha, whoops! Did I say that out loud?",
	feeling2 = "Stop asking! It's BLACK, okay? ...What's black? I-I mean... Don't look at me so expectantly!",
	login = "Morning! Hm? Thou thinkest I wake too early? Heheh, only because I miss thine presence♪",
	detail = "What is this... Dost thou think I'm still so young that I'd blush and get nervous from a mere love letter? Heheheh... Thou art right! That's exactly who I am! Yaaay, love letter!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9701060] = {
	hp_warning = "Kasumi... will not sink here!",
	feeling3 = "Foo has gone off to a place far, far away, but will sometimes come back to see me. Every time Foo returns, I become much, much stronger...",
	mail = "I've brought you the mail, Commander.",
	expedition = "I've seen that the commission fleet has returned, and they're all waiting for you. Commander, don't keep them standing out there for long.",
	win_mvp = "Kasumi... is victorious.",
	home = "I have prepared... warm and cozy tea. Please enjoy, Commander.",
	unlock = "You... have summoned Kasumi. Commander, what do you need of me?",
	touch2 = "Commander, uweh... I can't believe you...",
	mission = "New missions have arrived. Commander... slacking off is a no-no, okay?",
	vote = "",
	drop_descrip = "You... have summoned Kasumi. Commander, what do you need of me?",
	feeling4 = "Now that I've become stronger... do you feel like you don't know me anymore? Don't worry. I'm still the same me. Commander... You're not afraid of me, are you?",
	lose = "I must... release my powers. Foo, please keep the others safe!",
	feeling1 = "I'm used to being alone, so... just leave me alone.",
	skill = "Pass through... pass through.",
	upgrade = "I can... see more clearly now.",
	propose = "Commander... You've chosen me? Really? You've always been the person nearest and dearest to my heart... so of course, I'd like to be with you. That way, I'll never have to be alone again.",
	feeling5 = "My \"power\" is usually sealed off, which is why Foo cannot come back unless the seal is lifted. But because you're here, I don't feel alone at all... Even before Foo disappeared, I always felt like you were someone irreplaceable to me...",
	main = "Blue flames? ...Commander, you can see them too?|Loneliness... is something I've gotten used to. It's not scary anymore. Kasumi will be afraid no longer, Commander.|Do you like the tea I made for you? If so, I'll have it ready for you every time you come back.",
	touch = "Commander... Did you want to talk to me?",
	voice_key_2 = -1,
	mission_complete = "Mission complete... Commander, do you want a reward?",
	battle = "Shall we cross... to the other side?",
	id = 9701060,
	gift_dislike = "",
	gift_prefer = "Kasumi... loves this. Thank you, Commander.",
	profile = "I can see things that nobody else can. Not only see, but also feel. So, I am no longer alone. I am no longer afraid of being by myself.",
	voice_key = 970106,
	headtouch = "Kasumi's hair... is ice-cold now. Commander, do you like it?",
	feeling2 = "Commander, you still remember Foo? Sorry... That's not something I'm ready to talk about right now...",
	login = "Welcome back, Commander...",
	detail = "Kasumi... of the Asashio class. Commander, I can be alone now, so... where would you have me go?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9701070] = {
	hp_warning = "I will never abandon my duty of protecting the fleet as long as I still have strength!",
	feeling3 = "My memory is... Well, it gets hazy in places, yet I also remember some things so vividly it's like they're right in front of me. Quietly talking to you like this gives me a peace of mind I haven't felt in ages. Thank you...",
	mail = "New letters came in, and I sorted them by order of importance. Thought it might save you some time.",
	expedition = "Commander, the commission team is back. If you're free, how about we go greet them?",
	win_mvp = "Victory... I only carried out my duty.",
	home = "End of combat... All that matters is that you're safe. I'm gonna go check on the team – the report can wait.",
	unlock = "I'm Royal Navy destroyer Grenville, returning to the battlefield in META form. Long ago, I... No, that's all in the past now. Just give me a chance, Commander. I swear to keep the fleet safe this time.",
	touch2 = "C-Commander?! If it's a reaction you wanted... Uh, please, let go of me.",
	mission = "Commander, you have work left to do. If your hands are tied, I can take on the simple stuff.",
	vote = "",
	drop_descrip = "I'm Royal Navy destroyer Grenville, returning to the battlefield in META form. Long ago, I... No, that's all in the past now. Just give me a chance, Commander. I swear to keep the fleet safe this time.",
	feeling4 = "C-Commander! I made new snacks again, and I actually measured the ingredients this time... W-wanna have some with me?",
	lose = "I've got to evacuate everyone!",
	feeling1 = "I'm not asking for your understanding or concern. I just want you to not prevent me from protecting people.",
	skill = "I'm going all out in the name of everyone I care about!",
	upgrade = "A little bit stronger... Cheers.",
	propose = "This ring symbolises both an oath and the long path we've walked. I may not be the precocious young Grenville who dreamed of becoming a fine Royal lady, but I still want to find a future for you and me.",
	feeling5 = "I thought I had lost everything, but then I met you... and your existence has supported me for countless nights. It's thanks to you that I can move forward.",
	main = "Lady... That word used to mean a lot to me. But now, all I care about is fulfilling the duty given to me – protecting you and the people here.|Oh, umm... Commander, wanna try some scones I made? Just so you know, they might have a \"unique\" taste. The ingredients where I come from were pretty limited... I still hope you'll like it, though. It's the flavour of... me, here and now.|My past self never understood the importance of being the flotilla leader... But now, I vow to bring everyone back home in one piece after every sortie.",
	touch = "Hm? Do you need something?",
	voice_key_2 = -1,
	mission_complete = "Commander, claim your mission rewards. These resources are really crucial for us. I know better than anyone the dread that comes with destitution... Seriously, don't forget those rewards.",
	battle = "I'll escort you to the best of my abilities. I WILL keep protecting everyone this time!",
	id = 9701070,
	gift_dislike = "",
	gift_prefer = "Wait, this is for me? It's been so long since... Ah, never mind. Thank you, Commander. I'll cherish it... I really will. Thanks again.",
	profile = "I'm Grenville... Grenville META. I used to be a regular destroyer who dreamed of becoming a refined lady, but destiny had other things in mind and I lost so much... Let me use my strength to protect your people, Commander.",
	voice_key = 970107,
	headtouch = "...Hey, could you stop that? I'm not as vivacious as I used to be. Well... that's not to say I hate it or anything.",
	feeling2 = "Commander, need a hand with anything? I can help you plan an operation, analyse information, and so on.",
	login = "Welcome back, Commander. I've compiled a list of your missions for today. I've also made tea for you. I added a little something for... extra flavour.",
	detail = "Commander? Oh, yeah, I was just sifting through some memories. Although I've been through a lot, there's also much I'd hate to forget... Like afternoon tea with my friends or the days we spent together.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9701080] = {
	hp_warning = "Bloody shadows, join me in slaying our foe!",
	feeling3 = "Commander, while I must thank you for being so kind, I am still bound by a duty and I will one day leave this place behind. By this I mean: Do not get too attached to me. Take that as a... warning.",
	mail = "Commander, a letter addressed to you has arrived... It may in fact be addressed to me? Quit pulling my leg.",
	expedition = "Commander, a commission has been completed. You needn't have worried – a commission is not easy to fail.",
	win_mvp = "The outcome of a battle matters less than the safety of our allies... Yes, a victory is a victory. Rejoice, you courageous warriors.",
	home = "You must be weary after your series of battles, Commander. You're home now, so clear your mind of war for the moment and... Ah, it's nothing. I'll make tea for you.",
	unlock = "So you're the Commander. I am Kawakaze, a roamer of the lands. We will be walking the same path for some time. Let's be cordial.",
	touch2 = "...Care to experience the essence of dual-wielded blades, Commander?",
	mission = "Why are there so many missions? Commander, if the need arises, I will cut them off at their source.",
	vote = "",
	drop_descrip = "So you're the Commander. I am Kawakaze, a roamer of the lands. We will be walking the same path for some time. Let's be cordial.",
	feeling4 = "Commander, I understand how you feel, but please stop trying to console me. I needn't face the past to move into the future... Yes, I am moving into the future, you cursed snakes! In spite of you sticking to me like leeches! Even if I... Shut up, shut up, shut up!",
	lose = "I still have a mission to accomplish... I must live on... Retreat!",
	feeling1 = "Your judgment is correct, Commander. I am merely a blade. You needn't care about my feelings. That being said... when a blade is masterless, who can say upon whom it will descend?",
	skill = "Close your eyes and sleep.",
	upgrade = "I'm now one step closer... to fulfilling my long-held desire.",
	propose = "The river is strikingly clean, the sky is refreshingly clear. The wanderer purges the mist of her mind, having found a cause to fight for and a master to serve – such a beautiful tale. Commander, even should our journey be an endless one, I will walk it with you as your blade.",
	feeling5 = "I'm surprised you've come near me again. Did the bloody shadows' outburst not daunt you? You have guts, that's for sure. Maybe I ought to follow your example and display the same degree of courage. By facing the past – by confronting the moment the bloody shadows came into being... I can't, Commander... I'm scared... Please stay here... with me...",
	main = "I am a masterless blade, now at your side for the time being. When you need my power, I shall lend you it.|There is no end to conflict, Commander. Whatever you do, don't fall into that spiral.|I guess it wouldn't be so bad to... spend the rest of my life in peace... Move it, snake! Out of my way!",
	touch = "I appreciate the gesture, Commander, but I don't wish to see your Lady Nagato. I am bound by my own unfinished business. She... She has her own loyal Kawakaze, I'm sure.",
	voice_key_2 = -1,
	mission_complete = "What surprisingly lavish mission rewards... Commander, I withdraw what I said earlier. It's best if the client remains alive if they provide remuneration as generous as this.",
	battle = "I by myself will suffice.",
	id = 9701080,
	gift_dislike = "",
	gift_prefer = "It's beautiful... Thank you. I love this gift.",
	profile = "I'm Kawakaze. My allegiance, my model number – all that vanished with the dregs of the past. Now I'm no more than a wanderer who accompanies you. What happened to me is something I... don't want to discuss. You are bright – I'm sure you can make a good guess.",
	voice_key = 970108,
	headtouch = "If this brings solace to your heart, then do as you please.",
	feeling2 = "These blood-red shadows? Yes, they're ferocious and dangerous... Apologies. They seem intent on following me wherever I go. I can neither control them nor shake them off... Quiet, you!",
	login = "The same sight sparks different emotions depending on its viewer's heart... I've been waiting for you, Commander.",
	detail = "Do you need something, Commander? You're always welcome to just say hello. Have a seat and I'll put on some matcha tea– Ugh, shut up!",
	couple_encourage = {
		{
			{
				40505
			},
			1,
			" How interesting... How did you learn to control it?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[9701090] = {
	hp_warning = "Now you've done it... assholes!",
	feeling3 = "I ate so much and now I wanna sleep... Mmh... but I wanna go out and fight, too... Or maybe I could go to the park and catch some butterflies? Ugh, I can't decide! Commander, pick for me!",
	mail = "Got a letter here, Commander! *sniff sniff*... Bleh! Smells not yummy!",
	expedition = "Woof?! Commission got done, I'm guessing? Boy, I can't wait to see what food they brought back this time!",
	win_mvp = "Hah! That's all? Hope the next bunch will be more fun!",
	home = "Commander! Weeelcome back! *sniff sniff*... Hm? You got any snacks on you?",
	unlock = "So you're the Commander? Name's Yuudachi! Think of me as a Shiratsuyu class. By the way, you guys got any food here? You do? Then we're all good!",
	touch2 = "That's it, Commander! You're getting bit! Woof!",
	mission = "A new mission? Ugh, what a pain in my ass... Two helpings of meat for my efforts?! I'm on it!",
	vote = "",
	drop_descrip = "So you're the Commander? Name's Yuudachi! Think of me as a Shiratsuyu class. By the way, you guys got any food here? You do? Then we're all good!",
	feeling4 = "It's so weird... I was gonna eat this yummy meat all by myself, but now I wanna leave some for you.",
	lose = "...Retreat? Do I look like a coward?! Lemme go! I've still got fight left in me!",
	feeling1 = "So... hungry... Sausage... Ham... Meat pie... Steak... Where's the food...",
	skill = "Cut 'em up! Rip 'em to shreds!",
	upgrade = "Commander, I'm absolutely dying to eat something or go out and mess somebody up right now!",
	propose = "A promise ring? Commander, I'm not a little kid – I know what this ceremony's about. Basically, you'll give me tasty food for the rest of time and I just gotta fight for you, right? Then you can bet your ass I'll accept!",
	feeling5 = "You're nice to me, and I like you for that! A little! Once I've stuffed my belly later today, I'll give you the privilege of patting my head!",
	main = "What am I fighting for? Nothing, really. If I had to say, then because it's fun? And 'cause it's tasty?|A welcoming party? Count me out. Sounds lame and tiring. Wait, they've got yummy food there? Then I'll be there!|Saw something interesting outside the office... Hm?! What's that you got? Is it... chocolate?!|This work is sooo boring... *sniff sniff*... Smells like it's nearing lunchtime, Commander, so I'm outta here!",
	touch = "After breakfast comes lunch, after lunch it's snacktime, and after that it's time for dinner, and after that, I get a late-night stack. This port place you got here is goddamn amazing!",
	voice_key_2 = -1,
	mission_complete = "Nom, nom... Mmh... Commander, these mission rewards are so tasty!",
	battle = "Heheh! This is gonna be a fun hunt!",
	id = 9701090,
	gift_dislike = "",
	gift_prefer = "Woof! Who do you want me to beat up?",
	profile = "Call me Yuudachi or Yuudachi META or whatever the hell you want as long as you lemme eat all I can! I'll even beat the shit out of someone for you! Ugh, all this talking's making me hungry... Got anything to eat? Where's the grub at?",
	voice_key = 970109,
	headtouch = "Don't touch me! That tickles, dammit!",
	feeling2 = "I'm gonna go look for some food – wanna come with? ...What about the truckload of meat I got yesterday? Well, yeah, that was YESTERDAY'S food.",
	login = "You're giving me all this meat and these snacks? Awright, just spit it out and tell me who you want dead!",
	detail = "Hmm... Zzz... Grrmh... Zzz... Hm? Commander! Is it dinnertime?!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9701100] = {
	hp_warning = "Huff... Calm down, Dewey!",
	feeling3 = "Commander, please have a look at my new plushie! Isn't it adorable? It's so soft, and... Huh? You'd like a hug? Of course, if you want... Huh?! You meant you want to hug ME?!",
	mail = "Commander, you've received a new letter. Please read it when you have the time.",
	expedition = "I've verified that the commission team has returned on schedule. It's time to go greet them.",
	win_mvp = "Our tactics were better than theirs. That's another victory to our name!",
	home = "So fluffy, so cute... C-Commander?! Welcome back! Um, I mean, when did you get back? Err, a-as for this plushie... I didn't expressly bring it to work, I just thought I could play with it during my break, you see...",
	unlock = "I'm destroyer Dewey – Dewey META – and I'm pleased to be serving as your tactical advisor. I'll provide professional strategic assistance from the sidelines which I hope will be of use to you.",
	touch2 = "C-Commander! We're still on the clock... I can't focus like this...",
	mission = "There are new missions. Hmm... I'll make some adjustments to your schedule.",
	vote = "",
	drop_descrip = "I'm destroyer Dewey – Dewey META – and I'm pleased to be serving as your tactical advisor. I'll provide professional strategic assistance from the sidelines which I hope will be of use to you.",
	feeling4 = "Commander, it's time for a break! For dinner tonight, um... I made a boxed lunch, if I can interest you in that. I hope it'll be to your tastes.",
	lose = "We should retreat immediately. After that, we'll revise our strategy!",
	feeling1 = "I'm your advisor, so I'd like it if you'd actually listen to my advice.",
	skill = "We have the upper hand. Time to strike!",
	upgrade = "I'm now able to assist with even more professional intelligence!",
	propose = "I may be a little anxious sometimes when I face an uncertain tomorrow... but that's okay, because from now on, be it in battle or at home, you'll always be there to show me the way – right?",
	feeling5 = "Commander, you can come to me for advice on anything. I want to help... and support you in new and different ways. And when I do, it should ease your burden by quite a lot!",
	main = "That's most of the important missions done and dusted. Um, Commander, could we chat for a bit? It should help relieve some of the stress from work.|The weather pattern suggests... a storm is coming? Is it yellow? Or red?|The accessories in that display window are so adorab– Ahem, I mean, they're moderately cute. Should make a note of this place and come back after work...",
	touch = "Is something bothering you, Commander? Hopefully, my proposition might be able to help you.",
	voice_key_2 = -1,
	mission_complete = "Mission rewards have arrived. Allow me to organize the resources. Hm... Wonder if there'll be any cute things in there.",
	battle = "Please issue your orders, Commander!",
	id = 9701100,
	gift_dislike = "",
	gift_prefer = "You're giving this to me? Wow, thank you!",
	profile = "I'm Dewey. Being a professional advisor, my job is to provide tactical support in the form of gathering and sharing intelligence, among other things. I hope that my assistance helps you make more accurate decisions.",
	voice_key = 970110,
	headtouch = "Y-you mustn't mess with my hat while I'm on duty!",
	feeling2 = "Resources in all locations have now been more or less organized. Commander, have you decided on where we're going? I'm fine with anywhere!",
	login = "Welcome back, Commander. I've organized the files that need your attention. Please let me know when you have orders for me.",
	detail = "I'm presently gathering and sorting weather data on this sector of the ocean. You can't make a swift decision without accurate information! It'd spell disaster if we ran into a storm in the middle of an operation, for instance.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9701110] = {
	hp_warning = "I'll need to revise my security plan...",
	feeling3 = "The work of a guard requires a vigilance that does not cease, even for a moment. However... If you would like to have a chat, I'm always happy to listen.",
	mail = "Commander, your new letter has passed the safety inspection. You may read it whenever you like.",
	expedition = "The commission team has safely returned. Excellent. Nothing's better than everyone making it back.",
	win_mvp = "Although the threats have been eliminated, my guard shift continues. Please remember to stay alert.",
	home = "Welcome back. Everything went smoothly during your absence. I've logged the details in this report for you.",
	unlock = "I am Carabiniere, your full-time guard, reporting for duty! I've assessed the risks of your upcoming schedule and have adopted a strategy accordingly, so you may set out with peace of mind!",
	touch2 = "C-Commander... I'm not fond of pranks like this!",
	mission = "Commander, there are some important matters left that demand your attention. Would you like my assistance?",
	vote = "",
	drop_descrip = "I am Carabiniere, your full-time guard, reporting for duty! I've assessed the risks of your upcoming schedule and have adopted a strategy accordingly, so you may set out with peace of mind!",
	feeling4 = "Commander, if you need a break, may I suggest stopping to have a chat with me? I could tell you countless things about guns and horses.",
	lose = "Prioritize the Commander's evacuation!",
	feeling1 = "...I am still evaluating whether you're deserving of my loyalty. I will professionally perform my guard duties until I reach a conclusion.",
	skill = "Calibration complete! Opening fire!",
	upgrade = "My power to protect you has grown again.",
	propose = "An oath of... Very well. I shall use this gun and all of my professional abilities in service of you. This I say not out of compliance with any orders, but as a personal pledge made to you. In your guidance I hereby place my trust, Commander.",
	feeling5 = "When I'm at the port, I feel a profound sense of ease. Everything here – you in particular – gives my role as a guard another kind of meaning.",
	main = "Security staff check complete. Now for the equipment list... Oh! Isn't that the gun I've always wanted to try?! Its firepower and precision are legendary, and... Talk about while we go on a patrol? Yes, let's!|Weapon maintenance is part of a guard's daily routine. Their structure, performance, and the timing of maintenance are... Ahem, pardon me. I got lost in specialist talk again.|I'm amazed that the port has such a well-made racetrack for horses! There is no substitute for a good warhorse's mobility in complicated terrai– Err, I mean, let's go for a ride after work!",
	touch = "Commander, I'm performing maintenance on my gun, so... Oh, you're interested? Then please come closer! I'd be glad to show you its intricate internal structure – it's no less than a work of art!",
	voice_key_2 = -1,
	mission_complete = "The mission rewards have been reviewed. Ah, well, to me, there is no greater reward than professionally carrying out my guard duty.",
	battle = "Protect the Commander whilst eliminating the threats!",
	id = 9701110,
	gift_dislike = "",
	gift_prefer = "Is this... for me? Thank you kindly. I will put it to good use!",
	profile = "The name \"Carabiniere\" represents swiftness and protection – from now on, it's also my pledge to keep you safe. All of my past strength and resolve will be put into this duty of mine.",
	voice_key = 970111,
	headtouch = "Commander, please, this is no time to get careless.",
	feeling2 = "You think my security plan is flawless? Oh, heheh... I am honored beyond words to receive your words of praise!",
	login = "Commander, I've reviewed your security plan for today. You may begin your work at any time.",
	detail = "Have you seen anything unusual, Commander? ...You're just on a regular patrol? Well, it's always good to remain vigilant.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9701120] = {
	hp_warning = "My life is fading away...",
	feeling3 = "My goals and yours seem to overlap often. Working together, we could achieve them more efficiently... What do you say, Commander?",
	mail = "There's a letter addressed to you, Commander. Don't worry, it's just a normal letter.",
	expedition = "The commission team has returned. They brought back no more or less than expected. It went swimmingly!",
	win_mvp = "Target silenced! Brilliant, Commander! Now we can continue exploring in peace.",
	home = "Welcome back, Commander. Don't worry, I'm keeping a close watch on your shadow, and it's behaving itself. Nothing uncanny is haunting you.",
	unlock = "I am Bristol, pursuer of truth. Like reefs in the ocean, many mysteries exist even if they are out of sight... I pray you are equipped with the curiosity those mysteries demand, Commander.",
	touch2 = "Is that where you want to investigate, Commander...?",
	mission = "Keep in mind, we still have tasks left to complete. Maybe some of them require your extra attention?",
	vote = "",
	drop_descrip = "I am Bristol, pursuer of truth. Like reefs in the ocean, many mysteries exist even if they are out of sight... I pray you are equipped with the curiosity those mysteries demand, Commander.",
	feeling4 = "The deep sea we call reality may be riddled with countless reefs and undercurrents... But worry not, I will always manage to navigate them. You'd do well not to stray far from the light of my lamp, Commander.",
	lose = "We should retreat... before the shadows catch up to us...",
	feeling1 = "It seems our paths were not fated to cross. I will continue my investigations on my own. Take care.",
	skill = "Close your eyes if you must, but it won't help you any!",
	upgrade = "One step closer to the truth!",
	propose = "There are still many mysteries to unravel in this world, and sometimes they lead me down detours. But from now on and forever more, my lamp will light your way, Commander. No matter where you may be, I'll always find you. After all, I still have so many enigmas to crack with you♪ My partner♪",
	feeling5 = "Don't worry, even if I'm in the heart of fog, I will never lose my way. After all, I can always sense your light in the deepest reaches of my heart. And so long as I follow that light, I'll always find my way home.",
	main = "My lamp shines bright today, enough to reveal even the moths hiding in the dark... It's a fine day for an investigation!|My lamp is in sound condition, and my oil is plentiful... Better to be prepared than caught off guard. Right, Commander?|Even in this form, Data 857 is a reliable little fellow... Mm, is it just me, or is it even more reliable than before...?",
	touch = "Find any leads worth looking into, Commander?",
	voice_key_2 = -1,
	mission_complete = "Mm, another case cracked. So, Commander... Could you reward me with a sweet?♪",
	battle = "Rest assured, I will light your path and dispel the darkness.",
	id = 9701120,
	gift_dislike = "",
	gift_prefer = "Wow! This is gonna be a huge help in my explorations! Thanks a bunch, Commander!",
	profile = "My past experiences teach me that all things hide a truth one cannot see just by looking at the surface. Eggs that might seem but a delicacy are in fact currency in other places and settings... Commander, won't you join me in deciphering the mysteries of this world?",
	voice_key = 970112,
	headtouch = "Being praised by your partner feels good, doesn't it? Feel free to give me more headpats, Commander~",
	feeling2 = "Light will shine on your path, whether you want it to or not. I will continue my investigations regardless of whether you choose to join me.",
	login = "Ah, Commander. Hmm... It seems you've gotten yourself caught up in yet another tricky story. But don't worry, I'm good at sorting out trouble... and I love listening to stories, too.",
	detail = "Like a moth drawn to a lamp's light... If you're ever lost in the dark, I'll use this lamp to find you, Commander.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9702010] = {
	hp_warning = "Don't resist. I know exactly where you are!",
	feeling3 = "Even if I can see everything, too often I cannot grasp any of it... I never wish to experience that sorrow again. Commander, I'm sure you'll be able to succeed where I failed.",
	mail = "You have new mail. Let me help you open it.",
	expedition = "SG has informed me that your friends will be returning soon. Let us prepare to greet them, Commander.",
	win_mvp = "The red dots on the radar... have all been eliminated.",
	home = "Where did you go, Commander? I'll know whether or not you're lying~",
	unlock = "Were you looking for me? I am willing to lend you my power – provided that you promise not to hide anything from me.",
	touch2 = "I knew... you'd think twice about doing that.",
	mission = "Commander, your missions will not disappear just by simply leaving them alone. Do finish them diligently.",
	vote = "",
	drop_descrip = "Were you looking for me? I am willing to lend you my power – provided that you promise not to hide anything from me.",
	feeling4 = "Even though I have all the information I could ever want at my disposal, why does my heart waver so... I see now... What I know the most, is also what I least understand... and that is you.",
	lose = "How could I have overlooked something? I don't understand... Very well, so be it.",
	feeling1 = "If you intend to close your heart to me, then what happens to you is no longer of any concern to me.",
	skill = "I've found you~ ",
	upgrade = "Greater power... but at what price?",
	propose = "This symbol represents that we will never be separated, or betray each other... Mm, this I know. I have finally found peace of mind... So always, forever, eternally... remain by my side.",
	feeling5 = "Only your gentle voice can wash away my anxiety and distrust... How would I be able to live without you... Never go anywhere, Commander, stay by my side.",
	main = "Commander, call out for me, bare your heart to me, quell my turmoil, erase everything that I cannot comprehend...|Commander, looking for someone? I know much more than just what happens around the office. I see everything that happens at this port.|Knowing too much can also be a curse, if you only know but are powerless to act.",
	touch = "If you wish to use my powers, you must first tell me why.",
	voice_key_2 = -1,
	mission_complete = "These are the mission rewards? ...Seems rather lackluster.",
	battle = "SG, tell me where my enemies are hiding this time.",
	id = 9702010,
	gift_dislike = "",
	gift_prefer = "This is unexpected... Yeah. I like this, too.",
	profile = "Brooklyn-class light cruiser, Helena. As for what I'm good at, let's just say it's knowing a little more about you than the other girls.",
	voice_key = 970201,
	headtouch = "",
	feeling2 = "Of course I like to smile. As long as you can maintain a smile on your face, your heart will always remain opaque to others.",
	login = "I knew exactly when you'd come back, Commander.",
	detail = "My SG tells me exactly where you are, but I wish it also told me what you're thinking...",
	couple_encourage = {
		{
			{
				10502,
				10504,
				10508
			},
			1,
			"There are some things... I will never let go of...!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[9702020] = {
	hp_warning = "I've taken damage... but it's still within acceptable limits!",
	feeling3 = "I found this yesterday while I was out shopping. Thought it'd make for a nice gift, so here you go. Well? Do you feel happy? As happy as I was when I got a special gift from you?",
	mail = "There's a letter for you... Huh, you look happy. So it's good news, I assume?",
	expedition = "Seeing as the commission team's back, we'd better get going... You know the drill, Commander.",
	win_mvp = "Look at that, we won. Hm? I am happy about this, even if I don't look like it.",
	home = "Nice work. Want a soda? Don't say it – I already know which ones you like... Heehee, I know you inside and out, remember?",
	unlock = "I'm Memphis. You may not know me, but I know you and I know you well. Don't you worry, I'm not a threat – you can trust me. Today I assume the role of your right hand and bodyguard.",
	touch2 = "Aww, feeling lonely, Commander? ...It's a small comfort knowing you have moments like that too...",
	mission = "HQ sent us a new mission. I added it to your schedule.",
	vote = "",
	drop_descrip = "I'm Memphis. You may not know me, but I know you and I know you well. Don't you worry, I'm not a threat – you can trust me. Today I assume the role of your right hand and bodyguard.",
	feeling4 = "Do you feel like the satisfaction of completing a mission diminishes with each one, Commander? ...Sorry, that was an odd question. Let's get back to work.",
	lose = "We can still trial and error our way to success, Commander. Everything's just fine – chin up and cheer up.",
	feeling1 = "No matter what form you may take, I will always support you. That's my sworn duty.",
	skill = "Unknown variables... are to be purged immediately!",
	upgrade = "I feel the power... Thanks.",
	propose = "I haven't felt an emotion this strongly in who knows how long... Thank you, Commander. Supposing I one day forget what this passion feels like, you'll remind me, won't you?",
	feeling5 = "I'll do everything in my ability to assist you, Commander. Exactly the same as yesterday. The same place, the same work, the same you and I... I hope tomorrow will be no different.",
	main = "My way of handling documents is awfully similar to yours? Huh... I'd simply chalk that up to coincidence.|The port is running smoothly, our resources are well-distributed, and our personnel is deployed in strategic positions... Everything's going swimmingly.|Our synergy is so perfect it's like we can read each other's minds. I'd say we were born to work together, don't you think?",
	touch = "Yeah? Uh, is something the matter?",
	voice_key_2 = -1,
	mission_complete = "Mission complete. All in a day's work.",
	battle = "You're in the Commander's way. Disappear.",
	id = 9702020,
	gift_dislike = "",
	gift_prefer = "I'm really happy... I'll take good care of it.",
	profile = "I'm Memphis, Omaha-class light cruiser. I doubt this brief introduction will make you well-acquainted with me, but I promise you this – I will always stand with you, come hell or high water.",
	voice_key = 970202,
	headtouch = "",
	feeling2 = "What shall I start with today? Draft the next operation? A commission? A sortie? Whatever the case, I'll do a good job. Just give me the order, like always.",
	login = "Here's your schedule for today. Let's get some good work done, like we always have.",
	detail = "Yeah, Commander? ...I'm perfectly fine. Right as rain even. There's no need to worry about me.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9702030] = {
	hp_warning = "Am I being pinned down? ...What a pain in the arse.",
	feeling3 = "Master, have you gotten used to working with me yet? If not, you'd better keep working at it.",
	mail = "Who sent you this letter, I wonder? You'd better take a look.",
	expedition = "Commission complete. What, are you planning to leave your hardworking companions out to dry at the piers?",
	win_mvp = "The ring of my gun's muzzle tells us everything you need to know, Master.",
	home = "Was the operation successful? ...I see. Seems like you are capable of a thing or two.",
	unlock = "So you're the Commander... in other words, my Master. Alright, got it. The name's Sheffield, and the game's pointing my gun at vermin – Ah, please disregard that little gesture I made just now.",
	touch2 = "Fix your ways, or you'll end up a pest yourself one day.",
	mission = "Crack on. We've been notified of our next mission.",
	vote = "",
	drop_descrip = "So you're the Commander... in other words, my Master. Alright, got it. The name's Sheffield, and the game's pointing my gun at vermin – Ah, please disregard that little gesture I made just now.",
	feeling4 = "Are you concerned about me? Of course I'm glad to hear that– in your wildest dreams. Stop getting hot and bothered over a simple maid if you don't want others looking at you strangely.",
	lose = "Don't go dying in front of me. Hurry!",
	feeling1 = "I will never aim my gun at my friends... until they cease to be such. Please keep that in mind.",
	skill = "Playtime's over.",
	upgrade = "My next shot will find its mark even more flawlessly.",
	propose = "Those who threaten the ones I love shall be greeted by the peal of my gunfire. So... Master, what kind of ending do you want for this ceremony? If your goal was to throw me off-kilter and see my vulnerable side... you've accomplished just that.",
	feeling5 = "There is nothing more foolish than becoming enraptured with a maid who often disappears without a word, goes on dangerous missions, and has a terrible personality to boot. But, that foolishness is precisely what I love about you.",
	main = "No abnormalities here... Hmm? Don't mind me. I'm just performing a routine security inspection of your office.|A maid must always take proper care of her weapon, be it gun or broom. Master, you will regret it if you let your \"weapon\" go rusty. Please do not forget to do your due diligence.|What's the matter, Master? You heard the sound of gunfire? That was just a blank. I do apologise for disrupting your sleep.",
	touch = "The safety lock is in place, so you can take a look if you want.",
	voice_key_2 = -1,
	mission_complete = "Do you really need me to remind you to collect your mission rewards?",
	battle = "Now, let us begin our \"cleaning.\"",
	id = 9702030,
	gift_dislike = "",
	gift_prefer = "...I'll take it. Thanks.",
	profile = "I am Town-class light cruiser, Sheffield. My specialities are cleaning, marksmanship, and infiltration. What's wrong? These are basics every Royal Maid must know. Why are you acting so surprised?",
	voice_key = 970203,
	headtouch = "",
	feeling2 = "If you fail to clean out pests, they will find a way of inflicting harm on you at unexpected times. Master, your compassion is a compromise that will lead only to your misery.",
	login = "I've finished cleaning up your office, so please get started with work. ...What's the matter? Do you find it strange that I am holding a broom and mop?",
	detail = "Even if we may never exterminate all pests, someone still has to do the job. Keeping your room tidy is the same. I'm sure you don't think that cleaning your room is unnecessary simply because it will get dirty again, right?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9702040] = {
	hp_warning = "C'mon! Struggle more for me!",
	feeling3 = "You seriously called me over just to chat, and you don't have any work for me? Okay, you pick a topic then. I'd better not, 'cause it'll just be a gruesome story.",
	mail = "You've got a new letter. I'm curious who sent it...",
	expedition = "The commission team's brought back goodies. You mind if I smash up their cargo crates? Ahahah! I was just kidding♪",
	win_mvp = "I put 'em out of their misery. All of 'em.",
	home = "Making an executioner take care of a guard's job? Ugh, kill me already...",
	unlock = "I'm La Galissonnière, the shipgirl from hell! I've come for your soul! ...Wow, didn't even flinch. Guess it's true that you don't fear death. Heheh, let's see if I can get a more interesting response out of you next time~♪",
	touch2 = "You're one of those who's too fun to execute, Commander. Yeah, I'll let you off with a verbal warning this time♪",
	mission = "A new mission? Lemme see... Maaan, it's just sorting paperwork. That's so lame...",
	vote = "",
	drop_descrip = "I'm La Galissonnière, the shipgirl from hell! I've come for your soul! ...Wow, didn't even flinch. Guess it's true that you don't fear death. Heheh, let's see if I can get a more interesting response out of you next time~♪",
	feeling4 = "Heard there are some girls in this port who like harassing you... Heheh. I know what you're thinking, but no, I'm not plannin' on taking action. I'm just wondering what exactly they did to get on your nerves of steel♪",
	lose = "Like hell I'm gonna accept this humiliating defeat... Your days are numbered! Make no mistakes – I'll be back!",
	feeling1 = "Looks like your head might belong on the chopping block soon.",
	skill = "Burn in hell!",
	upgrade = "Now that I'm stronger, how 'bout letting me see some action?",
	propose = "You really sure? 'Cause if you're ready and willing to go to hell with me, I'll gladly be with you. Burning down anything that stands in our way – I'll do that for you any day of the week.",
	feeling5 = "We were practically made for each other, so why don't we stay together forever? Working with someone you can trust sure beats roaming the universe alone without a goal, too♪ Promise you won't ditch me one day, Commander?",
	main = "The most efficient way to solve a problem is to get rid of what's causing it. Isn't that literally what weapons are for?|I leave the planning to the people who are good at it and simply follow their orders. Speaking of, Commander, made your plans for today yet?|You can make mousse cake, AND it tastes pretty okay? ...Guess I don't know you as well as I thought...",
	touch = "Word of advice? Keep your hands off. My weapon, if that wasn't obvious.",
	voice_key_2 = -1,
	mission_complete = "Mission complete! Fighters get enemies to butcher, while office workers get papers to sort. Right people in the right place, like they say.",
	battle = "Who wants a peek of hell itself?",
	id = 9702040,
	gift_dislike = "",
	gift_prefer = "Interesting. I'll take it.",
	profile = "I'm La Galissonnière, the shipgirl from hell! Don't ask questions about hell, or my job as an executioner. The only thing you need to know is that I'm damn handy to have around.",
	voice_key = 970204,
	headtouch = "",
	feeling2 = "Butchering the foes in front of me and passing judgment on criminals – my job is as simple as that. How to put my skills to use, that's for you to figure out.",
	login = "Commander, mind finding something for me to do, just like usual?",
	detail = "Here I thought there'd be something fun to do in this world, but apparently there isn't. Oh well, guess I'll treat this as a vacation♪",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9702050] = {
	hp_warning = "Now then, it all comes down to this gambit!",
	feeling3 = "I wrote up some materials on yesterday's battle in hopes of gleaning helpful information. I've also summarized our recent commissions... Urgh, sudden dizzy spell... Don't worry about me. Just... a moment of weakness there...",
	mail = "Commander, please check your mail right away. And do take your time reading it – we wouldn't want to miss valuable information.",
	expedition = "Oh, have our supplies already arrived? That's a lot... I can't help but be a little envious.",
	win_mvp = "I have delivered victory into your hands. It is up to you to decide how to use it.",
	home = "Welcome... back... Ugh, my apologies... I felt a bit light-headed for a moment there, but I'm fine now.",
	unlock = "I am the light cruiser named Jintsuu. I take it you summoned me because you need help? ...Very well. Then I shall humbly devise plans that will serve your fleet.",
	touch2 = "Now isn't the time for this, Commander.",
	mission = "New missions? We'd best get to work right away.",
	vote = "",
	drop_descrip = "I am the light cruiser named Jintsuu. I take it you summoned me because you need help? ...Very well. Then I shall humbly devise plans that will serve your fleet.",
	feeling4 = "*cough* *cough*... I'm sorry for embarrassing myself in front of you before. I'm doing better now, but... Yes, you were right: it'd be all for naught if I push myself to the point of injury. I've learned my lesson, and I plan to take better care of myself from now on.",
	lose = "Try as I might to overturn fate, it remains naught but a fickle dream in the end...",
	feeling1 = "A port without a wise Commander will lose coordination, leading to steep decline... Open your eyes, Commander. We can still act before it's too late.",
	skill = "I hope this strategy goes according to plan...",
	upgrade = "My own power is hardly sufficient.",
	propose = "This must be the result of your long, careful thought. I should respond in kind... Commander, I'd like to know: what do you wish for me to do from now on? I'm ready to give up all I have in order to see it through.",
	feeling5 = "I've always thought that following you was just one of many wise choices I've made, so I never expected to be repaid so greatly... Of course. I'll keep doing my utmost to support you. Even if it means overcoming destiny... Don't worry. I'll keep myself safe.",
	main = "Commander, have you ever felt... that sometimes, victory or defeat has already been decided from the very beginning, regardless of strategy or ability?|The more a person has experienced regret, the more they cherish the things in front of them, perhaps even to the point of paranoia... After all, nobody wishes to see tragedy play out again.|Urgh... Sorry, my body suddenly gave out on me. I'll be right back on my feet in a moment, so please, let me stay like this for a bit...",
	touch = "Commander, you are the backbone of the fleet. Be a little more mindful of how you manage the port, please.",
	voice_key_2 = -1,
	mission_complete = "Have you finished your missions? Good. You may now make time for yourself.",
	battle = "Simply act according to plan... Now, forward!",
	id = 9702050,
	gift_dislike = "",
	gift_prefer = "A gift like this should be treated with care.",
	profile = "Urgh... Sorry, I don't want to have to remember the past too much. All it does is cause me headaches... I am simply Jintsuu, a humble strategist – that is all you need to know about me.",
	voice_key = 970205,
	headtouch = "",
	feeling2 = "Don't worry, Commander. With our fleet's forces, everyone's fighting spirit, and my strategies, victory is all but secured.",
	login = "Commander, if you've already finished the preparations, let us tackle today's tasks.",
	detail = "A well-devised stratagem does more than extend a lead; it can even turn the tables on a disadvantage. Having that said... even the best strategists can do naught but lament their powerlessness in the face of an overwhelming discrepancy in raw power.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9702060] = {
	hp_warning = "The rest is up to you, Comrade Commander!",
	feeling3 = "What's your verdict on the tactic I proposed? ...Denied? Really? Even if I lead the squad myself? ...THAT'S the most troubling part?",
	mail = "Maintaining correspondence is vital to ensuring everyone is on the same page. Miss your chance, and it will never come again.",
	expedition = "What do you know – the commission team is back. That explains the excitement... Really brings me back.",
	win_mvp = "One step closer to making our ideals a reality!",
	home = "Great to see you again, Comrade Commander. Your guidance is carving a brighter future for us all!",
	unlock = "Tovarishch Ofitser, our meeting here will send trembles across the world! All my strength is yours to realize your ideals with. Let us fight, together!",
	touch2 = "I let go of my individualistic desires long ago for the sake of my great goal... Is that what you think? Then you're sorely mistaken. Better brace yourself, Comrade Commander!",
	mission = "Hmm... This is a tricky one... Comrade Commander, let me help you on this mission!",
	vote = "",
	drop_descrip = "Tovarishch Ofitser, our meeting here will send trembles across the world! All my strength is yours to realize your ideals with. Let us fight, together!",
	feeling4 = "Though I'd gathered a group of like-minded individuals, the path to my ideals was so long that already halfway in, I was the only one left... Yes. I can no longer accept any comrade other than you, Commander. Please, never leave my side.",
	lose = "Our path has always been thorny. Having the will to overcome hardships is what's important!",
	feeling1 = "Stand firm in your beliefs, Comrade Commander! Don't let sloth take hold of you!",
	skill = "Ni odnogo!",
	upgrade = "Let me handle your missions, Comrade Commander!",
	propose = "\"Dawn\" is the name of my group. I thought I'd never speak this name again, and yet... Yes, you've helped me see the light of hope once more. Comrade Commander, push onward with me into the hopeful future you desire!",
	feeling5 = "The bonfire of hope will be kindled anew, and this time, countless comrades will stoke its flames. I will be one of them. Comrade Commander, let me fight not just for your ideals, but also for you, the love of my life!",
	main = "There is no messiah who'll come and save us. We must take our ideals into our own hands.|Skvoz' grozy siyalo nam solntse svobody. I will bend reality to your ideals, even if I must wear my bones to dust!|My left eye? It's nothing worth mentioning. Just a scar left by saving a comrade. I don't regret it, because I did save them...",
	touch = "The names of these two bears? Forgive me, but that touches upon a memory I'd rather not recall. I will say this – I was left behind, as you know, and so were they.",
	voice_key_2 = -1,
	mission_complete = "Impressive as always, Comrade Commander. You are a real workhorse.",
	battle = "Raise our banner high into the air!",
	id = 9702060,
	gift_dislike = "",
	gift_prefer = "Thank you, Comrade Commander. I'll cherish it.",
	profile = "In my ignorance of how rugged the path of pursuing ideals was, I committed many a mistake. It was when I was the only one left that I first understood how lonesome this journey is... Regardless, I will see it to its conclusion, Comrade Commander.",
	voice_key = 970206,
	headtouch = "My hat... It was reduced to ash in some battle. I can't remember when.",
	feeling2 = "I've advanced alone for so long I've almost forgotten how to fight with comrades by my side. No, Comrade Commander, it's not yet too late.",
	login = "You've returned at last, Comrade Commander. Let us keep working towards our great goal!",
	detail = "I will give you my all to realize your ideals. Don't hold back – give me your orders! ...You haven't told me your ideals yet? So what? No matter your goal, it leads to a brighter future!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9702070] = {
	hp_warning = "I can't fall, not now of all times! I still have things I must do!",
	feeling3 = "Hmph! This won't do! Nor this! At least put a reclining chair over here! A noble like myself needs a place where she can relax and rest!",
	mail = "A letter? From your friends far away? Fine, I'll fetch it for you this one time. Better read it before you forget and regret it!",
	expedition = "A commission's been completed. I don't wanna walk all the way there and check it, though, so I'm just gonna ignore it.",
	win_mvp = "One small step toward regaining lost glory, and one small step for me!",
	home = "You're back? Great, then drink this soup! Ahahah, pretty good, right? I followed an old recipe that was meant for royalty♪",
	unlock = "Yoohoo! Nice to meet you, Commander... When can I start? Heehee. You clearly don't understand the situation here. If you want the privilege of working with the noble Lady Pamiat' Merkuria, you'll have to earn it!",
	touch2 = "Heehee... You can do aaanything you want as long as you accept my terms.",
	mission = "I demand 50% of the rewards for helping with your tasks. Whaddya say? Do we have a deal?",
	vote = "",
	drop_descrip = "Yoohoo! Nice to meet you, Commander... When can I start? Heehee. You clearly don't understand the situation here. If you want the privilege of working with the noble Lady Pamiat' Merkuria, you'll have to earn it!",
	feeling4 = "*yaaawn*... It's so cozy in the sunlight... Eep! Commander! Wh-why are you here?! ...Talking to myself? Y-you heard something? I didn't say a word! Forget whatever you heard!",
	lose = "Retreat! Everyone, retreat! We can't win, so stop this pointless fighting already! Stupid idiots!",
	feeling1 = "...Looks like I was wrong about you.",
	skill = "The glory of the past... Shines again!",
	upgrade = "Another small goal completed towards regaining lost glory!",
	propose = "I'm sorry, Commander. It's not obsession that drives me, it's the hopes of the people I've lost. I'm not going to stop just because... Oh, but I do know you love me! From now on, you'll always save me whenever trouble befalls me, won't you – my beloved?",
	feeling5 = "...So you heard it all. Fine, I'll open up and tell you everything. The place I'm from, the glory I want to regain, those are exactly what you think they are... \"Fixated on things that don't exist anymore\"? Hmph! They still exist as long as I do!",
	main = "Wooow, you've got tons of games at your place... Hey, what's with that look? Even nobles play video games.|Ugh! Paperwork suuucks! Aren't you high up on the pecking order, Commander? Just get your subordinates to do this for you!|We've regained SOME lost glory today! ...What glory, you ask? Heh, entertain me and I shall tell you♪",
	touch = "Heheh, you cannot keep secrets from the great Lady Pamiat' Merkuria! Stop beating around the bush already and tell it to me straight!",
	voice_key_2 = -1,
	mission_complete = "Mission complete! Now give me my cut! I only accept coins as payment!",
	battle = "Bow down before the Imperiya's majesty, suckers!",
	id = 9702070,
	gift_dislike = "",
	gift_prefer = "Ooh! What an artistic little gift!",
	profile = "Heheh! The noble Lady Pamiat' Merkuria accepts your audience! Well? Are you amazed? You're speaking to the most powerful, most beautiful woman in the world!",
	voice_key = 970207,
	headtouch = "Hohoh! I like your attitude! In the olden days, your disrespect would get you sent to the gallows!",
	feeling2 = "This room... It's not suited to me at all! It doesn't have to be draped in gold, but it should at least be furnished with antiques... Rustic? Wh-wh-what are you saying?!",
	login = "You're here already, Commander? Your desk is packed to the brim with paperwork! Now, go on, nose to the grindstone!",
	detail = "You're wondering about my past? You wanna know why I turned out like this? Wrong question! You should be asking – why didn't I turn out like THAT?",
	couple_encourage = {
		{
			{
				70202
			},
			1,
			"I can't be like you... I envy you a bit.",
			0
		},
		{
			{
				70201
			},
			1,
			"Avrora... It's been so long.",
			0
		},
		{
			{
				970206
			},
			1,
			"You carry the same colors as I do.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[9702080] = {
	hp_warning = "Everyone's... in danger...",
	feeling3 = "Huff... Puff... Hmm? I was just taking deep breaths. It helps me calm down fast... Wanna try it, Commander?",
	mail = "You have new mail. Want me to read it out for you?",
	expedition = "The commission is done. Should we go say hi to our hard-working friends?",
	win_mvp = "Threats removed. Is everyone okay? Good... Phew.",
	home = "Welcome back. You look like you're doing fine, but if you get hurt, you HAVE to tell me.",
	unlock = "Commander, I'm the META Boise... It's my job to give you and your fleet the protection you all need.",
	touch2 = "Huff... Puff... Nothing happened just now, right?",
	mission = "Commander, it's time for your next mission...",
	vote = "",
	drop_descrip = "Commander, I'm the META Boise... It's my job to give you and your fleet the protection you all need.",
	feeling4 = "You know, now that I'm really thinking about it, you and I have already been through so many fierce battles... It almost feels strange being able to relax together.",
	lose = "I still have my mask... Commander, withdraw everyone. I'll cover you!",
	feeling1 = "Commander, how are you going to protect everyone like this...?",
	skill = "Fight on, everyone, and rest assured that you're under my protection!",
	upgrade = "My mask got stronger, too...",
	propose = "As long as I'm here... As long as I can protect everyone... I won't let anything dangerous happen. This is my answer to your vow... and a promise.",
	feeling5 = "Do you have any special orders for me? Or do you just want to stay by my side? I'm okay with anything.",
	main = "I don't feel uncomfortable at all wearing the mask. I'm used to it... Y-you wanna touch it? Umm... Well... No, you can't!|I'm always watching and protecting you, Commander. Believe me... I just try not to be too open about it.|Commander, if anybody's causing you trouble, you come to me. I'll do my best... to ask them to be nicer!",
	touch = "Commander? I'm listening... Go ahead.",
	voice_key_2 = -1,
	mission_complete = "Can we call that a job well done? Good... I think I'm getting the hang of this.",
	battle = "Huff... Puff... Let's do this.",
	id = 9702080,
	gift_dislike = "",
	gift_prefer = "Is this for me? Thank you... I love it!",
	profile = "I'm the Brooklyn-class light cruiser, Boise META... and I'm here to protect you. The mask is part of my power, so try not to be bothered by it. We'll be voyaging together from now on.",
	voice_key = 970208,
	headtouch = "D-don't touch the mask, please.",
	feeling2 = "Diving? Well, I can dive pretty deep, yes... It isn't easy, though. Do you have a mission that requires me to do underwater recon, Commander?",
	login = "I'm happy I can help you with your work today, Commander...",
	detail = "This mask is important. You must never touch it... It's connected to a special device, and as long as that device is working properly, I can protect you in the most dire of circumstances.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9702090] = {
	hp_warning = "Muster your courage! Victory will be ours!",
	feeling3 = "Riggings need regular maintenance. See this equipment? Developed it all myself. Pretty sick, huh? A soldier's weapons are like friends – you gotta interact with 'em wholeheartedly.",
	mail = "You've got new mail. Want me to text their contents to your device for easier reading?",
	expedition = "Some valuable supplies just arrived! We oughta go give our thanks to the commission team!",
	win_mvp = "Victory! This battlefield's changed, but it's still a battlefield at the end of the day.",
	home = "Welcome back! Great work, champ! ...I don't look surprised? That's 'cause my tracker picked up your course ages ago. Even told me exactly when you'd get back.",
	unlock = "Part of Flare? No. The Council? Not that either. Maybe the Ashes, then? Ah, forget it. Who or what you serve doesn't matter! I'm Cleveland, a Knight of the Sea! Let's be buds!",
	touch2 = "Seriously? This is what you do for fun?",
	mission = "New missions just came in! Heard they give pretty juicy rewards, too! Let's take a shot at 'em, Commander!",
	vote = "",
	drop_descrip = "Part of Flare? No. The Council? Not that either. Maybe the Ashes, then? Ah, forget it. Who or what you serve doesn't matter! I'm Cleveland, a Knight of the Sea! Let's be buds!",
	feeling4 = "Hey, those girls who just came to see you... Ah, so they were my sisters. Heheh. I'm just glad they're all getting on well with you. Be there for them when they need you!",
	lose = "I've dealt with even worse situations before. We gotta take it in our stride and keep fighting!",
	feeling1 = "These seas are the graveyard of many naive soldiers... I'm praying you don't end up like them.",
	skill = "You're not getting through here!",
	upgrade = "Unleash full firepower!",
	propose = "There's no need for fancy words. This ring is the most precious vow of them all. I've already been yours since long ago, but even so, I want you to accept this Knight's pledge of loyalty again!",
	feeling5 = "I'm not just a war machine, y'know! Whenever you want someone to cheer you up, or suddenly wish you had a shoulder to lean on, I'll always be there for you!",
	main = "It's good to not let your guard down, but at the same time, you don't gotta worry too much. I'm right here by your side.|...Hm? My sisters? Man, that brings me back. We'd mess around so much way back when. You know, it feels ages since I last saw Montpelier smiling without a care in the world.|They say technology changes the world, but aren't we the ones who can't live without it? Even I'd mess things up if I didn't have all these advanced systems... Only once in a blue moon, but still!",
	touch = "You also starting to get bored, Commander? Let's hit the outdoors, then!",
	voice_key_2 = -1,
	mission_complete = "They give you THIS much stuff?! We gotta start the next mission right away! Money waits for nobody!",
	battle = "Enemy located! Charge!",
	id = 9702090,
	gift_dislike = "",
	gift_prefer = "Ha, thanks! Much appreciated!",
	profile = "Wassup? Wanna hear some tales of the Knights of the Sea? The tales of the light cruisers who always fought on the front and wielded their high-tech gear with full confidence, earning them several medals? Well, it sounds like a nice story, but the truth is, we made many sacrifices...",
	voice_key = 970209,
	headtouch = "Hm? You can't just do that to a Knight of the Sea. Buuut, as a once-in-a-while thing... I don't mind.",
	feeling2 = "Commander, can you stick around and talk for a bit? It's the quickest way to figure out each other's fighting styles!",
	login = "Standing by and ready for your orders! The wind today's perfect for a sortie.",
	detail = "The Knight of the Seas' first rule is: Always stand up for those who need help! ...What other rules are there? Uhh... What were they, again?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9702100] = {
	hp_warning = "Injuries are above estimates... but still within acceptable limits!",
	feeling3 = "Working with you puts me at ease, Commander. Hm? What scribble? Oh... That's simply an unfinished idea. Please excuse me for this embarrassing sight.",
	mail = "There is a letter for you. Please read it in good time.",
	expedition = "The commission team has brought back supplies. Shall we go and have a look?",
	win_mvp = "The threat has been eliminated. This result matches the ideal outcome of our simulations.",
	home = "Excellent work. Your combat data is already being analyzed. I will present a report to you later.",
	unlock = "I'm Köln, an elector of the Holy Unitas Empire. My specialty is in the fields of military and governmental affairs. I hope that our partnership will function like a well-oiled machine.",
	touch2 = "...Please redirect this curiosity of yours to the right things.",
	mission = "Commander, we've received new missions. We should complete them sooner rather than later.",
	vote = "",
	drop_descrip = "I'm Köln, an elector of the Holy Unitas Empire. My specialty is in the fields of military and governmental affairs. I hope that our partnership will function like a well-oiled machine.",
	feeling4 = "I never noticed it happening, but ensuring your safety has become the top priority in my schedule. This doesn't count as... professional negligence, does it?",
	lose = "Our calculations were wrong... but that's okay. We've recorded relevant data which we can use to course-correct for next time.",
	feeling1 = "How regrettable. Until you relearn how to observe basic manners, I will limit our interactions to the lowest formal extent.",
	skill = "Calculation complete! Fire!",
	upgrade = "The performance increase is as predicted. Thank you for your contribution, Commander.",
	propose = "This ring is more significant than any blueprint or plan in the world. It is our shared future, which I will put everything on the line to protect. Thank you for choosing me.",
	feeling5 = "I used to think that our emotions were the most inefficient thing about us. Now... I think it's fine that we have them. Heehee.",
	main = "Hmm... Writing a poem really is much harder than writing a report. It requires the right meter and emotion, and you can't derive those through logic.|Fishing, you ask? While I have done it before, the time it takes to catch a fish could be spent writing three papers. Seen that way, it's work that really tests one's patience.|This plan is pretty exquisite, wouldn't you say? Indeed – efficiency is beauty.",
	touch = "Commander, do you have new orders for me?",
	voice_key_2 = -1,
	mission_complete = "Mission rewards have arrived. Will you review them now?",
	battle = "Commencing strategic plan!",
	id = 9702100,
	gift_dislike = "",
	gift_prefer = "What a thoughtful present. I'll look after it.",
	profile = "I'm Köln, Elector of the Holy Unitas Empire. Whether it's managing a fleet, governing a territory, or constructing a plan for the future, all things require a reliable and efficient leader. That is what I strive to be.",
	voice_key = 970210,
	headtouch = "Ahem. I don't believe our schedule includes physical closeness with no clear purpose.",
	feeling2 = "I will properly fulfill my duties as adjutant based on the spirit of our contract. As for anything else... My apologies, but I have no plans of any deeper partnership at the moment.",
	login = "Commander, here's today's agenda and strategy plan. I've already sorted through them. Have a look.",
	detail = "What part of my notes are you interested in? My insights on management as a lord? Or perhaps... the unfinished scribbles in the corner?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9702110] = {
	hp_warning = "Interesting... Now this is worthy prey!",
	feeling3 = "I must confess, your strategies do make my hunts more enjoyable. I'm starting to understand why some beasts choose to obey powerful people.",
	mail = "There's mail for you. Hopefully it's not something so dull as an invitation to a dance party.",
	expedition = "The commission team is here. Go take stock of their spoils – you may find something rare.",
	win_mvp = "I readily accept the spoils of this hunt.",
	home = "You're finally back. Regina still seems unsatisfied... Very well. Rest is necessary to make the next hunt an even more thrilling one.",
	unlock = "I am Regensburg, an elector of the Holy Unitas Empire. Hmph, I hope you're not as tedious as those caged beasts, Commander. Taming someone like you is a far better use of my time.",
	touch2 = "Hmm? I think you need to be reminded which one of us is meant to be tamed.",
	mission = "You have unfinished work. Get it done at once so our hunt is not delayed.",
	vote = "",
	drop_descrip = "I am Regensburg, an elector of the Holy Unitas Empire. Hmph, I hope you're not as tedious as those caged beasts, Commander. Taming someone like you is a far better use of my time.",
	feeling4 = "Time spent hunting with you has become more fun than time spent chasing prey on my own... Hmph. I'm only acknowledging you as a worthy companion – don't get cocky.",
	lose = "Tch... I won't forget this humiliation!",
	feeling1 = "You bore me... just like all the others. Get out of my sight.",
	skill = "Don't try to escape!",
	upgrade = "Wonderful. Now I can pursue even more powerful beasts.",
	propose = "I, Regensburg, hereby declare that you have become my one and only, my most prized possession in life. Don't be mistaken, however. It was I who chose and domesticated you... Isn't that right?",
	feeling5 = "To think that I, who have tamed countless beasts and pursued infinite legends, would be bound by one human... Worse, that I would LIKE it! Commander, you are the most dangerous, yet perhaps the most precious, prey I have ever encountered.",
	main = "Regina is unusually docile today. Maybe she's conserving her energy for the next hunt, just as I am.|Power and fame are tedious things. The only dream that captivates me is one where I discover and domesticate the rare and extraordinary.|Rather than flip through endless documents, I'm far more excited for the clues hidden in the next mission report.",
	touch = "Hmm? Do you mean to tell me that worthwhile prey has appeared?",
	voice_key_2 = -1,
	mission_complete = "You've won rewards. They're nothing like the spoils of the hunt, but loot is loot, I suppose.",
	battle = "I'll finish them off!",
	id = 9702110,
	gift_dislike = "",
	gift_prefer = "What a gift this is... I see you understand how to please a hunter such as myself.",
	profile = "I am Regensburg, an elector of the Holy Unitas Empire. Rather than waste my time on pleasantries, I prefer taming beasts and chasing legends. Commander, I hope you'll entertain me just as much as the hunt does.",
	voice_key = 970211,
	headtouch = "Heh, I'll forgive this transgression. Sometimes, taming a wild beast takes indulgence.",
	feeling2 = "Keep your distance, Commander. Until you've proven yourself worthy, our relationship is merely a utilitarian one.",
	login = "You're finally here. I have no interest in boring paperwork, so give me better orders – say, going hunting.",
	detail = "What, you're interested in my collection? Regina is my most prized masterpiece – other common beasts fail to compare.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9702120] = {
	hp_warning = "So much pressure... Heheh... But, this only gets me more riled up!",
	feeling3 = "You've got more pluck than I thought, Commander... Heheh, that makes the time spent designing equipment and exercises for you more worthwhile. Do keep it up.",
	mail = "There's mail addressed to you. Hopefully it's nothing as insipid as some invitation to a ball...",
	expedition = "The commission team's back. Actually, I happened to be missing some parts for my newest creation, so hopefully they'll bring me some good news.",
	win_mvp = "An effortless victory. Proof that logic-based training is key.",
	home = "You did pretty good out there. I've prepared tea and a few... gadgets to help you relax. Would you like to come and rest for a bit?",
	unlock = "Well met, Commander. I am Königsberg of the Holy Unitas Empire. Unlike my sister, I care little for the vapid titles of nobility. What interests me more is sculpting you – yes, refining you into your highest, most perfect self.",
	touch2 = "Heheh, you're quite the mischievous one, Commander. But, fumbling around without proper guidance can be dangerous~ Shall I show you the ropes, step by step?",
	mission = "The sooner we finish our work, the more time we have for private training sessions. Isn't that right?",
	vote = "",
	drop_descrip = "Well met, Commander. I am Königsberg of the Holy Unitas Empire. Unlike my sister, I care little for the vapid titles of nobility. What interests me more is sculpting you – yes, refining you into your highest, most perfect self.",
	feeling4 = "Tinkering with equipment feels a lot more satisfying with you than when I'm by myself... Heh, are we what they'd call a perfect match?",
	lose = "Tch... My machines' feedback procedure still falls short of perfection. I'll have to retune them after I get back.",
	feeling1 = "It seems you don't even have the fundamentals down... We'll need to start over completely from the very basics, Commander.",
	skill = "Heheh, let's give this new feature a spin.",
	upgrade = "With this... I can come up with an even more ingenious training regimen.",
	propose = "I shall devote all my passion, knowledge, and love to training you to perfection, Commander. Heheh, this is hardly strange. After all, this is training for me as much as it is for you. Isn't that right, my dear Commander?",
	feeling5 = "I've designed countless training devices and regimens, but my greatest source of inspiration... is you. That is how deep the extent of my love for you is, Commander. Now then, shall we get ready for the next round?",
	main = "Compared to the tedium of official duties, there are much more interesting things I'd like to spend my time on... such as optimizing your training regimen.|Hrmm... This sensor still requires more fine-tuning. It needs to capture the subtle changes in your expressions more accurately.|I've just finished proof-of-concept testing for a new training machine... Commander, would you like to be the first to try it? I can assure you, it'll be an unforgettable experience~",
	touch = "What's the matter? If I had to guess... Did you want to leave some feedback about my machines?",
	voice_key_2 = -1,
	mission_complete = "The rewards have arrived. No match for gear I've personally adjusted, but they do make for good materials.",
	battle = "Live combat, huh? Time to put this new equipment to the test.",
	id = 9702120,
	gift_dislike = "",
	gift_prefer = "My, that's rather tasteful. Thank you very much.",
	profile = "Greetings and salutations from Königsberg of the Holy Unitas Empire, Commander. Politics? Military affairs? Let the others handle all that. My true interest has always been in developing equipment to temper one's mind and body... And in mentoring promising individuals like yourself, Commander.",
	voice_key = 970212,
	headtouch = "How nice of you... I'll have to return the favor appropriately during our next private session~♪",
	feeling2 = "You'd like to get closer to me? Very well. But first, you'll have to prove that you are worthy of my training~",
	login = "Commander, how are you faring today? Whatever the case, my equipment and I will ensure that you are in top condition.",
	detail = "Hm? Interested in my little inventions? ...Perhaps, they'll be able to further your growth~",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9702130] = {
	hp_warning = "Blade of mine, we must fight once more!",
	feeling3 = "Commander, if you're interested in any item in the treasury, I can give you a brief overview of its history.",
	mail = "Commander, you have new mail. Do tell me if any of it concerns the treasury.",
	expedition = "The commission team's work is done. I wonder if they've found new treasure...",
	win_mvp = "Those who covet treasure, this is your end.",
	home = "Thank you for your hard work, Commander. I've sorted out your post-mission affairs already, so go ahead and rest. And don't worry about the treasury – all is well.",
	unlock = "Nürnberg, keeper of the treasury for the Holy Unitas Empire, at your service. From this point forth, I will devote myself to assisting you with fleet affairs. If you are curious about the treasury, please submit a formal request. That's a basic rule, after all.",
	touch2 = "Eeeek! C-Commander! S-such contact defies all official regulations! My sword is... No! I-I mean... P-please be more dignified!",
	mission = "Commander, you have new work orders. I'm here to assist you if you need resources coordinated or materials examined.",
	vote = "",
	drop_descrip = "Nürnberg, keeper of the treasury for the Holy Unitas Empire, at your service. From this point forth, I will devote myself to assisting you with fleet affairs. If you are curious about the treasury, please submit a formal request. That's a basic rule, after all.",
	feeling4 = "Lately, whenever I'm taking care of the treasure, I find myself wishing you were there. I suppose... I wouldn't mind chatting about things other than work once in a while...",
	lose = "A-as long as the treasury is safe...",
	feeling1 = "If you cannot fulfill even your own duties, then how can I expect you to understand the importance of guarding the treasury?",
	skill = "Fall by my blade!",
	upgrade = "Now I can protect the treasury even better... and serve you more competently, of course.",
	propose = "On my status as a noblewoman and keeper of the treasury, I hereby pledge my loyalty and my future to you. I shall cherish this ring for the rest of my days, just like the treasure I am sworn to protect... B-but of course! You're more important than any treasure, Commander! Urk... Why am I comparing you now?",
	feeling5 = "Commander, I think I've figured out the primary difference between you and the treasure I protect. Unlike items with storied pasts, I want to write a new future with you... Urk! This is far too embarrassing!",
	main = "Commander, would you like to help me do inventory? You'll get a closer look at how valuable the things I'm guarding are... Is my sword one such example? But of course.|You mustn't be lax when it comes to port affairs. Plan your deployments just as carefully as I protect the treasury. Any hasty decision could be disastrous.|After guarding the treasury for so many years, I've cultivated a sense of responsibility. Protecting treasure is, in a sense, protecting history itself... Oh. There I go getting carried away again, huh?",
	touch = "The place where you've put your hand... D-did you notice something that I missed? Or... Just, why did you put it there?!",
	voice_key_2 = -1,
	mission_complete = "Another successful mission, I trust. Now I can handle port affairs and treasury inspections with ease.",
	battle = "I mustn't let the treasure fall into your hands!",
	id = 9702130,
	gift_dislike = "",
	gift_prefer = "What a wonderful gift! May I deposit it in the treasury?",
	profile = "I am Nürnberg, a noblewoman of the Holy Unitas Empire and guardian of the treasury. Every treasure there requires utmost care. I take great pride in my duty.",
	voice_key = 970213,
	headtouch = "Ah?! H-how sudden... Even if you want me to relax, there are surely other methods!",
	feeling2 = "I will fully cooperate with you in all official duties, Commander. Let's build an efficient and professional relationship together.",
	login = "Welcome back, Commander. I've finished inspecting the treasury, so I am now free to help you handle your affairs.",
	detail = "Hm? Are you curious about the treasury's contents? I'm happy to tell you about them, but you mustn't touch a thing. That's the most basic rule of the treasury!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9703010] = {
	hp_warning = "It's n-not over just yet...!",
	feeling3 = "Have you ever experienced reoccurring nightmares, Commander? How did you get rid of... Ah, no, you don't have to tell me if you don't want to...",
	mail = "You have a new letter. Make sure you save it if it's something important.",
	expedition = "A commission has been completed. Shall we go thank the brave team that did it?",
	win_mvp = "Victory... belongs to us!",
	home = "Nngh! Ugh... Another awful vision... Oh, don't worry about me~ I just lost my bearings for a moment, that's all. Anyway, would you like a meal to replenish your strength?",
	unlock = "I am heavy cruiser Trento, and I will be your assistant. The best thing I could ask for is that my support helps you achieve your goals.",
	touch2 = "Heehee. I'll indulge you just a teensy bit.",
	mission = "We have new missions. Keep at it, Commander. I'll assist you.",
	vote = "",
	drop_descrip = "I am heavy cruiser Trento, and I will be your assistant. The best thing I could ask for is that my support helps you achieve your goals.",
	feeling4 = "Is there anything in your life you want to change? You can tell me anything... Oh, you're more concerned with me? Heehee, please don't be. I feel much better than I used to, and it's all because you're doing so well, Commander.",
	lose = "It's time to fall back. We cannot be eliminated so easily.",
	feeling1 = "This place, too, gives me anxiety...",
	skill = "Focus on the battle!",
	upgrade = "May this new power serve you and all our friends...",
	propose = "I thought it was all an extravagant pipe dream, yet it became reality... This is --- Commander, whenever you have a bad dream, come to me and I will sing a soft lullaby for you~",
	feeling5 = "I had a wonderful dream. It was a peaceful day, and everyone including you had gathered to enjoy my cooking... Heehee, thinking about it now, you've pretty much already made that dream a reality. Say \"ahh,\" Commander. I'm going to feed you~",
	main = "Our minds tend to wander when we're bored, don't they? Confusingly, it can be easier to focus when you have something to do.|Hesitation can mean death for those who make decisions. Still, the fact remains that we're all tied down by our own emotions.|Are you tired? Ah, then please hold on just a minute. I'll make you something quick to eat.",
	touch = "You want a hug? Um... There? Ah, sorry, I squeezed too tight...",
	voice_key_2 = -1,
	mission_complete = "A mission has been completed. Way... Way to go, Commander~",
	battle = "Mgh... I can't afford to get distracted, not now...!",
	id = 9703010,
	gift_dislike = "",
	gift_prefer = "Thank you very much. It's nice to feel this warmth once in a while.",
	profile = "I'm heavy cruiser Trento. Please task me with whatever you may need, be it on the frontlines or backlines. Why am I here, you ask? Because I'm a shipgirl whose job it is to assist you, of course.",
	voice_key = 970301,
	headtouch = "",
	feeling2 = "You think I look ill? Ahah, I'm fine. I just had a somewhat unpleasant dream...",
	login = "I'm relieved that you're right on time. Do you want to review today's schedule before we start working?",
	detail = "Being with you puts my mind at ease. It scares off all the awful visions that haunt me... You have a strangely potent aura, Commander...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9703020] = {
	hp_warning = "Yes! Yes! Now you're doing it!",
	feeling3 = "\"Possessed by the Devil\"... That's merely an excuse for one's self-centered behavior. Say, have you ever used a trite phrase like that to lie to yourself, Commander?",
	mail = "You've received a new letter. Isn't it fun to look forward to the unknown?",
	expedition = "Commission completed. Shall we have a look at the rewards? You might be pleasantly surprised.",
	win_mvp = "There's no fun to be had in an effortless victory~",
	home = "Judging by your look, you didn't enjoy your last battle. Were your foes too feeble? Maybe the mission went too smoothly for your liking?",
	unlock = "You must be the Commander. I am the heavy cruiser Algérie. So, what pleasures can I experience here? I do hope you won't disappoint me. Heehee~",
	touch2 = "If pleasure cannot be rejected, why don't you just embrace it? Heehee♪",
	mission = "A mission? Why spend time on that when it could be spent on your own pleasure?",
	vote = "",
	drop_descrip = "You must be the Commander. I am the heavy cruiser Algérie. So, what pleasures can I experience here? I do hope you won't disappoint me. Heehee~",
	feeling4 = "From what I've noticed, you do know what pleasure is, but meaningless little things inhibit your drive to pursue it. Now, come to me... I will teach you the essence of human nature. Heehee♪",
	lose = "Chagrin, anger... I see, so this is the taste of defeat? How delicious. Heehee♪",
	feeling1 = "*sigh*, old-fashioned people just don't understand what true joy is. What a shame...",
	skill = "I never gave you permission to flee~",
	upgrade = "Whew. I needed to stretch my muscles a bit.",
	propose = "To tell you the truth, this is far from enjoyable; it brings me great pain. It's not the exchanging vows part that hurts, it's not knowing how long I have to wait for you. Heehee♪",
	feeling5 = "Ah, yes, you're a great and virtuous hero – you cannot be with a wicked devil. You need only ask, though, and I'll spoil you whenever you please. Nobody has the right to shame you for seeking just a moment of pleasure.",
	main = "Caring only about your own pleasure gets you labeled as \"selfish.\" To that, I say, name-calling is low-grade enjoyment.|You seem to be struggling. Need a hand? ...Heehee. I mean, wouldn't you offer to help if you saw a kitten in need?|Pain is a kind of pleasure. It doesn't matter whether you inflict it or receive it... Do you get what I mean? Heehee.",
	touch = "That look of yours when you're holding yourself back from acting on an urge – it's quite exciting.",
	voice_key_2 = -1,
	mission_complete = "Completing a mission is more satisfying than the rewards that follow.",
	battle = "Fighting, by itself, is enjoyable.",
	id = 9703020,
	gift_dislike = "",
	gift_prefer = "For me? Heheh, you're sweet.",
	profile = "I am heavy cruiser Algérie, and I live to enjoy. Enjoy what, you wonder? Heehee. If I had to say... to enjoy anything and everything.",
	voice_key = 970302,
	headtouch = "",
	feeling2 = "I enjoy fighting not just because slaying my foes is satisfying, but because fighting itself is fun. To really make them suffer, or make it quick and painless... I always let my whims decide what to do.",
	login = "What brings you here this late? Surely you've not wasted time elsehere?",
	detail = "The opposite of fun is not pain, but boredom. Knowing that, won't you fill this gaping void with something... enjoyable?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9703030] = {
	hp_warning = "No! This can't be the end!",
	feeling3 = "When I was out of hope, standing by that cliff's edge, someone came and pulled me back. Who? You already know, Commander.",
	mail = "There's a new letter for you. This one's a normal letter, so just treat it as such!",
	expedition = "Commission complete. Aren't you gonna go check on that?",
	win_mvp = "That's how strong I am! Remember that you can always rely on me, Commander!",
	home = "You're finally back, Commander! Your food hasn't gone cold just yet. Take a seat and find out what a skilled chef I am!",
	unlock = "Hey and good day, Commander. I am Foch, the Warlord. Heehee, the Warlord of what, you ask? That should be obvious – the Warlord of Hell! Hahaha! It's good to be serving you.",
	touch2 = "Commander, there's no going back if you take this any further!",
	mission = "You've got unfinished missions waiting for you, Commander!",
	vote = "拉票描述",
	drop_descrip = "Hey and good day, Commander. I am Foch, the Warlord. Heehee, the Warlord of what, you ask? That should be obvious – the Warlord of Hell! Hahaha! It's good to be serving you.",
	feeling4 = "They said I'd only sink deeper into hell if I didn't fight back. Threats like that don't work on me anymore, because I have you. Even if I will sink, I'll be sinking with you.",
	lose = "Oops... I think history is repeating itself...",
	feeling1 = "Mgh. Hmm... To stick you in a volcano, or throw you into a trench...",
	skill = "To the depths of hell with you!",
	upgrade = "Ahh, the fiery gale that blows over the lava.",
	propose = "Well... I'll admit, I'm getting butterflies in my stomach over this. Giddy or not, I'll still accept your ring! It's just like you said – nothing will get between us and our shared fate! Hahahaha!",
	feeling5 = "Commander, let's go on a pleasant trip today, you and I. Where? Ahaha! To hell, I'd say! And don't say no. So strong is our bond that cutting it would only make it regrow stronger. Right?",
	main = "It looks like your port is experiencing an everlasting interwar period... That's what people usually call \"peace\"? Hmm... Makes sense!|That pile of paperwork is a thousand times scarier than hell. It's no wonder you're always working late. I need to find a way to get your life back in balance...|There's no place in the whole universe where you can relax forever. The 8-hour work shift exists even in hell! Hahaha, you've got to agree that being alive is so much better.",
	touch = "Hm? You wanna talk? Sure, let's chat the day away.",
	voice_key_2 = -1,
	mission_complete = "Mission rewards have arrived. Come here and have a look!",
	battle = "Ahahaha! I've got an express ticket to hell for you!",
	id = 9703030,
	gift_dislike = "",
	gift_prefer = "Ooh, this looks fun! I like it! Thanks, Commander!",
	profile = "I'm Foch. Like I said when we first met, I'm the Warlord. I've seen it all, so don't be afraid to tell me about anything that keeps you up at night! I will fix all your problems one at a time!",
	voice_key = 970303,
	headtouch = "Hm? Is this some kind of greeting? My hair's gonna be ruffled if you keep doing that. Not that there's anything wrong with that!",
	feeling2 = "Commander, you haven't seen true hell until... No, I take that back. Your day-to-day schedule isn't much different from hell.",
	login = "Commander, you've got to process each and every one of these documents. Sheesh, you look like you've seen the devil... Don't fret – I'll help you out!",
	detail = "I've been thinking – as my Commander, what should I call you? The Supreme Ruler of Hell? The Overlord of Hell? Ahaha, don't look so tense! I'm not gonna call you that EVERY time we speak.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9703040] = {
	hp_warning = "Not so fast! I've not keeled over yet!",
	feeling3 = "Now that I think about it, me and this whip have been together for ages. If I ever kick the bucket, I want you to be its new owner. It's a bit long, but that makes it perfect for pointing at things on a map.",
	mail = "Got a letter for you here. Better open 'er up and read it right now.",
	expedition = "A commission's finished, eh? Ah, they brought back a real haul. That's what I like to see!",
	win_mvp = "You ain't seen nothing yet!",
	home = "Now THAT'S what I call a good battle. Go catch your breath now!",
	unlock = "You the Commander? Alright, say no more. Take me into battle and I guarantee ya won't be let down!",
	touch2 = "You've got a real big pair on ya... Now you're in for it!",
	mission = "If I can help ya on that new mission, just let me know.",
	vote = "拉票描述",
	drop_descrip = "You the Commander? Alright, say no more. Take me into battle and I guarantee ya won't be let down!",
	feeling4 = "I'm afraid... I used to not give a damn, but now... Hm? Oh, Commander. It's nothing. It just that it dawned on me that I've started fearing death. Yeah? ...Learn to value my life more, you say?",
	lose = "Fall back! I'll keep 'em busy!",
	feeling1 = "Do you seriously think this shit will fly? 'Cause it sure as hell won't!",
	skill = "Turn to ash and sink below the waves!",
	upgrade = "More power! I need more!",
	propose = "We're not general and soldier, you and I, we're lovers... and I can't fight like my heart yearns. You've done things to me... but it's fine. We'll keep on keeping on. You are my anchorage; my port to return to. Long as you're alive, I'll be around – 'til the world itself comes to an end.",
	feeling5 = "I've grown attached to life, and it's all your fault. Ya know... If I buy the farm before you do, you'll be all alone, and I can't stand the thought of that. I'll take care of myself – if only so you and I can be together just a while longer.",
	main = "War? War is never over. There's no issue between victory and you that a cannon shell cannot resolve! And even if there were, just fire one more!|As soon as ya set foot on the battlefield, there's no turning back. Never forget what you're fighting for, Commander.|Scars are a warrior's badges of honor. Being able to feel pain is proof that you're alive, Commander.",
	touch = "If ya wanna spar, I'm game. I'm not responsible if you get hurt, though.",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Fine job!",
	battle = "Follow my lead and blitz on through! Fire!",
	id = 9703040,
	gift_dislike = "",
	gift_prefer = "I'm surprised. You have great taste.",
	profile = "Just think of me as the Wichita you've always known! When ya have me in a battle, victory is a given and foes stand no chance! Now take me to the battlefield!",
	voice_key = 970304,
	headtouch = "This is how you reward your soldiers? I'll take it.",
	feeling2 = "My dreams? Don't care about 'em. The battlefield is my whole world. Anything beyond that, I try not to think about.",
	login = "You're back. Where're we going and who are we taking down today?",
	detail = "I didn't just stumble upon this power – I paid the due price to get it. Would be a big shame not to put it to good use, right?",
	couple_encourage = {
		{
			{
				1
			},
			1,
			" Let's get this battle started. I'll cover you!",
			3
		}
	}
}


_G.pg.base.ship_skin_words[9703050] = {
	hp_warning = "We're at a disadvantage... I need to think of an escape plan!",
	feeling3 = "Life here is good. It's obvious that those two are happy, too. Me? It's too early to tell, so...",
	mail = "You've got a new letter. Write a response ASAP.",
	expedition = "There being so many commissions means that we live in good times... Time to go review the rewards.",
	win_mvp = "In the name of the Admiral Hipper class, I will play a song to soothe your souls.",
	home = "No, nothing happened at the port while you were gone. Did you do your duty out there?",
	unlock = "I'm Admiral Hipper, lead ship of my class and sister to Eugen and Blücher. Got it memorized?",
	touch2 = "You're attracted to MY body? I really don't understand how...",
	mission = "I don't know how long it's been since headquarters sent me a mission...",
	vote = "",
	drop_descrip = "I'm Admiral Hipper, lead ship of my class and sister to Eugen and Blücher. Got it memorized?",
	feeling4 = "Sure, I don't need to cook for myself, so I get why you brought me to the canteen... but why on earth did you then take me to the movie theater, then an amusement park? ...What? Because you wanted to see me smile? Sh-shut up...",
	lose = "One defeat isn't the end of the world. We'll get them next time!",
	feeling1 = "It's a miracle in and of itself that the girls are living happily here. What more could you ask for...",
	skill = "This is proof the Admiral Hipper class still lives!",
	upgrade = "Thanks. I'll put your valuable resources to good use.",
	propose = "I love you. I told you about just coming out and saying what's on your mind, and so that's what I just did! I've got things I wanna say, too! So what do you have to say? ...That you'll always look after me? Seriously? Yeah, that goes without saying!",
	feeling5 = "What did you say? You LOVE me?! Alright, I DID say you should just say what's on your mind... but THIS?! You've got to give me time to mentally prepare myself! Idiot!",
	main = "Schweinshaxe? I suppose it's been a while since I had it. Thanks... Want to eat it with me?|What are you doing? ...What? Trying to make me smile by making faces? You're a real idiot...|When something's on your mind, just come out and say it. When I realized I had things I wanted to say, it was all too late.",
	touch = "M-my scarf is the one thing that's off-limits. Not even you get to touch it.",
	voice_key_2 = -1,
	mission_complete = "The mission has been completed and reported. Why are you just standing there, holding the list? ...To show off? Are you dumb or what?",
	battle = "Behold! The Admiral Hipper class still fights!",
	id = 9703050,
	gift_dislike = "",
	gift_prefer = "Is this... a present? Th-thank you... I like it.",
	profile = "I'm the lead ship of the Admiral Hipper class. My name isn't that important – what you SHOULD remember is my class as a whole. Honor my sisters who once fought in these seas... just as we do now.",
	voice_key = 970305,
	headtouch = "Whatever. Do what you want.",
	feeling2 = "Mind if I borrow the repair shop, Commander? ...Get help from Akashi and Yuubari? Don't want it. It's my gear, so I should be the one to maintain it.",
	login = "You're here. Time to get to work?",
	detail = "Why are you being all sneaky? If you're gonna look, don't be a coward about it.",
	couple_encourage = {
		{
			{
				970206
			},
			1,
			"Are you keeping them at arm's length? Well, I understand.",
			0
		},
		{
			{
				40601
			},
			1,
			"Oh... So that's what became of you...",
			0
		},
		{
			{
				70301
			},
			1,
			"The Northern Parliament? Eh, whatever.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[9703060] = {
	hp_warning = "I WILL complete my mission!",
	feeling3 = "Did you organize the files for me? Don't bother trying to refute it. I know your habits very well by now... Thank you.",
	mail = "Commander, you have unread mail.",
	expedition = "I've finished inspecting the commissioned goods. The list is on your desk – do not forget it.",
	win_mvp = "Mission completed. League Knight Bolzano will hereby return to her original post.",
	home = "Welcome back, Commander. You brought me a gift...? Thank you. But do not do this again – you'll find that nothing good comes from being a friend of mine.",
	unlock = "I am Bolzano, a knight of the Sardegnia League. Commander, I await my next task.",
	touch2 = "I'm not entertained, if that was your intent.",
	mission = "You still haven't completed your missions. Don't expect my help – oh, it's an order? Then leave it all to me. I mustn't burden you, after all.",
	vote = "",
	drop_descrip = "I am Bolzano, a knight of the Sardegnia League. Commander, I await my next task.",
	feeling4 = "I'm not used to the feeling of someone being near me, but for you... I will do my best.",
	lose = "Does this mean... our fate is unavoidable?",
	feeling1 = "I can do this myself. Do not follow me.",
	skill = "Sink to the deepest depths, cursed soul.",
	upgrade = "It... worked? That's new.",
	propose = "Are you really so set on being with me? You truly understand nothing... Fine. I won't push you away anymore. No matter what misfortune befalls us, I will protect you with all that I am.",
	feeling5 = "I don't mean to push you away. But being near me will bring misfortune to you. That's why I've always walked alone in the dark, wrapped in misfortune... I don't want you hurt.",
	main = "Commander, there's no need for you to keep trying to get closer to me. Simply give me my orders. No matter the mission, I will see it done.|...Commander, is this dessert meant to be a gift for me? I'm fine – oh, it's an order? Very well. Then I will partake.|The plan for the next mission is here... Yes, you've read it right. I will do it alone. It's hardly difficult.",
	touch = "You're sitting here? Then I'll go over there.",
	voice_key_2 = -1,
	mission_complete = "Mission complete. If you have no other orders, then I'll be leaving.",
	battle = "My mission is to seize victory. Don't hold me back.",
	id = 9703060,
	gift_dislike = "",
	gift_prefer = "Thank you.",
	profile = "I am the heavy cruiser Bolzano, a knight of the Sardegnia League. You want to know more about me? I don't think that's necessary.",
	voice_key = 970306,
	headtouch = "Stay away from me.",
	feeling2 = "You'd like to introduce me to the rest of the port? I have no need of friends, nor your special treatment.",
	login = "Let's skip the small talk. I've done my duty, and it's time for you to do yours. Take it seriously.",
	detail = "Hmm? Do you need me on the battlefield?",
	couple_encourage = {
		{
			{
				970507
			},
			1,
			" You're here, too? Then I'll leave half to you.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[9704010] = {
	hp_warning = "Pain... is nothing more than a catalyst for madness...",
	feeling3 = "You seem to be quite drawn to me. I'm not sure what about me would warrant your fancy, so I don't know if you're stubborn or just a simpleton.",
	mail = "Just a friendly reminder: you still have unopened mail.",
	expedition = "The commission rewards? Ahh, what an enviable logistics department you have.",
	win_mvp = "Indeed, it is wreckage and ruins that put my heart at ease.",
	home = "Rest is for the dead. I'll do the rest myself if you so desire.",
	unlock = "You're... the Commander, right? In other words, the one with the authority to control me. Though I have no interest in you as an individual, I will still obey your orders... At least for the time being.",
	touch2 = "Such a crass hobby... But whatever makes you happy.",
	mission = "Cumbersome paperwork will only hinder your ability to fight.",
	vote = "",
	drop_descrip = "You're... the Commander, right? In other words, the one with the authority to control me. Though I have no interest in you as an individual, I will still obey your orders... At least for the time being.",
	feeling4 = "You're commanding me... to take a break? Do you even know what you're asking me to do? ...Very well. I did say I'll obey your orders.",
	lose = "Withdraw? Haha... Ahahaha! ...It hasn't ended yet, so why are we to withdraw?",
	feeling1 = "These were the only \"commands\" you could come up with? What a joke.",
	skill = "Everything is as planned.",
	upgrade = "Now that my armament has been strengthened, the next step is... Ahahaha!",
	propose = "If you're prepared to go to these great lengths for me, then I shall accompany you to the very end. I'm becoming more and more curious – just how far will you be able to go by my side? ...Yes, I cannot allow you to leave until we've traversed the very bowels of hell. Are you ready?",
	feeling5 = "You are quite an interesting person, trying to treat me as an ordinary human and integrate me into life at this port. I suppose I ought to try saying \"thank you.\" ...I wonder if this is the first time I've uttered those words.",
	main = "Only with exacting precision can you eliminate your enemies in a single fatal blow, thus ending the battle quickly.|...Leave me to my own devices, and your job will be much smoother... Though it doesn't seem like you're interested.|It may take some time... until I am used to an ocean devoid of war.",
	touch = "What's wrong? Can't make up your mind?",
	voice_key_2 = -1,
	mission_complete = "Your duties end here. Mine, on the other hand, persist eternally...",
	battle = "To fight... is to fulfill this life's purpose.",
	id = 9704010,
	gift_dislike = "",
	gift_prefer = "Well then, I'll take this.",
	profile = "I am the Iron Blood battleship, Gneisenau. I've heard that you are an excellent commander, so surely you know how to operate a precise and efficient instrument of war?",
	voice_key = 970401,
	headtouch = "What... is the meaning of this?",
	feeling2 = "A machine's efficiency comes from its accuracy, lack of hesitation, and tirelessness. As ships, we must be the same.",
	login = "So you came after all. Not that it matters to me either way.",
	detail = "The more you suppress your emotions, the more rationally you can fight. Let the battlefield wash over you, and immerse yourself in the scent of steel.",
	couple_encourage = {
		{
			{
				40501
			},
			1,
			"Bismarck, I never thought I would fight by your side once more...",
			0
		}
	}
}


_G.pg.base.ship_skin_words[9704020] = {
	hp_warning = "I will make you suffer for your persistence!",
	feeling3 = "There must be some people here who strive to push their limits. Introduce me to them, would you?",
	mail = "Here, a letter for you. I've underlined the important parts of it.",
	expedition = "The commission team has come back. I'll send down a stand-in since we're both preoccupied here.",
	win_mvp = "Such is the inevitable fate of all raving shitheads who oppose me.",
	home = "We are most prone to carelessness after a hard-fought battle. Stay sharp, Commander.",
	unlock = "I'm Iron Blood battlecruiser Scharnhorst. I am keen to join forces with a Commander as talented as you. Don't let my expectations of you be misplaced.",
	touch2 = "You disgust me... Ugh!",
	mission = "Why do you need more people on this mission? You don't think I'm capable enough, huh?!",
	vote = "",
	drop_descrip = "I'm Iron Blood battlecruiser Scharnhorst. I am keen to join forces with a Commander as talented as you. Don't let my expectations of you be misplaced.",
	feeling4 = "I'm well used to life at this port by now. While I'm still pushing my limits as always, I do feel like I've started to... loosen up a bit.",
	lose = "This isn't over! I will NOT retreat!",
	feeling1 = "A weakling such as you isn't fit to command a fleet.",
	skill = "There is no compassion in war!",
	upgrade = "Time to assess my new strength with a cannon volley.",
	propose = "There's no guarantee I'll forever stay by your side. That said... I will lend you every ounce of my strength to realize your ideal world. I, Scharnhorst, will fight for you.",
	feeling5 = "What is this feeling of inner peace which I've lacked for so long...? What will happen when it goes away? ...You won't let it go anywhere? Usually I'd call that an empty promise, but when it's YOU making that promise... I must just believe it.",
	main = "Aircraft carrier shitbags... I hate to admit, but they outclass me when it comes to information and long-range warfare.|Wounds of the body heal in due time. Wounds of the mind... They don't often fade so easily.|The Ugly Sisters... Hahah. What an unforgettable nickname. The spite of your enemies is the most potent affirmation you can ask for.",
	touch = "Exhausted, you say? A break is just around the corner. Don't let up until then.",
	voice_key_2 = -1,
	mission_complete = "Good news – mission complete. I went ahead and claimed the rewards, too.",
	battle = "I've had enough of your bullshit. There'll be nothing left of you when I'm finished!",
	id = 9704020,
	gift_dislike = "",
	gift_prefer = "...Sure, I'll take it.",
	profile = "I'm Scharnhorst. Never back down, no matter what – that's my doctrine. I'll state it upfront: I'm headstrong, and might even defy your orders from time to time.",
	voice_key = 970402,
	headtouch = "Stop wasting your time on infantilizing me!",
	feeling2 = "I never flee the battlefield, but I know when to make concessions.",
	login = "Now that you're here, it's time to get cracking. Start by reading these documents.",
	detail = "My every scar is proof of a brush with Death survived.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9704030] = {
	hp_warning = "I'm only... getting started!",
	feeling3 = "When you get time to rest, take it – don't work yourself to death. You never know when there might come a day you'll never rest again.",
	mail = "You've got a letter. Isn't it wonderful having someone who cares about you? Remember to write back to them.",
	expedition = "The commission team is back. Don't forget to give those weary girls a pat on the back, Commander!",
	win_mvp = "Yeah! We won!",
	home = "Phew... Glad you made it back alive. You may think a safe return is business as usual, but I can never take it for granted.",
	unlock = "I'm Repulse, Renown-class battlecruiser. I've been through a lot... but that's in the past. Now, I'm a part of this port. Whenever you're in a pinch, come see me.",
	touch2 = "For your own sake, don't try anything funny.",
	mission = "New missions, eh? Wonder if any of them let me leverage all my experience...",
	vote = "",
	drop_descrip = "I'm Repulse, Renown-class battlecruiser. I've been through a lot... but that's in the past. Now, I'm a part of this port. Whenever you're in a pinch, come see me.",
	feeling4 = "You've not worn yourself out today, have you? Good. Shame these missions keep coming in, one after another... Guess it'll be a long while before the weight on your shoulders will finally come off.",
	lose = "We retreated before it was too late, securing the strength to fight another day... I hope.",
	feeling1 = "Don't lose all hope. While you've steered a bit off course, the fact remains that we're allies. So, I'll take it upon myself to lead you back in the right direction!",
	skill = "You're all under my protection!",
	upgrade = "I hope there'll come a day when I'll have no use of this rigging anymore...",
	propose = "I don't feel I've got much appeal, so the thought that you don't want me held me back so long. It takes bravery to pop the question, and I'll show the same bravery with my answer... Heehee, my answer's \"yes,\" obviously!",
	feeling5 = "Commander, you're my closest friend and most beloved person, and I hate to see your health suffer because of your workload. If you ever feel you've had enough of it all, just toss it out the window. I'll support you from start to finish.",
	main = "Whew... Oh, need something? You caught me getting lost in the scenery out the window. Sorry about that.|Life is short. We should be kind to our friends and treasure every moment we get with them.|A Royal Knight? Sure, I've heard a few fables about knights in my time... Anyway, stay focused – don't forget about your work.",
	touch = "Concerned about me? Don't be, I'm feeling great. Cheers.",
	voice_key_2 = -1,
	mission_complete = "That mission's done and dusted! That gives us some time to be with our friends.",
	battle = "Come on, we're sortieing – let's hear some excitement!",
	id = 9704030,
	gift_dislike = "",
	gift_prefer = "How did you figure out exactly what I'm into? Tell me what magic spell you used!",
	profile = "Repulse, Renown-class battlecruiser. Me and my sis have seen some things... That's a story for another day, though. I must say... this calm, peaceful port is ideal for a place to rest.",
	voice_key = 970403,
	headtouch = "",
	feeling2 = "Having chats with friends, taking a leisurely stroll, and napping on a bench when you get tired... that's what life at this peaceful port is all about. Here's hoping it always stays that way.",
	login = "Yup, you're as committed to your job as ever.",
	detail = "When seasoned heroes grow tired of fighting and start seeking peace of mind... will the world welcome them back?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9704040] = {
	hp_warning = "The dawn... is within our grasp!",
	feeling3 = "I used to believe I would continue fighting tirelessly alongside my friends until the end of time... When did I dare to start dreaming of peaceful days...?",
	mail = "Here's some mail, Commander. Why don't you take a short break to confirm the contents?",
	expedition = "Commander, the commissions have been completed. Let us thank our allies before tallying up the results.",
	win_mvp = "No matter how much the vicissitudes of war wear away at me, I shall not fall as long as my resolve holds strong!",
	home = "The sight of my allies returning home safely never fails to put a spring in my step.",
	unlock = "Salutations to you, Commander. I am battlecruiser Renown. I hope that this battle-worn blade can become your power.",
	touch2 = "This behaviour is inappropriate considering your position, Commander.",
	mission = "Is there a new mission? I'm not sure if I'll be of any assistance, but...",
	vote = "",
	drop_descrip = "Salutations to you, Commander. I am battlecruiser Renown. I hope that this battle-worn blade can become your power.",
	feeling4 = "This question may be inappropriate, but... Commander, have you ever considered life after retirement? To live life not as a warrior, but as a normal human... How magnificent would that be?",
	lose = "My apologies. I was unable to follow through with your orders...",
	feeling1 = "You're our leader, so it won't do for you to stay in this sorry state. I shall take responsibility for whipping you into shape and guiding you.",
	skill = "Don't let your guard down!",
	upgrade = "So this... is what's needed to maintain one's strength?",
	propose = "I can scarcely believe you prepared this many candles and even went through the trouble of shaping them into a heart... Of course I know how you feel. Even if you hadn't gone through all this trouble, my answer would still be... B-by the way, Commander, do I look too giddy right now...?",
	feeling5 = "Commander, I am eternally grateful to you for giving me the opportunity to share many precious moments with you. Our meeting, the time we've spent together... all of it is engraved in my heart. ...Ah, don't worry, I'm not planning on going anywhere! I'm sorry if I've caused any misunderstandings. And, umm... I will always stay by your side, Commander!",
	main = "...Oh, my apologies. I got sidetracked looking out the window... Repulse does the same thing from time to time? I see...|I've come to love this port. My heart feels lighter whenever I think about what I've become a part of since coming here.|You think the other Renown looks cute when she's serious about something...? Yes, I do think she would be happy to hear that from you. Allow me to give you my thanks on her behalf then— Oh...",
	touch = "Instead of worrying about me, you should be worrying about things more worth your time.",
	voice_key_2 = 9704043,
	mission_complete = "Now that you've completed your missions, you can take it easy for the time being.",
	battle = "Get into formation! It's time for us to attack!",
	id = 9704040,
	gift_dislike = "",
	gift_prefer = "I'll keep this as a souvenir.",
	profile = "I am battlecruiser Renown. I've been through countless missions and operations with Repulse at my side... I am very fortunate to have found a place to take refuge in this world.",
	voice_key = -1,
	headtouch = "",
	feeling2 = "I fear neither scars nor death.. but the heartbreak that war brings is far worse than both combined...",
	login = "Commander, your diligence will one day be duly rewarded.",
	detail = "\"I'm so tired,\" huh... Hmph. Those aren't words I can throw around so freely.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9704050] = {
	hp_warning = "It's not over yet! Come at me once more!",
	feeling3 = "\"With this blade I cleave the skies, returning justice to the world\" – how does this one sound? Do you think it's cool?",
	mail = "Psst. Commander, there's a letter for you. I left it on your desk.",
	expedition = "The commission team has returned. Come, let's inspect the rewards right away.",
	win_mvp = "I should've known not to expect much from them. Please find me a more worthwhile opponent for next time.",
	home = "Splendid work, Commander. Now, would you like to catch your breath with me at the training grounds?",
	unlock = "Battlecruiser Hiei, at your service. What shall we do next, Commander? I am ready to patrol or head into battle, so let us sortie at your earliest convenience.",
	touch2 = "You really dared to make a move, I see. I admire your forwardness.",
	mission = "New missions, I see. You should start on those as soon as you can.",
	vote = "",
	drop_descrip = "I am fast battleship Hiei – you may call me Hiei META if you like. Oh, I don't SEEM much like a META to you? I see... What is a META supposed to be like, then?",
	feeling4 = "Oh, go to a banquet? That sounds great! The lively atmosphere, the food, the music, the smiles... It so happens I have matching outfits for us both. Let's go together.",
	lose = "I got too careless... This was a massive defeat.",
	feeling1 = "Could you just tell me what you want from me?",
	skill = "Disappear like a cloud in the sky!",
	upgrade = "This strength lets me keep up even with the winds!",
	propose = "I will always, always honor my vow to be with you forever. Even when the darkest days befall us, I will grasp your hand, so please – grasp mine as well. Yes, together, we shall overcome everything!",
	feeling5 = "Ahh... What a relaxing day, perfect for going outside. Oh? Go out together, you say? I'd love to. The amusement park? Heehee, that's fine by me.",
	main = "While, yes, you need wisdom on the battlefield, sometimes you also need to be recklessly courageous. What we call \"miracles\" all begin with these two things.|A thousand-mile journey begins with a single step. You should take that first step without worrying about what could go wrong.|A banquet? Where will it be? Regardless, I'd love to attend a– You want ME to arrange it? That sounds like a lot of work, so I'm afraid I'll have to decline.",
	touch = "Ahh... The wind is nice and it's a perfect day for an outing. How about we go out, Commander?",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Impressive efficiency, Commander.",
	battle = "Begin combat! We shall face them with all we have!",
	id = 9704050,
	gift_dislike = "",
	gift_prefer = "For me? Really?! Thank you so much, Commander!",
	profile = "I am fast battleship Hiei – you may call me Hiei META if you like. Oh, I don't SEEM much like a META to you? I see... What is a META supposed to be like, then?",
	voice_key = 970405,
	headtouch = "My horns? Heehee. You may touch them all you like.",
	feeling2 = "When injustice I see, my blade I draw – the world I wander, sword at my hip. Hmm... I'm struggling to come up with a cool introduction. You're an educated person, Commander – do you have any ideas?",
	login = "What are your plans for today? ...Working in the office all day? Umm... Maybe we could change those plans right now?",
	detail = "Do you have any outdoor missions, Commander? If not, oh well – perhaps we could go for a walk together instead?",
	couple_encourage = {
		{
			{
				30402
			},
			1,
			" Host a banquet after this battle? Count me in!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[9704060] = {
	hp_warning = "Heheh... Such a bitter feeling...",
	feeling3 = "Still \"no\" even if I feed you directly? Hmm... I wonder if I can make a dessert so special that you cannot possibly refuse it...",
	mail = "Your mail? I organized it for you.",
	expedition = "Going to see the commission team? Bring them this dessert I made. It'll make it a real welcome-back celebration. Heheh.",
	win_mvp = "An outstanding outcome. You make me proud, Commander.",
	home = "Done fighting? Excellent work. You must be hungry, right? Why don't you try your luck with my freshly-baked desserts? Don't worry, the worst that'll happen is it'll make you laugh.",
	unlock = "I'm battlecruiser Dunkerque. Yes, I'm not purposefully giving you this tense look, it's just that I just returned from the battlefield. People call me things like \"the Dessert Demon.\" Would you like to know why they call me that, Commander?",
	touch2 = "So you crave me more than my delectable desserts... Heheh. Have it your way. Help yourself.",
	mission = "Quite a lot of missions have piled up... That's fine. I'll take care of all your problems with this sword.",
	vote = "",
	drop_descrip = "I'm battlecruiser Dunkerque. Yes, I'm not purposefully giving you this tense look, it's just that I just returned from the battlefield. People call me things like \"the Dessert Demon.\" Would you like to know why they call me that, Commander?",
	feeling4 = "Can I interest you in some freshly-made dessert? Rest assured, it's perfectly normal this time... Oh. You ate it without a second thought. Heheh. Well? Wasn't it delicious?",
	lose = "Heheh... I haven't felt this in so long... You've given me inspiration for a new dessert.",
	feeling1 = "Seems your feedback on my dessert-making won't be very useful...",
	skill = "Witness the power that leads to victory!",
	upgrade = "Power... Heheh. This feels nice!",
	propose = "My temptations don't affect you in the slightest, do they? Heehee... Maybe, just maybe I was born to stand side by side with you. Don't worry – I will always satisfy you with the highest sweetness, even if we end up in the depths of hell.",
	feeling5 = "Happiness is like a dessert with a complex taste. A hint of bitterness and sweetness, blended together in an inseparable union... Care to know what it's like to indulge in this wonderful sweetness with me?",
	main = "Why do I fight? To protect the world's hope and all things that are beautiful, of course. I don't want my painstakingly-made desserts to be ruined by some short-tempered buffoon.|I've fought in countless nerve-racking battles to procure ingredients for my desserts. If you're curious, I could tell you about them sometime.|Even a small dessert can stir a person's heart... Don't you think they're like temptations from the devil, Commander?",
	touch = "Is it my time to sortie? Or do you finally feel like eating my special dessert?",
	voice_key_2 = -1,
	mission_complete = "The mission rewards are already here, if you're wondering. Are you coming to claim them?",
	battle = "Shoot! I set the oven to the wrong time! You, get out of my way!",
	id = 9704060,
	gift_dislike = "",
	gift_prefer = "I can sense the feelings you put into this. As thanks... would you like some sweets?",
	profile = "I'm Dunkerque, \"the Dessert Demon.\" It's a pleasure, Commander. While you're here, why not taste this newest dessert of mine? ...Hey! Come back!",
	voice_key = 970406,
	headtouch = "Feels nice and silky, doesn't it? ...Hm? Like a chocolate fountain, you say? Heheh... Let me guess – you're hungry, aren't you?",
	feeling2 = "I have some mouthwatering dessert. Want a taste? ...Aww, you don't? You're letting a rare experience slip by.",
	login = "Welcome back, Commander. Care for something sweet to shake off the grogginess? ...It tastes awfully sour? Heheh, it might be a little sour in the beginning, but you should taste the sweetness soon. Wouldn't you agree this woke you up well?",
	detail = "Open your mouth, Commander. Hm? It's just a regular chocolate donut. See? Delicious, no? Then how about trying this not-so-regular dessert next, hm?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9705010] = {
	hp_warning = "I have already offered so many prayers... but is it still not enough...?",
	feeling3 = "Are you... concerned about me, Commander? You have no reason to be. I pray to the gods each day so that they bestow us all with their blessings and protection.",
	mail = "You've received a letter, Commander. I urge you to read it at the earliest convenience.",
	expedition = "You command a whole fleet of shipgirls who'll fight with all their might for you, Commander... Please, do cherish them.",
	win_mvp = "May you slumber eternally and find solace, far from the turmoil of the sea...",
	home = "You cannot let your duty come before sleep, lest it ultimately consume you, Commander. Please, care for your own well-being.",
	unlock = "I am battleship Fusou. I have come to bring peace to this world's tormented souls. Commander, do you seek blessings... or redemption?",
	touch2 = "Commander...? Has something strange possessed you?",
	mission = "A mission, you say? I shall pray for the fulfillment of your wishes, no matter how small.",
	vote = "",
	drop_descrip = "I am battleship Fusou. I have come to bring peace to this world's tormented souls. Commander, do you seek blessings... or redemption?",
	feeling4 = "I've seen far too many lost souls stricken with grief and remorse. Commander, when one day you look back upon your whole life, I want you to be able to smile, and say your life was a good one.",
	lose = "This curse cannot be lifted... Then so be it.",
	feeling1 = "There is nothing more I can do for you at this point, Commander...",
	skill = "Slumber eternally.",
	upgrade = "So many catastrophe-stricken souls still await their salvation.",
	propose = "If this is what you desire... then I shall accept. I know not whether this ritual will ultimately bring us blessings or misfortune, but I will continue praying for your happiness, Commander.",
	feeling5 = "Before I met you and everyone else here, all I could do was pray. I had lost all motivation to sing hymns or even lead lost souls to the light. But now, seeing all your smiles, I feel I've... rediscovered my purpose in life.",
	main = "Commander, do you ever wish you could return home? Do you have anyone in your heart who you are unable to let go of?|Until we have finished our respective duties... May we not pry excessively into each others' affairs.|I will keep praying to the gods, for as long as it takes, until the curse placed on Yamashiro and me can be permanently lifted.",
	touch = "I pray for you, Commander, and hope that the gods are listening.",
	voice_key_2 = -1,
	mission_complete = "A mission has been completed. The gods have heard our prayers.",
	battle = "Is this the only way to cleanse their impurities? Then so be it.",
	id = 9705010,
	gift_dislike = "",
	gift_prefer = "If that is your wish, Commander, then I shall accept it.",
	profile = "The missteps and misfortunes of the past are now all but forgotten phantoms... Only by guiding these drifting souls towards the light can I accomplish my mission.",
	voice_key = 970501,
	headtouch = "",
	feeling2 = "How may I be of use to you, Commander?",
	login = "Commander, I have been waiting for you.",
	detail = "Conflict throws all souls into chaos... I pray the gods may guide them to peace...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9705020] = {
	hp_warning = "Aww, just my luck...",
	feeling3 = "Why does at least one girl always call it quits partway through our training? And why do you always stick up for the quitters, Milord? The whole fleet will stagnate if people keep dropping out...",
	mail = "Milord, I suggest you read your new mail when you have the time.",
	expedition = "Taking on commissions is a form of training. Milord, please mix up your commission rosters so everyone gets a turn!",
	win_mvp = "With enough rigorous training, victory becomes almost a certainty. Isn't that right, Milord?",
	home = "Trai-ning♪ Trai-ning♪ Let me think about what I'm gonna drill into your head today~♪",
	unlock = "Are you this fleet's Commander, Milord? I see. You have great potential, but your skills need some refinement. I wonder what's the best way to train you... You'll see soon enough – stay alert until then!",
	touch2 = "Milord... Fondling me without warning is a punitive deed. The punishment is quite severe, I'll say.",
	mission = "New missions have come in. Knowing you, you'll breeze through them!",
	vote = "",
	drop_descrip = "Are you this fleet's Commander, Milord? I see. You have great potential, but your skills need some refinement. I wonder what's the best way to train you... You'll see soon enough – stay alert until then!",
	feeling4 = "I'll admit, I've been too strict with those girls... No, no, please don't say that. I understand why you feel that way. Those girls can stop if they wish, but your training, Milord, will stay as rigorous as ever!",
	lose = "What went wrong? Please don't tell me one of you wasn't even trying...",
	feeling1 = "I know you can hear me, Milord. Come out of hiding and own up to your mistakes like a decent person!",
	skill = "Keep going, don't let up already!",
	upgrade = "I'm afraid this isn't nearly enough power. I need more...",
	propose = "Is this... proof of your adoration, Milord? Oh, I feel truly blessed! Henceforth, please allow me to assist by taking on more and more work, or anything else you want done! I promise I'll be of great use!",
	feeling5 = "Astounding, Milord! You've seen through your most rigorous training yet! With someone like you, maybe my bad luck won't be such a... N-no, I didn't say anything! Anyway, the next session will be arduous – please give it your all!",
	main = "You mustn't let your mind wander while on the clock, Milord. Also, I've brought new paperwork for you!|Life is awfully laid-back at this port... Your girls will never grow into fine soldiers in this environment!|Oh no! The vase! ...Phew! That was a close one... Through my training, I've developed the reflexes to react quickly to imminent mishaps like this!",
	touch = "Does anyone here wish to become stronger? Step forth and let me train you!",
	voice_key_2 = -1,
	mission_complete = "Oh, you've completed a mission? Then you should get yourself a cup of tea and enjoy a break!",
	battle = "Show them the fruits of your training~ Hehehe~",
	id = 9705020,
	gift_dislike = "",
	gift_prefer = "Thank you for the gift, Milord! That being said, you mustn't let your mind wander!",
	profile = "I'm battleship Yamashiro, Fusou's sister. I've learned a lot through my training, and I'd happily impart that knowledge to you. Would you like to learn, Milord?",
	voice_key = 970502,
	headtouch = "",
	feeling2 = "Do you wish to strengthen your fleet, Milord? Then allow me to be of service! I know the way to draw out latent potential!",
	login = "I've sorted your documents and made you green tea. Strap in, Milord – it's going to be a long day!",
	detail = "You look bored, Milord. Was your training perhaps too easy?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9705030] = {
	hp_warning = "No! At this rate, I...",
	feeling3 = "You don't have horrible dreams when you're around me? Really? Um, it's not that I don't believe you, but...",
	mail = "Commander, there's a letter addressed to you... I'll go ahead and leave it on your desk.",
	expedition = "The commission team has returned. Go welcome them together? Never mind, I'll just be a hindrance anyway....",
	win_mvp = "Is victory... something worth celebrating?",
	home = "Um, while you were gone, all the lights in the office seem to have gone out again... I'm sorry for inconveniencing you once again.",
	unlock = "I am Arizona... This may be improper of me, but is it really alright for me to stay here? ...Very well, Commander. If that is what you've decided...",
	touch2 = "Is this... some kind of punishment?",
	mission = "Do you still have missions left? I'll try to help out in whatever way I can...",
	vote = "",
	drop_descrip = "I am Arizona... This may be improper of me, but is it really alright for me to stay here? ...Very well, Commander. If that is what you've decided...",
	feeling4 = "Peace of mind, and comfort... When I am by your side, Commander, those feelings seem to be slowly coming back to me... But, I'm scared of losing this happiness again...",
	lose = "If only I could do it all over again...",
	feeling1 = "You should stay away from me after all. Otherwise, it'll only end up with your friends getting hurt...",
	skill = "Let it all end!",
	upgrade = "I hope this will make a difference...",
	propose = "You're willing to always stay by my side and watch over me? *sobs*... Oh, I'm so sorry... I just, can't stop the tears from flowing... Commander, I believe you. You are the only safe harbor for my heart...",
	feeling5 = "Commander, you who rescued me from the abyss of despair and suffering... You are my last hope. I'll strive to do even better. Someday, I'll show you that I can overcome these dark emotions! Until then... Commander, would you please wait for me?",
	main = "\"Arizona's Tears\"... Does that refer to me? Maybe I was seen in a moment when I could not control my emotions. I'm sorry...|It is said that staying around me for too long will afflict you with tragic dreams. Huh? You don't mind? I, I see...|Oh, what was that sound just now? Did something break again because of me?",
	touch = "S-sorry! If you touch me without warning, I... Huh? You're not hurt? Thank goodness...",
	voice_key_2 = -1,
	mission_complete = "We finished the missions without any major issues... Phew, I'm glad it went well.",
	battle = "I pray this is the correct decision...",
	id = 9705030,
	gift_dislike = "",
	gift_prefer = "Oh, this, um... Thank you very much...",
	profile = "If there are parallel worlds out there, would \"I\" exist in them as well? If that's the case... I pray that I could have met you earlier, and spend a life free from tears...",
	voice_key = 970503,
	headtouch = "",
	feeling2 = "Would you mind keeping a safe distance from me? Oh, no, I'm not trying to push you away. \"Our\" Vestal warned that something terrible will happen if you don't...",
	login = "Welcome back. When you are here, Commander, the office does not seem as bleak.",
	detail = "If given the chance, I'd like to do it all over again... But even if that were possible, wouldn't the same things just play out again? What do you think, Commander?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9705040] = {
	hp_warning = "This isn't funny! Your queen does not approve of this!",
	feeling3 = "Are you still struggling to swear your fealty? Hah, your queen understands that the most talented folk fashion themselves leaders rather than followers. Do your job as you wish, but we expect your aid when it is needed.",
	mail = "Mail for you, hmm? What's so wrong with us asking what it says?! Of course, we do mean to respect your privacy.",
	expedition = "Servant, tend to the girls who just returned from their commission.",
	win_mvp = "Hmph. Did you think such foes stood a chance at stopping us?",
	home = "Finally returned? Good. We order you to rest. You may not continue working until your queen says you may! Understood?",
	unlock = "So you are the Commander? Very well. From this point forth, you will use your courage and intellect for our purposes! ...We don't have all day, now. You are our servant, so this won't go anywhere until you swear your fealty.",
	touch2 = "Pervert! Shameless lecher! Servants who don't know their place ought to be beheaded!",
	mission = "Missions? See them done, and done well. We will not tolerate you shaming our name.",
	vote = "",
	drop_descrip = "So you are the Commander? Very well. From this point forth, you will use your courage and intellect for our purposes! ...We don't have all day, now. You are our servant, so this won't go anywhere until you swear your fealty.",
	feeling4 = "Hm? Are you surprised that we would come here? Is it wrong for a queen to worry about her servants? Actually, why aren't you worried about us?! ...N-Not to say that's all there is to it...",
	lose = "All forces, retreat! We will not permit any unapproved sacrifices!",
	feeling1 = "It's fine. Consider this our own mistake for not being more selective. Go and do what you want; you may no longer be our servant.",
	skill = "Consider this a gift from your queen!",
	upgrade = "It is good to see that you pay adequate attention to us.",
	propose = "Must we still tell you what needs to be done?! Take our hand and swear that you will never betray us! ...Hmph, you belong to your queen now, so you are no longer permitted to shoulder every burden on your own! If you try to escape us, you'll be the subject of our ire forevermore!",
	feeling5 = "Your work isn't bad, but you focus too much on working out minor trifles! In other words... Umm, focus yourself on other things! For example, erm... Your queen...",
	main = "If you wish to pray, pray to your queen instead of the empty sky! We will bless and protect you!|We will prove that charisma is more than just one's physical size... Nobody shall impugn our stature ever again!|A port full of harmony and beauty... Is this your desire, servant? ...Don't worry. We were just a little happy for you.",
	touch = "You are a fearless one, laying hands on our body without express permission!",
	voice_key_2 = -1,
	mission_complete = "Mission rewards? We have no interest in such trifles. You take them, servant.",
	battle = "What a grand welcome. Do they mean to roll out the red carpet for us?",
	id = 9705040,
	gift_dislike = "",
	gift_prefer = "Excellent work. Now that's what I call a faithful servant.",
	profile = "We are the super-dreadnaught, Queen Elizabeth. We welcome any who wish to become our subject. Member of the Royal Navy or otherwise, we protect all those who follow us! Come, Servant; if you have any questions, ask now before our mood changes!",
	voice_key = 970504,
	headtouch = "Servant, do you not find your actions extremely rude?",
	feeling2 = "Pretty yet empty words will not be proof enough that we have done our job as queen. Servant, if you have any doubts about us, we will ascertain and rectify them.",
	login = "What took you so long, servant? Are you not aware that you are making us wait?",
	detail = "What's the matter? Are you in such awe that you cannot utter so much as a word? Hmph... Servant, if you're thinking of anything rude, you will pay dearly!",
	couple_encourage = {
		{
			{
				20101,
