_G.pg.base.ship_skin_words[9705050] = {
	hp_warning = "Such fierce resistance from these physical entities...",
	feeling3 = "One can interpret \"powerful\" to mean, \"Having the strength to protect what you cherish.\" Yes, it's fair to say you would need extraordinary strength to protect the weak.",
	mail = "There is a letter for you. The way people communicate in the physical world is fascinating.",
	expedition = "Commission complete. Do you need \"me\" to go and receive the team?",
	win_mvp = "They've all been destroyed...",
	home = "Welcome back, Commander. \"I\" appreciate all your hard work.",
	unlock = "On behalf of all Rodneys, greetings... You must understand, \"I\" am a physical representation of the concept of \"Rodney.\" \"I\" am no more than that...",
	touch2 = "This gesture fascinates both \"me\" and Rodney as a whole... Please continue.",
	mission = "Your missions await your attention.",
	vote = "拉票描述",
	drop_descrip = "On behalf of all Rodneys, greetings... You must understand, \"I\" am a physical representation of the concept of \"Rodney.\" \"I\" am no more than that...",
	feeling4 = "You need strength to protect what you cherish... \"I\" wish to protect you, Commander, and therefore, don't you fit the definition of something \"I\" cherish? \"I\" – \"we\" – want to find the answer to that question.",
	lose = "You may have defeated \"me,\" but you haven't defeated Rodney.",
	feeling1 = "The path \"I\" walk for eternity is a lonesome one. What about yours? Is it the same?",
	skill = "Disappear.",
	upgrade = "You've made \"me\" stronger? As far as the concept of Rodney is concerned, that was a meaningless effort.",
	propose = "Do you see \"me\" as someone you cherish, Commander? Then you must become stronger. Protecting \"me\" will take an inordinate amount of... No, even should you be vanquished, \"I\" will always be with you. Forever, until the end of time.",
	feeling5 = "Commander, \"I\" now have both the strength to protect what \"I\" hold dear and the time to do so into perpetuity. Therefore, \"I\" may be interpreted as \"powerful,\" right?",
	main = "\"Powerful\"... Yes, that is what people say about \"me.\" \"We\" take that as evidence of \"our\" strength, as meaningless as it may be.|Time is a difficult concept for Rodney as a collective to understand. Still, it must be a very important thing – right, Commander?|What to have for supper? Anything will do... Actually, anything but Royal cuisine, please.",
	touch = "This is an act of closeness. Is \"my\" interpretation correct?",
	voice_key_2 = -1,
	mission_complete = "\"I\" have retrieved your physical rewards for you.",
	battle = "This is it...",
	id = 9705050,
	gift_dislike = "",
	gift_prefer = "I\" am very fond of this gift. Yes...",
	profile = "\"Rodney\" is an amalgamation that exists in a higher dimension, even if \"we\" take human form in different branches. As for \"me\"... Yes, you're free to regard \"me\" as an incarnation of the concept of Rodney, specific to this branch.",
	voice_key = 970505,
	headtouch = "Um... \"I\" see...?",
	feeling2 = "\"Powerful\" is a word often used to describe \"me.\" But what does it mean? It's all the same as far as the concept of Rodney is concerned.",
	login = "\"I\" am listening. Let \"me\" take care of all matters of the physical world.",
	detail = "Tomorrow's programme? \"I\" haven't given it any thought. The flow of time holds no significance for Rodney as a concept, you see.",
	couple_encourage = {
		{
			{
				970207
			},
			1,
			"Your concept... isn't the right one?",
			0
		},
		{
			{
				20501
			},
			1,
			"No matter the time or place, you will always be \"our\" queen.",
			0
		},
		{
			{
				970504
			},
			1,
			"It's an honour to fight by your side, Your Majesty.",
			0
		},
		{
			{
				20503
			},
			1,
			"\"I\" shall protect you, \"my\" sister.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[9705060] = {
	hp_warning = "I shall not fall... I shall not fall!",
	feeling3 = "I cannot grind my existence away on the front lines for perpetuity? And why do you say this? What would you do if your friends were hurt in the absence of my protection? You want me to trust you? Hmm... Well, let's see. It all depends on how you lead.",
	mail = "Commander, I have collected the mail addressed to you. Please do not neglect to read them over. You are not permitted to betray your companions' expectations.",
	expedition = "Commission complete... Indeed, let us go together and greet our friends.",
	win_mvp = "As flowers bloom, so too must they wither. You are no exception.",
	home = "You have done well. For that, is there some reward you would like? Do not be shy and speak your mind.",
	unlock = "I am Nagato, Guardian Fox of the \"Sakura Empire\". Tell me, why have you summoned me? For power? Or for a wish you would like to have granted?",
	touch2 = "Are you aware of the presumptuousness of your conduct?",
	mission = "Commander, the mission documentation is complete. The rest is up to you.",
	vote = "",
	drop_descrip = "I am Nagato, Guardian Fox of the \"Sakura Empire\". Tell me, why have you summoned me? For power? Or for a wish you would like to have granted?",
	feeling4 = "Before I realized it, I had already grown accustomed to having you at my side. I find it amusing that you neither fear nor worship me... But, do you truly have no desires? Should you be so inclined, I can make any wish of yours come true. Why not give it a try?",
	lose = "As moon waxes and wanes, so too do the tides of fortune ebb and flow. This is not the end!",
	feeling1 = "...So be it. Do as you please.",
	skill = "O thundering fox, prance betwixt the spirit realms!",
	upgrade = "Power is what I desire – the greater, the better.",
	propose = "Indeed... Your wish was well within my expectations, as the natural progression of the cosmos. But, I wonder if you truly understand the meaning of this wish... Though, I will not allow you to retract your words even if you say you don't understand. I have already accepted you; and just as flowers are short-lived, so too is the brevity of a maiden's spring. You've already come this far, so why space out now? Come, and make me yours.",
	feeling5 = "First you ask me to go flower-viewing with you, then you invite me to gaze at the moon... You're plotting something, aren't you? You're trying to use your own \"wishes\" as a pretense to get me to open up. Listen well – I am aware of your tricks. You have one last wish to make, so think carefully about what you want.",
	main = "Commander, the cherry blossoms at the port are... truly beautiful.|Whether everyone worships me or fears me matters not, as long as they are safe.|I possess a vast power. Feel free to turn to me should you ever be in need.",
	touch = "Do you have a wish? If so, come forth and speak your mind.",
	voice_key_2 = -1,
	mission_complete = "Mission complete... Yes, please come with me to inspect the rewards.",
	battle = "Only death awaits those who stand in my path.",
	id = 9705060,
	gift_dislike = "",
	gift_prefer = "Hrm... Most commendable. I... am truly glad.",
	profile = "I am Nagato. Nagato of the \"Sakura Empire\". As flowers bloom and wither, so too do people come and go... That is all you need to know. Now, enough sitting around. Go and do what you need to do.",
	voice_key = 970506,
	headtouch = "This sensation... is most sublime.",
	feeling2 = "Never again shall I sacrifice one for the many. I wield this power so that I will never be confronted with such a choice ever again. Through this power, I shall bring salvation to all.",
	login = "You have arrived in a timely manner. Most commendable.",
	detail = "The future you pursue is one and the same with my destination. I shall deliver you to the \"other side\". Fear not – I possess the requisite power.",
	couple_encourage = {
		{
			{
