_G.pg.base.ship_skin_words[9705070] = {
	hp_warning = "The die is cast... All that remains is to advance!",
	feeling3 = "I have dreamed many times of my day of triumph, walking through the triumphal arches whilst flowers rain and the people sing praises to my great achievements. In the end, though, that was naught by an empty dream.",
	mail = "Letters are time-sensitive things. Don't forget to read yours.",
	expedition = "The commission team has returned. Let us remember the importance of logistics and bid them a triumphant return together.",
	win_mvp = "Victory and glory always follow my path.",
	home = "The battlefield is more my element than this. Take me with you on your next sortie.",
	unlock = "I am Giulio Cesare, conqueror of the empire. Spare me the needless chatter. I have no desire to squander time on such things.",
	touch2 = "Good. This is how a conqueror such as you ought to act.",
	mission = "Do remember to tackle your missions.",
	vote = "",
	drop_descrip = "I am Giulio Cesare, conqueror of the empire. Spare me the needless chatter. I have no desire to squander time on such things.",
	feeling4 = "Whilst I can no longer remember my home, I have no doubt that it was a peaceful and prosperous place such as this. Keep it safe, Commander.",
	lose = "Send me additional legions, Commander.",
	feeling1 = "One day, I shall cross the Rubicon.",
	skill = "Veni, vidi, vici!",
	upgrade = "I will not stop here.",
	propose = "Wherever you belong is where I belong, my beloved. All those you seek to protect, I shall protect, too. And all your enemies are mine as well. Take my hand, Commander, and let us set off into this vast world full of uncertainties!",
	feeling5 = "A red carpet and a cannon salute? What is this about? ...My triumph? Thank you! Giulio Cesare, conqueror of the empire... has returned triumphantly!",
	main = "Commander, the patrol deployments around the port stand to be improved. May we discuss this?|Concentrating on aircraft and cannons alone isn't enough. In war, each and every soldier has value.|Orthodoxy rooster... Royal Navy lion? Heehee.",
	touch = "The endless sea, the vast sky – it all exists for me to conquer. Wouldn't you agree?",
	voice_key_2 = -1,
	mission_complete = "With greater fidelity comes higher efficiency. Excellent.",
	battle = "Begin the conquest!",
	id = 9705070,
	gift_dislike = "",
	gift_prefer = "This is not bad. Thanks.",
	profile = "I am Giulio Cesare, conqueror of the empire. I came, I saw, I conquered – and then, I will return home triumphantly... in that shining land of glory.",
	voice_key = 970507,
	headtouch = "While I do like the galeae my legionnaires wear, a naval cap is also satisfactory.",
	feeling2 = "You are extraordinarily talented as a leader, Commander. By working together, we can seize victory after victory and secure eternal glory.",
	login = "You've come? Then concentrate and get to work.",
	detail = "Hm? Are we beginning a new conquest?",
	couple_encourage = {
		{
			{
				60503
			},
			1,
			" I give you my respect, magnificent Roma.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[9705080] = {
	hp_warning = "It's okay. Just a scratch.",
	feeling3 = "Paying attention to your subordinates' health, both mental and physical, and giving individual care... This is something I could stand to learn from you.",
	mail = "Commander, I brought your mail. It's all just regular correspondence, so check it whenever you're free.",
	expedition = "You can't have booming business without smooth shipping routes. Good work, Commander.",
	win_mvp = "That was a well-earned victory. Heehee, good job, everyone!",
	home = "Commander, you look so tired. Take a break and let me take care of the mission postmortem review, okay?",
	unlock = "I'm Andrea Doria, of the Sardegnia League. Is this your port, Commander? I see... It's a lovely place. I think I'll like it here.",
	touch2 = "Heehee... I'm happy to indulge you as much as you want.",
	mission = "Commander, I just got word of new missions. Do you need any help?",
	vote = "",
	drop_descrip = "I'm Andrea Doria, of the Sardegnia League. Is this your port, Commander? I see... It's a lovely place. I think I'll like it here.",
	feeling4 = "You're warm and nostalgic like hot milk, Commander... I'd say I'm more like pure cocoa – rich and dark, but of unknowable depths. Heehee... Why don't we meet in the middle and enjoy a cup of hot chocolate?",
	lose = "This isn't good... All who are injured, retreat and get treated! Victory can wait another day!",
	feeling1 = "Commander, we need to speak about your inappropriate decision-making of late.",
	skill = "Good, good. Come even closer~",
	upgrade = "Well, this is... Heheh, not bad at all.",
	propose = "Then our oath is sworn. I will stay by your side forevermore... You're still curious about my story? Okay. I can reveal one of my hundred tales to you, my beloved Commander♪",
	feeling5 = "Do you want to know more about my past? About things not written in the history books? Hmm... Perhaps not yet. You're special to me, so I want to handle our relationship gently for the time being.",
	main = "Am I not that different from the Andrea Doria you know? Heehee, go on thinking that.|I do love hot milk, but pure cocoa is nice, too... Hmm. Talking with you has made me thirsty. Shall we get a drink, Commander?|Phew... I'm a little tired from this long stretch of work. Why don't we take a break?",
	touch = "If you're feeling down, a warm hug ought to lift your spirits.",
	voice_key_2 = -1,
	mission_complete = "Your missions are all done. Oh, sorry. I just wanted to ruffle your hair for a job well done... Your work is much appreciated.",
	battle = "To victory! Charge!",
	id = 9705080,
	gift_dislike = "",
