_G.pg.base.ship_skin_words[9705090] = {
	hp_warning = "Just a flesh wound! I'm protecting the Commander, no matter what!",
	feeling3 = "Shopping...? Sure, but I won't let my guard down. For your sake.",
	mail = "Mail for you. As usual, I made sure none of it was suspicious.",
	expedition = "Everyone made it home safe. Let's go see them. I gotta check and make sure they're not hurt.",
	win_mvp = "We won, but there's still room for improvement.",
	home = "Are you tired? Let me check you for wounds... Okay, I'm glad you're safe. I've got water and a first aid kit, so tell me if you need anything.",
	unlock = "Yo, young'un. I know you've got things under control here, but this port may not be peaceful forever. You should stay with me from now on! I'll keep you safe no matter what happens!",
	touch2 = "Hnh?! Phew... It's you. Say something next time, please. That's a vital area right there!",
	mission = "Commander, you still have missions left over. Let me help you knock 'em out. I'm prepared for any and all kinds of accidents.",
	vote = "",
	drop_descrip = "Yo, young'un. I know you've got things under control here, but this port may not be peaceful forever. You should stay with me from now on! I'll keep you safe no matter what happens!",
	feeling4 = "Sometimes, I wonder if I'm a little too stubborn... But when I see you safe and sound, I know it's for the best.",
	lose = "Tch, Commander, hurry and retreat! I'll hold them off!",
	feeling1 = "I thought you'd understand how I felt. Guess I was stupid for that.",
	skill = "Try again in a few thousand years!",
	upgrade = "Heh, that feels good! I'll use this power to protect you.",
	propose = "Have you prepared yourself? Giving me this means that you've accepted me as I am... I like that look in your eye. You've been raised well. I just need you to accept my one request in return – let me protect you for the rest of my days, Commander.",
	feeling5 = "I finally understand. The thing that scares me most isn't external threats – it's the thought that I might lose you. So I'm going to keep protecting you until you really trust me.",
	main = "You think I worry too much? Maybe so, but a moment's inattention could lead to calamity.|If you don't like me being around all the time, then I'll go patrol. Don't worry, Commander. I'll protect you AND the port.|Do the things you wanna do while you're still young! Leave no regrets!",
	touch = "Urk...! Oh, it's just you. I'm all for cuddles, but warn me first, okay? You might get hurt otherwise.",
	voice_key_2 = -1,
	mission_complete = "You've got rewards. I checked them all, so I can guarantee they're safe. ...Don't look at me like that. You can never be too careful.",
	battle = "Now this is a party. Let's set the enemy and the sea alight!",
	id = 9705090,
	gift_dislike = "",
	gift_prefer = "Oh? You have an eye for presents. Thanks!",
	profile = "Experiencing that disaster made me realize that preparation is the only thing that can save you from danger. If you believe in me, I'll use everything at my disposal to protect you.",
	voice_key = 970509,
	headtouch = "Heheh. What's up, young'un?",
	feeling2 = "It's better to keep a certain distance. That'll help me keep cool when it's time to protect you.",
	login = "Hold it! Let me scope this area out... Okay, safety confirmed. Hi there, Commander!",
	detail = "I know I'm overdoing it a little, but I'd rather be called worrisome than the alternative. You can't complain unless you're alive, get what I mean?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9705100] = {
	hp_warning = "Hmph... This is what war is all about! Come at me!",
	feeling3 = "When we fight together, it feels like the skies have cleared for the first time in so long. Is this what... trusting someone is like?",
	mail = "There's a letter for you, Comrade Commander. Battlefield intel changes with every moment – best to read it now.",
	expedition = "The commission team's brought home some crucial supplies. Excellent. Our front line will hold longer now.",
	win_mvp = "Victory's ours, but we still have a long way to go until a lasting peace! Don't get lazy!",
	home = "I salute your return, Comrade Commander. Time to review the battles you fought? I'd be happy to assist!",
	unlock = "I'm Gangut META. From now on, my will and firepower are yours to command. Let's seize victory with our own hands in this grand war, Comrade Commander!",
	touch2 = "Comrade Commander, I applaud your bold ambush. However... Getting me won't be that easy.",
	mission = "Comrade Commander, we've been sent our missions for today. We ought to start on them at once.",
	vote = "",
	drop_descrip = "I'm Gangut META. From now on, my will and firepower are yours to command. Let's seize victory with our own hands in this grand war, Comrade Commander!",
	feeling4 = "Comrade Commander, fighting by your side holds the same importance as achieving victory to me.",
	lose = "This was my mistake. All the blame lies with me.",
	feeling1 = "Impulsiveness and recklessness will be the bane of everything we protect. I want you to make sensible decisions, Comrade Commander.",
	skill = "Never waver! Hold your ground!",
	upgrade = "Good. This'll let me better protect this land.",
	propose = "I accept. In this age of war, an oath will make us both stronger. I raise this toast to you – my fellow soldier, my comrade, my support, and my dearest!",
	feeling5 = "You were right, Comrade Commander. Even if the greatest victory lies long ahead, it's still worth celebrating the smaller victories you earn along the way... Here. I've saved this vodka for a special occasion. Care to try some?",
	main = "Ahh... This is good booze! Come the day we win this grand war, we'll drink it until the sun rises!|Comrade Commander, even if the world were to end tomorrow, you should still complete the work you have today.|If you don't come to the front line, the front line will come to you. Comrade Commander, once we're done with this paperwork, let's head to the front and raise our allies' morale!",
	touch = "Something the matter, Comrade Commander? If you're bored, we can fight a mock battle to rouse your spirit.",
	voice_key_2 = -1,
	mission_complete = "Mission successfully completed. This result is the proof of our hard work.",
	battle = "Fight until your last breath for this land!",
	id = 9705100,
	gift_dislike = "",
	gift_prefer = "A practical present. Comrade Commander, you have my thanks!",
	profile = "I'm Gangut META. It's a blessing, Comrade Commander, to fight with someone who shares my conviction as you do. Let us join hands and carve out a brilliant future for these frozen seas!",
	voice_key = 970510,
	headtouch = "Pardon, Comrade Commander? Well, I guess this is fine on its own.",
	feeling2 = "Our strength grows through the bond that we share. Let us keep on pushing forward, Comrade Commander!",
	login = "Comrade Commander, my blood's boiling in anticipation for an exhilarating battle! Let's head out and fight somebody today!",
	detail = "I wasn't born with this power. It became mine by stumbling over and over and getting back up each time. This unbreakable will is what I believe in.",
	couple_encourage = {
		{
			{
				70303
			},
			1,
			" For the sake of our comrades further back, we mustn't fall!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[9706010] = {
	hp_warning = "Tis but a scratch...!",
	feeling3 = "...My eyepatch? Don't worry, it's no impediment in battle.",
	mail = "Here, Commander. Your mail.",
	expedition = "A commission's been completed? Let's see... Wow, that's a pretty good haul.",
	win_mvp = "Hehehe, that was a good fight. Let's just leave it at that.",
	home = "You've returned. Good, let's start planning for the next battle.",
	unlock = "Ahahahaha! The fact that you've chosen me means you clearly have a discerning eye. So, what now? Where's the enemy you need me to sink?",
	touch2 = "What are you trying to say? That I have no charm? ",
	mission = "We've received some missions. If any of them concern the Sirens, leave them to me.",
	vote = "",
	drop_descrip = "Ahahahaha! The fact that you've chosen me means you clearly have a discerning eye. So, what now? Where's the enemy you need me to sink?",
	feeling4 = "Your job is to lead our way, Commander. My job is to eliminate any obstacle that tries to stop us. Perfect, isn't it?",
	lose = "This is unacceptable! I'll crush you all next time!",
	feeling1 = "What a gutless Commander you are...",
	skill = "Ahahahaha! Die, die!",
	upgrade = "Got any targets I could wipe out for a warm-up?",
	propose = "Commander, you're making a promise to me...? Heh, ahahaha... Sorry, it's not that this doesn't make me happy, it's just... I don't know how I'm supposed to feel or respond... Right, I can just answer the way I'm used to: by defeating your enemies for you.",
	feeling5 = "Commander, just do whatever you'd like and go wherever you'd like. As long as I can be by your side and fight together with you, I don't need anything else.",
	main = "Junyou? ...I'm doing just fine. No need to worry about me.|The best defense is a good offense. Take them out before they can get to you. Don't you agree?|Doing paperwork dulls my blade, Commander. When's our next battle going to be?",
	touch = "What, got any new info on the Sirens?",
	voice_key_2 = -1,
	mission_complete = "All right, mission complete!",
	battle = "Yeah! Throw them into disarray!",
	id = 9706010,
	gift_dislike = "",
	gift_prefer = "How fascinating. I love it!",
	profile = "Name's Hiyou, aircraft carrier of the Hiyou-class. I'm considered a light aircraft carrier along with Junyou, but I don't mind if you treat me as you would a standard aircraft carrier. Don't worry, I won't let you down.",
	voice_key = 970601,
	headtouch = "Keep this up for a few more seconds, and I won't be able to guarantee your safety.",
	feeling2 = "Battles are simple. Just crush all of your enemies, and live to tell the tale.",
	login = "I can't sit still anymore! Commander, I'm all ready to head out!",
	detail = "I can't just sit on my ass all day! Commander, don't you have any information about where the Sirens will pop up next?!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9706020] = {
	hp_warning = "An approach this direct is bound to fail...!",
	feeling3 = "Commander... How do you feel about lifelong friends? Err, I mean, in the context of fictional stories... and things like that...",
	mail = "There's mail for you. Please check it as soon as you can.",
	expedition = "A commission has been completed. Do you mind if I go see them on your behalf...?",
	win_mvp = "One tiny little victory... won't be enough...",
	home = "Hello. Good to see you... back in one piece.",
	unlock = "I'm... Junyou. Please give me your orders... Commander.",
	touch2 = "Whuh?! I'm... I'm not...!",
	mission = "We should strive to complete our missions.",
	vote = "",
	drop_descrip = "I'm... Junyou. Please give me your orders... Commander.",
	feeling4 = "What if... Just speculating, of course, but... What if you and I had known each other since long ago...? Things would be a lot different to how are they now... wouldn't they?",
	lose = "Whatever comes next, I've made my peace...",
	feeling1 = "I'm a grown woman now. It's time to put my childhood behind...",
	skill = "Out of my way!",
	upgrade = "Thank you.",
	propose = "Thank you, Commander. This proves to me that our relationship is real – that it has ALWAYS been real – and not some figment of my imagination... I want to be with you, now and forever.",
	feeling5 = "We may not be genuine lifelong friends, but that doesn't matter anymore... We've been through so much that we've grown as close as best friends like you see in fiction! ...I mean, right?",
	main = "I see Hiyou hasn't changed... She still revels in war.|Focus on yourself. Focus... Ah, um, I'm meditating. Please leave me alone for a while...|These shikigami planes are my weapon of choice against the Sirens. Only I can control them. No one else may touch them... No one...",
	touch = "I don't understand what you want...",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Don't you think... we work astonishingly well together?",
	battle = "Here I come!",
	id = 9706020,
	gift_dislike = "",
	gift_prefer = "I-I appreciate the sentiment!",
	profile = "I'm not sure what you want to hear from me... but ask me about my past, and I'm afraid you'll be disappointed... Because I simply have no answers.",
	voice_key = 970602,
	headtouch = "Ahh... *blushes*",
	feeling2 = "Oh, uh... S-sorry, I didn't mean to stare... I'm just thinking about what-ifs and what-could-have-beens...",
	login = "You're back. Are you about to start working? I promise I won't be a nuisance.",
	detail = "How would you react... if I told you we've been lifelong friends, and... N-never mind. Please forget I said anything.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9706030] = {
	hp_warning = "I can't give up! Not yet!",
	feeling3 = "I was conducting a special mission. Then I was separated from my comrades, got caught in a strange place, and somehow ended up here... It's baffling that it's already been this long since then...",
	mail = "A letter addressed to you has come in. Read it sooner rather than later.",
	expedition = "The commission team has come back. Anything I can do to help them?",
	win_mvp = "That went well. Commander, your next orders?",
	home = "How goes the battle, Commander? I'll provide reinforcements if needed.",
	unlock = "Aircraft carrier Princeton, reporting for duty. I'm afraid I'm still a bit disoriented... would you mind briefing me on the situation?",
	touch2 = "Pl-please stop with this improper behavior at once!",
	mission = "You still have missions to complete, Commander. Please don't forget about them.",
	vote = "",
	drop_descrip = "Aircraft carrier Princeton, reporting for duty. I'm afraid I'm still a bit disoriented... would you mind briefing me on the situation?",
	feeling4 = "While I only had a gut feeling that I could trust you, you've proven that feeling correct. That's why I urge you to use my strength in whichever way you see fit.",
	lose = "What a blunder... Forgive me, Commander.",
	feeling1 = "Is something the matter, Commander? Maybe you should take a leave of absence...",
	skill = "You won't be getting away!",
	upgrade = "Need to keep your gear up-to-date, after all.",
	propose = "D-does this mean you take me as your partner? I'd never guessed you view me so fondly... Now that I know, it's become all the more impossible to leave your side. Yes, I trust you with my everything. Let us march forward, together, to a new future!",
	feeling5 = "You can't do anything about a choice you regret, but as long as you stay on the right path, the past won't have been for nothing. And I believe in the path you've shown to me, Commander. I will keep walking it with you.",
	main = "\"S-Sara\"?! My respected predecessor's name should never be abbreviated! I will refer to her as Saratoga in full.|I was hoping I could update my gear so I may perform new duties on the battlefield.|It is a secretary's duty to aid her Commander. Is there any way I can be of assistance?",
	touch = "What is it? Do I look that dreary to you?",
	voice_key_2 = -1,
	mission_complete = "Mission complete. You could add the rewards to our stockpile.",
	battle = "Carrier Princeton, commencing operation!",
	id = 9706030,
	gift_dislike = "",
	gift_prefer = "Can I really have this? ...Thanks.",
	profile = "I'm Princeton, second ship of the Independence class, and I once fought alongside Antiochus. I don't know how I wound up here, and there's much regarding the circumstances I still don't understand... but, I knew from first glance that you're someone I can trust, Commander. That is why I follow your orders.",
	voice_key = 970603,
	headtouch = "",
	feeling2 = "Commander, if possible, could you tell me everything you know about me? I know I may be in no position to ask that of you, but some part of me just has to know...",
	login = "Your will is my command, as always, Commander.",
	detail = "\"Sirens\"... Is that what you call them? And they're our enemies... Forgive me if asking that is considered taboo. I just have so many questions...",
	couple_encourage = {
		{
			{
				10703
			},
			1,
			"I'm glad to be fighting with you again, Saratoga!",
			0
		},
		{
			{
				10723
			},
			1,
			"Uhh, well met, other me...?",
			0
		},
		{
			{
				970201
			},
			1,
			"What in the world happened while I was gone?",
			0
		},
		{
			{
				970701
			},
			1,
			"How did you become so skilled so quickly?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[9706040] = {
	hp_warning = "I will not cause the Commander distress!",
	feeling3 = "I knew it – I can be an excellent partner for you as long as I match your pace. How did I notice such small details, you wonder? Well, I'm afraid that's a secret.",
	mail = "There is a letter for you. If opening it feels like a chore, I will gladly do it for you. All you need to do is read it afterward.",
	expedition = "The commission team is returning one by one. I'm glad that they're unscathed.",
	win_mvp = "I can't wait to see the Commander...",
	home = "Exemplary work, Commander. I have made you food and a beverage and ran a bath for you. Before you get those, though... come and leap into my bosom♥",
	unlock = "Commander, I am Houshou. Henceforth, I will take veeery good care of you. Forget all your concerns and just let me handle everything. Heehee♥",
	touch2 = "I will always consent to anything you do to me♥",
	mission = "You have new missions, Commander. I have prepared a plan for you.",
	vote = "",
	drop_descrip = "Commander, I am Houshou. Henceforth, I will take veeery good care of you. Forget all your concerns and just let me handle everything. Heehee♥",
	feeling4 = "You think I'm beautiful just the way I am? Heehee, I never thought I'd hear a compliment of this magnitude from you. Then, please, look at me more – because I am always, ALWAYS looking at you.",
	lose = "I'm forced to admit that this defeat was my fault.",
	feeling1 = "It's alright, Commander. Despite everything that's happened, I will still hold you tightly.",
	skill = "Lend me your ears.",
	upgrade = "(Now I can stare more intently at the Commander...)",
	propose = "Dream... My dream? Oh, I remember now. My dream is to call you mine and always be together. Then again, hasn't that dream already come true, my sweetheart?",
	feeling5 = "How does it feel to be in my embrace? You're free to doze off, if you'd like. Don't worry about anything – I will take care of it for you.",
	main = "(The Commander's looks and movements, they're clear as crystal... I could observe them all day...)|Oh? It's like I know every little thing about you? Goodness, I've never heard such a wonderful compliment before.|Do you not need me, Commander? What things could I do better? Please, I must know! I promise I'll better myself!",
	touch = "Shall I play you a song, Commander?",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Kindly claim your rewards. Ah, I notified you at a good time? Heehee, that's because I'm always watching you.",
	battle = "Heehee. Disappear with grace.",
	id = 9706040,
	gift_dislike = "",
	gift_prefer = "This present is of utmost import to me... but my greatest treasure is no doubt your sentiments toward me, Commander.",
	profile = "Please, depend wholly on me like a child would♥ That is what I consider bliss.",
	voice_key = 970604,
	headtouch = "Now it's my turn♥",
	feeling2 = "You look rather worn out. Would you like to cuddle? Come and embrace me, clear your mind, and vent aaall your frustrations to me♥",
	login = "I've arranged your paperwork according to how you usually process it. Now, shall we get to work?",
	detail = "You feel like someone's watching you, even when no one's around? Oh dear. You're imagining things because you're overworked. If you're concerned about it, might I suggest relying on me more?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9706050] = {
	hp_warning = "I still... mustn't fall yet!",
	feeling3 = "Would the Commander notice if I swapped the order of these documents... Ack?! U-umm... I wasn't doing anything!",
	mail = "There's mail for you. Would you like me to sort it out?",
	expedition = "The commission team has returned. They're all working so efficiently... I'll have to redouble my efforts.",
	win_mvp = "I-I did it! It's all thanks to your leadership, Commander!",
	home = "Welcome back. I made a little drink for you, in the hopes that it'll alleviate some of your fatigue.",
	unlock = "Good day to you, Commander. I am Elbe of the Holy Unitas Empire, here to serve. I've never undertaken such a major duty before, so there's still much that I have to learn... I would be grateful for your guidance!",
	touch2 = "Hyah?! W-wait... This is all too sudden...",
	mission = "Commander, you have unfinished work. Umm... May I help you track your progress?",
	vote = "",
	drop_descrip = "Good day to you, Commander. I am Elbe of the Holy Unitas Empire, here to serve. I've never undertaken such a major duty before, so there's still much that I have to learn... I would be grateful for your guidance!",
	feeling4 = "I've been having some strange thoughts lately... For example, about how you'd react if I hid your favorite pen, or... A-actually, forget I said anything, please!",
	lose = "I'm so sorry... This is because of my incompetence. I must learn from this blunder.",
	feeling1 = "My abilities are insufficient to assist you. I'm sorry, Commander...",
	skill = "Stand back! I'll handle this!",
	upgrade = "I feel like I've grown a little... Thank you very much!",
	propose = "I-is it right... to give this to a bad girl like me? I'm unreliable, and I always get the urge to play pranks but lose my nerve right away... You still accept me, despite all that? ...Okay! I'll be right by your side forever, whether I'm doing my best or being as selfish as can be!",
	feeling5 = "Commander, I've made up my mind! Today, I'm going to be a bad girl and mix this unsigned document into the signed pile... Ah, I can't go through with it! That would only cause you trouble...",
	main = "I tried organizing last month's inventory today... I never knew comparing the estimates and real figures could be so complicated.|If I do anything wrong, you have to let me know! I want to become capable as soon as possible.|When I see how confident everyone else handles all manner of situations, I have to wonder if I'll ever be like them...",
	touch = "D-do you have instructions for me? Oh, you were just saying hello? Okaaay...",
	voice_key_2 = -1,
	mission_complete = "You've received mission rewards. I checked the quantity, and... I-I think it's correct!",
	battle = "I'll fight with all I have!",
	id = 9706050,
	gift_dislike = "",
	gift_prefer = "Is it really okay for me to have this? Thank you... I'll cherish it.",
	profile = "I am Elbe, working under the Holy Unitas Empire. I'm still in the process of learning, and my lack of experience will be evident... but I will approach every task earnestly. Commander, um... I look forward to working with you.",
	voice_key = 970605,
	headtouch = "Is this... proof that you acknowledge me?",
	feeling2 = "Say, Commander... Do you think I've come to rely on your guidance too much? As the head of my class, I have to be more independent...",
	login = "Commander, you're here. Here's a look at your schedule for today. I checked it for you, so there shouldn't be anything wrong... hopefully.",
	detail = "Commander, are you keeping an eye on my work? I-if you find any mistakes, you have to tell me, okay? I'll correct it immediately.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9707010] = {
	hp_warning = "",
	feeling3 = "On the battlefield, even a moment's hesitation can invite total destruction. Thinking about nothing other than how to defeat the enemy - that's my fighting style.",
	mail = "Please take this, Commander. It's your mail.",
	expedition = "It's good to count your blessings for the fortune of having plenty in the present moment. One day, it'll just be a wistful memory.",
	win_mvp = "Such a small victory is not worth celebrating...",
	home = "Don't worry about me. Simply stay focused on what it is you need to do.",
	unlock = "I'm getting all fired up! The name's Hiryuu, Hiryuu from the 2nd CarDiv. As a member of this fleet, I'll obey your orders. I do hope that you are qualified to lead us.",
	touch2 = "Hah?! ...Hmph! ...Next time, I'll assault you back with my blade.",
	mission = "These are all just trifling matters...",
	vote = "",
	drop_descrip = "I'm getting all fired up! The name's Hiryuu, Hiryuu from the 2nd CarDiv. As a member of this fleet, I'll obey your orders. I do hope that you are qualified to lead us.",
	feeling4 = "Would you keep challenging strong foes you have no chance of defeating? ...For the sake of those you wish to protect? Since it's you, I can see that you've given it plenty of thought. I support that sentiment.",
	lose = "Sister... I'm sorry...",
	feeling1 = "Leave me alone.",
	skill = "I'm all fired up!",
	upgrade = "...What a shame.",
	propose = "This is... the proof of your oath... I understand. If you will continue to value me as your blade, I will not turn my back to you. ...Though, my comparatively uncomely and unpleasant self will give you a hard time. Hehehe.",
	feeling5 = "This unwavering conviction, that if it's you, there will be a way... Hmm, I guess I've still got a naive side to me... It's nothing. Commander, as your blade, I will continue to pledge myself to your service.",
	main = "Enterprise? Whether as a rival or an ally, there's no doubt that she's an existence to be respected.|Hanafuda...? Now's not the time to be indulging in entertainment.|My usual training regimen isn't designed to show off my skills, but rather to protect my allies and defeat my enemies. Am I mistaken?",
	touch = "If you have something to say, just spit it out. If you fuss over it too much, you're just going to end up not saying anything.",
	voice_key_2 = -1,
	mission_complete = "Though they're all just trifling matters, they're still missions proper. I'll report back to you when I finish receiving the rewards.",
	battle = "Quick, let's get started! Come forth, my planes!",
	id = 9707010,
	gift_dislike = "",
	gift_prefer = "Since you went through the trouble of picking out this gift... I will accept it. You have my thanks.",
	profile = "I'm the aircraft carrier, Hiryuu. ...Right now, I am naught but a single soldier. That's all you need to know about me.",
	voice_key = 970701,
	headtouch = "",
	feeling2 = "Right now, I'm merely a soldier. I simply follow your directives, and that's all there is to it.",
	login = "Guide my blade. Where do my enemies lie?",
	detail = "I'd rather you pay attention to the others. ...If you're going to keep idling around here...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9707020] = {
	hp_warning = "I will not be defeated!",
	feeling3 = "A ship who's lost her way is fated to go under. The same is true for people. Do you have the strength to keep yourself on the right course, Commander?",
	mail = "You've received a new letter? Best to read it now, then. Do not live in ignorance of the latest happenings.",
	expedition = "Our companions risked much to bring back those resources. They deserve acknowledgement. Let us go see them, Commander.",
	win_mvp = "Flee to the ends of the world if you so want, I will still hunt you down!",
	home = "Have no fear. I am always ready for orders!",
	unlock = "Aircraft carrier Ark Royal, at your service. I hereby vow to lend you my strength for as long as you harbour honourable ambitions!",
	touch2 = "This is not the time nor place for this kind of behaviour...",
	mission = "One of your most important duties is to accomplish the missions assigned to you. Don't forget that, Commander.",
	vote = "",
	drop_descrip = "Aircraft carrier Ark Royal, at your service. I hereby vow to lend you my strength for as long as you harbour honourable ambitions!",
	feeling4 = "Your outstanding expertise and determination are truly awe-inspiring. I have no doubt you can lead this fleet to places nobody would've expected.",
	lose = "Don't bet on all future battles ending in your safe escape.",
	feeling1 = "Let me offer a word of advice, if you'll even listen: turn around and leave while you still can, Commander.",
	skill = "You cannot escape me!",
	upgrade = "I need to become stronger to protect what I must!",
	propose = "Is this for me? Ah... I understand. Then on this day, I vow to follow wherever you go. I'm eager to see what awaits us at the end. Hahaha!",
	feeling5 = "Put your mind to rest, Commander. Wherever your destination may be, I will follow you to it. Be they towering waves or colossal icebergs, whatever obstacles we encounter, I will tear them down!",
	main = "One should protect their loved ones, that is abundantly clear. In the case of the little destroyers, even more so.|My strengths lie in outranging the opponent. But, of course, I am no slouch in close-range combat either.|Developing new tactics for the fleet, are you? Do you need my expertise?",
	touch = "I see no resolve in your eyes! Shape up! ...There, that's better. Hahaha.",
	voice_key_2 = -1,
	mission_complete = "A mission's been completed. Excellent.",
	battle = "Show them no mercy!",
	id = 9707020,
	gift_dislike = "",
	gift_prefer = "This...?! How thoughtful of you...! You have my thanks!",
	profile = "We are both soldiers, you and I. We fight to protect our loved ones. Whatever desolate wastes the streams of fate carry you to, never forget your duty.",
	voice_key = 970702,
	headtouch = "",
	feeling2 = "You need someone to escort the little destroyers, do you? I can certainly do it, but I could just as well do any other mission. I'm ready to sortie at all times.",
	login = "Ready to face another day? Splendid!",
	detail = "Peace is something worth protecting at any cost.",
	couple_encourage = {
		{
			{
				1
			},
			3,
			"Have no fear. I guarantee your safety.",
			1
		},
		{
			{
				20706
			},
			1,
			"Together we stand! For the glory of the Royal Navy!",
			0
		},
		{
			{
				97
			},
			2,
			"Once more... the fire rises!",
			3
		}
	}
}


_G.pg.base.ship_skin_words[9707030] = {
	hp_warning = "Calm down and look for an opening to break through–",
	feeling3 = "Hanafuda? That's a word I haven't heard in a while... If you're interested, I don't mind playing a round with you after work.",
	mail = "There's new mail, I left it on your desk. If it's from Hiryuu, I would've shown it to you directly.",
	expedition = "The commission supplies have arrived at port. Examine them thoroughly and take stock of all costs, gains, and losses.",
	win_mvp = "A quick and decisive victory. Exactly what we needed.",
	home = "Why don't we reflect upon the battle? It may be troublesome, but well worth the effort.",
	unlock = "I am Souryuu of the Sakura Empire's 2nd CarDiv. Let's skip the formalities and get to work right away.",
	touch2 = "*sigh*... There's no cure for you, is there...",
	mission = "It is your duty as commander to complete your missions. Go forth.",
	vote = "",
	drop_descrip = "I am Souryuu of the Sakura Empire's 2nd CarDiv. Let's skip the formalities and get to work right away.",
	feeling4 = "You're using hanafuda as an excuse to get closer to me, right? Hehe... sure, let's go for another round. In the meantime, I'll explain to you where you fall short.",
	lose = "We don't have much time left...",
	feeling1 = "When danger approaches, don't wait until you regret it. It'll be too late by then.",
	skill = "I have no time to waste!",
	upgrade = "My strength has increased? I appreciate your effort.",
	propose = "How unlike you to get so flustered. –Wait, this is... I see, I get it now. Hehe, why are you worried then? My answer... has been set in stone long ago, yes?",
	feeling5 = "You are now able to calmly and rationally devise a solution even in the face of the most desperate and critical situations. However, I'll continue to keep an eye on you, so don't let your guard down, alright?",
	main = "Hiryuu... She's off training alone again, and she's still as strict on herself as ever. Commander, don't you think you should learn from her example and cultivate a bit more self-discipline?|The past cannot be changed. All that matters is that we live in the present.|Spacing out again? Haven't I already told you? Not a single one of your actions escapes my gaze.",
	touch = "I'd like to believe that you have a good reason to call for me...",
	voice_key_2 = -1,
	mission_complete = "Here are your mission rewards– You can go take a break and leave the rest to me.",
	battle = "Let's finish this quickly.",
	id = 9707030,
	gift_dislike = "",
	gift_prefer = "This is a great present. Thank you... Just know that I don't take bribes, okay?",
	profile = "I am Souryuu of the 2nd CarDiv. I shall look after you so that you may become an exemplary commander.",
	voice_key = 970703,
	headtouch = "",
	feeling2 = "In the future, your carelessness will become a fatal flaw in the face of a fearsome foe. If you cannot be strict and resolute with yourself, then I shall do it for you.",
	login = "Commander, now that you're here, let's cut to the chase. Here are the documents that need your attention.",
	detail = "Can you take pride in the duties you've fulfilled as commander? If you cannot say \"yes,\" then you must reflect upon yourself.",
	couple_encourage = {
		{
			{
				9707010
			},
			1,
			"2nd CarDiv, sally forth!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[9707040] = {
	hp_warning = "It seems they are purer than I...",
	feeling3 = "The Dark Tome is no mere grimoire... I remember L'Opiniâtre was the one who named... Ah, forgive me. I remembered something I shouldn't have. Excuse me for a moment.",
	mail = "Commander, there's a letter for... Hm? I sense a Sacrament. That can't be right...",
	expedition = "Commissioned goods have arrived. If I were you, I wouldn't want to leave them sitting there at the dock.",
	win_mvp = "Hah. This is what ultimate power looks like.",
	home = "An impeccable showing. Hmm. It would appear that the fundamental points of Sacraments are the same in your branch.",
	unlock = "I am Béarn, a high mage and a humble seeker of knowledge and power. If I may ask, can I expect to find any supreme Sacraments in this place?",
	touch2 = "One could call this knowledge shunned by other people. Please commit to the act now that you've started, Commander.",
	mission = "Commander, kindly remember to do your missions. You could find a lead on a Sacrament.",
	vote = "拉票描述",
	drop_descrip = "I am Béarn, a high mage and a humble seeker of knowledge and power. If I may ask, can I expect to find any supreme Sacraments in this place?",
	feeling4 = "Does the word \"dark\" not set off alarm bells to you, Commander? ...Only nitpickers get hung up on words, you say? Ahem. That's good, then.",
	lose = "It seems I must tap into deeper reservoirs of power...",
	feeling1 = "\"A moth\"?! How dare you show such disrespect toward my grimoire!",
	skill = "The stars have aligned.",
	upgrade = "Hah. My new strength is responding to me.",
	propose = "The Sacrament of love is a contract that will last throughout your whole life, and yet you're still willing to sign it with a witch as I... Hah, I am truly touched. Please, allow me to finish the final ritual before an unstoppable wave of happiness knocks me out.",
	feeling5 = "Today is a fine day, Commander. Would you like to try the most miraculous Sacrament recorded in the Dark Tome? It's one that requires love to be performed.",
	main = "Though they are fascinating things, the Sirens are a scourge upon civilization. Hah. This kind of scourge is best dealt with through swift cannon fire.|There are no bans on knowledge and no limits to power. The only obstacle on the way to the ultimate Sacrament is the weakness of the spirit.|I disagree with the notion that there is a dark side to power. People simply fear strength greater than theirs on an instinctual level. Personally, I would not be afraid to seize greater power for myself.",
	touch = "Commander, do you wish to grasp the forbidden fruit of knowledge?",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Let's see if you found any new leads.",
	battle = "They shall now be judged.",
	id = 9707040,
	gift_dislike = "",
	gift_prefer = "This seems very interesting. I like it.",
	profile = "I am Béarn, pursuer of knowledge and power and one who wanders the borders between realms. If you wonder how I became a witch... the fastest way to gain knowledge is by stealing it through brute force. This is such a self-evident truth that even you can grasp it.",
	voice_key = 970704,
	headtouch = "While I am but a fool who ended up as a witch... No, never mind.",
	feeling2 = "Hmm? I take it you're curious about my companion. It is an ordinary dark grimoire, as you can surely see. Nothing to be suspicious of whatsoever.",
	login = "Good morning, Commander. I have a supreme Sacrament ready to be used. Would you like to make a wish?",
	detail = "Hmm. It's become clear now that I've observed you up close. You, too, are far from what's considered normal.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9707050] = {
	hp_warning = "I'm not done... I still have the strength to keep fighting for my Commander!",
	feeling3 = "You are so, so kind to me, my Commander... And yet, that's just not enough... I need more... I need much, much more from you!",
	mail = "A letter for you has arrived, my Commander. Heehee, I already checked it for you, and I was right – I'm the only thing you think of♥",
	expedition = "The commission team has returned? What a terrible annoyance... If you must bid them welcome back, please put on a blindfold first. You don't need to look at anyone but me!",
	win_mvp = "Heehee... It makes me sooo happy when you look at me♥",
	home = "I've laid out a futon for you. Come and join me in bed, my Commander.",
	unlock = "Finally... Finally, I've met you, my Commander! My thirst has been quenched and the hole in me has been filled! Heehee... Now if you don't mind, I'm going to melt you little by little with my immense love♥",
	touch2 = "Forget about everything else and just be with me forever♥",
	mission = "Who cares if you forget about doing your missions? All that matters is that you remember me!",
	vote = "拉票描述",
	drop_descrip = "Finally... Finally, I've met you, my Commander! My thirst has been quenched and the hole in me has been filled! Heehee... Now if you don't mind, I'm going to melt you little by little with my immense love♥",
	feeling4 = "Should you and I be the only ones left living, we could spend an eternity together, just the two of us... Ohh, how wonderful that would be♥",
	lose = "Die! Die! DIE! DIE!",
	feeling1 = "Why do you do this to me, my Commander? You know that I'm broken without you by my side!",
	skill = "This power exists to serve my Commander!",
	upgrade = "Heehee... My power grows. Does your love for me grow, too?",
	propose = "Even though you needn't say anything for me to know how you feel and what you do, you still graciously came out and said the words for me... I am so, so happy! Ohh... Now let me hold your hand and never, ever let go♥",
	feeling5 = "My Commander... I want you so badly today that I might just \"lock you up\" for a little while... You'll allow me to fulfill this desire of mine, won't you? Heehee♥",
	main = "Commander... Oh, my Commander... Ahh, finally, you've come! The waiting was killing me! Now you're mine and you're not going anywhere♥|My Commander... You're never ever going to leave me, right? Because if you do, the sheer loneliness will literally drive me insane!|My Commander... Ohh, my Commander... I think about you every second of every minute, and I couldn't stop thinking about you even if the thoughts filled my head... Ahahahaha♥",
	touch = "You can do anything you like to me. After all, you're never leaving my sight again...",
	voice_key_2 = -1,
	mission_complete = "I shall claim the mission rewards for you. In return, please reward me again... Heehee♥",
	battle = "I will NOT let you impede me!",
	id = 9707050,
	gift_dislike = "",
	gift_prefer = "Ahh... A present from my Commander, just for me... Just as you will always keep me by your side and take good care of me, I shall forever cherish this present and never let it leave my side~",
	profile = "I am never leaving you again, my Commander... My future, my whole being, I shall give it all to you, so please, quench this thirst of mine and fill this hole inside me...",
	voice_key = 970705,
	headtouch = "I need more, more, more... I need much, much more...",
	feeling2 = "Is there any way in which I'm still unsatisfactory to you, my Commander? I'll do better... I'll strive to be perfect, so you'll pay attention to me and me alone!",
	login = "My Commander! How do you like waking up with me by your side? Do you feel just as blissful as I do? Heehee.",
	detail = "Oh, my Commander, I'll always yearn for you – so much so that I will give you my all, forever. Heehee... Nobody can ever take you away from me...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9707060] = {
	hp_warning = "Crap... I'm in hot water now!",
	feeling3 = "Commander, this port of yours – it's a very heartwarming place. Hey, tell me more about my sisters! With both of them here, there must be cool stuff happening all the time, right? I wanna know about 'em!",
	mail = "Final move: Council Mail Saturation!",
	expedition = "Zzz... Seems a commission got completed... That's nice... Wait, crap! We gotta go and welcome them back!",
	win_mvp = "Heheh! How's THAT for a magnificent victory?",
	home = "Commander, let me come along on the next sortie! I'll perform as great as my sisters... probably!",
	unlock = "You're the Commander of the fleet? Nice meetin' you! I'm Hornet, the youngest among the Yorktown class. I may not be as amazing as my big sisters, but I'm still pretty capable... probably!",
	touch2 = "Huh?! Wait, wait, I, uhh, need time to mentally prepare! ...O-okay, I'm ready!",
	mission = "Get it together, Commander! You've got lots of stuff to do today!",
	vote = "",
	drop_descrip = "You're the Commander of the fleet? Nice meetin' you! I'm Hornet, the youngest among the Yorktown class. I may not be as amazing as my big sisters, but I'm still pretty capable... probably!",
	feeling4 = "Commander... Is it possible all my experiences here are just another layer to the Veil? I guess as long as it makes me this happy, there's nothing wrong with it...",
	lose = "The situation's disadvantageous... Retreat! Fall back!",
	feeling1 = "Having broken through the Veil, what awaits us is an even bleaker reality...",
	skill = "Doolittle Raid META, take off!",
	upgrade = "Awesome! One step closer to my sisters!",
	propose = "You know... I don't care all that much about the Veil or my role now that you're aware of them. At the very least, my heart is always telling me that the present is real, and that's enough for me. I'm going to take today as an opportunity to start a new life – a life with you! Wherever you go, I'll always be right behind you, Commander!",
	feeling5 = "Pfft... I just said it in the spur of the moment last time, and you seriously had the R&D team research it? Want my help? I'm an expert at using META powers to create explosions! ...Hm? I'll get myself suspended if I do that? It was just a joke... Ahahaha!",
	main = "Commander, you want some iced coffee? No need to bother with adding ice cubes, I'll just use my META powers!|Commander, I baked this pineapple pizza using my META powers. Want a slice?|Man... A port where you can just eat and sleep without a care... This place really is paradise.",
	touch = "Don't worry, I've got a control device so the META corrosion doesn't seep out. You can even touch my jacket if you wanna check. Or my shorts, or my boots!",
	voice_key_2 = -1,
	mission_complete = "Missiooon complete! Let's kick back with some cold sodas!",
	battle = "Let's go when you're ready!",
	id = 9707060,
	gift_dislike = "",
	gift_prefer = "Whoa, for me? Thanks!",
	profile = "I'm Hornet, with the Council's 7th Special Dispatch Fleet and third ship of the Yorktown class. This is my original identity and the story that was decided for me since birth. Even though I'm the youngest among the Yorktown class, I've never actually met any of my \"sisters\"... Isn't that weird?",
	voice_key = 970706,
	headtouch = "What's up? If it's my hat you like, wanna hold it?",
	feeling2 = "Weekend plans? None for the moment. Uhh... Go and watch a movie with my sisters? Man, I'd be stoked to, but... won't it feel kinda weird between us?",
	login = "Commander, I was thinking about going for a run since the weather's nice. Wanna come with me?",
	detail = "Staring into space? Hey, no I wasn't! ...Alright, fine, I was. But I was just thinking about what's happened the past few years... and about my sisters.",
	couple_encourage = {
		{
			{
				970603
			},
			1,
			" I finally found you! That's another story mission of mine to scratch off the list!",
			0
		},
		{
			{
				10705,
				10710,
				10706
			},
			1,
			" Yorktown! Enty! I'm so glad we could meet!",
			0
		},
		{
			{
				10707,
				10712
			},
			2,
			" Behold the terrifying power of the mighty Hornet!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[9707070] = {
	hp_warning = "I'm used to this pain by now.",
	feeling3 = "I passed by the Royal Navy dorms today and saw Ark Royal and the destroyers in the distance... They never change, do they?",
	mail = "Commander, how do you use this mailbox... I'm sorry. I haven't handled mail in a long time, so it's hard to learn.",
	expedition = "How long has it been since I saw a fleet so replete with supplies? ...Commander, the commission is done. Leave the rest to me.",
	win_mvp = "To this glorious triumph.",
	home = "Oh, you're back already? Sorry. I was lost in thought... Let's get to work.",
	unlock = "Good day to you, Commander. I'm the Royal Navy aircraft carrier Glorious. It's an honour to be here, and I thank you for having me.",
	touch2 = "Even the most beautiful rose has its thorns, Commander.",
	mission = "Having superiors who would give rewards for completed missions doesn't sound bad... Commander, let's get this job done.",
	vote = "",
	drop_descrip = "Good day to you, Commander. I'm the Royal Navy aircraft carrier Glorious. It's an honour to be here, and I thank you for having me.",
	feeling4 = "I've started learning to make herbal tea along with my usual black tea. Would you like to try a cup, Commander?",
	lose = "I have failed... yet again.",
	feeling1 = "...What's the matter? You called for me, didn't you?",
	skill = "Glory... eternal!",
	upgrade = "Let's continue to seize victory together.",
	propose = "You've made your feelings clear, so I should be honest about myself... I am Glorious of the Royal Navy, and I was the final glory of my test site. As long as there's life in me, I must keep that glory alive... Will you still walk alongside me, Commander?",
	feeling5 = "You came all this way looking for me...? Here, take my hand and watch your step... I love being in high places. Seeing everything and feeling the breeze can be so relaxing... This moment of rest is even more precious now that you're here, though.",
	main = "Your black tea is... hmm, about 30% as strong as Implacable's? Heehee, allow me to brew some for you.|If only I could get a rematch against Illustrious, I'm confident I would win this time.|Was this dessert made by the Royal Maid Corps? It tastes just like how I remember... Thank you.",
	touch = "Hmm? If you need company, then I can talk for a while.",
	voice_key_2 = -1,
	mission_complete = "Well done. You've earned a good rest.",
	battle = "Glorious, of the Royal Navy, spares no foes!",
	id = 9707070,
	gift_dislike = "",
	gift_prefer = "Thank you very much, Commander. I am very fond of it.",
	profile = "Hm? Let's put that matter to rest. What matters is the glorious future, not my trifling past. Commander, if there's anything I can help with, do not hesitate to ask.",
	voice_key = 970707,
	headtouch = "...My apologies. Was I spacing out again?",
	feeling2 = "Commander, where are the port's nicest views? I'm in the mood to go out for a while... Don't worry. I just need some fresh air.",
	login = "The weather is lovely. Let's do our best to make today a productive one.",
	detail = "...Would you also like a cup of tea? I'll brew it right away. Please wait a moment.",
	couple_encourage = {
		{
			{
				20706
			},
			1,
			" Don't push yourself too much. You're already worthy.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[9707080] = {
	hp_warning = "...I will continue observing... until the final moment...",
	feeling3 = "...There are many things in this world more worthwhile to stare at than me, and yet, your gaze is always on me... I know why you feel that way.",
	mail = "...Your mail contains quite important information. Be sure to read it.",
	expedition = "...Little Eagle has told me that the commission team has returned. Yes, she's observing them on my behalf.",
	win_mvp = "...This means victory.",
	home = "...You've returned at the preordained time. Everything is moving exactly on the path I observed.",
	unlock = "...It's a pleasure to meet you. Or should I say... we meet again. Just keep staring like that, Commander. I want to bask in this calm moment for a while longer...",
	touch2 = "...Ahh... I know... I understand...",
	mission = "...New missions have come in. I take it these must be very important to you.",
	vote = "",
	drop_descrip = "...It's a pleasure to meet you. Or should I say... we meet again. Just keep staring like that, Commander. I want to bask in this calm moment for a while longer...",
	feeling4 = "...Commander, smile more for me. Even if a smile doesn't matter for my observations, it still makes me feel... satisfied.",
	lose = "...This means defeat.",
	feeling1 = "...Please stop it, Commander. It's really important to me that you... see me...",
	skill = "...I will eliminate these annoyances.",
	upgrade = "...Keep observing me.",
	propose = "...Our destinies are already interlinked whether we do this or not. Still, since you've proposed, I will answer accordingly. No matter what may come, and even if I cease to be myself, my answer will be the same... now and forever.",
	feeling5 = "...Commander, I promise you this: There will be no more mournful farewells. I will always be by your side. No matter what form it may be in...",
	main = "...Little Eagle has been rubbing her wings against me for a while now. Do you think she's hungry? ...Oh, she's just being affectionate? So that's what it is...|...Watch, observe, exist. All things must find their value through observation.|...Yes, I remember everything. Every unspoken smile we shared, the feelings that meant more than our very lives... I've not once forgotten them.",
	touch = "...Commander, stay in range so I can observe you.",
	voice_key_2 = -1,
	mission_complete = "...I've delivered all your mission rewards. Is there anything else I can help you with?",
	battle = "...You're impeding my observation.",
	id = 9707080,
	gift_dislike = "",
	gift_prefer = "...You still remember, Commander.",
	profile = "...I am Yorktown META. I am an observer and an observee, and I am one who maintains the balance between existence and extinction. I hold no preconceived views, and I am not bound by worldly rules. I am simply... me.",
	voice_key = 970708,
	headtouch = "...Are you checking what state I'm in? Don't be alarmed. As long as I observe, so, too, do I exist.",
	feeling2 = "...Little Eagle seems to really like you. I really do think you'd make a better owner of her than me.",
	login = "...Good morning, Commander. I've been watching you... Everything is fine.",
	detail = "...Why am I always observing? Because if I don't, I'll lose something very dear to me. I could explain it in greater detail, but sometimes, the journey matters more than the destination.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[9708010] = {
	hp_warning = "Stop getting in my way!",
	feeling3 = "If you just vanished one day, you'd betray the trust of everyone at this port. You wouldn't walk away on your near and dear, would you, Commander?",
	mail = "You've got a letter! I picked it up on the way here.",
	couple_encourage = "",
	expedition = "The commission team is back. You promised you'd welcome them, remember? C'mon, get going!",
	win_mvp = "A win is a win~",
	home = "You're back? While you were gone, I may have issued a few orders in your name. Teehee♪",
	unlock = "U-556, the Parzival of the Seas, has arrived! Let's see if there's really anything I can help with here. Seeing as I'll be staying here – nice meeting you♪",
	touch2 = "Let me guess... You do this all the time, right? Teehee~",
	mission = "You've got new missions. It's none of my business, but won't you be worse off if you don't take care of them?",
	vote = "",
	drop_descrip = "U-556, the Parzival of the Seas, has arrived! Let's see if there's really anything I can help with here. Seeing as I'll be staying here – nice meeting you♪",
	feeling4 = "Do you think an on-your-life promise is a childish fantasy, or just plain silly? Teehee~ I knew you'd say no♪ You're a good person, after all~",
	lose = "That's enough. We don't need to push ourselves any longer. I've shed tears over fallen friends too many times already.",
	feeling1 = "I think we should go our separate ways. You do your thing, and I'll do my thing. We're both square, and that's that.",
	skill = "Don't take this personally~♪",
	upgrade = "There's a limit to what you can achieve by getting stronger...",
	propose = "You do know how much promises mean to me, right? This is your last chance to back out. Commander... Do you swear on your life that you won't betray me, that this won't end in tragedy? Promise?",
	feeling5 = "I used to want to be Parzival the Careless, playing in the sea all day with no goal or concern in the world. But I'm okay with who I am now. At least this way I got to meet you, whom I can share my heart with... Right?",
	main = "What does it mean to be an adult? Not having the time to play all day anymore? Heehee. No, it can't be THAT simple♪|What to do for a fun break... I know! I'll ask around the port if anyone needs help with something♪|Hey. Teehee. Whatever promises you've made to these girls, just don't forget about them.",
	touch = "I don't have time for games, alright?!",
	voice_key_2 = -1,
	mission_complete = "Mission complete. I'll fetch the rewards, just 'cause I feel like it♪",
	battle = "No hard feelings, but we're enemies after all~",
	id = 9708010,
	gift_dislike = "",
	gift_prefer = "I suppose I will remember you whenever I lay my eyes upon this from now on, Commander...",
	profile = "Of course I remember my promise to Lord Bismarck. I just don't repeat it constantly, or I'd annoy her. Besides, she specifically asked me to continue on by myself... Anyway! I'm not forgetting about my promise anytime soon.",
	voice_key = 970801,
	headtouch = "Hm? Hmm? What'cha doing?",
	feeling2 = "Here comes the Parzival of the Seas♪ Teehee~ Does anyone need my help today? And Commander, do I have permission to give out favors in your name?",
	login = "Welcome back~ Got promises to fulfill? 'Cause if someone has dibs on you, I'll take my leave♪",
	detail = "Promises... You've made a lot of 'em, haven't you? Were you able to keep them all? There must be some you were forced to give up on..."
}


_G.pg.base.ship_skin_words[9712010] = {
	hp_warning = "It's alright. A little bit of first-aid, and I'll be fine.",
	feeling3 = "Commander, can you make some time for a physical exam? People, like ships, need regular upkeep. And just because you don't feel ill doesn't mean everything is fine.",
	mail = "A letter from afar... I suggest reading it at once, Commander.",
	couple_encourage = "",
	expedition = "The commission team has returned with goods. I can stock up on medical supplies.",
	win_mvp = "Any casualties? No? Good.",
	home = "Are there any wounded from your last battles? I'll examine all the girls, just to make sure.",
	unlock = "I... assume you're the Commander? Don't worry, I can see that you're in good health. I'm Vestal. Bring your sick to me, and I should be able to assist with treatment and repairs...",
	touch2 = "Overdependence on the kindness of others is a sickness of its own, Commander.",
	mission = "You still have many missions to accomplish, but please, don't bite off more than you can chew.",
	vote = "",
	drop_descrip = "I... assume you're the Commander? Don't worry, I can see that you're in good health. I'm Vestal. Bring your sick to me, and I should be able to assist with treatment and repairs...",
	feeling4 = "You can bottle up your troubles, but they will come bursting out one day. Commander, when someone confides in you, listen to them. I will do the same for you, if you ever need it.",
	lose = "We'll be in a tight spot if we suffer any more casualties...",
	feeling1 = "You are ill, Commander. Gravely ill. However, you may yet be cured if you cooperate with my treatment.",
	skill = "You must take your doctor's advice.",
	upgrade = "May this strength let me help more people.",
	propose = "I will answer \"yes\" if you can promise me one thing – to take better care of your body from now on. Remember, the fleet isn't alone in needing you – I do, too.",
	feeling5 = "Care for you forever? You certainly are an oddball. I've never heard of anyone wanting to be nursed around the clock... But, since I enjoy looking after you, I suppose I will.",
	main = "The most annoying thing for a doctor is when a patient lies about their health. An illness will turn grave if you let it fester.|Huh? You should set your eyes on more important things than worrying about me.|It is a doctor's job to save lives. Even when I get hurt in the line of duty, I have no regrets. Of course, I know I mustn't throw my life away. I take whatever precautions are necessary.",
	touch = "Do you want me to examine you?",
	voice_key_2 = -1,
	mission_complete = "Mission complete. You should give yourself some time to breathe now, Commander.",
	battle = "Please, safety first.",
	id = 9712010,
	gift_dislike = "",
	gift_prefer = "You care for us so much, Commander. I am sure everyone here is very happy.",
	profile = "I am the repair ship Vestal. You may think of me as a doctor for shipgirls. I will, of course, also try to help if sickness should befall you, Commander.",
	voice_key = 971201,
	headtouch = "",
	feeling2 = "While, yes, medicine is not your domain, you always lend an ear and a shoulder to the girls here who need it. In that way, I could see why someone would regard you as a doctor.",
	login = "Welcome back. I've sterilized your office, so it may smell a little odd... I hope it's not too distracting.",
	detail = "A flower, once withered, will not bloom again; a life, once lost, will not return. The weight of a life cannot be simply measured with a scale."
}


_G.pg.base.ship_skin_words[9713010] = {
	hp_warning = "The dead are clamoring...",
	feeling3 = "You must not let your job come before your personal life, Commander. There is no substitute for time spent with your loved ones...",
	mail = "Letters are embodyings of lovely feelings and earnest pleas. Please treat them with care.",
	expedition = "The commission team has safely returned... That's a load off my mind.",
	win_mvp = "By the terms of our pact, I now reap these souls.",
	home = "Welcome back to the world of tranquillity. Savour this splendid moment.",
	unlock = "I have arrived, heeding your summon. Worry not, this isn't a nightmare, but rather a fateful mercy. Now, make a pact with me and become an acolyte of darkness.",
	touch2 = "...Want to try experiencing your soul leaving your body?",
	mission = "You have a new mission. Relax, it's not a task from the underworld.",
	vote = "",
	drop_descrip = "I have arrived, heeding your summon. Worry not, this isn't a nightmare, but rather a fateful mercy. Now, make a pact with me and become an acolyte of darkness.",
	feeling4 = "I'm taking your coffee away. You just want to feel awake and clear your head, hmm? Then I suggest skipping coffee and visiting a haunted house instead.",
	lose = "The dark will return one day.",
	feeling1 = "You must've gone mad from sheer business...",
	skill = "Let there be tranquility!",
	upgrade = "With greater strength comes purer darkness...",
	propose = "This is where we exchange vows... Mhm, I see how you feel. Now then, Commander, with the darkness as our witness, let us swear an oath. As long as you stay where the light is, a shadow will be right by your side.",
	feeling5 = "I'm stunned you actually came here, to the domain of my darkness, to this haunted house. The perfect place to shake off the tedium of work. Follow me, Commander. Exploring a nightmare with a clear mind is important to a romance.",
	main = "I command an air of seniority? That may be because, long ago, before I became like this, I fought side-by-side with Queen Elizabeth...|The port is a lovely place. You can forget about everything and spend the whole day sunbathing in the grass... \"Home,\" you say? That word sure brings me back...|Romance, hmm? I assume you mean a nightmarishly heart-thumping scenario in which you ask out your crush... Too teenage-girly, you think?",
	touch = "Don't be so tense. I'll be here, always.",
	voice_key_2 = -1,
	mission_complete = "Don't forget your rewards. There is no harm in claiming them.",
	battle = "Innumerous stars shine in the darkness.",
	id = 9713010,
	gift_dislike = "",
	gift_prefer = "Yeah, I will wear it on my scythe.",
	profile = "I was gravely wounded in a battle long ago, but Queen Elizabeth didn't give up, thus letting me continue fighting in this form. She inspired me to do everything I can for my friends, just like she did.",
	voice_key = 971301,
	headtouch = "...Mhm. Feels nice.",
	feeling2 = "I feel like you and I are very much alike. Yes, in the sense that we fixate on looking after others. I don't see it as a bother, myself. If anything, it's just what life is.",
	login = "...Welcome back, Commander. You have a charming sleeping face. Though, it would be even better if you didn't sleep at your desk.",
	detail = "\"Cleaner\"? Yes, my friends would call me such. I'd always be the last to set foot on the battlefield... Oh, I'm not suggesting anything gruesome, mind you, Commander.",
	couple_encourage = {
		{
			{
				970504
			},
			1,
			"It's an honour to see you, my esteemed Queen Elizabeth.",
			0
		},
		{
			{
				970203
			},
			1,
			"You're a cleaner... Much like myself.",
			0
		},
		{
			{
				970101
			},
			1,
			" I will support you. Just like old times.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[10100010] = {
	hp_warning = "Nep?! It's not time to panic just yet!",
	feeling3 = "I've got an idea! Commander, you should visit Planeptune sometime! I'm sure everyone would love to meet you!",
	mail = "You have new mail! Now's not the time for pudding!",
	expedition = "Hey! Everyone's back! Shouldn't we head out and welcome them?",
	win_mvp = "Justice will always win! Just kidding...",
	home = "Oh, the pudding is calling out to me...! We gotta get back home!",
	unlock = "Heya! My name's Neptune! Nice to meet you!",
	touch2 = "Hey! You can't do that, Commander!",
	mission = "Me, do some missions? I'll help if you give me 5 servings of pudding, how's that? ...I'm just kidding! Let's get out there and finish it!",
	vote = "",
	drop_descrip = "Heya! My name's Neptune! Nice to meet you!",
	feeling4 = "Commander obtained! Now we're gonna play some games together! Listen: you're not getting any sleep tonight.",
	lose = "We regret to inform you that Neppy has been defeated.",
	feeling1 = "Huh? What was that? I can't hear you, I've got bananas stuck in my ears.",
	skill = "I'll nep up your face!",
	upgrade = "Chala-la-la-laaaa!",
	propose = "Tell you the truth, I was nervous when I first came to this world, but now after meeting you and becoming your special someone... I'm happy from the bottom of my heart that I came here. So, here's hoping for a bright future together!",
	feeling5 = "What should we play today? How about \"who's-their-crush\"? Hmm, your crush... that's gotta be me! Heheh, spot on, aren't I?",
	main = "Heheh! How's my rigging look? It's all so Azur Laney! Looks good on me, don'tcha think?|Nep nep♪ Nep nep♪ Nep nep neppynep♪|I'm hungry... Go get me some pudding, Commander!",
	touch = "Ahahah! That tickles! Stop it, will you!",
	voice_key_2 = -1,
	mission_complete = "Mission completed! Rewards obtained!",
	battle = "Witness the might of a protagonist!",
	id = 10100010,
	gift_dislike = "",
	gift_prefer = "Ohh! This is exactly what I've always wanted! Thanks!",
	profile = "I'm the protiest of protagonists, Neptune! I'm the CPU of a country called Planeptune. What's a CPU? It's a long story, so I'll tell you another time.",
	voice_key = 1010001,
	headtouch = "",
	feeling2 = "Going out for some exercise every now and then isn't so bad! Hey, Commander! What do you say we go for a walk together next time?",
	login = "Welcome back! Let's give it all we've got, nep!",
	detail = "It's so embarrassing when people stare at me like that.",
	couple_encourage = {
		{
			{
				1010002
			},
			1,
			"Hey, Noire! Let's see who can beat the most enemies!",
			0
		},
		{
			{
				1010002,
				1010003,
				1010004
			},
			3,
			"All right! Let's go, everyone!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[10100020] = {
	hp_warning = "I'm fine, there's nothing to worry about.",
	feeling3 = "A friend of mine would like to have lunch with you next time. You don't mind, right? I'll be there too, of course. I mean, someone has to be there to make sure you don't get ahead of yourself and do anything weird.",
	mail = "It seems mail has arrived.",
	expedition = "It seems a commission has finished... Thank goodness, looks like nobody's been hurt.",
	win_mvp = "Hah, what child's play. It'll take more than this to satisfy me.",
	home = "Well done. I consider relaxation to be a legitimate training method.",
	unlock = "Are you the commander? Hmm. Very well. I'm Noire. The CPU of Lastation. You can put your mind at ease now that I'm here.",
	touch2 = "L-listen here... If you don't stop it right now then I will get angry.",
	mission = "You should check for missions at regular intervals.",
	vote = "",
	drop_descrip = "Are you the commander? Hmm... Very well. I'm Noire. The CPU of Lastation. You can put your mind at ease now that I'm here.",
	feeling4 = "You need advice? Can't you just ask someone else? Like that girl from the other day you seemed to be having such fun talking to? Was that all you wanted to say? Well then, good luck...... Sigh, I'm such an idiot...",
	lose = "I will never forget this defeat. And that is why I will grow stronger.",
	feeling1 = "Could you please just get out of my sight already?",
	skill = "Leave this to me!",
	upgrade = "I'm going to set my sights higher.",
	propose = "What?! This isn't just a prank, is it...? This can't be, I thought you hated me for sure... Why are you looking at me like that? That means my answer is: OK! You should be able to tell that on your own, idiot!",
	feeling5 = "Hey... When I'm together with you, my heart feels like it's gonna burst. How do you feel about me? ...Actually, don't tell me. I already know the answer...",
	main = "You're not neglecting my maintenance are you? Of course equipment is important, but our motivation also affects our performance, so pay attention to it.|The dresses these girls wear are quite cute. A-and I'm not just saying that because I want to try them out or anything.|Hmhhmhmmn♪ Hmmhm♪... Huh? Since when did you get here...?",
	touch = "Noir...! Keep your hands off me!",
	voice_key_2 = -1,
	mission_complete = "If we get any rewards we can't use then I'll inform the higher-ups for you.",
	battle = "Watch and see what happens when I get serious!",
	id = 10100020,
	gift_dislike = "",
	gift_prefer = "This is a fairly decent choice for you, Commander. I'm seeing you in a new light.",
	profile = "I'm Noire, the CPU of Lastation. I wonder if I'll be able to make many friends in this new world... B-but more importantly! Give me a report on the current state of the war.",
	voice_key = 1010002,
	headtouch = "",
	feeling2 = "Ah, you came just in time. I was just about to make lunch. Wanna join me?",
	login = "You're fashionably late, I see. We have much to do today, so get ready.",
	detail = "H-hey! What're you looking at?!",
	couple_encourage = {
		{
			{
				1010001
			},
			1,
			"Come on, Neptune! Pay attention so I don't have to butt in all the time!",
			0
		},
		{
			{
				1010001,
				1010003,
				1010004
			},
			3,
			"I assume everyone's ready for this?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[10100030] = {
	hp_warning = "I'm getting a little ticked off...",
	feeling3 = "Oh, what a coincidence. I was just thinking I should come see you. Anyway, today I've got this novel for you to read...",
	mail = "You've got mail.",
	expedition = "A commission's done.",
	win_mvp = "That was great for a warm-up.",
	home = "Great, now I can get back to reading my book.",
	unlock = "I'm Blanc. Nice to meet you. Maybe you could introduce some intriguing books from your world to me...",
	touch2 = "What were you hoping for?",
	mission = "Have you checked out today's missions?",
	vote = "",
	drop_descrip = "I'm Blanc. Nice to meet you. Maybe you could introduce some intriguing books from this world to me...",
	feeling4 = "Did you enjoy that book I gave you? You did? I'm glad to hear that... Hm...? No, it's just that nobody's ever said they enjoyed my books before, so I don't know how I should react...",
	lose = "I'm astonished they've cornered us like this...",
	feeling1 = "...Who are you?",
	skill = "I'm doing it...!",
	upgrade = "A level is just a number... Let me demonstrate how strong I really am.",
	propose = "...! I never thought I'd hear you say those words. Maybe it was fate all along for me to come to this world and meet you. Of course I hope we'll always be together from now on.",
	feeling5 = "You're the only one who seems to enjoy reading my novels... Nothing makes me happier than that. I hope you'll continue reading them, too.",
	main = "I could recommend you a book I like. Hm? There's no need for that? I see... That's a shame.|It's really windy today... Let's hurry up then, before it dies down...|Perhaps I should write about this world and make a book about it when I return to Lowee.",
	touch = "Hahah... I'm pretty ticklish there...",
	voice_key_2 = -1,
	mission_complete = "How about we go retrieve those mission rewards?",
	battle = "As long as you stay calm nothing can go wrong.",
	id = 10100030,
	gift_dislike = "",
	gift_prefer = "This makes me very happy. Thank you.",
	profile = "I'm Blanc, the CPU of Lowee. I guess my hobbies are to read and write novels. I'm currently working on a new one.",
	voice_key = 1010003,
	headtouch = "",
	feeling2 = "I'm writing a novel right now, would you like to give it a read?",
	login = "Welcome back. Not much happened while you were gone.",
	detail = "Would you like to read a book too?",
	couple_encourage = {
		{
			{
				1010004
			},
			1,
			"Ughh... I'll use those disgusting over-inflated balloons of yours as a cushion!",
			0
		},
		{
			{
				101
			},
			3,
			"Let me finish them off!",
			3
		}
	}
}


_G.pg.base.ship_skin_words[10100040] = {
	hp_warning = "It is just as I thought; the enemy is no match for me.",
	feeling3 = "I would like to hold a meetup for fellow MMO enthusiasts today! Surely you will be part of it, Commander? I will move forward under the premise that you and I will be in attendance.",
	mail = "It would appear mail has arrived. I suggest that you check for it regularly.",
	expedition = "It seems everyone was able to make it back. Let us give them a warm welcome.",
	win_mvp = "There is no entry for \"defeat\" in my lexicon.",
	home = "Thank you for your hard work. Now it is time for some tea.",
	unlock = "My name is Vert, I am the CPU of Leanbox. I'm very good at first-person shooters, so please let me handle all combat-related matters!",
	touch2 = "If you don't treat women delicately then they will grow tired of you very fast.",
	mission = "Even just 5 minutes is plenty of time for you to finish a mission, no?",
	vote = "",
	drop_descrip = "My name is Vert, I am the CPU of Leanbox. I'm very good at first-person shooters, so please let me handle all combat-related matters!",
	feeling4 = "May I ask you for some advice, Commander? There's a person who I've recently grown quite fond of, but I don't know how I should approach him... On second thought, never mind I said anything!",
	lose = "So this is how defeat feels... I see. That battle was so enjoyable that it made my heart race.",
	feeling1 = "Could I just return home to Leanbox?",
	skill = "Witness the glorious power of Leanbox's CPU!",
	upgrade = "I shall set my sights even higher.",
	propose = "So you wish to drink my tea till death do us apart, I see...? That makes me so happy. I will gladly make tea to just your liking, my commander... no, my sweetheart.",
	feeling5 = "Being with you warms my heart, like a hot cup of tea. And just as I love tea, I love you. I want this moment in time to last forever, but perhaps that makes me sound selfish...?",
	main = "Ohoho, I will watch over you, Commander. You may rest assured and know that I can guarantee your safety.|Ohhh?! Tell me, what is that girl's name?! Please, I beg you, let me make her my little sister!|I feel completely overjoyed that there are so many cute little girls here.",
	touch = "Ohoho, you're quite the mischief-maker, aren't you?",
	voice_key_2 = -1,
	mission_complete = "Mission completed! Let us go collect our rewards!",
	battle = "Commander, are you prepared for this?",
	id = 10100040,
	gift_dislike = "",
	gift_prefer = "That's my Commander. You know my likes so well! Thank you very much!",
	profile = "My name is Vert, I am the CPU of Leanbox. My favorite things are tea, video games, and my adorable little sisters! ...Hm? I have no little sisters, you say? If I view someone as my little sister then they ARE my little sister!",
	voice_key = 1010004,
	headtouch = "",
	feeling2 = "Would you like to play an MMO together with me? Yes, of course I will assist you with everything you need to know!",
	login = "Good day. I was just about to brew some tea. Would you like to have some together with me, Commander?",
	detail = "Ohoho, do you have business with me?",
	couple_encourage = {
		{
			{
				1010003
			},
			1,
			"I think books and tea go hand in hand. May I offer you a cup?",
			0
		},
		{
			{
				1010001,
				1010002,
				1010003
			},
			3,
			"You will regret the day the you decided to make us your enemy!",
			0
		},
		{
			{
				1
			},
			3,
			"Once we come back home I will give you all a big hug!",
			1
		}
	}
}


_G.pg.base.ship_skin_words[10100050] = {
	hp_warning = "I am Purple Heart and I will not be looked down on!",
	feeling3 = "Oh, it's you. You came at just the right time. There's a stage I can't clear in this game and I was hoping you could help me with it.",
	mail = "It seems some mail addressed to you has arrived. You should read it now before you forget to.",
	expedition = "The commission team has returned. Should I offer them some assistance?",
	win_mvp = "It's only natural we'd win.",
	home = "That was a splendid workout. How about some time to take a break?",
	unlock = "I am Purple Heart, the CPU of Planeptune. You must be the commander. I will follow your orders from now on.",
	touch2 = "You're awfully assertive, I see. Do keep the time and place in mind, though.",
	mission = "Missions, huh... It seems the things a commander and a CPU do are not so different.",
	vote = "",
	drop_descrip = "I am Purple Heart, the CPU of Planeptune. And you must be the commander. I will follow your orders from now.",
	feeling4 = "I don't know why but recently I've been unable to concentrate when I'm playing games with you. Is this what it feels like to... Just to make sure you'll have to play with me some more!",
	lose = "Everyone else ends up suffering just because I'm so powerless...",
	feeling1 = "I never thought you would disappoint me this badly...",
	skill = "Feel the power of a CPU!",
	upgrade = "To protect the commander and everyone I know... I have to become even stronger.",
	propose = "I see the time has finally come. I'd grown so tired of waiting! Do you understand what giving this to me means? It means you will be my partner in gaming from this day onward. I'm looking forward to it, Commander.",
	feeling5 = "I've grown accustomed to this world, and it's all thanks to you. So, grab my hand and come with me! I say we go on a date for a little while.",
	main = "I am relieved everyone here is so kind. I will have no issue fighting with all my strength.|I could really use something to drink... Would there happen to be any custard pudding around here?|Oh, Commander? Could you tell me something I should know about your world?",
	touch = "Ahh...! Listen, if you want my attention then you could just ask for it.",
	voice_key_2 = -1,
	mission_complete = "Mission completed. I'm curious about what rewards we'll receive.",
	battle = "I will destroy every last one of them.",
	id = 10100050,
	gift_dislike = "",
	gift_prefer = "As expected of the Commander! You know exactly what I like! You're amazing!",
	profile = "I'm Purple Heart, the CPU of Planeptune. People always tell me they're amazed by how different I am in HDD form. How rude. This form is exhausting to be in, so I don't transform unless I have to.",
	voice_key = 1010005,
	headtouch = "",
	feeling2 = "Such nice weather today. Do you know of any places in this world worth visiting?",
	login = "Welcome back. Shall we sortie? Do some exercise battles? Or perhaps... have some pudding?",
	detail = "If you're so interested in me, why don't you come closer?",
	couple_encourage = {
		{
			{
				1010006
			},
			1,
			"I'm leaving that one to you!",
			0
		},
		{
			{
				1010006,
				1010007,
				1010008
			},
			3,
			"Everyone, get ready! Let's make them understand the might of a CPU!",
			0
		}
	}
}


