	home = "Rest is important, too.",
	unlock = "I am the CPU of Leanbox, Green Heart. No matter who the enemy is, I will not hold back. Are you ready?",
	touch2 = "It's not a good idea to keep playing these distasteful pranks.",
	mission = "If you require my assistance at any time, just let me know.",
	vote = "",
	drop_descrip = "I am the CPU of Leanbox, Green Heart. No matter who the enemy is, I will not hold back. Are you ready?",
	feeling4 = "I have some free time tonight, so I would be glad to help you with work. Afterwards, I'd like you to give me... U-um... forget I said anything.",
