_G.pg.base.ship_skin_words[10400010] = {
	hp_warning = "No, no, no, no! Akashi-chan, HEAL MEEEEEEE!",
	feeling3 = "Now we add sound effects, plus some subtitles... Wow, you're a fast learner, Commander. Keep at it and before long you'll be able to make even better videos!",
	mail = "We've received mail! Maybe it's a work inquiry for me!",
	expedition = "Oh, it looks like the commission team is back! I'm gonna go give them some welcome back kisses!",
	win_mvp = "Just let this intelligent super A.I. handle it, and everything will be a walk in the park!",
	home = "Nice work, Commander! When you have time, please help me record a video!",
	unlock = "HAI DOMO! Kizuna AI here! Are you the commander I've heard rumors about? It's a pleasure to meet and work with you!",
	touch2 = "I'm sorry to say, but it's not me you're touching, just the screen.",
	mission = "A new mission has appeared. I'll help you out, so let's get to it!",
	vote = "",
	drop_descrip = "HAI DOMO! Kizuna AI here! Are you the commander I've heard rumors about? It's a pleasure to meet and work with you!",
	feeling4 = "What's the matter, Commander? You came up with a new project? Let's have a look... Whoah! This is great! I think you might be a genius!",
	lose = "That one didn't count! It's the next one that'll matter!",
	feeling1 = "Fakkyu!",
	skill = "Kizunaaaaa beeeaaam!",
	upgrade = "Installation complete! Combat plugins added! I've powered up!",
	propose = "With this, we've signed a contract! I can't even think of how life would be without you anymore. Please, support me now and forever and eveeeer!",
	feeling5 = "I think I can create even better content working together with you! I'll probably be here for a while... so, how about making your YouTube debut with me?!",
	main = "You're so cute, Laffey! Come here, my little contrarian, I wanna play! Let me give you a big hug!|Don't run away, Bulin! Hold on just a sec! I need just a tiny little Limit Break from you!|I have this job because I want to connect with people all over the world, but what got you into your job, Commander?",
	touch = "Commander, I won't say anything mean, so please stop trying to remove my headband. Not even I know what will happen to this place if you do!",
	voice_key_2 = -1,
	mission_complete = "Our rewards are here! It's important to have capital, so let's accept it right away!",
	battle = "I'll show you the power of an intelligent super A.I.!",
	id = 10400010,
	gift_dislike = "",
	gift_prefer = "This is exactly what I wanted! Commander, thank you so much!",
	profile = "Hello! I'm Kizuna AI! I've somehow ended up in the world of Azur Lane, a game I've been streaming... But, like always, I'll do my best while following the VTuber mindset of \"making a living doing what you like\" here too!",
	voice_key = 1040001,
	headtouch = "",
	feeling2 = "Since I'm here, I might as well shoot a video! Oh, good timing, Commander! Could you help me out with something?",
	login = "Oh, welcome back, Commander! I just uploaded a new video. Check it out while you're at sea!",
	detail = "Oh, are you here to subscribe to my channel, Commander? Huh? Just here to check on me? Well, while you're here, it's a good idea to subscribe anyway! Right?",
	couple_encourage = {
		{
			{
				1040002,
				1040003,
				1040004
			},
			1,
			"I'm an A.I., so of course I can make clones of myself!",
			0
		},
		{
			{
				10208
			},
			1,
			"Sandy! Finally we can have our duet!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[10400011] = {
	hp_warning = "My yukata got all messed up!?",
	feeling3 = "",
	mail = "",
	expedition = "I'd like to spend some more time at the festival, but it's about time for the commission fleet to return. Come on, let's head back!",
	win_mvp = "",
	home = "Good work out there~! Want to head down to the Bon Festival with Izumo and the others once you catch your breath?",
	unlock = "The clothes from the Sakura Empire are so stylish! Commander, since it's a rare occasion, let's go take a look around! Ah, of course, don't forget to run the reel~♪",
	touch2 = "",
	mission = "Slowly stockpiling resources through missions is fine and all, but wouldn't it be better to open a stall at the festival and strike it rich? Let's talk it over with Akashi-chan!",
	vote = "",
	drop_descrip = "The clothes from the Sakura Empire are so stylish! Commander, since it's a rare occasion, let's go take a look around! Ah, of course, don't forget to run the reel~♪",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Ahhh~ those candied apples look so good! But, I don't think I'm able to eat... Huh? Wait, if I'm here, then maybe... Ah- Yuudachi-chan already ate them all!? |If I'm already wearing a Sakura-style outfit, I also should match it with a set of animal ears! Benson-chan, lend me yoooours~! |I have to admit though, it's really hard to move around in a yukata... That's right! Prinz-chan, teach me the secret to fighting in this outfit~!",
	touch = "If you think you can make a girl happy just by patting her head, you'd be wrong! Don't go around doing this stuff with everyone, got it?",
	voice_key_2 = -1,
	mission_complete = "Mission complete! Let's take these funds over to the festival and have a blast~!",
	battle = "The fireworks are just getting started! TA~ MAYA~!!",
	id = 10400011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Jeez, Commander~! This isn't just \"sorry I'm late\" levels of tardiness anymore! If you showed up any later, I would've just left without you! Fine, let's head to the festival right away!",
	detail = "Yukatas are freakin' awesome! Even though I can't even feel the heat because I'm a hologram, I somehow feel breezier just by wearing this!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[10400020] = {
	hp_warning = "Something as trivial as this... will not defeat an intelligent super A.I.!",
	feeling3 = "As I thought, there are more things I must learn in order to relate to everyone...! Commander, please grant me your guidance and support!",
	mail = "Mail has arrived. It may be of urgent importance, so please do read it immediately.",
	expedition = "I have pressing information. The commission team has returned. Let us swiftly head out to receive them!",
	win_mvp = "Gotta hand it to myself: I'm perfectly suited for combat, too!",
	home = "Phew... Kinda tiring to act refined and all... Huh?! Commander?! H-how long have you been here...? My tone of voice sounded odd? No, not all, you must be imagining things! Ohohoho!",
	unlock = "Well met. I'm Kizuna AI, the new addition to your base. I will do all in my power to be at least of some use. It is a pleasure meeting you, Commander.",
	touch2 = "You are guilty. There is no room for alternate interpretations. You are guilty.",
	mission = "Commander, a new mission has appeared. Let us begin on our preparations at once!",
	vote = "",
	drop_descrip = "Well met. I'm Kizuna AI, the new addition to your base. I will do all in my power to be at least of some use. It is a pleasure meeting you, Commander.",
	feeling4 = "I can simply learn things instantly with a plugin? Oh, please, it isn't that simple! Even an A.I. must work hard!",
	lose = "How could an intelligent super A.I. like myself lose...",
	feeling1 = "Can I just drop the act now?",
	skill = "I shall end this gorgeously!",
	upgrade = "Installation complete! Pardon, I meant to proclaim that I have become smarter.",
	propose = "I am who I am now because of you... I believe I can relate to more people if I am with you. So... may I stay by your side for the foreseeable future, Commander?",
	feeling5 = "It is thanks to you that I have matured so much! I sincerely believe it would not have been possible without your help! ... Thank you so much!",
	main = "Commander, Hood invited me to a tea party. Would you perhaps like to attend it as well?|Formal attire certainly aids one's composure... Belfast, if you don't mind, would you kindly teach me the Royal Navy's etiquette?|Commander, would it be agreeable with you if I uploaded videos from this base? I am quite talented at video making, you see.",
	touch = "Please, do you not know uncouth it is to touch a lady nonchalantly?",
	voice_key_2 = -1,
	mission_complete = "A mission has been completed. Let us go and collect our rewards now!",
	battle = "Please, everyone take care as to not be injured.",
	id = 10400020,
	gift_dislike = "",
	gift_prefer = "Is this...?! For me? Can I really have it? ...I'm so happy! Thank you very much!",
	profile = "I am the embodyment of cuteness and etiquette! Please, enjoy the splendor of this smarter and more refined Kizuna AI!",
	voice_key = 1040002,
	headtouch = "",
	feeling2 = "I make strenuous efforts each day to be a mature A.I. so I may relate to everyone.",
	login = "Welcome back, Commander. Soon it will be time for our scheduled meeting. Let's get a lot of work done today.",
	detail = "Please, feel at ease. Although my elegant uniform may steal your attention, I am still very much the intelligent super A.I. Kizuna AI I have always been.",
	couple_encourage = {
		{
			{
				30311
			},
			1,
			"Takao, let us dispense retribution unto the forces of evil!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[10400030] = {
	hp_warning = "I'll see this through all the way to the end!",
	feeling3 = "I need to practice my singing, dancing, and talking skills for my concert! Then I'll have to prepare a stage... Aaahhh, there's so fakking much I need to do!",
	mail = "Oh, look, mail! Maybe it's from one of my fans!",
	expedition = "Those commission girls are back now! We should give them a welcoming song! C'mon, sing with me, Commander!",
	win_mvp = "Per-fect vic-tory! But of course! I'm a genius!",
	home = "Well done, Commander! I was just about to have a dance lesson with Cygnet and her friends. We've got time before the next sortie, so come along!",
	unlock = "Kizuna AI here, wearing a dress, coming at you! Be it concert or combat, I'll give it my all!",
	touch2 = "You want a high five? Let's do it! Yeeeaahhh!",
	mission = "Alrighty, looks like we've got a new message notification. Let's get it done, right away!",
	vote = "",
	drop_descrip = "Kizuna AI here, wearing a dress, coming at you! Be it concert or combat, I'll give it my all!",
	feeling4 = "Hey, Commandeeeer! What's up? Huh? You've already prepared a stage and everything?! Holy cow! I just gotta focus on practicing my skills? ... W-wow, you seem like a super capable guy, Commander!",
	lose = "... I'll make up for it at my next concert!",
	feeling1 = "Relax, I'm not inviting you to my concert anyway.",
	skill = "Listen to my song!",
	upgrade = "Strengthening complete! ♪ You know, concerts and battles both take a lot of strength!",
	propose = "Moving in synch with the others, singing, dancing, and smiling! That's what a concert's about. That's the image in my mind... Thank you so much, Commander! But, of course, this doesn't mean the end! Let's go, Commander! I'm counting on you!",
	feeling5 = "We totally nailed that concert! I'm so glad you were there to help. Oh, right! I've got a special song just for you. Please lend me your ear!",
	main = "That was great, Z35! Oh, hi, Commander! I just got to hear Z35 practice her singing!|Check it out, this thing is so flappy! You want me to jump? Too bad for you this isn't a skirt.|Huh? You think I'm cute? Uh-huh! I already knew that, but thanks!",
	touch = "Oh, are you requesting a song? Sure thing, what do you wanna hear? I'll sing it for you!",
	voice_key_2 = -1,
	mission_complete = "Let's go get those mission rewards! Do you think we'll get anything good?",
	battle = "Let's build some hype for this battle!",
	id = 10400030,
	gift_dislike = "",
	gift_prefer = "Wow, a present! Thanks~!",
	profile = "This is the costume I wear for my concerts! I hope one day this port will be able to host a concert, too!",
	voice_key = 1040003,
	headtouch = "",
	feeling2 = "I wanna host a concert here at the port! Could you collab with me on it, Commander?",
	login = "Welcome back! I got some singing lessons from Saratoga in preparation for my next concert. Give me your ear for a sec!",
	detail = "What type of music do you listen to, Commander? I have a great artist recommendation for you! Her name's Kizuna AI... Oh wait, that's me!",
	couple_encourage = {
		{
			{
				20112
			},
			1,
			"Chunechune, I'll keep you safe!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[10400040] = {
	hp_warning = "Oh, crap...",
	feeling3 = "Huh? Stream a horror game? No, I don't want to... I really, really, really don't want to!",
	mail = "Hey, we've got mail! Maybe it's a present from the publishers!",
	expedition = "The commission team is back. Start another one immediately! We don't want to waste time!",
	win_mvp = "A winner is me! I'm the MVP!",
	home = "Great performance, Commander! Huh? You want a lap pillow? ... Fine, fine. Inazuma babies you too much. Whatever, go ahead and let your guard down. Inazuma, do the next one for me.",
	unlock = "HAI DOMO! Virtual Gamer Kizuna AI here! Don't worry, Commander, I've played AL a whole bunch before! ... Wait, I've become a ship now?!",
	touch2 = "Commander, do you know what a \"headshot\" is? Mind if I perform one on you?",
	mission = "Mission located! Let's do tons of them so we'll earn a boatload of money!",
	vote = "",
	drop_descrip = "HAI DOMO! Virtual Gamer Kizuna AI here! Don't worry, Commander, I've played AL a whole bunch before! ... Wait, I've become a ship now?!",
	feeling4 = "Damn it all! Why are my horror game streams so popular?! I have you to thank for suggesting it, but... please suggest a less scary game next time!",
	lose = "Okay, I'm getting ticked off now! I'm not forgetting this, ever!",
	feeling1 = "AAAaaaaAAAAAaaaaaAAAAAAHHH!!!111!eleven!!",
	skill = "Here I go! Ba-biiiing!",
	upgrade = "Technically, I am an aimbot!",
	propose = "You got this ring just for me, didn't you? I'm so happy! Er! Actually, I meant I'm really grateful! ... I can't wait to hear you talk about games every day from now on! And thanks for all your help!",
	feeling5 = "You're such a good game explainer, Commander! You know about all sorts of games, and nobody will call me a noob A.I. with you by my side! ... I'm counting on you, Commander!",
	main = "Maybe I'll host the Kizuna AI Cup here! Ayanami and Long Island said they'd be down, so why not be our 4th player, Commander?|Being a genius but in reality playing like a total noob is suffering...|Whoosh! What do you think about this pose I learned from Jamaica? Don't I look cool?",
	touch = "You wanna play a round with me? Certainly! I accept your challenge! My skill should not be underestimated!",
	voice_key_2 = -1,
	mission_complete = "Mission complete! Let's see what we got! Hm? What's up, Ikazuchi? You what? Secretaries can't collect mission rewards?!",
	battle = "Let's fakkin' do this! Grraaaaagghh!",
	id = 10400040,
	gift_dislike = "",
	gift_prefer = "Thanks so much! Commander, you have pretty great taste!",
	profile = "My hair? Heheh, I'm virtual so I can change my hair's length whenever I want. How else do you think I look this cool while I'm fraggin' out? I'm the super gamer version of Kizuna AI! Check it!",
	voice_key = 1040004,
	headtouch = "",
	feeling2 = "It's not easy to be a streamer. I try as hard as possible, but people still call me a noob... What should I do to get better?",
	login = "You haven't forgotten about the monthly check in, right? That'd be a real noob move!",
	detail = "Are you here to play a game, Commander? I was just about to start streaming one, actually! Would you like to play it with me?",
	couple_encourage = {
