_G.pg.base.ship_skin_words[10600040] = {
	hp_warning = "This is just the beginning!",
	feeling3 = "Everyone looks extraordinary when fighting, but I guess they're really just normal girls when they're not. I've even found some friends who like comic books, heheh.",
	mail = "Commander, you've got mail. Come take a look!",
	expedition = "The commission team's returned! I wonder if they brought back some sweets~",
	win_mvp = "We won! Woohoo, a V for victory!",
	home = "Oh, Commander, nice work on that last battle! Now, how about a short break?",
	unlock = "It's nice to meet you! From what I've heard, you're the \"Commander,\" right? I'm Misaki. I have experience with various part-time jobs, so... I'm confident that I can be of help to you all. Let's do our best!",
	touch2 = "Wah?! Geez, I'll be really angry if you do that again!",
	mission = "Commander, you've got new missions! Don't we get rewards for completing them?",
	vote = "",
	drop_descrip = "It's nice to meet you! From what I've heard, you're the \"Commander,\" right? I'm Misaki. I have experience with various part-time jobs, so... I'm confident that I can be of help to you all. Let's do our best!",
	feeling4 = "Apparently, there's a two-for-one deal at the store for bubble milk tea right now! Two might be a bit too much for me, though... Commander, if you're free, do you want to go with me?",
	lose = "We lost... I can't believe it...",
	feeling1 = "This port might be an interesting place, but you? You're not very dependable... I guess the responsibility for whipping you into shape falls on me, the part-timer~",
	skill = "Keep your eyes on me!",
	upgrade = "What do you think? Can you feel my growth?",
	propose = "Ever since I've arrived at this place, you've taken such good care for me. I can't believe that I'm about to receive something this precious from you... Thank you, Commander! I'll work even harder for you!",
	feeling5 = "Commander, let's go to the dessert store~ Afterward, we can take a stroll together! I want to learn more about this place! And then, after that... um... Well, let's just get going!",
	main = "If you've got nothing else for me to do, I'm gonna head off to my part-time job... wait, I guess this is one, too...?|Mm~ I could go for some sweets right about now. Maybe a crêpe or something...|My sister might be scary at times, but she's a nice person at heart! ...Though, she might be a bit on the overprotective side...",
	touch = "Yeees? Did you call for me, Commander?",
	voice_key_2 = -1,
	mission_complete = "Mission complete! Commander, don't forget to give me my share of the rewards! Oh, I'm just pulling your leg! Ahaha!",
	battle = "Aaaaall right! When you do something, you gotta do it right!",
	id = 10600040,
	gift_dislike = "",
	gift_prefer = "Wow, amazing! Can I really have this?",
	profile = "You want me to introduce myself? I'm Misaki, and my hobbies include scuba diving, stargazing, and... reading comics, I guess. Also, I really like mango vanilla crêpes and bubble milk tea! Oh, right, and... be nice to my sister, Nagisa!",
	voice_key = 1060004,
	headtouch = "Hey, um... This feels odd to me...",
	feeling2 = "So, I can drash across the ocean if I put this rigging on? The wonders of technology, huh!",
	login = "Commander, hurry up~ Let's get to work, shall we?",
	detail = "I get these weird vibes from this port and the shipgirls that live here... But most of all, I get them from you, Commander. Oh, I'm just messing with you! Ahaha!",
	couple_encourage = {
		{
			{
				30110
			},
			1,
			"Sis? Oh, never mind...",
			0
		},
		{
			{
				1060005
			},
			1,
			"I can take care of myself, so focus on yourself, sis!",
			0
		}
	}
}


