_G.pg.base.ship_skin_words[10600080] = {
	hp_warning = "Not yet... I'm not done yet.",
	feeling3 = "Excuse me, Commander? Can I have a minute? Umm... I wanted you to be interested in me, too...",
	mail = "You got a letter. Information is important, you know.",
	expedition = "Everyone just came back. Heheh, I can't wait to hear their stories.",
