	feeling1 = "Sorry, I'm just thinking. Wait a minute... okay?",
	skill = "What do you think of... this?",
	upgrade = "Hmm... I can feel my power growing. Very interesting...",
	propose = "This world is very intriguing. No matter how much I research, there's always more to uncover. But Commander... I'm so much more interested in your heart, yet I can't figure it out... I need you to teach me more.",
	feeling5 = "*stare*... Hmm, I see. Heheh, I never tire of observing you, Commander. In fact... I only end up more intrigued. You are... an incredible research subject.",
	main = "Being able to walk on water... is very intriguing. Commander, let us research this vast expanse of ocean.|Does this world do 3 AM snacks? ...Hmm, good. Then you're certain to have a 5 AM roasted sweet potato tradition, too. ...I'm kidding.|So many books I've never seen before... I'll never have the time to read them all. I can't wait.|A nutritional drink? Well, thank you, Myoukou... Not that it'll fill my belly.|You'll get me equipment for recording and adventuring, Akashi? Yay... That'll make this so much easier.",
	touch = "...Hm? Do you have business with me? No, I mean... I guess it's okay if you don't, Commander.",
	voice_key_2 = -1,
	mission_complete = "...Finished your work? Then that means it's time for field work.",
	battle = "Luna joins the battle.",
	id = 10600080,
	gift_dislike = "",
	gift_prefer = "Hehehe... So cute. I'm... very happy. Simply... overjoyed.",
	profile = "Hippity, hoppity... Did I look like a bunny? Sorry, but my name is Luna... Hop. I'm a scholar and a Venus, and I like roasted sweet potatoes and bunnies. Commander, will you accompany me on my field work? ...Hop.",
	voice_key = 1060008,
	headtouch = "...Hm? What's the matter? Is it roasted sweet potato time?",
	feeling2 = "Heheh. I think I'm starting to get you as a person, Commander. But you're still... very intriguing.",
	login = "Good morning. Is it time for breakfast?",
	detail = "Commander, I like this place. The food is good, and it's full of interesting things... I'm happy here.",
	couple_encourage = {
		{
			{
				31201
			},
			1,
			" Kitty... Can you help me prepare for my next round of field work?",
			0
		},
		{
			{
				10703
			},
			1,
			" I wanna compare answers... Do you have time after the battle?",
			0
		}
	}
}


