_G.pg.base.ship_skin_words[10600090] = {
	hp_warning = "You've seen nothing yet!",
	feeling3 = "Oh, Commander♪ Perfect timing♥ I missed you, you know. Stay for a while, will you?",
	mail = "There's a letter here. And it's for you, it seems. Who could it be from?",
	expedition = "Looks like those girls are back from their errand. Come on, let's go greet them♪",
	win_mvp = "Ahahah! I put on a captivating show, didn't I?",
	home = "Welcome back, Commander. Good going out there. Now how about I give you a massage?",
	unlock = "Hmm? Where am I? Ohh, I get it now... I drank way too much yesterday... Ahahah. Oh well♪ There's tons of cuties here to keep me entertained❤ My name's Tamaki. It's a pleasure, Commander❤",
	touch2 = "Eep! Commander, please... We're still on the clock. Control yourself.",
	mission = "You've still got a lot of work to do... Want a hand?",
	vote = "",
	drop_descrip = "Hmm? Where am I? Ohh, I get it now... I drank way too much yesterday... Ahahah. Oh well♪ There's tons of cuties here to keep me entertained❤ My name's Tamaki. It's a pleasure, Commander❤",
	feeling4 = "Why are you standing there all speechless? Don't tell me... you're stunned by my beauty? Heehee. I'll make an exception for you – stare all you want♪",
	lose = "Hmm. I guess I was in over my head...",
	feeling1 = "Hm? Sorry, I'm busy right now. Come back later.",
	skill = "You'll want to see this!",
	upgrade = "Heehee♪ Thanks♥ You're helping me become even more beautiful.",
	propose = "Heeey! Commander! C'mere! Way to make me wait. Did you want me to get drunk all alone? You've gotta make up for this, and I won't take no for an answer♪ Heehee♪ Cheers♥",
	feeling5 = "I'm in love with this wonderful place. There's all these cute girls... and they're led by a cute Commander. Oops, you didn't hear that♥",
	main = "Oh, enjoying a break, Commander? I enjoy a bit of downtime as well. I know – how about we get comfortable together?|The sea breeze feels nice, but it's pretty terrible for your skin. I wonder if there's some sort of remedy to it?|Mmgh... This warm sunshine is making me sleepy... Don't you think we could have a nap after we finish this work?|Sure is hot today... Hm? A tea party to cool off? Sounds perfect! You're so considerate, Ms. Head Maid!|Incredible swordsmanship, Takao... Dare I say, you're also pretty hot♥ Why don't you sit down and enjoy a drink with me?",
	touch = "Hm? What is it? If you need something, you can tell me anything that's on your mind♥",
	voice_key_2 = -1,
	mission_complete = "Seems you've finished a job. Be sure to claim your rewards.",
	battle = "Let's show them what we're made of!",
	id = 10600090,
	gift_dislike = "",
	gift_prefer = "Wow! Thanks! I just can't resist presents♪",
	profile = "My name is Tamaki. I'm an ex-model turned fashion designer, and I do Venus work. My favorite things about my job are the pretty clothes, and moreover, the cute girls, I suppose♥ If you want to know more... I'll tell you after a few drinks♥",
	voice_key = 1060009,
	headtouch = "Oh, a pat on the head? If this is my reward, I'd like something... different♥",
	feeling2 = "Are you on the clock, Commander? You poor thing. Don't overwork yourself now, okay?",
	login = "Good morning, Commander. My, you look rather tired. Need something to wake you up?",
	detail = "Commander, if you're free, how about grabbing a few drinks? Take me to a place that serves some good liquor♥",
	couple_encourage = {
		{
			{
				10705,
				10710
			},
			1,
			" I've heard you can hold your liquor! Let's get drunk someti– Hey! Why are you stopping me?",
			0
		},
		{
			{
				30702
			},
			1,
			" Word is, you're hiding some exquisite plum liquor! Let me have a taste!",
			0
		}
	}
}


