	id = 10600101,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "There's no need to rush. Relax a little, why don't you? I'm not going anywhere.",
	detail = "I'm happy that you like my swimsuit, but it is a little embarrassing... Yes, you can look at it closer later when we're alone.",
	couple_encourage = {}
