_G.pg.base.ship_skin_words[10600110] = {
	hp_warning = "I'm not giving up yet... Kon!",
	feeling3 = "Thanks for inviting me out today, Commander... Yeah, I can't wait. Where should we go?",
	mail = "This is a letter for you... Read it.",
	expedition = "The girls came back from their errand. Go welcome them home, okay?",
	win_mvp = "Oh, we win... Kon!",
	home = "Welcome back, Commander. The kitties and birds said you had a rough day... Are you okay? Come over and rest.",
	unlock = "Don't get caught, don't get your cover blown... Hide carefully... Ack, I'm sorry! I'll leave right away... Hm? My ears and tail? Oh, I'm just cosplaying a fox, haha... Wait, did you say there are other girls like me around here? Okay... Umm, my name is Shizuku, and I'm a fox spirit. You mind if I stay here for now...?",
	touch2 = "No... Stop that. Even I'll get mad if you keep that up.",
	mission = "Commander, I think you still have work left... Kon.",
	vote = "",
	drop_descrip = "Don't get caught, don't get your cover blown... Hide carefully... Ack, I'm sorry! I'll leave right away... Hm? My ears and tail? Oh, I'm just cosplaying a fox, haha... Wait, did you say there are other girls like me around here? Okay... Umm, my name is Shizuku, and I'm a fox spirit. You mind if I stay here for now...?",
	feeling4 = "Do you like my tail...? Really? Then it was worth taking such good care of it. I'm happy you like it.",
	lose = "I'm a fox, not a prey animal...",
	feeling1 = "Mm... Sorry. I wasn't thinking of you.",
	skill = "I'll show you a kitsune's power...",
	upgrade = "My power is rising... This is incredible... Kon!",
	propose = "You're a strange person, Commander. But... You're also a kind person, especially to me. So it makes me happy to be with you... Kon!",
	feeling5 = "When I came here, I was all alone again... But you found me when I was terrified, and you became my friend... It made me really happy. I hope you'll let me stay with you longer.",
	main = "Everyone here is really nice. They don't even say anything when they see my ears... I feel really at ease... and happy here. Kon!|I like how quiet it is here. It's also clean, and the food is delicious... It wouldn't be right to do nothing, so I need to find a way to help out.|There are lots of people with big ears here. I thought they were all cosplayers at first, but they're not... It's incredible.",
	touch = "Mm... Your hands are chilly. It feels nice... Kon...",
	voice_key_2 = -1,
	mission_complete = "That's a lot of stuff... Are these the rewards from your work?",
	battle = "Cheer up. We can win... I know it.",
	id = 10600110,
	gift_dislike = "",
	gift_prefer = "Umm... I'm really happy. Kon!",
	profile = "Shizuku... That's my name. Are you curious about my ears and tail? It's just a cosplay... Okay, fine, they're real. I know you saw through me right away, but when I saw the people at this port... I realized that having fox ears and a tail isn't weird at all.",
	voice_key = 1060011,
	headtouch = "This is just a cosplay, so... Huh? You think it looks real? Have you ever actually touched a fox...?",
	feeling2 = "Found you, Commander! Can we hang out today? Yeah, I'm happy as long as I get to be with you... Kon!",
	login = "Good morning, Commander. It's another wonderful day... Kon!",
	detail = "You didn't introduce me to everyone as a fox cosplayer, but nobody even batted an eye... This place must be really accepting.",
	couple_encourage = {
		{
			{
				1060012
			},
			1,
			"Are bartenders... strong?",
			0
		},
		{
			{
				1060013
			},
			1,
			"Tsukushi... Would you like to cosplay with me?",
			0
		},
		{
			{
				30227
			},
			1,
			"Minase, let's do it together... Kon!",
			0
		}
	}
}


