	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 10600111,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Huh? You can see my tail? But this is a secret hideout, so nobody can see us... Besides, nobody here minds, so... Kon!",
	detail = "In places like this, I can see lots of little fish that usually hide out of sight. But I'd better be careful not to slip on the wet rocks...",
