_G.pg.base.ship_skin_words[10600120] = {
	hp_warning = "Now that you've gotten my attention... let's see who's the last one standing.",
	feeling3 = "Do you ever get bored with me... No? You have a lot of fun? That makes me feel better.",
	mail = "Commander, you have some paperwork here... Heehee, I feel like a secretary.",
	expedition = "Commander, your friends are back. What will you do?",
	win_mvp = "Oh... Is that all? Really?",
	home = "Welcome back, Commander. Huh? You think it's rare for me to come out to greet you? Heehee, then today must be your lucky day!",
