	expedition = "The commission team has returned to port. What diligent girls they all are.",
	win_mvp = "We've finished! How is everyone? No bruises or scratches?",
	home = "Welcome back, Commander. Would you like some tea and a snack while you rest?",
	unlock = "Why hello, my name's Azusa Miura~ Um, this is a port, right? And these are... shipgirls? Um~ Where exactly am I?",
	touch2 = "Eek! What was that for, Commander?",
	mission = "My, oh my. We still have work to do. Let's tackle them one at a time.",
	vote = "",
	drop_descrip = "Why hello, my name's Azusa Miura~ Um, this is a port, right? And these are... shipgirls? Um~ Where exactly am I?",
	feeling4 = "Oh, Commander, perfect timing. I had some free time and cooked up some food, but I wound up making way too much. Care to join me for dinner?",
	lose = "Is everyone okay? We should find a safe place to retreat to, quick!",
	feeling1 = "Sorry, I just... I just don't know what to talk about with you.",
	skill = "I hope you'll all enjoy this next song!",
	upgrade = "Thank you for helping me grow, Commander.",
	propose = "I don't know if it was my destiny to come here and meet you and the girls under your command, but I'm glad I did, and I'll treasure this memory always.",
	feeling5 = "Sorry that I always make you lead me around the port. I've just gotten so reliant on the comfort of having you show me the way when I get lost... Hehehe~",
	main = "Some destroyers came up to me the other day and wouldn't let me leave until I played a game with them. Hehehe~ Everyone here are such lovely people.|I have a poor memory for directions, so I often get lost. I've already needed people to come find me several times at this port... It's quite awkward for me.|You have so many types of cuisine on offer in the cafeteria. And they all taste so delicious... I need to watch it so I don't overeat.",
	touch = "My luck forecast for today is... Oh? Would you like your fortune read too, Commander?",
	voice_key_2 = -1,
	mission_complete = "Hehe~ Job completed. Excellent work.",
	battle = "Fighting is by no means my forte, but I'll do the best I can.",
	id = 10700040,
	gift_dislike = "",
	gift_prefer = "Hehehe. I am very fond of this~. Thank you very much, Commander.",
	profile = "My name is Azusa Miura. I decided to debut as an idol after graduating junior college. As for the specific reason why I chose this career... I suppose it was in hopes I'll one day find the person of my dreams.",
	voice_key = 1070004,
	headtouch = "My, oh my~ Is there something on your mind, Commander? I can lend an ear if you'd like to talk about it.",
	feeling2 = "What is it, Commander? ...Ah, you found my lost handkerchief? Thank you so much.",
	login = "Good morning, Commander. Let's have a good day of work, shall we?",
	detail = "You'd like to chat with me? Of course we can do that. Please, have a seat.",
	couple_encourage = {
		{
			{
				1070005
			},
			1,
			"Oh dear. What is this place, Ritsuko?",
			0
		},
		{
			{
				1070002
			},
			1,
			" Let's do our best, Chihaya!",
			0
		},
		{
			{
				1070003
			},
			1,
			"Oh dear... Wait for me, Iori!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[10700041] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome back from the summer heat, Commander. I'll get you a bottle of cold tea.",
	unlock = "Listening to the wind flow through the chimes on the porch seems to carry the summer heat right away. Commander, would you also like to come unwind with me?",
	touch2 = "Are you okay, Commander? You look like you're suffering from a heatstroke... Wait here. I'll fetch you some ice and a sports drink right away.",
	mission = "",
	vote = "",
	drop_descrip = "Listening to the wind flow through the chimes on the porch seems to carry the summer heat right away. Commander, would you also like to come unwind with me?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "As much as I love cooling off in an air-conditioned room, it's also nice to sit on the veranda and just feel the breeze.|Oh dear, the winds have died down. Then I'll instead use this paper fan to help you keep cool, Commander.|There are many kinds of wind chimes in the world. Some are made of metal, others are made of glass. I enjoy listening for the slight differences in sound between them all.",
	touch = "This yukata feels so much breezier than the clothes I usually wear. I recommend trying one for yourself, Commander.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 10700041,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Whew, it's so hot today. Make sure you drink plenty of water so you don't get dehydrated.",
	detail = "Oh! Thank you for coming all this way in the blistering heat. Let's see... I should have something cool to snack on in the fridge.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[10700050] = {
	hp_warning = "I'm not giving up until it's over...!",
	feeling3 = "Well done today, Commander. You're keeping yourself busy as always. Say, do you need help with something? I've got some spare time right now.",
	mail = "There's new mail for you. Best to read it now, before you forget.",
	expedition = "Those girls are back from their commission. Hellooo? It's time to get up and welcome them back, Commander!",
	win_mvp = "We've completed the job. Just as I predicted!",
	home = "Good to see you back, Commander. Take a moment to relax before our next task.",
	unlock = "Pleased to meet you. My name is Ritsuko Akizuki. I was wondering what was going to happen to me when I suddenly got blown away, but... In any case, I'm pleased to make your acquaintance!",
	touch2 = "Commander! Your time is better spent on doing work than doing... that!",
	mission = "There's still work left for us to do! Chop-chop! Let's wrap it up quick!",
	vote = "",
	drop_descrip = "Pleased to meet you. My name is Ritsuko Akizuki. I was wondering what was going to happen to me when I suddenly got blown away, but... In any case, I'm pleased to make your acquaintance!",
	feeling4 = "Your job description has a lot in common with that of a producer's. I feel I could learn new things by watching you, actually... Would you mind letting me do that, when you have time?",
	lose = "I suppose this means my prediction was wrong... I'll have to fix the kinks in the system!",
	feeling1 = "What about our last concert could we improve on...? Oh, excuse me, but I don't have the time right now.",
	skill = "It's showtime!",
	upgrade = "Steady progress! Everything is going exactly according to plan!",
	propose = "The things I've learned here will prove invaluable for my career, moving forward. So, allow me to say it once again: Thank you for everything, Commander!",
	feeling5 = "I've learned so much and gained experience I never would've otherwise by watching you work. I feel my horizons have expanded to the point I can come up with novel new strategies!",
	main = "Oops. Sorry for spacing out, Commander. I'm juggling several things at once right now...|It's good we all came here together, but that means things are as hectic as ever... Hey! Ami! Mami! Get back here! What are those shovels for?!|If we spruce up our choreography a bit, it should take our performance to the next level. Let's do it! We'll rehearse it for our next show!",
	touch = "You need a hand with your work? Of course! I'll make sure everything comes out looking flawless!",
	voice_key_2 = -1,
	mission_complete = "Great! You've finished that task. Don't forget to claim the rewards.",
	battle = "Everyone, let's stay sharp!",
	id = 10700050,
	gift_dislike = "",
	gift_prefer = "Now that's my commander♪ You know exactly the kinda things I like, don't you?",
	profile = "My name's Ritsuko Akizuki. I always give everything my best shot! And that includes working as an idol at this port. On a related note... Wow, you have a lot of shipgirls with potential starpower!",
	voice_key = 1070005,
	headtouch = "Goodness gracious, your hair is even messier than mine, Commander. Please, for your own sake, pay a little more attention to your appearance!",
	feeling2 = "Ah, Commander! Just who I was looking for. Do you have a full-length mirror anywhere? I could really use one for dance rehearsal.",
	login = "Let's have a look at our schedule and see what we have to do today, Commander.",
	detail = "It's important you closely read an idol's bio to grasp all her strengths. Take all the time you need.",
	couple_encourage = {
		{
			{
				1070007
			},
			1,
			"Mami! No more mischief, got it?",
			0
		},
		{
			{
				1070004
			},
			1,
			"Where have you been, Azusa?!",
			0
		},
		{
			{
				1070001
			},
			1,
			"Haruka, your could improve you choreography by doing it more like... This!",
			0
