_G.pg.base.ship_skin_words[10700060] = {
	hp_warning = "The legend of Ami Futami has only just begun!",
	feeling3 = "Let's see... Let's put a blackboard eraser above the door to the office, and a toy rat on the chair... Woaoh! You're already back, Commander?! Tsk. Foiled again~",
	mail = "It seems like there's some new mail~ You listening, Commander~?",
	expedition = "Everyone did a good job returning safely! I should go and praise them!",
	win_mvp = "Did you catch that? My shiny performance?",
	home = "Good job beating'em, Commander! I'm beat, too~ Let's have a snack break~",
	unlock = "Nihihi! I'm the idol, Ami Futami! This place seems awfully lively, just perfect for pranking~! See you around, Commander!",
	touch2 = "Ohoho~ So you're that kind of person after all~?",
	mission = "By any chance, is there still work left? If you don't hurry up and finish... Boss, the day's going to be over.",
	vote = "",
	drop_descrip = "Nihihi! I'm the idol, Ami Futami! This place seems awfully lively, just perfect for pranking~! See you around, Commander!",
	feeling4 = "Yeah yeah. Commander, I'm going to mimic your expression right now! ...Huh, it's not similar at all? That's strange~ When I showed my impression to everyone else, they said it was super similar~",
	lose = "Uh oh! My HP gauge is red!!! Retreaaat!",
	feeling1 = "It's hopeless... We can't clear the stage like this, Commander~ ...Please work a bit harder, Commander~",
	skill = "Tremble in the face of my power!",
	upgrade = "Level~up! Thanks, Commander!",
	propose = "You know, showing up here, and playing with you and the others has been super fun for me~♪ I'll be relying on you to keep me entertained in the future as well, Commander!",
	feeling5 = "Nihihi~ Who do you think this is! ...Eh, Ami? You're correct~! As expected of the Commander! As a prize, I'll share some of my sweets with you~",
	main = "There are so many people at the port~! I wonder who I should prank next~♪|Yay!!! I pulled an SSR!!! I feel crazy lucky today~☆|Hey hey, Commander~ ...Hmm? What am I going to be doing with this broom? Fufufu~ That's a secret, of course♪",
	touch = "What's that? You're going to play with me? What a boss!",
	voice_key_2 = -1,
	mission_complete = "Mission complete~! Don't you think I worked pretty hard too?",
	battle = "Who's next on the chopping block~?",
	id = 10700060,
	gift_dislike = "",
	gift_prefer = "This is one of my faves! That's my Commander!",
	profile = "The name's Ami Futami. Mami's my twin. Sometimes, I swap places with her for the day~ To tell you the truth, I might not be Ami, but actually Mami... Teehee~♪",
