_G.pg.base.ship_skin_words[10900010] = {
	atelier_yumia_shop_5 = "",
	mail = "A letter's come in! I wonder what's in it~",
	dal_shop2 = "",
	ryza_item4 = "Gotta be careful so this doesn't overload my rigging.",
	ryza_item3 = "I think I saw a yellow bird take off holding one of these...",
