	atelier_yumia_item_1 = "",
	atelier_yumia_shop_1 = "",
	asmr_008 = "",
	atelier_yumia_item_8 = "",
	gift_dislike = "",
	asmr_001 = "",
	atelier_yumia_item_12 = "",
	detail_replace = "",
	dal_shop5 = "",
	gift_prefer = "Whoa, I think I can make something really amazing with these materials! Thanks, I'll put them to good use!",
	atelier_yumia_shop_3 = "",
	headtouch_replace = "",
	headtouch = "Oh! It's a barrel!",
	feeling2 = "Mm, what a wonderful day! Let's go explore for something new and exciting!",
	atelier_yumia_shop_2 = "",
	mission_complete_replace = "",
	login = "Oh, it's you, Commander! What new adventures will we go on today?",
