_G.pg.base.ship_skin_words[10900060] = {
	hp_warning = "Oh ho. Perhaps it's finally time for me to get serious again!",
	feeling3 = "The time is nigh to break our fast. Commander, why don't you take me somewhere I can sate my appetite?",
	mail = "Oho. Commander, you've got mail. A love letter, perhaps... What? It's not?",
	expedition = "Your errand girls have returned. How I yearn to hear their stories.",
	win_mvp = "Quaint little foes, wouldn't you say so?",
	home = "Well, then... Perhaps I ought to organize the things I found during our travels.",
	unlock = "Oho. What sort of interesting person would summon me? My name is Kala Ideas, and I am the chief of the Wave Tuner clan. Perhaps I shall sojourn in this world for a spell, just as you desired.",
	touch2 = "I've lived long enough now that it'll take far from this to disturb me...but I think a tongue-lashing is in order.",
	mission = "It seems you have some unfinished missions. What will you do about them, I wonder?",
	vote = "",
	drop_descrip = "Oho. What sort of interesting person would summon me? My name is Kala Ideas, and I am the chief of the Wave Tuner clan. Perhaps I shall sojourn in this world for a spell, just as you desired.",
	feeling4 = "Traveling to another world seems to shatter one's \"common sense.\" But oddly...that isn't so bad an experience.",
	lose = "...These otherworldly fiends put up a surprising fight. Retreat seems to be the best course of action.",
	feeling1 = "You bore me...",
	skill = "Hah! Prepare thyselves!",
	upgrade = "Few can put me to such good use. You have my thanks, Commander.",
	propose = "Wh-what an exquisite item...! So this is a symbol of your sincerity? Very well. If it means so much to you, then I'm not one to refuse. As you wish, I will remain here and watch how this world changes for some time.",
	feeling5 = "Heehee, this place is full of such interesting folk. I never tire of watching them... Oh, but of course, you are the most interesting of all. Heehee! Is it a relief to hear that?",
	main = "Aha. So these little creatures are called Meowfficers? I've seen nothing of the sort in my own world... but they are such adorable things.|All the world's cultures gather in this port. The stories shared by all are truly fascinating.|Say, are there any dealers of rare curios in this port? Goodness! Then I must pay them a visit. Mind showing me the way, Commander?|Hah! How adorable it is to see someone who can't be true to her feelings. Take this advice from your elder: be sincere if you want your thoughts known.|A superior who looks after many... Heheh, I think you and I will be good friends. Come, why don't we chat over tea?",
	touch = "This port is brimming with young ladies. Say, Commander, which is your... Oh? Is that topic taboo? Your life isn't an easy one, I see.",
	voice_key_2 = -1,
	mission_complete = "That mission must have been quite successful if these rewards are anything to go by.",
	battle = "Heehee. Who wants to face me next, hmm?",
	id = 10900060,
	gift_dislike = "",
	gift_prefer = "Ohh! You know me well, don't you? Thanks so much, Commander! You have my praise!",
	profile = "I am Kala Ideas, chief of the Oren Songwave clan. The circumstances of my arrival may have been out of my hands, but a world with culture and history beyond my knowledge is fascinating indeed. I have been enjoying my time here.",
	voice_key = 1090006,
	headtouch = "So you wish to treat me like a child, too? Say... I suppose I could use some exercise. Have at you!",
	feeling2 = "Hrm. Suppose I ought to explore the port today. Commander, do you wish to join me?",
	login = "Those who set upon their work so diligently are a rare breed indeed. What an interesting one you are.",
	detail = "What's that? You're curious about the curios in my room? Heheh, they are all extremely valuable artifacts collected over the years. I'm quite attached to all of them.",
	couple_encourage = {
		{
			{
				1090001
			},
			1,
			" A most curious alchemist you are, Ryza.",
			0
		},
		{
			{
				1090004
			},
			1,
			" Impressive, Whitefang comrade. How reliable!",
			0
		},
		{
			{
				1090005
			},
			1,
			" I pray that your dream becomes reality, Serri.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[10900061] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Hmm... So far, so good. Yet it's so time-consuming... We'll have to wait.",
	unlock = "I expected this sort of work to be effortless for me... but I see how wrong I was. It's not as simple as they say... Well? Are you just going to stand there and watch, or are you going to help?",
	touch2 = "Hmph. Do you think I can do nothing right? Or do you just want me to shove some of this cream in your mouth to shut you up?",
	mission = "",
	vote = "",
	drop_descrip = "I expected this sort of work to be effortless for me... but I see how wrong I was. It's not as simple as they say... Well? Are you just going to stand there and watch, or are you going to help?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Hmm. Meowfficers, will you be assisting me? Just don't stare too much – as long as you value your lives, that is.|This outfit? I'm told it's formal wear here. Hmm... You're not plotting something, are you? Why are you averting your eyes?|Wait here. You may try my homemade treats... What, you can't wait a sparse few minutes? As impatient as a child...",
	touch = "Oh... How in the world did cream get there? Should I be thanking you, or...?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 10900061,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "You came at just the right time! Get over here and assist me, now!",
	detail = "I never did much baking back in my old world as it was outside my duties. It may not be easy to see, but I'll have you know that I'm enjoying myself.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[11000010] = {
	hp_warning = "I-I think I should still be fine!",
	feeling3 = "Oh, Commander! If I may ask... could you teach me how to fight in your world? Ninjutsu is pretty hard to make use of on the open ocean, you see!",
	mail = "There's a message for you, Commander. Shouldn't you read it?",
	expedition = "Looks like the girls are back from their errand! Hats off to them all.",
	win_mvp = "Phew, I'm feeling kinda sweaty! Rigging doesn't rust from sweat, do they?",
	home = "There ya are! ...Wait, sorry! Welcome back, Commander!",
	unlock = "Hello! I'm Asuka, second-year student at the Hanzō Academy! Wait... this isn't the new shinobi base at all! This place is your port, you say? Okay then... Well, no matter where I end up, I'll always train as best as I can!",
	touch2 = "You know, your naughty touch reminds me of Kat.",
	mission = "What's this? You've still got unfinished missions!",
	vote = "",
	drop_descrip = "Hello! I'm Asuka, second-year student at the Hanzō Academy! Wait... this isn't the new shinobi base at all! This place is your port, you say? Okay then... Well, no matter where I end up, I'll always train as best as I can!",
	feeling4 = "It feels like you've always got your hands full, Commander. Do you ever take breaks? I'm a little concerned over you!",
	lose = "It's so over...",
	feeling1 = "*sigh*, I can't believe you...",
	skill = "Secret Ninja Art!",
	upgrade = "I've gotten even stronger! I think my training's paying off.",
	propose = "After fighting the Sirens alongside the shipgirls under your command, I've realized I'm just not up to scratch. I'm going to get much, much stronger, so please support me on the way there, Commander!",
	feeling5 = "I've started thinking there may have been a reason why I was sent to this world. It was to train here, to fight using a rigging... and yes, meeting you is a big part of it as well.",
	main = "I wish I could treat everyone here to my grandpa's sushi. I guarantee you they'd love it!|While I love shinobi outfits, these \"riggings\" you have in this world are just amazingly cool!|The food in this world tastes amazing every time I eat it. Even your snacks are delish! Better watch my intake, or I'll put on weight.|Practice ninjutsu together with you, Akatsuki? Yes, please!|Kinu, you look like you're skilled with a blade... Are you a swordmaster, by any chance?",
	touch = "Huh?! Kat?! ...Oh, it's just you, Commander. What is it? Do you need something?",
	voice_key_2 = -1,
	mission_complete = "Oh! Mission complete, Commander!",
	battle = "May the best fighter win!",
	id = 11000010,
	gift_dislike = "",
	gift_prefer = "Wow! Awesome!! Commander, thank you so much! I'll treasure this♪",
	profile = "I'm Asuka, second-year student at the Hanzō National Academy! I train daily to become the best shinobi I can be! Oh, and my favorite food is the futomakis my grandpa makes!",
	voice_key = 1100001,
	headtouch = "It's calming when someone pats your head, isn't it?",
	feeling2 = "We're short on a lot of supplies... Huh? Go shopping together? That would be great!",
	login = "Good morning, Commander! Let's give it our all today, like always!",
	detail = "Gosh, I'm starving. I miss grandpa's futomaki rolls. They're the best ever, I tell you!",
	couple_encourage = {
		{
			{
				1100002
			},
			1,
			" Ikaruga! I'll take the lead here!",
			0
		},
		{
			{
				1100003
			},
			1,
			" Homura, I'll prove I'm better than you in this world too!",
			0
		},
		{
			{
				1100004
			},
			1,
			" Yumi, cover me!",
			0
		}
	}
}


