_G.pg.base.ship_skin_words[11000070] = {
	hp_warning = "Ugh... I've got no choice... but to do this! This is where the real fight begins!",
	feeling3 = "I think my shinobi skills have improved here. That may be partly due to your help, Commander... I hope Lady Jasmine can witness this after I return home...",
	mail = "I've received several messages addressed to you, Commander... Would you like to review them right now?",
	expedition = "Wow, that's amazing... So this is what everyone uses to help guide them back home? ...Oh, and if this part here is glowing, that means...",
	win_mvp = "Ahh... My blood boils with victory!",
	home = "Well fought, Commander. What did you think of our last battle? Hopefully, we were able to be of some use...",
	unlock = "My name is Yūyaki... and I'm the leader of the Tohno Tengu Shinobi Group... To be honest, I'm not great around water... Bad things always happen when I'm around it... And this place is a whole ocean, right? What should I do...?",
	touch2 = "I'm not sure... that's proper conduct...",
	mission = "Do you still have work left to do? Your job is quite difficult, isn't it...",
	vote = "",
	drop_descrip = "My name is Yūyaki... and I'm the leader of the Tohno Tengu Shinobi Group... To be honest, I'm not great around water... Bad things always happen when I'm around it... And this place is a whole ocean, right? What should I do...?",
	feeling4 = "Don't you think you've been... coming on a bit strong recently? No, um, I'm not saying you shouldn't... If anything, I kind of like it... Um, forget I said anything...",
	lose = "S-sorry... I think... I messed that one up a little...",
	feeling1 = "I might've placed too much faith in you. That is something I'll have to reflect upon...",
	skill = "Ahaha! I'll cut you to ribbons!",
	upgrade = "W-woah... I feel power coursing through me!",
	propose = "Everyone here... and above all, you, Commander, showed me acceptance... I've come to realize, that is truly the most valuable treasure. The things that've happened here have taught me how bonds between people are formed and strengthened.",
	feeling5 = "Commander, thanks to your mindfulness, I feel like... we've been able to move forward in a positive direction. Our ultimate goal is still to return home, and we're not going to give up on that, but... beyond that, we're glad to help you in other ways.",
	main = "Holding a weapon is scary... and it's not something I'm good at... But I'm not going to be able to fight otherwise, right?|I like animals a lot... but they don't seem to miss me a whole lot. Why do you think that is?|The warmer it is, the more nature flourishes... just as is the case with me.|There are lots of people here with silver or white hair, huh? I don't stand out much in comparison... Miss Belfast, you're also... very beautiful.|Miss Hiei, is that the fermented food you have here? Do you mind if I have a taste? ...Huh? That takes bravery? If you put it that way, I'm sure I'd have even more regrets if I don't at least try it...",
	touch = "People in the village always used to comment on how white and beautiful my hair is... What do you think, Commander?",
	voice_key_2 = -1,
	mission_complete = "You've already finished your work? Impressive, just as expected...",
	battle = "Heheheh... Just leave everything to me!",
	id = 11000070,
	gift_dislike = "",
	gift_prefer = "Commander, is this for me? Huh? Really?! No way... Thank you so much...",
	profile = "M-my name is Yūyaki... I'm the leader of the Tohno Tengu Shinobi Group. Um... I must say, this city is quite spectacular. It has so many big buildings and facilities... Huh? It's not a city, but rather a port? And it's your base of operations too? I see... Life can be full of unpredictable surprises...",
	voice_key = 1100007,
	headtouch = "Commander, do you... enjoy touching my hair?",
	feeling2 = "O-okay... But, that's still not enough... Eek! I, I'm so sorry! I wasn't watching where I was going... since I might've been lost in thought a little... I'll make sure to be more careful from now on.",
	login = "It's good to see you again. Let's... both give it our all today. Yes, me included...",
	detail = "There are so many things about this port that I don't yet understand. It would be terrible if I accidentally ended up wrecking it... Though, I'm sure that's nothing Miss Nachi can't resolve with some money...",
	couple_encourage = {
		{
			{
				1100005
			},
			1,
			" Fubuki! I'll show you the results of my training!",
			0
		},
		{
			{
				1100001,
				1100003
			},
			1,
			" Asuka, Homura... You two... are breathing perfectly in sync...",
			0
		},
		{
			{
				1100006
			},
			1,
			" Murasaki! Don't just clam up and disappear on us!",
			0
		}
	}
}


