	mission_complete = "",
	battle = "",
	id = 11000071,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Welcome back, Commander. Did you have any plans for the day? I don't mind keeping you company if you'd like...",
