_G.pg.base.ship_skin_words[11100020] = {
	hp_warning = "I-I'm getting mad!",
	feeling3 = "The port's tennis court is pretty nice. How about we go play a round together?",
	mail = "New mail just arrived. Want me to read it for you?",
	expedition = "Good work, everyone! Let me help next time, would you?",
	win_mvp = "Heheh! That's right, be grateful that I was here.",
	home = "Hi again. What sweet stuff did you bring back for me today?",
	unlock = "Uh-huh, so you're the Commander? I'm Nana, Lala's little sister. This port you've got here is pretty lively... Well, it was nice meeting you.",
	touch2 = "I said cut it out!",
	mission = "You've still got missions waiting. Is now the time to be slacking?",
	vote = "",
	drop_descrip = "Uh-huh, so you're the Commander? I'm Nana, Lala's little sister. This port you've got here is pretty lively... Well, it was nice meeting you.",
	feeling4 = "Wh-what do you mean, you're \"fine with flat\"?! Nobody asked, so keep your weirdo remarks to yourself, pervert!",
	lose = "H-hey, what the heck is going on here?",
	feeling1 = "So that's the kind of person you are...",
	skill = "Eat this!",
	upgrade = "Whoooa, awesome!",
	propose = "I accept that you're someone I can rely on, Commander. Let's stay together for a long time to come! Huh? No, I never said I LIKED you! Get over yourself!",
	feeling5 = "Thanks for coming to the zoo with me, Commander... Seeing all these cute animals really calms me down. I had a lot of fun today. Thanks again!",
	main = "The vibe here at port feels kinda lonely... I think it'd be more fun if you had more cute animals around! Man, I wanna meet some animals... Take me to the zoo, right now!|Commander, I see you staring at Momo... Wait, you think bigger is better, don't you?!|You're awfully quiet in front of me. It's suspicious... I'd better watch you closely. N-not that I'm enjoying watching you, or anything!|There are so many good swimmers here... Especially that I-25 girl. Her floppy bunny ears are too cute!",
	touch = "Hah! Dodged it. Don't underestimate me.",
	voice_key_2 = -1,
	mission_complete = "What's a mission reward? It's kind of like a game. Interesting...",
	battle = "Don't you worry. I'm right here with you, after all!",
	id = 11100020,
	gift_dislike = "",
	gift_prefer = "Huh? Can I really have this...? Thank you! I'm so happy!",
	profile = "Hm? Oh, I'm Lala's little sister, just like Momo. We came from Planet Deviluke. I can talk to animals! Also, if you do anything lewd around me, I'll hate you forever!",
	voice_key = 1110002,
	headtouch = "Hm? What's up?",
	feeling2 = "You might not be very reliable, Commander. I'll have to keep an eye out myself.",
	login = "Welcome back! Let's go for a walk or something, get some exercise. Gotta keep in shape!",
	detail = "I know everyone at this port loves you, but don't let it get to your head!",
	couple_encourage = {
		{
			{
				1110001,
				1110003
			},
			2,
			" Nice. With all of us here, this is in the bag.",
			0
