		{
			{
				1110004
			},
			1,
			" I'll show you what I'm made of.",
			0
		},
		{
			{
				1110006
			},
			1,
			" Let's do our best!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[11100021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Already done with your work? Then let's get back to it. Lala and Momo are waiting.",
	unlock = "There you are, Commander. I'm on a real hot streak today! Wanna come play with us and test your skills?",
	touch2 = "Not another touch, I mean it!",
	mission = "You can play AFTER you finish your missions.",
	vote = "",
	drop_descrip = "There you are, Commander. I'm on a real hot streak today! Wanna come play with us and test your skills?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Wow. You pick up on the rules fast, Commander. Do you play a lot of games? If so, let's play some more sometime.",
	main = "Luck's just another part of skill, you know. Winning games is too easy for me – ready to give up and accept defeat yet?|Heheh, I win again! Now you have to buy me snacks! ...Huh? You never promised that? Okay, then let's play again!|I could play with you all day, Commander! Oh, right, you have work... That's rough, buddy. Should I get Lala and Momo to help you?|Hey, so, I hear Long Island and Ayanami are good at video games... Does that make them good at card games, too? I dunno.",
	touch = "Whoa! You startled me... I was in the middle of thinking of a strategy!",
	voice_key_2 = -1,
	mission_complete = "While you're focused on missions, you might as well go and pick up your rewards.",
	battle = "",
	id = 11100021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "No peeking!",
	feeling2 = "",
	login = "Finally, you're here. We were just starting a new game... Come on, you know I'm not gonna let you get away.",
	detail = "What? Don't just stare at me. Or are you amazed by my skills?! Hah, you've got a good eye!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[11100030] = {
	hp_warning = "This is getting irksome...",
	feeling3 = "Everyone gets along so well here. That speaks to your impressive leadership, Commander.",
	mail = "I organized your new mail. Give it a read when you have time.",
	expedition = "The shipgirls who went out for commission work are back. Would you like for me to go help them?",
	win_mvp = "Yeah... I need to keep doing my best.",
	home = "Oh, welcome home! I cleaned up your office a little. I hope you don't mind...",
	unlock = "Hi there. You're the Commander of this port, right? I'm Momo Belia Deviluke, but you can just call me Momo. I look forward to fighting with you, and I hope we'll be best friends♪",
	touch2 = "My, my... That won't do, Commander.",
	mission = "You still have missions to do. Try your hardest for just a little longer, okay?",
	vote = "",
	drop_descrip = "Hi there. You're the Commander of this port, right? I'm Momo Belia Deviluke, but you can just call me Momo. I look forward to fighting with you, and I hope we'll be best friends♪",
	feeling4 = "Actually, I happen to have a certain... plan of my own. I'm sure it'll help you, but for now, it's my little secret.",
	lose = "I'm sorry, Commander.",
	feeling1 = "So this is the Commander who leads the port... How disappointing.",
	skill = "Don't underestimate my friends!",
	upgrade = "Oh, my... Have I changed?",
	propose = "In order to further our relationship... Yes, I need to execute my plan! Oh? You want to know what it is? Well, it's a genius plan... A plan to make everyone here love you even more!",
	feeling5 = "During our time together, I've begun to understand why all the girls here love you so much. This is indispensable information for the sake of my plan.",
	main = "How can you stay so calm when you're surrounded by lovely women all the time?|I love how fancy the port's café is. It even has plenty of video game consoles. If only it had a garden, it would be perfect.|Huh? Do I use my plants to monitor people? Ahaha~ Commander, your imagination is just wild. Of course I can't do that, silly.|Kiev of the Northern Parliament seems to really like cacti. Just recently, she had me teach her how to grow them.",
	touch = "Are you curious about my tail? Well, I suppose you can touch it...",
	voice_key_2 = -1,
	mission_complete = "Mission rewards? Once you get them, let's relax with some tea.",
	battle = "I'll do my very best not to disappoint the Commander!",
	id = 11100030,
	gift_dislike = "",
	gift_prefer = "Is this a present? Thank you very much.",
	profile = "I am Momo Belia Deviluke of Planet Deviluke, and I'm one of Lala's little sisters. Oh, and I can hear the voices of plants. I hope we can get along well during my time here.",
	voice_key = 1110003,
	headtouch = "Is something wrong? Do you need my help?",
