_G.pg.base.ship_skin_words[11100050] = {
	hp_warning = "...No!",
	feeling3 = "You're really sweet, Commander. You pay attention to me, help me when I need it... Thank you.",
	mail = "Remember to check your mail regularly.",
	expedition = "The commission team is back. Wanna go see them together, Commander?",
	win_mvp = "We won? Thank goodness! And thank you for your orders.",
	home = "Good work, Commander. You can go rest now. Leave the paperwork to me!",
	unlock = "Nice to meet you, Commander. My name is Haruna Sairenji. I'm going to be in your care for a while, but if there's anything you need my help with, don't hesitate to ask!",
	touch2 = "Eep?! We can't...",
	mission = "Make sure you don't forget your unfinished missions, okay?",
	vote = "",
	drop_descrip = "Nice to meet you, Commander. My name is Haruna Sairenji. I'm going to be in your care for a while, but if there's anything you need my help with, don't hesitate to ask!",
	feeling4 = "I had a lot of worries at first, but thanks to you and everyone else here, I feel a lot better.",
	lose = "I'm sorry, Commander... It's just so scary...",
	feeling1 = "Maybe this isn't a place I can rest easy in, after all...",
	skill = "I can do this! Yeah, I know it!",
	upgrade = "Do I feel stronger? I do. It's weird, though...",
	propose = "Is this proof that you've acknowledged me? Thank you! If there's anything else I can help you with, just tell me! I don't know how good at it I'll be, but I'll do my very best!",
	feeling5 = "At this point, I'd feel so bad saying goodbye to everyone. I care about Sainan, too, of course... but life here has been so fun. Let's keep making lots more memories together, okay?",
	main = "As a class representative, paperwork is kind of my specialty. But I'm willing to try other work, too. If I don't understand, could you teach me...?|Is Mary Celeste really a ghost? So ghosts really do exist...|Is it weird to walk around port in my school uniform? What do you think?|Lala's really taken to this place. I should do my best, too, so that I don't trouble the people of this world.",
	touch = "What's the matter, Commander? Oh, if you have time, let's chat for a while.",
	voice_key_2 = -1,
	mission_complete = "Your missions are all done! Good job. Get some rest.",
	battle = "I'm a little unconfident, but I'll try!",
	id = 11100050,
	gift_dislike = "",
	gift_prefer = "Thank you, Commander! I will treasure this.",
	profile = "My name is Haruna Sairenji. I'm a second-year student of Sainan High School, but somehow I've ended up here... Life here is different from how it was in Sainan, but I'm having fun. I like it.",
	voice_key = 1110005,
	headtouch = "Hm? Something wrong?",
	feeling2 = "I was worried that I wouldn't be able to get along with the people here, but with your help, I think I'll be just fine!",
	login = "Good morning, Commander. You've been busy lately, so I organized your work for today. Hopefully that helps.",
	detail = "This is called rigging...? And it's a weapon? How odd. I'll have to keep studying so I can learn to use it quickly.",
	couple_encourage = {
		{
			{
				1110001
			},
			1,
			" Lala, let's do our best!",
			0
		},
		{
			{
				1110006
			},
			1,
			" Impressive as ever, Kotegawa! I should to my best, too!",
			0
		}
	}
}


