_G.pg.base.ship_skin_words[11100060] = {
	hp_warning = "I can still keep fighting!",
	feeling3 = "I saw a girl with cat ears the other day. I'd assumed they were just a headband, but they were real! Lala's tail surprised me, but that was an even bigger shock.",
	mail = "Commander, there's new mail for you. Don't let your mailbox fill up with unread messages.",
	expedition = "Commander, the commission work is complete. Don't forget to collect the supplies.",
	win_mvp = "Phew... It's finally over.",
	home = "Thanks for your efforts, Commander. Rest is important, so... I brought you a cold drink...",
	unlock = "Are you the Commander? I'm Yui Kotegawa, and I'm pleased to make your acquaintance. Some strange circumstances brought me here... But if I'm to intrude on your port, then I promise to uphold discipline in return!",
	touch2 = "H-how... utterly depraaaved!",
	mission = "You have new mission deadlines, Commander. Don't miss them!",
	vote = "",
	drop_descrip = "Are you the Commander? I'm Yui Kotegawa, and I'm pleased to make your acquaintance. Some strange circumstances brought me here... But if I'm to intrude on your port, then I promise to uphold discipline in return!",
	feeling4 = "The school at port is a lot like the one we go to. But the chemical equation on the blackboard is wrong. Who wrote that...?",
	lose = "I-impossible!",
	feeling1 = "You have no common sense. Just disappointing.",
	skill = "No perverted activities on my watch!",
	upgrade = "Wh-what is this?! Am I... getting stronger?!",
	propose = "If everyone still needs me here, then I don't mind staying here longer. But no perverted behavior while I'm here, got it?!",
	feeling5 = "Before I knew it, I'd gotten so used to life here. I will continue to fight and carry out my disciplinary duties – for you, and for the people of the port!",
	main = "You need to focus when you're working, Commander! No glancing around or fiddling with random things!|The port's Meowfficers look a little different from normal cats... but they're round and cute in their own way, so it's fine.|This stuff called \"rigging\" is awfully flashy... Why does mine have a plant stem in its mouth, though?",
	touch = "What's up? Do you want help with something?",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Phew... Maybe now I can finally get a break.",
	battle = "I won't let even one breach of discipline pass!",
	id = 11100060,
	gift_dislike = "",
	gift_prefer = "This is so cute... Th-Thanks, Commander.",
	profile = "Yui Kotegawa, Sainan High Discipline Committee. I ended up here after an unfortunate accident, but it's obvious that discipline is a serious issue here. So I'm going to do my job – just leave it to me!",
	voice_key = 1110006,
	headtouch = "Wh-what? What's the problem?",
	feeling2 = "So many strange things around here converge on you... A Disciplinary Committee member knows no rest, I guess.",
	login = "Back at home, we said that disheveled dress reflects a disheveled mind. What I'm saying is, you should dress better.",
	detail = "Hmm... There are so many girls breaking the rules here that I can't deal with them all myself. Commander, can you help me patrol?",
	couple_encourage = {
		{
			{
				1110001
			},
			1,
			" Stop pulling out so many weird things during combat!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[11100061] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Don't you think it's time for a break? You shouldn't push yourself too much, okay...?",
	unlock = "Come on over, I'm not scary~... Wha, Commander?! H-hey... don't go barging into people's rooms! Look, you're scaring my new friend!",
	touch2 = "Commander?! Eeek! What are you looking at?! P-pervert!",
	mission = "",
	vote = "",
	drop_descrip = "Come on over, I'm not scary~... Wha, Commander?! H-hey... don't go barging into people's rooms! Look, you're scaring my new friend!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Next time you're free... We could go out to the cat café, or you could hang out here, even without a reason... Sometimes, though. Sometimes! I'm only offering because it'd be easier to get to know everyone and uphold discipline if you're with me, that's all!",
	main = "I think it'll be fine for now. Thanks for your help, Commander – but don't relax too much, because I might need it again soon.|Algérie and I chatted about cats and took a lot of pictures together. You should take a look, Commander.|I want to take this cat to the cat café. Can you come with me? It'd be awful if she got away.",
	touch = "",
	voice_key_2 = -1,
	mission_complete = "This kitty has really taken a liking to you. Now I feel bad about the thought of taking her back to the cat café...",
	battle = "",
	id = 11100061,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "What are you thinking right now?",
	feeling2 = "",
	login = "Commander, did you come looking for this kitty here? Thanks. Umm... If you have some spare time, you know... I mean... N-never mind!",
	detail = "I might not look it, but I'm a busy person... But I do worry about you, so if you have something to say, go ahead.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[11200010] = {
	hp_warning = "I've only... just begun!",
	feeling3 = "I was born for combat, but that doesn't mean that I can't connect with others. That includes you, of course.",
	mail = "There appears to be mail addressed to you. I recommend checking.",
	expedition = "Our allies have returned. I sense relief.",
	win_mvp = "Annihilation complete... Onward.",
	home = "You're back safe and sound... Do not forget to rest.",
	unlock = "Are you... my enemy? No... I don't sense hostility, but instead, strong willpower. So this world is full of struggle, too. You are... the Commander? I am BLACK★ROCK SHOOTER, and I will protect you.",
	touch2 = "...Should I perceive you as an enemy?",
	mission = "Something seems unnatural about your work. Am I just imagining it?",
	vote = "",
	drop_descrip = "Are you... my enemy? No... I don't sense hostility, but instead, strong willpower. So this world is full of struggle, too. You are... the Commander? I am BLACK★ROCK SHOOTER, and I will protect you.",
	feeling4 = "You protecting me... It's almost laughable how unrealistic it is. But I do feel a sense of gratitude...",
	lose = "I'm not done yet...",
	feeling1 = "Your many friends should be cherished, now and forever...",
	skill = "Limiters released! It's over for you!",
	upgrade = "I'm stronger... though I don't look any different.",
	propose = "I see fire in your eyes when you speak of the future. Is it the same fire that burns in my left eye? I don't know if I'll learn the answer today, tomorrow, or ever... but I hope to know someday.",
	feeling5 = "Love and hate are such powerful emotions. They can hurt others or save their lives. I could never refute these whims of the heart.",
	main = "Azur Lane and Sirens are concepts that I've never heard of, but I understand that here, they are firm reality.|Friends can quickly become foes – a common occurrence. Even then, my promise to protect you still stands.|There's nothing better than being able to find time to rest. You should keep that in mind, Commander.|I want to compare the power of cannons with that of my ★Rock Cannon. Knowing one's strength is important.",
	touch = "It's okay... I'm no illusion. I still exist in this world.",
	voice_key_2 = -1,
	mission_complete = "Your work is complete.",
	battle = "Let's go... I'll carve us a path.",
	id = 11200010,
	gift_dislike = "",
	gift_prefer = "Thanks... I'll treasure it.",
	profile = "When the world is shrouded in dark and all hope is lost, I continue to struggle and fight. I am BLACK★ROCK SHOOTER, and I will guide your way forward.",
	voice_key = 1120001,
	headtouch = "What? Do you doubt my existence? Hmm... Yes, you may see my existence as hazy.",
	feeling2 = "Have you ever heard... that talking with others can help you maintain a balanced heart and mind?",
	login = "Good morning, Commander. Beware... I sense another battle ahead of us.",
	detail = "What meaning is in the struggles of this world? I must fight on until I know.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[11200011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "I think I'll swim a little while I wash off the sweat of battle... You want to join me? Well, I don't mind...",
	unlock = "The babbling of brooks and the crashing of waves were once such minor things to me. As people who do battle on the sea, you all must see something greater in them, too. But I wonder... if this swimsuit isn't very well-suited for combat.",
	touch2 = "Don't you find your actions overly reckless?",
	mission = "",
	vote = "",
	drop_descrip = "The babbling of brooks and the crashing of waves were once such minor things to me. As people who do battle on the sea, you all must see something greater in them, too. But I wonder... if this swimsuit isn't very well-suited for combat.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "The sea stretching out into the horizon... I find this blue planet beautiful. The waves receding under my feet and the scent of the sea breeze are nice, too.|Is this swimsuit for personal use? I see... I'm sorry you had to go out of your way to prepare it for me. I'll thank you on the battlefield.|Even when it comes to water fights, I don't hold back, so give me your all. No, I'm not mad that you just soaked me a minute ago.",
	touch = "Forgive me for being a little more alert when I'm so exposed.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 11200011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I can sense your presence there, even when you just stare at me in silence.",
	detail = "If you want to train, then you should learn to swim in your usual clothes instead of a swimsuit. That'll be more useful in combat.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[11200020] = {
	hp_warning = "That's enough warm-up.",
	feeling3 = "I'm hardly one to speak, but why do you spend time with such an incomprehensible being? You're an odd one.",
	mail = "This message is for you, apparently. I guess you're not in much of a hurry.",
	expedition = "Your friends are back, you know. Do you always leave them hanging?",
	win_mvp = "Heehee, that was as refreshing as always.",
	home = "Welcome back. Done what you needed to do? Well, you look happy, so I'm happy.",
	unlock = "Now where exactly am I? Hmm... Well, this is a mess, isn't it? I want you to tell me everything, but if I'm here, then she must be, too... Oh, don't worry about it. I'm DEAD MASTER, and I guess I'm sticking with you for a while. There's got to be a good reason I'm here, after all.",
	touch2 = "You'd best think about the meaning of your actions.",
	mission = "Oh? Your work isn't done yet. Slacking off, are we?",
	vote = "",
	drop_descrip = "Now where exactly am I? Hmm... Well, this is a mess, isn't it? I want you to tell me everything, but if I'm here, then she must be, too... Oh, don't worry about it. I'm DEAD MASTER, and I guess I'm sticking with you for a while. There's got to be a good reason I'm here, after all.",
	feeling4 = "Thinking about everything so far... I realize that it's strange in itself that I can stand here and speak with you.",
	lose = "Makes my skin crawl...",
	feeling1 = "I want you to disappear without sound or trace. Oh, you think I'm joking?",
	skill = "May this blow haunt you for eternity!",
	upgrade = "Do I look different? If you say so, then it must be true.",
	propose = "My war with her was the only thing that gave me shape, but a certain something, some momentary respite, has ripped me out of that cycle and won't let me go... This must be a fleeting fantasy.",
	feeling5 = "Past, present, and future are all one and the same to me. I'm surprised that I've found someone other than her who can stand out among all that.",
	main = "You've explained this world to me, but I still don't understand it. That must mean it isn't worth my care.|You call this the \"port,\" but it's hard to wrap my head around what that means. I expect you to explain it clearly.|There's really no need for you to care especially about my existence here, you know.",
	touch = "Are you curious about the nature of my existence? Consider it... unstable.",
	voice_key_2 = -1,
	mission_complete = "So you finish your work, and then you pretend it doesn't exist? How carefree.",
	battle = "Ready your weapons. Yes, it's time to fight.",
	id = 11200020,
	gift_dislike = "",
	gift_prefer = "Do you know what it means to give a present? Oh. In that case, I'll take it.",
	profile = "I'm the nightmare chasing a certain girl upon her appearance in this world, both her greatest enemy and closest friend. Now, raise your sword. Let's fight.",
	voice_key = 1120002,
	headtouch = "You've never considered that mind and body might be separated? Heh, how naïve.",
	feeling2 = "Speaking with you like this feels... strange.",
	login = "It's been a while... Hm, but not that long, I suppose? I'm just doing what I feel like, so don't worry about me.",
	detail = "Her existence summons me. It's as universal as any other natural law.",
	couple_encourage = {}
}


