	detail_replace = "",
	dal_shop5 = "",
	gift_prefer = "Huh? Can I really have something this precious?! Th-thank you so much!",
	atelier_yumia_shop_3 = "",
	headtouch_replace = "",
	headtouch = "Oh, are you curious about my alchemy tools? Everyone I meet always is.",
	feeling2 = "Alright! Ready to get to work. Let's see if I can't put my alchemy to use!",
	atelier_yumia_shop_2 = "",
