_G.pg.base.ship_skin_words[11300020] = {
	atelier_yumia_shop_5 = "Whoa! I've completely sold out! Nice work, Commander!",
	mail = "Oh, you've got mail from everyone, Commander!",
	dal_shop2 = "",
	ryza_item4 = "",
	ryza_item3 = "",
	atelier_yumia_item_9 = "",
	mission = "If you put off all of the work you hate, that'll just make it more of a slog later.",
