	atelier_yumia_item_2 = "",
	skill = "",
	unlock_replace = "",
	upgrade = "Check this out. I'm even stronger now!",
	feeling1 = "You should try being nicer to people. It'll help you out in the future.",
	lose = "Ouch... Ugh! Hold back a little, would you?",
	feeling4 = "Tell me anything you need, alright? We're friends. Isn't it normal... to want to help you out?",
	drop_descrip = "I'm Isla von Duerer! Call me Isla! I'm with the Order of Eustella and the Aladiss Research Team... So hey, why am I here?! Do you know why?",
	vote = "",
	feeling5 = "There must be a really important reason why I ended up in this world... and I think I'll figure it out as long as I stay with you.",
	expedition_replace = "",
	skill_1 = "Check out... my ultimate move!",
	voice_key_2 = -1,
	unlock = "I'm Isla von Duerer! Call me Isla! I'm with the Order of Eustella and the Aladiss Research Team... So hey, why am I here?! Do you know why?",
	asmr_009 = "",
	win_mvp = "Woohoo! We won!",
	battle = "Here we go! Be careful, everyone!",
	feeling3 = "Oh? Commander, if you're free, then let's go shopping. I bet it'll be fun!",
	hp_warning = "No problem... This is like nothing to me!",
	id = 11300020,
	main_replace = "",
	touch_replace = "",
	propose = "Geez, don't make fun of me! I really didn't know how to respond to that... I mean... It's hard to accept that our relationship is really real, you know?",
	mission_replace = "",
	mail_replace = "",
	touch2_replace = "",
	skill_dal_1 = "",
	ryza_item1 = "",
	atelier_yumia_shop_4 = "You'll trade for this? Ah, you have good taste!",
