	ryza_shop4 = "",
	asmr_010 = "",
	atelier_yumia_item_3 = "",
	profile = "I'm Isla von Duerer, a member of the Order of Eustella! I run around doing all kinds of odd jobs, like killing monsters, and... Oh, that doesn't matter right now, huh? Anyway, you still gotta be fashionable when you're in a fight. I want to be at the forefront of style!",
	voice_key = 1130002,
	asmr_003 = "",
	ryza_shop3 = "",
	skill_dal_2 = "",
	detail = "I love clothes and accessorizing! It's fascinating how unique everyone's outfits are here!",
	ryza_item5 = "",
	ryza_shop2 = "",
	atelier_yumia_item_6 = "",
	expedition = "Your research team is back. Let's go say hi to them!",
	asmr_006 = "",
	atelier_yumia_item_11 = "",
	skill_2 = "Here comes a big one!",
	touch2 = "Huh?! Geez, what're you doing?!",
	ryza_item2 = "",
	login_replace = "",
	atelier_yumia_item_10 = "",
	touch = "Hmm? Are my clothes torn somewhere? That's okay! You might not guess it, but I'm great at mending!",
	ryza_shop1 = "",
	main = "I've tried out all kinds of awesome technology here. You guys don't call it alchemy, though... The world really is full of mysteries!|Back in our world, we could get pelts and stuff just by adventuring. It seems harder here... Huh? We can use sea monster skin? That does sound enticing...|I wanna try sewing an outfit or two for you... Would you be interested? I can do handsome, cute, and everything in between, as long as you're willing to model for me.",
	atelier_yumia_item_4 = "",
	mission_complete = "Our work here is done! Never leave a task undone, okay?",
	atelier_yumia_item_1 = "",
	atelier_yumia_shop_1 = "Welcome to my shop! Heh, just kidding♪",
	asmr_008 = "",
	atelier_yumia_item_8 = "",
	gift_dislike = "",
	asmr_001 = "",
	atelier_yumia_item_12 = "",
	detail_replace = "",
	dal_shop5 = "",
	gift_prefer = "Huh? Is this for me? Amazing! Thanks~",
	atelier_yumia_shop_3 = "Thank you! Come again!",
	headtouch_replace = "",
	headtouch = "Hm? Need help, or anything? Don't worry. I'm here to help!",
	feeling2 = "Haha, don't be so formal with me! Let's both relax a little, okay?",
	atelier_yumia_shop_2 = "What've you got to trade with me today?",
	mission_complete_replace = "",
	login = "Alright! Here's to another great day, Commander!",
	dal_shop3 = "",
	atelier_yumia_item_5 = "",
	couple_encourage = {
