_G.pg.base.ship_skin_words[11300030] = {
	atelier_yumia_shop_5 = "",
	mail = "Commander. This mail's for you, isn't it? Check more carefully next time.",
	dal_shop2 = "",
	ryza_item4 = "",
	ryza_item3 = "",
	atelier_yumia_item_9 = "",
	mission = "Hmm? You have unfinished tasks here. Did you forget?",
	dal_shop1 = "",
	atelier_yumia_item_2 = "",
	skill = "",
	unlock_replace = "",
	upgrade = "Oh my, my, my. Is it just me, or are you in need of help?",
	feeling1 = "I'll help you with your work. No more, no less.",
	lose = "Well... I've gone and embarrassed myself now.",
	feeling4 = "For some reason, I can always tell when you're looking at me. Yes, I'm surprised, too – who knew I'd care?",
	drop_descrip = "Well, hello there. I'm Nina, a member of the Research Team... Not that it matters much to you. Anyway, I'm not sure what to do now... Oh? You want me to go to your house? My, my, are you sure that's appropriate?",
	vote = "",
	feeling5 = "\"I was just wandering around, and I ended up here!\" Obviously, I'm kidding. This strange place, our new friends, and you... There must be a special meaning to it all.",
	expedition_replace = "",
	skill_1 = "This might hurt a little.",
	voice_key_2 = -1,
	unlock = "Well, hello there. I'm Nina, a member of the Research Team... Not that it matters much to you. Anyway, I'm not sure what to do now... Oh? You want me to go to your house? My, my, are you sure that's appropriate?",
	asmr_009 = "",
	win_mvp = "Aww. Is that all you've got?",
	battle = "Let's finish this quick!",
	feeling3 = "Strange... This doesn't seem right. Maybe if you were fluffier, I'd understand...",
	hp_warning = "Not done yet... I'm just getting started!",
	id = 11300030,
	main_replace = "",
	touch_replace = "",
	propose = "If I didn't run into you back then, I'm sure I wouldn't be here... I'd be someone else entirely. As for what that means? Leave it to the historians to find out.",
	mission_replace = "",
	mail_replace = "",
	touch2_replace = "",
	skill_dal_1 = "",
	ryza_item1 = "",
	atelier_yumia_shop_4 = "",
	dal_shop4 = "",
	asmr_002 = "",
	ryza_shop5 = "",
	asmr_004 = "",
	asmr_005 = "",
	asmr_007 = "",
	atelier_yumia_item_7 = "",
	home = "You look tired. How about I make you a cup of herbal tea? Relax a while.",
	ryza_shop4 = "",
	asmr_010 = "",
	atelier_yumia_item_3 = "",
