_G.pg.base.ship_skin_words[11400010] = {
	hp_warning = "I'll try a little harder.",
	feeling3 = "I think it'd be nice if you'd set aside a little more time for me.",
	mail = "Is this... a letter for you? Reckon it might be a love letter?",
	expedition = "Your familia who went on an errand are back. Huh? They're not familia, they're your friends? I see – you insist on that.",
	win_mvp = "Victory's mine!",
	home = "Welcome back, Commander! Thought something might've happened to you. I'm glad you're fine.",
	unlock = "I'm Hestia, the Patron Goddess of Hestia Familia, believe it or not! What? That doesn't surprise you at all? Hmm. You're nothing like the kiddos I've seen before.",
	touch2 = "Commander. Ready to face the consequences?",
	mission = "What, you still haven't finished this mission? I'll help.",
	vote = "",
	drop_descrip = "Repair ship – Hestia.",
	feeling4 = "Are you here to see me? Nice, that's the sign of a good familia member. Wait, maybe not a good familia member, but a good friend?",
	lose = "Darn it... They're gonna call me a fraud goddess again over this! No way, no way!! This doesn't count!",
	feeling1 = "Need something? Uh, can it wait? I'm so sleepy right now.",
	skill = "I'll do what I can.",
	upgrade = "You're telling me I've powered up? What's going on with this world?",
	propose = "The worlds you and I live in are so far apart... or more like totally different. It's pretty wild that we met and were able to spend time together like this.",
	feeling5 = "I was really stressed when I got thrown into this world out of the blue. I'm really glad I met someone as helpful as you.",
	main = "You've got so much tasty food here. It's almost as good as Potato Poppers. I've gotta try all of it before I go back to my home world!|Commander, I found something tasty – want a bite? Don't be shy, just give it a taste.|Ow, ow, ow... Hey, Commander! Why are you lying down over here? You've gotta sleep in a bed if you wanna recover your strength.",
	touch = "You just can't get enough of me, huh? ...What? I've got dust on me? Ohh. Brush it off, would you?",
	voice_key_2 = -1,
	mission_complete = "Hey, you've got missions to turn in! Don't just leave them sitting there.",
	battle = "Come on, let's go!",
	id = 11400010,
	gift_dislike = "",
	gift_prefer = "Thanks! Now, let's get this party started!",
	profile = "I'm Hestia, the goddess of the hearth and fire! And since I'm a god, you just go ahead and worship me. Also, is there any part-time work that pays well in this world?",
	voice_key = 1140001,
	headtouch = "Hrmh... Why are you staring at me like that, huh? Ah, don't call me a shortie or you're gonna get it!",
	feeling2 = "If my side hustle and our outing overlap on the same day... Hmm. That'll be annoying.",
	login = "Hey there, Commander! I've been waiting a looong time for you!",
	detail = "In my world, we gods had familias who'd conquer dungeons. I guess in this world... you'd conquer the sea, huh?",
	couple_encourage = {
		{
			{
				1140002
			},
			1,
			"Miss Elf, I'm going in.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[11400011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Nice job, Commander. Go and get comfortable in the shade over there. I'll get you something cold to drink!",
	unlock = "Hey-hey, Commander! You're finally here. I've been waiting my butt off! I've already had the full beach experience... Ah, wait, I still have things I wanna do, so do me a solid and stick around!",
	touch2 = "Hey! What do you think you're doing, huh?",
	mission = "",
	vote = "",
	drop_descrip = "Hey-hey, Commander! You're finally here. I've been waiting my butt off! I've already had the full beach experience... Ah, wait, I still have things I wanna do, so do me a solid and stick around!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "So many tasty-looking fish and shellfish... Hey, Commander, I say we treat ourselves to a barbecue while we're here!|Careful so you don't get sunburned. The sun's intense today... I'm gonna go put on some sunscreen, so can you wait just a minute?|You wanna swim? How about we swim together, then? It feels nice to just float in the sea!",
	touch = "Huh? I'll hold your hand, if that's what you want... Do you not know how to swim?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 11400011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Heeey! Commandeeer! Come here! Get yourself in order quickly!",
	detail = "The beach is so much fun! The surface is deep blue and pretty and the water's nice and cool! Being here makes it feel like time is flying by.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[11400020] = {
	hp_warning = "I mustn't back down... Not now!",
	feeling3 = "I appreciate your dedication to your goals. Yes, even I can give compliments.",
	mail = "Mail has arrived. Is now a good time to take a look?",
	expedition = "Everyone's returned safely. Commander, prepare to welcome them home.",
	win_mvp = "Victory... is ours.",
	home = "Welcome back, Commander. Let's get you dusted off... Okay. I will make you tea soon, so rest until then.",
	unlock = "Who are you? No – Where am I? This doesn't look like Orario. You must be the one who saved me, so thank you. My name is Ryu Lion, and I work as a waitress at the Hostess of Fertility pub in Orario.",
	touch2 = "Are you ready to prostrate yourself in apology?",
	mission = "Would you like my help?",
	vote = "",
	drop_descrip = "Light cruiser – Ryu Lion.",
	feeling4 = "Don't push yourself too much, please. Hurting yourself will hurt everyone else in the process. Being honest... I worry about you, too. Please take care of yourself.",
	lose = "Is it time to retreat? Now is the time for clarity of judgment.",
	feeling1 = "Surely you understand that your behavior is foolish.",
	skill = "In the name of justice, I will smite you!",
	upgrade = "I suppose this is a... rank-up? How delightful.",
	propose = "Something is wrong... Why is my heart beating so fast? D-don't get so close! You've done nothing wrong... Oh, how do I explain this?",
	feeling5 = "You're very kind, Commander. I can tell that your kindness extends to everyone... and I respect that greatly.",
	main = "As I understand, you form combat parties that combine members with varying roles... Fleets, you call them? Hmm. Noted.|My apologies for the delay. Here is your tea. Cookies, understood... Hmm? What am I doing? The Royal Maids asked me to help as a waitress, a job that I'm quite accustomed to.|What an outright abusive workload... Hmm? This isn't all for one person? It's meant to be shared among everyone? I-I'm sorry. I should know better than to make assumptions.",
	touch = "Enough! Any closer, and there's no telling what might happen.",
	voice_key_2 = -1,
	mission_complete = "Your rewards are piling up... Do you need me to sort them out for you?",
	battle = "...Let's go.",
	id = 11400020,
	gift_dislike = "",
	gift_prefer = "Hm? Could this be... Ahem. Thank you very much.",
	profile = "My name is Ryu Lion. I work at Hostess of Fertility in Orario. The bountiful experience and skills I've accumulated as an adventurer should come in handy here as well.",
	voice_key = 1140002,
	headtouch = "What do you think you're doing? I sense a malicious aura emanating from you.",
	feeling2 = "Having so much energy in the morning is commendable, yes, but you must direct it toward your work... No. I'm not angry.",
	login = "I've been waiting for you, Commander. Have you decided on our plans for today?",
	detail = "Forgive me... I tend to go too far sometimes.",
	couple_encourage = {
		{
			{
				1140001
			},
			1,
			"Let's go, Lady Hestia.",
			0
		}
	}
}


