	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 11400021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "W-welcome... I'm ready to take your order...",
	detail = "Wearing this is a little embarrassing, but I am happy that you like it.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[11500010] = {
	atelier_yumia_shop_5 = "",
	mail = "Is this... a letter for you? It must be important, so you should read it now.",
	dal_shop2 = "",
	ryza_item4 = "",
	ryza_item3 = "",
	atelier_yumia_item_9 = "",
	mission = "What? You still have work to do? Then let me help.",
	dal_shop1 = "",
	atelier_yumia_item_2 = "",
	skill = "Now... It is over!",
	unlock_replace = "",
	upgrade = "Ooh... I feel my power surging!",
	feeling1 = "Mm... Do whatever you want. I'm going back to the others.",
	lose = "It's... beyond... the reach of my power...",
	feeling4 = "Hmm, you're well-beloved by the people of this port. I understand it, though. You've saved them all, in a sense... I think that's remarkable.",
	drop_descrip = "Heavy cruiser – Tohka Yatogami.",
	vote = "",
	feeling5 = "My goal now is to become strong enough to protect you and everything you hold dear! Will you help me? Good! Then let's get training!",
	expedition_replace = "",
	skill_1 = "",
	voice_key_2 = -1,
	unlock = "Identify yourself. Are you my enemy? ...Perhaps not. Hmm... Could this be a different world entirely? No wonder I've seen so many unfamiliar things. Regardless, my name is Tohka Yatogami. It's an important name, so you'd best remember it. I suppose I'll be in your world for the time being. On that note... I'm hungry. Do you have anything to eat?",
	asmr_009 = "",
	win_mvp = "We won! Moving around makes me so hungry.",
	battle = "Come with me! I will carve a path!",
	feeling3 = "Hehe. Food tastes a lot better when we eat together, doesn't it? I wonder why that is.",
	hp_warning = "I mustn't fall now!",
	id = 11500010,
	main_replace = "",
	touch_replace = "",
	propose = "Spending time here has given me so many more things to cherish. Good foods, friends... Hmm? You act nonchalant, but you count, too. Hmm... Having so many things to cherish is, in itself, something rare and worth cherishing.",
	mission_replace = "",
	mail_replace = "",
	touch2_replace = "",
	skill_dal_1 = "Split the sky and sunder the earth! —Sandalphon",
	ryza_item1 = "",
	atelier_yumia_shop_4 = "",
	dal_shop4 = "",
	asmr_002 = "",
	ryza_shop5 = "",
	asmr_004 = "",
	asmr_005 = "",
	asmr_007 = "",
	atelier_yumia_item_7 = "",
	home = "Ah, Commander, you've returned! How was the battle? Don't spare a single detail.",
	ryza_shop4 = "",
	asmr_010 = "",
	atelier_yumia_item_3 = "",
	profile = "I'm Tohka Yatogami, a Spirit. What is a spirit? Hmm, it's hard to explain, but you might think of me as someone with much greater power than a normal human. Hmm... Well, I suppose that makes me sound the same as everyone else here. In that case, it's only a minor distinction!",
	voice_key = 1150001,
	asmr_003 = "",
	ryza_shop3 = "",
	skill_dal_2 = "Sandalphon",
	detail = "Commander, what are the best foods in this world? I have much I want to ask, but that's the most important thing!",
