	voice_key = 1150002,
	asmr_003 = "",
	ryza_shop3 = "",
	skill_dal_2 = "Metatron",
	detail = "The shipgirls here have very unique designs. I find it most illuminating. ...Might this be your preference, Commander?",
	ryza_item5 = "",
