_G.pg.base.ship_skin_words[11500030] = {
	atelier_yumia_shop_5 = "",
	mail = "You've got a message. Don't let these things pile up.",
	dal_shop2 = "",
	ryza_item4 = "",
	ryza_item3 = "",
	atelier_yumia_item_9 = "",
	mission = "There's still work to be done! C'mon, get on it already!",
	dal_shop1 = "",
	atelier_yumia_item_2 = "",
	skill = "Burn to ash!",
	unlock_replace = "",
	upgrade = "Heheh, very good. I'll show you what I'm like when I mean business.",
	feeling1 = "Um, can we set that aside for later? I don't have the time right now.",
	lose = "We must keep pressing forward... even if it's one step... at a time...",
	feeling4 = "Jeez, what am I even going to do with you? Fine, I'll do it for you, so make sure you pay close attention~♪ So, do you prefer me like that? Huh? You think both versions of me are cute? Well, um... if you like it so much, then maybe next time...",
	drop_descrip = "Battleship – Kotori Itsuka.",
	vote = "",
	feeling5 = "I know my words might be a bit harsh, but that's because I'm seriously looking out for the other person! ...Jeez, what are you trying to make me say?!",
	expedition_replace = "",
	skill_1 = "",
	voice_key_2 = -1,
	unlock = "Where the heck am I... I can't get a hold of Fraxinus... Don't tell me, we've crossed a dimensional wall?! In any case, I need to get a handle on the current situation—Oh, got a moment? My name's Kotori. Kotori Itsuka. I'm just a schoolgirl... You'll buy that, right? Sorry, but can I have a moment to speak with you?",
	asmr_009 = "",
	win_mvp = "Done already? How boring.",
	battle = "Let's get this done the right way. Follow my lead!",
	feeling3 = "What are you even saying? I'm super, duper appreciative! So that's why you get... the love-lashing~♪",
	hp_warning = "Look closely! This is where the real battle begins!",
	id = 11500030,
	main_replace = "",
	touch_replace = "",
	propose = "Don't you think it'd be awesome to have the kind of relationship where you can directly tell each other what you like or dislike? ...Huh? You ask what I am trying to say now? Jeez, could you pick a worse time to ask that?",
	mission_replace = "",
	mail_replace = "",
	touch2_replace = "",
	skill_dal_1 = "Turn them to ash, Flames of Purgatory! —Camael",
	ryza_item1 = "",
	atelier_yumia_shop_4 = "",
	dal_shop4 = "",
	asmr_002 = "",
	ryza_shop5 = "",
	asmr_004 = "",
	asmr_005 = "",
	asmr_007 = "",
	atelier_yumia_item_7 = "",
	home = "Good work. Commander, how would you rate this last sortie? Hm? You'd like my personal assessment? A full 100, of course. It goes without saying.",
	ryza_shop4 = "",
	asmr_010 = "",
	atelier_yumia_item_3 = "",
	profile = "The name's Kotori Itsuka. I guess you'd call me a Spirit, but... about that, the situation's pretty complicated though. I'd appreciate it if you didn't worry too much about that whole deal. As someone who knows what it's like to be a captain or commander, I hope we can have a good relationship as peers.",
	voice_key = 1150003,
	asmr_003 = "",
	ryza_shop3 = "",
	skill_dal_2 = "Camael",
	detail = "Back in the world where I'm from, I was the captain of an airship. But, that ship and the ships here are completely different... Like, we're talking on a conceptual existence level different...",
	ryza_item5 = "",
	ryza_shop2 = "",
	atelier_yumia_item_6 = "",
	expedition = "Looks like your friends are back. Go on, go greet them already. As a commander, you should know how important the aftercare is, no?",
	asmr_006 = "",
	atelier_yumia_item_11 = "",
	skill_2 = "",
	touch2 = "Wh-what are you doing?! ...I-i-i-it's not like I'm mad or anything though...",
	ryza_item2 = "",
	login_replace = "",
	atelier_yumia_item_10 = "",
	touch = "What do you want? ...No, I'm not mad or anything. I just wasn't expecting you to suddenly touch me.",
	ryza_shop1 = "",
	main = "I'm curious what it's like around here. Mind if I take a look around? Heehee, you could also escort me around while you're at it.|Even for someone like me who's used to seeing Spirits, this is kind of its own fairy tale kingdom. I mean, look—you have both magic and cannonballs flying through the air... Hmm? Looking at it that way, maybe our worlds aren't so different.|Spirits are a formidable threat, so our way of dealing with them is taking them out on dates and getting them to fall in love. I wonder if this also works for shipgirls...",
	atelier_yumia_item_4 = "",
	mission_complete = "Oh wow, looks like you've taken care of all the work over here. See, you can do it if you try.",
	atelier_yumia_item_1 = "",
	atelier_yumia_shop_1 = "",
	asmr_008 = "",
	atelier_yumia_item_8 = "",
	gift_dislike = "",
	asmr_001 = "",
	atelier_yumia_item_12 = "",
	detail_replace = "",
	dal_shop5 = "",
	gift_prefer = "Sorry, you must've gone through much trouble for me... But, thank you...",
	atelier_yumia_shop_3 = "",
	headtouch_replace = "",
	headtouch = "Wh-what are you doing all of a sudden! I-it's not like you startled me or anything!",
	feeling2 = "Alright, all done on my end. Next up is... Hey, why are you looking at me like you've got no skin in the game? Hurry up and help me!",
	atelier_yumia_shop_2 = "",
	mission_complete_replace = "",
	login = "Morning, Commander. Let's go all-out today as well!",
	dal_shop3 = "",
	atelier_yumia_item_5 = "",
	couple_encourage = {
		{
			{
				1150006
			},
			1,
			" You're both soaking wet... Want me to help dry you off?",
			0
		},
		{
			{
				1150005
			},
			1,
			" I just know you're up to something... Step out of line and you'll see me get real mad, Kurumi.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[11500031] = {
