	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Aren't you normally supposed to say something in situations like these? Well, I suppose it helps to have some experience first... W-wait, it's not like I'm trying to rush you or anything!|Ughh... I'm not embarrassed... I'm totally not embarrassed! This level of embarrassment doesn't even count as embarrassment!|Hmph... Well, as long as you like it. At least I didn't get changed for nothing.",
	touch = "Oh... am I getting sunburnt? Maybe I should see if they have sunscreen here...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 11500031,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Sorry to keep you waiting—Wh-what? It's not like I got changed just for your sake!",
	detail = "Jeez... What even goes through your mind all the time? Playing in the ocean at a time like this? ...Well, since you're this close anyway, I guess it makes sense.",
	couple_encourage = {}
