_G.pg.base.ship_skin_words[11500050] = {
	atelier_yumia_shop_5 = "",
	mail = "This letter... seems to be addressed to you.",
	dal_shop2 = "",
	ryza_item4 = "",
	ryza_item3 = "",
	atelier_yumia_item_9 = "",
	mission = "Come on now, there's still work to be done. Let us proceed with quiet diligence.",
	dal_shop1 = "",
	atelier_yumia_item_2 = "",
	skill = "Let the feast begin!",
	unlock_replace = "",
	upgrade = "Ahh, ahh! I can feel it! How exhilarating!",
	feeling1 = "Hmph... So that's how it is. Well, not like I was expecting much from the beginning.",
	lose = "Have I... been... defeated?",
	feeling4 = "Heehee, you're a LOT more interesting than I expected. You know, Commander—I'd love to devour you right up. Kihihi, just kidding~",
	drop_descrip = "Light cruiser – Kurumi Tokisaki.",
	vote = "",
	feeling5 = "Good evening. Recently, you've been meeting my gaze more and more often. Are you that captivated by me? ...Hmm? If our eyes are meeting, that means I've been looking at you too...? My, oh my...",
	expedition_replace = "",
	skill_1 = "",
	voice_key_2 = -1,
	unlock = "My, my... Now, where exactly might this be? Hmm, I seem to have... crossed into another world without realizing it. Kihihihi... It looks like things are about to get a lot more interesting. Ah, but please disregard that for now. Please allow me to introduce myself first. I am Kurumi Tokisaki. What might your name be?",
	asmr_009 = "",
	win_mvp = "Surely you didn't think you had a chance against me, did you?",
	battle = "Kihihihi! You think you have the might to go against me?",
	feeling3 = "Heehee. You know, you're quite the interesting person. I do like how you're not intimidated by me in the slightest.",
	hp_warning = "You should know now... THIS is where the true battle begins, understand?",
	id = 11500050,
	main_replace = "",
	touch_replace = "",
	propose = "Heehee, what a truly wonderful place this is. The deep blue of the sea, the foamy white crests of the waves... It brings peace even to my troubled heart. ...Hmm? What is it that troubles me? My, my... Wouldn't it be terribly dull for me to just go and say it?",
	mission_replace = "",
	mail_replace = "",
	touch2_replace = "",
	skill_dal_1 = "None may escape the prison of time. —Zafkiel",
	ryza_item1 = "",
	atelier_yumia_shop_4 = "",
	dal_shop4 = "",
	asmr_002 = "",
	ryza_shop5 = "",
	asmr_004 = "",
	asmr_005 = "",
	asmr_007 = "",
	atelier_yumia_item_7 = "",
	home = "It seems you were able to come back safe and sound. Yes, yes. I understand—but first, let us rejoice in your triumphant return.",
	ryza_shop4 = "",
	asmr_010 = "",
	atelier_yumia_item_3 = "",
	profile = "My name is Kurumi Tokisaki, but you can just call me Kurumi. Some call me scary things like \"the disaster that will destroy the world\" and the \"Worst Spirit\", but please don't let that get to you. As you can see, I am nothing more than a weak and powerless little thing. Kihihihi~",
	voice_key = 1150005,
	asmr_003 = "",
	ryza_shop3 = "",
	skill_dal_2 = "Zafkiel",
	detail = "Commander, what sort of impression do you have of me? Heehee~ Perhaps... I might not be the kind of girl you think I am.",
	ryza_item5 = "",
	ryza_shop2 = "",
	atelier_yumia_item_6 = "",
	expedition = "Welcome back. I'm glad you're all safe.",
	asmr_006 = "",
	atelier_yumia_item_11 = "",
	skill_2 = "",
	touch2 = "My, my... That's not proper, you know?",
	ryza_item2 = "",
	login_replace = "",
	atelier_yumia_item_10 = "",
	touch = "My, my, are you doubting the nature of my existence? Heehee... Though it is true—perhaps under different circumstances, I might've been a very different kind of being.",
	ryza_shop1 = "",
	main = "My, my... Are you THAT interested in me? I'm glad to hear it, heehee. Buuut, I wouldn't get too tangled up if I were you.|The seaside certainly has a unique charm to it, wouldn't you say? Like, one that cleanses the soul—Oh my, is there something you wanted to say?|My my, is there any particular reason why everyone is gathering here today? Is the fact that I am here so unusual to all of you? Though, if you ask me, there are some equally eccentric people here...",
	atelier_yumia_item_4 = "",
	mission_complete = "It seems that you've finished your mission. Please go ahead and collect the rewards, then.",
	atelier_yumia_item_1 = "",
	atelier_yumia_shop_1 = "",
	asmr_008 = "",
	atelier_yumia_item_8 = "",
	gift_dislike = "",
	asmr_001 = "",
	atelier_yumia_item_12 = "",
	detail_replace = "",
	dal_shop5 = "",
	gift_prefer = "My, my... You want me to have something this wonderful? Heehee, I'll take good care of it.",
	atelier_yumia_shop_3 = "",
	headtouch_replace = "",
	headtouch = "My, my... Is something the matter?",
	feeling2 = "My, my... What am I going to do with you? I suppose I'm willing to make an exception, just this once.",
	atelier_yumia_shop_2 = "",
	mission_complete_replace = "",
	login = "Good morning, Commander. May I ask what plans you have for the day?",
	dal_shop3 = "",
	atelier_yumia_item_5 = "",
	couple_encourage = {
		{
			{
				1150004
			},
			1,
			" Come on now, Yoshino. Let's fight together.",
			0
		},
		{
			{
				1150003
			},
			1,
			" Heehee. It's nice to see a familiar face, Kotori. For the time being, let's be allies.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[11500051] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "You're back? Well then, step closer and let me loosen up that weary body of yours.",
	unlock = "My, my. It seems that we've been seen, the other \"Me\". \"Indeed. Such a passionate gaze is naturally going to make me feel flushed.\" ...So, how long do you intend to stand there staring?",
	touch2 = "Kihihihi... How awfully daring of you~",
	mission = "",
	vote = "",
	drop_descrip = "My, my. It seems that we've been seen, the other \"Me\". \"Indeed. Such a passionate gaze is naturally going to make me feel flushed.\" ...So, how long do you intend to stand there staring?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "I personally think this is a bit too risque, but what do you think? \"Heehee... that beet-red face says it all.\"|My, my... I can't believe how deep these tan lines already are—Heehee, Commander, can you see them as well?|Why are there two of me? Heehee. Every girl has her secrets, right?",
	touch = "Hmm, it's really hard applying lotion to your own back... My, oh my. Are you expecting something from me?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 11500051,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Good day to you. My, you seem quite taken aback by this outfit of mine. Heehee, do you not think it looks good on me?",
	detail = "Two Kurumi Tokisakis—and both are \"me\". So, Commander, which \"me\" do you prefer?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[11500060] = {
	atelier_yumia_shop_5 = "",
	mail = "Commander, a message has arrived. Information is the key to any strategy. Read it posthaste.",
	dal_shop2 = "Anything catch your eye today? \"Suggestion. Yuzuru likes this one.\"",
	ryza_item4 = "",
	ryza_item3 = "",
	atelier_yumia_item_9 = "",
	mission = "Commander, I'm not impressed with how you neglect your work. \"Proposal. You should get it done already.\"",
	dal_shop1 = "We've been waiting for you, Commander! \"Greetings. Welcome.\"",
	atelier_yumia_item_2 = "",
	skill = "\"Binding.\"Penetrate!",
	unlock_replace = "",
	upgrade = "Ugh! This power... Be still, my right arm... \"Growth. Our abilities have improved.\"",
	feeling1 = "\"Surprise. You're still here?\" Come on, Yuzuru, let's bail.",
	lose = "Sorry, Yuzuru—I messed up... \"Rescue. Kaguya, hang in there!\"",
	feeling4 = "\"Response. Yes, what is it, Commander? Hmm. I see...\" \"Warning. I believe you should choose your words more carefully, Commander. Otherwise, misunderstandings are bound to occur, and these may throw the port into chaos.\"",
	drop_descrip = "Light cruiser – Kaguya Yamai・Yuzuru Yamai.",
	vote = "",
	feeling5 = "\"Gratitude. It is thanks to you that we've managed to survive in this place we know nothing about. You have our utmost thanks.\" Hey! Don't be a show-stealer! I wanna express how super grateful I am, too!",
	expedition_replace = "",
	skill_1 = "",
	voice_key_2 = -1,
	unlock = "Mwahaha! We are the Children of Typhoon who raze everything! Kaguya Yamai, and... \"Concur. Yuzuru Yamai.\" Wait, what? Where are we? \"Confusion. It seems we've wound up in another world.\" S-seriously? Wh-wh-what do we do now, Yuzuru?! \"Composure. Calm down. We should ask someone what is going on. You there, please explain as much as you can.\"",
	asmr_009 = "",
	win_mvp = "Alright! That's done! \"Report. Victory is ours.\"",
	battle = "The time is now! Follow me! \"Deploying. I'm heading out.\"",
	feeling3 = "Retainer of mine, your proven dedication to me has made you deserving of a reward. What do you desire? ...What? M-my smile?! S-such an eccentric fellow you are...",
	hp_warning = "I am... immortal! \"Unyielding. The true battle... begins now.\"",
	id = 11500060,
	main_replace = "",
	touch_replace = "",
	propose = "The world is a place where various causes and effects come together. When viewed that way, there must be a reason for us all meeting here. \"Affirmative. At the very least, we are grateful for having met you.\"",
	mission_replace = "",
	mail_replace = "",
	touch2_replace = "",
	skill_dal_1 = "Bear us forth on swift wings of steel! —Raphael",
	ryza_item1 = "",
	atelier_yumia_shop_4 = "",
	dal_shop4 = "\"Received. One would expect nothing less.\" Huh? Did something happen??",
	asmr_002 = "",
	ryza_shop5 = "",
	asmr_004 = "",
	asmr_005 = "",
	asmr_007 = "",
	atelier_yumia_item_7 = "",
	home = "Welcome back. You alright? Didn't get hurt out there, did you? \"Unharmed. That is a relief.\"",
	ryza_shop4 = "",
	asmr_010 = "",
	atelier_yumia_item_3 = "",
	profile = "Mwahaha... Kaguya Yamai is my name! And this Yuzuru, my other half! We are the Children of Typhoon who control the wind! Heed my word, my beloved subjects! The time has come! No foe can challenge my tyranny! Prostrate yourselves in awe and spread the noble name of Yamai across the world. \"Praise. Clap clap. You're so awesome, Kaguya. Woohoo.\" Hey, are you being sarcastic?",
	voice_key = 1150006,
	asmr_003 = "",
	ryza_shop3 = "",
	skill_dal_2 = "Raphael",
	detail = "\"Inquiry. What is our reason for being in this place?\" Hmm... I don't think you should think too hard about it.",
	ryza_item5 = "",
	ryza_shop2 = "",
	atelier_yumia_item_6 = "",
	expedition = "Oh, the girls are back from their errands! Come on, let's go see them!",
	asmr_006 = "",
	atelier_yumia_item_11 = "",
	skill_2 = "",
	touch2 = "Eek! Th-that's cold!",
	ryza_item2 = "",
	login_replace = "",
	atelier_yumia_item_10 = "",
	touch = "What's up? Need help with something? Fiiine, since you want it so badly. \"Observation. You seem rather pleased, Kaguya.\"",
	ryza_shop1 = "",
	main = "\"Praise. Don't you think it's very cute how Kaguya conducts herself? Moreover, her powers are a perfect 10/10.\" What? What're you chatting about? \"We were discussing how you should work on your temper.\" You what?!|\"Explanation. Kaguya and I were originally a single Spirit. At some point, we split into two.\" Huh? What kind of Spirit were we originally? Hmm... I'm not sure, but I DO know we were stronger than anyone else!|Incredible. Look how many facilities here can be used for competitions... My blood rushes with excitement! \"Concur. Let's have a match, Kaguya.\"",
	atelier_yumia_item_4 = "",
	mission_complete = "\"Received. Your rewards have arrived. Please have a look.\"",
	atelier_yumia_item_1 = "",
	atelier_yumia_shop_1 = "",
	asmr_008 = "",
	atelier_yumia_item_8 = "",
	gift_dislike = "",
	asmr_001 = "",
	atelier_yumia_item_12 = "",
	detail_replace = "",
	dal_shop5 = "\"Sold out. Now then, let's close up shop.\" Huh? We're sold out already?!",
	gift_prefer = "\"Delightful. You have my heartfelt gratitude.\" Wow, really? Thank you so much!",
	atelier_yumia_shop_3 = "",
	headtouch_replace = "",
	headtouch = "Eek! Wh-wh-what're you doing?! \"Supremacy. This is what is colloquially known as a 'headpat.'\"",
	feeling2 = "\"Greeting. Good day.\" What, got nothing better to do? Hmm. You wanna hang out with us, then? \"Concur. Casual mingling is fun.\"",
	atelier_yumia_shop_2 = "",
	mission_complete_replace = "",
	login = "\"Greeting. Good morning.\" Huh? Hey! I'm still in bed here! Don't gawk!",
	dal_shop3 = "A superb choice! \"Excellent choice! \"Props. Praise is in order.\"",
	atelier_yumia_item_5 = "",
	couple_encourage = {
		{
			{
				1150002
			},
			1,
			" \"Report. Master Origami, please behold the fruits of our training.\" What training?!",
			0
		},
		{
			{
				1150003
			},
			1,
			" Over there! Kotori! Isn't that a LITTLE too much firepower?! \"Analysis. She's trying to make her grand entrance with an explosion.\"",
			0
		}
	}
}


_G.pg.base.ship_skin_words[11500061] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome back, Commander! Surely now you've got time to play! \"Attention. The Commander is tired. We shouldn't be too pushy.\" Tired-shmired! Come on!",
	unlock = "I now entrust this body of mine to the beautiful flow of the sea god! Come, Commander, and give me your hand! \"Request. Let us hold hands so that we don't get lost in the sea.\" Come on, don't be shy!",
	touch2 = "Not THAT! My hand! Take my hand! \"Shock. How bold of you... Kaguya.\" I'M the bold one?!",
	mission = "",
	vote = "",
	drop_descrip = "I now entrust this body of mine to the beautiful flow of the sea god! Come, Commander, and give me your hand! \"Request. Let us hold hands so that we don't get lost in the sea.\" Come on, don't be shy!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Heheh! Well done on the escort! Henceforth, you shall follow me as my right hand! \"Doubt. I feel more like we are the ones being escorted here.\"|I've figured it out! Swimming underwater's not that different from flying! That being the case... My vassal! I shall reveal to you the realm of the fish beneath the great ocean!|\"Fear. I feel as though I'm being drawn to the sea bottom when doing this. Could you hold my hand for a little while?\"",
	touch = "Yuzuru and I are wearing matching swimsuits! How do we look? \"Confidence. No answer other than 'incredible' would be acceptable.\"",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 11500061,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I've been waiting for you! No time to waste—let's go swimming!",
	detail = "\"Shock. There are so many fish forming these schools...\" Heh! Our sheer charm must've drawn them here! \"Doubt. Maybe they think we're... coral?\" Umm.... Maybe, I guess?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[11700010] = {
	hp_warning = "I... can still do this!",
	feeling3 = "I'll cover you. That much, I know I can do.",
	mail = "Looks like you've got a message.",
	expedition = "Looks like someone's back?",
	win_mvp = "Just stay there and sink.",
	home = "All done? Just say the word if you need me.",
	unlock = "I'm... called A2. I'm used to fighting by myself, without support... but maybe it wouldn't be bad to find a place to rest my feet.",
	touch2 = "I'll destroy you...",
	mission = "Looks like there's still work to be done?",
	vote = "",
	drop_descrip = "Heavy cruiser – A2.",
	feeling4 = "Looks like I won't have to worry about you getting in my way.",
	lose = "Damn it! How could this happen, in a place like this...!",
	feeling1 = "...This is pointless.",
	skill = "I'll smash you to bits!",
	upgrade = "Not half bad.",
	propose = "I never thought I'd have a comrade to fight alongside ever again, but... for the time being, let's do this, together.",
	feeling5 = "...As long as our goals and desires align in some way, I'll lend you my strength... That should be good enough, right?",
	main = "I'm fine on my own. It's just business as usual.|So we'll be fighting on the sea the whole time, huh? Not used to that.|The sea, huh... Doesn't bring back any fond memories.",
	touch = "...Got nothing better to do?",
	voice_key_2 = -1,
	mission_complete = "Looks like a mission was completed.",
	battle = "Rout them all!",
	id = 11700010,
	gift_dislike = "",
	gift_prefer = "I appreciate it, really.",
	profile = "My goal is to destroy all machine lifeforms. As long as you don't get in my way, I might even help with your objectives. If I slack off now because there are no machine lifeforms around, I'll get rusty soon.",
	voice_key = 1170001,
	headtouch = "What...do you think you're doing?",
	feeling2 = "Defeating the enemy... As long as our objectives are the same, that's all that matters.",
	login = "About time you showed up.",
	detail = "Machine lifeforms or Sirens, I'll destroy them all.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[11700011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "You're back? ...No, it's not like I was waiting for you or anything...",
	unlock = "Why are you looking at me like that...? Is it so unusual to see me without armaments? ...Honestly, I don't think I'm much fun to stare at, but suit yourself.",
	touch2 = "Is it just me, or are you a bit warmer than usual?",
	mission = "",
	vote = "",
	drop_descrip = "Why are you looking at me like that...? Is it so unusual to see me without armaments? ...Honestly, I don't think I'm much fun to stare at, but suit yourself.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "If you have something to say, just say it already. Can't relax with silence like this.|Are you really alright getting this comfortable?|*sigh*... Fine, do as you like.",
	touch = "Will it kill you to not get so handsy all the time?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 11700011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "You came all the way out here just to chat with me? Awfully thoughtful of you...",
	detail = "No harmful substances detected in this fruit. Not that I was planning on eating it anyway.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[11700020] = {
	hp_warning = "I will not back down.",
	feeling3 = "Good day... I assessed that establishing communicative rapport would make things efficient here.",
	mail = "A message has arrived. Please look it over, Commander.",
	expedition = "The expedition team has reported their return. Would you like to review the results?",
	win_mvp = "Battle concluded. Now returning to base.",
	home = "We've returned to base safely. Awaiting orders for the next operation.",
	unlock = "I am YoRHa No.2 Type B, an all-purpose battle android belonging to the YoRHa squadron. You can just call me 2B. I do not know where this is, but I will respond to any requests for assistance. After all, it is our mission to fight for humanity.",
	touch2 = "No abnormalities detected. Maintenance should proceed without issue...",
	mission = "It appears that some tasks are still incomplete. I am simply reporting this, just in case.",
	vote = "",
	drop_descrip = "Light cruiser - 2B.",
	feeling4 = "You wish to learn more about machine lifeforms and aliens? I don't think I have any relevant information for you. But if you don't mind, we can talk about it some other time.",
	lose = "Damage is heavier than expected. Judging it detrimental to the operation, I will now start retreating...",
	feeling1 = "Should I conduct a system scan?",
	skill = "Break!",
	upgrade = "This body is successfully enhanced. Thank you.",
	propose = "Everyone, we all stand here to fight against our enemies, but nobody can fulfill this duty alone. To make up for that missing piece... Commander, perhaps that is why your presence is needed.",
	feeling5 = "I believe it is justified for a commander to treat casualties as statistics. It is not something you need to concern yourself over.",
	main = "YoRHa androids are forbidden from having emotions.|How am I meant to spend my time when there are no missions...?|These are goggles, not a blindfold.",
	touch = "...What is the purpose of such an action?",
	voice_key_2 = -1,
	mission_complete = "It appears that you've completed some tasks. I recommend proceeding with the follow-up procedure.",
	battle = "Enemy aircraft detected. Entering combat-ready state.",
	id = 11700020,
	gift_dislike = "",
	gift_prefer = "...Thank you.",
	profile = "I am 2B. YoRHa No.2 Type B. I excel in close-quarters combat and normally use my Pod support system to handle ranged combat. I take it that here, I will be using this rigging to conduct ranged combat?",
	voice_key = 1170002,
	headtouch = "...It's alright. There are no problems with basic functionalities.",
	feeling2 = "It's dangerous for you to be alone. Head back to your quarters first; I'll protect you.",
	login = "Confirming the Commander's arrival. Awaiting instructions.",
	detail = "I have no preferences when it comes to the choice of operations. Feel free to assign me whichever missions you see fit.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[11700021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Returning from combat operations. You deserve some rest as well, Commander.",
	unlock = "Confirming the safety of the surrounding area. I shall now enter sleep mode for the time being. While resting is not essential to us androids, the tranquil environment here seems to be urging me to do so.",
	touch2 = "I have detected a subtle abnormality in your tactile system. Could you do that one more time, for confirmation?",
	mission = "",
	vote = "",
	drop_descrip = "Confirming the safety of the surrounding area. I shall now enter sleep mode for the time being. While resting is not essential to us androids, the tranquil environment here seems to be urging me to do so.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "I wish to preserve this scenery in my memory module. I wonder if this is the process humans refer to as \"remembering.\"|Plants are said to have a relaxing effect. However, this is not the case for androids... supposedly.|Commander, do I appear to be \"relaxing\" to you?",
	touch = "I am able to measure your body temperature accurately, even without physical contact.",
	voice_key_2 = -1,
	mission_complete = "",
