	headtouch = "",
	feeling2 = "",
	login = "Commander... I recommend you take today off as well.",
	detail = "All mechanical devices require proper maintenance for stable operation, and androids are no exception. In other words, I am requesting maintenance.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[299010] = {
	hp_warning = "I seem to have underestimated the battlefield...",
	feeling3 = "The correct answer is - to do everything in your power to prevent that situation from occurring in the first place. Heehee~ Commander, if you wish to woo me, you will have to use your brain more~",
	mail = "Commander, there's mail for you. Hmm? I didn't do anything in particular~",
	expedition = "Commander, I shall temporarily grant you permission to leave my side so that you may greet the girls who have returned from commissions.",
	win_mvp = "Ehehe~ As a special service, I shall allow you to praise me more~♪",
	home = "You've done well to return home safe and sound.",
	unlock = "Who am I? I am the Royal Navy's large light cruiser, Neptune. I shall see to it that you will never forget my name~♪ Yes, pleased to be of service~♪",
	touch2 = "That simply will not do, Commander. You cannot seek to gain my attention that way. ",
	mission = "Commander, I see you have allowed your unfinished missions to pile up. I am not very fond of lazy people, you know?",
	vote = "",
	drop_descrip = "Light cruiser – Neptune.",
	feeling4 = "Having that said, I believe that a truly intelligent person knows how to rely on others when appropriate. Ah, that's right~ Commander, would you feed me some cake?",
	lose = "I shall not repeat this mistake again.",
	feeling1 = "Commander, did you know how high my expectations were for you at first? What a shame, for you shall now never know.",
	skill = "I have no intention of getting friendly with the enemy~",
	upgrade = "As expected!",
	propose = "\"You are my world?\" Did you think you could fool me with such flattery? Ehehe... well, I suppose there's a chance that I would let you fool me~ But first, you would have to repeat it ten times, nay, a hundred times~",
	feeling5 = "Commander, have you planned where we're going to go for our date? If you have picked out an outfit for me, why don't you help me put it on? Eh~? \"Why don't I wear it myself?\" Silly, that's what love is all about~ L.O.V.E~♡",
	main = "Unlike the other girls, this is my \"maiden voyage\" onto the battlefield. I wish to confirm for myself what this oft-touted \"difference in experience\" looks like. |Commander, if you get on your knees and beg, \"Please, Mistress Neptune,\" perhaps there would be a chance for something nice to happen? |Commander, if you wish to taste my freshly-baked cake, then please first brew your finest tea~",
	touch = "You would like to challenge me to a game? Very well. Do not expect me to hold back though, hehe~♪",
	voice_key_2 = -1,
	mission_complete = "Commander, what do you hope to gain through not collecting the mission rewards? Perchance you are waiting for me to remind you?",
	battle = "So this is a battlefield? Ahaha... how interesting.",
	id = 299010,
	gift_dislike = "",
	gift_prefer = "Bingo! Don't forget next time, either, okay?",
	profile = "My background? Ehehe, I am the large light cruiser who only existed on paper, Neptune, so it is understandable that you have never heard of me before. Though I have yet to step onto the battlefield, my abilities are top notch... allow me to prove that to you in live combat~",
	voice_key = 29901,
	headtouch = "",
	feeling2 = "Commander, I have a question. If in the future you were given the option to sacrifice me for world peace, what would you choose?",
	login = "That simply will not do, Commander, keeping me waiting all this time~",
	detail = "Want to know about this? It's called a trident. Don't you think it's cool?",
	couple_encourage = {
		{
			{
				20203
			},
			1,
			"I-I wouldn't do something like that...",
			0
		},
		{
			{
				20212
			},
			1,
			"Let's seize a decisive victory, Miss Head Maid~♪",
			0
		},
		{
			{
				20208,
				20226,
				20219,
				20211,
				20212,
				20218,
				20220,
				20221,
				20222,
				20304
			},
			1,
			"Let me see how the Maid Team fights~♪",
			0
		}
	}
}


_G.pg.base.ship_skin_words[299011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Commander, why don’t you take a guess which box I put your mail into~?",
	expedition = "",
	win_mvp = "That should wrap things up. Commander, let’s continue our party~",
	home = "",
	unlock = "Hehe~ I usually let the other girls have all the glory, but even I must sometimes give you something to remember me by. Merry Christmas, Commander~",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "Hehe~ I usually let the other girls have all the glory, but even I must sometimes give you something to remember me by. Merry Christmas, Commander~",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Commander, if you kneel in front of me and beg, you might just get something very nice in return~ Hehe~ |Commander, did you already forget? If you want a present from me, you must first give me something that I’d be satisfied with~ |Since joining the fleet, I’ve made a lot of friends. Especially Shropshire — she’s both a good friend and a good rival.",
	touch = "Commander, would you help me out with these presents that I prepared for Seattle’s party? They’re going to be for everyone~",
