	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, Merry Christmas~ ♪",
	detail = "My daily routine is nothing but missions and sorties, so it’s nice to be able to get dressed up and have a good time. Hehe~",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[299012] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "You're welcome~♪ It was only possible because of you, Commander.",
	home = "Welcome back. Now then, please take my hand once more. Oh... Is the trident getting in the way?",
	unlock = "Welcome to our celebration, Commander. At this breathtaking venue, I, Neptune, shall be the one to show you around, rather than the Royal Maids. Heehee~♪",
	touch2 = "That simply won't do, Commander. Everything has a proper time and place, you know?",
	mission = "",
	vote = "",
	drop_descrip = "Welcome to our celebration, Commander. At this breathtaking venue, I, Neptune, shall be the one to show you around, rather than the Royal Maids. Heehee~♪",
	feeling4 = "",
	lose = "Was I too preoccupied with putting on airs...?",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Allowing some other girl to attend you instead of choosing me? That simply won't do, Commander... Just kidding♪ I'll be waiting right here, so make sure you say hello to everyone~|Commander, have you forgotten the magic words when you want me to take you somewhere? \"Please, Mistress Neptune.\" Remember?|Charybdis' demeanor seems rather out of place compared to the rest of the Royal Maids... Say, Commander, how would you like it if I tried to act extra high-and-mighty to get you to do all sorts of stuff for me?",
	touch = "That's right, the party venue is right in front of you. Heehee~♪",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "You, going against the Commander? That simply won't do~♪",
	id = 299012,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "That simply won't do, Commander. As you are the guest of honor, we cannot have you arriving late. You've kept me waiting, you know. Heehee♪",
	detail = "Commander, I know you actually attend all sorts of parties with the Royal Maids. Buuut, heehee~ Don't you think I'm a cut above those girls when it comes to these kinds of situations?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[299013] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Commander, don't you think that jump I pulled off was just perfect? I put hours of practice into it! Phew... But now I'm tired... Pass me the water, would you?",
	unlock = "Step aside, officer comin' through! Oh, here already, advisor? Did you find any good clues? ...No? Heheh, watch and see how the pros do it!",
	touch2 = "We're on camera, Commander. Are you really so impatient?",
	mission = "This is a big case, and time is running out. Let's get to work, advisor.",
	vote = "",
	drop_descrip = "Step aside, officer comin' through! Oh, here already, advisor? Did you find any good clues? ...No? Heheh, watch and see how the pros do it!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Practicing that last jump has me exhausted... Say, how about you massage my thighs for me? Yeah, just like that... Aw, you can go higher if you want, you know.",
	main = "These traces are suspicious. It almost feels as if they were left on purpose... Advisor, write down everything that looks... Hm? Oh, right, that wasn't in the script. Sorry – I couldn't help but rely on you!|You're doing great work. Once this case is wrapped up, let me treat you to dinner. This is a personal invitation and not from the team, I'll have you know.|Are you telling me... this wasn't the first crime scene?! Ahem. How was that one, Commander? Hmm, you think I should be more confident like I always am? Okay, I'll give it a try!",
	touch = "Oh? Is there a problem with how my outfit's fitting? You're free to help me adjust it.",
	voice_key_2 = -1,
	mission_complete = "Advisor, our fieldwork is about done for the day. Let's give it a rest... Hey, you free later?",
	battle = "",
	id = 299013,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "You're just in time for our scene, Commander. Hurry up and get changed... Do you want my help? Hmm, only if you say please and thank you!",
	detail = "There's more to this case than meets the eye. Who knows how deep the rabbit hole goes... Advisor, it's time you start searching for clues. With your help, we've got this in the bag.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[299020] = {
	hp_warning = "If Wales were me, she would probably have sunk long ago.",
	feeling3 = "Love needs no repayment. No matter how much the Royal Family neglects me, my loyalty to them is unwavering.",
	mail = "You've received mail regarding the war. You would do best to check it.",
	expedition = "I wonder what efforts it took to materialise me... Hmph, regardless, I will see to it they are repaid in double.",
	win_mvp = "Heed my words: depend on me! I will always win!",
	home = "That was a marvellous welcome. Hmph, were I the only one returning, would anyone welcome me at all...?",
	unlock = "We meet for the first time. I am the battleship Monarch. Hmph, once I was discarded, but now I am needed; how ironic... Is this how low the Royal Navy has sunk?",
	touch2 = "Do not fall victim to those degenerate habits of theirs.",
	mission = "Let me handle this mission. I shall prove my excellence!",
	vote = "",
	drop_descrip = "Battleship – Monarch.",
	feeling4 = "So, they can still laugh together... Perhaps I wasn't discarded for nought, then... I have never felt this way before.",
	lose = "Am I... being discarded yet again?",
	feeling1 = "Are you saying that I am inferior to them?!",
	skill = "Not even the Queen's orders can subdue me!",
	upgrade = "Hmph, sure enough, I am the most excellent of the King George V class.",
	propose = "Even if the world no longer needs me, you will always need me. That is more than enough for me... Hahah, perhaps I was materialised with the sole purpose of meeting you. Even if so... I am happy.",
	feeling5 = "Commander, to me, you are the most special, most dear person in existence. You always have, and always will be...",
	main = "Wales and York... I despise them for bereaving me of my existence, but I cannot resent them for succeeding me.|A younger sister? If I have one, her name would be... Prince of Wales... That has a rather nice ring to it.|I will make the world understand how foolish it was not to choose me.",
	touch = "Is my presence needed, Commander?",
	voice_key_2 = -1,
	mission_complete = "For as long as I exist, it isn't over. I am excellence itself, therefore I must exist.",
	battle = "Depend on me! I will make sure this fleet returns home without as much as a scratch!",
	id = 299020,
	gift_dislike = "",
	gift_prefer = "A wonderful gift this is!",
	profile = "I am the battleship named Monarch, one of the rejected King George V-class designs. Hmph, though I was once forgotten, now I live and breathe...",
	voice_key = 29902,
	headtouch = "",
	feeling2 = "I only survived in that dark world by believing that I am excellence itself, and thus irreplaceable...",
	login = "Splendid; you're back. I, Monarch, am superior to the likes of Wales and York. Wouldn't you agree, Commander?",
	detail = "You are the one and only being who matters to me... Until I met you, there was nary a single soul who believed in me.",
	couple_encourage = {
		{
			{
				20506
			},
			1,
			"I am George, Elizabeth, and Edward... but I will never be \"Wales\"!",
			0
		},
		{
			{
				20507
			},
			1,
			"In another world, perhaps I would've been your real big sister.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[299021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "",
	unlock = "Hmph. One's outfit is merely superficial. True nobility must come from within. Don't you agree, Commander?",
	touch2 = "I admire your bravery. Now would you rather I stab or trample you? Or would you prefer to taste a volley from my guns?",
	mission = "",
	vote = "",
	drop_descrip = "Hmph. One's outfit is merely superficial. True nobility must come from within. Don't you agree, Commander?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "nil|Shall I teach you the Royal Navy's courtly dances?|Such splendid dress is normally reserved for special occasions. But for me, every day I exist is a day to be celebrated.",
	touch = "You like this dress, do you? Hmph, I see you've learned the art of empty flattery from Wales. But nonetheless... thank you...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Allow me to demonstrate the elegance with which a lady of the Royal Navy comports herself.",
	id = 299021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Don't just stand there gawking, Commander. There remains much to be done today.",
	detail = "Stand up straight and puff out your chest, Commander. You're the only one I deign to— You're not sure where to look? Well, why not look me in the eyes then?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[299022] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "",
	unlock = "So, an Eastern outfit this time... Hmph. My nobility is evident regardless of what I wear. However, since you prepared this outfit especially for me, it would be unbecoming of me to not express my gratitude. Thank you.",
	touch2 = "Have you been afflicted with Wales's vile proclivities? Commander?",
	mission = "",
	vote = "",
	drop_descrip = "So, an Eastern outfit this time... Hmph. My nobility is evident regardless of what I wear. However, since you prepared this outfit especially for me, it would be unbecoming of me to not express my gratitude. Thank you.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Tsk, Wales, must you always pester me with this Dragon Empery chinoiserie? I'll learn about their customs myself, without you.|A New Year's wish? Naturally, I wish to prove you were right to choose me. That isn't going to change.|Though I am a proud lady of the Royal Navy, I find myself deeply moved to have this chance to experience a festival from an exotic culture.",
	touch = "You desire my company? You should have said so.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 299022,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "This festival comes but once a year. I shan't let you waste it working yourself to death. Come, let me handle that. The fleet will survive you taking a break.",
	detail = "\"Paint our jubilant memories of this festival into history\"? Hmph, she's as grandiloquent as ever, isn't she?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[299023] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Did PhantoM send you a new calling card? Read it at once.",
	expedition = "",
	win_mvp = "",
	home = "Didn't think you'd be back so soon. Hm? What's this? You've pieced together all the clues in all the case files thus far? Bloody good job. This is why I say you're my most trusted partner.",
	unlock = "This common thief – calls herself \"PhantoM\" – is running circles around the Metropolitan Police. Now they've come to me for help... Bet they never thought this day would come when they demoted me to the sticks. On the bright side, we get to detect side by side again.",
	touch2 = "You've picked up some bad habits while I was gone. But fine, I'll turn a blind eye this one time. Only because we're partners.",
	mission = "",
	vote = "拉票描述",
	drop_descrip = "This common thief – calls herself \"PhantoM\" – is running circles around the Metropolitan Police. Now they've come to me for help... Bet they never thought this day would come when they demoted me to the sticks. On the bright side, we get to detect side by side again.",
	feeling4 = "",
	lose = "Bugger, I blew it... I'm going to hate writing this apology.",
	feeling1 = "",
	skill = "There's nowhere left to run!",
	upgrade = "",
	propose = "",
	feeling5 = "\"Stay with me, my partner. There's no one else like you in the world... \"That line wasn't in the script\"? You're right, it's not. I added it just now.",
	main = "This city has changed so much I don't recognise it anymore... Hmph, it's no wonder why PhantoM is so drawn to it. It's a bloody mess.|Buddy, it's time to go! To PhantoM's target! I've sent instructions to the task force already. That sodding thief isn't getting away this time!|PhantoM always knows where the force sets up traps for her... Hmph. There has to be a conspirator in our midst. Partner, who do you think it is?|I'll catch this PhantoM bastard even if it's the last thing I do. Then the whole force will see that I am the most excellent detective!",
	touch = "Hm? Have you found a new clue? ...No? You were just staring at me? Then why do you hesitate, my friend?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Drop your weapons! Stop resisting!",
	id = 299023,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Is... this some new city etiquette I missed the memo on?",
	feeling2 = "",
	login = "You've returned. I've organised your paperwork and written up the case in general and in detail. Heh... Now it is time to prove how much better we are than them.",
	detail = "You want to showcase our bond as partners and deliver a performance as realistic as possible, and so you'll keep your script hidden from me? ...Sounds like you're really enjoying this. Very well, I'll try to live up to your expectations.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[299024] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "We must congratulate the team's efforts, regardless of how the commission went... Yes, I understand.",
	win_mvp = "Relishing the beach and victory – that is how I celebrate my holiday with you. Hmph.",
	home = "You've returned. Have you enjoyed the beach to its fullest? ...Me? I've done more than just sit here and wait for you. I think so, at least...",
	unlock = "Whew... Surely now one can argue that I'm \"enjoying the beach,\" yes? ...Still not enough? I am laying my exposed self bare before you – what more is there I need to do?",
	touch2 = "Is it the beach you're enjoying, or is it me you're... No, forget it.",
	mission = "This is no time to fuss over being the most excellent. Complete your missions so we may enjoy the beach.",
	vote = "",
	drop_descrip = "Whew... Surely now one can argue that I'm \"enjoying the beach,\" yes? ...Still not enough? I am laying my exposed self bare before you – what more is there I need to do?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Though I may forget my duty momentarily, you have not changed in my eyes. You accepted me, guided me, and taught me how to enjoy everyday life... Hm? You've yet to teach me all the ways to have fun? Ugh – that is an unnecessary addition!",
	main = "I know everyone enjoys the beach in their own way, but how do you typically do it? I can't imagine you always sit and stare at people like this...|You say I take competitions all too seriously, even informal games between friends? I hate to admit it, but... you're right.|The sunshine is getting stronger. Whew... Are you alright, Commander? Should I bring you a cold beverage?",
	touch = "Suntan lotion? Oh, right. Appreciated...",
	voice_key_2 = -1,
	mission_complete = "Mission rewards have arrived. Now we can all better enjoy the beach, can we not?",
	battle = "I shall demonstrate how a monarch enjoys the beach!",
	id = 299024,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "While clothes are just a flourish, we are told to dress appropriately back home... I'd love to hear a reason for why I must wear this.",
	detail = "I look forward to the closing bonfire party George and the others are preparing. Will you be there, Commander? Ah, no, of course you will. They would not be making such grand preparations if you weren't coming.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[399010] = {
	hp_warning = "A fight with our backs to the wall? ... Exactly what I wanted!",
	feeling3 = "I'm cool, you say...? If anything, I am somewhat jealous of how everyone can always have a smile on their faces... In contrast, I simply do not know how to express my emotions...",
	mail = "Milord, your mail... Huh? You'd like me to read it? B-but that's embarrassing...",
	expedition = "Milord, the comm... Um, whatever these are called. Yes, they're done now.",
	win_mvp = "My skills are but party tricks, unworthy of such praise.",
	home = "Milord, if you are ever injured, please allow Ibuki to treat you with this mugwort liniment. There's still a lot left.",
	unlock = "Was it your voice that beckoned me from my timeless slumber? This lowly Ibuki, though still in training, shall be yours to use as you see fit.",
	touch2 = "Clear the mind, and purify the six roots... Eek! Mi, Milord...",
	mission = "We seem to have new missions. Would you like Ibuki to accompany you?",
	vote = "",
	drop_descrip = "Heavy cruiser – Ibuki.",
	feeling4 = "After spending a lot of time with everyone else, I've experienced firsthand how difficult it can be to express my emotions clearly... such as joy... and love...",
	lose = "Ugh... I must increase my training multifold.",
	feeling1 = "Had I known I would have to serve a person like you, I never would have manifested during this era...",
	skill = "The pinnacle of Ibuki... resides in this single strike!",
	upgrade = "Is this... the sensation of getting stronger? Thank you!",
	propose = "I never knew that having my feelings be reciprocated could be so overwhelmingly joyful... Milord, p-please don't look at me... I'm so happy that... my face must look strange... ",
	feeling5 = "The mugwort on Mount Ibuki is said to symbolize love that burns quietly... F-For example, right now, Milord... can you feel Ibuki's heart?",
	main = "Spending time alone with Milord... somehow... makes my heart pound... |Milord, if you have no further orders for me, may I go over there to meditate? |In order to hone my swordsmanship, I practice my strokes a thousand times every day... Don't worry, Milord, I already finished while you were gone.",
	touch = "You'd like me to put on a show? S-Sorry... in front of other people... I can't...",
	voice_key_2 = -1,
	mission_complete = "Milord, there's a big pile of stuff over there... Um, are those the rewards then?",
	battle = "The battlefield is callous... Ibuki, advancing!",
	id = 399010,
	gift_dislike = "",
	gift_prefer = "Thank you, Milord. I'll treasure this.",
	profile = "Milord, are you interested in me...? Mm... this Ibuki, who was never born, and has no history or accomplishments to speak of... Um, my hobby is poetry, and I'm skilled in swordsmanship! Are you satisfied with that? Um, also, I'm not very good around people...",
	voice_key = 39901,
	headtouch = "",
	feeling2 = "I would also enjoy a life of sitting atop the mountains, watching the clouds pass through the sky. But my current life here isn't so bad either.",
	login = "Milord, you must be tired.",
	detail = "Milord, w-welcome... I wasn't able to prepare much for your arrival... but would you like some tea?",
	couple_encourage = {
		{
			{
				299010,
				299020,
				399010,
				399020,
				499010,
				899010,
				199010,
				199020,
				399030,
				399040,
				499020,
				999010
			},
			1,
			"Feeble though I may be... I shall give this my all!",
			0
		}
	}
