_G.pg.base.ship_skin_words[399015] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome back, Milord. Would you like some cold ramune to relax with?",
	unlock = "Thank you for accepting my invitation... The sea breeze blows pleasantly here, but if it's still too hot for you, allow Ibuki to present you with some cold ramune... Milord, if you would like some... Wh-what's drawn in the sand behind me? I-it's nothing...!",
	touch2 = "Eek?! M-Milord, umm... there are no rocks to hide us here...",
	mission = "",
	vote = "",
	drop_descrip = "Thank you for accepting my invitation... The sea breeze blows pleasantly here, but if it's still too hot for you, allow Ibuki to present you with some cold ramune... Milord, if you would like some... Wh-what's drawn in the sand behind me? I-it's nothing...!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "The waves may wash away what I drew in the sand, but it matters not. My feelings for you will last for as long as the sea breeze blows. Ibuki's place is forever by your side, Commander...",
	main = "The briny smell of the breeze is a world of difference from the crisp winds of the mountains... But any scent is soothing with you by my side, Milord.|Shall we take a walk by the beach, Milord? There is something... quite important Ibuki wishes to tell you...|Milord, burying your feet in the warm sand feels quite good. Would you, hm... like to try it with me?",
	touch = "Here, Milord, have some ramune. It is your favorite flavor.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 399015,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Huh? The sea breeze is... messing up my hair?",
	feeling2 = "",
	login = "Milord, you're here. The sun feels quite pleasant... Shall we take a walk along the shore... Watching the rolling waves?",
	detail = "Admittedly, it is quite easy to move around in this swimsuit... Eh? What did I draw in the sand...? Oh, why would you ask me when you already know... Aah...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[399020] = {
	hp_warning = "P-put out the fire...!",
	feeling3 = "*Sigh*... Why do you always make that miserable face, Commander? It's so miserable that... it makes me want to scold you...",
	mail = "Here's a letter. It's rude to the sender to not read their letter thoroughly. Don't you agree?",
	expedition = "Commission complete. Why don't you go on one yourself, sometime?",
	win_mvp = "Victory? Of course we won!",
	home = "Look who's back. Time's precious, so start reflecting on your last sortie immediately.",
	unlock = "Battleship Izumo, reporting in. Are you the Commander? Sure don't look very reliable... Listen here: do anything to slow me down, and you won't hear the end of it!",
	touch2 = "... I-I'll slice your hand off!",
	mission = "What are you planning to do about these unfinished missions?",
	vote = "",
	drop_descrip = "Battleship – Izumo.",
	feeling4 = "Hey, you've started getting just a bit into shape recently... Hmph, I suppose I'll acknowledge you've worked hard.",
	lose = "Damn... I can... still fight...!",
	feeling1 = "You lack what it takes to order me to swing this blade.",
	skill = "Feel the wrath of my blade!",
	upgrade = "My blade grows sharper.",
	propose = "You're making that miserable face again. I just can't leave you be, huh... Listen, today is the day I will acknowledge your hard work... or, should I say, your talent! I, battleship Izumo, swear on my blade to walk with you, both in life and death.",
	feeling5 = "The path of my blade is one of constant solitude... or so I thought. Hmph, maybe being with you... isn't so bad after all.",
	main = "A blade requires careful maintenance. Isn't that obvious?|Sisters... eh. The Izumo class consists of just me, so I guess I'm a bit jealous.|Become stronger, Commander. Once you become strong enough to protect everyone... Once that happens, I...",
	touch = "Commander, you don't have the free time to endlessly chat with me.",
	voice_key_2 = -1,
	mission_complete = "Mission complete... Good lord, would you ever have realized it on your own?",
	battle = "All ships, form up! Target: enemies in front!",
	id = 399020,
	gift_dislike = "",
	gift_prefer = "You really did your homework. Thank you.",
	profile = "I'm battleship Izumo, of the Sakura Empire. I existed as a proposed Yamato-class design, although they didn't construct me... But if you look down me even slightly then prepare to taste one of my main cannon volleys.",
	voice_key = 39902,
	headtouch = "",
	feeling2 = "This blade is my other half. Casually touch it, and you'll get hurt.",
	login = "Late, as always. Just how long will you keep me waiting?",
	detail = "If you've got time to stare at me then maybe do your work instead.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[399021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "How stunning; how gorgeous – to my eyes, the sight of this battlefield is worth ten thousand ryo.",
	home = "",
	unlock = "You'd like to see my classical dance? Your tastes are quite refined, Commander... In that case, I'll show you the finest performance in the land!",
	touch2 = "Commander, are you insinuating you want a swift kick?",
