	login = "",
	detail = "My name has connections to classical dancing...? I-I see...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[399022] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Oh, you're back. Let's get back to our drinking contest, then. Get ready – I can hold my drink better than anyone.",
	unlock = "Finally realized I'm the bartender here? This isn't any ordinary wine, you know. Give it a try, if you're interested. Heheheh...",
	touch2 = "I'm still not drunk yet... You'll rue this day... I-I mean, no! I'll get you back right now...!",
	mission = "",
	vote = "",
	drop_descrip = "Finally realized I'm the bartender here? This isn't any ordinary wine, you know. Give it a try, if you're interested. Heheheh...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "The red liquid dripping from my tail isn't just for cocktails, you know. Who knows how you might change if you drank it directly? Heh... Interested? So am I. Go on, Commander... Give it a try.",
	main = "How can I drink the Commander under the table... If I keep this up, I'm done for...|Huh... Commander! How'd you get tied up in my tail?! Wait, why are you giving it free rein to do as it likes?!|...Did that one taste a little different? The secret is in the hole at the end of my tail. Open up, and I might just let you get a taste of the secret ingredient.",
	touch = "*sigh*... That's good drinkin'... Nnh... Zzz...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 399022,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Mm... Oddly soothing...",
	feeling2 = "",
	login = "I'm good at more than just bartending, you know. Why don't I join you for a round of drinks? ...Worried I'll get drunk? This isn't even enough wine to get me tipsy!",
	detail = "This stuff is stronger than I thought... Huh? Commander?! N-no, I'm not drunk! You're just imagining things!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[499010] = {
	hp_warning = "You dare hurt me...? YOU WILL PAY!",
	feeling3 = "It is our destiny to kill one another on the battlefield... So, wouldn't you say it's normal to revel in the killing just a little bit?",
	mail = "It's not any bad news, is it?",
	expedition = "Those commission girls must work really hard... Okay, everyone line up~ I'm going to give each of you a hug~",
	win_mvp = "Not only did you not sink yourselves upon seeing me, you even forced me to sink you myself... YOU WILL PAY!",
	home = "I want to pummel some enemies, too~ *Giggle*... The more of them you sink, the more you prove your worth, after all~",
	unlock = "I never thought I'd end up here... Hello, I am Roon. I don't know this place very well, so could I ask you to give me a tour?",
	touch2 = "Hm? Do you want a hug, too? Okay~",
	mission = "What might this next mission be? I'm getting a little excited.",
	vote = "",
	drop_descrip = "Heavy cruiser – Roon.",
	feeling4 = "Ahhh... The feeling of tearing apart enemies with gunfire... and breaking them into a million little pieces... I can't get enough of it... You know how I feel, don't you, Commander?",
	lose = "Aww... Did we fall prey to an ambush...?",
	feeling1 = "Commander... YOU WILL PAY!",
	skill = "Don't…look down on me!! ",
	upgrade = "Thank you for that, Commander.",
	propose = "Thank you so much. But listen, I finally understand now. What filled the void in my heart wasn't slaughter on the battlefield or love, it was the hatred known as \"envy\"... Commander, I love you just as much as I deeply, deeply, DEEPLY hate those other girls... THEY WILL PAY!",
	feeling5 = "*Giggle*, I get more fulfillment from being with you than from killing enemies on the battlefield... Is this the power of love? But then...",
	main = "Every time I see something beautiful get squashed on the battlefield, I just... Aahhh...|I want to do something to soothe your mind. But... what should I do...|What my hobby is? Perhaps something like \"granting sweet release\"?",
	touch = "Please open your mouth, Commander... *Giggle*, do you like it? Have I gotten better at cooking?",
	voice_key_2 = -1,
	mission_complete = "Let's give our all on the next mission, too.",
	battle = "*Giggle*... You saw me, and now you're trying to flee...? Do you really think you can flee from ME?!",
	id = 499010,
	gift_dislike = "",
	gift_prefer = "Thank you very much. I like it a lot.",
	profile = "I am Roon, the Iron Blood cruiser. In a far-off world, I never existed beyond the drawing board... But that aside, I've seen it, Commander... Deep within your heart, there's something that resembles me...",
	voice_key = 49901,
	headtouch = "",
	feeling2 = "How I'm faring at the base? Perfectly fine. Although... isn't it a little too peaceful here...?",
	login = "This place is so peaceful. Everyone's so nice, too...",
	detail = "Commander, do you have any interests outside of work? If you're okay with it, why don't we relax together?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[499011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Hehehe... That was another lovely \"banquet.\"",
	home = "",
	unlock = "Such a delightful party with our wonderful friends in this peaceful harbor... It's wonderful, really... But, it's all so boring...",
	touch2 = "Commander... I think you can get closer than that...",
	mission = "",
	vote = "",
	drop_descrip = "Such a delightful party with our wonderful friends in this peaceful harbor... It's wonderful, really... But, it's all so boring...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "When you see something so perfect and beautiful, don't you just feel the urge to... crush it?|Commander, I picked out this dress specifically for the occasion. Don't you feel like it... completes you?| All this merriment is making me nauseous... Commander, can you let me sortie when we get back?",
	touch = "Are you having a good time, Commander? ... Me? Oh I'm just happy to see you~",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "You're just in time, I needed to blow off a little steam!",
	id = 499011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Hah hah... it's not often we have a party. Let's enjoy ourselves, Commander.",
	detail = "Did my dress catch your attention, Commander? ... But when I think about you looking at the other girls' dresses, I just...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[499012] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "I can see the commission team all the way from up here. Well? Are you heading out to greet them?",
	win_mvp = "Heehee... Now that's what I'd call a good \"break\"~",
	home = "Welcome back! Let's give you a nice, waaarm hug♪",
	unlock = "It's so nice getting away from the bustling party hall and being alone with you, Commander. I'm eager to see what we'll do now as your idea of a... \"break\"~",
	touch2 = "Go on – we're all alone here~♥",
	mission = "",
	vote = "",
	drop_descrip = "It's so nice getting away from the bustling party hall and being alone with you, Commander. I'm eager to see what we'll do now as your idea of a... \"break\"~",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Ah, so this is what you meant by \"a break.\" It certainly is a cure for boredom, and I am happy to have some alone time with you, buuut... (I know you're trying to keep me in check, and you're going to pay for that♥)",
	main = "While I like vistas as much as the next person, I'm awfully fed up with the port's scenery at this point. Battlefields differ in that regard... Ahh... I'll never tire of seeing them.|Heehee~ Don't you worry, I'm not going anywhere. Why would I, when it's you who brought me here?|Since we have access to a piano, could you help me work on my singing? I'm starting to feel restless from sitting around for too long... Heehee~",
	touch = "Oh, you're back already? Then please, come here and let your heart be soothed♪",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "How DARE you ruin my special moment with the Commander!",
	id = 499012,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Good timing, actually – the party was starting to bore me. Thanks for pulling me out, Commander~",
	detail = "Mainz's favorite coffee is a nice party drink, though I think I still prefer Iron Blood beer. What do you prefer, Commander?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[499013] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Looks like the commission team is back. Heehee, is there something you were hoping for from me, Commander?",
	win_mvp = "Shall we pick up some ingredients for a late-night snack while we're here?",
	home = "There, there... Excellent job on that sortie. Phew. If you're feeling a bit more rested now, how about a light snack? This is my homemade cooking. I used the freshest ingredients.",
	unlock = "Good evening, Commander. Here, let me give you a late-night hug~ You want to know why my swimsuit's in tatters? Heehee, I ran into an unruly little shark when I went out to get food. To think it tried to resist ending up as my meal... It's going to pay!",
	touch2 = "Want to tear it up some more? Go ahead~",
	mission = "",
	vote = "",
	drop_descrip = "Good evening, Commander. Here, let me give you a late-night hug~ You want to know why my swimsuit's in tatters? Heehee, I ran into an unruly little shark when I went out to get food. To think it tried to resist ending up as my meal... It's going to pay!",
	feeling4 = "",
	lose = "Commander... don't tell me you wanted to see me defeated?",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Phew... It's late, but I'm feeling kind of restless. While I think we should get to bed, I could go for one last round of stress relief♪ You will join me, won't you, Commander?",
	main = "Ahhh, there's nothing like a sharp blade drawing a slit into flesh... Filleting fish is a nice change of pace, you know. Would you like to join me next time, Commander?|You were worried about me? I'm completely fine. I can down a battleship with a single punch, so all I need to do is flail around a bit to make a shark yield.|Letting the sea's nightly breeze caress you as you lie in a soft bed and drift into a peaceful slumber... It would be a bit too peaceful and boring to do every evening, but it's nice and refreshing once in a while. Hehe...",
	touch = "You're going to hug ME, Commander? Go right ahead. Nice and tight~",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 499013,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "You must be exhausted from playing with everyone during the day, Commander. Heehee, just leave your evening relaxation to me.",
	detail = "My swimsuit? Well, I thought you might like it if I tore it up a little, Commander. What do you think? Doesn't it suit me... just as much?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[499018] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Seems the commission team is back. Let's go say hello to them... and get some fresh air while we're at it♪",
	win_mvp = "Mmh! Now that was refreshing. Thank you, Commander♪",
	home = "Time for a welcome back hug, Commander! I can't believe you left me behind while you went out on a sortie... What do you have to say for yourself?",
	unlock = "Commander? You've not only filled the void in my heart, but also wholly embraced my fervid feelings... Ah, you really make me want to do things... Unforgivable things, like opening my heart for you.",
	touch2 = "The urge to ruin something for being beautiful... Heehee. You're just like me, Commander♥",
	mission = "Missions? I'll help you with them, just please be sure to have a reward ready for me at the end.",
	vote = "",
	drop_descrip = "Commander? You've not only filled the void in my heart, but also wholly embraced my fervid feelings... Ah, you really make me want to do things... Unforgivable things, like opening my heart for you.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Impetus and nihility, love and hatred, a surge of desire from the heart – you'd never be the same if you accepted my all, Commander... That's fine by you, you say? I can't believe how kind you are... Heehee. You may think it's fine to wish for that, but to me... Yes, to me, that's beyond unforgivable.",
	main = "When you hold me tightly like this, it makes me feel... a tremendous surge of \"love.\"|While the port can sometimes be boring, what with how tranquil it is, I'll still never tire of any place where I can always be with you. Whether it's me making a total mess of you, or you making a total mess of me... Ahh...|Has anything been troubling you lately? I'm always here to listen. If anyone – no matter who – hassles you, I will tear into them, rip them apart, and grind them into a paste with my own two hands♪",
	touch = "It's so exciting when you do this – touching me without being prompted to♪",
	voice_key_2 = -1,
	mission_complete = "Mission complete... Ah! Heehee, my, I wasn't expecting this hug. Thank you for the reward.",
	battle = "",
	id = 499018,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "A quiet moment, you say? While it may be that way to you, my head and heart are beating so hard it's bringing my sanity to the brink.",
	detail = "Jealous? Well, you and I have already sworn an oath, so I don't see any need to care about anyone else. Say, Commander, why would you ask that? Why would you bring up other girls? You'll pay for that!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[499100] = {
	hp_warning = "Urgh... Thank goodness my flying machine is intact...",
	feeling3 = "It is my fate as the Nachthexe to soar across the midnight sky. Do you know what that means, Commander? ...Huh? You know just how I feel and what I want? Okay, I understand...",
	mail = "Is this an invitation to the Night of Witches' Flight? Consider it accepted. Off we go!",
	expedition = "The girls that went on a commission are back. Perhaps they've brought magic components for my Midnight Wings with them?",
	win_mvp = "Gaze in awe! Know the Nachthexe's might!",
	home = "Praise to you, Commander. Rest while you can, for we'll soon make haste to the soaring witches' night gathering! ...It'll be a long ride!",
	unlock = "Hmph, so even the famed Commander wishes to be free of the shackles of gravity... D-do you, really? If you acknowledge my abilities, I might very well... lend you this flying machine – blessed with witchly powers.",
	touch2 = "Heehee... So you've fallen for this witch's charm. Care to experience the joy of falling from the sky as well, hm?",
	mission = "You can't forever gaze at the skies – you need to touch the ground and carry out your missions. Go forth, Commander!",
	vote = "",
	drop_descrip = "Battleship – Mecklenburg.",
	feeling4 = "You said you know how I feel and what I want, so you'll be the one to name my plan for tonight! Indeed, you and I will fly together for the entire night! A-and I really do mean the entire night, so...",
	lose = "We were THIS close! I'm SO gonna rain hellfire on them next time!",
	feeling1 = "You really don't understand the greatness of flying. You'll just have to walk with the rest of the commoners.",
	skill = "Heehee... See what the Nachthexe is truly capable of!",
	upgrade = "My witchly power grows and grows! Tonight, I shall rise with the blood moon!",
	propose = "Commander, our souls are drawn to one another... Every night from this day on, I will bring you on a journey through the skies, and I will make the dark night dance for you until morning comes. This is the Nachthexe's everlasting spell.",
	feeling5 = "Commander, these are my Wings of the Dark Night. My witchly power is concentrated in them, and they're for you alone. Do you like them? Don't worry – I'll keep you safe. I won't leave your side.",
	main = "I've run a little short of magic components for the next-generation flying machine I'm working on... Will you come help me look for some tonight, Commander?|Ahem. What I have in my hand is the Magical Tome of the Dark Night. It will allow me to seize incredible powers that– Hm? It's a night battle notebook? A-ha! All the more reason to read it.|The flight plan for the new Dark Oracle – running on my pure witchly power, of course – is set for midnight! Its official designation shall be... Huh? \"Operation: Skyfall\"? No! Absolutely not! My powers would never fail and lead to a crash!|Seeing as the port has no notable events planned for tonight, it seems the airborne gatherings that I host can continue! I could bring in a rock band for tonight's climax... Ahahaha! I must continue preparing for the flying show!",
	touch = "Hm? Do you want to revel in the dark night together?",
	voice_key_2 = -1,
	mission_complete = "Do remember to claim your rewards, alright? Or else I'll take them for my own purposes.",
	battle = "Things are heating up, I see. I hope you've braced yourselves for the Nachthexe's wrath!",
	id = 499100,
	gift_dislike = "",
	gift_prefer = "Hmm! I love this! It's perfect for a fun evening!",
	profile = "I am the Nachthexe, otherwise known as Iron Blood battleship Mecklenburg. Listen to the symphony of boiling blood and madness! To the poem of electric guitars and drums in tandem that pierces the sky! As my witchly power surges, to the lonesome, lofty sky realm shall I ascend!",
	voice_key = 49910,
	headtouch = "Can you feel my witchly power? I'm brimming with it!",
	feeling2 = "A witch defying gravity knows too well the world of loneliness. Heehee... Keep your eyes out during the night, and you'll see me flying across the face of the blood moon.",
	login = "Commander, behold this impeccable weather. Even nature's ambient waste dares not show itself... You want to freely soar the skies with me, eh? Hah! Fittingly, I just recharged my flying machine. Wanna go for a ride? I said: Wanna go for a ride?!",
	detail = "Should the sun, to shine, refuse, the eternal blood moon will rise with you. The witch shall recite a dark incantation. The heavens shall crack from light, wings of destiny shall take flight, then comes the oracle of the dark night – this eve, who shall join me in the sky?",
	couple_encourage = {
		{
			{
				30201
			},
			1,
			" Have you ever seen a flying machine brimming with witchly powers before?",
			0
		},
		{
			{
				110201
			},
			1,
			" Do NOT touch my flying machine! I mean it! It'll curse you!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[499101] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Splendid! You fought well! The power granted by my brand lets you conquer everything, doesn't it?",
	unlock = "Commander – I mean – Imperator! You've been seeing me far too little as of late, which has left me in a very sour mood. I will punish you by inscribing my seal on your body, so that you'll remember me! Um... How do I do this, again?",
	touch2 = "Agh... Why does this pleasure feel like being launched skyward?!",
	mission = "Go, my Imperator, and realize your duty! Complete your missions before I imprint my brand upon you!",
	vote = "",
	drop_descrip = "Commander – I mean – Imperator! You've been seeing me far too little as of late, which has left me in a very sour mood. I will punish you by inscribing my seal on your body, so that you'll remember me! Um... How do I do this, again?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "I feel it... Power surges from within my body!",
	propose = "",
	feeling5 = "By the pact of this brand, you are to grant me the power to fly, Imperator... Not yet? Oh. Well, then let's take this time to \"deepen\" this bond between us. Soon, it will be time... Heehee♥",
	main = "Welcome to my domain! Now come and revel in this pain that gnaws at the soul; in this pleasure that sends you to the heavens!|Hm? Why do you have a marker pe– I mean, a Branding Mark? Do you seriously mean to brand me? I'd love to see you try to– W-wait! Not my thigh! It tickles like mad!|The whip? Oh, you mean this? Yes, I felt a tremendous power flow into me the moment I took it in hand. I feel an even greater power when I swing it! Go on, you give it a try as well!",
	touch = "Even if you'd welcome receiving my brand, it's too late to– Huh? You wanted my brand since the very start?",
	voice_key_2 = -1,
	mission_complete = "You're finished? That was rather quick. Are you that excited to receive my brand?",
	battle = "",
	id = 499101,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Oh? Do you want my brand more deeply imprinted on you?",
	feeling2 = "",
	login = "Welcome to my shop of refreshments, Imperator. I'm glad you answered my call. Now, let this searing pain leave a mark on your memory!",
	detail = "Ahem... You are my Imperator alone, and I am your Nachthexe alone. This night together shall deepen our bond.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[899010] = {
	hp_warning = "This too... is God's trial...!",
	feeling3 = "I see my sisters in arms smile every day as if without a worry in the world. Perhaps this is their Canaan...",
	mail = "Commander, does it not matter if these letters remain unopened?",
	expedition = "Commander, my sisters in arms have returned from their commission.",
	win_mvp = "Ashes to ashes, dust to dust...",
	home = "Suffering is the brand of a warrior. Everyone, I'm proud of you for making it through.",
	unlock = "It is an honor to meet you at last - my prophet, my leader. I am Saint Louis, brought to your side by God's will. As long as it is justice that guides your hand, then this humble spear shall be yours to wield.",
	touch2 = "Commander, your self-respect...",
	mission = "Commander, it may not be the will of God, but you do have new missions issued from headquarters.",
	vote = "",
	drop_descrip = "Heavy cruiser – Saint Louis.",
	feeling4 = "I feel like I have earned the acceptance of the fleet. However, is this truly the land that I was promised? ... No, I do not mean to cast doubt upon anyone. I merely feel that... I may yet have a deeper purpose.",
	lose = "My Lord, why have you abandoned me...",
	feeling1 = "My sisters in arms here may be righteous, but not you. Prepare to face divine punishment, sinner.",
	skill = "God's love is boundless.",
	upgrade = "For the sake of the role that we all must play...",
	propose = "This I do swear. Your joy is my will, your victory is my glory, and the place that I can call home, is by your side... Blessed be the Lord who has brought me together with you – my commander, my love, and... my light.",
	feeling5 = "I finally understand now, Commander. What I experience now is the same as my sisters in arms – nay, perhaps even more fulfilling. Being a part of this fleet, by your side... is truly my Canaan.",
	main = "Commander, your time should not be squandered here. Leave the chores to me. |If there are any disputes within our ranks, allow me to handle the arbitration. That is my specialty. |Just winning the battle alone is enough to satisfy me, but you, Commander, ought to look far beyond that.",
	touch = "I fight so that there may be peace. That is the single role that I can play.",
	voice_key_2 = -1,
	mission_complete = "While rewards may certainly be nice... I have no interest in them.",
	battle = "You shall all be purged equally!",
	id = 899010,
	gift_dislike = "",
	gift_prefer = "Thank you.",
	profile = "Because ruination befell my homeland, I was returned to nothingness before I was born. As I am now, I am but an illusion, a manifestation of an ideal. But as long as you continue to lead my way, I shall in return clear all obstacles standing before yours.",
	voice_key = 89901,
	headtouch = "Commander, I do not think this can be considered appropriate conduct...",
	feeling2 = "So this is the land that I was promised... Tell me, will this place be Sodom, or Canaan?",
	login = "Bonjour, Commander. Please instruct me, what should we do next?",
	detail = "Commander, have you come here to offer your prayers to God?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[899011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "I would much rather wield my spear upon the seas of battle than sit up here like a statue, Commander.",
	unlock = "With all due respect, Commander, this finery and this throne are not fit for one such as myself. Despite the hallowed name I have inherited, I am nothing more than a warrior. —However, if such an arrangement pleases you, then I shall hold my objections.",
	touch2 = "",
	mission = "",
	vote = "",
	drop_descrip = "With all due respect, Commander, this finery and this throne are not fit for one such as myself. Despite the hallowed name I have inherited, I am nothing more than a warrior. —However, if such an arrangement pleases you, then I shall hold my objections.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "As a servant of God, there is no need for vanity— Having that said, as the recipient of your love, you are free to make any arrangements that please you. After all, great and permissive is God's love.",
	main = "So I've managed to capture your gaze? Your eyes are... Nevermind, it doesn't bother me.|My arbitration is needed? ...Very well, please excuse me for a moment. I will make sure to hear them out.|As the one guiding this fleet forward... Commander, you are the one best suited to this throne.",
	touch = "My weapon is always within reach. Should you will it, I am ready to sortie at any time.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 899011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, making me sit up here waiting for you by myself is a tribulation in its own right.",
	detail = "I have no serious objections to sitting up here, but... there is one thing I cannot figure out. Are you perhaps deriving pleasure from seeing me up here like this?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[899012] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Commander, our comrades-in-arms have returned from their commission. Let us take over their responsibilities so that they may enjoy the Spring Festival.",
	win_mvp = "",
	home = "God witnesses all your deeds. The trials you endure today will surely bear fruit in the future.",
	unlock = "Commander, regarding your next appointment... Ah, hard work is one of the highest virtues of the Iris's holy knights. On weekdays or vacations, in knights' armor or the Dragon Empery's attire, there can be no pause to my prayer, my training, or my duties as the administrator of your will.",
	touch2 = "A-ahem!",
	mission = "Here are today's assignments. Let's work together to finish them quickly.",
	vote = "",
	drop_descrip = "Commander, regarding your next appointment... Ah, hard work is one of the highest virtues of the Iris's holy knights. On weekdays or vacations, in knights' armor or the Dragon Empery's attire, there can be no pause to my prayer, my training, or my duties as the administrator of your will.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "The Dragon Empery's Spring Festival... the celebration of a new year seems quintessential to all. Please rest well after completing your work.|La Galissonnière... seems to be thoroughly enjoying this holiday. Rather, that girl seems to be able to find enjoyment in just about anything. Quite broad-minded of her.|The greatest joy is to be able to have a life of peace. If everyone can act in accordance with God's will, then there would be no need for justicars.",
	touch = "",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Be cleansed in the Iris's light!",
	id = 899012,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Bonjour, Commander. Please determine the duty you would like to fulfill first today.",
	detail = "Let us also give our utmost this coming year, as to not squander the preparations everyone has painstakingly made.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[899013] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome back. I'm relieved to see you return unharmed. Thank you for allowing me this rest in your absence. I am now in perfect condition.",
	unlock = "...Commander? When did this happen...? Sorry, I must have misjudged my alcohol tolerance. Don't worry, I shall not let my guard down over something like this... Yesh... I have not let my guard down... at all...",
	touch2 = "Am I to take it that you're fond of this flavor, Commander?",
	mission = "",
	vote = "",
	drop_descrip = "...Commander? When did this happen...? Sorry, I must have misjudged my alcohol tolerance. Don't worry, I shall not let my guard down over something like this... Yesh... I have not let my guard down... at all...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Commander, that smile of yours... is a little different than what I usually see. Is it because you saw me in a less disciplined state? How curious that I do not find the current situation to be all that unpleasant...",
	main = "The solemn duties of combat and arbitration must not be carried out with vagueness or deceit. And yet, I find myself less disciplined in your presence, Commander... so much so that I can hear my own heart pound...|I'm sorry, Commander. Forgive me for being unable to drink with you any longer. Freedom must not be an excuse to indulge. I must keep my wits about me in order to protect you.|The lights of this banquet feel much warmer than the flames of the battlefield. You have nothing to fear, Commander. I shall always be able to distinguish your light from any other.",
	touch = "Commander... it seems I have made a terrible error.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 899013,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Aaah... Zzz... Mm? Oh, forgive me. It seems I unintentionally let my guard down in your presence.",
	feeling2 = "",
	login = "Is your glass empty, Commander? Worry not. It seems the alcohol is affecting me somewhat... but I won't forget my duty to pour you another drink.",
	detail = "My body may be disobedient at present, but I still wish to conduct myself properly before you... I-I wonder whether I may be forgiven for lying down in such a manner.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[199010] = {
	hp_warning = "C'mon, team, we can do better!",
	feeling3 = "I love throwing parties, but I'm not gonna FORCE anyone to show up to 'em. But I guarantee anyone who does show up is gonna have a heckin' good time, even the super-introverts!",
	mail = "Commander, you've got new mail! Hell, it might be an invite to a party!",
	expedition = "Yo, commission team's done, Commander. We oughta go give 'em a snack or something!",
	win_mvp = "Victoryyyy! Let's throw a big party when we get back!",
	home = "Fighting's important and all, but you gotta take regular breaks, Commander!",
	unlock = "Sup! You the one who woke me up? Alrighty then~ The name's Seattle! Nice meeting you!",
	touch2 = "Listen, if you did that on purpose, then consider my gears grinded!",
	mission = "New missions! We need more manpower up in here!",
	vote = "",
	drop_descrip = "Light cruiser – Seattle.",
	feeling4 = "Glad you finally understand the magic of parties, Commander! That magic being: you can make friends with anyone if you just hang out with them! As an example: me and you are best buds now!",
	lose = "Man, if only we'd brought more firepower~",
	feeling1 = "Hm? My party? You're not invited, so be a good commander and get back to work.",
	skill = "Let's get some hype up in this place!",
	upgrade = "I feel like I could snipe a mosquito out of the air!",
	propose = "Okay, I'm 100% ready for this! Oh, and needless to say, I love you too, Commander! I wouldn't invite you to go drinking if I didn't~ So, back on topic... There's one more thing we gotta do today besides partying – it's go on a date! Dee-ay-tee-ee!",
	feeling5 = "Hey, we're BFFs, so tell me who's your crush and I'll give you some hot tips~ Heheheh~ ... It's me? Wait, hold up, you serious? Y-y-you really mean it?!",
	main = "Hey, Commander... Isn't it kinda lonely with just one secretary? Whaddya say we liven it up and get some more peeps in here?|You free once you're done with work today, Commander? Listen, I'm throwing a cool party later! You can drop by any time if you want!|I've got zilch combat experience on paper, but with everyone teaching me stuff, I'll catch up in no time!",
	touch = "Commander, you wanna do some dance practice? You'll rise on the girls' popularity lists if you can dance well!",
	voice_key_2 = -1,
	mission_complete = "Mission complete! Aren't you gonna celebrate, Commander?",
	battle = "All right, let's gang up on 'em!",
	id = 199010,
	gift_dislike = "",
	gift_prefer = "Ooh~ Thank ya very much!",
	profile = "Heyoooo! The name's Seattle– Err, I don't technically have a real name, but just call me Seattle! Seriously, don't sweat the small stuff! Anyhow, I was one of the prototypes for the Worcester class, and as an improvement on the Atlanta class, AA is my A-game! Just leave anything with wings to me!",
	voice_key = 19901,
	headtouch = "",
	feeling2 = "Mi amigo, you oughta let up on your jabberwocky mission talky and just live a little sometimes. Listen, I'm throwing a party later, so stop by and have some fun, alright?",
	login = "You eat yet, Commander? If not, would you like me to whip something up real quick?",
	detail = "I've got a party, tea time, girls meetup, and drinking get-together to attend... Okay! My schedule is PACKED! Guess that's not really a bad thing, though!",
	couple_encourage = {
		{
			{
				10206,
				10207,
				10208
			},
			1,
			"Hey, you girls wanna come to my party once we're done here?",
			0
		},
		{
			{
				30402
			},
			1,
			"I wanna know more about these Sakura Empire banquets you throw!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[199011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "",
	unlock = "Hey! Great to have you here, Commander! I've gotta ask, whaddya think of my dress? Looking real gorgeous, right? ...Phew, awesome! I was worried my dress didn't look nice and might be dragging down the party mood, that's all!",
	touch2 = "Eek! Hey pal, I think you might be a little tipsy there.",
	mission = "",
	vote = "",
	drop_descrip = "Hey! Great to have you here, Commander! I've gotta ask, whaddya think of my dress? Looking real gorgeous, right? ...Phew, awesome! I was worried my dress didn't look nice and might be dragging down the party mood, that's all!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "As much as I love me a hype party, I totally get the appeal of the occasional formal banquet like this. This way I can have some alone time with my sweetheart, y'know? Oh man, I'm feeling pretty dang drunk right now... Mmhh, shleepy...",
	main = "What kind of drink do ya want, Georgia? Ah, an Oxycola sour on the rocks? So the usual, then? You got it!|So like, you know parties are a group activity, right? Let's get you away from your drinking-alone corner and out in front of some friends!|I spy with my little eye a few peeps who don't party much... Just gimme a few minutes. I'm gonna go hit 'em up!",
	touch = "What's your poison, Commander? There's always soft drinks if alcohol's outta your league.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Heheh! Let's totally rock this place!",
	id = 199011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Hey! Welcome to my fabulous party, Commander! We're the life of the party tonight, you and I! Well, kinda.",
	detail = "I dig how super-refined I look with this violin! It's not just for show though, I've got a little number for you! Check this out!",
	couple_encourage = {}
}


