	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "All righty, that should about do it for the food preparations.",
	unlock = "Meeeerry Christmas~! Even though the party is about to start, as you can see, I'm still getting ready~ Just gimme a moment, all righty~?",
