_G.pg.base.ship_skin_words[199023] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "",
	unlock = "Happy New Year, Commander! I guess you dress up all flashy like this for the Sakura New Year. Would you escort me...? What are you gawking like that for...? Haha, am I so dazzling? Hahaha!",
	touch2 = "Hey now, you're going to mess up my outfit.",
	mission = "",
	vote = "",
	drop_descrip = "Happy New Year, Commander! I guess you dress up all flashy like this for the Sakura New Year. Would you escort me...? What are you gawking like that for...? Haha, am I so dazzling? Hahaha!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "So this \"Momotarou\" pops out of a peach! What an amazing little guy!|Seattle, I got an invite to this party or something. Any idea for a talent show? It has to be something better than the \"Georgia Beam\"!|Commander, I just finished my new drink - mixing cola with tea! Come on, try it!",
