_G.pg.base.ship_skin_words[199060] = {
	hp_warning = "*yaaawn*... I'm getting exhausted...",
	feeling3 = "Commander? The weather is so nice. Just let me lie down a little... Hmm... Or you could join me?",
	mail = "Wanna... check your mail? I'll leave it up to you...",
	expedition = "The commission's completed? Great. I'll wait here for you to come back, so you go welcome them home...",
	win_mvp = "Welp, we won. How about we just head back now? There are too many people here... It's not great for my mental health.",
	home = "Thanks for all your hard work... Where should we go rest now? My place, or yours?",
	unlock = "Mmm... Commander? I was just resting my eyes. I didn't think you'd get here so fast... Ahem. I'm battleship Kansas with the Eagle Union, and I'm ready to fight for you any time. By the way... are there any missions I need to fight in today?",
	touch2 = "Commander, I'm awake right now...",
	mission = "Hmm... Are we assigning tasks now?",
	vote = "",
	drop_descrip = "Battleship – Kansas.",
	feeling4 = "It's so quiet here in your office... Can I slack off – ahem, stay with you a little longer? If you need me, just wake me up... Hmm? I'm being too obvious? Who cares... Good night...",
	lose = "Oh, okay. So we lost. Gather the fleet and get ready for retreat...",
	feeling1 = "Don't waste your energy, Commander... Never mind. Do what you want...",
	skill = "I have awakened. Bring it on!",
	upgrade = "Hmm. Now I can relax in style.",
	propose = "Commander, you wouldn't secretly make such a big decision while I was sleeping, would you? You might not realize it, but I'm always watching you... I promised I'd fight for you any time, so of course I'll stay by your side... Mm... Suddenly, I'm really sleepy. But now, I can sleep next to you all the time...",
	feeling5 = "How long have you been staring at me now... I can't sleep well if you keep doing that... What? Would I rather sleep alone or with you watching me? That's a hard choice... I do sleep better with you around, though.",
	main = "Mm... If there's no special work to be done, then let's go look at the scenery and find a place to doze... I'll let you pick the place...|Commander, you mentioned going to a seminar... Whatever it is, there must be too many people there. I don't think I have the energy for it...|I did all your work for you already... Hmm? That was too fast? That just shows how hard I worked... Yep, time for bed.|I wasn't slacking off this whole time... I just used up all my energy when you weren't looking. I'm only resting right now... so I can be ready to fight for you...",
	touch = "Mm... Ready to fight, just say the word... *yawn*... Oh, you're just touching me? Have at it, then...",
	voice_key_2 = -1,
	mission_complete = "Missions are done. How about a nap?",
	battle = "Then today, I fight for the Commander! But let's get it over with quickly...",
	id = 199060,
	gift_dislike = "",
	gift_prefer = "Hm? I love everything you pick out for me, of course.",
	profile = "Union battleship Kansas... Zzz... Oh, I'm not actually sleeping. It's just hard to be energetic... Don't worry. I'm still ready to fight for you.",
	voice_key = 19906,
	headtouch = "Commander, your hand... Actually, never mind. It's fine there.",
	feeling2 = "Did you come to wake me up again? Mm... Okay. I'm ready to set sail at... Zzz...",
	login = "*yawn*... Another new day. I'm ready whenever, just say the word... Mind if I take a nap first, though?",
	detail = "My hair? *sigh*... If it's not messy, then don't worry about it. It's easier to just let it all hang... Hm? Of course... It makes it easier to sleep comfortably.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[199061] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "*yawn*... Good work. I actually just built up enough energy to come see you. So... Want a drink?",
	unlock = "*yawn*... That's enough rest. It's just you and me tonight... Whatever it is that you want from me, I've stored up enough energy to go all the way.",
	touch2 = "Hmm... Maybe it's time I unleash my full power. I just hope the energy I have left is enough to satisfy you...",
	mission = "Commander, missions just came in... The sooner you finish them, the sooner we can get back to relaxing.",
	vote = "",
	drop_descrip = "*yawn*... That's enough rest. It's just you and me tonight... Whatever it is that you want from me, I've stored up enough energy to go all the way.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "Phew... I think tonight is going to be a long night.",
	propose = "",
	feeling5 = "With you here, by my side... I'd love to just sleep the night away, but I don't want to take my eyes off of you... Do you feel the same way? Hehe, I guess romantic nights come with their own dilemmas...",
	main = "Commander, let me lean on you for a bit. I'm not out of energy, no, it's just... Umm, I like doing it...|I can't waste my energy on trivial things. My full power must stay reserved for whenever you demand it.|Tonight, I'm at your disposal... What I do and how I do it is all up to you. I won't fall asleep first, I swear...|Hmm? You'd like to know our signature cocktails? Well... I'll make them all either way, so why not just order me, instead?",
	touch = "Hm? Would you like to order? Or... Do you just want to touch me? Either way is fine.",
	voice_key_2 = -1,
	mission_complete = "Mission complete... Let's relax and enjoy the rest of our night together.",
	battle = "",
	id = 199061,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Can we stay together... a little longer?",
	feeling2 = "",
	login = "Mm... When you got here, I woke right up. You're the only person who can make me feel this way...",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[399030] = {
	hp_warning = "It’s not wise to swim against the current... but we have no choice now!",
	feeling3 = "My sisters always give me lots of candy whenever they see me. I, I suppose I can share them with you, Commander...",
	mail = "Let’s check the mail. I have a feeling that something good has happened...!",
	expedition = "The commission fleet must have returned with a lot of goodies. Commander, you should take a look.",
	win_mvp = "A single victory is nothing to be proud of. Let us prepare for the next battle.",
	home = "Good work, Commander. Please leave the rest of the work to me. I shall not disappoint you.",
	unlock = "Indeed, the preparations are complete... Now that I, Kitakaze, shall be assisting you with your operational command, you can now sleep more soundly at night, Commander. Heheh!",
	touch2 = "Hmm... The responsibility of cleaning up your conduct weighs heavily upon me, but... please cease your crass behavior.",
	mission = "Shape up, Commander. You can’t afford to just leave these missions sitting there.",
	vote = "",
	drop_descrip = "Destroyer – Kitakaze.",
	feeling4 = "I’m not... good with the dark. I, Kitakaze, shall slowly follow behind you!",
	lose = "Impossible... h-how did I miscalculate...?",
	feeling1 = "Commander, if you continue to squander your talents, then one day...",
	skill = "My single strike shall seal your fate!",
	upgrade = "Even after gaining power, I, Kitakaze, shall keep a clear head.",
	propose = "My mind is at peace whenever I am by your side, Commander... so can I always keep you company? Can we pinky swear on it then? My sisters told me... that this is enough to form a vow with a person of integrity.",
	feeling5 = "*yawn*.... I am getting a bit sleepy... and the Commander probably won’t ignore that... Indeed, the Commander would probably carry me back to bed... My intuition is seldom wrong... Hehe...",
	main = "My Akizuki-class sisters have always taken good care of me. I, Kitakaze, swear to meet their expectations, and will work hard to protect everyone. |I prefer strategizing and leading from the rear over fighting in the frontlines... B-but I’m perfectly capable of fighting head on. |True power comes from the strength of one’s convictions. It would behoove you to not underestimate my abilities!",
	touch = "Being small has its advantages... Heheh. For example, don’t even try to hit me in a game of dodgeball!",
	voice_key_2 = -1,
	mission_complete = "Effort is rewarded in kind. Given how hard you’ve worked, Commander, your rewards won’t be disappointing.",
	battle = "The enemy’s movements... are clear as day! Everyone, follow me!",
	id = 399030,
	gift_dislike = "",
	gift_prefer = "I graciously accept your kind gesture. Don't worry – I'll repay you.",
	profile = "Lead ship of the Super Akizuki-class... That is I, Kitakaze. During the war, I was not able to display my prowess upon the battlefield, but it is not too late to do so here. Bear witness to my agility as well as the strengths of my armaments.",
	voice_key = 39903,
	headtouch = "",
	feeling2 = "Hmm, you’re curious about the little one...? Very well, perhaps I will give you a demonstration when I get the chance.",
	login = "Commander, you’ve come. I am currently training this little one. Indeed, I must teach it to stand like a general.",
	detail = "Those who lead upon the battlefield must also carry their own blade... Worry not, this one is not heavy at all.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[399031] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Archery and goldfish scooping... these activities are nothing before my skills. Commander, I'm pretty awesome, aren't I!",
	unlock = "All the preparations are now complete... Commander, let us sally forth and conquer these festival grounds! ...But before that, can we get something to eat first?",
