	vote = "",
	drop_descrip = "All the preparations are now complete... Commander, let us sally forth and conquer these festival grounds! ...But before that, can we get something to eat first?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "As long as you predict the movements of the goldfish in advance, there is nothing difficult about this game. |Since it's a holiday, we can afford to take it easy today... But starting tomorrow, we'll have to redouble our efforts! Got it, Commander? |Commander, since you've been kind enough to explore the festival with me, I'll share some of my food with you. Would you like some candied apple? Or how about some taiyaki?",
	touch = "Heheh... Did you want to challenge me at one of these game stalls? Very well, bring it on!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 399031,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "The little ones are getting restless. Let us make haste, Commander. The festival will not conquer itself.",
	detail = "Takoyaki! Grilled squid! ...Mmm... they even have yakisoba! Commander, help me hold onto some of this... Ah! I want that too!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[399033] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Very well! Let us celebrate by pulling some party poppers!",
	home = "If you are getting bored backstage, how about playing a game of pop-up pirate with me? Heh heh, Kitakaze does not intend on losing!",
	unlock = "Mm, preparations complete. If I keep it up, the production will surely be a great success. The doves have been on their best behavior too. Commander, what do you think about Kitakaze's magic show?",
	touch2 = "Wait, hold on! I'm not hiding anything over there! I bet you're doing this on purpose!",
	mission = "",
	vote = "",
	drop_descrip = "Mm, preparations complete. If I keep it up, the production will surely be a great success. The doves have been on their best behavior too. Commander, what do you think about Kitakaze's magic show?",
	feeling4 = "",
	lose = "C-crap... Now everyone will see through my tricks...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "I am well versed with this magic box! You put a person inside, and then it is totally fine to chop it to pieces! Commander, hop inside and let us give it a try! ...Hm? That's not quite right?|Hanazuki, please select one of these cards... Um, these are just regular poker cards, so there's no need to be so nervous...|Magic tricks with doves are a dime a dozen. I wonder if there's anything else small enough for me to use in my performance... Oh, I got it! Commander, I'm going to see if Suzutsuki will let me borrow Pooky!",
	touch = "Know of any new magic tricks, Commander? Hurry up and tell me!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Heheh, behold the elegance with which I run circles around my enemies.",
	id = 399033,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, you've come at just the right time! Want to help me catch all these doves that are flying around? *sigh*... Why did they decide to act up all of a sudden?",
	detail = "Commander, do you wish to assist me in my disappearing act? I, I do not enjoy being in that dark box, alone...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[399040] = {
	hp_warning = "A little wound like this, it's nothing...!",
	feeling3 = "I'd like to get to know the other Sakura girls, and the others besides. What do you think of holding a mixer...? I could provide... the refreshments! Hehehe.",
	mail = "I got the mail. Please look it over.",
	expedition = "The girls you sent out on commission have returned. Would you like me to inspect the rewards for you? Commander?",
	win_mvp = "This was the result of everyone's hard work. I was merely part of the team.",
	home = "Welcome home. Commander, I have tea, snacks... and a massage chair here for you. Why not take a load off?",
	unlock = "Large cruiser, Azuma, reporting for duty. As a special prototype ship, there are many things that I am still unfamiliar with... However, I will lay down my life to protect you, Commander. It would please me greatly if you would place your trust in me. Hehe~",
	touch2 = "Commander? There's a time and a place...",
	mission = "Is it a very difficult mission? I can help.",
	vote = "",
	drop_descrip = "Large cruiser – Azuma.",
	feeling4 = "You know what, Commander? The most delightful thing in the world is a happy smile... All the smiles, and of course your smile, Commander, I will protect them all.",
	lose = "We lost... How will I tell the Commander...?",
	feeling1 = "Commander, I'm worried about you... You can do better, can't you?",
	skill = "It's now my turn~",
	upgrade = "Hehe, that's it~",
	propose = "Now that I understand your feelings, Commander, I will offer you all that I am, body and soul... Phew... Saying that out loud is as embarrassing as I thought it would be. Hehehe.",
	feeling5 = "Commander, are you tired? Hehehe. Then come here and lie down. Let Azuma clean your ears... Hmm, after a shoulder massage, I think.",
	main = "This defense power will definitely be useful in battle!|My guns are very precise...? Thank you for saying so. I think it's more the result of training than any natural talent. Hehehe.|Commander, is there something you would like from me?",
	touch = "Oh? You want to touch me? Or would you like me to touch you? You'll have to come out and say it.",
	voice_key_2 = -1,
	mission_complete = "So many mission rewards... Commander, you're fantastic.",
	battle = "I am to lead the fleet...? I shall not make any promises, but... I will do what I can!",
	id = 399040,
	gift_dislike = "",
	gift_prefer = "Getting such a nice gift from you has put a big smile on my face. Hehehe...",
	profile = "I am Large Cruiser Azuma. I was designed to lead torpedo squadrons into night battles, but I never saw any actual combat. I'm quite good at commanding night battles, but torpedoes are another story... Ahahaha...",
	voice_key = 39904,
	headtouch = "",
	feeling2 = "I still have trouble finding my way around... Pardon me, Commander, do you think you could find time to accompany me on my patrols...?",
	login = "Shall we begin the day's work? Do not worry, I will be right here with you the whole time.",
	detail = "I need more experience if I'm to keep up with the others... So please give me something to do. Hehehe.",
	couple_encourage = {
