}


_G.pg.base.ship_skin_words[399041] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Commander, would you mind giving me a moment of your time? Only for a little bit. I'd just like to know what it feels like to monopolize you for a while... Hehehe, I'm only joking.",
	unlock = "Commander? Oh, I haven't quite finished changing. My hair still needs work... Sorry, would you mind waiting a bit longer?",
	touch2 = "Don't do that! At least, don't do it right now...!",
	mission = "",
	vote = "",
	drop_descrip = "Commander? Oh, I haven't quite finished changing. My hair still needs work... Sorry, would you mind waiting a bit longer?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Are you tired, Commander? Hehe, with all this carousing it's only natural that you'd get worn out. Now then, rest your head on Azuma's bosom for a while.",
	main = "I understand these \"Tangyuan\" soup balls have some association with \"unity\" or \"gathering\" in the language of the Dragon Empery, but if I eat the tangyuan, doesn't that mean I've broken the unity?|Our friends are drawing that \"Fu\" character everywhere, so I went ahead and tried my hand. I think I did alright... Ahahaha...|Do you need help with the decorations in your office? I'd like to give decorating a try.",
	touch = "Having you here, Commander, makes me feel at ease.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 399041,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, the Spring Festival is a busy, exciting time. But do take care not to catch a cold when you're out having fun.",
	detail = "E-even if it's for a picture, holding this pose all this time is not easy...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[399042] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "You really are a star pupil, Commander. Heehee!",
	home = "Welcome back, Commander. What do you want to do, who do you want to be? Tell me with your words... or your body...",
	unlock = "Graduation is approaching, and that means it's time for career counseling. Do you want to be a great general who wins with impossible tactics, or a leader beloved by all the port? Which will it be, Commander? Or... Heehee, I already know your plan.",
	touch2 = "Let's see, is there anyone outside... Phew, okay. Come on, Commander~ There's nobody around but us♡",
	mission = "Are you having trouble with your missions? Heehee, don't be shy. Tell me all about it.",
	vote = "",
	drop_descrip = "Graduation is approaching, and that means it's time for career counseling. Do you want to be a great general who wins with impossible tactics, or a leader beloved by all the port? Which will it be, Commander? Or... Heehee, I already know your plan.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Hmm... It just feels off to be your guidance counselor. You're our Commander, after all, but maybe if you played a different role... Aha! Heheh, it isn't quite an occupation, but what if you role-played as... my groom?",
	main = "I can't imagine you getting tutored. Maybe tutoring others... But I wouldn't be here in that scenario, would I?|You're the reason that the port is so undisciplined, you know. Do you understand that? Heehee!|Here you go... You like getting stepped on a little in your role-play, don't you? Ah, so I still need to improve my skills... Hm? You think I don't need to learn that?",
	touch = "That was a sign that you want to be touched, wasn't it?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 399042,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Have you submitted all of your documents? If anything is missing, I'll help you revise them. Just the two of us...",
	detail = "You want me to try scolding you...? Okay... Ahem. Commander, you've seen something you shouldn't have. Go ahead and fess up – what was it? Oh... Did I misunderstand what you wanted?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[399048] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "You must be tired from your sortie. Please sit down and allow me to massage your shoulders. Mm, is this pressure to your liking?",
	unlock = "I must be dreaming, to be able to don this white veil... Haha, though, what's more important is our life together afterwards! Commander, please look forward to the rich fruit of my bridal training~",
	touch2 = "Commander, you're quite the flirt.... *blushes*",
	mission = "",
	vote = "",
	drop_descrip = "I must be dreaming, to be able to don this white veil... Haha, though, what's more important is our life together afterwards! Commander, please look forward to the rich fruit of my bridal training~",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "For me, happiness means spending our days together, taking each day slowly, one step at a time... Of course I'm quite happy right now~ How about you, Commander? Does having me by your side... make you happy as well?",
	main = "Though I am rather confident about my sturdiness, I'll proceed cautiously so that you won't have to worry about me.|Commander, please have some tea! Haha, this is something I've learned after hours of practice with Kongou~|Please look after me, through both fair weather and harsh storms. I will always remain at your side and heed your every call~",
	touch = "Now then, if you've had your fun, I do believe it's now my turn? Hehe, just kidding~",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 399048,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Welcome back, Commander. Be at ease, for I will always remain by your side~",
	detail = "I learned some new cooking techniques from Hiei today. Commander, do look forward to tomorrow's lunch. Hehe~",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[499020] = {
	hp_warning = "I shall persevere yet.",
	feeling3 = "Things such as courage have no value on the battlefield. Only those who approach Laplace’s demon shall approach victory.",
	mail = "Shall I sing the contents of this message for you?",
	expedition = "We must properly praise the girls who have returned from their commissions.",
	win_mvp = "What a pity. The encore had only just begun...",
	home = "Welcome back. Whether it’s good news or bad news, I’d be glad to hear you out.",
	unlock = "You've returned to my side once more, my child. Tell me, what is it that you wish for? Wealth? Glory? Or perhaps eternal youth?",
	touch2 = "Just like a baby... how sweet.",
	mission = "My child, no matter what it is that you desire, I can help you obtain it.",
	vote = "",
	drop_descrip = "Battleship – Friedrich der Große.",
	feeling4 = "I do prefer this to fighting. Here, my child. Open your mouth~ ahhn~",
	lose = "Please await our next performance...",
	feeling1 = "I wonder if you’re properly repenting yet...?",
	skill = "The 9th Symphony... in unison!",
	upgrade = "I feel as if I can bring out even more beautiful music.",
	propose = "From now on, I shall share everything with you - your sorrow, your joy, your pain, and your pleasure. My child, I will always, always welcome you into my embrace...",
	feeling5 = "Please dote upon me more. Yes, more... more...!",
	main = "All those emotions that you’ve bottled up through all those conflicts... Listen to my concert, and let it all out. |My appearance upon the battlefield gives off an air of cruelty? Hehe... I’ll take that as a compliment. |Even should you anger me, I’ll forgive you as long as you properly apologize.",
	touch = "If you are ever afraid, come hide behind my back.",
	voice_key_2 = -1,
	mission_complete = "Now then, what kind of reward would you like?",
	battle = "Let us play a requiem! Resound, o hatred, fear, and despair—!",
	id = 499020,
	gift_dislike = "",
	gift_prefer = "I like this.",
	profile = "I am Friedrich der Große, prototype H-class battleship of the Iron Blood Navy. Come, my child... If you are unable to sleep, allow me to play you a lullaby.",
	voice_key = 49902,
	headtouch = "Trying to get my attention, my child? Heehee.",
	feeling2 = "I never should have come to exist in this world... But since I am here, there must be a higher principle behind it...",
	login = "The performers can wait no longer! Hurry, let us raise the curtains of battle!",
	detail = "My child, if you desire absolute victory, you must maintain absolute rationality.",
	couple_encourage = {
		{
			{
				40146
			},
			1,
			"You should let me pamper you once in a while.",
			0
		},
		{
			{
				40502
			},
			1,
			"Perhaps you're unable to display your full power with me in charge?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[499021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome back. I've prepared a beverage for you. Come warm yourself as I read the report to you.",
	unlock = "I see, so this is a \"kimono\" from the Sakura Empire. Exquisitely crafted, comfortable to the touch, and elegantly designed... How to wear it? ...My child, what are you talking about?",
	touch2 = "Do you like it here, my child? Hehehe~",
	mission = "",
	vote = "",
	drop_descrip = "I see, so this is a \"kimono\" from the Sakura Empire. Exquisitely crafted, comfortable to the touch, and elegantly designed... How to wear it? ...My child, what are you talking about?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Sakura Empire's classical \"gagaku\" is said to elicit profound and mysterious emotions... I'm quite curious about it. |The release of repressed emotions can be both medicine and poison. The effect depends on how well you can control your state of being. |My child, could you help me with putting on this outfit?",
	touch = "The sensation of this embrace is the warmth of human contact... Do you understand, my child?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Turn into nothingness, along with the symphony of the void!",
	id = 499021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Shouldn't I be the one doing this to you instead, my child?",
	feeling2 = "",
	login = "Aren't you cold standing over there? Come to me, my child.",
	detail = "Mankind's ambitions know no limits. Indeed, just like these riggings of mine... they strive to expand, to become more powerful... to command more cannons, and to seize greater glory...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[499022] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "You look tired. Come, come. Lie down with me and rest.",
	unlock = "Welcome, my child. What do you desire tonight? That which ripples in my cup? This sweet, red fruit? Or to sate the desires sleeping deep, deep in your heart?",
	touch2 = "Heehee... It's my job to sate your intellectual thirst...",
	mission = "",
	vote = "",
	drop_descrip = "Welcome, my child. What do you desire tonight? That which ripples in my cup? This sweet, red fruit? Or to sate the desires sleeping deep, deep in your heart?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Hmm? You want another? ...Say it outright, and put your desires in the open. I'll give you everything you want, and more.",
	main = "Do you want cherries? ...Heehee, I'm so glad you're honest, my child. As a reward... I'll feed you, just like this.|Don't be afraid of spoiling my mood or angering me. Just tell me what you desire – it's my duty to satisfy that.|Sometimes, it's good to give our rational mind a break. My only desire... is to pamper you in my arms on this beautiful summer night, my child.",
	touch = "Do you wish to feel my warmth? But of course, my dear child.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 499022,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "You really like this hairstyle, don't you, my child?",
	feeling2 = "",
	login = "Heehee... Will you come and visit me every night until the end of summer, my dear child?",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[499023] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Welcome back, my child. Soon, you will have your own red envelope... Go on. Reach out your hand, if you dare.",
	unlock = "I've heard that in the Dragon Empery, it is customary to give out red envelopes on special occasions... Come hither, my child. Allow me to give you a special gift for this priceless moment—",
	touch2 = "Yes, that's the spot... Let us celebrate your growth together, my sweet child.",
	mission = "",
	vote = "",
	drop_descrip = "I've heard that in the Dragon Empery, it is customary to give out red envelopes on special occasions... Come hither, my child. Allow me to give you a special gift for this priceless moment—",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "What do I wish for? Simply for my sweet child to live a happy and fulfilling life, where in my arms, all of your dreams come true... Heehee. I think you've helped me realize my wish.",
	main = "What's in the envelope? One could say... it's your deepest, most heartfelt desire.|Do you like the decorations tonight? Hehe, then isn't there something you should say? Something other than \"thank you,\" of course.|Ah... Let's play a beautiful serenade together on this night, my child.",
	touch = "You'd like to savor the process of being rewarded this time? Heehee, fine by me...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 499023,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Your reward isn't here, heehee...",
	feeling2 = "",
	login = "I hear cheery music playing outside... Hehe, come, my child. Let's share in the mirth together.",
	detail = "How soft and delicate this silk lingerie is... Heehee. If you like it, then feel it for yourself, my child.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[499024] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "I'd like to sing you a lullaby, but you're still full of energy. For now, I suppose I should satisfy that ambition of yours...",
	unlock = "My child, I am honored to have guided you through this long night, leading you to greater maturity. Now, come and savor this eve's fruits until dawn comes, as a gift for your profound growth...",
	touch2 = "Mm... Not bad, my child...",
	mission = "",
	vote = "",
	drop_descrip = "My child, I am honored to have guided you through this long night, leading you to greater maturity. Now, come and savor this eve's fruits until dawn comes, as a gift for your profound growth...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "My love for you is boundless, and it only grows with each passing day. My child, if you have any requests, speak – I am all too eager to please.",
	main = "Once you're inside, you are to strip. If you feel the cold, then come snuggle in my arms... Here is the warmest of ports for you, my child.|I'll follow your pace and lead you along the way...|Only by maintaining rationality in moments of deep desire can we truly attain bliss. Immerse yourself in my teachings, my child.",
	touch = "You're doing well, but you're capable of more.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 499024,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Is my hair a mess, my child?",
	feeling2 = "",
	login = "What will you explore today, my child? And how will you put it into practice?",
	detail = "Ah... Even knowing what great accomplishments you've achieved, you're still my dear, sweet child. I'll happily spoil you any time you like...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[499028] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "You can leave the report for later. Let me see your face, my child... Hehe, there's nothing amiss... Is there anything you'd like to talk to me about, my child?",
	unlock = "Ahh, the dreamlike beauty of this variation... let us write down this movement so that it may continue forever, my sweet child.",
	touch2 = "What a selfish child... But no matter, I shall accept you unconditionally.",
	mission = "",
	vote = "",
	drop_descrip = "Ahh, the dreamlike beauty of this variation... let us write down this movement so that it may continue forever, my sweet child.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "My child, I will accept you unconditionally, and lay low anything that attempts to stand in your way. Come, allow me to pamper you more. Yes, more... more... give me more...",
	main = "Is there something giving you difficulty? Please tell me about it. I shall take care of everything for you.|Save your cold rationality for your enemies on the battlefield. Before me, however, you need not hold back. Just indulge yourself to your heart's desire, my child.|If you are tired, lie down right here... I will bring you pleasant dreams... Good, sweet child... I'll always be watching over you.",
	touch = "Do you wish to touch your beloved more intimately? Come closer, my dear child.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 499028,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "What would you like to listen to today, my child?",
	detail = "What I hope to get from you? Hehe... For me, the most important thing in the world... what I hope for the most - is you, my child.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[999010] = {
	hp_warning = "Combat execution systems failing, requesting support.",
	feeling3 = "Phenomena known as \"emotions\" and \"impulses\" occur when interacting with members of the fleet. Requesting instructions for achieving satisfactory interaction.",
	mail = "Attention: confirmation required for new mail.",
	expedition = "Attention: confirmation required for commission team's return.",
	win_mvp = "Report: destruction of targets confirmed. Combat mission complete.",
	home = "A glass of armagnac has been prepared.",
	unlock = "Gascogne activation process complete. Directive assigned: secure liberty and victory for Master. Gascogne commencing active service.",
	touch2 = "Body temperature abnormality detected. Requesting thorough physical examination.",
	mission = "Attention: confirmation required for incomplete missions.",
	vote = "",
	drop_descrip = "Battleship – Gascogne.",
	feeling4 = "\"Emotions\" generated from physical contact were analyzed and interpreted as \"comfort\" and \"happiness.\" Concluding that this holds strategic significance if this is Master's intention.",
	lose = "Failure is intolerable. Proposal: improve Gascogne's capabilities, or terminate system.",
	feeling1 = "Gascogne is a weapon and a warship. No other definitions are applicable.",
	skill = "Armaments activated. Engaging at maximum output.",
	upgrade = "Ability enhancements... Confirmed.",
	propose = "I now understand the emotion known as love. It is the throbbing of one's heart; the gratitude, longing, warmth, and light one feels for a person who does not seek recompense. This ring is the greatest gift I could ask for. I love you, Master.",
	feeling5 = "Phenomena known as \"worries\" and \"hopes\" were observed and successfully classified during routine \"emotion\" cache analysis. System can be updated with permissions to access and act upon \"emotions\" if Master so wishes. Thank you, Master.",
	main = "\"Raise the corners of your lips\"... Unable to determine significance of said action.|Analysis complete. Master identified to be in a state of \"slacking off.\" State evaluated as an impediment to productivity.|\"Do whatever you want\"... Analysis of strategic significance of order deemed impossible.|Discrepancy detected in the frequency of \"smiles\" recorded between members of the fleet, Gascogne's recollection, and expression identification database.",
	touch = "Awaiting Master's orders.",
	voice_key_2 = -1,
	mission_complete = "Attention: confirmation required for mission rewards.",
	battle = "Targets identified. Commencing destruction.",
	id = 999010,
	gift_dislike = "",
	gift_prefer = "Positive effect on current functions confirmed.",
	profile = "Gascogne, Richelieu-class battleship number 4, construction canceled due to wartime conditions. Purpose: engage in battle and destroy Master's enemies.",
	voice_key = 99901,
	headtouch = "",
	feeling2 = "Numerous requests for Gascogne's participation in activities without strategic significance received from members of the fleet. Requesting Master's assessment.",
	login = "Identification complete. Welcome back, Master.",
	detail = "Analyzing armaments... Condition: satisfactory. Gascogne is able to execute orders.",
	couple_encourage = {}
}


