_G.pg.base.ship_skin_words[299034] = {
	hp_warning = "Owie... Maybe my doves will be of some use to you, Owner?",
	feeling3 = "",
	mail = "I used a magic trick to hide your letter inside this card! Ahaha, I'm just joking with you!",
	expedition = "The commission team is back? I hope they brought the souvenirs I ordered for you!",
	win_mvp = "Mission complete! Owner, did you like my fireworks?",
	home = "Way to go, Owner! Do you wanna see me do a little hopping dance? Or maybe a magic trick instead?",
	unlock = "Owneeer! Lookie! You'll be spending the night with a magician – me! What's the matter? Are you already head over paws for my new look? Don't think I didn't notice how you can't take your eyes off me!",
	touch2 = "Oh, Owner. I know exactly what's going through your head! And I'm perfectly fine with it♡",
	mission = "Owner, you still have missions to do! Are there any that Cheshire the Magician can help with?",
	vote = "拉票描述",
	drop_descrip = "Owneeer! Lookie! You'll be spending the night with a magician – me! What's the matter? Are you already head over paws for my new look? Don't think I didn't notice how you can't take your eyes off me!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "Behold the magic of love!",
	upgrade = "I learned a new magic trick! I'll show it to you later!",
	propose = "",
	feeling5 = "Owner, is there anything you wish for? I can make it happen with my magic! Hm? You just wanna be with me forever? Oh gosh! An unexpected profession of love! You know, you don't need to wish for that – I'll make it come true either way! That's just what you do when you love someone more than anyone else in the whole world!",
	main = "Are you tired after the party, Owner? You should lie down next to me! And rest your head on my thighs!|Watch closely, Owner! I'm going to perform a stunning magic trick! Tadah! I made a Cheshire appear, and she really loves her Owner!|Here comes a trick that reveals how much I love you! Abracadabra... Did you see that? It said I love you as much as physically possible!|Owner, stick your hand in my hat! Hm? You feel something soft inside? I'm sure that's just the rabbit in my hat♡",
	touch = "Owneeer! Hm? Why are you blushing all of a sudden? Has that spark inside you rekindled, hmm?",
	voice_key_2 = -1,
	mission_complete = "After you've claimed those mission rewards, do you wanna go watch the fireworks with me?",
	battle = "I'll pull a shell out of this hat and it's gonna hurt for you!",
	id = 299034,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Owner, my hat's gonna fall off if you keep headpatting me! There are other places you can touch me, you know!",
	feeling2 = "",
	login = "Owneeer! Squeee! Cuddle! Fluff! Sniff! Hey, how does it feel to hug me? I bet it feels even better than usual!",
	detail = "Owner! Did you know rabbits will get sick if they're lonely? I might not be a rabbit, but I also hate being lonely! So to keep your favourite Cheshire happy, you'll need to give her a steady supply of hugs!",
	couple_encourage = {}
}


