	headtouch = "",
	feeling2 = "",
	login = "I heard this is a nice place to swim. Imagine my surprise to learn it wasn't a beach, but an outdoor pool... Still, I guess if we're just killing time, this is as good a place as any...",
	detail = "Artificial waves? Hmm, this might be more fun than I thought. Time to show off my swimming skills!",
	couple_encourage = {}
