_G.pg.base.ship_skin_words[499030] = {
	hp_warning = "Ugh, to think that my equipment wouldn't work...?!",
	feeling3 = "If I am lacking in actual battle experience, there is nothing to do but humbly accumulate more. Commander, I won't mince words - please send me out on more battles.",
	mail = "There's new mail. There's no way you've forgotten, right?",
	expedition = "The girls who went on commissions are returning. I'll be leaving my seat for a bit.",
	win_mvp = "An expected outcome, given that I am here.",
	home = "My equipment needs maintenance, too.",
	unlock = "Light cruiser, Mainz. You'll be my first Commander. Hmph. Don't you dare disappoint me.",
	touch2 = "Perfect. I can finish testing my guns by firing them at you.",
	mission = "Are you going to neglect all the missions?",
	vote = "",
	drop_descrip = "Light cruiser – Mainz.",
	feeling4 = "At one point I fought to prove myself. However, I now fight for your sake. I want to prove to everyone else that you are a sufficiently reliable person.",
	lose = "Hm. I'll consider this as valuable practical experience.",
	feeling1 = "To think that my first commander would be this pathetic... How depressing.",
	skill = "Now's the time! Begin firing!",
	upgrade = "Hm. Let's test this out in a real battle.",
	propose = "My existence is no longer just about battle. My life and fate have already been tied to yours. My beloved Commander, I henceforth pledge my heart to you for the rest of eternity.",
	feeling5 = "Commander, I recognize you as the first and last commander I swear my loyalty to... But that's not all. You are the only one I've ever thought I wanted to get closer to.",
	main = "What do you think you're doing! Adding milk to coffee is nothing short of blasphemy! The same goes for sugar!!!|I can't believe it... though this room is so large, it doesn't even have a coffee maker...!|If only I were constructed in the Great War instead of being incarnated in this form, I wonder how much I would have been able to do... I guess thinking about it doesn't help.",
	touch = "What's wrong? Do you want me to comfort you?",
	voice_key_2 = -1,
	mission_complete = "How long... are you planning on ignoring the mission rewards?",
	battle = "Don't get in my way.",
	id = 499030,
	gift_dislike = "",
	gift_prefer = "I didn't expect to receive something like this... This has made me see you in a new light.",
	profile = "Light cruiser, Mainz. There were plans for me to succeed the Admiral Hipper class, but due to circumstances, I've incarnated in this form. You get the rest without me telling you, right?",
	voice_key = 49903,
	headtouch = "",
	feeling2 = "Because I was born into this world, I shall accomplish something. Otherwise, I wouldn't be able to face those who designed me.",
	login = "Make sure that the wait was worth my time, Commander.",
	detail = "Achievements? ...Let's start racking them up today.",
	couple_encourage = {
		{
			{
				49901,
				49902,
				49904
			},
			1,
			"Witness the true power of the Iron Blood!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[499032] = {
	hp_warning = "",
	feeling3 = "",
	mail = "You have new mail. I told them to leave it in your office, so we can check it later.",
	expedition = "",
	win_mvp = "",
	home = "Where did you go, Commander? Tiring yourself out now would defeat the whole point of relaxing.",
	unlock = "Ah! Changed already? Just wait a minute... No, you don't have to leave. I'm almost done.",
	touch2 = "W-wait! Don't do that, or else...!",
	mission = "A mission, huh? ...Let's put it off for now. It'll still be there after we take a break.",
	vote = "",
	drop_descrip = "Ah! Changed already? Just wait a minute... No, you don't have to leave. I'm almost done.",
	feeling4 = "",
	lose = "I guess I got too comfortable...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Nngh... It's hard to tie this sash tight enough. But if it's too loose...|They didn't let me bring a coffee machine into the bathhouse, but... Heh, I did get to set it up outside. Black, of course.|The mirror? I'd assume it's fogged up from the steam. ...Look at my reflection, you say? What do you... Oh. *blushes*",
	touch = "You've done well, Commander. It's time to take a break.",
	voice_key_2 = -1,
	mission_complete = "Finished your missions already? Then that gives us more time to kick back.",
	battle = "",
	id = 499032,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "I wouldn't have minded waiting longer. After all, I know you're not the type to forget a promise.",
	detail = "Blücher tried to wear her rigging to the bath, but Eugen and I managed to stop her. Seems like Hipper didn't want to get in with us, though...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[499033] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Have you been working this whole time? Goodness. Get over here and relax already.",
	unlock = "Commander, come join me in rest. ...Hm? I look unusually relaxed? This is a rare break, and I don't plan to waste it by being stuffy.",
	touch2 = "H-hold on! Does it have to be right now...?",
	mission = "",
	vote = "",
	drop_descrip = "Commander, come join me in rest. ...Hm? I look unusually relaxed? This is a rare break, and I don't plan to waste it by being stuffy.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "The Dragon Empery New Year is a day for family gatherings. I think it's a lovely thing, but I want to take this opportunity to tell you... that you are more important to me than anyone else. That our fates are bound tightly. Wherever you go, that is my home.",
	main = "Tea and black coffee... Entirely different flavors, but many shared aspects. For example, traditional tea doesn't include sugar or milk.|I think Hipper was interested in this dress. She was staring an awful lot... Should I have one made for her, too?|It is a little cramped, but if we try hard enough, we could both sleep here. So... Want to lie down with me?",
	touch = "My shoe fell off? When in the world...",
	voice_key_2 = -1,
	mission_complete = "Your mission rewards... Bah, they can wait. You're on break right now, after all!",
	battle = "",
	id = 499033,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "How does it, umm... feel?",
	feeling2 = "",
	login = "Phew... Want me to scooch over for you?",
	detail = "Do you have any plans later today? If not, feel very free to stay with me.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[499040] = {
	hp_warning = "Carry out emergency damage control plan!",
	feeling3 = "Mourn for my fallen comrades? If I were to stop and mourn for every lost soul, I would never win the war.",
	mail = "Mail has arrived. Could it be new intelligence?",
	expedition = "The commission team has returned. Excellent, exactly as was planned.",
	win_mvp = "Victory was ours since before the battle began.",
	home = "Commander, we are in all-out war; we cannot afford to rest.",
	unlock = "Are you the one who summoned me here? I am Odin. I hereby take up post as your tactician.",
	touch2 = "Y-you will hear from me at the court martial!",
	mission = "You have missions. Leaving them unfinished would be a foolish choice.",
	vote = "",
	drop_descrip = "Battlecruiser – Odin.",
	feeling4 = "We make a fine pair, both in the office and the war room. But that can backfire, as I may end up becoming reliant on you...",
	lose = "Impossible... My plan should have been flawless...!",
	feeling1 = "I am not even disappointed, I simply wonder how someone as lousy as you became a commander in the first place.",
	skill = "You wasted your last chance to turn back!",
	upgrade = "With strength, one can reduce the number of irregularities in a plan.",
	propose = "Understood. I shall continue to provide assistance for you, whenever– Hey, wait a minute... Th-this isn't what you said would happen! ...No, that's not to say I oppose this! I just wasn't... mentally prepared... What I'm getting at is: give me a moment to think!",
	feeling5 = "I do not approve of being reliant on someone. Excessive intimacy is a hindrance in war, clouding one's judgment and forming obstacles to one's plans... Ah, I can't believe what I'm saying...",
	main = "One day, I hope to meet the Scharnhorst sisters myself.|Sometimes, things don't go as planned. You must think carefully before committing yourself to anything, Commander.|Don't blame others over things that are out of their control. Nobody can predict the future.",
	touch = "Yes? Has there been a change of plans?",
	voice_key_2 = -1,
	mission_complete = "Mission successful. Let us get started on the next one, Commander.",
	battle = "Flee while you still can.",
	id = 499040,
	gift_dislike = "",
	gift_prefer = "Wait a second... I don't remember telling you what I like. How did you know?",
	profile = "I am the battleship Odin. I existed only within the realm of the Iron Blood navy's imagination. Destiny has brought me here to serve under you and assist in the realization of your goals.",
	voice_key = 49904,
	headtouch = "",
	feeling2 = "Names and titles are no proof of strength, that much is true. But that is fine. As time passes, you learn how futile your concerns are.",
	login = "Excellent, you're back. Have you finished work our next plan yet, Commander?",
	detail = "I don't understand. Why are all the people at this base so at ease?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[499041] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "To fight is to put one's whole being into something, be that firing volleys on the battlefield or turning a blank canvas into a masterpiece.",
	unlock = "I thought I would never have time to pursue the fine arts, and yet here I am now. Your thoughts, Commander? Eastern as this calligraphy may be, does it not suit the connotations of my name?",
	touch2 = "Stop it! I am trying to focus here!",
	mission = "",
	vote = "",
	drop_descrip = "I thought I would never have time to pursue the fine arts, and yet here I am now. Your thoughts, Commander? Eastern as this calligraphy may be, does it not suit the connotations of my name?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Gneisenau, enjoyment of the arts will always elude you if you only think in statistics. You stand to learn from Scharnhorst in that regard.|Lord Tirpitz, whereabouts is Lord Bismarck? Forsooth, 'tis reassuring to know that thou knoweth. I shan't inquire further.|Plum trees and snow... This is an unfamiliar, but picturesque sight that I will likely never forget.",
	touch = "",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 499041,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "It is good to see you again. You ought to dedicate your days off to your own hobbies, Commander.",
	detail = "I don't understand. Why are all the people at this base so at ease? ...No, it is simply I who is always trying too hard.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[899020] = {
	hp_warning = "These scars will become my aegis.",
	feeling3 = "Trees bury their roots deep into the ground to avoid being blown away, and fish swim upstream to propagate their kind. Though they know they are fated to return to nothingness, living things defy their circumstances to the best of their ability.",
	mail = "A notice has arrived. Is it a joyous one, or is it a tragic one? Is it a desirable one, or a hateful one?",
	expedition = "The birds' clarion call... It seems that our comrades have returned to us.",
	win_mvp = "I ensure that missions sown shall bear rich fruit.",
	home = "Immerse yourself in the liberating quintessence of wine, for the mind requires reprieve. Man is naught without repose.",
	unlock = "I am the personification of Champagne, part of the Iris Libre. Commander, please give me an order—a reason to exist.",
	touch2 = "Though your transgression may be slight, such conduct may turn others away from you.",
	mission = "The falcon that spreads not its wings cannot reach the sky. The ship that rows not its oars cannot reach the other shore. ",
	vote = "",
	drop_descrip = "Battleship – Champagne.",
	feeling4 = "Commander, there is no way for you to wear the rigging—armor, main guns, and torpedoes—that is required to defend the fleet. As I am a ship, I will take on the mission to protect you.",
	lose = "Our true destination still awaits.",
	feeling1 = "The hope you brought was but a false light. Why, Commander, must you torment me so?",
	skill = "Sleep in the blue depths of the ocean...",
	upgrade = "Even the most polished blade must eventually rot. That is to say, there is no point in chasing power.",
	propose = "Even if words stop existing, I will still listen to your voice. Even if the world loses its radiance, I will still look into your eyes. There is nothing in this world that can erase your existence from my heart. The warmth I've received from you, I shall repay with my eternal protection... These are my true feelings.",
	feeling5 = "If those who are powerless resist fate, those with power cannot stand by and do nothing. Commander, your radiance, warmth, and affection—in order to protect all of this, I offer up my body and swear my love.",
	main = "Commander, art thou pondering the meaning of life? Or perhaps...|The ebb and flow of tides are natural phenomena, and so are the flowing fates of humankind.|\"Live, together with the fleet.\" Understood. I have received my newest directive from the Commander.",
	touch = "The warmth and sensation of being touched... How exceedingly difficult to forget.",
	voice_key_2 = -1,
	mission_complete = "Only for the gardener whose blood nurtures the soil can the iris bloom in triumphant beauty.",
	battle = "Devote thyself not to the fleet― for that is my solemn charge.",
	id = 899020,
	gift_dislike = "",
	gift_prefer = "Too overwhelming is this joy – I must express my gratitude.",
	profile = "Never have I received orders, nor have I ever accomplished anything. I am merely a blank slate—existing simply to become the delectable champagne presented to thee, the victor.",
	voice_key = 89902,
	headtouch = "",
	feeling2 = "This world is the surface of a calm lake— Disturbances may mar the waters with ripples, but peace must return in time.",
	login = "Your orders, Commander. Whatever your will may be, I shall usher into reality.",
	detail = "Whether your ambitions leads you into the wilderness of unparalleled achievements, the lofty spires of world domination, or the gardens of peaceful sanctuary, command me as would best serve your will.",
	couple_encourage = {
		{
			{
				40146
			},
			1,
			"Let us open our eyes to this colorful world.",
			0
		},
		{
			{
				99901
			},
			1,
			"Let us harken, for the world speaks.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[899021] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Please enlighten me. The significance of this festive garb, and the things I must do.",
	unlock = "It is not against the teachings to halt one's pursuit of destiny and to surrender to the warm draft of festivities. It is mankind's prerogative to seek out auspicious portents.",
	touch2 = "Animals attempt to break their fetters in order to satiate their desires, whereas humans challenge taboos to satiate their curiosity.",
	mission = "",
	vote = "",
	drop_descrip = "It is not against the teachings to halt one's pursuit of destiny and to surrender to the warm draft of festivities. It is mankind's prerogative to seek out auspicious portents.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Mountains, birds, fruits. All wonderful signs of a dream in which spring blooms forth.|Our connected memories spread out, like freshly-fallen powder snow, as our affected emotions are as if blown by the spring breeze. ...May these peaceful festivities spread much joy.|The Cardinal's favorite book was one recommended by me. Humans and ships alike desire to satisfy their curiosity...",
	touch = "",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 899021,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Hm...? Did you want to know about my dreams...?",
	feeling2 = "",
	login = "What I desire on the first day of the new year... a peaceful night's sleep, and a rainbow-colored dream that reflects my wishes.",
	detail = "Reliving one's childhood by enjoying games is one way to enjoy festivities. That being the case, I lack knowledge of the rules designated for these games...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[899028] = {
	hp_warning = "",
	feeling3 = "",
	mail = "A message is received. Is it joyful or sorrowful news? Triumphant or regretful? The answers lay in your reply, Commander.",
	expedition = "What I am telling you are the honeyed words of a lover—let us prepare to greet those who have returned together.",
	win_mvp = "Unlike the fleeting bubbles dancing in the air, this victory will be remembered for all time.",
	home = "A decision must be made. The baptism of innocent lost spirits, the flavor of filling fertility, or the indulgence of a lover's tryst?",
	unlock = "An ode of gratitude for the venerable Iris, echoing tones condensing to pure prayer. Seek blessings not in public worship, but in humanity's true triumph: our everlasting bonds.",
	touch2 = "Even knowing eternal love, one desires momentary pleasure. I know that it falls to me to see your wishes granted, Commander...",
	mission = "",
	vote = "",
	drop_descrip = "An ode of gratitude for the venerable Iris, echoing tones condensing to pure prayer. Seek blessings not in public worship, but in humanity's true triumph: our everlasting bonds.",
	feeling4 = "",
	lose = "A vow mustn't be broken. My protection is eternal.",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Life is fleeting. The hulls of shipgirls are transient. It is our inescapable fate to love momentary bliss.|It is the duty of Champagne to fill your cup. That means keeping you punctual and rested in equal measure...|Hymns passed down cannot fool the heart. I will celebrate your great deeds and offer you love eternal.",
	touch = "Your warmth, heartbeat, touch, and more seem meant to tempt me into rapture...",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "I fight for the Commander's sake—That is my credo.",
	id = 899028,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Feel, perceive. The beating of our connected hearts, the trembling of our damp lips.",
	detail = "Praise be this vow. Love, faithfulness, entrusted duty, ordained creed—I must be one who protects the happiness of all.",
	couple_encourage = {}
}


