_G.pg.base.ship_skin_words[399053] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission team has returned, eh? Heheh, let's go show them my blade!",
	win_mvp = "",
	home = "Wipe off the oil, apply whetstone powder... Just as a sword needs maintenance, you need regular rest. Quit your complaining and take a break!",
	unlock = "Hahahaha! Now THIS is a sword worthy of my hands! Perfect blade, perfect hilt, perfect cut – only a master of their craft could make such a beauty! Come on, let's see what this blade can do!",
	touch2 = "Again, you can't have it... H-hey, that was no fair!",
	mission = "Any missions I can test my weapon on? ...Find one myself? But you're the one receiving the assignments, not me!",
	vote = "",
	drop_descrip = "Hahahaha! Now THIS is a sword worthy of my hands! Perfect blade, perfect hilt, perfect cut – only a master of their craft could make such a beauty! Come on, let's see what this blade can do!",
	feeling4 = "",
	lose = "Where's my katana... Huh? You brought it for me? Th-thank you...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "A katana isn't just a weapon – it is a warrior's very heart. That should tell you why all the girls at port treasure their own weapons so much. If you ever get the opportunity to forge a sword... heh, your first one will be all mine!",
	main = "My katana is right here in my hands – you're too late to hide it from me! ...You weren't going to? As if I'd believe that now!|The dragon carving, my name engraved into it... Truly, this was made just for me. Heh, I must thank you!|Tamahagane must be hammered hundreds of times to forge a mighty blade. Don't forget your daily exercise! ...You think it's okay to take today off because you're halfway there? I-is that how it works?",
	touch = "Hmm? If you want to touch it, then go ahead... Ack! You almost tricked me, damn it!",
	voice_key_2 = -1,
	mission_complete = "The rewards... too valuable to waste, huh? Tch. I'll go find a hay bale, or something.",
	battle = "I will cut them all down with one swing!",
	id = 399053,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "What's the matter? Intimidated by my raw aura? Hahaha, you won't be taking my katana from me today!",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[399054] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "The room feels cramped? You clearly don't see the value of this sunlight! It is a bit rough in the summer, yes, but it's just fine if you can handle that!",
	unlock = "Y-you! How dare you make me wear... \"I thought it would look good on you, and your current outfit is too breezy\"?! What nonsense! I can wear whatever I want in my room! ...Achoo?!",
	touch2 = "D-don't grab out of nowhere!",
	mission = "",
	vote = "",
	drop_descrip = "Y-you! How dare you make me wear... \"I thought it would look good on you, and your current outfit is too breezy\"?! What nonsense! I can wear whatever I want in my room! ...Achoo?!",
	feeling4 = "",
	lose = "Tch... No wonder I felt weak!",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Hmph. If that's what you want... I'm even LESS likely to wear it! I'll go naked before I... Achoo?! You're scared I'll catch a cold? Why didn't you say that sooner?!",
	main = "Achoo?! Ugh... I think my room is too cold. I-I'd rather turn off the AC or whatever than wear THAT!|My katana's right here! Heh, those kinds of tricks don't work on me anymore! ...Yeah, you got a problem with the room being too small to hide it?! Is that the whole reason you're here?!|A true warrior cares not for appearances. Cut down your enemy and win the day – that's what matters. You must understand this, surely.",
	touch = "Now that you mention it, the size really does... Did you get my measurements perfectly just by looking?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Achoo! Tch... I only need my katana!",
	id = 399054,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Are you here to tease me again? I told you, I'm not wearing it! No matter how much you want to see it... G-give my katana back! Fiiine, I'll wear it!",
	detail = "It's not like me to tidy up? Hmph! What fool would make a mess of their room a short few days after moving in?! My katana? Where... Where is it?!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[499050] = {
	hp_warning = "Caught on to me, have you...",
	feeling3 = "I'm going for a drink, and you shall accompany me, Commander. Get as drunk as you wish. I'll overlook whatever silly things you say while under the influence.",
	mail = "A letter has arrived from afar. Read it, would you?",
	expedition = "A commission has been completed. How long must your subordinates wait for you to acknowledge them, hmm?",
	win_mvp = "Those fools were but splashes of water beneath my bow. Hahaha... Ahahahahaha!",
	home = "You wish to rest, do you? I'm afraid the heap of soon-due paperwork on your desk won't allow it.",
	unlock = "Well met. I am large cruiser Ägir. Your will is my command. Hehehe... Now let's find out what you can accomplish with my arsenal of talents.",
	touch2 = "You're brave, I'll give you that... What?! Twice in a row?!",
	mission = "I see we still have unfinished missions. Do them now, and I shall refrain from dismissing you as incapable.",
	vote = "",
	drop_descrip = "Large cruiser – Ägir.",
	feeling4 = "I don't mind your efforts to win my interest, but must you stare holes through me? Hehe. I suppose you're more daring when drunk... W-wait, you aren't drunk?!",
	lose = "Nobody, and I mean NOBODY denies me my victory! I shall return with a vengeance!",
	feeling1 = "You are undisciplined trash not worthy of my compassion.",
	skill = "Ahahahahaha! Be engulfed by my maelstrom!",
	upgrade = "Prosit. The occasion warrants a toast. Mmh!",
	propose = "A symbol of our marriage? You must adore having proof of the ties that bind you to me. Prepare to double down, then. I'll find something that binds you to me. Physically... Hahaha! You shall see what I mean.",
	feeling5 = "You're in over your head if you thought you could drink one named after the god of the sea under the table. What's the matter? Can't move a muscle? Then I've proven my– Eek!",
	main = "Insufficiently motivated, are we? A dinner with copious amounts of beer can fix that.|You like gazing at seas in tempest too, do you? Hahaha. A sea is at its truest when a storm rages through it.|...What? You have that look on your face like I'm distracting you.",
	touch = "Would you like it... if I came a bit closer?",
	voice_key_2 = -1,
	mission_complete = "Mission complete. I suppose you are at least qualified for your position.",
	battle = "I shall tear you asunder! Ahahahaha!",
	id = 499050,
	gift_dislike = "",
	gift_prefer = "You understand me better than I thought. I'm impressed.",
	profile = "I am Ägir, named after the very same mythological ruler of the sea. Though, compared to a god who smote adversaries with storms and crashing waves, my way of dealing with my enemies is much more subdued. Ahahaha.",
	voice_key = 49905,
	headtouch = "...What?!",
	feeling2 = "My interests in life? Hahaha! Fighting worthy foes, savoring good beer, gazing at the stormy seas, and... What? Are you grasping at straws just to get my attention?",
	login = "Who might it be that just stepped through those doors? ...Oh, it's you. Best of luck with your work, then.",
	detail = "My serpents have a tendency for violence, so be aware of the risk should you dare to touch me, Commander.",
	couple_encourage = {
		{
			{
				29901
			},
			1,
			"If you would, do mind your manners.",
			0
		},
		{
			{
				40301,
				70301
			},
			1,
			"We shall drink later, but now, we must fight.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[499051] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
