_G.pg.base.ship_skin_words[499052] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "That commission is done. Now go. Those girls deserve some appreciation for working on a holiday.",
	win_mvp = "",
	home = "Even lords of the sea need to rest. Why don't you sit down and enjoy the soothing aroma in the air?",
	unlock = "New decorations, new outfits, and countless preparations to make... Lunar New Year is quite the busy time of year. Go on, see to your duties. I'm well aware how essential you are to this holiday's smooth operation. Just don't keep me waiting all day. Heehee.",
	touch2 = "Wha–?! You made me spill ink everywhere! I, I'll clean it up myself!",
	mission = "All these missions leave you with no time to enjoy the holiday... That is unacceptable. Hmph, I'll assist you with them.",
	vote = "",
	drop_descrip = "New decorations, new outfits, and countless preparations to make... Lunar New Year is quite the busy time of year. Go on, see to your duties. I'm well aware how essential you are to this holiday's smooth operation. Just don't keep me waiting all day. Heehee.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "How does one hold a brush? Like this? Or like... this? Ugh... I refuse to believe you don't know the proper technique. Stop gawking and come show me!|So that's what their dragon dance is like... When I first heard of it, I thought they would use a dragon-like rigging, similar to what we have in the Iron Blood.|Brünhilde, is this bowl an Empery antique of yours? I must admit, the workmanship is remarkable. Hmph, I suppose you do have a refined taste.",
	touch = "Go on a stroll together, you say? I could do that... But first, put my heels on my feet, would you?",
	voice_key_2 = -1,
	mission_complete = "Mission complete. You may now concentrate on celebrating.",
	battle = "",
	id = 499052,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Don't you touch my horn ornaments without my permission!",
	feeling2 = "",
	login = "You're back. Heheh, missed me, did you? Or are you just tired?",
	detail = "I heard the Dragon Empery regards their namesake dragon as sacred... Then why is its sign merely the 5th ordinal in their zodiac?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[499053] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Commission rewards have arrived. Are you going to examine the haul?",
	win_mvp = "",
	home = "Tired? Do you want to sit upon this couch? Hah, I don't mind giving it up for... Hm? Where have my shoes gone?",
	unlock = "Well, I'm pleasantly surprised. A comfortable seat, high-quality beverages, and a nice private room... Hm? Are you going to stand there the whole day? Don't just stare at me like that...",
	touch2 = "Again?! You don't need to keep doing this just because we're alone...",
	mission = "Are you really hell-bent on doing missions during your break time? I'll give you a hand, so get them done quickly.",
	vote = "",
	drop_descrip = "Well, I'm pleasantly surprised. A comfortable seat, high-quality beverages, and a nice private room... Hm? Are you going to stand there the whole day? Don't just stare at me like that...",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Are you really content to merely stand and watch after I calmed the raging seas for you? Ugh... I had a hunch... Just this once, I permit you to do as you please with me.",
	main = "Oh? You want to have a drink with me? You're forthcoming, for once... Probiotic yogurt? Because it's good for your health? Come on, you must have something better than that!|It's warming up in here. Perhaps I should take off my jacket... O-oh, you're taking yours off, too?|You want to sit next to me, do you? There's too little room for the both of us to... Hey!",
	touch = "Wish to borrow my jacket?",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Now let us pour some drinks and get comfortable! Oh... A shame we only have drinks suited for children.",
	battle = "",
	id = 499053,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Hm? What are you doing?",
	feeling2 = "",
	login = "The seas have calmed, and no one can disturb us here. You should enjoy this moment of respite to its fullest.",
	detail = "Come on, get over here and help me with– Eek! Wh-why are you touching me there?! Eek!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[499060] = {
	hp_warning = "Tis too soon to start mourning for me.",
	feeling3 = "Zeppelin and I both know what you are. An insignificant insect, trying to defy your destiny. Having said that... I believe a soul like you isn't meant to blindly accept their destiny.",
	mail = "There's a letter for you. I command you to read it at once.",
	expedition = "Your commission team underlings have returned. You know what to do now, yes?",
	win_mvp = "I've achieved the victory you desired. It wasn't so hard.",
	home = "I bid you welcome back, Commander. Well fought. I await the day you work up the courage to challenge me.",
	unlock = "You've finally come, my familiar... Pardon, my \"commander.\" I am the Unhulde, August von Parseval. 'Tis a pleasure to meet you.",
	touch2 = "You let your urges take control of you... Fine. Revel in the bliss of your inevitable, pathetic defeat.",
	mission = "I can't imagine you'll falter in the face of such simple trials. Or \"missions,\" as you call them.",
	vote = "",
	drop_descrip = "Aircraft carrier – August von Parseval.",
	feeling4 = "I enshackled you precisely so you'd want to rebel and make me submit to you. Why, you ask? Because I've been drawn to you all along. Now show me that fearsome potential that sleeps within you.",
	lose = "For every victor, there must also be a loser...",
	feeling1 = "I have nothing to say to those who cannot fight.",
	skill = "There is no escaping me.",
	upgrade = "Improving the base principles.",
	propose = "So you seized the chance to subjugate me first. Yes, you are at your brightest when you kick and scream in the cage known as love. Allow yourself to be bound to me and amuse me for all eternity... Darling.",
	feeling5 = "People cannot say no to their hearts. Much like I cannot refute my love for you, you cannot deny your feelings for me. That is the link that binds us together.",
	main = "What does being my familiar entail? You shall learn in due time.|You're awfully quiet... Have you given up already? Obedience does not amuse me.|I can read you like an open book when you stare at me, Commander.",
	touch = "What do you seek to learn from the Unhulde?",
	voice_key_2 = -1,
	mission_complete = "\"Mission\" complete. Congratulations. Another small step towards that alluring, dangerous climax.",
	battle = "Bow before me!",
	id = 499060,
	gift_dislike = "",
	gift_prefer = "I have to thank you for putting a smile on my face.",
	profile = "Tis I, August von Parseval, Iron Blood aircraft carrier. I am but a vessel, but I am also the chains that bind you. Remember this, my familiar. Or should I say, \"Commander?\"",
	voice_key = 49906,
	headtouch = "Are you... disobeying me?",
	feeling2 = "To indulge in the sweet sap of sloth, or to swallow the bitter medicine of hard work? The choice is yours alone to make, Commander.",
	login = "Quiet, you... Your arrival has merely made my aide a little wary. Pay it no mind.",
	detail = "Yes, resist me. I look forward to seeing your reaction when you realize that all your struggling has been for naught.",
	couple_encourage = {
		{
			{
				49905
			},
			1,
			"You seem like you'd know a thing or two about magic.",
			0
		},
		{
			{
				40703
			},
			1,
			"Your strength is worthy of admiration.",
			0
		},
		{
			{
				40701
			},
			1,
			"Show me the face of the Finale.",
			0
		}
	}
}


_G.pg.base.ship_skin_words[499061] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Check... your mail...",
	couple_encourage = "",
	expedition = "",
	win_mvp = "This is the victory you wished for, \"Master.\" Hehehe.",
	home = "Welcome back, \"Master.\" You may give me any order you desire... Anything you want...",
	unlock = "My hair is a mess... There we go. No, I don't need a hand. I am here to serve you in this fleeting dream of yours. Enjoy it while it lasts. Hehehe.",
	touch2 = "Yes, use your maid to satisfy all your desires, \"Master.\"",
	mission = "",
	vote = "",
	drop_descrip = "My hair is a mess... There we go. No, I don't need a hand. I am here to serve you in this fleeting dream of yours. Enjoy it while it lasts. Hehehe.",
	feeling4 = "",
	lose = "I suppose my unfamiliarity with this role is to blame.",
	feeling1 = "",
	skill = "",
	upgrade = "This new power is no dream.",
	propose = "",
	feeling5 = "",
	main = "You will never subjugate me if you get complacent in your temporary position. You desire permanence, but we shall inevitably return to the status quo.|I know your disposition, Master. Simply watching from a distance does not satisfy you.|You did not conquer me. I simply chose to \"lose\" to you. Hehehe~♡",
	touch = "Yes, \"Master\"...?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "Keep on struggling through this ceaseless dream.",
	id = 499061,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Mgh... Yes, do whatever you please...",
	feeling2 = "",
	login = "There you are, my familiar... and \"Master.\" I'm curious to see how you'll attempt to defy and make use of me today.",
	detail = "Order me around as you please. A lowly maid deserves no pity or modesty from her defiant conqueror."
}


_G.pg.base.ship_skin_words[499062] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Heehee... Surely you have the time to at least open a letter.",
	expedition = "A commission has been completed? Then it's time to issue your next orders.",
	win_mvp = "",
	home = "Welcome back. Though I'm not getting changed just yet, do not take this as laziness on my part. Remember that you are in no position to order me around.",
	unlock = "You've come, my familiar. I wondered when you'd awake from your... Hm? A little nicer than usual? Yes, because even I have my moments of placidness. Would you prefer that I was more harsh to you?",
	touch2 = "*sigh*... Are you raring to struggle again, as you did yesterday?",
	mission = "You should have completed that mission and returned sooner, Commander.",
	vote = "",
	drop_descrip = "You've come, my familiar. I wondered when you'd awake from your... Hm? A little nicer than usual? Yes, because even I have my moments of placidness. Would you prefer that I was more harsh to you?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "This shirt? Why, yes, it's the same one that you wore yesterday. What of it? Isn't it only to be expected that you as my familiar offer me a nightly tribute?",
	main = "While I do not personally grant you this sunlight and moment of reprieve, I allow you to enjoy it beside me.|What are your plans for the day? You may as well try to resist me and amuse me when you eventually submit.|You know that I can read your mind when you stare at me, and yet you continue doing it... What, I wonder, has caught your eye?",
	touch = "Will you try to pass this off as a \"massage\"?",
	voice_key_2 = -1,
	mission_complete = "Of course. This is your reward, my familiar. Is there anything else you wish for?",
	battle = "",
	id = 499062,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Oh? It's \"unbecoming\" of me to style my hair with my own hands? Then you shall do it for me, my familiar.",
	feeling2 = "",
	login = "Here you are, my fitting familiar, amidst the bright sunlight... Now, allow the Unhulde to enjoy her moment. Naturally, you have no right to object.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[499063] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "I knew you would return. Heehee... Not even you can escape the Unhulde's clutches.",
	unlock = "Welcome to the Unhulde's secret garden, my familiar. I have prepared this night banquet for you alone. Now then... if you would please step forth.",
	touch2 = "Do what you will in the Unhulde's garden. It won't make a difference.",
	mission = "The ceremony cannot continue until you are finished with your \"missions.\"",
	vote = "",
	drop_descrip = "Welcome to the Unhulde's secret garden, my familiar. I have prepared this night banquet for you alone. Now then... if you would please step forth.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "You have done well tonight, my familiar. The lights of this secret garden will shine for you for all eternity, and I shall wait for you here on each night that the stars twinkle. Do not keep me waiting too long.",
	main = "Have you forgotten? In order to dance with the Unhulde, you must first make the appropriate preparations. It seems my familiar is a touch impatient.|My dress is beautiful, you say? Shouldn't those eyes of yours be focusing on something more valuable than my attire? Heehee.|I am satisfied with you tonight. You may have this dance as a reward... I ask that you decide when it ends.",
	touch = "You will put more tension into those arms and hold me tightly... that's right. Very good.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 499063,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "You revealed yourself at the appropriate time. Such an obedient little familiar... Now that the banquet's guests of honor are here, the stars have begun to shine for you.",
	detail = "The moonlight glitters on the water's surface, and even the final ripple peters out into a lull. Take my hand. The Unhulde's ceremony is about to begin.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[699010] = {
	hp_warning = "Danger is an opportunity! Have at you!",
	feeling3 = "You possess insight and views superior to those of commonplace boors. But, as it stands, you could use some more... well, ambition.",
	mail = "A letter of surrender from our enemies? Then allow me to establish our terms.",
	expedition = "The commission team has returned. Take it from me, you really ought to venture out with them to see the sights of the world more often.",
	win_mvp = "They're surrendering already? So... We won? What pathetic adversaries we have.",
	home = "I believe the secretary should have the power to issue commands. Only while you're away, of course.",
	unlock = "I hope you know what you're in for, now that you've awoken me. Hehehe... You look to be a commander of valor and culture. Magnificent! I am Marco Polo. Now, come! Our first order of business is to spread the Sardegna Empire's glory through the world!",
	touch2 = "Tsk! Such boorish behavior...",
	mission = "New missions? Be magnificent and get them done in a jiffy, okay? Chop-chop.",
	vote = "",
	drop_descrip = "Battleship – Marco Polo.",
	feeling4 = "You command a whole fleet of ships, and you don't even try to use them to spread the Empire's– I mean, your own glory? It truly baffles me.",
	lose = "You wretches... I will inflict this humiliation back at you a hundred times over!",
	feeling1 = "If not for your position, I would've sent you away to... Never you mind. Hmph!",
	skill = "Bow before my might!",
	upgrade = "The greater one's strength, the more privileges one is entitled to. You know this, yes? Magnificent!",
	propose = "A woman with great aspirations doesn't let commitments bind her. But... for you, I'll make an exception. And don't you dare vanish on me until your ambitions are realized!",
	feeling5 = "You! What is the deal with you? I never said you should \"spread the glory of Marco Polo's name!\" You... You... You're too ambitious for your own good!",
	main = "All things of value are bound to fall into someone's hands, sooner or later. Better it be yours than someone else's.|The golden Dragon Empery... I have countless stories of it to share if you'll only lend me an ear!|Looking at the map... This port is unbelievably small. Has the thought of expanding it never crossed your mind?",
	touch = "For what have I been summoned?",
	voice_key_2 = -1,
	mission_complete = "You've finished those chores? Magnificent! Now we can focus on more important matters.",
	battle = "Soldiers, weigh anchor! For the glory of Sardegna!",
	id = 699010,
	gift_dislike = "",
	gift_prefer = "I graciously accept this sincere gift of yours. Heheheh!",
	profile = "I am Marco Polo, Sardegnian battleship. Compare me with Veneto if you so wish, but just for the record: I could do her job much better. Ohohoho!",
	voice_key = 69901,
	headtouch = "I've been meaning to ask... Why do you always behave so childishly?",
	feeling2 = "Oh? You're approaching me? Instead of keeping me at arm's length, you wish to get to know me? Then by all means... Hehehe!",
	login = "So you've come prepared to sacrifice a portion of your time on this mortal coil in the name of productivity? Magnificent!",
	detail = "I don't mind you acting as my own Rustichello. In fact, I adore having someone who chronicles my life. Oh, but please do omit my mistakes!",
	couple_encourage = {
		{
			{
				60501
			},
			1,
			"A leader who second-guesses herself is no leader at all.",
			0
		},
		{
			{
				6
			},
			5,
			"For the glory of the Empire!",
			3
		}
	}
}


_G.pg.base.ship_skin_words[699011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "I've left your letter right over there. It's as easy to reach as possibly can be.",
	expedition = "The commission team has returned. Someone must receive them, but who?",
	win_mvp = "Acting on the Commander's behalf, I raise a toast to this victory!",
	home = "Where, oh where is my master who refuses to delegate work to a maid? Here, I've taken these duties upon myself in your stead.",
	unlock = "Me? Serve as your maid? Oho! That's more like it, Commander! How magnificent and ambitious of you! ...Only temporarily? And you're content with that?",
	touch2 = "Hwaaah?!",
	mission = "You've been given new missions. Fascinating how announcing that is part of a maid's duties...",
	vote = "",
	drop_descrip = "Me? Serve as your maid? Oho! That's more like it, Commander! How magnificent and ambitious of you! ...Only temporarily? And you're content with that?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Interested to learn a trick, Anchorage? Watch this card... Tadah! It's gone! Oh, silly Commander. A magician never reveals her secrets.|I wonder how many maids our port has... And of them, how many are assigned to the Commander's office and personal quarters... Stop it, Marco! There's no point in pondering that question!|Is it not a maid's duty to issue a slap on the wrist when her master procrastinates? Hehehe! How magnificent that you understand!",
	touch = "Routine tasks, making meals, greeting guests, filing paperwork, hatching plans, doing battle... I can perform anything you require!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 699011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Hm-hm~♪ Have you no orders for your maid? You're hardly the authoritative master I'd imagined.",
	detail = "I've been told many desire to be in a position where they can give you hands-on assistance – like a maid does. Which is to say: I am envied by everyone around me. Hehehe, hehehehe~",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[699012] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Did you see that? My magnificent performance!",
	home = "Come, Commander, forget about any hidden doors and focus on my show. Perhaps if you watch carefully from right up close, you might be able to see through the trick.",
	unlock = "Welcome to Marco Polo's magic show! Make sure you watch closely, Commander, and pay attention! Don't get too engrossed in the entertainment, now! Ooohohoho!",
	touch2 = "Now that you have dared to come this close, I... I won't let you get away!",
	mission = "",
	vote = "",
	drop_descrip = "Welcome to Marco Polo's magic show! Make sure you watch closely, Commander, and pay attention! Don't get too engrossed in the entertainment, now! Ooohohoho!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "That's quite some nerve you have. You know my objective is not as simple as it seems, yet you still chose to approach. I'm going to find it even harder to let you go than ever before!",
	main = "Time to perform a miracle... Heehee! Well, Commander, did my perfect finale blow you away?|Mmgh! Nnngh! A problem with the stage? That's impossible – I'm Marco Polo! This interval is the perfect thing to add a little excitement to my performance! I have everything under control!|This is an intriguing outfit, don't you think? Oh? It suits me, does it? Say, why are you looking at me like that?",
	touch = "It's just a little trick. You have nothing to be afraid of... Now, hurry up and come in!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 699012,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "I-I'm in the middle of my performance! What about my hat? There's nothing hidden underneath it!",
	feeling2 = "",
	login = "What do you think? There's nothing to it, even when I'm stuck inside a box and immobile. Now, will you engage in this thrilling challenge with me?",
	detail = "How strange... The box's hidden door won't open. Keep your composure, Marco Polo. You can't afford to show any weakness... Just strike a pose before the Commander realizes there's something amiss! Nrk! My arm's gone to sleep!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[699030] = {
	hp_warning = "So this is real combat... It's a lot harder than my simulations!",
	feeling3 = "Commander, let's go read in the library today. Ugh, you have work? Hmm... Then I'll bring a book here! I can study anywhere as long as you're there with me!",
	mail = "New correspondence has come for you. I'll go get it – it's hardly fair to waste your study time on trivial matters.",
	expedition = "Commander, the commission has been completed. I'll go pick the team's brains!",
	win_mvp = "Heheh... A textbook victory.",
	home = "Commander, work-life balance matters. Get some rest. I already know what needs to be done, so rest assured – I'll handle it.",
	unlock = "Good day to you, Commander. I am Vittorio Cuniberti, a Sardegnian destroyer. It's a pleasure. From now on... Hmm? You're hankering for an academic discussion? I'd be delighted! Tell me, what should we discuss? If mew want... I-I mean, ahem!",
	touch2 = "I-I-I have a question! The optimal sequence of romantic development should mean that the next step is... Argh, what was it? Why can't I remember?!",
	mission = "A new mission? Fantastic! Let's keep our brains limber and agile!",
	vote = "",
	drop_descrip = "Destroyer – Vittorio Cuniberti.",
	feeling4 = "This is such a weird feeling... My heart won't stop pounding. Could this be... love's ultimate puzzle?! Have you encountered this puzzle, too, Commander?",
	lose = "I lost? Well, that removes one suboptimal path... Let's run it back!",
	feeling1 = "I thought I could learn so much from you, but it looks like I'll have to be the teacher now. *sigh*...",
	skill = "Now you'll see what raw knowledge can do!",
	upgrade = "Heheh. Yet more knowledge for me.",
	propose = "Commander... Love is such a difficult puzzle to solve. Heheh, I'VE already found the perfect solution, but I can't just share it with you... All you need to know is that you, yourself, are the solution. Because from now on, you'll take my hand and lead the way... won't you?",
	feeling5 = "Commander, do you remember that puzzle I mentioned? Well... I think I've figured out the solution! Heheh, I'll show you the most beautiful mathematical proof. Just you watch!",
	main = "Ahem... I have more than one method at my disposal to solve this. See here? This presents a totally new perspective. Huh? You've found a logical flaw? That can't be... I checked this so many times! Commander, think harder before you offer a conclusion!|*sigh*... I've explained this three times. How can people still not understand it? How do they plan to pass the exam... Huh? Do I look smug right now? H-heh...|They were doing research in this story, but they left it unfinished! Commander, we need to follow up on this! Right now! To the laboratory we go! Even if it blows up, this is vital!|Wow... The port library has so many more books than I imagined... Huh? This one is clearly on the wrong shelf... Heheh, I've studied collections management. Time to put my knowledge to practice!",
	touch = "Hmm... Meow?! Geez, you scared me! ...Oh?! I just had a flash of inspiration!",
	voice_key_2 = -1,
	mission_complete = "The process of completing a mission involves the acquisition and application of knowledge... Is this how you learn, Commander?",
	battle = "We have ample intelligence and ammunition. Time to put some fear into those unprepared buffoons!",
	id = 699030,
	gift_dislike = "",
	gift_prefer = "I've never seen this before! Fascinating!",
	profile = "I'm Vittorio Cuniberti of the Sardegna Empire. My passion is researching pioneering subjects. Of course, if you need my knowledge put into practice, I'm more than happy to oblige.",
	voice_key = 69903,
	headtouch = "Mreow?! Hands off my headband, please!",
	feeling2 = "Ahem... Commander, did you need me for something? Otherwise, I don't know why you'd be staring so much... Yes, I know – I watch you in my peripheral vision. So? Do you want to learn something, or do you think that my earnest work is worth learning from?",
	login = "Your work documents are ready. Start whenever you feel like. Heheh... It was no big deal. I just considered what I would want if I were in your shoes – Oh? It looks like double your usual work? That can't be... I thought I'd reduced it...",
	detail = "The only subjects worthy of my study are the ones that are utterly incomprehensible to mundane minds. Hmm... The solution to this one can't possibly be as simple as it looks. Heheh... I already have an idea. Let's start the experiment right away!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[699031] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Zzz... Mmnh... Commander, welcome back... Huh?! I-I wasn't sleeping! Cats only ACTUALLY sleep for four to five hours a day – the rest of the time, they're just dozing!",
	unlock = "To study an animal's habits, you must first learn and imitate... B-basically, what I'm doing is imitating how cats do things! Don't read into this!",
	touch2 = "Commander, where did you learn to do that? I-it feels nice...",
	mission = "",
	vote = "",
	drop_descrip = "To study an animal's habits, you must first learn and imitate... B-basically, what I'm doing is imitating how cats do things! Don't read into this!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Commander, I've cracked the code of feline courtship! Heheh, showing their bellies is just one way. See... Hyah?! My bra strap slid off?! D-don't look! Look, and I'll bite! Grrr, chomp!",
	main = "Commander, I'll get bored if you just keep waving around the same toy all day. Can you pick a new toy? I have yarn, and... Huh? What's with this belt? Do cats like belts?|I'm the one who spilled the milk. Cats like to do that, so... Oh! Can I play with it more?|Geez, Commander... I understand it's easy to get distracted by how cute those cats are, but we're in the middle of important research! You should be focusing on me!|Why did I lick my glove? Because it's where you just touched. This is how a cat learns her owner's scent.",
	touch = "Hyah?! C-Commander! Do NOT touch my tail without permission! I'll bite!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 699031,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Mreow?! You should know that cats' ears aren't to be touched so flippantly!",
	feeling2 = "",
	login = "Commander, I think I'm starting to understand how cats feel... Why, I'm practically dying to bat at that cat toy. Kitties must feel the same way, don't you think?!",
	detail = "Purr, purr... Purr, purr... This is how cats get their owners' attention. When they do that, their owner needs to scratch under their chin... Then, they'll be happy!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[299050] = {
	hp_warning = "I'm ashamed to show you my unsightly side...",
	feeling3 = "I don't know too much about the Royal Maid Corps. Since I support you just as they do, there should not be much difference in our positions. Do you agree, dear Commander?",
	mail = "Rejoice, dear Commander, for new mail has arrived.",
	expedition = "A commission has been completed. Let us rejoice now, dear Commander.",
	win_mvp = "Victory is ours. Rejoice, dear Commander.",
	home = "Rejoice, dear Commander—I have come to bring you a full-course Sardegnian meal. ...It's too heavy, you say?",
	unlock = "I offer my greetings to you who has manifested me, Commander. I am the blueprint ship, Plymouth. Starting here and now, I stand ready to execute your every order. May you rejoice in our blessed encounter.",
	touch2 = "Yes, do as you please with me. As long as it makes you rejoice, dear Commander.",
	mission = "A new mission has arrived, Commander. Allow me to– Hmm? You're going to do it yourself?",
	vote = "",
	drop_descrip = "Light Cruiser—Plymouth",
	feeling4 = "Rejoice, dear Commander, for I shall be assisting the Royal Maids today. ...With the assistance of my colleagues, I shall be able to support you to an even greater capacity –a reason to rejoice indeed.",
	lose = "So this is the taste of defeat, Commander. How repugnant.",
	feeling1 = "Rejoice, dear Commander, for you can still turn to me for help now.",
	skill = "Please excuse me.",
	upgrade = "Strength flows through me. Rejoice, dear Commander, for I have become \"easier to use.\"",
	propose = "Rejoice, dear Commander! Starting today, I shall become your exclusive-use shipgirl! By exclusive, I mean special... Basically, I've become someone special to you, so can I stop looking after you today and just rejoice for myself? Heehee~",
	feeling5 = "Commander, are there any wishes you'd like to have fulfilled today? I am no longer here just to support you. Should you desire, I shall assist you, serve you, and of course, love you... Rejoice, dear Commander, for there is nothing I will not do for your sake.",
	main = "Oh, do be careful now... Miss Edinburgh, it seems that the rumors of your clumsiness were... not greatly exaggerated.|Did you need some papers disposed of. *BOOM* ...There you go. Rejoice, for I have turned your troubles into a pile of ash!|Having trouble focusing on your work? Well, I suppose I could tell you a fairy tale. A long, long time ago...",
	touch = "You'd like to hear me sing? Then, please tell me what you'd like to hear—if it's something I don't already know, I'm willing to learn.",
	voice_key_2 = -1,
	mission_complete = "The mission rewards are here. Let's open it—it'll be destroyed if I fire a shell at it? Understood.",
	battle = "I shall take you on.",
	id = 299050,
	gift_dislike = "",
	gift_prefer = "I want you to be pleased, Commander, because you've made me very happy.",
	profile = "I am the blueprint ship Plymouth, an alternate branch of the Edinburgh class. I give my thanks to you for manifesting me in this port. Please, use me as you see fit.",
	voice_key = 29905,
	headtouch = "Your hand feels most pleasing upon my head. Thank you.",
	feeling2 = "You may rely on me more, Commander. After all, my duty is to help you help everyone.",
	login = "Rejoice, dear Commander, for this morning is most refreshing. How shall we start our day?",
	detail = "A pleasure to see you today. I hope to spend another wonderful day with you today, dear Commander. Mhm, quite the reason to rejoice.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[299051] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Be it the cooling waves or the taste of victory, please indulge as much as you'd like, dear Commander.",
	home = "Good work on your mission. Is there anything you'd like me to get for you, dear Commander? Since we're at the pool, how about... some toys, some fruits, and some wine? How does that sound?",
	unlock = "Rejoice, Commander. I have no doubt that this refreshing sensation will bring you the utmost satisfaction. Come, let us enjoy this experience together.",
	touch2 = "Revel in me. Rejoice to your heart's content, dear Commander.",
	mission = "",
	vote = "",
	drop_descrip = "Rejoice, Commander. I have no doubt that this refreshing sensation will bring you the utmost satisfaction. Come, let us enjoy this experience together.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Dear Commander, if you are feeling restless, might I recommend taking a dip with me in the refreshing water?|You want some song suggestions? Well, if you're fine with the kind of screamo Miss Ulrich has been showing me, then... Oh, I don't need to sing it for you?|Will you be swimming? Then let me make the pool larger... Excuse me, would you mind getting out of range of my main battery? Oh... Dearie me.",
	touch = "Sure, let's laze around together.",
	voice_key_2 = -1,
	mission_complete = "The mission rewards have arrived. Rejoice, dear Commander.",
	battle = "This is rather embarrassing, but...",
	id = 299051,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Rejoice, dear Commander, the sun's rays shine as splendidly as usual — which means, it's a perfect day for a soak in the pool.",
	detail = "Are you satisfied after seeing me in my swimsuit? If you'd like to see me in another outfit, just give me your order. W-whether it's a maid outfit, or a bunny girl outfit... as long as it makes you rejoice...?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[299052] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Well done on your mission. I'll perform a special full-body physical for you now, so please lie down.",
	unlock = "Rejoice, Commander – I will be assisting you with your physical. If you feel any discomfort at all, please let me know at once.",
	touch2 = "Please do whatever you'd like, until you're satisfied. It's good for the body and the mind.",
	mission = "",
	vote = "",
	drop_descrip = "Rejoice, Commander – I will be assisting you with your physical. If you feel any discomfort at all, please let me know at once.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "You can ask me for anything. I can adjust your pillow, or I can let you listen to my heartbeat... Whatever you may need. I love you, after all.",
	main = "Is the bed uncomfortable to lie on? Wait just a moment... Okay, I've disposed of all beds of that model. Instead, you may use me as your bed. I'll hold you tight so you can sleep well.|Are you nervous about your physical? I can offer you some special, relaxing care to help you. Please enjoy...|Ah! Commander, your heart is racing. Lie down and let me examine you, okay?",
	touch = "I came running as soon as I heard your voice. I'll take your temperature now.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 299052,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Is my warmth soothing? If my face isn't enough, I can let you try other places, too.",
	feeling2 = "",
	login = "Commander, it's almost time for your physical. I hope this outfit I picked out will help you relax.",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[499070] = {
	hp_warning = "How?! But, I'm the strongest...!",
	feeling3 = "Hmph. I've taken a slight interest in you since I can see a smidge of potential within you. Then again, that much should be obvious given that I call you \"Commander.\"",
	mail = "A letter... Nothing I'd care about, it seems.",
	expedition = "The commission team has returned. I wonder what tributes they've brought me.",
	win_mvp = "Me being the MVP is such an obvious outcome I don't even feel happy about it.",
	home = "Look who's back. I suppose you have your moments as the Commander♪",
	unlock = "Ooh, so you're the self-proclaimed Commander, huh... Hmph! Commander of what, exactly? From now on, I shall be the one issuing commands around here! Now, hurry along~♪",
	touch2 = "Eek! Don't touch me!",
	mission = "Missions, eh... Do them yourself. I'm above all that busywork.",
	vote = "",
	drop_descrip = "Battlecruiser – Prinz Rupprecht.",
	feeling4 = "You belong to no one but me, Prinz Rupprecht. That should be obvious, seeing as how I have acknowledged you as \"Commander.\" Do you have a problem with being mine? Too bad – you've never had and never will have the right to object!",
	lose = "You're horribly mistaken if you think you'll get away with this!",
	feeling1 = "Get out of my sight. You're an eyesore.",
	skill = "Hahahaha! I'll squash you like bugs!",
	upgrade = "It's the obvious choice, because I am the strongest♪",
	propose = "Marriage? What are you talking about? This is an act of insolence on your part, one-sidedly hoping I'll exchange vows with you. Obviously, it's my choice whether to accept or refuse... If you want my hand so badly, cry and plead for it one more time! And don't try to run away!",
	feeling5 = "You don't want to be mine? You have some nerve, you impudent cretin. You are mine, full stop. I don't give a damn what anyone else says! You belong to me, and that's that!",
	main = "A tea party? Who went and decided I have to spend my time on that? If anything, YOU should be spending time with ME♪|...Oh, this sweet candy? I got it from a destroyer. And no, you can't have any.|You can't even do this no-brainer work? And you seriously call yourself the Commander? ...Things would be better if I had your position.",
	touch = "What's that you're staring at? Hand it over. I want to see it for myself.",
	voice_key_2 = -1,
	mission_complete = "Mission rewards! I've claimed them in my na– What the hell! This is just a list!",
	battle = "Victory will be mine!",
	id = 499070,
	gift_dislike = "",
	gift_prefer = "What a sweet tribute. It's mine now!",
	profile = "I'm Prinz Rupprecht, Iron Blood blueprint ship. It's my way or the highway. Hmph, obviously I get to act high and mighty because I AM high and mighty. I don't HAVE to follow your orders, they are merely suggestions to me!",
	voice_key = 49907,
	headtouch = "Blep!",
	feeling2 = "You should be thankful that someone such as myself would even deign to call a complete nobody like you \"Commander.\"",
	login = "You're late! What excuse do you have to keep ME waiting? Do you WANT me to send you packing?",
	detail = "Tuning my rigging should just take a little... Whoa, calm down! Heed my damn command! ...You! Stop gawking and help me! It's only the obvious thing to do!",
	couple_encourage = {
		{
			{
				40304,
				49902
			},
			1,
			" That dummkopf is mine, you hear?!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[499071] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Hmph! There's your victory! You'll obviously reward me for my efforts, yes?",
	home = "They've changed my port so drastically I don't know what's what anymore... I should've stayed home since the Commander's away... Whuah?! C-Commander?!",
	unlock = "Woah, so this is the Dragon Empery's \"Spring Festival\" that I've heard so much about. But, why are they celebrating it in the middle of winter? And you, Commander – why are you helping with such a grandiose... Whuah?! What was that noise?!",
	touch2 = "D-don't you dare blame it on my dress!",
	mission = "",
	vote = "",
	drop_descrip = "Woah, so this is the Dragon Empery's \"Spring Festival\" that I've heard so much about. But, why are they celebrating it in the middle of winter? And you, Commander – why are you helping with such a grandiose... Whuah?! What was that noise?!",
	feeling4 = "",
	lose = "They... beat us? They beat ME?! There's no way...",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "You belong to me, which obviously means you have a duty to amuse me! Understood, simpleton? You're to give me a full tour of the port's Spring Festival makeover! Hold my hand and show me around! That's your job!",
	main = "Ägir mentioned a lion that dances in the air – I want to check it out... If I SAY it flies, then it FLIES, okay?! And you're going with me, obviously!|A red envelope? Are you that strapped for cash even though you run this place? ...Hm? You're giving it to me? I don't want it! Blep!|Here's what happens to idiots who don't pay attention to me! Hahaha! That's right, run in fear from my firecrackers!",
	touch = "Where did that cretin bumble off to... Hyeep?! D-don't just sneak up on me out of the blue!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 499071,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "So for the Spring Festival, a carp is needed as decoration, which then turns into a dragon... Doesn't make any sense to me. Besides, how in the world is a fish supposed to turn into... Whuah?! What the heck was that?!",
	detail = "You are mine, and that means everything you make is mine as well! Nom! ...What'd you call this candied fruit thing? \"Tanghulu\"? It's sour yet sweet, and surprisingly tasty...",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[499072] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "Oh, the commission team is back. Someone should receive them... b-but that can wait, can't it?",
	win_mvp = "I did it! Heheh, did you see that? You must have! ...See what? Me mopping the floor with them, duh!",
	home = "I waited for you here this whole time. Why didn't I just ride something by myself? *whispering* Because I didn't wanna get lost... Shush, I said nothing! I waited here because I WANTED to!",
	unlock = "You're late! I've been waiting ages for you! ...We never agreed to meet tonight? If I say we did, then we did! Anyway, you should feel bad! That's obvious!",
	touch2 = "Wh-what do you think you're doing?!",
	mission = "New missions... Will you stick around if I help with them?",
	vote = "",
	drop_descrip = "You're late! I've been waiting ages for you! ...We never agreed to meet tonight? If I say we did, then we did! Anyway, you should feel bad! That's obvious!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Hmph! I can have all kinds of fun right here! I can swim in the pool, watch the fireworks, think about all the fun we're gonna have... F-forget that last one!",
	main = "You belong to me, so this amusement park also belongs to me! That obviously means I get to ride any attraction whenever I want! ...So, which one do you wanna go on?|The fireworks are nice to look at, but we could've done so much else if you'd come sooner... Blep!|I'm feeling kind of hungry... Speaking of which, do these stalls charge money? Can't YOU get food for free if you ask for it?",
	touch = "Ahahaha! Take this! *splash splash*",
	voice_key_2 = -1,
	mission_complete = "Go get the mission rewards already! They belong to me, so obviously you should be quick♪",
	battle = "",
	id = 499072,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "First, you're coming with me to check out all the night attractions, then we'll go somewhere quiet, and then... Go on, come up with a route plan♪",
	detail = "",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[599010] = {
	hp_warning = "If you think you've got what it takes, come at me!",
	feeling3 = "What do you do on your days off? I... like going out with my friends, I guess. Get some good food and drinks. It's a great change of pace! Oh right, since we have free time today, let's go do that right now!",
	mail = "I picked up the mail for you on the way here. Hurry up and take a look!",
	expedition = "Oh, it looks like our friends are back from their commission! Perfect timing, Commander, let's throw a welcoming banquet!",
	win_mvp = "Hmph, absolutely pathetic. Not even worthy of being my playthings.",
	home = "You must be tired from all that running around, right? Want me to help you relax? I can draw the bathwater for you, or give you a massage... You in?",
	unlock = "The name's Harbin, Dragon Empery light cruiser. You're the Commander of this joint? Hrmm... I like the look in your eyes, and your bod's not half-bad either... Good stuff! From now on, you're rollin' with me!",
	touch2 = "Oho? You've got guts. Real punchable guts.",
	mission = "Another job, huh? Just leave it to me. I'll have everything sorted out for you.",
	vote = "",
	drop_descrip = "Light cruiser - Harbin.",
	feeling4 = "Commander, c'mon, let's get going! Go where, you say? Lemme think... Oh yeah, how about looking for some enemies to beat the crap out of? It's dangerous? Hah, not when I'm by your side!",
	lose = "Retreat now – I'll handle things over here!",
	feeling1 = "A soldier's failure dooms one, but a general's failure dooms the whole army. You're the Commander, so get your act together already!",
	skill = "See how you like this!",
	upgrade = "Hahaha! I'm itchin' for a fight!",
	propose = "Looks like you've already made up your mind. But, this venue isn't lively enough... Let's find an auspicious day and invite all our friends over for a huge banquet. I'm gonna invite everyone, so you better yell my name out to the world!",
	feeling5 = "I've been thinking, Commander. You should totally become mine. We'll go through heaven and hell together, get drunk off glory and riches together, and if you're ever in danger, I'll be there to protect you. Now that's what you call a whirlwind romance! Ahaha!",
	main = "Commander, want to cap off work with a bit of wine? Of course, you're free to drink something else. Gotta treat yourself right after a day of hard work, right?|Hai Tien's always sayin' stuff like \"you are what you eat,\" but she's always guzzling down those chilis like it's nobody's business. If you ask me, the best food is whatever fills your belly.|Chen Hai's out there doing divinations on the cosmos before she makes her move, but I'm the complete opposite. Hit first, ask questions later! Hahaha!",
	touch = "If you have time to burn, wanna see one of my comedy skits? Hahaha, I've got quite a few little hobbies outside of fightin'.",
	voice_key_2 = -1,
	mission_complete = "Well done! I'll hand out the rewards, so you just worry about getting rested up.",
	battle = "Everyone, follow me!",
	id = 599010,
	gift_dislike = "",
	gift_prefer = "You're too kind. You're gonna make me blush! Hahahah!",
	profile = "The name's Harbin, light cruiser from the Dragon Empery. What, didn't expect to see me here? Ahaha, well, life is full of surprises. In any case, I don't plan on letting you down, and neither do my guns!",
	voice_key = 59901,
	headtouch = "",
	feeling2 = "If you're not busy, want to step out for a chat? Haha, there's nothing to be embarrassed about. The best way to get to know someone is to have a nice, long chat with them, right?",
	login = "Mornin', Commander. Need help with anything today? There's no need to be shy - just say the word!",
	detail = "Commander, if there's anything on your mind, just lay 'em on me! Let's not beat around the bush.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[599011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission team just got back. How about we invite them along? The more, the merrier!",
	win_mvp = "",
	home = "Take a hot bath, and you wanna stay in there a bit longer. Go in the ocean, and you wanna start swimming. See what I mean? When people go places, it changes the way they feel.",
	unlock = "Pheeew! I just love blue skies and a fair ocean breeze. Since you're already here, Commander, set aside all the boring paperwork and business stuff, and come enjoy the waves!",
	touch2 = "Look at you, goin' for it out in the open... Yikes.",
	mission = "",
	vote = "",
	drop_descrip = "Pheeew! I just love blue skies and a fair ocean breeze. Since you're already here, Commander, set aside all the boring paperwork and business stuff, and come enjoy the waves!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Are those the Four Unbreakables over there? Looks like they're buildin' a sand castle together... How about we make one of our own?|They say if you hold french fries on the beach, seagulls flock you. We brought french fries, right? Wanna give it a try?!|Look, I reserved this whole beach to be alone with you so that... Huh? The other girls will see? Damn... You've got it rough, bud.",
	touch = "Ooh, you wanna wrestle in the water? I'm not goin' easy on you! Take this!",
	voice_key_2 = -1,
	mission_complete = "Mission rewards, huh? Aw damn, they gave us frozen watermelon! Now there's a stroke of luck. I was just thinkin' of how to cool down!",
	battle = "",
	id = 599011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Commander, you've got some damn nerve makin' me wait... Hah! Hahaha! Got you! Long as you're here, I don't care!",
	detail = "It's cool. If you wanna look, go right ahead! I got this swimsuit just because I wanted you to see me in it, after all!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[599012] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission team's back. Go see 'em! ...Hm? You want me to come, too? Then let's get going right now!",
	win_mvp = "That all you got? Next time, bring someone a little stronger!",
	home = "Someone's looking chipper. You been having fun out there? Oh, if you saw something you like, tell me. I'll buy it for you!",
	unlock = "Hey, there you are. Remember what I said about the two of us being partners in crime? Well, actions speak louder than words, so I reserved this whole cruise for just the two of us. Whaddya say? Sound good, partner?",
	touch2 = "Hah! I'm amazed you can do that in broad daylight. You wanna get cooked, friend?",
	mission = "Do you have new missions? Man, and I was just getting comfy... Nah. If you've got work to do, then let me help. Let's get it done quick!",
	vote = "拉票描述",
	drop_descrip = "Hey, there you are. Remember what I said about the two of us being partners in crime? Well, actions speak louder than words, so I reserved this whole cruise for just the two of us. Whaddya say? Sound good, partner?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "Hahaha, as long as you're happy, I'm happy!",
	propose = "",
	feeling5 = "Heyo, Commander. Are you enjoying the luxuries of the cruise I bought us? Hahaha, hey, it's no big deal. If there's anything else you want, or if someone starts trouble with you, come to me! That's what love is all about, right?",
	main = "Commander, you haven't tried a salt and milk bath yet, have you? No idea what I'm talking about, huh? I'll do it for you next time I wash your back!|Money doesn't magically appear when you're born, and you can't take it with you when you die. What I'm saying is, use it while you can. If I can make you happy, then that's enough return on investment for me!|Hahaha, wanna go play poker? Yeah, fine by me! I'll deal and get you a few free wins!",
	touch = "Did my button come out? Is that a problem? ...Okay, if it bothers you that much, can you fix it for me?",
	voice_key_2 = -1,
	mission_complete = "Finished your missions? Great work! Wanna spar a bit after you rest?",
	battle = "",
	id = 599012,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Finally here, eh? I've been waiting for ages! Was I bored? Nah. I had a lot of fun thinkin' about how I could cook you... Ahahaha! I'm just kidding!",
	detail = "Commander? What's up? Let me buy you something you want! Can't believe you're being so modest with me, of all people... You see my credit card here? Use it as much as you want!",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[599018] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission team is back. Let's take a look... Alrighty! I've got everything I need to make some tasty snacks!",
	win_mvp = "A crushing victory! Let's celebrate with a banquet when we get back home!",
	home = "Geesh, just seeing you beaten and battered by the elements like that has me feeling bad for you, even if you don't think much of it. Hurry on in and take a warm shower, alright?",
	unlock = "Sorry to keep you waiting, Commander. So, how's my new look? It's got me a bit embarrassed... But, well, all that matters is that you like it.",
	touch2 = "Oho? If you're this enthusiastic, I suppose I'll take you up on it~",
	mission = "We've got another job coming up. Why not treat it as some light exercise? You'll get rusty if you sit at your desk all day.",
	vote = "",
	drop_descrip = "Sorry to keep you waiting, Commander. So, how's my new look? It's got me a bit embarrassed... But, well, all that matters is that you like it.",
	feeling4 = "",
	lose = "Heh... Even if I fall here, you're not laying a finger on my friends!",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "I heard that a \"date\" is a great way for two people to learn more about each other. Well, you choose the restaurant then, and I'll cover the bill. Let's treat ourselves to some kick-ass food and liquor! ...That's not it? Did I misunderstand something? I thought that's what it said in one of those novels...",
	main = "Even the most passionate romances eventually become tamed by time... No, no! That simply can't be! Commander, for our next anniversary, let's do something crazy!|Commander, I know we promised to go through hell and high water together, but I don't want to put you through hardships. What if you get hurt? ...Ugh, emotions really are so complicated.|What kind of food are you in the mood for? I'll take you out to somewhere nice tomorrow! You're my lover now, so how could I let you dine on anything but the finest? Ahaha!",
	touch = "If you want me to stay here with you, know that I'm not going anywhere.",
	voice_key_2 = -1,
	mission_complete = "Another job done. The two of us make an unstoppable duo. Let's keep up the pace and pick up the rewards as well.",
	battle = "I'll take up the front!",
	id = 599018,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "About to start on today's work? If you need any help, feel free to ask. We're practically family at this point, so whatever happens, we'll deal with it together.",
	detail = "By the way, d'you reckon I'm any different right now compared to my usual self? For example... a little more feminine, or something?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[799010] = {
	hp_warning = "You're making this harder than it needs to be...!",
	feeling3 = "Ah! ...Another blackout. Yeah, it's a problem with my lab, not the port itself. All my tinkering has made the power really unstable. Just make yourself at home and wait for the lights to come back.",
	mail = "Letter for you, Commander. Be sure to give it a read.",
	expedition = "Commission complete. That's all she wrote. Nothing special.",
	win_mvp = "Done already? Then, let's get moving. We're not getting paid to stand around.",
	home = "Back safe and sound, I see. Here's the after-action report with all the data sorted out. I'll leave the debriefing to you.",
	unlock = "Introductions? Fine, fine... I'm Chkalov, Northern Parliament blueprint ship. That good enough? Let's get back to work then; it's a better use of time for both of us, right?",
	touch2 = "Need to vent some stress, do you? Heehee♡",
	mission = "Here are some mission instructions for you. I can do overtime if it's for science, but I'd rather not for this type of work.",
	vote = "",
	drop_descrip = "Aircraft carrier - Chkalov.",
	feeling4 = "You're more courageous than I took you for, Commander. What do I mean? Well, you know just how risky it is to be alone with me in this place... don't you?",
	lose = "Tsk... I hate writing self-improvement reviews...",
	feeling1 = "I'm actually curious as to how someone can keep failing over and over. You are an awful outlier.",
	skill = "How's this?",
	upgrade = "Well, that's one way of doing it.",
	propose = "A ring, huh... So you'll be indebted to me if I accept it – is that right? Then I'll gladly take it. Sharing a special relationship with you works out nicely... because it makes it easier to examine your mind and body♡",
	feeling5 = "I'll be frank with you. I find you fairly... no, VERY fascinating, Commander. You're the one who leads the shipgirls at this port. It's not often someone gets the chance to closely examine you from the inside and out, wouldn't you say? Heehee♡",
	main = "Ugh... Wish there was some vodka in here... Your office is so much stricter than my lab when it comes to rules and the like.|I'm curious – based on what criteria do you choose a secretary? Surely it's not just good looks? ...But if it is, don't be afraid to admit it♡|I'd appreciate it if you'd let me handle data analysis in addition to office work. Work is boring, but I can stick to it longer when it involves something I'm good at.",
	touch = "What's up? Want me to get you some coffee?",
	voice_key_2 = -1,
	mission_complete = "Mission complete. Maybe I'll get to return to my lab early today...",
	battle = "Sometimes, you have to get your hands dirty.",
	id = 799010,
	gift_dislike = "",
	gift_prefer = "A gift? Don't get mad if I use this for an experiment, ok?",
	profile = "I'm blueprint ship Chkalov, Project 71B aircraft carrier. I'll do a good job as long as you pay me, and if I ever ask for something, you can expect something in return. I hope we can have a mutually beneficial relationship.",
	voice_key = 79901,
	headtouch = "",
	feeling2 = "I sleep in my lab on most nights. There are some places to lie down, and for dinner you can always just order home delivery. Why don't you stay sometime, Commander?",
	login = "Oh, so you're a real workhorse. Suppose I'll really have to apply myself as your secretary then.",
	detail = "You're not just here to chat, are you? If you've got something important to say, spit it out. Just don't expect me to respond right away because I'm busy.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[799011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission team has returned. Oh, looks like they're running over to their friends. Shouldn't you go see them, Commander?",
	win_mvp = "Will you let me examine your body later, as a reward? No?",
	home = "You look like you had a blast back there. I recommend getting some rest.",
	unlock = "Oh? What made you come over here instead of heading down to the beach? Surely you didn't ditch your friends on a hard-earned day off just to see me? But, I don't mind. It's called a day off because you get to decide how to spend your time.",
	touch2 = "\"Come and give Ms. Chkalov a hug!\" Heehee♡",
	mission = "I hope inspiration will hit me as we go through these missions.",
	vote = "",
	drop_descrip = "Oh? What made you come over here instead of heading down to the beach? Surely you didn't ditch your friends on a hard-earned day off just to see me? But, I don't mind. It's called a day off because you get to decide how to spend your time.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "I've pinned down your swimsuit preferences after tracking your eyes and analyzing your phrasing when asked for feedback. Heehee.|Still hard at work? You're hardly treating this like a vacation day. No, no, I know it's for the sake of all of us. You can expect a little something from me later.|Seeing Northern Parliament girls take off their winter coats and put on skimpy swimwear must be a real treat. For you, that is.",
	touch = "I feel this occasion calls for a bottle of vodka.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 799011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Hanging out, basking in the sunset's glow together... It's pretty nice, wouldn't you say?",
	detail = "I like the sea breeze, but the sun is a bit much for me. Life in the lab makes you sensitive to sunlight, you see. On that note, try not to spend TOO much time in your office, Commander.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[799030] = {
	hp_warning = "Ack! Things are getting a little hairy.",
	feeling3 = "Yoohoo! I'm here to help you get through your overtime work! Guess what I brought you... Ooh, does it smell burnt? That's right – I made cookies to look like you! They look just like you apart from the whole \"burnt to a crisp\" thing, right?",
	mail = "Yoohoo! Reminder from the super-popular Dmitri: you've got new mail, so read it soon!",
	expedition = "Yoohoo, the commission team's back! Go thank them properly, okay? And thank ME for reminding you, too!",
	win_mvp = "See that? They realized they were up against a star, so they let me win!",
	home = "Yoohoo! Looks like I greeted you first again. If you need anything, leave it to me, okay? I'll have it done as perfectly as can be.",
	unlock = "Yoohoo, Commander! I've been looking ALL over for you! Whaaat? YOU were looking for ME, too? Pssh, whatever – anyway, you must be so happy to meet me, right? Heheh, it's written all over your face!",
	touch2 = "Whoa! You're unusually bold. I like that!",
	mission = "You're going to let me handle this new mission, right? Right? Riiiiight?",
	vote = "",
	drop_descrip = "Light cruiser – Dmitri Donskoi.",
	feeling4 = "Yoohoo! I finished all the work you gave me. Do you know what you're supposed to do next? Huh? You DON'T? Then repeat after me: \"Dmitri is the cutest! Dmitri is the awesomest!\"",
	lose = "O-oof... Don't worry, Dmitri. People won't hate you over one loss!",
	feeling1 = "Hmm... Even I can't help you if you keep that up...",
	skill = "You'd better be happy to meet me! Smile, or you're gonna get it!",
	upgrade = "Yoohoo! More proof that I'm your favorite, huh?",
	propose = "Finally... Finally, the day has come! I knew you cared about me, Commander! You LOVE me! Hehe... And I love and care about you a lot, too! I... super-love you, okay? Can you... prove your love to me now?",
	feeling5 = "Hey, Commander? I'm not as popular as I used to be, so... I'm leaving, and I'm never coming back– Ah?! C-Commander? C-cut it out, I was just messing with you! Wait, where are you taking me?!",
	main = "Yoohoo, Commander! Guess what snack I brought today! Tadaaa – it's a super-rich chocolate cake! It's a perfect refreshment for a long day's work! I bought it for you, so eat up!|Commandeeer! Have you noticed anything different about me today? Haha, that's right! I didn't say yoohoo this time! Would I be just as popular this way, you think?|Yoohoo, Commander! Is anything on your mind? Talk to me, if you need to. After all... the whole reason I'm here is to help you!|Yoohoo, Commander! Everyone says you're the most popular person at port. You've gotta have some kind of secret, right? Huh? You don't? Well, I'm gonna wait here until you give me pointers!",
	touch = "Ah! Hey, Commander, how can I be even more popular? Got any advice for me?",
	voice_key_2 = -1,
	mission_complete = "Yoohoo, mission's done! A big win for the Commander – and for me, by extension!",
	battle = "You're up against a star today!",
	id = 799030,
	gift_dislike = "",
	gift_prefer = "Oh, wow. This is like my favorite thing! You know me so well, Commander.",
	profile = "Yoohoo! I'm Dmitri Donskoi, and I'm a blueprint ship of the Northern Parliament! You know, I'm actually a super-popular star. Haha, I saw that smile! You can tell, can't you?",
	voice_key = 79903,
	headtouch = "Whoa! You can just take my hat off if you want, you know. Like this... Huh? Come on, back to petting!",
	feeling2 = "Yoohoo, Commander! It's important to keep up your spirits, so let's go to the amusement park and ride some roller coasters! I hear it's a great way to relieve stress.",
	login = "Yoohoo! Look at that, we meet again! I kept your seat warm for you. Aren't you happy?",
	detail = "Guess who! ...Correct! High five for your BFF! Hehe.",
	couple_encourage = {
		{
			{
				40302,
				10208
			},
			1,
			" Heheh☆ Yoohoo!",
			0
		}
	}
}


_G.pg.base.ship_skin_words[799031] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "Yoohoo! Tired from all that traveling, Commander? You look beat. How about a massage and a lullaby, courtesy of Dmitri? They're guaranteed to get you dreaming in no time!",
	unlock = "Yoohoo! Welcome, Commander! How do you like your room? Does it make your heart flutter? Hehe, we've got all kinds of services – I can put you to bed with a massage, or do whatever animal role-play you're into... Bunny Dmitri's here to make all your dreams come true!",
	touch2 = "Commander, bunnies bite when they get mad... Ah! I'm not saying you can't touch me. I'm saying you can't LEAVE!",
	mission = "",
	vote = "",
	drop_descrip = "Yoohoo! Welcome, Commander! How do you like your room? Does it make your heart flutter? Hehe, we've got all kinds of services – I can put you to bed with a massage, or do whatever animal role-play you're into... Bunny Dmitri's here to make all your dreams come true!",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "This room is all ours now, Commander~ I know you just love me to bits in this outfit, don't you? Heheh♪ In that case... Why don't we take things one step further?",
	main = "Yoohoo! Congrats on winning the jackpot in the Bunny Dmitri Lottery, Commander! As for your prize... Tadaaa! You get 999 nights of being put to bed by me! The number doesn't really matter – I'll just do it whenever you want.|Ding-dong, it's time for my animal role-play survey! What do you like, Commander? My bunny impression, or my bear impression? Answer carefully, now. Bunnies go \"squeak!\", and bears go \"roar!\" ...Pretty good, right?|Yoohoo, Commander. Do you know what this pose means? \"On the hunt\"? Well, you are... Correct! Can you guess who my prey is? Hehehe~ It's you, of course!",
	touch = "You really like my outfit, don't you, Commander? Hehe, I can see right through you!",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 799031,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "What's up? Did my bunny ears get messed up? ...Huh?! They weren't, but they are NOW because you touched me? Well, you'd better keep going and give me more headpats!",
	feeling2 = "",
	login = "If you're not happy with this room, I can get you into another one! ...You are? Okay, then this is our secret hideout now! Get ready to enjoy my special service, Commander♪",
	detail = "You wanna bake cookies? Is that the whole reason you came here? Nuh-uh! Your personal bunny is right here, Commander... What other snacks do you need?",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[899030] = {
	hp_warning = "There's no need for haste. We have plenty of time still~",
	feeling3 = "The oracles of legend were said to be able to foretell the fates of humans. Even though I don't have that power, I've read your story up close, and believe that you have what it takes to become a true Champion.",
	mail = "New mail has arrived.",
	expedition = "Our friends have returned to us from their odyssey. I wonder what kind of stories they brought back with them?",
	win_mvp = "And thus, a new passage is inscribed in our Champion's paean––",
	home = "Our Champion returns triumphantly... I feel the inspiration for a new paean coming~",
	unlock = "Are you our Champion? I am Brest of Iris Libre. Now that fate has brought us together, may our journey be blessed.",
	touch2 = "Oh my... I suppose every champion's tale has indiscretions such as these~",
	mission = "There's no need for haste, Champion. Keep it slow and steady, just as you always do.",
	vote = "",
	drop_descrip = "Large cruiser - Brest.",
	feeling4 = "The bards of legend were said to travel the world, singing paeans of their champions. The paean I compose for your tale shall also be sung across the world one day.",
	lose = "Setbacks are a necessary component of any champion's tale.",
	feeling1 = "Your tale ought not to end here. Please regather yourself and press onward.",
	skill = "Thus exeunts the villains.",
	upgrade = "A more harmonious timbre.",
	propose = "To think that I, as a singer, would become part of my Champion's tale... What an unexpected plot twist. Heehee~ O Champion, shall we join hands and weave the paean to a more joyous tomorrow?",
	feeling5 = "The champions of legend accomplished feats that transcended time, but all mortals will succumb to fatigue. Should you ever feel tired, please make sure to rest. I shall nourish you with my finest song and verse.",
	main = "Why not stop to smell the roses on your odyssey forward? Take heed of nature's marvels and friends who cherish you – there are still many things here worthy of your attention.|Every life is a wonderful story – be it an epic akin to a turbulent storm, or a lullaby as calming as the gentle sea breeze. Everything is embraced by the land and the sea, and committed to memory.|What's my favorite type of tea? Umm, whatever you'd like. As for desserts... Well, I'm fine with just about anything...",
	touch = "Hmm...? Did you need my advice, Champion?",
	voice_key_2 = -1,
	mission_complete = "The mission rewards aren't going anywhere. There's no need for haste - we can always check them later.",
	battle = "Go forward with the Saintess of Victory's everlasting blessings.",
	id = 899030,
	gift_dislike = "",
	gift_prefer = "You'd give me such a precious item? I'm flattered, really.",
	profile = "I am large cruiser Brest, born upon Iris Libre's hallowed ground. I love hearing all the tales spanning land and sea, and spreading my own tales through song and poem. I look forward to hearing the tales you are bound to weave, Champion.",
	voice_key = 89903,
	headtouch = "Oh? Is this intended to bring me succor...?",
	feeling2 = "O Champion, I've heard a great many tales about you from many different people. Now, how goes the tale you narrate through your own eyes? How I wish to find out.",
	login = "O Champion, what tales of heroism will you weave into the annals of history today?",
	detail = "Phew... Oh my, I do believe our Champion has arrived. Why yes, I'm perfectly fine. I was just struck with inspiration for a new paean and simply must put pen to paper.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[899031] = {
	hp_warning = "",
	feeling3 = "",
	mail = "The tide brings new mail. There... This ought to keep it dry.",
	expedition = "The tide tells a tale... Ah, Champion, so the commission company has returned.",
	win_mvp = "",
	home = "Tales of adventure in the briny blue... This could make for an entertaining piece, Champion.",
	unlock = "\"I devote this paean to thee, Champion of seas blue and free.\" There, the song is completed. But we've come all this way... Shall we continue our adventure through these undersea ruins, Champion?",
	touch2 = "My, my... What's come over you?",
	mission = "Might we be blessed with a quest to delve into these ruins?",
	vote = "",
	drop_descrip = "\"I devote this paean to thee, Champion of seas blue and free.\" There, the song is completed. But we've come all this way... Shall we continue our adventure through these undersea ruins, Champion?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Champion, there is much that I wish to tell Richelieu and the others about these ruins. May I spin a hymn here and now?|An adventuring party? I would be happy to serve as your sage... Worry not. You are more than valorous enough to lead the vanguard, Champion.|We must protect these seas, including the most dangerous places—even if they have their own faults, much like my beloved Champion. Heehee!",
	touch = "How I'd love to take such pretty coral home with me, but perhaps it is best left as a memory.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 899031,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Gazing from a ship's deck leaves me wanting. Just imagine the fathomless secrets that lay beneath these waves.",
	detail = "The secret to enriching the mind is traveling and broadening your horizons—be it contemplating nature's beauty or visiting historical locales~",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[899032] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "O Champion, you've been hard at work. Come to me and enjoy a moment's respite.",
	unlock = "O Champion, what manner of floral makeup would look best upon my brow? Or, could I perhaps... call upon you to apply it for me? ♪",
	touch2 = "Heehee... O Champion, put out the candles first.",
	mission = "",
	vote = "",
	drop_descrip = "O Champion, what manner of floral makeup would look best upon my brow? Or, could I perhaps... call upon you to apply it for me? ♪",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "With zither and lyric, let us weave a song of this night. Of a brief yet wonderful time, of a minstrel who desires her own part in the tale... To be forever remembered by her champion.",
	main = "O Champion, do you think the red floral makeup suits me more? Good. Then I'll keep applying this one...|The way you paint my face now reminds me of lovers in old folktales.|O Champion, please come closer. You may find the scenery tonight is unique enough to warrant a moment's rest.",
	touch = "O Champion, do you wish to sit next to me? Here is a cushion... Oh? You want me to be your cushion?",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 899032,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "Should I style my hair in a Dragon Empery fashion, as well?",
	feeling2 = "",
	login = "The window's view of the moon, the fragrance of the stove... A perfect environment in which to pen poetry.",
	detail = "Those of the Empery often quote, \"A woman dresses herself for the one who delights in her.\" In other words, we try to be beautiful for the one we love... Right now, that would be an apt description for me.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[199040] = {
	hp_warning = "The operation is going awry... What is this?!",
	feeling3 = "Your individual tastes and interests... That's a good perspective. I'll ask my acquaintances for basic info later... For now, open your mouth. I made borscht, and this will help me determine your tastes. Come on, say \"ahh.\"",
	mail = "Confirming that a letter has arrived. Take a look.",
	expedition = "Confirming the commission team has returned. I'll go collect the goods.",
	win_mvp = "Combat appraisal complete. Moving on to the next stage of the operation.",
	home = "Welcome back, now have a breather. After-action review? Ah, right, you went on a sortie. Would it have been better if I'd joined you?",
	unlock = "Activation sequence complete. I am aviation battleship Kearsarge, Hybrid Idealization X given flesh and blood. Henceforth, I will serve you at this port. So, which division do I belong to, and what's my mission?",
	touch2 = "How much intent is in this act you're committing?",
	mission = "Confirming there are unfinished missions. If you won't do them, I'll remove them from your schedule as I see fit. You sure you want that?",
	vote = "",
	drop_descrip = "Aviation battleship – Kearsarge.",
	feeling4 = "Though calling it a \"date\" is a misnomer, a date does present a great opportunity to learn your habits and savoir-faire. Here is your schedule for today. Give it a quick read, then we'll get started.",
	lose = "Combat appraisal complete. I shall maintain momentum while resuming formation, then launch a counterattack.",
	feeling1 = "Your commanding ability has been evaluated... Simply following your orders is detrimental.",
	skill = "Freeze, then burst!",
	upgrade = "Performance and fleet potential increase confirmed. Keep it up.",
	propose = "Confirming vitals all green. Hm? Oh, don't worry, I simply snuck a vital sensor onto you – a return gift for this ring you gave me. It's necessary to keep a regular check on your health, and to know when to come running when you need help. Makes sense, no?",
	feeling5 = "I trust you, Commander, and I want to become intimately familiar with you. However, I'm unable to fully determine your feelings towards me due to my own ineptness... Do you trust me the way I trust you? Do you, as others would say, love me?",
	main = "Save the small talk for after work. I'm concentrating on my secretary duties, so don't disturb me.|It doesn't help to always look back on the past – keep moving forward, and don't stop. Even when you want to self-reflect, you must adapt to developments as they happen.|On occasion, I neglect your will and prioritize the here and now on the battlefield. While you are the Commander, sometimes you have to let your soldiers handle things – the sooner you accept this, the better.|(Kearsarge is sitting upright on the couch with her eyes closed. Is she asleep, or...?)",
	touch = "Yes, I know you're here. What do you need?",
	voice_key_2 = -1,
	mission_complete = "Confirming that rewards have come in. I'll go collect them.",
	battle = "The advantage is ours! Strike!",
	id = 199040,
	gift_dislike = "",
	gift_prefer = "Your taste is commendable. Sorry – I should thank you first.",
	profile = "I'm Kearsarge, Eagle Union blueprint ship given form. My design was a hybrid between battleship and aircraft carrier, giving me the ability to deal with almost any situation or battlefield. I hope you'll put my strength to good use, Commander.",
	voice_key = 19904,
	headtouch = "...Hm? What are you doing?",
	feeling2 = "I've determined that establishing mutual trust between us is beneficial to my battlefield performance. So, without further ado, allow me to check your schedule... Hm? Is information-gathering not customary when getting to know someone?",
	login = "Ah, Commander. Pardon me for starting work without you. Pay me no mind and begin with your own tasks.",
	detail = "...I'm not sleeping, I'm just letting my brain rest a while. While, yes, I did leave the door wide open, you should at least knock before you enter next time, Commander.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[199041] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission team has returned. We'll continue after you've welcomed the girls back.",
	win_mvp = "Combat appraisal complete. Energy consumption is within normal values. Commander, continue with the operation.",
	home = "Confirming activation of energy circuit. I can move more now. You should recharge your batteries as well, Commander. Just give me your order.",
	unlock = "I am now the Hybrid Idealization given flesh and blood wearing a suit designed with my performance for you in mind. I am ready to receive orders at any time.",
	touch2 = "Confirming activation of contact circuit... Oh, um, you could increase the contact area for greater efficiency...",
	mission = "Confirming there are unfinished missions... but right now, you're meant to enjoy my performance. The missions can wait.",
	vote = "",
	drop_descrip = "I am now the Hybrid Idealization given flesh and blood wearing a suit designed with my performance for you in mind. I am ready to receive orders at any time.",
	feeling4 = "",
	lose = "Combat appraisal complete. Energy consumption exceeds estimated values. Commander, provide additional energy via contact circuit.",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "",
	main = "Confirming rise in vital signs. Heart rate, pulse, body temperature, and... Ahem. Is this what is called a \"state of arousal\"?|This pole was originally installed to suit your needs in all kinds of scenarios. Naturally, this performance will go perfectly... Heh.|...Oh. Right, I'm still in the middle of my pop-up store performance. Have you been watching me, Commander?|Let me show you some moves New Jersey taught me. I even made a few original modifications, based on the data from your reactions.|(Kearsarge's breathing is faintly audible. Is she meditating again, or is she just pondering what to do for her next performance?)",
	touch = "Mhh... Is that better?",
	voice_key_2 = -1,
	mission_complete = "Confirming that mission rewards have arrived. Would you mind getting it yourself, Commander?",
	battle = "",
	id = 199041,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "Eagle Union bunny girl Kearsarge will charm you tonight. Don't worry, I can keep dancing as long as you're watching my– Oh. I don't recommend staying up all night for it.",
	detail = "This pole is a prop to assist with my performance and is installed with a contact circuit to replenish my energy. It's multifunctional and very convenient to... Oh, I shouldn't be explaining this right now.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[199042] = {
	hp_warning = "",
	feeling3 = "",
	mail = "Confirming the arrival of a new letter. You've received a large influx of seasonal greetings. Should I prepare a reply template for you?",
	expedition = "A commission has been completed. Don't forget to bring a treat to thank the team for their hard work.",
	win_mvp = "",
	home = "Vitals are within normal parameters. Presumption: Your sortie went well. Proceeding to preparation of nourishment following completion of current task.",
	unlock = "This suit is a fusion of tradition and modernity. Your feedback would be appreciated... but first, a small issue must be dealt with. May I request your assistance in the matter, Commander?",
	touch2 = "Mmh... Analyzing your tastes has proven... very worthwhile...",
	mission = "Confirming the presence of unfinished missions. While it is a holiday, you must still carry out your duty. I am always ready to aid you.",
	vote = "",
	drop_descrip = "This suit is a fusion of tradition and modernity. Your feedback would be appreciated... but first, a small issue must be dealt with. May I request your assistance in the matter, Commander?",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Today, I recorded large amounts of data about you and further deepened my understanding of love. While this feeling is hard to quantify, I do look forward to spending more time with you over this new year. Not only for logging and analysis purposes, but also to... revel in the happiness of being with you.",
	main = "I've logged an ample amount of data on dumpling recipes. Shall I make some for you? ...Good cooking takes more than simply knowing the recipe?|New Year's wishes? Mine is as follows: I wish to log more data of you and get to know you better. This answer should be within your expectations.|I've heard that the size of a red envelope corresponds to the closeness between the giver and receiver... Oh, no, I wasn't trying to coax you into giving me one. Not at all.|(You feel a weight on your shoulder and hear the sound of soft snoring. Kearsarge has a small smile on her lips. She must have logged a lot of data which makes her happy today.)",
	touch = "Oh. Thank you, Commander. I'd like it if you could prop me up for just a moment.",
	voice_key_2 = -1,
	mission_complete = "Confirming the arrival of mission rewards. Don't worry about me – let me accompany you on your supply retrieval.",
	battle = "",
	id = 199042,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "...Is this kind of contact equivalent to a blessing? Oh, never mind. Keep doing it.",
	feeling2 = "",
	login = "Oh, Commander... Sorry, please stand by for a moment. I need to readjust the fitting of my shoewear.",
	detail = "While these clothes are less flexible than my suit, based on the data I've collected on your preferences, this outfit is the most appropriate under this circumstance. Your expression, likewise, says as much.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[199048] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "Battle evaluation complete. I'm the MVP... Hmm. My dress isn't dirty. Good.",
	home = "Have you finished your tasks? Don't worry; no matter how long it takes, I will be here waiting for you.",
	unlock = "Let us make our genuine vow in this fantasy world I've created for us. I trust and cherish you, and I shall endeavor to be close to you, to understand you, and to be needed by you. You are my one and only, Commander.",
	touch2 = "I was planning to go one step at a time... but I suppose my plans will need revision.",
	mission = "",
	vote = "",
	drop_descrip = "Let us make our genuine vow in this fantasy world I've created for us. I trust and cherish you, and I shall endeavor to be close to you, to understand you, and to be needed by you. You are my one and only, Commander.",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "Affection, adoration, trust... I still haven't found the perfect word to express my feelings for you. What truly matters is that I, Kearsarge, do vow my eternal loyalty to you. Your wish is my command.",
	main = "Would you like to take a walk? I'm happy to accompany you for as long and as far as you desire.|You say this looks dreamy? In my opinion, it is closer to a manifestation of my ideal... but I will accept your opinion as valid, too. You are the core of this space, after all.|I revised many details to be more in line with your preferences. It seems I was successful.|Commander... (Kearsarge seems to be calling your name in her sleep.)",
	touch = "Today, I am ready to respond to even the most indulgent acts.",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 199048,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "The starry sky is my veil, too. Do you like it?",
	feeling2 = "",
	login = "Your heart rate is higher than normal, but your vital data remains stable... The same is true for me. If you are ready, then please take my hand.",
	detail = "I will take all of today's vows to heart. Commander, is there anything else you would like me to do? I was born from the idea of omnipotence, expected to handle any and all situations... so I'm more than capable of handling your requests.",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[399060] = {
	hp_warning = "Upon those who would lay hands on my scales, punishment descends––",
	feeling3 = "You still seem somewhat reserved around me. If you do not change your ways, then I have no choice but to treat you with greater dignity as well– (*gurgle*)... Th-that wasn't my stomach growling... it, it was the rumbling of thunder!",
	mail = "Mail? Will someone drop by to deliver it...?",
	expedition = "A military commission? I see. For the purpose of bringing me an offering, I presume?",
	win_mvp = "Worship me! Fear the raging Dragon God's storm! ...Ahaha, my shikigami have reverted back to soggy pieces of paper...",
	home = "Well done out there, Commander. Did you have a good fight? Oh, it's not like I had anything to do with it, so there's no need for that respectful tone.",
	unlock = "Release the Seal of Denial; open your eyes and worship the great Dragon God– Heehee, don't worry about it. I am Shimanto, a fantasy given form through wishes embodied. Commander, don't be too hard on me, 'kay?",
	touch2 = "Hmm... I wonder if this warrants a curse...",
	mission = "Duties are to be fulfilled. Go forth and do your utmost, Commander.",
	vote = "",
	drop_descrip = "Light cruiser - Shimanto.",
	feeling4 = "Yes, that's right! You can chat with me and enjoy snacks with me as normal! Even if I am the Dragon God, right now, I'm just a regular friend who you can shoot the breeze with! And if you want, I can even go on a date with you! ...Umm, hey. I was totally serious about that, okay?",
	lose = "I've got a lot more bad vibes on me than I expected... Urgh...",
	feeling1 = "Ever wonder what it would be like to get on a dragon's bad side? Surely you're not going to go out of your way to satisfy that curiosity... right?",
	skill = "Shikigami serpent, unleash your divine might!",
	upgrade = "Can you make me even stronger? Then I suppose I shall use this power without reservation~",
	propose = "Should we exchange vows, then an inseparable bond would form between us– indeed, this is both a blessing and a curse. Are you fine with that? ...I see. Heehee. In that case, what should we do next? A kiss? A hug? Or maybe...",
	feeling5 = "I'm here to go on a date with you today, Commander, so there's no need to get hung up about that Dragon God thing. Come on, show me the ropes. This is my first time doing something like this, so I wouldn't be able to put on airs even if I wanted to– Heehee, you're getting a bit better at dealing with me, aren't you?",
	main = "What kind of offerings do I prefer? If you insist on knowing, your favorite snack will suffice... Err, ahem. I meant, anything will do.|You're not done with work yet, right? There's not much left, so keep at it. If you slack off, you might invite a curse upon yourself~|I can somewhat relate with the Guardian Fox's frustrations. Things are a lot better thanks to you, but being revered all the time can be kind of tiring... It's kind of embarrassing to be called the Dragon God all the time.|Perfect, all done. Oh, this isn't an ordinary paper airplane– it's a shikigami plane. Uhh, but, right now, it pretty much is just a paper airplane, just as you said... Mhm...",
	touch = "Got a prayer you want the Dragon God to hear? Want me to make it rain?",
	voice_key_2 = -1,
	mission_complete = "All done with the mission? I see. Well done, then.",
	battle = "\"Ryuujin no hougeki wo kurae––\"",
	id = 399060,
	gift_dislike = "",
	gift_prefer = "The Dragon God loves this. Hehehe!",
	profile = "I am the Sakura Empire light cruiser, Shimanto. As a blueprint ship that embodies wishes given form and the unsealed dragon of lore, I shall hereby lend my assistance to your fleet, Commander– Oh, umm... You know, you're welcome to call me by my title of Dragon God...?",
	voice_key = 39906,
	headtouch = "Hmm...?",
	feeling2 = "How you conduct yourself and the attitude you exhibit towards me can only be one of two options– either you fear and revere me as the Dragon God lest I bring disaster upon you, or you trust and rely upon me, Shimanto, as shipgirl and Commander. The choice is yours; it matters not which you pick.",
	login = "Ahem. Commander, speak your wish to me. ...Hm? Why aren't you saying it? Do you want to give your secretary a day off?",
	detail = "Now then, set yourself free. This is your port– in other words, our home is now synonymous with the Dragon God's domain. Well, setting all that aside, just take it easy around me. There's no need for the formalities.",
	couple_encourage = {
		{
			{
				39905
			},
			1,
			" Keep a tight grip on that katana of yours. Heehee~",
			0
		},
		{
			{
				90103,
				80108,
				60110
			},
			1,
			" Do you hate green peppers that much...?",
			0
		}
	}
}


_G.pg.base.ship_skin_words[399061] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "The commission fleet is back? Do we have enough refreshments? Shall I have Azuma and the others bring some more over?",
	win_mvp = "Be it boiling tea or fighting, there's nothing the Dragon God can't do.",
	home = "You've done well. Would you like a cup of tea first, or would you prefer to lie down? Either way, I've made things nice and comfy for you~",
